import React, { useState } from 'react';
import { Category } from '../types';
import { ChevronRight, ChevronDown, Folder, FolderOpen, Layers } from 'lucide-react';

interface TreeSidebarProps {
  categories: Category[];
  selectedCategoryId: string | null;
  onSelectCategory: (id: string | null) => void;
}

const TreeNode: React.FC<{
  category: Category;
  selectedId: string | null;
  onSelect: (id: string) => void;
  depth: number;
}> = ({ category, selectedId, onSelect, depth }) => {
  const [isOpen, setIsOpen] = useState(depth < 1); // Auto expand root
  const hasChildren = category.children && category.children.length > 0;
  const isSelected = selectedId === category.id;

  return (
    <div className="select-none">
      <div
        onClick={(e) => {
            e.stopPropagation();
            if(hasChildren) setIsOpen(!isOpen);
            onSelect(category.id);
        }}
        className={`
          flex items-center px-3 py-2 cursor-pointer text-sm transition-colors rounded-md mx-2
          ${isSelected ? 'bg-blue-100 text-blue-700 font-medium' : 'text-slate-600 hover:bg-slate-100'}
        `}
        style={{ paddingLeft: `${depth * 16 + 12}px` }}
      >
        <div className="w-4 h-4 mr-1 flex items-center justify-center shrink-0">
            {hasChildren && (
                isOpen ? <ChevronDown size={14} /> : <ChevronRight size={14} />
            )}
        </div>
        <div className="mr-2 text-slate-400">
            {hasChildren ? (isOpen ? <FolderOpen size={16}/> : <Folder size={16}/>) : <Layers size={16}/>}
        </div>
        <span className="truncate">{category.name}</span>
      </div>
      {isOpen && hasChildren && (
        <div className="border-l border-slate-200 ml-[22px]">
          {category.children!.map((child) => (
            <TreeNode
              key={child.id}
              category={child}
              selectedId={selectedId}
              onSelect={onSelect}
              depth={depth + 1}
            />
          ))}
        </div>
      )}
    </div>
  );
};

export const TreeSidebar: React.FC<TreeSidebarProps> = ({
  categories,
  selectedCategoryId,
  onSelectCategory,
}) => {
  return (
    <div className="w-72 bg-white border-r border-slate-200 flex flex-col h-full">
