        </button>

        <button 
            onClick={onOpenImport}
            className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-white bg-emerald-600 rounded-lg hover:bg-emerald-700 shadow-sm"
        >
            <Upload size={16} />
