import React, { useState } from 'react';
import { X, FileSpreadsheet, UploadCloud, CheckCircle, AlertCircle } from 'lucide-react';

interface ImportModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export const ImportModal: React.FC<ImportModalProps> = ({ isOpen, onClose }) => {
  const [step, setStep] = useState<1 | 2 | 3>(1);
  const [isDragging, setIsDragging] = useState(false);

  if (!isOpen) return null;

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    setStep(2);
    // Simulate processing
    setTimeout(() => setStep(3), 1500);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
      <div className="w-full max-w-lg bg-white rounded-xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100 bg-slate-50">
          <h3 className="text-lg font-semibold text-slate-800 flex items-center gap-2">
            <FileSpreadsheet className="text-emerald-600" size={20} />
            Data Ingestion (ETL)
          </h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600">
            <X size={20} />
          </button>
        </div>

        <div className="p-8">
          {step === 1 && (
            <div 
                className={`border-2 border-dashed rounded-xl p-10 flex flex-col items-center justify-center text-center transition-colors
                    ${isDragging ? 'border-blue-500 bg-blue-50' : 'border-slate-300 hover:border-slate-400 bg-slate-50/50'}
                `}
                onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
                onDragLeave={() => setIsDragging(false)}
                onDrop={handleDrop}
            >
              <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mb-4">
                <UploadCloud size={32} />
              </div>
              <h4 className="text-slate-900 font-medium mb-1">Upload Laboratory Data</h4>
              <p className="text-slate-500 text-sm mb-4">Drag & drop .xlsx or .csv files here</p>
              <button 
                onClick={() => { setStep(2); setTimeout(() => setStep(3), 1500); }}
                className="px-4 py-2 bg-blue-600 text-white text-sm font-medium rounded-lg hover:bg-blue-700"
              >
                Browse Files
              </button>
              <div className="mt-6 text-xs text-slate-400 bg-yellow-50 text-yellow-700 px-3 py-2 rounded">
                 Security: Local encryption enabled. Raw data is pre-processed before cloud sync.
              </div>
            </div>
          )}

          {step === 2 && (
            <div className="flex flex-col items-center justify-center py-10">
                <div className="w-12 h-12 border-4 border-blue-200 border-t-blue-600 rounded-full animate-spin mb-4"></div>
                <h4 className="text-slate-900 font-medium">Standardizing Data Structure...</h4>
                <p className="text-slate-500 text-sm">Mapping columns to JSONB schema</p>
            </div>
          )}

          {step === 3 && (
            <div className="flex flex-col items-center justify-center py-6 text-center">
                <CheckCircle className="text-emerald-500 w-16 h-16 mb-4" />
                <h4 className="text-slate-900 font-bold text-lg">Ingestion Complete</h4>
                <p className="text-slate-600 text-sm mt-2 mb-6">
                    Successfully parsed <span className="font-mono font-bold">exp_batch_2023.xlsx</span>.<br/>
                    42 new records identified. 3 duplicates merged.
                </p>
                <div className="flex gap-3 w-full">
                    <button onClick={onClose} className="flex-1 px-4 py-2 bg-slate-100 text-slate-700 font-medium rounded-lg hover:bg-slate-200">
                        View Log
                    </button>
                    <button onClick={onClose} className="flex-1 px-4 py-2 bg-slate-900 text-white font-medium rounded-lg hover:bg-slate-800">
                        Done
                    </button>
                </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { CATEGORY_TREE, MOCK_PRODUCTS } from './constants';
import { Product, ColumnConfig } from './types';
import { TreeSidebar } from './components/TreeSidebar';
import { DataGrid } from './components/DataGrid';
import { TopBar } from './components/TopBar';
import { ImportModal } from './components/ImportModal';
import { Database, ShieldCheck, Server } from 'lucide-react';

// Extract all unique property keys from products to create dynamic columns
const getDynamicColumns = (products: Product[]): ColumnConfig[] => {
  const propertyKeys = new Set<string>();
  products.forEach(p => {
    Object.keys(p.properties).forEach(k => propertyKeys.add(k));
  });

  const dynamicCols: ColumnConfig[] = Array.from(propertyKeys).map(key => ({
    key,
    label: key,
    visible: ['Density', 'Melt Flow Rate'].includes(key), // Default visibility
    isSystem: false
  }));

  const systemCols: ColumnConfig[] = [
    { key: 'gradeName', label: 'Grade Name', visible: true, isSystem: true },
    { key: 'manufacturer', label: 'Manufacturer', visible: true, isSystem: true },
    { key: 'updatedAt', label: 'Last Updated', visible: false, isSystem: false },
  ];

  return [...systemCols, ...dynamicCols];
};

const App: React.FC = () => {
  const [selectedCategoryId, setSelectedCategoryId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [columns, setColumns] = useState<ColumnConfig[]>([]);
  const [isImportOpen, setIsImportOpen] = useState(false);

  // Initialize columns based on data
  useEffect(() => {
    setColumns(getDynamicColumns(MOCK_PRODUCTS));
  }, []);

  const handleToggleColumn = (key: string) => {
    setColumns(cols => cols.map(c => 
      c.key === key ? { ...c, visible: !c.visible } : c
    ));
  };

  // Filter Logic:
  // 1. Category Filter: Product must contain the categoryId in its list (Multi-path)
  // 2. Search Filter: String match on basic fields
  const filteredData = useMemo(() => {
    return MOCK_PRODUCTS.filter(product => {
      // Step 1: Multi-path Category Matching
      // If a category is selected, the product's array of categoryIds must include it.
      // This fulfills the "Redundant Classification" requirement.
      const matchesCategory = selectedCategoryId 
        ? product.categoryIds.includes(selectedCategoryId)
        : true;

      if (!matchesCategory) return false;

      // Step 2: Text Search
      const query = searchQuery.toLowerCase();
      const matchesSearch = 
        product.gradeName.toLowerCase().includes(query) ||
        product.manufacturer.toLowerCase().includes(query) ||
        Object.keys(product.properties).some(k => k.toLowerCase().includes(query));

      return matchesSearch;
    });
  }, [selectedCategoryId, searchQuery]);

  return (
    <div className="flex h-screen bg-white font-sans text-slate-900">

      {/* Sidebar - Navigation */}
      <TreeSidebar 
        categories={CATEGORY_TREE}
        selectedCategoryId={selectedCategoryId}
        onSelectCategory={setSelectedCategoryId}
      />

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0 bg-slate-50">

        {/* Top Header */}
        <TopBar 
            searchQuery={searchQuery}
            onSearchChange={setSearchQuery}
            columns={columns}
            onToggleColumn={handleToggleColumn}
            onOpenImport={() => setIsImportOpen(true)}
        />

        {/* Content Body */}
        <div className="flex-1 p-6 overflow-y-auto">
            <div className="flex items-center justify-between mb-4">
                <div>
                    <h1 className="text-2xl font-bold text-slate-800">
                        {selectedCategoryId 
                            ? `Category View: ${selectedCategoryId}` 
                            : 'All Products Database'}
                    </h1>
                    <p className="text-slate-500 text-sm mt-1">
                        Showing {filteredData.length} result(s) based on active filters.
                    </p>
                </div>
                <div className="flex gap-2">
                    <span className="px-3 py-1 bg-blue-50 text-blue-700 text-xs font-semibold rounded-full border border-blue-100 flex items-center gap-1">
                        <Server size={12}/> PostgreSQL
                    </span>
                    <span className="px-3 py-1 bg-emerald-50 text-emerald-700 text-xs font-semibold rounded-full border border-emerald-100 flex items-center gap-1">
                        <ShieldCheck size={12}/> Python FastAPI
                    </span>
                </div>
            </div>

            <DataGrid 
                data={filteredData}
                columns={columns}
                isLoading={false}
            />
        </div>
      </div>

      <ImportModal isOpen={isImportOpen} onClose={() => setIsImportOpen(false)} />
    </div>
  );
};

export default App;

export interface Category {
  id: string;
  name: string;
  children?: Category[];
}

export interface PropertyValue {
  value: string | number;
  unit?: string;
}

export interface Product {
  id: string;
  gradeName: string; // 牌号
  manufacturer: string; // 厂家
  description?: string;
  // The core requirement: A product belongs to multiple paths (Category IDs)
  categoryIds: string[]; 
  // Simulating PostgreSQL JSONB for flexible attributes
  properties: Record<string, PropertyValue>;
  updatedAt: string;
}

export type ViewMode = 'grid' | 'chart';

export interface ColumnConfig {
  key: string;
  label: string;
