              <YAxis type="number" dataKey={yAxisKey} name={yAxisKey} stroke="#64748b" fontSize={12} label={{ value: yAxisKey, angle: -90, position: 'insideLeft', style: { fill: '#64748b' } }} />
              <ZAxis dataKey="name" name="Product" />
              <RechartsTooltip cursor={{ strokeDasharray: '3 3' }} contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} />
              <Legend />
              <Scatter name="Products" data={chartData} fill="#10b981" />
              {showTrendline && trendlineData.length > 0 && (
                <Scatter 
                    name="Trendline" 
                    data={trendlineData} 
                    line={{ stroke: '#ef4444', strokeWidth: 2, strokeDasharray: '5 5' }} 
                    shape={() => null} // Hide the points for the trendline
                    legendType="none" // Hide from legend
                    tooltipType="none" // Hide from tooltip
                    isAnimationActive={false}
                />
              )}
            </ScatterChart>
          )}
        </ResponsiveContainer>
      </div>
      <div className="px-6 py-3 bg-slate-50 border-t border-slate-200 text-xs text-slate-500 flex justify-between">
        <span>Visualize relationships between {availableProperties.join(', ')}.</span>
        {showTrendline && chartType === 'scatter' && (
            <span className="text-indigo-600 font-medium flex items-center gap-1">
                <TrendingUp size={12} /> Linear Regression Active
            </span>
        )}
      </div>
    </div>
  );
};

