            className={`px-3 py-2 mx-2 mb-2 rounded-md text-sm cursor-pointer flex items-center gap-2 ${!selectedCategoryId ? 'bg-blue-600 text-white shadow-sm' : 'text-slate-600 hover:bg-slate-100'}`}
