    </div>
  );
};

import React from 'react';
import { Product, ColumnConfig } from '../types';
import { MoreHorizontal, FileText, Factory } from 'lucide-react';

interface DataGridProps {
  data: Product[];
  columns: ColumnConfig[];
  isLoading: boolean;
}

export const DataGrid: React.FC<DataGridProps> = ({ data, columns, isLoading }) => {
  const visibleColumns = columns.filter((c) => c.visible);

  if (isLoading) {
    return <div className="p-12 text-center text-slate-400">正在加载合成树脂数据...</div>;
  }

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400 bg-slate-50/50">
        <FileText size={48} className="mb-4 text-slate-300" />
        <p className="text-lg font-medium text-slate-500">未找到产品</p>
        <p className="text-sm">请尝试选择其他分类或调整筛选条件。</p>
      </div>
    );
  }

  return (
    <div className="overflow-x-auto border border-slate-200 rounded-lg shadow-sm bg-white">
      <table className="w-full text-sm text-left">
        <thead className="text-xs text-slate-500 uppercase bg-slate-50 border-b border-slate-200">
          <tr>
            {visibleColumns.map((col) => (
              <th key={col.key} className="px-6 py-4 font-semibold whitespace-nowrap">
                {col.label}
              </th>
            ))}
            <th className="px-6 py-4 text-right">操作</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-slate-100">
          {data.map((product) => (
            <tr key={product.id} className="hover:bg-blue-50/30 transition-colors group">
              {visibleColumns.map((col) => {
                // Determine how to render cell based on key
                let content: React.ReactNode = '-';

                if (col.key === 'gradeName') {
                    content = <span className="font-medium text-blue-600">{product.gradeName}</span>;
                } else if (col.key === 'manufacturer') {
                    content = (
                        <div className="flex items-center gap-1.5 text-slate-700">
                            <Factory size={14} className="text-slate-400" />
                            {product.manufacturer}
                        </div>
                    );
                } else if (col.key === 'updatedAt') {
                    content = <span className="text-slate-400 text-xs">{product.updatedAt}</span>;
                } else {
                    // Dynamic JSONB property handling
                    const prop = product.properties[col.key];
                    if (prop) {
                        content = (
                            <span>
                                {prop.value} 
                                <span className="text-slate-400 text-xs ml-1">{prop.unit}</span>
                            </span>
                        );
                    }
                }

                return (
                  <td key={`${product.id}-${col.key}`} className="px-6 py-4 whitespace-nowrap">
                    {content}
                  </td>
                );
              })}
              <td className="px-6 py-4 text-right">
                <button className="p-1 rounded hover:bg-slate-200 text-slate-400 hover:text-slate-700">
                    <MoreHorizontal size={16} />
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

