import React, { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer,
  ScatterChart, Scatter, ZAxis
} from 'recharts';
import { Product } from '../types';
import { BarChart2, Activity, TrendingUp, FileJson, FileSpreadsheet, Factory } from 'lucide-react';

interface DataVisualizerProps {
  data: Product[];
}

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('密度');
  const [yAxisKey, setYAxisKey] = useState<string>('熔体流动速率');
  const [showTrendline, setShowTrendline] = useState<boolean>(false);

  // Extract numeric properties for Axes selection (Dropdowns)
  const numericProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (!isNaN(Number(val.value))) {
          props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // Extract ALL properties for Tooltip display
  const allProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.keys(p.properties).forEach(k => props.add(k));
    });
    return Array.from(props);
  }, [data]);

  // Helper to extract unit for properties (memoized)
  const propertyUnits = useMemo(() => {
    const units: Record<string, string> = {};
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (v.unit && !units[k]) units[k] = v.unit;
        });
    });
    return units;
  }, [data]);

  // Transform data for Recharts
  const chartData = useMemo(() => {
    return data.map(product => {
      const flattened: any = {
        name: product.gradeName,
        manufacturer: product.manufacturer,
      };

      Object.entries(product.properties).forEach(([key, val]) => {
        const numVal = Number(val.value);
        // If it is a valid number, store as number for plotting. 
        // Otherwise store as string for display in tooltip.
        if (!isNaN(numVal) && val.value !== '' && val.value !== null) {
          flattened[key] = numVal;
        } else {
          flattened[key] = val.value;
        }
      });
      return flattened;
    });
  }, [data]);

  const yAxisUnit = propertyUnits[yAxisKey];
  const xAxisUnit = propertyUnits[xAxisKey];

  const yAxisLabel = yAxisUnit ? `${yAxisKey} (${yAxisUnit})` : yAxisKey;
  const xAxisLabel = xAxisUnit ? `${xAxisKey} (${xAxisUnit})` : xAxisKey;

  // Calculate Linear Regression Trendline
  const trendlineData = useMemo(() => {
    if (chartType !== 'scatter' || !showTrendline || chartData.length < 2) return [];

    let sumX = 0;
    let sumY = 0;
    let sumXY = 0;
    let sumXX = 0;
    let count = 0;

    chartData.forEach((point) => {
        const x = point[xAxisKey];
        const y = point[yAxisKey];

        if (typeof x === 'number' && typeof y === 'number') {
            sumX += x;
            sumY += y;
            sumXY += x * y;
            sumXX += x * x;
            count++;
        }
    });

    if (count < 2) return [];

    const slope = (count * sumXY - sumX * sumY) / (count * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / count;

    const xValues = chartData
        .map(d => d[xAxisKey])
        .filter(v => typeof v === 'number') as number[];

    if (xValues.length === 0) return [];

    const minX = Math.min(...xValues);
    const maxX = Math.max(...xValues);

    return [
        { [xAxisKey]: minX, [yAxisKey]: slope * minX + intercept },
        { [xAxisKey]: maxX, [yAxisKey]: slope * maxX + intercept }
    ];

  }, [chartData, xAxisKey, yAxisKey, showTrendline, chartType]);

  const handleExportJSON = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(chartData));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", "chart_data.json");
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const handleExportCSV = () => {
    if (chartData.length === 0) return;
    const allKeys = Array.from(new Set(chartData.flatMap(Object.keys)));
    const csvContent = [
      allKeys.join(','), 
      ...chartData.map(row => 
        allKeys.map(key => {
          const val = row[key];
          if (val === null || val === undefined) return '';
          const stringVal = String(val);
          if (stringVal.includes(',') || stringVal.includes('"')) {
            return `"${stringVal.replace(/"/g, '""')}"`;
          }
          return stringVal;
        }).join(',')
      )
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'chart_data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const pointData = payload[0].payload;
      if (!pointData.manufacturer) return null;

      const otherProperties = allProperties.filter(key => {
          if (key === yAxisKey) return false;
          if (chartType === 'scatter' && key === xAxisKey) return false;
          // Show property if it exists in the data point and isn't empty
          return pointData[key] !== undefined && pointData[key] !== null && pointData[key] !== '';
      });

      return (
        <div className="bg-white p-3 border border-slate-200 shadow-xl rounded-lg text-sm min-w-[240px] z-50">
            <div className="mb-2">
                <p className="font-bold text-slate-800 text-base">{pointData.name}</p>
                <div className="flex items-center gap-1.5 text-xs text-slate-500 mt-0.5">
                    <Factory size={12} className="text-slate-400"/>
                    <span>{pointData.manufacturer}</span>
                </div>
            </div>
            <div className="border-t border-slate-100 pt-2 space-y-1.5 max-h-[300px] overflow-y-auto custom-scrollbar">
                {/* Main Axis Values */}
                {chartType === 'scatter' && (
                    <div className="flex items-center justify-between text-xs bg-blue-50/50 p-1 rounded">
                        <span className="text-slate-500 font-medium">{xAxisKey}:</span>
                        <span className="font-mono font-semibold text-blue-700">
                            {pointData[xAxisKey]} <span className="text-[10px] text-slate-400 font-normal">{xAxisUnit}</span>
                        </span>
                    </div>
                )}
                <div className="flex items-center justify-between text-xs bg-blue-50/50 p-1 rounded">
                    <span className="text-slate-500 font-medium">{yAxisKey}:</span>
                    <span className="font-mono font-semibold text-blue-700">
                        {pointData[yAxisKey]} <span className="text-[10px] text-slate-400 font-normal">{yAxisUnit}</span>
                    </span>
                </div>

                {/* Additional Properties */}
                {otherProperties.length > 0 && (
                    <>
                        <div className="border-t border-slate-100 my-2"></div>
                        {otherProperties.slice(0, 15).map(prop => (
                            <div key={prop} className="flex items-center justify-between text-xs group">
                                <span className="text-slate-500 truncate mr-2 max-w-[130px]" title={prop}>{prop}:</span>
                                <span className="font-mono text-slate-700 text-right truncate max-w-[100px]" title={String(pointData[prop])}>
                                    {pointData[prop]} 
                                    {propertyUnits[prop] && <span className="text-[10px] text-slate-400 ml-1">{propertyUnits[prop]}</span>}
                                </span>
                            </div>
                        ))}
                         {otherProperties.length > 15 && (
                            <div className="text-xs text-slate-400 italic mt-1 text-center">
                                + {otherProperties.length - 15} more attributes
                            </div>
                        )}
                    </>
                )}
            </div>
        </div>
      );
    }
    return null;
  };

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400">
        <Activity size={48} className="mb-4 text-slate-300" />
        <p>暂无数据，请先导入或选择数据。</p>
      </div>
    );
  }

  if (numericProperties.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400">
        <Activity size={48} className="mb-4 text-slate-300" />
        <p>暂无可用的数值数据用于绘图。</p>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-lg shadow-sm border border-slate-200 flex flex-col h-full">
      {/* Controls Header */}
      <div className="p-4 border-b border-slate-100 bg-slate-50 flex flex-col sm:flex-row gap-4 justify-between items-center">
        <div className="flex items-center gap-4 flex-wrap">
          <div className="flex bg-white rounded-lg border border-slate-200 p-1">
            <button
              onClick={() => setChartType('bar')}
              className={`flex items-center gap-2 px-3 py-1.5 text-sm font-medium rounded-md transition-colors ${
                chartType === 'bar' ? 'bg-blue-50 text-blue-700' : 'text-slate-600 hover:bg-slate-50'
              }`}
            >
              <BarChart2 size={16} />
              对比
            </button>
            <button
              onClick={() => setChartType('scatter')}
              className={`flex items-center gap-2 px-3 py-1.5 text-sm font-medium rounded-md transition-colors ${
                chartType === 'scatter' ? 'bg-blue-50 text-blue-700' : 'text-slate-600 hover:bg-slate-50'
              }`}
            >
              <Activity size={16} />
              相关性
            </button>
          </div>

          <div className="h-6 w-px bg-slate-300 mx-2 hidden sm:block"></div>

          <div className="flex items-center gap-2">
            {chartType === 'scatter' && (
               <>
                <span className="text-sm text-slate-500">X轴:</span>
                <select 
                  value={xAxisKey} 
                  onChange={(e) => setXAxisKey(e.target.value)}
                  className="bg-white border border-slate-300 text-slate-700 text-sm rounded-md focus:ring-blue-500 focus:border-blue-500 p-1.5 max-w-[120px]"
                >
                  {numericProperties.map(p => <option key={p} value={p}>{p}</option>)}
                </select>
               </>
            )}

            <span className="text-sm text-slate-500">{chartType === 'bar' ? '属性:' : 'Y轴:'}</span>
            <select 
               value={yAxisKey} 
               onChange={(e) => setYAxisKey(e.target.value)}
               className="bg-white border border-slate-300 text-slate-700 text-sm rounded-md focus:ring-blue-500 focus:border-blue-500 p-1.5 max-w-[120px]"
            >
              {numericProperties.map(p => <option key={p} value={p}>{p}</option>)}
            </select>
          </div>

          {chartType === 'scatter' && (
              <button
                onClick={() => setShowTrendline(!showTrendline)}
                className={`flex items-center gap-2 px-3 py-1.5 text-sm font-medium rounded-lg border transition-colors ml-2 ${
                    showTrendline 
                    ? 'bg-indigo-50 text-indigo-700 border-indigo-200' 
                    : 'bg-white text-slate-600 border-slate-300 hover:bg-slate-50'
                }`}
              >
                <TrendingUp size={16} />
                趋势线
              </button>
          )}
        </div>

        <div className="flex items-center gap-2">
            <button 
                onClick={handleExportJSON}
                className="flex items-center gap-2 px-3 py-1.5 text-sm font-medium text-slate-600 bg-white border border-slate-300 rounded-lg hover:bg-slate-50"
                title="导出 JSON"
            >
                <FileJson size={16} />
                <span className="hidden sm:inline">JSON</span>
            </button>
            <button 
                onClick={handleExportCSV}
                className="flex items-center gap-2 px-3 py-1.5 text-sm font-medium text-slate-600 bg-white border border-slate-300 rounded-lg hover:bg-slate-50"
                title="导出 CSV"
            >
                <FileSpreadsheet size={16} />
                <span className="hidden sm:inline">CSV</span>
            </button>
        </div>
      </div>

      {/* Chart Canvas */}
      <div className="flex-1 p-6 min-h-[400px]">
        <ResponsiveContainer width="100%" height="100%">
          {chartType === 'bar' ? (
            <BarChart
              data={chartData}
              margin={{ top: 20, right: 30, left: 20, bottom: 5 }}
            >
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
              <XAxis dataKey="name" stroke="#64748b" fontSize={12} tickLine={false} axisLine={{ stroke: '#cbd5e1' }} />
              <YAxis 
                stroke="#64748b" 
                fontSize={12} 
                tickLine={false} 
                axisLine={{ stroke: '#cbd5e1' }} 
                label={{ 
                    value: yAxisLabel, 
                    angle: -90, 
                    position: 'insideLeft', 
                    style: { textAnchor: 'middle', fill: '#94a3b8' } 
                }} 
              />
              <RechartsTooltip 
                content={<CustomTooltip />}
                cursor={{ fill: '#f1f5f9' }}
              />
              <Legend />
              <Bar 
                dataKey={yAxisKey} 
                fill="#3b82f6" 
                radius={[4, 4, 0, 0]} 
                name={yAxisLabel} 
                barSize={60}
                isAnimationActive={true}
                animationDuration={800}
                animationEasing="ease-in-out"
              />
            </BarChart>
          ) : (
            <ScatterChart
              margin={{ top: 20, right: 20, bottom: 20, left: 20 }}
            >
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
              <XAxis 
                type="number" 
                dataKey={xAxisKey} 
                name={xAxisKey} 
                stroke="#64748b" 
                fontSize={12} 
                label={{ 
                    value: xAxisLabel, 
                    position: 'bottom', 
                    offset: 0, 
                    style: { fill: '#64748b' } 
                }} 
              />
              <YAxis 
                type="number" 
                dataKey={yAxisKey} 
                name={yAxisKey} 
                stroke="#64748b" 
                fontSize={12} 
                label={{ 
                    value: yAxisLabel, 
                    angle: -90, 
                    position: 'insideLeft', 
                    style: { fill: '#64748b' } 
                }} 
              />
              <ZAxis dataKey="name" name="产品名称" />
              <RechartsTooltip 
                content={<CustomTooltip />}
