import React, { useState, useMemo, useEffect } from 'react';
import { CATEGORY_TREE, MOCK_PRODUCTS } from './constants';
import { Product, ColumnConfig, ViewMode } from './types';
import { TreeSidebar } from './components/TreeSidebar';
import { DataGrid } from './components/DataGrid';
import { DataVisualizer } from './components/DataVisualizer';
import { TopBar } from './components/TopBar';
import { ImportModal } from './components/ImportModal';
import { ShieldCheck, Server } from 'lucide-react';

// Extract all unique property keys from products to create dynamic columns
const getDynamicColumns = (products: Product[]): ColumnConfig[] => {
  const propertyKeys = new Set<string>();
  products.forEach(p => {
    Object.keys(p.properties).forEach(k => propertyKeys.add(k));
  });

  // Define a list of "popular" columns to show by default so the table isn't empty
  const defaultVisible = ['密度', '熔体流动速率', '应用', '类型', '典型应用', '硬度'];

  const dynamicCols: ColumnConfig[] = Array.from(propertyKeys).map(key => ({
    key,
    label: key,
    visible: defaultVisible.includes(key),
    isSystem: false
  }));

  const systemCols: ColumnConfig[] = [
    { key: 'gradeName', label: '牌号', visible: true, isSystem: true },
    { key: 'manufacturer', label: '生产厂家', visible: true, isSystem: true },
    { key: 'updatedAt', label: '更新时间', visible: false, isSystem: false },
  ];

  return [...systemCols, ...dynamicCols];
};

const App: React.FC = () => {
  const [selectedCategoryId, setSelectedCategoryId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [columns, setColumns] = useState<ColumnConfig[]>([]);
  const [isImportOpen, setIsImportOpen] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>('grid');

  // Initialize columns based on data
  useEffect(() => {
    setColumns(getDynamicColumns(MOCK_PRODUCTS));
  }, []);

  const handleToggleColumn = (key: string) => {
    setColumns(cols => cols.map(c => 
      c.key === key ? { ...c, visible: !c.visible } : c
    ));
  };

  const handleToggleAllColumns = (visible: boolean) => {
    setColumns(cols => cols.map(c => 
      c.isSystem ? c : { ...c, visible }
    ));
  };

  // Filter Logic:
  // 1. Category Filter: Product must contain the categoryId in its list (Multi-path)
  // 2. Search Filter: String match on basic fields
  const filteredData = useMemo(() => {
    return MOCK_PRODUCTS.filter(product => {
      // Step 1: Multi-path Category Matching
      // If a category is selected, the product's array of categoryIds must include it.
      // This fulfills the "Redundant Classification" requirement.
      const matchesCategory = selectedCategoryId 
        ? product.categoryIds.includes(selectedCategoryId)
        : true;

      if (!matchesCategory) return false;

      // Step 2: Text Search
      const query = searchQuery.toLowerCase();
      const matchesSearch = 
        product.gradeName.toLowerCase().includes(query) ||
        product.manufacturer.toLowerCase().includes(query) ||
        Object.keys(product.properties).some(k => k.toLowerCase().includes(query));

      return matchesSearch;
    });
  }, [selectedCategoryId, searchQuery]);

  return (
    <div className="flex h-screen bg-white font-sans text-slate-900">

      {/* Sidebar - Navigation */}
      <TreeSidebar 
        categories={CATEGORY_TREE}
        selectedCategoryId={selectedCategoryId}
        onSelectCategory={setSelectedCategoryId}
      />

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0 bg-slate-50">

        {/* Top Header */}
        <TopBar 
            searchQuery={searchQuery}
            onSearchChange={setSearchQuery}
            columns={columns}
            onToggleColumn={handleToggleColumn}
            onToggleAllColumns={handleToggleAllColumns}
            onOpenImport={() => setIsImportOpen(true)}
            currentView={viewMode}
            onViewChange={setViewMode}
        />

        {/* Content Body */}
        <div className="flex-1 p-6 overflow-y-auto flex flex-col">
            <div className="flex items-center justify-between mb-4 flex-shrink-0">
                <div>
                    <h1 className="text-2xl font-bold text-slate-800">
                        {selectedCategoryId 
                            ? `分类视图: ${selectedCategoryId}` 
                            : '全量合成树脂数据库'}
                    </h1>
                    <p className="text-slate-500 text-sm mt-1">
                        基于当前筛选条件显示 {filteredData.length} 条结果。
                    </p>
                </div>
                <div className="flex gap-2">
                     <span className={`text-xs px-2 py-1 rounded border ${viewMode === 'grid' ? 'bg-blue-50 text-blue-700 border-blue-200' : 'bg-slate-50 text-slate-500 border-slate-200'}`}>
                        {viewMode === 'grid' ? '表格视图' : '可视化视图'}
                    </span>
                </div>
            </div>

            {viewMode === 'grid' ? (
                <DataGrid 
                    data={filteredData}
                    columns={columns}
                    isLoading={false}
                />
            ) : (
                <DataVisualizer data={filteredData} />
            )}
        </div>
      </div>

      <ImportModal 
        isOpen={isImportOpen} 
        onClose={() => setIsImportOpen(false)} 
      />
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer,
  ScatterChart, Scatter, ZAxis, LabelList
} from 'recharts';
import { Product } from '../types';
import { BarChart2, Activity, TrendingUp, FileJson, FileSpreadsheet, Factory } from 'lucide-react';

interface DataVisualizerProps {
  data: Product[];
}

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('密度');
  const [yAxisKey, setYAxisKey] = useState<string>('熔体流动速率');
  const [showTrendline, setShowTrendline] = useState<boolean>(false);

  // Extract numeric properties for Axes selection (Dropdowns)
  const numericProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (!isNaN(Number(val.value))) {
          props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // Extract ALL properties for Tooltip display
  const allProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.keys(p.properties).forEach(k => props.add(k));
    });
    return Array.from(props);
  }, [data]);

  // Helper to extract unit for properties (memoized)
  const propertyUnits = useMemo(() => {
    const units: Record<string, string> = {};
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (v.unit && !units[k]) units[k] = v.unit;
        });
    });
    return units;
  }, [data]);

  // Transform data for Recharts
  const chartData = useMemo(() => {
    return data.map(product => {
      const flattened: any = {
        name: product.gradeName,
        manufacturer: product.manufacturer,
      };

      Object.entries(product.properties).forEach(([key, val]) => {
        const numVal = Number(val.value);
        if (!isNaN(numVal) && val.value !== '' && val.value !== null) {
          flattened[key] = numVal;
        } else {
          flattened[key] = val.value;
        }
      });
      return flattened;
    });
  }, [data]);

  const yAxisUnit = propertyUnits[yAxisKey];
  const xAxisUnit = propertyUnits[xAxisKey];

  const yAxisLabel = yAxisUnit ? `${yAxisKey} (${yAxisUnit})` : yAxisKey;
  const xAxisLabel = xAxisUnit ? `${xAxisKey} (${xAxisUnit})` : xAxisKey;

  // Calculate Linear Regression Trendline
  const trendlineData = useMemo(() => {
    if (chartType !== 'scatter' || !showTrendline || chartData.length < 2) return [];

    let sumX = 0;
    let sumY = 0;
    let sumXY = 0;
    let sumXX = 0;
    let count = 0;

    chartData.forEach((point) => {
        const x = point[xAxisKey];
        const y = point[yAxisKey];

        if (typeof x === 'number' && typeof y === 'number') {
            sumX += x;
            sumY += y;
            sumXY += x * y;
            sumXX += x * x;
            count++;
        }
    });

    if (count < 2) return [];

    const slope = (count * sumXY - sumX * sumY) / (count * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / count;

    const xValues = chartData
        .map(d => d[xAxisKey])
        .filter(v => typeof v === 'number') as number[];

    if (xValues.length === 0) return [];

    const minX = Math.min(...xValues);
    const maxX = Math.max(...xValues);

    return [
        { [xAxisKey]: minX, [yAxisKey]: slope * minX + intercept },
        { [xAxisKey]: maxX, [yAxisKey]: slope * maxX + intercept }
    ];

  }, [chartData, xAxisKey, yAxisKey, showTrendline, chartType]);

  const handleExportJSON = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(chartData));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", "chart_data.json");
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const handleExportCSV = () => {
    if (chartData.length === 0) return;
    const allKeys = Array.from(new Set(chartData.flatMap(Object.keys)));
    const csvContent = [
      allKeys.join(','), 
      ...chartData.map(row => 
        allKeys.map(key => {
          const val = row[key];
          if (val === null || val === undefined) return '';
          const stringVal = String(val);
          if (stringVal.includes(',') || stringVal.includes('"')) {
            return `"${stringVal.replace(/"/g, '""')}"`;
          }
          return stringVal;
        }).join(',')
      )
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'chart_data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const pointData = payload[0].payload;
      if (!pointData.manufacturer) return null;

      const otherProperties = allProperties.filter(key => {
          if (key === yAxisKey) return false;
          if (chartType === 'scatter' && key === xAxisKey) return false;
          return pointData[key] !== undefined && pointData[key] !== null && pointData[key] !== '';
      });

      return (
        <div className="bg-white p-3 border border-slate-200 shadow-xl rounded-lg text-sm min-w-[240px] z-50">
            <div className="mb-2">
                <p className="font-bold text-slate-800 text-base">{pointData.name}</p>
                <div className="flex items-center gap-1.5 text-xs text-slate-500 mt-0.5">
                    <Factory size={12} className="text-slate-400"/>
                    <span>{pointData.manufacturer}</span>
                </div>
            </div>
            <div className="border-t border-slate-100 pt-2 space-y-1.5 max-h-[300px] overflow-y-auto custom-scrollbar">
                {/* Main Axis Values */}
                {chartType === 'scatter' && (
                    <div className="flex items-center justify-between text-xs bg-blue-50/50 p-1 rounded">
                        <span className="text-slate-500 font-medium">{xAxisKey}:</span>
                        <span className="font-mono font-semibold text-blue-700">
                            {pointData[xAxisKey]} <span className="text-[10px] text-slate-400 font-normal">{xAxisUnit}</span>
                        </span>
                    </div>
                )}
                <div className="flex items-center justify-between text-xs bg-blue-50/50 p-1 rounded">
                    <span className="text-slate-500 font-medium">{yAxisKey}:</span>
                    <span className="font-mono font-semibold text-blue-700">
                        {pointData[yAxisKey]} <span className="text-[10px] text-slate-400 font-normal">{yAxisUnit}</span>
                    </span>
                </div>

                {/* Additional Properties */}
                {otherProperties.length > 0 && (
                    <>
                        <div className="border-t border-slate-100 my-2"></div>
                        {otherProperties.slice(0, 15).map(prop => (
                            <div key={prop} className="flex items-center justify-between text-xs group">
                                <span className="text-slate-500 truncate mr-2 max-w-[130px]" title={prop}>{prop}:</span>
                                <span className="font-mono text-slate-700 text-right truncate max-w-[100px]" title={String(pointData[prop])}>
                                    {pointData[prop]} 
                                    {propertyUnits[prop] && <span className="text-[10px] text-slate-400 ml-1">{propertyUnits[prop]}</span>}
                                </span>
                            </div>
                        ))}
                         {otherProperties.length > 15 && (
                            <div className="text-xs text-slate-400 italic mt-1 text-center">
                                + {otherProperties.length - 15} more attributes
                            </div>
                        )}
                    </>
                )}
            </div>
        </div>
      );
    }
    return null;
  };

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400">
        <Activity size={48} className="mb-4 text-slate-300" />
        <p>暂无数据，请先导入或选择数据。</p>
      </div>
    );
  }

  if (numericProperties.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400">
        <Activity size={48} className="mb-4 text-slate-300" />
        <p>暂无可用的数值数据用于绘图。</p>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-lg shadow-sm border border-slate-200 flex flex-col h-full">
      {/* Controls Header */}
      <div className="p-4 border-b border-slate-100 bg-slate-50 flex flex-col sm:flex-row gap-4 justify-between items-center">
        <div className="flex items-center gap-4 flex-wrap">
          <div className="flex bg-white rounded-lg border border-slate-200 p-1">
            <button
              onClick={() => setChartType('bar')}
              className={`flex items-center gap-2 px-3 py-1.5 text-sm font-medium rounded-md transition-colors ${
                chartType === 'bar' ? 'bg-blue-50 text-blue-700' : 'text-slate-600 hover:bg-slate-50'
              }`}
            >
              <BarChart2 size={16} />
              对比
            </button>
            <button
              onClick={() => setChartType('scatter')}
              className={`flex items-center gap-2 px-3 py-1.5 text-sm font-medium rounded-md transition-colors ${
                chartType === 'scatter' ? 'bg-blue-50 text-blue-700' : 'text-slate-600 hover:bg-slate-50'
              }`}
            >
              <Activity size={16} />
              相关性
            </button>
          </div>

          <div className="h-6 w-px bg-slate-300 mx-2 hidden sm:block"></div>

          <div className="flex items-center gap-2">
            {chartType === 'scatter' && (
               <>
                <span className="text-sm text-slate-500">X轴:</span>
                <select 
                  value={xAxisKey} 
                  onChange={(e) => setXAxisKey(e.target.value)}
                  className="bg-white border border-slate-300 text-slate-700 text-sm rounded-md focus:ring-blue-500 focus:border-blue-500 p-1.5 max-w-[120px]"
                >
                  {numericProperties.map(p => <option key={p} value={p}>{p}</option>)}
                </select>
               </>
            )}

            <span className="text-sm text-slate-500">{chartType === 'bar' ? '属性:' : 'Y轴:'}</span>
            <select 
               value={yAxisKey} 
               onChange={(e) => setYAxisKey(e.target.value)}
               className="bg-white border border-slate-300 text-slate-700 text-sm rounded-md focus:ring-blue-500 focus:border-blue-500 p-1.5 max-w-[120px]"
            >
              {numericProperties.map(p => <option key={p} value={p}>{p}</option>)}
            </select>
          </div>

          {chartType === 'scatter' && (
              <button
                onClick={() => setShowTrendline(!showTrendline)}
                className={`flex items-center gap-2 px-3 py-1.5 text-sm font-medium rounded-lg border transition-colors ml-2 ${
                    showTrendline 
                    ? 'bg-indigo-50 text-indigo-700 border-indigo-200' 
                    : 'bg-white text-slate-600 border-slate-300 hover:bg-slate-50'
                }`}
              >
                <TrendingUp size={16} />
                趋势线
              </button>
          )}
        </div>

        <div className="flex items-center gap-2">
            <button 
                onClick={handleExportJSON}
                className="flex items-center gap-2 px-3 py-1.5 text-sm font-medium text-slate-600 bg-white border border-slate-300 rounded-lg hover:bg-slate-50"
                title="导出 JSON"
            >
                <FileJson size={16} />
                <span className="hidden sm:inline">JSON</span>
            </button>
            <button 
                onClick={handleExportCSV}
                className="flex items-center gap-2 px-3 py-1.5 text-sm font-medium text-slate-600 bg-white border border-slate-300 rounded-lg hover:bg-slate-50"
                title="导出 CSV"
            >
                <FileSpreadsheet size={16} />
                <span className="hidden sm:inline">CSV</span>
            </button>
        </div>
      </div>

      {/* Chart Canvas */}
      <div className="flex-1 p-6 min-h-[400px]">
        <ResponsiveContainer width="100%" height="100%">
          {chartType === 'bar' ? (
            <BarChart
              data={chartData}
              margin={{ top: 20, right: 30, left: 20, bottom: 5 }}
            >
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
              <XAxis dataKey="name" stroke="#64748b" fontSize={12} tickLine={false} axisLine={{ stroke: '#cbd5e1' }} />
              <YAxis 
                stroke="#64748b" 
                fontSize={12} 
                tickLine={false} 
                axisLine={{ stroke: '#cbd5e1' }}
                // Use auto domain to highlight differences in small ranges (e.g. 0.91 vs 0.92)
                domain={['auto', 'auto']}
                label={{ 
                    value: yAxisLabel, 
                    angle: -90, 
                    position: 'insideLeft', 
                    style: { textAnchor: 'middle', fill: '#94a3b8' } 
                }} 
              />
              <RechartsTooltip 
                content={<CustomTooltip />}
                cursor={{ fill: '#f1f5f9' }}
              />
              <Legend />
              <Bar 
                dataKey={yAxisKey} 
                fill="#3b82f6" 
                radius={[4, 4, 0, 0]} 
                name={yAxisLabel} 
                barSize={60}
                isAnimationActive={true}
                animationDuration={800}
                animationEasing="ease-in-out"
              >
                  <LabelList dataKey={yAxisKey} position="top" fill="#64748b" fontSize={12} />
              </Bar>
            </BarChart>
          ) : (
            <ScatterChart
              margin={{ top: 20, right: 20, bottom: 20, left: 20 }}
            >
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
              <XAxis 
                type="number" 
                dataKey={xAxisKey} 
                name={xAxisKey} 
                stroke="#64748b" 
                fontSize={12}
                domain={['auto', 'auto']}
                label={{ 
                    value: xAxisLabel, 
                    position: 'bottom', 
                    offset: 0, 
                    style: { fill: '#64748b' } 
                }} 
              />
              <YAxis 
                type="number" 
                dataKey={yAxisKey} 
                name={yAxisKey} 
                stroke="#64748b" 
                fontSize={12}
                domain={['auto', 'auto']}
                label={{ 
                    value: yAxisLabel, 
                    angle: -90, 
                    position: 'insideLeft', 
                    style: { fill: '#64748b' } 
                }} 
              />
              <ZAxis dataKey="name" name="产品名称" />
              <RechartsTooltip 
                content={<CustomTooltip />}
                cursor={{ strokeDasharray: '3 3' }} 
              />
              <Legend />
              <Scatter 
                name="产品分布" 
                data={chartData} 
                fill="#10b981" 
                isAnimationActive={true}
                animationDuration={800}
                animationEasing="ease-in-out"
              />
              {showTrendline && trendlineData.length > 0 && (
                <Scatter 
                    name="趋势线" 
                    data={trendlineData} 
                    line={{ stroke: '#ef4444', strokeWidth: 2, strokeDasharray: '5 5' }} 
                    shape={() => null} 
                    legendType="none" 
                    tooltipType="none" 
                    isAnimationActive={false}
                />
              )}
            </ScatterChart>
          )}
        </ResponsiveContainer>
      </div>
      <div className="px-6 py-3 bg-slate-50 border-t border-slate-200 text-xs text-slate-500 flex justify-between">
        <span>已启用自动缩放以高亮微小数值差异。</span>
        {showTrendline && chartType === 'scatter' && (
            <span className="text-indigo-600 font-medium flex items-center gap-1">
                <TrendingUp size={12} /> 线性回归已启用
            </span>
        )}
      </div>
    </div>
  );
};

import React from 'react';
import { Product, ColumnConfig } from '../types';
import { MoreHorizontal, FileText, Factory } from 'lucide-react';

interface DataGridProps {
  data: Product[];
  columns: ColumnConfig[];
  isLoading: boolean;
}

export const DataGrid: React.FC<DataGridProps> = ({ data, columns, isLoading }) => {
  const visibleColumns = columns.filter((c) => c.visible);

  // Helper to determine if a column is likely numeric based on the first few data points
  const isNumericColumn = (key: string) => {
    // System columns are treated as text/mixed
    if (['gradeName', 'manufacturer', 'updatedAt'].includes(key)) return false;

    // Check first few valid values
    for (const p of data.slice(0, 5)) {
        const val = p.properties[key]?.value;
        if (val !== undefined && val !== null && val !== '') {
             if (typeof val === 'number') return true;
             // If string but looks like number (e.g. "0.95")
             if (!isNaN(Number(val))) return true;
        }
    }
    return false;
  };

  if (isLoading) {
    return <div className="p-12 text-center text-slate-400">正在加载合成树脂数据...</div>;
  }

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400 bg-slate-50/50 border border-slate-200 rounded-lg">
        <FileText size={48} className="mb-4 text-slate-300" />
        <p className="text-lg font-medium text-slate-500">未找到产品</p>
        <p className="text-sm">请尝试选择其他分类或调整筛选条件。</p>
      </div>
    );
  }

  return (
    <div className="overflow-x-auto border border-slate-300 rounded-lg shadow-sm bg-white">
      <table className="w-full text-sm text-left border-collapse">
        <thead className="text-xs text-slate-700 uppercase bg-slate-100">
          <tr>
            {visibleColumns.map((col) => {
                const isNum = isNumericColumn(col.key);
                return (
                    <th key={col.key} className={`px-4 py-3 font-bold border border-slate-300 whitespace-nowrap ${isNum ? 'text-right' : 'text-left'}`}>
                        {col.label}
                    </th>
                );
            })}
            <th className="px-4 py-3 text-right border border-slate-300">操作</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-slate-200">
          {data.map((product) => (
            <tr key={product.id} className="hover:bg-blue-50 transition-colors group">
              {visibleColumns.map((col) => {
                const isNum = isNumericColumn(col.key);
                let content: React.ReactNode = <span className="text-slate-300">-</span>;

                if (col.key === 'gradeName') {
                    content = <span className="font-semibold text-blue-700">{product.gradeName}</span>;
                } else if (col.key === 'manufacturer') {
                    content = (
                        <div className="flex items-center gap-1.5 text-slate-700">
                            <Factory size={14} className="text-slate-400" />
                            {product.manufacturer}
                        </div>
                    );
                } else if (col.key === 'updatedAt') {
                    content = <span className="text-slate-500 text-xs font-mono">{product.updatedAt}</span>;
                } else {
                    // Dynamic JSONB property handling
                    const prop = product.properties[col.key];
                    if (prop && prop.value !== undefined && prop.value !== null && prop.value !== '') {
                        content = (
                            <span>
                                {prop.value} 
                                <span className="text-slate-400 text-xs ml-1 scale-90 inline-block origin-left">{prop.unit}</span>
                            </span>
                        );
                    }
                }

                return (
                  <td key={`${product.id}-${col.key}`} className={`px-4 py-2 border border-slate-300 whitespace-nowrap ${isNum ? 'text-right font-mono text-slate-700' : ''}`}>
                    {content}
                  </td>
                );
              })}
              <td className="px-4 py-2 text-right border border-slate-300">
                <button className="p-1.5 rounded hover:bg-slate-200 text-slate-500 hover:text-slate-800 transition-colors">
                    <MoreHorizontal size={16} />
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer,
  ScatterChart, Scatter, ZAxis, LabelList, Cell
} from 'recharts';
import { Product } from '../types';
import { 
  BarChart2, Activity, TrendingUp, FileJson, FileSpreadsheet, 
  Factory, Settings2, Palette, MoveVertical, MoveHorizontal, Box
} from 'lucide-react';

interface DataVisualizerProps {
  data: Product[];
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16', '#6366f1'];

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('密度');
  const [yAxisKey, setYAxisKey] = useState<string>('熔体流动速率');
  const [zAxisKey, setZAxisKey] = useState<string>('none');
  const [colorByKey, setColorByKey] = useState<string>('none');
  const [showTrendline, setShowTrendline] = useState<boolean>(false);
  const [showConfig, setShowConfig] = useState<boolean>(true);

  // 1. Extract Numeric Properties (for X, Y, Z axes)
  const numericProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (!isNaN(Number(val.value)) && val.value !== '') {
          props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // 2. Extract Categorical Properties (for Coloring)
  // Heuristic: Strings with low cardinality or specific keys like manufacturer
  const categoricalProperties = useMemo(() => {
    const props = new Set<string>(['manufacturer']); // Manufacturer is always a category
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        // If it's a string and relatively short, treat as categorical candidate
        if (typeof val.value === 'string' && val.value.length < 20) {
            props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // 3. Helper to extract units
  const propertyUnits = useMemo(() => {
    const units: Record<string, string> = {};
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (v.unit && !units[k]) units[k] = v.unit;
        });
    });
    return units;
  }, [data]);

  // 4. Transform Data for Recharts (Flattening)
  const chartData = useMemo(() => {
    return data.map(product => {
      const flattened: any = {
        name: product.gradeName,
        manufacturer: product.manufacturer, // Ensure top-level props are accessible
        id: product.id
      };

      Object.entries(product.properties).forEach(([key, val]) => {
        const numVal = Number(val.value);
        if (!isNaN(numVal) && val.value !== '' && val.value !== null) {
          flattened[key] = numVal;
        } else {
          flattened[key] = val.value;
        }
      });
      return flattened;
    });
  }, [data]);

  // 5. Group Data for Scatter Series (if coloring is enabled)
  const scatterGroups = useMemo(() => {
    if (chartType !== 'scatter' || colorByKey === 'none') return null;

    const groups: Record<string, any[]> = {};
    chartData.forEach(d => {
        const keyVal = d[colorByKey];
        const groupName = keyVal ? String(keyVal) : '未分类';
        if (!groups[groupName]) groups[groupName] = [];
        groups[groupName].push(d);
    });
    return groups;
  }, [chartData, chartType, colorByKey]);

  // 6. Color Map for Bar Chart Legend
  const colorMap = useMemo(() => {
    if (colorByKey === 'none') return null;
    const uniqueValues = Array.from(new Set(chartData.map(d => String(d[colorByKey] || '未分类'))));
    const map: Record<string, string> = {};
    uniqueValues.forEach((val, idx) => {
        map[val] = COLORS[idx % COLORS.length];
    });
    return map;
  }, [chartData, colorByKey]);

  // Axis Labels
  const yAxisUnit = propertyUnits[yAxisKey];
  const xAxisUnit = propertyUnits[xAxisKey];
  const zAxisUnit = zAxisKey !== 'none' ? propertyUnits[zAxisKey] : '';

  const yAxisLabel = yAxisUnit ? `${yAxisKey} (${yAxisUnit})` : yAxisKey;
  const xAxisLabel = xAxisUnit ? `${xAxisKey} (${xAxisUnit})` : xAxisKey;

  // Trendline Logic
  const trendlineData = useMemo(() => {
    if (chartType !== 'scatter' || !showTrendline || chartData.length < 2) return [];

    let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0, count = 0;
    chartData.forEach((point) => {
        const x = point[xAxisKey];
        const y = point[yAxisKey];
        if (typeof x === 'number' && typeof y === 'number') {
            sumX += x; sumY += y; sumXY += x * y; sumXX += x * x; count++;
        }
    });

    if (count < 2) return [];
    const slope = (count * sumXY - sumX * sumY) / (count * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / count;
    const xValues = chartData.map(d => d[xAxisKey]).filter(v => typeof v === 'number') as number[];
    if (xValues.length === 0) return [];
    const minX = Math.min(...xValues);
    const maxX = Math.max(...xValues);

    return [
        { [xAxisKey]: minX, [yAxisKey]: slope * minX + intercept },
        { [xAxisKey]: maxX, [yAxisKey]: slope * maxX + intercept }
    ];
  }, [chartData, xAxisKey, yAxisKey, showTrendline, chartType]);

  const handleExportJSON = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(chartData));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", "chart_data.json");
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const pointData = payload[0].payload;
      return (
        <div className="bg-white p-3 border border-slate-200 shadow-xl rounded-lg text-sm min-w-[240px] z-50">
            <div className="mb-2">
                <p className="font-bold text-slate-800 text-base">{pointData.name}</p>
                <div className="flex items-center gap-1.5 text-xs text-slate-500 mt-0.5">
                    <Factory size={12} className="text-slate-400"/>
                    <span>{pointData.manufacturer}</span>
                </div>
            </div>
            <div className="border-t border-slate-100 pt-2 space-y-1.5">
                {/* Scatter X Axis */}
                {chartType === 'scatter' && (
                    <div className="flex justify-between text-xs bg-slate-50 p-1 rounded">
                        <span className="text-slate-500">{xAxisKey}:</span>
                        <span className="font-mono font-semibold text-blue-700">
                            {pointData[xAxisKey]} <span className="text-[10px] text-slate-400">{xAxisUnit}</span>
                        </span>
                    </div>
                )}
                {/* Y Axis */}
                <div className="flex justify-between text-xs bg-slate-50 p-1 rounded">
                    <span className="text-slate-500">{yAxisKey}:</span>
                    <span className="font-mono font-semibold text-blue-700">
                        {pointData[yAxisKey]} <span className="text-[10px] text-slate-400">{yAxisUnit}</span>
                    </span>
                </div>
                 {/* Z Axis */}
                 {zAxisKey !== 'none' && (
                    <div className="flex justify-between text-xs bg-slate-50 p-1 rounded">
                        <span className="text-slate-500">{zAxisKey}:</span>
                        <span className="font-mono font-semibold text-purple-700">
                            {pointData[zAxisKey]} <span className="text-[10px] text-slate-400">{zAxisUnit}</span>
                        </span>
                    </div>
                )}
                {/* Categorical Value if selected */}
                {colorByKey !== 'none' && (
                    <div className="flex justify-between text-xs mt-2 pt-2 border-t border-slate-100">
                        <span className="text-slate-500">{colorByKey}:</span>
                        <span className="font-medium text-slate-800">{pointData[colorByKey]}</span>
                    </div>
                )}
            </div>
        </div>
      );
    }
    return null;
  };

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400">
        <Activity size={48} className="mb-4 text-slate-300" />
        <p>暂无数据，请先导入或选择数据。</p>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-lg shadow-sm border border-slate-200 flex flex-col h-full">

      {/* Configuration Header */}
      <div className="border-b border-slate-100 bg-slate-50">
        <div className="p-3 px-4 flex items-center justify-between">
            <div className="flex items-center gap-2 text-slate-800 font-semibold">
                <Settings2 size={18} className="text-blue-600" />
                <span>图表配置</span>
            </div>
            <div className="flex gap-2">
                 <button 
                    onClick={() => setShowConfig(!showConfig)}
                    className="text-xs text-blue-600 hover:text-blue-700 font-medium px-2 py-1 rounded hover:bg-blue-50 transition-colors"
                >
                    {showConfig ? '收起配置' : '展开配置'}
                </button>
                 <div className="h-4 w-px bg-slate-300 self-center mx-1"></div>
                 <button onClick={handleExportJSON} className="text-slate-500 hover:text-slate-700" title="导出 JSON"><FileJson size={16}/></button>
                 <button onClick={() => {}} className="text-slate-500 hover:text-slate-700" title="导出 CSV"><FileSpreadsheet size={16}/></button>
            </div>
        </div>

        {showConfig && (
            <div className="p-4 pt-0 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 animate-in slide-in-from-top-2 duration-200">
                {/* 1. Chart Type */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <Activity size={12}/> 图表类型
                    </label>
                    <div className="flex bg-white rounded-md border border-slate-200 p-1">
                        <button
                        onClick={() => setChartType('bar')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'bar' ? 'bg-blue-50 text-blue-700 shadow-sm' : 'text-slate-600 hover:bg-slate-50'
                        }`}
                        >
                        <BarChart2 size={14} /> 对比 (柱状图)
                        </button>
                        <button
                        onClick={() => setChartType('scatter')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'scatter' ? 'bg-blue-50 text-blue-700 shadow-sm' : 'text-slate-600 hover:bg-slate-50'
                        }`}
                        >
                        <Activity size={14} /> 相关性 (散点图)
                        </button>
                    </div>
                </div>

                {/* 2. Axes Configuration */}
                <div className="space-y-1.5 lg:col-span-2">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <MoveVertical size={12}/> 坐标轴映射
                    </label>
                    <div className="flex gap-2">
                        {/* X Axis (Only for Scatter) */}
                        {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={xAxisKey} onChange={(e) => setXAxisKey(e.target.value)}
                                    className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                                >
                                    {numericProperties.map(p => <option key={p} value={p}>X轴: {p}</option>)}
                                </select>
                             </div>
                        )}

                        {/* Y Axis (Common) */}
                        <div className="flex-1 min-w-[120px]">
                            <select 
                                value={yAxisKey} onChange={(e) => setYAxisKey(e.target.value)}
                                className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                            >
                                {numericProperties.map(p => <option key={p} value={p}>{chartType === 'bar' ? '数值:' : 'Y轴:'} {p}</option>)}
                            </select>
                        </div>

                         {/* Z Axis (Only for Scatter) */}
                         {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={zAxisKey} onChange={(e) => setZAxisKey(e.target.value)}
                                    className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                                >
                                    <option value="none">Z轴: 无 (默认大小)</option>
                                    {numericProperties.map(p => <option key={p} value={p}>Z轴 (气泡): {p}</option>)}
                                </select>
                             </div>
                        )}
                    </div>
                </div>

                {/* 3. Style & Color */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <Palette size={12}/> 样式与分组
                    </label>
                    <div className="flex gap-2 items-center">
                         <select 
                            value={colorByKey} onChange={(e) => setColorByKey(e.target.value)}
                            className="flex-1 bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                        >
                            <option value="none">颜色: 单一颜色</option>
                            <optgroup label="分类属性">
                                {categoricalProperties.map(p => <option key={p} value={p}>按 {p} 分组</option>)}
                            </optgroup>
                        </select>
                        {chartType === 'scatter' && (
                             <button
                                onClick={() => setShowTrendline(!showTrendline)}
                                title="切换趋势线"
                                className={`p-1.5 rounded border transition-colors ${showTrendline ? 'bg-indigo-50 text-indigo-600 border-indigo-200' : 'bg-white text-slate-400 border-slate-200'}`}
                             >
                                 <TrendingUp size={16} />
                             </button>
                        )}
                    </div>
                </div>
            </div>
        )}
      </div>

      {/* Chart Canvas */}
      <div className="flex-1 p-6 min-h-[400px] relative">
        <ResponsiveContainer width="100%" height="100%">
          {chartType === 'bar' ? (
            <BarChart
              data={chartData}
              margin={{ top: 20, right: 30, left: 20, bottom: 40 }}
            >
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
              <XAxis dataKey="name" stroke="#64748b" fontSize={12} tickLine={false} axisLine={{ stroke: '#cbd5e1' }} interval={0} angle={-30} textAnchor="end" height={60} />
              <YAxis 
                stroke="#64748b" fontSize={12} tickLine={false} axisLine={{ stroke: '#cbd5e1' }} domain={['auto', 'auto']}
                label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { textAnchor: 'middle', fill: '#94a3b8' } }} 
              />
              <RechartsTooltip content={<CustomTooltip />} cursor={{ fill: '#f1f5f9' }} />
              <Legend />
              <Bar 
                dataKey={yAxisKey} 
                fill="#3b82f6" 
                radius={[4, 4, 0, 0]} 
                name={yAxisLabel} 
                barSize={40}
                isAnimationActive={true}
              >
                  {/* Conditional Coloring for Bar Chart */}
                  {colorByKey !== 'none' && chartData.map((entry, index) => {
                      const val = String(entry[colorByKey] || '未分类');
                      return <Cell key={`cell-${index}`} fill={colorMap?.[val] || '#3b82f6'} />;
                  })}
                  <LabelList dataKey={yAxisKey} position="top" fill="#64748b" fontSize={12} formatter={(val: number) => val.toFixed(2)} />
              </Bar>
            </BarChart>
          ) : (
            <ScatterChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
              <XAxis 
                type="number" dataKey={xAxisKey} name={xAxisKey} stroke="#64748b" fontSize={12} domain={['auto', 'auto']}
                label={{ value: xAxisLabel, position: 'bottom', offset: 0, style: { fill: '#64748b' } }} 
              />
              <YAxis 
                type="number" dataKey={yAxisKey} name={yAxisKey} stroke="#64748b" fontSize={12} domain={['auto', 'auto']}
                label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { fill: '#64748b' } }} 
              />
              {/* Conditional Z Axis for Bubble Size */}
              {zAxisKey !== 'none' && (
                  <ZAxis type="number" dataKey={zAxisKey} range={[60, 600]} name={zAxisKey} unit={zAxisUnit} />
              )}

              <RechartsTooltip content={<CustomTooltip />} cursor={{ strokeDasharray: '3 3' }} />
              <Legend />

              {/* Rendering logic based on coloring */}
              {colorByKey !== 'none' && scatterGroups ? (
                  // Multiple Series for colored scatter
                  Object.entries(scatterGroups).map(([groupName, groupData], index) => (
                    <Scatter 
                        key={groupName}
                        name={groupName}
                        data={groupData}
                        fill={COLORS[index % COLORS.length]}
                    />
                  ))
              ) : (
                  // Single Series
                  <Scatter name="产品分布" data={chartData} fill="#3b82f6" />
              )}

              {showTrendline && trendlineData.length > 0 && (
                <Scatter name="趋势线" data={trendlineData} line={{ stroke: '#ef4444', strokeWidth: 2, strokeDasharray: '5 5' }} shape={() => null} legendType="none" tooltipType="none" isAnimationActive={false}/>
              )}
            </ScatterChart>
          )}
        </ResponsiveContainer>

        {/* Custom Legend Display for Bar Chart when Colored */}
        {chartType === 'bar' && colorByKey !== 'none' && colorMap && (
             <div className="absolute top-4 right-6 bg-white/90 p-2 rounded border border-slate-200 text-xs shadow-sm max-w-[150px]">
                 <p className="font-semibold text-slate-500 mb-1 border-b border-slate-100 pb-1">按 {colorByKey}</p>
                 <div className="space-y-1 max-h-[100px] overflow-y-auto custom-scrollbar">
                     {Object.entries(colorMap).map(([label, color]) => (
                         <div key={label} className="flex items-center gap-2">
                             <div className="w-2 h-2 rounded-full" style={{ backgroundColor: color }}></div>
                             <span className="truncate text-slate-600" title={label}>{label}</span>
                         </div>
                     ))}
                 </div>
             </div>
        )}
      </div>

      <div className="px-6 py-2 bg-slate-50 border-t border-slate-200 text-[10px] text-slate-400 flex justify-between">
         <span>支持动态维度映射。Z轴仅在散点图模式下生效（控制气泡大小）。</span>
         <span>ResinDB Visualization Engine v1.2</span>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer,
  ScatterChart, Scatter, ZAxis, LabelList, Cell
} from 'recharts';
import { Product } from '../types';
import { 
  BarChart2, Activity, TrendingUp, FileJson, FileSpreadsheet, 
  Factory, Settings2, Palette, MoveVertical, MoveHorizontal, Box
} from 'lucide-react';

interface DataVisualizerProps {
  data: Product[];
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16', '#6366f1'];

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('密度');
  const [yAxisKey, setYAxisKey] = useState<string>('熔体流动速率');
  const [zAxisKey, setZAxisKey] = useState<string>('none');
  const [colorByKey, setColorByKey] = useState<string>('none');
  const [showTrendline, setShowTrendline] = useState<boolean>(false);
  const [showConfig, setShowConfig] = useState<boolean>(true);

  // 1. Extract Numeric Properties (for X, Y, Z axes)
  const numericProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (!isNaN(Number(val.value)) && val.value !== '') {
          props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // 2. Extract Categorical Properties (for Coloring)
  // Heuristic: Strings with low cardinality or specific keys like manufacturer
  const categoricalProperties = useMemo(() => {
    const props = new Set<string>(['manufacturer']); // Manufacturer is always a category
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        // If it's a string and relatively short, treat as categorical candidate
        if (typeof val.value === 'string' && val.value.length < 20) {
            props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // 3. Helper to extract units
  const propertyUnits = useMemo(() => {
    const units: Record<string, string> = {};
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (v.unit && !units[k]) units[k] = v.unit;
        });
    });
    return units;
  }, [data]);

  // 4. Transform Data for Recharts (Flattening)
  const chartData = useMemo(() => {
    return data.map(product => {
      const flattened: any = {
        name: product.gradeName,
        manufacturer: product.manufacturer, // Ensure top-level props are accessible
        id: product.id
      };

      Object.entries(product.properties).forEach(([key, val]) => {
        const numVal = Number(val.value);
        if (!isNaN(numVal) && val.value !== '' && val.value !== null) {
          flattened[key] = numVal;
        } else {
          flattened[key] = val.value;
        }
      });
      return flattened;
    });
  }, [data]);

  // 5. Group Data for Scatter Series (if coloring is enabled)
  const scatterGroups = useMemo(() => {
    if (chartType !== 'scatter' || colorByKey === 'none') return null;

    const groups: Record<string, any[]> = {};
    chartData.forEach(d => {
        const keyVal = d[colorByKey];
        const groupName = keyVal ? String(keyVal) : '未分类';
        if (!groups[groupName]) groups[groupName] = [];
        groups[groupName].push(d);
    });
    return groups;
  }, [chartData, chartType, colorByKey]);

  // 6. Color Map for Bar Chart Legend
  const colorMap = useMemo(() => {
    if (colorByKey === 'none') return null;
    const uniqueValues = Array.from(new Set(chartData.map(d => String(d[colorByKey] || '未分类'))));
    const map: Record<string, string> = {};
    uniqueValues.forEach((val, idx) => {
        map[val] = COLORS[idx % COLORS.length];
    });
    return map;
  }, [chartData, colorByKey]);

  // Axis Labels
  const yAxisUnit = propertyUnits[yAxisKey];
  const xAxisUnit = propertyUnits[xAxisKey];
  const zAxisUnit = zAxisKey !== 'none' ? propertyUnits[zAxisKey] : '';

  const yAxisLabel = yAxisUnit ? `${yAxisKey} (${yAxisUnit})` : yAxisKey;
  const xAxisLabel = xAxisUnit ? `${xAxisKey} (${xAxisUnit})` : xAxisKey;

  // Trendline Logic
  const trendlineData = useMemo(() => {
    if (chartType !== 'scatter' || !showTrendline || chartData.length < 2) return [];

    let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0, count = 0;
    chartData.forEach((point) => {
        const x = point[xAxisKey];
        const y = point[yAxisKey];
        if (typeof x === 'number' && typeof y === 'number') {
            sumX += x; sumY += y; sumXY += x * y; sumXX += x * x; count++;
        }
    });

    if (count < 2) return [];
    const slope = (count * sumXY - sumX * sumY) / (count * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / count;
    const xValues = chartData.map(d => d[xAxisKey]).filter(v => typeof v === 'number') as number[];
    if (xValues.length === 0) return [];
    const minX = Math.min(...xValues);
    const maxX = Math.max(...xValues);

    return [
        { [xAxisKey]: minX, [yAxisKey]: slope * minX + intercept },
        { [xAxisKey]: maxX, [yAxisKey]: slope * maxX + intercept }
    ];
  }, [chartData, xAxisKey, yAxisKey, showTrendline, chartType]);

  const handleExportJSON = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(chartData));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", "chart_data.json");
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const handleExportCSV = () => {
    if (chartData.length === 0) return;

    // Get all unique keys from the data objects to ensure all columns are present
    const allKeys = Array.from(new Set(chartData.flatMap(Object.keys)));

    // Create CSV header row
    const header = allKeys.join(',');

    // Create CSV body rows
    const rows = chartData.map(row => 
      allKeys.map(key => {
        const val = row[key];
        if (val === null || val === undefined) return '';
        const stringVal = String(val);
        // Escape quotes (") by doubling them ("") and wrap fields containing commas or quotes in quotes
        if (stringVal.includes(',') || stringVal.includes('"') || stringVal.includes('\n')) {
          return `"${stringVal.replace(/"/g, '""')}"`;
        }
        return stringVal;
      }).join(',')
    );

    const csvContent = [header, ...rows].join('\n');

    // Create a Blob with the CSV content and UTF-8 BOM for Excel compatibility
    const blob = new Blob(["\uFEFF" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);

    // Trigger download
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'chart_data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const pointData = payload[0].payload;
      return (
        <div className="bg-white p-3 border border-slate-200 shadow-xl rounded-lg text-sm min-w-[240px] z-50">
            <div className="mb-2">
                <p className="font-bold text-slate-800 text-base">{pointData.name}</p>
                <div className="flex items-center gap-1.5 text-xs text-slate-500 mt-0.5">
                    <Factory size={12} className="text-slate-400"/>
                    <span>{pointData.manufacturer}</span>
                </div>
            </div>
            <div className="border-t border-slate-100 pt-2 space-y-1.5">
                {/* Scatter X Axis */}
                {chartType === 'scatter' && (
                    <div className="flex justify-between text-xs bg-slate-50 p-1 rounded">
                        <span className="text-slate-500">{xAxisKey}:</span>
                        <span className="font-mono font-semibold text-blue-700">
                            {pointData[xAxisKey]} <span className="text-[10px] text-slate-400">{xAxisUnit}</span>
                        </span>
                    </div>
                )}
                {/* Y Axis */}
                <div className="flex justify-between text-xs bg-slate-50 p-1 rounded">
                    <span className="text-slate-500">{yAxisKey}:</span>
                    <span className="font-mono font-semibold text-blue-700">
                        {pointData[yAxisKey]} <span className="text-[10px] text-slate-400">{yAxisUnit}</span>
                    </span>
                </div>
                 {/* Z Axis */}
                 {zAxisKey !== 'none' && (
                    <div className="flex justify-between text-xs bg-slate-50 p-1 rounded">
                        <span className="text-slate-500">{zAxisKey}:</span>
                        <span className="font-mono font-semibold text-purple-700">
                            {pointData[zAxisKey]} <span className="text-[10px] text-slate-400">{zAxisUnit}</span>
                        </span>
                    </div>
                )}
                {/* Categorical Value if selected */}
                {colorByKey !== 'none' && (
                    <div className="flex justify-between text-xs mt-2 pt-2 border-t border-slate-100">
                        <span className="text-slate-500">{colorByKey}:</span>
                        <span className="font-medium text-slate-800">{pointData[colorByKey]}</span>
                    </div>
                )}
            </div>
        </div>
      );
    }
    return null;
  };

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400">
        <Activity size={48} className="mb-4 text-slate-300" />
        <p>暂无数据，请先导入或选择数据。</p>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-lg shadow-sm border border-slate-200 flex flex-col h-full">

      {/* Configuration Header */}
      <div className="border-b border-slate-100 bg-slate-50">
        <div className="p-3 px-4 flex items-center justify-between">
            <div className="flex items-center gap-2 text-slate-800 font-semibold">
                <Settings2 size={18} className="text-blue-600" />
                <span>图表配置</span>
            </div>
            <div className="flex gap-2">
                 <button 
                    onClick={() => setShowConfig(!showConfig)}
                    className="text-xs text-blue-600 hover:text-blue-700 font-medium px-2 py-1 rounded hover:bg-blue-50 transition-colors"
                >
                    {showConfig ? '收起配置' : '展开配置'}
                </button>
                 <div className="h-4 w-px bg-slate-300 self-center mx-1"></div>
                 <button onClick={handleExportJSON} className="text-slate-500 hover:text-slate-700" title="导出 JSON"><FileJson size={16}/></button>
                 <button onClick={handleExportCSV} className="text-slate-500 hover:text-slate-700" title="导出 CSV"><FileSpreadsheet size={16}/></button>
            </div>
        </div>

        {showConfig && (
            <div className="p-4 pt-0 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 animate-in slide-in-from-top-2 duration-200">
                {/* 1. Chart Type */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <Activity size={12}/> 图表类型
                    </label>
                    <div className="flex bg-white rounded-md border border-slate-200 p-1">
                        <button
                        onClick={() => setChartType('bar')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'bar' ? 'bg-blue-50 text-blue-700 shadow-sm' : 'text-slate-600 hover:bg-slate-50'
                        }`}
                        >
                        <BarChart2 size={14} /> 对比 (柱状图)
                        </button>
                        <button
                        onClick={() => setChartType('scatter')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'scatter' ? 'bg-blue-50 text-blue-700 shadow-sm' : 'text-slate-600 hover:bg-slate-50'
                        }`}
                        >
                        <Activity size={14} /> 相关性 (散点图)
                        </button>
                    </div>
                </div>

                {/* 2. Axes Configuration */}
                <div className="space-y-1.5 lg:col-span-2">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <MoveVertical size={12}/> 坐标轴映射
                    </label>
                    <div className="flex gap-2">
                        {/* X Axis (Only for Scatter) */}
                        {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={xAxisKey} onChange={(e) => setXAxisKey(e.target.value)}
                                    className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                                >
                                    {numericProperties.map(p => <option key={p} value={p}>X轴: {p}</option>)}
                                </select>
                             </div>
                        )}

                        {/* Y Axis (Common) */}
                        <div className="flex-1 min-w-[120px]">
                            <select 
                                value={yAxisKey} onChange={(e) => setYAxisKey(e.target.value)}
                                className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                            >
                                {numericProperties.map(p => <option key={p} value={p}>{chartType === 'bar' ? '数值:' : 'Y轴:'} {p}</option>)}
                            </select>
                        </div>

                         {/* Z Axis (Only for Scatter) */}
                         {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={zAxisKey} onChange={(e) => setZAxisKey(e.target.value)}
                                    className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                                >
                                    <option value="none">Z轴: 无 (默认大小)</option>
                                    {numericProperties.map(p => <option key={p} value={p}>Z轴 (气泡): {p}</option>)}
                                </select>
                             </div>
                        )}
                    </div>
                </div>

                {/* 3. Style & Color */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <Palette size={12}/> 样式与分组
                    </label>
                    <div className="flex gap-2 items-center">
                         <select 
                            value={colorByKey} onChange={(e) => setColorByKey(e.target.value)}
                            className="flex-1 bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                        >
                            <option value="none">颜色: 单一颜色</option>
                            <optgroup label="分类属性">
                                {categoricalProperties.map(p => <option key={p} value={p}>按 {p} 分组</option>)}
                            </optgroup>
                        </select>
                        {chartType === 'scatter' && (
                             <button
                                onClick={() => setShowTrendline(!showTrendline)}
                                title="切换趋势线"
                                className={`p-1.5 rounded border transition-colors ${showTrendline ? 'bg-indigo-50 text-indigo-600 border-indigo-200' : 'bg-white text-slate-400 border-slate-200'}`}
                             >
                                 <TrendingUp size={16} />
                             </button>
                        )}
                    </div>
                </div>
            </div>
        )}
      </div>

      {/* Chart Canvas */}
      <div className="flex-1 p-6 min-h-[400px] relative">
        <ResponsiveContainer width="100%" height="100%">
          {chartType === 'bar' ? (
            <BarChart
              data={chartData}
              margin={{ top: 20, right: 30, left: 20, bottom: 40 }}
            >
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
              <XAxis dataKey="name" stroke="#64748b" fontSize={12} tickLine={false} axisLine={{ stroke: '#cbd5e1' }} interval={0} angle={-30} textAnchor="end" height={60} />
              <YAxis 
                stroke="#64748b" fontSize={12} tickLine={false} axisLine={{ stroke: '#cbd5e1' }} domain={['auto', 'auto']}
                label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { textAnchor: 'middle', fill: '#94a3b8' } }} 
              />
              <RechartsTooltip content={<CustomTooltip />} cursor={{ fill: '#f1f5f9' }} />
              <Legend />
              <Bar 
                dataKey={yAxisKey} 
                fill="#3b82f6" 
                radius={[4, 4, 0, 0]} 
                name={yAxisLabel} 
                barSize={40}
                isAnimationActive={true}
              >
                  {/* Conditional Coloring for Bar Chart */}
                  {colorByKey !== 'none' && chartData.map((entry, index) => {
                      const val = String(entry[colorByKey] || '未分类');
                      return <Cell key={`cell-${index}`} fill={colorMap?.[val] || '#3b82f6'} />;
                  })}
                  <LabelList dataKey={yAxisKey} position="top" fill="#64748b" fontSize={12} formatter={(val: number) => val.toFixed(2)} />
              </Bar>
            </BarChart>
          ) : (
            <ScatterChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
              <XAxis 
                type="number" dataKey={xAxisKey} name={xAxisKey} stroke="#64748b" fontSize={12} domain={['auto', 'auto']}
                label={{ value: xAxisLabel, position: 'bottom', offset: 0, style: { fill: '#64748b' } }} 
              />
              <YAxis 
                type="number" dataKey={yAxisKey} name={yAxisKey} stroke="#64748b" fontSize={12} domain={['auto', 'auto']}
                label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { fill: '#64748b' } }} 
              />
              {/* Conditional Z Axis for Bubble Size */}
              {zAxisKey !== 'none' && (
                  <ZAxis type="number" dataKey={zAxisKey} range={[60, 600]} name={zAxisKey} unit={zAxisUnit} />
              )}

              <RechartsTooltip content={<CustomTooltip />} cursor={{ strokeDasharray: '3 3' }} />
              <Legend />

              {/* Rendering logic based on coloring */}
              {colorByKey !== 'none' && scatterGroups ? (
                  // Multiple Series for colored scatter
                  Object.entries(scatterGroups).map(([groupName, groupData], index) => (
                    <Scatter 
                        key={groupName}
                        name={groupName}
                        data={groupData}
                        fill={COLORS[index % COLORS.length]}
                    />
                  ))
              ) : (
                  // Single Series
                  <Scatter name="产品分布" data={chartData} fill="#3b82f6" />
              )}

              {showTrendline && trendlineData.length > 0 && (
                <Scatter name="趋势线" data={trendlineData} line={{ stroke: '#ef4444', strokeWidth: 2, strokeDasharray: '5 5' }} shape={() => null} legendType="none" tooltipType="none" isAnimationActive={false}/>
              )}
            </ScatterChart>
          )}
        </ResponsiveContainer>

        {/* Custom Legend Display for Bar Chart when Colored */}
        {chartType === 'bar' && colorByKey !== 'none' && colorMap && (
             <div className="absolute top-4 right-6 bg-white/90 p-2 rounded border border-slate-200 text-xs shadow-sm max-w-[150px]">
                 <p className="font-semibold text-slate-500 mb-1 border-b border-slate-100 pb-1">按 {colorByKey}</p>
                 <div className="space-y-1 max-h-[100px] overflow-y-auto custom-scrollbar">
                     {Object.entries(colorMap).map(([label, color]) => (
                         <div key={label} className="flex items-center gap-2">
                             <div className="w-2 h-2 rounded-full" style={{ backgroundColor: color }}></div>
                             <span className="truncate text-slate-600" title={label}>{label}</span>
                         </div>
                     ))}
                 </div>
             </div>
        )}
      </div>

      <div className="px-6 py-2 bg-slate-50 border-t border-slate-200 text-[10px] text-slate-400 flex justify-between">
         <span>支持动态维度映射。Z轴仅在散点图模式下生效（控制气泡大小）。</span>
         <span>ResinDB Visualization Engine v1.2</span>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer,
  ScatterChart, Scatter, ZAxis, LabelList, Cell
} from 'recharts';
import { Product } from '../types';
import { 
  BarChart2, Activity, TrendingUp, FileJson, FileSpreadsheet, 
  Factory, Settings2, Palette, MoveVertical
} from 'lucide-react';

interface DataVisualizerProps {
  data: Product[];
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16', '#6366f1'];

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  // Initialize with empty strings, will be populated by useEffect
  const [xAxisKey, setXAxisKey] = useState<string>('');
  const [yAxisKey, setYAxisKey] = useState<string>('');
  const [zAxisKey, setZAxisKey] = useState<string>('none');
  const [colorByKey, setColorByKey] = useState<string>('none');
  const [showTrendline, setShowTrendline] = useState<boolean>(false);
  const [showConfig, setShowConfig] = useState<boolean>(true);

  // 1. Extract Numeric Properties (for X, Y, Z axes)
  const numericProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (!isNaN(Number(val.value)) && val.value !== '' && val.value !== null) {
          props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // 2. Extract Categorical Properties (for Coloring)
  const categoricalProperties = useMemo(() => {
    const props = new Set<string>(['manufacturer']); 
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (typeof val.value === 'string' && val.value.length < 20) {
            props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // 3. Helper to extract units
  const propertyUnits = useMemo(() => {
    const units: Record<string, string> = {};
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (v.unit && !units[k]) units[k] = v.unit;
        });
    });
    return units;
  }, [data]);

  // Auto-select axes when data changes to prevent empty charts
  useEffect(() => {
    if (numericProperties.length === 0) return;

    // Check if current Y axis is valid, if not, find a better default
    if (!yAxisKey || !numericProperties.includes(yAxisKey)) {
        if (numericProperties.includes('熔体流动速率')) setYAxisKey('熔体流动速率');
        else if (numericProperties.includes('密度')) setYAxisKey('密度');
        else setYAxisKey(numericProperties[0]);
    }

    // Check if current X axis is valid
    if (!xAxisKey || !numericProperties.includes(xAxisKey)) {
        if (numericProperties.includes('密度')) setXAxisKey('密度');
        else if (numericProperties.includes('熔体流动速率')) setXAxisKey('熔体流动速率');
        else setXAxisKey(numericProperties.length > 1 ? numericProperties[1] : numericProperties[0]);
    }
  }, [numericProperties, xAxisKey, yAxisKey]);

  // 4. Transform Data for Recharts
  const chartData = useMemo(() => {
    return data.map(product => {
      const flattened: any = {
        name: product.gradeName,
        manufacturer: product.manufacturer,
        id: product.id
      };

      Object.entries(product.properties).forEach(([key, val]) => {
        const numVal = Number(val.value);
        if (!isNaN(numVal) && val.value !== '' && val.value !== null) {
          flattened[key] = numVal;
        } else {
          flattened[key] = val.value;
        }
      });
      return flattened;
    });
  }, [data]);

  // 5. Group Data for Scatter Series
  const scatterGroups = useMemo(() => {
    if (chartType !== 'scatter' || colorByKey === 'none') return null;

    const groups: Record<string, any[]> = {};
    chartData.forEach(d => {
        const keyVal = d[colorByKey];
        const groupName = keyVal ? String(keyVal) : '未分类';
        if (!groups[groupName]) groups[groupName] = [];
        groups[groupName].push(d);
    });
    return groups;
  }, [chartData, chartType, colorByKey]);

  // 6. Color Map
  const colorMap = useMemo(() => {
    if (colorByKey === 'none') return null;
    const uniqueValues = Array.from(new Set(chartData.map(d => String(d[colorByKey] || '未分类'))));
    const map: Record<string, string> = {};
    uniqueValues.forEach((val, idx) => {
        map[val] = COLORS[idx % COLORS.length];
    });
    return map;
  }, [chartData, colorByKey]);

  // Axis Labels
  const yAxisUnit = propertyUnits[yAxisKey];
  const xAxisUnit = propertyUnits[xAxisKey];
  const zAxisUnit = zAxisKey !== 'none' ? propertyUnits[zAxisKey] : '';

  const yAxisLabel = yAxisUnit ? `${yAxisKey} (${yAxisUnit})` : yAxisKey;
  const xAxisLabel = xAxisUnit ? `${xAxisKey} (${xAxisUnit})` : xAxisKey;

  // Trendline Logic
  const trendlineData = useMemo(() => {
    if (chartType !== 'scatter' || !showTrendline || chartData.length < 2) return [];

    let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0, count = 0;
    chartData.forEach((point) => {
        const x = point[xAxisKey];
        const y = point[yAxisKey];
        if (typeof x === 'number' && typeof y === 'number') {
            sumX += x; sumY += y; sumXY += x * y; sumXX += x * x; count++;
        }
    });

    if (count < 2) return [];
    const slope = (count * sumXY - sumX * sumY) / (count * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / count;
    const xValues = chartData.map(d => d[xAxisKey]).filter(v => typeof v === 'number') as number[];
    if (xValues.length === 0) return [];
    const minX = Math.min(...xValues);
    const maxX = Math.max(...xValues);

    return [
        { [xAxisKey]: minX, [yAxisKey]: slope * minX + intercept },
        { [xAxisKey]: maxX, [yAxisKey]: slope * maxX + intercept }
    ];
  }, [chartData, xAxisKey, yAxisKey, showTrendline, chartType]);

  const handleExportJSON = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(chartData));
    const link = document.createElement('a');
    link.href = dataStr;
    link.download = "chart_data.json";
    link.click();
  };

  const handleExportCSV = () => {
    if (chartData.length === 0) return;

    // Get all unique keys from the data objects to ensure all columns are present
    const allKeys = Array.from(new Set(chartData.flatMap(Object.keys)));

    // Create CSV header row
    const header = allKeys.join(',');

    // Create CSV body rows
    const rows = chartData.map(row => 
      allKeys.map(key => {
        const val = row[key];
        if (val === null || val === undefined) return '';
        const stringVal = String(val);
        // Escape quotes (") by doubling them ("") and wrap fields containing commas or quotes in quotes
        if (stringVal.includes(',') || stringVal.includes('"') || stringVal.includes('\n')) {
          return `"${stringVal.replace(/"/g, '""')}"`;
        }
        return stringVal;
      }).join(',')
    );

    const csvContent = [header, ...rows].join('\n');

    // Create a Blob with the CSV content and UTF-8 BOM for Excel compatibility
    const blob = new Blob(["\uFEFF" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);

    // Trigger download
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'chart_data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const pointData = payload[0].payload;
      return (
        <div className="bg-white p-3 border border-slate-200 shadow-xl rounded-lg text-sm min-w-[240px] z-50">
            <div className="mb-2">
                <p className="font-bold text-slate-800 text-base">{pointData.name}</p>
                <div className="flex items-center gap-1.5 text-xs text-slate-500 mt-0.5">
                    <Factory size={12} className="text-slate-400"/>
                    <span>{pointData.manufacturer}</span>
                </div>
            </div>
            <div className="border-t border-slate-100 pt-2 space-y-1.5">
                {chartType === 'scatter' && (
                    <div className="flex justify-between text-xs bg-slate-50 p-1 rounded">
                        <span className="text-slate-500">{xAxisKey}:</span>
                        <span className="font-mono font-semibold text-blue-700">
                            {pointData[xAxisKey]} <span className="text-[10px] text-slate-400">{xAxisUnit}</span>
                        </span>
                    </div>
                )}
                <div className="flex justify-between text-xs bg-slate-50 p-1 rounded">
                    <span className="text-slate-500">{yAxisKey}:</span>
                    <span className="font-mono font-semibold text-blue-700">
                        {pointData[yAxisKey]} <span className="text-[10px] text-slate-400">{yAxisUnit}</span>
                    </span>
                </div>
                 {zAxisKey !== 'none' && (
                    <div className="flex justify-between text-xs bg-slate-50 p-1 rounded">
                        <span className="text-slate-500">{zAxisKey}:</span>
                        <span className="font-mono font-semibold text-purple-700">
                            {pointData[zAxisKey]} <span className="text-[10px] text-slate-400">{zAxisUnit}</span>
                        </span>
                    </div>
                )}
                {colorByKey !== 'none' && (
                    <div className="flex justify-between text-xs mt-2 pt-2 border-t border-slate-100">
                        <span className="text-slate-500">{colorByKey}:</span>
                        <span className="font-medium text-slate-800">{pointData[colorByKey]}</span>
                    </div>
                )}
            </div>
        </div>
      );
    }
    return null;
  };

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400">
        <Activity size={48} className="mb-4 text-slate-300" />
        <p>暂无数据，请先导入或选择数据。</p>
      </div>
    );
  }

  // Fallback if no numeric properties exist in filtered data
  if (numericProperties.length === 0) {
     return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400 border border-slate-200 rounded-lg bg-white">
        <Activity size={48} className="mb-4 text-slate-300" />
        <p>当前数据无可用数值指标，无法生成图表。</p>
        <p className="text-xs mt-2">请尝试切换分类或检查数据字段。</p>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-lg shadow-sm border border-slate-200 flex flex-col h-full w-full">

      {/* Configuration Header */}
      <div className="border-b border-slate-100 bg-slate-50">
        <div className="p-3 px-4 flex items-center justify-between">
            <div className="flex items-center gap-2 text-slate-800 font-semibold">
                <Settings2 size={18} className="text-blue-600" />
                <span>图表配置</span>
            </div>
            <div className="flex gap-2">
                 <button 
                    onClick={() => setShowConfig(!showConfig)}
                    className="text-xs text-blue-600 hover:text-blue-700 font-medium px-2 py-1 rounded hover:bg-blue-50 transition-colors"
                >
                    {showConfig ? '收起配置' : '展开配置'}
                </button>
                 <div className="h-4 w-px bg-slate-300 self-center mx-1"></div>
                 <button onClick={handleExportJSON} className="text-slate-500 hover:text-slate-700" title="导出 JSON"><FileJson size={16}/></button>
                 <button onClick={handleExportCSV} className="text-slate-500 hover:text-slate-700" title="导出 CSV"><FileSpreadsheet size={16}/></button>
            </div>
        </div>

        {showConfig && (
            <div className="p-4 pt-0 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 animate-in slide-in-from-top-2 duration-200">
                {/* 1. Chart Type */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <Activity size={12}/> 图表类型
                    </label>
                    <div className="flex bg-white rounded-md border border-slate-200 p-1">
                        <button
                        onClick={() => setChartType('bar')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'bar' ? 'bg-blue-50 text-blue-700 shadow-sm' : 'text-slate-600 hover:bg-slate-50'
                        }`}
                        >
                        <BarChart2 size={14} /> 对比 (柱状图)
                        </button>
                        <button
                        onClick={() => setChartType('scatter')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'scatter' ? 'bg-blue-50 text-blue-700 shadow-sm' : 'text-slate-600 hover:bg-slate-50'
                        }`}
                        >
                        <Activity size={14} /> 相关性 (散点图)
                        </button>
                    </div>
                </div>

                {/* 2. Axes Configuration */}
                <div className="space-y-1.5 lg:col-span-2">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <MoveVertical size={12}/> 坐标轴映射
                    </label>
                    <div className="flex gap-2">
                        {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={xAxisKey} onChange={(e) => setXAxisKey(e.target.value)}
                                    className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                                >
                                    {numericProperties.map(p => <option key={p} value={p}>X轴: {p}</option>)}
                                </select>
                             </div>
                        )}

                        <div className="flex-1 min-w-[120px]">
                            <select 
                                value={yAxisKey} onChange={(e) => setYAxisKey(e.target.value)}
                                className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                            >
                                {numericProperties.map(p => <option key={p} value={p}>{chartType === 'bar' ? '数值:' : 'Y轴:'} {p}</option>)}
                            </select>
                        </div>

                         {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={zAxisKey} onChange={(e) => setZAxisKey(e.target.value)}
                                    className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                                >
                                    <option value="none">Z轴: 无 (默认大小)</option>
                                    {numericProperties.map(p => <option key={p} value={p}>Z轴: {p}</option>)}
                                </select>
                             </div>
                        )}
                    </div>
                </div>

                {/* 3. Style & Color */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <Palette size={12}/> 样式与分组
                    </label>
                    <div className="flex gap-2 items-center">
                         <select 
                            value={colorByKey} onChange={(e) => setColorByKey(e.target.value)}
                            className="flex-1 bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                        >
                            <option value="none">颜色: 单一颜色</option>
                            <optgroup label="分类属性">
                                {categoricalProperties.map(p => <option key={p} value={p}>按 {p} 分组</option>)}
                            </optgroup>
                        </select>
                        {chartType === 'scatter' && (
                             <button
                                onClick={() => setShowTrendline(!showTrendline)}
                                title="切换趋势线"
                                className={`p-1.5 rounded border transition-colors ${showTrendline ? 'bg-indigo-50 text-indigo-600 border-indigo-200' : 'bg-white text-slate-400 border-slate-200'}`}
                             >
                                 <TrendingUp size={16} />
                             </button>
                        )}
                    </div>
                </div>
            </div>
        )}
      </div>

      {/* Chart Canvas */}
      <div className="flex-1 p-6 min-h-[400px] relative w-full h-full">
        {yAxisKey && numericProperties.includes(yAxisKey) && (
            <ResponsiveContainer width="100%" height="100%">
            {chartType === 'bar' ? (
                <BarChart
                data={chartData}
                margin={{ top: 20, right: 30, left: 20, bottom: 40 }}
                >
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" stroke="#64748b" fontSize={12} tickLine={false} axisLine={{ stroke: '#cbd5e1' }} interval={0} angle={-30} textAnchor="end" height={60} />
                <YAxis 
                    stroke="#64748b" fontSize={12} tickLine={false} axisLine={{ stroke: '#cbd5e1' }} domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { textAnchor: 'middle', fill: '#94a3b8' } }} 
                />
                <RechartsTooltip content={<CustomTooltip />} cursor={{ fill: '#f1f5f9' }} />
                <Legend />
                <Bar 
                    dataKey={yAxisKey} 
                    fill="#3b82f6" 
                    radius={[4, 4, 0, 0]} 
                    name={yAxisLabel} 
                    barSize={40}
                    isAnimationActive={true}
                >
                    {colorByKey !== 'none' && chartData.map((entry, index) => {
                        const val = String(entry[colorByKey] || '未分类');
                        return <Cell key={`cell-${index}`} fill={colorMap?.[val] || '#3b82f6'} />;
                    })}
                    <LabelList dataKey={yAxisKey} position="top" fill="#64748b" fontSize={12} formatter={(val: number) => val.toFixed(2)} />
                </Bar>
                </BarChart>
            ) : (
                <ScatterChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis 
                    type="number" dataKey={xAxisKey} name={xAxisKey} stroke="#64748b" fontSize={12} domain={['auto', 'auto']}
                    label={{ value: xAxisLabel, position: 'bottom', offset: 0, style: { fill: '#64748b' } }} 
                />
                <YAxis 
                    type="number" dataKey={yAxisKey} name={yAxisKey} stroke="#64748b" fontSize={12} domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { fill: '#64748b' } }} 
                />
                {zAxisKey !== 'none' && (
                    <ZAxis type="number" dataKey={zAxisKey} range={[60, 600]} name={zAxisKey} unit={zAxisUnit} />
                )}

                <RechartsTooltip content={<CustomTooltip />} cursor={{ strokeDasharray: '3 3' }} />
                <Legend />

                {colorByKey !== 'none' && scatterGroups ? (
                    Object.entries(scatterGroups).map(([groupName, groupData], index) => (
                        <Scatter 
                            key={groupName}
                            name={groupName}
                            data={groupData}
                            fill={COLORS[index % COLORS.length]}
                        />
                    ))
                ) : (
                    <Scatter name="产品分布" data={chartData} fill="#3b82f6" />
                )}

                {showTrendline && trendlineData.length > 0 && (
                    <Scatter name="趋势线" data={trendlineData} line={{ stroke: '#ef4444', strokeWidth: 2, strokeDasharray: '5 5' }} shape={() => null} legendType="none" tooltipType="none" isAnimationActive={false}/>
                )}
                </ScatterChart>
            )}
            </ResponsiveContainer>
        )}

        {chartType === 'bar' && colorByKey !== 'none' && colorMap && (
             <div className="absolute top-4 right-6 bg-white/90 p-2 rounded border border-slate-200 text-xs shadow-sm max-w-[150px]">
                 <p className="font-semibold text-slate-500 mb-1 border-b border-slate-100 pb-1">按 {colorByKey}</p>
                 <div className="space-y-1 max-h-[100px] overflow-y-auto custom-scrollbar">
                     {Object.entries(colorMap).map(([label, color]) => (
                         <div key={label} className="flex items-center gap-2">
                             <div className="w-2 h-2 rounded-full" style={{ backgroundColor: color }}></div>
                             <span className="truncate text-slate-600" title={label}>{label}</span>
                         </div>
                     ))}
                 </div>
             </div>
        )}
      </div>

      <div className="px-6 py-2 bg-slate-50 border-t border-slate-200 text-[10px] text-slate-400 flex justify-between">
         <span>支持动态维度映射。Z轴仅在散点图模式下生效。</span>
         <span>ResinDB Visualization Engine v1.2</span>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer,
  ScatterChart, Scatter, ZAxis, LabelList, Cell
} from 'recharts';
import { Product } from '../types';
import { 
  BarChart2, Activity, TrendingUp, FileJson, FileSpreadsheet, 
  Factory, Settings2, Palette, MoveVertical
} from 'lucide-react';

interface DataVisualizerProps {
  data: Product[];
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16', '#6366f1'];

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [userXAxisKey, setUserXAxisKey] = useState<string>('');
  const [userYAxisKey, setUserYAxisKey] = useState<string>('');
  const [zAxisKey, setZAxisKey] = useState<string>('none');
  const [colorByKey, setColorByKey] = useState<string>('none');
  const [showTrendline, setShowTrendline] = useState<boolean>(false);
  const [showConfig, setShowConfig] = useState<boolean>(true);

  // 1. Extract Numeric Properties (for X, Y, Z axes)
  const numericProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (!isNaN(Number(val.value)) && val.value !== '' && val.value !== null) {
          props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // 2. Extract Categorical Properties (for Coloring)
  const categoricalProperties = useMemo(() => {
    const props = new Set<string>(['manufacturer']); 
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (typeof val.value === 'string' && val.value.length < 20) {
            props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // 3. Helper to extract units
  const propertyUnits = useMemo(() => {
    const units: Record<string, string> = {};
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (v.unit && !units[k]) units[k] = v.unit;
        });
    });
    return units;
  }, [data]);

  // 4. Calculate Default/Active Keys synchronously to ensure render is never empty
  const activeYKey = useMemo(() => {
    // If user selected a key and it still exists in the data, use it
    if (userYAxisKey && numericProperties.includes(userYAxisKey)) return userYAxisKey;

    // Otherwise fallbacks
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    if (numericProperties.includes('密度')) return '密度';
    return numericProperties[0] || '';
  }, [userYAxisKey, numericProperties]);

  const activeXKey = useMemo(() => {
    if (userXAxisKey && numericProperties.includes(userXAxisKey)) return userXAxisKey;

    if (numericProperties.includes('密度')) return '密度';
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    return numericProperties.length > 1 ? numericProperties[1] : numericProperties[0] || '';
  }, [userXAxisKey, numericProperties]);

  // 5. Transform Data for Recharts
  const chartData = useMemo(() => {
    return data.map(product => {
      const flattened: any = {
        name: product.gradeName,
        manufacturer: product.manufacturer,
        id: product.id
      };

      Object.entries(product.properties).forEach(([key, val]) => {
        const numVal = Number(val.value);
        if (!isNaN(numVal) && val.value !== '' && val.value !== null) {
          flattened[key] = numVal;
        } else {
          flattened[key] = val.value;
        }
      });
      return flattened;
    });
  }, [data]);

  // 6. Group Data for Scatter Series
  const scatterGroups = useMemo(() => {
    if (chartType !== 'scatter' || colorByKey === 'none') return null;

    const groups: Record<string, any[]> = {};
    chartData.forEach(d => {
        const keyVal = d[colorByKey];
        const groupName = keyVal ? String(keyVal) : '未分类';
        if (!groups[groupName]) groups[groupName] = [];
        groups[groupName].push(d);
    });
    return groups;
  }, [chartData, chartType, colorByKey]);

  // 7. Color Map
  const colorMap = useMemo(() => {
    if (colorByKey === 'none') return null;
    const uniqueValues = Array.from(new Set(chartData.map(d => String(d[colorByKey] || '未分类'))));
    const map: Record<string, string> = {};
    uniqueValues.forEach((val, idx) => {
        map[val] = COLORS[idx % COLORS.length];
    });
    return map;
  }, [chartData, colorByKey]);

  // Axis Labels
  const yAxisUnit = propertyUnits[activeYKey];
  const xAxisUnit = propertyUnits[activeXKey];
  const zAxisUnit = zAxisKey !== 'none' ? propertyUnits[zAxisKey] : '';

  const yAxisLabel = yAxisUnit ? `${activeYKey} (${yAxisUnit})` : activeYKey;
  const xAxisLabel = xAxisUnit ? `${activeXKey} (${xAxisUnit})` : activeXKey;

  // Trendline Logic
  const trendlineData = useMemo(() => {
    if (chartType !== 'scatter' || !showTrendline || chartData.length < 2) return [];

    let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0, count = 0;
    chartData.forEach((point) => {
        const x = point[activeXKey];
        const y = point[activeYKey];
        if (typeof x === 'number' && typeof y === 'number') {
            sumX += x; sumY += y; sumXY += x * y; sumXX += x * x; count++;
        }
    });

    if (count < 2) return [];
    const slope = (count * sumXY - sumX * sumY) / (count * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / count;
    const xValues = chartData.map(d => d[activeXKey]).filter(v => typeof v === 'number') as number[];
    if (xValues.length === 0) return [];
    const minX = Math.min(...xValues);
    const maxX = Math.max(...xValues);

    return [
        { [activeXKey]: minX, [activeYKey]: slope * minX + intercept },
        { [activeXKey]: maxX, [activeYKey]: slope * maxX + intercept }
    ];
  }, [chartData, activeXKey, activeYKey, showTrendline, chartType]);

  const handleExportJSON = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(chartData));
    const link = document.createElement('a');
    link.href = dataStr;
    link.download = "chart_data.json";
    link.click();
  };

  const handleExportCSV = () => {
    if (chartData.length === 0) return;
    const allKeys = Array.from(new Set(chartData.flatMap(Object.keys)));
    const header = allKeys.join(',');
    const rows = chartData.map(row => 
      allKeys.map(key => {
        const val = row[key];
        if (val === null || val === undefined) return '';
        const stringVal = String(val);
        if (stringVal.includes(',') || stringVal.includes('"') || stringVal.includes('\n')) {
          return `"${stringVal.replace(/"/g, '""')}"`;
        }
        return stringVal;
      }).join(',')
    );
    const csvContent = [header, ...rows].join('\n');
    const blob = new Blob(["\uFEFF" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'chart_data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const pointData = payload[0].payload;
      return (
        <div className="bg-white p-3 border border-slate-200 shadow-xl rounded-lg text-sm min-w-[240px] z-50">
            <div className="mb-2">
                <p className="font-bold text-slate-800 text-base">{pointData.name}</p>
                <div className="flex items-center gap-1.5 text-xs text-slate-500 mt-0.5">
                    <Factory size={12} className="text-slate-400"/>
                    <span>{pointData.manufacturer}</span>
                </div>
            </div>
            <div className="border-t border-slate-100 pt-2 space-y-1.5">
                {chartType === 'scatter' && (
                    <div className="flex justify-between text-xs bg-slate-50 p-1 rounded">
                        <span className="text-slate-500">{activeXKey}:</span>
                        <span className="font-mono font-semibold text-blue-700">
                            {pointData[activeXKey]} <span className="text-[10px] text-slate-400">{xAxisUnit}</span>
                        </span>
                    </div>
                )}
                <div className="flex justify-between text-xs bg-slate-50 p-1 rounded">
                    <span className="text-slate-500">{activeYKey}:</span>
                    <span className="font-mono font-semibold text-blue-700">
                        {pointData[activeYKey]} <span className="text-[10px] text-slate-400">{yAxisUnit}</span>
                    </span>
                </div>
                 {zAxisKey !== 'none' && (
                    <div className="flex justify-between text-xs bg-slate-50 p-1 rounded">
                        <span className="text-slate-500">{zAxisKey}:</span>
                        <span className="font-mono font-semibold text-purple-700">
                            {pointData[zAxisKey]} <span className="text-[10px] text-slate-400">{zAxisUnit}</span>
                        </span>
                    </div>
                )}
                {colorByKey !== 'none' && (
                    <div className="flex justify-between text-xs mt-2 pt-2 border-t border-slate-100">
                        <span className="text-slate-500">{colorByKey}:</span>
                        <span className="font-medium text-slate-800">{pointData[colorByKey]}</span>
                    </div>
                )}
            </div>
        </div>
      );
    }
    return null;
  };

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400">
        <Activity size={48} className="mb-4 text-slate-300" />
        <p>暂无数据，请先导入或选择数据。</p>
      </div>
    );
  }

  // Fallback if no numeric properties exist
  if (numericProperties.length === 0) {
     return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400 border border-slate-200 rounded-lg bg-white">
        <Activity size={48} className="mb-4 text-slate-300" />
        <p>当前数据无可用数值指标，无法生成图表。</p>
        <p className="text-xs mt-2">请尝试切换分类或检查数据字段。</p>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-lg shadow-sm border border-slate-200 flex flex-col w-full h-full min-h-[500px]">

      {/* Configuration Header */}
      <div className="border-b border-slate-100 bg-slate-50 flex-shrink-0">
        <div className="p-3 px-4 flex items-center justify-between">
            <div className="flex items-center gap-2 text-slate-800 font-semibold">
                <Settings2 size={18} className="text-blue-600" />
                <span>图表配置</span>
            </div>
            <div className="flex gap-2">
                 <button 
                    onClick={() => setShowConfig(!showConfig)}
                    className="text-xs text-blue-600 hover:text-blue-700 font-medium px-2 py-1 rounded hover:bg-blue-50 transition-colors"
                >
                    {showConfig ? '收起配置' : '展开配置'}
                </button>
                 <div className="h-4 w-px bg-slate-300 self-center mx-1"></div>
                 <button onClick={handleExportJSON} className="text-slate-500 hover:text-slate-700" title="导出 JSON"><FileJson size={16}/></button>
                 <button onClick={handleExportCSV} className="text-slate-500 hover:text-slate-700" title="导出 CSV"><FileSpreadsheet size={16}/></button>
            </div>
        </div>

        {showConfig && (
            <div className="p-4 pt-0 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 animate-in slide-in-from-top-2 duration-200">
                {/* 1. Chart Type */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <Activity size={12}/> 图表类型
                    </label>
                    <div className="flex bg-white rounded-md border border-slate-200 p-1">
                        <button
                        onClick={() => setChartType('bar')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'bar' ? 'bg-blue-50 text-blue-700 shadow-sm' : 'text-slate-600 hover:bg-slate-50'
                        }`}
                        >
                        <BarChart2 size={14} /> 对比 (柱状图)
                        </button>
                        <button
                        onClick={() => setChartType('scatter')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'scatter' ? 'bg-blue-50 text-blue-700 shadow-sm' : 'text-slate-600 hover:bg-slate-50'
                        }`}
                        >
                        <Activity size={14} /> 相关性 (散点图)
                        </button>
                    </div>
                </div>

                {/* 2. Axes Configuration */}
                <div className="space-y-1.5 lg:col-span-2">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <MoveVertical size={12}/> 坐标轴映射
                    </label>
                    <div className="flex gap-2">
                        {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={activeXKey} onChange={(e) => setUserXAxisKey(e.target.value)}
                                    className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                                >
                                    {numericProperties.map(p => <option key={p} value={p}>X轴: {p}</option>)}
                                </select>
                             </div>
                        )}

                        <div className="flex-1 min-w-[120px]">
                            <select 
                                value={activeYKey} onChange={(e) => setUserYAxisKey(e.target.value)}
                                className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                            >
                                {numericProperties.map(p => <option key={p} value={p}>{chartType === 'bar' ? '数值:' : 'Y轴:'} {p}</option>)}
                            </select>
                        </div>

                         {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={zAxisKey} onChange={(e) => setZAxisKey(e.target.value)}
                                    className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                                >
                                    <option value="none">Z轴: 无 (默认大小)</option>
                                    {numericProperties.map(p => <option key={p} value={p}>Z轴: {p}</option>)}
                                </select>
                             </div>
                        )}
                    </div>
                </div>

                {/* 3. Style & Color */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <Palette size={12}/> 样式与分组
                    </label>
                    <div className="flex gap-2 items-center">
                         <select 
                            value={colorByKey} onChange={(e) => setColorByKey(e.target.value)}
                            className="flex-1 bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                        >
                            <option value="none">颜色: 单一颜色</option>
                            <optgroup label="分类属性">
                                {categoricalProperties.map(p => <option key={p} value={p}>按 {p} 分组</option>)}
                            </optgroup>
                        </select>
                        {chartType === 'scatter' && (
                             <button
                                onClick={() => setShowTrendline(!showTrendline)}
                                title="切换趋势线"
                                className={`p-1.5 rounded border transition-colors ${showTrendline ? 'bg-indigo-50 text-indigo-600 border-indigo-200' : 'bg-white text-slate-400 border-slate-200'}`}
                             >
                                 <TrendingUp size={16} />
                             </button>
                        )}
                    </div>
                </div>
            </div>
        )}
      </div>

      {/* Chart Canvas */}
      <div className="flex-1 p-6 relative w-full h-[500px]">
        {activeYKey && (
            <ResponsiveContainer width="100%" height="100%">
            {chartType === 'bar' ? (
                <BarChart
                data={chartData}
                margin={{ top: 20, right: 30, left: 20, bottom: 40 }}
                >
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" stroke="#64748b" fontSize={12} tickLine={false} axisLine={{ stroke: '#cbd5e1' }} interval={0} angle={-30} textAnchor="end" height={60} />
                <YAxis 
                    stroke="#64748b" fontSize={12} tickLine={false} axisLine={{ stroke: '#cbd5e1' }} domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { textAnchor: 'middle', fill: '#94a3b8' } }} 
                />
                <RechartsTooltip content={<CustomTooltip />} cursor={{ fill: '#f1f5f9' }} />
                <Legend />
                <Bar 
                    dataKey={activeYKey} 
                    fill="#3b82f6" 
                    radius={[4, 4, 0, 0]} 
                    name={yAxisLabel} 
                    barSize={40}
                    isAnimationActive={true}
                >
                    {colorByKey !== 'none' && chartData.map((entry, index) => {
                        const val = String(entry[colorByKey] || '未分类');
                        return <Cell key={`cell-${index}`} fill={colorMap?.[val] || '#3b82f6'} />;
                    })}
                    <LabelList dataKey={activeYKey} position="top" fill="#64748b" fontSize={12} formatter={(val: number) => val.toFixed(2)} />
                </Bar>
                </BarChart>
            ) : (
                <ScatterChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis 
                    type="number" dataKey={activeXKey} name={activeXKey} stroke="#64748b" fontSize={12} domain={['auto', 'auto']}
                    label={{ value: xAxisLabel, position: 'bottom', offset: 0, style: { fill: '#64748b' } }} 
                />
                <YAxis 
                    type="number" dataKey={activeYKey} name={activeYKey} stroke="#64748b" fontSize={12} domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { fill: '#64748b' } }} 
                />
                {zAxisKey !== 'none' && (
                    <ZAxis type="number" dataKey={zAxisKey} range={[60, 600]} name={zAxisKey} unit={zAxisUnit} />
                )}

                <RechartsTooltip content={<CustomTooltip />} cursor={{ strokeDasharray: '3 3' }} />
                <Legend />

                {colorByKey !== 'none' && scatterGroups ? (
                    Object.entries(scatterGroups).map(([groupName, groupData], index) => (
                        <Scatter 
                            key={groupName}
                            name={groupName}
                            data={groupData}
                            fill={COLORS[index % COLORS.length]}
                        />
                    ))
                ) : (
                    <Scatter name="产品分布" data={chartData} fill="#3b82f6" />
                )}

                {showTrendline && trendlineData.length > 0 && (
                    <Scatter name="趋势线" data={trendlineData} line={{ stroke: '#ef4444', strokeWidth: 2, strokeDasharray: '5 5' }} shape={() => null} legendType="none" tooltipType="none" isAnimationActive={false}/>
                )}
                </ScatterChart>
            )}
            </ResponsiveContainer>
        )}

        {chartType === 'bar' && colorByKey !== 'none' && colorMap && (
             <div className="absolute top-4 right-6 bg-white/90 p-2 rounded border border-slate-200 text-xs shadow-sm max-w-[150px]">
                 <p className="font-semibold text-slate-500 mb-1 border-b border-slate-100 pb-1">按 {colorByKey}</p>
                 <div className="space-y-1 max-h-[100px] overflow-y-auto custom-scrollbar">
                     {Object.entries(colorMap).map(([label, color]) => (
                         <div key={label} className="flex items-center gap-2">
                             <div className="w-2 h-2 rounded-full" style={{ backgroundColor: color }}></div>
                             <span className="truncate text-slate-600" title={label}>{label}</span>
                         </div>
                     ))}
                 </div>
             </div>
        )}
      </div>

      <div className="px-6 py-2 bg-slate-50 border-t border-slate-200 text-[10px] text-slate-400 flex justify-between flex-shrink-0">
         <span>支持动态维度映射。Z轴仅在散点图模式下生效。</span>
         <span>ResinDB Visualization Engine v1.2</span>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer,
  ScatterChart, Scatter, ZAxis, LabelList, Cell
} from 'recharts';
import { Product } from '../types';
import { 
  BarChart2, Activity, TrendingUp, FileJson, FileSpreadsheet, 
  Factory, Settings2, Palette, MoveVertical
} from 'lucide-react';

interface DataVisualizerProps {
  data: Product[];
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16', '#6366f1'];

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [userXAxisKey, setUserXAxisKey] = useState<string>('');
  const [userYAxisKey, setUserYAxisKey] = useState<string>('');
  const [zAxisKey, setZAxisKey] = useState<string>('none');
  const [colorByKey, setColorByKey] = useState<string>('none');
  const [showTrendline, setShowTrendline] = useState<boolean>(false);
  const [showConfig, setShowConfig] = useState<boolean>(true);

  // 1. Extract Numeric Properties (for X, Y, Z axes)
  const numericProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        // Robust number check: handle strings that look like numbers
        const num = Number(val.value);
        if (!isNaN(num) && val.value !== '' && val.value !== null) {
          props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // 2. Extract Categorical Properties (for Coloring)
  const categoricalProperties = useMemo(() => {
    const props = new Set<string>(['manufacturer']); 
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (typeof val.value === 'string' && val.value.length < 20) {
            props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // 3. Helper to extract units
  const propertyUnits = useMemo(() => {
    const units: Record<string, string> = {};
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (v.unit && !units[k]) units[k] = v.unit;
        });
    });
    return units;
  }, [data]);

  // 4. Calculate Default/Active Keys synchronously
  const activeYKey = useMemo(() => {
    if (userYAxisKey && numericProperties.includes(userYAxisKey)) return userYAxisKey;
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    if (numericProperties.includes('密度')) return '密度';
    return numericProperties[0] || '';
  }, [userYAxisKey, numericProperties]);

  const activeXKey = useMemo(() => {
    if (userXAxisKey && numericProperties.includes(userXAxisKey)) return userXAxisKey;
    if (numericProperties.includes('密度')) return '密度';
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    return numericProperties.length > 1 ? numericProperties[1] : numericProperties[0] || '';
  }, [userXAxisKey, numericProperties]);

  // 5. Transform Data for Recharts
  const chartData = useMemo(() => {
    return data.map(product => {
      const flattened: any = {
        name: product.gradeName,
        manufacturer: product.manufacturer,
        id: product.id
      };

      Object.entries(product.properties).forEach(([key, val]) => {
        const numVal = Number(val.value);
        if (!isNaN(numVal) && val.value !== '' && val.value !== null) {
          flattened[key] = numVal;
        } else {
          flattened[key] = val.value;
        }
      });
      return flattened;
    });
  }, [data]);

  // 6. Group Data for Scatter Series
  const scatterGroups = useMemo(() => {
    if (chartType !== 'scatter' || colorByKey === 'none') return null;

    const groups: Record<string, any[]> = {};
    chartData.forEach(d => {
        const keyVal = d[colorByKey];
        const groupName = keyVal ? String(keyVal) : '未分类';
        if (!groups[groupName]) groups[groupName] = [];
        groups[groupName].push(d);
    });
    return groups;
  }, [chartData, chartType, colorByKey]);

  // 7. Color Map
  const colorMap = useMemo(() => {
    if (colorByKey === 'none') return null;
    const uniqueValues = Array.from(new Set(chartData.map(d => String(d[colorByKey] || '未分类'))));
    const map: Record<string, string> = {};
    uniqueValues.forEach((val, idx) => {
        map[val] = COLORS[idx % COLORS.length];
    });
    return map;
  }, [chartData, colorByKey]);

  // Trendline Logic
  const trendlineData = useMemo(() => {
    if (chartType !== 'scatter' || !showTrendline || chartData.length < 2) return [];

    let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0, count = 0;
    chartData.forEach((point) => {
        const x = point[activeXKey];
        const y = point[activeYKey];
        if (typeof x === 'number' && typeof y === 'number') {
            sumX += x; sumY += y; sumXY += x * y; sumXX += x * x; count++;
        }
    });

    if (count < 2) return [];
    const slope = (count * sumXY - sumX * sumY) / (count * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / count;
    const xValues = chartData.map(d => d[activeXKey]).filter(v => typeof v === 'number') as number[];
    if (xValues.length === 0) return [];
    const minX = Math.min(...xValues);
    const maxX = Math.max(...xValues);

    return [
        { [activeXKey]: minX, [activeYKey]: slope * minX + intercept },
        { [activeXKey]: maxX, [activeYKey]: slope * maxX + intercept }
    ];
  }, [chartData, activeXKey, activeYKey, showTrendline, chartType]);

  const handleExportJSON = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(chartData));
    const link = document.createElement('a');
    link.href = dataStr;
    link.download = "chart_data.json";
    link.click();
  };

  const handleExportCSV = () => {
    if (chartData.length === 0) return;
    const allKeys = Array.from(new Set(chartData.flatMap(Object.keys)));
    const header = allKeys.join(',');
    const rows = chartData.map(row => 
      allKeys.map(key => {
        const val = row[key];
        if (val === null || val === undefined) return '';
        const stringVal = String(val);
        if (stringVal.includes(',') || stringVal.includes('"') || stringVal.includes('\n')) {
          return `"${stringVal.replace(/"/g, '""')}"`;
        }
        return stringVal;
      }).join(',')
    );
    const csvContent = [header, ...rows].join('\n');
    const blob = new Blob(["\uFEFF" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'chart_data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const yAxisUnit = propertyUnits[activeYKey];
  const xAxisUnit = propertyUnits[activeXKey];
  const zAxisUnit = zAxisKey !== 'none' ? propertyUnits[zAxisKey] : '';
  const yAxisLabel = yAxisUnit ? `${activeYKey} (${yAxisUnit})` : activeYKey;
  const xAxisLabel = xAxisUnit ? `${activeXKey} (${xAxisUnit})` : activeXKey;

  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const pointData = payload[0].payload;
      return (
        <div className="bg-white p-3 border border-slate-200 shadow-xl rounded-lg text-sm min-w-[240px] z-50">
            <div className="mb-2">
                <p className="font-bold text-slate-800 text-base">{pointData.name}</p>
                <div className="flex items-center gap-1.5 text-xs text-slate-500 mt-0.5">
                    <Factory size={12} className="text-slate-400"/>
                    <span>{pointData.manufacturer}</span>
                </div>
            </div>
            <div className="border-t border-slate-100 pt-2 space-y-1.5">
                {chartType === 'scatter' && (
                    <div className="flex justify-between text-xs bg-slate-50 p-1 rounded">
                        <span className="text-slate-500">{activeXKey}:</span>
                        <span className="font-mono font-semibold text-blue-700">
                            {pointData[activeXKey]} <span className="text-[10px] text-slate-400">{xAxisUnit}</span>
                        </span>
                    </div>
                )}
                <div className="flex justify-between text-xs bg-slate-50 p-1 rounded">
                    <span className="text-slate-500">{activeYKey}:</span>
                    <span className="font-mono font-semibold text-blue-700">
                        {pointData[activeYKey]} <span className="text-[10px] text-slate-400">{yAxisUnit}</span>
                    </span>
                </div>
                 {zAxisKey !== 'none' && (
                    <div className="flex justify-between text-xs bg-slate-50 p-1 rounded">
                        <span className="text-slate-500">{zAxisKey}:</span>
                        <span className="font-mono font-semibold text-purple-700">
                            {pointData[zAxisKey]} <span className="text-[10px] text-slate-400">{zAxisUnit}</span>
                        </span>
                    </div>
                )}
                {colorByKey !== 'none' && (
                    <div className="flex justify-between text-xs mt-2 pt-2 border-t border-slate-100">
                        <span className="text-slate-500">{colorByKey}:</span>
                        <span className="font-medium text-slate-800">{pointData[colorByKey]}</span>
                    </div>
                )}
            </div>
        </div>
      );
    }
    return null;
  };

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400 border border-slate-200 rounded-lg bg-white">
        <Activity size={48} className="mb-4 text-slate-300" />
        <p>暂无数据，请先导入或选择数据。</p>
      </div>
    );
  }

  // Fallback if no numeric properties exist
  if (numericProperties.length === 0) {
     return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400 border border-slate-200 rounded-lg bg-white">
        <Activity size={48} className="mb-4 text-slate-300" />
        <p>当前数据无可用数值指标，无法生成图表。</p>
        <p className="text-xs mt-2">请尝试切换分类或检查数据字段。</p>
      </div>
    );
  }

  return (
    // Explicit height style ensures the chart container always has size, even in a scrolling parent
    <div className="bg-white rounded-lg shadow-sm border border-slate-200 flex flex-col w-full" style={{ minHeight: '600px', height: '600px' }}>

      {/* Configuration Header */}
      <div className="border-b border-slate-100 bg-slate-50 flex-shrink-0">
        <div className="p-3 px-4 flex items-center justify-between">
            <div className="flex items-center gap-2 text-slate-800 font-semibold">
                <Settings2 size={18} className="text-blue-600" />
                <span>图表配置</span>
            </div>
            <div className="flex gap-2">
                 <button 
                    onClick={() => setShowConfig(!showConfig)}
                    className="text-xs text-blue-600 hover:text-blue-700 font-medium px-2 py-1 rounded hover:bg-blue-50 transition-colors"
                >
                    {showConfig ? '收起配置' : '展开配置'}
                </button>
                 <div className="h-4 w-px bg-slate-300 self-center mx-1"></div>
                 <button onClick={handleExportJSON} className="text-slate-500 hover:text-slate-700" title="导出 JSON"><FileJson size={16}/></button>
                 <button onClick={handleExportCSV} className="text-slate-500 hover:text-slate-700" title="导出 CSV"><FileSpreadsheet size={16}/></button>
            </div>
        </div>

        {showConfig && (
            <div className="p-4 pt-0 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 animate-in slide-in-from-top-2 duration-200">
                {/* 1. Chart Type */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <Activity size={12}/> 图表类型
                    </label>
                    <div className="flex bg-white rounded-md border border-slate-200 p-1">
                        <button
                        onClick={() => setChartType('bar')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'bar' ? 'bg-blue-50 text-blue-700 shadow-sm' : 'text-slate-600 hover:bg-slate-50'
                        }`}
                        >
                        <BarChart2 size={14} /> 对比 (柱状图)
                        </button>
                        <button
                        onClick={() => setChartType('scatter')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'scatter' ? 'bg-blue-50 text-blue-700 shadow-sm' : 'text-slate-600 hover:bg-slate-50'
                        }`}
                        >
                        <Activity size={14} /> 相关性 (散点图)
                        </button>
                    </div>
                </div>

                {/* 2. Axes Configuration */}
                <div className="space-y-1.5 lg:col-span-2">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <MoveVertical size={12}/> 坐标轴映射
                    </label>
                    <div className="flex gap-2">
                        {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={activeXKey} onChange={(e) => setUserXAxisKey(e.target.value)}
                                    className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                                >
                                    {numericProperties.map(p => <option key={p} value={p}>X轴: {p}</option>)}
                                </select>
                             </div>
                        )}

                        <div className="flex-1 min-w-[120px]">
                            <select 
                                value={activeYKey} onChange={(e) => setUserYAxisKey(e.target.value)}
                                className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                            >
                                {numericProperties.map(p => <option key={p} value={p}>{chartType === 'bar' ? '数值:' : 'Y轴:'} {p}</option>)}
                            </select>
                        </div>

                         {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={zAxisKey} onChange={(e) => setZAxisKey(e.target.value)}
                                    className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                                >
                                    <option value="none">Z轴: 无 (默认大小)</option>
                                    {numericProperties.map(p => <option key={p} value={p}>Z轴: {p}</option>)}
                                </select>
                             </div>
                        )}
                    </div>
                </div>

                {/* 3. Style & Color */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <Palette size={12}/> 样式与分组
                    </label>
                    <div className="flex gap-2 items-center">
                         <select 
                            value={colorByKey} onChange={(e) => setColorByKey(e.target.value)}
                            className="flex-1 bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                        >
                            <option value="none">颜色: 单一颜色</option>
                            <optgroup label="分类属性">
                                {categoricalProperties.map(p => <option key={p} value={p}>按 {p} 分组</option>)}
                            </optgroup>
                        </select>
                        {chartType === 'scatter' && (
                             <button
                                onClick={() => setShowTrendline(!showTrendline)}
                                title="切换趋势线"
                                className={`p-1.5 rounded border transition-colors ${showTrendline ? 'bg-indigo-50 text-indigo-600 border-indigo-200' : 'bg-white text-slate-400 border-slate-200'}`}
                             >
                                 <TrendingUp size={16} />
                             </button>
                        )}
                    </div>
                </div>
            </div>
        )}
      </div>

      {/* Chart Canvas */}
      <div className="flex-1 p-6 relative w-full h-full">
        {activeYKey && (
            <ResponsiveContainer width="100%" height="100%">
            {chartType === 'bar' ? (
                <BarChart
                data={chartData}
                margin={{ top: 20, right: 30, left: 20, bottom: 40 }}
                >
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis 
                    dataKey="name" 
                    stroke="#64748b" 
                    fontSize={12} 
                    tickLine={false} 
                    axisLine={{ stroke: '#cbd5e1' }} 
                    interval={0} 
                    angle={-30} 
                    textAnchor="end" 
                    height={60} 
                />
                <YAxis 
                    stroke="#64748b" 
                    fontSize={12} 
                    tickLine={false} 
                    axisLine={{ stroke: '#cbd5e1' }} 
                    domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { textAnchor: 'middle', fill: '#94a3b8' } }} 
                />
                <RechartsTooltip content={<CustomTooltip />} cursor={{ fill: '#f1f5f9' }} />
                <Legend />
                <Bar 
                    dataKey={activeYKey} 
                    fill="#3b82f6" 
                    radius={[4, 4, 0, 0]} 
                    name={yAxisLabel} 
                    barSize={40}
                    isAnimationActive={false} // Disable animation to prevent potential white-screen errors on mount
                >
                    {colorByKey !== 'none' && chartData.map((entry, index) => {
                        const val = String(entry[colorByKey] || '未分类');
                        return <Cell key={`cell-${index}`} fill={colorMap?.[val] || '#3b82f6'} />;
                    })}
                    <LabelList dataKey={activeYKey} position="top" fill="#64748b" fontSize={12} formatter={(val: number) => val.toFixed(2)} />
                </Bar>
                </BarChart>
            ) : (
                <ScatterChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis 
                    type="number" dataKey={activeXKey} name={activeXKey} stroke="#64748b" fontSize={12} domain={['auto', 'auto']}
                    label={{ value: xAxisLabel, position: 'bottom', offset: 0, style: { fill: '#64748b' } }} 
                />
                <YAxis 
                    type="number" dataKey={activeYKey} name={activeYKey} stroke="#64748b" fontSize={12} domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { fill: '#64748b' } }} 
                />
                {zAxisKey !== 'none' && (
                    <ZAxis type="number" dataKey={zAxisKey} range={[60, 600]} name={zAxisKey} unit={zAxisUnit} />
                )}

                <RechartsTooltip content={<CustomTooltip />} cursor={{ strokeDasharray: '3 3' }} />
                <Legend />

                {colorByKey !== 'none' && scatterGroups ? (
                    Object.entries(scatterGroups).map(([groupName, groupData], index) => (
                        <Scatter 
                            key={groupName}
                            name={groupName}
                            data={groupData}
                            fill={COLORS[index % COLORS.length]}
                            isAnimationActive={false}
                        />
                    ))
                ) : (
                    <Scatter name="产品分布" data={chartData} fill="#3b82f6" isAnimationActive={false} />
                )}

                {showTrendline && trendlineData.length > 0 && (
                    <Scatter name="趋势线" data={trendlineData} line={{ stroke: '#ef4444', strokeWidth: 2, strokeDasharray: '5 5' }} shape={() => null} legendType="none" tooltipType="none" isAnimationActive={false}/>
                )}
                </ScatterChart>
            )}
            </ResponsiveContainer>
        )}

        {chartType === 'bar' && colorByKey !== 'none' && colorMap && (
             <div className="absolute top-4 right-6 bg-white/90 p-2 rounded border border-slate-200 text-xs shadow-sm max-w-[150px]">
                 <p className="font-semibold text-slate-500 mb-1 border-b border-slate-100 pb-1">按 {colorByKey}</p>
                 <div className="space-y-1 max-h-[100px] overflow-y-auto custom-scrollbar">
                     {Object.entries(colorMap).map(([label, color]) => (
                         <div key={label} className="flex items-center gap-2">
                             <div className="w-2 h-2 rounded-full" style={{ backgroundColor: color }}></div>
                             <span className="truncate text-slate-600" title={label}>{label}</span>
                         </div>
                     ))}
                 </div>
             </div>
        )}
      </div>

      <div className="px-6 py-2 bg-slate-50 border-t border-slate-200 text-[10px] text-slate-400 flex justify-between flex-shrink-0">
