import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { MessageSquare, Send, Image as ImageIcon, Sparkles, X, Loader2, BrainCircuit, Bot, User } from 'lucide-react';
import { Product } from '../types';

interface AIAssistantProps {
  contextData: Product[];
}

interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  image?: string;
  isThinking?: boolean;
}

export const AIAssistant: React.FC<AIAssistantProps> = ({ contextData }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<Message[]>([
    { 
      id: 'welcome', 
      role: 'model', 
      text: '您好！我是 ResinAI 助手。我可以帮您分析当前的树脂数据，识别产品文档，或解答化工相关问题。' 
    }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const [useThinking, setUseThinking] = useState(false);
  const [attachedImage, setAttachedImage] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Auto-scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isOpen]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setAttachedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSend = async () => {
    if ((!input.trim() && !attachedImage) || isLoading) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      image: attachedImage || undefined
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setAttachedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Context Engineering: Summarize visible data for the AI
      const dataSummary = contextData.slice(0, 50).map(p => 
        `- ${p.gradeName} (${p.manufacturer}): ${Object.entries(p.properties).map(([k,v]) => `${k}=${v.value}${v.unit||''}`).join(', ')}`
      ).join('\n');

      const systemInstruction = `You are ResinAI, an expert assistant for a petrochemical synthetic resin database.

      Context Data (First 50 visible items):
      ${dataSummary}

      Instructions:
      1. Answer questions based on the provided resin data when possible.
      2. If analyzing an image, describe the technical specs, material properties, or identify the form factor.
      3. Be concise and professional.
      `;

      let modelName = 'gemini-3-flash-preview';
      let config: any = {
        systemInstruction,
      };

      // Configuration logic based on features
      if (attachedImage) {
        // Feature: Analyze Images -> Must use gemini-3-pro-preview
        modelName = 'gemini-3-pro-preview';
      } else if (useThinking) {
        // Feature: Thinking Mode -> Must use gemini-3-pro-preview with high thinking budget
        modelName = 'gemini-3-pro-preview';
        config.thinkingConfig = { thinkingBudget: 32768 };
        // Note: Do not set maxOutputTokens when using thinkingConfig
      }

      // Prepare contents
      let contents: any;

      if (userMsg.image) {
        // Split base64 to get data and mimeType
        const [meta, data] = userMsg.image.split(',');
        const mimeType = meta.match(/:(.*?);/)?.[1] || 'image/png';

        contents = {
          parts: [
            { inlineData: { mimeType, data } },
            { text: userMsg.text || "Please analyze this image." }
          ]
        };
      } else {
        contents = {
            parts: [{ text: userMsg.text }]
        };
      }

      const response = await ai.models.generateContent({
        model: modelName,
        contents,
        config
      });

      const responseText = response.text || "I processed that, but produced no text output.";

      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: responseText
      }]);

    } catch (error: any) {
      console.error("GenAI Error:", error);
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: `Error: ${error.message || "Something went wrong."}`
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* Floating Action Button */}
      {!isOpen && (
        <button
          onClick={() => setIsOpen(true)}
          className="fixed bottom-6 right-6 w-14 h-14 bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-full shadow-lg hover:shadow-xl transition-all hover:scale-105 flex items-center justify-center z-50 group"
          title="Open ResinAI Assistant"
        >
          <Sparkles className="w-6 h-6 animate-pulse" />
          <div className="absolute -top-1 -right-1 w-3 h-3 bg-red-500 rounded-full border-2 border-white"></div>
        </button>
      )}

      {/* Chat Window */}
      {isOpen && (
        <div className="fixed bottom-6 right-6 w-96 h-[600px] max-h-[80vh] bg-white rounded-2xl shadow-2xl border border-slate-200 flex flex-col z-50 animate-in slide-in-from-bottom-5 duration-300">

          {/* Header */}
          <div className="flex items-center justify-between p-4 border-b border-slate-100 bg-gradient-to-r from-blue-50 to-indigo-50 rounded-t-2xl">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 bg-indigo-100 text-indigo-600 rounded-full flex items-center justify-center">
                <Bot size={18} />
              </div>
              <div>
                <h3 className="font-bold text-slate-800 text-sm">ResinAI 助手</h3>
                <p className="text-[10px] text-slate-500 flex items-center gap-1">
                  Powered by Gemini 3 <Sparkles size={8} />
                </p>
              </div>
            </div>
            <button 
              onClick={() => setIsOpen(false)}
              className="text-slate-400 hover:text-slate-600 p-1 hover:bg-white rounded-full transition-colors"
            >
              <X size={18} />
            </button>
          </div>

          {/* Messages Area */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50/50">
            {messages.map((msg) => (
              <div
                key={msg.id}
                className={`flex gap-3 ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}
              >
                <div 
                  className={`w-8 h-8 rounded-full flex-shrink-0 flex items-center justify-center text-xs
                  ${msg.role === 'user' ? 'bg-slate-200 text-slate-600' : 'bg-indigo-600 text-white shadow-md'}
                  `}
                >
                  {msg.role === 'user' ? <User size={14} /> : <Sparkles size={14} />}
                </div>

                <div className={`max-w-[80%] space-y-2 ${msg.role === 'user' ? 'items-end flex flex-col' : ''}`}>
                    {msg.image && (
                        <img 
                            src={msg.image} 
                            alt="Uploaded" 
                            className="max-w-full h-auto rounded-lg border border-slate-200 shadow-sm"
                            style={{ maxHeight: '150px' }} 
                        />
                    )}
                    <div
                        className={`p-3 text-sm rounded-2xl shadow-sm whitespace-pre-wrap leading-relaxed
                        ${msg.role === 'user' 
                            ? 'bg-white text-slate-800 border border-slate-100 rounded-tr-none' 
                            : 'bg-indigo-50 text-slate-800 border border-indigo-100 rounded-tl-none'}
                        `}
                    >
                        {msg.text}
                    </div>
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex gap-3">
                <div className="w-8 h-8 bg-indigo-600 text-white rounded-full flex items-center justify-center shadow-md">
                    <Sparkles size={14} />
                </div>
                <div className="bg-indigo-50 p-3 rounded-2xl rounded-tl-none border border-indigo-100 flex items-center gap-2">
                   <Loader2 size={16} className="animate-spin text-indigo-500" />
                   <span className="text-xs text-indigo-500 font-medium">
                       {useThinking ? '深度思考中 (Thinking Mode)...' : '正在分析...'}
                   </span>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input Area */}
          <div className="p-3 bg-white border-t border-slate-100 rounded-b-2xl">
            {/* Toolbar */}
            <div className="flex items-center gap-2 mb-2 px-1">
                <button
                    onClick={() => setUseThinking(!useThinking)}
                    className={`flex items-center gap-1.5 px-2 py-1 rounded-full text-[10px] font-medium transition-all border
                    ${useThinking 
                        ? 'bg-purple-100 text-purple-700 border-purple-200 shadow-inner' 
                        : 'bg-slate-50 text-slate-500 border-slate-200 hover:bg-slate-100'}
                    `}
                    title="Toggle Thinking Mode (Gemini 3 Pro)"
                >
                    <BrainCircuit size={12} />
                    {useThinking ? '深度思考 ON' : '深度思考 OFF'}
                </button>
            </div>

            <div className="relative flex items-center gap-2">
                {/* Image Upload */}
                <input 
                    type="file" 
                    accept="image/*" 
                    ref={fileInputRef}
                    className="hidden"
                    onChange={handleImageUpload}
                />
                <button 
                    onClick={() => fileInputRef.current?.click()}
                    className={`p-2 rounded-full transition-colors ${attachedImage ? 'bg-green-100 text-green-600' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}
                    title="上传图片分析"
                >
                    <ImageIcon size={18} />
                </button>

                {/* Text Input */}
                <input
                    type="text"
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                    placeholder={attachedImage ? "描述这张图片..." : "输入问题..."}
                    className="flex-1 bg-slate-50 border border-slate-200 text-slate-900 text-sm rounded-full focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 px-4 py-2 transition-all outline-none"
                    disabled={isLoading}
                />

                {/* Send Button */}
                <button
                    onClick={handleSend}
                    disabled={isLoading || (!input.trim() && !attachedImage)}
                    className="p-2 bg-indigo-600 text-white rounded-full hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed shadow-md transition-all active:scale-95"
                >
                    <Send size={18} />
                </button>
            </div>
            {attachedImage && (
                 <div className="mt-2 flex items-center gap-2 text-xs text-slate-500 bg-slate-50 px-2 py-1 rounded border border-slate-100 w-max">
                    <span className="truncate max-w-[200px]">已附加图片</span>
                    <button onClick={() => setAttachedImage(null)} className="hover:text-red-500"><X size={12}/></button>
                 </div>
            )}
          </div>
        </div>
      )}
    </>
  );
};

