import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { MessageSquare, Send, Image as ImageIcon, Sparkles, X, Loader2, BrainCircuit, Bot, User, ChevronDown, Cpu } from 'lucide-react';
import { Product } from '../types';

interface AIAssistantProps {
  contextData: Product[];
}

interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  image?: string;
  isThinking?: boolean;
}

export const AIAssistant: React.FC<AIAssistantProps> = ({ contextData }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<Message[]>([
    { 
      id: 'welcome', 
      role: 'model', 
      text: '您好！我是 ResinAI 助手。我可以帮您分析当前的树脂数据，识别产品文档，或解答化工相关问题。' 
    }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const [useThinking, setUseThinking] = useState(false);
  const [selectedModel, setSelectedModel] = useState('gemini-3-flash-preview');
  const [attachedImage, setAttachedImage] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Auto-scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isOpen]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setAttachedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSend = async () => {
    if ((!input.trim() && !attachedImage) || isLoading) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      image: attachedImage || undefined
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setAttachedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Context Engineering: Summarize visible data for the AI
      const dataSummary = contextData.slice(0, 50).map(p => 
        `- ${p.gradeName} (${p.manufacturer}): ${Object.entries(p.properties).map(([k,v]) => `${k}=${v.value}${v.unit||''}`).join(', ')}`
      ).join('\n');

      const systemInstruction = `You are ResinAI, an expert assistant for a petrochemical synthetic resin database.

      Context Data (First 50 visible items):
      ${dataSummary}

      Instructions:
      1. Answer questions based on the provided resin data when possible.
      2. If analyzing an image, describe the technical specs, material properties, or identify the form factor.
      3. Be concise and professional.
      `;

      let modelName = selectedModel;
      let config: any = {
        systemInstruction,
      };

      // Configuration logic based on features
      if (useThinking) {
        // Feature: Thinking Mode
        // Gemini 3 Flash supports thinking but with a smaller budget than Pro usually.
        // We set a budget appropriate for the series.
        const budget = modelName.includes('pro') ? 32768 : 16000;
        config.thinkingConfig = { thinkingBudget: budget };
        // Note: Do not set maxOutputTokens when using thinkingConfig
      }

      // Prepare contents
      let contents: any;

      if (userMsg.image) {
        // Split base64 to get data and mimeType
        const [meta, data] = userMsg.image.split(',');
        const mimeType = meta.match(/:(.*?);/)?.[1] || 'image/png';

        contents = {
          parts: [
            { inlineData: { mimeType, data } },
            { text: userMsg.text || "Please analyze this image." }
          ]
        };
      } else {
        contents = {
            parts: [{ text: userMsg.text }]
        };
      }

      const response = await ai.models.generateContent({
        model: modelName,
        contents,
        config
      });

      const responseText = response.text || "I processed that, but produced no text output.";

      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: responseText
      }]);

    } catch (error: any) {
      console.error("GenAI Error:", error);
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: `Error: ${error.message || "Something went wrong."}`
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* Floating Action Button */}
      {!isOpen && (
        <button
          onClick={() => setIsOpen(true)}
          className="fixed bottom-6 right-6 w-14 h-14 bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-full shadow-lg hover:shadow-xl transition-all hover:scale-105 flex items-center justify-center z-50 group"
          title="Open ResinAI Assistant"
        >
          <Sparkles className="w-6 h-6 animate-pulse" />
          <div className="absolute -top-1 -right-1 w-3 h-3 bg-red-500 rounded-full border-2 border-white"></div>
        </button>
      )}

      {/* Chat Window */}
      {isOpen && (
        <div className="fixed bottom-6 right-6 w-96 h-[600px] max-h-[80vh] bg-white rounded-2xl shadow-2xl border border-slate-200 flex flex-col z-50 animate-in slide-in-from-bottom-5 duration-300">

          {/* Header */}
          <div className="flex flex-col p-4 border-b border-slate-100 bg-gradient-to-r from-blue-50 to-indigo-50 rounded-t-2xl gap-3">
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                    <div className="w-8 h-8 bg-indigo-100 text-indigo-600 rounded-full flex items-center justify-center">
                        <Bot size={18} />
                    </div>
                    <div>
                        <h3 className="font-bold text-slate-800 text-sm">ResinAI 助手</h3>
                        <p className="text-[10px] text-slate-500 flex items-center gap-1">
                        Powered by Gemini <Sparkles size={8} />
                        </p>
                    </div>
                </div>
                <button 
                onClick={() => setIsOpen(false)}
                className="text-slate-400 hover:text-slate-600 p-1 hover:bg-white rounded-full transition-colors"
                >
                <X size={18} />
                </button>
            </div>

            {/* Model Selector */}
            <div className="flex items-center gap-2 bg-white/50 p-1 rounded-lg border border-slate-200/50">
                <Cpu size={14} className="text-slate-400 ml-1" />
                <select 
                    value={selectedModel}
                    onChange={(e) => setSelectedModel(e.target.value)}
                    className="flex-1 bg-transparent text-xs text-slate-700 font-medium outline-none cursor-pointer"
                >
                    <option value="gemini-3-flash-preview">Gemini 3 Flash (快速/标准)</option>
                    <option value="gemini-3-pro-preview">Gemini 3 Pro (推理/专家)</option>
                    <option value="gemini-2.5-flash-latest">Gemini 2.5 Flash (稳定版)</option>
                    <option value="gemini-flash-lite-latest">Gemini Flash Lite (轻量级)</option>
                </select>
                <ChevronDown size={14} className="text-slate-400 mr-1" />
            </div>
          </div>

          {/* Messages Area */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50/50">
            {messages.map((msg) => (
              <div
                key={msg.id}
                className={`flex gap-3 ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}
              >
                <div 
                  className={`w-8 h-8 rounded-full flex-shrink-0 flex items-center justify-center text-xs
                  ${msg.role === 'user' ? 'bg-slate-200 text-slate-600' : 'bg-indigo-600 text-white shadow-md'}
                  `}
                >
                  {msg.role === 'user' ? <User size={14} /> : <Sparkles size={14} />}
                </div>

                <div className={`max-w-[80%] space-y-2 ${msg.role === 'user' ? 'items-end flex flex-col' : ''}`}>
                    {msg.image && (
                        <img 
                            src={msg.image} 
                            alt="Uploaded" 
                            className="max-w-full h-auto rounded-lg border border-slate-200 shadow-sm"
                            style={{ maxHeight: '150px' }} 
                        />
                    )}
                    <div
                        className={`p-3 text-sm rounded-2xl shadow-sm whitespace-pre-wrap leading-relaxed
                        ${msg.role === 'user' 
                            ? 'bg-white text-slate-800 border border-slate-100 rounded-tr-none' 
                            : 'bg-indigo-50 text-slate-800 border border-indigo-100 rounded-tl-none'}
                        `}
                    >
                        {msg.text}
                    </div>
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex gap-3">
                <div className="w-8 h-8 bg-indigo-600 text-white rounded-full flex items-center justify-center shadow-md">
                    <Sparkles size={14} />
                </div>
                <div className="bg-indigo-50 p-3 rounded-2xl rounded-tl-none border border-indigo-100 flex items-center gap-2">
                   <Loader2 size={16} className="animate-spin text-indigo-500" />
                   <span className="text-xs text-indigo-500 font-medium">
                       {useThinking ? `深度思考中 (${selectedModel})...` : '正在分析...'}
                   </span>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input Area */}
          <div className="p-3 bg-white border-t border-slate-100 rounded-b-2xl">
            {/* Toolbar */}
            <div className="flex items-center gap-2 mb-2 px-1">
                <button
                    onClick={() => setUseThinking(!useThinking)}
                    className={`flex items-center gap-1.5 px-2 py-1 rounded-full text-[10px] font-medium transition-all border
                    ${useThinking 
                        ? 'bg-purple-100 text-purple-700 border-purple-200 shadow-inner' 
                        : 'bg-slate-50 text-slate-500 border-slate-200 hover:bg-slate-100'}
                    `}
                    title="Enable Thinking Mode (Recommended for complex reasoning)"
                >
                    <BrainCircuit size={12} />
                    {useThinking ? '深度思考 ON' : '深度思考 OFF'}
                </button>
            </div>

            <div className="relative flex items-center gap-2">
                {/* Image Upload */}
                <input 
                    type="file" 
                    accept="image/*" 
                    ref={fileInputRef}
                    className="hidden"
                    onChange={handleImageUpload}
                />
                <button 
                    onClick={() => fileInputRef.current?.click()}
                    className={`p-2 rounded-full transition-colors ${attachedImage ? 'bg-green-100 text-green-600' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}
                    title="上传图片分析"
                >
                    <ImageIcon size={18} />
                </button>

                {/* Text Input */}
                <input
                    type="text"
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                    placeholder={attachedImage ? "描述这张图片..." : "输入问题..."}
                    className="flex-1 bg-slate-50 border border-slate-200 text-slate-900 text-sm rounded-full focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 px-4 py-2 transition-all outline-none"
                    disabled={isLoading}
                />

                {/* Send Button */}
                <button
                    onClick={handleSend}
                    disabled={isLoading || (!input.trim() && !attachedImage)}
                    className="p-2 bg-indigo-600 text-white rounded-full hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed shadow-md transition-all active:scale-95"
                >
                    <Send size={18} />
                </button>
            </div>
            {attachedImage && (
                 <div className="mt-2 flex items-center gap-2 text-xs text-slate-500 bg-slate-50 px-2 py-1 rounded border border-slate-100 w-max">
                    <span className="truncate max-w-[200px]">已附加图片</span>
                    <button onClick={() => setAttachedImage(null)} className="hover:text-red-500"><X size={12}/></button>
                 </div>
            )}
          </div>
        </div>
      )}
    </>
  );
};

import React, { useState } from 'react';
import { Category } from '../types';
import { ChevronRight, ChevronDown, Folder, FolderOpen, Layers, LayoutGrid, Beaker, Database } from 'lucide-react';

interface TreeSidebarProps {
  categories: Category[];
  selectedCategoryId: string | null;
  onSelectCategory: (id: string | null) => void;
}

const TreeNode: React.FC<{
  category: Category;
  selectedId: string | null;
  onSelect: (id: string) => void;
  depth: number;
}> = ({ category, selectedId, onSelect, depth }) => {
  const [isOpen, setIsOpen] = useState(depth < 1); // Auto expand root
  const hasChildren = category.children && category.children.length > 0;
  const isSelected = selectedId === category.id;

  return (
    <div className="select-none">
      <div
        onClick={(e) => {
            e.stopPropagation();
            if(hasChildren) setIsOpen(!isOpen);
            onSelect(category.id);
        }}
        className={`
          flex items-center px-3 py-2.5 cursor-pointer text-sm transition-all duration-200 mx-2 rounded-lg mb-0.5 group
          ${isSelected 
            ? 'bg-emerald-600 text-white shadow-md shadow-emerald-900/20 font-medium' 
            : 'text-slate-400 hover:bg-slate-800 hover:text-slate-100'}
        `}
        style={{ paddingLeft: `${depth * 16 + 12}px` }}
      >
        <div className={`w-4 h-4 mr-2 flex items-center justify-center shrink-0 transition-transform duration-200 ${isOpen && hasChildren ? 'rotate-90' : ''}`}>
            {hasChildren && (
                <ChevronRight size={14} className={isSelected ? 'text-white' : 'text-slate-500 group-hover:text-slate-300'} />
            )}
        </div>
        <div className={`mr-2.5 ${isSelected ? 'text-white' : 'text-slate-500 group-hover:text-slate-300'}`}>
            {hasChildren ? (isOpen ? <FolderOpen size={16}/> : <Folder size={16}/>) : <Layers size={16}/>}
        </div>
        <span className="truncate">{category.name}</span>
      </div>
      {isOpen && hasChildren && (
        <div className="border-l border-slate-700/50 ml-[23px] my-1">
          {category.children!.map((child) => (
            <TreeNode
              key={child.id}
              category={child}
              selectedId={selectedId}
              onSelect={onSelect}
              depth={depth + 1}
            />
          ))}
        </div>
      )}
    </div>
  );
};

