import React from 'react';
import { Product, ColumnConfig } from '../types';
import { MoreHorizontal, FileText, Factory, Tag, CalendarClock } from 'lucide-react';

interface DataGridProps {
  data: Product[];
  columns: ColumnConfig[];
  isLoading: boolean;
}

export const DataGrid: React.FC<DataGridProps> = ({ data, columns, isLoading }) => {
  const visibleColumns = columns.filter((c) => c.visible);

  const isNumericColumn = (key: string) => {
    if (['gradeName', 'manufacturer', 'updatedAt'].includes(key)) return false;
    for (const p of data.slice(0, 5)) {
        const val = p.properties[key]?.value;
        if (val !== undefined && val !== null && val !== '') {
             if (typeof val === 'number') return true;
             if (!isNaN(Number(val))) return true;
        }
    }
    return false;
  };

  if (isLoading) {
    return (
        <div className="flex flex-col items-center justify-center h-64 text-slate-400">
            <div className="w-8 h-8 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin mb-4"></div>
            <span className="text-sm font-medium">Loading synthetic resin data...</span>
        </div>
    );
  }

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-[500px] text-slate-400 bg-white border border-slate-200 rounded-xl shadow-sm">
        <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mb-4">
            <FileText size={32} className="text-slate-300" />
        </div>
        <p className="text-lg font-semibold text-slate-700">No products found</p>
        <p className="text-sm text-slate-500 mt-1">Try adjusting your filters or search query.</p>
      </div>
    );
  }

  return (
    <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden flex flex-col h-full">
      <div className="overflow-x-auto overflow-y-auto scrollbar-thin scrollbar-thumb-slate-200 scrollbar-track-transparent">
        <table className="w-full text-sm text-left border-collapse">
          <thead className="text-xs text-slate-500 uppercase bg-slate-50/80 sticky top-0 z-10 backdrop-blur-sm">
            <tr>
              {visibleColumns.map((col) => {
                  const isNum = isNumericColumn(col.key);
                  return (
                      <th key={col.key} className={`px-5 py-3.5 font-semibold border-b border-slate-200 whitespace-nowrap bg-slate-50 ${isNum ? 'text-right' : 'text-left'}`}>
                          {col.label}
                      </th>
                  );
              })}
              <th className="px-5 py-3.5 text-right border-b border-slate-200 bg-slate-50 sticky right-0 z-20 w-16">
                  Actions
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 bg-white">
            {data.map((product) => (
              <tr key={product.id} className="hover:bg-slate-50/80 transition-colors group">
                {visibleColumns.map((col) => {
                  const isNum = isNumericColumn(col.key);
                  let content: React.ReactNode = <span className="text-slate-200">-</span>;

                  if (col.key === 'gradeName') {
                      content = (
                        <div className="flex items-center gap-2">
                             <div className="w-2 h-2 rounded-full bg-emerald-500/50"></div>
                             <span className="font-bold text-slate-700 group-hover:text-emerald-700 transition-colors">{product.gradeName}</span>
                        </div>
                      );
                  } else if (col.key === 'manufacturer') {
                      content = (
                          <div className="flex items-center gap-2 text-slate-600">
                              <Factory size={13} className="text-slate-400" />
                              <span className="truncate max-w-[180px]" title={product.manufacturer}>{product.manufacturer}</span>
                          </div>
                      );
                  } else if (col.key === 'updatedAt') {
                      content = (
                        <div className="flex items-center gap-1.5 text-slate-400 text-xs">
                             <CalendarClock size={12}/>
                             <span className="font-mono">{product.updatedAt}</span>
                        </div>
                      );
                  } else {
                      const prop = product.properties[col.key];
                      if (prop && prop.value !== undefined && prop.value !== null && prop.value !== '') {
                          content = (
                              <span className="inline-flex items-baseline">
                                  {prop.value} 
                                  {prop.unit && <span className="text-slate-400 text-[10px] ml-1 font-medium">{prop.unit}</span>}
                              </span>
                          );
                      }
                  }

                  return (
                    <td key={`${product.id}-${col.key}`} className={`px-5 py-3 border-b border-slate-100 whitespace-nowrap ${isNum ? 'text-right font-mono text-slate-700' : 'text-slate-600'}`}>
                      {content}
                    </td>
                  );
                })}
                <td className="px-5 py-3 text-right border-b border-slate-100 sticky right-0 bg-white group-hover:bg-slate-50/80">
                  <button className="p-1.5 rounded-lg text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 transition-colors">
                      <MoreHorizontal size={18} />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="px-5 py-3 border-t border-slate-200 bg-slate-50 text-xs text-slate-500 flex justify-between items-center sticky bottom-0 z-20">
         <span>Showing {data.length} records</span>
         <div className="flex gap-2">
             <span className="px-2 py-0.5 bg-white border border-slate-200 rounded text-slate-400">Page 1</span>
         </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { CATEGORY_TREE, MOCK_PRODUCTS } from './constants';
import { Product, ColumnConfig, ViewMode } from './types';
import { TreeSidebar } from './components/TreeSidebar';
import { DataGrid } from './components/DataGrid';
import { DataVisualizer } from './components/DataVisualizer';
import { TopBar } from './components/TopBar';
import { ImportModal } from './components/ImportModal';
import { AIAssistant } from './components/AIAssistant';
import { LayoutDashboard, Database, Activity } from 'lucide-react';

const getDynamicColumns = (products: Product[]): ColumnConfig[] => {
  const propertyKeys = new Set<string>();
  products.forEach(p => {
    Object.keys(p.properties).forEach(k => propertyKeys.add(k));
  });

  const defaultVisible = ['密度', '熔体流动速率', '应用', '类型', '典型应用', '硬度', '悬臂梁缺口冲击', '拉伸强度'];

  const dynamicCols: ColumnConfig[] = Array.from(propertyKeys).map(key => ({
    key,
    label: key,
    visible: defaultVisible.includes(key),
    isSystem: false
  })).sort((a, b) => {
      // Prioritize numeric columns slightly for better default view
      const aIsLikelyImportant = defaultVisible.includes(a.key);
      const bIsLikelyImportant = defaultVisible.includes(b.key);
      if (aIsLikelyImportant && !bIsLikelyImportant) return -1;
      if (!aIsLikelyImportant && bIsLikelyImportant) return 1;
      return a.label.localeCompare(b.label);
  });

  const systemCols: ColumnConfig[] = [
    { key: 'gradeName', label: '牌号', visible: true, isSystem: true },
    { key: 'manufacturer', label: '生产厂家', visible: true, isSystem: true },
    { key: 'updatedAt', label: '更新时间', visible: false, isSystem: false },
  ];

  return [...systemCols, ...dynamicCols];
};

const App: React.FC = () => {
  const [selectedCategoryId, setSelectedCategoryId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [columns, setColumns] = useState<ColumnConfig[]>([]);
  const [isImportOpen, setIsImportOpen] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>('grid');

  useEffect(() => {
    setColumns(getDynamicColumns(MOCK_PRODUCTS));
  }, []);

  const handleToggleColumn = (key: string) => {
    setColumns(cols => cols.map(c => 
      c.key === key ? { ...c, visible: !c.visible } : c
    ));
  };

  const handleToggleAllColumns = (visible: boolean) => {
    setColumns(cols => cols.map(c => 
      c.isSystem ? c : { ...c, visible }
    ));
  };

  const filteredData = useMemo(() => {
    return MOCK_PRODUCTS.filter(product => {
      const matchesCategory = selectedCategoryId 
        ? product.categoryIds.includes(selectedCategoryId)
        : true;

      if (!matchesCategory) return false;

      const query = searchQuery.toLowerCase();
      const matchesSearch = 
        product.gradeName.toLowerCase().includes(query) ||
        product.manufacturer.toLowerCase().includes(query) ||
        Object.keys(product.properties).some(k => k.toLowerCase().includes(query));

      return matchesSearch;
    });
  }, [selectedCategoryId, searchQuery]);

  return (
    <div className="flex h-screen bg-slate-50 font-sans text-slate-900 overflow-hidden">

      {/* Sidebar - Navigation */}
      <TreeSidebar 
        categories={CATEGORY_TREE}
        selectedCategoryId={selectedCategoryId}
        onSelectCategory={setSelectedCategoryId}
      />

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0 h-full relative">

        {/* Top Header */}
        <TopBar 
            searchQuery={searchQuery}
            onSearchChange={setSearchQuery}
            columns={columns}
            onToggleColumn={handleToggleColumn}
            onToggleAllColumns={handleToggleAllColumns}
            onOpenImport={() => setIsImportOpen(true)}
            viewMode={viewMode}
            onViewModeChange={setViewMode}
        />

        {/* Content Body */}
        <div className="flex-1 p-6 overflow-y-auto overflow-x-hidden w-full">
            {/* Page Header */}
            <div className="flex items-end justify-between mb-6 flex-shrink-0 animate-in fade-in slide-in-from-top-4 duration-300">
                <div>
                    <h1 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
                        {viewMode === 'grid' ? <Database size={24} className="text-emerald-600"/> : <Activity size={24} className="text-indigo-600"/>}
                        {selectedCategoryId 
                            ? `Category: ${selectedCategoryId}` 
                            : viewMode === 'grid' ? 'Database Overview' : 'Data Analytics'}
                    </h1>
                    <p className="text-slate-500 text-sm mt-1 ml-8">
                        Found <span className="font-semibold text-slate-900">{filteredData.length}</span> synthetic resin products matching your criteria.
                    </p>
                </div>
            </div>

            <div className="w-full h-[calc(100%-80px)] animate-in fade-in zoom-in-95 duration-300">
                {viewMode === 'grid' ? (
                    <DataGrid 
                        data={filteredData}
                        columns={columns}
                        isLoading={false}
                    />
                ) : (
                    <DataVisualizer data={filteredData} />
                )}
            </div>
        </div>
      </div>

      <ImportModal 
        isOpen={isImportOpen} 
        onClose={() => setIsImportOpen(false)} 
      />

      {/* Gemini Powered Assistant */}
      <AIAssistant contextData={filteredData} />
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Send, Image as ImageIcon, Sparkles, X, Loader2, BrainCircuit, Bot, User, ChevronDown, Cpu, MessageSquarePlus } from 'lucide-react';
import { Product } from '../types';

interface AIAssistantProps {
  contextData: Product[];
}

interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  image?: string;
  isThinking?: boolean;
}

export const AIAssistant: React.FC<AIAssistantProps> = ({ contextData }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<Message[]>([
    { 
      id: 'welcome', 
      role: 'model', 
      text: '你好！我是 ResinDB 智能助手。基于当前筛选的树脂数据，我可以帮你进行性能对比、牌号推荐或解答化工技术问题。' 
    }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const [useThinking, setUseThinking] = useState(false);
  const [selectedModel, setSelectedModel] = useState('gemini-3-flash-preview');
  const [attachedImage, setAttachedImage] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isOpen]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setAttachedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSend = async () => {
    if ((!input.trim() && !attachedImage) || isLoading) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      image: attachedImage || undefined
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setAttachedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const dataSummary = contextData.slice(0, 50).map(p => 
        `- ${p.gradeName} (${p.manufacturer}): ${Object.entries(p.properties).map(([k,v]) => `${k}=${v.value}${v.unit||''}`).join(', ')}`
      ).join('\n');

      const systemInstruction = `You are ResinAI, an expert assistant for a petrochemical synthetic resin database (ResinDB).

      Current Data Context (First 50 visible items from user filter):
      ${dataSummary}

      Instructions:
      1. Answer questions based specifically on the provided resin data when possible.
      2. If the user asks for comparison, use the numeric data to compare properties like Density, MFR, Tensile Strength etc.
      3. If analyzing an image, identify standard resin pellets, technical data sheets, or plastic part defects.
      4. Use a professional yet helpful tone.
      `;

      let modelName = selectedModel;
      let config: any = {
        systemInstruction,
      };

      if (useThinking) {
        const budget = modelName.includes('pro') ? 32768 : 16000;
        config.thinkingConfig = { thinkingBudget: budget };
      }

      let contents: any;

      if (userMsg.image) {
        const [meta, data] = userMsg.image.split(',');
        const mimeType = meta.match(/:(.*?);/)?.[1] || 'image/png';

        contents = {
          parts: [
            { inlineData: { mimeType, data } },
            { text: userMsg.text || "Please analyze this image." }
          ]
        };
      } else {
        contents = {
            parts: [{ text: userMsg.text }]
        };
      }

      const response = await ai.models.generateContent({
        model: modelName,
        contents,
        config
      });

      const responseText = response.text || "Thinking process completed, but no direct text output was generated.";

      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: responseText
      }]);

    } catch (error: any) {
      console.error("GenAI Error:", error);
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: `Error: ${error.message || "Something went wrong."}`
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* Floating Trigger */}
      {!isOpen && (
        <button
          onClick={() => setIsOpen(true)}
          className="fixed bottom-8 right-8 w-14 h-14 bg-slate-900 text-white rounded-2xl shadow-2xl hover:shadow-emerald-900/30 hover:scale-105 transition-all flex items-center justify-center z-50 group border border-slate-700"
        >
          <div className="absolute inset-0 bg-gradient-to-tr from-emerald-600 to-indigo-600 rounded-2xl opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
          <Sparkles className="w-6 h-6 relative z-10" strokeWidth={1.5} />
          <div className="absolute -top-1 -right-1 w-3 h-3 bg-red-500 rounded-full border-2 border-slate-900 z-20"></div>
        </button>
      )}

      {/* Chat Window */}
      {isOpen && (
        <div className="fixed bottom-8 right-8 w-[420px] h-[650px] max-h-[85vh] bg-white rounded-3xl shadow-2xl border border-slate-200/60 flex flex-col z-50 animate-in slide-in-from-bottom-10 fade-in duration-300 overflow-hidden font-sans">

          {/* Header */}
          <div className="flex flex-col p-5 bg-white/90 backdrop-blur-md border-b border-slate-100 relative z-10">
            <div className="flex items-center justify-between mb-4">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-purple-600 text-white rounded-xl flex items-center justify-center shadow-lg shadow-indigo-200">
                        <Bot size={22} />
                    </div>
                    <div>
                        <h3 className="font-bold text-slate-900 text-base leading-tight">ResinAI Copilot</h3>
                        <div className="flex items-center gap-1.5 mt-0.5">
                            <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span>
                            <span className="text-[11px] text-slate-500 font-medium">Gemini Pro Active</span>
                        </div>
                    </div>
                </div>
                <button 
                    onClick={() => setIsOpen(false)}
                    className="w-8 h-8 flex items-center justify-center text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full transition-colors"
                >
                    <X size={20} />
                </button>
            </div>

            {/* Model Selector Pill */}
            <div className="flex items-center justify-between bg-slate-50 p-1 pl-3 pr-2 rounded-xl border border-slate-200/50">
                <div className="flex items-center gap-2 text-xs text-slate-600 font-medium">
                    <Cpu size={14} className="text-indigo-500" />
                    <select 
                        value={selectedModel}
                        onChange={(e) => setSelectedModel(e.target.value)}
                        className="bg-transparent outline-none cursor-pointer hover:text-indigo-600 transition-colors appearance-none pr-4"
