}

const TreeNode: React.FC<{
  category: Category;
  selectedId: string | null;
  onSelect: (id: string) => void;
  depth: number;
}> = ({ category, selectedId, onSelect, depth }) => {
  const [isOpen, setIsOpen] = useState(depth < 1); // Auto expand root
  const hasChildren = category.children && category.children.length > 0;
  const isSelected = selectedId === category.id;
  const { language } = useLanguage();

  return (
    <div className="select-none">
      <div
        onClick={(e) => {
            e.stopPropagation();
            if(hasChildren) setIsOpen(!isOpen);
            onSelect(category.id);
        }}
        className={`
          flex items-center px-3 py-2.5 cursor-pointer text-sm transition-all duration-200 mx-2 rounded-lg mb-0.5 group
          ${isSelected 
            ? 'bg-emerald-600 text-white shadow-md shadow-emerald-900/20 font-medium' 
            : 'text-slate-400 hover:bg-slate-800 hover:text-slate-100'}
        `}
        style={{ paddingLeft: `${depth * 16 + 12}px` }}
      >
        <div className={`w-4 h-4 mr-2 flex items-center justify-center shrink-0 transition-transform duration-200 ${isOpen && hasChildren ? 'rotate-90' : ''}`}>
            {hasChildren && (
                <ChevronRight size={14} className={isSelected ? 'text-white' : 'text-slate-500 group-hover:text-slate-300'} />
            )}
        </div>
        <div className={`mr-2.5 ${isSelected ? 'text-white' : 'text-slate-500 group-hover:text-slate-300'}`}>
            {hasChildren ? (isOpen ? <FolderOpen size={16}/> : <Folder size={16}/>) : <Layers size={16}/>}
        </div>
        <span className="truncate">{language === 'en' && category.nameEn ? category.nameEn : category.name}</span>
      </div>
      {isOpen && hasChildren && (
        <div className="border-l border-slate-700/50 ml-[23px] my-1">
          {category.children!.map((child) => (
            <TreeNode
              key={child.id}
              category={child}
              selectedId={selectedId}
              onSelect={onSelect}
              depth={depth + 1}
            />
          ))}
        </div>
      )}
