                        <div className="flex-1 min-w-[120px]">
                            <select 
                                value={activeYKey} onChange={(e) => setUserYAxisKey(e.target.value)}
                                className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                            >
                                {numericProperties.map(p => <option key={p} value={p}>{chartType === 'bar' ? t('val') : t('yAxis')}: {tProp(p)}</option>)}
                            </select>
                        </div>

                         {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={zAxisKey} onChange={(e) => setZAxisKey(e.target.value)}
                                    className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                                >
                                    <option value="none">{t('zAxis')}: {t('noneAxis')}</option>
                                    {numericProperties.map(p => <option key={p} value={p}>{t('zAxis')}: {tProp(p)}</option>)}
                                </select>
                             </div>
                        )}
                    </div>
                </div>

                {/* 3. Style & Color */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <Palette size={12}/> {t('styleGrouping')}
                    </label>
                    <div className="flex gap-2 items-center">
                         <select 
                            value={colorByKey} onChange={(e) => setColorByKey(e.target.value)}
                            className="flex-1 bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                        >
                            <option value="none">{t('colorSingle')}</option>
                            <optgroup label="Properties">
                                {categoricalProperties.map(p => <option key={p} value={p}>{t('groupBy').replace('{key}', tProp(p))}</option>)}
                            </optgroup>
                        </select>
                        {chartType === 'scatter' && (
                             <button
                                onClick={() => setShowTrendline(!showTrendline)}
                                title={t('trendline')}
                                className={`p-1.5 rounded border transition-colors ${showTrendline ? 'bg-indigo-50 text-indigo-600 border-indigo-200' : 'bg-white text-slate-400 border-slate-200'}`}
                             >
                                 <TrendingUp size={16} />
                             </button>
                        )}
                    </div>
                </div>
            </div>
        )}
      </div>

      {/* Chart Canvas */}
      <div className="flex-1 p-6 relative w-full h-full">
        {activeYKey && (
            <ResponsiveContainer width="100%" height="100%">
            {chartType === 'bar' ? (
                <BarChart
                data={chartData}
                margin={{ top: 20, right: 30, left: 20, bottom: 40 }}
                >
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis 
                    dataKey="name" 
                    stroke="#64748b" 
                    fontSize={12} 
                    tickLine={false} 
                    axisLine={{ stroke: '#cbd5e1' }} 
                    interval={0} 
                    angle={-30} 
                    textAnchor="end" 
                    height={60} 
                />
                <YAxis 
                    stroke="#64748b" 
                    fontSize={12} 
                    tickLine={false} 
                    axisLine={{ stroke: '#cbd5e1' }} 
                    domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { textAnchor: 'middle', fill: '#94a3b8' } }} 
                />
                <RechartsTooltip content={<CustomTooltip />} cursor={{ fill: '#f1f5f9' }} />
                <Legend />
                <Bar 
                    dataKey={activeYKey} 
                    fill="#3b82f6" 
                    radius={[4, 4, 0, 0]} 
                    name={yAxisLabel} 
                    barSize={40}
                    isAnimationActive={false} // Disable animation to prevent potential white-screen errors on mount
                >
                    {colorByKey !== 'none' && chartData.map((entry, index) => {
                        const val = String(entry[colorByKey] || 'Unclassified');
                        return <Cell key={`cell-${index}`} fill={colorMap?.[val] || '#3b82f6'} />;
                    })}
                    <LabelList dataKey={activeYKey} position="top" fill="#64748b" fontSize={12} formatter={(val: number) => val.toFixed(2)} />
                </Bar>
                </BarChart>
            ) : (
                <ScatterChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis 
                    type="number" dataKey={activeXKey} name={activeXKey} stroke="#64748b" fontSize={12} domain={['auto', 'auto']}
                    label={{ value: xAxisLabel, position: 'bottom', offset: 0, style: { fill: '#64748b' } }} 
                />
                <YAxis 
                    type="number" dataKey={activeYKey} name={activeYKey} stroke="#64748b" fontSize={12} domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { fill: '#64748b' } }} 
                />
                {zAxisKey !== 'none' && (
                    <ZAxis type="number" dataKey={zAxisKey} range={[60, 600]} name={zAxisKey} unit={zAxisUnit} />
                )}

                <RechartsTooltip content={<CustomTooltip />} cursor={{ strokeDasharray: '3 3' }} />
                <Legend />

                {colorByKey !== 'none' && scatterGroups ? (
                    Object.entries(scatterGroups).map(([groupName, groupData], index) => (
                        <Scatter 
                            key={groupName}
                            name={groupName}
                            data={groupData}
                            fill={COLORS[index % COLORS.length]}
                            isAnimationActive={false}
                        />
                    ))
                ) : (
                    <Scatter name={t('chartTitle')} data={chartData} fill="#3b82f6" isAnimationActive={false} />
                )}

                {showTrendline && trendlineData.length > 0 && (
                    <Scatter name={t('trendline')} data={trendlineData} line={{ stroke: '#ef4444', strokeWidth: 2, strokeDasharray: '5 5' }} shape={() => null} legendType="none" tooltipType="none" isAnimationActive={false}/>
                )}
                </ScatterChart>
            )}
            </ResponsiveContainer>
        )}

        {chartType === 'bar' && colorByKey !== 'none' && colorMap && (
             <div className="absolute top-4 right-6 bg-white/90 p-2 rounded border border-slate-200 text-xs shadow-sm max-w-[150px]">
                 <p className="font-semibold text-slate-500 mb-1 border-b border-slate-100 pb-1">{t('groupBy').replace('{key}', tProp(colorByKey))}</p>
                 <div className="space-y-1 max-h-[100px] overflow-y-auto custom-scrollbar">
                     {Object.entries(colorMap).map(([label, color]) => (
                         <div key={label} className="flex items-center gap-2">
                             <div className="w-2 h-2 rounded-full" style={{ backgroundColor: color }}></div>
                             <span className="truncate text-slate-600" title={label}>{label}</span>
                         </div>
                     ))}
                 </div>
             </div>
        )}
      </div>

      <div className="px-6 py-2 bg-slate-50 border-t border-slate-200 text-[10px] text-slate-400 flex justify-between flex-shrink-0">
         <span>ResinDB Visualization Engine v1.2</span>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Send, Image as ImageIcon, Sparkles, X, Loader2, BrainCircuit, Bot, User, ChevronDown, Cpu, MessageSquarePlus } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';

interface AIAssistantProps {
  contextData: Product[];
}

interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  image?: string;
  isThinking?: boolean;
}

export const AIAssistant: React.FC<AIAssistantProps> = ({ contextData }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const { t, language } = useLanguage();
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [useThinking, setUseThinking] = useState(false);
  const [selectedModel, setSelectedModel] = useState('gemini-3-flash-preview');
  const [attachedImage, setAttachedImage] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Reset/Init Welcome message when language changes or first open
  useEffect(() => {
    if (messages.length === 0) {
        setMessages([{ 
            id: 'welcome', 
            role: 'model', 
            text: t('welcomeMessage') 
        }]);
    }
  }, [t, messages.length]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isOpen]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setAttachedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSend = async () => {
    if ((!input.trim() && !attachedImage) || isLoading) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      image: attachedImage || undefined
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setAttachedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const dataSummary = contextData.slice(0, 50).map(p => 
        `- ${p.gradeName} (${p.manufacturer}): ${Object.entries(p.properties).map(([k,v]) => `${k}=${v.value}${v.unit||''}`).join(', ')}`
      ).join('\n');

      const systemInstruction = `You are ResinAI, an expert assistant for a petrochemical synthetic resin database (ResinDB).

      Current Data Context (First 50 visible items from user filter):
      ${dataSummary}

      Instructions:
      1. Answer questions based specifically on the provided resin data when possible.
      2. If the user asks for comparison, use the numeric data to compare properties like Density, MFR, Tensile Strength etc.
      3. If analyzing an image, identify standard resin pellets, technical data sheets, or plastic part defects.
      4. Answer in the requested language (${language === 'zh' ? 'Chinese' : 'English'}).
      `;

      let modelName = selectedModel;
      let config: any = {
        systemInstruction,
      };

      if (useThinking) {
        const budget = modelName.includes('pro') ? 32768 : 16000;
        config.thinkingConfig = { thinkingBudget: budget };
      }

      let contents: any;

      if (userMsg.image) {
        const [meta, data] = userMsg.image.split(',');
        const mimeType = meta.match(/:(.*?);/)?.[1] || 'image/png';

        contents = {
          parts: [
            { inlineData: { mimeType, data } },
            { text: userMsg.text || "Please analyze this image." }
          ]
        };
      } else {
        contents = {
            parts: [{ text: userMsg.text }]
        };
      }

      const response = await ai.models.generateContent({
        model: modelName,
        contents,
        config
      });

      const responseText = response.text || "Thinking process completed, but no direct text output was generated.";

      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: responseText
      }]);

    } catch (error: any) {
      console.error("GenAI Error:", error);
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: `${t('error')}: ${error.message || "Something went wrong."}`
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* Floating Trigger */}
      {!isOpen && (
        <button
          onClick={() => setIsOpen(true)}
          className="fixed bottom-8 right-8 w-14 h-14 bg-slate-900 text-white rounded-2xl shadow-2xl hover:shadow-emerald-900/30 hover:scale-105 transition-all flex items-center justify-center z-50 group border border-slate-700"
        >
          <div className="absolute inset-0 bg-gradient-to-tr from-emerald-600 to-indigo-600 rounded-2xl opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
          <Sparkles className="w-6 h-6 relative z-10" strokeWidth={1.5} />
          <div className="absolute -top-1 -right-1 w-3 h-3 bg-red-500 rounded-full border-2 border-slate-900 z-20"></div>
        </button>
      )}

      {/* Chat Window */}
      {isOpen && (
        <div className="fixed bottom-8 right-8 w-[420px] h-[650px] max-h-[85vh] bg-white rounded-3xl shadow-2xl border border-slate-200/60 flex flex-col z-50 animate-in slide-in-from-bottom-10 fade-in duration-300 overflow-hidden font-sans">

          {/* Header */}
          <div className="flex flex-col p-5 bg-white/90 backdrop-blur-md border-b border-slate-100 relative z-10">
            <div className="flex items-center justify-between mb-4">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-purple-600 text-white rounded-xl flex items-center justify-center shadow-lg shadow-indigo-200">
                        <Bot size={22} />
                    </div>
                    <div>
                        <h3 className="font-bold text-slate-900 text-base leading-tight">{t('copilot')}</h3>
                        <div className="flex items-center gap-1.5 mt-0.5">
                            <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span>
                            <span className="text-[11px] text-slate-500 font-medium">{t('modelActive')}</span>
                        </div>
                    </div>
                </div>
                <button 
                    onClick={() => setIsOpen(false)}
                    className="w-8 h-8 flex items-center justify-center text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full transition-colors"
                >
                    <X size={20} />
                </button>
            </div>

            {/* Model Selector Pill */}
            <div className="flex items-center justify-between bg-slate-50 p-1 pl-3 pr-2 rounded-xl border border-slate-200/50">
                <div className="flex items-center gap-2 text-xs text-slate-600 font-medium">
                    <Cpu size={14} className="text-indigo-500" />
                    <select 
                        value={selectedModel}
                        onChange={(e) => setSelectedModel(e.target.value)}
                        className="bg-transparent outline-none cursor-pointer hover:text-indigo-600 transition-colors appearance-none pr-4"
                    >
                        <option value="gemini-3-flash-preview">Gemini 3 Flash (Fast)</option>
                        <option value="gemini-3-pro-preview">Gemini 3 Pro (Reasoning)</option>
                        <option value="gemini-2.5-flash-latest">Gemini 2.5 Flash</option>
                    </select>
                </div>
                <div className="flex items-center">
                    <button
                        onClick={() => setUseThinking(!useThinking)}
                        className={`flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-[10px] font-bold uppercase tracking-wide transition-all ${
                            useThinking 
                            ? 'bg-purple-100 text-purple-700 shadow-sm' 
                            : 'text-slate-400 hover:bg-slate-200/50'
                        }`}
                    >
