  const handleAnalyzeUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];

    if (!file) {
      // No file selected, do nothing
      return;
    }

    try {
      const reader = new FileReader();

      reader.onload = async (event: ProgressEvent<FileReader>) => {
        const imageBase64 = event.target?.result as string;
        const prompt = `Analyze this image for resin defects or type: ${imageBase64}`;

        // Ensure the input value is reset after processing
        if (analyzeInputRef.current) {
          analyzeInputRef.current.value = "";
        }

        await handleSend(prompt, file);
      };

      reader.onerror = (error) => {
        console.error("Error reading the image file:", error);
      };
      reader.readAsDataURL(file);

    } catch (error) {
      console.error("Error during image analysis:", error);
    }
  };
