import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Send, Image as ImageIcon, Sparkles, X, Loader2, BrainCircuit, Bot, User, ChevronDown, Cpu, MessageSquarePlus, ScanEye } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';

interface AIAssistantProps {
  contextData: Product[];
}

interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  image?: string;
  isThinking?: boolean;
}

export const AIAssistant: React.FC<AIAssistantProps> = ({ contextData }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const { t, language } = useLanguage();
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [useThinking, setUseThinking] = useState(false);
  const [selectedModel, setSelectedModel] = useState('gemini-3-flash-preview');
  const [attachedImage, setAttachedImage] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const analyzeInputRef = useRef<HTMLInputElement>(null);

  // Reset/Init Welcome message when language changes or first open
  useEffect(() => {
    if (messages.length === 0) {
        setMessages([{ 
            id: 'welcome', 
            role: 'model', 
            text: t('welcomeMessage') 
        }]);
    }
  }, [t, messages.length]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isOpen]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setAttachedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
    // Reset value to allow re-selecting same file
    e.target.value = '';
  };

  const handleAnalyzeUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const imgData = reader.result as string;
        // Trigger analysis immediately
        const prompt = language === 'zh' 
          ? "请分析这张图片，识别其中可见的树脂类型、形态特征或任何潜在的缺陷（如晶点、杂质、色差）。" 
          : "Please analyze this image to identify potential resin types, morphological features, or any visible defects (like gels, impurities, discoloration).";

        handleSend(prompt, imgData);
      };
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  };

  const handleSend = async (manualText?: string, manualImage?: string) => {
    // Determine effective content (manual overrides take precedence)
    const textToSend = typeof manualText === 'string' ? manualText : input;
    const imageToSend = typeof manualImage === 'string' ? manualImage : attachedImage;

    if ((!textToSend.trim() && !imageToSend) || isLoading) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: textToSend,
      image: imageToSend || undefined
    };

    setMessages(prev => [...prev, userMsg]);

    // Only clear state if we used the state values
    if (typeof manualText !== 'string') setInput('');
    if (typeof manualImage !== 'string') setAttachedImage(null);

    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const dataSummary = contextData.slice(0, 50).map(p => 
        `- ${p.gradeName} (${p.manufacturer}): ${Object.entries(p.properties).map(([k,v]) => `${k}=${v.value}${v.unit||''}`).join(', ')}`
      ).join('\n');

      const systemInstruction = `You are ResinAI, an expert assistant for a petrochemical synthetic resin database (ResinDB).

      Current Data Context (First 50 visible items from user filter):
      ${dataSummary}

      Instructions:
      1. Answer questions based specifically on the provided resin data when possible.
      2. If the user asks for comparison, use the numeric data to compare properties like Density, MFR, Tensile Strength etc.
      3. If analyzing an image, identify standard resin pellets, technical data sheets, or plastic part defects.
      4. Answer in the requested language (${language === 'zh' ? 'Chinese' : 'English'}).
      `;

      let modelName = selectedModel;
      let config: any = {
        systemInstruction,
      };

      if (useThinking) {
        const budget = modelName.includes('pro') ? 32768 : 16000;
        config.thinkingConfig = { thinkingBudget: budget };
      }

      let contents: any;

      if (userMsg.image) {
        const [meta, data] = userMsg.image.split(',');
        const mimeType = meta.match(/:(.*?);/)?.[1] || 'image/png';

        contents = {
          parts: [
            { inlineData: { mimeType, data } },
            { text: userMsg.text || "Please analyze this image." }
          ]
        };
      } else {
        contents = {
            parts: [{ text: userMsg.text }]
        };
      }

      const response = await ai.models.generateContent({
        model: modelName,
        contents,
        config
      });

      const responseText = response.text || "Thinking process completed, but no direct text output was generated.";

      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: responseText
      }]);

    } catch (error: any) {
      console.error("GenAI Error:", error);
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: `${t('error')}: ${error.message || "Something went wrong."}`
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* Floating Trigger */}
      {!isOpen && (
        <button
          onClick={() => setIsOpen(true)}
          className="fixed bottom-8 right-8 w-14 h-14 bg-slate-900 text-white rounded-2xl shadow-2xl hover:shadow-emerald-900/30 hover:scale-105 transition-all flex items-center justify-center z-50 group border border-slate-700"
        >
          <div className="absolute inset-0 bg-gradient-to-tr from-emerald-600 to-indigo-600 rounded-2xl opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
          <Sparkles className="w-6 h-6 relative z-10" strokeWidth={1.5} />
          <div className="absolute -top-1 -right-1 w-3 h-3 bg-red-500 rounded-full border-2 border-slate-900 z-20"></div>
        </button>
      )}

      {/* Chat Window */}
      {isOpen && (
        <div className="fixed bottom-8 right-8 w-[420px] h-[650px] max-h-[85vh] bg-white rounded-3xl shadow-2xl border border-slate-200/60 flex flex-col z-50 animate-in slide-in-from-bottom-10 fade-in duration-300 overflow-hidden font-sans">

          {/* Header */}
          <div className="flex flex-col p-5 bg-white/90 backdrop-blur-md border-b border-slate-100 relative z-10">
            <div className="flex items-center justify-between mb-4">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-purple-600 text-white rounded-xl flex items-center justify-center shadow-lg shadow-indigo-200">
                        <Bot size={22} />
                    </div>
                    <div>
                        <h3 className="font-bold text-slate-900 text-base leading-tight">{t('copilot')}</h3>
                        <div className="flex items-center gap-1.5 mt-0.5">
                            <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span>
                            <span className="text-[11px] text-slate-500 font-medium">{t('modelActive')}</span>
                        </div>
                    </div>
                </div>
                <button 
                    onClick={() => setIsOpen(false)}
                    className="w-8 h-8 flex items-center justify-center text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full transition-colors"
                >
                    <X size={20} />
                </button>
            </div>

            {/* Model Selector Pill */}
            <div className="flex items-center justify-between bg-slate-50 p-1 pl-3 pr-2 rounded-xl border border-slate-200/50">
                <div className="flex items-center gap-2 text-xs text-slate-600 font-medium">
                    <Cpu size={14} className="text-indigo-500" />
                    <select 
                        value={selectedModel}
                        onChange={(e) => setSelectedModel(e.target.value)}
                        className="bg-transparent outline-none cursor-pointer hover:text-indigo-600 transition-colors appearance-none pr-4"
                    >
                        <option value="gemini-3-flash-preview">Gemini 3 Flash (Fast)</option>
                        <option value="gemini-3-pro-preview">Gemini 3 Pro (Reasoning)</option>
                        <option value="gemini-2.5-flash-latest">Gemini 2.5 Flash</option>
                    </select>
                </div>
                <div className="flex items-center">
                    <button
                        onClick={() => setUseThinking(!useThinking)}
                        className={`flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-[10px] font-bold uppercase tracking-wide transition-all ${
                            useThinking 
                            ? 'bg-purple-100 text-purple-700 shadow-sm' 
                            : 'text-slate-400 hover:bg-slate-200/50'
                        }`}
                    >
                        <BrainCircuit size={12} />
                        {useThinking ? 'THINK ON' : 'THINK OFF'}
                    </button>
                </div>
            </div>
          </div>

          {/* Messages Area */}
          <div className="flex-1 overflow-y-auto p-5 space-y-6 bg-slate-50/50 scroll-smooth">
            {messages.map((msg) => (
              <div
                key={msg.id}
                className={`flex gap-3 ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}
              >
                <div 
                  className={`w-8 h-8 rounded-full flex-shrink-0 flex items-center justify-center shadow-sm text-xs
                  ${msg.role === 'user' 
                    ? 'bg-slate-900 text-white' 
                    : 'bg-white border border-slate-200 text-indigo-600'}
                  `}
                >
                  {msg.role === 'user' ? <User size={14} /> : <Sparkles size={14} />}
                </div>

                <div className={`max-w-[85%] space-y-2 ${msg.role === 'user' ? 'items-end flex flex-col' : ''}`}>
                    {msg.image && (
                        <div className="p-1.5 bg-white border border-slate-200 rounded-2xl shadow-sm inline-block">
                             <img 
                                src={msg.image} 
                                alt="Uploaded" 
                                className="max-w-full h-auto rounded-xl max-h-40"
                            />
                        </div>
                    )}
                    <div
                        className={`px-4 py-3 text-[13.5px] leading-relaxed shadow-sm
                        ${msg.role === 'user' 
                            ? 'bg-slate-900 text-slate-50 rounded-2xl rounded-tr-sm' 
                            : 'bg-white text-slate-800 border border-slate-200/60 rounded-2xl rounded-tl-sm'}
                        `}
                    >
                        {msg.text}
                    </div>
                </div>
              </div>
            ))}

            {isLoading && (
              <div className="flex gap-3">
                 <div className="w-8 h-8 rounded-full bg-white border border-slate-200 text-indigo-600 flex items-center justify-center shadow-sm">
                    <Sparkles size={14} />
                 </div>
                 <div className="bg-white border border-slate-200 px-4 py-3 rounded-2xl rounded-tl-sm shadow-sm flex items-center gap-3">
                    <Loader2 size={16} className="animate-spin text-indigo-500" />
                    <span className="text-xs text-slate-500 font-medium">
                        {useThinking ? t('reasoning') : t('analyzing')}
                    </span>
                 </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input Area */}
          <div className="p-4 bg-white border-t border-slate-100">
            <div className="relative flex items-end gap-2 bg-slate-100 p-2 rounded-2xl border border-slate-200 focus-within:ring-2 focus-within:ring-indigo-100 focus-within:border-indigo-300 transition-all">
                <input 
                    type="file" 
                    accept="image/*" 
                    ref={fileInputRef}
                    className="hidden"
                    onChange={handleImageUpload}
                />
                 <input 
                    type="file" 
                    accept="image/*" 
                    ref={analyzeInputRef}
                    className="hidden"
                    onChange={handleAnalyzeUpload}
                />

                <button 
                    onClick={() => fileInputRef.current?.click()}
                    className={`p-2.5 rounded-xl transition-all h-10 w-10 flex items-center justify-center ${
                        attachedImage 
                        ? 'bg-emerald-100 text-emerald-600' 
                        : 'text-slate-400 hover:bg-white hover:shadow-sm hover:text-slate-600'
                    }`}
                    title={t('uploadImage')}
                >
                    <ImageIcon size={18} />
                </button>

                <button 
                    onClick={() => analyzeInputRef.current?.click()}
                    className="p-2.5 rounded-xl transition-all h-10 w-10 flex items-center justify-center text-indigo-500 hover:bg-indigo-50 hover:text-indigo-600"
                    title="Analyze Defects/Type"
                >
                    <ScanEye size={18} />
                </button>

                <textarea
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => {
                        if (e.key === 'Enter' && !e.shiftKey) {
                            e.preventDefault();
                            handleSend();
                        }
                    }}
                    placeholder={attachedImage ? t('imageContext') : t('aiPlaceholder')}
                    className="flex-1 bg-transparent border-none text-slate-800 text-sm placeholder:text-slate-400 focus:ring-0 px-2 py-2.5 max-h-32 resize-none custom-scrollbar"
                    rows={1}
                    disabled={isLoading}
                />

                <button
                    onClick={() => handleSend()}
                    disabled={isLoading || (!input.trim() && !attachedImage)}
                    className="p-2.5 bg-slate-900 text-white rounded-xl hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed shadow-md transition-all active:scale-95 h-10 w-10 flex items-center justify-center"
                >
                    <Send size={16} strokeWidth={2.5} />
                </button>
            </div>
            {attachedImage && (
                 <div className="mt-2 ml-1 flex items-center gap-2 text-[10px] text-slate-400">
                    <span className="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>
                    <span>{t('imageAttached')}</span>
                    <button onClick={() => setAttachedImage(null)} className="hover:text-red-500 ml-1"><X size={10}/></button>
                 </div>
            )}
            <div className="mt-2 text-center">
                <p className="text-[10px] text-slate-300">{t('disclaimer')}</p>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer,
  ScatterChart, Scatter, ZAxis, LabelList, Cell
} from 'recharts';
import { Product } from '../types';
import { 
  BarChart2, Activity, TrendingUp, FileJson, FileSpreadsheet, 
  Factory, Settings2, Palette, MoveVertical, Filter, Plus, Trash2, X
} from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

interface DataVisualizerProps {
  data: Product[];
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16', '#6366f1'];

interface RangeFilter {
    id: string;
    key: string;
    min: string;
    max: string;
}

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [userXAxisKey, setUserXAxisKey] = useState<string>('');
  const [userYAxisKey, setUserYAxisKey] = useState<string>('');
  const [zAxisKey, setZAxisKey] = useState<string>('none');
  const [colorByKey, setColorByKey] = useState<string>('none');
  const [showTrendline, setShowTrendline] = useState<boolean>(false);
  const [showConfig, setShowConfig] = useState<boolean>(true);
  const [filters, setFilters] = useState<RangeFilter[]>([]);

  const { t, tProp } = useLanguage();

  // 1. Extract Numeric Properties (for X, Y, Z axes)
  const numericProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        // Robust number check: handle strings that look like numbers
        const num = Number(val.value);
        if (!isNaN(num) && val.value !== '' && val.value !== null) {
          props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // Filter Logic
  const addFilter = () => {
    if (numericProperties.length > 0) {
        setFilters([...filters, { id: Date.now().toString(), key: numericProperties[0], min: '', max: '' }]);
    }
  };

  const removeFilter = (id: string) => {
    setFilters(filters.filter(f => f.id !== id));
  };

  const updateFilter = (id: string, field: keyof RangeFilter, value: string) => {
    setFilters(filters.map(f => f.id === id ? { ...f, [field]: value } : f));
  };

  // Filtered Data
  const filteredData = useMemo(() => {
    if (filters.length === 0) return data;
    return data.filter(item => {
        return filters.every(f => {
             const valObj = item.properties[f.key];
             if (!valObj) return false;
             const val = Number(valObj.value);
             if (isNaN(val)) return false;

             const min = f.min === '' ? -Infinity : Number(f.min);
             const max = f.max === '' ? Infinity : Number(f.max);

             return val >= min && val <= max;
        });
    });
  }, [data, filters]);

  // 2. Extract Categorical Properties (for Coloring)
  const categoricalProperties = useMemo(() => {
    const props = new Set<string>(['manufacturer']); 
    // Use original data for extraction to maintain option stability
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (typeof val.value === 'string' && val.value.length < 20) {
            props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // 3. Helper to extract units
  const propertyUnits = useMemo(() => {
    const units: Record<string, string> = {};
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (v.unit && !units[k]) units[k] = v.unit;
        });
    });
    return units;
  }, [data]);

  // 4. Calculate Default/Active Keys synchronously
  const activeYKey = useMemo(() => {
    if (userYAxisKey && numericProperties.includes(userYAxisKey)) return userYAxisKey;
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    if (numericProperties.includes('密度')) return '密度';
    return numericProperties[0] || '';
  }, [userYAxisKey, numericProperties]);

  const activeXKey = useMemo(() => {
    if (userXAxisKey && numericProperties.includes(userXAxisKey)) return userXAxisKey;
    if (numericProperties.includes('密度')) return '密度';
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    return numericProperties.length > 1 ? numericProperties[1] : numericProperties[0] || '';
  }, [userXAxisKey, numericProperties]);

  // 5. Transform Data for Recharts (Using Filtered Data)
  const chartData = useMemo(() => {
    return filteredData.map(product => {
      const flattened: any = {
        name: product.gradeName,
        manufacturer: product.manufacturer,
        id: product.id
      };

      Object.entries(product.properties).forEach(([key, val]) => {
        const numVal = Number(val.value);
        if (!isNaN(numVal) && val.value !== '' && val.value !== null) {
          flattened[key] = numVal;
        } else {
          flattened[key] = val.value;
        }
      });
      return flattened;
    });
  }, [filteredData]);

  // 6. Group Data for Scatter Series
  const scatterGroups = useMemo(() => {
    if (chartType !== 'scatter' || colorByKey === 'none') return null;

    const groups: Record<string, any[]> = {};
    chartData.forEach(d => {
        const keyVal = d[colorByKey];
        const groupName = keyVal ? String(keyVal) : 'Unclassified';
        if (!groups[groupName]) groups[groupName] = [];
        groups[groupName].push(d);
    });
    return groups;
  }, [chartData, chartType, colorByKey]);

  // 7. Color Map
  const colorMap = useMemo(() => {
    if (colorByKey === 'none') return null;
    const uniqueValues = Array.from(new Set(chartData.map(d => String(d[colorByKey] || 'Unclassified'))));
    const map: Record<string, string> = {};
    uniqueValues.forEach((val, idx) => {
        map[val] = COLORS[idx % COLORS.length];
    });
    return map;
  }, [chartData, colorByKey]);

  // Trendline Logic
  const trendlineData = useMemo(() => {
    if (chartType !== 'scatter' || !showTrendline || chartData.length < 2) return [];

    let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0, count = 0;
    chartData.forEach((point) => {
        const x = point[activeXKey];
        const y = point[activeYKey];
        if (typeof x === 'number' && typeof y === 'number') {
            sumX += x; sumY += y; sumXY += x * y; sumXX += x * x; count++;
        }
    });

    if (count < 2) return [];
    const slope = (count * sumXY - sumX * sumY) / (count * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / count;
    const xValues = chartData.map(d => d[activeXKey]).filter(v => typeof v === 'number') as number[];
    if (xValues.length === 0) return [];
    const minX = Math.min(...xValues);
    const maxX = Math.max(...xValues);

    return [
        { [activeXKey]: minX, [activeYKey]: slope * minX + intercept },
        { [activeXKey]: maxX, [activeYKey]: slope * maxX + intercept }
    ];
  }, [chartData, activeXKey, activeYKey, showTrendline, chartType]);

  const handleExportJSON = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(chartData));
    const link = document.createElement('a');
    link.href = dataStr;
    link.download = "chart_data.json";
    link.click();
  };

  const handleExportCSV = () => {
    if (chartData.length === 0) return;
    const allKeys = Array.from(new Set(chartData.flatMap(Object.keys)));
    const header = allKeys.join(',');
    const rows = chartData.map(row => 
      allKeys.map(key => {
        const val = row[key];
        if (val === null || val === undefined) return '';
        const stringVal = String(val);
        if (stringVal.includes(',') || stringVal.includes('"') || stringVal.includes('\n')) {
          return `"${stringVal.replace(/"/g, '""')}"`;
        }
        return stringVal;
      }).join(',')
    );
    const csvContent = [header, ...rows].join('\n');
    const blob = new Blob(["\uFEFF" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'chart_data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const yAxisUnit = propertyUnits[activeYKey];
  const xAxisUnit = propertyUnits[activeXKey];
  const zAxisUnit = zAxisKey !== 'none' ? propertyUnits[zAxisKey] : '';
  const yAxisLabel = yAxisUnit ? `${tProp(activeYKey)} (${yAxisUnit})` : tProp(activeYKey);
  const xAxisLabel = xAxisUnit ? `${tProp(activeXKey)} (${xAxisUnit})` : tProp(activeXKey);

  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const pointData = payload[0].payload;

      // List of specific properties to display if available, beyond the axes
      const detailKeys = ['乙烯含量', '二烯烃含量', 'VA含量', '门尼粘度', '灰分'];

      return (
        <div className="bg-white p-3 border border-slate-200 shadow-xl rounded-lg text-sm min-w-[240px] z-50">
            <div className="mb-2">
                <p className="font-bold text-slate-800 text-base">{pointData.name}</p>
                <div className="flex items-center gap-1.5 text-xs text-slate-500 mt-0.5">
                    <Factory size={12} className="text-slate-400"/>
                    <span>{pointData.manufacturer}</span>
                </div>
            </div>
            <div className="border-t border-slate-100 pt-2 space-y-1.5">
                {chartType === 'scatter' && (
                    <div className="flex justify-between text-xs bg-slate-50 p-1 rounded">
                        <span className="text-slate-500">{tProp(activeXKey)}:</span>
                        <span className="font-mono font-semibold text-blue-700">
                            {pointData[activeXKey]} <span className="text-[10px] text-slate-400">{xAxisUnit}</span>
                        </span>
                    </div>
                )}
                <div className="flex justify-between text-xs bg-slate-50 p-1 rounded">
                    <span className="text-slate-500">{tProp(activeYKey)}:</span>
                    <span className="font-mono font-semibold text-blue-700">
                        {pointData[activeYKey]} <span className="text-[10px] text-slate-400">{yAxisUnit}</span>
                    </span>
                </div>
                 {zAxisKey !== 'none' && (
                    <div className="flex justify-between text-xs bg-slate-50 p-1 rounded">
                        <span className="text-slate-500">{tProp(zAxisKey)}:</span>
                        <span className="font-mono font-semibold text-purple-700">
                            {pointData[zAxisKey]} <span className="text-[10px] text-slate-400">{zAxisUnit}</span>
                        </span>
                    </div>
                )}

                {/* Dynamic Extra Properties */}
                {detailKeys.map(key => {
                    // Don't duplicate if it's already shown as an axis
                    if (pointData[key] !== undefined && key !== activeXKey && key !== activeYKey && key !== zAxisKey) {
                         return (
                            <div key={key} className="flex justify-between text-xs bg-emerald-50/50 p-1 rounded border border-emerald-100/50">
                                <span className="text-slate-500">{tProp(key)}:</span>
                                <span className="font-mono font-medium text-emerald-700">
                                    {pointData[key]} <span className="text-[10px] text-slate-400">{propertyUnits[key]}</span>
                                </span>
                            </div>
                        );
                    }
                    return null;
                })}

                {colorByKey !== 'none' && (
                    <div className="flex justify-between text-xs mt-2 pt-2 border-t border-slate-100">
                        <span className="text-slate-500">{tProp(colorByKey)}:</span>
                        <span className="font-medium text-slate-800">{pointData[colorByKey]}</span>
                    </div>
                )}
            </div>
        </div>
      );
    }
    return null;
  };

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400 border border-slate-200 rounded-lg bg-white">
        <Activity size={48} className="mb-4 text-slate-300" />
        <p>{t('noProducts')}</p>
      </div>
    );
  }

  // Fallback if no numeric properties exist
  if (numericProperties.length === 0) {
     return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400 border border-slate-200 rounded-lg bg-white">
        <Activity size={48} className="mb-4 text-slate-300" />
        <p>{t('noNumericData')}</p>
      </div>
    );
  }

  return (
    // Explicit height style ensures the chart container always has size, even in a scrolling parent
    <div className="bg-white rounded-lg shadow-sm border border-slate-200 flex flex-col w-full" style={{ minHeight: '600px', height: '600px' }}>

      {/* Configuration Header */}
      <div className="border-b border-slate-100 bg-slate-50 flex-shrink-0">
        <div className="p-3 px-4 flex items-center justify-between">
            <div className="flex items-center gap-2 text-slate-800 font-semibold">
                <Settings2 size={18} className="text-blue-600" />
                <span>{t('chartConfig')}</span>
            </div>
            <div className="flex gap-2">
                 <button 
                    onClick={() => setShowConfig(!showConfig)}
                    className="text-xs text-blue-600 hover:text-blue-700 font-medium px-2 py-1 rounded hover:bg-blue-50 transition-colors"
                >
                    {showConfig ? t('collapseConfig') : t('expandConfig')}
                </button>
                 <div className="h-4 w-px bg-slate-300 self-center mx-1"></div>
                 <button onClick={handleExportJSON} className="text-slate-500 hover:text-slate-700" title={t('exportJson')}><FileJson size={16}/></button>
                 <button onClick={handleExportCSV} className="text-slate-500 hover:text-slate-700" title={t('exportCsv')}><FileSpreadsheet size={16}/></button>
            </div>
        </div>

        {showConfig && (
            <div className="p-4 pt-0 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 animate-in slide-in-from-top-2 duration-200">
                {/* 1. Chart Type */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <Activity size={12}/> {t('chartType')}
                    </label>
                    <div className="flex bg-white rounded-md border border-slate-200 p-1">
                        <button
                        onClick={() => setChartType('bar')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'bar' ? 'bg-blue-50 text-blue-700 shadow-sm' : 'text-slate-600 hover:bg-slate-50'
                        }`}
                        >
                        <BarChart2 size={14} /> {t('barChart')}
                        </button>
                        <button
                        onClick={() => setChartType('scatter')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'scatter' ? 'bg-blue-50 text-blue-700 shadow-sm' : 'text-slate-600 hover:bg-slate-50'
                        }`}
                        >
                        <Activity size={14} /> {t('scatterChart')}
                        </button>
                    </div>
                </div>

                {/* 2. Axes Configuration */}
                <div className="space-y-1.5 lg:col-span-2">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <MoveVertical size={12}/> {t('axisMapping')}
                    </label>
                    <div className="flex gap-2">
                        {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={activeXKey} onChange={(e) => setUserXAxisKey(e.target.value)}
                                    className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                                >
                                    {numericProperties.map(p => <option key={p} value={p}>{t('xAxis')}: {tProp(p)}</option>)}
                                </select>
                             </div>
                        )}

                        <div className="flex-1 min-w-[120px]">
                            <select 
                                value={activeYKey} onChange={(e) => setUserYAxisKey(e.target.value)}
                                className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                            >
                                {numericProperties.map(p => <option key={p} value={p}>{chartType === 'bar' ? t('val') : t('yAxis')}: {tProp(p)}</option>)}
                            </select>
                        </div>

                         {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={zAxisKey} onChange={(e) => setZAxisKey(e.target.value)}
                                    className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                                >
                                    <option value="none">{t('zAxis')}: {t('noneAxis')}</option>
                                    {numericProperties.map(p => <option key={p} value={p}>{t('zAxis')}: {tProp(p)}</option>)}
                                </select>
                             </div>
                        )}
                    </div>
                </div>

                {/* 3. Style & Color */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <Palette size={12}/> {t('styleGrouping')}
                    </label>
                    <div className="flex gap-2 items-center">
                         <select 
                            value={colorByKey} onChange={(e) => setColorByKey(e.target.value)}
                            className="flex-1 bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                        >
                            <option value="none">{t('colorSingle')}</option>
                            <optgroup label="Properties">
                                {categoricalProperties.map(p => <option key={p} value={p}>{t('groupBy').replace('{key}', tProp(p))}</option>)}
                            </optgroup>
                        </select>
                        {chartType === 'scatter' && (
                             <button
                                onClick={() => setShowTrendline(!showTrendline)}
                                title={t('trendline')}
                                className={`p-1.5 rounded border transition-colors ${showTrendline ? 'bg-indigo-50 text-indigo-600 border-indigo-200' : 'bg-white text-slate-400 border-slate-200'}`}
                             >
                                 <TrendingUp size={16} />
                             </button>
                        )}
                    </div>
                </div>

                {/* 4. Data Filters */}
                <div className="space-y-1.5 lg:col-span-4 border-t border-slate-200 pt-3 mt-1">
                    <div className="flex items-center justify-between">
                        <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                            <Filter size={12}/> {t('dataFilters')}
                        </label>
                        <button 
                            onClick={addFilter}
                            className="flex items-center gap-1 text-[10px] font-medium text-blue-600 bg-blue-50 hover:bg-blue-100 px-2 py-1 rounded-md transition-colors"
                        >
                            <Plus size={12}/> {t('addFilter')}
                        </button>
                    </div>

                    {filters.length === 0 ? (
                        <p className="text-[10px] text-slate-400 italic pl-1">{t('noFilters')}</p>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2 mt-2">
                            {filters.map(filter => (
                                <div key={filter.id} className="flex items-center gap-2 bg-slate-50 p-1.5 rounded-lg border border-slate-200 shadow-sm animate-in fade-in zoom-in-95 duration-200">
                                    <select 
                                        value={filter.key} 
                                        onChange={(e) => updateFilter(filter.id, 'key', e.target.value)}
                                        className="bg-white border-slate-200 text-xs rounded py-1 pl-1 pr-6 flex-1 min-w-0 focus:ring-1 focus:ring-blue-500 focus:border-blue-500"
                                    >
                                        {numericProperties.map(p => <option key={p} value={p}>{tProp(p)}</option>)}
                                    </select>
                                    <div className="flex items-center gap-1 bg-white border border-slate-200 rounded px-1">
                                        <input 
                                            type="number" 
                                            placeholder={t('min')} 
                                            value={filter.min}
                                            onChange={(e) => updateFilter(filter.id, 'min', e.target.value)}
                                            className="w-12 text-xs border-none p-1 focus:ring-0 text-right placeholder:text-slate-300"
                                        />
                                        <span className="text-slate-300 text-[10px]">-</span>
                                        <input 
                                            type="number" 
                                            placeholder={t('max')} 
                                            value={filter.max}
                                            onChange={(e) => updateFilter(filter.id, 'max', e.target.value)}
                                            className="w-12 text-xs border-none p-1 focus:ring-0 text-right placeholder:text-slate-300"
                                        />
                                    </div>
                                    <button 
                                        onClick={() => removeFilter(filter.id)} 
                                        className="text-slate-400 hover:text-red-500 hover:bg-red-50 p-1 rounded transition-colors"
                                    >
                                        <Trash2 size={12}/>
                                    </button>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        )}
      </div>

      {/* Chart Canvas */}
      <div className="flex-1 p-6 relative w-full h-full">
        {activeYKey && (
            <ResponsiveContainer width="100%" height="100%">
            {chartType === 'bar' ? (
                <BarChart
                data={chartData}
                margin={{ top: 20, right: 30, left: 20, bottom: 40 }}
                >
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis 
                    dataKey="name" 
                    stroke="#64748b" 
                    fontSize={12} 
                    tickLine={false} 
                    axisLine={{ stroke: '#cbd5e1' }} 
                    interval={0} 
                    angle={-30} 
                    textAnchor="end" 
                    height={60} 
                />
                <YAxis 
                    stroke="#64748b" 
                    fontSize={12} 
                    tickLine={false} 
                    axisLine={{ stroke: '#cbd5e1' }} 
                    domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { textAnchor: 'middle', fill: '#94a3b8' } }} 
                />
                <RechartsTooltip content={<CustomTooltip />} cursor={{ fill: '#f1f5f9' }} />
                <Legend />
                <Bar 
                    dataKey={activeYKey} 
                    fill="#3b82f6" 
                    radius={[4, 4, 0, 0]} 
                    name={yAxisLabel} 
                    barSize={40}
                    isAnimationActive={false} // Disable animation to prevent potential white-screen errors on mount
                >
                    {colorByKey !== 'none' && chartData.map((entry, index) => {
                        const val = String(entry[colorByKey] || 'Unclassified');
                        return <Cell key={`cell-${index}`} fill={colorMap?.[val] || '#3b82f6'} />;
                    })}
                    <LabelList dataKey={activeYKey} position="top" fill="#64748b" fontSize={12} formatter={(val: number) => val.toFixed(2)} />
                </Bar>
                </BarChart>
            ) : (
                <ScatterChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis 
                    type="number" dataKey={activeXKey} name={activeXKey} stroke="#64748b" fontSize={12} domain={['auto', 'auto']}
                    label={{ value: xAxisLabel, position: 'bottom', offset: 0, style: { fill: '#64748b' } }} 
                />
                <YAxis 
                    type="number" dataKey={activeYKey} name={activeYKey} stroke="#64748b" fontSize={12} domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { fill: '#64748b' } }} 
                />
                {zAxisKey !== 'none' && (
                    <ZAxis type="number" dataKey={zAxisKey} range={[60, 600]} name={zAxisKey} unit={zAxisUnit} />
                )}

                <RechartsTooltip content={<CustomTooltip />} cursor={{ strokeDasharray: '3 3' }} />
                <Legend />

                {colorByKey !== 'none' && scatterGroups ? (
                    Object.entries(scatterGroups).map(([groupName, groupData], index) => (
                        <Scatter 
                            key={groupName}
                            name={groupName}
                            data={groupData}
                            fill={COLORS[index % COLORS.length]}
                            isAnimationActive={false}
                        />
                    ))
                ) : (
                    <Scatter name={t('chartTitle')} data={chartData} fill="#3b82f6" isAnimationActive={false} />
                )}

                {showTrendline && trendlineData.length > 0 && (
                    <Scatter name={t('trendline')} data={trendlineData} line={{ stroke: '#ef4444', strokeWidth: 2, strokeDasharray: '5 5' }} shape={() => null} legendType="none" tooltipType="none" isAnimationActive={false}/>
                )}
                </ScatterChart>
            )}
            </ResponsiveContainer>
        )}

        {chartType === 'bar' && colorByKey !== 'none' && colorMap && (
             <div className="absolute top-4 right-6 bg-white/90 p-2 rounded border border-slate-200 text-xs shadow-sm max-w-[150px]">
                 <p className="font-semibold text-slate-500 mb-1 border-b border-slate-100 pb-1">{t('groupBy').replace('{key}', tProp(colorByKey))}</p>
                 <div className="space-y-1 max-h-[100px] overflow-y-auto custom-scrollbar">
                     {Object.entries(colorMap).map(([label, color]) => (
                         <div key={label} className="flex items-center gap-2">
                             <div className="w-2 h-2 rounded-full" style={{ backgroundColor: color }}></div>
                             <span className="truncate text-slate-600" title={label}>{label}</span>
                         </div>
                     ))}
                 </div>
             </div>
        )}
      </div>

      <div className="px-6 py-2 bg-slate-50 border-t border-slate-200 text-[10px] text-slate-400 flex justify-between flex-shrink-0">
         <span>ResinDB Visualization Engine v1.2</span>
         {filters.length > 0 && <span>Filtered: {filteredData.length} records</span>}
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer,
  ScatterChart, Scatter, ZAxis, LabelList, Cell
} from 'recharts';
import { Product } from '../types';
import { 
  BarChart2, Activity, TrendingUp, FileJson, FileSpreadsheet, 
  Factory, Settings2, Palette, MoveVertical, Filter, Plus, Trash2, X
} from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

interface DataVisualizerProps {
  data: Product[];
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16', '#6366f1'];

interface RangeFilter {
    id: string;
    key: string;
    min: string;
    max: string;
}

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [userXAxisKey, setUserXAxisKey] = useState<string>('');
  const [userYAxisKey, setUserYAxisKey] = useState<string>('');
  const [zAxisKey, setZAxisKey] = useState<string>('none');
  const [colorByKey, setColorByKey] = useState<string>('none');
  const [showTrendline, setShowTrendline] = useState<boolean>(false);
  const [showConfig, setShowConfig] = useState<boolean>(true);
  const [filters, setFilters] = useState<RangeFilter[]>([]);

  const { t, tProp } = useLanguage();

  // 1. Extract Numeric Properties (for X, Y, Z axes)
  const numericProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        // Robust number check: handle strings that look like numbers
        const num = Number(val.value);
        if (!isNaN(num) && val.value !== '' && val.value !== null) {
          props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // Filter Logic
  const addFilter = () => {
    if (numericProperties.length > 0) {
        setFilters([...filters, { id: Date.now().toString(), key: numericProperties[0], min: '', max: '' }]);
    }
  };

  const removeFilter = (id: string) => {
    setFilters(filters.filter(f => f.id !== id));
  };

  const updateFilter = (id: string, field: keyof RangeFilter, value: string) => {
    setFilters(filters.map(f => f.id === id ? { ...f, [field]: value } : f));
  };

  // Filtered Data
  const filteredData = useMemo(() => {
    if (filters.length === 0) return data;
    return data.filter(item => {
        return filters.every(f => {
             const valObj = item.properties[f.key];
             if (!valObj) return false;
             const val = Number(valObj.value);
             if (isNaN(val)) return false;

             const min = f.min === '' ? -Infinity : Number(f.min);
             const max = f.max === '' ? Infinity : Number(f.max);

             return val >= min && val <= max;
        });
    });
  }, [data, filters]);

  // 2. Extract Categorical Properties (for Coloring)
  const categoricalProperties = useMemo(() => {
    const props = new Set<string>(['manufacturer']); 
    // Use original data for extraction to maintain option stability
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (typeof val.value === 'string' && val.value.length < 20) {
            props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // 3. Helper to extract units
  const propertyUnits = useMemo(() => {
    const units: Record<string, string> = {};
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (v.unit && !units[k]) units[k] = v.unit;
        });
    });
    return units;
  }, [data]);

  // 4. Calculate Default/Active Keys synchronously
  const activeYKey = useMemo(() => {
    if (userYAxisKey && numericProperties.includes(userYAxisKey)) return userYAxisKey;
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    if (numericProperties.includes('密度')) return '密度';
    return numericProperties[0] || '';
  }, [userYAxisKey, numericProperties]);

  const activeXKey = useMemo(() => {
    if (userXAxisKey && numericProperties.includes(userXAxisKey)) return userXAxisKey;
    if (numericProperties.includes('密度')) return '密度';
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    return numericProperties.length > 1 ? numericProperties[1] : numericProperties[0] || '';
  }, [userXAxisKey, numericProperties]);

  // 5. Transform Data for Recharts (Using Filtered Data)
  const chartData = useMemo(() => {
    return filteredData.map(product => {
      const flattened: any = {
        name: product.gradeName,
        manufacturer: product.manufacturer,
        id: product.id
      };

      Object.entries(product.properties).forEach(([key, val]) => {
        const numVal = Number(val.value);
        if (!isNaN(numVal) && val.value !== '' && val.value !== null) {
          flattened[key] = numVal;
        } else {
          flattened[key] = val.value;
        }
      });
      return flattened;
    });
  }, [filteredData]);

  // 6. Group Data for Scatter Series
  const scatterGroups = useMemo(() => {
    if (chartType !== 'scatter' || colorByKey === 'none') return null;

    const groups: Record<string, any[]> = {};
    chartData.forEach(d => {
        const keyVal = d[colorByKey];
        const groupName = keyVal ? String(keyVal) : 'Unclassified';
        if (!groups[groupName]) groups[groupName] = [];
        groups[groupName].push(d);
    });
    return groups;
  }, [chartData, chartType, colorByKey]);

  // 7. Color Map
  const colorMap = useMemo(() => {
    if (colorByKey === 'none') return null;
    const uniqueValues = Array.from(new Set(chartData.map(d => String(d[colorByKey] || 'Unclassified'))));
    const map: Record<string, string> = {};
    uniqueValues.forEach((val, idx) => {
        map[val] = COLORS[idx % COLORS.length];
    });
    return map;
  }, [chartData, colorByKey]);

  // Trendline Logic
  const trendlineData = useMemo(() => {
    if (chartType !== 'scatter' || !showTrendline || chartData.length < 2) return [];

    let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0, count = 0;
    chartData.forEach((point) => {
        const x = point[activeXKey];
        const y = point[activeYKey];
        if (typeof x === 'number' && typeof y === 'number') {
            sumX += x; sumY += y; sumXY += x * y; sumXX += x * x; count++;
        }
    });

    if (count < 2) return [];
    const slope = (count * sumXY - sumX * sumY) / (count * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / count;
    const xValues = chartData.map(d => d[activeXKey]).filter(v => typeof v === 'number') as number[];
    if (xValues.length === 0) return [];
    const minX = Math.min(...xValues);
    const maxX = Math.max(...xValues);

    return [
        { [activeXKey]: minX, [activeYKey]: slope * minX + intercept },
        { [activeXKey]: maxX, [activeYKey]: slope * maxX + intercept }
    ];
  }, [chartData, activeXKey, activeYKey, showTrendline, chartType]);

  const handleExportJSON = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(chartData));
    const link = document.createElement('a');
    link.href = dataStr;
    link.download = "chart_data.json";
    link.click();
  };

  const handleExportCSV = () => {
    if (chartData.length === 0) return;
    const allKeys = Array.from(new Set(chartData.flatMap(Object.keys)));
    const header = allKeys.join(',');
    const rows = chartData.map(row => 
      allKeys.map(key => {
        const val = row[key];
        if (val === null || val === undefined) return '';
        const stringVal = String(val);
        if (stringVal.includes(',') || stringVal.includes('"') || stringVal.includes('\n')) {
          return `"${stringVal.replace(/"/g, '""')}"`;
        }
        return stringVal;
      }).join(',')
    );
    const csvContent = [header, ...rows].join('\n');
    const blob = new Blob(["\uFEFF" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'chart_data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const yAxisUnit = propertyUnits[activeYKey];
  const xAxisUnit = propertyUnits[activeXKey];
  const zAxisUnit = zAxisKey !== 'none' ? propertyUnits[zAxisKey] : '';
  const yAxisLabel = yAxisUnit ? `${tProp(activeYKey)} (${yAxisUnit})` : tProp(activeYKey);
  const xAxisLabel = xAxisUnit ? `${tProp(activeXKey)} (${xAxisUnit})` : tProp(activeXKey);

  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const pointData = payload[0].payload;

      // List of specific properties to display if available, beyond the axes
      const detailKeys = ['乙烯含量', '二烯烃含量', 'VA含量', '门尼粘度', '灰分'];

      return (
        <div className="bg-white p-3 border border-slate-200 shadow-xl rounded-lg text-sm min-w-[240px] z-50">
            <div className="mb-2">
                <p className="font-bold text-slate-800 text-base">{pointData.name}</p>
                <div className="flex items-center gap-1.5 text-xs text-slate-500 mt-0.5">
                    <Factory size={12} className="text-slate-400"/>
                    <span>{pointData.manufacturer}</span>
                </div>
            </div>
            <div className="border-t border-slate-100 pt-2 space-y-1.5">
                {chartType === 'scatter' && (
                    <div className="flex justify-between text-xs bg-slate-50 p-1 rounded">
                        <span className="text-slate-500">{tProp(activeXKey)}:</span>
                        <span className="font-mono font-semibold text-blue-700">
                            {pointData[activeXKey]} <span className="text-[10px] text-slate-400">{xAxisUnit}</span>
                        </span>
                    </div>
                )}
                <div className="flex justify-between text-xs bg-slate-50 p-1 rounded">
                    <span className="text-slate-500">{tProp(activeYKey)}:</span>
                    <span className="font-mono font-semibold text-blue-700">
                        {pointData[activeYKey]} <span className="text-[10px] text-slate-400">{yAxisUnit}</span>
                    </span>
                </div>
                 {zAxisKey !== 'none' && (
                    <div className="flex justify-between text-xs bg-slate-50 p-1 rounded">
                        <span className="text-slate-500">{tProp(zAxisKey)}:</span>
                        <span className="font-mono font-semibold text-purple-700">
                            {pointData[zAxisKey]} <span className="text-[10px] text-slate-400">{zAxisUnit}</span>
                        </span>
                    </div>
                )}

                {/* Dynamic Extra Properties */}
                {detailKeys.map(key => {
                    // Don't duplicate if it's already shown as an axis
                    if (pointData[key] !== undefined && key !== activeXKey && key !== activeYKey && key !== zAxisKey) {
                         return (
                            <div key={key} className="flex justify-between text-xs bg-emerald-50/50 p-1 rounded border border-emerald-100/50">
                                <span className="text-slate-500">{tProp(key)}:</span>
                                <span className="font-mono font-medium text-emerald-700">
                                    {pointData[key]} <span className="text-[10px] text-slate-400">{propertyUnits[key]}</span>
                                </span>
                            </div>
                        );
                    }
                    return null;
                })}

                {colorByKey !== 'none' && (
                    <div className="flex justify-between text-xs mt-2 pt-2 border-t border-slate-100">
                        <span className="text-slate-500">{tProp(colorByKey)}:</span>
                        <span className="font-medium text-slate-800">{pointData[colorByKey]}</span>
                    </div>
                )}
            </div>
        </div>
      );
    }
    return null;
  };

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400 border border-slate-200 rounded-lg bg-white">
        <Activity size={48} className="mb-4 text-slate-300" />
        <p>{t('noProducts')}</p>
      </div>
    );
  }

  // Fallback if no numeric properties exist
  if (numericProperties.length === 0) {
     return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400 border border-slate-200 rounded-lg bg-white">
        <Activity size={48} className="mb-4 text-slate-300" />
        <p>{t('noNumericData')}</p>
      </div>
    );
  }

  return (
    // Explicit height style ensures the chart container always has size, even in a scrolling parent
    <div className="bg-white rounded-lg shadow-sm border border-slate-200 flex flex-col w-full" style={{ minHeight: '600px', height: '600px' }}>

      {/* Configuration Header */}
      <div className="border-b border-slate-100 bg-slate-50 flex-shrink-0">
        <div className="p-3 px-4 flex items-center justify-between">
            <div className="flex items-center gap-2 text-slate-800 font-semibold">
                <Settings2 size={18} className="text-blue-600" />
                <span>{t('chartConfig')}</span>
            </div>
            <div className="flex gap-2">
                 <button 
                    onClick={() => setShowConfig(!showConfig)}
                    className="text-xs text-blue-600 hover:text-blue-700 font-medium px-2 py-1 rounded hover:bg-blue-50 transition-colors"
                >
                    {showConfig ? t('collapseConfig') : t('expandConfig')}
                </button>
                 <div className="h-4 w-px bg-slate-300 self-center mx-1"></div>
                 <button onClick={handleExportJSON} className="text-slate-500 hover:text-slate-700" title={t('exportJson')}><FileJson size={16}/></button>
                 <button onClick={handleExportCSV} className="text-slate-500 hover:text-slate-700" title={t('exportCsv')}><FileSpreadsheet size={16}/></button>
            </div>
        </div>

        {showConfig && (
            <div className="p-4 pt-0 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 animate-in slide-in-from-top-2 duration-200">
                {/* 1. Chart Type */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <Activity size={12}/> {t('chartType')}
                    </label>
                    <div className="flex bg-white rounded-md border border-slate-200 p-1">
                        <button
                        onClick={() => setChartType('bar')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'bar' ? 'bg-blue-50 text-blue-700 shadow-sm' : 'text-slate-600 hover:bg-slate-50'
                        }`}
                        >
                        <BarChart2 size={14} /> {t('barChart')}
                        </button>
                        <button
                        onClick={() => setChartType('scatter')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'scatter' ? 'bg-blue-50 text-blue-700 shadow-sm' : 'text-slate-600 hover:bg-slate-50'
                        }`}
                        >
                        <Activity size={14} /> {t('scatterChart')}
                        </button>
                    </div>
                </div>

                {/* 2. Axes Configuration */}
                <div className="space-y-1.5 lg:col-span-2">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <MoveVertical size={12}/> {t('axisMapping')}
                    </label>
                    <div className="flex gap-2">
                        {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={activeXKey} onChange={(e) => setUserXAxisKey(e.target.value)}
                                    className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                                >
                                    {numericProperties.map(p => <option key={p} value={p}>{t('xAxis')}: {tProp(p)}</option>)}
                                </select>
                             </div>
                        )}

                        <div className="flex-1 min-w-[120px]">
                            <select 
                                value={activeYKey} onChange={(e) => setUserYAxisKey(e.target.value)}
                                className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                            >
                                {numericProperties.map(p => <option key={p} value={p}>{chartType === 'bar' ? t('val') : t('yAxis')}: {tProp(p)}</option>)}
                            </select>
                        </div>

                         {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={zAxisKey} onChange={(e) => setZAxisKey(e.target.value)}
                                    className="w-full bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                                >
                                    <option value="none">{t('zAxis')}: {t('noneAxis')}</option>
                                    {numericProperties.map(p => <option key={p} value={p}>{t('zAxis')}: {tProp(p)}</option>)}
                                </select>
                             </div>
                        )}
                    </div>
                </div>

                {/* 3. Style & Color */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                        <Palette size={12}/> {t('styleGrouping')}
                    </label>
                    <div className="flex gap-2 items-center">
                         <select 
                            value={colorByKey} onChange={(e) => setColorByKey(e.target.value)}
                            className="flex-1 bg-white border border-slate-300 text-slate-700 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5"
                        >
                            <option value="none">{t('colorSingle')}</option>
                            <optgroup label="Properties">
                                {categoricalProperties.map(p => <option key={p} value={p}>{t('groupBy').replace('{key}', tProp(p))}</option>)}
                            </optgroup>
                        </select>
                        {chartType === 'scatter' && (
                             <button
                                onClick={() => setShowTrendline(!showTrendline)}
                                title={t('trendline')}
                                className={`p-1.5 rounded border transition-colors ${showTrendline ? 'bg-indigo-50 text-indigo-600 border-indigo-200' : 'bg-white text-slate-400 border-slate-200'}`}
                             >
                                 <TrendingUp size={16} />
                             </button>
                        )}
                    </div>
                </div>

                {/* 4. Data Filters */}
                <div className="space-y-1.5 lg:col-span-4 border-t border-slate-200 pt-3 mt-1">
                    <div className="flex items-center justify-between">
                        <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                            <Filter size={12}/> {t('dataFilters')}
                        </label>
                        <button 
                            onClick={addFilter}
                            className="flex items-center gap-1 text-[10px] font-medium text-blue-600 bg-blue-50 hover:bg-blue-100 px-2 py-1 rounded-md transition-colors"
                        >
                            <Plus size={12}/> {t('addFilter')}
                        </button>
                    </div>

                    {filters.length === 0 ? (
                        <p className="text-[10px] text-slate-400 italic pl-1">{t('noFilters')}</p>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2 mt-2">
                            {filters.map(filter => (
                                <div key={filter.id} className="flex items-center gap-2 bg-slate-50 p-1.5 rounded-lg border border-slate-200 shadow-sm animate-in fade-in zoom-in-95 duration-200">
                                    <select 
                                        value={filter.key} 
                                        onChange={(e) => updateFilter(filter.id, 'key', e.target.value)}
                                        className="bg-white border-slate-200 text-xs rounded py-1 pl-1 pr-6 flex-1 min-w-0 focus:ring-1 focus:ring-blue-500 focus:border-blue-500"
                                    >
                                        {numericProperties.map(p => <option key={p} value={p}>{tProp(p)}</option>)}
                                    </select>
                                    <div className="flex items-center gap-1 bg-white border border-slate-200 rounded px-1">
                                        <input 
                                            type="number" 
                                            placeholder={t('min')} 
                                            value={filter.min}
                                            onChange={(e) => updateFilter(filter.id, 'min', e.target.value)}
                                            className="w-12 text-xs border-none p-1 focus:ring-0 text-right placeholder:text-slate-300"
                                        />
                                        <span className="text-slate-300 text-[10px]">-</span>
                                        <input 
                                            type="number" 
                                            placeholder={t('max')} 
                                            value={filter.max}
                                            onChange={(e) => updateFilter(filter.id, 'max', e.target.value)}
                                            className="w-12 text-xs border-none p-1 focus:ring-0 text-right placeholder:text-slate-300"
                                        />
                                    </div>
                                    <button 
                                        onClick={() => removeFilter(filter.id)} 
                                        className="text-slate-400 hover:text-red-500 hover:bg-red-50 p-1 rounded transition-colors"
                                    >
                                        <Trash2 size={12}/>
                                    </button>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        )}
      </div>

      {/* Chart Canvas */}
      <div className="flex-1 p-6 relative w-full h-full">
        {activeYKey && (
            <ResponsiveContainer width="100%" height="100%">
            {chartType === 'bar' ? (
                <BarChart
                data={chartData}
                margin={{ top: 20, right: 30, left: 20, bottom: 40 }}
                >
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis 
                    dataKey="name" 
                    stroke="#64748b" 
                    fontSize={12} 
                    tickLine={false} 
                    axisLine={{ stroke: '#cbd5e1' }} 
                    interval={0} 
                    angle={-30} 
                    textAnchor="end" 
                    height={60} 
                />
                <YAxis 
                    stroke="#64748b" 
                    fontSize={12} 
                    tickLine={false} 
                    axisLine={{ stroke: '#cbd5e1' }} 
                    domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { textAnchor: 'middle', fill: '#94a3b8' } }} 
                />
                <RechartsTooltip content={<CustomTooltip />} cursor={{ fill: '#f1f5f9' }} />
                <Legend />
                <Bar 
                    dataKey={activeYKey} 
                    fill="#3b82f6" 
                    radius={[4, 4, 0, 0]} 
                    name={yAxisLabel} 
                    barSize={40}
                    isAnimationActive={false} // Disable animation to prevent potential white-screen errors on mount
                >
                    {colorByKey !== 'none' && chartData.map((entry, index) => {
                        const val = String(entry[colorByKey] || 'Unclassified');
                        return <Cell key={`cell-${index}`} fill={colorMap?.[val] || '#3b82f6'} />;
                    })}
                    <LabelList dataKey={activeYKey} position="top" fill="#64748b" fontSize={12} formatter={(val: number) => val.toFixed(2)} />
                </Bar>
                </BarChart>
            ) : (
                <ScatterChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis 
                    type="number" dataKey={activeXKey} name={activeXKey} stroke="#64748b" fontSize={12} domain={['auto', 'auto']}
                    label={{ value: xAxisLabel, position: 'bottom', offset: 0, style: { fill: '#64748b' } }} 
                />
                <YAxis 
                    type="number" dataKey={activeYKey} name={activeYKey} stroke="#64748b" fontSize={12} domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { fill: '#64748b' } }} 
                />
                {zAxisKey !== 'none' && (
                    <ZAxis type="number" dataKey={zAxisKey} range={[60, 600]} name={zAxisKey} unit={zAxisUnit} />
                )}

                <RechartsTooltip content={<CustomTooltip />} cursor={{ strokeDasharray: '3 3' }} />
                <Legend />

                {colorByKey !== 'none' && scatterGroups ? (
                    Object.entries(scatterGroups).map(([groupName, groupData], index) => (
                        <Scatter 
                            key={groupName}
                            name={groupName}
                            data={groupData}
                            fill={COLORS[index % COLORS.length]}
                            isAnimationActive={false}
                        />
                    ))
                ) : (
                    <Scatter name={t('chartTitle')} data={chartData} fill="#3b82f6" isAnimationActive={false} />
                )}

                {showTrendline && trendlineData.length > 0 && (
                    <Scatter name={t('trendline')} data={trendlineData} line={{ stroke: '#ef4444', strokeWidth: 2, strokeDasharray: '5 5' }} shape={() => null} legendType="none" tooltipType="none" isAnimationActive={false}/>
                )}
                </ScatterChart>
            )}
            </ResponsiveContainer>
        )}

        {chartType === 'bar' && colorByKey !== 'none' && colorMap && (
             <div className="absolute top-4 right-6 bg-white/90 p-2 rounded border border-slate-200 text-xs shadow-sm max-w-[150px]">
                 <p className="font-semibold text-slate-500 mb-1 border-b border-slate-100 pb-1">{t('groupBy').replace('{key}', tProp(colorByKey))}</p>
                 <div className="space-y-1 max-h-[100px] overflow-y-auto custom-scrollbar">
                     {Object.entries(colorMap).map(([label, color]) => (
                         <div key={label} className="flex items-center gap-2">
                             <div className="w-2 h-2 rounded-full" style={{ backgroundColor: color }}></div>
                             <span className="truncate text-slate-600" title={label}>{label}</span>
                         </div>
                     ))}
                 </div>
             </div>
        )}
      </div>

      <div className="px-6 py-2 bg-slate-50 border-t border-slate-200 text-[10px] text-slate-400 flex justify-between flex-shrink-0">
         <span>ResinDB Visualization Engine v1.2</span>
         {filters.length > 0 && <span>Filtered: {filteredData.length} records</span>}
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Send, Image as ImageIcon, Sparkles, X, Loader2, BrainCircuit, Bot, User, ChevronDown, Cpu, MessageSquarePlus, ScanEye } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';

interface AIAssistantProps {
  contextData: Product[];
}

interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  image?: string;
  isThinking?: boolean;
}

export const AIAssistant: React.FC<AIAssistantProps> = ({ contextData }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const { t, language } = useLanguage();
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [useThinking, setUseThinking] = useState(false);
  const [selectedModel, setSelectedModel] = useState('gemini-3-flash-preview');
  const [attachedImage, setAttachedImage] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const analyzeInputRef = useRef<HTMLInputElement>(null);

  // Reset/Init Welcome message when language changes or first open
  useEffect(() => {
    if (messages.length === 0) {
        setMessages([{ 
            id: 'welcome', 
            role: 'model', 
            text: t('welcomeMessage') 
        }]);
    }
  }, [t, messages.length]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isOpen]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setAttachedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
    // Reset value to allow re-selecting same file
    e.target.value = '';
  };

  const handleAnalyzeUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const imgData = reader.result as string;
        // Trigger analysis immediately
        const prompt = language === 'zh' 
          ? "请详细分析这张图片。如果图片包含塑料颗粒，请尝试识别其可能的树脂类型（如PE, PP, ABS等）和形态。如果图片显示塑料制品或测试样条，请指出是否存在可见缺陷（如晶点、杂质、流纹、焦烧、色差等）。" 
          : "Please analyze this image in detail. If it contains resin pellets, try to identify the potential resin type (e.g., PE, PP, ABS) and morphology. If it shows plastic parts or test bars, identify any visible defects (like gels, contamination, flow marks, burns, discoloration).";

        handleSend(prompt, imgData);
      };
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  };

  const handleSend = async (manualText?: string, manualImage?: string) => {
    // Determine effective content (manual overrides take precedence)
    const textToSend = typeof manualText === 'string' ? manualText : input;
    const imageToSend = typeof manualImage === 'string' ? manualImage : attachedImage;

    if ((!textToSend.trim() && !imageToSend) || isLoading) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: textToSend,
      image: imageToSend || undefined
    };

    setMessages(prev => [...prev, userMsg]);

    // Only clear state if we used the state values
    if (typeof manualText !== 'string') setInput('');
    if (typeof manualImage !== 'string') setAttachedImage(null);

    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const dataSummary = contextData.slice(0, 50).map(p => 
        `- ${p.gradeName} (${p.manufacturer}): ${Object.entries(p.properties).map(([k,v]) => `${k}=${v.value}${v.unit||''}`).join(', ')}`
      ).join('\n');

      const systemInstruction = `You are ResinAI, an expert assistant for a petrochemical synthetic resin database (ResinDB).

      Current Data Context (First 50 visible items from user filter):
      ${dataSummary}

      Instructions:
      1. Answer questions based specifically on the provided resin data when possible.
      2. If the user asks for comparison, use the numeric data to compare properties like Density, MFR, Tensile Strength etc.
      3. If analyzing an image, identify standard resin pellets, technical data sheets, or plastic part defects.
      4. Answer in the requested language (${language === 'zh' ? 'Chinese' : 'English'}).
      `;

      let modelName = selectedModel;
      let config: any = {
        systemInstruction,
      };

      if (useThinking) {
        const budget = modelName.includes('pro') ? 32768 : 16000;
        config.thinkingConfig = { thinkingBudget: budget };
      }

      let contents: any;

      if (userMsg.image) {
        const [meta, data] = userMsg.image.split(',');
        const mimeType = meta.match(/:(.*?);/)?.[1] || 'image/png';

        contents = {
          parts: [
            { inlineData: { mimeType, data } },
            { text: userMsg.text || "Please analyze this image." }
          ]
        };
      } else {
        contents = {
            parts: [{ text: userMsg.text }]
        };
      }

      const response = await ai.models.generateContent({
        model: modelName,
        contents,
        config
      });

      const responseText = response.text || "Thinking process completed, but no direct text output was generated.";

      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: responseText
      }]);

    } catch (error: any) {
      console.error("GenAI Error:", error);
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: `${t('error')}: ${error.message || "Something went wrong."}`
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* Floating Trigger */}
      {!isOpen && (
        <button
          onClick={() => setIsOpen(true)}
          className="fixed bottom-8 right-8 w-14 h-14 bg-slate-900 text-white rounded-2xl shadow-2xl hover:shadow-emerald-900/30 hover:scale-105 transition-all flex items-center justify-center z-50 group border border-slate-700"
        >
          <div className="absolute inset-0 bg-gradient-to-tr from-emerald-600 to-indigo-600 rounded-2xl opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
          <Sparkles className="w-6 h-6 relative z-10" strokeWidth={1.5} />
          <div className="absolute -top-1 -right-1 w-3 h-3 bg-red-500 rounded-full border-2 border-slate-900 z-20"></div>
        </button>
      )}

      {/* Chat Window */}
      {isOpen && (
        <div className="fixed bottom-8 right-8 w-[420px] h-[650px] max-h-[85vh] bg-white rounded-3xl shadow-2xl border border-slate-200/60 flex flex-col z-50 animate-in slide-in-from-bottom-10 fade-in duration-300 overflow-hidden font-sans">

          {/* Header */}
          <div className="flex flex-col p-5 bg-white/90 backdrop-blur-md border-b border-slate-100 relative z-10">
            <div className="flex items-center justify-between mb-4">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-purple-600 text-white rounded-xl flex items-center justify-center shadow-lg shadow-indigo-200">
                        <Bot size={22} />
                    </div>
                    <div>
                        <h3 className="font-bold text-slate-900 text-base leading-tight">{t('copilot')}</h3>
                        <div className="flex items-center gap-1.5 mt-0.5">
                            <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span>
                            <span className="text-[11px] text-slate-500 font-medium">{t('modelActive')}</span>
                        </div>
                    </div>
                </div>
                <button 
                    onClick={() => setIsOpen(false)}
                    className="w-8 h-8 flex items-center justify-center text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full transition-colors"
                >
                    <X size={20} />
                </button>
            </div>

            {/* Model Selector Pill */}
            <div className="flex items-center justify-between bg-slate-50 p-1 pl-3 pr-2 rounded-xl border border-slate-200/50">
                <div className="flex items-center gap-2 text-xs text-slate-600 font-medium">
