                    <div className="px-4 py-3 flex items-center justify-between bg-slate-50/80 dark:bg-slate-800/80 rounded-t-xl backdrop-blur-sm">
                        <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">{t('configureColumns')}</p>
                        <div className="flex gap-3 text-xs">
