                                <span className={`ml-3 truncate flex-1 ${col.isSystem ? 'text-slate-900 dark:text-slate-200 font-medium' : 'text-slate-600 dark:text-slate-400 group-hover:text-slate-900 dark:group-hover:text-slate-200'}`}>{tProp(col.label)}</span>
                                {col.isSystem && <span className="ml-auto text-[10px] text-slate-400 font-medium bg-slate-100 dark:bg-slate-800 px-1.5 py-0.5 rounded border border-slate-200 dark:border-slate-700">FIXED</span>}
                            </label>
                        ))}
