};

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Send, Image as ImageIcon, Sparkles, X, Loader2, BrainCircuit, Bot, User, ChevronDown, Cpu, MessageSquarePlus, ScanEye, Zap } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';

interface AIAssistantProps {
  contextData: Product[];
}

interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  image?: string;
  isThinking?: boolean;
}

export const AIAssistant: React.FC<AIAssistantProps> = ({ contextData }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const { t, language } = useLanguage();
  const { theme } = useTheme();
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [useThinking, setUseThinking] = useState(false);
  const [selectedModel, setSelectedModel] = useState('gemini-3-flash-preview');
  const [attachedImage, setAttachedImage] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const analyzeInputRef = useRef<HTMLInputElement>(null);

  // Reset/Init Welcome message
  useEffect(() => {
    if (messages.length === 0) {
        setMessages([{ 
            id: 'welcome', 
            role: 'model', 
            text: t('welcomeMessage') 
        }]);
    }
  }, [t, messages.length]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isOpen]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setAttachedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  };

  const handleAnalyzeUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const imgData = reader.result as string;
        const prompt = language === 'zh' 
          ? "请详细分析这张图片。如果图片包含塑料颗粒，请尝试识别其可能的树脂类型（如PE, PP, ABS等）和形态。如果图片显示塑料制品或测试样条，请指出是否存在可见缺陷（如晶点、杂质、流纹、焦烧、色差等）。" 
          : "Please analyze this image in detail. If it contains resin pellets, try to identify the potential resin type (e.g., PE, PP, ABS) and morphology. If it shows plastic parts or test bars, identify any visible defects (like gels, contamination, flow marks, burns, discoloration).";

        handleSend(prompt, imgData);
      };
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  };

  const handleSend = async (manualText?: string, manualImage?: string) => {
    const textToSend = typeof manualText === 'string' ? manualText : input;
    const imageToSend = typeof manualImage === 'string' ? manualImage : attachedImage;

    if ((!textToSend.trim() && !imageToSend) || isLoading) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: textToSend,
      image: imageToSend || undefined
    };

    setMessages(prev => [...prev, userMsg]);
    if (typeof manualText !== 'string') setInput('');
    if (typeof manualImage !== 'string') setAttachedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const dataSummary = contextData.slice(0, 50).map(p => 
        `- ${p.gradeName} (${p.manufacturer}): ${Object.entries(p.properties).map(([k,v]) => `${k}=${v.value}${v.unit||''}`).join(', ')}`
      ).join('\n');

      const systemInstruction = `You are ResinAI, an expert assistant for a petrochemical synthetic resin database (ResinDB).
      Current Data Context (First 50 visible items from user filter):
      ${dataSummary}
      Instructions:
      1. Answer questions based specifically on the provided resin data when possible.
      2. If the user asks for comparison, use the numeric data to compare properties like Density, MFR, Tensile Strength etc.
      3. If analyzing an image, identify standard resin pellets, technical data sheets, or plastic part defects.
      4. Answer in the requested language (${language === 'zh' ? 'Chinese' : 'English'}).
      `;

      let modelName = selectedModel;
      let config: any = { systemInstruction };
      if (useThinking) {
        const budget = modelName.includes('pro') ? 32768 : 16000;
        config.thinkingConfig = { thinkingBudget: budget };
      }

      let contents: any;
      if (userMsg.image) {
        const [meta, data] = userMsg.image.split(',');
        const mimeType = meta.match(/:(.*?);/)?.[1] || 'image/png';
        contents = {
          parts: [
            { inlineData: { mimeType, data } },
            { text: userMsg.text || "Please analyze this image." }
          ]
        };
      } else {
        contents = { parts: [{ text: userMsg.text }] };
      }

      const response = await ai.models.generateContent({ model: modelName, contents, config });
      const responseText = response.text || "Thinking process completed, but no direct text output was generated.";

      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: responseText
      }]);
    } catch (error: any) {
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: `${t('error')}: ${error.message || "Something went wrong."}`
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* Floating Trigger - Modernized */}
      {!isOpen && (
        <button
          onClick={() => setIsOpen(true)}
          className={`fixed bottom-8 right-8 w-14 h-14 rounded-2xl shadow-2xl hover:scale-105 transition-all flex items-center justify-center z-50 group
             ${theme === 'dark' 
               ? 'bg-slate-900 border border-slate-700 hover:shadow-cyan-900/50' 
               : 'bg-slate-900 text-white hover:shadow-emerald-900/30'}
          `}
        >
          {theme === 'dark' && (
             <div className="absolute inset-0 rounded-2xl bg-cyan-500/20 blur-md opacity-50 group-hover:opacity-100 transition-opacity"></div>
          )}
          <div className={`absolute inset-0 rounded-2xl opacity-0 group-hover:opacity-100 transition-opacity duration-500
            ${theme === 'dark' ? 'bg-gradient-to-tr from-cyan-900/50 to-blue-900/50' : 'bg-gradient-to-tr from-emerald-600 to-indigo-600'}`}>
          </div>
          <Sparkles className={`w-6 h-6 relative z-10 ${theme === 'dark' ? 'text-cyan-400' : 'text-white'}`} strokeWidth={1.5} />
          <div className="absolute -top-1 -right-1 w-3 h-3 bg-red-500 rounded-full border-2 border-slate-900 z-20"></div>
        </button>
      )}

      {/* Chat Window - Optimized for Dark/Light */}
      {isOpen && (
        <div className={`fixed bottom-8 right-8 w-[420px] h-[650px] max-h-[85vh] rounded-3xl shadow-2xl flex flex-col z-50 animate-in slide-in-from-bottom-10 fade-in duration-300 overflow-hidden font-sans border backdrop-blur-2xl
            ${theme === 'dark' 
              ? 'bg-slate-950/80 border-slate-700/50 shadow-black/80 ring-1 ring-white/5' 
              : 'bg-white/95 border-slate-200/60 shadow-slate-300/50'}
        `}>

          {/* Header */}
          <div className={`flex flex-col p-5 border-b relative z-10 transition-colors
              ${theme === 'dark' ? 'bg-slate-900/50 border-slate-800' : 'bg-white/90 border-slate-100'}`}>
            <div className="flex items-center justify-between mb-4">
                <div className="flex items-center gap-3">
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg transition-all
                        ${theme === 'dark' 
                          ? 'bg-gradient-to-br from-cyan-500/20 to-blue-600/20 text-cyan-400 shadow-cyan-900/20 ring-1 ring-cyan-500/30' 
                          : 'bg-gradient-to-br from-indigo-500 to-purple-600 text-white shadow-indigo-200'}
                    `}>
                        <Bot size={22} />
                    </div>
                    <div>
                        <h3 className={`font-bold text-base leading-tight ${theme === 'dark' ? 'text-slate-100' : 'text-slate-900'}`}>{t('copilot')}</h3>
                        <div className="flex items-center gap-1.5 mt-0.5">
                            <span className={`w-1.5 h-1.5 rounded-full animate-pulse ${theme === 'dark' ? 'bg-cyan-500 shadow-[0_0_8px_rgba(6,182,212,0.6)]' : 'bg-emerald-500'}`}></span>
                            <span className={`text-[11px] font-medium ${theme === 'dark' ? 'text-cyan-200/70' : 'text-slate-500'}`}>{t('modelActive')}</span>
                        </div>
                    </div>
                </div>
                <button 
                    onClick={() => setIsOpen(false)}
                    className={`w-8 h-8 flex items-center justify-center rounded-full transition-colors
                        ${theme === 'dark' ? 'text-slate-400 hover:bg-slate-800 hover:text-slate-200' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100'}`}
                >
                    <X size={20} />
                </button>
            </div>

            {/* Controls */}
            <div className={`flex items-center justify-between p-1 pl-3 pr-2 rounded-xl border transition-colors
                ${theme === 'dark' ? 'bg-slate-800/40 border-slate-700/50' : 'bg-slate-50 border-slate-200/50'}`}>
                <div className="flex items-center gap-2 text-xs font-medium">
                    <Cpu size={14} className={theme === 'dark' ? 'text-cyan-400' : 'text-indigo-500'} />
                    <select 
                        value={selectedModel}
                        onChange={(e) => setSelectedModel(e.target.value)}
                        className={`bg-transparent outline-none cursor-pointer transition-colors appearance-none pr-4
                             ${theme === 'dark' ? 'text-slate-300 hover:text-cyan-300' : 'text-slate-600 hover:text-indigo-600'}`}
                    >
                        <option value="gemini-3-flash-preview" className={theme === 'dark' ? 'bg-slate-900' : ''}>Gemini 2.5 Flash</option>
                        <option value="gemini-3-pro-preview" className={theme === 'dark' ? 'bg-slate-900' : ''}>Gemini 2.5 Pro</option>
                    </select>
                </div>

                <button 
                    onClick={() => setUseThinking(!useThinking)}
                    className={`flex items-center gap-1.5 px-2 py-1 rounded-lg text-[10px] font-bold uppercase tracking-wide transition-all ${
                        useThinking 
                        ? (theme === 'dark' ? 'bg-rose-500/20 text-rose-300 border border-rose-500/50 shadow-[0_0_10px_rgba(244,63,94,0.3)]' : 'bg-gradient-to-r from-pink-500 to-rose-500 text-white shadow-md shadow-rose-200')
                        : (theme === 'dark' ? 'bg-slate-800 text-slate-500 border border-slate-700 hover:bg-slate-700' : 'bg-white text-slate-400 border border-slate-200 hover:bg-slate-100')
                    }`}
                >
                    <BrainCircuit size={12} />
                    {useThinking ? t('thinkingOn') : t('thinkingOff')}
                </button>
            </div>
          </div>

          {/* Messages Area */}
          <div className={`flex-1 overflow-y-auto p-4 space-y-5 custom-scrollbar scroll-smooth
               ${theme === 'dark' ? 'bg-slate-950/30' : 'bg-slate-50/50'}`}>
            {messages.map((msg) => (
              <div key={msg.id} className={`flex gap-3 ${msg.role === 'user' ? 'flex-row-reverse' : ''} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
                <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 mt-1 shadow-sm border
                    ${msg.role === 'user' 
                    ? (theme === 'dark' ? 'bg-slate-800 border-slate-700 text-slate-300' : 'bg-slate-200 border-slate-300 text-slate-600')
                    : (theme === 'dark' ? 'bg-slate-900 border-cyan-900/50 text-cyan-400' : 'bg-white border-indigo-100 text-indigo-600')
                }`}>
                    {msg.role === 'user' ? <User size={16} /> : <Bot size={16} />}
                </div>
                <div className={`flex flex-col gap-1 max-w-[85%]`}>
                    <div className={`p-3.5 text-sm shadow-sm leading-relaxed backdrop-blur-sm
                        ${msg.role === 'user' 
                        ? (theme === 'dark' 
                            ? 'bg-gradient-to-br from-indigo-600 to-blue-700 text-white rounded-2xl rounded-tr-sm border border-indigo-500/30' 
                            : 'bg-slate-800 text-white rounded-2xl rounded-tr-sm')
                        : (theme === 'dark'
                            ? 'bg-slate-900/80 text-slate-200 border border-slate-800 rounded-2xl rounded-tl-sm'
                            : 'bg-white text-slate-700 border border-slate-200 rounded-2xl rounded-tl-sm')
                    }`}>
                        {msg.image && (
                            <img src={msg.image} alt="Upload" className="w-full h-auto rounded-lg mb-3 border border-white/10" />
                        )}
                        <p className="whitespace-pre-wrap">{msg.text}</p>
                    </div>
                </div>
              </div>
            ))}

            {/* Loading Indicator */}
            {isLoading && (
               <div className="flex gap-3 animate-pulse">
                   <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 mt-1 border
                        ${theme === 'dark' ? 'bg-slate-900 border-cyan-900/50 text-cyan-400' : 'bg-white border-indigo-100 text-indigo-600'}`}>
                        <Loader2 size={16} className="animate-spin" />
                   </div>
                   <div className={`p-3.5 rounded-2xl rounded-tl-sm text-sm flex items-center gap-2 border
                       ${theme === 'dark' ? 'bg-slate-900/80 border-slate-800 text-slate-400' : 'bg-white border-slate-200 text-slate-500'}`}>
                       {useThinking ? <BrainCircuit size={14} className="animate-pulse text-rose-500"/> : null}
                       <span>{useThinking ? t('reasoning') : t('analyzing')}</span>
                       <span className="flex gap-1 ml-1">
                          <span className="w-1 h-1 bg-slate-400 rounded-full animate-bounce" style={{animationDelay: '0ms'}}></span>
                          <span className="w-1 h-1 bg-slate-400 rounded-full animate-bounce" style={{animationDelay: '150ms'}}></span>
                          <span className="w-1 h-1 bg-slate-400 rounded-full animate-bounce" style={{animationDelay: '300ms'}}></span>
                       </span>
                   </div>
               </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input Area */}
          <div className={`p-4 border-t ${theme === 'dark' ? 'bg-slate-900/80 border-slate-800' : 'bg-white border-slate-100'}`}>
             {attachedImage && (
                 <div className="mb-3 relative inline-block animate-in zoom-in duration-200">
                     <div className="relative group">
                        <img src={attachedImage} alt="Preview" className={`h-16 w-16 object-cover rounded-lg shadow-sm border ${theme === 'dark' ? 'border-slate-700' : 'border-slate-200'}`} />
                        <button 
                            onClick={() => setAttachedImage(null)}
                            className="absolute -top-2 -right-2 bg-slate-800 text-white rounded-full p-0.5 shadow-md opacity-0 group-hover:opacity-100 transition-opacity"
                        >
                            <X size={12} />
                        </button>
                     </div>
                     <span className="text-[10px] text-emerald-600 font-medium absolute -bottom-4 left-0 w-full text-center whitespace-nowrap">{t('imageAttached')}</span>
                 </div>
             )}

             <div className={`flex items-end gap-2 p-2 rounded-2xl border transition-all
                  ${theme === 'dark' 
                    ? 'bg-slate-950 border-slate-800 focus-within:border-cyan-800 focus-within:ring-1 focus-within:ring-cyan-900/50' 
                    : 'bg-slate-50 border-slate-200 focus-within:border-indigo-300 focus-within:ring-2 focus-within:ring-indigo-100'}`}>
                {/* Inputs */}
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
                <button 
                    onClick={() => fileInputRef.current?.click()}
                    className={`p-2 rounded-xl transition-colors
                        ${theme === 'dark' ? 'text-slate-500 hover:text-cyan-400 hover:bg-slate-800' : 'text-slate-400 hover:text-indigo-600 hover:bg-indigo-50'}`}
                    title={t('uploadImage')}
                >
                    <ImageIcon size={20} />
                </button>

                <input type="file" ref={analyzeInputRef} className="hidden" accept="image/*" onChange={handleAnalyzeUpload} />
                <button 
                    onClick={() => analyzeInputRef.current?.click()}
                    className={`p-2 rounded-xl transition-colors
                        ${theme === 'dark' ? 'text-slate-500 hover:text-emerald-400 hover:bg-slate-800' : 'text-slate-400 hover:text-emerald-600 hover:bg-emerald-50'}`}
                    title="Scan & Analyze"
                >
                    <ScanEye size={20} />
                </button>

                <textarea
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => {
                        if (e.key === 'Enter' && !e.shiftKey) {
                            e.preventDefault();
                            handleSend();
                        }
                    }}
                    placeholder={attachedImage ? t('imageContext') : t('aiPlaceholder')}
                    className={`flex-1 max-h-32 bg-transparent border-none focus:ring-0 text-sm py-2.5 resize-none placeholder:text-slate-500
                         ${theme === 'dark' ? 'text-slate-200' : 'text-slate-800'}`}
                    rows={1}
                />
                <button 
                    onClick={() => handleSend()}
                    disabled={(!input.trim() && !attachedImage) || isLoading}
                    className={`p-2 rounded-xl transition-all shadow-md disabled:opacity-50 disabled:cursor-not-allowed
                         ${theme === 'dark' 
                           ? 'bg-gradient-to-br from-cyan-600 to-blue-600 text-white shadow-cyan-900/30 hover:shadow-cyan-900/50' 
                           : 'bg-slate-900 text-white shadow-slate-200 hover:bg-slate-800'}`}
                >
                    <Send size={18} />
                </button>
             </div>
             <p className="text-[10px] text-center text-slate-500 mt-2">
                {t('disclaimer')}
             </p>
          </div>
        </div>
      )}
    </>
  );
};

import React, { useState } from 'react';
import { Category } from '../types';
import { ChevronRight, Folder, FolderOpen, Layers, LayoutGrid, Beaker, Database } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

interface TreeSidebarProps {
  categories: Category[];
  selectedCategoryId: string | null;
  onSelectCategory: (id: string | null) => void;
}

const TreeNode: React.FC<{
  category: Category;
  selectedId: string | null;
  onSelect: (id: string) => void;
  depth: number;
}> = ({ category, selectedId, onSelect, depth }) => {
  const [isOpen, setIsOpen] = useState(depth < 1); // Auto expand root
  const hasChildren = category.children && category.children.length > 0;
  const isSelected = selectedId === category.id;
  const { language } = useLanguage();

  return (
    <div className="select-none">
      <div
        onClick={(e) => {
            e.stopPropagation();
            if(hasChildren) setIsOpen(!isOpen);
            onSelect(category.id);
        }}
        className={`
          flex items-center px-3 py-2.5 cursor-pointer text-sm transition-all duration-200 mx-2 rounded-lg mb-0.5 group relative overflow-hidden
          ${isSelected 
            ? 'bg-emerald-600 text-white shadow-md shadow-emerald-900/20 dark:shadow-emerald-900/40 font-medium' 
            : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800/60 hover:text-slate-900 dark:hover:text-slate-200'}
        `}
        style={{ paddingLeft: `${depth * 16 + 12}px` }}
      >
