import React, { useState } from 'react';
import { X, FileSpreadsheet, UploadCloud, CheckCircle, AlertCircle } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

interface ImportModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export const ImportModal: React.FC<ImportModalProps> = ({ isOpen, onClose }) => {
  const [step, setStep] = useState<1 | 2 | 3>(1);
  const [isDragging, setIsDragging] = useState(false);
  const { t } = useLanguage();

  if (!isOpen) return null;

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    setStep(2);
    // Simulate processing
    setTimeout(() => setStep(3), 1500);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
      <div className="w-full max-w-lg bg-white dark:bg-slate-900 rounded-xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200 ring-1 ring-slate-200 dark:ring-slate-800">
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/50">
          <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 flex items-center gap-2">
            <FileSpreadsheet className="text-emerald-600 dark:text-emerald-500" size={20} />
            {t('importTitle')}
          </h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200">
            <X size={20} />
          </button>
        </div>

        <div className="p-8">
          {step === 1 && (
            <div 
                className={`border-2 border-dashed rounded-xl p-10 flex flex-col items-center justify-center text-center transition-colors
                    ${isDragging 
                        ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/20' 
                        : 'border-slate-300 dark:border-slate-700 hover:border-slate-400 dark:hover:border-slate-600 bg-slate-50/50 dark:bg-slate-800/30'}
                `}
                onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
                onDragLeave={() => setIsDragging(false)}
                onDrop={handleDrop}
            >
              <div className="w-16 h-16 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-full flex items-center justify-center mb-4">
                <UploadCloud size={32} />
              </div>
              <h4 className="text-slate-900 dark:text-slate-100 font-medium mb-1">{t('dragDrop')}</h4>
              <p className="text-slate-500 dark:text-slate-400 text-sm mb-4">{t('dragDropDesc')}</p>
              <button 
                onClick={() => { setStep(2); setTimeout(() => setStep(3), 1500); }}
                className="px-4 py-2 bg-blue-600 text-white text-sm font-medium rounded-lg hover:bg-blue-700 dark:hover:bg-blue-500 transition-colors"
              >
                {t('browseFiles')}
              </button>
              <div className="mt-6 text-xs text-yellow-700 dark:text-yellow-400 bg-yellow-50 dark:bg-yellow-900/20 px-3 py-2 rounded border border-yellow-200 dark:border-yellow-900/30">
                 {t('securityNote')}
              </div>
            </div>
          )}

          {step === 2 && (
            <div className="flex flex-col items-center justify-center py-10">
                <div className="w-12 h-12 border-4 border-blue-200 dark:border-blue-900 border-t-blue-600 dark:border-t-blue-400 rounded-full animate-spin mb-4"></div>
                <h4 className="text-slate-900 dark:text-slate-100 font-medium">{t('processing')}</h4>
            </div>
          )}

          {step === 3 && (
            <div className="flex flex-col items-center justify-center py-6 text-center">
                <CheckCircle className="text-emerald-500 dark:text-emerald-400 w-16 h-16 mb-4" />
                <h4 className="text-slate-900 dark:text-white font-bold text-lg">{t('success')}</h4>
                <p className="text-slate-600 dark:text-slate-400 text-sm mt-2 mb-6">
                    {t('importSuccessMsg')}<br/>
                    {t('importStatMsg')}
                </p>
                <div className="flex gap-3 w-full">
                    <button onClick={onClose} className="flex-1 px-4 py-2 bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-200 font-medium rounded-lg hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">
                        {t('viewLog')}
                    </button>
                    <button onClick={onClose} className="flex-1 px-4 py-2 bg-slate-900 dark:bg-slate-700 text-white font-medium rounded-lg hover:bg-slate-800 dark:hover:bg-slate-600 transition-colors">
                        {t('finish')}
                    </button>
                </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

