                >
                    <ImageIcon size={20} />
                </button>

                {/* Scan Button (Explicitly Requested) */}
                <input type="file" ref={analyzeInputRef} className="hidden" accept="image/*" onChange={handleAnalyzeUpload} />
                <button 
                    onClick={() => analyzeInputRef.current?.click()}
                    className={`p-2 rounded-lg transition-colors
                        ${theme === 'dark' ? 'text-emerald-500 hover:text-emerald-400 hover:bg-slate-900' : 'text-emerald-600 hover:text-emerald-700 hover:bg-emerald-50'}`}
                    title="Scan Resin/Defects"
                >
                    <ScanEye size={20} />
                </button>

                <textarea
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => {
                        if (e.key === 'Enter' && !e.shiftKey) {
                            e.preventDefault();
                            handleSend();
                        }
                    }}
                    placeholder={attachedImage ? t('imageContext') : t('aiPlaceholder')}
                    className={`flex-1 max-h-32 bg-transparent border-none focus:ring-0 text-sm py-2 px-1 resize-none placeholder:text-slate-400
                         ${theme === 'dark' ? 'text-slate-200' : 'text-slate-800'}`}
                    rows={1}
                />

                {/* Send Button */}
                <button 
                    onClick={() => handleSend()}
                    disabled={(!input.trim() && !attachedImage) || isLoading}
                    className={`p-2 rounded-lg transition-all shadow-sm disabled:opacity-50 disabled:cursor-not-allowed
                         ${theme === 'dark' 
                           ? 'bg-emerald-600 hover:bg-emerald-500 text-white' 
                           : 'bg-emerald-600 hover:bg-emerald-700 text-white'}`}
                >
                    <Send size={18} />
                </button>
             </div>
          </div>
        </div>
      )}
    </>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { CATEGORY_TREE, MOCK_PRODUCTS } from './constants';
import { Product, ColumnConfig, ViewMode } from './types';
import { TreeSidebar } from './components/TreeSidebar';
import { DataGrid } from './components/DataGrid';
import { DataVisualizer } from './components/DataVisualizer';
import { TopBar } from './components/TopBar';
import { ImportModal } from './components/ImportModal';
import { AIAssistant } from './components/AIAssistant';
import { LayoutDashboard, Database, Activity } from 'lucide-react';
import { LanguageProvider } from './contexts/LanguageContext';
import { ThemeProvider } from './contexts/ThemeContext';

const getDynamicColumns = (products: Product[]): ColumnConfig[] => {
  const propertyKeys = new Set<string>();
  products.forEach(p => {
    Object.keys(p.properties).forEach(k => propertyKeys.add(k));
  });

  const defaultVisible = ['密度', '熔体流动速率', '应用', '类型', '典型应用', '硬度', '悬臂梁缺口冲击', '拉伸强度'];

  const dynamicCols: ColumnConfig[] = Array.from(propertyKeys).map(key => ({
    key,
    label: key,
    visible: defaultVisible.includes(key),
    isSystem: false
  })).sort((a, b) => {
      // Prioritize numeric columns slightly for better default view
      const aIsLikelyImportant = defaultVisible.includes(a.key);
      const bIsLikelyImportant = defaultVisible.includes(b.key);
      if (aIsLikelyImportant && !bIsLikelyImportant) return -1;
      if (!aIsLikelyImportant && bIsLikelyImportant) return 1;
      return a.label.localeCompare(b.label);
  });

  const systemCols: ColumnConfig[] = [
    { key: 'gradeName', label: '牌号', visible: true, isSystem: true },
    { key: 'manufacturer', label: '生产厂家', visible: true, isSystem: true },
    { key: 'updatedAt', label: '更新时间', visible: false, isSystem: false },
  ];

  return [...systemCols, ...dynamicCols];
};

const AppContent: React.FC = () => {
  // State for products to allow updates/imports
  const [allProducts, setAllProducts] = useState<Product[]>(MOCK_PRODUCTS);
  const [selectedCategoryId, setSelectedCategoryId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [columns, setColumns] = useState<ColumnConfig[]>([]);
  const [isImportOpen, setIsImportOpen] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>('grid');

  // Initialize columns based on initial data
  useEffect(() => {
    setColumns(getDynamicColumns(allProducts));
  }, []); // Run once on mount

  // Update columns if new properties appear in data (optional, but good for robustness)
  useEffect(() => {
     // We only update if the number of potential columns has changed to avoid resetting user preference too often
     // For a prototype, re-calculating on data change is acceptable behavior
     const newCols = getDynamicColumns(allProducts);
     if (newCols.length !== columns.length) {
         setColumns(newCols);
     }
  }, [allProducts.length]);

  const handleToggleColumn = (key: string) => {
    setColumns(cols => cols.map(c => 
      c.key === key ? { ...c, visible: !c.visible } : c
    ));
  };

  const handleToggleAllColumns = (visible: boolean) => {
    setColumns(cols => cols.map(c => 
      c.isSystem ? c : { ...c, visible }
    ));
  };

  // Simulate importing data
  const handleImportData = () => {
      const newProducts: Product[] = Array.from({ length: 5 }).map((_, i) => ({
        id: `imported-${Date.now()}-${i}`,
        gradeName: `New-Grade-${1000 + i} (Imported)`,
        manufacturer: 'Synthetic Tech Inc.',
        categoryIds: ['cat_pe', 'cat_packaging'],
        updatedAt: new Date().toISOString().split('T')[0],
        properties: {
          '密度': { value: 0.92 + (Math.random() * 0.05), unit: 'g/cm³' },
          '熔体流动速率': { value: 1 + (Math.random() * 5), unit: 'g/10min' },
          '应用': { value: 'Imported batch test' }
        }
      }));

      setAllProducts(prev => [...newProducts, ...prev]);
      setIsImportOpen(false);
  };

  const filteredData = useMemo(() => {
    return allProducts.filter(product => {
      const matchesCategory = selectedCategoryId 
        ? product.categoryIds.includes(selectedCategoryId)
        : true;

      if (!matchesCategory) return false;

      const query = searchQuery.toLowerCase();
      const matchesSearch = 
        product.gradeName.toLowerCase().includes(query) ||
        product.manufacturer.toLowerCase().includes(query) ||
        Object.keys(product.properties).some(k => k.toLowerCase().includes(query));

      return matchesSearch;
    });
  }, [allProducts, selectedCategoryId, searchQuery]);

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 font-sans text-slate-900 dark:text-slate-100 overflow-hidden transition-colors duration-300 selection:bg-emerald-500/30">

      {/* Sidebar - Navigation */}
      <TreeSidebar 
        categories={CATEGORY_TREE}
        selectedCategoryId={selectedCategoryId}
        onSelectCategory={setSelectedCategoryId}
      />

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0 h-full relative">

        {/* Top Header */}
        <TopBar 
            searchQuery={searchQuery}
            onSearchChange={setSearchQuery}
            columns={columns}
            onToggleColumn={handleToggleColumn}
            onToggleAllColumns={handleToggleAllColumns}
            onOpenImport={() => setIsImportOpen(true)}
            viewMode={viewMode}
            onViewModeChange={setViewMode}
        />

        {/* Content Body */}
        <div className="flex-1 p-6 overflow-y-auto overflow-x-hidden w-full scroll-smooth">
            {/* Page Header */}
            <div className="flex items-end justify-between mb-6 flex-shrink-0 animate-in fade-in slide-in-from-top-4 duration-300">
                <div>
                    <h1 className="text-2xl font-bold text-slate-900 dark:text-slate-100 flex items-center gap-2 tracking-tight">
                        {viewMode === 'grid' ? <Database size={24} className="text-emerald-600 dark:text-emerald-500"/> : <Activity size={24} className="text-indigo-600 dark:text-indigo-400"/>}
                        {selectedCategoryId 
                            ? `Category: ${selectedCategoryId}` 
                            : viewMode === 'grid' ? 'Database Overview' : 'Data Analytics'}
                    </h1>
                    <p className="text-slate-500 dark:text-slate-400 text-sm mt-1 ml-8">
                        Found <span className="font-semibold text-slate-900 dark:text-slate-200">{filteredData.length}</span> synthetic resin products matching your criteria.
                    </p>
                </div>
            </div>

            <div className="w-full h-[calc(100%-80px)] animate-in fade-in zoom-in-95 duration-300">
                {viewMode === 'grid' ? (
                    <DataGrid 
                        data={filteredData}
                        columns={columns}
                        isLoading={false}
                    />
                ) : (
                    <DataVisualizer data={filteredData} />
                )}
            </div>
        </div>
      </div>

      <ImportModal 
        isOpen={isImportOpen} 
        onClose={() => setIsImportOpen(false)} 
        onImport={handleImportData}
      />

      {/* Gemini Powered Assistant */}
      <AIAssistant contextData={filteredData} />
    </div>
  );
};

const App: React.FC = () => {
  return (
    <LanguageProvider>
      <ThemeProvider>
        <AppContent />
      </ThemeProvider>
    </LanguageProvider>
  );
};

export default App;

import React, { useState } from 'react';
import { X, FileSpreadsheet, UploadCloud, CheckCircle, AlertCircle } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

interface ImportModalProps {
  isOpen: boolean;
  onClose: () => void;
  onImport?: () => void;
}

export const ImportModal: React.FC<ImportModalProps> = ({ isOpen, onClose, onImport }) => {
  const [step, setStep] = useState<1 | 2 | 3>(1);
  const [isDragging, setIsDragging] = useState(false);
  const { t } = useLanguage();

  if (!isOpen) return null;

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    setStep(2);
    // Simulate processing
    setTimeout(() => setStep(3), 1500);
  };

  const handleFinish = () => {
      if (onImport) onImport();
      onClose();
      // Reset state after closing
      setTimeout(() => setStep(1), 300);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
      <div className="w-full max-w-lg bg-white dark:bg-slate-900 rounded-xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200 ring-1 ring-slate-200 dark:ring-slate-800">
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/50">
          <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 flex items-center gap-2">
            <FileSpreadsheet className="text-emerald-600 dark:text-emerald-500" size={20} />
            {t('importTitle')}
          </h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors">
            <X size={20} />
          </button>
        </div>

        <div className="p-8">
          {step === 1 && (
            <div 
                className={`border-2 border-dashed rounded-xl p-10 flex flex-col items-center justify-center text-center transition-colors duration-200
                    ${isDragging 
                        ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/20' 
                        : 'border-slate-300 dark:border-slate-700 hover:border-slate-400 dark:hover:border-slate-600 bg-slate-50/50 dark:bg-slate-800/30'}
                `}
                onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
                onDragLeave={() => setIsDragging(false)}
                onDrop={handleDrop}
            >
              <div className="w-16 h-16 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-full flex items-center justify-center mb-4">
                <UploadCloud size={32} />
              </div>
              <h4 className="text-slate-900 dark:text-slate-100 font-medium mb-1">{t('dragDrop')}</h4>
              <p className="text-slate-500 dark:text-slate-400 text-sm mb-4">{t('dragDropDesc')}</p>
              <button 
                onClick={() => { setStep(2); setTimeout(() => setStep(3), 1500); }}
                className="px-4 py-2 bg-blue-600 text-white text-sm font-medium rounded-lg hover:bg-blue-700 dark:hover:bg-blue-500 transition-colors shadow-sm"
              >
                {t('browseFiles')}
              </button>
              <div className="mt-6 text-xs text-yellow-700 dark:text-yellow-400 bg-yellow-50 dark:bg-yellow-900/20 px-3 py-2 rounded border border-yellow-200 dark:border-yellow-900/30 flex items-center gap-2">
                 <AlertCircle size={12} />
                 {t('securityNote')}
              </div>
            </div>
          )}

          {step === 2 && (
            <div className="flex flex-col items-center justify-center py-10">
                <div className="relative mb-4">
                    <div className="w-12 h-12 border-4 border-blue-200 dark:border-blue-900 border-t-blue-600 dark:border-t-blue-400 rounded-full animate-spin"></div>
                </div>
                <h4 className="text-slate-900 dark:text-slate-100 font-medium animate-pulse">{t('processing')}</h4>
            </div>
          )}

          {step === 3 && (
            <div className="flex flex-col items-center justify-center py-6 text-center">
                <div className="w-16 h-16 bg-emerald-100 dark:bg-emerald-900/30 rounded-full flex items-center justify-center mb-4 animate-in zoom-in duration-300">
                    <CheckCircle className="text-emerald-600 dark:text-emerald-400 w-8 h-8" />
                </div>
                <h4 className="text-slate-900 dark:text-white font-bold text-lg mb-1">{t('success')}</h4>
                <p className="text-slate-600 dark:text-slate-400 text-sm mt-2 mb-6 max-w-xs mx-auto">
                    {t('importSuccessMsg')}<br/>
                    <span className="text-slate-500 dark:text-slate-500 text-xs mt-1 block">{t('importStatMsg')}</span>
                </p>
                <div className="flex gap-3 w-full">
                    <button onClick={onClose} className="flex-1 px-4 py-2.5 bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 font-medium rounded-lg hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">
                        {t('viewLog')}
                    </button>
                    <button onClick={handleFinish} className="flex-1 px-4 py-2.5 bg-slate-900 dark:bg-slate-700 text-white font-medium rounded-lg hover:bg-slate-800 dark:hover:bg-slate-600 transition-colors shadow-lg shadow-slate-500/20 dark:shadow-none">
                        {t('finish')}
                    </button>
                </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Send, Image as ImageIcon, Sparkles, X, Loader2, BrainCircuit, Bot, User, Cpu, ScanEye } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';

interface AIAssistantProps {
  contextData: Product[];
}

interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  image?: string;
  isThinking?: boolean;
}

// Simple text formatter to handle bold (**text**) and lists (- item)
const FormattedText: React.FC<{ text: string; className?: string }> = ({ text, className }) => {
  if (!text) return null;

  return (
    <div className={className}>
      {text.split('\n').map((line, i) => {
        // Handle bullet points
        if (line.trim().startsWith('- ') || line.trim().startsWith('* ')) {
             const content = line.trim().substring(2);
             const parts = content.split(/(\*\*.*?\*\*)/g);
             return (
                <div key={i} className="flex gap-2 ml-1 mb-1">
                    <span className="text-emerald-500 dark:text-emerald-400 mt-1.5">•</span>
                    <span>
                        {parts.map((part, j) => {
                            if (part.startsWith('**') && part.endsWith('**')) {
                                return <strong key={j} className="font-bold">{part.slice(2, -2)}</strong>;
                            }
                            return <span key={j}>{part}</span>;
                        })}
                    </span>
                </div>
             );
        }

        // Handle standard text with bolding
        const parts = line.split(/(\*\*.*?\*\*)/g);
        return (
          <p key={i} className="mb-1.5 last:mb-0 min-h-[1.2em]">
            {parts.map((part, j) => {
              if (part.startsWith('**') && part.endsWith('**')) {
                return <strong key={j} className="font-bold text-slate-800 dark:text-slate-100">{part.slice(2, -2)}</strong>;
              }
              return <span key={j}>{part}</span>;
            })}
          </p>
        );
      })}
    </div>
  );
};

export const AIAssistant: React.FC<AIAssistantProps> = ({ contextData }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const { t, language } = useLanguage();
  const { theme } = useTheme();
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [useThinking, setUseThinking] = useState(false);
  const [selectedModel, setSelectedModel] = useState('gemini-3-flash-preview');
  const [attachedImage, setAttachedImage] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const analyzeInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (messages.length === 0) {
        setMessages([{ 
            id: 'welcome', 
            role: 'model', 
            text: t('welcomeMessage') 
        }]);
    }
  }, [t, messages.length]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isOpen]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setAttachedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  };

  const handleAnalyzeUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const imgData = reader.result as string;
        const prompt = language === 'zh' 
          ? "请详细分析这张图片。重点关注：1. 识别树脂类型（如PE, PP, ABS等）及形态（颗粒、粉末、制件）。2. 检测可见缺陷（晶点、杂质、焦烧、流纹、色差等）。请以专业技术人员的口吻回答，列出要点。" 
          : "Please analyze this image specifically for resin properties. Focus on: 1. Identifying the resin type (e.g., PE, PP, ABS) and physical form (pellets, powder, part). 2. Detecting visible defects (gels, black specks, burns, flow marks, discoloration). Provide a technical assessment in bullet points.";

        handleSend(prompt, imgData);
      };
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  };

  const handleSend = async (manualText?: string, manualImage?: string) => {
    const textToSend = typeof manualText === 'string' ? manualText : input;
    const imageToSend = typeof manualImage === 'string' ? manualImage : attachedImage;

    if ((!textToSend.trim() && !imageToSend) || isLoading) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: textToSend,
      image: imageToSend || undefined
    };

    setMessages(prev => [...prev, userMsg]);
    if (typeof manualText !== 'string') setInput('');
    if (typeof manualImage !== 'string') setAttachedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const dataSummary = contextData.slice(0, 50).map(p => 
        `- ${p.gradeName} (${p.manufacturer}): ${Object.entries(p.properties).map(([k,v]) => `${k}=${v.value}${v.unit||''}`).join(', ')}`
      ).join('\n');

      const systemInstruction = `You are ResinAI, an expert assistant for a petrochemical synthetic resin database (ResinDB).
      Current Data Context (First 50 visible items from user filter):
      ${dataSummary}
      Instructions:
      1. Answer questions based specifically on the provided resin data when possible.
      2. If the user asks for comparison, use the numeric data to compare properties like Density, MFR, Tensile Strength etc.
      3. If analyzing an image, identify standard resin pellets, technical data sheets, or plastic part defects.
      4. Use **bold** text for key values and product names.
      5. Answer in the requested language (${language === 'zh' ? 'Chinese' : 'English'}).
      `;

      let modelName = selectedModel;
      let config: any = { systemInstruction };
      if (useThinking) {
        const budget = modelName.includes('pro') ? 32768 : 16000;
        config.thinkingConfig = { thinkingBudget: budget };
      }

      let contents: any;
      if (userMsg.image) {
        const [meta, data] = userMsg.image.split(',');
        const mimeType = meta.match(/:(.*?);/)?.[1] || 'image/png';
        contents = {
          parts: [
            { inlineData: { mimeType, data } },
            { text: userMsg.text || "Please analyze this image." }
          ]
        };
      } else {
        contents = { parts: [{ text: userMsg.text }] };
      }

      const response = await ai.models.generateContent({ model: modelName, contents, config });
      const responseText = response.text || "Thinking process completed, but no direct text output was generated.";

      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: responseText
      }]);
    } catch (error: any) {
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: `${t('error')}: ${error.message || "Something went wrong."}`
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* Floating Trigger */}
      {!isOpen && (
        <button
          onClick={() => setIsOpen(true)}
          className={`fixed bottom-8 right-8 w-14 h-14 rounded-2xl shadow-xl hover:scale-110 transition-all duration-300 flex items-center justify-center z-50 group border
             ${theme === 'dark' 
               ? 'bg-slate-900 border-slate-700 hover:shadow-emerald-900/50 text-emerald-500 hover:text-emerald-400' 
               : 'bg-emerald-600 text-white hover:bg-emerald-700 shadow-emerald-200 border-emerald-500'}
          `}
        >
          <Sparkles className="w-6 h-6 animate-pulse" strokeWidth={1.5} />
          <div className="absolute -top-1 -right-1 w-3.5 h-3.5 bg-red-500 rounded-full border-2 border-white dark:border-slate-900 z-20"></div>
        </button>
      )}

      {/* Chat Window */}
      {isOpen && (
        <div className={`fixed bottom-8 right-8 w-[420px] h-[650px] max-h-[85vh] rounded-2xl shadow-2xl flex flex-col z-50 animate-in slide-in-from-bottom-10 fade-in duration-300 overflow-hidden font-sans border backdrop-blur-md
            ${theme === 'dark' 
              ? 'bg-slate-950/95 border-slate-700 shadow-black' 
              : 'bg-white/95 border-slate-200 shadow-slate-300'}
        `}>

          {/* Header */}
          <div className={`flex flex-col p-4 border-b relative z-10 transition-colors
              ${theme === 'dark' ? 'bg-slate-950/50 border-slate-800' : 'bg-slate-50/80 border-slate-100'}`}>
            <div className="flex items-center justify-between mb-3">
                <div className="flex items-center gap-3">
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-sm border
                        ${theme === 'dark' 
                          ? 'bg-slate-900 border-slate-800 text-emerald-500' 
                          : 'bg-white border-slate-200 text-emerald-600'}
                    `}>
                        <Bot size={22} />
                    </div>
                    <div>
                        <h3 className={`font-bold text-sm leading-tight ${theme === 'dark' ? 'text-slate-100' : 'text-slate-900'}`}>{t('copilot')}</h3>
                        <div className="flex items-center gap-1.5 mt-0.5">
                            <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span>
                            <span className={`text-[11px] font-medium ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>{t('modelActive')}</span>
                        </div>
                    </div>
                </div>
                <button 
                    onClick={() => setIsOpen(false)}
                    className={`w-8 h-8 flex items-center justify-center rounded-lg transition-colors
                        ${theme === 'dark' ? 'text-slate-400 hover:bg-slate-800 hover:text-slate-200' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-200'}`}
                >
                    <X size={18} />
                </button>
            </div>

            {/* Controls */}
            <div className={`flex items-center justify-between p-1 pl-2 pr-1 rounded-lg border transition-colors
                ${theme === 'dark' ? 'bg-slate-900/50 border-slate-800' : 'bg-white border-slate-200'}`}>
                <div className="flex items-center gap-2 text-xs font-medium pl-1">
                    <Cpu size={14} className={theme === 'dark' ? 'text-slate-400' : 'text-slate-500'} />
                    <select 
                        value={selectedModel}
                        onChange={(e) => setSelectedModel(e.target.value)}
                        className={`bg-transparent outline-none cursor-pointer transition-colors appearance-none
                             ${theme === 'dark' ? 'text-slate-300 hover:text-white' : 'text-slate-600 hover:text-slate-900'}`}
                    >
                        <option value="gemini-3-flash-preview" className={theme === 'dark' ? 'bg-slate-900' : ''}>Gemini 2.5 Flash</option>
                        <option value="gemini-3-pro-preview" className={theme === 'dark' ? 'bg-slate-900' : ''}>Gemini 2.5 Pro</option>
                    </select>
                </div>

                <button 
                    onClick={() => setUseThinking(!useThinking)}
                    className={`flex items-center gap-1.5 px-2 py-1 rounded-md text-[10px] font-bold uppercase tracking-wide transition-all ${
                        useThinking 
                        ? (theme === 'dark' ? 'bg-rose-900/30 text-rose-400 border border-rose-800' : 'bg-rose-100 text-rose-600 border border-rose-200')
                        : (theme === 'dark' ? 'bg-slate-800 text-slate-500 border border-slate-700 hover:bg-slate-700' : 'bg-slate-100 text-slate-400 border border-slate-200 hover:bg-slate-200')
                    }`}
                >
                    <BrainCircuit size={12} />
                    {useThinking ? t('thinkingOn') : t('thinkingOff')}
                </button>
            </div>
          </div>

          {/* Messages Area */}
          <div className={`flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar scroll-smooth
               ${theme === 'dark' ? 'bg-slate-950' : 'bg-slate-50'}`}>
            {messages.map((msg) => (
              <div key={msg.id} className={`flex gap-3 ${msg.role === 'user' ? 'flex-row-reverse' : ''} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
                <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 mt-1 shadow-sm border
                    ${msg.role === 'user' 
                    ? (theme === 'dark' ? 'bg-emerald-900/30 border-emerald-800 text-emerald-500' : 'bg-emerald-100 border-emerald-200 text-emerald-700')
                    : (theme === 'dark' ? 'bg-slate-900 border-slate-800 text-slate-400' : 'bg-white border-slate-200 text-slate-600')
                }`}>
                    {msg.role === 'user' ? <User size={16} /> : <Bot size={16} />}
                </div>
                <div className={`flex flex-col gap-1 max-w-[85%]`}>
                    <div className={`p-3.5 text-sm shadow-sm leading-relaxed
                        ${msg.role === 'user' 
                        ? 'bg-emerald-600 text-white rounded-2xl rounded-tr-sm' 
                        : (theme === 'dark'
                            ? 'bg-slate-900 text-slate-300 border border-slate-800 rounded-2xl rounded-tl-sm'
                            : 'bg-white text-slate-700 border border-slate-200 rounded-2xl rounded-tl-sm')
                    }`}>
                        {msg.image && (
                            <img src={msg.image} alt="Upload" className="w-full h-auto rounded-lg mb-3 border border-white/10" />
                        )}
                        <FormattedText text={msg.text} />
                    </div>
                </div>
              </div>
            ))}

            {/* Loading Indicator */}
            {isLoading && (
               <div className="flex gap-3 animate-pulse">
                   <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 mt-1 border
                        ${theme === 'dark' ? 'bg-slate-900 border-slate-800 text-slate-400' : 'bg-white border-slate-200 text-slate-600'}`}>
                        <Loader2 size={16} className="animate-spin" />
                   </div>
                   <div className={`p-3.5 rounded-2xl rounded-tl-sm text-sm flex items-center gap-2 border
                       ${theme === 'dark' ? 'bg-slate-900 border-slate-800 text-slate-400' : 'bg-white border-slate-200 text-slate-500'}`}>
                       <span>{useThinking ? t('reasoning') : t('analyzing')}</span>
                       <span className="flex gap-1 ml-1">
                          <span className="w-1 h-1 bg-slate-400 rounded-full animate-bounce" style={{animationDelay: '0ms'}}></span>
                          <span className="w-1 h-1 bg-slate-400 rounded-full animate-bounce" style={{animationDelay: '150ms'}}></span>
                          <span className="w-1 h-1 bg-slate-400 rounded-full animate-bounce" style={{animationDelay: '300ms'}}></span>
                       </span>
                   </div>
               </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input Area */}
          <div className={`p-3 border-t ${theme === 'dark' ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'}`}>
             {attachedImage && (
                 <div className="mb-2 relative inline-block animate-in zoom-in duration-200">
                     <div className="relative group">
                        <img src={attachedImage} alt="Preview" className={`h-12 w-12 object-cover rounded-lg shadow-sm border ${theme === 'dark' ? 'border-slate-700' : 'border-slate-200'}`} />
                        <button 
                            onClick={() => setAttachedImage(null)}
                            className="absolute -top-1.5 -right-1.5 bg-slate-800 text-white rounded-full p-0.5 shadow-md opacity-0 group-hover:opacity-100 transition-opacity"
                        >
                            <X size={10} />
                        </button>
                     </div>
                 </div>
             )}

             <div className={`flex items-end gap-2 p-1.5 rounded-xl border transition-all
                  ${theme === 'dark' 
                    ? 'bg-slate-950 border-slate-800 focus-within:border-emerald-800 focus-within:ring-1 focus-within:ring-emerald-900/50' 
                    : 'bg-slate-50 border-slate-200 focus-within:border-emerald-300 focus-within:ring-2 focus-within:ring-emerald-100'}`}>

                {/* Image Upload */}
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
                <button 
                    onClick={() => fileInputRef.current?.click()}
                    className={`p-2 rounded-lg transition-colors
                        ${theme === 'dark' ? 'text-slate-500 hover:text-emerald-400 hover:bg-slate-900' : 'text-slate-400 hover:text-emerald-600 hover:bg-emerald-50'}`}
                    title={t('uploadImage')}
                >
                    <ImageIcon size={20} />
                </button>

                {/* Scan Button (Explicitly Requested) */}
                <input type="file" ref={analyzeInputRef} className="hidden" accept="image/*" onChange={handleAnalyzeUpload} />
                <button 
                    onClick={() => analyzeInputRef.current?.click()}
                    className={`p-2 rounded-lg transition-colors
                        ${theme === 'dark' ? 'text-emerald-500 hover:text-emerald-400 hover:bg-slate-900' : 'text-emerald-600 hover:text-emerald-700 hover:bg-emerald-50'}`}
                    title="Scan Resin/Defects"
                >
                    <ScanEye size={20} />
                </button>

                <textarea
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => {
                        if (e.key === 'Enter' && !e.shiftKey) {
                            e.preventDefault();
                            handleSend();
                        }
                    }}
                    placeholder={attachedImage ? t('imageContext') : t('aiPlaceholder')}
                    className={`flex-1 max-h-32 bg-transparent border-none focus:ring-0 text-sm py-2 px-1 resize-none placeholder:text-slate-400
                         ${theme === 'dark' ? 'text-slate-200' : 'text-slate-800'}`}
                    rows={1}
                />

                {/* Send Button */}
                <button 
                    onClick={() => handleSend()}
                    disabled={(!input.trim() && !attachedImage) || isLoading}
                    className={`p-2 rounded-lg transition-all shadow-sm disabled:opacity-50 disabled:cursor-not-allowed
                         ${theme === 'dark' 
                           ? 'bg-emerald-600 hover:bg-emerald-500 text-white' 
                           : 'bg-emerald-600 hover:bg-emerald-700 text-white'}`}
                >
                    <Send size={18} />
                </button>
             </div>
          </div>
        </div>
      )}
    </>
  );
};

