                          <span className="w-1 h-1 bg-slate-400 rounded-full animate-bounce" style={{animationDelay: '0ms'}}></span>
                          <span className="w-1 h-1 bg-slate-400 rounded-full animate-bounce" style={{animationDelay: '150ms'}}></span>
                          <span className="w-1 h-1 bg-slate-400 rounded-full animate-bounce" style={{animationDelay: '300ms'}}></span>
                       </span>
                   </div>
               </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input Area */}
          <div className={`p-3 border-t ${theme === 'dark' ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'}`}>
             {attachedImage && (
                 <div className="mb-2 relative inline-block animate-in zoom-in duration-200">
                     <div className="relative group">
                        <img src={attachedImage} alt="Preview" className={`h-12 w-12 object-cover rounded-lg shadow-sm border ${theme === 'dark' ? 'border-slate-700' : 'border-slate-200'}`} />
                        <button 
                            onClick={() => setAttachedImage(null)}
                            className="absolute -top-1.5 -right-1.5 bg-slate-800 text-white rounded-full p-0.5 shadow-md opacity-0 group-hover:opacity-100 transition-opacity"
                        >
                            <X size={10} />
                        </button>
                     </div>
                 </div>
             )}

             <div className={`flex items-end gap-2 p-1.5 rounded-xl border transition-all
                  ${theme === 'dark' 
                    ? 'bg-slate-950 border-slate-800 focus-within:border-emerald-800 focus-within:ring-1 focus-within:ring-emerald-900/50' 
                    : 'bg-slate-50 border-slate-200 focus-within:border-emerald-300 focus-within:ring-2 focus-within:ring-emerald-100'}`}>

                {/* Image Upload */}
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
                <button 
                    onClick={() => fileInputRef.current?.click()}
                    className={`p-2 rounded-lg transition-colors
                        ${theme === 'dark' ? 'text-slate-500 hover:text-emerald-400 hover:bg-slate-900' : 'text-slate-400 hover:text-emerald-600 hover:bg-emerald-50'}`}
                    title={t('uploadImage')}
                >
                    <ImageIcon size={20} />
                </button>

                {/* Scan Button (Explicitly Requested) */}
                <input type="file" ref={analyzeInputRef} className="hidden" accept="image/*" onChange={handleAnalyzeUpload} />
                <button 
                    onClick={() => analyzeInputRef.current?.click()}
                    className={`p-2 rounded-lg transition-colors
                        ${theme === 'dark' ? 'text-emerald-500 hover:text-emerald-400 hover:bg-slate-900' : 'text-emerald-600 hover:text-emerald-700 hover:bg-emerald-50'}`}
                    title="Scan Resin/Defects"
                >
                    <ScanEye size={20} />
                </button>

                <textarea
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => {
                        if (e.key === 'Enter' && !e.shiftKey) {
                            e.preventDefault();
                            handleSend();
                        }
                    }}
                    placeholder={attachedImage ? t('imageContext') : t('aiPlaceholder')}
                    className={`flex-1 max-h-32 bg-transparent border-none focus:ring-0 text-sm py-2 px-1 resize-none placeholder:text-slate-400
                         ${theme === 'dark' ? 'text-slate-200' : 'text-slate-800'}`}
                    rows={1}
                />

                {/* Send Button */}
                <button 
                    onClick={() => handleSend()}
                    disabled={(!input.trim() && !attachedImage) || isLoading}
                    className={`p-2 rounded-lg transition-all shadow-sm disabled:opacity-50 disabled:cursor-not-allowed
                         ${theme === 'dark' 
                           ? 'bg-emerald-600 hover:bg-emerald-500 text-white' 
                           : 'bg-emerald-600 hover:bg-emerald-700 text-white'}`}
                >
                    <Send size={18} />
                </button>
             </div>
          </div>
        </div>
      )}
    </>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer,
  ScatterChart, Scatter, ZAxis, LabelList, Cell
} from 'recharts';
import { Product } from '../types';
import { 
  BarChart2, Activity, TrendingUp, FileJson, FileSpreadsheet, 
  Factory, Settings2, Palette, MoveVertical, Filter, Plus, Trash2, X
} from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';

interface DataVisualizerProps {
  data: Product[];
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16', '#6366f1'];

interface RangeFilter {
    id: string;
    key: string;
    min: string;
    max: string;
}

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [userXAxisKey, setUserXAxisKey] = useState<string>('');
  const [userYAxisKey, setUserYAxisKey] = useState<string>('');
  const [zAxisKey, setZAxisKey] = useState<string>('none');
  const [colorByKey, setColorByKey] = useState<string>('none');
  const [showTrendline, setShowTrendline] = useState<boolean>(false);
  const [showConfig, setShowConfig] = useState<boolean>(true);
  const [filters, setFilters] = useState<RangeFilter[]>([]);

  const { t, tProp } = useLanguage();
  const { theme } = useTheme();

  // Chart styling constants based on theme
  const chartStyles = useMemo(() => {
    const isDark = theme === 'dark';
    return {
        gridStroke: isDark ? '#334155' : '#e2e8f0', // slate-700 vs slate-200
        axisStroke: isDark ? '#94a3b8' : '#64748b', // slate-400 vs slate-500
        axisTextFill: isDark ? '#94a3b8' : '#64748b',
        tooltipBg: isDark ? '#0f172a' : '#ffffff', // slate-900 vs white
        tooltipBorder: isDark ? '#1e293b' : '#e2e8f0', // slate-800 vs slate-200
        tooltipText: isDark ? '#f8fafc' : '#1e293b', // slate-50 vs slate-800
        barFill: '#3b82f6'
    };
  }, [theme]);

  // 1. Extract Numeric Properties (for X, Y, Z axes)
  const numericProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        const num = Number(val.value);
        if (!isNaN(num) && val.value !== '' && val.value !== null) {
          props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // Filter Logic
  const addFilter = () => {
    if (numericProperties.length > 0) {
        setFilters([...filters, { id: Date.now().toString(), key: numericProperties[0], min: '', max: '' }]);
    }
  };

  const removeFilter = (id: string) => {
    setFilters(filters.filter(f => f.id !== id));
  };

  const updateFilter = (id: string, field: keyof RangeFilter, value: string) => {
    setFilters(filters.map(f => f.id === id ? { ...f, [field]: value } : f));
  };

  // Filtered Data
  const filteredData = useMemo(() => {
    if (filters.length === 0) return data;
    return data.filter(item => {
        return filters.every(f => {
             const valObj = item.properties[f.key];
             if (!valObj) return false;
             const val = Number(valObj.value);
             if (isNaN(val)) return false;

             const min = f.min === '' ? -Infinity : Number(f.min);
             const max = f.max === '' ? Infinity : Number(f.max);

             return val >= min && val <= max;
        });
    });
  }, [data, filters]);

  // 2. Extract Categorical Properties (for Coloring)
  const categoricalProperties = useMemo(() => {
    const props = new Set<string>(['manufacturer']); 
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (typeof val.value === 'string' && val.value.length < 20) {
            props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // 3. Helper to extract units
  const propertyUnits = useMemo(() => {
    const units: Record<string, string> = {};
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (v.unit && !units[k]) units[k] = v.unit;
        });
    });
    return units;
  }, [data]);

  // 4. Calculate Default/Active Keys synchronously
  const activeYKey = useMemo(() => {
    if (userYAxisKey && numericProperties.includes(userYAxisKey)) return userYAxisKey;
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    if (numericProperties.includes('密度')) return '密度';
    return numericProperties[0] || '';
  }, [userYAxisKey, numericProperties]);

  const activeXKey = useMemo(() => {
    if (userXAxisKey && numericProperties.includes(userXAxisKey)) return userXAxisKey;
    if (numericProperties.includes('密度')) return '密度';
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    return numericProperties.length > 1 ? numericProperties[1] : numericProperties[0] || '';
  }, [userXAxisKey, numericProperties]);

  // 5. Transform Data for Recharts
  const chartData = useMemo(() => {
    return filteredData.map(product => {
      const flattened: any = {
        name: product.gradeName,
        manufacturer: product.manufacturer,
        id: product.id
      };

      Object.entries(product.properties).forEach(([key, val]) => {
        const numVal = Number(val.value);
        if (!isNaN(numVal) && val.value !== '' && val.value !== null) {
          flattened[key] = numVal;
        } else {
          flattened[key] = val.value;
        }
      });
      return flattened;
    });
  }, [filteredData]);

  // 6. Group Data for Scatter Series
  const scatterGroups = useMemo(() => {
    if (chartType !== 'scatter' || colorByKey === 'none') return null;

    const groups: Record<string, any[]> = {};
    chartData.forEach(d => {
        const keyVal = d[colorByKey];
        const groupName = keyVal ? String(keyVal) : 'Unclassified';
        if (!groups[groupName]) groups[groupName] = [];
        groups[groupName].push(d);
    });
    return groups;
  }, [chartData, chartType, colorByKey]);

  // 7. Color Map
  const colorMap = useMemo(() => {
    if (colorByKey === 'none') return null;
    const uniqueValues = Array.from(new Set(chartData.map(d => String(d[colorByKey] || 'Unclassified'))));
    const map: Record<string, string> = {};
    uniqueValues.forEach((val, idx) => {
        map[val] = COLORS[idx % COLORS.length];
    });
    return map;
  }, [chartData, colorByKey]);

  // Trendline Logic
  const trendlineData = useMemo(() => {
    if (chartType !== 'scatter' || !showTrendline || chartData.length < 2) return [];

    let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0, count = 0;
    chartData.forEach((point) => {
        const x = point[activeXKey];
        const y = point[activeYKey];
        if (typeof x === 'number' && typeof y === 'number') {
            sumX += x; sumY += y; sumXY += x * y; sumXX += x * x; count++;
        }
    });

    if (count < 2) return [];
    const slope = (count * sumXY - sumX * sumY) / (count * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / count;
    const xValues = chartData.map(d => d[activeXKey]).filter(v => typeof v === 'number') as number[];
    if (xValues.length === 0) return [];
    const minX = Math.min(...xValues);
    const maxX = Math.max(...xValues);

    return [
        { [activeXKey]: minX, [activeYKey]: slope * minX + intercept },
        { [activeXKey]: maxX, [activeYKey]: slope * maxX + intercept }
    ];
  }, [chartData, activeXKey, activeYKey, showTrendline, chartType]);

  const handleExportJSON = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(chartData));
    const link = document.createElement('a');
    link.href = dataStr;
    link.download = "chart_data.json";
    link.click();
  };

  const handleExportCSV = () => {
    if (chartData.length === 0) return;
    const allKeys = Array.from(new Set(chartData.flatMap(Object.keys)));
    const header = allKeys.join(',');
    const rows = chartData.map(row => 
      allKeys.map(key => {
        const val = row[key];
        if (val === null || val === undefined) return '';
        const stringVal = String(val);
        if (stringVal.includes(',') || stringVal.includes('"') || stringVal.includes('\n')) {
          return `"${stringVal.replace(/"/g, '""')}"`;
        }
        return stringVal;
      }).join(',')
    );
    const csvContent = [header, ...rows].join('\n');
    const blob = new Blob(["\uFEFF" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'chart_data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const yAxisUnit = propertyUnits[activeYKey];
  const xAxisUnit = propertyUnits[activeXKey];
  const zAxisUnit = zAxisKey !== 'none' ? propertyUnits[zAxisKey] : '';
  const yAxisLabel = yAxisUnit ? `${tProp(activeYKey)} (${yAxisUnit})` : tProp(activeYKey);
  const xAxisLabel = xAxisUnit ? `${tProp(activeXKey)} (${xAxisUnit})` : tProp(activeXKey);

  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const pointData = payload[0].payload;

      // Calculate dynamic properties to display (excluding axes and non-numeric)
      // This ensures we show 'Ethylene Content' etc. if they exist for the record but aren't axes.
      const dynamicKeys = numericProperties.filter(key => 
        pointData[key] !== undefined && 
        pointData[key] !== null && 
        key !== activeXKey && 
        key !== activeYKey && 
        key !== zAxisKey
      ).sort();

      return (
        <div className="bg-white dark:bg-slate-900 p-3 border border-slate-200 dark:border-slate-800 shadow-xl rounded-lg text-sm min-w-[240px] z-50 transition-colors duration-200">
            <div className="mb-2">
                <p className="font-bold text-slate-800 dark:text-slate-100 text-base">{pointData.name}</p>
                <div className="flex items-center gap-1.5 text-xs text-slate-500 dark:text-slate-400 mt-0.5">
                    <Factory size={12} className="text-slate-400 dark:text-slate-500"/>
                    <span>{pointData.manufacturer}</span>
                </div>
            </div>
            <div className="border-t border-slate-100 dark:border-slate-800 pt-2 space-y-1.5">
                {chartType === 'scatter' && (
                    <div className="flex justify-between text-xs bg-slate-50 dark:bg-slate-800/50 p-1 rounded">
                        <span className="text-slate-500 dark:text-slate-400">{tProp(activeXKey)}:</span>
                        <span className="font-mono font-semibold text-blue-700 dark:text-blue-400">
                            {pointData[activeXKey]} <span className="text-[10px] text-slate-400 dark:text-slate-500">{xAxisUnit}</span>
                        </span>
                    </div>
                )}
                <div className="flex justify-between text-xs bg-slate-50 dark:bg-slate-800/50 p-1 rounded">
                    <span className="text-slate-500 dark:text-slate-400">{tProp(activeYKey)}:</span>
                    <span className="font-mono font-semibold text-blue-700 dark:text-blue-400">
                        {pointData[activeYKey]} <span className="text-[10px] text-slate-400 dark:text-slate-500">{yAxisUnit}</span>
                    </span>
                </div>
                 {zAxisKey !== 'none' && (
                    <div className="flex justify-between text-xs bg-slate-50 dark:bg-slate-800/50 p-1 rounded">
                        <span className="text-slate-500 dark:text-slate-400">{tProp(zAxisKey)}:</span>
                        <span className="font-mono font-semibold text-purple-700 dark:text-purple-400">
                            {pointData[zAxisKey]} <span className="text-[10px] text-slate-400 dark:text-slate-500">{zAxisUnit}</span>
                        </span>
                    </div>
                )}

                {/* Dynamic Extra Properties */}
                {dynamicKeys.map(key => (
                    <div key={key} className="flex justify-between text-xs bg-emerald-50/50 dark:bg-emerald-900/10 p-1 rounded border border-emerald-100/50 dark:border-emerald-800/20">
                        <span className="text-slate-500 dark:text-slate-400">{tProp(key)}:</span>
                        <span className="font-mono font-medium text-emerald-700 dark:text-emerald-400">
                            {pointData[key]} <span className="text-[10px] text-slate-400 dark:text-slate-500">{propertyUnits[key]}</span>
                        </span>
                    </div>
                ))}

                {colorByKey !== 'none' && (
                    <div className="flex justify-between text-xs mt-2 pt-2 border-t border-slate-100 dark:border-slate-800">
                        <span className="text-slate-500 dark:text-slate-400">{tProp(colorByKey)}:</span>
                        <span className="font-medium text-slate-800 dark:text-slate-200">{pointData[colorByKey]}</span>
                    </div>
                )}
            </div>
        </div>
      );
    }
    return null;
  };

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400 dark:text-slate-500 border border-slate-200 dark:border-slate-800 rounded-lg bg-white dark:bg-slate-900 transition-colors">
        <Activity size={48} className="mb-4 text-slate-300 dark:text-slate-600" />
        <p>{t('noProducts')}</p>
      </div>
    );
  }

  if (numericProperties.length === 0) {
     return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400 dark:text-slate-500 border border-slate-200 dark:border-slate-800 rounded-lg bg-white dark:bg-slate-900 transition-colors">
        <Activity size={48} className="mb-4 text-slate-300 dark:text-slate-600" />
        <p>{t('noNumericData')}</p>
      </div>
    );
  }

  return (
    <div className="bg-white dark:bg-slate-900 rounded-lg shadow-sm border border-slate-200 dark:border-slate-800 flex flex-col w-full transition-colors duration-300" style={{ minHeight: '600px', height: '600px' }}>

      {/* Configuration Header */}
      <div className="border-b border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-900/50 flex-shrink-0 transition-colors">
        <div className="p-3 px-4 flex items-center justify-between">
            <div className="flex items-center gap-2 text-slate-800 dark:text-slate-200 font-semibold">
                <Settings2 size={18} className="text-blue-600 dark:text-blue-400" />
                <span>{t('chartConfig')}</span>
            </div>
            <div className="flex gap-2">
                 <button 
                    onClick={() => setShowConfig(!showConfig)}
                    className="text-xs text-blue-600 dark:text-blue-400 hover:text-blue-700 dark:hover:text-blue-300 font-medium px-2 py-1 rounded hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors"
                >
                    {showConfig ? t('collapseConfig') : t('expandConfig')}
                </button>
                 <div className="h-4 w-px bg-slate-300 dark:bg-slate-700 self-center mx-1"></div>
                 <button onClick={handleExportJSON} className="text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200" title={t('exportJson')}><FileJson size={16}/></button>
                 <button onClick={handleExportCSV} className="text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200" title={t('exportCsv')}><FileSpreadsheet size={16}/></button>
            </div>
        </div>

        {showConfig && (
            <div className="p-4 pt-0 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 animate-in slide-in-from-top-2 duration-200">
                {/* 1. Chart Type */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center gap-1">
                        <Activity size={12}/> {t('chartType')}
                    </label>
                    <div className="flex bg-white dark:bg-slate-800 rounded-md border border-slate-200 dark:border-slate-700 p-1 transition-colors">
                        <button
                        onClick={() => setChartType('bar')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'bar' ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400 shadow-sm' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
                        }`}
                        >
                        <BarChart2 size={14} /> {t('barChart')}
                        </button>
                        <button
                        onClick={() => setChartType('scatter')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'scatter' ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400 shadow-sm' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
                        }`}
                        >
                        <Activity size={14} /> {t('scatterChart')}
                        </button>
                    </div>
                </div>

                {/* 2. Axes Configuration */}
                <div className="space-y-1.5 lg:col-span-2">
                    <label className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center gap-1">
                        <MoveVertical size={12}/> {t('axisMapping')}
                    </label>
                    <div className="flex gap-2">
                        {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={activeXKey} onChange={(e) => setUserXAxisKey(e.target.value)}
                                    className="w-full bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5 transition-colors"
                                >
                                    {numericProperties.map(p => <option key={p} value={p}>{t('xAxis')}: {tProp(p)}</option>)}
                                </select>
                             </div>
                        )}

                        <div className="flex-1 min-w-[120px]">
                            <select 
                                value={activeYKey} onChange={(e) => setUserYAxisKey(e.target.value)}
                                className="w-full bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5 transition-colors"
                            >
                                {numericProperties.map(p => <option key={p} value={p}>{chartType === 'bar' ? t('val') : t('yAxis')}: {tProp(p)}</option>)}
                            </select>
                        </div>

                         {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={zAxisKey} onChange={(e) => setZAxisKey(e.target.value)}
                                    className="w-full bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5 transition-colors"
                                >
                                    <option value="none">{t('zAxis')}: {t('noneAxis')}</option>
                                    {numericProperties.map(p => <option key={p} value={p}>{t('zAxis')}: {tProp(p)}</option>)}
                                </select>
                             </div>
                        )}
                    </div>
                </div>

                {/* 3. Style & Color */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center gap-1">
                        <Palette size={12}/> {t('styleGrouping')}
                    </label>
                    <div className="flex gap-2 items-center">
                         <select 
                            value={colorByKey} onChange={(e) => setColorByKey(e.target.value)}
                            className="flex-1 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5 transition-colors"
                        >
                            <option value="none">{t('colorSingle')}</option>
                            <optgroup label="Properties">
                                {categoricalProperties.map(p => <option key={p} value={p}>{t('groupBy').replace('{key}', tProp(p))}</option>)}
                            </optgroup>
                        </select>
                        {chartType === 'scatter' && (
                             <button
                                onClick={() => setShowTrendline(!showTrendline)}
                                title={t('trendline')}
                                className={`p-1.5 rounded border transition-colors ${showTrendline ? 'bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 border-indigo-200 dark:border-indigo-800' : 'bg-white dark:bg-slate-800 text-slate-400 dark:text-slate-500 border-slate-200 dark:border-slate-700'}`}
                             >
                                 <TrendingUp size={16} />
                             </button>
                        )}
                    </div>
                </div>

                {/* 4. Data Filters */}
                <div className="space-y-1.5 lg:col-span-4 border-t border-slate-200 dark:border-slate-800 pt-3 mt-1">
                    <div className="flex items-center justify-between">
                        <label className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center gap-1">
                            <Filter size={12}/> {t('dataFilters')}
                        </label>
                        <button 
                            onClick={addFilter}
                            className="flex items-center gap-1 text-[10px] font-medium text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/20 hover:bg-blue-100 dark:hover:bg-blue-900/40 px-2 py-1 rounded-md transition-colors"
                        >
                            <Plus size={12}/> {t('addFilter')}
                        </button>
                    </div>

                    {filters.length === 0 ? (
                        <p className="text-[10px] text-slate-400 dark:text-slate-600 italic pl-1">{t('noFilters')}</p>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2 mt-2">
                            {filters.map(filter => (
                                <div key={filter.id} className="flex items-center gap-2 bg-slate-50 dark:bg-slate-800/50 p-1.5 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm animate-in fade-in zoom-in-95 duration-200">
                                    <select 
                                        value={filter.key} 
                                        onChange={(e) => updateFilter(filter.id, 'key', e.target.value)}
                                        className="bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-600 text-slate-700 dark:text-slate-200 text-xs rounded py-1 pl-1 pr-6 flex-1 min-w-0 focus:ring-1 focus:ring-blue-500 focus:border-blue-500"
                                    >
                                        {numericProperties.map(p => <option key={p} value={p}>{tProp(p)}</option>)}
                                    </select>
                                    <div className="flex items-center gap-1 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-600 rounded px-1">
                                        <input 
                                            type="number" 
                                            placeholder={t('min')} 
                                            value={filter.min}
                                            onChange={(e) => updateFilter(filter.id, 'min', e.target.value)}
                                            className="w-12 text-xs border-none p-1 focus:ring-0 text-right placeholder:text-slate-300 dark:placeholder:text-slate-600 bg-transparent text-slate-700 dark:text-slate-200"
                                        />
                                        <span className="text-slate-300 dark:text-slate-600 text-[10px]">-</span>
                                        <input 
                                            type="number" 
                                            placeholder={t('max')} 
                                            value={filter.max}
                                            onChange={(e) => updateFilter(filter.id, 'max', e.target.value)}
                                            className="w-12 text-xs border-none p-1 focus:ring-0 text-right placeholder:text-slate-300 dark:placeholder:text-slate-600 bg-transparent text-slate-700 dark:text-slate-200"
                                        />
                                    </div>
                                    <button 
                                        onClick={() => removeFilter(filter.id)} 
                                        className="text-slate-400 dark:text-slate-500 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 p-1 rounded transition-colors"
                                    >
                                        <Trash2 size={12}/>
                                    </button>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        )}
      </div>

      {/* Chart Canvas */}
      <div className="flex-1 p-6 relative w-full h-full">
        {activeYKey && (
            <ResponsiveContainer width="100%" height="100%">
            {chartType === 'bar' ? (
                <BarChart
                data={chartData}
                margin={{ top: 20, right: 30, left: 20, bottom: 40 }}
                >
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={chartStyles.gridStroke} />
                <XAxis 
                    dataKey="name" 
                    stroke={chartStyles.axisStroke} 
                    fontSize={12} 
                    tickLine={false} 
                    axisLine={{ stroke: chartStyles.axisStroke }} 
                    interval={0} 
                    angle={-30} 
                    textAnchor="end" 
                    height={60} 
                />
                <YAxis 
                    stroke={chartStyles.axisStroke} 
                    fontSize={12} 
                    tickLine={false} 
                    axisLine={{ stroke: chartStyles.axisStroke }} 
                    domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { textAnchor: 'middle', fill: chartStyles.axisTextFill } }} 
                />
                <RechartsTooltip content={<CustomTooltip />} cursor={{ fill: theme === 'dark' ? '#1e293b' : '#f1f5f9' }} />
                <Legend wrapperStyle={{ color: chartStyles.axisTextFill }}/>
                <Bar 
                    dataKey={activeYKey} 
                    fill="#3b82f6" 
                    radius={[4, 4, 0, 0]} 
                    name={yAxisLabel} 
                    barSize={40}
                    isAnimationActive={false}
                >
                    {colorByKey !== 'none' && chartData.map((entry, index) => {
                        const val = String(entry[colorByKey] || 'Unclassified');
                        return <Cell key={`cell-${index}`} fill={colorMap?.[val] || '#3b82f6'} />;
                    })}
                    <LabelList dataKey={activeYKey} position="top" fill={chartStyles.axisTextFill} fontSize={12} formatter={(val: number) => val.toFixed(2)} />
                </Bar>
                </BarChart>
            ) : (
                <ScatterChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                <CartesianGrid strokeDasharray="3 3" stroke={chartStyles.gridStroke} />
                <XAxis 
                    type="number" dataKey={activeXKey} name={activeXKey} stroke={chartStyles.axisStroke} fontSize={12} domain={['auto', 'auto']}
                    label={{ value: xAxisLabel, position: 'bottom', offset: 0, style: { fill: chartStyles.axisTextFill } }} 
                />
                <YAxis 
                    type="number" dataKey={activeYKey} name={activeYKey} stroke={chartStyles.axisStroke} fontSize={12} domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { fill: chartStyles.axisTextFill } }} 
                />
                {zAxisKey !== 'none' && (
                    <ZAxis type="number" dataKey={zAxisKey} range={[60, 600]} name={zAxisKey} unit={zAxisUnit} />
                )}

                <RechartsTooltip content={<CustomTooltip />} cursor={{ strokeDasharray: '3 3' }} />
                <Legend wrapperStyle={{ color: chartStyles.axisTextFill }} />

                {colorByKey !== 'none' && scatterGroups ? (
                    Object.entries(scatterGroups).map(([groupName, groupData], index) => (
                        <Scatter 
                            key={groupName}
                            name={groupName}
                            data={groupData}
                            fill={COLORS[index % COLORS.length]}
                            isAnimationActive={false}
                        />
                    ))
                ) : (
                    <Scatter name={t('chartTitle')} data={chartData} fill="#3b82f6" isAnimationActive={false} />
                )}

                {showTrendline && trendlineData.length > 0 && (
                    <Scatter name={t('trendline')} data={trendlineData} line={{ stroke: '#ef4444', strokeWidth: 2, strokeDasharray: '5 5' }} shape={() => null} legendType="none" tooltipType="none" isAnimationActive={false}/>
                )}
                </ScatterChart>
            )}
            </ResponsiveContainer>
        )}

        {chartType === 'bar' && colorByKey !== 'none' && colorMap && (
             <div className="absolute top-4 right-6 bg-white/90 dark:bg-slate-800/90 p-2 rounded border border-slate-200 dark:border-slate-700 text-xs shadow-sm max-w-[150px] transition-colors">
                 <p className="font-semibold text-slate-500 dark:text-slate-400 mb-1 border-b border-slate-100 dark:border-slate-700 pb-1">{t('groupBy').replace('{key}', tProp(colorByKey))}</p>
                 <div className="space-y-1 max-h-[100px] overflow-y-auto custom-scrollbar">
                     {Object.entries(colorMap).map(([label, color]) => (
                         <div key={label} className="flex items-center gap-2">
                             <div className="w-2 h-2 rounded-full" style={{ backgroundColor: color }}></div>
                             <span className="truncate text-slate-600 dark:text-slate-300" title={label}>{label}</span>
                         </div>
                     ))}
                 </div>
             </div>
        )}
      </div>

      <div className="px-6 py-2 bg-slate-50 dark:bg-slate-900 border-t border-slate-200 dark:border-slate-800 text-[10px] text-slate-400 dark:text-slate-500 flex justify-between flex-shrink-0 rounded-b-lg transition-colors">
         <span>ResinDB Visualization Engine v1.3</span>
         {filters.length > 0 && <span>Filtered: {filteredData.length} records</span>}
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer,
  ScatterChart, Scatter, ZAxis, LabelList, Cell
} from 'recharts';
import { Product } from '../types';
import { 
  BarChart2, Activity, TrendingUp, FileJson, FileSpreadsheet, ImageDown,
  Factory, Settings2, Palette, MoveVertical, Filter, Plus, Trash2, X
} from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16', '#6366f1'];

interface RangeFilter {
    id: string;
    key: string;
    min: string;
    max: string;
}

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [userXAxisKey, setUserXAxisKey] = useState<string>('');
  const [userYAxisKey, setUserYAxisKey] = useState<string>('');
  const [zAxisKey, setZAxisKey] = useState<string>('none');
  const [colorByKey, setColorByKey] = useState<string>('none');
  const [showTrendline, setShowTrendline] = useState<boolean>(false);
  const [showConfig, setShowConfig] = useState<boolean>(true);
  const [filters, setFilters] = useState<RangeFilter[]>([]);

  const chartContainerRef = useRef<HTMLDivElement>(null);

  const { t, tProp } = useLanguage();
  const { theme } = useTheme();

  // Chart styling constants based on theme
  const chartStyles = useMemo(() => {
    const isDark = theme === 'dark';
    return {
        gridStroke: isDark ? '#334155' : '#e2e8f0', // slate-700 vs slate-200
        axisStroke: isDark ? '#94a3b8' : '#64748b', // slate-400 vs slate-500
        axisTextFill: isDark ? '#94a3b8' : '#64748b',
        tooltipBg: isDark ? '#0f172a' : '#ffffff', // slate-900 vs white
        tooltipBorder: isDark ? '#1e293b' : '#e2e8f0', // slate-800 vs slate-200
        tooltipText: isDark ? '#f8fafc' : '#1e293b', // slate-50 vs slate-800
        barFill: '#3b82f6'
    };
  }, [theme]);

  // 1. Extract Numeric Properties (for X, Y, Z axes)
  const numericProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        const num = Number(val.value);
        if (!isNaN(num) && val.value !== '' && val.value !== null) {
          props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // Filter Logic
  const addFilter = () => {
    if (numericProperties.length > 0) {
        setFilters([...filters, { id: Date.now().toString(), key: numericProperties[0], min: '', max: '' }]);
    }
  };

  const removeFilter = (id: string) => {
    setFilters(filters.filter(f => f.id !== id));
  };

  const updateFilter = (id: string, field: keyof RangeFilter, value: string) => {
    setFilters(filters.map(f => f.id === id ? { ...f, [field]: value } : f));
  };

  // Filtered Data
  const filteredData = useMemo(() => {
    if (filters.length === 0) return data;
    return data.filter(item => {
        return filters.every(f => {
             const valObj = item.properties[f.key];
             if (!valObj) return false;
             const val = Number(valObj.value);
             if (isNaN(val)) return false;

             const min = f.min === '' ? -Infinity : Number(f.min);
             const max = f.max === '' ? Infinity : Number(f.max);

             return val >= min && val <= max;
        });
    });
  }, [data, filters]);

  // 2. Extract Categorical Properties (for Coloring)
  const categoricalProperties = useMemo(() => {
    const props = new Set<string>(['manufacturer']); 
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (typeof val.value === 'string' && val.value.length < 20) {
            props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // 3. Helper to extract units
  const propertyUnits = useMemo(() => {
    const units: Record<string, string> = {};
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (v.unit && !units[k]) units[k] = v.unit;
        });
    });
    return units;
  }, [data]);

  // 4. Calculate Default/Active Keys synchronously
  const activeYKey = useMemo(() => {
    if (userYAxisKey && numericProperties.includes(userYAxisKey)) return userYAxisKey;
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    if (numericProperties.includes('密度')) return '密度';
    return numericProperties[0] || '';
  }, [userYAxisKey, numericProperties]);

  const activeXKey = useMemo(() => {
    if (userXAxisKey && numericProperties.includes(userXAxisKey)) return userXAxisKey;
    if (numericProperties.includes('密度')) return '密度';
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    return numericProperties.length > 1 ? numericProperties[1] : numericProperties[0] || '';
  }, [userXAxisKey, numericProperties]);

  // 5. Transform Data for Recharts
  const chartData = useMemo(() => {
    return filteredData.map(product => {
      const flattened: any = {
        name: product.gradeName,
        manufacturer: product.manufacturer,
        id: product.id
      };

      Object.entries(product.properties).forEach(([key, val]) => {
        const numVal = Number(val.value);
        if (!isNaN(numVal) && val.value !== '' && val.value !== null) {
          flattened[key] = numVal;
        } else {
          flattened[key] = val.value;
        }
      });
      return flattened;
    });
  }, [filteredData]);

  // 6. Group Data for Scatter Series
  const scatterGroups = useMemo(() => {
    if (chartType !== 'scatter' || colorByKey === 'none') return null;

    const groups: Record<string, any[]> = {};
    chartData.forEach(d => {
        const keyVal = d[colorByKey];
        const groupName = keyVal ? String(keyVal) : 'Unclassified';
        if (!groups[groupName]) groups[groupName] = [];
        groups[groupName].push(d);
    });
    return groups;
  }, [chartData, chartType, colorByKey]);

  // 7. Color Map
  const colorMap = useMemo(() => {
    if (colorByKey === 'none') return null;
    const uniqueValues = Array.from(new Set(chartData.map(d => String(d[colorByKey] || 'Unclassified'))));
    const map: Record<string, string> = {};
    uniqueValues.forEach((val, idx) => {
        map[val] = COLORS[idx % COLORS.length];
    });
    return map;
  }, [chartData, colorByKey]);

  // Trendline Logic
  const trendlineData = useMemo(() => {
    if (chartType !== 'scatter' || !showTrendline || chartData.length < 2) return [];

    let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0, count = 0;
    chartData.forEach((point) => {
        const x = point[activeXKey];
        const y = point[activeYKey];
        if (typeof x === 'number' && typeof y === 'number') {
            sumX += x; sumY += y; sumXY += x * y; sumXX += x * x; count++;
        }
    });

    if (count < 2) return [];
    const slope = (count * sumXY - sumX * sumY) / (count * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / count;
    const xValues = chartData.map(d => d[activeXKey]).filter(v => typeof v === 'number') as number[];
    if (xValues.length === 0) return [];
    const minX = Math.min(...xValues);
    const maxX = Math.max(...xValues);

    return [
        { [activeXKey]: minX, [activeYKey]: slope * minX + intercept },
        { [activeXKey]: maxX, [activeYKey]: slope * maxX + intercept }
    ];
  }, [chartData, activeXKey, activeYKey, showTrendline, chartType]);

  const handleExportJSON = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(chartData));
    const link = document.createElement('a');
    link.href = dataStr;
    link.download = "chart_data.json";
    link.click();
  };

  const handleExportCSV = () => {
    if (chartData.length === 0) return;
    const allKeys = Array.from(new Set(chartData.flatMap(Object.keys)));
    const header = allKeys.join(',');
    const rows = chartData.map(row => 
      allKeys.map(key => {
        const val = row[key];
        if (val === null || val === undefined) return '';
        const stringVal = String(val);
        if (stringVal.includes(',') || stringVal.includes('"') || stringVal.includes('\n')) {
          return `"${stringVal.replace(/"/g, '""')}"`;
        }
        return stringVal;
      }).join(',')
    );
    const csvContent = [header, ...rows].join('\n');
    const blob = new Blob(["\uFEFF" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'chart_data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleExportPNG = async () => {
    if (!chartContainerRef.current) return;
    try {
        const canvas = await html2canvas(chartContainerRef.current, {
            scale: 2, // High resolution
            backgroundColor: theme === 'dark' ? '#0f172a' : '#ffffff', // slate-900 or white
            logging: false,
            useCORS: true
        });
        const link = document.createElement('a');
        link.download = `chart_${Date.now()}.png`;
        link.href = canvas.toDataURL('image/png');
        link.click();
    } catch (err) {
        console.error("Export failed", err);
    }
  };

  const yAxisUnit = propertyUnits[activeYKey];
  const xAxisUnit = propertyUnits[activeXKey];
  const zAxisUnit = zAxisKey !== 'none' ? propertyUnits[zAxisKey] : '';
  const yAxisLabel = yAxisUnit ? `${tProp(activeYKey)} (${yAxisUnit})` : tProp(activeYKey);
  const xAxisLabel = xAxisUnit ? `${tProp(activeXKey)} (${xAxisUnit})` : tProp(activeXKey);

  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const pointData = payload[0].payload;

      // Calculate dynamic properties to display (excluding axes and non-numeric)
      // This ensures we show 'Ethylene Content' etc. if they exist for the record but aren't axes.
      const dynamicKeys = numericProperties.filter(key => 
        pointData[key] !== undefined && 
        pointData[key] !== null && 
        key !== activeXKey && 
        key !== activeYKey && 
        key !== zAxisKey
      ).sort();

      return (
        <div className="bg-white dark:bg-slate-900 p-3 border border-slate-200 dark:border-slate-800 shadow-xl rounded-lg text-sm min-w-[240px] z-50 transition-colors duration-200">
            <div className="mb-2">
                <p className="font-bold text-slate-800 dark:text-slate-100 text-base">{pointData.name}</p>
                <div className="flex items-center gap-1.5 text-xs text-slate-500 dark:text-slate-400 mt-0.5">
                    <Factory size={12} className="text-slate-400 dark:text-slate-500"/>
                    <span>{pointData.manufacturer}</span>
                </div>
            </div>
            <div className="border-t border-slate-100 dark:border-slate-800 pt-2 space-y-1.5">
                {chartType === 'scatter' && (
                    <div className="flex justify-between text-xs bg-slate-50 dark:bg-slate-800/50 p-1 rounded">
                        <span className="text-slate-500 dark:text-slate-400">{tProp(activeXKey)}:</span>
                        <span className="font-mono font-semibold text-blue-700 dark:text-blue-400">
                            {pointData[activeXKey]} <span className="text-[10px] text-slate-400 dark:text-slate-500">{xAxisUnit}</span>
                        </span>
                    </div>
                )}
                <div className="flex justify-between text-xs bg-slate-50 dark:bg-slate-800/50 p-1 rounded">
                    <span className="text-slate-500 dark:text-slate-400">{tProp(activeYKey)}:</span>
                    <span className="font-mono font-semibold text-blue-700 dark:text-blue-400">
                        {pointData[activeYKey]} <span className="text-[10px] text-slate-400 dark:text-slate-500">{yAxisUnit}</span>
                    </span>
                </div>
                 {zAxisKey !== 'none' && (
                    <div className="flex justify-between text-xs bg-slate-50 dark:bg-slate-800/50 p-1 rounded">
                        <span className="text-slate-500 dark:text-slate-400">{tProp(zAxisKey)}:</span>
                        <span className="font-mono font-semibold text-purple-700 dark:text-purple-400">
                            {pointData[zAxisKey]} <span className="text-[10px] text-slate-400 dark:text-slate-500">{zAxisUnit}</span>
                        </span>
                    </div>
                )}

                {/* Dynamic Extra Properties */}
                {dynamicKeys.map(key => (
                    <div key={key} className="flex justify-between text-xs bg-emerald-50/50 dark:bg-emerald-900/10 p-1 rounded border border-emerald-100/50 dark:border-emerald-800/20">
                        <span className="text-slate-500 dark:text-slate-400">{tProp(key)}:</span>
                        <span className="font-mono font-medium text-emerald-700 dark:text-emerald-400">
                            {pointData[key]} <span className="text-[10px] text-slate-400 dark:text-slate-500">{propertyUnits[key]}</span>
                        </span>
                    </div>
                ))}

                {colorByKey !== 'none' && (
                    <div className="flex justify-between text-xs mt-2 pt-2 border-t border-slate-100 dark:border-slate-800">
                        <span className="text-slate-500 dark:text-slate-400">{tProp(colorByKey)}:</span>
                        <span className="font-medium text-slate-800 dark:text-slate-200">{pointData[colorByKey]}</span>
                    </div>
                )}
            </div>
        </div>
      );
    }
    return null;
  };

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400 dark:text-slate-500 border border-slate-200 dark:border-slate-800 rounded-lg bg-white dark:bg-slate-900 transition-colors">
        <Activity size={48} className="mb-4 text-slate-300 dark:text-slate-600" />
        <p>{t('noProducts')}</p>
      </div>
    );
  }

  if (numericProperties.length === 0) {
     return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400 dark:text-slate-500 border border-slate-200 dark:border-slate-800 rounded-lg bg-white dark:bg-slate-900 transition-colors">
        <Activity size={48} className="mb-4 text-slate-300 dark:text-slate-600" />
        <p>{t('noNumericData')}</p>
      </div>
    );
  }

  return (
    <div className="bg-white dark:bg-slate-900 rounded-lg shadow-sm border border-slate-200 dark:border-slate-800 flex flex-col w-full transition-colors duration-300" style={{ minHeight: '600px', height: '600px' }}>

      {/* Configuration Header */}
      <div className="border-b border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-900/50 flex-shrink-0 transition-colors">
        <div className="p-3 px-4 flex items-center justify-between">
            <div className="flex items-center gap-2 text-slate-800 dark:text-slate-200 font-semibold">
                <Settings2 size={18} className="text-blue-600 dark:text-blue-400" />
                <span>{t('chartConfig')}</span>
            </div>
            <div className="flex gap-2">
                 <button 
                    onClick={() => setShowConfig(!showConfig)}
                    className="text-xs text-blue-600 dark:text-blue-400 hover:text-blue-700 dark:hover:text-blue-300 font-medium px-2 py-1 rounded hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors"
                >
                    {showConfig ? t('collapseConfig') : t('expandConfig')}
                </button>
                 <div className="h-4 w-px bg-slate-300 dark:bg-slate-700 self-center mx-1"></div>
                 <button onClick={handleExportJSON} className="text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200" title={t('exportJson')}><FileJson size={16}/></button>
                 <button onClick={handleExportCSV} className="text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200" title={t('exportCsv')}><FileSpreadsheet size={16}/></button>
                 <button onClick={handleExportPNG} className="text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200" title={t('exportPng')}><ImageDown size={16}/></button>
            </div>
        </div>

        {showConfig && (
            <div className="p-4 pt-0 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 animate-in slide-in-from-top-2 duration-200">
                {/* 1. Chart Type */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center gap-1">
                        <Activity size={12}/> {t('chartType')}
                    </label>
                    <div className="flex bg-white dark:bg-slate-800 rounded-md border border-slate-200 dark:border-slate-700 p-1 transition-colors">
                        <button
                        onClick={() => setChartType('bar')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'bar' ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400 shadow-sm' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
                        }`}
                        >
                        <BarChart2 size={14} /> {t('barChart')}
                        </button>
                        <button
                        onClick={() => setChartType('scatter')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'scatter' ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400 shadow-sm' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
                        }`}
                        >
                        <Activity size={14} /> {t('scatterChart')}
                        </button>
                    </div>
                </div>

                {/* 2. Axes Configuration */}
                <div className="space-y-1.5 lg:col-span-2">
                    <label className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center gap-1">
                        <MoveVertical size={12}/> {t('axisMapping')}
                    </label>
                    <div className="flex gap-2">
                        {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={activeXKey} onChange={(e) => setUserXAxisKey(e.target.value)}
                                    className="w-full bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5 transition-colors"
                                >
                                    {numericProperties.map(p => <option key={p} value={p}>{t('xAxis')}: {tProp(p)}</option>)}
                                </select>
                             </div>
                        )}

                        <div className="flex-1 min-w-[120px]">
                            <select 
                                value={activeYKey} onChange={(e) => setUserYAxisKey(e.target.value)}
                                className="w-full bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5 transition-colors"
                            >
                                {numericProperties.map(p => <option key={p} value={p}>{chartType === 'bar' ? t('val') : t('yAxis')}: {tProp(p)}</option>)}
                            </select>
                        </div>

                         {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={zAxisKey} onChange={(e) => setZAxisKey(e.target.value)}
                                    className="w-full bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5 transition-colors"
                                >
                                    <option value="none">{t('zAxis')}: {t('noneAxis')}</option>
                                    {numericProperties.map(p => <option key={p} value={p}>{t('zAxis')}: {tProp(p)}</option>)}
                                </select>
                             </div>
                        )}
                    </div>
                </div>

                {/* 3. Style & Color */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center gap-1">
                        <Palette size={12}/> {t('styleGrouping')}
                    </label>
                    <div className="flex gap-2 items-center">
                         <select 
                            value={colorByKey} onChange={(e) => setColorByKey(e.target.value)}
                            className="flex-1 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5 transition-colors"
                        >
                            <option value="none">{t('colorSingle')}</option>
                            <optgroup label="Properties">
                                {categoricalProperties.map(p => <option key={p} value={p}>{t('groupBy').replace('{key}', tProp(p))}</option>)}
                            </optgroup>
                        </select>
                        {chartType === 'scatter' && (
                             <button
                                onClick={() => setShowTrendline(!showTrendline)}
                                title={t('trendline')}
                                className={`p-1.5 rounded border transition-colors ${showTrendline ? 'bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 border-indigo-200 dark:border-indigo-800' : 'bg-white dark:bg-slate-800 text-slate-400 dark:text-slate-500 border-slate-200 dark:border-slate-700'}`}
                             >
                                 <TrendingUp size={16} />
                             </button>
                        )}
                    </div>
                </div>

                {/* 4. Data Filters */}
                <div className="space-y-1.5 lg:col-span-4 border-t border-slate-200 dark:border-slate-800 pt-3 mt-1">
                    <div className="flex items-center justify-between">
                        <label className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center gap-1">
                            <Filter size={12}/> {t('dataFilters')}
                        </label>
                        <button 
                            onClick={addFilter}
                            className="flex items-center gap-1 text-[10px] font-medium text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/20 hover:bg-blue-100 dark:hover:bg-blue-900/40 px-2 py-1 rounded-md transition-colors"
                        >
                            <Plus size={12}/> {t('addFilter')}
                        </button>
                    </div>

                    {filters.length === 0 ? (
                        <p className="text-[10px] text-slate-400 dark:text-slate-600 italic pl-1">{t('noFilters')}</p>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2 mt-2">
                            {filters.map(filter => (
                                <div key={filter.id} className="flex items-center gap-2 bg-slate-50 dark:bg-slate-800/50 p-1.5 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm animate-in fade-in zoom-in-95 duration-200">
                                    <select 
                                        value={filter.key} 
                                        onChange={(e) => updateFilter(filter.id, 'key', e.target.value)}
                                        className="bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-600 text-slate-700 dark:text-slate-200 text-xs rounded py-1 pl-1 pr-6 flex-1 min-w-0 focus:ring-1 focus:ring-blue-500 focus:border-blue-500"
                                    >
                                        {numericProperties.map(p => <option key={p} value={p}>{tProp(p)}</option>)}
                                    </select>
                                    <div className="flex items-center gap-1 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-600 rounded px-1">
                                        <input 
                                            type="number" 
                                            placeholder={t('min')} 
                                            value={filter.min}
                                            onChange={(e) => updateFilter(filter.id, 'min', e.target.value)}
                                            className="w-12 text-xs border-none p-1 focus:ring-0 text-right placeholder:text-slate-300 dark:placeholder:text-slate-600 bg-transparent text-slate-700 dark:text-slate-200"
                                        />
                                        <span className="text-slate-300 dark:text-slate-600 text-[10px]">-</span>
                                        <input 
                                            type="number" 
                                            placeholder={t('max')} 
                                            value={filter.max}
                                            onChange={(e) => updateFilter(filter.id, 'max', e.target.value)}
                                            className="w-12 text-xs border-none p-1 focus:ring-0 text-right placeholder:text-slate-300 dark:placeholder:text-slate-600 bg-transparent text-slate-700 dark:text-slate-200"
                                        />
                                    </div>
                                    <button 
                                        onClick={() => removeFilter(filter.id)} 
                                        className="text-slate-400 dark:text-slate-500 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 p-1 rounded transition-colors"
                                    >
                                        <Trash2 size={12}/>
                                    </button>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        )}
      </div>

      {/* Chart Canvas */}
      <div ref={chartContainerRef} className="flex-1 p-6 relative w-full h-full bg-white dark:bg-slate-900 transition-colors">
        {activeYKey && (
            <ResponsiveContainer width="100%" height="100%">
            {chartType === 'bar' ? (
                <BarChart
                data={chartData}
                margin={{ top: 20, right: 30, left: 20, bottom: 40 }}
                >
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={chartStyles.gridStroke} />
                <XAxis 
                    dataKey="name" 
                    stroke={chartStyles.axisStroke} 
                    fontSize={12} 
                    tickLine={false} 
                    axisLine={{ stroke: chartStyles.axisStroke }} 
                    interval={0} 
                    angle={-30} 
                    textAnchor="end" 
                    height={60} 
                />
                <YAxis 
                    stroke={chartStyles.axisStroke} 
                    fontSize={12} 
                    tickLine={false} 
                    axisLine={{ stroke: chartStyles.axisStroke }} 
                    domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { textAnchor: 'middle', fill: chartStyles.axisTextFill } }} 
                />
                <RechartsTooltip content={<CustomTooltip />} cursor={{ fill: theme === 'dark' ? '#1e293b' : '#f1f5f9' }} />
                <Legend wrapperStyle={{ color: chartStyles.axisTextFill }}/>
                <Bar 
                    dataKey={activeYKey} 
                    fill="#3b82f6" 
                    radius={[4, 4, 0, 0]} 
                    name={yAxisLabel} 
                    barSize={40}
                    isAnimationActive={false}
                >
                    {colorByKey !== 'none' && chartData.map((entry, index) => {
                        const val = String(entry[colorByKey] || 'Unclassified');
                        return <Cell key={`cell-${index}`} fill={colorMap?.[val] || '#3b82f6'} />;
                    })}
                    <LabelList dataKey={activeYKey} position="top" fill={chartStyles.axisTextFill} fontSize={12} formatter={(val: number) => val.toFixed(2)} />
                </Bar>
                </BarChart>
            ) : (
                <ScatterChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                <CartesianGrid strokeDasharray="3 3" stroke={chartStyles.gridStroke} />
                <XAxis 
                    type="number" dataKey={activeXKey} name={activeXKey} stroke={chartStyles.axisStroke} fontSize={12} domain={['auto', 'auto']}
                    label={{ value: xAxisLabel, position: 'bottom', offset: 0, style: { fill: chartStyles.axisTextFill } }} 
                />
                <YAxis 
                    type="number" dataKey={activeYKey} name={activeYKey} stroke={chartStyles.axisStroke} fontSize={12} domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { fill: chartStyles.axisTextFill } }} 
                />
                {zAxisKey !== 'none' && (
                    <ZAxis type="number" dataKey={zAxisKey} range={[60, 600]} name={zAxisKey} unit={zAxisUnit} />
                )}

                <RechartsTooltip content={<CustomTooltip />} cursor={{ strokeDasharray: '3 3' }} />
                <Legend wrapperStyle={{ color: chartStyles.axisTextFill }} />

                {colorByKey !== 'none' && scatterGroups ? (
                    Object.entries(scatterGroups).map(([groupName, groupData], index) => (
                        <Scatter 
                            key={groupName}
                            name={groupName}
                            data={groupData}
                            fill={COLORS[index % COLORS.length]}
                            isAnimationActive={false}
                        />
                    ))
                ) : (
                    <Scatter name={t('chartTitle')} data={chartData} fill="#3b82f6" isAnimationActive={false} />
                )}

                {showTrendline && trendlineData.length > 0 && (
                    <Scatter name={t('trendline')} data={trendlineData} line={{ stroke: '#ef4444', strokeWidth: 2, strokeDasharray: '5 5' }} shape={() => null} legendType="none" tooltipType="none" isAnimationActive={false}/>
                )}
                </ScatterChart>
            )}
            </ResponsiveContainer>
        )}

        {chartType === 'bar' && colorByKey !== 'none' && colorMap && (
             <div className="absolute top-4 right-6 bg-white/90 dark:bg-slate-800/90 p-2 rounded border border-slate-200 dark:border-slate-700 text-xs shadow-sm max-w-[150px] transition-colors">
                 <p className="font-semibold text-slate-500 dark:text-slate-400 mb-1 border-b border-slate-100 dark:border-slate-700 pb-1">{t('groupBy').replace('{key}', tProp(colorByKey))}</p>
                 <div className="space-y-1 max-h-[100px] overflow-y-auto custom-scrollbar">
                     {Object.entries(colorMap).map(([label, color]) => (
                         <div key={label} className="flex items-center gap-2">
                             <div className="w-2 h-2 rounded-full" style={{ backgroundColor: color }}></div>
                             <span className="truncate text-slate-600 dark:text-slate-300" title={label}>{label}</span>
                         </div>
                     ))}
                 </div>
             </div>
        )}
      </div>

      <div className="px-6 py-2 bg-slate-50 dark:bg-slate-900 border-t border-slate-200 dark:border-slate-800 text-[10px] text-slate-400 dark:text-slate-500 flex justify-between flex-shrink-0 rounded-b-lg transition-colors">
         <span>ResinDB Visualization Engine v1.3</span>
         {filters.length > 0 && <span>Filtered: {filteredData.length} records</span>}
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer,
  ScatterChart, Scatter, ZAxis, LabelList, Cell
} from 'recharts';
import { Product } from '../types';
import { 
  BarChart2, Activity, TrendingUp, FileJson, FileSpreadsheet, ImageDown,
  Factory, Settings2, Palette, MoveVertical, Filter, Plus, Trash2, X, ChevronDown, ArrowRight
} from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16', '#6366f1'];

interface RangeFilter {
    id: string;
    key: string;
    min: string;
    max: string;
}

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [userXAxisKey, setUserXAxisKey] = useState<string>('');
  const [userYAxisKey, setUserYAxisKey] = useState<string>('');
  const [zAxisKey, setZAxisKey] = useState<string>('none');
  const [colorByKey, setColorByKey] = useState<string>('none');
  const [showTrendline, setShowTrendline] = useState<boolean>(false);
  const [showConfig, setShowConfig] = useState<boolean>(true);
  const [filters, setFilters] = useState<RangeFilter[]>([]);

  const chartContainerRef = useRef<HTMLDivElement>(null);

  const { t, tProp } = useLanguage();
  const { theme } = useTheme();

  // Chart styling constants based on theme
  const chartStyles = useMemo(() => {
    const isDark = theme === 'dark';
    return {
        gridStroke: isDark ? '#334155' : '#e2e8f0', // slate-700 vs slate-200
        axisStroke: isDark ? '#94a3b8' : '#64748b', // slate-400 vs slate-500
        axisTextFill: isDark ? '#94a3b8' : '#64748b',
        tooltipBg: isDark ? '#0f172a' : '#ffffff', // slate-900 vs white
        tooltipBorder: isDark ? '#1e293b' : '#e2e8f0', // slate-800 vs slate-200
        tooltipText: isDark ? '#f8fafc' : '#1e293b', // slate-50 vs slate-800
        barFill: '#3b82f6'
    };
  }, [theme]);

  // 1. Extract Numeric Properties (for X, Y, Z axes)
  const numericProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        const num = Number(val.value);
        if (!isNaN(num) && val.value !== '' && val.value !== null) {
          props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // Filter Logic
  const addFilter = () => {
    if (numericProperties.length > 0) {
        setFilters([...filters, { id: Date.now().toString(), key: numericProperties[0], min: '', max: '' }]);
    }
  };

  const removeFilter = (id: string) => {
    setFilters(filters.filter(f => f.id !== id));
  };

  const updateFilter = (id: string, field: keyof RangeFilter, value: string) => {
    setFilters(filters.map(f => f.id === id ? { ...f, [field]: value } : f));
  };

  // Filtered Data
  const filteredData = useMemo(() => {
    if (filters.length === 0) return data;
    return data.filter(item => {
        return filters.every(f => {
             const valObj = item.properties[f.key];
             if (!valObj) return false;
             const val = Number(valObj.value);
             if (isNaN(val)) return false;

             const min = f.min === '' ? -Infinity : Number(f.min);
             const max = f.max === '' ? Infinity : Number(f.max);

             return val >= min && val <= max;
        });
    });
  }, [data, filters]);

  // 2. Extract Categorical Properties (for Coloring)
  const categoricalProperties = useMemo(() => {
    const props = new Set<string>(['manufacturer']); 
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (typeof val.value === 'string' && val.value.length < 20) {
            props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // 3. Helper to extract units
  const propertyUnits = useMemo(() => {
    const units: Record<string, string> = {};
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (v.unit && !units[k]) units[k] = v.unit;
        });
    });
    return units;
  }, [data]);

  // 4. Calculate Default/Active Keys synchronously
  const activeYKey = useMemo(() => {
    if (userYAxisKey && numericProperties.includes(userYAxisKey)) return userYAxisKey;
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    if (numericProperties.includes('密度')) return '密度';
    return numericProperties[0] || '';
  }, [userYAxisKey, numericProperties]);

  const activeXKey = useMemo(() => {
    if (userXAxisKey && numericProperties.includes(userXAxisKey)) return userXAxisKey;
    if (numericProperties.includes('密度')) return '密度';
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    return numericProperties.length > 1 ? numericProperties[1] : numericProperties[0] || '';
  }, [userXAxisKey, numericProperties]);

  // 5. Transform Data for Recharts
  const chartData = useMemo(() => {
    return filteredData.map(product => {
      const flattened: any = {
        name: product.gradeName,
        manufacturer: product.manufacturer,
        id: product.id
      };

      Object.entries(product.properties).forEach(([key, val]) => {
        const numVal = Number(val.value);
        if (!isNaN(numVal) && val.value !== '' && val.value !== null) {
          flattened[key] = numVal;
        } else {
          flattened[key] = val.value;
        }
      });
      return flattened;
    });
  }, [filteredData]);

  // 6. Group Data for Scatter Series
  const scatterGroups = useMemo(() => {
    if (chartType !== 'scatter' || colorByKey === 'none') return null;

    const groups: Record<string, any[]> = {};
    chartData.forEach(d => {
        const keyVal = d[colorByKey];
        const groupName = keyVal ? String(keyVal) : 'Unclassified';
        if (!groups[groupName]) groups[groupName] = [];
        groups[groupName].push(d);
    });
    return groups;
  }, [chartData, chartType, colorByKey]);

  // 7. Color Map
  const colorMap = useMemo(() => {
    if (colorByKey === 'none') return null;
    const uniqueValues = Array.from(new Set(chartData.map(d => String(d[colorByKey] || 'Unclassified'))));
    const map: Record<string, string> = {};
    uniqueValues.forEach((val, idx) => {
        map[val] = COLORS[idx % COLORS.length];
    });
    return map;
  }, [chartData, colorByKey]);

  // Trendline Logic
  const trendlineData = useMemo(() => {
    if (chartType !== 'scatter' || !showTrendline || chartData.length < 2) return [];

    let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0, count = 0;
    chartData.forEach((point) => {
        const x = point[activeXKey];
        const y = point[activeYKey];
        if (typeof x === 'number' && typeof y === 'number') {
            sumX += x; sumY += y; sumXY += x * y; sumXX += x * x; count++;
        }
    });

    if (count < 2) return [];
    const slope = (count * sumXY - sumX * sumY) / (count * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / count;
    const xValues = chartData.map(d => d[activeXKey]).filter(v => typeof v === 'number') as number[];
    if (xValues.length === 0) return [];
    const minX = Math.min(...xValues);
    const maxX = Math.max(...xValues);

    return [
        { [activeXKey]: minX, [activeYKey]: slope * minX + intercept },
        { [activeXKey]: maxX, [activeYKey]: slope * maxX + intercept }
    ];
  }, [chartData, activeXKey, activeYKey, showTrendline, chartType]);

  const handleExportJSON = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(chartData));
    const link = document.createElement('a');
    link.href = dataStr;
    link.download = "chart_data.json";
    link.click();
  };

  const handleExportCSV = () => {
    if (chartData.length === 0) return;
    const allKeys = Array.from(new Set(chartData.flatMap(Object.keys)));
    const header = allKeys.join(',');
    const rows = chartData.map(row => 
      allKeys.map(key => {
        const val = row[key];
        if (val === null || val === undefined) return '';
        const stringVal = String(val);
        if (stringVal.includes(',') || stringVal.includes('"') || stringVal.includes('\n')) {
          return `"${stringVal.replace(/"/g, '""')}"`;
        }
        return stringVal;
      }).join(',')
    );
    const csvContent = [header, ...rows].join('\n');
    const blob = new Blob(["\uFEFF" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'chart_data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleExportPNG = async () => {
    if (!chartContainerRef.current) return;
    try {
        const canvas = await html2canvas(chartContainerRef.current, {
            scale: 2, // High resolution
            backgroundColor: theme === 'dark' ? '#0f172a' : '#ffffff', // slate-900 or white
            logging: false,
            useCORS: true
        });
        const link = document.createElement('a');
        link.download = `chart_${Date.now()}.png`;
        link.href = canvas.toDataURL('image/png');
        link.click();
    } catch (err) {
        console.error("Export failed", err);
    }
  };

  const yAxisUnit = propertyUnits[activeYKey];
  const xAxisUnit = propertyUnits[activeXKey];
  const zAxisUnit = zAxisKey !== 'none' ? propertyUnits[zAxisKey] : '';
  const yAxisLabel = yAxisUnit ? `${tProp(activeYKey)} (${yAxisUnit})` : tProp(activeYKey);
  const xAxisLabel = xAxisUnit ? `${tProp(activeXKey)} (${xAxisUnit})` : tProp(activeXKey);

  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const pointData = payload[0].payload;

      // Calculate dynamic properties to display (excluding axes and non-numeric)
      // This ensures we show 'Ethylene Content' etc. if they exist for the record but aren't axes.
      const dynamicKeys = numericProperties.filter(key => 
        pointData[key] !== undefined && 
        pointData[key] !== null && 
        key !== activeXKey && 
        key !== activeYKey && 
        key !== zAxisKey
      ).sort();

      return (
        <div className="bg-white dark:bg-slate-900 p-3 border border-slate-200 dark:border-slate-800 shadow-xl rounded-lg text-sm min-w-[240px] z-50 transition-colors duration-200">
            <div className="mb-2">
                <p className="font-bold text-slate-800 dark:text-slate-100 text-base">{pointData.name}</p>
                <div className="flex items-center gap-1.5 text-xs text-slate-500 dark:text-slate-400 mt-0.5">
                    <Factory size={12} className="text-slate-400 dark:text-slate-500"/>
                    <span>{pointData.manufacturer}</span>
                </div>
            </div>
            <div className="border-t border-slate-100 dark:border-slate-800 pt-2 space-y-1.5">
                {chartType === 'scatter' && (
                    <div className="flex justify-between text-xs bg-slate-50 dark:bg-slate-800/50 p-1 rounded">
                        <span className="text-slate-500 dark:text-slate-400">{tProp(activeXKey)}:</span>
                        <span className="font-mono font-semibold text-blue-700 dark:text-blue-400">
                            {pointData[activeXKey]} <span className="text-[10px] text-slate-400 dark:text-slate-500">{xAxisUnit}</span>
                        </span>
                    </div>
                )}
                <div className="flex justify-between text-xs bg-slate-50 dark:bg-slate-800/50 p-1 rounded">
                    <span className="text-slate-500 dark:text-slate-400">{tProp(activeYKey)}:</span>
                    <span className="font-mono font-semibold text-blue-700 dark:text-blue-400">
                        {pointData[activeYKey]} <span className="text-[10px] text-slate-400 dark:text-slate-500">{yAxisUnit}</span>
                    </span>
                </div>
                 {zAxisKey !== 'none' && (
                    <div className="flex justify-between text-xs bg-slate-50 dark:bg-slate-800/50 p-1 rounded">
                        <span className="text-slate-500 dark:text-slate-400">{tProp(zAxisKey)}:</span>
                        <span className="font-mono font-semibold text-purple-700 dark:text-purple-400">
                            {pointData[zAxisKey]} <span className="text-[10px] text-slate-400 dark:text-slate-500">{zAxisUnit}</span>
                        </span>
                    </div>
                )}

                {/* Dynamic Extra Properties */}
                {dynamicKeys.map(key => (
                    <div key={key} className="flex justify-between text-xs bg-emerald-50/50 dark:bg-emerald-900/10 p-1 rounded border border-emerald-100/50 dark:border-emerald-800/20">
                        <span className="text-slate-500 dark:text-slate-400">{tProp(key)}:</span>
                        <span className="font-mono font-medium text-emerald-700 dark:text-emerald-400">
                            {pointData[key]} <span className="text-[10px] text-slate-400 dark:text-slate-500">{propertyUnits[key]}</span>
                        </span>
                    </div>
                ))}

                {colorByKey !== 'none' && (
                    <div className="flex justify-between text-xs mt-2 pt-2 border-t border-slate-100 dark:border-slate-800">
                        <span className="text-slate-500 dark:text-slate-400">{tProp(colorByKey)}:</span>
                        <span className="font-medium text-slate-800 dark:text-slate-200">{pointData[colorByKey]}</span>
                    </div>
                )}
            </div>
        </div>
      );
    }
    return null;
  };

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400 dark:text-slate-500 border border-slate-200 dark:border-slate-800 rounded-lg bg-white dark:bg-slate-900 transition-colors">
        <Activity size={48} className="mb-4 text-slate-300 dark:text-slate-600" />
        <p>{t('noProducts')}</p>
      </div>
    );
  }

  if (numericProperties.length === 0) {
     return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400 dark:text-slate-500 border border-slate-200 dark:border-slate-800 rounded-lg bg-white dark:bg-slate-900 transition-colors">
        <Activity size={48} className="mb-4 text-slate-300 dark:text-slate-600" />
        <p>{t('noNumericData')}</p>
      </div>
    );
  }

  return (
    <div className="bg-white dark:bg-slate-900 rounded-lg shadow-sm border border-slate-200 dark:border-slate-800 flex flex-col w-full transition-colors duration-300" style={{ minHeight: '600px', height: '600px' }}>

      {/* Configuration Header */}
      <div className="border-b border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-900/50 flex-shrink-0 transition-colors">
        <div className="p-3 px-4 flex items-center justify-between">
            <div className="flex items-center gap-2 text-slate-800 dark:text-slate-200 font-semibold">
                <Settings2 size={18} className="text-blue-600 dark:text-blue-400" />
                <span>{t('chartConfig')}</span>
            </div>
            <div className="flex gap-2">
                 <button 
                    onClick={() => setShowConfig(!showConfig)}
                    className="text-xs text-blue-600 dark:text-blue-400 hover:text-blue-700 dark:hover:text-blue-300 font-medium px-2 py-1 rounded hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors"
                >
                    {showConfig ? t('collapseConfig') : t('expandConfig')}
                </button>
                 <div className="h-4 w-px bg-slate-300 dark:bg-slate-700 self-center mx-1"></div>
                 <button onClick={handleExportJSON} className="text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200" title={t('exportJson')}><FileJson size={16}/></button>
                 <button onClick={handleExportCSV} className="text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200" title={t('exportCsv')}><FileSpreadsheet size={16}/></button>
                 <button onClick={handleExportPNG} className="text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200" title={t('exportPng')}><ImageDown size={16}/></button>
            </div>
        </div>

        {showConfig && (
            <div className="p-4 pt-0 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 animate-in slide-in-from-top-2 duration-200">
                {/* 1. Chart Type */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center gap-1">
                        <Activity size={12}/> {t('chartType')}
                    </label>
                    <div className="flex bg-white dark:bg-slate-800 rounded-md border border-slate-200 dark:border-slate-700 p-1 transition-colors">
                        <button
                        onClick={() => setChartType('bar')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'bar' ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400 shadow-sm' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
                        }`}
                        >
                        <BarChart2 size={14} /> {t('barChart')}
                        </button>
                        <button
                        onClick={() => setChartType('scatter')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'scatter' ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400 shadow-sm' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
                        }`}
                        >
                        <Activity size={14} /> {t('scatterChart')}
                        </button>
                    </div>
                </div>

                {/* 2. Axes Configuration */}
                <div className="space-y-1.5 lg:col-span-2">
                    <label className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center gap-1">
                        <MoveVertical size={12}/> {t('axisMapping')}
                    </label>
                    <div className="flex gap-2">
                        {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={activeXKey} onChange={(e) => setUserXAxisKey(e.target.value)}
                                    className="w-full bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5 transition-colors"
                                >
                                    {numericProperties.map(p => <option key={p} value={p}>{t('xAxis')}: {tProp(p)}</option>)}
                                </select>
                             </div>
                        )}

                        <div className="flex-1 min-w-[120px]">
                            <select 
                                value={activeYKey} onChange={(e) => setUserYAxisKey(e.target.value)}
                                className="w-full bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5 transition-colors"
                            >
                                {numericProperties.map(p => <option key={p} value={p}>{chartType === 'bar' ? t('val') : t('yAxis')}: {tProp(p)}</option>)}
                            </select>
                        </div>

                         {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={zAxisKey} onChange={(e) => setZAxisKey(e.target.value)}
                                    className="w-full bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5 transition-colors"
                                >
                                    <option value="none">{t('zAxis')}: {t('noneAxis')}</option>
                                    {numericProperties.map(p => <option key={p} value={p}>{t('zAxis')}: {tProp(p)}</option>)}
                                </select>
                             </div>
                        )}
                    </div>
                </div>

                {/* 3. Style & Color */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center gap-1">
                        <Palette size={12}/> {t('styleGrouping')}
                    </label>
                    <div className="flex gap-2 items-center">
                         <select 
                            value={colorByKey} onChange={(e) => setColorByKey(e.target.value)}
                            className="flex-1 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5 transition-colors"
                        >
                            <option value="none">{t('colorSingle')}</option>
                            <optgroup label="Properties">
                                {categoricalProperties.map(p => <option key={p} value={p}>{t('groupBy').replace('{key}', tProp(p))}</option>)}
                            </optgroup>
                        </select>
                        {chartType === 'scatter' && (
                             <button
                                onClick={() => setShowTrendline(!showTrendline)}
                                title={t('trendline')}
                                className={`p-1.5 rounded border transition-colors ${showTrendline ? 'bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 border-indigo-200 dark:border-indigo-800' : 'bg-white dark:bg-slate-800 text-slate-400 dark:text-slate-500 border-slate-200 dark:border-slate-700'}`}
                             >
                                 <TrendingUp size={16} />
                             </button>
                        )}
                    </div>
                </div>

                {/* 4. Data Filters */}
                <div className="space-y-1.5 lg:col-span-4 border-t border-slate-200 dark:border-slate-800 pt-3 mt-1">
                    <div className="flex items-center justify-between">
                        <label className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center gap-1">
                            <Filter size={12}/> {t('dataFilters')}
                        </label>
                        <button 
                            onClick={addFilter}
                            className="flex items-center gap-1 text-[10px] font-medium text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/20 hover:bg-blue-100 dark:hover:bg-blue-900/40 px-2 py-1 rounded-md transition-colors"
                        >
                            <Plus size={12}/> {t('addFilter')}
                        </button>
                    </div>

                    {filters.length === 0 ? (
                        <p className="text-[10px] text-slate-400 dark:text-slate-600 italic pl-1">{t('noFilters')}</p>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3 mt-2">
                            {filters.map(filter => (
                                <div key={filter.id} className="bg-white dark:bg-slate-800 p-2.5 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm group animate-in fade-in zoom-in-95 duration-200 hover:shadow-md hover:border-emerald-500/30 dark:hover:border-emerald-500/30 transition-all">
                                    <div className="flex items-center justify-between gap-2 mb-2">
                                        <div className="flex-1 relative">
                                            <select 
                                                value={filter.key} 
                                                onChange={(e) => updateFilter(filter.id, 'key', e.target.value)}
                                                className="w-full text-xs font-semibold bg-transparent border-none p-0 pr-4 focus:ring-0 text-slate-700 dark:text-slate-200 cursor-pointer appearance-none truncate"
                                            >
                                                {numericProperties.map(p => <option key={p} value={p}>{tProp(p)}</option>)}
                                            </select>
                                            {/* Tiny triangle indicator for select */}
                                            <div className="absolute right-0 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                                                <ChevronDown size={10} />
                                            </div>
                                        </div>
                                        <button 
                                            onClick={() => removeFilter(filter.id)} 
                                            className="text-slate-400 hover:text-red-500 dark:text-slate-500 dark:hover:text-red-400 transition-colors p-0.5 rounded hover:bg-red-50 dark:hover:bg-red-900/20"
                                        >
                                            <X size={14}/>
                                        </button>
                                    </div>

                                    <div className="flex items-center gap-2">
                                        <div className="flex-1 flex items-center bg-slate-50 dark:bg-slate-900 rounded border border-slate-200 dark:border-slate-700 px-2 py-1.5 focus-within:ring-1 focus-within:ring-emerald-500/50 focus-within:border-emerald-500/50 transition-all">
                                            <span className="text-[10px] font-medium text-slate-400 mr-1.5 select-none">{t('min')}</span>
                                            <input 
                                                type="number" 
                                                value={filter.min}
                                                onChange={(e) => updateFilter(filter.id, 'min', e.target.value)}
                                                placeholder="-"
                                                className="w-full bg-transparent border-none p-0 text-xs font-mono focus:ring-0 text-slate-700 dark:text-slate-200 placeholder:text-slate-300 dark:placeholder:text-slate-600"
                                            />
                                        </div>
                                        <div className="text-slate-300 dark:text-slate-600">
                                            <ArrowRight size={12} />
                                        </div>
                                        <div className="flex-1 flex items-center bg-slate-50 dark:bg-slate-900 rounded border border-slate-200 dark:border-slate-700 px-2 py-1.5 focus-within:ring-1 focus-within:ring-emerald-500/50 focus-within:border-emerald-500/50 transition-all">
                                            <span className="text-[10px] font-medium text-slate-400 mr-1.5 select-none">{t('max')}</span>
                                            <input 
                                                type="number" 
                                                value={filter.max}
                                                onChange={(e) => updateFilter(filter.id, 'max', e.target.value)}
                                                placeholder="-"
                                                className="w-full bg-transparent border-none p-0 text-xs font-mono focus:ring-0 text-slate-700 dark:text-slate-200 placeholder:text-slate-300 dark:placeholder:text-slate-600"
                                            />
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        )}
      </div>

      {/* Chart Canvas */}
      <div ref={chartContainerRef} className="flex-1 p-6 relative w-full h-full bg-white dark:bg-slate-900 transition-colors">
        {activeYKey && (
            <ResponsiveContainer width="100%" height="100%">
            {chartType === 'bar' ? (
                <BarChart
                data={chartData}
                margin={{ top: 20, right: 30, left: 20, bottom: 40 }}
                >
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={chartStyles.gridStroke} />
                <XAxis 
                    dataKey="name" 
                    stroke={chartStyles.axisStroke} 
                    fontSize={12} 
                    tickLine={false} 
                    axisLine={{ stroke: chartStyles.axisStroke }} 
                    interval={0} 
                    angle={-30} 
                    textAnchor="end" 
                    height={60} 
                />
                <YAxis 
                    stroke={chartStyles.axisStroke} 
                    fontSize={12} 
                    tickLine={false} 
                    axisLine={{ stroke: chartStyles.axisStroke }} 
                    domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { textAnchor: 'middle', fill: chartStyles.axisTextFill } }} 
                />
                <RechartsTooltip content={<CustomTooltip />} cursor={{ fill: theme === 'dark' ? '#1e293b' : '#f1f5f9' }} />
                <Legend wrapperStyle={{ color: chartStyles.axisTextFill }}/>
                <Bar 
                    dataKey={activeYKey} 
                    fill="#3b82f6" 
                    radius={[4, 4, 0, 0]} 
                    name={yAxisLabel} 
                    barSize={40}
                    isAnimationActive={false}
                >
                    {colorByKey !== 'none' && chartData.map((entry, index) => {
                        const val = String(entry[colorByKey] || 'Unclassified');
                        return <Cell key={`cell-${index}`} fill={colorMap?.[val] || '#3b82f6'} />;
                    })}
                    <LabelList dataKey={activeYKey} position="top" fill={chartStyles.axisTextFill} fontSize={12} formatter={(val: number) => val.toFixed(2)} />
                </Bar>
                </BarChart>
            ) : (
                <ScatterChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                <CartesianGrid strokeDasharray="3 3" stroke={chartStyles.gridStroke} />
                <XAxis 
                    type="number" dataKey={activeXKey} name={activeXKey} stroke={chartStyles.axisStroke} fontSize={12} domain={['auto', 'auto']}
                    label={{ value: xAxisLabel, position: 'bottom', offset: 0, style: { fill: chartStyles.axisTextFill } }} 
                />
                <YAxis 
                    type="number" dataKey={activeYKey} name={activeYKey} stroke={chartStyles.axisStroke} fontSize={12} domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { fill: chartStyles.axisTextFill } }} 
                />
                {zAxisKey !== 'none' && (
                    <ZAxis type="number" dataKey={zAxisKey} range={[60, 600]} name={zAxisKey} unit={zAxisUnit} />
                )}

                <RechartsTooltip content={<CustomTooltip />} cursor={{ strokeDasharray: '3 3' }} />
                <Legend wrapperStyle={{ color: chartStyles.axisTextFill }} />

                {colorByKey !== 'none' && scatterGroups ? (
                    Object.entries(scatterGroups).map(([groupName, groupData], index) => (
                        <Scatter 
                            key={groupName}
                            name={groupName}
                            data={groupData}
                            fill={COLORS[index % COLORS.length]}
                            isAnimationActive={false}
                        />
                    ))
                ) : (
                    <Scatter name={t('chartTitle')} data={chartData} fill="#3b82f6" isAnimationActive={false} />
                )}

                {showTrendline && trendlineData.length > 0 && (
                    <Scatter name={t('trendline')} data={trendlineData} line={{ stroke: '#ef4444', strokeWidth: 2, strokeDasharray: '5 5' }} shape={() => null} legendType="none" tooltipType="none" isAnimationActive={false}/>
                )}
                </ScatterChart>
            )}
            </ResponsiveContainer>
        )}

        {chartType === 'bar' && colorByKey !== 'none' && colorMap && (
             <div className="absolute top-4 right-6 bg-white/90 dark:bg-slate-800/90 p-2 rounded border border-slate-200 dark:border-slate-700 text-xs shadow-sm max-w-[150px] transition-colors">
                 <p className="font-semibold text-slate-500 dark:text-slate-400 mb-1 border-b border-slate-100 dark:border-slate-700 pb-1">{t('groupBy').replace('{key}', tProp(colorByKey))}</p>
                 <div className="space-y-1 max-h-[100px] overflow-y-auto custom-scrollbar">
                     {Object.entries(colorMap).map(([label, color]) => (
                         <div key={label} className="flex items-center gap-2">
                             <div className="w-2 h-2 rounded-full" style={{ backgroundColor: color }}></div>
                             <span className="truncate text-slate-600 dark:text-slate-300" title={label}>{label}</span>
                         </div>
                     ))}
                 </div>
             </div>
        )}
      </div>

      <div className="px-6 py-2 bg-slate-50 dark:bg-slate-900 border-t border-slate-200 dark:border-slate-800 text-[10px] text-slate-400 dark:text-slate-500 flex justify-between flex-shrink-0 rounded-b-lg transition-colors">
         <span>ResinDB Visualization Engine v1.3</span>
         {filters.length > 0 && <span>Filtered: {filteredData.length} records</span>}
      </div>
    </div>
  );
};

