              flex items-center px-3 py-2.5 mx-2 mb-1 rounded-lg text-sm cursor-pointer transition-all duration-200 outline-none focus:ring-2 focus:ring-emerald-500/50
              ${!selectedCategoryId 
                ? 'bg-gradient-to-r from-emerald-600 to-emerald-500 text-white shadow-md shadow-emerald-900/20 dark:shadow-emerald-900/40 font-semibold' 
                : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800/60 hover:text-slate-900 dark:hover:text-slate-200'
              }
            `}
            onClick={() => onSelectCategory(null)}
            onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    onSelectCategory(null);
                }
            }}
        >
            <div className="w-4 h-4 mr-2 shrink-0 flex items-center justify-center">
                 {!selectedCategoryId && <div className="w-1.5 h-1.5 bg-white rounded-full animate-pulse"></div>}
            </div>
            <div className={`mr-2.5 ${!selectedCategoryId ? 'text-white' : 'text-slate-500 dark:text-slate-500'}`}>
                <LayoutGrid size={16} />
            </div>
            <span className="tracking-wide">{t('allProducts')}</span>
        </div>

        <div className="mx-4 my-2 border-b border-slate-100 dark:border-slate-800 transition-colors"></div>

        {categories.map((cat) => (
          <TreeNode
            key={cat.id}
            category={cat}
            selectedId={selectedCategoryId}
            onSelect={onSelectCategory}
            depth={0}
          />
        ))}
      </div>

      {/* Footer */}
      <div className="p-4 bg-slate-50 dark:bg-slate-950/30 border-t border-slate-100 dark:border-slate-800 transition-colors duration-300">
        <div className="flex items-center gap-3 text-xs text-slate-500 dark:text-slate-500">
            <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.4)]"></div>
            <span>{t('systemOnline')} • v2.5.0</span>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer,
  ScatterChart, Scatter, ZAxis, LabelList, Cell
} from 'recharts';
import { Product } from '../types';
import { 
  BarChart2, Activity, TrendingUp, FileJson, FileSpreadsheet, ImageDown,
  Factory, Settings2, Palette, MoveVertical, Filter, Plus, Trash2, X, ChevronDown, ArrowRight, Info, Microscope
} from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16', '#6366f1'];

interface RangeFilter {
    id: string;
    key: string;
    min: string;
    max: string;
}

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [userXAxisKey, setUserXAxisKey] = useState<string>('');
  const [userYAxisKey, setUserYAxisKey] = useState<string>('');
  const [zAxisKey, setZAxisKey] = useState<string>('none');
  const [colorByKey, setColorByKey] = useState<string>('none');
  const [showTrendline, setShowTrendline] = useState<boolean>(false);
  const [showConfig, setShowConfig] = useState<boolean>(true);
  const [filters, setFilters] = useState<RangeFilter[]>([]);

  const chartContainerRef = useRef<HTMLDivElement>(null);

  const { t, tProp } = useLanguage();
  const { theme } = useTheme();

  // Chart styling constants based on theme
  const chartStyles = useMemo(() => {
    const isDark = theme === 'dark';
    return {
        gridStroke: isDark ? '#334155' : '#e2e8f0', // slate-700 vs slate-200
        axisStroke: isDark ? '#94a3b8' : '#64748b', // slate-400 vs slate-500
        axisTextFill: isDark ? '#94a3b8' : '#64748b',
        tooltipBg: isDark ? '#0f172a' : '#ffffff', // slate-900 vs white
        tooltipBorder: isDark ? '#1e293b' : '#e2e8f0', // slate-800 vs slate-200
        tooltipText: isDark ? '#f8fafc' : '#1e293b', // slate-50 vs slate-800
        barFill: '#3b82f6'
    };
  }, [theme]);

  // 1. Extract Numeric Properties (for X, Y, Z axes)
  const numericProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        const num = Number(val.value);
        if (!isNaN(num) && val.value !== '' && val.value !== null) {
          props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // Filter Logic
  const addFilter = () => {
    if (numericProperties.length > 0) {
        setFilters([...filters, { id: Date.now().toString(), key: numericProperties[0], min: '', max: '' }]);
    }
  };

  const removeFilter = (id: string) => {
    setFilters(filters.filter(f => f.id !== id));
  };

  const updateFilter = (id: string, field: keyof RangeFilter, value: string) => {
    setFilters(filters.map(f => f.id === id ? { ...f, [field]: value } : f));
  };

  // Filtered Data
  const filteredData = useMemo(() => {
    if (filters.length === 0) return data;
    return data.filter(item => {
        return filters.every(f => {
             const valObj = item.properties[f.key];
             if (!valObj) return false;
             const val = Number(valObj.value);
             if (isNaN(val)) return false;

             const min = f.min === '' ? -Infinity : Number(f.min);
             const max = f.max === '' ? Infinity : Number(f.max);

             return val >= min && val <= max;
        });
    });
  }, [data, filters]);

  // 2. Extract Categorical Properties (for Coloring)
  const categoricalProperties = useMemo(() => {
    const props = new Set<string>(['manufacturer']); 
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (typeof val.value === 'string' && val.value.length < 20) {
            props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // 3. Helper to extract units
  const propertyUnits = useMemo(() => {
    const units: Record<string, string> = {};
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (v.unit && !units[k]) units[k] = v.unit;
        });
    });
    return units;
  }, [data]);

  // 4. Calculate Default/Active Keys synchronously
  const activeYKey = useMemo(() => {
    if (userYAxisKey && numericProperties.includes(userYAxisKey)) return userYAxisKey;
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    if (numericProperties.includes('密度')) return '密度';
    return numericProperties[0] || '';
  }, [userYAxisKey, numericProperties]);

  const activeXKey = useMemo(() => {
    if (userXAxisKey && numericProperties.includes(userXAxisKey)) return userXAxisKey;
    if (numericProperties.includes('密度')) return '密度';
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    return numericProperties.length > 1 ? numericProperties[1] : numericProperties[0] || '';
  }, [userXAxisKey, numericProperties]);

  // 5. Transform Data for Recharts
  const chartData = useMemo(() => {
    return filteredData.map(product => {
      const flattened: any = {
        name: product.gradeName,
        manufacturer: product.manufacturer,
        id: product.id
      };

      Object.entries(product.properties).forEach(([key, val]) => {
        const numVal = Number(val.value);
        if (!isNaN(numVal) && val.value !== '' && val.value !== null) {
          flattened[key] = numVal;
        } else {
          flattened[key] = val.value;
        }
      });
      return flattened;
    });
  }, [filteredData]);

  // 6. Group Data for Scatter Series
  const scatterGroups = useMemo(() => {
    if (chartType !== 'scatter' || colorByKey === 'none') return null;

    const groups: Record<string, any[]> = {};
    chartData.forEach(d => {
        const keyVal = d[colorByKey];
        const groupName = keyVal ? String(keyVal) : 'Unclassified';
        if (!groups[groupName]) groups[groupName] = [];
        groups[groupName].push(d);
    });
    return groups;
  }, [chartData, chartType, colorByKey]);

  // 7. Color Map
  const colorMap = useMemo(() => {
    if (colorByKey === 'none') return null;
    const uniqueValues = Array.from(new Set(chartData.map(d => String(d[colorByKey] || 'Unclassified'))));
    const map: Record<string, string> = {};
    uniqueValues.forEach((val, idx) => {
        map[val] = COLORS[idx % COLORS.length];
    });
    return map;
  }, [chartData, colorByKey]);

  // Trendline Logic
  const trendlineData = useMemo(() => {
    if (chartType !== 'scatter' || !showTrendline || chartData.length < 2) return [];

    let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0, count = 0;
    chartData.forEach((point) => {
        const x = point[activeXKey];
        const y = point[activeYKey];
        if (typeof x === 'number' && typeof y === 'number') {
            sumX += x; sumY += y; sumXY += x * y; sumXX += x * x; count++;
        }
    });

    if (count < 2) return [];
    const slope = (count * sumXY - sumX * sumY) / (count * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / count;
    const xValues = chartData.map(d => d[activeXKey]).filter(v => typeof v === 'number') as number[];
    if (xValues.length === 0) return [];
    const minX = Math.min(...xValues);
    const maxX = Math.max(...xValues);

    return [
        { [activeXKey]: minX, [activeYKey]: slope * minX + intercept },
        { [activeXKey]: maxX, [activeYKey]: slope * maxX + intercept }
    ];
  }, [chartData, activeXKey, activeYKey, showTrendline, chartType]);

  const handleExportJSON = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(chartData));
    const link = document.createElement('a');
    link.href = dataStr;
    link.download = "chart_data.json";
    link.click();
  };

  const handleExportCSV = () => {
    if (chartData.length === 0) return;
    const allKeys = Array.from(new Set(chartData.flatMap(Object.keys)));
    const header = allKeys.join(',');
    const rows = chartData.map(row => 
      allKeys.map(key => {
        const val = row[key];
        if (val === null || val === undefined) return '';
        const stringVal = String(val);
        if (stringVal.includes(',') || stringVal.includes('"') || stringVal.includes('\n')) {
          return `"${stringVal.replace(/"/g, '""')}"`;
        }
        return stringVal;
      }).join(',')
    );
    const csvContent = [header, ...rows].join('\n');
    const blob = new Blob(["\uFEFF" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'chart_data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleExportPNG = async () => {
    if (!chartContainerRef.current) return;
    try {
        const canvas = await html2canvas(chartContainerRef.current, {
            scale: 2, // High resolution
            backgroundColor: theme === 'dark' ? '#0f172a' : '#ffffff', // slate-900 or white
            logging: false,
            useCORS: true
        });
        const link = document.createElement('a');
        link.download = `chart_${Date.now()}.png`;
        link.href = canvas.toDataURL('image/png');
        link.click();
    } catch (err) {
        console.error("Export failed", err);
    }
  };

  // Determine units for active axes
  const yAxisUnit = propertyUnits[activeYKey];
  const xAxisUnit = propertyUnits[activeXKey];
  const zAxisUnit = zAxisKey !== 'none' ? propertyUnits[zAxisKey] : '';

  // Construct labels with units for the chart axes
  const yAxisLabel = yAxisUnit ? `${tProp(activeYKey)} (${yAxisUnit})` : tProp(activeYKey);
  const xAxisLabel = xAxisUnit ? `${tProp(activeXKey)} (${xAxisUnit})` : tProp(activeXKey);

  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const pointData = payload[0].payload;

      // Calculate dynamic numeric properties to display (excluding axes)
      const dynamicKeys = numericProperties.filter(key => 
        pointData[key] !== undefined && 
        pointData[key] !== null && 
        key !== activeXKey && 
        key !== activeYKey && 
        key !== zAxisKey
      ).sort();

      // Calculate extra text properties (excluding system keys, axes, and color grouping)
      const extraTextKeys = Object.keys(pointData).filter(key => 
        typeof pointData[key] === 'string' &&
        key !== 'name' && 
        key !== 'manufacturer' &&
        key !== 'id' &&
        key !== activeXKey && 
        key !== activeYKey && 
        key !== zAxisKey &&
        key !== colorByKey
      ).slice(0, 3); // Limit to top 3

      return (
        <div className="bg-white dark:bg-slate-900 p-3.5 border border-slate-200 dark:border-slate-800 shadow-xl rounded-lg text-sm min-w-[280px] max-w-[320px] z-50 transition-colors duration-200 backdrop-blur-sm bg-opacity-95 dark:bg-opacity-95">
            <div className="mb-2.5 pb-2.5 border-b border-slate-100 dark:border-slate-800">
                <p className="font-bold text-slate-800 dark:text-slate-100 text-base leading-tight">{pointData.name}</p>
                <div className="flex items-center gap-1.5 text-xs text-slate-500 dark:text-slate-400 mt-1">
                    <Factory size={12} className="text-slate-400 dark:text-slate-500"/>
                    <span>{pointData.manufacturer}</span>
                </div>
            </div>

            <div className="space-y-1.5">
                {/* Main Axes Values Highlighted */}
                 <div className="grid grid-cols-2 gap-2 mb-2">
                    {chartType === 'scatter' && (
                        <div className="flex flex-col bg-slate-50 dark:bg-slate-800/50 p-1.5 rounded">
                            <span className="text-[10px] text-slate-400 dark:text-slate-500 uppercase tracking-wide">{tProp(activeXKey)}</span>
                            <span className="font-mono font-semibold text-blue-700 dark:text-blue-400 text-sm">
                                {pointData[activeXKey]} 
                                {xAxisUnit && <span className="text-[10px] text-slate-400 dark:text-slate-500 ml-1 font-normal">{xAxisUnit}</span>}
                            </span>
                        </div>
                    )}
                    <div className="flex flex-col bg-slate-50 dark:bg-slate-800/50 p-1.5 rounded">
                        <span className="text-[10px] text-slate-400 dark:text-slate-500 uppercase tracking-wide">{tProp(activeYKey)}</span>
                        <span className="font-mono font-semibold text-blue-700 dark:text-blue-400 text-sm">
                            {pointData[activeYKey]} 
                            {yAxisUnit && <span className="text-[10px] text-slate-400 dark:text-slate-500 ml-1 font-normal">{yAxisUnit}</span>}
                        </span>
                    </div>
                 </div>

                 {/* Z Axis Value */}
                 {zAxisKey !== 'none' && (
                    <div className="flex justify-between text-xs bg-slate-50 dark:bg-slate-800/50 p-1 rounded">
                        <span className="text-slate-500 dark:text-slate-400">{tProp(zAxisKey)}:</span>
                        <span className="font-mono font-semibold text-purple-700 dark:text-purple-400">
                            {pointData[zAxisKey]} 
                            {zAxisUnit && <span className="text-[10px] text-slate-400 dark:text-slate-500 ml-1">{zAxisUnit}</span>}
                        </span>
                    </div>
                )}

                {/* Grid for Extra Numeric Properties (Composition, etc) */}
                {dynamicKeys.length > 0 && (
                    <div className="pt-1">
                        <p className="text-[10px] font-semibold text-slate-400 dark:text-slate-500 uppercase tracking-wider mb-1 flex items-center gap-1">
                             <Microscope size={10} />
                             {t('details')}
                        </p>
                        <div className="grid grid-cols-1 gap-1">
                            {dynamicKeys.map(key => (
                                <div key={key} className="flex justify-between items-center text-xs p-1 rounded hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors">
                                    <span className="text-slate-500 dark:text-slate-400 truncate pr-2">{tProp(key)}</span>
                                    <span className="font-mono font-medium text-emerald-700 dark:text-emerald-400 whitespace-nowrap">
                                        {pointData[key]} 
                                        {propertyUnits[key] && <span className="text-[10px] text-slate-400 dark:text-slate-500 ml-0.5">{propertyUnits[key]}</span>}
                                    </span>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {colorByKey !== 'none' && (
                    <div className="flex justify-between text-xs mt-2 pt-2 border-t border-slate-100 dark:border-slate-800">
                        <span className="text-slate-500 dark:text-slate-400">{tProp(colorByKey)}:</span>
                        <span className="font-medium text-slate-800 dark:text-slate-200">{pointData[colorByKey]}</span>
                    </div>
                )}

                {/* Text Properties Section */}
                {extraTextKeys.length > 0 && (
                    <div className="mt-2 pt-2 border-t border-slate-100 dark:border-slate-800 space-y-1">
                        <p className="text-[10px] font-semibold text-slate-400 dark:text-slate-500 uppercase tracking-wider mb-1 flex items-center gap-1">
                             <Info size={10} />
                             {t('otherDetails')}
                        </p>
                        {extraTextKeys.map(key => (
                             <div key={key} className="flex flex-col gap-0.5 text-xs bg-slate-50/50 dark:bg-slate-800/30 p-1 rounded">
                                <span className="text-slate-500 dark:text-slate-400 font-medium text-[10px] uppercase">{tProp(key)}</span>
                                <span className="text-slate-700 dark:text-slate-300 leading-snug break-words">
                                    {pointData[key]}
                                </span>
                             </div>
                        ))}
                    </div>
                )}
            </div>
        </div>
      );
    }
    return null;
  };

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400 dark:text-slate-500 border border-slate-200 dark:border-slate-800 rounded-lg bg-white dark:bg-slate-900 transition-colors">
        <Activity size={48} className="mb-4 text-slate-300 dark:text-slate-600" />
        <p>{t('noProducts')}</p>
      </div>
    );
  }

  if (numericProperties.length === 0) {
     return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400 dark:text-slate-500 border border-slate-200 dark:border-slate-800 rounded-lg bg-white dark:bg-slate-900 transition-colors">
        <Activity size={48} className="mb-4 text-slate-300 dark:text-slate-600" />
        <p>{t('noNumericData')}</p>
      </div>
    );
  }

  return (
    <div className="bg-white dark:bg-slate-900 rounded-lg shadow-sm border border-slate-200 dark:border-slate-800 flex flex-col w-full transition-colors duration-300" style={{ minHeight: '600px', height: '600px' }}>

      {/* Configuration Header */}
      <div className="border-b border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-900/50 flex-shrink-0 transition-colors">
        <div className="p-3 px-4 flex items-center justify-between">
            <div className="flex items-center gap-2 text-slate-800 dark:text-slate-200 font-semibold">
                <Settings2 size={18} className="text-blue-600 dark:text-blue-400" />
                <span>{t('chartConfig')}</span>
            </div>
            <div className="flex gap-2">
                 <button 
                    onClick={() => setShowConfig(!showConfig)}
                    className="text-xs text-blue-600 dark:text-blue-400 hover:text-blue-700 dark:hover:text-blue-300 font-medium px-2 py-1 rounded hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors"
                >
                    {showConfig ? t('collapseConfig') : t('expandConfig')}
                </button>
                 <div className="h-4 w-px bg-slate-300 dark:bg-slate-700 self-center mx-1"></div>
                 <button onClick={handleExportJSON} className="text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200" title={t('exportJson')}><FileJson size={16}/></button>
                 <button onClick={handleExportCSV} className="text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200" title={t('exportCsv')}><FileSpreadsheet size={16}/></button>
                 <button onClick={handleExportPNG} className="text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200" title={t('exportPng')}><ImageDown size={16}/></button>
            </div>
        </div>

        {showConfig && (
            <div className="p-4 pt-0 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 animate-in slide-in-from-top-2 duration-200">
                {/* 1. Chart Type */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center gap-1">
                        <Activity size={12}/> {t('chartType')}
                    </label>
                    <div className="flex bg-white dark:bg-slate-800 rounded-md border border-slate-200 dark:border-slate-700 p-1 transition-colors">
                        <button
                        onClick={() => setChartType('bar')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'bar' ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400 shadow-sm' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
                        }`}
                        >
                        <BarChart2 size={14} /> {t('barChart')}
                        </button>
                        <button
                        onClick={() => setChartType('scatter')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'scatter' ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400 shadow-sm' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
                        }`}
                        >
                        <Activity size={14} /> {t('scatterChart')}
                        </button>
                    </div>
                </div>

                {/* 2. Axes Configuration */}
                <div className="space-y-1.5 lg:col-span-2">
                    <label className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center gap-1">
                        <MoveVertical size={12}/> {t('axisMapping')}
                    </label>
                    <div className="flex gap-2">
                        {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={activeXKey} onChange={(e) => setUserXAxisKey(e.target.value)}
                                    className="w-full bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5 transition-colors"
                                >
                                    {numericProperties.map(p => <option key={p} value={p}>{t('xAxis')}: {tProp(p)}</option>)}
                                </select>
                             </div>
                        )}

                        <div className="flex-1 min-w-[120px]">
                            <select 
                                value={activeYKey} onChange={(e) => setUserYAxisKey(e.target.value)}
                                className="w-full bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5 transition-colors"
                            >
                                {numericProperties.map(p => <option key={p} value={p}>{chartType === 'bar' ? t('val') : t('yAxis')}: {tProp(p)}</option>)}
                            </select>
                        </div>

                         {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={zAxisKey} onChange={(e) => setZAxisKey(e.target.value)}
                                    className="w-full bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5 transition-colors"
                                >
                                    <option value="none">{t('zAxis')}: {t('noneAxis')}</option>
                                    {numericProperties.map(p => <option key={p} value={p}>{t('zAxis')}: {tProp(p)}</option>)}
                                </select>
                             </div>
                        )}
                    </div>
                </div>

                {/* 3. Style & Color */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center gap-1">
                        <Palette size={12}/> {t('styleGrouping')}
                    </label>
                    <div className="flex gap-2 items-center">
                         <select 
                            value={colorByKey} onChange={(e) => setColorByKey(e.target.value)}
                            className="flex-1 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5 transition-colors"
                        >
                            <option value="none">{t('colorSingle')}</option>
                            <optgroup label="Properties">
                                {categoricalProperties.map(p => <option key={p} value={p}>{t('groupBy').replace('{key}', tProp(p))}</option>)}
                            </optgroup>
                        </select>
                        {chartType === 'scatter' && (
                             <button
                                onClick={() => setShowTrendline(!showTrendline)}
                                title={t('trendline')}
                                className={`p-1.5 rounded border transition-colors ${showTrendline ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 border-blue-200 dark:border-blue-800' : 'bg-white dark:bg-slate-800 text-slate-400 dark:text-slate-500 border-slate-200 dark:border-slate-700'}`}
                             >
                                 <TrendingUp size={16} />
                             </button>
                        )}
                    </div>
                </div>

                {/* 4. Data Filters */}
                <div className="space-y-1.5 lg:col-span-4 border-t border-slate-200 dark:border-slate-800 pt-3 mt-1">
                    <div className="flex items-center justify-between">
                        <label className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center gap-1">
                            <Filter size={12}/> {t('dataFilters')}
                        </label>
                        <button 
                            onClick={addFilter}
                            className="flex items-center gap-1 text-[10px] font-medium text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/20 hover:bg-blue-100 dark:hover:bg-blue-900/40 px-2 py-1 rounded-md transition-colors"
                        >
                            <Plus size={12}/> {t('addFilter')}
                        </button>
                    </div>

                    {filters.length === 0 ? (
                        <p className="text-[10px] text-slate-400 dark:text-slate-600 italic pl-1">{t('noFilters')}</p>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3 mt-2">
                            {filters.map(filter => (
                                <div key={filter.id} className="bg-white dark:bg-slate-800 p-2.5 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm group animate-in fade-in zoom-in-95 duration-200 hover:shadow-md hover:border-emerald-500/30 dark:hover:border-emerald-500/30 transition-all">
                                    <div className="flex items-center justify-between gap-2 mb-2">
                                        <div className="flex-1 relative">
                                            <select 
                                                value={filter.key} 
                                                onChange={(e) => updateFilter(filter.id, 'key', e.target.value)}
                                                className="w-full text-xs font-semibold bg-transparent border-none p-0 pr-4 focus:ring-0 text-slate-700 dark:text-slate-200 cursor-pointer appearance-none truncate"
                                            >
                                                {numericProperties.map(p => <option key={p} value={p}>{tProp(p)}</option>)}
                                            </select>
                                            {/* Tiny triangle indicator for select */}
                                            <div className="absolute right-0 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                                                <ChevronDown size={10} />
                                            </div>
                                        </div>
                                        <button 
                                            onClick={() => removeFilter(filter.id)} 
                                            className="text-slate-400 hover:text-red-500 dark:text-slate-500 dark:hover:text-red-400 transition-colors p-0.5 rounded hover:bg-red-50 dark:hover:bg-red-900/20"
                                        >
                                            <X size={14}/>
                                        </button>
                                    </div>

                                    <div className="flex items-center gap-2">
                                        <div className="flex-1 flex items-center bg-slate-50 dark:bg-slate-900 rounded border border-slate-200 dark:border-slate-700 px-2 py-1.5 focus-within:ring-1 focus-within:ring-emerald-500/50 focus-within:border-emerald-500/50 transition-all">
                                            <span className="text-[10px] font-medium text-slate-400 mr-1.5 select-none">{t('min')}</span>
                                            <input 
                                                type="number" 
                                                value={filter.min}
                                                onChange={(e) => updateFilter(filter.id, 'min', e.target.value)}
                                                placeholder="-"
                                                className="w-full bg-transparent border-none p-0 text-xs font-mono focus:ring-0 text-slate-700 dark:text-slate-200 placeholder:text-slate-300 dark:placeholder:text-slate-600"
                                            />
                                        </div>
                                        <div className="text-slate-300 dark:text-slate-600">
                                            <ArrowRight size={12} />
                                        </div>
                                        <div className="flex-1 flex items-center bg-slate-50 dark:bg-slate-900 rounded border border-slate-200 dark:border-slate-700 px-2 py-1.5 focus-within:ring-1 focus-within:ring-emerald-500/50 focus-within:border-emerald-500/50 transition-all">
                                            <span className="text-[10px] font-medium text-slate-400 mr-1.5 select-none">{t('max')}</span>
                                            <input 
                                                type="number" 
                                                value={filter.max}
                                                onChange={(e) => updateFilter(filter.id, 'max', e.target.value)}
                                                placeholder="-"
                                                className="w-full bg-transparent border-none p-0 text-xs font-mono focus:ring-0 text-slate-700 dark:text-slate-200 placeholder:text-slate-300 dark:placeholder:text-slate-600"
                                            />
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        )}
      </div>

      {/* Chart Canvas */}
      <div ref={chartContainerRef} className="flex-1 p-6 relative w-full h-full bg-white dark:bg-slate-900 transition-colors">
        {activeYKey && (
            <ResponsiveContainer width="100%" height="100%">
            {chartType === 'bar' ? (
                <BarChart
                data={chartData}
                margin={{ top: 20, right: 30, left: 40, bottom: 40 }}
                >
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={chartStyles.gridStroke} />
                <XAxis 
                    dataKey="name" 
                    stroke={chartStyles.axisStroke} 
                    fontSize={12} 
                    tickLine={false} 
                    axisLine={{ stroke: chartStyles.axisStroke }} 
                    interval={0} 
                    angle={-30} 
                    textAnchor="end" 
                    height={60} 
                />
                <YAxis 
                    stroke={chartStyles.axisStroke} 
                    fontSize={12} 
                    tickLine={false} 
                    axisLine={{ stroke: chartStyles.axisStroke }} 
                    domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { textAnchor: 'middle', fill: chartStyles.axisTextFill } }} 
                />
                <RechartsTooltip content={<CustomTooltip />} cursor={{ fill: theme === 'dark' ? '#1e293b' : '#f1f5f9' }} />
                <Legend wrapperStyle={{ color: chartStyles.axisTextFill }}/>
                <Bar 
                    dataKey={activeYKey} 
                    fill="#3b82f6" 
                    radius={[4, 4, 0, 0]} 
                    name={yAxisLabel} 
                    barSize={40}
                    isAnimationActive={false}
                >
                    {colorByKey !== 'none' && chartData.map((entry, index) => {
                        const val = String(entry[colorByKey] || 'Unclassified');
                        return <Cell key={`cell-${index}`} fill={colorMap?.[val] || '#3b82f6'} />;
                    })}
                    <LabelList dataKey={activeYKey} position="top" fill={chartStyles.axisTextFill} fontSize={12} formatter={(val: number) => val.toFixed(2)} />
                </Bar>
                </BarChart>
            ) : (
                <ScatterChart margin={{ top: 20, right: 20, bottom: 20, left: 40 }}>
                <CartesianGrid strokeDasharray="3 3" stroke={chartStyles.gridStroke} />
                <XAxis 
                    type="number" dataKey={activeXKey} name={activeXKey} stroke={chartStyles.axisStroke} fontSize={12} domain={['auto', 'auto']}
                    label={{ value: xAxisLabel, position: 'bottom', offset: 0, style: { fill: chartStyles.axisTextFill } }} 
                />
                <YAxis 
                    type="number" dataKey={activeYKey} name={activeYKey} stroke={chartStyles.axisStroke} fontSize={12} domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { fill: chartStyles.axisTextFill } }} 
                />
                {zAxisKey !== 'none' && (
                    <ZAxis type="number" dataKey={zAxisKey} range={[60, 600]} name={zAxisKey} unit={zAxisUnit} />
                )}

                <RechartsTooltip content={<CustomTooltip />} cursor={{ strokeDasharray: '3 3' }} />
                <Legend wrapperStyle={{ color: chartStyles.axisTextFill }} />

                {colorByKey !== 'none' && scatterGroups ? (
                    Object.entries(scatterGroups).map(([groupName, groupData], index) => (
                        <Scatter 
                            key={groupName}
                            name={groupName}
                            data={groupData}
                            fill={COLORS[index % COLORS.length]}
                            isAnimationActive={false}
                        />
                    ))
                ) : (
                    <Scatter name={t('chartTitle')} data={chartData} fill="#3b82f6" isAnimationActive={false} />
                )}

                {showTrendline && trendlineData.length > 0 && (
                    <Scatter name={t('trendline')} data={trendlineData} line={{ stroke: '#ef4444', strokeWidth: 2, strokeDasharray: '5 5' }} shape={() => null} legendType="none" tooltipType="none" isAnimationActive={false}/>
                )}
                </ScatterChart>
            )}
            </ResponsiveContainer>
        )}

        {chartType === 'bar' && colorByKey !== 'none' && colorMap && (
             <div className="absolute top-4 right-6 bg-white/90 dark:bg-slate-800/90 p-2 rounded border border-slate-200 dark:border-slate-700 text-xs shadow-sm max-w-[150px] transition-colors">
                 <p className="font-semibold text-slate-500 dark:text-slate-400 mb-1 border-b border-slate-100 dark:border-slate-700 pb-1">{t('groupBy').replace('{key}', tProp(colorByKey))}</p>
                 <div className="space-y-1 max-h-[100px] overflow-y-auto custom-scrollbar">
                     {Object.entries(colorMap).map(([label, color]) => (
                         <div key={label} className="flex items-center gap-2">
                             <div className="w-2 h-2 rounded-full" style={{ backgroundColor: color }}></div>
                             <span className="truncate text-slate-600 dark:text-slate-300" title={label}>{label}</span>
                         </div>
                     ))}
                 </div>
             </div>
        )}
      </div>

      <div className="px-6 py-2 bg-slate-50 dark:bg-slate-900 border-t border-slate-200 dark:border-slate-800 text-[10px] text-slate-400 dark:text-slate-500 flex justify-between flex-shrink-0 rounded-b-lg transition-colors">
         <span>ResinDB Visualization Engine v1.3</span>
         {filters.length > 0 && <span>Filtered: {filteredData.length} records</span>}
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer,
  ScatterChart, Scatter, ZAxis, LabelList, Cell
} from 'recharts';
import { Product } from '../types';
import { 
  BarChart2, Activity, TrendingUp, FileJson, FileSpreadsheet, ImageDown,
  Factory, Settings2, Palette, MoveVertical, Filter, Plus, Trash2, X, ChevronDown, ArrowRight, Info, Microscope, PaintBucket
} from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16', '#6366f1'];

interface RangeFilter {
    id: string;
    key: string;
    min: string;
    max: string;
}

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [userXAxisKey, setUserXAxisKey] = useState<string>('');
  const [userYAxisKey, setUserYAxisKey] = useState<string>('');
  const [zAxisKey, setZAxisKey] = useState<string>('none');
  const [colorByKey, setColorByKey] = useState<string>('none');
  const [showTrendline, setShowTrendline] = useState<boolean>(false);
  const [showConfig, setShowConfig] = useState<boolean>(true);
  const [filters, setFilters] = useState<RangeFilter[]>([]);
  const [customColors, setCustomColors] = useState<Record<string, string>>({});
  const [showColorEdit, setShowColorEdit] = useState(false);

  const chartContainerRef = useRef<HTMLDivElement>(null);
  const colorPickerRef = useRef<HTMLDivElement>(null);

  const { t, tProp } = useLanguage();
  const { theme } = useTheme();

  // Close color picker when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (colorPickerRef.current && !colorPickerRef.current.contains(event.target as Node)) {
        setShowColorEdit(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Chart styling constants based on theme
  const chartStyles = useMemo(() => {
    const isDark = theme === 'dark';
    return {
        gridStroke: isDark ? '#334155' : '#e2e8f0', // slate-700 vs slate-200
        axisStroke: isDark ? '#94a3b8' : '#64748b', // slate-400 vs slate-500
        axisTextFill: isDark ? '#94a3b8' : '#64748b',
        tooltipBg: isDark ? '#0f172a' : '#ffffff', // slate-900 vs white
        tooltipBorder: isDark ? '#1e293b' : '#e2e8f0', // slate-800 vs slate-200
        tooltipText: isDark ? '#f8fafc' : '#1e293b', // slate-50 vs slate-800
        barFill: '#3b82f6'
    };
  }, [theme]);

  // 1. Extract Numeric Properties (for X, Y, Z axes)
  const numericProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        const num = Number(val.value);
        if (!isNaN(num) && val.value !== '' && val.value !== null) {
          props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // Filter Logic
  const addFilter = () => {
    if (numericProperties.length > 0) {
        setFilters([...filters, { id: Date.now().toString(), key: numericProperties[0], min: '', max: '' }]);
    }
  };

  const removeFilter = (id: string) => {
    setFilters(filters.filter(f => f.id !== id));
  };

  const updateFilter = (id: string, field: keyof RangeFilter, value: string) => {
    setFilters(filters.map(f => f.id === id ? { ...f, [field]: value } : f));
  };

  // Filtered Data
  const filteredData = useMemo(() => {
    if (filters.length === 0) return data;
    return data.filter(item => {
        return filters.every(f => {
             const valObj = item.properties[f.key];
             if (!valObj) return false;
             const val = Number(valObj.value);
             if (isNaN(val)) return false;

             const min = f.min === '' ? -Infinity : Number(f.min);
             const max = f.max === '' ? Infinity : Number(f.max);

             return val >= min && val <= max;
        });
    });
  }, [data, filters]);

  // 2. Extract Categorical Properties (for Coloring)
  const categoricalProperties = useMemo(() => {
    const props = new Set<string>(['manufacturer']); 
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (typeof val.value === 'string' && val.value.length < 20) {
            props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // 3. Helper to extract units
  const propertyUnits = useMemo(() => {
    const units: Record<string, string> = {};
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (v.unit && !units[k]) units[k] = v.unit;
        });
    });
    return units;
  }, [data]);

  // 4. Calculate Default/Active Keys synchronously
  const activeYKey = useMemo(() => {
    if (userYAxisKey && numericProperties.includes(userYAxisKey)) return userYAxisKey;
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    if (numericProperties.includes('密度')) return '密度';
    return numericProperties[0] || '';
  }, [userYAxisKey, numericProperties]);

  const activeXKey = useMemo(() => {
    if (userXAxisKey && numericProperties.includes(userXAxisKey)) return userXAxisKey;
    if (numericProperties.includes('密度')) return '密度';
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    return numericProperties.length > 1 ? numericProperties[1] : numericProperties[0] || '';
  }, [userXAxisKey, numericProperties]);

  // 5. Transform Data for Recharts
  const chartData = useMemo(() => {
    return filteredData.map(product => {
      const flattened: any = {
        name: product.gradeName,
        manufacturer: product.manufacturer,
        id: product.id
      };

      Object.entries(product.properties).forEach(([key, val]) => {
        const numVal = Number(val.value);
        if (!isNaN(numVal) && val.value !== '' && val.value !== null) {
          flattened[key] = numVal;
        } else {
          flattened[key] = val.value;
        }
      });
      return flattened;
    });
  }, [filteredData]);

  // 6. Group Data for Scatter Series
  const scatterGroups = useMemo(() => {
    if (chartType !== 'scatter' || colorByKey === 'none') return null;

    const groups: Record<string, any[]> = {};
    chartData.forEach(d => {
        const keyVal = d[colorByKey];
        const groupName = keyVal ? String(keyVal) : 'Unclassified';
        if (!groups[groupName]) groups[groupName] = [];
        groups[groupName].push(d);
    });
    return groups;
  }, [chartData, chartType, colorByKey]);

  // 7. Color Map
  const colorMap = useMemo(() => {
    if (colorByKey === 'none') return null;
    const uniqueValues = Array.from(new Set(chartData.map(d => String(d[colorByKey] || 'Unclassified'))));
    const map: Record<string, string> = {};
    uniqueValues.forEach((val, idx) => {
        map[val] = customColors[val] || COLORS[idx % COLORS.length];
    });
    return map;
  }, [chartData, colorByKey, customColors]);

  // Trendline Logic
  const trendlineData = useMemo(() => {
    if (chartType !== 'scatter' || !showTrendline || chartData.length < 2) return [];

    let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0, count = 0;
    chartData.forEach((point) => {
        const x = point[activeXKey];
        const y = point[activeYKey];
        if (typeof x === 'number' && typeof y === 'number') {
            sumX += x; sumY += y; sumXY += x * y; sumXX += x * x; count++;
        }
    });

    if (count < 2) return [];
    const slope = (count * sumXY - sumX * sumY) / (count * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / count;
    const xValues = chartData.map(d => d[activeXKey]).filter(v => typeof v === 'number') as number[];
    if (xValues.length === 0) return [];
    const minX = Math.min(...xValues);
    const maxX = Math.max(...xValues);

    return [
        { [activeXKey]: minX, [activeYKey]: slope * minX + intercept },
        { [activeXKey]: maxX, [activeYKey]: slope * maxX + intercept }
    ];
  }, [chartData, activeXKey, activeYKey, showTrendline, chartType]);

  const handleExportJSON = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(chartData));
    const link = document.createElement('a');
    link.href = dataStr;
    link.download = "chart_data.json";
    link.click();
  };

  const handleExportCSV = () => {
    if (chartData.length === 0) return;
    const allKeys = Array.from(new Set(chartData.flatMap(Object.keys)));
    const header = allKeys.join(',');
    const rows = chartData.map(row => 
      allKeys.map(key => {
        const val = row[key];
        if (val === null || val === undefined) return '';
        const stringVal = String(val);
        if (stringVal.includes(',') || stringVal.includes('"') || stringVal.includes('\n')) {
          return `"${stringVal.replace(/"/g, '""')}"`;
        }
        return stringVal;
      }).join(',')
    );
    const csvContent = [header, ...rows].join('\n');
    const blob = new Blob(["\uFEFF" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'chart_data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleExportPNG = async () => {
    if (!chartContainerRef.current) return;
    try {
        const canvas = await html2canvas(chartContainerRef.current, {
            scale: 2, // High resolution
            backgroundColor: theme === 'dark' ? '#0f172a' : '#ffffff', // slate-900 or white
            logging: false,
            useCORS: true
        });
        const link = document.createElement('a');
        link.download = `chart_${Date.now()}.png`;
        link.href = canvas.toDataURL('image/png');
        link.click();
    } catch (err) {
        console.error("Export failed", err);
    }
  };

  // Determine units for active axes
  const yAxisUnit = propertyUnits[activeYKey];
  const xAxisUnit = propertyUnits[activeXKey];
  const zAxisUnit = zAxisKey !== 'none' ? propertyUnits[zAxisKey] : '';

  // Construct labels with units for the chart axes
  const yAxisLabel = yAxisUnit ? `${tProp(activeYKey)} (${yAxisUnit})` : tProp(activeYKey);
  const xAxisLabel = xAxisUnit ? `${tProp(activeXKey)} (${xAxisUnit})` : tProp(activeXKey);

  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const pointData = payload[0].payload;

      // Calculate dynamic numeric properties to display (excluding axes)
      const dynamicKeys = numericProperties.filter(key => 
        pointData[key] !== undefined && 
        pointData[key] !== null && 
        key !== activeXKey && 
        key !== activeYKey && 
        key !== zAxisKey
      ).sort();

      // Calculate extra text properties (excluding system keys, axes, and color grouping)
      const extraTextKeys = Object.keys(pointData).filter(key => 
        typeof pointData[key] === 'string' &&
        key !== 'name' && 
        key !== 'manufacturer' &&
        key !== 'id' &&
        key !== activeXKey && 
        key !== activeYKey && 
        key !== zAxisKey &&
        key !== colorByKey
      ).slice(0, 3); // Limit to top 3

      return (
        <div className="bg-white dark:bg-slate-900 p-3.5 border border-slate-200 dark:border-slate-800 shadow-xl rounded-lg text-sm min-w-[280px] max-w-[320px] z-50 transition-colors duration-200 backdrop-blur-sm bg-opacity-95 dark:bg-opacity-95">
            <div className="mb-2.5 pb-2.5 border-b border-slate-100 dark:border-slate-800">
                <p className="font-bold text-slate-800 dark:text-slate-100 text-base leading-tight">{pointData.name}</p>
                <div className="flex items-center gap-1.5 text-xs text-slate-500 dark:text-slate-400 mt-1">
                    <Factory size={12} className="text-slate-400 dark:text-slate-500"/>
                    <span>{pointData.manufacturer}</span>
                </div>
            </div>

            <div className="space-y-1.5">
                {/* Main Axes Values Highlighted */}
                 <div className="grid grid-cols-2 gap-2 mb-2">
                    {chartType === 'scatter' && (
                        <div className="flex flex-col bg-slate-50 dark:bg-slate-800/50 p-1.5 rounded">
                            <span className="text-[10px] text-slate-400 dark:text-slate-500 uppercase tracking-wide">{tProp(activeXKey)}</span>
                            <span className="font-mono font-semibold text-blue-700 dark:text-blue-400 text-sm">
                                {pointData[activeXKey]} 
                                {xAxisUnit && <span className="text-[10px] text-slate-400 dark:text-slate-500 ml-1 font-normal">{xAxisUnit}</span>}
                            </span>
                        </div>
                    )}
                    <div className="flex flex-col bg-slate-50 dark:bg-slate-800/50 p-1.5 rounded">
                        <span className="text-[10px] text-slate-400 dark:text-slate-500 uppercase tracking-wide">{tProp(activeYKey)}</span>
                        <span className="font-mono font-semibold text-blue-700 dark:text-blue-400 text-sm">
                            {pointData[activeYKey]} 
                            {yAxisUnit && <span className="text-[10px] text-slate-400 dark:text-slate-500 ml-1 font-normal">{yAxisUnit}</span>}
                        </span>
                    </div>
                 </div>

                 {/* Z Axis Value */}
                 {zAxisKey !== 'none' && (
                    <div className="flex justify-between text-xs bg-slate-50 dark:bg-slate-800/50 p-1 rounded">
                        <span className="text-slate-500 dark:text-slate-400">{tProp(zAxisKey)}:</span>
                        <span className="font-mono font-semibold text-purple-700 dark:text-purple-400">
                            {pointData[zAxisKey]} 
                            {zAxisUnit && <span className="text-[10px] text-slate-400 dark:text-slate-500 ml-1">{zAxisUnit}</span>}
                        </span>
                    </div>
                )}

                {/* Grid for Extra Numeric Properties (Composition, etc) */}
                {dynamicKeys.length > 0 && (
                    <div className="pt-1">
                        <p className="text-[10px] font-semibold text-slate-400 dark:text-slate-500 uppercase tracking-wider mb-1 flex items-center gap-1">
                             <Microscope size={10} />
                             {t('details')}
                        </p>
                        <div className="grid grid-cols-1 gap-1">
                            {dynamicKeys.map(key => (
                                <div key={key} className="flex justify-between items-center text-xs p-1 rounded hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors">
                                    <span className="text-slate-500 dark:text-slate-400 truncate pr-2">{tProp(key)}</span>
                                    <span className="font-mono font-medium text-emerald-700 dark:text-emerald-400 whitespace-nowrap">
                                        {pointData[key]} 
                                        {propertyUnits[key] && <span className="text-[10px] text-slate-400 dark:text-slate-500 ml-0.5">{propertyUnits[key]}</span>}
                                    </span>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {colorByKey !== 'none' && (
                    <div className="flex justify-between text-xs mt-2 pt-2 border-t border-slate-100 dark:border-slate-800">
                        <span className="text-slate-500 dark:text-slate-400">{tProp(colorByKey)}:</span>
                        <span className="font-medium text-slate-800 dark:text-slate-200">{pointData[colorByKey]}</span>
                    </div>
                )}

                {/* Text Properties Section */}
                {extraTextKeys.length > 0 && (
                    <div className="mt-2 pt-2 border-t border-slate-100 dark:border-slate-800 space-y-1">
                        <p className="text-[10px] font-semibold text-slate-400 dark:text-slate-500 uppercase tracking-wider mb-1 flex items-center gap-1">
                             <Info size={10} />
                             {t('otherDetails')}
                        </p>
                        {extraTextKeys.map(key => (
                             <div key={key} className="flex flex-col gap-0.5 text-xs bg-slate-50/50 dark:bg-slate-800/30 p-1 rounded">
                                <span className="text-slate-500 dark:text-slate-400 font-medium text-[10px] uppercase">{tProp(key)}</span>
                                <span className="text-slate-700 dark:text-slate-300 leading-snug break-words">
                                    {pointData[key]}
                                </span>
                             </div>
                        ))}
                    </div>
                )}
            </div>
        </div>
      );
    }
    return null;
  };

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400 dark:text-slate-500 border border-slate-200 dark:border-slate-800 rounded-lg bg-white dark:bg-slate-900 transition-colors">
        <Activity size={48} className="mb-4 text-slate-300 dark:text-slate-600" />
        <p>{t('noProducts')}</p>
      </div>
    );
  }

  if (numericProperties.length === 0) {
     return (
      <div className="flex flex-col items-center justify-center h-96 text-slate-400 dark:text-slate-500 border border-slate-200 dark:border-slate-800 rounded-lg bg-white dark:bg-slate-900 transition-colors">
        <Activity size={48} className="mb-4 text-slate-300 dark:text-slate-600" />
        <p>{t('noNumericData')}</p>
      </div>
    );
  }

  return (
    <div className="bg-white dark:bg-slate-900 rounded-lg shadow-sm border border-slate-200 dark:border-slate-800 flex flex-col w-full transition-colors duration-300" style={{ minHeight: '600px', height: '600px' }}>

      {/* Configuration Header */}
      <div className="border-b border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-900/50 flex-shrink-0 transition-colors">
        <div className="p-3 px-4 flex items-center justify-between">
            <div className="flex items-center gap-2 text-slate-800 dark:text-slate-200 font-semibold">
                <Settings2 size={18} className="text-blue-600 dark:text-blue-400" />
                <span>{t('chartConfig')}</span>
            </div>
            <div className="flex gap-2">
                 <button 
                    onClick={() => setShowConfig(!showConfig)}
                    className="text-xs text-blue-600 dark:text-blue-400 hover:text-blue-700 dark:hover:text-blue-300 font-medium px-2 py-1 rounded hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors"
                >
                    {showConfig ? t('collapseConfig') : t('expandConfig')}
                </button>
                 <div className="h-4 w-px bg-slate-300 dark:bg-slate-700 self-center mx-1"></div>
                 <button onClick={handleExportJSON} className="text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200" title={t('exportJson')}><FileJson size={16}/></button>
                 <button onClick={handleExportCSV} className="text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200" title={t('exportCsv')}><FileSpreadsheet size={16}/></button>
                 <button onClick={handleExportPNG} className="text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200" title={t('exportPng')}><ImageDown size={16}/></button>
            </div>
        </div>

        {showConfig && (
            <div className="p-4 pt-0 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 animate-in slide-in-from-top-2 duration-200">
                {/* 1. Chart Type */}
                <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center gap-1">
                        <Activity size={12}/> {t('chartType')}
                    </label>
                    <div className="flex bg-white dark:bg-slate-800 rounded-md border border-slate-200 dark:border-slate-700 p-1 transition-colors">
                        <button
                        onClick={() => setChartType('bar')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'bar' ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400 shadow-sm' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
                        }`}
                        >
                        <BarChart2 size={14} /> {t('barChart')}
                        </button>
                        <button
                        onClick={() => setChartType('scatter')}
                        className={`flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-xs font-medium rounded transition-colors ${
                            chartType === 'scatter' ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400 shadow-sm' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
                        }`}
                        >
                        <Activity size={14} /> {t('scatterChart')}
                        </button>
                    </div>
                </div>

                {/* 2. Axes Configuration */}
                <div className="space-y-1.5 lg:col-span-2">
                    <label className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center gap-1">
                        <MoveVertical size={12}/> {t('axisMapping')}
                    </label>
                    <div className="flex gap-2">
                        {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={activeXKey} onChange={(e) => setUserXAxisKey(e.target.value)}
                                    className="w-full bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5 transition-colors"
                                >
                                    {numericProperties.map(p => <option key={p} value={p}>{t('xAxis')}: {tProp(p)}</option>)}
                                </select>
                             </div>
                        )}

                        <div className="flex-1 min-w-[120px]">
                            <select 
                                value={activeYKey} onChange={(e) => setUserYAxisKey(e.target.value)}
                                className="w-full bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5 transition-colors"
                            >
                                {numericProperties.map(p => <option key={p} value={p}>{chartType === 'bar' ? t('val') : t('yAxis')}: {tProp(p)}</option>)}
                            </select>
                        </div>

                         {chartType === 'scatter' && (
                             <div className="flex-1 min-w-[120px]">
                                <select 
                                    value={zAxisKey} onChange={(e) => setZAxisKey(e.target.value)}
                                    className="w-full bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5 transition-colors"
                                >
                                    <option value="none">{t('zAxis')}: {t('noneAxis')}</option>
                                    {numericProperties.map(p => <option key={p} value={p}>{t('zAxis')}: {tProp(p)}</option>)}
                                </select>
                             </div>
                        )}
                    </div>
                </div>

                {/* 3. Style & Color */}
                <div className="space-y-1.5 relative">
                    <label className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center gap-1">
                        <Palette size={12}/> {t('styleGrouping')}
                    </label>
                    <div className="flex gap-2 items-center">
                         <select 
                            value={colorByKey} onChange={(e) => setColorByKey(e.target.value)}
                            className="flex-1 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded shadow-sm focus:ring-blue-500 focus:border-blue-500 p-1.5 transition-colors"
                        >
                            <option value="none">{t('colorSingle')}</option>
                            <optgroup label="Properties">
                                {categoricalProperties.map(p => <option key={p} value={p}>{t('groupBy').replace('{key}', tProp(p))}</option>)}
                            </optgroup>
                        </select>
                        {chartType === 'scatter' && (
                             <button
                                onClick={() => setShowTrendline(!showTrendline)}
                                title={t('trendline')}
                                className={`p-1.5 rounded border transition-colors ${showTrendline ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 border-blue-200 dark:border-blue-800' : 'bg-white dark:bg-slate-800 text-slate-400 dark:text-slate-500 border-slate-200 dark:border-slate-700'}`}
                             >
                                 <TrendingUp size={16} />
                             </button>
                        )}
                        {colorByKey !== 'none' && (
                             <button
                                onClick={() => setShowColorEdit(!showColorEdit)}
                                title="Customize Colors"
                                className={`p-1.5 rounded border transition-colors ${showColorEdit ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 border-blue-200 dark:border-blue-800' : 'bg-white dark:bg-slate-800 text-slate-400 dark:text-slate-500 border-slate-200 dark:border-slate-700'}`}
                             >
                                 <PaintBucket size={16} />
                             </button>
                        )}
                    </div>

                    {/* Custom Color Picker Popover */}
                    {showColorEdit && colorByKey !== 'none' && colorMap && (
                        <div ref={colorPickerRef} className="absolute top-full left-0 right-0 z-20 mt-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg shadow-xl p-3 animate-in fade-in zoom-in-95 duration-200 min-w-[240px]">
                            <div className="flex justify-between items-center mb-2 pb-2 border-b border-slate-100 dark:border-slate-800">
                                <span className="text-xs font-semibold text-slate-700 dark:text-slate-300">Series Colors</span>
                                <button onClick={() => setCustomColors({})} className="text-[10px] text-blue-600 hover:text-blue-700 dark:text-blue-400 hover:underline">Reset All</button>
                            </div>
                            <div className="max-h-48 overflow-y-auto custom-scrollbar space-y-1.5 pr-1">
                                {Object.entries(colorMap).map(([label, color]) => (
                                    <div key={label} className="flex items-center justify-between text-xs group">
                                        <span className="truncate text-slate-600 dark:text-slate-400 max-w-[140px]" title={label}>{label}</span>
                                        <div className="flex items-center gap-2">
                                            <input 
                                                type="color" 
                                                value={color} 
                                                onChange={(e) => setCustomColors(prev => ({ ...prev, [label]: e.target.value }))}
                                                className="w-5 h-5 p-0 border-none rounded cursor-pointer bg-transparent" 
                                            />
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                </div>

                {/* 4. Data Filters */}
                <div className="space-y-1.5 lg:col-span-4 border-t border-slate-200 dark:border-slate-800 pt-3 mt-1">
                    <div className="flex items-center justify-between">
                        <label className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center gap-1">
                            <Filter size={12}/> {t('dataFilters')}
                        </label>
                        <button 
                            onClick={addFilter}
                            className="flex items-center gap-1 text-[10px] font-medium text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/20 hover:bg-blue-100 dark:hover:bg-blue-900/40 px-2 py-1 rounded-md transition-colors"
                        >
                            <Plus size={12}/> {t('addFilter')}
                        </button>
                    </div>

                    {filters.length === 0 ? (
                        <p className="text-[10px] text-slate-400 dark:text-slate-600 italic pl-1">{t('noFilters')}</p>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3 mt-2">
                            {filters.map(filter => (
                                <div key={filter.id} className="bg-white dark:bg-slate-800 p-2.5 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm group animate-in fade-in zoom-in-95 duration-200 hover:shadow-md hover:border-emerald-500/30 dark:hover:border-emerald-500/30 transition-all">
                                    <div className="flex items-center justify-between gap-2 mb-2">
                                        <div className="flex-1 relative">
                                            <select 
                                                value={filter.key} 
                                                onChange={(e) => updateFilter(filter.id, 'key', e.target.value)}
                                                className="w-full text-xs font-semibold bg-transparent border-none p-0 pr-4 focus:ring-0 text-slate-700 dark:text-slate-200 cursor-pointer appearance-none truncate"
                                            >
                                                {numericProperties.map(p => <option key={p} value={p}>{tProp(p)}</option>)}
                                            </select>
                                            {/* Tiny triangle indicator for select */}
                                            <div className="absolute right-0 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                                                <ChevronDown size={10} />
                                            </div>
                                        </div>
                                        <button 
                                            onClick={() => removeFilter(filter.id)} 
                                            className="text-slate-400 hover:text-red-500 dark:text-slate-500 dark:hover:text-red-400 transition-colors p-0.5 rounded hover:bg-red-50 dark:hover:bg-red-900/20"
                                        >
                                            <X size={14}/>
                                        </button>
                                    </div>

                                    <div className="flex items-center gap-2">
                                        <div className="flex-1 flex items-center bg-slate-50 dark:bg-slate-900 rounded border border-slate-200 dark:border-slate-700 px-2 py-1.5 focus-within:ring-1 focus-within:ring-emerald-500/50 focus-within:border-emerald-500/50 transition-all">
                                            <span className="text-[10px] font-medium text-slate-400 mr-1.5 select-none">{t('min')}</span>
                                            <input 
                                                type="number" 
                                                value={filter.min}
                                                onChange={(e) => updateFilter(filter.id, 'min', e.target.value)}
                                                placeholder="-"
                                                className="w-full bg-transparent border-none p-0 text-xs font-mono focus:ring-0 text-slate-700 dark:text-slate-200 placeholder:text-slate-300 dark:placeholder:text-slate-600"
                                            />
                                        </div>
                                        <div className="text-slate-300 dark:text-slate-600">
                                            <ArrowRight size={12} />
                                        </div>
                                        <div className="flex-1 flex items-center bg-slate-50 dark:bg-slate-900 rounded border border-slate-200 dark:border-slate-700 px-2 py-1.5 focus-within:ring-1 focus-within:ring-emerald-500/50 focus-within:border-emerald-500/50 transition-all">
                                            <span className="text-[10px] font-medium text-slate-400 mr-1.5 select-none">{t('max')}</span>
                                            <input 
                                                type="number" 
                                                value={filter.max}
                                                onChange={(e) => updateFilter(filter.id, 'max', e.target.value)}
                                                placeholder="-"
                                                className="w-full bg-transparent border-none p-0 text-xs font-mono focus:ring-0 text-slate-700 dark:text-slate-200 placeholder:text-slate-300 dark:placeholder:text-slate-600"
                                            />
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        )}
      </div>

      {/* Chart Canvas */}
      <div ref={chartContainerRef} className="flex-1 p-6 relative w-full h-full bg-white dark:bg-slate-900 transition-colors">
        {activeYKey && (
            <ResponsiveContainer width="100%" height="100%">
            {chartType === 'bar' ? (
                <BarChart
                data={chartData}
                margin={{ top: 20, right: 30, left: 40, bottom: 40 }}
                >
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={chartStyles.gridStroke} />
                <XAxis 
                    dataKey="name" 
                    stroke={chartStyles.axisStroke} 
                    fontSize={12} 
                    tickLine={false} 
                    axisLine={{ stroke: chartStyles.axisStroke }} 
                    interval={0} 
                    angle={-30} 
                    textAnchor="end" 
                    height={60} 
                />
                <YAxis 
                    stroke={chartStyles.axisStroke} 
                    fontSize={12} 
                    tickLine={false} 
                    axisLine={{ stroke: chartStyles.axisStroke }} 
                    domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { textAnchor: 'middle', fill: chartStyles.axisTextFill } }} 
                />
                <RechartsTooltip content={<CustomTooltip />} cursor={{ fill: theme === 'dark' ? '#1e293b' : '#f1f5f9' }} />
                <Legend wrapperStyle={{ color: chartStyles.axisTextFill }}/>
                <Bar 
                    dataKey={activeYKey} 
                    fill="#3b82f6" 
                    radius={[4, 4, 0, 0]} 
                    name={yAxisLabel} 
                    barSize={40}
                    isAnimationActive={false}
                >
                    {colorByKey !== 'none' && chartData.map((entry, index) => {
                        const val = String(entry[colorByKey] || 'Unclassified');
                        return <Cell key={`cell-${index}`} fill={colorMap?.[val] || '#3b82f6'} />;
                    })}
                    <LabelList dataKey={activeYKey} position="top" fill={chartStyles.axisTextFill} fontSize={12} formatter={(val: number) => val.toFixed(2)} />
                </Bar>
                </BarChart>
            ) : (
                <ScatterChart margin={{ top: 20, right: 20, bottom: 20, left: 40 }}>
                <CartesianGrid strokeDasharray="3 3" stroke={chartStyles.gridStroke} />
                <XAxis 
                    type="number" dataKey={activeXKey} name={activeXKey} stroke={chartStyles.axisStroke} fontSize={12} domain={['auto', 'auto']}
                    label={{ value: xAxisLabel, position: 'bottom', offset: 0, style: { fill: chartStyles.axisTextFill } }} 
                />
                <YAxis 
                    type="number" dataKey={activeYKey} name={activeYKey} stroke={chartStyles.axisStroke} fontSize={12} domain={['auto', 'auto']}
                    label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', style: { fill: chartStyles.axisTextFill } }} 
                />
                {zAxisKey !== 'none' && (
                    <ZAxis type="number" dataKey={zAxisKey} range={[60, 600]} name={zAxisKey} unit={zAxisUnit} />
                )}

                <RechartsTooltip content={<CustomTooltip />} cursor={{ strokeDasharray: '3 3' }} />
                <Legend wrapperStyle={{ color: chartStyles.axisTextFill }} />

                {colorByKey !== 'none' && scatterGroups ? (
                    Object.entries(scatterGroups).map(([groupName, groupData], index) => (
                        <Scatter 
                            key={groupName}
                            name={groupName}
                            data={groupData}
                            fill={colorMap?.[groupName] || COLORS[index % COLORS.length]}
                            isAnimationActive={false}
                        />
                    ))
                ) : (
                    <Scatter name={t('chartTitle')} data={chartData} fill="#3b82f6" isAnimationActive={false} />
                )}

                {showTrendline && trendlineData.length > 0 && (
                    <Scatter name={t('trendline')} data={trendlineData} line={{ stroke: '#ef4444', strokeWidth: 2, strokeDasharray: '5 5' }} shape={() => null} legendType="none" tooltipType="none" isAnimationActive={false}/>
                )}
                </ScatterChart>
            )}
            </ResponsiveContainer>
        )}

        {chartType === 'bar' && colorByKey !== 'none' && colorMap && !showColorEdit && (
             <div className="absolute top-4 right-6 bg-white/90 dark:bg-slate-800/90 p-2 rounded border border-slate-200 dark:border-slate-700 text-xs shadow-sm max-w-[150px] transition-colors">
                 <p className="font-semibold text-slate-500 dark:text-slate-400 mb-1 border-b border-slate-100 dark:border-slate-700 pb-1">{t('groupBy').replace('{key}', tProp(colorByKey))}</p>
                 <div className="space-y-1 max-h-[100px] overflow-y-auto custom-scrollbar">
                     {Object.entries(colorMap).map(([label, color]) => (
                         <div key={label} className="flex items-center gap-2">
                             <div className="w-2 h-2 rounded-full" style={{ backgroundColor: color }}></div>
                             <span className="truncate text-slate-600 dark:text-slate-300" title={label}>{label}</span>
                         </div>
                     ))}
                 </div>
             </div>
        )}
      </div>

      <div className="px-6 py-2 bg-slate-50 dark:bg-slate-900 border-t border-slate-200 dark:border-slate-800 text-[10px] text-slate-400 dark:text-slate-500 flex justify-between flex-shrink-0 rounded-b-lg transition-colors">
         <span>ResinDB Visualization Engine v1.3</span>
         {filters.length > 0 && <span>Filtered: {filteredData.length} records</span>}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { X, Save, Plus, Trash2, Beaker, Factory } from 'lucide-react';
import { Product, PropertyValue } from '../types';
import { useLanguage } from '../contexts/LanguageContext';

interface EditProductModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (product: Product) => void;
  product: Product | null;
}

interface PropertyRow {
  id: string;
  key: string;
  value: string;
  unit: string;
}

export const EditProductModal: React.FC<EditProductModalProps> = ({ isOpen, onClose, onSave, product }) => {
  const { t } = useLanguage();
  const [formData, setFormData] = useState<Partial<Product>>({});
  const [propertyRows, setPropertyRows] = useState<PropertyRow[]>([]);

  useEffect(() => {
    if (product) {
      setFormData({
        id: product.id,
        gradeName: product.gradeName,
        manufacturer: product.manufacturer,
        categoryIds: product.categoryIds,
        updatedAt: product.updatedAt,
      });

      const rows: PropertyRow[] = Object.entries(product.properties).map(([key, val], index) => ({
        id: `prop-${index}-${Date.now()}`,
        key,
        value: String(val.value),
        unit: val.unit || ''
      }));
      setPropertyRows(rows);
    }
  }, [product, isOpen]);

  if (!isOpen || !product) return null;

  const handleSave = () => {
    const newProperties: Record<string, PropertyValue> = {};
    propertyRows.forEach(row => {
      if (row.key.trim()) {
        const numVal = Number(row.value);
        newProperties[row.key] = {
          value: !isNaN(numVal) && row.value.trim() !== '' ? numVal : row.value,
          unit: row.unit.trim() || undefined
        };
      }
    });

    onSave({
      ...product,
      ...formData as Product,
      properties: newProperties,
      updatedAt: new Date().toISOString().split('T')[0] // Auto update timestamp
    });
    onClose();
  };

  const addProperty = () => {
    setPropertyRows([...propertyRows, { id: `new-${Date.now()}`, key: '', value: '', unit: '' }]);
  };

  const removeProperty = (id: string) => {
    setPropertyRows(propertyRows.filter(p => p.id !== id));
  };

  const updateProperty = (id: string, field: keyof PropertyRow, val: string) => {
    setPropertyRows(propertyRows.map(p => p.id === id ? { ...p, [field]: val } : p));
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="w-full max-w-2xl bg-white dark:bg-slate-900 rounded-xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200 ring-1 ring-slate-200 dark:ring-slate-800 flex flex-col max-h-[90vh]">

        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/50">
          <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 flex items-center justify-center">
                <Beaker size={18} />
            </div>
            {t('editProduct')}
          </h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors">
            <X size={20} />
          </button>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">

            {/* Basic Info Section */}
            <div className="mb-6">
                <h4 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-4 border-b border-slate-100 dark:border-slate-800 pb-2">
                    {t('basicInfo')}
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                        <label className="text-sm font-medium text-slate-700 dark:text-slate-300">{tProp('牌号')}</label>
                        <input 
                            type="text" 
                            value={formData.gradeName || ''}
                            onChange={(e) => setFormData({...formData, gradeName: e.target.value})}
                            className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all"
                        />
                    </div>
                    <div className="space-y-1.5">
                        <label className="text-sm font-medium text-slate-700 dark:text-slate-300">{tProp('生产厂家')}</label>
                        <div className="relative">
                            <Factory size={16} className="absolute left-3 top-2.5 text-slate-400" />
                            <input 
                                type="text" 
                                value={formData.manufacturer || ''}
                                onChange={(e) => setFormData({...formData, manufacturer: e.target.value})}
                                className="w-full pl-9 pr-3 py-2 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all"
                            />
                        </div>
                    </div>
                </div>
            </div>

            {/* Dynamic Properties Section */}
            <div>
                <div className="flex items-center justify-between mb-4 border-b border-slate-100 dark:border-slate-800 pb-2">
                    <h4 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                        {t('properties')}
                    </h4>
                    <button 
                        onClick={addProperty}
                        className="text-xs flex items-center gap-1 text-emerald-600 dark:text-emerald-400 hover:text-emerald-700 font-medium px-2 py-1 rounded hover:bg-emerald-50 dark:hover:bg-emerald-900/20 transition-colors"
                    >
                        <Plus size={14} /> {t('addProperty')}
                    </button>
                </div>

                <div className="space-y-2">
                    {propertyRows.map((row) => (
                        <div key={row.id} className="flex items-center gap-2 group">
                            <input 
                                type="text" 
                                placeholder={t('propertyName')}
                                value={row.key}
                                onChange={(e) => updateProperty(row.id, 'key', e.target.value)}
                                className="flex-1 px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md text-sm focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 outline-none"
                            />
                            <input 
                                type="text" 
                                placeholder={t('propertyValue')}
                                value={row.value}
                                onChange={(e) => updateProperty(row.id, 'value', e.target.value)}
                                className="flex-1 px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md text-sm focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 outline-none font-mono"
                            />
                            <input 
                                type="text" 
                                placeholder={t('propertyUnit')}
                                value={row.unit}
                                onChange={(e) => updateProperty(row.id, 'unit', e.target.value)}
                                className="w-20 px-3 py-2 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-md text-sm text-slate-500 focus:border-emerald-500 outline-none"
                            />
                            <button 
                                onClick={() => removeProperty(row.id)}
                                className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-md transition-colors opacity-0 group-hover:opacity-100 focus:opacity-100"
                                title={t('delete')}
                            >
                                <Trash2 size={16} />
                            </button>
                        </div>
                    ))}
                    {propertyRows.length === 0 && (
                        <div className="text-center py-6 text-slate-400 dark:text-slate-600 text-sm italic border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-lg">
                            No properties defined. Click "Add Property" to start.
                        </div>
                    )}
                </div>
            </div>

        </div>

        {/* Footer */}
        <div className="p-4 border-t border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/50 flex justify-end gap-3">
            <button 
                onClick={onClose}
                className="px-4 py-2 text-sm font-medium text-slate-600 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors"
            >
                {t('cancel')}
            </button>
            <button 
                onClick={handleSave}
                className="px-4 py-2 text-sm font-medium text-white bg-emerald-600 hover:bg-emerald-700 rounded-lg shadow-md shadow-emerald-500/20 flex items-center gap-2 transition-all active:scale-95"
            >
                <Save size={16} />
                {t('save')}
            </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Product, ColumnConfig } from '../types';
import { MoreHorizontal, FileText, Factory, CalendarClock, Edit, Trash2, CheckSquare, Square, MinusSquare } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { EditProductModal } from './EditProductModal';

interface DataGridProps {
  data: Product[];
  columns: ColumnConfig[];
  isLoading: boolean;
  onDelete: (ids: string[]) => void;
  onUpdate: (product: Product) => void;
}

export const DataGrid: React.FC<DataGridProps> = ({ data, columns, isLoading, onDelete, onUpdate }) => {
  const { t, tProp } = useLanguage();
  const visibleColumns = columns.filter((c) => c.visible);

  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);

  // Clear selection when data changes significantly (e.g. filter change), 
  // but keeping it simple: just persist unless manually cleared or deleted.
  // Actually, we should clean up IDs that are no longer in data if we care about consistency,
  // but for a view filter, it might be annoying to lose selection. 

  const isAllSelected = data.length > 0 && selectedIds.size === data.length;
  const isIndeterminate = selectedIds.size > 0 && selectedIds.size < data.length;

  const toggleSelectAll = () => {
    if (isAllSelected) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(data.map(p => p.id)));
    }
  };

  const toggleSelectRow = (id: string) => {
    const newSet = new Set(selectedIds);
    if (newSet.has(id)) {
      newSet.delete(id);
    } else {
      newSet.add(id);
    }
    setSelectedIds(newSet);
  };

  const handleBatchDelete = () => {
    if (window.confirm(`${t('confirmDelete')} ${selectedIds.size} ${t('items')}?`)) {
        onDelete(Array.from(selectedIds));
        setSelectedIds(new Set());
    }
  };

  const handleDeleteSingle = (id: string) => {
      if (window.confirm(t('confirmDelete') + '?')) {
          onDelete([id]);
          if(selectedIds.has(id)) {
              const newSet = new Set(selectedIds);
              newSet.delete(id);
              setSelectedIds(newSet);
          }
      }
  };

  const isNumericColumn = (key: string) => {
    if (['gradeName', 'manufacturer', 'updatedAt'].includes(key)) return false;
    for (const p of data.slice(0, 5)) {
        const val = p.properties[key]?.value;
        if (val !== undefined && val !== null && val !== '') {
             if (typeof val === 'number') return true;
             if (!isNaN(Number(val))) return true;
        }
    }
    return false;
  };

  if (isLoading) {
    return (
        <div className="flex flex-col items-center justify-center h-64 text-slate-400 dark:text-slate-500">
            <div className="w-8 h-8 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin mb-4 shadow-[0_0_10px_rgba(16,185,129,0.2)]"></div>
            <span className="text-sm font-medium">{t('loading')}</span>
        </div>
    );
  }

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-[500px] text-slate-400 dark:text-slate-500 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm">
        <div className="w-16 h-16 bg-slate-50 dark:bg-slate-800 rounded-full flex items-center justify-center mb-4 transition-colors">
            <FileText size={32} className="text-slate-300 dark:text-slate-600" />
        </div>
        <p className="text-lg font-semibold text-slate-700 dark:text-slate-300">{t('noProducts')}</p>
        <p className="text-sm text-slate-500 dark:text-slate-500 mt-1">{t('noProductsDesc')}</p>
      </div>
    );
  }

  return (
    <>
    <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden flex flex-col h-full transition-colors duration-300 relative">

      {/* Batch Action Toolbar */}
      {selectedIds.size > 0 && (
          <div className="absolute top-0 left-0 right-0 z-20 h-[50px] bg-emerald-50 dark:bg-emerald-900/30 border-b border-emerald-100 dark:border-emerald-800/50 flex items-center justify-between px-5 animate-in slide-in-from-top-2 duration-200">
              <div className="flex items-center gap-3 text-sm font-medium text-emerald-800 dark:text-emerald-300">
                  <div className="flex items-center justify-center w-5 h-5 bg-emerald-600 rounded text-white">
                      <MinusSquare size={14} />
                  </div>
                  <span>{selectedIds.size} {t('selected')}</span>
              </div>
              <div className="flex gap-2">
                  <button 
                    onClick={handleBatchDelete}
                    className="flex items-center gap-1.5 px-3 py-1.5 bg-white dark:bg-slate-800 text-rose-600 dark:text-rose-400 border border-rose-200 dark:border-rose-900/50 rounded-lg hover:bg-rose-50 dark:hover:bg-rose-900/20 text-xs font-semibold transition-colors shadow-sm"
                  >
                      <Trash2 size={14} />
                      {t('batchDelete')}
                  </button>
              </div>
          </div>
      )}

      <div className="overflow-x-auto overflow-y-auto custom-scrollbar flex-1">
        <table className="w-full text-sm text-left border-collapse">
          <thead className="text-xs text-slate-500 dark:text-slate-400 uppercase bg-slate-50/80 dark:bg-slate-900/90 sticky top-0 z-10 backdrop-blur-sm">
            <tr>
              <th className="w-10 px-5 py-3.5 border-b border-slate-200 dark:border-slate-800 bg-slate-50/80 dark:bg-slate-900/90">
                 <div 
                    onClick={toggleSelectAll}
                    className="cursor-pointer text-slate-400 hover:text-emerald-600 dark:hover:text-emerald-500 transition-colors"
                 >
                     {isAllSelected ? <CheckSquare size={18} className="text-emerald-600 dark:text-emerald-500"/> : (isIndeterminate ? <MinusSquare size={18} className="text-emerald-600 dark:text-emerald-500"/> : <Square size={18}/>)}
                 </div>
              </th>
              {visibleColumns.map((col) => {
                  const isNum = isNumericColumn(col.key);
                  return (
                      <th key={col.key} className={`px-5 py-3.5 font-semibold border-b border-slate-200 dark:border-slate-800 whitespace-nowrap bg-slate-50/80 dark:bg-slate-900/90 transition-colors ${isNum ? 'text-right' : 'text-left'}`}>
                          {tProp(col.label)}
                      </th>
                  );
              })}
              <th className="px-5 py-3.5 text-right border-b border-slate-200 dark:border-slate-800 bg-slate-50/80 dark:bg-slate-900/90 sticky right-0 z-20 w-24 backdrop-blur-sm transition-colors">
                  {t('actions')}
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 dark:divide-slate-800/50 bg-white dark:bg-slate-900">
            {data.map((product) => {
              const isSelected = selectedIds.has(product.id);
              return (
                <tr 
                    key={product.id} 
                    className={`hover:bg-slate-50/80 dark:hover:bg-slate-800/40 transition-colors group ${isSelected ? 'bg-emerald-50/30 dark:bg-emerald-900/10' : ''}`}
                >
                  <td className="px-5 py-3 border-b border-slate-100 dark:border-slate-800/50">
                      <div 
                        onClick={() => toggleSelectRow(product.id)}
                        className="cursor-pointer text-slate-300 hover:text-emerald-600 dark:text-slate-600 dark:hover:text-emerald-500 transition-colors"
                      >
                         {isSelected ? <CheckSquare size={18} className="text-emerald-600 dark:text-emerald-500"/> : <Square size={18}/>}
                      </div>
                  </td>
                  {visibleColumns.map((col) => {
                    const isNum = isNumericColumn(col.key);
                    let content: React.ReactNode = <span className="text-slate-200 dark:text-slate-700">-</span>;

                    if (col.key === 'gradeName') {
                        content = (
                          <div className="flex items-center gap-2">
                               <div className="w-2 h-2 rounded-full bg-emerald-500/50 dark:bg-emerald-500/80 shadow-[0_0_6px_rgba(16,185,129,0.3)]"></div>
                               <span className="font-bold text-slate-700 dark:text-slate-200 group-hover:text-emerald-700 dark:group-hover:text-emerald-400 transition-colors">{product.gradeName}</span>
                          </div>
                        );
                    } else if (col.key === 'manufacturer') {
                        content = (
                            <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400">
                                <Factory size={13} className="text-slate-400 dark:text-slate-600" />
                                <span className="truncate max-w-[180px]" title={product.manufacturer}>{product.manufacturer}</span>
                            </div>
                        );
                    } else if (col.key === 'updatedAt') {
                        content = (
                          <div className="flex items-center gap-1.5 text-slate-400 dark:text-slate-500 text-xs">
                               <CalendarClock size={12}/>
                               <span className="font-mono">{product.updatedAt}</span>
                          </div>
                        );
                    } else {
                        const prop = product.properties[col.key];
                        if (prop && prop.value !== undefined && prop.value !== null && prop.value !== '') {
                            content = (
                                <span className="inline-flex items-baseline text-slate-700 dark:text-slate-300">
                                    {prop.value} 
                                    {prop.unit && <span className="text-slate-400 dark:text-slate-500 text-[10px] ml-1 font-medium">{prop.unit}</span>}
                                </span>
                            );
                        }
                    }

                    return (
                      <td key={`${product.id}-${col.key}`} className={`px-5 py-3 border-b border-slate-100 dark:border-slate-800/50 whitespace-nowrap transition-colors ${isNum ? 'text-right font-mono' : ''}`}>
                        {content}
                      </td>
                    );
                  })}
                  <td className="px-5 py-3 text-right border-b border-slate-100 dark:border-slate-800/50 sticky right-0 bg-white dark:bg-slate-900 group-hover:bg-slate-50/80 dark:group-hover:bg-slate-800/40 transition-colors">
                    <div className="flex items-center justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button 
                            onClick={() => setEditingProduct(product)}
                            className="p-1.5 rounded-md text-slate-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors"
                            title={t('edit')}
                        >
                            <Edit size={16} />
                        </button>
                        <button 
                            onClick={() => handleDeleteSingle(product.id)}
                            className="p-1.5 rounded-md text-slate-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"
                            title={t('delete')}
                        >
                            <Trash2 size={16} />
                        </button>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      <div className="px-5 py-3 border-t border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-900 text-xs text-slate-500 dark:text-slate-400 flex justify-between items-center sticky bottom-0 z-20 transition-colors flex-shrink-0">
         <span>{t('showing')} {data.length} {t('records')}</span>
         <div className="flex gap-2">
             <span className="px-2 py-0.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded text-slate-400 dark:text-slate-300">{t('page')} 1</span>
         </div>
      </div>
    </div>

    <EditProductModal 
        isOpen={!!editingProduct} 
        onClose={() => setEditingProduct(null)} 
        product={editingProduct} 
        onSave={(updated) => {
            onUpdate(updated);
            setEditingProduct(null);
        }}
    />
    </>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { CATEGORY_TREE, MOCK_PRODUCTS } from './constants';
import { Product, ColumnConfig, ViewMode } from './types';
import { TreeSidebar } from './components/TreeSidebar';
import { DataGrid } from './components/DataGrid';
import { DataVisualizer } from './components/DataVisualizer';
import { TopBar } from './components/TopBar';
import { ImportModal } from './components/ImportModal';
import { AIAssistant } from './components/AIAssistant';
import { LayoutDashboard, Database, Activity } from 'lucide-react';
import { LanguageProvider } from './contexts/LanguageContext';
import { ThemeProvider } from './contexts/ThemeContext';

const getDynamicColumns = (products: Product[]): ColumnConfig[] => {
  const propertyKeys = new Set<string>();
  products.forEach(p => {
    Object.keys(p.properties).forEach(k => propertyKeys.add(k));
  });

  const defaultVisible = ['密度', '熔体流动速率', '应用', '类型', '典型应用', '硬度', '悬臂梁缺口冲击', '拉伸强度'];

  const dynamicCols: ColumnConfig[] = Array.from(propertyKeys).map(key => ({
    key,
    label: key,
    visible: defaultVisible.includes(key),
    isSystem: false
  })).sort((a, b) => {
      // Prioritize numeric columns slightly for better default view
      const aIsLikelyImportant = defaultVisible.includes(a.key);
      const bIsLikelyImportant = defaultVisible.includes(b.key);
      if (aIsLikelyImportant && !bIsLikelyImportant) return -1;
      if (!aIsLikelyImportant && bIsLikelyImportant) return 1;
      return a.label.localeCompare(b.label);
  });

  const systemCols: ColumnConfig[] = [
    { key: 'gradeName', label: '牌号', visible: true, isSystem: true },
    { key: 'manufacturer', label: '生产厂家', visible: true, isSystem: true },
    { key: 'updatedAt', label: '更新时间', visible: false, isSystem: false },
  ];

  return [...systemCols, ...dynamicCols];
};

const AppContent: React.FC = () => {
  // State for products to allow updates/imports
  const [allProducts, setAllProducts] = useState<Product[]>(MOCK_PRODUCTS);
  const [selectedCategoryId, setSelectedCategoryId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [columns, setColumns] = useState<ColumnConfig[]>([]);
  const [isImportOpen, setIsImportOpen] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>('grid');

  // Initialize columns based on initial data
  useEffect(() => {
    setColumns(getDynamicColumns(allProducts));
  }, []); // Run once on mount

  // Update columns if new properties appear in data (optional, but good for robustness)
  useEffect(() => {
     // We only update if the number of potential columns has changed to avoid resetting user preference too often
     // For a prototype, re-calculating on data change is acceptable behavior
     const newCols = getDynamicColumns(allProducts);
     if (newCols.length !== columns.length) {
         setColumns(newCols);
     }
  }, [allProducts.length]);

  const handleToggleColumn = (key: string) => {
    setColumns(cols => cols.map(c => 
      c.key === key ? { ...c, visible: !c.visible } : c
    ));
  };

  const handleToggleAllColumns = (visible: boolean) => {
    setColumns(cols => cols.map(c => 
      c.isSystem ? c : { ...c, visible }
    ));
  };

  // Simulate importing data
  const handleImportData = () => {
      const newProducts: Product[] = Array.from({ length: 5 }).map((_, i) => ({
        id: `imported-${Date.now()}-${i}`,
        gradeName: `New-Grade-${1000 + i} (Imported)`,
        manufacturer: 'Synthetic Tech Inc.',
        categoryIds: ['cat_pe', 'cat_packaging'],
        updatedAt: new Date().toISOString().split('T')[0],
        properties: {
          '密度': { value: 0.92 + (Math.random() * 0.05), unit: 'g/cm³' },
          '熔体流动速率': { value: 1 + (Math.random() * 5), unit: 'g/10min' },
          '应用': { value: 'Imported batch test' }
        }
      }));

      setAllProducts(prev => [...newProducts, ...prev]);
      setIsImportOpen(false);
  };

  // Logic to delete products
  const handleDeleteProducts = (ids: string[]) => {
    setAllProducts(prev => prev.filter(p => !ids.includes(p.id)));
  };

  // Logic to update a single product
  const handleUpdateProduct = (updatedProduct: Product) => {
    setAllProducts(prev => prev.map(p => p.id === updatedProduct.id ? updatedProduct : p));
  };

  const filteredData = useMemo(() => {
    return allProducts.filter(product => {
      const matchesCategory = selectedCategoryId 
        ? product.categoryIds.includes(selectedCategoryId)
        : true;

      if (!matchesCategory) return false;

      const query = searchQuery.toLowerCase();
      const matchesSearch = 
        product.gradeName.toLowerCase().includes(query) ||
        product.manufacturer.toLowerCase().includes(query) ||
        Object.keys(product.properties).some(k => k.toLowerCase().includes(query));

      return matchesSearch;
    });
  }, [allProducts, selectedCategoryId, searchQuery]);

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 font-sans text-slate-900 dark:text-slate-100 overflow-hidden transition-colors duration-300 selection:bg-emerald-500/30">

      {/* Sidebar - Navigation */}
      <TreeSidebar 
        categories={CATEGORY_TREE}
        selectedCategoryId={selectedCategoryId}
        onSelectCategory={setSelectedCategoryId}
      />

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0 h-full relative">

        {/* Top Header */}
        <TopBar 
            searchQuery={searchQuery}
            onSearchChange={setSearchQuery}
            columns={columns}
            onToggleColumn={handleToggleColumn}
            onToggleAllColumns={handleToggleAllColumns}
            onOpenImport={() => setIsImportOpen(true)}
            viewMode={viewMode}
            onViewModeChange={setViewMode}
        />

        {/* Content Body */}
        <div className="flex-1 p-6 overflow-y-auto overflow-x-hidden w-full scroll-smooth">
            {/* Page Header */}
            <div className="flex items-end justify-between mb-6 flex-shrink-0 animate-in fade-in slide-in-from-top-4 duration-300">
                <div>
                    <h1 className="text-2xl font-bold text-slate-900 dark:text-slate-100 flex items-center gap-2 tracking-tight">
                        {viewMode === 'grid' ? <Database size={24} className="text-emerald-600 dark:text-emerald-500"/> : <Activity size={24} className="text-indigo-600 dark:text-indigo-400"/>}
                        {selectedCategoryId 
                            ? `Category: ${selectedCategoryId}` 
                            : viewMode === 'grid' ? 'Database Overview' : 'Data Analytics'}
                    </h1>
                    <p className="text-slate-500 dark:text-slate-400 text-sm mt-1 ml-8">
                        Found <span className="font-semibold text-slate-900 dark:text-slate-200">{filteredData.length}</span> synthetic resin products matching your criteria.
                    </p>
                </div>
            </div>

            <div className="w-full h-[calc(100%-80px)] animate-in fade-in zoom-in-95 duration-300">
                {viewMode === 'grid' ? (
                    <DataGrid 
                        data={filteredData}
                        columns={columns}
                        isLoading={false}
                        onDelete={handleDeleteProducts}
                        onUpdate={handleUpdateProduct}
                    />
                ) : (
                    <DataVisualizer data={filteredData} />
                )}
            </div>
        </div>
      </div>

      <ImportModal 
        isOpen={isImportOpen} 
        onClose={() => setIsImportOpen(false)} 
        onImport={handleImportData}
      />

      {/* Gemini Powered Assistant */}
      <AIAssistant contextData={filteredData} />
    </div>
  );
};

const App: React.FC = () => {
