  const yAxisUnit = propertyUnits[activeYKey];
  const xAxisUnit = propertyUnits[activeXKey];
  const zAxisUnit = zAxisKey !== 'none' ? propertyUnits[zAxisKey] : '';

  // Construct labels with units for the chart axes
  const yAxisLabel = yAxisUnit ? `${tProp(activeYKey)} (${yAxisUnit})` : tProp(activeYKey);
  const xAxisLabel = xAxisUnit ? `${tProp(activeXKey)} (${xAxisUnit})` : tProp(activeXKey);

  const CustomTooltip = ({ active, payload }: any) => {
