                                <ChevronDown size={14} className="absolute right-3 top-3 text-slate-400 pointer-events-none" />
                            </div>
                        </div>
                    )}
                </div>
            </div>

            {/* Styling & Color */}
            <div className="space-y-4">
                 <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider block flex items-center gap-2">
                    <Palette size={14} />
                    {t('styleGrouping')}
                </label>

                <div>
                    <span className="text-xs text-slate-500 dark:text-slate-400 mb-1 block">{t('groupBy')} (Color)</span>
                    <div className="relative">
                         <select 
                            value={colorByKey} 
