                    <div className="space-y-3">
                        {filters.map((f) => (
                            <div key={f.id} className="bg-slate-50 dark:bg-slate-800/50 p-2.5 rounded-lg border border-slate-100 dark:border-slate-800 animate-in fade-in slide-in-from-left-2">
                                <div className="flex items-center justify-between mb-2">
                                    <select 
                                        value={f.key}
                                        onChange={(e) => updateFilter(f.id, 'key', e.target.value)}
                                        className="text-xs bg-transparent font-medium text-slate-700 dark:text-slate-300 outline-none cursor-pointer"
                                    >
                                        {numericProperties.map(key => (
                                            <option key={key} value={key}>{tProp(key)}</option>
                                        ))}
                                    </select>
                                    <button onClick={() => removeFilter(f.id)} className="text-slate-400 hover:text-red-500 transition-colors">
                                        <Trash2 size={12} />
                                    </button>
                                </div>
                                <div className="flex items-center gap-2">
                                    <input 
                                        type="number" 
                                        placeholder={t('min')} 
                                        value={f.min}
                                        onChange={(e) => updateFilter(f.id, 'min', e.target.value)}
                                        className="w-full px-2 py-1 text-xs bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded focus:border-emerald-500 outline-none"
                                    />
                                    <span className="text-slate-400">-</span>
                                    <input 
                                        type="number" 
                                        placeholder={t('max')} 
                                        value={f.max}
                                        onChange={(e) => updateFilter(f.id, 'max', e.target.value)}
                                        className="w-full px-2 py-1 text-xs bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded focus:border-emerald-500 outline-none"
                                    />
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            {/* Export Actions */}
            <div className="pt-4 border-t border-slate-100 dark:border-slate-800 grid grid-cols-3 gap-2">
                <button onClick={handleExportJSON} className="flex flex-col items-center justify-center p-2 rounded bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-400 transition-colors" title={t('exportJson')}>
                    <FileJson size={16} className="mb-1"/>
                    <span className="text-[10px] font-medium">JSON</span>
                </button>
                <button onClick={handleExportCSV} className="flex flex-col items-center justify-center p-2 rounded bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-400 transition-colors" title={t('exportCsv')}>
                    <FileSpreadsheet size={16} className="mb-1"/>
                    <span className="text-[10px] font-medium">CSV</span>
                </button>
                <button onClick={handleExportPNG} className="flex flex-col items-center justify-center p-2 rounded bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-400 transition-colors" title={t('exportPng')}>
                    <ImageDown size={16} className="mb-1"/>
                    <span className="text-[10px] font-medium">PNG</span>
                </button>
            </div>

        </div>
      </div>

      {/* Main Chart Area */}
      <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden relative">

        {/* Toggle Config Button */}
        {!showConfig && (
            <button 
                onClick={() => setShowConfig(true)}
                className="absolute top-4 left-4 z-10 p-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 shadow-md rounded-lg text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors animate-in fade-in zoom-in"
                title={t('expandConfig')}
            >
                <Settings2 size={18} />
            </button>
        )}

        {/* Header */}
        <div className="h-16 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between px-6 bg-slate-50/50 dark:bg-slate-950/30">
            <h2 className="font-bold text-lg text-slate-800 dark:text-slate-100 flex items-center gap-2">
               {t('chartTitle')}
               <span className="text-sm font-normal text-slate-500 dark:text-slate-400 bg-slate-100 dark:bg-slate-800 px-2 py-0.5 rounded-full border border-slate-200 dark:border-slate-700">
                   {filteredData.length} items
               </span>
            </h2>
            <div className="flex items-center gap-4 text-xs font-medium text-slate-500 dark:text-slate-400">
                <div className="flex items-center gap-1.5">
                    <div className="w-2 h-2 rounded-full bg-blue-500"></div>
                    <span>{xAxisLabel}</span>
                </div>
                <ArrowRight size={12} />
                <div className="flex items-center gap-1.5">
                     <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
                     <span>{yAxisLabel}</span>
                </div>
            </div>
        </div>

        {/* Chart */}
        <div className="flex-1 p-4" ref={chartContainerRef}>
            {chartData.length === 0 ? (
                 <div className="h-full flex flex-col items-center justify-center text-slate-400 dark:text-slate-500">
                    <Activity size={48} className="mb-4 opacity-50" />
                    <p className="text-lg font-medium">{t('noNumericData')}</p>
                 </div>
            ) : (
                <ResponsiveContainer width="100%" height="100%">
                    {chartType === 'bar' ? (
                        <BarChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 40 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={chartStyles.gridStroke} vertical={false} />
                            <XAxis 
                                dataKey="name" 
                                angle={-45} 
                                textAnchor="end" 
                                height={70} 
                                tick={{ fill: chartStyles.axisTextFill, fontSize: 10 }}
                                stroke={chartStyles.axisStroke}
                            />
                            <YAxis 
                                label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', fill: chartStyles.axisTextFill, fontSize: 11 }}
                                tick={{ fill: chartStyles.axisTextFill, fontSize: 11 }}
                                stroke={chartStyles.axisStroke}
                            />
                            <RechartsTooltip content={<CustomTooltip />} cursor={{ fill: theme === 'dark' ? '#334155' : '#f1f5f9', opacity: 0.4 }} />
                            {colorByKey !== 'none' && colorMap ? (
                                // Grouped Bar logic is complex in simple Recharts without data transformation, 
                                // so for Bar chart we usually just color bars individually or use Stacked. 
                                // For simplicity in this prototype, we just color the single bar if grouping is on.
                                <Bar dataKey={activeYKey} radius={[4, 4, 0, 0]}>
                                    {chartData.map((entry, index) => {
                                        const color = colorMap[String(entry[colorByKey] || 'Unclassified')] || chartStyles.barFill;
                                        return <Cell key={`cell-${index}`} fill={color} />;
                                    })}
                                </Bar>
                            ) : (
                                <Bar dataKey={activeYKey} fill={chartStyles.barFill} radius={[4, 4, 0, 0]} />
                            )}
                        </BarChart>
                    ) : (
                        <ScatterChart margin={{ top: 20, right: 30, left: 20, bottom: 20 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={chartStyles.gridStroke} />
                            <XAxis 
                                type="number" 
                                dataKey={activeXKey} 
                                name={tProp(activeXKey)} 
                                label={{ value: xAxisLabel, position: 'bottom', offset: 0, fill: chartStyles.axisTextFill, fontSize: 11 }}
                                tick={{ fill: chartStyles.axisTextFill, fontSize: 11 }}
                                stroke={chartStyles.axisStroke}
                                domain={['auto', 'auto']}
                            />
                            <YAxis 
                                type="number" 
                                dataKey={activeYKey} 
                                name={tProp(activeYKey)} 
                                label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', fill: chartStyles.axisTextFill, fontSize: 11 }}
                                tick={{ fill: chartStyles.axisTextFill, fontSize: 11 }}
                                stroke={chartStyles.axisStroke}
                                domain={['auto', 'auto']}
                            />
                            {zAxisKey !== 'none' && <ZAxis type="number" dataKey={zAxisKey} range={[50, 400]} name={tProp(zAxisKey)} />}

                            <RechartsTooltip content={<CustomTooltip />} cursor={{ strokeDasharray: '3 3' }} />

                            {/* Trendline Scatter */}
                            {chartType === 'scatter' && showTrendline && trendlineData.length > 0 && (
                                <Scatter
                                    name="Trendline"
                                    data={trendlineData}
                                    line={{ stroke: '#ef4444', strokeWidth: 2, strokeDasharray: '5 5' }}
                                    shape={() => null} // Hide dots
                                    legendType="none"
                                    isAnimationActive={false}
                                />
                            )}

                            {/* Data Points */}
                            {colorByKey !== 'none' && scatterGroups ? (
                                Object.entries(scatterGroups).map(([group, groupData], idx) => (
                                    <Scatter 
                                        key={group} 
                                        name={group} 
                                        data={groupData} 
                                        fill={colorMap![group] || COLORS[idx % COLORS.length]} 
                                    />
                                ))
                            ) : (
                                <Scatter name="Products" data={chartData} fill="#3b82f6" />
                            )}

                            {colorByKey !== 'none' && <Legend wrapperStyle={{ fontSize: '11px', paddingTop: '10px' }} />}
                        </ScatterChart>
                    )}
                </ResponsiveContainer>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer,
  ScatterChart, Scatter, ZAxis, LabelList, Cell
} from 'recharts';
import { Product } from '../types';
import { 
  BarChart2, Activity, TrendingUp, FileJson, FileSpreadsheet, ImageDown,
  Factory, Settings2, Palette, MoveVertical, Filter, Plus, Trash2, X, ChevronDown, ArrowRight, Info, Microscope, PaintBucket
} from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16', '#6366f1'];

interface RangeFilter {
    id: string;
    key: string;
    min: string;
    max: string;
}

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [userXAxisKey, setUserXAxisKey] = useState<string>('');
  const [userYAxisKey, setUserYAxisKey] = useState<string>('');
  const [zAxisKey, setZAxisKey] = useState<string>('none');
  const [colorByKey, setColorByKey] = useState<string>('none');

  // Trendline state
  const [showTrendline, setShowTrendline] = useState<boolean>(false);
  const [trendlineColor, setTrendlineColor] = useState<string>('#ef4444');
  const [trendlineWidth, setTrendlineWidth] = useState<number>(2);
  const [trendlineStyle, setTrendlineStyle] = useState<'solid' | 'dashed' | 'dotted'>('dashed');

  const [showConfig, setShowConfig] = useState<boolean>(true);
  const [filters, setFilters] = useState<RangeFilter[]>([]);
  const [customColors, setCustomColors] = useState<Record<string, string>>({});
  const [showColorEdit, setShowColorEdit] = useState(false);

  const chartContainerRef = useRef<HTMLDivElement>(null);
  const colorPickerRef = useRef<HTMLDivElement>(null);

  const { t, tProp } = useLanguage();
  const { theme } = useTheme();

  // Close color picker when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (colorPickerRef.current && !colorPickerRef.current.contains(event.target as Node)) {
        setShowColorEdit(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Chart styling constants based on theme
  const chartStyles = useMemo(() => {
    const isDark = theme === 'dark';
    return {
        gridStroke: isDark ? '#334155' : '#e2e8f0', // slate-700 vs slate-200
        axisStroke: isDark ? '#94a3b8' : '#64748b', // slate-400 vs slate-500
        axisTextFill: isDark ? '#94a3b8' : '#64748b',
        tooltipBg: isDark ? '#0f172a' : '#ffffff', // slate-900 vs white
        tooltipBorder: isDark ? '#1e293b' : '#e2e8f0', // slate-800 vs slate-200
        tooltipText: isDark ? '#f8fafc' : '#1e293b', // slate-50 vs slate-800
        barFill: '#3b82f6'
    };
  }, [theme]);

  // 1. Extract Numeric Properties (for X, Y, Z axes)
  const numericProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        const num = Number(val.value);
        if (!isNaN(num) && val.value !== '' && val.value !== null) {
          props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // Filter Logic
  const addFilter = () => {
    if (numericProperties.length > 0) {
        setFilters([...filters, { id: Date.now().toString(), key: numericProperties[0], min: '', max: '' }]);
    }
  };

  const removeFilter = (id: string) => {
    setFilters(filters.filter(f => f.id !== id));
  };

  const updateFilter = (id: string, field: keyof RangeFilter, value: string) => {
    setFilters(filters.map(f => f.id === id ? { ...f, [field]: value } : f));
  };

  // Filtered Data
  const filteredData = useMemo(() => {
    if (filters.length === 0) return data;
    return data.filter(item => {
        return filters.every(f => {
             const valObj = item.properties[f.key];
             if (!valObj) return false;
             const val = Number(valObj.value);
             if (isNaN(val)) return false;

             const min = f.min === '' ? -Infinity : Number(f.min);
             const max = f.max === '' ? Infinity : Number(f.max);

             return val >= min && val <= max;
        });
    });
  }, [data, filters]);

  // 2. Extract Categorical Properties (for Coloring)
  const categoricalProperties = useMemo(() => {
    const props = new Set<string>(['manufacturer']); 
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (typeof val.value === 'string' && val.value.length < 20) {
            props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // 3. Helper to extract units
  const propertyUnits = useMemo(() => {
    const units: Record<string, string> = {};
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (v.unit && !units[k]) units[k] = v.unit;
        });
    });
    return units;
  }, [data]);

  // 4. Calculate Default/Active Keys synchronously
  const activeYKey = useMemo(() => {
    if (userYAxisKey && numericProperties.includes(userYAxisKey)) return userYAxisKey;
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    if (numericProperties.includes('密度')) return '密度';
    return numericProperties[0] || '';
  }, [userYAxisKey, numericProperties]);

  const activeXKey = useMemo(() => {
    if (userXAxisKey && numericProperties.includes(userXAxisKey)) return userXAxisKey;
    if (numericProperties.includes('密度')) return '密度';
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    return numericProperties.length > 1 ? numericProperties[1] : numericProperties[0] || '';
  }, [userXAxisKey, numericProperties]);

  // 5. Transform Data for Recharts
  const chartData = useMemo(() => {
    return filteredData.map(product => {
      const flattened: any = {
        name: product.gradeName,
        manufacturer: product.manufacturer,
        id: product.id
      };

      Object.entries(product.properties).forEach(([key, val]) => {
        const numVal = Number(val.value);
        if (!isNaN(numVal) && val.value !== '' && val.value !== null) {
          flattened[key] = numVal;
        } else {
          flattened[key] = val.value;
        }
      });
      return flattened;
    });
  }, [filteredData]);

  // 6. Group Data for Scatter Series
  const scatterGroups = useMemo(() => {
    if (chartType !== 'scatter' || colorByKey === 'none') return null;

    const groups: Record<string, any[]> = {};
    chartData.forEach(d => {
        const keyVal = d[colorByKey];
        const groupName = keyVal ? String(keyVal) : 'Unclassified';
        if (!groups[groupName]) groups[groupName] = [];
        groups[groupName].push(d);
    });
    return groups;
  }, [chartData, chartType, colorByKey]);

  // 7. Color Map
  const colorMap = useMemo(() => {
    if (colorByKey === 'none') return null;
    const uniqueValues = Array.from(new Set(chartData.map(d => String(d[colorByKey] || 'Unclassified'))));
    const map: Record<string, string> = {};
    uniqueValues.forEach((val, idx) => {
        map[val] = customColors[val] || COLORS[idx % COLORS.length];
    });
    return map;
  }, [chartData, colorByKey, customColors]);

  // Trendline Logic
  const trendlineData = useMemo(() => {
    if (chartType !== 'scatter' || !showTrendline || chartData.length < 2) return [];

    let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0, count = 0;
    chartData.forEach((point) => {
        const x = point[activeXKey];
        const y = point[activeYKey];
        if (typeof x === 'number' && typeof y === 'number') {
            sumX += x; sumY += y; sumXY += x * y; sumXX += x * x; count++;
        }
    });

    if (count < 2) return [];
    const slope = (count * sumXY - sumX * sumY) / (count * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / count;
    const xValues = chartData.map(d => d[activeXKey]).filter(v => typeof v === 'number') as number[];
    if (xValues.length === 0) return [];
    const minX = Math.min(...xValues);
    const maxX = Math.max(...xValues);

    return [
        { [activeXKey]: minX, [activeYKey]: slope * minX + intercept },
        { [activeXKey]: maxX, [activeYKey]: slope * maxX + intercept }
    ];
  }, [chartData, activeXKey, activeYKey, showTrendline, chartType]);

  const handleExportJSON = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(chartData));
    const link = document.createElement('a');
    link.href = dataStr;
    link.download = "chart_data.json";
    link.click();
  };

  const handleExportCSV = () => {
    if (chartData.length === 0) return;
    const allKeys = Array.from(new Set(chartData.flatMap(Object.keys)));
    const header = allKeys.join(',');
    const rows = chartData.map(row => 
      allKeys.map(key => {
        const val = row[key];
        if (val === null || val === undefined) return '';
        const stringVal = String(val);
        if (stringVal.includes(',') || stringVal.includes('"') || stringVal.includes('\n')) {
          return `"${stringVal.replace(/"/g, '""')}"`;
        }
        return stringVal;
      }).join(',')
    );
    const csvContent = [header, ...rows].join('\n');
    const blob = new Blob(["\uFEFF" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'chart_data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleExportPNG = async () => {
    if (!chartContainerRef.current) return;
    try {
        const canvas = await html2canvas(chartContainerRef.current, {
            scale: 2, // High resolution
            backgroundColor: theme === 'dark' ? '#0f172a' : '#ffffff', // slate-900 or white
            logging: false,
            useCORS: true
        });
        const link = document.createElement('a');
        link.download = `chart_${Date.now()}.png`;
        link.href = canvas.toDataURL('image/png');
        link.click();
    } catch (err) {
        console.error("Export failed", err);
    }
  };

  // Determine units for active axes
  const yAxisUnit = propertyUnits[activeYKey];
  const xAxisUnit = propertyUnits[activeXKey];
  const zAxisUnit = zAxisKey !== 'none' ? propertyUnits[zAxisKey] : '';

  // Construct labels with units for the chart axes
  const yAxisLabel = yAxisUnit ? `${tProp(activeYKey)} (${yAxisUnit})` : tProp(activeYKey);
  const xAxisLabel = xAxisUnit ? `${tProp(activeXKey)} (${xAxisUnit})` : tProp(activeXKey);

  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const pointData = payload[0].payload;

      // Calculate dynamic numeric properties to display (excluding axes)
      const dynamicKeys = numericProperties.filter(key => 
        pointData[key] !== undefined && 
        pointData[key] !== null && 
        key !== activeXKey && 
        key !== activeYKey && 
        key !== zAxisKey
      ).sort();

      // Calculate extra text properties (excluding system keys, axes, and color grouping)
      const extraTextKeys = Object.keys(pointData).filter(key => 
        typeof pointData[key] === 'string' &&
        key !== 'name' && 
        key !== 'manufacturer' &&
        key !== 'id' &&
        key !== activeXKey && 
        key !== activeYKey && 
        key !== zAxisKey &&
        key !== colorByKey
      ).slice(0, 3); // Limit to top 3

      return (
        <div className="bg-white dark:bg-slate-900 p-3.5 border border-slate-200 dark:border-slate-800 shadow-xl rounded-lg text-sm min-w-[280px] max-w-[320px] z-50 transition-colors duration-200 backdrop-blur-sm bg-opacity-95 dark:bg-opacity-95">
            <div className="mb-2.5 pb-2.5 border-b border-slate-100 dark:border-slate-800">
                <p className="font-bold text-slate-800 dark:text-slate-100 text-base leading-tight">{pointData.name}</p>
                <div className="flex items-center gap-1.5 text-xs text-slate-500 dark:text-slate-400 mt-1">
                    <Factory size={12} className="text-slate-400 dark:text-slate-500"/>
                    <span>{pointData.manufacturer}</span>
                </div>
            </div>

            <div className="space-y-1.5">
                {/* Main Axes Values Highlighted */}
                 <div className="grid grid-cols-2 gap-2 mb-2">
                    {chartType === 'scatter' && (
                        <div className="flex flex-col bg-slate-50 dark:bg-slate-800/50 p-1.5 rounded">
                            <span className="text-[10px] text-slate-400 dark:text-slate-500 uppercase tracking-wide">{tProp(activeXKey)}</span>
                            <span className="font-mono font-semibold text-blue-700 dark:text-blue-400 text-sm">
                                {pointData[activeXKey]} 
                                {xAxisUnit && <span className="text-[10px] text-slate-400 dark:text-slate-500 ml-1 font-normal">{xAxisUnit}</span>}
                            </span>
                        </div>
                    )}
                    <div className="flex flex-col bg-slate-50 dark:bg-slate-800/50 p-1.5 rounded">
                        <span className="text-[10px] text-slate-400 dark:text-slate-500 uppercase tracking-wide">{tProp(activeYKey)}</span>
                        <span className="font-mono font-semibold text-blue-700 dark:text-blue-400 text-sm">
                            {pointData[activeYKey]} 
                            {yAxisUnit && <span className="text-[10px] text-slate-400 dark:text-slate-500 ml-1 font-normal">{yAxisUnit}</span>}
                        </span>
                    </div>
                 </div>

                 {/* Z Axis Value */}
                 {zAxisKey !== 'none' && (
                    <div className="flex justify-between text-xs bg-slate-50 dark:bg-slate-800/50 p-1 rounded">
                        <span className="text-slate-500 dark:text-slate-400">{tProp(zAxisKey)}:</span>
                        <span className="font-mono font-semibold text-purple-700 dark:text-purple-400">
                            {pointData[zAxisKey]} 
                            {zAxisUnit && <span className="text-[10px] text-slate-400 dark:text-slate-500 ml-1">{zAxisUnit}</span>}
                        </span>
                    </div>
                )}

                {/* Grid for Extra Numeric Properties (Composition, etc) */}
                {dynamicKeys.length > 0 && (
                    <div className="pt-1">
                        <p className="text-[10px] font-semibold text-slate-400 dark:text-slate-500 uppercase tracking-wider mb-1 flex items-center gap-1">
                             <Microscope size={10} />
                             {t('details')}
                        </p>
                        <div className="grid grid-cols-1 gap-1">
                            {dynamicKeys.map(key => (
                                <div key={key} className="flex justify-between items-center text-xs p-1 rounded hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors">
                                    <span className="text-slate-500 dark:text-slate-400 truncate pr-2">{tProp(key)}</span>
                                    <span className="font-mono font-medium text-emerald-700 dark:text-emerald-400 whitespace-nowrap">
                                        {pointData[key]} 
                                        {propertyUnits[key] && <span className="text-[10px] text-slate-400 dark:text-slate-500 ml-0.5">{propertyUnits[key]}</span>}
                                    </span>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {colorByKey !== 'none' && (
                    <div className="flex justify-between text-xs mt-2 pt-2 border-t border-slate-100 dark:border-slate-800">
                        <span className="text-slate-500 dark:text-slate-400">{tProp(colorByKey)}:</span>
                        <span className="font-medium text-slate-800 dark:text-slate-200">{pointData[colorByKey]}</span>
                    </div>
                )}

                {extraTextKeys.length > 0 && (
                     <div className="mt-2 pt-2 border-t border-slate-100 dark:border-slate-800">
                         <p className="text-[10px] font-semibold text-slate-400 dark:text-slate-500 uppercase tracking-wider mb-1">
                             {t('otherDetails')}
                         </p>
                         {extraTextKeys.map(key => (
                             <div key={key} className="text-xs text-slate-600 dark:text-slate-400 mb-0.5">
                                 <span className="opacity-75 mr-1">{tProp(key)}:</span>
                                 <span>{pointData[key]}</span>
                             </div>
                         ))}
                     </div>
                )}
            </div>
        </div>
      );
    }
    return null;
  };

  return (
    <div className="flex h-full w-full gap-4 relative">
