                        <ChevronDown size={14} className="absolute right-3 top-3 text-slate-400 pointer-events-none" />
                    </div>
                </div>

                {/* Legend Customization for Grouping */}
                {colorByKey !== 'none' && colorMap && (
                     <div className="mt-2 space-y-1.5 animate-in fade-in slide-in-from-top-2 duration-200 max-h-40 overflow-y-auto custom-scrollbar pr-1">
