                                        className="w-4 h-4 rounded-full shadow-sm border border-black/10 hover:scale-110 transition-transform" 
                                        style={{ backgroundColor: color }}
                                    />
                                </div>
                            </div>
                        ))}
                     </div>
                )}

                {/* Trendline Configuration */}
                {chartType === 'scatter' && (
                    <div className="mt-3 p-3 bg-slate-50 dark:bg-slate-800/50 rounded-lg border border-slate-100 dark:border-slate-800 space-y-3">
                        <div className="flex items-center justify-between">
                             <div className="flex items-center gap-2">
                                <TrendingUp size={16} className="text-emerald-600 dark:text-emerald-500" />
                                <span className="text-xs font-medium text-slate-700 dark:text-slate-300">{t('showTrendline')}</span>
                            </div>
                            <button
                                onClick={() => setShowTrendline(!showTrendline)}
                                className={`w-9 h-5 rounded-full relative transition-colors duration-200 ease-in-out ${showTrendline ? 'bg-emerald-500' : 'bg-slate-300 dark:bg-slate-600'}`}
                            >
                                <span className={`absolute top-0.5 left-0.5 w-4 h-4 rounded-full bg-white shadow-sm transition-transform duration-200 ease-in-out ${showTrendline ? 'translate-x-4' : 'translate-x-0'}`} />
                            </button>
                        </div>

                        {showTrendline && (
                            <div className="pt-2 border-t border-slate-200 dark:border-slate-700 space-y-2 animate-in slide-in-from-top-1">
                                <div className="grid grid-cols-2 gap-2">
                                    <div>
                                        <label className="text-[10px] text-slate-500 dark:text-slate-400 block mb-1">{t('trendlineColor')}</label>
                                        <div className="flex items-center gap-2">
                                            <input 
                                                type="color" 
                                                value={trendlineColor}
                                                onChange={(e) => setTrendlineColor(e.target.value)}
                                                className="h-6 w-8 p-0 bg-transparent border-0 cursor-pointer rounded"
                                            />
                                            <span className="text-xs text-slate-600 dark:text-slate-300 font-mono">{trendlineColor}</span>
                                        </div>
                                    </div>
                                    <div>
                                         <label className="text-[10px] text-slate-500 dark:text-slate-400 block mb-1">{t('trendlineWidth')}</label>
                                         <input 
                                            type="range" 
                                            min="1" 
                                            max="5" 
                                            step="0.5"
                                            value={trendlineWidth}
                                            onChange={(e) => setTrendlineWidth(Number(e.target.value))}
                                            className="w-full h-1 bg-slate-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-emerald-500"
                                         />
                                    </div>
                                </div>
                                <div>
                                    <label className="text-[10px] text-slate-500 dark:text-slate-400 block mb-1">{t('trendlineStyle')}</label>
                                    <select
                                        value={trendlineStyle}
                                        onChange={(e) => setTrendlineStyle(e.target.value as any)}
                                        className="w-full py-1 px-2 text-xs bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded focus:border-emerald-500 outline-none"
                                    >
                                        <option value="solid">{t('solid')}</option>
                                        <option value="dashed">{t('dashed')}</option>
                                        <option value="dotted">{t('dotted')}</option>
                                    </select>
                                </div>
                            </div>
                        )}
                    </div>
                )}
            </div>

            {/* Data Filters */}
            <div className="space-y-3 pt-2 border-t border-slate-100 dark:border-slate-800">
                <div className="flex items-center justify-between">
                     <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider block flex items-center gap-2">
                        <Filter size={14} />
                        {t('dataFilters')}
                    </label>
                    <button onClick={addFilter} className="text-emerald-600 dark:text-emerald-500 hover:bg-emerald-50 dark:hover:bg-emerald-900/20 p-1 rounded transition-colors">
                        <Plus size={14} />
                    </button>
                </div>

                {filters.length === 0 ? (
                    <p className="text-xs text-slate-400 italic text-center py-2">{t('noFilters')}</p>
                ) : (
                    <div className="space-y-3">
                        {filters.map((f) => (
                            <div key={f.id} className="bg-slate-50 dark:bg-slate-800/50 p-2.5 rounded-lg border border-slate-100 dark:border-slate-800 animate-in fade-in slide-in-from-left-2">
                                <div className="flex items-center justify-between mb-2">
                                    <select 
                                        value={f.key}
                                        onChange={(e) => updateFilter(f.id, 'key', e.target.value)}
                                        className="text-xs bg-transparent font-medium text-slate-700 dark:text-slate-300 outline-none cursor-pointer"
                                    >
                                        {numericProperties.map(key => (
                                            <option key={key} value={key}>{tProp(key)}</option>
                                        ))}
                                    </select>
                                    <button onClick={() => removeFilter(f.id)} className="text-slate-400 hover:text-red-500 transition-colors">
                                        <Trash2 size={12} />
                                    </button>
                                </div>
                                <div className="flex items-center gap-2">
                                    <input 
                                        type="number" 
                                        placeholder={t('min')} 
                                        value={f.min}
                                        onChange={(e) => updateFilter(f.id, 'min', e.target.value)}
                                        className="w-full px-2 py-1 text-xs bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded focus:border-emerald-500 outline-none"
                                    />
                                    <span className="text-slate-400">-</span>
                                    <input 
                                        type="number" 
                                        placeholder={t('max')} 
                                        value={f.max}
                                        onChange={(e) => updateFilter(f.id, 'max', e.target.value)}
                                        className="w-full px-2 py-1 text-xs bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded focus:border-emerald-500 outline-none"
                                    />
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            {/* Export Actions */}
            <div className="pt-4 border-t border-slate-100 dark:border-slate-800 grid grid-cols-3 gap-2">
