                    <div className="space-y-3">
                        {filters.map((f) => (
                            <div key={f.id} className="bg-slate-50 dark:bg-slate-800/50 p-2.5 rounded-lg border border-slate-100 dark:border-slate-800 animate-in fade-in slide-in-from-left-2">
                                <div className="flex items-center justify-between mb-2">
                                    <select 
                                        value={f.key}
                                        onChange={(e) => updateFilter(f.id, 'key', e.target.value)}
                                        className="text-xs bg-transparent font-medium text-slate-700 dark:text-slate-300 outline-none cursor-pointer"
                                    >
                                        {numericProperties.map(key => (
                                            <option key={key} value={key}>{tProp(key)}</option>
                                        ))}
                                    </select>
                                    <button onClick={() => removeFilter(f.id)} className="text-slate-400 hover:text-red-500 transition-colors">
                                        <Trash2 size={12} />
                                    </button>
                                </div>
                                <div className="flex items-center gap-2">
                                    <input 
                                        type="number" 
                                        placeholder={t('min')} 
                                        value={f.min}
                                        onChange={(e) => updateFilter(f.id, 'min', e.target.value)}
                                        className="w-full px-2 py-1 text-xs bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded focus:border-emerald-500 outline-none"
                                    />
                                    <span className="text-slate-400">-</span>
                                    <input 
                                        type="number" 
                                        placeholder={t('max')} 
                                        value={f.max}
                                        onChange={(e) => updateFilter(f.id, 'max', e.target.value)}
                                        className="w-full px-2 py-1 text-xs bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded focus:border-emerald-500 outline-none"
                                    />
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            {/* Export Actions */}
            <div className="pt-4 border-t border-slate-100 dark:border-slate-800 grid grid-cols-3 gap-2">
                <button onClick={handleExportJSON} className="flex flex-col items-center justify-center p-2 rounded bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-400 transition-colors" title={t('exportJson')}>
                    <FileJson size={16} className="mb-1"/>
                    <span className="text-[10px] font-medium">JSON</span>
                </button>
                <button onClick={handleExportCSV} className="flex flex-col items-center justify-center p-2 rounded bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-400 transition-colors" title={t('exportCsv')}>
                    <FileSpreadsheet size={16} className="mb-1"/>
                    <span className="text-[10px] font-medium">CSV</span>
                </button>
                <button onClick={handleExportPNG} className="flex flex-col items-center justify-center p-2 rounded bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-400 transition-colors" title={t('exportPng')}>
                    <ImageDown size={16} className="mb-1"/>
                    <span className="text-[10px] font-medium">PNG</span>
                </button>
            </div>

        </div>
      </div>

      {/* Main Chart Area */}
      <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden relative">

        {/* Toggle Config Button */}
        {!showConfig && (
            <button 
                onClick={() => setShowConfig(true)}
                className="absolute top-4 left-4 z-10 p-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 shadow-md rounded-lg text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors animate-in fade-in zoom-in"
                title={t('expandConfig')}
            >
                <Settings2 size={18} />
            </button>
        )}

        {/* Header */}
        <div className="h-16 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between px-6 bg-slate-50/50 dark:bg-slate-950/30">
            <h2 className="font-bold text-lg text-slate-800 dark:text-slate-100 flex items-center gap-2">
               {t('chartTitle')}
               <span className="text-sm font-normal text-slate-500 dark:text-slate-400 bg-slate-100 dark:bg-slate-800 px-2 py-0.5 rounded-full border border-slate-200 dark:border-slate-700">
                   {filteredData.length} items
               </span>
            </h2>
            <div className="flex items-center gap-4 text-xs font-medium text-slate-500 dark:text-slate-400">
                <div className="flex items-center gap-1.5">
                    <div className="w-2 h-2 rounded-full bg-blue-500"></div>
                    <span>{xAxisLabel}</span>
                </div>
                <ArrowRight size={12} />
                <div className="flex items-center gap-1.5">
                     <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
                     <span>{yAxisLabel}</span>
                </div>
            </div>
        </div>

        {/* Chart */}
        <div className="flex-1 p-4" ref={chartContainerRef}>
            {chartData.length === 0 ? (
                 <div className="h-full flex flex-col items-center justify-center text-slate-400 dark:text-slate-500">
                    <Activity size={48} className="mb-4 opacity-50" />
                    <p className="text-lg font-medium">{t('noNumericData')}</p>
                 </div>
            ) : (
                <ResponsiveContainer width="100%" height="100%">
                    {chartType === 'bar' ? (
                        <BarChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 40 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={chartStyles.gridStroke} vertical={false} />
                            <XAxis 
                                dataKey="name" 
                                angle={-45} 
                                textAnchor="end" 
                                height={70} 
                                tick={{ fill: chartStyles.axisTextFill, fontSize: 10 }}
                                stroke={chartStyles.axisStroke}
                            />
                            <YAxis 
                                label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', fill: chartStyles.axisTextFill, fontSize: 11 }}
                                tick={{ fill: chartStyles.axisTextFill, fontSize: 11 }}
                                stroke={chartStyles.axisStroke}
                            />
                            <RechartsTooltip content={<CustomTooltip />} cursor={{ fill: theme === 'dark' ? '#334155' : '#f1f5f9', opacity: 0.4 }} />
                            {colorByKey !== 'none' && colorMap ? (
                                // Grouped Bar logic is complex in simple Recharts without data transformation, 
                                // so for Bar chart we usually just color bars individually or use Stacked. 
                                // For simplicity in this prototype, we just color the single bar if grouping is on.
                                <Bar dataKey={activeYKey} radius={[4, 4, 0, 0]}>
                                    {chartData.map((entry, index) => {
                                        const color = colorMap[String(entry[colorByKey] || 'Unclassified')] || chartStyles.barFill;
                                        return <Cell key={`cell-${index}`} fill={color} />;
                                    })}
                                </Bar>
                            ) : (
                                <Bar dataKey={activeYKey} fill={chartStyles.barFill} radius={[4, 4, 0, 0]} />
                            )}
                        </BarChart>
                    ) : (
                        <ScatterChart margin={{ top: 20, right: 30, left: 20, bottom: 20 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={chartStyles.gridStroke} />
                            <XAxis 
                                type="number" 
                                dataKey={activeXKey} 
                                name={tProp(activeXKey)} 
                                label={{ value: xAxisLabel, position: 'bottom', offset: 0, fill: chartStyles.axisTextFill, fontSize: 11 }}
                                tick={{ fill: chartStyles.axisTextFill, fontSize: 11 }}
                                stroke={chartStyles.axisStroke}
                                domain={['auto', 'auto']}
                            />
                            <YAxis 
                                type="number" 
                                dataKey={activeYKey} 
                                name={tProp(activeYKey)} 
                                label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', fill: chartStyles.axisTextFill, fontSize: 11 }}
                                tick={{ fill: chartStyles.axisTextFill, fontSize: 11 }}
                                stroke={chartStyles.axisStroke}
                                domain={['auto', 'auto']}
                            />
                            {zAxisKey !== 'none' && <ZAxis type="number" dataKey={zAxisKey} range={[50, 400]} name={tProp(zAxisKey)} />}

                            <RechartsTooltip content={<CustomTooltip />} cursor={{ strokeDasharray: '3 3' }} />

                            {/* Trendline Scatter */}
                            {chartType === 'scatter' && showTrendline && trendlineData.length > 0 && (
                                <Scatter
                                    name="Trendline"
                                    data={trendlineData}
                                    line={{ 
                                        stroke: trendlineColor, 
                                        strokeWidth: trendlineWidth, 
                                        strokeDasharray: trendlineStyle === 'solid' ? '0' : (trendlineStyle === 'dashed' ? '5 5' : '2 2') 
                                    }}
                                    shape={() => null} // Hide dots
                                    legendType="none"
                                    isAnimationActive={false}
                                />
                            )}

                            {/* Data Points */}
                            {colorByKey !== 'none' && scatterGroups ? (
                                Object.entries(scatterGroups).map(([group, groupData], idx) => (
                                    <Scatter 
                                        key={group} 
                                        name={group} 
                                        data={groupData} 
                                        fill={colorMap![group] || COLORS[idx % COLORS.length]} 
                                    />
                                ))
                            ) : (
                                <Scatter name="Products" data={chartData} fill="#3b82f6" />
                            )}

                            {colorByKey !== 'none' && <Legend wrapperStyle={{ fontSize: '11px', paddingTop: '10px' }} />}
                        </ScatterChart>
                    )}
                </ResponsiveContainer>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { X, Save, Plus, Trash2, Beaker, Factory } from 'lucide-react';
import { Product, PropertyValue } from '../types';
import { useLanguage } from '../contexts/LanguageContext';

interface EditProductModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (product: Product) => void;
  product: Product | null;
}

interface PropertyRow {
  id: string;
  key: string;
  value: string;
  unit: string;
}

export const EditProductModal: React.FC<EditProductModalProps> = ({ isOpen, onClose, onSave, product }) => {
  const { t, tProp } = useLanguage();
  const [formData, setFormData] = useState<Partial<Product>>({});
  const [propertyRows, setPropertyRows] = useState<PropertyRow[]>([]);
  const [ethyleneData, setEthyleneData] = useState({ value: '', unit: '' });

  useEffect(() => {
    if (product) {
      setFormData({
        id: product.id,
        gradeName: product.gradeName,
        manufacturer: product.manufacturer,
        categoryIds: product.categoryIds,
        updatedAt: product.updatedAt,
      });

      // Handle dedicated Ethylene Content field
      const ethProp = product.properties['乙烯含量'];
      setEthyleneData({
        value: ethProp ? String(ethProp.value) : '',
        unit: ethProp?.unit || ''
      });

      // Filter out Ethylene Content from dynamic rows to avoid duplicates
      const rows: PropertyRow[] = Object.entries(product.properties)
        .filter(([key]) => key !== '乙烯含量')
        .map(([key, val], index) => ({
          id: `prop-${index}-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
          key,
          value: String(val.value),
          unit: val.unit || ''
        }));
      setPropertyRows(rows);
    }
  }, [product, isOpen]);

  if (!isOpen || !product) return null;

  const handleSave = () => {
    const newProperties: Record<string, PropertyValue> = {};

    // Add dedicated Ethylene Content if value exists
    if (ethyleneData.value.trim() !== '') {
        const numVal = Number(ethyleneData.value);
        newProperties['乙烯含量'] = {
            value: !isNaN(numVal) ? numVal : ethyleneData.value,
            unit: ethyleneData.unit.trim() || undefined
        };
    }

    propertyRows.forEach(row => {
      if (row.key.trim()) {
        const numVal = Number(row.value);
        newProperties[row.key] = {
          value: !isNaN(numVal) && row.value.trim() !== '' ? numVal : row.value,
          unit: row.unit.trim() || undefined
        };
      }
    });

    onSave({
      ...product,
      ...formData as Product,
      properties: newProperties,
      updatedAt: new Date().toISOString().split('T')[0] // Auto update timestamp
    });
    onClose();
  };

  const addProperty = () => {
    setPropertyRows([...propertyRows, { id: `new-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`, key: '', value: '', unit: '' }]);
  };

  const removeProperty = (id: string) => {
    setPropertyRows(prev => prev.filter(p => p.id !== id));
  };

  const updateProperty = (id: string, field: keyof PropertyRow, val: string) => {
    setPropertyRows(prev => prev.map(p => p.id === id ? { ...p, [field]: val } : p));
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="w-full max-w-2xl bg-white dark:bg-slate-900 rounded-xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200 ring-1 ring-slate-200 dark:ring-slate-800 flex flex-col max-h-[90vh]">

        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/50">
          <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 flex items-center justify-center">
                <Beaker size={18} />
            </div>
            {t('editProduct')}
          </h3>
          <button onClick={onClose} type="button" className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors">
            <X size={20} />
          </button>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">

            {/* Basic Info Section */}
            <div className="mb-6">
                <h4 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-4 border-b border-slate-100 dark:border-slate-800 pb-2">
                    {t('basicInfo')}
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                        <label className="text-sm font-medium text-slate-700 dark:text-slate-300">{tProp('牌号')}</label>
                        <input 
                            type="text" 
                            value={formData.gradeName || ''}
                            onChange={(e) => setFormData({...formData, gradeName: e.target.value})}
                            className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all"
                        />
                    </div>
                    <div className="space-y-1.5">
                        <label className="text-sm font-medium text-slate-700 dark:text-slate-300">{tProp('生产厂家')}</label>
                        <div className="relative">
                            <Factory size={16} className="absolute left-3 top-2.5 text-slate-400" />
                            <input 
                                type="text" 
                                value={formData.manufacturer || ''}
                                onChange={(e) => setFormData({...formData, manufacturer: e.target.value})}
                                className="w-full pl-9 pr-3 py-2 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all"
                            />
                        </div>
                    </div>
                </div>
            </div>

            {/* Dynamic Properties Section */}
            <div>
                <div className="flex items-center justify-between mb-4 border-b border-slate-100 dark:border-slate-800 pb-2">
                    <h4 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                        {t('properties')}
                    </h4>
                    <button 
                        onClick={addProperty}
                        type="button"
                        className="text-xs flex items-center gap-1 text-emerald-600 dark:text-emerald-400 hover:text-emerald-700 font-medium px-2 py-1 rounded hover:bg-emerald-50 dark:hover:bg-emerald-900/20 transition-colors"
                    >
                        <Plus size={14} /> {t('addProperty')}
                    </button>
                </div>

                <div className="space-y-2">
                    {/* Specific Ethylene Content Field */}
                    <div className="flex items-center gap-2 group p-0.5 rounded-md hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                        <div className="flex-1 px-3 py-2 bg-slate-100 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-700 rounded-md text-sm text-slate-600 dark:text-slate-400 font-medium select-none">
                            {tProp('乙烯含量')}
                        </div>
                        <input 
                            type="text" 
                            placeholder={t('propertyValue')}
                            value={ethyleneData.value}
                            onChange={(e) => setEthyleneData(prev => ({ ...prev, value: e.target.value }))}
                            className="flex-1 px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md text-sm focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 outline-none font-mono"
                        />
                        <input 
                            type="text" 
                            placeholder={t('propertyUnit')}
                            value={ethyleneData.unit}
                            onChange={(e) => setEthyleneData(prev => ({ ...prev, unit: e.target.value }))}
                            className="w-20 px-3 py-2 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-md text-sm text-slate-500 focus:border-emerald-500 outline-none"
                        />
                        <div className="w-[34px]"></div> {/* Spacer for alignment with delete buttons */}
                    </div>

                    {propertyRows.map((row) => (
                        <div key={row.id} className="flex items-center gap-2 group">
                            <input 
                                type="text" 
                                placeholder={t('propertyName')}
                                value={row.key}
                                onChange={(e) => updateProperty(row.id, 'key', e.target.value)}
                                className="flex-1 px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md text-sm focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 outline-none"
                            />
                            <input 
                                type="text" 
                                placeholder={t('propertyValue')}
                                value={row.value}
                                onChange={(e) => updateProperty(row.id, 'value', e.target.value)}
                                className="flex-1 px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md text-sm focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 outline-none font-mono"
                            />
                            <input 
                                type="text" 
                                placeholder={t('propertyUnit')}
                                value={row.unit}
                                onChange={(e) => updateProperty(row.id, 'unit', e.target.value)}
                                className="w-20 px-3 py-2 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-md text-sm text-slate-500 focus:border-emerald-500 outline-none"
                            />
                            <button 
                                onClick={() => removeProperty(row.id)}
                                type="button"
                                className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-md transition-colors opacity-0 group-hover:opacity-100 focus:opacity-100"
                                title={t('delete')}
                            >
                                <Trash2 size={16} />
                            </button>
                        </div>
                    ))}
                    {propertyRows.length === 0 && ethyleneData.value === '' && (
                        <div className="text-center py-6 text-slate-400 dark:text-slate-600 text-sm italic border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-lg">
                            No properties defined. Click "Add Property" to start.
                        </div>
                    )}
                </div>
            </div>

        </div>

        {/* Footer */}
        <div className="p-4 border-t border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/50 flex justify-end gap-3">
            <button 
                onClick={onClose}
                type="button"
                className="px-4 py-2 text-sm font-medium text-slate-600 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors"
            >
                {t('cancel')}
            </button>
            <button 
                onClick={handleSave}
                type="button"
                className="px-4 py-2 text-sm font-medium text-white bg-emerald-600 hover:bg-emerald-700 rounded-lg shadow-md shadow-emerald-500/20 flex items-center gap-2 transition-all active:scale-95"
            >
                <Save size={16} />
                {t('save')}
            </button>
        </div>
      </div>
    </div>
  );
};

