                            <YAxis 
                                type="number" 
                                dataKey={activeYKey} 
                                name={tProp(activeYKey)} 
                                label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', fill: chartStyles.axisTextFill, fontSize: 11 }}
                                tick={{ fill: chartStyles.axisTextFill, fontSize: 11 }}
