            )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { X, Save, Plus, Trash2, Beaker, Factory } from 'lucide-react';
import { Product, PropertyValue } from '../types';
import { useLanguage } from '../contexts/LanguageContext';

interface EditProductModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (product: Product) => void;
  product: Product | null;
}

interface PropertyRow {
  id: string;
  key: string;
  value: string;
  unit: string;
}

export const EditProductModal: React.FC<EditProductModalProps> = ({ isOpen, onClose, onSave, product }) => {
  const { t, tProp } = useLanguage();
  const [formData, setFormData] = useState<Partial<Product>>({});
  const [propertyRows, setPropertyRows] = useState<PropertyRow[]>([]);

  // Dedicated states for common properties
  const [ethyleneData, setEthyleneData] = useState({ value: '', unit: '' });
  const [densityData, setDensityData] = useState({ value: '', unit: '' });
  const [mfrData, setMfrData] = useState({ value: '', unit: '' });

  useEffect(() => {
    if (product) {
      setFormData({
        id: product.id,
        gradeName: product.gradeName,
        manufacturer: product.manufacturer,
        categoryIds: product.categoryIds,
        updatedAt: product.updatedAt,
      });

      // Handle dedicated Density field
      const denProp = product.properties['密度'];
      setDensityData({
        value: denProp ? String(denProp.value) : '',
        unit: denProp?.unit || ''
      });

      // Handle dedicated MFR field
      const mfrProp = product.properties['熔体流动速率'];
      setMfrData({
        value: mfrProp ? String(mfrProp.value) : '',
        unit: mfrProp?.unit || ''
      });

      // Handle dedicated Ethylene Content field
      const ethProp = product.properties['乙烯含量'];
      setEthyleneData({
        value: ethProp ? String(ethProp.value) : '',
        unit: ethProp?.unit || ''
      });

      // Filter out dedicated fields from dynamic rows to avoid duplicates
      const dedicatedKeys = ['乙烯含量', '密度', '熔体流动速率'];
      const rows: PropertyRow[] = Object.entries(product.properties)
        .filter(([key]) => !dedicatedKeys.includes(key))
        .map(([key, val], index) => ({
          id: `prop-${index}-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
          key,
          value: String(val.value),
          unit: val.unit || ''
        }));
      setPropertyRows(rows);
    }
  }, [product, isOpen]);

  if (!isOpen || !product) return null;

  const handleSave = () => {
    const newProperties: Record<string, PropertyValue> = {};

    // Add dedicated Density
    if (densityData.value.trim() !== '') {
        const numVal = Number(densityData.value);
        newProperties['密度'] = {
            value: !isNaN(numVal) ? numVal : densityData.value,
            unit: densityData.unit.trim() || undefined
        };
    }

    // Add dedicated MFR
    if (mfrData.value.trim() !== '') {
        const numVal = Number(mfrData.value);
        newProperties['熔体流动速率'] = {
            value: !isNaN(numVal) ? numVal : mfrData.value,
            unit: mfrData.unit.trim() || undefined
        };
    }

    // Add dedicated Ethylene Content if value exists
    if (ethyleneData.value.trim() !== '') {
        const numVal = Number(ethyleneData.value);
        newProperties['乙烯含量'] = {
            value: !isNaN(numVal) ? numVal : ethyleneData.value,
            unit: ethyleneData.unit.trim() || undefined
        };
    }

    propertyRows.forEach(row => {
      if (row.key.trim()) {
        const numVal = Number(row.value);
        newProperties[row.key] = {
          value: !isNaN(numVal) && row.value.trim() !== '' ? numVal : row.value,
          unit: row.unit.trim() || undefined
        };
      }
    });

    onSave({
      ...product,
      ...formData as Product,
      properties: newProperties,
      updatedAt: new Date().toISOString().split('T')[0] // Auto update timestamp
    });
    onClose();
  };

  const addProperty = () => {
    setPropertyRows([...propertyRows, { id: `new-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`, key: '', value: '', unit: '' }]);
  };

  const removeProperty = (id: string) => {
    setPropertyRows(prev => prev.filter(p => p.id !== id));
  };

  const updateProperty = (id: string, field: keyof PropertyRow, val: string) => {
    setPropertyRows(prev => prev.map(p => p.id === id ? { ...p, [field]: val } : p));
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="w-full max-w-2xl bg-white dark:bg-slate-900 rounded-xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200 ring-1 ring-slate-200 dark:ring-slate-800 flex flex-col max-h-[90vh]">

        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/50">
          <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 flex items-center justify-center">
                <Beaker size={18} />
            </div>
            {t('editProduct')}
          </h3>
          <button onClick={onClose} type="button" className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors">
            <X size={20} />
          </button>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">

            {/* Basic Info Section */}
            <div className="mb-6">
                <h4 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-4 border-b border-slate-100 dark:border-slate-800 pb-2">
                    {t('basicInfo')}
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                        <label className="text-sm font-medium text-slate-700 dark:text-slate-300">{tProp('牌号')}</label>
                        <input 
                            type="text" 
                            value={formData.gradeName || ''}
                            onChange={(e) => setFormData({...formData, gradeName: e.target.value})}
                            className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all"
                        />
                    </div>
                    <div className="space-y-1.5">
                        <label className="text-sm font-medium text-slate-700 dark:text-slate-300">{tProp('生产厂家')}</label>
                        <div className="relative">
                            <Factory size={16} className="absolute left-3 top-2.5 text-slate-400" />
                            <input 
                                type="text" 
                                value={formData.manufacturer || ''}
                                onChange={(e) => setFormData({...formData, manufacturer: e.target.value})}
                                className="w-full pl-9 pr-3 py-2 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all"
                            />
                        </div>
                    </div>
                </div>
            </div>

            {/* Dynamic Properties Section */}
            <div>
                <div className="flex items-center justify-between mb-4 border-b border-slate-100 dark:border-slate-800 pb-2">
                    <h4 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                        {t('properties')}
                    </h4>
                    <button 
                        onClick={addProperty}
                        type="button"
                        className="text-xs flex items-center gap-1 text-emerald-600 dark:text-emerald-400 hover:text-emerald-700 font-medium px-2 py-1 rounded hover:bg-emerald-50 dark:hover:bg-emerald-900/20 transition-colors"
                    >
                        <Plus size={14} /> {t('addProperty')}
                    </button>
                </div>

                <div className="space-y-2">

                    {/* Specific Density Field */}
                    <div className="flex items-center gap-2 group p-0.5 rounded-md hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                        <div className="flex-1 px-3 py-2 bg-slate-100 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-700 rounded-md text-sm text-slate-600 dark:text-slate-400 font-medium select-none">
                            {tProp('密度')}
                        </div>
                        <input 
                            type="text" 
                            placeholder={t('propertyValue')}
                            value={densityData.value}
                            onChange={(e) => setDensityData(prev => ({ ...prev, value: e.target.value }))}
                            className="flex-1 px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md text-sm focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 outline-none font-mono"
                        />
                        <input 
                            type="text" 
                            placeholder={t('propertyUnit')}
                            value={densityData.unit}
                            onChange={(e) => setDensityData(prev => ({ ...prev, unit: e.target.value }))}
                            className="w-20 px-3 py-2 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-md text-sm text-slate-500 focus:border-emerald-500 outline-none"
                        />
                        <div className="w-[34px]"></div>
                    </div>

                    {/* Specific MFR Field */}
                    <div className="flex items-center gap-2 group p-0.5 rounded-md hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                        <div className="flex-1 px-3 py-2 bg-slate-100 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-700 rounded-md text-sm text-slate-600 dark:text-slate-400 font-medium select-none">
                            {tProp('熔体流动速率')}
                        </div>
                        <input 
                            type="text" 
                            placeholder={t('propertyValue')}
                            value={mfrData.value}
                            onChange={(e) => setMfrData(prev => ({ ...prev, value: e.target.value }))}
                            className="flex-1 px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md text-sm focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 outline-none font-mono"
                        />
                        <input 
                            type="text" 
                            placeholder={t('propertyUnit')}
                            value={mfrData.unit}
                            onChange={(e) => setMfrData(prev => ({ ...prev, unit: e.target.value }))}
                            className="w-20 px-3 py-2 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-md text-sm text-slate-500 focus:border-emerald-500 outline-none"
                        />
                        <div className="w-[34px]"></div>
                    </div>

                    {/* Specific Ethylene Content Field */}
                    <div className="flex items-center gap-2 group p-0.5 rounded-md hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                        <div className="flex-1 px-3 py-2 bg-slate-100 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-700 rounded-md text-sm text-slate-600 dark:text-slate-400 font-medium select-none">
                            {tProp('乙烯含量')}
                        </div>
                        <input 
                            type="text" 
                            placeholder={t('propertyValue')}
                            value={ethyleneData.value}
                            onChange={(e) => setEthyleneData(prev => ({ ...prev, value: e.target.value }))}
                            className="flex-1 px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md text-sm focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 outline-none font-mono"
                        />
                        <input 
                            type="text" 
                            placeholder={t('propertyUnit')}
                            value={ethyleneData.unit}
                            onChange={(e) => setEthyleneData(prev => ({ ...prev, unit: e.target.value }))}
                            className="w-20 px-3 py-2 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-md text-sm text-slate-500 focus:border-emerald-500 outline-none"
                        />
                        <div className="w-[34px]"></div> {/* Spacer for alignment with delete buttons */}
                    </div>

                    {propertyRows.map((row) => (
                        <div key={row.id} className="flex items-center gap-2 group">
                            <input 
                                type="text" 
                                placeholder={t('propertyName')}
                                value={row.key}
                                onChange={(e) => updateProperty(row.id, 'key', e.target.value)}
                                className="flex-1 px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md text-sm focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 outline-none"
                            />
                            <input 
                                type="text" 
                                placeholder={t('propertyValue')}
                                value={row.value}
                                onChange={(e) => updateProperty(row.id, 'value', e.target.value)}
                                className="flex-1 px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md text-sm focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 outline-none font-mono"
                            />
                            <input 
                                type="text" 
                                placeholder={t('propertyUnit')}
                                value={row.unit}
                                onChange={(e) => updateProperty(row.id, 'unit', e.target.value)}
                                className="w-20 px-3 py-2 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-md text-sm text-slate-500 focus:border-emerald-500 outline-none"
                            />
                            <button 
                                onClick={() => removeProperty(row.id)}
                                type="button"
                                className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-md transition-colors opacity-0 group-hover:opacity-100 focus:opacity-100"
                                title={t('delete')}
                            >
                                <Trash2 size={16} />
                            </button>
                        </div>
                    ))}
                    {propertyRows.length === 0 && ethyleneData.value === '' && densityData.value === '' && mfrData.value === '' && (
                        <div className="text-center py-6 text-slate-400 dark:text-slate-600 text-sm italic border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-lg">
                            No properties defined. Click "Add Property" to start.
                        </div>
                    )}
                </div>
            </div>

        </div>

        {/* Footer */}
        <div className="p-4 border-t border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/50 flex justify-end gap-3">
            <button 
                onClick={onClose}
                type="button"
                className="px-4 py-2 text-sm font-medium text-slate-600 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors"
            >
                {t('cancel')}
            </button>
            <button 
                onClick={handleSave}
                type="button"
                className="px-4 py-2 text-sm font-medium text-white bg-emerald-600 hover:bg-emerald-700 rounded-lg shadow-md shadow-emerald-500/20 flex items-center gap-2 transition-all active:scale-95"
            >
                <Save size={16} />
                {t('save')}
            </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer,
  ScatterChart, Scatter, ZAxis, LabelList, Cell
} from 'recharts';
import { Product } from '../types';
import { 
  BarChart2, Activity, TrendingUp, FileJson, FileSpreadsheet, ImageDown,
  Factory, Settings2, Palette, MoveVertical, Filter, Plus, Trash2, X, ChevronDown, ArrowRight, Info, Microscope, PaintBucket, Beaker
} from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16', '#6366f1'];

interface RangeFilter {
    id: string;
    key: string;
    min: string;
    max: string;
}

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [userXAxisKey, setUserXAxisKey] = useState<string>('');
  const [userYAxisKey, setUserYAxisKey] = useState<string>('');
  const [zAxisKey, setZAxisKey] = useState<string>('none');
  const [colorByKey, setColorByKey] = useState<string>('none');

  // Trendline state
  const [showTrendline, setShowTrendline] = useState<boolean>(false);
  const [trendlineColor, setTrendlineColor] = useState<string>('#ef4444');
  const [trendlineWidth, setTrendlineWidth] = useState<number>(2);
  const [trendlineStyle, setTrendlineStyle] = useState<'solid' | 'dashed' | 'dotted'>('dashed');

  const [showConfig, setShowConfig] = useState<boolean>(true);
  const [filters, setFilters] = useState<RangeFilter[]>([]);
  const [customColors, setCustomColors] = useState<Record<string, string>>({});
  const [showColorEdit, setShowColorEdit] = useState(false);

  const chartContainerRef = useRef<HTMLDivElement>(null);
  const colorPickerRef = useRef<HTMLDivElement>(null);

  const { t, tProp } = useLanguage();
  const { theme } = useTheme();

  // Close color picker when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (colorPickerRef.current && !colorPickerRef.current.contains(event.target as Node)) {
        setShowColorEdit(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Chart styling constants based on theme
  const chartStyles = useMemo(() => {
    const isDark = theme === 'dark';
    return {
        gridStroke: isDark ? '#334155' : '#e2e8f0', // slate-700 vs slate-200
        axisStroke: isDark ? '#94a3b8' : '#64748b', // slate-400 vs slate-500
        axisTextFill: isDark ? '#94a3b8' : '#64748b',
        tooltipBg: isDark ? '#0f172a' : '#ffffff', // slate-900 vs white
        tooltipBorder: isDark ? '#1e293b' : '#e2e8f0', // slate-800 vs slate-200
        tooltipText: isDark ? '#f8fafc' : '#1e293b', // slate-50 vs slate-800
        barFill: '#3b82f6'
    };
  }, [theme]);

  // 1. Extract Numeric Properties (for X, Y, Z axes)
  const numericProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        const num = Number(val.value);
        if (!isNaN(num) && val.value !== '' && val.value !== null) {
          props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // Filter Logic
  const addFilter = () => {
    if (numericProperties.length > 0) {
        setFilters([...filters, { id: Date.now().toString(), key: numericProperties[0], min: '', max: '' }]);
    }
  };

  const removeFilter = (id: string) => {
    setFilters(filters.filter(f => f.id !== id));
  };

  const updateFilter = (id: string, field: keyof RangeFilter, value: string) => {
    setFilters(filters.map(f => f.id === id ? { ...f, [field]: value } : f));
  };

  // Filtered Data
  const filteredData = useMemo(() => {
    if (filters.length === 0) return data;
    return data.filter(item => {
        return filters.every(f => {
             const valObj = item.properties[f.key];
             if (!valObj) return false;
             const val = Number(valObj.value);
             if (isNaN(val)) return false;

             const min = f.min === '' ? -Infinity : Number(f.min);
             const max = f.max === '' ? Infinity : Number(f.max);

             return val >= min && val <= max;
        });
    });
  }, [data, filters]);

  // 2. Extract Categorical Properties (for Coloring)
  const categoricalProperties = useMemo(() => {
    const props = new Set<string>(['manufacturer']); 
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (typeof val.value === 'string' && val.value.length < 20) {
            props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // 3. Helper to extract units
  const propertyUnits = useMemo(() => {
    const units: Record<string, string> = {};
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (v.unit && !units[k]) units[k] = v.unit;
        });
    });
    return units;
  }, [data]);

  // 4. Calculate Default/Active Keys synchronously
  const activeYKey = useMemo(() => {
    if (userYAxisKey && numericProperties.includes(userYAxisKey)) return userYAxisKey;
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    if (numericProperties.includes('密度')) return '密度';
    return numericProperties[0] || '';
  }, [userYAxisKey, numericProperties]);

  const activeXKey = useMemo(() => {
    if (userXAxisKey && numericProperties.includes(userXAxisKey)) return userXAxisKey;
    if (numericProperties.includes('密度')) return '密度';
    if (numericProperties.includes('熔体流动速率')) return '熔体流动速率';
    return numericProperties.length > 1 ? numericProperties[1] : numericProperties[0] || '';
  }, [userXAxisKey, numericProperties]);

  // 5. Transform Data for Recharts
  const chartData = useMemo(() => {
    return filteredData.map(product => {
      const flattened: any = {
        name: product.gradeName,
        manufacturer: product.manufacturer,
        id: product.id
      };

      Object.entries(product.properties).forEach(([key, val]) => {
        const numVal = Number(val.value);
        if (!isNaN(numVal) && val.value !== '' && val.value !== null) {
          flattened[key] = numVal;
        } else {
          flattened[key] = val.value;
        }
      });
      return flattened;
    });
  }, [filteredData]);

  // 6. Group Data for Scatter Series
  const scatterGroups = useMemo(() => {
    if (chartType !== 'scatter' || colorByKey === 'none') return null;

    const groups: Record<string, any[]> = {};
    chartData.forEach(d => {
        const keyVal = d[colorByKey];
        const groupName = keyVal ? String(keyVal) : 'Unclassified';
        if (!groups[groupName]) groups[groupName] = [];
        groups[groupName].push(d);
    });
    return groups;
  }, [chartData, chartType, colorByKey]);

  // 7. Color Map
  const colorMap = useMemo(() => {
    if (colorByKey === 'none') return null;
    const uniqueValues = Array.from(new Set(chartData.map(d => String(d[colorByKey] || 'Unclassified'))));
    const map: Record<string, string> = {};
    uniqueValues.forEach((val, idx) => {
        map[val] = customColors[val] || COLORS[idx % COLORS.length];
    });
    return map;
  }, [chartData, colorByKey, customColors]);

  // Trendline Logic (Linear Regression)
  const trendlineData = useMemo(() => {
    if (chartType !== 'scatter' || !showTrendline || chartData.length < 2) return [];

    let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0, count = 0;
    chartData.forEach((point) => {
        const x = point[activeXKey];
        const y = point[activeYKey];
        if (typeof x === 'number' && typeof y === 'number') {
            sumX += x; sumY += y; sumXY += x * y; sumXX += x * x; count++;
        }
    });

    if (count < 2) return [];
    const slope = (count * sumXY - sumX * sumY) / (count * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / count;
    const xValues = chartData.map(d => d[activeXKey]).filter(v => typeof v === 'number') as number[];
    if (xValues.length === 0) return [];
    const minX = Math.min(...xValues);
    const maxX = Math.max(...xValues);

    return [
        { [activeXKey]: minX, [activeYKey]: slope * minX + intercept },
        { [activeXKey]: maxX, [activeYKey]: slope * maxX + intercept }
    ];
  }, [chartData, activeXKey, activeYKey, showTrendline, chartType]);

  const handleExportJSON = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(chartData));
    const link = document.createElement('a');
    link.href = dataStr;
    link.download = "chart_data.json";
    link.click();
  };

  const handleExportCSV = () => {
    if (chartData.length === 0) return;
    const allKeys = Array.from(new Set(chartData.flatMap(Object.keys)));
    const header = allKeys.join(',');
    const rows = chartData.map(row => 
      allKeys.map(key => {
        const val = row[key];
        if (val === null || val === undefined) return '';
        const stringVal = String(val);
        if (stringVal.includes(',') || stringVal.includes('"') || stringVal.includes('\n')) {
          return `"${stringVal.replace(/"/g, '""')}"`;
        }
        return stringVal;
      }).join(',')
    );
    const csvContent = [header, ...rows].join('\n');
    const blob = new Blob(["\uFEFF" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'chart_data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleExportPNG = async () => {
    if (!chartContainerRef.current) return;
    try {
        const canvas = await html2canvas(chartContainerRef.current, {
            scale: 2, // High resolution
            backgroundColor: theme === 'dark' ? '#0f172a' : '#ffffff', // slate-900 or white
            logging: false,
            useCORS: true
        });
        const link = document.createElement('a');
        link.download = `chart_${Date.now()}.png`;
        link.href = canvas.toDataURL('image/png');
        link.click();
    } catch (err) {
        console.error("Export failed", err);
    }
  };

  // Determine units for active axes
  const yAxisUnit = propertyUnits[activeYKey];
  const xAxisUnit = propertyUnits[activeXKey];
  const zAxisUnit = zAxisKey !== 'none' ? propertyUnits[zAxisKey] : '';

  // Construct labels with units for the chart axes
  const yAxisLabel = yAxisUnit ? `${tProp(activeYKey)} (${yAxisUnit})` : tProp(activeYKey);
  const xAxisLabel = xAxisUnit ? `${tProp(activeXKey)} (${xAxisUnit})` : tProp(activeXKey);

  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const pointData = payload[0].payload;

      const usedKeys = new Set([activeXKey, activeYKey, zAxisKey, 'name', 'manufacturer', 'id', colorByKey]);
      const priorityList = ['乙烯含量', '二烯烃含量', 'VA含量', '密度', '熔体流动速率'];

      // 1. Identify priority keys to show (if not used as axis)
      const priorityProps = priorityList.filter(key => 
        !usedKeys.has(key) && 
        pointData[key] !== undefined && 
        pointData[key] !== null && 
        pointData[key] !== ''
      );

      // 2. Identify other numeric properties (excluding axes, system keys, and priority keys)
      const otherNumericProps = numericProperties.filter(key => 
        !usedKeys.has(key) && 
        !priorityList.includes(key) &&
        pointData[key] !== undefined && 
        pointData[key] !== null
      ).sort((a, b) => a.localeCompare(b));

      // 3. Identify other text properties
      const otherTextKeys = Object.keys(pointData).filter(key => 
        !usedKeys.has(key) &&
        !priorityList.includes(key) &&
        !numericProperties.includes(key) &&
        typeof pointData[key] === 'string'
      ).slice(0, 3); // Limit to top 3

      return (
        <div className="bg-white dark:bg-slate-900 p-3.5 border border-slate-200 dark:border-slate-800 shadow-xl rounded-lg text-sm min-w-[280px] max-w-[320px] z-50 transition-colors duration-200 backdrop-blur-sm bg-opacity-95 dark:bg-opacity-95">
            <div className="mb-2.5 pb-2.5 border-b border-slate-100 dark:border-slate-800">
                <p className="font-bold text-slate-800 dark:text-slate-100 text-base leading-tight">{pointData.name}</p>
                <div className="flex items-center gap-1.5 text-xs text-slate-500 dark:text-slate-400 mt-1">
                    <Factory size={12} className="text-slate-400 dark:text-slate-500"/>
                    <span>{pointData.manufacturer}</span>
                </div>
            </div>

            <div className="space-y-1.5">
                {/* Main Axes Values Highlighted */}
                 <div className="grid grid-cols-2 gap-2 mb-2">
                    {chartType === 'scatter' && (
                        <div className="flex flex-col bg-slate-50 dark:bg-slate-800/50 p-1.5 rounded">
                            <span className="text-[10px] text-slate-400 dark:text-slate-500 uppercase tracking-wide">{tProp(activeXKey)}</span>
                            <span className="font-mono font-semibold text-blue-700 dark:text-blue-400 text-sm">
                                {pointData[activeXKey]} 
                                {xAxisUnit && <span className="text-[10px] text-slate-400 dark:text-slate-500 ml-1 font-normal">{xAxisUnit}</span>}
                            </span>
                        </div>
                    )}
                    <div className="flex flex-col bg-slate-50 dark:bg-slate-800/50 p-1.5 rounded">
                        <span className="text-[10px] text-slate-400 dark:text-slate-500 uppercase tracking-wide">{tProp(activeYKey)}</span>
                        <span className="font-mono font-semibold text-blue-700 dark:text-blue-400 text-sm">
                            {pointData[activeYKey]} 
                            {yAxisUnit && <span className="text-[10px] text-slate-400 dark:text-slate-500 ml-1 font-normal">{yAxisUnit}</span>}
                        </span>
                    </div>
                 </div>

                 {/* Z Axis Value */}
                 {zAxisKey !== 'none' && (
                    <div className="flex justify-between text-xs bg-slate-50 dark:bg-slate-800/50 p-1 rounded">
                        <span className="text-slate-500 dark:text-slate-400">{tProp(zAxisKey)}:</span>
                        <span className="font-mono font-semibold text-purple-700 dark:text-purple-400">
                            {pointData[zAxisKey]} 
                            {zAxisUnit && <span className="text-[10px] text-slate-400 dark:text-slate-500 ml-1">{zAxisUnit}</span>}
                        </span>
                    </div>
                )}

                {/* Priority Properties (Highlighted) */}
                {priorityProps.length > 0 && (
                     <div className="pt-1 pb-1">
                        <p className="text-[10px] font-semibold text-emerald-600 dark:text-emerald-500 uppercase tracking-wider mb-1 flex items-center gap-1">
                             <Beaker size={10} />
                             {t('properties')}
                        </p>
                        <div className="grid grid-cols-1 gap-1">
                            {priorityProps.map(key => (
                                <div key={key} className="flex justify-between items-center text-xs p-1.5 bg-emerald-50/50 dark:bg-emerald-900/10 border border-emerald-100 dark:border-emerald-900/20 rounded transition-colors">
                                    <span className="text-slate-600 dark:text-slate-300 font-medium truncate pr-2">{tProp(key)}</span>
                                    <span className="font-mono font-bold text-emerald-700 dark:text-emerald-400 whitespace-nowrap">
                                        {pointData[key]} 
