                                    className="w-full pl-3 pr-8 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm appearance-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-colors"
                                >
                                    {numericProperties.map(key => (
                                        <option key={key} value={key}>{tProp(key)}</option>
                                    ))}
