import React, { useState, useMemo } from 'react';
import { Product, ColumnConfig } from '../types';
import { MoreHorizontal, FileText, Factory, CalendarClock, Edit, Trash2, CheckSquare, Square, MinusSquare } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { EditProductModal } from './EditProductModal';
import { DeleteConfirmationModal } from './DeleteConfirmationModal';

interface DataGridProps {
  data: Product[];
  columns: ColumnConfig[];
  isLoading: boolean;
  onDelete: (ids: string[]) => void;
  onUpdate: (product: Product) => void;
}

export const DataGrid: React.FC<DataGridProps> = ({ data, columns, isLoading, onDelete, onUpdate }) => {
  const { t, tProp } = useLanguage();
  const visibleColumns = columns.filter((c) => c.visible);

  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [deletingIds, setDeletingIds] = useState<string[] | null>(null);

  const isAllSelected = data.length > 0 && selectedIds.size === data.length;
  const isIndeterminate = selectedIds.size > 0 && selectedIds.size < data.length;

  const toggleSelectAll = () => {
    if (isAllSelected) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(data.map(p => p.id)));
    }
  };

  const toggleSelectRow = (id: string) => {
    const newSet = new Set(selectedIds);
    if (newSet.has(id)) {
      newSet.delete(id);
    } else {
      newSet.add(id);
    }
    setSelectedIds(newSet);
  };

  const handleBatchDeleteClick = () => {
    setDeletingIds(Array.from(selectedIds));
  };

  const handleDeleteSingleClick = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      setDeletingIds([id]);
  };

  const handleConfirmDelete = () => {
      if (deletingIds && deletingIds.length > 0) {
          onDelete(deletingIds);
          // Sync selection
          const newSet = new Set(selectedIds);
          deletingIds.forEach(id => newSet.delete(id));
          setSelectedIds(newSet);
          setDeletingIds(null);
      }
  };

  const handleEditClick = (product: Product, e: React.MouseEvent) => {
      e.stopPropagation();
      setEditingProduct(product);
  };

  const isNumericColumn = (key: string) => {
    if (['gradeName', 'manufacturer', 'updatedAt'].includes(key)) return false;
    for (const p of data.slice(0, 5)) {
        const val = p.properties[key]?.value;
        if (val !== undefined && val !== null && val !== '') {
             if (typeof val === 'number') return true;
             if (!isNaN(Number(val))) return true;
        }
    }
    return false;
  };

  const deletingProductNames = useMemo(() => {
    if (!deletingIds) return [];
    return deletingIds.map(id => {
        const product = data.find(p => p.id === id);
        return product ? product.gradeName : id;
    });
  }, [deletingIds, data]);

  if (isLoading) {
    return (
        <div className="flex flex-col items-center justify-center h-64 text-slate-400 dark:text-slate-500">
            <div className="w-8 h-8 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin mb-4 shadow-[0_0_10px_rgba(16,185,129,0.2)]"></div>
            <span className="text-sm font-medium">{t('loading')}</span>
        </div>
    );
  }

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-[500px] text-slate-400 dark:text-slate-500 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm">
        <div className="w-16 h-16 bg-slate-50 dark:bg-slate-800 rounded-full flex items-center justify-center mb-4 transition-colors">
            <FileText size={32} className="text-slate-300 dark:text-slate-600" />
        </div>
        <p className="text-lg font-semibold text-slate-700 dark:text-slate-300">{t('noProducts')}</p>
        <p className="text-sm text-slate-500 dark:text-slate-500 mt-1">{t('noProductsDesc')}</p>
      </div>
    );
  }

  return (
    <>
    <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden flex flex-col h-full transition-colors duration-300 relative">

      {/* Batch Action Toolbar */}
      {selectedIds.size > 0 && (
          <div className="absolute top-0 left-0 right-0 z-30 h-[60px] bg-emerald-50/95 dark:bg-slate-800/95 backdrop-blur-sm border-b border-emerald-100 dark:border-slate-700 flex items-center justify-between px-6 animate-in slide-in-from-top-2 duration-200 shadow-md">
              <div className="flex items-center gap-3 text-sm font-medium text-emerald-800 dark:text-emerald-300">
                  <div className="flex items-center justify-center w-6 h-6 bg-emerald-600 rounded-md text-white shadow-sm">
                      <MinusSquare size={16} />
                  </div>
                  <span className="font-semibold">{selectedIds.size} {t('selected')}</span>
              </div>
              <div className="flex gap-3">
                  <button 
                    onClick={handleBatchDeleteClick}
                    className="flex items-center gap-2 px-4 py-2 bg-rose-600 hover:bg-rose-700 active:bg-rose-800 text-white rounded-lg text-sm font-bold transition-all shadow-md hover:shadow-lg focus:ring-2 focus:ring-rose-500/50 focus:outline-none"
                  >
                      <Trash2 size={16} />
                      {t('deleteSelected')}
                  </button>
              </div>
          </div>
      )}

      <div className="overflow-x-auto overflow-y-auto custom-scrollbar flex-1">
        <table className="w-full text-sm text-left border-collapse">
          <thead className="text-xs text-slate-500 dark:text-slate-400 uppercase bg-slate-50/80 dark:bg-slate-900/90 sticky top-0 z-20 backdrop-blur-sm">
            <tr>
              <th className="w-10 px-5 py-3.5 border-b border-slate-200 dark:border-slate-800 bg-slate-50/80 dark:bg-slate-900/90 z-20">
                 <div 
                    onClick={toggleSelectAll}
                    className="cursor-pointer text-slate-400 hover:text-emerald-600 dark:hover:text-emerald-500 transition-colors"
                 >
                     {isAllSelected ? <CheckSquare size={18} className="text-emerald-600 dark:text-emerald-500"/> : (isIndeterminate ? <MinusSquare size={18} className="text-emerald-600 dark:text-emerald-500"/> : <Square size={18}/>)}
                 </div>
              </th>
              {visibleColumns.map((col) => {
                  const isNum = isNumericColumn(col.key);
                  return (
                      <th key={col.key} className={`px-5 py-3.5 font-semibold border-b border-slate-200 dark:border-slate-800 whitespace-nowrap bg-slate-50/80 dark:bg-slate-900/90 transition-colors ${isNum ? 'text-right' : 'text-left'}`}>
                          {tProp(col.label)}
                      </th>
                  );
              })}
              <th className="px-5 py-3.5 text-right border-b border-slate-200 dark:border-slate-800 bg-slate-50/80 dark:bg-slate-900/90 sticky right-0 z-30 w-24 backdrop-blur-sm transition-colors shadow-[-4px_0_8px_-2px_rgba(0,0,0,0.05)] dark:shadow-[-4px_0_8px_-2px_rgba(0,0,0,0.2)]">
                  {t('actions')}
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 dark:divide-slate-800/50 bg-white dark:bg-slate-900">
            {data.map((product) => {
              const isSelected = selectedIds.has(product.id);
              return (
                <tr 
                    key={product.id} 
                    className={`hover:bg-slate-50/80 dark:hover:bg-slate-800/40 transition-colors group ${isSelected ? 'bg-emerald-50/30 dark:bg-emerald-900/10' : ''}`}
                >
                  <td className="px-5 py-3 border-b border-slate-100 dark:border-slate-800/50">
                      <div 
                        onClick={() => toggleSelectRow(product.id)}
                        className="cursor-pointer text-slate-300 hover:text-emerald-600 dark:text-slate-600 dark:hover:text-emerald-500 transition-colors"
                      >
                         {isSelected ? <CheckSquare size={18} className="text-emerald-600 dark:text-emerald-500"/> : <Square size={18}/>}
                      </div>
                  </td>
                  {visibleColumns.map((col) => {
                    const isNum = isNumericColumn(col.key);
                    let content: React.ReactNode = <span className="text-slate-200 dark:text-slate-700">-</span>;

                    if (col.key === 'gradeName') {
                        content = (
                          <div className="flex items-center gap-2">
                               <div className="w-2 h-2 rounded-full bg-emerald-500/50 dark:bg-emerald-500/80 shadow-[0_0_6px_rgba(16,185,129,0.3)]"></div>
                               <span className="font-bold text-slate-700 dark:text-slate-200 group-hover:text-emerald-700 dark:group-hover:text-emerald-400 transition-colors">{product.gradeName}</span>
                          </div>
                        );
                    } else if (col.key === 'manufacturer') {
                        content = (
                            <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400">
                                <Factory size={13} className="text-slate-400 dark:text-slate-600" />
                                <span className="truncate max-w-[180px]" title={product.manufacturer}>{product.manufacturer}</span>
                            </div>
                        );
                    } else if (col.key === 'updatedAt') {
                        content = (
                          <div className="flex items-center gap-1.5 text-slate-400 dark:text-slate-500 text-xs">
                               <CalendarClock size={12}/>
                               <span className="font-mono">{product.updatedAt}</span>
                          </div>
                        );
                    } else {
                        const prop = product.properties[col.key];
                        if (prop && prop.value !== undefined && prop.value !== null && prop.value !== '') {
                            content = (
                                <span className="inline-flex items-baseline text-slate-700 dark:text-slate-300">
                                    {prop.value} 
                                    {prop.unit && <span className="text-slate-400 dark:text-slate-500 text-[10px] ml-1 font-medium">{prop.unit}</span>}
                                </span>
                            );
                        }
                    }

                    return (
                      <td key={`${product.id}-${col.key}`} className={`px-5 py-3 border-b border-slate-100 dark:border-slate-800/50 whitespace-nowrap transition-colors ${isNum ? 'text-right font-mono' : ''}`}>
                        {content}
                      </td>
                    );
                  })}
                  <td className="px-5 py-3 text-right border-b border-slate-100 dark:border-slate-800/50 sticky right-0 bg-white dark:bg-slate-900 group-hover:bg-slate-50/80 dark:group-hover:bg-slate-800/40 transition-colors z-20 shadow-[-4px_0_8px_-2px_rgba(0,0,0,0.05)] dark:shadow-[-4px_0_8px_-2px_rgba(0,0,0,0.2)]">
                    <div className="flex items-center justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button 
                            onClick={(e) => handleEditClick(product, e)}
                            className="p-1.5 rounded-md text-slate-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors"
                            title={t('edit')}
                            type="button"
                        >
                            <Edit size={16} />
                        </button>
                        <button 
                            onClick={(e) => handleDeleteSingleClick(product.id, e)}
                            className="p-1.5 rounded-md text-slate-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"
                            title={t('delete')}
                            type="button"
                        >
                            <Trash2 size={16} />
                        </button>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      <div className="px-5 py-3 border-t border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-900 text-xs text-slate-500 dark:text-slate-400 flex justify-between items-center sticky bottom-0 z-20 transition-colors flex-shrink-0">
         <span>{t('showing')} {data.length} {t('records')}</span>
         <div className="flex gap-2">
             <span className="px-2 py-0.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded text-slate-400 dark:text-slate-300">{t('page')} 1</span>
         </div>
      </div>
    </div>

    <EditProductModal 
        isOpen={!!editingProduct} 
        onClose={() => setEditingProduct(null)} 
        product={editingProduct} 
        onSave={(updated) => {
            onUpdate(updated);
            setEditingProduct(null);
        }}
    />

    <DeleteConfirmationModal 
        isOpen={!!deletingIds}
        onClose={() => setDeletingIds(null)}
        onConfirm={handleConfirmDelete}
        productNames={deletingProductNames}
    />
    </>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Send, Image as ImageIcon, Sparkles, X, Loader2, BrainCircuit, Bot, User, Cpu, ScanEye } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';

interface AIAssistantProps {
  contextData: Product[];
}

interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  image?: string;
  isThinking?: boolean;
}

// Simple text formatter to handle bold (**text**) and lists (- item)
const FormattedText: React.FC<{ text: string; className?: string }> = ({ text, className }) => {
  if (!text) return null;

  return (
    <div className={className}>
      {text.split('\n').map((line, i) => {
        // Handle bullet points
        if (line.trim().startsWith('- ') || line.trim().startsWith('* ')) {
             const content = line.trim().substring(2);
             const parts = content.split(/(\*\*.*?\*\*)/g);
             return (
                <div key={i} className="flex gap-2 ml-1 mb-1">
                    <span className="text-emerald-500 dark:text-emerald-400 mt-1.5">•</span>
                    <span>
                        {parts.map((part, j) => {
                            if (part.startsWith('**') && part.endsWith('**')) {
                                return <strong key={j} className="font-bold">{part.slice(2, -2)}</strong>;
                            }
                            return <span key={j}>{part}</span>;
                        })}
                    </span>
                </div>
             );
        }

        // Handle standard text with bolding
        const parts = line.split(/(\*\*.*?\*\*)/g);
        return (
          <p key={i} className="mb-1.5 last:mb-0 min-h-[1.2em]">
            {parts.map((part, j) => {
              if (part.startsWith('**') && part.endsWith('**')) {
                return <strong key={j} className="font-bold text-slate-800 dark:text-slate-100">{part.slice(2, -2)}</strong>;
              }
              return <span key={j}>{part}</span>;
            })}
          </p>
        );
      })}
    </div>
  );
};

export const AIAssistant: React.FC<AIAssistantProps> = ({ contextData }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const { t, language } = useLanguage();
  const { theme } = useTheme();
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [useThinking, setUseThinking] = useState(false);
  const [selectedModel, setSelectedModel] = useState('gemini-3-flash-preview');
  const [attachedImage, setAttachedImage] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const analyzeInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (messages.length === 0) {
        setMessages([{ 
            id: 'welcome', 
            role: 'model', 
            text: t('welcomeMessage') 
        }]);
    }
  }, [t, messages.length]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isOpen]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setAttachedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  };

  const handleAnalyzeUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const imgData = reader.result as string;
        // Specific prompt triggered by the "Scan" button for defect analysis
        const prompt = language === 'zh' 
          ? "请详细分析这张树脂图片。1. 识别树脂类型（如PE, PP, ABS等）及物理形态（颗粒、粉末、制件）。2. 重点进行质量缺陷检测，特别是：**黑点 (black specks)**、**晶点 (gels/fisheyes)**、**流纹 (flow marks)** 以及 **变色 (discoloration)**。请以专业质检员的角度提供分析结果。" 
          : "Please analyze this resin image. 1. Identify the resin type and physical form (pellets, powder, parts). 2. Specifically conduct a quality check for these defects: **Black Specks**, **Gels (fisheyes)**, **Flow Marks**, and **Discoloration**. Provide a technical quality assessment.";

        handleSend(prompt, imgData);
      };
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  };

  const handleSend = async (manualText?: string, manualImage?: string) => {
    const textToSend = typeof manualText === 'string' ? manualText : input;
    const imageToSend = typeof manualImage === 'string' ? manualImage : attachedImage;

    if ((!textToSend.trim() && !imageToSend) || isLoading) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: textToSend,
      image: imageToSend || undefined
    };

    setMessages(prev => [...prev, userMsg]);
    if (typeof manualText !== 'string') setInput('');
    if (typeof manualImage !== 'string') setAttachedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const dataSummary = contextData.slice(0, 50).map(p => 
        `- ${p.gradeName} (${p.manufacturer}): ${Object.entries(p.properties).map(([k,v]) => `${k}=${v.value}${v.unit||''}`).join(', ')}`
      ).join('\n');

      const systemInstruction = `You are ResinAI, an expert assistant for a petrochemical synthetic resin database (ResinDB).

      Current Data Context (First 50 visible items from user filter):
      ${dataSummary}

      Instructions:
      1. Answer questions based specifically on the provided resin data when possible.
      2. If the user asks for comparison, use the numeric data to compare properties like Density, MFR, Tensile Strength etc.
      3. **Image Analysis / Quality Control**: You are an expert in visual inspection of plastics. You must be able to identify:
         - Resin types and forms (pellets, powder, molded parts).
         - **Common Defects**:
           * **Black Specks**: Carbonized degradation or contamination.
           * **Gels** (fisheyes): Unmelted high molecular weight polymer.
           * **Flow Marks**: Surface imperfections from molding flow.
           * **Discoloration**: Yellowing/browning from thermal degradation.
      4. Use **bold** text for key values, product names, and identified defects.
      5. Answer in the requested language (${language === 'zh' ? 'Chinese' : 'English'}).
      `;

      let modelName = selectedModel;
      let config: any = { systemInstruction };
      if (useThinking) {
        const budget = modelName.includes('pro') ? 32768 : 16000;
        config.thinkingConfig = { thinkingBudget: budget };
      }

      let contents: any;
      if (userMsg.image) {
        const [meta, data] = userMsg.image.split(',');
        const mimeType = meta.match(/:(.*?);/)?.[1] || 'image/png';

        // Default prompt if user just uploads an image without text - enhanced for defects
        const defaultImagePrompt = language === 'zh'
            ? "分析这张图片。识别树脂类型和形态。重点检测是否存在质量缺陷，例如：**黑点 (black specks)**、**晶点 (gels)**、**流纹 (flow marks)** 或 **变色 (discoloration)**。"
            : "Analyze this image. Identify the resin type and form. Specifically check for quality defects such as **black specks**, **gels**, **flow marks**, and **discoloration**.";

        contents = {
          parts: [
            { inlineData: { mimeType, data } },
            { text: userMsg.text || defaultImagePrompt }
          ]
        };
      } else {
        contents = { parts: [{ text: userMsg.text }] };
      }

      const response = await ai.models.generateContent({ model: modelName, contents, config });
      const responseText = response.text || "Thinking process completed, but no direct text output was generated.";

      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: responseText
      }]);
    } catch (error: any) {
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: `${t('error')}: ${error.message || "Something went wrong."}`
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* Floating Trigger */}
      {!isOpen && (
        <button
          onClick={() => setIsOpen(true)}
          className={`fixed bottom-8 right-8 w-14 h-14 rounded-2xl shadow-xl hover:scale-110 transition-all duration-300 flex items-center justify-center z-50 group border
             ${theme === 'dark' 
               ? 'bg-slate-900 border-slate-700 hover:shadow-emerald-900/50 text-emerald-500 hover:text-emerald-400' 
               : 'bg-emerald-600 text-white hover:bg-emerald-700 shadow-emerald-200 border-emerald-500'}
          `}
        >
          <Sparkles className="w-6 h-6 animate-pulse" strokeWidth={1.5} />
          <div className="absolute -top-1 -right-1 w-3.5 h-3.5 bg-red-500 rounded-full border-2 border-white dark:border-slate-900 z-20"></div>
        </button>
      )}

      {/* Chat Window */}
      {isOpen && (
        <div className={`fixed bottom-8 right-8 w-[420px] h-[650px] max-h-[85vh] rounded-2xl shadow-2xl flex flex-col z-50 animate-in slide-in-from-bottom-10 fade-in duration-300 overflow-hidden font-sans border backdrop-blur-md
            ${theme === 'dark' 
              ? 'bg-slate-950/95 border-slate-700 shadow-black' 
              : 'bg-white/95 border-slate-200 shadow-slate-300'}
        `}>

          {/* Header */}
          <div className={`flex flex-col p-4 border-b relative z-10 transition-colors
              ${theme === 'dark' ? 'bg-slate-950/50 border-slate-800' : 'bg-slate-50/80 border-slate-100'}`}>
            <div className="flex items-center justify-between mb-3">
                <div className="flex items-center gap-3">
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-sm border
                        ${theme === 'dark' 
                          ? 'bg-slate-900 border-slate-800 text-emerald-500' 
                          : 'bg-white border-slate-200 text-emerald-600'}
                    `}>
                        <Bot size={22} />
                    </div>
                    <div>
                        <h3 className={`font-bold text-sm leading-tight ${theme === 'dark' ? 'text-slate-100' : 'text-slate-900'}`}>{t('copilot')}</h3>
                        <div className="flex items-center gap-1.5 mt-0.5">
                            <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span>
                            <span className={`text-[11px] font-medium ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>{t('modelActive')}</span>
                        </div>
                    </div>
                </div>
                <button 
                    onClick={() => setIsOpen(false)}
                    className={`w-8 h-8 flex items-center justify-center rounded-lg transition-colors
                        ${theme === 'dark' ? 'text-slate-400 hover:bg-slate-800 hover:text-slate-200' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-200'}`}
                >
                    <X size={18} />
                </button>
            </div>

            {/* Controls */}
            <div className={`flex items-center justify-between p-1 pl-2 pr-1 rounded-lg border transition-colors
                ${theme === 'dark' ? 'bg-slate-900/50 border-slate-800' : 'bg-white border-slate-200'}`}>
                <div className="flex items-center gap-2 text-xs font-medium pl-1">
                    <Cpu size={14} className={theme === 'dark' ? 'text-slate-400' : 'text-slate-500'} />
                    <select 
                        value={selectedModel}
                        onChange={(e) => setSelectedModel(e.target.value)}
                        className={`bg-transparent outline-none cursor-pointer transition-colors appearance-none
                             ${theme === 'dark' ? 'text-slate-300 hover:text-white' : 'text-slate-600 hover:text-slate-900'}`}
                    >
                        <option value="gemini-3-flash-preview" className={theme === 'dark' ? 'bg-slate-900' : ''}>Gemini 2.5 Flash</option>
                        <option value="gemini-3-pro-preview" className={theme === 'dark' ? 'bg-slate-900' : ''}>Gemini 2.5 Pro</option>
                    </select>
                </div>

                <button 
                    onClick={() => setUseThinking(!useThinking)}
                    className={`flex items-center gap-1.5 px-2 py-1 rounded-md text-[10px] font-bold uppercase tracking-wide transition-all ${
                        useThinking 
                        ? (theme === 'dark' ? 'bg-rose-900/30 text-rose-400 border border-rose-800' : 'bg-rose-100 text-rose-600 border border-rose-200')
                        : (theme === 'dark' ? 'bg-slate-800 text-slate-500 border border-slate-700 hover:bg-slate-700' : 'bg-slate-100 text-slate-400 border border-slate-200 hover:bg-slate-200')
                    }`}
                >
                    <BrainCircuit size={12} />
                    {useThinking ? t('thinkingOn') : t('thinkingOff')}
                </button>
            </div>
          </div>

          {/* Messages Area */}
          <div className={`flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar scroll-smooth
               ${theme === 'dark' ? 'bg-slate-950' : 'bg-slate-50'}`}>
            {messages.map((msg) => (
              <div key={msg.id} className={`flex gap-3 ${msg.role === 'user' ? 'flex-row-reverse' : ''} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
                <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 mt-1 shadow-sm border
                    ${msg.role === 'user' 
                    ? (theme === 'dark' ? 'bg-emerald-900/30 border-emerald-800 text-emerald-500' : 'bg-emerald-100 border-emerald-200 text-emerald-700')
                    : (theme === 'dark' ? 'bg-slate-900 border-slate-800 text-slate-400' : 'bg-white border-slate-200 text-slate-600')
                }`}>
                    {msg.role === 'user' ? <User size={16} /> : <Bot size={16} />}
                </div>
                <div className={`flex flex-col gap-1 max-w-[85%]`}>
                    <div className={`p-3.5 text-sm shadow-sm leading-relaxed
                        ${msg.role === 'user' 
                        ? 'bg-emerald-600 text-white rounded-2xl rounded-tr-sm' 
                        : (theme === 'dark'
                            ? 'bg-slate-900 text-slate-300 border border-slate-800 rounded-2xl rounded-tl-sm'
                            : 'bg-white text-slate-700 border border-slate-200 rounded-2xl rounded-tl-sm')
                    }`}>
                        {msg.image && (
                            <img src={msg.image} alt="Upload" className="w-full h-auto rounded-lg mb-3 border border-white/10" />
                        )}
                        <FormattedText text={msg.text} />
                    </div>
                </div>
              </div>
            ))}

            {/* Loading Indicator */}
            {isLoading && (
               <div className="flex gap-3 animate-pulse">
                   <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 mt-1 border
                        ${theme === 'dark' ? 'bg-slate-900 border-slate-800 text-slate-400' : 'bg-white border-slate-200 text-slate-600'}`}>
                        <Loader2 size={16} className="animate-spin" />
                   </div>
                   <div className={`p-3.5 rounded-2xl rounded-tl-sm text-sm flex items-center gap-2 border
                       ${theme === 'dark' ? 'bg-slate-900 border-slate-800 text-slate-400' : 'bg-white border-slate-200 text-slate-500'}`}>
                       <span>{useThinking ? t('reasoning') : t('analyzing')}</span>
                       <span className="flex gap-1 ml-1">
                          <span className="w-1 h-1 bg-slate-400 rounded-full animate-bounce" style={{animationDelay: '0ms'}}></span>
                          <span className="w-1 h-1 bg-slate-400 rounded-full animate-bounce" style={{animationDelay: '150ms'}}></span>
                          <span className="w-1 h-1 bg-slate-400 rounded-full animate-bounce" style={{animationDelay: '300ms'}}></span>
                       </span>
                   </div>
               </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input Area */}
          <div className={`p-3 border-t ${theme === 'dark' ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'}`}>
             {attachedImage && (
                 <div className="mb-2 relative inline-block animate-in zoom-in duration-200">
                     <div className="relative group">
                        <img src={attachedImage} alt="Preview" className={`h-12 w-12 object-cover rounded-lg shadow-sm border ${theme === 'dark' ? 'border-slate-700' : 'border-slate-200'}`} />
                        <button 
                            onClick={() => setAttachedImage(null)}
                            className="absolute -top-1.5 -right-1.5 bg-slate-800 text-white rounded-full p-0.5 shadow-md opacity-0 group-hover:opacity-100 transition-opacity"
                        >
                            <X size={10} />
                        </button>
                     </div>
                 </div>
             )}

             <div className={`flex items-end gap-2 p-1.5 rounded-xl border transition-all
                  ${theme === 'dark' 
                    ? 'bg-slate-950 border-slate-800 focus-within:border-emerald-800 focus-within:ring-1 focus-within:ring-emerald-900/50' 
                    : 'bg-slate-50 border-slate-200 focus-within:border-emerald-300 focus-within:ring-2 focus-within:ring-emerald-100'}`}>

                {/* Image Upload */}
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
                <button 
                    onClick={() => fileInputRef.current?.click()}
                    className={`p-2 rounded-lg transition-colors
                        ${theme === 'dark' ? 'text-slate-500 hover:text-emerald-400 hover:bg-slate-900' : 'text-slate-400 hover:text-emerald-600 hover:bg-emerald-50'}`}
                    title={t('uploadImage')}
                >
                    <ImageIcon size={20} />
                </button>

                {/* Scan Button (Explicitly Requested) */}
                <input type="file" ref={analyzeInputRef} className="hidden" accept="image/*" onChange={handleAnalyzeUpload} />
                <button 
                    onClick={() => analyzeInputRef.current?.click()}
                    className={`p-2 rounded-lg transition-colors
                        ${theme === 'dark' ? 'text-emerald-500 hover:text-emerald-400 hover:bg-slate-900' : 'text-emerald-600 hover:text-emerald-700 hover:bg-emerald-50'}`}
                    title="Scan Resin/Defects"
                >
                    <ScanEye size={20} />
                </button>

                <textarea
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => {
                        if (e.key === 'Enter' && !e.shiftKey) {
                            e.preventDefault();
                            handleSend();
                        }
                    }}
                    placeholder={attachedImage ? t('imageContext') : t('aiPlaceholder')}
                    className={`flex-1 max-h-32 bg-transparent border-none focus:ring-0 text-sm py-2 px-1 resize-none placeholder:text-slate-400
                         ${theme === 'dark' ? 'text-slate-200' : 'text-slate-800'}`}
                    rows={1}
                />

                {/* Send Button */}
                <button 
                    onClick={() => handleSend()}
                    disabled={(!input.trim() && !attachedImage) || isLoading}
                    className={`p-2 rounded-lg transition-all shadow-sm disabled:opacity-50 disabled:cursor-not-allowed
                         ${theme === 'dark' 
                           ? 'bg-emerald-600 hover:bg-emerald-500 text-white' 
                           : 'bg-emerald-600 hover:bg-emerald-700 text-white'}`}
                >
                    <Send size={18} />
                </button>
             </div>
          </div>
        </div>
      )}
    </>
  );
};

