    }
  };

  const handleExportCSV = () => {
    if (chartData.length === 0) return;

    // Get all unique keys from all data points to ensure columns align
    const allKeys = Array.from(new Set(chartData.flatMap(Object.keys)));

    // Create header row
    const header = allKeys.join(',');

    // Create data rows
    const csvRows = chartData.map((row) => {
      return allKeys.map((key) => {
        let value = row[key];
        if (value === null || value === undefined) {
          return ''; // Or handle null/undefined as needed
        }
        // Escape special characters and wrap in double quotes
        if (typeof value === 'string') {
          value = value.replace(/"/g, '""'); // Escape double quotes
          if (value.includes(',') || value.includes('"') || value.includes('\n') || value.includes('\r')) {
            value = `"${value}"`;
          }
        }
        return value;
      }).join(',');
    });

    // Combine header and data rows
    const csvString = '\uFEFF' + header + '\n' + csvRows.join('\n');

    // Create a Blob and initiate download
    const blob = new Blob([csvString], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'chart_data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  return (
