                </button>
                <button onClick={handleExportPNG} className="flex flex-col items-center justify-center p-2 rounded bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-400 transition-colors" title={t('exportPng')}>
                    <ImageDown size={16} className="mb-1"/>
                    <span className="text-[10px] font-medium">PNG</span>
                </button>
            </div>

        </div>
      </div>

      {/* Main Chart Area */}
      <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden relative">

        {/* Toggle Config Button */}
        {!showConfig && (
            <button 
                onClick={() => setShowConfig(true)}
                className="absolute top-4 left-4 z-10 p-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 shadow-md rounded-lg text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors animate-in fade-in zoom-in"
                title={t('expandConfig')}
            >
                <Settings2 size={18} />
            </button>
        )}

        {/* Header */}
        <div className="h-16 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between px-6 bg-slate-50/50 dark:bg-slate-950/30">
            <h2 className="font-bold text-lg text-slate-800 dark:text-slate-100 flex items-center gap-2">
               {t('chartTitle')}
               <span className="text-sm font-normal text-slate-500 dark:text-slate-400 bg-slate-100 dark:bg-slate-800 px-2 py-0.5 rounded-full border border-slate-200 dark:border-slate-700">
                   {filteredData.length} items
               </span>
            </h2>
            <div className="flex items-center gap-4 text-xs font-medium text-slate-500 dark:text-slate-400">
                <div className="flex items-center gap-1.5">
                    <div className="w-2 h-2 rounded-full bg-blue-500"></div>
                    <span>{xAxisLabel}</span>
                </div>
                <ArrowRight size={12} />
                <div className="flex items-center gap-1.5">
                     <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
                     <span>{yAxisLabel}</span>
                </div>
            </div>
        </div>

        {/* Chart */}
        <div className="flex-1 p-4" ref={chartContainerRef}>
            {chartData.length === 0 ? (
                 <div className="h-full flex flex-col items-center justify-center text-slate-400 dark:text-slate-500">
                    <Activity size={48} className="mb-4 opacity-50" />
                    <p className="text-lg font-medium">{t('noNumericData')}</p>
                 </div>
            ) : (
                <ResponsiveContainer width="100%" height="100%">
                    {chartType === 'bar' ? (
                        <BarChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 40 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={chartStyles.gridStroke} vertical={false} />
                            <XAxis 
                                dataKey="name" 
                                angle={-45} 
                                textAnchor="end" 
                                height={70} 
                                tick={{ fill: chartStyles.axisTextFill, fontSize: 10 }}
                                stroke={chartStyles.axisStroke}
                            />
                            <YAxis 
                                label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', fill: chartStyles.axisTextFill, fontSize: 11 }}
                                tick={{ fill: chartStyles.axisTextFill, fontSize: 11 }}
                                stroke={chartStyles.axisStroke}
                            />
                            <RechartsTooltip content={<CustomTooltip />} cursor={{ fill: theme === 'dark' ? '#334155' : '#f1f5f9', opacity: 0.4 }} />
                            {colorByKey !== 'none' && colorMap ? (
                                <Bar dataKey={activeYKey} radius={[4, 4, 0, 0]}>
                                    {chartData.map((entry, index) => {
                                        const color = colorMap[String(entry[colorByKey] || 'Unclassified')] || chartStyles.barFill;
                                        return <Cell key={`cell-${index}`} fill={color} />;
                                    })}
                                </Bar>
                            ) : (
                                <Bar dataKey={activeYKey} fill={chartStyles.barFill} radius={[4, 4, 0, 0]} />
                            )}
                        </BarChart>
                    ) : (
                        <ScatterChart margin={{ top: 20, right: 30, left: 20, bottom: 20 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={chartStyles.gridStroke} />
                            <XAxis 
                                type="number" 
                                dataKey={activeXKey} 
                                name={tProp(activeXKey)} 
                                label={{ value: xAxisLabel, position: 'bottom', offset: 0, fill: chartStyles.axisTextFill, fontSize: 11 }}
                                tick={{ fill: chartStyles.axisTextFill, fontSize: 11 }}
                                stroke={chartStyles.axisStroke}
                                domain={['auto', 'auto']}
                            />
                            <YAxis 
                                type="number" 
                                dataKey={activeYKey} 
                                name={tProp(activeYKey)} 
                                label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', fill: chartStyles.axisTextFill, fontSize: 11 }}
                                tick={{ fill: chartStyles.axisTextFill, fontSize: 11 }}
                                stroke={chartStyles.axisStroke}
                                domain={['auto', 'auto']}
                            />
                            {zAxisKey !== 'none' && <ZAxis type="number" dataKey={zAxisKey} range={[50, 400]} name={tProp(zAxisKey)} />}

                            <RechartsTooltip content={<CustomTooltip />} cursor={{ strokeDasharray: '3 3' }} />

                            {/* Trendline via ReferenceLine - More reliable than Scatter for lines */}
                            {chartType === 'scatter' && showTrendline && trendlineSegment && (
                                <ReferenceLine
                                    segment={trendlineSegment}
                                    stroke={trendlineColor}
                                    strokeWidth={trendlineWidth}
                                    strokeDasharray={trendlineStyle === 'solid' ? '0' : (trendlineStyle === 'dashed' ? '5 5' : '2 2')}
                                    ifOverflow="extendDomain"
                                />
                            )}

                            {/* Data Points */}
                            {colorByKey !== 'none' && scatterGroups ? (
                                Object.entries(scatterGroups).map(([group, groupData], idx) => (
                                    <Scatter 
                                        key={group} 
                                        name={group} 
                                        data={groupData} 
                                        fill={colorMap![group] || COLORS[idx % COLORS.length]} 
                                    />
                                ))
                            ) : (
                                <Scatter name="Products" data={chartData} fill="#3b82f6" />
                            )}

                            {colorByKey !== 'none' && <Legend wrapperStyle={{ fontSize: '11px', paddingTop: '10px' }} />}
                        </ScatterChart>
                    )}
                </ResponsiveContainer>
            )}
        </div>
      </div>
    </div>
  );
};

