interface DataVisualizerProps {
  data: Product[];
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16', '#6366f1'];

interface RangeFilter {
    id: string;
    key: string;
    min: string;
    max: string;
}

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('scatter');
  const [userXAxisKey, setUserXAxisKey] = useState<string>('');
  const [userYAxisKey, setUserYAxisKey] = useState<string>('');
  const [zAxisKey, setZAxisKey] = useState<string>('none');
  const [colorByKey, setColorByKey] = useState<string>('none');

  const [showTrendline, setShowTrendline] = useState<boolean>(true);
  const [trendlineColor, setTrendlineColor] = useState<string>('#ef4444');
  const [trendlineWidth, setTrendlineWidth] = useState<number>(3);
  const [trendlineStyle, setTrendlineStyle] = useState<'solid' | 'dashed' | 'dotted'>('solid');

  const [showConfig, setShowConfig] = useState<boolean>(true);
  const [filters, setFilters] = useState<RangeFilter[]>([]);
  const [customColors, setCustomColors] = useState<Record<string, string>>({});

  const chartContainerRef = useRef<HTMLDivElement>(null);

  const { t, tProp } = useLanguage();
  const { theme } = useTheme();

  const chartStyles = useMemo(() => {
    const isDark = theme === 'dark';
    return {
        gridStroke: isDark ? '#475569' : '#e2e8f0',
        axisStroke: isDark ? '#94a3b8' : '#64748b',
        axisTextFill: isDark ? '#cbd5e1' : '#475569',
        tooltipBg: isDark ? '#0f172a' : '#ffffff', 
        barFill: '#3b82f6'
    };
  }, [theme]);

  // 1. Extract Numeric Properties
  const numericProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        const num = Number(val.value);
        if (!isNaN(num) && val.value !== '' && val.value !== null) {
          props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  const addFilter = () => {
    if (numericProperties.length > 0) {
        setFilters([...filters, { id: Date.now().toString(), key: numericProperties[0], min: '', max: '' }]);
    }
  };

  const removeFilter = (id: string) => {
    setFilters(filters.filter(f => f.id !== id));
  };

  const updateFilter = (id: string, field: keyof RangeFilter, value: string) => {
    setFilters(filters.map(f => f.id === id ? { ...f, [field]: value } : f));
  };

  const filteredData = useMemo(() => {
    if (filters.length === 0) return data;
    return data.filter(item => {
        return filters.every(f => {
             const valObj = item.properties[f.key];
             if (!valObj) return false;
             const val = Number(valObj.value);
             if (isNaN(val)) return false;

             const min = f.min === '' ? -Infinity : Number(f.min);
             const max = f.max === '' ? Infinity : Number(f.max);

             return val >= min && val <= max;
        });
    });
  }, [data, filters]);

  const categoricalProperties = useMemo(() => {
    const props = new Set<string>(['manufacturer']); 
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (typeof val.value === 'string' && val.value.length < 20) {
            props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  const propertyUnits = useMemo(() => {
    const units: Record<string, string> = {};
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (v.unit && !units[k]) units[k] = v.unit;
        });
    });
    return units;
  }, [data]);

  // Calculate Active Keys with Fallback priority
  const activeYKey = useMemo(() => {
    if (userYAxisKey && numericProperties.includes(userYAxisKey)) return userYAxisKey;
    const defaults = ['熔体流动速率', 'MFR', '拉伸强度', 'Tensile Str.', '密度', 'Density'];
    for (const d of defaults) {
        if (numericProperties.includes(d)) return d;
    }
    return numericProperties[0] || '';
  }, [userYAxisKey, numericProperties]);

  const activeXKey = useMemo(() => {
    if (userXAxisKey && numericProperties.includes(userXAxisKey)) return userXAxisKey;
    const defaults = ['密度', 'Density', '熔体流动速率', 'MFR'];
    for (const d of defaults) {
        if (numericProperties.includes(d) && d !== activeYKey) return d;
    }
    // Fallback to second property or first
    if (numericProperties.length > 1 && numericProperties[1] !== activeYKey) return numericProperties[1];
    return numericProperties[0] || '';
  }, [userXAxisKey, numericProperties, activeYKey]);

  const chartData = useMemo(() => {
    return filteredData.map(product => {
      const flattened: any = {
        name: product.gradeName,
        manufacturer: product.manufacturer,
        id: product.id
      };

      Object.entries(product.properties).forEach(([key, val]) => {
        const numVal = Number(val.value);
        if (!isNaN(numVal) && val.value !== '' && val.value !== null) {
          flattened[key] = numVal;
        } else {
          flattened[key] = val.value;
        }
      });
      return flattened;
    });
  }, [filteredData]);

  const scatterGroups = useMemo(() => {
    if (chartType !== 'scatter' || colorByKey === 'none') return null;

    const groups: Record<string, any[]> = {};
    chartData.forEach(d => {
        const keyVal = d[colorByKey];
        const groupName = keyVal ? String(keyVal) : 'Unclassified';
        if (!groups[groupName]) groups[groupName] = [];
        groups[groupName].push(d);
    });
    return groups;
  }, [chartData, chartType, colorByKey]);

  const colorMap = useMemo(() => {
    if (colorByKey === 'none') return null;
    const uniqueValues = Array.from(new Set(chartData.map(d => String(d[colorByKey] || 'Unclassified'))));
    const map: Record<string, string> = {};
    uniqueValues.forEach((val, idx) => {
        map[val] = customColors[val] || COLORS[idx % COLORS.length];
    });
    return map;
  }, [chartData, colorByKey, customColors]);

  // Trendline Logic
  const trendlineSegment = useMemo(() => {
    if (chartType !== 'scatter' || !showTrendline || chartData.length < 2) return null;

    let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0, count = 0;
    const validPoints: {x: number, y: number}[] = [];

    chartData.forEach((point) => {
        const x = point[activeXKey];
        const y = point[activeYKey];
        if (typeof x === 'number' && typeof y === 'number' && !isNaN(x) && !isNaN(y)) {
            sumX += x; sumY += y; sumXY += x * y; sumXX += x * x; count++;
            validPoints.push({x, y});
        }
    });

    if (count < 2) return null;
    const slope = (count * sumXY - sumX * sumY) / (count * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / count;

    const xValues = validPoints.map(p => p.x);
    const minX = Math.min(...xValues);
    const maxX = Math.max(...xValues);

    return [
        { x: minX, y: slope * minX + intercept },
        { x: maxX, y: slope * maxX + intercept }
    ];
  }, [chartData, activeXKey, activeYKey, showTrendline, chartType]);

  const handleExportJSON = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(chartData));
    const link = document.createElement('a');
    link.href = dataStr;
    link.download = "chart_data.json";
    link.click();
  };

  const handleExportCSV = () => {
    if (chartData.length === 0) return;
    const allKeys = Array.from(new Set(chartData.flatMap(Object.keys)));
    const header = allKeys.join(',');
    const rows = chartData.map(row => 
      allKeys.map(key => {
        const val = row[key];
        if (val === null || val === undefined) return '';
        const stringVal = String(val);
        if (stringVal.includes(',') || stringVal.includes('"') || stringVal.includes('\n')) {
          return `"${stringVal.replace(/"/g, '""')}"`;
        }
        return stringVal;
      }).join(',')
    );
    const csvContent = [header, ...rows].join('\n');
    const blob = new Blob(["\uFEFF" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'chart_data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleExportPNG = async () => {
    if (!chartContainerRef.current) return;
    try {
        const canvas = await html2canvas(chartContainerRef.current, {
            scale: 2, 
            backgroundColor: theme === 'dark' ? '#0f172a' : '#ffffff',
            logging: false,
            useCORS: true
        });
        const link = document.createElement('a');
        link.download = `chart_${Date.now()}.png`;
        link.href = canvas.toDataURL('image/png');
        link.click();
    } catch (err) {
        console.error("Export failed", err);
    }
  };

  const yAxisUnit = propertyUnits[activeYKey];
  const xAxisUnit = propertyUnits[activeXKey];
  const zAxisUnit = zAxisKey !== 'none' ? propertyUnits[zAxisKey] : '';

  const yAxisLabel = yAxisUnit ? `${tProp(activeYKey)} (${yAxisUnit})` : tProp(activeYKey);
  const xAxisLabel = xAxisUnit ? `${tProp(activeXKey)} (${xAxisUnit})` : tProp(activeXKey);

  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const pointData = payload[0].payload;
      if (!pointData) return null;

      const priorityProps = ['乙烯含量', '二烯烃含量', 'VA含量', '密度', '熔体流动速率'].filter(k => k !== activeXKey && k !== activeYKey);

      return (
        <div className="bg-white dark:bg-slate-900 p-3.5 border border-slate-200 dark:border-slate-800 shadow-xl rounded-lg text-sm min-w-[280px] z-50 transition-colors backdrop-blur-sm bg-opacity-95">
            <div className="mb-2 pb-2 border-b border-slate-100 dark:border-slate-800">
                <p className="font-bold text-slate-800 dark:text-slate-100">{pointData.name}</p>
                <div className="flex items-center gap-1.5 text-xs text-slate-500 mt-1">
                    <Factory size={12} />
                    <span>{pointData.manufacturer}</span>
                </div>
            </div>

            <div className="grid grid-cols-2 gap-2 mb-2">
                 <div className="flex flex-col bg-slate-50 dark:bg-slate-800/50 p-1.5 rounded">
                     <span className="text-[10px] text-slate-400 uppercase">{tProp(activeXKey)}</span>
                     <span className="font-mono font-semibold text-blue-600 dark:text-blue-400">
                         {pointData[activeXKey]} {xAxisUnit}
                     </span>
                 </div>
                 <div className="flex flex-col bg-slate-50 dark:bg-slate-800/50 p-1.5 rounded">
                     <span className="text-[10px] text-slate-400 uppercase">{tProp(activeYKey)}</span>
                     <span className="font-mono font-semibold text-emerald-600 dark:text-emerald-400">
                         {pointData[activeYKey]} {yAxisUnit}
                     </span>
                 </div>
            </div>

            {priorityProps.map(key => pointData[key] !== undefined && (
                <div key={key} className="flex justify-between text-xs py-1 border-t border-slate-50 dark:border-slate-800/50">
                    <span className="text-slate-500">{tProp(key)}:</span>
                    <span className="font-mono text-slate-700 dark:text-slate-300">{pointData[key]} {propertyUnits[key]}</span>
                </div>
            ))}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="flex h-full w-full gap-4 relative">
      {/* Configuration Sidebar */}
      <div 
        className={`bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm flex flex-col transition-all duration-300 overflow-hidden z-10
            ${showConfig ? 'w-80' : 'w-0 opacity-0 pointer-events-none border-0'}`}
      >
        <div className="p-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-950/50">
           <h3 className="font-semibold text-slate-800 dark:text-slate-200 flex items-center gap-2">
               <Settings2 size={18} className="text-emerald-600 dark:text-emerald-500"/>
               {t('chartConfig')}
           </h3>
           <button onClick={() => setShowConfig(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200">
               <X size={16} />
           </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-6 custom-scrollbar">

            {/* Chart Type Selection */}
            <div className="space-y-3">
                <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider block">{t('chartType')}</label>
                <div className="grid grid-cols-2 gap-2">
                    <button 
                        onClick={() => setChartType('bar')}
                        className={`flex flex-col items-center justify-center p-3 rounded-lg border transition-all ${chartType === 'bar' ? 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-500 text-emerald-700 dark:text-emerald-400' : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'}`}
                    >
                        <BarChart2 size={24} className="mb-1" />
                        <span className="text-xs font-medium">{t('barChart')}</span>
                    </button>
                    <button 
                        onClick={() => setChartType('scatter')}
                        className={`flex flex-col items-center justify-center p-3 rounded-lg border transition-all ${chartType === 'scatter' ? 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-500 text-emerald-700 dark:text-emerald-400' : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'}`}
                    >
                        <Activity size={24} className="mb-1" />
                        <span className="text-xs font-medium">{t('scatterChart')}</span>
                    </button>
                </div>
            </div>

            {/* Axis Configuration */}
            <div className="space-y-4">
                <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider block flex items-center gap-2">
                    <MoveVertical size={14} />
                    {t('axisMapping')}
                </label>

                <div className="space-y-3">
                    <div>
                        <span className="text-xs text-slate-500 dark:text-slate-400 mb-1 block">{t('yAxis')} ({t('val')})</span>
                        <div className="relative">
                            <select 
                                value={activeYKey} 
                                onChange={(e) => setUserYAxisKey(e.target.value)}
                                className="w-full pl-3 pr-8 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm appearance-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-colors"
                            >
                                {numericProperties.map(key => (
                                    <option key={key} value={key}>{tProp(key)}</option>
                                ))}
                            </select>
                            <ChevronDown size={14} className="absolute right-3 top-3 text-slate-400 pointer-events-none" />
                        </div>
                    </div>

                    {chartType === 'scatter' && (
                         <div className="animate-in fade-in slide-in-from-top-2 duration-200">
                            <span className="text-xs text-slate-500 dark:text-slate-400 mb-1 block">{t('xAxis')}</span>
                            <div className="relative">
                                <select 
                                    value={activeXKey} 
                                    onChange={(e) => setUserXAxisKey(e.target.value)}
                                    className="w-full pl-3 pr-8 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm appearance-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-colors"
                                >
                                    {numericProperties.map(key => (
                                        <option key={key} value={key}>{tProp(key)}</option>
                                    ))}
                                </select>
                                <ChevronDown size={14} className="absolute right-3 top-3 text-slate-400 pointer-events-none" />
                            </div>
                        </div>
                    )}

                    {chartType === 'scatter' && (
                        <div className="animate-in fade-in slide-in-from-top-2 duration-200">
                             <span className="text-xs text-slate-500 dark:text-slate-400 mb-1 block">{t('zAxis')} (Size)</span>
                             <div className="relative">
                                <select 
                                    value={zAxisKey} 
                                    onChange={(e) => setZAxisKey(e.target.value)}
                                    className="w-full pl-3 pr-8 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm appearance-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-colors"
                                >
                                    <option value="none">{t('noneAxis')}</option>
                                    {numericProperties.map(key => (
                                        <option key={key} value={key}>{tProp(key)}</option>
                                    ))}
                                </select>
                                <ChevronDown size={14} className="absolute right-3 top-3 text-slate-400 pointer-events-none" />
                            </div>
                        </div>
                    )}
                </div>
            </div>

            {/* Styling & Color */}
            <div className="space-y-4">
                 <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider block flex items-center gap-2">
                    <Palette size={14} />
                    {t('styleGrouping')}
                </label>

                <div>
                    <span className="text-xs text-slate-500 dark:text-slate-400 mb-1 block">{t('groupBy')} (Color)</span>
                    <div className="relative">
                         <select 
                            value={colorByKey} 
                            onChange={(e) => setColorByKey(e.target.value)}
                            className="w-full pl-3 pr-8 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm appearance-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-colors"
                        >
                            <option value="none">{t('colorSingle')}</option>
                            {categoricalProperties.map(key => (
                                <option key={key} value={key}>{tProp(key)}</option>
                            ))}
                        </select>
                        <ChevronDown size={14} className="absolute right-3 top-3 text-slate-400 pointer-events-none" />
                    </div>
                </div>

                {/* Legend Customization for Grouping */}
                {colorByKey !== 'none' && colorMap && (
                     <div className="mt-2 space-y-1.5 animate-in fade-in slide-in-from-top-2 duration-200 max-h-40 overflow-y-auto custom-scrollbar pr-1 border border-slate-100 dark:border-slate-800 rounded-lg p-1 bg-slate-50/50 dark:bg-slate-900/50">
                        {Object.entries(colorMap).map(([groupName, color]) => (
                            <div key={groupName} className="flex items-center justify-between text-xs px-2 py-1.5 rounded hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors group">
                                <span className="truncate max-w-[140px] text-slate-600 dark:text-slate-300 font-medium" title={groupName}>
                                    {groupName}
                                </span>
                                <div className="relative flex items-center gap-2">
                                     {customColors[groupName] && (
                                        <button 
                                            onClick={() => {
                                                const newColors = {...customColors};
                                                delete newColors[groupName];
                                                setCustomColors(newColors);
                                            }}
                                            className="text-slate-300 hover:text-slate-500 opacity-0 group-hover:opacity-100 transition-opacity"
                                            title="Reset"
                                        >
                                            <RefreshCw size={12} />
                                        </button>
                                     )}
                                    <div className="relative w-5 h-5 rounded-md shadow-sm border border-slate-200 dark:border-slate-600 overflow-hidden hover:scale-105 transition-transform cursor-pointer">
                                         <div className="absolute inset-0" style={{ backgroundColor: color }} />
                                         <input 
                                            type="color" 
                                            value={color}
                                            onChange={(e) => setCustomColors(prev => ({ ...prev, [groupName]: e.target.value }))}
                                            className="absolute inset-0 opacity-0 w-full h-full cursor-pointer"
                                         />
                                    </div>
                                </div>
                            </div>
                        ))}
                     </div>
                )}

                {/* Trendline Configuration */}
                {chartType === 'scatter' && (
                    <div className="mt-3 p-3 bg-slate-50 dark:bg-slate-800/50 rounded-lg border border-slate-100 dark:border-slate-800 space-y-3">
                        <div className="flex items-center justify-between">
                             <div className="flex items-center gap-2">
                                <TrendingUp size={16} className="text-emerald-600 dark:text-emerald-500" />
                                <span className="text-xs font-medium text-slate-700 dark:text-slate-300">{t('showTrendline')}</span>
                            </div>
                            <button
                                onClick={() => setShowTrendline(!showTrendline)}
                                className={`w-9 h-5 rounded-full relative transition-colors duration-200 ease-in-out ${showTrendline ? 'bg-emerald-500' : 'bg-slate-300 dark:bg-slate-600'}`}
                            >
                                <span className={`absolute top-0.5 left-0.5 w-4 h-4 rounded-full bg-white shadow-sm transition-transform duration-200 ease-in-out ${showTrendline ? 'translate-x-4' : 'translate-x-0'}`} />
                            </button>
                        </div>

                        {showTrendline && (
                            <div className="pt-2 border-t border-slate-200 dark:border-slate-700 space-y-2 animate-in slide-in-from-top-1">
                                <div className="grid grid-cols-2 gap-2">
                                    <div>
                                        <label className="text-[10px] text-slate-500 dark:text-slate-400 block mb-1">{t('trendlineColor')}</label>
                                        <div className="flex items-center gap-2">
                                            <input 
                                                type="color" 
                                                value={trendlineColor}
                                                onChange={(e) => setTrendlineColor(e.target.value)}
                                                className="h-6 w-8 p-0 bg-transparent border-0 cursor-pointer rounded"
                                            />
                                            <span className="text-xs text-slate-600 dark:text-slate-300 font-mono">{trendlineColor}</span>
                                        </div>
                                    </div>
                                    <div>
                                         <label className="text-[10px] text-slate-500 dark:text-slate-400 block mb-1">{t('trendlineWidth')}</label>
                                         <input 
                                            type="range" 
                                            min="1" 
                                            max="5" 
                                            step="0.5"
                                            value={trendlineWidth}
                                            onChange={(e) => setTrendlineWidth(Number(e.target.value))}
                                            className="w-full h-1 bg-slate-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-emerald-500"
                                         />
                                    </div>
                                </div>
                                <div>
                                    <label className="text-[10px] text-slate-500 dark:text-slate-400 block mb-1">{t('trendlineStyle')}</label>
                                    <select
                                        value={trendlineStyle}
                                        onChange={(e) => setTrendlineStyle(e.target.value as 'solid' | 'dashed' | 'dotted')}
                                        className="w-full py-1 px-2 text-xs bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded focus:border-emerald-500 outline-none"
                                    >
                                        <option value="solid">{t('solid')}</option>
                                        <option value="dashed">{t('dashed')}</option>
                                        <option value="dotted">{t('dotted')}</option>
                                    </select>
                                </div>
                            </div>
                        )}
                    </div>
                )}
            </div>

            {/* Data Filters */}
            <div className="space-y-3 pt-2 border-t border-slate-100 dark:border-slate-800">
                <div className="flex items-center justify-between">
                     <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider block flex items-center gap-2">
                        <Filter size={14} />
                        {t('dataFilters')}
                    </label>
                    <button onClick={addFilter} className="text-emerald-600 dark:text-emerald-500 hover:bg-emerald-50 dark:hover:bg-emerald-900/20 p-1 rounded transition-colors">
                        <Plus size={14} />
                    </button>
                </div>
                {/* ... existing filter UI logic remains same if simplified ... */}
            </div>

            {/* Export Actions */}
            <div className="pt-4 border-t border-slate-100 dark:border-slate-800 grid grid-cols-3 gap-2">
                <button onClick={handleExportJSON} className="flex flex-col items-center justify-center p-2 rounded bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-400 transition-colors">
                    <FileJson size={16} className="mb-1"/>
                    <span className="text-[10px] font-medium">JSON</span>
                </button>
                <button onClick={handleExportCSV} className="flex flex-col items-center justify-center p-2 rounded bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-400 transition-colors">
                    <FileSpreadsheet size={16} className="mb-1"/>
                    <span className="text-[10px] font-medium">CSV</span>
                </button>
                <button onClick={handleExportPNG} className="flex flex-col items-center justify-center p-2 rounded bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-400 transition-colors">
                    <ImageDown size={16} className="mb-1"/>
                    <span className="text-[10px] font-medium">PNG</span>
                </button>
            </div>

        </div>
      </div>

      {/* Main Chart Area */}
      <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden relative">

        {/* Toggle Config Button */}
        {!showConfig && (
            <button 
                onClick={() => setShowConfig(true)}
                className="absolute top-4 left-4 z-10 p-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 shadow-md rounded-lg text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors animate-in fade-in zoom-in"
                title={t('expandConfig')}
            >
                <Settings2 size={18} />
            </button>
        )}

        {/* Header */}
        <div className="h-16 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between px-6 bg-slate-50/50 dark:bg-slate-950/30">
            <h2 className="font-bold text-lg text-slate-800 dark:text-slate-100 flex items-center gap-2">
               {t('chartTitle')}
               <span className="text-sm font-normal text-slate-500 dark:text-slate-400 bg-slate-100 dark:bg-slate-800 px-2 py-0.5 rounded-full border border-slate-200 dark:border-slate-700">
                   {filteredData.length} items
               </span>
            </h2>
            <div className="flex items-center gap-4 text-xs font-medium text-slate-500 dark:text-slate-400">
                <div className="flex items-center gap-1.5">
                    <div className="w-2 h-2 rounded-full bg-blue-500"></div>
                    <span>{xAxisLabel}</span>
                </div>
                <ArrowRight size={12} />
                <div className="flex items-center gap-1.5">
                     <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
                     <span>{yAxisLabel}</span>
                </div>
            </div>
        </div>

        {/* Chart */}
        <div className="flex-1 p-4 w-full h-full" ref={chartContainerRef}>
            {chartData.length === 0 ? (
                 <div className="h-full flex flex-col items-center justify-center text-slate-400 dark:text-slate-500">
                    <Activity size={48} className="mb-4 opacity-50" />
                    <p className="text-lg font-medium">{t('noNumericData')}</p>
                 </div>
            ) : (
                <ResponsiveContainer width="100%" height="100%">
                    {chartType === 'bar' ? (
                        <BarChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 40 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={chartStyles.gridStroke} vertical={false} />
                            <XAxis 
                                dataKey="name" 
                                angle={-45} 
                                textAnchor="end" 
                                height={70} 
                                tick={{ fill: chartStyles.axisTextFill, fontSize: 10 }}
                                stroke={chartStyles.axisStroke}
                            />
                            <YAxis 
                                label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', fill: chartStyles.axisTextFill, fontSize: 11 }}
                                tick={{ fill: chartStyles.axisTextFill, fontSize: 11 }}
                                stroke={chartStyles.axisStroke}
                            />
                            <RechartsTooltip content={<CustomTooltip />} cursor={{ fill: theme === 'dark' ? '#334155' : '#f1f5f9', opacity: 0.4 }} />
                            {colorByKey !== 'none' && colorMap ? (
                                <Bar dataKey={activeYKey} radius={[4, 4, 0, 0]}>
                                    {chartData.map((entry, index) => {
                                        const color = colorMap[String(entry[colorByKey] || 'Unclassified')] || chartStyles.barFill;
                                        return <Cell key={`cell-${index}`} fill={color} />;
                                    })}
                                </Bar>
                            ) : (
                                <Bar dataKey={activeYKey} fill={chartStyles.barFill} radius={[4, 4, 0, 0]} />
                            )}
                        </BarChart>
                    ) : (
                        <ScatterChart margin={{ top: 20, right: 30, left: 20, bottom: 20 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={chartStyles.gridStroke} />
                            <XAxis 
                                type="number" 
                                dataKey={activeXKey} 
                                name={tProp(activeXKey)} 
                                label={{ value: xAxisLabel, position: 'bottom', offset: 0, fill: chartStyles.axisTextFill, fontSize: 11 }}
                                tick={{ fill: chartStyles.axisTextFill, fontSize: 11 }}
                                stroke={chartStyles.axisStroke}
                                domain={['auto', 'auto']}
                            />
                            <YAxis 
                                type="number" 
                                dataKey={activeYKey} 
                                name={tProp(activeYKey)} 
                                label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', fill: chartStyles.axisTextFill, fontSize: 11 }}
                                tick={{ fill: chartStyles.axisTextFill, fontSize: 11 }}
                                stroke={chartStyles.axisStroke}
                                domain={['auto', 'auto']}
                            />
                            {zAxisKey !== 'none' && <ZAxis type="number" dataKey={zAxisKey} range={[50, 400]} name={tProp(zAxisKey)} />}

                            <RechartsTooltip content={<CustomTooltip />} cursor={{ strokeDasharray: '3 3' }} />

                            {/* Trendline via ReferenceLine */}
                            {chartType === 'scatter' && showTrendline && trendlineSegment && (
                                <ReferenceLine
                                    segment={trendlineSegment}
                                    stroke={trendlineColor}
                                    strokeWidth={trendlineWidth}
                                    strokeDasharray={trendlineStyle === 'solid' ? '0' : (trendlineStyle === 'dashed' ? '5 5' : '2 2')}
                                />
                            )}

                            {/* Data Points */}
                            {colorByKey !== 'none' && scatterGroups ? (
                                Object.entries(scatterGroups).map(([group, groupData], idx) => (
                                    <Scatter 
                                        key={group} 
                                        name={group} 
                                        data={groupData} 
                                        fill={colorMap![group] || COLORS[idx % COLORS.length]} 
                                    />
                                ))
                            ) : (
                                <Scatter name="Products" data={chartData} fill="#3b82f6" />
                            )}

                            {colorByKey !== 'none' && <Legend wrapperStyle={{ fontSize: '11px', paddingTop: '10px' }} />}
                        </ScatterChart>
                    )}
                </ResponsiveContainer>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useRef } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer,
  ScatterChart, Scatter, ZAxis, Cell, ReferenceLine
} from 'recharts';
import { Product } from '../types';
import { 
  BarChart2, Activity, TrendingUp, FileJson, FileSpreadsheet, ImageDown,
  Factory, Settings2, Palette, MoveVertical, Filter, Plus, Trash2, X, ChevronDown, ArrowRight, Beaker, RefreshCw
} from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16', '#6366f1'];

interface RangeFilter {
    id: string;
    key: string;
    min: string;
    max: string;
}

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('scatter');
  const [userXAxisKey, setUserXAxisKey] = useState<string>('');
  const [userYAxisKey, setUserYAxisKey] = useState<string>('');
  const [zAxisKey, setZAxisKey] = useState<string>('none');
  const [colorByKey, setColorByKey] = useState<string>('none');

  const [showTrendline, setShowTrendline] = useState<boolean>(true);
  const [trendlineColor, setTrendlineColor] = useState<string>('#ef4444');
  const [trendlineWidth, setTrendlineWidth] = useState<number>(3);
  const [trendlineStyle, setTrendlineStyle] = useState<'solid' | 'dashed' | 'dotted'>('solid');

  const [showConfig, setShowConfig] = useState<boolean>(true);
  const [filters, setFilters] = useState<RangeFilter[]>([]);
  const [customColors, setCustomColors] = useState<Record<string, string>>({});

  const chartContainerRef = useRef<HTMLDivElement>(null);

  const { t, tProp } = useLanguage();
  const { theme } = useTheme();

  const chartStyles = useMemo(() => {
    const isDark = theme === 'dark';
    return {
        gridStroke: isDark ? '#475569' : '#e2e8f0',
        axisStroke: isDark ? '#94a3b8' : '#64748b',
        axisTextFill: isDark ? '#cbd5e1' : '#475569',
        tooltipBg: isDark ? '#0f172a' : '#ffffff', 
        barFill: '#3b82f6'
    };
  }, [theme]);

  // 1. Extract Numeric Properties
  const numericProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        const num = Number(val.value);
        if (!isNaN(num) && val.value !== '' && val.value !== null) {
          props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  const addFilter = () => {
    if (numericProperties.length > 0) {
        setFilters([...filters, { id: Date.now().toString(), key: numericProperties[0], min: '', max: '' }]);
    }
  };

  const removeFilter = (id: string) => {
    setFilters(filters.filter(f => f.id !== id));
  };

  const updateFilter = (id: string, field: keyof RangeFilter, value: string) => {
    setFilters(filters.map(f => f.id === id ? { ...f, [field]: value } : f));
  };

  const filteredData = useMemo(() => {
    if (filters.length === 0) return data;
    return data.filter(item => {
        return filters.every(f => {
             const valObj = item.properties[f.key];
             if (!valObj) return false;
             const val = Number(valObj.value);
             if (isNaN(val)) return false;

             const min = f.min === '' ? -Infinity : Number(f.min);
             const max = f.max === '' ? Infinity : Number(f.max);

             return val >= min && val <= max;
        });
    });
  }, [data, filters]);

  const categoricalProperties = useMemo(() => {
    const props = new Set<string>(['manufacturer']); 
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (typeof val.value === 'string' && val.value.length < 20) {
            props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  const propertyUnits = useMemo(() => {
    const units: Record<string, string> = {};
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (v.unit && !units[k]) units[k] = v.unit;
        });
    });
    return units;
  }, [data]);

  // Calculate Active Keys with Fallback priority
  const activeYKey = useMemo(() => {
    if (userYAxisKey && numericProperties.includes(userYAxisKey)) return userYAxisKey;
    const defaults = ['熔体流动速率', 'MFR', '拉伸强度', 'Tensile Str.', '密度', 'Density'];
    for (const d of defaults) {
        if (numericProperties.includes(d)) return d;
    }
    return numericProperties[0] || '';
  }, [userYAxisKey, numericProperties]);

  const activeXKey = useMemo(() => {
    if (userXAxisKey && numericProperties.includes(userXAxisKey)) return userXAxisKey;
    const defaults = ['密度', 'Density', '熔体流动速率', 'MFR'];
    for (const d of defaults) {
        if (numericProperties.includes(d) && d !== activeYKey) return d;
    }
    // Fallback to second property or first
    if (numericProperties.length > 1 && numericProperties[1] !== activeYKey) return numericProperties[1];
    return numericProperties[0] || '';
  }, [userXAxisKey, numericProperties, activeYKey]);

  const chartData = useMemo(() => {
    return filteredData.map(product => {
      const flattened: any = {
        name: product.gradeName,
        manufacturer: product.manufacturer,
        id: product.id
      };

      Object.entries(product.properties).forEach(([key, val]) => {
        const numVal = Number(val.value);
        if (!isNaN(numVal) && val.value !== '' && val.value !== null) {
          flattened[key] = numVal;
        } else {
          flattened[key] = val.value;
        }
      });
      return flattened;
    });
  }, [filteredData]);

  const scatterGroups = useMemo(() => {
    if (chartType !== 'scatter' || colorByKey === 'none') return null;

    const groups: Record<string, any[]> = {};
    chartData.forEach(d => {
        const keyVal = d[colorByKey];
        const groupName = keyVal ? String(keyVal) : 'Unclassified';
        if (!groups[groupName]) groups[groupName] = [];
        groups[groupName].push(d);
    });
    return groups;
  }, [chartData, chartType, colorByKey]);

  const colorMap = useMemo(() => {
    if (colorByKey === 'none') return null;
    const uniqueValues = Array.from(new Set(chartData.map(d => String(d[colorByKey] || 'Unclassified'))));
    const map: Record<string, string> = {};
    uniqueValues.forEach((val, idx) => {
        map[val] = customColors[val] || COLORS[idx % COLORS.length];
    });
    return map;
  }, [chartData, colorByKey, customColors]);

  // Trendline Logic
  const trendlineSegment = useMemo(() => {
    if (chartType !== 'scatter' || !showTrendline || chartData.length < 2) return null;

    let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0, count = 0;
    const validPoints: {x: number, y: number}[] = [];

    chartData.forEach((point) => {
        const x = point[activeXKey];
        const y = point[activeYKey];
        if (typeof x === 'number' && typeof y === 'number' && !isNaN(x) && !isNaN(y)) {
            sumX += x; sumY += y; sumXY += x * y; sumXX += x * x; count++;
            validPoints.push({x, y});
        }
    });

    if (count < 2) return null;
    const slope = (count * sumXY - sumX * sumY) / (count * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / count;

    const xValues = validPoints.map(p => p.x);
    const minX = Math.min(...xValues);
    const maxX = Math.max(...xValues);

    return [
        { x: minX, y: slope * minX + intercept },
        { x: maxX, y: slope * maxX + intercept }
    ] as [{ x: number; y: number }, { x: number; y: number }];
  }, [chartData, activeXKey, activeYKey, showTrendline, chartType]);

  const handleExportJSON = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(chartData));
    const link = document.createElement('a');
    link.href = dataStr;
    link.download = "chart_data.json";
    link.click();
  };

  const handleExportCSV = () => {
    if (chartData.length === 0) return;
    const allKeys = Array.from(new Set(chartData.flatMap(Object.keys)));
    const header = allKeys.join(',');
    const rows = chartData.map(row => 
      allKeys.map(key => {
        const val = row[key];
        if (val === null || val === undefined) return '';
        const stringVal = String(val);
        if (stringVal.includes(',') || stringVal.includes('"') || stringVal.includes('\n')) {
          return `"${stringVal.replace(/"/g, '""')}"`;
        }
        return stringVal;
      }).join(',')
    );
    const csvContent = [header, ...rows].join('\n');
    const blob = new Blob(["\uFEFF" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'chart_data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleExportPNG = async () => {
    if (!chartContainerRef.current) return;
    try {
        const canvas = await html2canvas(chartContainerRef.current, {
            scale: 2, 
            backgroundColor: theme === 'dark' ? '#0f172a' : '#ffffff',
            logging: false,
            useCORS: true
        });
        const link = document.createElement('a');
        link.download = `chart_${Date.now()}.png`;
        link.href = canvas.toDataURL('image/png');
        link.click();
    } catch (err) {
        console.error("Export failed", err);
    }
  };

  const yAxisUnit = propertyUnits[activeYKey];
  const xAxisUnit = propertyUnits[activeXKey];
  const zAxisUnit = zAxisKey !== 'none' ? propertyUnits[zAxisKey] : '';

  const yAxisLabel = yAxisUnit ? `${tProp(activeYKey)} (${yAxisUnit})` : tProp(activeYKey);
  const xAxisLabel = xAxisUnit ? `${tProp(activeXKey)} (${xAxisUnit})` : tProp(activeXKey);

  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const pointData = payload[0].payload;
      if (!pointData) return null;

      const priorityProps = ['乙烯含量', '二烯烃含量', 'VA含量', '密度', '熔体流动速率'].filter(k => k !== activeXKey && k !== activeYKey);

      return (
        <div className="bg-white dark:bg-slate-900 p-3.5 border border-slate-200 dark:border-slate-800 shadow-xl rounded-lg text-sm min-w-[280px] z-50 transition-colors backdrop-blur-sm bg-opacity-95">
            <div className="mb-2 pb-2 border-b border-slate-100 dark:border-slate-800">
                <p className="font-bold text-slate-800 dark:text-slate-100">{pointData.name}</p>
                <div className="flex items-center gap-1.5 text-xs text-slate-500 mt-1">
                    <Factory size={12} />
                    <span>{pointData.manufacturer}</span>
                </div>
            </div>

            <div className="grid grid-cols-2 gap-2 mb-2">
                 <div className="flex flex-col bg-slate-50 dark:bg-slate-800/50 p-1.5 rounded">
                     <span className="text-[10px] text-slate-400 uppercase">{tProp(activeXKey)}</span>
                     <span className="font-mono font-semibold text-blue-600 dark:text-blue-400">
                         {pointData[activeXKey]} {xAxisUnit}
                     </span>
                 </div>
                 <div className="flex flex-col bg-slate-50 dark:bg-slate-800/50 p-1.5 rounded">
                     <span className="text-[10px] text-slate-400 uppercase">{tProp(activeYKey)}</span>
                     <span className="font-mono font-semibold text-emerald-600 dark:text-emerald-400">
                         {pointData[activeYKey]} {yAxisUnit}
                     </span>
                 </div>
            </div>

            {priorityProps.map(key => pointData[key] !== undefined && (
                <div key={key} className="flex justify-between text-xs py-1 border-t border-slate-50 dark:border-slate-800/50">
                    <span className="text-slate-500">{tProp(key)}:</span>
                    <span className="font-mono text-slate-700 dark:text-slate-300">{pointData[key]} {propertyUnits[key]}</span>
                </div>
            ))}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="flex h-full w-full gap-4 relative">
      {/* Configuration Sidebar */}
      <div 
        className={`bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm flex flex-col transition-all duration-300 overflow-hidden z-10
            ${showConfig ? 'w-80' : 'w-0 opacity-0 pointer-events-none border-0'}`}
      >
        <div className="p-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-950/50">
           <h3 className="font-semibold text-slate-800 dark:text-slate-200 flex items-center gap-2">
               <Settings2 size={18} className="text-emerald-600 dark:text-emerald-500"/>
               {t('chartConfig')}
           </h3>
           <button onClick={() => setShowConfig(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200">
               <X size={16} />
           </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-6 custom-scrollbar">

            {/* Chart Type Selection */}
            <div className="space-y-3">
                <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider block">{t('chartType')}</label>
                <div className="grid grid-cols-2 gap-2">
                    <button 
                        onClick={() => setChartType('bar')}
                        className={`flex flex-col items-center justify-center p-3 rounded-lg border transition-all ${chartType === 'bar' ? 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-500 text-emerald-700 dark:text-emerald-400' : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'}`}
                    >
                        <BarChart2 size={24} className="mb-1" />
                        <span className="text-xs font-medium">{t('barChart')}</span>
                    </button>
                    <button 
                        onClick={() => setChartType('scatter')}
                        className={`flex flex-col items-center justify-center p-3 rounded-lg border transition-all ${chartType === 'scatter' ? 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-500 text-emerald-700 dark:text-emerald-400' : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'}`}
                    >
                        <Activity size={24} className="mb-1" />
                        <span className="text-xs font-medium">{t('scatterChart')}</span>
                    </button>
                </div>
            </div>

            {/* Axis Configuration */}
            <div className="space-y-4">
                <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider block flex items-center gap-2">
                    <MoveVertical size={14} />
                    {t('axisMapping')}
                </label>

                <div className="space-y-3">
                    <div>
                        <span className="text-xs text-slate-500 dark:text-slate-400 mb-1 block">{t('yAxis')} ({t('val')})</span>
                        <div className="relative">
                            <select 
                                value={activeYKey} 
                                onChange={(e) => setUserYAxisKey(e.target.value)}
                                className="w-full pl-3 pr-8 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm appearance-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-colors"
                            >
                                {numericProperties.map(key => (
                                    <option key={key} value={key}>{tProp(key)}</option>
                                ))}
                            </select>
                            <ChevronDown size={14} className="absolute right-3 top-3 text-slate-400 pointer-events-none" />
                        </div>
                    </div>

                    {chartType === 'scatter' && (
                         <div className="animate-in fade-in slide-in-from-top-2 duration-200">
                            <span className="text-xs text-slate-500 dark:text-slate-400 mb-1 block">{t('xAxis')}</span>
                            <div className="relative">
                                <select 
                                    value={activeXKey} 
                                    onChange={(e) => setUserXAxisKey(e.target.value)}
                                    className="w-full pl-3 pr-8 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm appearance-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-colors"
                                >
                                    {numericProperties.map(key => (
                                        <option key={key} value={key}>{tProp(key)}</option>
                                    ))}
                                </select>
                                <ChevronDown size={14} className="absolute right-3 top-3 text-slate-400 pointer-events-none" />
                            </div>
                        </div>
                    )}

                    {chartType === 'scatter' && (
                        <div className="animate-in fade-in slide-in-from-top-2 duration-200">
                             <span className="text-xs text-slate-500 dark:text-slate-400 mb-1 block">{t('zAxis')} (Size)</span>
                             <div className="relative">
                                <select 
                                    value={zAxisKey} 
                                    onChange={(e) => setZAxisKey(e.target.value)}
                                    className="w-full pl-3 pr-8 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm appearance-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-colors"
                                >
                                    <option value="none">{t('noneAxis')}</option>
                                    {numericProperties.map(key => (
                                        <option key={key} value={key}>{tProp(key)}</option>
                                    ))}
                                </select>
                                <ChevronDown size={14} className="absolute right-3 top-3 text-slate-400 pointer-events-none" />
                            </div>
                        </div>
                    )}
                </div>
            </div>

            {/* Styling & Color */}
            <div className="space-y-4">
                 <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider block flex items-center gap-2">
                    <Palette size={14} />
                    {t('styleGrouping')}
                </label>

                <div>
                    <span className="text-xs text-slate-500 dark:text-slate-400 mb-1 block">{t('groupBy')} (Color)</span>
                    <div className="relative">
                         <select 
                            value={colorByKey} 
                            onChange={(e) => setColorByKey(e.target.value)}
                            className="w-full pl-3 pr-8 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm appearance-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-colors"
                        >
                            <option value="none">{t('colorSingle')}</option>
                            {categoricalProperties.map(key => (
                                <option key={key} value={key}>{tProp(key)}</option>
                            ))}
                        </select>
                        <ChevronDown size={14} className="absolute right-3 top-3 text-slate-400 pointer-events-none" />
                    </div>
                </div>

                {/* Legend Customization for Grouping */}
                {colorByKey !== 'none' && colorMap && (
                     <div className="mt-2 space-y-1.5 animate-in fade-in slide-in-from-top-2 duration-200 max-h-40 overflow-y-auto custom-scrollbar pr-1 border border-slate-100 dark:border-slate-800 rounded-lg p-1 bg-slate-50/50 dark:bg-slate-900/50">
                        {Object.entries(colorMap).map(([groupName, color]) => (
                            <div key={groupName} className="flex items-center justify-between text-xs px-2 py-1.5 rounded hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors group">
                                <span className="truncate max-w-[140px] text-slate-600 dark:text-slate-300 font-medium" title={groupName}>
                                    {groupName}
                                </span>
                                <div className="relative flex items-center gap-2">
                                     {customColors[groupName] && (
                                        <button 
                                            onClick={() => {
                                                const newColors = {...customColors};
                                                delete newColors[groupName];
                                                setCustomColors(newColors);
                                            }}
                                            className="text-slate-300 hover:text-slate-500 opacity-0 group-hover:opacity-100 transition-opacity"
                                            title="Reset"
                                        >
                                            <RefreshCw size={12} />
                                        </button>
                                     )}
                                    <div className="relative w-5 h-5 rounded-md shadow-sm border border-slate-200 dark:border-slate-600 overflow-hidden hover:scale-105 transition-transform cursor-pointer">
                                         <div className="absolute inset-0" style={{ backgroundColor: color }} />
                                         <input 
                                            type="color" 
                                            value={color}
                                            onChange={(e) => setCustomColors(prev => ({ ...prev, [groupName]: e.target.value }))}
                                            className="absolute inset-0 opacity-0 w-full h-full cursor-pointer"
                                         />
                                    </div>
                                </div>
                            </div>
                        ))}
                     </div>
                )}

                {/* Trendline Configuration */}
                {chartType === 'scatter' && (
                    <div className="mt-3 p-3 bg-slate-50 dark:bg-slate-800/50 rounded-lg border border-slate-100 dark:border-slate-800 space-y-3">
                        <div className="flex items-center justify-between">
                             <div className="flex items-center gap-2">
                                <TrendingUp size={16} className="text-emerald-600 dark:text-emerald-500" />
                                <span className="text-xs font-medium text-slate-700 dark:text-slate-300">{t('showTrendline')}</span>
                            </div>
                            <button
                                onClick={() => setShowTrendline(!showTrendline)}
                                className={`w-9 h-5 rounded-full relative transition-colors duration-200 ease-in-out ${showTrendline ? 'bg-emerald-500' : 'bg-slate-300 dark:bg-slate-600'}`}
                            >
                                <span className={`absolute top-0.5 left-0.5 w-4 h-4 rounded-full bg-white shadow-sm transition-transform duration-200 ease-in-out ${showTrendline ? 'translate-x-4' : 'translate-x-0'}`} />
                            </button>
                        </div>

                        {showTrendline && (
                            <div className="pt-2 border-t border-slate-200 dark:border-slate-700 space-y-2 animate-in slide-in-from-top-1">
                                <div className="grid grid-cols-2 gap-2">
                                    <div>
                                        <label className="text-[10px] text-slate-500 dark:text-slate-400 block mb-1">{t('trendlineColor')}</label>
                                        <div className="flex items-center gap-2">
                                            <input 
                                                type="color" 
                                                value={trendlineColor}
                                                onChange={(e) => setTrendlineColor(e.target.value)}
                                                className="h-6 w-8 p-0 bg-transparent border-0 cursor-pointer rounded"
                                            />
                                            <span className="text-xs text-slate-600 dark:text-slate-300 font-mono">{trendlineColor}</span>
                                        </div>
                                    </div>
                                    <div>
                                         <label className="text-[10px] text-slate-500 dark:text-slate-400 block mb-1">{t('trendlineWidth')}</label>
                                         <input 
                                            type="range" 
                                            min="1" 
                                            max="5" 
                                            step="0.5"
                                            value={trendlineWidth}
                                            onChange={(e) => setTrendlineWidth(Number(e.target.value))}
                                            className="w-full h-1 bg-slate-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-emerald-500"
                                         />
                                    </div>
                                </div>
                                <div>
                                    <label className="text-[10px] text-slate-500 dark:text-slate-400 block mb-1">{t('trendlineStyle')}</label>
                                    <select
                                        value={trendlineStyle}
                                        onChange={(e) => setTrendlineStyle(e.target.value as 'solid' | 'dashed' | 'dotted')}
                                        className="w-full py-1 px-2 text-xs bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded focus:border-emerald-500 outline-none"
                                    >
                                        <option value="solid">{t('solid')}</option>
                                        <option value="dashed">{t('dashed')}</option>
                                        <option value="dotted">{t('dotted')}</option>
                                    </select>
                                </div>
                            </div>
                        )}
                    </div>
                )}
            </div>

            {/* Data Filters */}
            <div className="space-y-3 pt-2 border-t border-slate-100 dark:border-slate-800">
                <div className="flex items-center justify-between">
                     <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider block flex items-center gap-2">
                        <Filter size={14} />
                        {t('dataFilters')}
                    </label>
                    <button onClick={addFilter} className="text-emerald-600 dark:text-emerald-500 hover:bg-emerald-50 dark:hover:bg-emerald-900/20 p-1 rounded transition-colors">
                        <Plus size={14} />
                    </button>
                </div>
                {filters.length === 0 ? (
                    <p className="text-xs text-slate-400 italic">{t('noFilters')}</p>
                ) : (
                    filters.map(filter => (
                        <div key={filter.id} className="bg-slate-50 dark:bg-slate-800/50 p-2 rounded-lg border border-slate-100 dark:border-slate-800 animate-in slide-in-from-left-2 duration-200">
                             <div className="flex items-center justify-between mb-1.5">
                                 <select 
                                    value={filter.key}
                                    onChange={(e) => updateFilter(filter.id, 'key', e.target.value)}
                                    className="text-xs bg-transparent font-medium text-slate-700 dark:text-slate-300 border-none p-0 focus:ring-0 cursor-pointer"
                                 >
                                     {numericProperties.map(key => <option key={key} value={key}>{tProp(key)}</option>)}
                                 </select>
                                 <button onClick={() => removeFilter(filter.id)} className="text-slate-400 hover:text-red-500 transition-colors">
                                     <Trash2 size={12} />
                                 </button>
                             </div>
                             <div className="flex items-center gap-2">
                                 <div className="relative flex-1">
                                     <input 
                                        type="number" 
                                        placeholder={t('min')} 
                                        value={filter.min}
                                        onChange={(e) => updateFilter(filter.id, 'min', e.target.value)}
                                        className="w-full text-xs px-2 py-1 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded focus:border-emerald-500 outline-none"
                                     />
                                 </div>
                                 <span className="text-slate-400 text-xs">-</span>
                                 <div className="relative flex-1">
                                     <input 
                                        type="number" 
                                        placeholder={t('max')} 
                                        value={filter.max}
                                        onChange={(e) => updateFilter(filter.id, 'max', e.target.value)}
                                        className="w-full text-xs px-2 py-1 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded focus:border-emerald-500 outline-none"
                                     />
                                 </div>
                             </div>
                        </div>
                    ))
                )}
            </div>

            {/* Export Actions */}
            <div className="pt-4 border-t border-slate-100 dark:border-slate-800 grid grid-cols-3 gap-2">
                <button onClick={handleExportJSON} className="flex flex-col items-center justify-center p-2 rounded bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-400 transition-colors">
                    <FileJson size={16} className="mb-1"/>
                    <span className="text-[10px] font-medium">JSON</span>
                </button>
                <button onClick={handleExportCSV} className="flex flex-col items-center justify-center p-2 rounded bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-400 transition-colors">
                    <FileSpreadsheet size={16} className="mb-1"/>
                    <span className="text-[10px] font-medium">CSV</span>
                </button>
                <button onClick={handleExportPNG} className="flex flex-col items-center justify-center p-2 rounded bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-400 transition-colors">
                    <ImageDown size={16} className="mb-1"/>
                    <span className="text-[10px] font-medium">PNG</span>
                </button>
            </div>

        </div>
      </div>

      {/* Main Chart Area */}
      <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden relative">

        {/* Toggle Config Button */}
        {!showConfig && (
            <button 
                onClick={() => setShowConfig(true)}
                className="absolute top-4 left-4 z-10 p-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 shadow-md rounded-lg text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors animate-in fade-in zoom-in"
                title={t('expandConfig')}
            >
                <Settings2 size={18} />
            </button>
        )}

        {/* Header */}
        <div className="h-16 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between px-6 bg-slate-50/50 dark:bg-slate-950/30">
            <h2 className="font-bold text-lg text-slate-800 dark:text-slate-100 flex items-center gap-2">
               {t('chartTitle')}
               <span className="text-sm font-normal text-slate-500 dark:text-slate-400 bg-slate-100 dark:bg-slate-800 px-2 py-0.5 rounded-full border border-slate-200 dark:border-slate-700">
                   {filteredData.length} items
               </span>
            </h2>
            <div className="flex items-center gap-4 text-xs font-medium text-slate-500 dark:text-slate-400">
                <div className="flex items-center gap-1.5">
                    <div className="w-2 h-2 rounded-full bg-blue-500"></div>
                    <span>{xAxisLabel}</span>
                </div>
                <ArrowRight size={12} />
                <div className="flex items-center gap-1.5">
                     <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
                     <span>{yAxisLabel}</span>
                </div>
            </div>
        </div>

        {/* Chart */}
        <div className="flex-1 p-4 w-full h-full" ref={chartContainerRef}>
            {chartData.length === 0 ? (
                 <div className="h-full flex flex-col items-center justify-center text-slate-400 dark:text-slate-500">
                    <Activity size={48} className="mb-4 opacity-50" />
                    <p className="text-lg font-medium">{t('noNumericData')}</p>
                 </div>
            ) : (
                <ResponsiveContainer width="100%" height="100%">
                    {chartType === 'bar' ? (
                        <BarChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 40 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={chartStyles.gridStroke} vertical={false} />
                            <XAxis 
                                dataKey="name" 
                                angle={-45} 
                                textAnchor="end" 
                                height={70} 
                                tick={{ fill: chartStyles.axisTextFill, fontSize: 10 }}
                                stroke={chartStyles.axisStroke}
                            />
                            <YAxis 
                                label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', fill: chartStyles.axisTextFill, fontSize: 11 }}
                                tick={{ fill: chartStyles.axisTextFill, fontSize: 11 }}
                                stroke={chartStyles.axisStroke}
                            />
                            <RechartsTooltip content={<CustomTooltip />} cursor={{ fill: theme === 'dark' ? '#334155' : '#f1f5f9', opacity: 0.4 }} />
                            {colorByKey !== 'none' && colorMap ? (
                                <Bar dataKey={activeYKey} radius={[4, 4, 0, 0]}>
                                    {chartData.map((entry, index) => {
                                        const color = colorMap[String(entry[colorByKey] || 'Unclassified')] || chartStyles.barFill;
                                        return <Cell key={`cell-${index}`} fill={color} />;
                                    })}
                                </Bar>
                            ) : (
                                <Bar dataKey={activeYKey} fill={chartStyles.barFill} radius={[4, 4, 0, 0]} />
                            )}
                        </BarChart>
                    ) : (
                        <ScatterChart margin={{ top: 20, right: 30, left: 20, bottom: 20 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={chartStyles.gridStroke} />
                            <XAxis 
                                type="number" 
                                dataKey={activeXKey} 
                                name={tProp(activeXKey)} 
                                label={{ value: xAxisLabel, position: 'bottom', offset: 0, fill: chartStyles.axisTextFill, fontSize: 11 }}
                                tick={{ fill: chartStyles.axisTextFill, fontSize: 11 }}
                                stroke={chartStyles.axisStroke}
                                domain={['auto', 'auto']}
                            />
                            <YAxis 
                                type="number" 
                                dataKey={activeYKey} 
                                name={tProp(activeYKey)} 
                                label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', fill: chartStyles.axisTextFill, fontSize: 11 }}
                                tick={{ fill: chartStyles.axisTextFill, fontSize: 11 }}
                                stroke={chartStyles.axisStroke}
                                domain={['auto', 'auto']}
                            />
                            {zAxisKey !== 'none' && <ZAxis type="number" dataKey={zAxisKey} range={[50, 400]} name={tProp(zAxisKey)} />}

                            <RechartsTooltip content={<CustomTooltip />} cursor={{ strokeDasharray: '3 3' }} />

                            {/* Trendline via ReferenceLine */}
                            {chartType === 'scatter' && showTrendline && trendlineSegment && (
                                <ReferenceLine
                                    segment={trendlineSegment}
                                    stroke={trendlineColor}
                                    strokeWidth={trendlineWidth}
                                    strokeDasharray={trendlineStyle === 'solid' ? '0' : (trendlineStyle === 'dashed' ? '5 5' : '2 2')}
                                />
                            )}

                            {/* Data Points */}
                            {colorByKey !== 'none' && scatterGroups ? (
                                Object.entries(scatterGroups).map(([group, groupData], idx) => (
                                    <Scatter 
                                        key={group} 
                                        name={group} 
                                        data={groupData} 
                                        fill={colorMap![group] || COLORS[idx % COLORS.length]} 
                                    />
                                ))
                            ) : (
                                <Scatter name="Products" data={chartData} fill="#3b82f6" />
                            )}

                            {colorByKey !== 'none' && <Legend wrapperStyle={{ fontSize: '11px', paddingTop: '10px' }} />}
                        </ScatterChart>
                    )}
                </ResponsiveContainer>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useRef } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer,
  ScatterChart, Scatter, ZAxis, Cell, ReferenceLine
} from 'recharts';
import { Product } from '../types';
import { 
  BarChart2, Activity, TrendingUp, FileJson, FileSpreadsheet, ImageDown,
  Factory, Settings2, Palette, MoveVertical, Filter, Plus, Trash2, X, ChevronDown, ArrowRight, Beaker, RefreshCw
} from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16', '#6366f1'];

interface RangeFilter {
    id: string;
    key: string;
    min: string;
    max: string;
}

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('scatter');
  const [userXAxisKey, setUserXAxisKey] = useState<string>('');
  const [userYAxisKey, setUserYAxisKey] = useState<string>('');
  const [zAxisKey, setZAxisKey] = useState<string>('none');
  const [colorByKey, setColorByKey] = useState<string>('none');

  const [showTrendline, setShowTrendline] = useState<boolean>(true);
  const [trendlineColor, setTrendlineColor] = useState<string>('#ef4444');
  const [trendlineWidth, setTrendlineWidth] = useState<number>(3);
  const [trendlineStyle, setTrendlineStyle] = useState<'solid' | 'dashed' | 'dotted'>('solid');

  const [showConfig, setShowConfig] = useState<boolean>(true);
  const [filters, setFilters] = useState<RangeFilter[]>([]);
  const [customColors, setCustomColors] = useState<Record<string, string>>({});

  const chartContainerRef = useRef<HTMLDivElement>(null);

  const { t, tProp } = useLanguage();
  const { theme } = useTheme();

  const chartStyles = useMemo(() => {
    const isDark = theme === 'dark';
    return {
        gridStroke: isDark ? '#475569' : '#e2e8f0',
        axisStroke: isDark ? '#94a3b8' : '#64748b',
        axisTextFill: isDark ? '#cbd5e1' : '#475569',
        tooltipBg: isDark ? '#0f172a' : '#ffffff', 
        barFill: '#3b82f6'
    };
  }, [theme]);

  // 1. Extract Numeric Properties
  const numericProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        const num = Number(val.value);
        if (!isNaN(num) && val.value !== '' && val.value !== null) {
          props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  const addFilter = () => {
    if (numericProperties.length > 0) {
        setFilters([...filters, { id: Date.now().toString(), key: numericProperties[0], min: '', max: '' }]);
    }
  };

  const removeFilter = (id: string) => {
    setFilters(filters.filter(f => f.id !== id));
  };

  const updateFilter = (id: string, field: keyof RangeFilter, value: string) => {
    setFilters(filters.map(f => f.id === id ? { ...f, [field]: value } : f));
  };

  const filteredData = useMemo(() => {
    if (filters.length === 0) return data;
    return data.filter(item => {
        return filters.every(f => {
             const valObj = item.properties[f.key];
             if (!valObj) return false;
             const val = Number(valObj.value);
             if (isNaN(val)) return false;

             const min = f.min === '' ? -Infinity : Number(f.min);
             const max = f.max === '' ? Infinity : Number(f.max);

             return val >= min && val <= max;
        });
    });
  }, [data, filters]);

  const categoricalProperties = useMemo(() => {
    const props = new Set<string>(['manufacturer']); 
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (typeof val.value === 'string' && val.value.length < 20) {
            props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  const propertyUnits = useMemo(() => {
    const units: Record<string, string> = {};
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (v.unit && !units[k]) units[k] = v.unit;
        });
    });
    return units;
  }, [data]);

  // Calculate Active Keys with Fallback priority
  const activeYKey = useMemo(() => {
    if (userYAxisKey && numericProperties.includes(userYAxisKey)) return userYAxisKey;
    const defaults = ['熔体流动速率', 'MFR', '拉伸强度', 'Tensile Str.', '密度', 'Density'];
    for (const d of defaults) {
        if (numericProperties.includes(d)) return d;
    }
    return numericProperties[0] || '';
  }, [userYAxisKey, numericProperties]);

  const activeXKey = useMemo(() => {
    if (userXAxisKey && numericProperties.includes(userXAxisKey)) return userXAxisKey;
    const defaults = ['密度', 'Density', '熔体流动速率', 'MFR'];
    for (const d of defaults) {
        if (numericProperties.includes(d) && d !== activeYKey) return d;
    }
    // Fallback to second property or first
    if (numericProperties.length > 1 && numericProperties[1] !== activeYKey) return numericProperties[1];
    return numericProperties[0] || '';
  }, [userXAxisKey, numericProperties, activeYKey]);

  const chartData = useMemo(() => {
    return filteredData.map(product => {
      const flattened: any = {
        name: product.gradeName,
        manufacturer: product.manufacturer,
        id: product.id
      };

      Object.entries(product.properties).forEach(([key, val]) => {
        const numVal = Number(val.value);
        if (!isNaN(numVal) && val.value !== '' && val.value !== null) {
          flattened[key] = numVal;
        } else {
          flattened[key] = val.value;
        }
      });
      return flattened;
    });
  }, [filteredData]);

  const scatterGroups = useMemo(() => {
    if (chartType !== 'scatter' || colorByKey === 'none') return null;

    const groups: Record<string, any[]> = {};
    chartData.forEach(d => {
        const keyVal = d[colorByKey];
        const groupName = keyVal ? String(keyVal) : 'Unclassified';
        if (!groups[groupName]) groups[groupName] = [];
        groups[groupName].push(d);
    });
    return groups;
  }, [chartData, chartType, colorByKey]);

  const colorMap = useMemo(() => {
    if (colorByKey === 'none') return null;
    const uniqueValues = Array.from(new Set(chartData.map(d => String(d[colorByKey] || 'Unclassified'))));
    const map: Record<string, string> = {};
    uniqueValues.forEach((val, idx) => {
        map[val] = customColors[val] || COLORS[idx % COLORS.length];
    });
    return map;
  }, [chartData, colorByKey, customColors]);

  // Trendline Logic
  const trendlineSegment = useMemo(() => {
    if (chartType !== 'scatter' || !showTrendline || chartData.length < 2) return null;

    let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0, count = 0;
    const validPoints: {x: number, y: number}[] = [];

    chartData.forEach((point) => {
        const x = point[activeXKey];
        const y = point[activeYKey];
        if (typeof x === 'number' && typeof y === 'number' && !isNaN(x) && !isNaN(y)) {
            sumX += x; sumY += y; sumXY += x * y; sumXX += x * x; count++;
            validPoints.push({x, y});
        }
    });

    if (count < 2) return null;
    const slope = (count * sumXY - sumX * sumY) / (count * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / count;

    const xValues = validPoints.map(p => p.x);
    const minX = Math.min(...xValues);
    const maxX = Math.max(...xValues);

    return [
        { x: minX, y: slope * minX + intercept },
        { x: maxX, y: slope * maxX + intercept }
    ] as [{ x: number; y: number }, { x: number; y: number }];
  }, [chartData, activeXKey, activeYKey, showTrendline, chartType]);

  const handleExportJSON = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(chartData));
    const link = document.createElement('a');
    link.href = dataStr;
    link.download = "chart_data.json";
    link.click();
  };

  const handleExportCSV = () => {
    if (chartData.length === 0) return;
    const allKeys = Array.from(new Set(chartData.flatMap(Object.keys)));
    const header = allKeys.join(',');
    const rows = chartData.map(row => 
      allKeys.map(key => {
        const val = row[key];
        if (val === null || val === undefined) return '';
        const stringVal = String(val);
        if (stringVal.includes(',') || stringVal.includes('"') || stringVal.includes('\n')) {
          return `"${stringVal.replace(/"/g, '""')}"`;
        }
        return stringVal;
      }).join(',')
    );
    const csvContent = [header, ...rows].join('\n');
    const blob = new Blob(["\uFEFF" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'chart_data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleExportPNG = async () => {
    if (!chartContainerRef.current) return;
    try {
        const canvas = await html2canvas(chartContainerRef.current, {
            scale: 2, 
            backgroundColor: theme === 'dark' ? '#0f172a' : '#ffffff',
            logging: false,
            useCORS: true
        });
        const link = document.createElement('a');
        link.download = `chart_${Date.now()}.png`;
        link.href = canvas.toDataURL('image/png');
        link.click();
    } catch (err) {
        console.error("Export failed", err);
    }
  };

  const yAxisUnit = propertyUnits[activeYKey];
  const xAxisUnit = propertyUnits[activeXKey];
  const zAxisUnit = zAxisKey !== 'none' ? propertyUnits[zAxisKey] : '';

  const yAxisLabel = yAxisUnit ? `${tProp(activeYKey)} (${yAxisUnit})` : tProp(activeYKey);
  const xAxisLabel = xAxisUnit ? `${tProp(activeXKey)} (${xAxisUnit})` : tProp(activeXKey);

  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const pointData = payload[0].payload;
      if (!pointData) return null;

      const priorityProps = ['乙烯含量', '二烯烃含量', 'VA含量', '密度', '熔体流动速率'].filter(k => k !== activeXKey && k !== activeYKey);

      return (
        <div className="bg-white dark:bg-slate-900 p-3.5 border border-slate-200 dark:border-slate-800 shadow-xl rounded-lg text-sm min-w-[280px] z-50 transition-colors backdrop-blur-sm bg-opacity-95">
            <div className="mb-2 pb-2 border-b border-slate-100 dark:border-slate-800">
                <p className="font-bold text-slate-800 dark:text-slate-100">{pointData.name}</p>
                <div className="flex items-center gap-1.5 text-xs text-slate-500 mt-1">
                    <Factory size={12} />
                    <span>{pointData.manufacturer}</span>
                </div>
            </div>

            <div className="grid grid-cols-2 gap-2 mb-2">
                 <div className="flex flex-col bg-slate-50 dark:bg-slate-800/50 p-1.5 rounded">
                     <span className="text-[10px] text-slate-400 uppercase">{tProp(activeXKey)}</span>
                     <span className="font-mono font-semibold text-blue-600 dark:text-blue-400">
                         {pointData[activeXKey]} {xAxisUnit}
                     </span>
                 </div>
                 <div className="flex flex-col bg-slate-50 dark:bg-slate-800/50 p-1.5 rounded">
                     <span className="text-[10px] text-slate-400 uppercase">{tProp(activeYKey)}</span>
                     <span className="font-mono font-semibold text-emerald-600 dark:text-emerald-400">
                         {pointData[activeYKey]} {yAxisUnit}
                     </span>
                 </div>
            </div>

            {priorityProps.map(key => pointData[key] !== undefined && (
                <div key={key} className="flex justify-between text-xs py-1 border-t border-slate-50 dark:border-slate-800/50">
                    <span className="text-slate-500">{tProp(key)}:</span>
                    <span className="font-mono text-slate-700 dark:text-slate-300">{pointData[key]} {propertyUnits[key]}</span>
                </div>
            ))}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="flex h-full w-full gap-4 relative">
      {/* Configuration Sidebar */}
      <div 
        className={`bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm flex flex-col transition-all duration-300 overflow-hidden z-10
            ${showConfig ? 'w-80' : 'w-0 opacity-0 pointer-events-none border-0'}`}
      >
        <div className="p-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-950/50">
           <h3 className="font-semibold text-slate-800 dark:text-slate-200 flex items-center gap-2">
               <Settings2 size={18} className="text-emerald-600 dark:text-emerald-500"/>
               {t('chartConfig')}
           </h3>
           <button onClick={() => setShowConfig(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200">
               <X size={16} />
           </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-6 custom-scrollbar">

            {/* Chart Type Selection */}
            <div className="space-y-3">
                <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider block">{t('chartType')}</label>
                <div className="grid grid-cols-2 gap-2">
                    <button 
                        onClick={() => setChartType('bar')}
                        className={`flex flex-col items-center justify-center p-3 rounded-lg border transition-all ${chartType === 'bar' ? 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-500 text-emerald-700 dark:text-emerald-400' : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'}`}
