                        className="w-full max-h-32 min-h-[44px] py-2.5 pl-3 pr-10 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none resize-none custom-scrollbar"
                        rows={1}
                        style={{ height: 'auto', minHeight: '44px' }}
                    />
                    <div className="absolute right-2 bottom-2 text-[10px] text-slate-400 pointer-events-none select-none">
                        Gemini
