                    disabled={(!input.trim() && !attachedImage) || isLoading}
                    className="p-2.5 bg-emerald-600 hover:bg-emerald-500 disabled:bg-slate-200 dark:disabled:bg-slate-800 disabled:text-slate-400 text-white rounded-xl transition-all shadow-md disabled:shadow-none mb-0.5 shrink-0"
