import React, { useState } from 'react';
import { Search, SlidersHorizontal, Upload, LayoutGrid, BarChart2, Moon, Sun, Eye, EyeOff, CheckSquare, Square } from 'lucide-react';
import { ColumnConfig, ViewMode } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';

interface TopBarProps {
  searchQuery: string;
  onSearchChange: (query: string) => void;
  columns: ColumnConfig[];
  onToggleColumn: (key: string) => void;
  onToggleAllColumns: (visible: boolean) => void;
  onOpenImport: () => void;
  viewMode: ViewMode;
  onViewModeChange: (mode: ViewMode) => void;
}

export const TopBar: React.FC<TopBarProps> = ({
  searchQuery,
  onSearchChange,
  columns,
  onToggleColumn,
  onToggleAllColumns,
  onOpenImport,
  viewMode,
  onViewModeChange,
}) => {
  const [isColumnMenuOpen, setIsColumnMenuOpen] = useState(false);
  const { t, language, setLanguage, tProp } = useLanguage();
  const { theme, toggleTheme } = useTheme();

  return (
    <div className="h-16 px-6 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between z-30 transition-colors duration-300">
      {/* Search Bar */}
      <div className="flex-1 max-w-xl relative group">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-emerald-500 transition-colors" size={20} />
        <input
          type="text"
          placeholder={t('searchPlaceholder')}
          value={searchQuery}
          onChange={(e) => onSearchChange(e.target.value)}
          className="w-full pl-10 pr-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 transition-all dark:text-slate-200 placeholder:text-slate-400"
        />
      </div>

      {/* Actions */}
      <div className="flex items-center gap-3 ml-4">

        {/* View Toggle */}
        <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-lg border border-slate-200 dark:border-slate-700">
            <button
                onClick={() => onViewModeChange('grid')}
                className={`p-1.5 rounded-md transition-all ${viewMode === 'grid' ? 'bg-white dark:bg-slate-700 text-emerald-600 dark:text-emerald-400 shadow-sm' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-300'}`}
                title={t('viewList')}
            >
                <LayoutGrid size={18} />
            </button>
            <button
                onClick={() => onViewModeChange('chart')}
                className={`p-1.5 rounded-md transition-all ${viewMode === 'chart' ? 'bg-white dark:bg-slate-700 text-emerald-600 dark:text-emerald-400 shadow-sm' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-300'}`}
                title={t('viewChart')}
            >
                <BarChart2 size={18} />
            </button>
        </div>

        {/* Column Config (Only in Grid View) */}
        {viewMode === 'grid' && (
            <div className="relative">
            <button
                onClick={() => setIsColumnMenuOpen(!isColumnMenuOpen)}
                className={`flex items-center gap-2 px-3 py-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm font-medium transition-colors ${isColumnMenuOpen ? 'ring-2 ring-emerald-500/20 border-emerald-500 text-emerald-600' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700'}`}
            >
                <SlidersHorizontal size={18} />
                <span className="hidden sm:inline">{t('display')}</span>
            </button>

            {/* Column Menu Dropdown */}
            {isColumnMenuOpen && (
                <>
                <div className="fixed inset-0 z-10" onClick={() => setIsColumnMenuOpen(false)}></div>
                <div className="absolute right-0 top-full mt-2 w-72 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-xl z-20 flex flex-col max-h-[80vh] overflow-hidden animate-in fade-in zoom-in-95 duration-200">
                    <div className="p-3 border-b border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/50 flex justify-between items-center">
                        <span className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">{t('configureColumns')}</span>
                        <div className="flex gap-2">
                             <button onClick={() => onToggleAllColumns(true)} className="text-xs text-emerald-600 hover:text-emerald-700 font-medium">{t('all')}</button>
                             <span className="text-slate-300">|</span>
                             <button onClick={() => onToggleAllColumns(false)} className="text-xs text-slate-500 hover:text-slate-700">{t('none')}</button>
                        </div>
                    </div>
                    <div className="overflow-y-auto p-2 custom-scrollbar">
                        {columns.map(col => (
                            <label key={col.key} className={`flex items-center gap-3 px-3 py-2 rounded-lg cursor-pointer transition-colors ${col.isSystem ? 'opacity-50 cursor-not-allowed bg-slate-50 dark:bg-slate-800' : 'hover:bg-slate-50 dark:hover:bg-slate-800'}`}>
                                <div className="relative flex items-center justify-center text-slate-400">
                                    <input 
                                        type="checkbox" 
                                        checked={col.visible} 
                                        onChange={() => !col.isSystem && onToggleColumn(col.key)}
                                        disabled={col.isSystem}
                                        className="appearance-none w-4 h-4 rounded border border-slate-300 checked:bg-emerald-500 checked:border-emerald-500 disabled:checked:bg-slate-400 transition-colors"
                                    />
                                    {col.visible && <CheckSquare size={16} className="absolute pointer-events-none text-white" strokeWidth={3} />}
                                    {!col.visible && <Square size={16} className="absolute pointer-events-none text-transparent" />}
                                </div>
                                <span className={`text-sm ${col.visible ? 'text-slate-900 dark:text-slate-100 font-medium' : 'text-slate-500 dark:text-slate-400'}`}>
                                    {tProp(col.label)}
                                </span>
                                {col.visible ? <Eye size={14} className="ml-auto text-emerald-500 opacity-50" /> : <EyeOff size={14} className="ml-auto text-slate-300 opacity-50" />}
                            </label>
                        ))}
                    </div>
                </div>
                </>
            )}
            </div>
        )}

        <div className="w-px h-8 bg-slate-200 dark:bg-slate-800 mx-1"></div>

        {/* Import Button */}
        <button
          onClick={onOpenImport}
          className="flex items-center gap-2 px-4 py-2.5 bg-slate-900 dark:bg-emerald-600 hover:bg-slate-800 dark:hover:bg-emerald-500 text-white rounded-xl text-sm font-medium transition-all shadow-lg shadow-slate-200/50 dark:shadow-emerald-900/20 active:scale-95"
        >
          <Upload size={18} />
          <span className="hidden sm:inline">{t('importData')}</span>
        </button>

        <div className="w-px h-8 bg-slate-200 dark:bg-slate-800 mx-1"></div>

        {/* Theme Toggle */}
        <button 
            onClick={toggleTheme}
            className="p-2.5 text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition-colors"
            title={theme === 'dark' ? 'Light Mode' : 'Dark Mode'}
        >
            {theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}
        </button>

        {/* Language Toggle */}
        <button 
            onClick={() => setLanguage(language === 'zh' ? 'en' : 'zh')}
            className="p-2.5 text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition-colors font-bold text-xs flex items-center justify-center w-10"
            title="Switch Language"
        >
            {language === 'zh' ? 'EN' : '中'}
        </button>

      </div>
    </div>
  );
};

