import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { TreeView, TreeItem } from '@mui/x-tree-view';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import ChevronRightIcon from '@mui/icons-material/ChevronRight';
import { LayoutGrid } from './LayoutGrid';

interface TreeSidebarProps {
  categories: any[];
  selectedCategoryId: string | null;
  onCategorySelect: (categoryId: string | null) => void;
}

const TreeSidebar: React.FC<TreeSidebarProps> = ({ categories, selectedCategoryId, onCategorySelect }) => {
  const { t } = useTranslation();
  const [expanded, setExpanded] = useState<string[]>([]);
  const [selected, setSelected] = useState<string | null>(null);

  useEffect(() => {
    setSelected(selectedCategoryId);
  }, [selectedCategoryId]);

  const handleToggle = (event: React.SyntheticEvent, nodeIds: string[]) => {
    setExpanded(nodeIds);
  };

  const handleSelect = (event: React.SyntheticEvent, nodeId: string | null) => {
    setSelected(nodeId);
    onCategorySelect(nodeId);
  };

  const isCategorySelected = (categoryId: string | null) => {
    return selectedCategoryId === categoryId;
  };

  return (
    <LayoutGrid>
      <TreeView
        aria-label="file system navigator"
        defaultCollapseIcon={<ExpandMoreIcon />}
        defaultExpandIcon={<ChevronRightIcon />}
