          nodeId="all-products"
          label={
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                padding: '8px',
                borderRadius: '4px',
                background: isCategorySelected(null) ? 'linear-gradient(to right, #6dd5ed, #2193b0)' : 'transparent',
                color: isCategorySelected(null) ? 'white' : 'inherit',
                fontWeight: isCategorySelected(null) ? 'bold' : 'normal',
              }}
            >
              {t('allProducts')}
            </div>
          }
        />
        {categories.map((category) => (
          <TreeItem
            key={category.id}
            nodeId={category.id}
            label={
              <div
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  padding: '8px',
                  borderRadius: '4px',
                  background: isCategorySelected(category.id) ? 'linear-gradient(to right, #6dd5ed, #2193b0)' : 'transparent',
                  color: isCategorySelected(category.id) ? 'white' : 'inherit',
                  fontWeight: isCategorySelected(category.id) ? 'bold' : 'normal',
                }}
              >
                {category.name}
              </div>
            }
          >
            {category.children &&
              category.children.map((child: any) => (
                <TreeItem
                  key={child.id}
                  nodeId={child.id}
                  label={
                    <div
                      style={{
                        display: 'flex',
                        alignItems: 'center',
                        padding: '8px',
                        borderRadius: '4px',
                        marginLeft: '16px',
                        background: isCategorySelected(child.id) ? 'linear-gradient(to right, #6dd5ed, #2193b0)' : 'transparent',
                        color: isCategorySelected(child.id) ? 'white' : 'inherit',
                        fontWeight: isCategorySelected(child.id) ? 'bold' : 'normal',
                      }}
                    >
                      {child.name}


