                                         <input 
                                            type="color" 
                                            value={color}
                                            onChange={(e) => setCustomColors(prev => ({ ...prev, [groupName]: e.target.value }))}
                                            className="absolute inset-0 opacity-0 w-full h-full cursor-pointer"
                                         />
                                    </div>
                                </div>
                            </div>
