import React, { useState, useMemo } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  ReferenceLine
} from 'recharts';
import { Settings, Download, ChevronUp, ChevronDown, BarChart2, ScatterChart as ScatterIcon, TrendingUp } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';

interface DataVisualizerProps {
  data: Product[];
}

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const { t, tProp } = useLanguage();
  const { theme } = useTheme();

  const [showConfig, setShowConfig] = useState(true);
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('gradeName');
  const [yAxisKey, setYAxisKey] = useState<string>('');

  // Trendline Configuration State
  const [showTrendline, setShowTrendline] = useState(false);
  const [trendlineColor, setTrendlineColor] = useState('#ef4444');
  const [trendlineWidth, setTrendlineWidth] = useState(2);
  const [trendlineStyle, setTrendlineStyle] = useState<'solid' | 'dashed' | 'dotted'>('solid');

  // Extract keys that have numeric values across the dataset
  const numericKeys = useMemo(() => {
     const keys = new Set<string>();
     data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
           // Basic check if value looks numeric
           if (typeof v.value === 'number') {
               keys.add(k);
           } else if (!isNaN(Number(v.value)) && v.value !== '') {
               keys.add(k);
           }
        });
     });
     return Array.from(keys).sort();
  }, [data]);

  // Set default Y Axis if not set
  useMemo(() => {
      if (!yAxisKey && numericKeys.length > 0) {
          // Prefer common properties if available
          const preferred = ['密度', '熔体流动速率', '拉伸强度'].find(k => numericKeys.includes(k));
          setYAxisKey(preferred || numericKeys[0]);
      }
  }, [numericKeys, yAxisKey]);

  // Prepare Data for Recharts
  const chartData = useMemo(() => {
    return data.map(p => {
        const item: any = {
            id: p.id,
            gradeName: p.gradeName,
            manufacturer: p.manufacturer,
        };
        // Flatten properties
        Object.entries(p.properties).forEach(([k, v]) => {
            const num = Number(v.value);
            if (!isNaN(num) && v.value !== '') {
                item[k] = num;
            }
        });
        return item;
    });
  }, [data]);

  // Calculate Trendline (Linear Regression)
  const trendlineSegment = useMemo(() => {
    if (chartType !== 'scatter' || !showTrendline || !xAxisKey || !yAxisKey) return null;

    // Can only calculate trendline if X axis is numeric
    if (!numericKeys.includes(xAxisKey)) return null;

    const points = chartData
        .map(d => ({ x: Number(d[xAxisKey]), y: Number(d[yAxisKey]) }))
        .filter(p => !isNaN(p.x) && !isNaN(p.y));

    if (points.length < 2) return null;

    const n = points.length;
    const sumX = points.reduce((a, b) => a + b.x, 0);
    const sumY = points.reduce((a, b) => a + b.y, 0);
    const sumXY = points.reduce((a, b) => a + b.x * b.y, 0);
    const sumXX = points.reduce((a, b) => a + b.x * b.x, 0);

    const slope = (n * sumXY - sumX * sumY) / (n * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / n;

    if (isNaN(slope) || isNaN(intercept)) return null;

    const xValues = points.map(p => p.x);
    const minX = Math.min(...xValues);
    const maxX = Math.max(...xValues);

    // Cast to explicit tuple to satisfy Recharts ReferenceLine segment prop
    return [
        { x: minX, y: slope * minX + intercept },
        { x: maxX, y: slope * maxX + intercept }
    ] as [{ x: number; y: number }, { x: number; y: number }];
  }, [chartData, chartType, showTrendline, xAxisKey, yAxisKey, numericKeys]);

  const handleExport = () => {
      const dataStr = JSON.stringify(chartData, null, 2);
      const blob = new Blob([dataStr], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = "chart_data.json";
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
  };

  const gridColor = theme === 'dark' ? '#334155' : '#e2e8f0';
  const textColor = theme === 'dark' ? '#94a3b8' : '#64748b';
  const tooltipBg = theme === 'dark' ? '#1e293b' : '#ffffff';
  const tooltipBorder = theme === 'dark' ? '#334155' : '#e2e8f0';

  if (numericKeys.length === 0) {
      return (
        <div className="flex flex-col items-center justify-center h-full text-slate-400 dark:text-slate-500 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800">
            <BarChart2 size={48} className="mb-4 opacity-20" />
            <p>{t('noNumericData')}</p>
        </div>
      );
  }

  // Use 'any' type for tooltip props to avoid compatibility issues with Recharts type definitions
  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      const dataItem = payload[0].payload;
      return (
        <div 
            style={{ backgroundColor: tooltipBg, borderColor: tooltipBorder }}
            className="p-3 border rounded-lg shadow-xl text-sm z-50"
        >
          <p className="font-bold text-slate-800 dark:text-slate-100 mb-1">{dataItem.gradeName}</p>
          <p className="text-xs text-slate-500 mb-2 border-b border-slate-100 dark:border-slate-700 pb-1">{dataItem.manufacturer}</p>
          {payload.map((entry: any, index: number) => (
             <div key={index} className="flex items-center gap-2 my-0.5">
                <div className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color }}></div>
                <span className="text-slate-600 dark:text-slate-300 font-medium">{tProp(entry.name as string)}:</span>
                <span className="font-mono">{Number(entry.value).toFixed(2)}</span>
             </div>
          ))}
          {chartType === 'scatter' && xAxisKey !== 'gradeName' && (
              <div className="flex items-center gap-2 my-0.5">
                 <div className="w-2 h-2 rounded-full bg-slate-400"></div>
                 <span className="text-slate-600 dark:text-slate-300 font-medium">{tProp(xAxisKey)}:</span>
                 <span className="font-mono">{Number(dataItem[xAxisKey]).toFixed(2)}</span>
              </div>
          )}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-950 rounded-xl relative overflow-hidden">
       {/* Toolbar */}
       <div className="absolute top-4 right-4 z-20 flex gap-2">
           <button 
             onClick={handleExport}
             className="p-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg shadow-sm text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors"
             title={t('exportJson')}
           >
               <Download size={18} />
           </button>
           <button 
             onClick={() => setShowConfig(!showConfig)}
             className={`p-2 border border-slate-200 dark:border-slate-700 rounded-lg shadow-sm transition-colors flex items-center gap-2 text-sm font-medium
                ${showConfig ? 'bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 border-emerald-200 dark:border-emerald-800' : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300'}
             `}
           >
               <Settings size={18} />
               <span className="hidden sm:inline">{t('chartConfig')}</span>
               {showConfig ? <ChevronUp size={16}/> : <ChevronDown size={16}/>}
           </button>
       </div>

       {/* Config Panel */}
       {showConfig && (
           <div className="bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 p-4 animate-in slide-in-from-top-2 z-10 shadow-sm">
               <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-4xl">
                   <div>
                       <label className="block text-xs font-bold text-slate-500 dark:text-slate-500 uppercase tracking-wider mb-2">{t('chartType')}</label>
                       <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-lg border border-slate-200 dark:border-slate-700">
                           <button 
                             onClick={() => setChartType('bar')}
                             className={`flex-1 py-1.5 px-3 text-xs font-medium rounded-md transition-all flex items-center justify-center gap-2 ${chartType === 'bar' ? 'bg-white dark:bg-slate-700 shadow-sm text-emerald-600 dark:text-emerald-400' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'}`}
                           >
                               <BarChart2 size={14} />
                               {t('barChart')}
                           </button>
                           <button 
                             onClick={() => setChartType('scatter')}
                             className={`flex-1 py-1.5 px-3 text-xs font-medium rounded-md transition-all flex items-center justify-center gap-2 ${chartType === 'scatter' ? 'bg-white dark:bg-slate-700 shadow-sm text-emerald-600 dark:text-emerald-400' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'}`}
                           >
                               <ScatterIcon size={14} />
                               {t('scatterChart')}
                           </button>
                       </div>
                   </div>

                   <div>
                       <label className="block text-xs font-bold text-slate-500 dark:text-slate-500 uppercase tracking-wider mb-2">{t('xAxis')}</label>
                       <div className="relative">
                            <select 
                                value={xAxisKey} 
                                onChange={(e) => setXAxisKey(e.target.value)}
                                className="w-full pl-3 pr-8 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm text-slate-700 dark:text-slate-200 outline-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 appearance-none transition-colors"
                            >
                                <option value="gradeName">{tProp('牌号')}</option>
                                {numericKeys.map(k => (
                                    <option key={k} value={k}>{tProp(k)}</option>
                                ))}
                            </select>
                            <ChevronDown className="absolute right-3 top-2.5 text-slate-400 pointer-events-none" size={16} />
                       </div>
                   </div>

                   <div>
                       <label className="block text-xs font-bold text-slate-500 dark:text-slate-500 uppercase tracking-wider mb-2">{t('yAxis')}</label>
                       <div className="relative">
                            <select 
                                value={yAxisKey} 
                                onChange={(e) => setYAxisKey(e.target.value)}
                                className="w-full pl-3 pr-8 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm text-slate-700 dark:text-slate-200 outline-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 appearance-none transition-colors"
                            >
                                {numericKeys.map(k => (
                                    <option key={k} value={k}>{tProp(k)}</option>
                                ))}
                            </select>
                            <ChevronDown className="absolute right-3 top-2.5 text-slate-400 pointer-events-none" size={16} />
                        </div>
                   </div>
               </div>

               {/* Trendline Configuration Section */}
               {chartType === 'scatter' && numericKeys.includes(xAxisKey) && (
                   <div className="mt-4 pt-4 border-t border-slate-100 dark:border-slate-800 animate-in fade-in slide-in-from-top-1">
                       <div className="flex flex-wrap items-center gap-6">
                           <label className="flex items-center gap-2 cursor-pointer select-none">
                               <div className="relative">
                                   <input 
                                     type="checkbox" 
                                     checked={showTrendline} 
                                     onChange={(e) => setShowTrendline(e.target.checked)}
                                     className="sr-only peer"
                                   />
                                   <div className="w-9 h-5 bg-slate-200 peer-focus:outline-none rounded-full peer dark:bg-slate-700 peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all dark:border-gray-600 peer-checked:bg-emerald-600"></div>
                               </div>
                               <span className="text-sm font-medium text-slate-700 dark:text-slate-300 flex items-center gap-1.5">
                                   <TrendingUp size={16} className="text-emerald-600 dark:text-emerald-500"/>
                                   {t('showTrendline')}
                               </span>
                           </label>

                           {showTrendline && (
                               <>
                                   <div className="flex items-center gap-2">
                                       <span className="text-xs font-bold text-slate-500 dark:text-slate-500 uppercase">{t('trendlineColor')}</span>
                                       <div className="flex items-center gap-2 bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded-md border border-slate-200 dark:border-slate-700">
                                            <input 
                                                type="color" 
                                                value={trendlineColor}
                                                onChange={(e) => setTrendlineColor(e.target.value)}
                                                className="w-5 h-5 rounded cursor-pointer bg-transparent border-0 p-0"
                                            />
                                            <span className="text-xs font-mono text-slate-600 dark:text-slate-400">{trendlineColor}</span>
                                       </div>
                                   </div>

                                   <div className="flex items-center gap-2">
                                       <span className="text-xs font-bold text-slate-500 dark:text-slate-500 uppercase">{t('trendlineWidth')}</span>
                                       <div className="flex items-center gap-2">
                                            <input 
                                                type="range" 
                                                min="1" 
                                                max="5" 
                                                step="0.5" 
                                                value={trendlineWidth}
                                                onChange={(e) => setTrendlineWidth(Number(e.target.value))}
                                                className="w-20 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-emerald-500"
                                            />
                                            <span className="text-xs font-mono text-slate-600 dark:text-slate-400 w-4">{trendlineWidth}</span>
                                       </div>
                                   </div>

                                   <div className="flex items-center gap-2">
                                       <span className="text-xs font-bold text-slate-500 dark:text-slate-500 uppercase">{t('trendlineStyle')}</span>
                                       <div className="relative">
                                            <select 
                                                value={trendlineStyle} 
                                                onChange={(e) => setTrendlineStyle(e.target.value as any)}
                                                className="pl-2 pr-6 py-1 bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md text-xs focus:ring-1 focus:ring-emerald-500 outline-none appearance-none cursor-pointer"
                                            >
                                                <option value="solid">{t('solid')}</option>
                                                <option value="dashed">{t('dashed')}</option>
                                                <option value="dotted">{t('dotted')}</option>
                                            </select>
                                            <ChevronDown className="absolute right-1 top-1.5 text-slate-400 pointer-events-none" size={12} />
                                       </div>
                                   </div>
                               </>
                           )}
                       </div>
                   </div>
               )}
           </div>
