            <Database size={12} />
            {t('dataCatalog')}
        </h2>

        {/* Fixed 'All Products' Root Node */}
        <div 
            role="button"
            tabIndex={0}
            className={`
              flex items-center px-3 py-2.5 mx-2 rounded-lg text-sm cursor-pointer transition-all duration-200 outline-none focus:ring-2 focus:ring-emerald-500/50
              ${!selectedCategoryId 
                ? 'bg-gradient-to-r from-emerald-600 to-emerald-500 text-white shadow-md shadow-emerald-900/20 dark:shadow-emerald-900/40 font-semibold' 
                : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800/60 hover:text-slate-900 dark:hover:text-slate-200'
