import React, { useState, useMemo, useEffect } from 'react';
import { Product, ColumnConfig, SortConfig } from '../types';
import { MoreHorizontal, FileText, Factory, CalendarClock, Edit, Trash2, CheckSquare, Square, MinusSquare, ArrowUp, ArrowDown, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { EditProductModal } from './EditProductModal';
import { DeleteConfirmationModal } from './DeleteConfirmationModal';

interface DataGridProps {
  data: Product[];
  columns: ColumnConfig[];
  isLoading: boolean;
  onDelete: (ids: string[]) => void;
  onUpdate: (product: Product) => void;
}

export const DataGrid: React.FC<DataGridProps> = ({ data, columns, isLoading, onDelete, onUpdate }) => {
  const { t, tProp } = useLanguage();
  const visibleColumns = columns.filter((c) => c.visible);

  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [deletingIds, setDeletingIds] = useState<string[] | null>(null);

  // Sorting State
  const [sortConfig, setSortConfig] = useState<SortConfig | null>(null);

  // Pagination State
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(15);

  // Reset pagination when data changes length (e.g. search filter)
  useEffect(() => {
    setCurrentPage(1);
  }, [data.length]);

  const handleSort = (key: string) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const sortedData = useMemo(() => {
    if (!sortConfig) return data;
    return [...data].sort((a, b) => {
      // Helper to get value for sorting
      const getVal = (p: Product, k: string) => {
        if (k === 'gradeName') return p.gradeName;
        if (k === 'manufacturer') return p.manufacturer;
        if (k === 'updatedAt') return p.updatedAt;
        const prop = p.properties[k];
        return prop && prop.value !== undefined ? prop.value : '';
      };

      const valA = getVal(a, sortConfig.key);
      const valB = getVal(b, sortConfig.key);

      if (typeof valA === 'number' && typeof valB === 'number') {
        return sortConfig.direction === 'asc' ? valA - valB : valB - valA;
      }
      return sortConfig.direction === 'asc' 
        ? String(valA).localeCompare(String(valB))
        : String(valB).localeCompare(String(valA));
    });
  }, [data, sortConfig]);

  const paginatedData = useMemo(() => {
    const startIndex = (currentPage - 1) * pageSize;
    return sortedData.slice(startIndex, startIndex + pageSize);
  }, [sortedData, currentPage, pageSize]);

  const totalPages = Math.ceil(sortedData.length / pageSize);

  // Calculate Max Values for Numeric Columns (for visual bars)
  const columnMaxValues = useMemo(() => {
    const maxVals: Record<string, number> = {};
    visibleColumns.forEach(col => {
       if (['gradeName', 'manufacturer', 'updatedAt'].includes(col.key)) return;
       // Find max in the ENTIRE sorted dataset (or just current page? dataset is better context)
       let max = 0;
       data.forEach(p => {
           const v = p.properties[col.key]?.value;
           if (typeof v === 'number' && v > max) max = v;
           else if (v && !isNaN(Number(v)) && Number(v) > max) max = Number(v);
       });
       if (max > 0) maxVals[col.key] = max;
    });
    return maxVals;
  }, [data, visibleColumns]);

  const isAllSelected = paginatedData.length > 0 && paginatedData.every(p => selectedIds.has(p.id));
  const isIndeterminate = paginatedData.some(p => selectedIds.has(p.id)) && !isAllSelected;

  const toggleSelectAll = () => {
    const newSet = new Set(selectedIds);
    if (isAllSelected) {
      paginatedData.forEach(p => newSet.delete(p.id));
    } else {
      paginatedData.forEach(p => newSet.add(p.id));
    }
    setSelectedIds(newSet);
  };

  const toggleSelectRow = (id: string) => {
    const newSet = new Set(selectedIds);
    if (newSet.has(id)) {
      newSet.delete(id);
    } else {
      newSet.add(id);
    }
    setSelectedIds(newSet);
  };

  const handleBatchDeleteClick = () => {
    setDeletingIds(Array.from(selectedIds));
  };

  const handleDeleteSingleClick = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      setDeletingIds([id]);
  };

  const handleConfirmDelete = () => {
      if (deletingIds && deletingIds.length > 0) {
          onDelete(deletingIds);
          const newSet = new Set(selectedIds);
          deletingIds.forEach(id => newSet.delete(id));
          setSelectedIds(newSet);
          setDeletingIds(null);
      }
  };

  const handleEditClick = (product: Product, e: React.MouseEvent) => {
      e.stopPropagation();
      setEditingProduct(product);
  };

  const deletingProductNames = useMemo(() => {
    if (!deletingIds) return [];
    return deletingIds.map(id => {
        const product = data.find(p => p.id === id);
        return product ? product.gradeName : id;
    });
  }, [deletingIds, data]);

  if (isLoading) {
    return (
        <div className="flex flex-col items-center justify-center h-64 text-slate-400 dark:text-slate-500">
            <div className="w-8 h-8 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin mb-4 shadow-[0_0_10px_rgba(16,185,129,0.2)]"></div>
            <span className="text-sm font-medium">{t('loading')}</span>
        </div>
    );
  }

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-[500px] text-slate-400 dark:text-slate-500 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm">
        <div className="w-16 h-16 bg-slate-50 dark:bg-slate-800 rounded-full flex items-center justify-center mb-4 transition-colors">
            <FileText size={32} className="text-slate-300 dark:text-slate-600" />
        </div>
        <p className="text-lg font-semibold text-slate-700 dark:text-slate-300">{t('noProducts')}</p>
        <p className="text-sm text-slate-500 dark:text-slate-500 mt-1">{t('noProductsDesc')}</p>
      </div>
    );
  }

  return (
    <>
    <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden flex flex-col h-full transition-colors duration-300 relative">

      {/* Batch Action Toolbar */}
      {selectedIds.size > 0 && (
          <div className="absolute top-0 left-0 right-0 z-30 h-[60px] bg-emerald-50/95 dark:bg-slate-800/95 backdrop-blur-sm border-b border-emerald-100 dark:border-slate-700 flex items-center justify-between px-6 animate-in slide-in-from-top-2 duration-200 shadow-md">
              <div className="flex items-center gap-3 text-sm font-medium text-emerald-800 dark:text-emerald-300">
                  <div className="flex items-center justify-center w-6 h-6 bg-emerald-600 rounded-md text-white shadow-sm">
                      <MinusSquare size={16} />
                  </div>
                  <span className="font-semibold">{selectedIds.size} {t('selected')}</span>
              </div>
              <div className="flex gap-3">
                  <button 
                    onClick={handleBatchDeleteClick}
                    className="flex items-center gap-2 px-4 py-2 bg-rose-600 hover:bg-rose-700 active:bg-rose-800 text-white rounded-lg text-sm font-bold transition-all shadow-lg shadow-rose-500/30 hover:shadow-rose-500/50 focus:ring-2 focus:ring-rose-500/50 focus:outline-none transform active:scale-95"
                  >
                      <Trash2 size={16} />
                      {t('deleteSelected')}
                  </button>
              </div>
          </div>
      )}

      <div className="overflow-x-auto overflow-y-auto custom-scrollbar flex-1">
        <table className="w-full text-sm text-left border-collapse">
          <thead className="text-xs text-slate-500 dark:text-slate-400 uppercase bg-slate-50/80 dark:bg-slate-900/90 sticky top-0 z-20 backdrop-blur-sm">
            <tr>
              <th className="w-10 px-5 py-3.5 border-b border-slate-200 dark:border-slate-800 bg-slate-50/80 dark:bg-slate-900/90 z-20">
                 <div 
                    onClick={toggleSelectAll}
                    className="cursor-pointer text-slate-400 hover:text-emerald-600 dark:hover:text-emerald-500 transition-colors"
                 >
                     {isAllSelected ? <CheckSquare size={18} className="text-emerald-600 dark:text-emerald-500"/> : (isIndeterminate ? <MinusSquare size={18} className="text-emerald-600 dark:text-emerald-500"/> : <Square size={18}/>)}
                 </div>
              </th>
              {visibleColumns.map((col) => {
                  const maxVal = columnMaxValues[col.key];
                  const isNum = !!maxVal;
                  const isSortActive = sortConfig?.key === col.key;

                  return (
                      <th 
                        key={col.key} 
                        onClick={() => handleSort(col.key)}
                        className={`px-5 py-3.5 font-semibold border-b border-slate-200 dark:border-slate-800 whitespace-nowrap bg-slate-50/80 dark:bg-slate-900/90 transition-colors cursor-pointer group hover:bg-slate-100 dark:hover:bg-slate-800 ${isNum ? 'text-right' : 'text-left'}`}
                      >
                          <div className={`flex items-center gap-1.5 ${isNum ? 'justify-end' : 'justify-start'}`}>
                              {tProp(col.label)}
                              <div className={`flex flex-col text-slate-300 dark:text-slate-600 ${isSortActive ? 'text-emerald-500' : 'group-hover:text-slate-400'}`}>
                                   {isSortActive && sortConfig?.direction === 'asc' ? <ArrowUp size={12} strokeWidth={3} /> : (isSortActive && sortConfig?.direction === 'desc' ? <ArrowDown size={12} strokeWidth={3} /> : <div className="h-3 w-3 flex flex-col justify-center items-center opacity-0 group-hover:opacity-100"><ArrowUp size={8}/><ArrowDown size={8}/></div>)}
                              </div>
                          </div>
                      </th>
                  );
              })}
              <th className="px-5 py-3.5 text-right border-b border-slate-200 dark:border-slate-800 bg-slate-50/80 dark:bg-slate-900/90 sticky right-0 z-30 w-24 backdrop-blur-sm transition-colors shadow-[-4px_0_8px_-2px_rgba(0,0,0,0.05)] dark:shadow-[-4px_0_8px_-2px_rgba(0,0,0,0.2)]">
                  {t('actions')}
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 dark:divide-slate-800/50 bg-white dark:bg-slate-900">
            {paginatedData.map((product) => {
              const isSelected = selectedIds.has(product.id);
              return (
                <tr 
                    key={product.id} 
                    className={`hover:bg-slate-50/80 dark:hover:bg-slate-800/40 transition-colors group ${isSelected ? 'bg-emerald-50/30 dark:bg-emerald-900/10' : ''}`}
                >
                  <td className="px-5 py-3 border-b border-slate-100 dark:border-slate-800/50">
                      <div 
                        onClick={() => toggleSelectRow(product.id)}
                        className="cursor-pointer text-slate-300 hover:text-emerald-600 dark:text-slate-600 dark:hover:text-emerald-500 transition-colors"
                      >
                         {isSelected ? <CheckSquare size={18} className="text-emerald-600 dark:text-emerald-500"/> : <Square size={18}/>}
                      </div>
                  </td>
                  {visibleColumns.map((col) => {
                    const maxVal = columnMaxValues[col.key];
                    const isNum = !!maxVal;
                    let content: React.ReactNode = <span className="text-slate-200 dark:text-slate-700">-</span>;
                    let cellStyle: React.CSSProperties = {};

                    if (col.key === 'gradeName') {
                        content = (
                          <div className="flex items-center gap-2">
                               <div className="w-2 h-2 rounded-full bg-emerald-500/50 dark:bg-emerald-500/80 shadow-[0_0_6px_rgba(16,185,129,0.3)]"></div>
                               <span className="font-bold text-slate-700 dark:text-slate-200 group-hover:text-emerald-700 dark:group-hover:text-emerald-400 transition-colors">{product.gradeName}</span>
                          </div>
                        );
                    } else if (col.key === 'manufacturer') {
                        content = (
                            <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400">
                                <Factory size={13} className="text-slate-400 dark:text-slate-600" />
                                <span className="truncate max-w-[180px]" title={product.manufacturer}>{product.manufacturer}</span>
                            </div>
                        );
                    } else if (col.key === 'updatedAt') {
                        content = (
                          <div className="flex items-center gap-1.5 text-slate-400 dark:text-slate-500 text-xs">
                               <CalendarClock size={12}/>
                               <span className="font-mono">{product.updatedAt}</span>
                          </div>
                        );
                    } else {
                        const prop = product.properties[col.key];
                        if (prop && prop.value !== undefined && prop.value !== null && prop.value !== '') {
                            const val = Number(prop.value);

                            // Visual Bar Logic
                            if (isNum && !isNaN(val)) {
                                const percent = Math.min((val / maxVal) * 100, 100);
                                // This gradient creates a bar that fills from right to left (if rtl) or left to right.
                                // For numeric text-right, a right-aligned bar might look weird, usually bars are left aligned.
                                // Let's make the background hint subtle.
                                cellStyle = {
                                    background: `linear-gradient(90deg, transparent ${100 - percent}%, rgba(16, 185, 129, 0.08) ${100 - percent}%)`
                                };
                            }

                            content = (
                                <span className="inline-flex items-baseline text-slate-700 dark:text-slate-300 relative z-10">
                                    {prop.value} 
                                    {prop.unit && <span className="text-slate-400 dark:text-slate-500 text-[10px] ml-1 font-medium">{prop.unit}</span>}
                                </span>
                            );
                        }
                    }

                    return (
                      <td 
                        key={`${product.id}-${col.key}`} 
                        className={`px-5 py-3 border-b border-slate-100 dark:border-slate-800/50 whitespace-nowrap transition-colors relative ${isNum ? 'text-right font-mono' : ''}`}
                        style={isNum ? {} : {}}
                      >
                        {/* Background Bar */}
                        {isNum && cellStyle.background && (
                            <div className="absolute inset-y-1 right-0 left-0" style={cellStyle}></div>
                        )}
                        {content}
                      </td>
                    );
                  })}
                  <td className="px-5 py-3 text-right border-b border-slate-100 dark:border-slate-800/50 sticky right-0 bg-white dark:bg-slate-900 group-hover:bg-slate-50/80 dark:group-hover:bg-slate-800/40 transition-colors z-20 shadow-[-4px_0_8px_-2px_rgba(0,0,0,0.05)] dark:shadow-[-4px_0_8px_-2px_rgba(0,0,0,0.2)]">
                    <div className="flex items-center justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button 
                            onClick={(e) => handleEditClick(product, e)}
                            className="p-1.5 rounded-md text-slate-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors"
                            title={t('edit')}
                            type="button"
                        >
                            <Edit size={16} />
                        </button>
                        <button 
                            onClick={(e) => handleDeleteSingleClick(product.id, e)}
                            className="p-1.5 rounded-md text-slate-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"
                            title={t('delete')}
                            type="button"
                        >
                            <Trash2 size={16} />
                        </button>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* Pagination Footer */}
      <div className="px-5 py-3 border-t border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-900 text-xs text-slate-500 dark:text-slate-400 flex justify-between items-center sticky bottom-0 z-20 transition-colors flex-shrink-0">
         <div className="flex items-center gap-4">
             <span>{t('showing')} {paginatedData.length > 0 ? (currentPage - 1) * pageSize + 1 : 0} - {Math.min(currentPage * pageSize, sortedData.length)} / {sortedData.length} {t('records')}</span>
             <select 
                value={pageSize}
                onChange={(e) => setPageSize(Number(e.target.value))}
                className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded px-2 py-1 outline-none focus:border-emerald-500"
             >
                 <option value={10}>10 / {t('page')}</option>
                 <option value={15}>15 / {t('page')}</option>
                 <option value={30}>30 / {t('page')}</option>
                 <option value={50}>50 / {t('page')}</option>
             </select>
         </div>

         <div className="flex items-center gap-2">
             <button 
                onClick={() => setCurrentPage(1)}
                disabled={currentPage === 1}
                className="p-1 rounded hover:bg-slate-200 dark:hover:bg-slate-700 disabled:opacity-30 disabled:hover:bg-transparent transition-colors"
                title="First Page"
             >
                 <ChevronsLeft size={16} />
             </button>
             <button 
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                disabled={currentPage === 1}
                className="p-1 rounded hover:bg-slate-200 dark:hover:bg-slate-700 disabled:opacity-30 disabled:hover:bg-transparent transition-colors"
                title={t('previous')}
             >
                 <ChevronLeft size={16} />
             </button>

             <span className="mx-2 font-medium text-slate-700 dark:text-slate-200">
                 {t('page')} {currentPage} / {Math.max(1, totalPages)}
             </span>

             <button 
                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                disabled={currentPage === totalPages || totalPages === 0}
                className="p-1 rounded hover:bg-slate-200 dark:hover:bg-slate-700 disabled:opacity-30 disabled:hover:bg-transparent transition-colors"
                title={t('next')}
             >
                 <ChevronRight size={16} />
             </button>
             <button 
                onClick={() => setCurrentPage(totalPages)}
                disabled={currentPage === totalPages || totalPages === 0}
                className="p-1 rounded hover:bg-slate-200 dark:hover:bg-slate-700 disabled:opacity-30 disabled:hover:bg-transparent transition-colors"
                title="Last Page"
             >
                 <ChevronsRight size={16} />
             </button>
         </div>
      </div>
    </div>

    <EditProductModal 
        isOpen={!!editingProduct} 
        onClose={() => setEditingProduct(null)} 
        product={editingProduct} 
        onSave={(updated) => {
            onUpdate(updated);
            setEditingProduct(null);
        }}
    />

    <DeleteConfirmationModal 
        isOpen={!!deletingIds}
        onClose={() => setDeletingIds(null)}
        onConfirm={handleConfirmDelete}
        productNames={deletingProductNames}
    />
    </>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { CATEGORY_TREE, MOCK_PRODUCTS } from './constants';
import { Product, ColumnConfig, ViewMode, Category } from './types';
import { TreeSidebar } from './components/TreeSidebar';
import { DataGrid } from './components/DataGrid';
import { DataVisualizer } from './components/DataVisualizer';
import { TopBar } from './components/TopBar';
import { ImportModal } from './components/ImportModal';
import { AIAssistant } from './components/AIAssistant';
import { LayoutDashboard, Database, Activity, Home, ChevronRight, Package, Factory, BarChart3, FlaskConical } from 'lucide-react';
import { LanguageProvider, useLanguage } from './contexts/LanguageContext';
import { ThemeProvider } from './contexts/ThemeContext';

const getDynamicColumns = (products: Product[]): ColumnConfig[] => {
  const propertyKeys = new Set<string>();
  products.forEach(p => {
    Object.keys(p.properties).forEach(k => propertyKeys.add(k));
  });

  const defaultVisible = ['密度', '熔体流动速率', '应用', '类型', '典型应用', '硬度', '悬臂梁缺口冲击', '拉伸强度'];

  const dynamicCols: ColumnConfig[] = Array.from(propertyKeys).map(key => ({
    key,
    label: key,
    visible: defaultVisible.includes(key),
    isSystem: false
  })).sort((a, b) => {
      // Prioritize numeric columns slightly for better default view
      const aIsLikelyImportant = defaultVisible.includes(a.key);
      const bIsLikelyImportant = defaultVisible.includes(b.key);
      if (aIsLikelyImportant && !bIsLikelyImportant) return -1;
      if (!aIsLikelyImportant && bIsLikelyImportant) return 1;
      return a.label.localeCompare(b.label);
  });

  const systemCols: ColumnConfig[] = [
    { key: 'gradeName', label: '牌号', visible: true, isSystem: true },
    { key: 'manufacturer', label: '生产厂家', visible: true, isSystem: true },
    { key: 'updatedAt', label: '更新时间', visible: false, isSystem: false },
  ];

  return [...systemCols, ...dynamicCols];
};

const Breadcrumbs: React.FC<{ categoryId: string | null }> = ({ categoryId }) => {
    const { t, language } = useLanguage();

    const path = useMemo(() => {
        if (!categoryId) return [];
        const findPath = (nodes: Category[], targetId: string, currentPath: Category[]): Category[] | null => {
            for (const node of nodes) {
                if (node.id === targetId) return [...currentPath, node];
                if (node.children) {
                    const childResult = findPath(node.children, targetId, [...currentPath, node]);
                    if (childResult) return childResult;
                }
            }
            return null;
        };
        return findPath(CATEGORY_TREE, categoryId, []) || [];
    }, [categoryId]);

    return (
