            const m = p.properties['熔体流动速率']?.value;
            if (typeof m === 'number') { mfrSum += m; mfrCount++; }
        });

        return {
            count: data.length,
            manufacturers,
            avgDensity: densityCount ? (densitySum / densityCount).toFixed(3) : '-',
