import React, { useState, useMemo, useEffect } from 'react';
import { Product, ColumnConfig, SortConfig } from '../types';
import { MoreHorizontal, FileText, Factory, CalendarClock, Edit, Trash2, CheckSquare, Square, MinusSquare, ArrowUp, ArrowDown, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight, ArrowUpDown } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { EditProductModal } from './EditProductModal';
import { DeleteConfirmationModal } from './DeleteConfirmationModal';

interface DataGridProps {
  data: Product[];
  columns: ColumnConfig[];
  isLoading: boolean;
  onDelete: (ids: string[]) => void;
  onUpdate: (product: Product) => void;
}

export const DataGrid: React.FC<DataGridProps> = ({ data, columns, isLoading, onDelete, onUpdate }) => {
  const { t, tProp } = useLanguage();
  const visibleColumns = columns.filter((c) => c.visible);

  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [deletingIds, setDeletingIds] = useState<string[] | null>(null);

  // Sorting State
  const [sortConfig, setSortConfig] = useState<SortConfig | null>(null);

  // Pagination State
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(15);

  useEffect(() => {
    setCurrentPage(1);
  }, [data.length]);

  const handleSort = (key: string) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const sortedData = useMemo(() => {
    if (!sortConfig) return data;
    return [...data].sort((a, b) => {
      const getVal = (p: Product, k: string) => {
        if (k === 'gradeName') return p.gradeName;
        if (k === 'manufacturer') return p.manufacturer;
        if (k === 'updatedAt') return p.updatedAt;
        const prop = p.properties[k];
        return prop && prop.value !== undefined ? prop.value : '';
      };

      const valA = getVal(a, sortConfig.key);
      const valB = getVal(b, sortConfig.key);

      if (typeof valA === 'number' && typeof valB === 'number') {
        return sortConfig.direction === 'asc' ? valA - valB : valB - valA;
      }
      return sortConfig.direction === 'asc' 
        ? String(valA).localeCompare(String(valB))
        : String(valB).localeCompare(String(valA));
    });
  }, [data, sortConfig]);

  const paginatedData = useMemo(() => {
    const startIndex = (currentPage - 1) * pageSize;
    return sortedData.slice(startIndex, startIndex + pageSize);
  }, [sortedData, currentPage, pageSize]);

  const totalPages = Math.ceil(sortedData.length / pageSize);

  const columnMaxValues = useMemo(() => {
    const maxVals: Record<string, number> = {};
    visibleColumns.forEach(col => {
       if (['gradeName', 'manufacturer', 'updatedAt'].includes(col.key)) return;
       let max = 0;
       data.forEach(p => {
           const v = p.properties[col.key]?.value;
           if (typeof v === 'number' && v > max) max = v;
           else if (v && !isNaN(Number(v)) && Number(v) > max) max = Number(v);
       });
       if (max > 0) maxVals[col.key] = max;
    });
    return maxVals;
  }, [data, visibleColumns]);

  const isAllSelected = paginatedData.length > 0 && paginatedData.every(p => selectedIds.has(p.id));
  const isIndeterminate = paginatedData.some(p => selectedIds.has(p.id)) && !isAllSelected;

  const toggleSelectAll = () => {
    const newSet = new Set(selectedIds);
    if (isAllSelected) {
      paginatedData.forEach(p => newSet.delete(p.id));
    } else {
      paginatedData.forEach(p => newSet.add(p.id));
    }
    setSelectedIds(newSet);
  };

  const toggleSelectRow = (id: string) => {
    const newSet = new Set(selectedIds);
    if (newSet.has(id)) {
      newSet.delete(id);
    } else {
      newSet.add(id);
    }
    setSelectedIds(newSet);
  };

  const handleBatchDeleteClick = () => {
    setDeletingIds(Array.from(selectedIds));
  };

  const handleDeleteSingleClick = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      setDeletingIds([id]);
  };

  const handleConfirmDelete = () => {
      if (deletingIds && deletingIds.length > 0) {
          onDelete(deletingIds);
          const newSet = new Set(selectedIds);
          deletingIds.forEach(id => newSet.delete(id));
          setSelectedIds(newSet);
          setDeletingIds(null);
      }
  };

  const handleEditClick = (product: Product, e: React.MouseEvent) => {
      e.stopPropagation();
      setEditingProduct(product);
  };

  const deletingProductNames = useMemo(() => {
    if (!deletingIds) return [];
    return deletingIds.map(id => {
        const product = data.find(p => p.id === id);
        return product ? product.gradeName : id;
    });
  }, [deletingIds, data]);

  if (isLoading) {
    return (
        <div className="flex flex-col items-center justify-center h-64 text-slate-400 dark:text-slate-500">
            <div className="w-8 h-8 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin mb-4 shadow-[0_0_10px_rgba(16,185,129,0.2)]"></div>
            <span className="text-sm font-medium animate-pulse">{t('loading')}</span>
        </div>
    );
  }

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-full min-h-[400px] text-slate-400 dark:text-slate-500 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm">
        <div className="w-16 h-16 bg-slate-50 dark:bg-slate-800 rounded-full flex items-center justify-center mb-4">
            <FileText size={32} className="text-slate-300 dark:text-slate-600" />
        </div>
        <p className="text-lg font-semibold text-slate-700 dark:text-slate-300">{t('noProducts')}</p>
        <p className="text-sm text-slate-500 dark:text-slate-500 mt-1">{t('noProductsDesc')}</p>
      </div>
    );
  }

  return (
    <>
    <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden flex flex-col h-full transition-colors duration-300 relative ring-1 ring-slate-900/5 dark:ring-white/10">

      {/* Batch Action Toolbar - Floating */}
      <div className={`absolute top-0 left-0 right-0 z-40 h-[52px] bg-emerald-50/95 dark:bg-slate-800/95 backdrop-blur-md border-b border-emerald-100 dark:border-slate-700 flex items-center justify-between px-4 transition-all duration-300 transform ${selectedIds.size > 0 ? 'translate-y-0 opacity-100' : '-translate-y-full opacity-0 pointer-events-none'}`}>
          <div className="flex items-center gap-3 text-sm font-medium text-emerald-800 dark:text-emerald-300">
              <div className="flex items-center justify-center w-5 h-5 bg-emerald-600 rounded text-white shadow-sm">
                  <MinusSquare size={14} />
              </div>
              <span className="font-semibold">{selectedIds.size} {t('selected')}</span>
          </div>
          <div className="flex gap-2">
              <button 
                onClick={handleBatchDeleteClick}
                className="flex items-center gap-1.5 px-3 py-1.5 bg-rose-600 hover:bg-rose-700 active:bg-rose-800 text-white rounded-lg text-xs font-bold transition-all shadow-md shadow-rose-500/20 active:scale-95"
              >
                  <Trash2 size={14} />
                  {t('deleteSelected')}
              </button>
          </div>
      </div>

      <div className="overflow-x-auto overflow-y-auto custom-scrollbar flex-1 relative">
        <table className="w-full text-sm text-left border-collapse">
          <thead className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase bg-slate-50/90 dark:bg-slate-900/95 sticky top-0 z-30 backdrop-blur-md shadow-sm">
            <tr>
              <th className="w-12 px-4 py-3 border-b border-slate-200 dark:border-slate-800">
                 <div 
                    onClick={toggleSelectAll}
                    className="cursor-pointer text-slate-400 hover:text-emerald-600 dark:hover:text-emerald-500 transition-colors flex justify-center"
                 >
                     {isAllSelected ? <CheckSquare size={16} className="text-emerald-600 dark:text-emerald-500"/> : (isIndeterminate ? <MinusSquare size={16} className="text-emerald-600 dark:text-emerald-500"/> : <Square size={16}/>)}
                 </div>
              </th>
              {visibleColumns.map((col) => {
                  const maxVal = columnMaxValues[col.key];
                  const isNum = !!maxVal;
                  const isSortActive = sortConfig?.key === col.key;

                  return (
                      <th 
                        key={col.key} 
                        onClick={() => handleSort(col.key)}
                        className={`px-5 py-3 border-b border-slate-200 dark:border-slate-800 whitespace-nowrap cursor-pointer group hover:bg-slate-100 dark:hover:bg-slate-800/80 transition-colors select-none ${isNum ? 'text-right' : 'text-left'}`}
                      >
                          <div className={`flex items-center gap-1.5 ${isNum ? 'justify-end' : 'justify-start'}`}>
                              <span className={`${isSortActive ? 'text-emerald-600 dark:text-emerald-400' : ''}`}>{tProp(col.label)}</span>
                              <span className={`flex flex-col ${isSortActive ? 'text-emerald-500' : 'text-slate-300 dark:text-slate-600 group-hover:text-slate-400'}`}>
                                   {isSortActive ? (sortConfig?.direction === 'asc' ? <ArrowUp size={12} strokeWidth={2.5}/> : <ArrowDown size={12} strokeWidth={2.5}/>) : <ArrowUpDown size={12} strokeWidth={1.5} className="opacity-0 group-hover:opacity-100 transition-opacity" />}
                              </span>
                          </div>
                      </th>
                  );
              })}
              <th className="px-5 py-3 text-right border-b border-slate-200 dark:border-slate-800 sticky right-0 z-40 w-24 bg-slate-50/95 dark:bg-slate-900/95 backdrop-blur-md shadow-[-4px_0_12px_-4px_rgba(0,0,0,0.1)] dark:shadow-[-4px_0_12px_-4px_rgba(0,0,0,0.5)]">
                  {t('actions')}
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 dark:divide-slate-800/60 bg-white dark:bg-slate-900">
            {paginatedData.map((product) => {
              const isSelected = selectedIds.has(product.id);
              return (
                <tr 
                    key={product.id} 
                    className={`group transition-colors duration-150 ${isSelected ? 'bg-emerald-50/40 dark:bg-emerald-900/20' : 'hover:bg-slate-50 dark:hover:bg-slate-800/40'}`}
                >
                  <td className="px-4 py-3 border-b border-slate-100 dark:border-slate-800/50">
                      <div 
                        onClick={() => toggleSelectRow(product.id)}
                        className="cursor-pointer text-slate-300 hover:text-emerald-600 dark:text-slate-600 dark:hover:text-emerald-500 transition-colors flex justify-center"
                      >
                         {isSelected ? <CheckSquare size={16} className="text-emerald-600 dark:text-emerald-500"/> : <Square size={16}/>}
                      </div>
                  </td>
                  {visibleColumns.map((col) => {
                    const maxVal = columnMaxValues[col.key];
                    const isNum = !!maxVal;
                    let content: React.ReactNode = <span className="text-slate-300 dark:text-slate-700">-</span>;
                    let barWidth = 0;

                    if (col.key === 'gradeName') {
                        content = (
                          <div className="flex items-center gap-2.5">
                               <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 dark:bg-emerald-400 shadow-[0_0_8px_rgba(16,185,129,0.4)]"></div>
                               <span className="font-bold text-slate-800 dark:text-slate-200 group-hover:text-emerald-700 dark:group-hover:text-emerald-400 transition-colors">{product.gradeName}</span>
                          </div>
                        );
                    } else if (col.key === 'manufacturer') {
                        content = (
                            <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400">
                                <Factory size={12} className="text-slate-400 dark:text-slate-600 shrink-0" />
                                <span className="truncate max-w-[160px] text-xs font-medium" title={product.manufacturer}>{product.manufacturer}</span>
                            </div>
                        );
                    } else if (col.key === 'updatedAt') {
                        content = (
                          <div className="flex items-center gap-1.5 text-slate-400 dark:text-slate-500 text-[10px] uppercase tracking-wider font-mono">
                               <span>{product.updatedAt}</span>
                          </div>
                        );
                    } else {
                        const prop = product.properties[col.key];
                        if (prop && prop.value !== undefined && prop.value !== null && prop.value !== '') {
                            const val = Number(prop.value);

                            // Visual Bar Logic
                            if (isNum && !isNaN(val)) {
                                barWidth = Math.min((val / maxVal) * 100, 100);
                            }

                            content = (
                                <span className="inline-flex items-baseline text-slate-700 dark:text-slate-300 relative z-10 font-mono text-xs">
                                    {prop.value} 
                                    {prop.unit && <span className="text-slate-400 dark:text-slate-500 text-[9px] ml-0.5 font-sans">{prop.unit}</span>}
                                </span>
                            );
                        }
                    }

                    return (
                      <td 
                        key={`${product.id}-${col.key}`} 
                        className={`px-5 py-2.5 border-b border-slate-100 dark:border-slate-800/50 whitespace-nowrap transition-colors relative ${isNum ? 'text-right' : ''}`}
                      >
                        {/* Background Bar for numeric values */}
                        {isNum && barWidth > 0 && (
                            <div className="absolute inset-y-2 left-2 right-2 rounded overflow-hidden pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                                 {/* Only show on hover to keep interface clean, or keep subtle always? Let's do subtle always + stronger on hover */}
                            </div>
                        )}
                        {isNum && barWidth > 0 && (
                             <div 
                                className="absolute bottom-1 right-0 h-0.5 bg-emerald-500/20 dark:bg-emerald-400/20 rounded-l-full transition-all duration-500"
                                style={{ width: `${barWidth}%`, right: '1.25rem' }} // Align with padding
                             ></div>
                        )}
                        {content}
                      </td>
                    );
                  })}
                  <td className="px-5 py-2.5 text-right border-b border-slate-100 dark:border-slate-800/50 sticky right-0 bg-white dark:bg-slate-900 group-hover:bg-slate-50 dark:group-hover:bg-slate-800/40 transition-colors z-30 shadow-[-4px_0_12px_-4px_rgba(0,0,0,0.02)] dark:shadow-[-4px_0_12px_-4px_rgba(0,0,0,0.5)]">
                    <div className="flex items-center justify-end gap-1 opacity-0 group-hover:opacity-100 transition-all duration-200 transform translate-x-2 group-hover:translate-x-0">
                        <button 
                            onClick={(e) => handleEditClick(product, e)}
                            className="p-1.5 rounded-md text-slate-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/30 transition-colors"
                            title={t('edit')}
                            type="button"
                        >
                            <Edit size={14} />
                        </button>
                        <button 
                            onClick={(e) => handleDeleteSingleClick(product.id, e)}
                            className="p-1.5 rounded-md text-slate-400 hover:text-rose-600 hover:bg-rose-50 dark:hover:bg-rose-900/30 transition-colors"
                            title={t('delete')}
                            type="button"
                        >
                            <Trash2 size={14} />
                        </button>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* Pagination Footer - Sticky Bottom */}
      <div className="px-5 py-3 border-t border-slate-200 dark:border-slate-800 bg-white/80 dark:bg-slate-900/90 backdrop-blur text-xs text-slate-500 dark:text-slate-400 flex justify-between items-center sticky bottom-0 z-30 transition-colors">
         <div className="flex items-center gap-4">
             <span className="font-medium text-slate-600 dark:text-slate-400">{t('showing')} <span className="text-slate-900 dark:text-slate-100 font-bold">{paginatedData.length > 0 ? (currentPage - 1) * pageSize + 1 : 0} - {Math.min(currentPage * pageSize, sortedData.length)}</span> / {sortedData.length}</span>
             <div className="h-4 w-px bg-slate-200 dark:bg-slate-700"></div>
             <select 
                value={pageSize}
                onChange={(e) => setPageSize(Number(e.target.value))}
                className="bg-transparent border-none text-slate-700 dark:text-slate-300 font-medium focus:ring-0 cursor-pointer hover:text-emerald-600 dark:hover:text-emerald-400 transition-colors pr-8"
             >
                 <option value={10}>10 / {t('page')}</option>
                 <option value={15}>15 / {t('page')}</option>
                 <option value={30}>30 / {t('page')}</option>
                 <option value={50}>50 / {t('page')}</option>
             </select>
         </div>

         <div className="flex items-center gap-1">
             <button 
                onClick={() => setCurrentPage(1)}
                disabled={currentPage === 1}
                className="p-1.5 rounded-md hover:bg-slate-100 dark:hover:bg-slate-800 disabled:opacity-30 disabled:hover:bg-transparent transition-colors text-slate-600 dark:text-slate-400"
             >
                 <ChevronsLeft size={14} />
             </button>
             <button 
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                disabled={currentPage === 1}
                className="p-1.5 rounded-md hover:bg-slate-100 dark:hover:bg-slate-800 disabled:opacity-30 disabled:hover:bg-transparent transition-colors text-slate-600 dark:text-slate-400"
             >
                 <ChevronLeft size={14} />
             </button>

             <span className="mx-3 font-mono text-slate-700 dark:text-slate-300">
                 {currentPage} <span className="text-slate-400">/</span> {Math.max(1, totalPages)}
             </span>

             <button 
                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                disabled={currentPage === totalPages || totalPages === 0}
                className="p-1.5 rounded-md hover:bg-slate-100 dark:hover:bg-slate-800 disabled:opacity-30 disabled:hover:bg-transparent transition-colors text-slate-600 dark:text-slate-400"
             >
                 <ChevronRight size={14} />
             </button>
             <button 
                onClick={() => setCurrentPage(totalPages)}
                disabled={currentPage === totalPages || totalPages === 0}
                className="p-1.5 rounded-md hover:bg-slate-100 dark:hover:bg-slate-800 disabled:opacity-30 disabled:hover:bg-transparent transition-colors text-slate-600 dark:text-slate-400"
             >
                 <ChevronsRight size={14} />
             </button>
         </div>
      </div>
    </div>

    <EditProductModal 
        isOpen={!!editingProduct} 
        onClose={() => setEditingProduct(null)} 
        product={editingProduct} 
        onSave={(updated) => {
            onUpdate(updated);
            setEditingProduct(null);
        }}
    />

    <DeleteConfirmationModal 
        isOpen={!!deletingIds}
        onClose={() => setDeletingIds(null)}
        onConfirm={handleConfirmDelete}
        productNames={deletingProductNames}
    />
    </>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Send, Image as ImageIcon, Sparkles, X, Loader2, BrainCircuit, Bot, User, Cpu, ScanEye, Trash2, Maximize2, Minimize2 } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';

interface AIAssistantProps {
  contextData: Product[];
}

interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  image?: string;
  isThinking?: boolean;
}

const FormattedText: React.FC<{ text: string; className?: string }> = ({ text, className }) => {
  if (!text) return null;

  return (
    <div className={className}>
      {text.split('\n').map((line, i) => {
        const trimmed = line.trim();
        if (trimmed.startsWith('- ') || trimmed.startsWith('* ') || trimmed.match(/^\d+\./)) {
             const cleanLine = trimmed.replace(/^[-*]\s+|\d+\.\s+/, '');
             const parts = cleanLine.split(/(\*\*.*?\*\*)/g);
             return (
                <div key={i} className="flex gap-2.5 ml-1 mb-1.5 items-start">
                    <span className="text-emerald-500 dark:text-emerald-400 mt-1.5 shrink-0 text-[10px]">•</span>
                    <span className="leading-relaxed text-sm">
                        {parts.map((part, j) => {
                            if (part.startsWith('**') && part.endsWith('**')) {
                                return <strong key={j} className="font-bold text-slate-800 dark:text-white">{part.slice(2, -2)}</strong>;
                            }
                            return <span key={j}>{part}</span>;
                        })}
                    </span>
                </div>
             );
        }

        const parts = line.split(/(\*\*.*?\*\*)/g);
        if (line.startsWith('##')) {
             return <h3 key={i} className="font-bold text-emerald-700 dark:text-emerald-400 mt-4 mb-2 text-base">{line.replace(/#/g, '')}</h3>
        }

        if (!trimmed) return <div key={i} className="h-2"></div>;

        return (
          <p key={i} className="mb-2 last:mb-0 leading-relaxed text-sm">
            {parts.map((part, j) => {
              if (part.startsWith('**') && part.endsWith('**')) {
                return <strong key={j} className="font-bold text-slate-800 dark:text-white">{part.slice(2, -2)}</strong>;
              }
              return <span key={j}>{part}</span>;
            })}
          </p>
        );
      })}
    </div>
  );
};

export const AIAssistant: React.FC<AIAssistantProps> = ({ contextData }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const [input, setInput] = useState('');
  const { t, language } = useLanguage();
  const { theme } = useTheme();
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [useThinking, setUseThinking] = useState(false);
  const [attachedImage, setAttachedImage] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (messages.length === 0) {
        setMessages([{ 
            id: 'welcome', 
            role: 'model', 
            text: t('welcomeMessage') 
        }]);
    }
  }, [t]);

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 5 * 1024 * 1024) {
          alert("File too large. Please use an image under 5MB.");
          return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setAttachedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSendMessage = async () => {
    if ((!input.trim() && !attachedImage) || isLoading) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      image: attachedImage || undefined
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setAttachedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const parts: any[] = [];

      if (userMsg.image) {
         const base64Data = userMsg.image.split(',')[1];
         parts.push({
            inlineData: {
                mimeType: 'image/jpeg', 
                data: base64Data
            }
         });

         let analysisPrompt = userMsg.text;
         if (!analysisPrompt) analysisPrompt = "Analyze this image.";

         analysisPrompt += `\n\n[System Instruction]: You are a Senior QC Engineer. Check for: Black Specks, Gels, Flow Marks, Discoloration.`;
         parts.push({ text: analysisPrompt });
      } else {
         parts.push({ text: userMsg.text });

         if (contextData.length > 0) {
            const contextStr = JSON.stringify(contextData.slice(0, 20).map(p => ({
                grade: p.gradeName,
                manufacturer: p.manufacturer,
                properties: p.properties
            })));
            parts.push({ text: `\n[Context]: ${contextStr}` });
         }
      }

      const result = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: { role: 'user', parts: parts },
        config: {
            systemInstruction: "You are ResinAI. Technical, precise. Analyze data or images.",
            thinkingConfig: useThinking ? { thinkingBudget: 1024 } : undefined,
        }
      });

      const responseText = result.text || "I processed the data but could not generate a text response.";

      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        text: responseText
      }]);

    } catch (error) {
      console.error("AI Error:", error);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        text: "Error connecting to AI service."
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  return (
    <>
      {/* Floating Button */}
      <button
        onClick={() => setIsOpen(true)}
        className={`fixed bottom-6 right-6 z-40 group p-0 w-14 h-14 rounded-full shadow-xl shadow-emerald-500/30 transition-all duration-300 hover:scale-110 active:scale-95 ${isOpen ? 'scale-0 opacity-0 pointer-events-none' : 'scale-100 opacity-100'}`}
      >
         <div className="absolute inset-0 bg-gradient-to-tr from-emerald-600 to-teal-400 rounded-full animate-spin-slow opacity-80 group-hover:opacity-100 transition-opacity"></div>
         <div className="absolute inset-1 bg-slate-900 rounded-full flex items-center justify-center">
            <Sparkles size={24} className="text-emerald-400" />
         </div>
      </button>

      {/* Chat Window */}
