                        <div className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl rounded-tl-sm px-4 py-3 shadow-sm flex items-center gap-3">
                            <div className="flex gap-1">
                                <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                                <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                                <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-bounce"></span>
                            </div>
                            <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">
                                {useThinking ? t('reasoning') : t('analyzing')}
                            </span>
                        </div>
                     </div>
                </div>
            )}
            <div ref={messagesEndRef} />
        </div>

        {/* Input Area */}
        <div className="p-3 bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800">
            {attachedImage && (
                <div className="flex items-center justify-between px-3 py-2 mb-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg animate-in slide-in-from-bottom-2">
                    <div className="flex items-center gap-3 overflow-hidden">
                        <div className="w-10 h-10 rounded bg-slate-200 dark:bg-slate-700 shrink-0 overflow-hidden border border-slate-300 dark:border-slate-600">
                             <img src={attachedImage} alt="Preview" className="w-full h-full object-cover" />
                        </div>
                        <div className="flex flex-col overflow-hidden">
                             <span className="text-xs font-semibold text-slate-700 dark:text-slate-200 truncate">{t('imageAttached')}</span>
                             <span className="text-[10px] text-slate-400">QC analysis active</span>
                        </div>
                    </div>
                    <button onClick={() => setAttachedImage(null)} className="p-1.5 text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-md transition-colors">
                        <Trash2 size={16} />
                    </button>
                </div>
            )}

            <div className="flex items-end gap-2 bg-slate-100 dark:bg-slate-800/50 p-1.5 rounded-2xl border border-slate-200 dark:border-slate-700 focus-within:ring-2 focus-within:ring-emerald-500/20 focus-within:border-emerald-500 transition-all">
                <input 
                    type="file" 
                    ref={fileInputRef}
                    accept="image/*" 
                    className="hidden"
                    onChange={handleImageUpload}
                />
                <button 
                    onClick={() => fileInputRef.current?.click()}
                    className={`p-2 rounded-xl transition-all shrink-0 ${attachedImage ? 'text-emerald-600 dark:text-emerald-400 bg-emerald-100 dark:bg-emerald-900/30' : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700'}`}
                    title={t('uploadImage')}
                >
                    {attachedImage ? <ScanEye size={20} /> : <ImageIcon size={20} />}
                </button>

                <textarea
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder={attachedImage ? t('imageContext') : t('aiPlaceholder')}
                    className="w-full max-h-32 min-h-[40px] py-2 bg-transparent text-sm text-slate-800 dark:text-slate-200 placeholder:text-slate-400 outline-none resize-none custom-scrollbar leading-relaxed"
                    rows={1}
                />

                <button 
                    onClick={handleSendMessage}
                    disabled={(!input.trim() && !attachedImage) || isLoading}
                    className="p-2 bg-slate-900 dark:bg-emerald-600 hover:bg-slate-800 dark:hover:bg-emerald-500 disabled:bg-slate-200 dark:disabled:bg-slate-700 disabled:text-slate-400 text-white rounded-xl transition-all shadow-sm disabled:shadow-none shrink-0"
                >
                    {isLoading ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />}
                </button>
            </div>
            <div className="text-[10px] text-center text-slate-400 dark:text-slate-600 mt-2 select-none">
                AI can make mistakes. Check important info.
            </div>
        </div>
      </div>
    </>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  ReferenceLine,
  Cell,
  LabelList
} from 'recharts';
import { Settings, Download, ChevronUp, ChevronDown, BarChart2, ScatterChart as ScatterIcon, TrendingUp, Palette, PaintBucket, FileJson, FileType, Image as ImageIcon } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

const DEFAULT_PALETTE = [
  '#10b981', // Emerald
  '#3b82f6', // Blue
  '#f59e0b', // Amber
  '#ef4444', // Red
  '#8b5cf6', // Violet
  '#ec4899', // Pink
  '#06b6d4', // Cyan
  '#84cc16', // Lime
  '#f97316', // Orange
  '#6366f1', // Indigo
];

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const { t, tProp } = useLanguage();
  const { theme } = useTheme();
  const chartRef = useRef<HTMLDivElement>(null);

  const [showConfig, setShowConfig] = useState(true);
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('gradeName');
  const [yAxisKey, setYAxisKey] = useState<string>('');

  // Manual Axis Limits
  const [xMin, setXMin] = useState<number | ''>('');
  const [xMax, setXMax] = useState<number | ''>('');

  // Trendline State
  const [showTrendline, setShowTrendline] = useState(false);

  // Scatter Plot Grouping State
  const [groupByKey, setGroupByKey] = useState<string>('');
  const [groupColors, setGroupColors] = useState<Record<string, string>>({});

  // 1. Identify Numeric Keys (for Axes)
  const numericKeys = useMemo(() => {
     const keys = new Set<string>();
     data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
           if (typeof v.value === 'number') {
               keys.add(k);
           } else if (!isNaN(Number(v.value)) && v.value !== '') {
               keys.add(k);
           }
        });
     });
     return Array.from(keys).sort();
  }, [data]);

  // 2. Identify Categorical Keys (for Grouping)
  const categoricalKeys = useMemo(() => {
    const keys = new Set<string>(['manufacturer']); // Always available
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            // Treat strings as categories
            if (typeof v.value === 'string' && isNaN(Number(v.value))) {
                keys.add(k);
            }
        });
    });
    return Array.from(keys).sort();
  }, [data]);

  // Set default Y Axis if empty
  useEffect(() => {
      if (!yAxisKey && numericKeys.length > 0) {
          const preferred = ['密度', '熔体流动速率', '拉伸强度'].find(k => numericKeys.includes(k));
          setYAxisKey(preferred || numericKeys[0]);
      }
  }, [numericKeys, yAxisKey]);

  // Reset axis limits when xAxisKey changes
  useEffect(() => {
    setXMin('');
    setXMax('');
  }, [xAxisKey]);

  // 3. Prepare Chart Data
  const chartData = useMemo(() => {
    return data.map(p => {
        const item: any = {
            id: p.id,
            gradeName: p.gradeName,
            manufacturer: p.manufacturer,
            tooltipTitle: `${p.manufacturer} - ${p.gradeName}`
        };

        // Map properties to top-level keys for Recharts
        Object.entries(p.properties).forEach(([k, v]) => {
            const num = Number(v.value);
            if (!isNaN(num) && v.value !== '') {
                item[k] = num;
            } else {
                item[k] = v.value;
            }
        });
        return item;
    });
  }, [data]);

  // 4. Determine Unique Groups based on selected groupByKey
  const uniqueGroups = useMemo(() => {
    if (!groupByKey) return [];
    const groups = new Set<string>();
    chartData.forEach((item: any) => {
        const val = item[groupByKey];
        if (val !== undefined && val !== null) {
            groups.add(String(val));
        } else {
            groups.add('Unknown');
        }
    });
    return Array.from(groups).sort();
  }, [groupByKey, chartData]);

  // 5. Auto-assign colors when groups change
  useEffect(() => {
    if (uniqueGroups.length > 0) {
        setGroupColors(prev => {
            const next = { ...prev };
            uniqueGroups.forEach((group, index) => {
                if (!next[group]) {
                    next[group] = DEFAULT_PALETTE[index % DEFAULT_PALETTE.length];
                }
            });
            return next;
        });
    }
  }, [uniqueGroups]);

  const handleDownload = async (type: 'json' | 'csv' | 'png') => {
    if (type === 'json') {
        const jsonString = JSON.stringify(chartData, null, 2);
        const blob = new Blob([jsonString], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_data.json';
        a.click();
    } else if (type === 'csv') {
        // Simple CSV export
        const headers = ['Grade', 'Manufacturer', ...numericKeys];
        const rows = chartData.map((row: any) => [
            row.gradeName,
            row.manufacturer,
            ...numericKeys.map(k => row[k] ?? '')
        ]);
        const csvContent = [
            headers.join(','),
            ...rows.map(r => r.join(','))
        ].join('\n');
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_data.csv';
        a.click();
    } else if (type === 'png' && chartRef.current) {
        const canvas = await html2canvas(chartRef.current, {
            backgroundColor: theme === 'dark' ? '#0f172a' : '#ffffff' 
        });
        const url = canvas.toDataURL('image/png');
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_chart.png';
        a.click();
    }
  };

  const AxisSelector = ({ label, value, onChange, options }: any) => (
    <div className="flex flex-col gap-1.5">
        <label className="text-[10px] uppercase font-bold text-slate-400 tracking-wider">{label}</label>
        <div className="relative">
            <select
                value={value}
                onChange={(e) => onChange(e.target.value)}
                className="w-full appearance-none bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded-lg px-3 py-2 pr-8 focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all"
            >
                {options.map((key: string) => (
                    <option key={key} value={key}>{tProp(key)}</option>
                ))}
            </select>
            <ChevronDown size={14} className="absolute right-3 top-2.5 text-slate-400 pointer-events-none" />
        </div>
    </div>
  );

  return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900 rounded-xl shadow-sm border border-slate-200 dark:border-slate-800 overflow-hidden relative ring-1 ring-slate-900/5 dark:ring-white/10">

      {/* Header / Config Toggle */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-950/30 backdrop-blur-sm z-20">
          <div className="flex items-center gap-2 text-slate-700 dark:text-slate-200">
              <div className="p-1.5 bg-emerald-100 dark:bg-emerald-900/30 rounded-md text-emerald-600 dark:text-emerald-400">
                  {chartType === 'bar' ? <BarChart2 size={16} /> : <ScatterIcon size={16} />}
              </div>
              <h3 className="font-semibold text-sm">{t('chartTitle')}</h3>
          </div>
          <div className="flex items-center gap-2">
               {/* Export Menu */}
               <div className="flex items-center bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg p-0.5">
                   <button onClick={() => handleDownload('json')} className="p-1.5 text-slate-400 hover:text-emerald-600 dark:hover:text-emerald-400 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-md transition-colors" title={t('exportJson')}>
                       <FileJson size={14} />
                   </button>
                   <button onClick={() => handleDownload('csv')} className="p-1.5 text-slate-400 hover:text-blue-600 dark:hover:text-blue-400 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-md transition-colors" title={t('exportCsv')}>
                       <FileType size={14} />
                   </button>
                   <button onClick={() => handleDownload('png')} className="p-1.5 text-slate-400 hover:text-purple-600 dark:hover:text-purple-400 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-md transition-colors" title={t('exportPng')}>
                       <ImageIcon size={14} />
                   </button>
               </div>

               <div className="w-px h-4 bg-slate-300 dark:bg-slate-700 mx-1"></div>

               <button 
                  onClick={() => setShowConfig(!showConfig)}
                  className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${showConfig ? 'bg-slate-200 dark:bg-slate-700 text-slate-800 dark:text-slate-100' : 'bg-white dark:bg-slate-800 text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
               >
                   <Settings size={14} />
                   {showConfig ? t('collapseConfig') : t('expandConfig')}
               </button>
          </div>
      </div>

      <div className="flex-1 flex min-h-0 relative">
        {/* Config Panel - Side */}
        <div className={`
            w-72 border-r border-slate-100 dark:border-slate-800 bg-slate-50/30 dark:bg-slate-900/50 flex flex-col overflow-y-auto custom-scrollbar transition-all duration-300
            ${showConfig ? 'translate-x-0 opacity-100' : '-translate-x-full w-0 opacity-0 overflow-hidden'}
        `}>
            <div className="p-5 space-y-6">

                {/* Chart Type */}
                <div className="space-y-3">
                    <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider flex items-center gap-2">
                        <BarChart2 size={12} />
                        {t('chartType')}
                    </label>
                    <div className="grid grid-cols-2 gap-2">
                        <button
                            onClick={() => setChartType('bar')}
                            className={`flex flex-col items-center justify-center p-3 rounded-xl border transition-all ${chartType === 'bar' ? 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-500 text-emerald-700 dark:text-emerald-400 ring-1 ring-emerald-500/50' : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:border-emerald-300 dark:hover:border-emerald-700'}`}
                        >
                            <BarChart2 size={20} className="mb-2" />
                            <span className="text-[10px] font-medium">{t('barChart')}</span>
                        </button>
                        <button
                            onClick={() => setChartType('scatter')}
                            className={`flex flex-col items-center justify-center p-3 rounded-xl border transition-all ${chartType === 'scatter' ? 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-500 text-emerald-700 dark:text-emerald-400 ring-1 ring-emerald-500/50' : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:border-emerald-300 dark:hover:border-emerald-700'}`}
                        >
                            <ScatterIcon size={20} className="mb-2" />
                            <span className="text-[10px] font-medium">{t('scatterChart')}</span>
                        </button>
                    </div>
                </div>

                <hr className="border-slate-200 dark:border-slate-800" />

                {/* Axes */}
                <div className="space-y-4">
                    <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider flex items-center gap-2">
                        <Settings size={12} />
                        {t('axisMapping')}
                    </label>
                    <AxisSelector label={t('xAxis')} value={xAxisKey} onChange={setXAxisKey} options={chartType === 'bar' ? ['gradeName', 'manufacturer'] : numericKeys} />
                    <AxisSelector label={t('yAxis')} value={yAxisKey} onChange={setYAxisKey} options={numericKeys} />
                </div>

                {/* Specific Config based on Chart Type */}
                {chartType === 'scatter' && (
                    <>
                    <hr className="border-slate-200 dark:border-slate-800" />

                    {/* X-Axis Manual Limits */}
                    <div className="space-y-4">
                        <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider flex items-center gap-2">
                            <TrendingUp size={12} />
                            {t('axisMapping')} (Limits)
                        </label>
                        <div className="grid grid-cols-2 gap-3">
                            <div className="space-y-1.5">
                                <label className="text-[10px] uppercase font-bold text-slate-400 tracking-wider">{t('min')}</label>
                                <input
                                    type="number"
                                    placeholder="Auto"
                                    value={xMin}
                                    onChange={(e) => setXMin(e.target.value === '' ? '' : Number(e.target.value))}
                                    className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded-lg px-3 py-2 focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all"
                                />
                            </div>
                            <div className="space-y-1.5">
                                <label className="text-[10px] uppercase font-bold text-slate-400 tracking-wider">{t('max')}</label>
                                <input
                                    type="number"
                                    placeholder="Auto"
                                    value={xMax}
                                    onChange={(e) => setXMax(e.target.value === '' ? '' : Number(e.target.value))}
                                    className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded-lg px-3 py-2 focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all"
                                />
                            </div>
                        </div>
                    </div>

                    <hr className="border-slate-200 dark:border-slate-800" />

                    {/* Scatter Grouping & Colors */}
                    <div className="space-y-4">
                        <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider flex items-center gap-2">
                            <Palette size={12} />
                            {t('styleGrouping')}
                        </label>

                        <div className="flex flex-col gap-1.5">
                             <label className="text-[10px] uppercase font-bold text-slate-400 tracking-wider">{t('groupBy')}</label>
                             <div className="relative">
                                <select
                                    value={groupByKey}
                                    onChange={(e) => setGroupByKey(e.target.value)}
                                    className="w-full appearance-none bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded-lg px-3 py-2 pr-8 focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all"
                                >
                                    <option value="">{t('colorSingle')}</option>
                                    {categoricalKeys.map(key => (
                                        <option key={key} value={key}>{tProp(key)}</option>
                                    ))}
                                </select>
                                <ChevronDown size={14} className="absolute right-3 top-2.5 text-slate-400 pointer-events-none" />
                            </div>
                        </div>

                        {/* Color Palette Picker */}
                        {groupByKey && uniqueGroups.length > 0 && (
                            <div className="bg-white dark:bg-slate-800/50 rounded-lg border border-slate-200 dark:border-slate-700 p-3 space-y-2 animate-in slide-in-from-top-2">
                                <span className="text-[10px] font-semibold text-slate-500 dark:text-slate-400 block mb-2">Color Palette</span>
                                <div className="space-y-1.5 max-h-40 overflow-y-auto custom-scrollbar pr-1">
                                    {uniqueGroups.map((group) => (
                                        <div key={group} className="flex items-center gap-2">
                                            <div className="relative w-6 h-6 shrink-0 rounded-md overflow-hidden ring-1 ring-slate-200 dark:ring-slate-600 cursor-pointer shadow-sm hover:scale-110 transition-transform">
                                                <input 
                                                    type="color" 
                                                    value={groupColors[group] || '#000000'}
                                                    onChange={(e) => setGroupColors(prev => ({...prev, [group]: e.target.value}))}
                                                    className="absolute inset-0 w-[150%] h-[150%] -top-[25%] -left-[25%] p-0 border-0 cursor-pointer"
                                                />
                                            </div>
                                            <span className="text-xs text-slate-600 dark:text-slate-300 truncate flex-1" title={group}>
                                                {group}
                                            </span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}
                    </div>

                    <hr className="border-slate-200 dark:border-slate-800" />

                    {/* Trendline */}
                    <div className="space-y-3">
                         <div className="flex items-center justify-between">
                            <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider flex items-center gap-2">
                                <TrendingUp size={12} />
                                {t('trendline')}
                            </label>
                            <div className={`relative inline-flex h-4 w-8 shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500 focus-visible:ring-offset-2 ${showTrendline ? 'bg-emerald-500' : 'bg-slate-200 dark:bg-slate-700'}`} onClick={() => setShowTrendline(!showTrendline)}>
                                <span className={`pointer-events-none inline-block h-3 w-3 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out ${showTrendline ? 'translate-x-4' : 'translate-x-0'}`} />
                            </div>
                         </div>
                    </div>
                    </>
                )}
            </div>
        </div>

        {/* Chart Area */}
        <div className="flex-1 p-6 relative overflow-hidden bg-white/50 dark:bg-slate-900/50" ref={chartRef}>
            {/* Background Pattern */}
            <div className="absolute inset-0 opacity-[0.03] dark:opacity-[0.05] pointer-events-none" style={{ backgroundImage: `radial-gradient(#94a3b8 1px, transparent 1px)`, backgroundSize: '24px 24px' }}></div>

            <ResponsiveContainer width="100%" height="100%">
                {chartType === 'bar' ? (
                    <BarChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 60 }}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={theme === 'dark' ? '#334155' : '#e2e8f0'} />
                        <XAxis 
                            dataKey={xAxisKey} 
                            tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b', fontSize: 11 }} 
                            axisLine={{ stroke: theme === 'dark' ? '#475569' : '#cbd5e1' }}
                            tickLine={false}
                            angle={-45}
                            textAnchor="end"
                            height={60}
                        />
                        <YAxis 
                            tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b', fontSize: 11 }}
                            axisLine={false}
                            tickLine={false}
                            label={{ value: tProp(yAxisKey), angle: -90, position: 'insideLeft', fill: theme === 'dark' ? '#cbd5e1' : '#475569', fontSize: 12, fontWeight: 600 }}
                        />
                        <Tooltip 
                            contentStyle={{ 
                                backgroundColor: theme === 'dark' ? '#1e293b' : '#ffffff', 
                                borderRadius: '12px', 
                                border: '1px solid ' + (theme === 'dark' ? '#334155' : '#e2e8f0'),
                                boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)',
                                color: theme === 'dark' ? '#f8fafc' : '#0f172a'
                            }}
                            cursor={{ fill: theme === 'dark' ? '#334155' : '#f1f5f9', opacity: 0.4 }}
                        />
                        <Bar dataKey={yAxisKey} radius={[6, 6, 0, 0]} animationDuration={1000}>
                            {chartData.map((entry: any, index: number) => (
                                <Cell key={`cell-${index}`} fill={DEFAULT_PALETTE[index % DEFAULT_PALETTE.length]} />
                            ))}
                        </Bar>
                    </BarChart>
                ) : (
                    <ScatterChart margin={{ top: 20, right: 30, left: 20, bottom: 60 }}>
                        <CartesianGrid strokeDasharray="3 3" stroke={theme === 'dark' ? '#334155' : '#e2e8f0'} />
                        <XAxis 
                            type="number" 
                            dataKey={xAxisKey} 
                            name={tProp(xAxisKey)}
                            domain={[xMin === '' ? 'auto' : xMin, xMax === '' ? 'auto' : xMax]}
                            tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b', fontSize: 11 }} 
                            axisLine={{ stroke: theme === 'dark' ? '#475569' : '#cbd5e1' }}
                            tickLine={false}
                            label={{ value: tProp(xAxisKey), position: 'insideBottom', offset: -10, fill: theme === 'dark' ? '#cbd5e1' : '#475569', fontSize: 12, fontWeight: 600 }}
                        />
                        <YAxis 
                            type="number" 
                            dataKey={yAxisKey} 
                            name={tProp(yAxisKey)}
                            tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b', fontSize: 11 }}
                            axisLine={false}
                            tickLine={false}
                            label={{ value: tProp(yAxisKey), angle: -90, position: 'insideLeft', fill: theme === 'dark' ? '#cbd5e1' : '#475569', fontSize: 12, fontWeight: 600 }}
                        />
                        <Tooltip 
                            cursor={{ strokeDasharray: '3 3' }}
                            content={({ active, payload }) => {
                                if (active && payload && payload.length) {
                                    const dataPoint = payload[0].payload;
                                    return (
                                        <div className={`p-3 rounded-xl border shadow-lg ${theme === 'dark' ? 'bg-slate-800 border-slate-700 text-slate-100' : 'bg-white border-slate-100 text-slate-900'}`}>
                                            <p className="font-bold text-sm mb-1">{dataPoint.tooltipTitle}</p>
                                            <p className="text-xs text-slate-500 mb-2">{groupByKey && `${tProp(groupByKey)}: ${dataPoint[groupByKey]}`}</p>
                                            <div className="space-y-1 text-xs font-mono">
                                                <div className="flex justify-between gap-4">
                                                    <span className="text-slate-500">{tProp(xAxisKey)}:</span>
                                                    <span className="font-semibold">{dataPoint[xAxisKey]}</span>
                                                </div>
                                                <div className="flex justify-between gap-4">
                                                    <span className="text-slate-500">{tProp(yAxisKey)}:</span>
                                                    <span className="font-semibold">{dataPoint[yAxisKey]}</span>
                                                </div>
                                            </div>
                                        </div>
                                    );
                                }
                                return null;
                            }}
                        />
                        {groupByKey ? (
                            <>
                                <Legend 
                                    wrapperStyle={{ paddingTop: '20px' }}
                                    formatter={(value) => <span style={{ color: theme === 'dark' ? '#94a3b8' : '#475569', fontSize: '12px' }}>{value}</span>}
                                />
                                {uniqueGroups.map((group) => (
                                    <Scatter
                                        key={group}
                                        name={group}
                                        data={chartData.filter((d: any) => String(d[groupByKey] ?? 'Unknown') === group)}
                                        fill={groupColors[group] || '#000'}
                                    />
                                ))}
                            </>
                        ) : (
                            <Scatter name="Products" data={chartData} fill="#10b981" />
                        )}
                    </ScatterChart>
                )}
            </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  ReferenceLine,
  Cell,
  LabelList
} from 'recharts';
import { Settings, Download, ChevronUp, ChevronDown, BarChart2, ScatterChart as ScatterIcon, TrendingUp, Palette, PaintBucket, FileJson, FileType, Image as ImageIcon, RotateCcw } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

const DEFAULT_PALETTE = [
  '#10b981', // Emerald
  '#3b82f6', // Blue
  '#f59e0b', // Amber
  '#ef4444', // Red
  '#8b5cf6', // Violet
  '#ec4899', // Pink
  '#06b6d4', // Cyan
  '#84cc16', // Lime
  '#f97316', // Orange
  '#6366f1', // Indigo
];

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const { t, tProp } = useLanguage();
  const { theme } = useTheme();
  const chartRef = useRef<HTMLDivElement>(null);

  const [showConfig, setShowConfig] = useState(true);
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('gradeName');
  const [yAxisKey, setYAxisKey] = useState<string>('');

  // Manual Axis Limits
  const [xMin, setXMin] = useState<number | ''>('');
  const [xMax, setXMax] = useState<number | ''>('');
  const [yMin, setYMin] = useState<number | ''>('');
  const [yMax, setYMax] = useState<number | ''>('');

  // Trendline State
  const [showTrendline, setShowTrendline] = useState(false);

  // Scatter Plot Grouping State
  const [groupByKey, setGroupByKey] = useState<string>('');
  const [groupColors, setGroupColors] = useState<Record<string, string>>({});

  // 1. Identify Numeric Keys (for Axes)
  const numericKeys = useMemo(() => {
     const keys = new Set<string>();
     data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
           if (typeof v.value === 'number') {
               keys.add(k);
           } else if (!isNaN(Number(v.value)) && v.value !== '') {
               keys.add(k);
           }
        });
     });
     return Array.from(keys).sort();
  }, [data]);

  // 2. Identify Categorical Keys (for Grouping)
  const categoricalKeys = useMemo(() => {
    const keys = new Set<string>(['manufacturer']); // Always available
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            // Treat strings as categories
            if (typeof v.value === 'string' && isNaN(Number(v.value))) {
                keys.add(k);
            }
        });
    });
    return Array.from(keys).sort();
  }, [data]);

  // Set default Y Axis if empty
  useEffect(() => {
      if (!yAxisKey && numericKeys.length > 0) {
          const preferred = ['密度', '熔体流动速率', '拉伸强度'].find(k => numericKeys.includes(k));
          setYAxisKey(preferred || numericKeys[0]);
      }
  }, [numericKeys, yAxisKey]);

  // Reset axis limits when xAxisKey or yAxisKey changes
  useEffect(() => {
    setXMin('');
    setXMax('');
  }, [xAxisKey]);

  useEffect(() => {
    setYMin('');
    setYMax('');
  }, [yAxisKey]);

  // 3. Prepare Chart Data
  const chartData = useMemo(() => {
    return data.map(p => {
        const item: any = {
            id: p.id,
            gradeName: p.gradeName,
            manufacturer: p.manufacturer,
            tooltipTitle: `${p.manufacturer} - ${p.gradeName}`
        };

        // Map properties to top-level keys for Recharts
        Object.entries(p.properties).forEach(([k, v]) => {
            const num = Number(v.value);
            if (!isNaN(num) && v.value !== '') {
                item[k] = num;
            } else {
                item[k] = v.value;
            }
        });
        return item;
    });
  }, [data]);

  // 4. Determine Unique Groups based on selected groupByKey
  const uniqueGroups = useMemo(() => {
    if (!groupByKey) return [];
    const groups = new Set<string>();
    chartData.forEach((item: any) => {
        const val = item[groupByKey];
        if (val !== undefined && val !== null && val !== '') {
            groups.add(String(val));
        } else {
            groups.add('Unknown');
        }
    });
    return Array.from(groups).sort();
  }, [groupByKey, chartData]);

  // 5. Auto-assign colors when groups change
  useEffect(() => {
    if (uniqueGroups.length > 0) {
        setGroupColors(prev => {
            const next = { ...prev };
            uniqueGroups.forEach((group, index) => {
                if (!next[group]) {
                    next[group] = DEFAULT_PALETTE[index % DEFAULT_PALETTE.length];
                }
            });
            return next;
        });
    }
  }, [uniqueGroups]);

  const handleDownload = async (type: 'json' | 'csv' | 'png') => {
    if (type === 'json') {
        const jsonString = JSON.stringify(chartData, null, 2);
        const blob = new Blob([jsonString], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_data.json';
        a.click();
    } else if (type === 'csv') {
        // Simple CSV export
        const headers = ['Grade', 'Manufacturer', ...numericKeys];
        const rows = chartData.map((row: any) => [
            row.gradeName,
            row.manufacturer,
            ...numericKeys.map(k => row[k] ?? '')
        ]);
        const csvContent = [
            headers.join(','),
            ...rows.map(r => r.join(','))
        ].join('\n');
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_data.csv';
        a.click();
    } else if (type === 'png' && chartRef.current) {
        const canvas = await html2canvas(chartRef.current, {
            backgroundColor: theme === 'dark' ? '#0f172a' : '#ffffff' 
        });
        const url = canvas.toDataURL('image/png');
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_chart.png';
        a.click();
    }
  };

  const AxisSelector = ({ label, value, onChange, options }: any) => (
    <div className="flex flex-col gap-1.5">
        <label className="text-[10px] uppercase font-bold text-slate-400 tracking-wider">{label}</label>
        <div className="relative">
            <select
                value={value}
                onChange={(e) => onChange(e.target.value)}
                className="w-full appearance-none bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded-lg px-3 py-2 pr-8 focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all"
            >
                {options.map((key: string) => (
                    <option key={key} value={key}>{tProp(key)}</option>
                ))}
            </select>
            <ChevronDown size={14} className="absolute right-3 top-2.5 text-slate-400 pointer-events-none" />
        </div>
    </div>
  );

  return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900 rounded-xl shadow-sm border border-slate-200 dark:border-slate-800 overflow-hidden relative ring-1 ring-slate-900/5 dark:ring-white/10">

      {/* Header / Config Toggle */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-950/30 backdrop-blur-sm z-20">
          <div className="flex items-center gap-2 text-slate-700 dark:text-slate-200">
              <div className="p-1.5 bg-emerald-100 dark:bg-emerald-900/30 rounded-md text-emerald-600 dark:text-emerald-400">
                  {chartType === 'bar' ? <BarChart2 size={16} /> : <ScatterIcon size={16} />}
              </div>
              <h3 className="font-semibold text-sm">{t('chartTitle')}</h3>
          </div>
          <div className="flex items-center gap-2">
               {/* Export Menu */}
               <div className="flex items-center bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg p-0.5">
                   <button onClick={() => handleDownload('json')} className="p-1.5 text-slate-400 hover:text-emerald-600 dark:hover:text-emerald-400 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-md transition-colors" title={t('exportJson')}>
                       <FileJson size={14} />
                   </button>
                   <button onClick={() => handleDownload('csv')} className="p-1.5 text-slate-400 hover:text-blue-600 dark:hover:text-blue-400 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-md transition-colors" title={t('exportCsv')}>
                       <FileType size={14} />
                   </button>
                   <button onClick={() => handleDownload('png')} className="p-1.5 text-slate-400 hover:text-purple-600 dark:hover:text-purple-400 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-md transition-colors" title={t('exportPng')}>
                       <ImageIcon size={14} />
                   </button>
               </div>

               <div className="w-px h-4 bg-slate-300 dark:bg-slate-700 mx-1"></div>

               <button 
                  onClick={() => setShowConfig(!showConfig)}
                  className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${showConfig ? 'bg-slate-200 dark:bg-slate-700 text-slate-800 dark:text-slate-100' : 'bg-white dark:bg-slate-800 text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
               >
                   <Settings size={14} />
                   {showConfig ? t('collapseConfig') : t('expandConfig')}
               </button>
          </div>
      </div>

      <div className="flex-1 flex min-h-0 relative">
        {/* Config Panel - Side */}
        <div className={`
            w-72 border-r border-slate-100 dark:border-slate-800 bg-slate-50/30 dark:bg-slate-900/50 flex flex-col overflow-y-auto custom-scrollbar transition-all duration-300
            ${showConfig ? 'translate-x-0 opacity-100' : '-translate-x-full w-0 opacity-0 overflow-hidden'}
        `}>
            <div className="p-5 space-y-6">

                {/* Chart Type */}
                <div className="space-y-3">
                    <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider flex items-center gap-2">
                        <BarChart2 size={12} />
                        {t('chartType')}
                    </label>
                    <div className="grid grid-cols-2 gap-2">
                        <button
                            onClick={() => setChartType('bar')}
                            className={`flex flex-col items-center justify-center p-3 rounded-xl border transition-all ${chartType === 'bar' ? 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-500 text-emerald-700 dark:text-emerald-400 ring-1 ring-emerald-500/50' : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:border-emerald-300 dark:hover:border-emerald-700'}`}
                        >
                            <BarChart2 size={20} className="mb-2" />
                            <span className="text-[10px] font-medium">{t('barChart')}</span>
                        </button>
                        <button
                            onClick={() => setChartType('scatter')}
                            className={`flex flex-col items-center justify-center p-3 rounded-xl border transition-all ${chartType === 'scatter' ? 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-500 text-emerald-700 dark:text-emerald-400 ring-1 ring-emerald-500/50' : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:border-emerald-300 dark:hover:border-emerald-700'}`}
                        >
                            <ScatterIcon size={20} className="mb-2" />
                            <span className="text-[10px] font-medium">{t('scatterChart')}</span>
                        </button>
                    </div>
                </div>

                <hr className="border-slate-200 dark:border-slate-800" />

                {/* Axes */}
                <div className="space-y-4">
                    <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider flex items-center gap-2">
                        <Settings size={12} />
                        {t('axisMapping')}
                    </label>
                    <AxisSelector label={t('xAxis')} value={xAxisKey} onChange={setXAxisKey} options={chartType === 'bar' ? ['gradeName', 'manufacturer'] : numericKeys} />
                    <AxisSelector label={t('yAxis')} value={yAxisKey} onChange={setYAxisKey} options={numericKeys} />
                </div>

                {/* Specific Config based on Chart Type */}
                {chartType === 'scatter' && (
                    <>
                    <hr className="border-slate-200 dark:border-slate-800" />

                    {/* Axis Manual Limits */}
                    <div className="space-y-4">
                        <div className="flex items-center justify-between">
                            <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider flex items-center gap-2">
                                <TrendingUp size={12} />
                                {t('axisMapping')} (Limits)
                            </label>
                            <button 
                                onClick={() => {setXMin(''); setXMax(''); setYMin(''); setYMax('');}}
                                className="text-[10px] text-emerald-600 dark:text-emerald-400 hover:underline flex items-center gap-1"
                            >
                                <RotateCcw size={10} />
                                {t('reset')}
                            </button>
                        </div>

                        {/* X-Axis Limits */}
                        <div className="space-y-2">
                            <span className="text-[10px] font-semibold text-slate-500">{tProp(xAxisKey)}</span>
                            <div className="grid grid-cols-2 gap-2">
                                <div className="space-y-1">
                                    <label className="text-[9px] uppercase text-slate-400 tracking-wider">{t('min')}</label>
                                    <input
                                        type="number"
                                        placeholder="Auto"
                                        value={xMin}
                                        onChange={(e) => setXMin(e.target.value === '' ? '' : Number(e.target.value))}
                                        className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded-lg px-2 py-1.5 focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all"
                                    />
                                </div>
                                <div className="space-y-1">
                                    <label className="text-[9px] uppercase text-slate-400 tracking-wider">{t('max')}</label>
                                    <input
                                        type="number"
                                        placeholder="Auto"
                                        value={xMax}
                                        onChange={(e) => setXMax(e.target.value === '' ? '' : Number(e.target.value))}
                                        className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded-lg px-2 py-1.5 focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all"
                                    />
                                </div>
                            </div>
                        </div>

                        {/* Y-Axis Limits */}
                        <div className="space-y-2">
                            <span className="text-[10px] font-semibold text-slate-500">{tProp(yAxisKey)}</span>
                            <div className="grid grid-cols-2 gap-2">
                                <div className="space-y-1">
                                    <label className="text-[9px] uppercase text-slate-400 tracking-wider">{t('min')}</label>
                                    <input
                                        type="number"
                                        placeholder="Auto"
                                        value={yMin}
                                        onChange={(e) => setYMin(e.target.value === '' ? '' : Number(e.target.value))}
                                        className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded-lg px-2 py-1.5 focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all"
                                    />
                                </div>
                                <div className="space-y-1">
                                    <label className="text-[9px] uppercase text-slate-400 tracking-wider">{t('max')}</label>
                                    <input
                                        type="number"
                                        placeholder="Auto"
                                        value={yMax}
                                        onChange={(e) => setYMax(e.target.value === '' ? '' : Number(e.target.value))}
                                        className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded-lg px-2 py-1.5 focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all"
                                    />
                                </div>
                            </div>
                        </div>
                    </div>

                    <hr className="border-slate-200 dark:border-slate-800" />

                    {/* Scatter Grouping & Colors */}
                    <div className="space-y-4">
                        <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider flex items-center gap-2">
                            <Palette size={12} />
                            {t('styleGrouping')}
                        </label>

                        <div className="flex flex-col gap-1.5">
                             <label className="text-[10px] uppercase font-bold text-slate-400 tracking-wider">{t('groupBy')}</label>
                             <div className="relative">
                                <select
                                    value={groupByKey}
                                    onChange={(e) => setGroupByKey(e.target.value)}
                                    className="w-full appearance-none bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded-lg px-3 py-2 pr-8 focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all"
                                >
                                    <option value="">{t('colorSingle')}</option>
                                    {categoricalKeys.map(key => (
                                        <option key={key} value={key}>{tProp(key)}</option>
                                    ))}
                                </select>
                                <ChevronDown size={14} className="absolute right-3 top-2.5 text-slate-400 pointer-events-none" />
                            </div>
                        </div>

                        {/* Color Palette Picker */}
                        {groupByKey && uniqueGroups.length > 0 && (
                            <div className="bg-white dark:bg-slate-800/50 rounded-lg border border-slate-200 dark:border-slate-700 p-3 space-y-3 animate-in slide-in-from-top-2">
                                <div className="flex items-center justify-between">
                                    <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase">{t('styleGrouping')}</span>
                                    <PaintBucket size={12} className="text-slate-400" />
                                </div>
                                <div className="space-y-1.5 max-h-56 overflow-y-auto custom-scrollbar pr-1">
                                    {uniqueGroups.map((group) => (
                                        <div key={group} className="flex items-center gap-3 group/item">
                                            <div className="relative w-7 h-7 shrink-0 rounded-lg overflow-hidden ring-1 ring-slate-200 dark:ring-slate-600 cursor-pointer shadow-sm hover:ring-emerald-400 dark:hover:ring-emerald-500 transition-all active:scale-95">
                                                <input 
                                                    type="color" 
                                                    value={groupColors[group] || '#000000'}
                                                    onChange={(e) => setGroupColors(prev => ({...prev, [group]: e.target.value}))}
                                                    className="absolute inset-0 w-[200%] h-[200%] -top-[50%] -left-[50%] p-0 border-0 cursor-pointer"
                                                />
                                            </div>
                                            <span className="text-[11px] font-medium text-slate-600 dark:text-slate-300 truncate flex-1 group-hover/item:text-slate-900 dark:group-hover/item:text-slate-100 transition-colors" title={group}>
                                                {group}
                                            </span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}
                    </div>

                    <hr className="border-slate-200 dark:border-slate-800" />

                    {/* Trendline */}
                    <div className="space-y-3">
                         <div className="flex items-center justify-between">
                            <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider flex items-center gap-2">
                                <TrendingUp size={12} />
                                {t('trendline')}
                            </label>
