interface AIAssistantProps {
  contextData: Product[];
}

interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  image?: string;
  isThinking?: boolean;
}

const FormattedText: React.FC<{ text: string; className?: string }> = ({ text, className }) => {
  if (!text) return null;

  return (
    <div className={className}>
      {text.split('\n').map((line, i) => {
        const trimmed = line.trim();
        if (trimmed.startsWith('- ') || trimmed.startsWith('* ') || trimmed.match(/^\d+\./)) {
             const cleanLine = trimmed.replace(/^[-*]\s+|\d+\.\s+/, '');
             const parts = cleanLine.split(/(\*\*.*?\*\*)/g);
             return (
                <div key={i} className="flex gap-2.5 ml-1 mb-1.5 items-start">
                    <span className="text-emerald-500 dark:text-emerald-400 mt-1.5 shrink-0 text-[10px]">•</span>
                    <span className="leading-relaxed text-sm">
                        {parts.map((part, j) => {
                            if (part.startsWith('**') && part.endsWith('**')) {
                                return <strong key={j} className="font-bold text-slate-800 dark:text-white">{part.slice(2, -2)}</strong>;
                            }
                            return <span key={j}>{part}</span>;
                        })}
                    </span>
                </div>
             );
        }

        const parts = line.split(/(\*\*.*?\*\*)/g);
        if (line.startsWith('##')) {
             return <h3 key={i} className="font-bold text-emerald-700 dark:text-emerald-400 mt-4 mb-2 text-base">{line.replace(/#/g, '')}</h3>
        }

        if (!trimmed) return <div key={i} className="h-2"></div>;

        return (
          <p key={i} className="mb-2 last:mb-0 leading-relaxed text-sm">
            {parts.map((part, j) => {
              if (part.startsWith('**') && part.endsWith('**')) {
                return <strong key={j} className="font-bold text-slate-800 dark:text-white">{part.slice(2, -2)}</strong>;
              }
              return <span key={j}>{part}</span>;
            })}
          </p>
        );
      })}
    </div>
  );
};

export const AIAssistant: React.FC<AIAssistantProps> = ({ contextData }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const [input, setInput] = useState('');
  const { t, language } = useLanguage();
  const { theme } = useTheme();
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [useThinking, setUseThinking] = useState(false);
  const [attachedImage, setAttachedImage] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (messages.length === 0) {
        setMessages([{ 
            id: 'welcome', 
            role: 'model', 
            text: t('welcomeMessage') 
        }]);
    }
  }, [t]);

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 5 * 1024 * 1024) {
          alert("File too large. Please use an image under 5MB.");
          return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setAttachedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSendMessage = async () => {
    if ((!input.trim() && !attachedImage) || isLoading) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      image: attachedImage || undefined
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setAttachedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const parts: any[] = [];
      let systemInstruction = "You are ResinAI. Technical, precise. Analyze data or images.";

      if (userMsg.image) {
         const base64Data = userMsg.image.split(',')[1];
         parts.push({
            inlineData: {
                mimeType: 'image/jpeg', 
                data: base64Data
            }
         });

         // Set specialized system instruction for QC Image Analysis
         systemInstruction = `You are a Senior QC Engineer specializing in petrochemical synthetic resins. 
When analyzing an image:
1. Identify the resin type (e.g., PE, PP, ABS, PC) and its physical form (e.g., pellets, powder, molded part).
2. Specifically and meticulously check for common resin defects including: 'black specks', 'gels' (fisheyes), 'flow marks', and 'discoloration'.
3. Provide a professional quality assessment, identifying any anomalies and describing their potential impact on production quality.`;

         const analysisPrompt = userMsg.text 
           ? `${userMsg.text}\n\nPlease also identify the resin type/form and check for black specks, gels, flow marks, or discoloration.`
           : "Identify the resin type and form, and check for black specks, gels, flow marks, and discoloration.";
         parts.push({ text: analysisPrompt });
      } else {
         parts.push({ text: userMsg.text });

         if (contextData.length > 0) {
            const contextStr = JSON.stringify(contextData.slice(0, 20).map(p => ({
                grade: p.gradeName,
                manufacturer: p.manufacturer,
                properties: p.properties
            })));
            parts.push({ text: `\n[Context]: ${contextStr}` });
         }
      }

      const result = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: { role: 'user', parts: parts },
        config: {
            systemInstruction: systemInstruction,
            thinkingConfig: useThinking ? { thinkingBudget: 1024 } : undefined,
        }
      });

      const responseText = result.text || "I processed the data but could not generate a text response.";

      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        text: responseText
      }]);

    } catch (error) {
      console.error("AI Error:", error);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        text: "Error connecting to AI service."
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  return (
    <>
      {/* Floating Button */}
      <button
        onClick={() => setIsOpen(true)}
        className={`fixed bottom-6 right-6 z-40 group p-0 w-14 h-14 rounded-full shadow-xl shadow-emerald-500/30 transition-all duration-300 hover:scale-110 active:scale-95 ${isOpen ? 'scale-0 opacity-0 pointer-events-none' : 'scale-100 opacity-100'}`}
      >
         <div className="absolute inset-0 bg-gradient-to-tr from-emerald-600 to-teal-400 rounded-full animate-spin-slow opacity-80 group-hover:opacity-100 transition-opacity"></div>
         <div className="absolute inset-1 bg-slate-900 rounded-full flex items-center justify-center">
            <Sparkles size={24} className="text-emerald-400" />
         </div>
      </button>

      {/* Chat Window */}
      <div 
        className={`fixed bottom-6 right-6 z-50 bg-white dark:bg-slate-900 rounded-2xl shadow-2xl ring-1 ring-slate-200 dark:ring-slate-800 flex flex-col overflow-hidden transition-all duration-300 origin-bottom-right ${isOpen ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10 pointer-events-none scale-95'} ${isExpanded ? 'w-[600px] h-[800px] max-w-[90vw] max-h-[90vh]' : 'w-[380px] h-[600px] max-w-[90vw] max-h-[85vh]'}`}
      >
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-3 border-b border-slate-100 dark:border-slate-800 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md z-10">
            <div className="flex items-center gap-3">
                <div className="w-8 h-8 bg-gradient-to-br from-emerald-500 to-teal-600 rounded-lg flex items-center justify-center shadow-lg shadow-emerald-500/20">
                    <Bot size={18} className="text-white" />
                </div>
                <div>
                    <h3 className="font-bold text-sm text-slate-800 dark:text-white leading-tight">{t('aiAssistant')}</h3>
                    <div className="flex items-center gap-1.5">
                        <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span>
                        <span className="text-[10px] text-slate-500 dark:text-slate-400 font-medium">Gemini Pro 2.5</span>
                    </div>
                </div>
            </div>
            <div className="flex items-center gap-1">
                 <button 
                    onClick={() => setUseThinking(!useThinking)}
                    className={`p-1.5 rounded-md transition-all ${useThinking ? 'bg-indigo-100 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400' : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                    title={useThinking ? t('thinkingOn') : t('thinkingOff')}
                >
                    <BrainCircuit size={16} />
                </button>
                <button 
                    onClick={() => setIsExpanded(!isExpanded)} 
                    className="p-1.5 text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-md transition-colors hidden sm:block"
                >
                    {isExpanded ? <Minimize2 size={16} /> : <Maximize2 size={16} />}
                </button>
                <button 
                    onClick={() => setIsOpen(false)} 
                    className="p-1.5 text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-md transition-colors"
                >
                    <X size={18} />
                </button>
            </div>
        </div>

        {/* Messages Area */}
        <div className="flex-1 overflow-y-auto p-4 space-y-5 bg-slate-50/50 dark:bg-slate-950/50 custom-scrollbar" ref={chatContainerRef}>
            {messages.map((msg) => (
                <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
                    <div className={`flex gap-3 max-w-[85%] ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                        {/* Avatar */}
                        <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 border ${msg.role === 'user' ? 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700' : 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-100 dark:border-emerald-800/50'}`}>
                            {msg.role === 'user' ? <User size={14} className="text-slate-600 dark:text-slate-400"/> : <Sparkles size={14} className="text-emerald-600 dark:text-emerald-400"/>}
                        </div>

                        {/* Message Bubble */}
                        <div className={`flex flex-col gap-1 ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                            <div className={`rounded-2xl px-4 py-3 text-sm shadow-sm ${
                                msg.role === 'user' 
                                ? 'bg-slate-900 dark:bg-emerald-600 text-white rounded-tr-sm' 
                                : 'bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-200 border border-slate-200 dark:border-slate-700 rounded-tl-sm'
                            }`}>
                                {msg.image && (
                                    <div className="mb-3 rounded-lg overflow-hidden border border-white/20 shadow-sm">
                                        <img src={msg.image} alt="Uploaded" className="max-w-full h-auto max-h-48 object-cover" />
                                    </div>
                                )}
                                <FormattedText text={msg.text} />
                            </div>
                        </div>
                    </div>
                </div>
            ))}

            {isLoading && (
                <div className="flex justify-start animate-in fade-in duration-300">
                     <div className="flex gap-3 max-w-[85%]">
                        <div className="w-8 h-8 rounded-full bg-emerald-50 dark:bg-emerald-900/20 border border-emerald-100 dark:border-emerald-800/50 flex items-center justify-center shrink-0">
                            <Sparkles size={14} className="text-emerald-600 dark:text-emerald-400"/>
                        </div>
                        <div className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl rounded-tl-sm px-4 py-3 shadow-sm flex items-center gap-3">
