                />
                <button 
                    onClick={() => fileInputRef.current?.click()}
                    className={`p-2 rounded-xl transition-all shrink-0 ${attachedImage ? 'text-emerald-600 dark:text-emerald-400 bg-emerald-100 dark:bg-emerald-900/30' : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700'}`}
                    title={t('uploadImage')}
                >
                    {attachedImage ? <ScanEye size={20} /> : <ImageIcon size={20} />}
                </button>

                <textarea
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder={attachedImage ? t('imageContext') : t('aiPlaceholder')}
                    className="w-full max-h-32 min-h-[40px] py-2 bg-transparent text-sm text-slate-800 dark:text-slate-200 placeholder:text-slate-400 outline-none resize-none custom-scrollbar leading-relaxed"
                    rows={1}
                />

                <button 
                    onClick={handleSendMessage}
                    disabled={(!input.trim() && !attachedImage) || isLoading}
                    className="p-2 bg-slate-900 dark:bg-emerald-600 hover:bg-slate-800 dark:hover:bg-emerald-500 disabled:bg-slate-200 dark:disabled:bg-slate-700 disabled:text-slate-400 text-white rounded-xl transition-all shadow-sm disabled:shadow-none shrink-0"
                >
                    {isLoading ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />}
