export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const { t, tProp } = useLanguage();
  const { theme } = useTheme();
  const chartRef = useRef<HTMLDivElement>(null);

  const [showConfig, setShowConfig] = useState(true);
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('gradeName');
  const [yAxisKey, setYAxisKey] = useState<string>('');

  // Manual Axis Limits
  const [xMin, setXMin] = useState<number | ''>('');
  const [xMax, setXMax] = useState<number | ''>('');
  const [yMin, setYMin] = useState<number | ''>('');
  const [yMax, setYMax] = useState<number | ''>('');

  // Trendline State
  const [showTrendline, setShowTrendline] = useState(false);
  const [trendlineColor, setTrendlineColor] = useState('#ef4444');
  const [trendlineWidth, setTrendlineWidth] = useState(2);
  const [trendlineStyle, setTrendlineStyle] = useState<'solid' | 'dashed' | 'dotted'>('dashed');

  // Scatter Plot Grouping State
  const [groupByKey, setGroupByKey] = useState<string>('');
  const [groupColors, setGroupColors] = useState<Record<string, string>>({});

  // 1. Identify Numeric Keys (for Axes)
  const numericKeys = useMemo(() => {
     const keys = new Set<string>();
     data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
           if (typeof v.value === 'number') {
               keys.add(k);
           } else if (!isNaN(Number(v.value)) && v.value !== '') {
               keys.add(k);
           }
        });
     });
     return Array.from(keys).sort();
  }, [data]);

  // 2. Identify Categorical Keys (for Grouping)
  const categoricalKeys = useMemo(() => {
    const keys = new Set<string>(['manufacturer']); // Always available
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            // Treat strings as categories
            if (typeof v.value === 'string' && isNaN(Number(v.value))) {
                keys.add(k);
            }
        });
    });
    return Array.from(keys).sort();
  }, [data]);

  // Set default Y Axis if empty
  useEffect(() => {
      if (!yAxisKey && numericKeys.length > 0) {
          const preferred = ['密度', '熔体流动速率', '拉伸强度'].find(k => numericKeys.includes(k));
          setYAxisKey(preferred || numericKeys[0]);
      }
  }, [numericKeys, yAxisKey]);

  // Reset axis limits when xAxisKey or yAxisKey changes
  useEffect(() => {
    setXMin('');
    setXMax('');
  }, [xAxisKey]);

  useEffect(() => {
    setYMin('');
    setYMax('');
  }, [yAxisKey]);

  // 3. Prepare Chart Data
  const chartData = useMemo(() => {
    return data.map(p => {
        const item: any = {
            id: p.id,
            gradeName: p.gradeName,
            manufacturer: p.manufacturer,
            tooltipTitle: `${p.manufacturer} - ${p.gradeName}`
        };

        // Map properties to top-level keys for Recharts
        Object.entries(p.properties).forEach(([k, v]) => {
            const num = Number(v.value);
            if (!isNaN(num) && v.value !== '') {
                item[k] = num;
            } else {
                item[k] = v.value;
            }
        });
        return item;
    });
  }, [data]);

  // 4. Determine Unique Groups based on selected groupByKey
  const uniqueGroups = useMemo(() => {
    if (!groupByKey) return [];
    const groups = new Set<string>();
    chartData.forEach((item: any) => {
        const val = item[groupByKey];
        if (val !== undefined && val !== null && val !== '') {
            groups.add(String(val));
        } else {
            groups.add('Unknown');
        }
    });
    return Array.from(groups).sort();
  }, [groupByKey, chartData]);

  // 5. Auto-assign colors when groups change
  useEffect(() => {
    if (uniqueGroups.length > 0) {
        setGroupColors(prev => {
            const next = { ...prev };
            uniqueGroups.forEach((group, index) => {
                if (!next[group]) {
                    next[group] = DEFAULT_PALETTE[index % DEFAULT_PALETTE.length];
                }
            });
            return next;
        });
    }
  }, [uniqueGroups]);

  const handleDownload = async (type: 'json' | 'csv' | 'png') => {
    if (type === 'json') {
        const jsonString = JSON.stringify(chartData, null, 2);
        const blob = new Blob([jsonString], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_data.json';
        a.click();
    } else if (type === 'csv') {
        // Simple CSV export
        const headers = ['Grade', 'Manufacturer', ...numericKeys];
        const rows = chartData.map((row: any) => [
            row.gradeName,
            row.manufacturer,
            ...numericKeys.map(k => row[k] ?? '')
        ]);
        const csvContent = [
            headers.join(','),
            ...rows.map(r => r.join(','))
        ].join('\n');
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_data.csv';
        a.click();
    } else if (type === 'png' && chartRef.current) {
        const canvas = await html2canvas(chartRef.current, {
            backgroundColor: theme === 'dark' ? '#0f172a' : '#ffffff' 
        });
        const url = canvas.toDataURL('image/png');
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_chart.png';
        a.click();
    }
  };

  const AxisSelector = ({ label, value, onChange, options }: any) => (
    <div className="flex flex-col gap-1.5">
        <label className="text-[10px] uppercase font-bold text-slate-400 tracking-wider">{label}</label>
        <div className="relative">
            <select
                value={value}
                onChange={(e) => onChange(e.target.value)}
                className="w-full appearance-none bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-200 text-xs rounded-lg px-3 py-2 pr-8 focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all"
            >
                {options.map((key: string) => (
                    <option key={key} value={key}>{tProp(key)}</option>
                ))}
            </select>
            <ChevronDown size={14} className="absolute right-3 top-2.5 text-slate-400 pointer-events-none" />
        </div>
    </div>
  );

  const getDashArray = () => {
    switch (trendlineStyle) {
        case 'dashed': return '5 5';
        case 'dotted': return '2 2';
        default: return '';
    }
  };

  return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900 rounded-xl shadow-sm border border-slate-200 dark:border-slate-800 overflow-hidden relative ring-1 ring-slate-900/5 dark:ring-white/10">

      {/* Header / Config Toggle */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-950/30 backdrop-blur-sm z-20">
          <div className="flex items-center gap-2 text-slate-700 dark:text-slate-200">
              <div className="p-1.5 bg-emerald-100 dark:bg-emerald-900/30 rounded-md text-emerald-600 dark:text-emerald-400">
                  {chartType === 'bar' ? <BarChart2 size={16} /> : <ScatterIcon size={16} />}
              </div>
              <h3 className="font-semibold text-sm">{t('chartTitle')}</h3>
          </div>
          <div className="flex items-center gap-2">
               {/* Export Menu */}
               <div className="flex items-center bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg p-0.5">
                   <button onClick={() => handleDownload('json')} className="p-1.5 text-slate-400 hover:text-emerald-600 dark:hover:text-emerald-400 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-md transition-colors" title={t('exportJson')}>
                       <FileJson size={14} />
                   </button>
                   <button onClick={() => handleDownload('csv')} className="p-1.5 text-slate-400 hover:text-blue-600 dark:hover:text-blue-400 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-md transition-colors" title={t('exportCsv')}>
                       <FileType size={14} />
                   </button>
                   <button onClick={() => handleDownload('png')} className="p-1.5 text-slate-400 hover:text-purple-600 dark:hover:text-purple-400 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-md transition-colors" title={t('exportPng')}>
                       <ImageIcon size={14} />
                   </button>
               </div>

               <div className="w-px h-4 bg-slate-300 dark:bg-slate-700 mx-1"></div>

               <button 
                  onClick={() => setShowConfig(!showConfig)}
                  className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${showConfig ? 'bg-slate-200 dark:bg-slate-700 text-slate-800 dark:text-slate-100' : 'bg-white dark:bg-slate-800 text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
               >
                   <Settings size={14} />
                   {showConfig ? t('collapseConfig') : t('expandConfig')}
               </button>
