import React, { useState, useEffect } from 'react';
import { X, Save, Plus, Trash2, Beaker, Factory } from 'lucide-react';
import { Product, PropertyValue } from '../types';
import { useLanguage } from '../contexts/LanguageContext';

interface EditProductModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (product: Product) => void;
  product: Product | null;
}

interface PropertyRow {
  id: string;
  key: string;
  value: string;
  unit: string;
}

export const EditProductModal: React.FC<EditProductModalProps> = ({ isOpen, onClose, onSave, product }) => {
  const { t, tProp } = useLanguage();
  const [formData, setFormData] = useState<Partial<Product>>({});
  const [propertyRows, setPropertyRows] = useState<PropertyRow[]>([]);

  // Dedicated states for common properties for better UX
  const [ethyleneData, setEthyleneData] = useState({ value: '', unit: '' });
  const [densityData, setDensityData] = useState({ value: '', unit: '' });
  const [mfrData, setMfrData] = useState({ value: '', unit: '' });

  useEffect(() => {
    if (product) {
      setFormData({
        id: product.id,
        gradeName: product.gradeName,
        manufacturer: product.manufacturer,
        categoryIds: product.categoryIds,
        updatedAt: product.updatedAt,
      });

      // Handle dedicated Density field
      const denProp = product.properties['密度'];
      setDensityData({
        value: denProp ? String(denProp.value) : '',
        unit: denProp?.unit || 'g/cm³'
      });

      // Handle dedicated MFR field
      const mfrProp = product.properties['熔体流动速率'];
      setMfrData({
        value: mfrProp ? String(mfrProp.value) : '',
        unit: mfrProp?.unit || 'g/10min'
      });

      // Handle dedicated Ethylene Content field
      const ethProp = product.properties['乙烯含量'];
      setEthyleneData({
        value: ethProp ? String(ethProp.value) : '',
        unit: ethProp?.unit || '%'
      });

      // Filter out dedicated fields from dynamic rows to avoid duplicates
      const dedicatedKeys = ['乙烯含量', '密度', '熔体流动速率'];
      const rows: PropertyRow[] = Object.entries(product.properties)
        .filter(([key]) => !dedicatedKeys.includes(key))
        .map(([key, val], index) => ({
          id: `prop-${index}-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
          key,
          value: String(val.value),
          unit: val.unit || ''
        }));
      setPropertyRows(rows);
    }
  }, [product, isOpen]);

  if (!isOpen || !product) return null;

  const handleSave = () => {
    const newProperties: Record<string, PropertyValue> = {};

    // Add dedicated Density
    if (densityData.value.trim() !== '') {
        const numVal = Number(densityData.value);
        newProperties['密度'] = {
            value: !isNaN(numVal) ? numVal : densityData.value,
            unit: densityData.unit.trim() || undefined
        };
    }

    // Add dedicated MFR
    if (mfrData.value.trim() !== '') {
        const numVal = Number(mfrData.value);
        newProperties['熔体流动速率'] = {
            value: !isNaN(numVal) ? numVal : mfrData.value,
            unit: mfrData.unit.trim() || undefined
        };
    }

    // Add dedicated Ethylene Content
    if (ethyleneData.value.trim() !== '') {
        const numVal = Number(ethyleneData.value);
        newProperties['乙烯含量'] = {
            value: !isNaN(numVal) ? numVal : ethyleneData.value,
            unit: ethyleneData.unit.trim() || undefined
        };
    }

    propertyRows.forEach(row => {
      if (row.key.trim()) {
        const numVal = Number(row.value);
        newProperties[row.key] = {
          value: !isNaN(numVal) && row.value.trim() !== '' ? numVal : row.value,
          unit: row.unit.trim() || undefined
        };
      }
    });

    onSave({
      ...product,
      ...formData as Product,
      properties: newProperties,
      updatedAt: new Date().toISOString().split('T')[0]
    });
    onClose();
  };

  const addProperty = () => {
    setPropertyRows([...propertyRows, { id: `new-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`, key: '', value: '', unit: '' }]);
  };

  const removeProperty = (id: string) => {
    setPropertyRows(prev => prev.filter(p => p.id !== id));
  };

  const updateProperty = (id: string, field: keyof PropertyRow, val: string) => {
    setPropertyRows(prev => prev.map(p => p.id === id ? { ...p, [field]: val } : p));
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="w-full max-w-2xl bg-white dark:bg-slate-900 rounded-xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200 ring-1 ring-slate-200 dark:ring-slate-800 flex flex-col max-h-[90vh]">

