                    className="p-1.5 text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-md transition-colors hidden sm:block"
                >
                    {isExpanded ? <Minimize2 size={16} /> : <Maximize2 size={16} />}
                </button>
                <button 
                    onClick={() => setIsOpen(false)} 
                    className="p-1.5 text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-md transition-colors"
                >
                    <X size={18} />
                </button>
            </div>
        </div>

        {/* Messages Area */}
        <div className="flex-1 overflow-y-auto p-4 space-y-5 bg-slate-50/50 dark:bg-slate-950/50 custom-scrollbar" ref={chatContainerRef}>
            {messages.map((msg) => (
                <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
                    <div className={`flex gap-3 max-w-[85%] ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                        {/* Avatar */}
                        <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 border ${msg.role === 'user' ? 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700' : 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-100 dark:border-emerald-800/50'}`}>
                            {msg.role === 'user' ? <User size={14} className="text-slate-600 dark:text-slate-400"/> : <Sparkles size={14} className="text-emerald-600 dark:text-emerald-400"/>}
                        </div>

                        {/* Message Bubble */}
                        <div className={`flex flex-col gap-1 ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                            <div className={`rounded-2xl px-4 py-3 text-sm shadow-sm ${
                                msg.role === 'user' 
                                ? 'bg-slate-900 dark:bg-emerald-600 text-white rounded-tr-sm' 
                                : 'bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-200 border border-slate-200 dark:border-slate-700 rounded-tl-sm'
                            }`}>
                                {msg.image && (
                                    <div className="mb-3 rounded-lg overflow-hidden border border-white/20 shadow-sm relative group/img">
                                        <img src={msg.image} alt="Uploaded" className="max-w-full h-auto max-h-48 object-cover" />
                                        <div className="absolute top-2 left-2 px-1.5 py-0.5 bg-black/60 backdrop-blur-sm rounded text-[9px] text-white font-bold flex items-center gap-1 opacity-0 group-hover/img:opacity-100 transition-opacity">
                                            <ShieldCheck size={10} className="text-emerald-400" />
                                            QC PROTOCOL
                                        </div>
                                    </div>
                                )}
                                <FormattedText text={msg.text} />
                            </div>
                        </div>
                    </div>
                </div>
            ))}

            {isLoading && (
                <div className="flex justify-start animate-in fade-in duration-300">
                     <div className="flex gap-3 max-w-[85%]">
                        <div className="w-8 h-8 rounded-full bg-emerald-50 dark:bg-emerald-900/20 border border-emerald-100 dark:border-emerald-800/50 flex items-center justify-center shrink-0">
                            <Sparkles size={14} className="text-emerald-600 dark:text-emerald-400"/>
                        </div>
                        <div className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl rounded-tl-sm px-4 py-3 shadow-sm flex items-center gap-3">
                            <div className="flex gap-1">
                                <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                                <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                                <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-bounce"></span>
                            </div>
                            <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">
                                {useThinking ? t('reasoning') : t('analyzing')}
                            </span>
                        </div>
                     </div>
                </div>
            )}
            <div ref={messagesEndRef} />
        </div>

        {/* Input Area */}
        <div className="p-3 bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800">
            {attachedImage && (
                <div className="flex items-center justify-between px-3 py-2 mb-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg animate-in slide-in-from-bottom-2">
                    <div className="flex items-center gap-3 overflow-hidden">
                        <div className="w-10 h-10 rounded bg-slate-200 dark:bg-slate-700 shrink-0 overflow-hidden border border-slate-300 dark:border-slate-600">
                             <img src={attachedImage} alt="Preview" className="w-full h-full object-cover" />
                        </div>
                        <div className="flex flex-col overflow-hidden">
                             <span className="text-xs font-semibold text-slate-700 dark:text-slate-200 truncate">{t('imageAttached')}</span>
                             <span className="text-[10px] text-emerald-600 dark:text-emerald-400 flex items-center gap-1">
                                <ShieldCheck size={10} />
                                QC Analysis Protocol Active
                             </span>
                        </div>
                    </div>
                    <button onClick={() => setAttachedImage(null)} className="p-1.5 text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-md transition-colors">
                        <Trash2 size={16} />
                    </button>
                </div>
            )}

            <div className="flex items-end gap-2 bg-slate-100 dark:bg-slate-800/50 p-1.5 rounded-2xl border border-slate-200 dark:border-slate-700 focus-within:ring-2 focus-within:ring-emerald-500/20 focus-within:border-emerald-500 transition-all">
                <input 
                    type="file" 
                    ref={fileInputRef}
                    accept="image/*" 
                    className="hidden"
                    onChange={handleImageUpload}
                />
                <button 
                    onClick={() => fileInputRef.current?.click()}
                    className={`p-2 rounded-xl transition-all shrink-0 ${attachedImage ? 'text-emerald-600 dark:text-emerald-400 bg-emerald-100 dark:bg-emerald-900/30' : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700'}`}
                    title={t('uploadImage')}
                >
                    {attachedImage ? <ScanEye size={20} /> : <ImageIcon size={20} />}
                </button>

                <textarea
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder={attachedImage ? t('imageContext') : t('aiPlaceholder')}
                    className="w-full max-h-32 min-h-[40px] py-2 bg-transparent text-sm text-slate-800 dark:text-slate-200 placeholder:text-slate-400 outline-none resize-none custom-scrollbar leading-relaxed"
                    rows={1}
                />

                <button 
                    onClick={handleSendMessage}
                    disabled={(!input.trim() && !attachedImage) || isLoading}
                    className="p-2 bg-slate-900 dark:bg-emerald-600 hover:bg-slate-800 dark:hover:bg-emerald-500 disabled:bg-slate-200 dark:disabled:bg-slate-700 disabled:text-slate-400 text-white rounded-xl transition-all shadow-sm disabled:shadow-none shrink-0"
                >
                    {isLoading ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />}
                </button>
            </div>
            <div className="text-[10px] text-center text-slate-400 dark:text-slate-600 mt-2 select-none">
                AI Vision specialized in defect detection. Accuracy varies by lighting.
            </div>
        </div>
      </div>
    </>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  ReferenceLine,
  Cell,
  LabelList,
  Line,
  ComposedChart,
  ZAxis
} from 'recharts';
import { Settings, Download, ChevronUp, ChevronDown, BarChart2, ScatterChart as ScatterIcon, TrendingUp, Palette, PaintBucket, FileJson, FileType, Image as ImageIcon, RotateCcw } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

const DEFAULT_PALETTE = [
  '#10b981', // Emerald
  '#3b82f6', // Blue
  '#f59e0b', // Amber
  '#ef4444', // Red
  '#8b5cf6', // Violet
  '#ec4899', // Pink
  '#06b6d4', // Cyan
  '#84cc16', // Lime
  '#f97316', // Orange
  '#6366f1', // Indigo
];

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const { t, tProp } = useLanguage();
  const { theme } = useTheme();
  const chartRef = useRef<HTMLDivElement>(null);

  const [showConfig, setShowConfig] = useState(true);
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('gradeName');
  const [yAxisKey, setYAxisKey] = useState<string>('');

  // Manual Axis Limits
  const [xMin, setXMin] = useState<number | ''>('');
  const [xMax, setXMax] = useState<number | ''>('');
  const [yMin, setYMin] = useState<number | ''>('');
  const [yMax, setYMax] = useState<number | ''>('');

  // Trendline State
  const [showTrendline, setShowTrendline] = useState(false);
  const [trendlineColor, setTrendlineColor] = useState('#ef4444');
  const [trendlineWidth, setTrendlineWidth] = useState(2);
  const [trendlineStyle, setTrendlineStyle] = useState<'solid' | 'dashed' | 'dotted'>('dashed');

  // Scatter Plot Grouping State
  const [groupByKey, setGroupByKey] = useState<string>('');
  const [groupColors, setGroupColors] = useState<Record<string, string>>({});

  // 1. Identify Numeric Keys (for Axes)
  const numericKeys = useMemo(() => {
     const keys = new Set<string>();
     data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
           if (typeof v.value === 'number') {
               keys.add(k);
           } else if (!isNaN(Number(v.value)) && v.value !== '') {
               keys.add(k);
           }
        });
     });
     return Array.from(keys).sort();
  }, [data]);

  // 2. Identify Categorical Keys (for Grouping)
  const categoricalKeys = useMemo(() => {
    const keys = new Set<string>(['manufacturer']); // Always available
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (typeof v.value === 'string' && isNaN(Number(v.value))) {
                keys.add(k);
            }
        });
    });
    return Array.from(keys).sort();
  }, [data]);

  useEffect(() => {
      if (!yAxisKey && numericKeys.length > 0) {
          const preferred = ['密度', '熔体流动速率', '拉伸强度'].find(k => numericKeys.includes(k));
          setYAxisKey(preferred || numericKeys[0]);
      }
  }, [numericKeys, yAxisKey]);

  useEffect(() => {
    setXMin('');
    setXMax('');
  }, [xAxisKey]);

  useEffect(() => {
    setYMin('');
    setYMax('');
  }, [yAxisKey]);

  // 3. Prepare Chart Data
  const chartData = useMemo(() => {
    return data.map(p => {
        const item: any = {
            id: p.id,
            gradeName: p.gradeName,
            manufacturer: p.manufacturer,
            tooltipTitle: `${p.manufacturer} - ${p.gradeName}`
        };

        Object.entries(p.properties).forEach(([k, v]) => {
            const num = Number(v.value);
            if (!isNaN(num) && v.value !== '') {
                item[k] = num;
            } else {
                item[k] = v.value;
            }
        });
        return item;
    });
  }, [data]);

  // 4. Calculate Linear Regression for Trendline
  const trendlineSegment = useMemo(() => {
    if (!showTrendline || chartType !== 'scatter') return null;

    const validPoints = chartData.filter(d => 
        typeof d[xAxisKey] === 'number' && 
        typeof d[yAxisKey] === 'number'
    );

    if (validPoints.length < 2) return null;

    const n = validPoints.length;
    let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
    let minX = Infinity, maxX = -Infinity;

    validPoints.forEach(p => {
        const x = p[xAxisKey];
        const y = p[yAxisKey];
        sumX += x;
        sumY += y;
        sumXY += x * y;
        sumX2 += x * x;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
    });

    const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
    const intercept = (sumY - slope * sumX) / n;

    return [
        { [xAxisKey]: minX, [yAxisKey]: slope * minX + intercept, isTrend: true },
        { [xAxisKey]: maxX, [yAxisKey]: slope * maxX + intercept, isTrend: true }
    ];
  }, [chartData, xAxisKey, yAxisKey, showTrendline, chartType]);

  const dashArray = useMemo(() => {
    if (trendlineStyle === 'dashed') return '5 5';
    if (trendlineStyle === 'dotted') return '2 2';
    return '0';
  }, [trendlineStyle]);

  // 5. Determine Unique Groups
  const uniqueGroups = useMemo(() => {
    if (!groupByKey) return [];
    const groups = new Set<string>();
    chartData.forEach((item: any) => {
        const val = item[groupByKey];
        if (val !== undefined && val !== null && val !== '') {
            groups.add(String(val));
        } else {
            groups.add('Unknown');
        }
    });
    return Array.from(groups).sort();
  }, [groupByKey, chartData]);

  useEffect(() => {
    if (uniqueGroups.length > 0) {
        setGroupColors(prev => {
            const next = { ...prev };
            uniqueGroups.forEach((group, index) => {
                if (!next[group]) {
                    next[group] = DEFAULT_PALETTE[index % DEFAULT_PALETTE.length];
                }
            });
            return next;
        });
    }
  }, [uniqueGroups]);

  const handleDownload = async (type: 'json' | 'csv' | 'png') => {
    if (type === 'json') {
        const jsonString = JSON.stringify(chartData, null, 2);
        const blob = new Blob([jsonString], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_data.json';
        a.click();
    } else if (type === 'csv') {
        const headers = ['Grade', 'Manufacturer', ...numericKeys];
        const rows = chartData.map((row: any) => [
            row.gradeName,
            row.manufacturer,
            ...numericKeys.map(k => row[k] ?? '')
        ]);
        const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
        const blob = new Blob([csvContent], { type: 'text/csv' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_data.csv';
        a.click();
    } else if (type === 'png' && chartRef.current) {
        const canvas = await html2canvas(chartRef.current, {
            backgroundColor: theme === 'dark' ? '#020617' : '#ffffff'
        });
        const url = canvas.toDataURL('image/png');
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_chart.png';
        a.click();
    }
  };

  return (
    <div className="flex flex-col md:flex-row h-full gap-4 overflow-hidden">
      {/* Settings Panel */}
      <div className={`flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl transition-all duration-300 overflow-hidden shrink-0 ${showConfig ? 'w-full md:w-80 opacity-100' : 'w-0 opacity-0 overflow-hidden md:border-none'}`}>
        <div className="p-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-950/50">
          <div className="flex items-center gap-2 font-bold text-sm text-slate-700 dark:text-slate-200 uppercase tracking-wider">
            <Settings size={16} className="text-emerald-500" />
            {t('chartConfig')}
          </div>
          <button onClick={() => setShowConfig(false)} className="md:hidden text-slate-400 hover:text-slate-600 dark:hover:text-slate-300">
            <ChevronUp size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-5 custom-scrollbar space-y-6">
          {/* Chart Type Selection */}
          <div className="space-y-3">
             <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <LayoutDashboard size={12} />
                {t('chartType')}
             </label>
             <div className="flex gap-2">
                <button 
                  onClick={() => setChartType('bar')}
                  className={`flex-1 flex flex-col items-center gap-2 p-3 rounded-xl border-2 transition-all ${chartType === 'bar' ? 'border-emerald-500 bg-emerald-50/50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 shadow-md shadow-emerald-500/10' : 'border-slate-100 dark:border-slate-800 text-slate-400 hover:border-slate-200 dark:hover:border-slate-700'}`}
                >
                  <BarChart2 size={24} />
                  <span className="text-[10px] font-bold uppercase">{t('barChart')}</span>
                </button>
                <button 
                  onClick={() => setChartType('scatter')}
                  className={`flex-1 flex flex-col items-center gap-2 p-3 rounded-xl border-2 transition-all ${chartType === 'scatter' ? 'border-emerald-500 bg-emerald-50/50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 shadow-md shadow-emerald-500/10' : 'border-slate-100 dark:border-slate-800 text-slate-400 hover:border-slate-200 dark:hover:border-slate-700'}`}
                >
                  <ScatterIcon size={24} />
                  <span className="text-[10px] font-bold uppercase">{t('scatterChart')}</span>
                </button>
             </div>
          </div>

          {/* Axis Mapping */}
          <div className="space-y-4">
            <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <RotateCcw size={12} />
                {t('axisMapping')}
            </label>
            <div className="space-y-3">
              <div className="space-y-1.5">
                <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('xAxis')}</span>
                <select 
                  value={xAxisKey} 
                  onChange={(e) => setXAxisKey(e.target.value)}
                  className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 outline-none transition-all"
                >
                  {chartType === 'bar' && <option value="gradeName">{tProp('牌号')}</option>}
                  {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                </select>
              </div>
              <div className="space-y-1.5">
                <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('yAxis')}</span>
                <select 
                  value={yAxisKey} 
                  onChange={(e) => setYAxisKey(e.target.value)}
                  className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 outline-none transition-all"
                >
                  {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                </select>
              </div>
            </div>
          </div>

          {/* Color & Grouping */}
          <div className="space-y-4 pt-2 border-t border-slate-100 dark:border-slate-800">
             <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <Palette size={12} />
                {t('styleGrouping')}
             </label>
             <div className="space-y-1.5">
               <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('groupBy')}</span>
               <select 
                 value={groupByKey} 
                 onChange={(e) => setGroupByKey(e.target.value)}
                 className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 outline-none transition-all"
               >
                 <option value="">{t('none')}</option>
                 {categoricalKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
               </select>
             </div>
          </div>

          {/* Trendline Settings (Scatter only) */}
          {chartType === 'scatter' && (
            <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
               <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                  <TrendingUp size={12} />
                  {t('trendline')}
               </label>
               <div className="space-y-3">
                  <label className="flex items-center gap-3 cursor-pointer group">
                      <div className={`w-8 h-4 rounded-full relative transition-colors ${showTrendline ? 'bg-emerald-500' : 'bg-slate-200 dark:bg-slate-700'}`}>
                          <div className={`absolute top-0.5 w-3 h-3 bg-white rounded-full transition-transform ${showTrendline ? 'left-4.5 translate-x-4' : 'left-0.5'}`}></div>
                          <input type="checkbox" checked={showTrendline} onChange={() => setShowTrendline(!showTrendline)} className="hidden" />
                      </div>
                      <span className="text-sm text-slate-600 dark:text-slate-300">{t('showTrendline')}</span>
                  </label>

                  {showTrendline && (
                    <div className="space-y-3 pl-2 animate-in fade-in slide-in-from-top-1">
                      <div className="space-y-1">
                        <span className="text-[10px] text-slate-400 font-bold uppercase">{t('trendlineColor')}</span>
                        <div className="flex gap-2 flex-wrap">
                          {['#ef4444', '#f59e0b', '#10b981', '#3b82f6', '#8b5cf6'].map(c => (
                            <button 
                              key={c} 
                              onClick={() => setTrendlineColor(c)}
                              className={`w-6 h-6 rounded-full border-2 ${trendlineColor === c ? 'border-white ring-2 ring-emerald-500' : 'border-transparent'}`}
                              style={{ backgroundColor: c }}
                            />
                          ))}
                          <input 
                            type="color" 
                            value={trendlineColor} 
                            onChange={(e) => setTrendlineColor(e.target.value)}
                            className="w-6 h-6 p-0 border-none bg-transparent cursor-pointer"
                          />
                        </div>
                      </div>
                      <div className="space-y-1">
                        <span className="text-[10px] text-slate-400 font-bold uppercase">{t('trendlineWidth')}</span>
                        <input 
                          type="range" min="1" max="5" step="1" 
                          value={trendlineWidth} 
                          onChange={(e) => setTrendlineWidth(Number(e.target.value))}
                          className="w-full accent-emerald-500" 
                        />
                      </div>
                      <div className="space-y-1">
                        <span className="text-[10px] text-slate-400 font-bold uppercase">{t('trendlineStyle')}</span>
                        <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-lg">
                           {(['solid', 'dashed', 'dotted'] as const).map(style => (
                             <button
                                key={style}
                                onClick={() => setTrendlineStyle(style)}
                                className={`flex-1 px-2 py-1 text-[9px] font-bold uppercase rounded transition-all ${trendlineStyle === style ? 'bg-white dark:bg-slate-700 shadow-sm text-emerald-600' : 'text-slate-400'}`}
                             >
                               {t(style)}
                             </button>
                           ))}
                        </div>
                      </div>
                    </div>
                  )}
               </div>
            </div>
          )}

          {/* Export Group */}
          <div className="pt-4 border-t border-slate-100 dark:border-slate-800 grid grid-cols-2 gap-2">
            <button 
              onClick={() => handleDownload('json')}
              className="flex items-center justify-center gap-2 p-2 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-lg text-[10px] font-bold text-slate-600 dark:text-slate-400 transition-colors uppercase"
            >
              <FileJson size={14} />
              JSON
            </button>
            <button 
              onClick={() => handleDownload('png')}
              className="flex items-center justify-center gap-2 p-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-[10px] font-bold transition-colors uppercase shadow-md shadow-emerald-500/20"
            >
              <ImageIcon size={14} />
              PNG
            </button>
          </div>
        </div>
      </div>

      {/* Chart Canvas Area */}
      <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl relative min-h-[400px]">
        {!showConfig && (
            <button 
                onClick={() => setShowConfig(true)}
                className="absolute top-4 left-4 z-10 p-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-emerald-500 hover:scale-105 transition-transform shadow-lg"
            >
                <Settings size={20} />
            </button>
        )}

        <div className="flex-1 p-6 flex flex-col min-h-0" ref={chartRef}>
            <div className="mb-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
               <div>
                  <h2 className="text-lg font-bold text-slate-800 dark:text-white flex items-center gap-2">
                     {chartType === 'bar' ? <BarChart2 size={20} className="text-emerald-500" /> : <ScatterIcon size={20} className="text-emerald-500" />}
                     {tProp(yAxisKey)} vs {chartType === 'bar' ? tProp('牌号') : tProp(xAxisKey)}
                  </h2>
                  <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">{t('chartTitle')}</p>
               </div>
               {groupByKey && (
                 <div className="flex flex-wrap gap-2">
                    {uniqueGroups.map(group => (
                        <div key={group} className="flex items-center gap-1.5 px-2 py-1 bg-slate-50 dark:bg-slate-800 rounded-full border border-slate-100 dark:border-slate-700">
                           <div className="w-2 h-2 rounded-full" style={{ backgroundColor: groupColors[group] }}></div>
                           <span className="text-[10px] font-bold text-slate-600 dark:text-slate-300">{group}</span>
                        </div>
                    ))}
                 </div>
               )}
            </div>

            <div className="flex-1 w-full min-h-0">
                <ResponsiveContainer width="100%" height="100%">
                    {chartType === 'bar' ? (
                        <BarChart data={chartData} margin={{ top: 10, right: 30, left: 0, bottom: 40 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis 
                                dataKey="gradeName" 
                                angle={-45} 
                                textAnchor="end" 
                                interval={0} 
                                height={60} 
                                fontSize={10} 
                                stroke={theme === 'dark' ? '#475569' : '#94a3b8'}
                                tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b' }}
                            />
                            <YAxis 
                                fontSize={10} 
                                stroke={theme === 'dark' ? '#475569' : '#94a3b8'}
                                tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b' }}
                            />
                            <Tooltip 
                                cursor={{ fill: 'rgba(16, 185, 129, 0.05)' }}
                                contentStyle={{ 
                                    backgroundColor: theme === 'dark' ? '#0f172a' : '#ffffff',
                                    borderColor: theme === 'dark' ? '#1e293b' : '#e2e8f0',
                                    borderRadius: '12px',
                                    fontSize: '12px',
                                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)'
                                }}
                            />
                            <Bar dataKey={yAxisKey} radius={[4, 4, 0, 0]} animationDuration={1000}>
                                {chartData.map((entry, index) => (
                                    <Cell 
                                        key={`cell-${index}`} 
                                        fill={groupByKey ? groupColors[String(entry[groupByKey])] : DEFAULT_PALETTE[index % DEFAULT_PALETTE.length]} 
                                    />
                                ))}
                            </Bar>
                        </BarChart>
                    ) : (
                        <ComposedChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis 
                                type="number" 
                                dataKey={xAxisKey} 
                                name={tProp(xAxisKey)} 
                                fontSize={10} 
                                stroke={theme === 'dark' ? '#475569' : '#94a3b8'}
                                tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b' }}
                                label={{ value: tProp(xAxisKey), position: 'bottom', offset: 0, fontSize: 10, fill: '#64748b' }}
                            />
                            <YAxis 
                                type="number" 
                                dataKey={yAxisKey} 
                                name={tProp(yAxisKey)} 
                                fontSize={10} 
                                stroke={theme === 'dark' ? '#475569' : '#94a3b8'}
                                tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b' }}
                                label={{ value: tProp(yAxisKey), angle: -90, position: 'insideLeft', offset: 10, fontSize: 10, fill: '#64748b' }}
                            />
                            <ZAxis range={[60, 400]} />
                            <Tooltip 
                                cursor={{ strokeDasharray: '3 3' }}
                                contentStyle={{ 
                                    backgroundColor: theme === 'dark' ? '#0f172a' : '#ffffff',
                                    borderColor: theme === 'dark' ? '#1e293b' : '#e2e8f0',
                                    borderRadius: '12px',
                                    fontSize: '12px',
                                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)'
                                }}
                                content={({ active, payload }) => {
                                    if (active && payload && payload.length) {
                                        const d = payload[0].payload;
                                        if (d.isTrend) return null;
                                        return (
                                            <div className="p-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-xl">
                                                <p className="font-bold text-slate-800 dark:text-white mb-1">{d.gradeName}</p>
                                                <p className="text-[10px] text-slate-500 dark:text-slate-400 mb-2">{d.manufacturer}</p>
                                                <div className="space-y-1 pt-1 border-t border-slate-100 dark:border-slate-800">
                                                    <p className="text-xs flex justify-between gap-4">
                                                        <span className="text-slate-500">{tProp(xAxisKey)}:</span>
                                                        <span className="font-mono font-bold text-emerald-600">{d[xAxisKey]}</span>
                                                    </p>
                                                    <p className="text-xs flex justify-between gap-4">
                                                        <span className="text-slate-500">{tProp(yAxisKey)}:</span>
                                                        <span className="font-mono font-bold text-blue-600">{d[yAxisKey]}</span>
                                                    </p>
                                                </div>
                                            </div>
                                        );
                                    }
                                    return null;
                                }}
                            />
                            <Scatter 
                                name="Resin Samples" 
                                data={chartData} 
                                animationDuration={1500}
                                animationEasing="ease-in-out"
                            >
                                {chartData.map((entry, index) => (
                                    <Cell 
                                        key={`cell-${index}`} 
                                        fill={groupByKey ? groupColors[String(entry[groupByKey])] : '#10b981'} 
                                        strokeWidth={1}
                                        stroke="#ffffff"
                                        className="hover:scale-125 transition-transform"
                                    />
                                ))}
                            </Scatter>
                            {trendlineSegment && (
                                <Line 
                                    type="monotone" 
                                    data={trendlineSegment} 
                                    dataKey={yAxisKey} 
                                    stroke={trendlineColor} 
                                    strokeWidth={trendlineWidth} 
                                    strokeDasharray={dashArray}
                                    dot={false}
                                    activeDot={false}
                                    legendType="none"
                                />
                            )}
                        </ComposedChart>
                    )}
                </ResponsiveContainer>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  ReferenceLine,
  Cell,
  LabelList,
  Line,
  ComposedChart,
  ZAxis
} from 'recharts';
// Added LayoutDashboard to the imports from lucide-react
import { Settings, Download, ChevronUp, ChevronDown, BarChart2, ScatterChart as ScatterIcon, TrendingUp, Palette, PaintBucket, FileJson, FileType, Image as ImageIcon, RotateCcw, LayoutDashboard } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

const DEFAULT_PALETTE = [
  '#10b981', // Emerald
  '#3b82f6', // Blue
  '#f59e0b', // Amber
  '#ef4444', // Red
  '#8b5cf6', // Violet
  '#ec4899', // Pink
  '#06b6d4', // Cyan
  '#84cc16', // Lime
  '#f97316', // Orange
  '#6366f1', // Indigo
];

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const { t, tProp } = useLanguage();
  const { theme } = useTheme();
  const chartRef = useRef<HTMLDivElement>(null);

  const [showConfig, setShowConfig] = useState(true);
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('gradeName');
  const [yAxisKey, setYAxisKey] = useState<string>('');

  // Manual Axis Limits
  const [xMin, setXMin] = useState<number | ''>('');
  const [xMax, setXMax] = useState<number | ''>('');
  const [yMin, setYMin] = useState<number | ''>('');
  const [yMax, setYMax] = useState<number | ''>('');

  // Trendline State
  const [showTrendline, setShowTrendline] = useState(false);
  const [trendlineColor, setTrendlineColor] = useState('#ef4444');
  const [trendlineWidth, setTrendlineWidth] = useState(2);
  const [trendlineStyle, setTrendlineStyle] = useState<'solid' | 'dashed' | 'dotted'>('dashed');

  // Scatter Plot Grouping State
  const [groupByKey, setGroupByKey] = useState<string>('');
  const [groupColors, setGroupColors] = useState<Record<string, string>>({});

  // 1. Identify Numeric Keys (for Axes)
  const numericKeys = useMemo(() => {
     const keys = new Set<string>();
     data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
           if (typeof v.value === 'number') {
               keys.add(k);
           } else if (!isNaN(Number(v.value)) && v.value !== '') {
               keys.add(k);
           }
        });
     });
     return Array.from(keys).sort();
  }, [data]);

  // 2. Identify Categorical Keys (for Grouping)
  const categoricalKeys = useMemo(() => {
    const keys = new Set<string>(['manufacturer']); // Always available
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (typeof v.value === 'string' && isNaN(Number(v.value))) {
                keys.add(k);
            }
        });
    });
    return Array.from(keys).sort();
  }, [data]);

  useEffect(() => {
      if (!yAxisKey && numericKeys.length > 0) {
          const preferred = ['密度', '熔体流动速率', '拉伸强度'].find(k => numericKeys.includes(k));
          setYAxisKey(preferred || numericKeys[0]);
      }
  }, [numericKeys, yAxisKey]);

  useEffect(() => {
    setXMin('');
    setXMax('');
  }, [xAxisKey]);

  useEffect(() => {
    setYMin('');
    setYMax('');
  }, [yAxisKey]);

  // 3. Prepare Chart Data
  const chartData = useMemo(() => {
    return data.map(p => {
        const item: any = {
            id: p.id,
            gradeName: p.gradeName,
            manufacturer: p.manufacturer,
            tooltipTitle: `${p.manufacturer} - ${p.gradeName}`
        };

        Object.entries(p.properties).forEach(([k, v]) => {
            const num = Number(v.value);
            if (!isNaN(num) && v.value !== '') {
                item[k] = num;
            } else {
                item[k] = v.value;
            }
        });
        return item;
    });
  }, [data]);

  // 4. Calculate Linear Regression for Trendline
  const trendlineSegment = useMemo(() => {
    if (!showTrendline || chartType !== 'scatter') return null;

    const validPoints = chartData.filter(d => 
        typeof d[xAxisKey] === 'number' && 
        typeof d[yAxisKey] === 'number'
    );

    if (validPoints.length < 2) return null;

    const n = validPoints.length;
    let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
    let minX = Infinity, maxX = -Infinity;

    validPoints.forEach(p => {
        const x = p[xAxisKey];
        const y = p[yAxisKey];
        sumX += x;
        sumY += y;
        sumXY += x * y;
        sumX2 += x * x;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
    });

    const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
    const intercept = (sumY - slope * sumX) / n;

    return [
        { [xAxisKey]: minX, [yAxisKey]: slope * minX + intercept, isTrend: true },
        { [xAxisKey]: maxX, [yAxisKey]: slope * maxX + intercept, isTrend: true }
    ];
  }, [chartData, xAxisKey, yAxisKey, showTrendline, chartType]);

  const dashArray = useMemo(() => {
    if (trendlineStyle === 'dashed') return '5 5';
    if (trendlineStyle === 'dotted') return '2 2';
    return '0';
  }, [trendlineStyle]);

  // 5. Determine Unique Groups
  const uniqueGroups = useMemo(() => {
    if (!groupByKey) return [];
    const groups = new Set<string>();
    chartData.forEach((item: any) => {
        const val = item[groupByKey];
        if (val !== undefined && val !== null && val !== '') {
            groups.add(String(val));
        } else {
            groups.add('Unknown');
        }
    });
    return Array.from(groups).sort();
  }, [groupByKey, chartData]);

  useEffect(() => {
    if (uniqueGroups.length > 0) {
        setGroupColors(prev => {
            const next = { ...prev };
            uniqueGroups.forEach((group, index) => {
                if (!next[group]) {
                    next[group] = DEFAULT_PALETTE[index % DEFAULT_PALETTE.length];
                }
            });
            return next;
        });
    }
  }, [uniqueGroups]);

  const handleDownload = async (type: 'json' | 'csv' | 'png') => {
    if (type === 'json') {
        const jsonString = JSON.stringify(chartData, null, 2);
        const blob = new Blob([jsonString], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_data.json';
        a.click();
    } else if (type === 'csv') {
        const headers = ['Grade', 'Manufacturer', ...numericKeys];
        const rows = chartData.map((row: any) => [
            row.gradeName,
            row.manufacturer,
            ...numericKeys.map(k => row[k] ?? '')
        ]);
        const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
        const blob = new Blob([csvContent], { type: 'text/csv' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_data.csv';
        a.click();
    } else if (type === 'png' && chartRef.current) {
        const canvas = await html2canvas(chartRef.current, {
            backgroundColor: theme === 'dark' ? '#020617' : '#ffffff'
        });
        const url = canvas.toDataURL('image/png');
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_chart.png';
        a.click();
    }
  };

  return (
    <div className="flex flex-col md:flex-row h-full gap-4 overflow-hidden">
      {/* Settings Panel */}
      <div className={`flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl transition-all duration-300 overflow-hidden shrink-0 ${showConfig ? 'w-full md:w-80 opacity-100' : 'w-0 opacity-0 overflow-hidden md:border-none'}`}>
        <div className="p-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-950/50">
          <div className="flex items-center gap-2 font-bold text-sm text-slate-700 dark:text-slate-200 uppercase tracking-wider">
            <Settings size={16} className="text-emerald-500" />
            {t('chartConfig')}
          </div>
          <button onClick={() => setShowConfig(false)} className="md:hidden text-slate-400 hover:text-slate-600 dark:hover:text-slate-300">
            <ChevronUp size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-5 custom-scrollbar space-y-6">
          {/* Chart Type Selection */}
          <div className="space-y-3">
             <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <LayoutDashboard size={12} />
                {t('chartType')}
             </label>
             <div className="flex gap-2">
                <button 
                  onClick={() => setChartType('bar')}
                  className={`flex-1 flex flex-col items-center gap-2 p-3 rounded-xl border-2 transition-all ${chartType === 'bar' ? 'border-emerald-500 bg-emerald-50/50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 shadow-md shadow-emerald-500/10' : 'border-slate-100 dark:border-slate-800 text-slate-400 hover:border-slate-200 dark:hover:border-slate-700'}`}
                >
                  <BarChart2 size={24} />
                  <span className="text-[10px] font-bold uppercase">{t('barChart')}</span>
                </button>
                <button 
                  onClick={() => setChartType('scatter')}
                  className={`flex-1 flex flex-col items-center gap-2 p-3 rounded-xl border-2 transition-all ${chartType === 'scatter' ? 'border-emerald-500 bg-emerald-50/50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 shadow-md shadow-emerald-500/10' : 'border-slate-100 dark:border-slate-800 text-slate-400 hover:border-slate-200 dark:hover:border-slate-700'}`}
                >
                  <ScatterIcon size={24} />
                  <span className="text-[10px] font-bold uppercase">{t('scatterChart')}</span>
                </button>
             </div>
          </div>

          {/* Axis Mapping */}
          <div className="space-y-4">
            <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <RotateCcw size={12} />
                {t('axisMapping')}
            </label>
            <div className="space-y-3">
              <div className="space-y-1.5">
                <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('xAxis')}</span>
                <select 
                  value={xAxisKey} 
                  onChange={(e) => setXAxisKey(e.target.value)}
                  className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 outline-none transition-all"
                >
                  {chartType === 'bar' && <option value="gradeName">{tProp('牌号')}</option>}
                  {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                </select>
              </div>
              <div className="space-y-1.5">
                <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('yAxis')}</span>
                <select 
                  value={yAxisKey} 
                  onChange={(e) => setYAxisKey(e.target.value)}
                  className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 outline-none transition-all"
                >
                  {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                </select>
              </div>
            </div>
          </div>

          {/* Color & Grouping */}
          <div className="space-y-4 pt-2 border-t border-slate-100 dark:border-slate-800">
             <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <Palette size={12} />
                {t('styleGrouping')}
             </label>
             <div className="space-y-1.5">
               <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('groupBy')}</span>
               <select 
                 value={groupByKey} 
                 onChange={(e) => setGroupByKey(e.target.value)}
                 className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 outline-none transition-all"
               >
                 <option value="">{t('none')}</option>
                 {categoricalKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
               </select>
             </div>
          </div>

          {/* Trendline Settings (Scatter only) */}
          {chartType === 'scatter' && (
            <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
               <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                  <TrendingUp size={12} />
                  {t('trendline')}
               </label>
               <div className="space-y-3">
                  <label className="flex items-center gap-3 cursor-pointer group">
                      <div className={`w-8 h-4 rounded-full relative transition-colors ${showTrendline ? 'bg-emerald-500' : 'bg-slate-200 dark:bg-slate-700'}`}>
                          <div className={`absolute top-0.5 w-3 h-3 bg-white rounded-full transition-transform ${showTrendline ? 'left-4.5 translate-x-4' : 'left-0.5'}`}></div>
                          <input type="checkbox" checked={showTrendline} onChange={() => setShowTrendline(!showTrendline)} className="hidden" />
                      </div>
                      <span className="text-sm text-slate-600 dark:text-slate-300">{t('showTrendline')}</span>
                  </label>

                  {showTrendline && (
                    <div className="space-y-3 pl-2 animate-in fade-in slide-in-from-top-1">
                      <div className="space-y-1">
                        <span className="text-[10px] text-slate-400 font-bold uppercase">{t('trendlineColor')}</span>
                        <div className="flex gap-2 flex-wrap">
                          {['#ef4444', '#f59e0b', '#10b981', '#3b82f6', '#8b5cf6'].map(c => (
                            <button 
                              key={c} 
                              onClick={() => setTrendlineColor(c)}
                              className={`w-6 h-6 rounded-full border-2 ${trendlineColor === c ? 'border-white ring-2 ring-emerald-500' : 'border-transparent'}`}
                              style={{ backgroundColor: c }}
                            />
                          ))}
                          <input 
                            type="color" 
                            value={trendlineColor} 
                            onChange={(e) => setTrendlineColor(e.target.value)}
                            className="w-6 h-6 p-0 border-none bg-transparent cursor-pointer"
                          />
                        </div>
                      </div>
                      <div className="space-y-1">
                        <span className="text-[10px] text-slate-400 font-bold uppercase">{t('trendlineWidth')}</span>
                        <input 
                          type="range" min="1" max="5" step="1" 
                          value={trendlineWidth} 
                          onChange={(e) => setTrendlineWidth(Number(e.target.value))}
                          className="w-full accent-emerald-500" 
                        />
                      </div>
                      <div className="space-y-1">
                        <span className="text-[10px] text-slate-400 font-bold uppercase">{t('trendlineStyle')}</span>
                        <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-lg">
                           {(['solid', 'dashed', 'dotted'] as const).map(style => (
                             <button
                                key={style}
                                onClick={() => setTrendlineStyle(style)}
                                className={`flex-1 px-2 py-1 text-[9px] font-bold uppercase rounded transition-all ${trendlineStyle === style ? 'bg-white dark:bg-slate-700 shadow-sm text-emerald-600' : 'text-slate-400'}`}
                             >
                               {t(style)}
                             </button>
                           ))}
                        </div>
                      </div>
                    </div>
                  )}
               </div>
            </div>
          )}

          {/* Export Group */}
          <div className="pt-4 border-t border-slate-100 dark:border-slate-800 grid grid-cols-2 gap-2">
            <button 
              onClick={() => handleDownload('json')}
              className="flex items-center justify-center gap-2 p-2 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-lg text-[10px] font-bold text-slate-600 dark:text-slate-400 transition-colors uppercase"
            >
              <FileJson size={14} />
              JSON
            </button>
            <button 
              onClick={() => handleDownload('png')}
              className="flex items-center justify-center gap-2 p-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-[10px] font-bold transition-colors uppercase shadow-md shadow-emerald-500/20"
            >
              <ImageIcon size={14} />
              PNG
            </button>
          </div>
        </div>
      </div>

      {/* Chart Canvas Area */}
      <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl relative min-h-[400px]">
        {!showConfig && (
            <button 
                onClick={() => setShowConfig(true)}
                className="absolute top-4 left-4 z-10 p-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-emerald-500 hover:scale-105 transition-transform shadow-lg"
            >
                <Settings size={20} />
            </button>
        )}

        <div className="flex-1 p-6 flex flex-col min-h-0" ref={chartRef}>
            <div className="mb-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
               <div>
                  <h2 className="text-lg font-bold text-slate-800 dark:text-white flex items-center gap-2">
                     {chartType === 'bar' ? <BarChart2 size={20} className="text-emerald-500" /> : <ScatterIcon size={20} className="text-emerald-500" />}
                     {tProp(yAxisKey)} vs {chartType === 'bar' ? tProp('牌号') : tProp(xAxisKey)}
                  </h2>
                  <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">{t('chartTitle')}</p>
               </div>
               {groupByKey && (
                 <div className="flex flex-wrap gap-2">
                    {uniqueGroups.map(group => (
                        <div key={group} className="flex items-center gap-1.5 px-2 py-1 bg-slate-50 dark:bg-slate-800 rounded-full border border-slate-100 dark:border-slate-700">
                           <div className="w-2 h-2 rounded-full" style={{ backgroundColor: groupColors[group] }}></div>
                           <span className="text-[10px] font-bold text-slate-600 dark:text-slate-300">{group}</span>
                        </div>
                    ))}
                 </div>
               )}
            </div>

            <div className="flex-1 w-full min-h-0">
                <ResponsiveContainer width="100%" height="100%">
                    {chartType === 'bar' ? (
                        <BarChart data={chartData} margin={{ top: 10, right: 30, left: 0, bottom: 40 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis 
                                dataKey="gradeName" 
                                angle={-45} 
                                textAnchor="end" 
                                interval={0} 
                                height={60} 
                                fontSize={10} 
                                stroke={theme === 'dark' ? '#475569' : '#94a3b8'}
                                tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b' }}
                            />
                            <YAxis 
                                fontSize={10} 
                                stroke={theme === 'dark' ? '#475569' : '#94a3b8'}
                                tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b' }}
                            />
                            <Tooltip 
                                cursor={{ fill: 'rgba(16, 185, 129, 0.05)' }}
                                contentStyle={{ 
                                    backgroundColor: theme === 'dark' ? '#0f172a' : '#ffffff',
                                    borderColor: theme === 'dark' ? '#1e293b' : '#e2e8f0',
                                    borderRadius: '12px',
                                    fontSize: '12px',
                                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)'
                                }}
                            />
                            <Bar dataKey={yAxisKey} radius={[4, 4, 0, 0]} animationDuration={1000}>
                                {chartData.map((entry, index) => (
                                    <Cell 
                                        key={`cell-${index}`} 
                                        fill={groupByKey ? groupColors[String(entry[groupByKey])] : DEFAULT_PALETTE[index % DEFAULT_PALETTE.length]} 
                                    />
                                ))}
                            </Bar>
                        </BarChart>
                    ) : (
                        <ComposedChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis 
                                type="number" 
                                dataKey={xAxisKey} 
                                name={tProp(xAxisKey)} 
                                fontSize={10} 
                                stroke={theme === 'dark' ? '#475569' : '#94a3b8'}
                                tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b' }}
                                label={{ value: tProp(xAxisKey), position: 'bottom', offset: 0, fontSize: 10, fill: '#64748b' }}
                            />
                            <YAxis 
                                type="number" 
                                dataKey={yAxisKey} 
                                name={tProp(yAxisKey)} 
                                fontSize={10} 
                                stroke={theme === 'dark' ? '#475569' : '#94a3b8'}
                                tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b' }}
                                label={{ value: tProp(yAxisKey), angle: -90, position: 'insideLeft', offset: 10, fontSize: 10, fill: '#64748b' }}
                            />
                            <ZAxis range={[60, 400]} />
                            <Tooltip 
                                cursor={{ strokeDasharray: '3 3' }}
                                contentStyle={{ 
                                    backgroundColor: theme === 'dark' ? '#0f172a' : '#ffffff',
                                    borderColor: theme === 'dark' ? '#1e293b' : '#e2e8f0',
                                    borderRadius: '12px',
                                    fontSize: '12px',
                                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)'
                                }}
                                content={({ active, payload }) => {
                                    if (active && payload && payload.length) {
                                        const d = payload[0].payload;
                                        if (d.isTrend) return null;
                                        return (
                                            <div className="p-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-xl">
                                                <p className="font-bold text-slate-800 dark:text-white mb-1">{d.gradeName}</p>
                                                <p className="text-[10px] text-slate-500 dark:text-slate-400 mb-2">{d.manufacturer}</p>
                                                <div className="space-y-1 pt-1 border-t border-slate-100 dark:border-slate-800">
                                                    <p className="text-xs flex justify-between gap-4">
                                                        <span className="text-slate-500">{tProp(xAxisKey)}:</span>
                                                        <span className="font-mono font-bold text-emerald-600">{d[xAxisKey]}</span>
                                                    </p>
                                                    <p className="text-xs flex justify-between gap-4">
                                                        <span className="text-slate-500">{tProp(yAxisKey)}:</span>
                                                        <span className="font-mono font-bold text-blue-600">{d[yAxisKey]}</span>
                                                    </p>
                                                </div>
                                            </div>
                                        );
                                    }
                                    return null;
                                }}
                            />
                            <Scatter 
                                name="Resin Samples" 
                                data={chartData} 
                                animationDuration={1500}
                                animationEasing="ease-in-out"
                            >
                                {chartData.map((entry, index) => (
                                    <Cell 
                                        key={`cell-${index}`} 
                                        fill={groupByKey ? groupColors[String(entry[groupByKey])] : '#10b981'} 
                                        strokeWidth={1}
                                        stroke="#ffffff"
                                        className="hover:scale-125 transition-transform"
                                    />
                                ))}
                            </Scatter>
                            {trendlineSegment && (
                                <Line 
                                    type="monotone" 
                                    data={trendlineSegment} 
                                    dataKey={yAxisKey} 
                                    stroke={trendlineColor} 
                                    strokeWidth={trendlineWidth} 
                                    strokeDasharray={dashArray}
                                    dot={false}
                                    activeDot={false}
                                    legendType="none"
                                />
                            )}
                        </ComposedChart>
                    )}
                </ResponsiveContainer>
            </div>
        </div>
      </div>
    </div>
  );
};

export type Language = 'zh' | 'en';

export interface User {
  id: string;
  name: string;
  email: string;
  role: 'admin' | 'editor' | 'viewer';
  avatar?: string;
}

export interface Category {
  id: string;
  name: string;
  nameEn?: string; // English name for the category
  children?: Category[];
}

export interface PropertyValue {
  value: string | number;
  unit?: string;
}

export interface Product {
  id: string;
  gradeName: string; // 牌号
  manufacturer: string; // 厂家
  description?: string;
  // The core requirement: A product belongs to multiple paths (Category IDs)
  categoryIds: string[]; 
  // Simulating PostgreSQL JSONB for flexible attributes
  properties: Record<string, PropertyValue>;
  updatedAt: string;
}

export type ViewMode = 'grid' | 'chart';

export interface ColumnConfig {
  key: string;
  label: string;
  visible: boolean;
  isSystem?: boolean; // If true, cannot be hidden (e.g., Name)
}

export interface SortConfig {
  key: string;
  direction: 'asc' | 'desc';
}

