}

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const { t, language, toggleLanguage } = useLanguage();
  const { theme, toggleTheme } = useTheme();

  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [username, setUsername] = useState('admin');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('123456');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [rememberMe, setRememberMe] = useState(true);
  const [accounts, setAccounts] = useState<PersistentUser[]>([]);

  // Load existing accounts from localStorage on mount
  useEffect(() => {
    const savedAccounts = localStorage.getItem('resindb-users');
    if (savedAccounts) {
      setAccounts(JSON.parse(savedAccounts));
    } else {
      // Default initial user
      const defaultUser: PersistentUser = {
        id: 'user-001',
        name: 'System Administrator',
        email: 'admin@petrochina.com.cn',
        role: 'admin',
        password: '123456',
        avatar: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=100&h=100&fit=crop'
      };
      setAccounts([defaultUser]);
      localStorage.setItem('resindb-users', JSON.stringify([defaultUser]));
    }
  }, []);

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    setTimeout(() => {
      if (mode === 'login') {
        const found = accounts.find(acc => 
          (acc.name.toLowerCase() === username.toLowerCase() || acc.email.toLowerCase() === username.toLowerCase()) && 
          acc.password === password
        );

        if (found) {
          onLogin(found);
        } else {
          alert('Invalid credentials');
        }
      } else {
        // Register mode
        if (password !== confirmPassword) {
          alert('Passwords do not match');
          setIsLoading(false);
          return;
        }

        const newUser: PersistentUser = {
          id: `user-${Date.now()}`,
          name: username,
          email: email || `${username}@petrochina.com.cn`,
          role: 'editor',
          password: password,
          avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${username}`
        };

        const updated = [...accounts, newUser];
        setAccounts(updated);
        localStorage.setItem('resindb-users', JSON.stringify(updated));

        // Auto login
        onLogin(newUser);
      }
      setIsLoading(false);
    }, 1200);
  };

  const selectAccount = (acc: PersistentUser) => {
    setUsername(acc.email || acc.name);
    setPassword(acc.password || '');
    setMode('login');
  };

  return (
    <div className="min-h-screen flex items-center justify-center relative overflow-hidden bg-slate-50 dark:bg-slate-950 transition-colors duration-500 p-4">

