      <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-500/10 rounded-full blur-[120px] animate-pulse [animation-delay:2s]"></div>

      <div className="z-10 w-full max-w-4xl flex flex-col md:flex-row gap-6 animate-in fade-in zoom-in-95 duration-500">

        {/* Left: Accounts List (Only on Login Mode) */}
        <div className={`hidden md:flex flex-col w-full md:w-72 bg-white/50 dark:bg-slate-900/50 backdrop-blur-xl border border-slate-200 dark:border-slate-800 rounded-3xl p-6 transition-all duration-300 ${mode === 'register' ? 'opacity-30 pointer-events-none grayscale' : ''}`}>
            <h2 className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-6 flex items-center gap-2">
                <User size={14} className="text-emerald-500" />
                {t('availableAccounts')}
            </h2>
            <div className="flex-1 space-y-3 overflow-y-auto custom-scrollbar pr-1">
                {accounts.map(acc => (
                    <button 
