import { useLanguage } from '../contexts/LanguageContext';

interface ProfileModalProps {
  isOpen: boolean;
  onClose: () => void;
  user: UserType | null;
  onSave: (updatedUser: any) => void;
}

export const ProfileModal: React.FC<ProfileModalProps> = ({ isOpen, onClose, user, onSave }) => {
  const { t } = useLanguage();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [avatar, setAvatar] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);

  useEffect(() => {
    if (user && isOpen) {
      setName(user.name);
      setEmail(user.email);
      setAvatar(user.avatar || '');
      // We don't load password for security reasons in real apps, 
      // but in this mock we'll handle it if we need to change it.
      setPassword(''); 
      setShowSuccess(false);
    }
  }, [user, isOpen]);

  if (!isOpen || !user) return null;

  const handleLocalUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        alert("File too large. Please use an image under 2MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setAvatar(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);

    // Simulate API update
    setTimeout(() => {
      const updatedData: any = {
        name,
        email,
        avatar
      };
      if (password) updatedData.password = password;

      onSave(updatedData);
      setIsSaving(false);
      setShowSuccess(true);

      // Auto close after showing success
      setTimeout(() => {
        onClose();
      }, 1500);
    }, 1000);
  };

