                    rows={1}
                />
                <button onClick={handleSendMessage} disabled={(!input.trim() && !attachedImage) || isLoading} className="p-2 bg-slate-900 dark:bg-emerald-600 hover:bg-slate-800 dark:hover:bg-emerald-500 disabled:bg-slate-200 dark:disabled:bg-slate-700 text-white rounded-xl transition-all shrink-0 shadow-md active:scale-95">
                    {isLoading ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />}
                </button>
            </div>
        </div>
      </div>
    </>
  );
};

import React, { useState, useEffect } from 'react';
import { Beaker, Eye, EyeOff, Lock, User, Globe, Moon, Sun, Loader2, ArrowRight, Mail, ShieldCheck, ChevronRight, UserPlus, Trash2 } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import { User as UserType } from '../types';

interface AuthScreenProps {
  onLogin: (user: UserType) => void;
}

interface PersistentUser extends UserType {
  password?: string;
}

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const { t, language, toggleLanguage } = useLanguage();
  const { theme, toggleTheme } = useTheme();

  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [username, setUsername] = useState('admin');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('123456');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [rememberMe, setRememberMe] = useState(true);
  const [accounts, setAccounts] = useState<PersistentUser[]>([]);

  const loadAccounts = () => {
    const savedAccounts = localStorage.getItem('resindb-users');
    if (savedAccounts) {
      setAccounts(JSON.parse(savedAccounts));
    } else {
      const defaultUser: PersistentUser = {
        id: 'user-001',
        name: 'System Administrator',
        email: 'admin@petrochina.com.cn',
        role: 'admin',
        password: '123456',
        avatar: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=100&h=100&fit=crop'
      };
      setAccounts([defaultUser]);
      localStorage.setItem('resindb-users', JSON.stringify([defaultUser]));
    }
  };

  useEffect(() => {
    loadAccounts();
    // Watch for local storage changes (if user registers in another tab, though unlikely here)
    window.addEventListener('storage', loadAccounts);
    return () => window.removeEventListener('storage', loadAccounts);
  }, []);

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    setTimeout(() => {
      if (mode === 'login') {
        const found = accounts.find(acc => 
          (acc.name.toLowerCase() === username.toLowerCase() || acc.email.toLowerCase() === username.toLowerCase()) && 
          acc.password === password
        );

        if (found) {
          onLogin(found);
        } else {
          alert('Invalid credentials. Please check your username and password.');
        }
      } else {
        if (password !== confirmPassword) {
          alert('Passwords do not match');
          setIsLoading(false);
          return;
        }

        const newUser: PersistentUser = {
          id: `user-${Date.now()}`,
          name: username,
          email: email || `${username}@petrochina.com.cn`,
          role: 'editor',
          password: password,
          avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${username}`
        };

        const updated = [...accounts, newUser];
        setAccounts(updated);
        localStorage.setItem('resindb-users', JSON.stringify(updated));
        onLogin(newUser);
      }
      setIsLoading(false);
    }, 1200);
  };

  const removeAccount = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (id === 'user-001') {
        alert("Primary admin account cannot be removed.");
        return;
    }
    const updated = accounts.filter(acc => acc.id !== id);
    setAccounts(updated);
    localStorage.setItem('resindb-users', JSON.stringify(updated));
  };

  const selectAccount = (acc: PersistentUser) => {
    setUsername(acc.email || acc.name);
    setPassword(acc.password || '');
    setMode('login');
  };

  return (
    <div className="min-h-screen flex items-center justify-center relative overflow-hidden bg-slate-50 dark:bg-slate-950 transition-colors duration-500 p-4">
      <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-emerald-500/10 rounded-full blur-[120px] animate-pulse"></div>
      <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-500/10 rounded-full blur-[120px] animate-pulse [animation-delay:2s]"></div>

      <div className="z-10 w-full max-w-4xl flex flex-col md:flex-row gap-6 animate-in fade-in zoom-in-95 duration-500">
        <div className={`hidden md:flex flex-col w-full md:w-72 bg-white/50 dark:bg-slate-900/50 backdrop-blur-xl border border-slate-200 dark:border-slate-800 rounded-3xl p-6 transition-all duration-300 ${mode === 'register' ? 'opacity-30 pointer-events-none grayscale' : ''}`}>
            <h2 className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-6 flex items-center gap-2">
                <User size={14} className="text-emerald-500" />
                {t('availableAccounts')}
            </h2>
            <div className="flex-1 space-y-3 overflow-y-auto custom-scrollbar pr-1">
                {accounts.map(acc => (
                    <div key={acc.id} className="group relative">
                        <button 
                            onClick={() => selectAccount(acc)}
                            className={`w-full flex items-center gap-3 p-2 rounded-2xl hover:bg-white dark:hover:bg-slate-800 transition-all border border-transparent hover:border-slate-100 dark:hover:border-slate-700 text-left ${username === (acc.email || acc.name) ? 'bg-emerald-50/50 dark:bg-emerald-900/10 border-emerald-100/50 dark:border-emerald-900/30' : ''}`}
                        >
                            <div className="w-10 h-10 rounded-xl overflow-hidden shadow-sm border border-slate-200 dark:border-slate-700 shrink-0">
                                <img src={acc.avatar} alt={acc.name} className="w-full h-full object-cover" />
                            </div>
                            <div className="flex-1 overflow-hidden">
                                <p className="text-xs font-bold text-slate-900 dark:text-slate-100 truncate">{acc.name}</p>
                                <p className="text-[10px] text-slate-500 truncate">{acc.email}</p>
                            </div>
                            <ChevronRight size={14} className={`text-slate-300 transition-all ${username === (acc.email || acc.name) ? 'opacity-100 text-emerald-500' : 'opacity-0 group-hover:opacity-100'}`} />
                        </button>
                        <button 
                            onClick={(e) => removeAccount(e, acc.id)}
                            className="absolute -top-1 -right-1 p-1.5 bg-white dark:bg-slate-800 rounded-lg text-slate-300 hover:text-rose-500 shadow-sm border border-slate-100 dark:border-slate-700 opacity-0 group-hover:opacity-100 transition-all"
                        >
                            <Trash2 size={10} />
                        </button>
                    </div>
                ))}
            </div>
            <button 
                onClick={() => setMode('register')}
                className="mt-6 w-full flex items-center justify-center gap-2 p-3 bg-white dark:bg-slate-800 hover:bg-emerald-50 dark:hover:bg-emerald-900/20 text-slate-600 dark:text-slate-400 hover:text-emerald-600 rounded-2xl text-[10px] font-bold uppercase tracking-widest transition-all border border-slate-100 dark:border-slate-700 shadow-sm"
            >
                <UserPlus size={14} />
                {t('signUp')}
            </button>
        </div>

        <div className="flex-1 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl shadow-2xl overflow-hidden flex flex-col">
          <div className="p-8 pb-4 text-center">
            <div className="inline-flex p-3 bg-emerald-600 rounded-2xl shadow-xl shadow-emerald-500/20 mb-6">
              <Beaker size={32} className="text-white" />
            </div>
            <h1 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight leading-none mb-2">
              {mode === 'login' ? t('loginTitle') : t('registerTitle')}
            </h1>
            <p className="text-sm text-slate-500 dark:text-slate-400 font-medium">
              {mode === 'login' ? t('loginSubtitle') : t('registerSubtitle')}
            </p>
          </div>

          <form onSubmit={handleAuth} className="p-8 pt-4 space-y-5">
            <div className="space-y-1.5">
              <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest ml-1">{t('username')}</label>
              <div className="relative group">
                <User size={18} className="absolute left-3.5 top-3 text-slate-400 group-focus-within:text-emerald-500 transition-colors" />
                <input
                  type="text" required value={username} onChange={(e) => setUsername(e.target.value)}
                  className="block w-full pl-11 pr-4 py-3 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 focus:border-emerald-500 rounded-xl text-sm transition-all outline-none focus:ring-4 focus:ring-emerald-500/10 dark:text-slate-200"
                  placeholder={mode === 'login' ? "Username or Email" : "Your Name"}
                />
              </div>
            </div>

            {mode === 'register' && (
                <div className="space-y-1.5 animate-in fade-in slide-in-from-top-2">
                    <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest ml-1">{t('email')}</label>
                    <div className="relative group">
                        <Mail size={18} className="absolute left-3.5 top-3 text-slate-400 group-focus-within:text-emerald-500 transition-colors" />
                        <input
                            type="email" required value={email} onChange={(e) => setEmail(e.target.value)}
                            className="block w-full pl-11 pr-4 py-3 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 focus:border-emerald-500 rounded-xl text-sm outline-none focus:ring-4 focus:ring-emerald-500/10 dark:text-slate-200"
                            placeholder="your@email.com"
                        />
                    </div>
                </div>
            )}

            <div className="space-y-1.5">
              <div className="flex justify-between items-center ml-1">
                <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest">{t('password')}</label>
                {mode === 'login' && (
                    <button type="button" className="text-[10px] font-bold text-emerald-600 hover:text-emerald-500 uppercase tracking-wider">{t('forgotPassword')}</button>
                )}
              </div>
              <div className="relative group">
                <Lock size={18} className="absolute left-3.5 top-3 text-slate-400 group-focus-within:text-emerald-500 transition-colors" />
                <input
                  type={showPassword ? 'text' : 'password'} required value={password} onChange={(e) => setPassword(e.target.value)}
                  className="block w-full pl-11 pr-12 py-3 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 focus:border-emerald-500 rounded-xl text-sm outline-none focus:ring-4 focus:ring-emerald-500/10 dark:text-slate-200"
                  placeholder="••••••••"
                />
                <button
                  type="button" onClick={() => setShowPassword(!showPassword)}
                  className="absolute inset-y-0 right-0 pr-3.5 flex items-center text-slate-400 hover:text-slate-600 transition-colors"
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>

            {mode === 'register' && (
                <div className="space-y-1.5 animate-in fade-in slide-in-from-top-2">
                    <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest ml-1">{t('confirmPassword')}</label>
                    <div className="relative group">
                        <ShieldCheck size={18} className="absolute left-3.5 top-3 text-slate-400 group-focus-within:text-emerald-500 transition-colors" />
                        <input
                            type={showPassword ? 'text' : 'password'} required value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)}
                            className="block w-full pl-11 pr-12 py-3 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 focus:border-emerald-500 rounded-xl text-sm outline-none focus:ring-4 focus:ring-emerald-500/10 dark:text-slate-200"
                            placeholder="••••••••"
                        />
                    </div>
                </div>
            )}

            <div className="flex items-center justify-between gap-4">
                <label className="flex items-center gap-3 cursor-pointer group select-none">
                    <div className={`w-5 h-5 rounded-md border-2 transition-all flex items-center justify-center ${rememberMe ? 'bg-emerald-600 border-emerald-600' : 'border-slate-200 dark:border-slate-700 group-hover:border-emerald-400'}`}>
                    {rememberMe && <div className="w-1.5 h-1.5 bg-white rounded-full"></div>}
                    <input type="checkbox" checked={rememberMe} onChange={() => setRememberMe(!rememberMe)} className="hidden" />
                    </div>
                    <span className="text-xs font-medium text-slate-600 dark:text-slate-400">{t('rememberMe')}</span>
                </label>
                <button type="button" onClick={() => setMode(mode === 'login' ? 'register' : 'login')} className="text-xs font-bold text-emerald-600 hover:text-emerald-500">
                    {mode === 'login' ? t('noAccount') : t('haveAccount')}
                </button>
            </div>

            <button
              type="submit" disabled={isLoading}
              className="w-full flex items-center justify-center gap-2 py-3.5 px-4 bg-slate-900 dark:bg-emerald-600 hover:bg-slate-800 dark:hover:bg-emerald-500 text-white rounded-2xl font-bold text-sm transition-all shadow-xl shadow-slate-900/10 dark:shadow-emerald-500/20 active:scale-[0.98] disabled:opacity-70"
            >
              {isLoading ? <Loader2 size={20} className="animate-spin" /> : <>{mode === 'login' ? t('signIn') : t('signUp')}<ArrowRight size={18} /></>}
            </button>
          </form>

          <div className="px-8 py-6 bg-slate-50 dark:bg-slate-950/50 border-t border-slate-100 dark:border-slate-800 flex justify-center gap-4 mt-auto">
            <button onClick={toggleLanguage} className="flex items-center gap-2 text-[10px] font-bold text-slate-500 dark:text-slate-400 hover:text-emerald-600 uppercase tracking-widest transition-colors">
              <Globe size={14} /> {language === 'zh' ? 'English' : '中文'}
            </button>
            <div className="w-px h-3 bg-slate-200 dark:bg-slate-800 mt-1"></div>
            <button onClick={toggleTheme} className="flex items-center gap-2 text-[10px] font-bold text-slate-500 dark:text-slate-400 hover:text-amber-500 uppercase tracking-widest transition-colors">
              {theme === 'dark' ? <Sun size={14} /> : <Moon size={14} />} {theme === 'dark' ? 'Light' : 'Dark'}
            </button>
          </div>
        </div>
      </div>
      <p className="absolute bottom-6 text-center text-[10px] text-slate-400 dark:text-slate-600 font-bold tracking-widest uppercase">
        © 2024 Petrochemical Research Institute • ResinDB Pro System
      </p>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { X, Save, User, Mail, Lock, Camera, CheckCircle2, Loader2, ShieldCheck, Trash2, RotateCcw } from 'lucide-react';
import { User as UserType } from '../types';
import { useLanguage } from '../contexts/LanguageContext';

interface ProfileModalProps {
  isOpen: boolean;
  onClose: () => void;
  user: UserType | null;
  onSave: (updatedUser: any) => void;
}

export const ProfileModal: React.FC<ProfileModalProps> = ({ isOpen, onClose, user, onSave }) => {
  const { t } = useLanguage();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [avatar, setAvatar] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);

  useEffect(() => {
    if (user && isOpen) {
      setName(user.name);
      setEmail(user.email);
      setAvatar(user.avatar || '');
      setPassword(''); 
      setShowSuccess(false);
    }
  }, [user, isOpen]);

  if (!isOpen || !user) return null;

  const handleLocalUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        alert("File too large. Please use an image under 2MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setAvatar(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const resetToDefault = () => {
    setAvatar(`https://api.dicebear.com/7.x/avataaars/svg?seed=${name}`);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);

    setTimeout(() => {
      const updatedData: any = {
        name,
        email,
        avatar
      };
      if (password) updatedData.password = password;

      onSave(updatedData);
      setIsSaving(false);
      setShowSuccess(true);

      setTimeout(() => {
        onClose();
      }, 1500);
    }, 1000);
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-in fade-in duration-300">
      <div className="w-full max-w-lg bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300">
        <div className="px-6 py-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50/50 dark:bg-slate-950/50">
          <div className="flex items-center gap-3">
             <div className="p-2 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 rounded-xl">
                <User size={20} />
             </div>
             <h3 className="text-lg font-bold text-slate-900 dark:text-white">{t('editProfile')}</h3>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200">
            <X size={20} />
          </button>
        </div>

        {showSuccess ? (
            <div className="p-12 flex flex-col items-center justify-center text-center animate-in fade-in zoom-in-95">
                <div className="w-20 h-20 bg-emerald-100 dark:bg-emerald-900/40 text-emerald-600 dark:text-emerald-400 rounded-full flex items-center justify-center mb-6 shadow-lg shadow-emerald-500/20">
                    <CheckCircle2 size={40} />
                </div>
                <h4 className="text-xl font-bold text-slate-900 dark:text-white mb-2">{t('updateSuccess')}</h4>
                <p className="text-sm text-slate-500 dark:text-slate-400">Security protocols updated successfully.</p>
            </div>
        ) : (
            <form onSubmit={handleSubmit} className="p-8 space-y-6">
                <div className="flex flex-col items-center gap-6 mb-2">
                    <div className="relative group">
                        <div 
                          className="w-28 h-28 rounded-[2rem] overflow-hidden border-4 border-white dark:border-slate-800 shadow-2xl group-hover:scale-105 transition-all duration-300 cursor-pointer"
                          onClick={() => fileInputRef.current?.click()}
                        >
                            <img src={avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${name}`} alt="Preview" className="w-full h-full object-cover" />
                        </div>
                        <div className="absolute -bottom-2 flex gap-1 left-1/2 -translate-x-1/2">
                            <button 
                              type="button" onClick={() => fileInputRef.current?.click()}
                              className="p-2 bg-emerald-600 text-white rounded-xl shadow-lg hover:bg-emerald-500 active:scale-90 transition-all border-2 border-white dark:border-slate-900"
                              title={t('changeAvatar')}
                            >
                              <Camera size={16} />
                            </button>
                            <button 
                              type="button" onClick={resetToDefault}
                              className="p-2 bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 rounded-xl shadow-lg hover:bg-slate-200 active:scale-90 transition-all border-2 border-white dark:border-slate-900"
                              title="Reset to default"
                            >
                              <RotateCcw size={16} />
                            </button>
                        </div>
                        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleLocalUpload} />
                    </div>
                    <div className="w-full space-y-1">
                      <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">{t('avatarUrl')}</label>
                      <input 
                          type="text" value={avatar.startsWith('data:') ? 'Local Image Attached (Base64)' : avatar}
                          onChange={(e) => setAvatar(e.target.value)}
                          className={`w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-xs font-mono outline-none focus:border-emerald-500 transition-all dark:text-slate-200 ${avatar.startsWith('data:') ? 'italic text-emerald-600 dark:text-emerald-400' : ''}`}
                          placeholder="Or paste an image URL..."
                      />
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                    <div className="space-y-1.5">
                        <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">{t('username')}</label>
                        <div className="relative group">
                            <User size={16} className="absolute left-3.5 top-3 text-slate-400 group-focus-within:text-emerald-500 transition-colors" />
                            <input 
                                type="text" required value={name} onChange={(e) => setName(e.target.value)}
                                className="w-full pl-11 pr-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none focus:border-emerald-500 transition-all dark:text-slate-200"
                            />
                        </div>
                    </div>
                    <div className="space-y-1.5">
                        <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">{t('email')}</label>
                        <div className="relative group">
                            <Mail size={16} className="absolute left-3.5 top-3 text-slate-400 group-focus-within:text-emerald-500 transition-colors" />
                            <input 
                                type="email" required value={email} onChange={(e) => setEmail(e.target.value)}
                                className="w-full pl-11 pr-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none focus:border-emerald-500 transition-all dark:text-slate-200"
                            />
                        </div>
                    </div>
                </div>

                <div className="space-y-1.5 pt-2 border-t border-slate-100 dark:border-slate-800">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">{t('password')} (Optional Change)</label>
                    <div className="relative group">
                        <Lock size={16} className="absolute left-3.5 top-3 text-slate-400 group-focus-within:text-emerald-500 transition-colors" />
                        <input 
                            type="password" value={password} onChange={(e) => setPassword(e.target.value)}
                            placeholder="Keep empty if not changing"
                            className="w-full pl-11 pr-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none focus:border-emerald-500 transition-all dark:text-slate-200"
                        />
                    </div>
                </div>

                <div className="flex items-center justify-between px-4 py-3 bg-slate-100 dark:bg-slate-800/50 rounded-2xl border border-slate-200 dark:border-slate-700">
                    <div className="flex items-center gap-2">
                        <ShieldCheck size={16} className="text-emerald-500" />
                        <span className="text-xs font-bold text-slate-500 uppercase tracking-widest">Active Role</span>
                    </div>
                    <span className="text-[10px] font-bold text-emerald-600 dark:text-emerald-400 uppercase tracking-widest bg-emerald-50 dark:bg-emerald-900/20 px-2.5 py-1 rounded-lg border border-emerald-200 dark:border-emerald-800/50">
                        {user.role}
                    </span>
                </div>

                <div className="flex gap-4 pt-4">
                    <button type="button" onClick={onClose} className="flex-1 py-3 text-sm font-bold text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-2xl transition-all">{t('cancel')}</button>
                    <button 
                        type="submit" disabled={isSaving}
                        className="flex-[2] py-3 bg-emerald-600 hover:bg-emerald-500 text-white rounded-2xl font-bold text-sm shadow-xl shadow-emerald-500/20 active:scale-95 disabled:opacity-70 flex items-center justify-center gap-2"
                    >
                        {isSaving ? <Loader2 size={20} className="animate-spin" /> : <><Save size={20} />{t('save')}</>}
                    </button>
                </div>
            </form>
        )}
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  ReferenceLine,
  Cell,
  LabelList,
  Line,
  ComposedChart,
  ZAxis
} from 'recharts';
import { Settings, Download, ChevronUp, ChevronDown, BarChart2, ScatterChart as ScatterIcon, TrendingUp, Palette, PaintBucket, FileJson, FileType, Image as ImageIcon, RotateCcw, LayoutDashboard } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

const DEFAULT_PALETTE = [
  '#10b981', // Emerald
  '#3b82f6', // Blue
  '#f59e0b', // Amber
  '#ef4444', // Red
  '#8b5cf6', // Violet
  '#ec4899', // Pink
  '#06b6d4', // Cyan
  '#84cc16', // Lime
  '#f97316', // Orange
  '#6366f1', // Indigo
];

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const { t, tProp } = useLanguage();
  const { theme } = useTheme();
  const chartRef = useRef<HTMLDivElement>(null);

  const [showConfig, setShowConfig] = useState(true);
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('gradeName');
  const [yAxisKey, setYAxisKey] = useState<string>('');

  // Manual Axis Limits
  const [xMin, setXMin] = useState<number | ''>('');
  const [xMax, setXMax] = useState<number | ''>('');
  const [yMin, setYMin] = useState<number | ''>('');
  const [yMax, setYMax] = useState<number | ''>('');

  // Trendline State
  const [showTrendline, setShowTrendline] = useState(false);
  const [trendlineColor, setTrendlineColor] = useState('#ef4444');
  const [trendlineWidth, setTrendlineWidth] = useState(2);
  const [trendlineStyle, setTrendlineStyle] = useState<'solid' | 'dashed' | 'dotted'>('dashed');

  // Scatter Plot Grouping State
  const [groupByKey, setGroupByKey] = useState<string>('');
  const [groupColors, setGroupColors] = useState<Record<string, string>>({});

  // 1. Identify Numeric Keys (for Axes)
  const numericKeys = useMemo(() => {
     const keys = new Set<string>();
     data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
           if (typeof v.value === 'number') {
               keys.add(k);
           } else if (!isNaN(Number(v.value)) && v.value !== '') {
               keys.add(k);
           }
        });
     });
     return Array.from(keys).sort();
  }, [data]);

  // 2. Identify Categorical Keys (for Grouping)
  const categoricalKeys = useMemo(() => {
    const keys = new Set<string>(['manufacturer']); // Always available
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (typeof v.value === 'string' && isNaN(Number(v.value))) {
                keys.add(k);
            }
        });
    });
    return Array.from(keys).sort();
  }, [data]);

  useEffect(() => {
      if (!yAxisKey && numericKeys.length > 0) {
          const preferred = ['密度', '熔体流动速率', '拉伸强度'].find(k => numericKeys.includes(k));
          setYAxisKey(preferred || numericKeys[0]);
      }
  }, [numericKeys, yAxisKey]);

  useEffect(() => {
    setXMin('');
    setXMax('');
  }, [xAxisKey]);

  useEffect(() => {
    setYMin('');
    setYMax('');
  }, [yAxisKey]);

  // 3. Prepare Chart Data
  const chartData = useMemo(() => {
    return data.map(p => {
        const item: any = {
            id: p.id,
            gradeName: p.gradeName,
            manufacturer: p.manufacturer,
            tooltipTitle: `${p.manufacturer} - ${p.gradeName}`
        };

        Object.entries(p.properties).forEach(([k, v]) => {
            const num = Number(v.value);
            if (!isNaN(num) && v.value !== '') {
                item[k] = num;
            } else {
                item[k] = v.value;
            }
        });
        return item;
    });
  }, [data]);

  // 4. Calculate Linear Regression for Trendline
  const trendlineSegment = useMemo(() => {
    if (!showTrendline || chartType !== 'scatter') return null;

    const validPoints = chartData.filter(d => 
        typeof d[xAxisKey] === 'number' && 
        typeof d[yAxisKey] === 'number'
    );

    if (validPoints.length < 2) return null;

    const n = validPoints.length;
    let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
    let minX = Infinity, maxX = -Infinity;

    validPoints.forEach(p => {
        const x = p[xAxisKey];
        const y = p[yAxisKey];
        sumX += x;
        sumY += y;
        sumXY += x * y;
        sumX2 += x * x;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
    });

    const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
    const intercept = (sumY - slope * sumX) / n;

    return [
        { [xAxisKey]: minX, [yAxisKey]: slope * minX + intercept, isTrend: true },
        { [xAxisKey]: maxX, [yAxisKey]: slope * maxX + intercept, isTrend: true }
    ];
  }, [chartData, xAxisKey, yAxisKey, showTrendline, chartType]);

  const dashArray = useMemo(() => {
    if (trendlineStyle === 'dashed') return '5 5';
    if (trendlineStyle === 'dotted') return '2 2';
    return '0';
  }, [trendlineStyle]);

  // 5. Determine Unique Groups
  const uniqueGroups = useMemo(() => {
    if (!groupByKey) return [];
    const groups = new Set<string>();
    chartData.forEach((item: any) => {
        const val = item[groupByKey];
        if (val !== undefined && val !== null && val !== '') {
            groups.add(String(val));
        } else {
            groups.add('Unknown');
        }
    });
    return Array.from(groups).sort();
  }, [groupByKey, chartData]);

  useEffect(() => {
    if (uniqueGroups.length > 0) {
        setGroupColors(prev => {
            const next = { ...prev };
            uniqueGroups.forEach((group, index) => {
                if (!next[group]) {
                    next[group] = DEFAULT_PALETTE[index % DEFAULT_PALETTE.length];
                }
            });
            return next;
        });
    }
  }, [uniqueGroups]);

  const handleDownload = async (type: 'json' | 'csv' | 'png') => {
    if (type === 'json') {
        const jsonString = JSON.stringify(chartData, null, 2);
        const blob = new Blob([jsonString], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_data.json';
        a.click();
    } else if (type === 'csv') {
        const headers = ['Grade', 'Manufacturer', ...numericKeys];
        const rows = chartData.map((row: any) => [
            row.gradeName,
            row.manufacturer,
            ...numericKeys.map(k => row[k] ?? '')
        ]);
        const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
        const blob = new Blob([csvContent], { type: 'text/csv' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_data.csv';
        a.click();
    } else if (type === 'png' && chartRef.current) {
        const canvas = await html2canvas(chartRef.current, {
            backgroundColor: theme === 'dark' ? '#020617' : '#ffffff'
        });
        const url = canvas.toDataURL('image/png');
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_chart.png';
        a.click();
    }
  };

  const CustomTooltipContent = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const d = payload[0].payload;
      if (d.isTrend) return null;

      const product = data.find(p => p.id === d.id);
      if (!product) return null;

      // Prioritize properties not already displayed
      const additionalProps = Object.entries(product.properties)
        .filter(([k]) => k !== xAxisKey && k !== yAxisKey && k !== groupByKey)
        .slice(0, 3);

      return (
        <div className="p-4 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-2xl min-w-[200px] animate-in fade-in zoom-in-95 duration-200">
          <div className="flex items-center justify-between gap-4 mb-1">
            <p className="font-bold text-slate-800 dark:text-white truncate text-sm">{product.gradeName}</p>
            {groupByKey && d[groupByKey] && (
               <span className="text-[9px] px-2 py-0.5 rounded-full bg-emerald-50 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 font-bold border border-emerald-100 dark:border-emerald-800/50">
                  {d[groupByKey]}
               </span>
            )}
          </div>
          <p className="text-[10px] text-slate-500 dark:text-slate-400 mb-3">{product.manufacturer}</p>

          <div className="space-y-1.5 pt-2 border-t border-slate-100 dark:border-slate-800">
             {chartType === 'scatter' ? (
               <>
                 <p className="text-xs flex justify-between gap-4">
                    <span className="text-slate-500">{tProp(xAxisKey)}:</span>
                    <span className="font-mono font-bold text-emerald-600">
                        {product.properties[xAxisKey]?.value ?? d[xAxisKey]}
                        {product.properties[xAxisKey]?.unit ? ` ${product.properties[xAxisKey].unit}` : ''}
                    </span>
                 </p>
                 <p className="text-xs flex justify-between gap-4">
                    <span className="text-slate-500">{tProp(yAxisKey)}:</span>
                    <span className="font-mono font-bold text-blue-600">
                        {product.properties[yAxisKey]?.value ?? d[yAxisKey]}
                        {product.properties[yAxisKey]?.unit ? ` ${product.properties[yAxisKey].unit}` : ''}
                    </span>
                 </p>
               </>
             ) : (
               <p className="text-xs flex justify-between gap-4">
                  <span className="text-slate-500">{tProp(yAxisKey)}:</span>
                  <span className="font-mono font-bold text-emerald-600">
                      {product.properties[yAxisKey]?.value ?? d[yAxisKey]}
                      {product.properties[yAxisKey]?.unit ? ` ${product.properties[yAxisKey].unit}` : ''}
                  </span>
               </p>
             )}
          </div>

          {additionalProps.length > 0 && (
            <div className="mt-3 pt-3 border-t border-slate-100 dark:border-slate-800 space-y-1.5">
              <p className="text-[9px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1">{t('details')}</p>
              {additionalProps.map(([key, prop]) => (
                <p key={key} className="text-[11px] flex justify-between gap-4 text-slate-600 dark:text-slate-300">
                  <span className="opacity-70 truncate max-w-[110px]">{tProp(key)}:</span>
                  <span className="font-medium whitespace-nowrap">
                    {prop.value}
                    {prop.unit ? ` ${prop.unit}` : ''}
                  </span>
                </p>
              ))}
            </div>
          )}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="flex flex-col md:flex-row h-full gap-4 overflow-hidden">
      {/* Settings Panel */}
      <div className={`flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl transition-all duration-300 overflow-hidden shrink-0 ${showConfig ? 'w-full md:w-80 opacity-100' : 'w-0 opacity-0 overflow-hidden md:border-none'}`}>
        <div className="p-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-950/50">
          <div className="flex items-center gap-2 font-bold text-sm text-slate-700 dark:text-slate-200 uppercase tracking-wider">
            <Settings size={16} className="text-emerald-500" />
            {t('chartConfig')}
          </div>
          <button onClick={() => setShowConfig(false)} className="md:hidden text-slate-400 hover:text-slate-600 dark:hover:text-slate-300">
            <ChevronUp size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-5 custom-scrollbar space-y-6">
          {/* Chart Type Selection */}
          <div className="space-y-3">
             <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <LayoutDashboard size={12} />
                {t('chartType')}
             </label>
             <div className="flex gap-2">
                <button 
                  onClick={() => setChartType('bar')}
                  className={`flex-1 flex flex-col items-center gap-2 p-3 rounded-xl border-2 transition-all ${chartType === 'bar' ? 'border-emerald-500 bg-emerald-50/50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 shadow-md shadow-emerald-500/10' : 'border-slate-100 dark:border-slate-800 text-slate-400 hover:border-slate-200 dark:hover:border-slate-700'}`}
                >
                  <BarChart2 size={24} />
                  <span className="text-[10px] font-bold uppercase">{t('barChart')}</span>
                </button>
                <button 
                  onClick={() => setChartType('scatter')}
                  className={`flex-1 flex flex-col items-center gap-2 p-3 rounded-xl border-2 transition-all ${chartType === 'scatter' ? 'border-emerald-500 bg-emerald-50/50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 shadow-md shadow-emerald-500/10' : 'border-slate-100 dark:border-slate-800 text-slate-400 hover:border-slate-200 dark:hover:border-slate-700'}`}
                >
                  <ScatterIcon size={24} />
                  <span className="text-[10px] font-bold uppercase">{t('scatterChart')}</span>
                </button>
             </div>
          </div>

          {/* Axis Mapping */}
          <div className="space-y-4">
            <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <RotateCcw size={12} />
                {t('axisMapping')}
            </label>
            <div className="space-y-3">
              <div className="space-y-1.5">
                <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('xAxis')}</span>
                <select 
                  value={xAxisKey} 
                  onChange={(e) => setXAxisKey(e.target.value)}
                  className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 outline-none transition-all"
                >
                  {chartType === 'bar' && <option value="gradeName">{tProp('牌号')}</option>}
                  {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                </select>
              </div>
              <div className="space-y-1.5">
                <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('yAxis')}</span>
                <select 
                  value={yAxisKey} 
                  onChange={(e) => setYAxisKey(e.target.value)}
                  className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 outline-none transition-all"
                >
                  {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                </select>
              </div>
            </div>
          </div>

          {/* Color & Grouping */}
          <div className="space-y-4 pt-2 border-t border-slate-100 dark:border-slate-800">
             <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <Palette size={12} />
                {t('styleGrouping')}
             </label>
             <div className="space-y-1.5">
               <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('groupBy')}</span>
               <select 
                 value={groupByKey} 
                 onChange={(e) => setGroupByKey(e.target.value)}
                 className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 outline-none transition-all"
               >
                 <option value="">{t('none')}</option>
                 {categoricalKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
               </select>
             </div>
          </div>

          {/* Trendline Settings (Scatter only) */}
          {chartType === 'scatter' && (
            <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
               <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                  <TrendingUp size={12} />
                  {t('trendline')}
               </label>
               <div className="space-y-3">
                  <label className="flex items-center gap-3 cursor-pointer group">
                      <div className={`w-8 h-4 rounded-full relative transition-colors ${showTrendline ? 'bg-emerald-500' : 'bg-slate-200 dark:bg-slate-700'}`}>
                          <div className={`absolute top-0.5 w-3 h-3 bg-white rounded-full transition-transform ${showTrendline ? 'left-4.5 translate-x-4' : 'left-0.5'}`}></div>
                          <input type="checkbox" checked={showTrendline} onChange={() => setShowTrendline(!showTrendline)} className="hidden" />
                      </div>
                      <span className="text-sm text-slate-600 dark:text-slate-300">{t('showTrendline')}</span>
                  </label>

                  {showTrendline && (
                    <div className="space-y-3 pl-2 animate-in fade-in slide-in-from-top-1">
                      <div className="space-y-1">
                        <span className="text-[10px] text-slate-400 font-bold uppercase">{t('trendlineColor')}</span>
                        <div className="flex gap-2 flex-wrap">
                          {['#ef4444', '#f59e0b', '#10b981', '#3b82f6', '#8b5cf6'].map(c => (
                            <button 
                              key={c} 
                              onClick={() => setTrendlineColor(c)}
                              className={`w-6 h-6 rounded-full border-2 ${trendlineColor === c ? 'border-white ring-2 ring-emerald-500' : 'border-transparent'}`}
                              style={{ backgroundColor: c }}
                            />
                          ))}
                          <input 
                            type="color" 
                            value={trendlineColor} 
                            onChange={(e) => setTrendlineColor(e.target.value)}
                            className="w-6 h-6 p-0 border-none bg-transparent cursor-pointer"
                          />
                        </div>
                      </div>
                      <div className="space-y-1">
                        <span className="text-[10px] text-slate-400 font-bold uppercase">{t('trendlineWidth')}</span>
                        <input 
                          type="range" min="1" max="5" step="1" 
                          value={trendlineWidth} 
                          onChange={(e) => setTrendlineWidth(Number(e.target.value))}
                          className="w-full accent-emerald-500" 
                        />
                      </div>
                      <div className="space-y-1">
                        <span className="text-[10px] text-slate-400 font-bold uppercase">{t('trendlineStyle')}</span>
                        <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-lg">
                           {(['solid', 'dashed', 'dotted'] as const).map(style => (
                             <button
                                key={style}
                                onClick={() => setTrendlineStyle(style)}
                                className={`flex-1 px-2 py-1 text-[9px] font-bold uppercase rounded transition-all ${trendlineStyle === style ? 'bg-white dark:bg-slate-700 shadow-sm text-emerald-600' : 'text-slate-400'}`}
                             >
                               {t(style)}
                             </button>
                           ))}
                        </div>
                      </div>
                    </div>
                  )}
               </div>
            </div>
          )}

          {/* Export Group */}
          <div className="pt-4 border-t border-slate-100 dark:border-slate-800 grid grid-cols-2 gap-2">
            <button 
              onClick={() => handleDownload('json')}
              className="flex items-center justify-center gap-2 p-2 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-lg text-[10px] font-bold text-slate-600 dark:text-slate-400 transition-colors uppercase"
            >
              <FileJson size={14} />
              JSON
            </button>
            <button 
              onClick={() => handleDownload('png')}
              className="flex items-center justify-center gap-2 p-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-[10px] font-bold transition-colors uppercase shadow-md shadow-emerald-500/20"
            >
              <ImageIcon size={14} />
              PNG
            </button>
          </div>
        </div>
      </div>

      {/* Chart Canvas Area */}
      <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl relative min-h-[400px]">
        {!showConfig && (
            <button 
                onClick={() => setShowConfig(true)}
                className="absolute top-4 left-4 z-10 p-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-emerald-500 hover:scale-105 transition-transform shadow-lg"
            >
                <Settings size={20} />
            </button>
        )}

        <div className="flex-1 p-6 flex flex-col min-h-0" ref={chartRef}>
            <div className="mb-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
               <div>
                  <h2 className="text-lg font-bold text-slate-800 dark:text-white flex items-center gap-2">
                     {chartType === 'bar' ? <BarChart2 size={20} className="text-emerald-500" /> : <ScatterIcon size={20} className="text-emerald-500" />}
                     {tProp(yAxisKey)} vs {chartType === 'bar' ? tProp('牌号') : tProp(xAxisKey)}
                  </h2>
                  <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">{t('chartTitle')}</p>
               </div>
               {groupByKey && (
                 <div className="flex flex-wrap gap-2">
                    {uniqueGroups.map(group => (
                        <div key={group} className="flex items-center gap-1.5 px-2 py-1 bg-slate-50 dark:bg-slate-800 rounded-full border border-slate-100 dark:border-slate-700">
                           <div className="w-2 h-2 rounded-full" style={{ backgroundColor: groupColors[group] }}></div>
                           <span className="text-[10px] font-bold text-slate-600 dark:text-slate-300">{group}</span>
                        </div>
                    ))}
                 </div>
               )}
            </div>

            <div className="flex-1 w-full min-h-0">
                <ResponsiveContainer width="100%" height="100%">
                    {chartType === 'bar' ? (
                        <BarChart data={chartData} margin={{ top: 10, right: 30, left: 0, bottom: 40 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis 
                                dataKey="gradeName" 
                                angle={-45} 
                                textAnchor="end" 
                                interval={0} 
                                height={60} 
                                fontSize={10} 
                                stroke={theme === 'dark' ? '#475569' : '#94a3b8'}
                                tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b' }}
                            />
                            <YAxis 
                                fontSize={10} 
                                stroke={theme === 'dark' ? '#475569' : '#94a3b8'}
                                tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b' }}
                            />
                            <Tooltip 
                                cursor={{ fill: 'rgba(16, 185, 129, 0.05)' }}
                                content={<CustomTooltipContent />}
                            />
                            <Bar dataKey={yAxisKey} radius={[4, 4, 0, 0]} animationDuration={1000}>
                                {chartData.map((entry, index) => (
                                    <Cell 
                                        key={`cell-${index}`} 
                                        fill={groupByKey ? groupColors[String(entry[groupByKey])] : DEFAULT_PALETTE[index % DEFAULT_PALETTE.length]} 
                                    />
                                ))}
                            </Bar>
                        </BarChart>
                    ) : (
                        <ComposedChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis 
                                type="number" 
                                dataKey={xAxisKey} 
                                name={tProp(xAxisKey)} 
                                fontSize={10} 
                                stroke={theme === 'dark' ? '#475569' : '#94a3b8'}
                                tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b' }}
                                label={{ value: tProp(xAxisKey), position: 'bottom', offset: 0, fontSize: 10, fill: '#64748b' }}
                            />
                            <YAxis 
                                type="number" 
                                dataKey={yAxisKey} 
                                name={tProp(yAxisKey)} 
                                fontSize={10} 
                                stroke={theme === 'dark' ? '#475569' : '#94a3b8'}
                                tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b' }}
                                label={{ value: tProp(yAxisKey), angle: -90, position: 'insideLeft', offset: 10, fontSize: 10, fill: '#64748b' }}
                            />
                            <ZAxis range={[60, 400]} />
                            <Tooltip 
                                cursor={{ strokeDasharray: '3 3' }}
                                content={<CustomTooltipContent />}
                            />
                            <Scatter 
                                name="Resin Samples" 
                                data={chartData} 
                                animationDuration={1500}
                                animationEasing="ease-in-out"
                            >
                                {chartData.map((entry, index) => (
                                    <Cell 
                                        key={`cell-${index}`} 
                                        fill={groupByKey ? groupColors[String(entry[groupByKey])] : '#10b981'} 
                                        strokeWidth={1}
                                        stroke="#ffffff"
                                        className="hover:scale-125 transition-transform"
                                    />
                                ))}
                            </Scatter>
                            {trendlineSegment && (
                                <Line 
                                    type="monotone" 
                                    data={trendlineSegment} 
                                    dataKey={yAxisKey} 
                                    stroke={trendlineColor} 
                                    strokeWidth={trendlineWidth} 
                                    strokeDasharray={dashArray}
                                    dot={false}
                                    activeDot={false}
                                    legendType="none"
                                />
                            )}
                        </ComposedChart>
                    )}
                </ResponsiveContainer>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  ReferenceLine,
  Cell,
  LabelList,
  Line,
  ComposedChart,
  ZAxis
} from 'recharts';
import { Settings, Download, ChevronUp, ChevronDown, BarChart2, ScatterChart as ScatterIcon, TrendingUp, Palette, PaintBucket, FileJson, FileType, Image as ImageIcon, RotateCcw, LayoutDashboard, Pipette } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

const DEFAULT_PALETTE = [
  '#10b981', // Emerald
  '#3b82f6', // Blue
  '#f59e0b', // Amber
  '#ef4444', // Red
  '#8b5cf6', // Violet
  '#ec4899', // Pink
  '#06b6d4', // Cyan
  '#84cc16', // Lime
  '#f97316', // Orange
  '#6366f1', // Indigo
];

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const { t, tProp } = useLanguage();
  const { theme } = useTheme();
  const chartRef = useRef<HTMLDivElement>(null);

  const [showConfig, setShowConfig] = useState(true);
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('gradeName');
  const [yAxisKey, setYAxisKey] = useState<string>('');

  // Manual Axis Limits
  const [xMin, setXMin] = useState<number | ''>('');
  const [xMax, setXMax] = useState<number | ''>('');
  const [yMin, setYMin] = useState<number | ''>('');
  const [yMax, setYMax] = useState<number | ''>('');

  // Trendline State
  const [showTrendline, setShowTrendline] = useState(false);
  const [trendlineColor, setTrendlineColor] = useState('#ef4444');
  const [trendlineWidth, setTrendlineWidth] = useState(2);
  const [trendlineStyle, setTrendlineStyle] = useState<'solid' | 'dashed' | 'dotted'>('dashed');

  // Scatter Plot Grouping State
  const [groupByKey, setGroupByKey] = useState<string>('');
  const [groupColors, setGroupColors] = useState<Record<string, string>>({});

  // 1. Identify Numeric Keys (for Axes)
  const numericKeys = useMemo(() => {
     const keys = new Set<string>();
     data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
           if (typeof v.value === 'number') {
               keys.add(k);
           } else if (!isNaN(Number(v.value)) && v.value !== '') {
               keys.add(k);
           }
        });
     });
     return Array.from(keys).sort();
  }, [data]);

  // 2. Identify Categorical Keys (for Grouping)
  const categoricalKeys = useMemo(() => {
    const keys = new Set<string>(['manufacturer']); // Always available
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (typeof v.value === 'string' && isNaN(Number(v.value))) {
                keys.add(k);
            }
        });
    });
    return Array.from(keys).sort();
  }, [data]);

  useEffect(() => {
      if (!yAxisKey && numericKeys.length > 0) {
          const preferred = ['密度', '熔体流动速率', '拉伸强度'].find(k => numericKeys.includes(k));
          setYAxisKey(preferred || numericKeys[0]);
      }
  }, [numericKeys, yAxisKey]);

  useEffect(() => {
    setXMin('');
    setXMax('');
  }, [xAxisKey]);

  useEffect(() => {
    setYMin('');
    setYMax('');
  }, [yAxisKey]);

  // 3. Prepare Chart Data
  const chartData = useMemo(() => {
    return data.map(p => {
        const item: any = {
            id: p.id,
            gradeName: p.gradeName,
            manufacturer: p.manufacturer,
            tooltipTitle: `${p.manufacturer} - ${p.gradeName}`
        };

        Object.entries(p.properties).forEach(([k, v]) => {
            const num = Number(v.value);
            if (!isNaN(num) && v.value !== '') {
                item[k] = num;
            } else {
                item[k] = v.value;
            }
        });
        return item;
    });
  }, [data]);

  // 4. Calculate Linear Regression for Trendline
  const trendlineSegment = useMemo(() => {
    if (!showTrendline || chartType !== 'scatter') return null;

    const validPoints = chartData.filter(d => 
        typeof d[xAxisKey] === 'number' && 
        typeof d[yAxisKey] === 'number'
    );

    if (validPoints.length < 2) return null;

    const n = validPoints.length;
    let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
    let minX = Infinity, maxX = -Infinity;

    validPoints.forEach(p => {
        const x = p[xAxisKey];
        const y = p[yAxisKey];
        sumX += x;
        sumY += y;
        sumXY += x * y;
        sumX2 += x * x;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
    });

    const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
    const intercept = (sumY - slope * sumX) / n;

    return [
        { [xAxisKey]: minX, [yAxisKey]: slope * minX + intercept, isTrend: true },
        { [xAxisKey]: maxX, [yAxisKey]: slope * maxX + intercept, isTrend: true }
    ];
  }, [chartData, xAxisKey, yAxisKey, showTrendline, chartType]);

  const dashArray = useMemo(() => {
    if (trendlineStyle === 'dashed') return '5 5';
    if (trendlineStyle === 'dotted') return '2 2';
    return '0';
  }, [trendlineStyle]);

  // 5. Determine Unique Groups
  const uniqueGroups = useMemo(() => {
    if (!groupByKey) return [];
    const groups = new Set<string>();
    chartData.forEach((item: any) => {
        const val = item[groupByKey];
        if (val !== undefined && val !== null && val !== '') {
            groups.add(String(val));
        } else {
            groups.add('Unknown');
        }
    });
    return Array.from(groups).sort();
  }, [groupByKey, chartData]);

  useEffect(() => {
    if (uniqueGroups.length > 0) {
        setGroupColors(prev => {
            const next = { ...prev };
            uniqueGroups.forEach((group, index) => {
                if (!next[group]) {
                    next[group] = DEFAULT_PALETTE[index % DEFAULT_PALETTE.length];
                }
            });
            return next;
        });
    }
  }, [uniqueGroups]);

  const updateGroupColor = (group: string, color: string) => {
    setGroupColors(prev => ({ ...prev, [group]: color }));
  };

  const handleDownload = async (type: 'json' | 'csv' | 'png') => {
    if (type === 'json') {
        const jsonString = JSON.stringify(chartData, null, 2);
        const blob = new Blob([jsonString], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_data.json';
        a.click();
    } else if (type === 'csv') {
        const headers = ['Grade', 'Manufacturer', ...numericKeys];
        const rows = chartData.map((row: any) => [
            row.gradeName,
            row.manufacturer,
            ...numericKeys.map(k => row[k] ?? '')
        ]);
        const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
        const blob = new Blob([csvContent], { type: 'text/csv' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_data.csv';
        a.click();
    } else if (type === 'png' && chartRef.current) {
        const canvas = await html2canvas(chartRef.current, {
            backgroundColor: theme === 'dark' ? '#020617' : '#ffffff'
        });
        const url = canvas.toDataURL('image/png');
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_chart.png';
        a.click();
    }
  };

  const CustomTooltipContent = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const d = payload[0].payload;
      if (d.isTrend) return null;

      const product = data.find(p => p.id === d.id);
      if (!product) return null;

      // Prioritize properties not already displayed as axes or color keys
      const additionalProps = Object.entries(product.properties)
        .filter(([k]) => k !== xAxisKey && k !== yAxisKey && k !== groupByKey)
        // Further prioritize potentially "less common" ones by skipping very common ones if possible
        .sort((a, b) => {
           const common = ['密度', '熔体流动速率', '拉伸强度', '应用', '类型'];
           const aIsCommon = common.includes(a[0]);
           const bIsCommon = common.includes(b[0]);
           if (aIsCommon && !bIsCommon) return 1;
           if (!aIsCommon && bIsCommon) return -1;
           return 0;
        })
        .slice(0, 3);

      return (
        <div className="p-4 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-2xl min-w-[200px] animate-in fade-in zoom-in-95 duration-200">
          <div className="flex items-center justify-between gap-4 mb-1">
            <p className="font-bold text-slate-800 dark:text-white truncate text-sm">{product.gradeName}</p>
            {groupByKey && d[groupByKey] && (
               <span className="text-[9px] px-2 py-0.5 rounded-full text-white font-bold" style={{ backgroundColor: groupColors[String(d[groupByKey])] }}>
                  {d[groupByKey]}
               </span>
            )}
          </div>
          <p className="text-[10px] text-slate-500 dark:text-slate-400 mb-3">{product.manufacturer}</p>

          <div className="space-y-1.5 pt-2 border-t border-slate-100 dark:border-slate-800">
             {chartType === 'scatter' ? (
               <>
                 <p className="text-xs flex justify-between gap-4">
                    <span className="text-slate-500">{tProp(xAxisKey)}:</span>
                    <span className="font-mono font-bold text-emerald-600 dark:text-emerald-400">
                        {product.properties[xAxisKey]?.value ?? d[xAxisKey]}
                        {product.properties[xAxisKey]?.unit ? ` ${product.properties[xAxisKey].unit}` : ''}
                    </span>
                 </p>
                 <p className="text-xs flex justify-between gap-4">
                    <span className="text-slate-500">{tProp(yAxisKey)}:</span>
                    <span className="font-mono font-bold text-blue-600 dark:text-blue-400">
                        {product.properties[yAxisKey]?.value ?? d[yAxisKey]}
                        {product.properties[yAxisKey]?.unit ? ` ${product.properties[yAxisKey].unit}` : ''}
                    </span>
                 </p>
               </>
             ) : (
               <p className="text-xs flex justify-between gap-4">
                  <span className="text-slate-500">{tProp(yAxisKey)}:</span>
                  <span className="font-mono font-bold text-emerald-600 dark:text-emerald-400">
                      {product.properties[yAxisKey]?.value ?? d[yAxisKey]}
                      {product.properties[yAxisKey]?.unit ? ` ${product.properties[yAxisKey].unit}` : ''}
                  </span>
               </p>
             )}
          </div>

          {additionalProps.length > 0 && (
            <div className="mt-3 pt-3 border-t border-slate-100 dark:border-slate-800 space-y-1.5">
              <p className="text-[9px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1">{t('details')}</p>
              {additionalProps.map(([key, prop]) => (
                <p key={key} className="text-[11px] flex justify-between gap-4 text-slate-600 dark:text-slate-300">
                  <span className="opacity-70 truncate max-w-[110px]">{tProp(key)}:</span>
                  <span className="font-medium whitespace-nowrap">
                    {prop.value}
                    {prop.unit ? ` ${prop.unit}` : ''}
                  </span>
                </p>
              ))}
            </div>
          )}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="flex flex-col md:flex-row h-full gap-4 overflow-hidden">
      {/* Settings Panel */}
      <div className={`flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl transition-all duration-300 overflow-hidden shrink-0 ${showConfig ? 'w-full md:w-80 opacity-100' : 'w-0 opacity-0 overflow-hidden md:border-none'}`}>
        <div className="p-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-950/50">
          <div className="flex items-center gap-2 font-bold text-sm text-slate-700 dark:text-slate-200 uppercase tracking-wider">
            <Settings size={16} className="text-emerald-500" />
            {t('chartConfig')}
          </div>
          <button onClick={() => setShowConfig(false)} className="md:hidden text-slate-400 hover:text-slate-600 dark:hover:text-slate-300">
            <ChevronUp size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-5 custom-scrollbar space-y-6">
          {/* Chart Type Selection */}
          <div className="space-y-3">
             <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <LayoutDashboard size={12} />
                {t('chartType')}
             </label>
             <div className="flex gap-2">
                <button 
                  onClick={() => setChartType('bar')}
                  className={`flex-1 flex flex-col items-center gap-2 p-3 rounded-xl border-2 transition-all ${chartType === 'bar' ? 'border-emerald-500 bg-emerald-50/50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 shadow-md shadow-emerald-500/10' : 'border-slate-100 dark:border-slate-800 text-slate-400 hover:border-slate-200 dark:hover:border-slate-700'}`}
                >
                  <BarChart2 size={24} />
                  <span className="text-[10px] font-bold uppercase">{t('barChart')}</span>
                </button>
                <button 
                  onClick={() => setChartType('scatter')}
                  className={`flex-1 flex flex-col items-center gap-2 p-3 rounded-xl border-2 transition-all ${chartType === 'scatter' ? 'border-emerald-500 bg-emerald-50/50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 shadow-md shadow-emerald-500/10' : 'border-slate-100 dark:border-slate-800 text-slate-400 hover:border-slate-200 dark:hover:border-slate-700'}`}
                >
                  <ScatterIcon size={24} />
                  <span className="text-[10px] font-bold uppercase">{t('scatterChart')}</span>
                </button>
             </div>
          </div>

          {/* Axis Mapping */}
          <div className="space-y-4">
            <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <RotateCcw size={12} />
                {t('axisMapping')}
            </label>
            <div className="space-y-3">
              <div className="space-y-1.5">
                <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('xAxis')}</span>
                <select 
                  value={xAxisKey} 
                  onChange={(e) => setXAxisKey(e.target.value)}
                  className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 outline-none transition-all"
                >
                  {chartType === 'bar' && <option value="gradeName">{tProp('牌号')}</option>}
                  {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                </select>
              </div>
              <div className="space-y-1.5">
                <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('yAxis')}</span>
                <select 
                  value={yAxisKey} 
                  onChange={(e) => setYAxisKey(e.target.value)}
                  className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 outline-none transition-all"
                >
                  {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                </select>
              </div>
            </div>
          </div>

          {/* Color & Grouping */}
          <div className="space-y-4 pt-2 border-t border-slate-100 dark:border-slate-800">
             <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <Palette size={12} />
                {t('styleGrouping')}
             </label>
             <div className="space-y-1.5">
               <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('groupBy')}</span>
               <select 
                 value={groupByKey} 
                 onChange={(e) => setGroupByKey(e.target.value)}
                 className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 outline-none transition-all"
               >
                 <option value="">{t('none')}</option>
                 {categoricalKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
               </select>
             </div>

             {/* Group Color Assignment */}
             {groupByKey && uniqueGroups.length > 0 && (
                <div className="space-y-3 pt-2 animate-in fade-in slide-in-from-top-2">
                    <span className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest ml-1">Color Mapping</span>
                    <div className="space-y-3 bg-slate-50 dark:bg-slate-950/30 p-3 rounded-xl border border-slate-100 dark:border-slate-800">
                        {uniqueGroups.map((group) => (
                            <div key={group} className="flex flex-col gap-1.5">
                                <span className="text-[10px] font-bold text-slate-600 dark:text-slate-400 truncate">{group}</span>
                                <div className="flex items-center gap-2">
                                    <div className="flex gap-1 flex-wrap flex-1">
                                        {DEFAULT_PALETTE.slice(0, 6).map(color => (
                                            <button 
                                                key={color}
                                                onClick={() => updateGroupColor(group, color)}
                                                className={`w-5 h-5 rounded-full border transition-all ${groupColors[group] === color ? 'border-white ring-1 ring-emerald-500 scale-110' : 'border-transparent opacity-60 hover:opacity-100'}`}
                                                style={{ backgroundColor: color }}
                                            />
                                        ))}
                                    </div>
                                    <div className="relative group/picker flex items-center gap-1 bg-white dark:bg-slate-800 p-1 rounded-md border border-slate-200 dark:border-slate-700">
                                        <Pipette size={10} className="text-slate-400" />
                                        <input 
                                            type="color" 
                                            value={groupColors[group] || '#10b981'}
                                            onChange={(e) => updateGroupColor(group, e.target.value)}
                                            className="w-4 h-4 p-0 border-none bg-transparent cursor-pointer"
                                        />
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
             )}
          </div>

          {/* Trendline Settings (Scatter only) */}
          {chartType === 'scatter' && (
            <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
               <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                  <TrendingUp size={12} />
                  {t('trendline')}
               </label>
               <div className="space-y-3">
                  <label className="flex items-center gap-3 cursor-pointer group">
                      <div className={`w-8 h-4 rounded-full relative transition-colors ${showTrendline ? 'bg-emerald-500' : 'bg-slate-200 dark:bg-slate-700'}`}>
                          <div className={`absolute top-0.5 w-3 h-3 bg-white rounded-full transition-transform ${showTrendline ? 'left-4.5 translate-x-4' : 'left-0.5'}`}></div>
                          <input type="checkbox" checked={showTrendline} onChange={() => setShowTrendline(!showTrendline)} className="hidden" />
                      </div>
                      <span className="text-sm text-slate-600 dark:text-slate-300">{t('showTrendline')}</span>
                  </label>

                  {showTrendline && (
                    <div className="space-y-3 pl-2 animate-in fade-in slide-in-from-top-1">
                      <div className="space-y-1">
                        <span className="text-[10px] text-slate-400 font-bold uppercase">{t('trendlineColor')}</span>
                        <div className="flex gap-2 flex-wrap">
                          {['#ef4444', '#f59e0b', '#10b981', '#3b82f6', '#8b5cf6'].map(c => (
                            <button 
                              key={c} 
                              onClick={() => setTrendlineColor(c)}
                              className={`w-6 h-6 rounded-full border-2 ${trendlineColor === c ? 'border-white ring-2 ring-emerald-500' : 'border-transparent'}`}
                              style={{ backgroundColor: c }}
                            />
                          ))}
                          <input 
                            type="color" 
                            value={trendlineColor} 
                            onChange={(e) => setTrendlineColor(e.target.value)}
                            className="w-6 h-6 p-0 border-none bg-transparent cursor-pointer"
                          />
                        </div>
                      </div>
                      <div className="space-y-1">
                        <span className="text-[10px] text-slate-400 font-bold uppercase">{t('trendlineWidth')}</span>
                        <input 
                          type="range" min="1" max="5" step="1" 
                          value={trendlineWidth} 
                          onChange={(e) => setTrendlineWidth(Number(e.target.value))}
                          className="w-full accent-emerald-500" 
                        />
                      </div>
                      <div className="space-y-1">
                        <span className="text-[10px] text-slate-400 font-bold uppercase">{t('trendlineStyle')}</span>
                        <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-lg">
                           {(['solid', 'dashed', 'dotted'] as const).map(style => (
                             <button
                                key={style}
                                onClick={() => setTrendlineStyle(style)}
                                className={`flex-1 px-2 py-1 text-[9px] font-bold uppercase rounded transition-all ${trendlineStyle === style ? 'bg-white dark:bg-slate-700 shadow-sm text-emerald-600' : 'text-slate-400'}`}
                             >
                               {t(style)}
                             </button>
                           ))}
                        </div>
                      </div>
                    </div>
                  )}
               </div>
            </div>
          )}

          {/* Export Group */}
          <div className="pt-4 border-t border-slate-100 dark:border-slate-800 grid grid-cols-2 gap-2">
            <button 
              onClick={() => handleDownload('json')}
              className="flex items-center justify-center gap-2 p-2 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-lg text-[10px] font-bold text-slate-600 dark:text-slate-400 transition-colors uppercase"
            >
              <FileJson size={14} />
              JSON
            </button>
            <button 
              onClick={() => handleDownload('png')}
              className="flex items-center justify-center gap-2 p-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-[10px] font-bold transition-colors uppercase shadow-md shadow-emerald-500/20"
            >
              <ImageIcon size={14} />
              PNG
            </button>
          </div>
        </div>
      </div>

      {/* Chart Canvas Area */}
      <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl relative min-h-[400px]">
        {!showConfig && (
            <button 
                onClick={() => setShowConfig(true)}
                className="absolute top-4 left-4 z-10 p-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-emerald-500 hover:scale-105 transition-transform shadow-lg"
            >
                <Settings size={20} />
            </button>
        )}

        <div className="flex-1 p-6 flex flex-col min-h-0" ref={chartRef}>
            <div className="mb-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
               <div>
                  <h2 className="text-lg font-bold text-slate-800 dark:text-white flex items-center gap-2">
                     {chartType === 'bar' ? <BarChart2 size={20} className="text-emerald-500" /> : <ScatterIcon size={20} className="text-emerald-500" />}
                     {tProp(yAxisKey)} vs {chartType === 'bar' ? tProp('牌号') : tProp(xAxisKey)}
                  </h2>
                  <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">{t('chartTitle')}</p>
               </div>
               {groupByKey && (
                 <div className="flex flex-wrap gap-2">
                    {uniqueGroups.map(group => (
                        <div key={group} className="flex items-center gap-1.5 px-2 py-1 bg-slate-50 dark:bg-slate-800 rounded-full border border-slate-100 dark:border-slate-700">
                           <div className="w-2 h-2 rounded-full" style={{ backgroundColor: groupColors[group] }}></div>
                           <span className="text-[10px] font-bold text-slate-600 dark:text-slate-300">{group}</span>
                        </div>
                    ))}
                 </div>
               )}
            </div>

            <div className="flex-1 w-full min-h-0">
                <ResponsiveContainer width="100%" height="100%">
                    {chartType === 'bar' ? (
                        <BarChart data={chartData} margin={{ top: 10, right: 30, left: 0, bottom: 40 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis 
                                dataKey="gradeName" 
                                angle={-45} 
                                textAnchor="end" 
                                interval={0} 
                                height={60} 
                                fontSize={10} 
                                stroke={theme === 'dark' ? '#475569' : '#94a3b8'}
                                tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b' }}
                            />
                            <YAxis 
                                fontSize={10} 
                                stroke={theme === 'dark' ? '#475569' : '#94a3b8'}
                                tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b' }}
                            />
                            <Tooltip 
                                cursor={{ fill: 'rgba(16, 185, 129, 0.05)' }}
                                content={<CustomTooltipContent />}
                            />
                            <Bar dataKey={yAxisKey} radius={[4, 4, 0, 0]} animationDuration={1000}>
                                {chartData.map((entry, index) => (
                                    <Cell 
                                        key={`cell-${index}`} 
                                        fill={groupByKey ? groupColors[String(entry[groupByKey])] : DEFAULT_PALETTE[index % DEFAULT_PALETTE.length]} 
                                    />
                                ))}
                            </Bar>
                        </BarChart>
                    ) : (
                        <ComposedChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis 
                                type="number" 
                                dataKey={xAxisKey} 
                                name={tProp(xAxisKey)} 
                                fontSize={10} 
                                stroke={theme === 'dark' ? '#475569' : '#94a3b8'}
                                tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b' }}
                                label={{ value: tProp(xAxisKey), position: 'bottom', offset: 0, fontSize: 10, fill: '#64748b' }}
                            />
                            <YAxis 
                                type="number" 
                                dataKey={yAxisKey} 
                                name={tProp(yAxisKey)} 
                                fontSize={10} 
                                stroke={theme === 'dark' ? '#475569' : '#94a3b8'}
                                tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b' }}
                                label={{ value: tProp(yAxisKey), angle: -90, position: 'insideLeft', offset: 10, fontSize: 10, fill: '#64748b' }}
                            />
                            <ZAxis range={[60, 400]} />
                            <Tooltip 
                                cursor={{ strokeDasharray: '3 3' }}
                                content={<CustomTooltipContent />}
                            />
                            <Scatter 
                                name="Resin Samples" 
                                data={chartData} 
                                animationDuration={1500}
                                animationEasing="ease-in-out"
                            >
                                {chartData.map((entry, index) => (
                                    <Cell 
                                        key={`cell-${index}`} 
                                        fill={groupByKey ? groupColors[String(entry[groupByKey])] : '#10b981'} 
                                        strokeWidth={1}
                                        stroke="#ffffff"
                                        className="hover:scale-125 transition-transform"
                                    />
                                ))}
                            </Scatter>
                            {trendlineSegment && (
                                <Line 
                                    type="monotone" 
                                    data={trendlineSegment} 
                                    dataKey={yAxisKey} 
                                    stroke={trendlineColor} 
                                    strokeWidth={trendlineWidth} 
                                    strokeDasharray={dashArray}
                                    dot={false}
                                    activeDot={false}
                                    legendType="none"
                                />
                            )}
                        </ComposedChart>
                    )}
                </ResponsiveContainer>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  ReferenceLine,
  Cell,
  LabelList,
  Line,
  ComposedChart,
  ZAxis
} from 'recharts';
import { Settings, Download, ChevronUp, ChevronDown, BarChart2, ScatterChart as ScatterIcon, TrendingUp, Palette, PaintBucket, FileJson, FileType, Image as ImageIcon, RotateCcw, LayoutDashboard, Pipette, Maximize } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

const DEFAULT_PALETTE = [
  '#10b981', // Emerald
  '#3b82f6', // Blue
  '#f59e0b', // Amber
  '#ef4444', // Red
  '#8b5cf6', // Violet
  '#ec4899', // Pink
  '#06b6d4', // Cyan
  '#84cc16', // Lime
  '#f97316', // Orange
  '#6366f1', // Indigo
];

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const { t, tProp } = useLanguage();
  const { theme } = useTheme();
  const chartRef = useRef<HTMLDivElement>(null);

  const [showConfig, setShowConfig] = useState(true);
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('gradeName');
  const [yAxisKey, setYAxisKey] = useState<string>('');

  // Manual Axis Limits
  const [xMin, setXMin] = useState<number | ''>('');
  const [xMax, setXMax] = useState<number | ''>('');
  const [yMin, setYMin] = useState<number | ''>('');
  const [yMax, setYMax] = useState<number | ''>('');

  // Trendline State
  const [showTrendline, setShowTrendline] = useState(false);
  const [trendlineColor, setTrendlineColor] = useState('#ef4444');
  const [trendlineWidth, setTrendlineWidth] = useState(2);
  const [trendlineStyle, setTrendlineStyle] = useState<'solid' | 'dashed' | 'dotted'>('dashed');

  // Scatter Plot Grouping State
  const [groupByKey, setGroupByKey] = useState<string>('');
  const [groupColors, setGroupColors] = useState<Record<string, string>>({});

  // 1. Identify Numeric Keys (for Axes)
  const numericKeys = useMemo(() => {
     const keys = new Set<string>();
     data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
           if (typeof v.value === 'number') {
               keys.add(k);
           } else if (!isNaN(Number(v.value)) && v.value !== '') {
               keys.add(k);
           }
        });
     });
     return Array.from(keys).sort();
  }, [data]);

  // 2. Identify Categorical Keys (for Grouping)
  const categoricalKeys = useMemo(() => {
    const keys = new Set<string>(['manufacturer']); // Always available
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (typeof v.value === 'string' && isNaN(Number(v.value))) {
                keys.add(k);
            }
        });
    });
    return Array.from(keys).sort();
  }, [data]);

  useEffect(() => {
      if (!yAxisKey && numericKeys.length > 0) {
          const preferred = ['密度', '熔体流动速率', '拉伸强度'].find(k => numericKeys.includes(k));
          setYAxisKey(preferred || numericKeys[0]);
      }
  }, [numericKeys, yAxisKey]);

  useEffect(() => {
    setXMin('');
    setXMax('');
  }, [xAxisKey]);

  useEffect(() => {
    setYMin('');
    setYMax('');
  }, [yAxisKey]);

  // 3. Prepare Chart Data
  const chartData = useMemo(() => {
    return data.map(p => {
        const item: any = {
            id: p.id,
            gradeName: p.gradeName,
            manufacturer: p.manufacturer,
            tooltipTitle: `${p.manufacturer} - ${p.gradeName}`
        };

        Object.entries(p.properties).forEach(([k, v]) => {
            const num = Number(v.value);
            if (!isNaN(num) && v.value !== '') {
                item[k] = num;
            } else {
                item[k] = v.value;
            }
        });
        return item;
    });
  }, [data]);

  // 4. Calculate Linear Regression for Trendline
  const trendlineSegment = useMemo(() => {
    if (!showTrendline || chartType !== 'scatter') return null;

    const validPoints = chartData.filter(d => 
        typeof d[xAxisKey] === 'number' && 
        typeof d[yAxisKey] === 'number'
    );

    if (validPoints.length < 2) return null;

    const n = validPoints.length;
    let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
    let minX = Infinity, maxX = -Infinity;

    validPoints.forEach(p => {
        const x = p[xAxisKey];
        const y = p[yAxisKey];
        sumX += x;
        sumY += y;
        sumXY += x * y;
        sumX2 += x * x;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
    });

    const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
    const intercept = (sumY - slope * sumX) / n;

    return [
        { [xAxisKey]: minX, [yAxisKey]: slope * minX + intercept, isTrend: true },
        { [xAxisKey]: maxX, [yAxisKey]: slope * maxX + intercept, isTrend: true }
    ];
  }, [chartData, xAxisKey, yAxisKey, showTrendline, chartType]);

  const dashArray = useMemo(() => {
    if (trendlineStyle === 'dashed') return '5 5';
    if (trendlineStyle === 'dotted') return '2 2';
    return '0';
  }, [trendlineStyle]);

  // 5. Determine Unique Groups
  const uniqueGroups = useMemo(() => {
    if (!groupByKey) return [];
    const groups = new Set<string>();
    chartData.forEach((item: any) => {
        const val = item[groupByKey];
        if (val !== undefined && val !== null && val !== '') {
            groups.add(String(val));
        } else {
            groups.add('Unknown');
        }
    });
    return Array.from(groups).sort();
  }, [groupByKey, chartData]);

  useEffect(() => {
    if (uniqueGroups.length > 0) {
        setGroupColors(prev => {
            const next = { ...prev };
            uniqueGroups.forEach((group, index) => {
                if (!next[group]) {
                    next[group] = DEFAULT_PALETTE[index % DEFAULT_PALETTE.length];
                }
            });
            return next;
        });
    }
  }, [uniqueGroups]);

  const updateGroupColor = (group: string, color: string) => {
    setGroupColors(prev => ({ ...prev, [group]: color }));
  };

  const handleDownload = async (type: 'json' | 'csv' | 'png') => {
    if (type === 'json') {
        const jsonString = JSON.stringify(chartData, null, 2);
        const blob = new Blob([jsonString], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_data.json';
        a.click();
    } else if (type === 'csv') {
        const headers = ['Grade', 'Manufacturer', ...numericKeys];
        const rows = chartData.map((row: any) => [
            row.gradeName,
            row.manufacturer,
            ...numericKeys.map(k => row[k] ?? '')
        ]);
        const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
        const blob = new Blob([csvContent], { type: 'text/csv' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_data.csv';
        a.click();
    } else if (type === 'png' && chartRef.current) {
        const canvas = await html2canvas(chartRef.current, {
            backgroundColor: theme === 'dark' ? '#020617' : '#ffffff'
        });
        const url = canvas.toDataURL('image/png');
        const a = document.createElement('a');
        a.href = url;
        a.download = 'resindb_chart.png';
        a.click();
    }
  };

  const CustomTooltipContent = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const d = payload[0].payload;
      if (d.isTrend) return null;

      const product = data.find(p => p.id === d.id);
      if (!product) return null;

      // Prioritize properties not already displayed as axes or color keys
      const additionalProps = Object.entries(product.properties)
        .filter(([k]) => k !== xAxisKey && k !== yAxisKey && k !== groupByKey)
        // Further prioritize potentially "less common" ones by skipping very common ones if possible
        .sort((a, b) => {
           const common = ['密度', '熔体流动速率', '拉伸强度', '应用', '类型'];
           const aIsCommon = common.includes(a[0]);
           const bIsCommon = common.includes(b[0]);
           if (aIsCommon && !bIsCommon) return 1;
           if (!aIsCommon && bIsCommon) return -1;
           return 0;
        })
        .slice(0, 3);

      return (
        <div className="p-4 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-2xl min-w-[200px] animate-in fade-in zoom-in-95 duration-200">
          <div className="flex items-center justify-between gap-4 mb-1">
            <p className="font-bold text-slate-800 dark:text-white truncate text-sm">{product.gradeName}</p>
            {groupByKey && d[groupByKey] && (
               <span className="text-[9px] px-2 py-0.5 rounded-full text-white font-bold" style={{ backgroundColor: groupColors[String(d[groupByKey])] }}>
                  {d[groupByKey]}
               </span>
            )}
          </div>
          <p className="text-[10px] text-slate-500 dark:text-slate-400 mb-3">{product.manufacturer}</p>

          <div className="space-y-1.5 pt-2 border-t border-slate-100 dark:border-slate-800">
             {chartType === 'scatter' ? (
               <>
                 <p className="text-xs flex justify-between gap-4">
                    <span className="text-slate-500">{tProp(xAxisKey)}:</span>
                    <span className="font-mono font-bold text-emerald-600 dark:text-emerald-400">
                        {product.properties[xAxisKey]?.value ?? d[xAxisKey]}
                        {product.properties[xAxisKey]?.unit ? ` ${product.properties[xAxisKey].unit}` : ''}
                    </span>
                 </p>
                 <p className="text-xs flex justify-between gap-4">
                    <span className="text-slate-500">{tProp(yAxisKey)}:</span>
                    <span className="font-mono font-bold text-blue-600 dark:text-blue-400">
                        {product.properties[yAxisKey]?.value ?? d[yAxisKey]}
                        {product.properties[yAxisKey]?.unit ? ` ${product.properties[yAxisKey].unit}` : ''}
                    </span>
                 </p>
               </>
             ) : (
               <p className="text-xs flex justify-between gap-4">
                  <span className="text-slate-500">{tProp(yAxisKey)}:</span>
                  <span className="font-mono font-bold text-emerald-600 dark:text-emerald-400">
                      {product.properties[yAxisKey]?.value ?? d[yAxisKey]}
                      {product.properties[yAxisKey]?.unit ? ` ${product.properties[yAxisKey].unit}` : ''}
                  </span>
               </p>
             )}
          </div>

          {additionalProps.length > 0 && (
            <div className="mt-3 pt-3 border-t border-slate-100 dark:border-slate-800 space-y-1.5">
              <p className="text-[9px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1">{t('details')}</p>
              {additionalProps.map(([key, prop]) => (
                <p key={key} className="text-[11px] flex justify-between gap-4 text-slate-600 dark:text-slate-300">
                  <span className="opacity-70 truncate max-w-[110px]">{tProp(key)}:</span>
                  <span className="font-medium whitespace-nowrap">
                    {prop.value}
                    {prop.unit ? ` ${prop.unit}` : ''}
                  </span>
                </p>
              ))}
            </div>
          )}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="flex flex-col md:flex-row h-full gap-4 overflow-hidden">
      {/* Settings Panel */}
      <div className={`flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl transition-all duration-300 overflow-hidden shrink-0 ${showConfig ? 'w-full md:w-80 opacity-100' : 'w-0 opacity-0 overflow-hidden md:border-none'}`}>
        <div className="p-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-950/50">
          <div className="flex items-center gap-2 font-bold text-sm text-slate-700 dark:text-slate-200 uppercase tracking-wider">
            <Settings size={16} className="text-emerald-500" />
            {t('chartConfig')}
          </div>
          <button onClick={() => setShowConfig(false)} className="md:hidden text-slate-400 hover:text-slate-600 dark:hover:text-slate-300">
            <ChevronUp size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-5 custom-scrollbar space-y-6">
          {/* Chart Type Selection */}
          <div className="space-y-3">
             <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <LayoutDashboard size={12} />
                {t('chartType')}
             </label>
             <div className="flex gap-2">
                <button 
                  onClick={() => setChartType('bar')}
                  className={`flex-1 flex flex-col items-center gap-2 p-3 rounded-xl border-2 transition-all ${chartType === 'bar' ? 'border-emerald-500 bg-emerald-50/50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 shadow-md shadow-emerald-500/10' : 'border-slate-100 dark:border-slate-800 text-slate-400 hover:border-slate-200 dark:hover:border-slate-700'}`}
                >
                  <BarChart2 size={24} />
                  <span className="text-[10px] font-bold uppercase">{t('barChart')}</span>
                </button>
                <button 
                  onClick={() => setChartType('scatter')}
                  className={`flex-1 flex flex-col items-center gap-2 p-3 rounded-xl border-2 transition-all ${chartType === 'scatter' ? 'border-emerald-500 bg-emerald-50/50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 shadow-md shadow-emerald-500/10' : 'border-slate-100 dark:border-slate-800 text-slate-400 hover:border-slate-200 dark:hover:border-slate-700'}`}
                >
                  <ScatterIcon size={24} />
                  <span className="text-[10px] font-bold uppercase">{t('scatterChart')}</span>
                </button>
             </div>
          </div>

          {/* Axis Mapping */}
          <div className="space-y-4">
            <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <RotateCcw size={12} />
                {t('axisMapping')}
            </label>
            <div className="space-y-3">
              <div className="space-y-1.5">
                <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('xAxis')}</span>
                <select 
                  value={xAxisKey} 
                  onChange={(e) => setXAxisKey(e.target.value)}
                  className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 outline-none transition-all"
                >
                  {chartType === 'bar' && <option value="gradeName">{tProp('牌号')}</option>}
                  {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                </select>
              </div>
              <div className="space-y-1.5">
                <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('yAxis')}</span>
                <select 
                  value={yAxisKey} 
                  onChange={(e) => setYAxisKey(e.target.value)}
                  className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 outline-none transition-all"
                >
                  {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                </select>
              </div>
            </div>
          </div>

          {/* Axis Limits (Scatter only) */}
          {chartType === 'scatter' && (
            <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
               <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                  <Maximize size={12} />
                  {t('axisMapping')}
               </label>
               <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <span className="text-[10px] font-bold text-slate-500 uppercase tracking-tighter ml-1">{t('xAxisMin')}</span>
                    <input 
                      type="number" 
                      value={xMin} 
                      onChange={(e) => setXMin(e.target.value === '' ? '' : Number(e.target.value))}
                      placeholder="Auto"
                      className="w-full px-3 py-1.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-xs outline-none focus:ring-2 focus:ring-emerald-500/20"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <span className="text-[10px] font-bold text-slate-500 uppercase tracking-tighter ml-1">{t('xAxisMax')}</span>
                    <input 
                      type="number" 
                      value={xMax} 
                      onChange={(e) => setXMax(e.target.value === '' ? '' : Number(e.target.value))}
                      placeholder="Auto"
                      className="w-full px-3 py-1.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-xs outline-none focus:ring-2 focus:ring-emerald-500/20"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <span className="text-[10px] font-bold text-slate-500 uppercase tracking-tighter ml-1">{t('yAxisMin')}</span>
                    <input 
                      type="number" 
                      value={yMin} 
                      onChange={(e) => setYMin(e.target.value === '' ? '' : Number(e.target.value))}
                      placeholder="Auto"
                      className="w-full px-3 py-1.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-xs outline-none focus:ring-2 focus:ring-emerald-500/20"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <span className="text-[10px] font-bold text-slate-500 uppercase tracking-tighter ml-1">{t('yAxisMax')}</span>
                    <input 
                      type="number" 
                      value={yMax} 
                      onChange={(e) => setYMax(e.target.value === '' ? '' : Number(e.target.value))}
                      placeholder="Auto"
                      className="w-full px-3 py-1.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-xs outline-none focus:ring-2 focus:ring-emerald-500/20"
                    />
                  </div>
               </div>
            </div>
          )}

          {/* Color & Grouping */}
          <div className="space-y-4 pt-2 border-t border-slate-100 dark:border-slate-800">
             <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <Palette size={12} />
                {t('styleGrouping')}
             </label>
             <div className="space-y-1.5">
               <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('groupBy')}</span>
               <select 
                 value={groupByKey} 
                 onChange={(e) => setGroupByKey(e.target.value)}
                 className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 outline-none transition-all"
               >
                 <option value="">{t('none')}</option>
                 {categoricalKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
               </select>
             </div>

             {/* Group Color Assignment */}
             {groupByKey && uniqueGroups.length > 0 && (
                <div className="space-y-3 pt-2 animate-in fade-in slide-in-from-top-2">
                    <span className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest ml-1">Color Mapping</span>
                    <div className="space-y-3 bg-slate-50 dark:bg-slate-950/30 p-3 rounded-xl border border-slate-100 dark:border-slate-800">
                        {uniqueGroups.map((group) => (
                            <div key={group} className="flex flex-col gap-1.5">
                                <span className="text-[10px] font-bold text-slate-600 dark:text-slate-400 truncate">{group}</span>
                                <div className="flex items-center gap-2">
                                    <div className="flex gap-1 flex-wrap flex-1">
                                        {DEFAULT_PALETTE.slice(0, 6).map(color => (
                                            <button 
                                                key={color}
                                                onClick={() => updateGroupColor(group, color)}
                                                className={`w-5 h-5 rounded-full border transition-all ${groupColors[group] === color ? 'border-white ring-1 ring-emerald-500 scale-110' : 'border-transparent opacity-60 hover:opacity-100'}`}
                                                style={{ backgroundColor: color }}
                                            />
                                        ))}
                                    </div>
                                    <div className="relative group/picker flex items-center gap-1 bg-white dark:bg-slate-800 p-1 rounded-md border border-slate-200 dark:border-slate-700">
                                        <Pipette size={10} className="text-slate-400" />
                                        <input 
                                            type="color" 
                                            value={groupColors[group] || '#10b981'}
                                            onChange={(e) => updateGroupColor(group, e.target.value)}
                                            className="w-4 h-4 p-0 border-none bg-transparent cursor-pointer"
                                        />
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
             )}
          </div>

          {/* Trendline Settings (Scatter only) */}
          {chartType === 'scatter' && (
            <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
               <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                  <TrendingUp size={12} />
                  {t('trendline')}
               </label>
               <div className="space-y-3">
                  <label className="flex items-center gap-3 cursor-pointer group">
                      <div className={`w-8 h-4 rounded-full relative transition-colors ${showTrendline ? 'bg-emerald-500' : 'bg-slate-200 dark:bg-slate-700'}`}>
                          <div className={`absolute top-0.5 w-3 h-3 bg-white rounded-full transition-transform ${showTrendline ? 'left-4.5 translate-x-4' : 'left-0.5'}`}></div>
                          <input type="checkbox" checked={showTrendline} onChange={() => setShowTrendline(!showTrendline)} className="hidden" />
                      </div>
                      <span className="text-sm text-slate-600 dark:text-slate-300">{t('showTrendline')}</span>
                  </label>

                  {showTrendline && (
                    <div className="space-y-3 pl-2 animate-in fade-in slide-in-from-top-1">
                      <div className="space-y-1">
                        <span className="text-[10px] text-slate-400 font-bold uppercase">{t('trendlineColor')}</span>
                        <div className="flex gap-2 flex-wrap">
                          {['#ef4444', '#f59e0b', '#10b981', '#3b82f6', '#8b5cf6'].map(c => (
                            <button 
                              key={c} 
                              onClick={() => setTrendlineColor(c)}
                              className={`w-6 h-6 rounded-full border-2 ${trendlineColor === c ? 'border-white ring-2 ring-emerald-500' : 'border-transparent'}`}
                              style={{ backgroundColor: c }}
                            />
                          ))}
                          <input 
                            type="color" 
                            value={trendlineColor} 
                            onChange={(e) => setTrendlineColor(e.target.value)}
                            className="w-6 h-6 p-0 border-none bg-transparent cursor-pointer"
                          />
                        </div>
                      </div>
                      <div className="space-y-1">
                        <span className="text-[10px] text-slate-400 font-bold uppercase">{t('trendlineWidth')}</span>
                        <input 
                          type="range" min="1" max="5" step="1" 
                          value={trendlineWidth} 
                          onChange={(e) => setTrendlineWidth(Number(e.target.value))}
                          className="w-full accent-emerald-500" 
                        />
                      </div>
                      <div className="space-y-1">
                        <span className="text-[10px] text-slate-400 font-bold uppercase">{t('trendlineStyle')}</span>
                        <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-lg">
                           {(['solid', 'dashed', 'dotted'] as const).map(style => (
                             <button
                                key={style}
                                onClick={() => setTrendlineStyle(style)}
                                className={`flex-1 px-2 py-1 text-[9px] font-bold uppercase rounded transition-all ${trendlineStyle === style ? 'bg-white dark:bg-slate-700 shadow-sm text-emerald-600' : 'text-slate-400'}`}
                             >
                               {t(style)}
                             </button>
                           ))}
                        </div>
                      </div>
                    </div>
                  )}
               </div>
            </div>
          )}

          {/* Export Group */}
          <div className="pt-4 border-t border-slate-100 dark:border-slate-800 grid grid-cols-2 gap-2">
            <button 
              onClick={() => handleDownload('json')}
              className="flex items-center justify-center gap-2 p-2 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-lg text-[10px] font-bold text-slate-600 dark:text-slate-400 transition-colors uppercase"
            >
              <FileJson size={14} />
              JSON
            </button>
            <button 
              onClick={() => handleDownload('png')}
              className="flex items-center justify-center gap-2 p-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-[10px] font-bold transition-colors uppercase shadow-md shadow-emerald-500/20"
            >
              <ImageIcon size={14} />
              PNG
            </button>
          </div>
        </div>
      </div>

      {/* Chart Canvas Area */}
      <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl relative min-h-[400px]">
        {!showConfig && (
            <button 
                onClick={() => setShowConfig(true)}
                className="absolute top-4 left-4 z-10 p-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-emerald-500 hover:scale-105 transition-transform shadow-lg"
            >
                <Settings size={20} />
            </button>
        )}

        <div className="flex-1 p-6 flex flex-col min-h-0" ref={chartRef}>
            <div className="mb-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
               <div>
                  <h2 className="text-lg font-bold text-slate-800 dark:text-white flex items-center gap-2">
                     {chartType === 'bar' ? <BarChart2 size={20} className="text-emerald-500" /> : <ScatterIcon size={20} className="text-emerald-500" />}
                     {tProp(yAxisKey)} vs {chartType === 'bar' ? tProp('牌号') : tProp(xAxisKey)}
                  </h2>
                  <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">{t('chartTitle')}</p>
               </div>
               {groupByKey && (
                 <div className="flex flex-wrap gap-2">
                    {uniqueGroups.map(group => (
                        <div key={group} className="flex items-center gap-1.5 px-2 py-1 bg-slate-50 dark:bg-slate-800 rounded-full border border-slate-100 dark:border-slate-700">
                           <div className="w-2 h-2 rounded-full" style={{ backgroundColor: groupColors[group] }}></div>
                           <span className="text-[10px] font-bold text-slate-600 dark:text-slate-300">{group}</span>
                        </div>
                    ))}
                 </div>
               )}
            </div>

            <div className="flex-1 w-full min-h-0">
                <ResponsiveContainer width="100%" height="100%">
                    {chartType === 'bar' ? (
                        <BarChart data={chartData} margin={{ top: 10, right: 30, left: 0, bottom: 40 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis 
                                dataKey="gradeName" 
                                angle={-45} 
                                textAnchor="end" 
                                interval={0} 
                                height={60} 
                                fontSize={10} 
                                stroke={theme === 'dark' ? '#475569' : '#94a3b8'}
                                tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b' }}
                            />
                            <YAxis 
                                fontSize={10} 
                                stroke={theme === 'dark' ? '#475569' : '#94a3b8'}
                                tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b' }}
                            />
                            <Tooltip 
                                cursor={{ fill: 'rgba(16, 185, 129, 0.05)' }}
                                content={<CustomTooltipContent />}
                            />
                            <Bar dataKey={yAxisKey} radius={[4, 4, 0, 0]} animationDuration={1000}>
                                {chartData.map((entry, index) => (
                                    <Cell 
                                        key={`cell-${index}`} 
                                        fill={groupByKey ? groupColors[String(entry[groupByKey])] : DEFAULT_PALETTE[index % DEFAULT_PALETTE.length]} 
                                    />
                                ))}
                            </Bar>
                        </BarChart>
                    ) : (
                        <ComposedChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis 
                                type="number" 
                                dataKey={xAxisKey} 
                                name={tProp(xAxisKey)} 
                                fontSize={10} 
                                domain={[xMin === '' ? 'auto' : xMin, xMax === '' ? 'auto' : xMax]}
                                stroke={theme === 'dark' ? '#475569' : '#94a3b8'}
                                tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b' }}
                                label={{ value: tProp(xAxisKey), position: 'bottom', offset: 0, fontSize: 10, fill: '#64748b' }}
                            />
                            <YAxis 
                                type="number" 
                                dataKey={yAxisKey} 
                                name={tProp(yAxisKey)} 
                                fontSize={10} 
                                domain={[yMin === '' ? 'auto' : yMin, yMax === '' ? 'auto' : yMax]}
                                stroke={theme === 'dark' ? '#475569' : '#94a3b8'}
                                tick={{ fill: theme === 'dark' ? '#94a3b8' : '#64748b' }}
                                label={{ value: tProp(yAxisKey), angle: -90, position: 'insideLeft', offset: 10, fontSize: 10, fill: '#64748b' }}
                            />
                            <ZAxis range={[60, 400]} />
                            <Tooltip 
                                cursor={{ strokeDasharray: '3 3' }}
                                content={<CustomTooltipContent />}
                            />
                            <Scatter 
                                name="Resin Samples" 
                                data={chartData} 
                                animationDuration={1500}
                                animationEasing="ease-in-out"
                            >
                                {chartData.map((entry, index) => (
                                    <Cell 
                                        key={`cell-${index}`} 
                                        fill={groupByKey ? groupColors[String(entry[groupByKey])] : '#10b981'} 
                                        strokeWidth={1}
                                        stroke="#ffffff"
                                        className="hover:scale-125 transition-transform"
                                    />
                                ))}
                            </Scatter>
                            {trendlineSegment && (
                                <Line 
                                    type="monotone" 
                                    data={trendlineSegment} 
                                    dataKey={yAxisKey} 
                                    stroke={trendlineColor} 
                                    strokeWidth={trendlineWidth} 
                                    strokeDasharray={dashArray}
                                    dot={false}
                                    activeDot={false}
                                    legendType="none"
                                />
                            )}
                        </ComposedChart>
                    )}
                </ResponsiveContainer>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  ReferenceLine,
  Cell,
  LabelList,
  Line,
  ComposedChart,
  ZAxis
} from 'recharts';
import { Settings, Download, ChevronUp, BarChart2, ScatterChart as ScatterIcon, TrendingUp, Palette, FileJson, Image as ImageIcon, RotateCcw, LayoutDashboard, Pipette, Maximize, X } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

const DEFAULT_PALETTE = [
  '#10b981', // Emerald
  '#3b82f6', // Blue
  '#f59e0b', // Amber
  '#ef4444', // Red
  '#8b5cf6', // Violet
  '#ec4899', // Pink
  '#06b6d4', // Cyan
  '#84cc16', // Lime
  '#f97316', // Orange
  '#6366f1', // Indigo
];

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const { t, tProp } = useLanguage();
  const { theme } = useTheme();
  const chartRef = useRef<HTMLDivElement>(null);

  const [showConfig, setShowConfig] = useState(true);
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('gradeName');
  const [yAxisKey, setYAxisKey] = useState<string>('');

  // Manual Axis Limits
  const [xMin, setXMin] = useState<number | ''>('');
  const [xMax, setXMax] = useState<number | ''>('');
  const [yMin, setYMin] = useState<number | ''>('');
  const [yMax, setYMax] = useState<number | ''>('');

  // Trendline State
  const [showTrendline, setShowTrendline] = useState(false);
  const [trendlineColor, setTrendlineColor] = useState('#ef4444');
  const [trendlineWidth, setTrendlineWidth] = useState(2);
  const [trendlineStyle, setTrendlineStyle] = useState<'solid' | 'dashed' | 'dotted'>('dashed');

  // Grouping & Color State
  const [groupByKey, setGroupByKey] = useState<string>('');
  const [groupColors, setGroupColors] = useState<Record<string, string>>({});

  // 1. Identify Numeric Keys (for Axes)
  const numericKeys = useMemo(() => {
     const keys = new Set<string>();
     data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
           if (typeof v.value === 'number' || (!isNaN(Number(v.value)) && v.value !== '')) {
               keys.add(k);
           }
        });
     });
     return Array.from(keys).sort();
  }, [data]);

  // 2. Identify Categorical Keys (for Grouping)
  const categoricalKeys = useMemo(() => {
    const keys = new Set<string>(['manufacturer']); // Always available
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (typeof v.value === 'string' && isNaN(Number(v.value))) {
                keys.add(k);
            }
        });
    });
    return Array.from(keys).sort();
  }, [data]);

  useEffect(() => {
      if (!yAxisKey && numericKeys.length > 0) {
          const preferred = ['密度', '熔体流动速率', '拉伸强度'].find(k => numericKeys.includes(k));
          setYAxisKey(preferred || numericKeys[0]);
      }
  }, [numericKeys, yAxisKey]);

  useEffect(() => {
    setXMin(''); setXMax(''); setYMin(''); setYMax('');
  }, [xAxisKey, yAxisKey, chartType]);

  // 3. Prepare Chart Data
  const chartData = useMemo(() => {
    return data.map(p => {
        const item: any = {
            id: p.id,
            gradeName: p.gradeName,
            manufacturer: p.manufacturer,
            tooltipTitle: `${p.manufacturer} - ${p.gradeName}`
        };
        Object.entries(p.properties).forEach(([k, v]) => {
            const num = Number(v.value);
            item[k] = !isNaN(num) && v.value !== '' ? num : v.value;
        });
        return item;
    });
  }, [data]);

  // 4. Calculate Linear Regression for Trendline
  const trendlineSegment = useMemo(() => {
    if (!showTrendline || chartType !== 'scatter') return null;

    const validPoints = chartData.filter(d => 
        typeof d[xAxisKey] === 'number' && typeof d[yAxisKey] === 'number'
    );

    if (validPoints.length < 2) return null;

    const n = validPoints.length;
    let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
    let minX = Infinity, maxX = -Infinity;

    validPoints.forEach(p => {
        const x = p[xAxisKey];
        const y = p[yAxisKey];
        sumX += x; sumY += y; sumXY += x * y; sumX2 += x * x;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
    });

    const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
    const intercept = (sumY - slope * sumX) / n;

    return [
        { [xAxisKey]: minX, [yAxisKey]: slope * minX + intercept, isTrend: true },
        { [xAxisKey]: maxX, [yAxisKey]: slope * maxX + intercept, isTrend: true }
    ];
  }, [chartData, xAxisKey, yAxisKey, showTrendline, chartType]);

  const dashArray = useMemo(() => {
    if (trendlineStyle === 'dashed') return '5 5';
    if (trendlineStyle === 'dotted') return '2 2';
    return '0';
  }, [trendlineStyle]);

  // 5. Determine Unique Groups
  const uniqueGroups = useMemo(() => {
    if (!groupByKey) return [];
    const groups = new Set<string>();
    chartData.forEach((item: any) => {
        groups.add(String(item[groupByKey] || 'Unknown'));
    });
    return Array.from(groups).sort();
  }, [groupByKey, chartData]);

  useEffect(() => {
    if (uniqueGroups.length > 0) {
        setGroupColors(prev => {
            const next = { ...prev };
            uniqueGroups.forEach((group, index) => {
                if (!next[group]) next[group] = DEFAULT_PALETTE[index % DEFAULT_PALETTE.length];
            });
            return next;
        });
    }
  }, [uniqueGroups]);

  const updateGroupColor = (group: string, color: string) => {
    setGroupColors(prev => ({ ...prev, [group]: color }));
  };

  const handleDownload = async (type: 'json' | 'png') => {
    if (type === 'json') {
        const blob = new Blob([JSON.stringify(chartData, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = 'resindb_data.json'; a.click();
    } else if (type === 'png' && chartRef.current) {
        const canvas = await html2canvas(chartRef.current, { backgroundColor: theme === 'dark' ? '#020617' : '#ffffff' });
        const a = document.createElement('a');
        a.href = canvas.toDataURL('image/png'); a.download = 'resindb_chart.png'; a.click();
    }
  };

  const CustomTooltipContent = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const d = payload[0].payload;
      if (d.isTrend) return null;
      const product = data.find(p => p.id === d.id);
      if (!product) return null;

      const additionalProps = Object.entries(product.properties)
        .filter(([k]) => k !== xAxisKey && k !== yAxisKey && k !== groupByKey)
        .sort((a, b) => {
           const common = ['密度', '熔体流动速率', '拉伸强度', '应用', '类型'];
           return (common.includes(a[0]) ? 1 : 0) - (common.includes(b[0]) ? 1 : 0);
        })
        .slice(0, 3);

      return (
        <div className="p-4 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-2xl min-w-[220px] animate-in fade-in zoom-in-95 duration-200">
          <div className="flex items-center justify-between gap-4 mb-1">
            <p className="font-bold text-slate-800 dark:text-white truncate text-sm">{product.gradeName}</p>
            {groupByKey && d[groupByKey] && (
               <span className="text-[9px] px-2 py-0.5 rounded-full text-white font-bold" style={{ backgroundColor: groupColors[String(d[groupByKey])] }}>
                  {d[groupByKey]}
               </span>
            )}
          </div>
          <p className="text-[10px] text-slate-500 dark:text-slate-400 mb-3">{product.manufacturer}</p>
          <div className="space-y-1.5 pt-2 border-t border-slate-100 dark:border-slate-800">
             <p className="text-xs flex justify-between gap-4">
                <span className="text-slate-500">{tProp(yAxisKey)}:</span>
                <span className="font-mono font-bold text-emerald-600 dark:text-emerald-400">
                    {product.properties[yAxisKey]?.value ?? d[yAxisKey]}
                    {product.properties[yAxisKey]?.unit ? ` ${product.properties[yAxisKey].unit}` : ''}
                </span>
             </p>
             {chartType === 'scatter' && (
               <p className="text-xs flex justify-between gap-4">
                  <span className="text-slate-500">{tProp(xAxisKey)}:</span>
                  <span className="font-mono font-bold text-blue-600 dark:text-blue-400">
                      {product.properties[xAxisKey]?.value ?? d[xAxisKey]}
                      {product.properties[xAxisKey]?.unit ? ` ${product.properties[xAxisKey].unit}` : ''}
                  </span>
               </p>
             )}
          </div>
          {additionalProps.length > 0 && (
            <div className="mt-3 pt-3 border-t border-slate-100 dark:border-slate-800 space-y-1.5">
              <p className="text-[9px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1">{t('details')}</p>
              {additionalProps.map(([key, prop]) => (
                <p key={key} className="text-[11px] flex justify-between gap-4 text-slate-600 dark:text-slate-300">
                  <span className="opacity-70 truncate max-w-[120px]">{tProp(key)}:</span>
                  <span className="font-medium whitespace-nowrap">
                    {prop.value} {prop.unit || ''}
                  </span>
                </p>
              ))}
            </div>
          )}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="flex flex-col md:flex-row h-full gap-4 overflow-hidden">
      {/* Settings Panel */}
      <div className={`flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl transition-all duration-300 shrink-0 overflow-hidden ${showConfig ? 'w-full md:w-80 opacity-100' : 'w-0 opacity-0 md:border-none'}`}>
        <div className="p-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-950/50">
          <div className="flex items-center gap-2 font-bold text-sm text-slate-700 dark:text-slate-200 uppercase tracking-wider">
            <Settings size={16} className="text-emerald-500" />
            {t('chartConfig')}
          </div>
          <button onClick={() => setShowConfig(false)} className="md:hidden text-slate-400 hover:text-slate-600">
            <X size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-5 custom-scrollbar space-y-6">
          <div className="space-y-3">
             <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <LayoutDashboard size={12} /> {t('chartType')}
             </label>
             <div className="flex gap-2">
                <button onClick={() => setChartType('bar')} className={`flex-1 flex flex-col items-center gap-2 p-3 rounded-xl border-2 transition-all ${chartType === 'bar' ? 'border-emerald-500 bg-emerald-50/50 dark:bg-emerald-900/20 text-emerald-600' : 'border-slate-100 dark:border-slate-800 text-slate-400'}`}>
                  <BarChart2 size={24} /> <span className="text-[10px] font-bold uppercase">{t('barChart')}</span>
                </button>
                <button onClick={() => setChartType('scatter')} className={`flex-1 flex flex-col items-center gap-2 p-3 rounded-xl border-2 transition-all ${chartType === 'scatter' ? 'border-emerald-500 bg-emerald-50/50 dark:bg-emerald-900/20 text-emerald-600' : 'border-slate-100 dark:border-slate-800 text-slate-400'}`}>
                  <ScatterIcon size={24} /> <span className="text-[10px] font-bold uppercase">{t('scatterChart')}</span>
                </button>
             </div>
          </div>

          <div className="space-y-4 pt-2 border-t border-slate-100 dark:border-slate-800">
            <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <RotateCcw size={12} /> {t('axisMapping')}
            </label>
            <div className="space-y-3">
              <div className="space-y-1.5">
                <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('yAxis')}</span>
                <select value={yAxisKey} onChange={(e) => setYAxisKey(e.target.value)} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm outline-none">
                  {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                </select>
              </div>
              {chartType === 'scatter' && (
                <div className="space-y-1.5">
                    <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('xAxis')}</span>
                    <select value={xAxisKey} onChange={(e) => setXAxisKey(e.target.value)} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm outline-none">
                        {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                    </select>
                </div>
              )}
            </div>
          </div>

          {chartType === 'scatter' && (
            <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
               <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                  <Maximize size={12} /> {t('axisMapping')} (Limits)
               </label>
               <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1"><span className="text-[10px] text-slate-500 font-bold uppercase">{t('xAxisMin')}</span>
                    <input type="number" value={xMin} onChange={(e) => setXMin(e.target.value === '' ? '' : Number(e.target.value))} placeholder="Auto" className="w-full px-2 py-1 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded text-xs outline-none" />
                  </div>
                  <div className="space-y-1"><span className="text-[10px] text-slate-500 font-bold uppercase">{t('xAxisMax')}</span>
                    <input type="number" value={xMax} onChange={(e) => setXMax(e.target.value === '' ? '' : Number(e.target.value))} placeholder="Auto" className="w-full px-2 py-1 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded text-xs outline-none" />
                  </div>
               </div>
            </div>
          )}

          <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
             <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <Palette size={12} /> {t('styleGrouping')}
             </label>
             <div className="space-y-1.5">
               <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('groupBy')}</span>
               <select value={groupByKey} onChange={(e) => setGroupByKey(e.target.value)} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm outline-none">
                 <option value="">{t('none')}</option>
                 {categoricalKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
               </select>
             </div>
             {groupByKey && uniqueGroups.map(group => (
                <div key={group} className="flex items-center justify-between gap-4 animate-in fade-in slide-in-from-left-2">
                    <span className="text-[10px] font-bold text-slate-500 truncate flex-1">{group}</span>
                    <div className="flex items-center gap-2">
                        <input type="color" value={groupColors[group] || '#10b981'} onChange={(e) => updateGroupColor(group, e.target.value)} className="w-6 h-6 p-0 border-none bg-transparent cursor-pointer" />
                        <Pipette size={12} className="text-slate-400" />
                    </div>
                </div>
             ))}
          </div>

          {chartType === 'scatter' && (
            <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
               <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                  <TrendingUp size={12} /> {t('trendline')}
               </label>
               <label className="flex items-center gap-3 cursor-pointer group">
                  <div className={`w-8 h-4 rounded-full relative transition-colors ${showTrendline ? 'bg-emerald-500' : 'bg-slate-200 dark:bg-slate-700'}`}>
                      <div className={`absolute top-0.5 w-3 h-3 bg-white rounded-full transition-transform ${showTrendline ? 'translate-x-4' : ''}`}></div>
                      <input type="checkbox" checked={showTrendline} onChange={() => setShowTrendline(!showTrendline)} className="hidden" />
                  </div>
                  <span className="text-sm text-slate-600 dark:text-slate-300">{t('showTrendline')}</span>
               </label>
            </div>
          )}

          <div className="pt-4 border-t border-slate-100 dark:border-slate-800 grid grid-cols-2 gap-2">
            <button onClick={() => handleDownload('json')} className="flex items-center justify-center gap-2 p-2 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 rounded-lg text-[10px] font-bold text-slate-600 transition-colors uppercase">
              <FileJson size={14} /> JSON
            </button>
            <button onClick={() => handleDownload('png')} className="flex items-center justify-center gap-2 p-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-[10px] font-bold transition-colors uppercase shadow-md shadow-emerald-500/20">
              <ImageIcon size={14} /> PNG
            </button>
          </div>
        </div>
      </div>

      {/* Chart Canvas Area */}
      <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl relative min-h-[400px]">
        {!showConfig && (
            <button onClick={() => setShowConfig(true)} className="absolute top-4 left-4 z-10 p-2.5 bg-white dark:bg-slate-800 border border-slate-200 rounded-xl text-emerald-500 shadow-lg">
                <Settings size={20} />
            </button>
        )}
        <div className="flex-1 p-6 flex flex-col min-h-0" ref={chartRef}>
            <div className="mb-6 flex justify-between items-center gap-4">
               <h2 className="text-lg font-bold text-slate-800 dark:text-white flex items-center gap-2">
                  {chartType === 'bar' ? <BarChart2 size={20} className="text-emerald-500" /> : <ScatterIcon size={20} className="text-emerald-500" />}
                  {tProp(yAxisKey)} vs {chartType === 'bar' ? tProp('牌号') : tProp(xAxisKey)}
               </h2>
               {groupByKey && (
                 <div className="flex gap-2">
                    {uniqueGroups.slice(0, 4).map(g => (
                        <div key={g} className="flex items-center gap-1.5 px-2 py-0.5 bg-slate-50 dark:bg-slate-800 rounded-full border border-slate-100 dark:border-slate-700">
                           <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: groupColors[g] }}></div>
                           <span className="text-[9px] font-bold text-slate-500">{g}</span>
                        </div>
                    ))}
                 </div>
               )}
            </div>

            <div className="flex-1 w-full min-h-0">
                <ResponsiveContainer width="100%" height="100%">
                    {chartType === 'bar' ? (
                        <BarChart data={chartData} margin={{ top: 10, right: 30, left: 0, bottom: 40 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis dataKey="gradeName" angle={-45} textAnchor="end" interval={0} height={60} fontSize={10} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} />
                            <YAxis fontSize={10} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} />
                            <Tooltip cursor={{ fill: 'rgba(16, 185, 129, 0.05)' }} content={<CustomTooltipContent />} />
                            <Bar dataKey={yAxisKey} radius={[4, 4, 0, 0]} animationDuration={1000}>
                                {chartData.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={groupByKey ? groupColors[String(entry[groupByKey])] : DEFAULT_PALETTE[index % DEFAULT_PALETTE.length]} />
                                ))}
                            </Bar>
                        </BarChart>
                    ) : (
                        <ComposedChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis type="number" dataKey={xAxisKey} name={tProp(xAxisKey)} fontSize={10} domain={[xMin === '' ? 'auto' : xMin, xMax === '' ? 'auto' : xMax]} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} label={{ value: tProp(xAxisKey), position: 'bottom', offset: 0, fontSize: 10, fill: '#64748b' }} />
                            <YAxis type="number" dataKey={yAxisKey} name={tProp(yAxisKey)} fontSize={10} domain={[yMin === '' ? 'auto' : yMin, yMax === '' ? 'auto' : yMax]} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} label={{ value: tProp(yAxisKey), angle: -90, position: 'insideLeft', offset: 10, fontSize: 10, fill: '#64748b' }} />
                            <ZAxis range={[60, 400]} />
                            <Tooltip cursor={{ strokeDasharray: '3 3' }} content={<CustomTooltipContent />} />
                            <Scatter name="Resin Samples" data={chartData} animationDuration={1500}>
                                {chartData.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={groupByKey ? groupColors[String(entry[groupByKey])] : '#10b981'} strokeWidth={1} stroke="#ffffff" />
                                ))}
                            </Scatter>
                            {trendlineSegment && (
                                <Line type="monotone" data={trendlineSegment} dataKey={yAxisKey} stroke={trendlineColor} strokeWidth={trendlineWidth} strokeDasharray={dashArray} dot={false} activeDot={false} legendType="none" />
                            )}
                        </ComposedChart>
                    )}
                </ResponsiveContainer>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  ReferenceLine,
  Cell,
  LabelList,
  Line,
  ComposedChart,
  ZAxis
} from 'recharts';
import { Settings, Download, ChevronUp, BarChart2, ScatterChart as ScatterIcon, TrendingUp, Palette, FileJson, Image as ImageIcon, RotateCcw, LayoutDashboard, Pipette, Maximize, X, Filter, Plus, Trash2 } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

interface PlotFilter {
  id: string;
  key: string;
  operator: '>' | '<' | '>=' | '<=' | 'between';
  value: number | '';
  value2: number | '';
}

const DEFAULT_PALETTE = [
  '#10b981', // Emerald
  '#3b82f6', // Blue
  '#f59e0b', // Amber
  '#ef4444', // Red
  '#8b5cf6', // Violet
  '#ec4899', // Pink
  '#06b6d4', // Cyan
  '#84cc16', // Lime
  '#f97316', // Orange
  '#6366f1', // Indigo
];

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const { t, tProp } = useLanguage();
  const { theme } = useTheme();
  const chartRef = useRef<HTMLDivElement>(null);

  const [showConfig, setShowConfig] = useState(true);
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('gradeName');
  const [yAxisKey, setYAxisKey] = useState<string>('');

  // Manual Axis Limits
  const [xMin, setXMin] = useState<number | ''>('');
  const [xMax, setXMax] = useState<number | ''>('');
  const [yMin, setYMin] = useState<number | ''>('');
  const [yMax, setYMax] = useState<number | ''>('');

  // Plot Filters
  const [plotFilters, setPlotFilters] = useState<PlotFilter[]>([]);

  // Trendline State
  const [showTrendline, setShowTrendline] = useState(false);
  const [trendlineColor, setTrendlineColor] = useState('#ef4444');
  const [trendlineWidth, setTrendlineWidth] = useState(2);
  const [trendlineStyle, setTrendlineStyle] = useState<'solid' | 'dashed' | 'dotted'>('dashed');

  // Grouping & Color State
  const [groupByKey, setGroupByKey] = useState<string>('');
  const [groupColors, setGroupColors] = useState<Record<string, string>>({});

  // 1. Identify Numeric Keys (for Axes and Filtering)
  const numericKeys = useMemo(() => {
     const keys = new Set<string>();
     data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
           if (typeof v.value === 'number' || (!isNaN(Number(v.value)) && v.value !== '')) {
               keys.add(k);
           }
        });
     });
     return Array.from(keys).sort();
  }, [data]);

  // 2. Identify Categorical Keys (for Grouping)
  const categoricalKeys = useMemo(() => {
    const keys = new Set<string>(['manufacturer']); // Always available
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (typeof v.value === 'string' && isNaN(Number(v.value))) {
                keys.add(k);
            }
        });
    });
    return Array.from(keys).sort();
  }, [data]);

  useEffect(() => {
      if (!yAxisKey && numericKeys.length > 0) {
          const preferred = ['密度', '熔体流动速率', '拉伸强度'].find(k => numericKeys.includes(k));
          setYAxisKey(preferred || numericKeys[0]);
      }
  }, [numericKeys, yAxisKey]);

  useEffect(() => {
    setXMin(''); setXMax(''); setYMin(''); setYMax('');
  }, [xAxisKey, yAxisKey, chartType]);

  // 3. Prepare Chart Data (with Filters applied)
  const chartData = useMemo(() => {
    const filtered = data.filter(product => {
        return plotFilters.every(f => {
            if (!f.key || f.value === '') return true;
            const prop = product.properties[f.key];
            if (!prop || prop.value === undefined || prop.value === null || prop.value === '') return false;
            const val = Number(prop.value);
            if (isNaN(val)) return false;

            const v1 = Number(f.value);
            const v2 = f.value2 !== '' ? Number(f.value2) : Infinity;

            switch (f.operator) {
                case '>': return val > v1;
                case '<': return val < v1;
                case '>=': return val >= v1;
                case '<=': return val <= v1;
                case 'between': return val >= v1 && val <= v2;
                default: return true;
            }
        });
    });

    return filtered.map(p => {
        const item: any = {
            id: p.id,
            gradeName: p.gradeName,
            manufacturer: p.manufacturer,
            tooltipTitle: `${p.manufacturer} - ${p.gradeName}`
        };
        Object.entries(p.properties).forEach(([k, v]) => {
            const num = Number(v.value);
            item[k] = !isNaN(num) && v.value !== '' ? num : v.value;
        });
        return item;
    });
  }, [data, plotFilters]);

  // 4. Calculate Linear Regression for Trendline
  const trendlineSegment = useMemo(() => {
    if (!showTrendline || chartType !== 'scatter') return null;

    const validPoints = chartData.filter(d => 
        typeof d[xAxisKey] === 'number' && typeof d[yAxisKey] === 'number'
    );

    if (validPoints.length < 2) return null;

    const n = validPoints.length;
    let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
    let minX = Infinity, maxX = -Infinity;

    validPoints.forEach(p => {
        const x = p[xAxisKey];
        const y = p[yAxisKey];
        sumX += x; sumY += y; sumXY += x * y; sumX2 += x * x;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
    });

    const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
    const intercept = (sumY - slope * sumX) / n;

    return [
        { [xAxisKey]: minX, [yAxisKey]: slope * minX + intercept, isTrend: true },
        { [xAxisKey]: maxX, [yAxisKey]: slope * maxX + intercept, isTrend: true }
    ];
  }, [chartData, xAxisKey, yAxisKey, showTrendline, chartType]);

  const dashArray = useMemo(() => {
    if (trendlineStyle === 'dashed') return '5 5';
    if (trendlineStyle === 'dotted') return '2 2';
    return '0';
  }, [trendlineStyle]);

  // 5. Determine Unique Groups
  const uniqueGroups = useMemo(() => {
    if (!groupByKey) return [];
    const groups = new Set<string>();
    chartData.forEach((item: any) => {
        groups.add(String(item[groupByKey] || 'Unknown'));
    });
    return Array.from(groups).sort();
  }, [groupByKey, chartData]);

  useEffect(() => {
    if (uniqueGroups.length > 0) {
        setGroupColors(prev => {
            const next = { ...prev };
            uniqueGroups.forEach((group, index) => {
                if (!next[group]) next[group] = DEFAULT_PALETTE[index % DEFAULT_PALETTE.length];
            });
            return next;
        });
    }
  }, [uniqueGroups]);

  const updateGroupColor = (group: string, color: string) => {
    setGroupColors(prev => ({ ...prev, [group]: color }));
  };

  const handleDownload = async (type: 'json' | 'png') => {
    if (type === 'json') {
        const blob = new Blob([JSON.stringify(chartData, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = 'resindb_data.json'; a.click();
    } else if (type === 'png' && chartRef.current) {
        const canvas = await html2canvas(chartRef.current, { backgroundColor: theme === 'dark' ? '#020617' : '#ffffff' });
        const a = document.createElement('a');
        a.href = canvas.toDataURL('image/png'); a.download = 'resindb_chart.png'; a.click();
    }
  };

  const addPlotFilter = () => {
    const newFilter: PlotFilter = {
        id: Date.now().toString(),
        key: numericKeys[0] || '',
        operator: '>=',
        value: '',
        value2: ''
    };
    setPlotFilters([...plotFilters, newFilter]);
  };

  const updatePlotFilter = (id: string, updates: Partial<PlotFilter>) => {
    setPlotFilters(prev => prev.map(f => f.id === id ? { ...f, ...updates } : f));
  };

  const removePlotFilter = (id: string) => {
    setPlotFilters(prev => prev.filter(f => f.id !== id));
  };

  const CustomTooltipContent = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const d = payload[0].payload;
      if (d.isTrend) return null;
      const product = data.find(p => p.id === d.id);
      if (!product) return null;

      const additionalProps = Object.entries(product.properties)
        .filter(([k]) => k !== xAxisKey && k !== yAxisKey && k !== groupByKey)
        .sort((a, b) => {
           const common = ['密度', '熔体流动速率', '拉伸强度', '应用', '类型'];
           return (common.includes(a[0]) ? 1 : 0) - (common.includes(b[0]) ? 1 : 0);
        })
        .slice(0, 3);

      return (
        <div className="p-4 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-2xl min-w-[220px] animate-in fade-in zoom-in-95 duration-200">
          <div className="flex items-center justify-between gap-4 mb-1">
            <p className="font-bold text-slate-800 dark:text-white truncate text-sm">{product.gradeName}</p>
