                                    <Cell key={`cell-${index}`} fill={groupByKey ? groupColors[String(entry[groupByKey])] : DEFAULT_PALETTE[index % DEFAULT_PALETTE.length]} />
                                ))}
                            </Bar>
                        </BarChart>
                    ) : (
                        <ComposedChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis type="number" dataKey={xAxisKey} name={tProp(xAxisKey)} fontSize={10} domain={[xMin === '' ? 'auto' : xMin, xMax === '' ? 'auto' : xMax]} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} label={{ value: tProp(xAxisKey), position: 'bottom', offset: 0, fontSize: 10, fill: '#64748b' }} />
                            <YAxis type="number" dataKey={yAxisKey} name={tProp(yAxisKey)} fontSize={10} domain={[yMin === '' ? 'auto' : yMin, yMax === '' ? 'auto' : yMax]} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} label={{ value: tProp(yAxisKey), angle: -90, position: 'insideLeft', offset: 10, fontSize: 10, fill: '#64748b' }} />
                            <ZAxis range={[60, 400]} />
                            <Tooltip cursor={{ strokeDasharray: '3 3' }} content={<CustomTooltipContent />} />
                            <Scatter name="Resin Samples" data={chartData} animationDuration={1500}>
                                {chartData.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={groupByKey ? groupColors[String(entry[groupByKey])] : '#10b981'} strokeWidth={1} stroke="#ffffff" />
                                ))}
                            </Scatter>
                            {trendlineSegment && (
                                <Line type="monotone" data={trendlineSegment} dataKey={yAxisKey} stroke={trendlineColor} strokeWidth={trendlineWidth} strokeDasharray={dashArray} dot={false} activeDot={false} legendType="none" />
                            )}
                        </ComposedChart>
                    )}
                </ResponsiveContainer>
            </div>
        </div>
      </div>
    </div>
  );
};

