                <p className="text-2xl font-bold text-slate-900 dark:text-white pl-1">{stats.count}</p>
            </div>

            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 p-4 rounded-xl shadow-sm hover:shadow-md transition-shadow relative overflow-hidden group">
                <div className="absolute top-0 right-0 p-3 opacity-10 group-hover:opacity-20 transition-opacity">
                     <Factory size={64} className="text-indigo-500" />
                </div>
                <div className="flex items-center gap-3 mb-2">
                    <div className="w-8 h-8 rounded-lg bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 dark:text-indigo-400 flex items-center justify-center">
                        <Factory size={16} />
                    </div>
                    <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">{t('manufacturers')}</p>
                </div>
                <p className="text-2xl font-bold text-slate-900 dark:text-white pl-1">{stats.manufacturers}</p>
            </div>

