import React, { useState, useMemo, useEffect } from 'react';
import { Product, ColumnConfig, SortConfig } from '../types';
import { MoreHorizontal, FileText, Factory, CalendarClock, Edit, Trash2, CheckSquare, Square, MinusSquare, ArrowUp, ArrowDown, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight, ArrowUpDown, ListChecks, Tags } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { EditProductModal } from './EditProductModal';
import { DeleteConfirmationModal } from './DeleteConfirmationModal';
import { BatchEditModal } from './BatchEditModal';
import { CATEGORY_TREE } from '../constants';

interface DataGridProps {
  data: Product[];
  columns: ColumnConfig[];
  isLoading: boolean;
  onDelete: (ids: string[]) => void;
  onUpdate: (product: Product) => void;
  onBatchUpdate: (ids: string[], updates: Partial<Product>) => void;
}

export const DataGrid: React.FC<DataGridProps> = ({ data, columns, isLoading, onDelete, onUpdate, onBatchUpdate }) => {
  const { t, tProp, language } = useLanguage();
  const visibleColumns = columns.filter((c) => c.visible);

  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [isBatchEditing, setIsBatchEditing] = useState(false);
  const [deletingIds, setDeletingIds] = useState<string[] | null>(null);
  const [sortConfig, setSortConfig] = useState<SortConfig | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(15);

  useEffect(() => { setCurrentPage(1); }, [data.length]);

  const handleSort = (key: string) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') direction = 'desc';
    setSortConfig({ key, direction });
  };

  const sortedData = useMemo(() => {
    if (!sortConfig) return data;
    return [...data].sort((a, b) => {
      const getVal = (p: Product, k: string) => {
        if (k === 'gradeName') return p.gradeName;
        if (k === 'manufacturer') return p.manufacturer;
        if (k === 'updatedAt') return p.updatedAt;
        const prop = p.properties[k];
        return prop && prop.value !== undefined ? prop.value : '';
      };
      const valA = getVal(a, sortConfig.key);
      const valB = getVal(b, sortConfig.key);
      if (typeof valA === 'number' && typeof valB === 'number') return sortConfig.direction === 'asc' ? valA - valB : valB - valA;
      return sortConfig.direction === 'asc' ? String(valA).localeCompare(String(valB)) : String(valB).localeCompare(String(valA));
    });
  }, [data, sortConfig]);

  const paginatedData = useMemo(() => {
    const startIndex = (currentPage - 1) * pageSize;
    return sortedData.slice(startIndex, startIndex + pageSize);
  }, [sortedData, currentPage, pageSize]);

  const totalPages = Math.ceil(sortedData.length / pageSize);

  const columnMaxValues = useMemo(() => {
    const maxVals: Record<string, number> = {};
    visibleColumns.forEach(col => {
       if (['gradeName', 'manufacturer', 'updatedAt'].includes(col.key)) return;
       let max = 0;
       data.forEach(p => {
           const v = p.properties[col.key]?.value;
           if (typeof v === 'number' && v > max) max = v;
       });
       if (max > 0) maxVals[col.key] = max;
    });
    return maxVals;
  }, [data, visibleColumns]);

  const isAllSelected = paginatedData.length > 0 && paginatedData.every(p => selectedIds.has(p.id));
  const isIndeterminate = paginatedData.some(p => selectedIds.has(p.id)) && !isAllSelected;

  const toggleSelectAll = () => {
    const newSet = new Set(selectedIds);
    if (isAllSelected) paginatedData.forEach(p => newSet.delete(p.id));
    else paginatedData.forEach(p => newSet.add(p.id));
    setSelectedIds(newSet);
  };

  const getCategoryNames = (ids: string[]) => {
      const names: string[] = [];
      const traverse = (cats: any[]) => {
          cats.forEach(c => {
              if (ids.includes(c.id)) names.push(language === 'en' && c.nameEn ? c.nameEn : c.name);
              if (c.children) traverse(c.children);
          });
      };
      traverse(CATEGORY_TREE);
      return Array.from(new Set(names));
  };

  if (isLoading) return <div className="flex flex-col items-center justify-center h-64 text-slate-400 animate-pulse">...</div>;

  return (
    <>
    <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden flex flex-col h-full relative ring-1 ring-slate-900/5 transition-colors">

      {/* Batch Action Toolbar */}
      <div className={`absolute top-0 left-0 right-0 z-40 h-[52px] bg-emerald-600 dark:bg-emerald-600 backdrop-blur-md flex items-center justify-between px-4 transition-all duration-300 transform ${selectedIds.size > 0 ? 'translate-y-0 opacity-100' : '-translate-y-full opacity-0 pointer-events-none'}`}>
          <div className="flex items-center gap-3 text-sm font-bold text-white">
              <CheckSquare size={18} />
              <span>{selectedIds.size} {t('selected')}</span>
          </div>
          <div className="flex gap-2">
              <button onClick={() => setIsBatchEditing(true)} className="flex items-center gap-1.5 px-3 py-1.5 bg-white/20 hover:bg-white/30 text-white rounded-lg text-xs font-bold transition-all"><ListChecks size={14} /> 批量编辑</button>
              <button onClick={() => setDeletingIds(Array.from(selectedIds))} className="flex items-center gap-1.5 px-3 py-1.5 bg-rose-500 hover:bg-rose-400 text-white rounded-lg text-xs font-bold transition-all"><Trash2 size={14} /> {t('deleteSelected')}</button>
          </div>
      </div>

      <div className="overflow-x-auto overflow-y-auto custom-scrollbar flex-1 relative">
        <table className="w-full text-sm text-left border-collapse">
          <thead className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase bg-slate-50/80 dark:bg-slate-950/80 sticky top-0 z-30 backdrop-blur-md border-b border-slate-100 dark:border-slate-800">
            <tr>
              <th className="w-12 px-4 py-3"><div onClick={toggleSelectAll} className="cursor-pointer flex justify-center">{isAllSelected ? <CheckSquare size={16} className="text-emerald-500"/> : (isIndeterminate ? <MinusSquare size={16} className="text-emerald-500"/> : <Square size={16}/>)}</div></th>
              {visibleColumns.map((col) => (
                <th key={col.key} onClick={() => handleSort(col.key)} className={`px-5 py-3 whitespace-nowrap cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors ${columnMaxValues[col.key] ? 'text-right' : 'text-left'}`}>
                  <div className={`flex items-center gap-1.5 ${columnMaxValues[col.key] ? 'justify-end' : 'justify-start'}`}>
                    <span className={sortConfig?.key === col.key ? 'text-emerald-500' : ''}>{tProp(col.label)}</span>
                    {sortConfig?.key === col.key && (sortConfig.direction === 'asc' ? <ArrowUp size={10} /> : <ArrowDown size={10} />)}
                  </div>
                </th>
              ))}
              <th className="px-5 py-3 text-right sticky right-0 z-40 bg-slate-50/90 dark:bg-slate-950/90 shadow-[-4px_0_12px_-4px_rgba(0,0,0,0.1)]">{t('actions')}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
            {paginatedData.map((product) => (
              <tr key={product.id} className={`group hover:bg-slate-50 dark:hover:bg-slate-800/40 transition-colors ${selectedIds.has(product.id) ? 'bg-emerald-50/30 dark:bg-emerald-900/10' : ''}`}>
                <td className="px-4 py-3"><div onClick={() => { const s = new Set(selectedIds); if(s.has(product.id)) s.delete(product.id); else s.add(product.id); setSelectedIds(s); }} className="cursor-pointer flex justify-center text-slate-300 dark:text-slate-700 group-hover:text-emerald-500">{selectedIds.has(product.id) ? <CheckSquare size={16} className="text-emerald-500"/> : <Square size={16}/>}</div></td>
                {visibleColumns.map((col) => {
                  const isNum = !!columnMaxValues[col.key];
                  const barWidth = isNum ? Math.min((Number(product.properties[col.key]?.value || 0) / columnMaxValues[col.key]) * 100, 100) : 0;

                  return (
                    <td key={col.key} className={`px-5 py-3 whitespace-nowrap relative ${isNum ? 'text-right font-mono' : ''}`}>
                      {col.key === 'gradeName' ? (
                        <div className="flex flex-col">
                            <span className="font-bold text-slate-800 dark:text-slate-100">{product.gradeName}</span>
                            <span className="text-[9px] text-slate-400 flex items-center gap-1 uppercase tracking-wider font-semibold"><Factory size={10} /> {product.manufacturer}</span>
                        </div>
                      ) : col.key === 'manufacturer' ? (
                        <div className="flex flex-wrap gap-1 max-w-[200px]">
                            {getCategoryNames(product.categoryIds).slice(0, 3).map(name => (
                                <span key={name} className="px-1.5 py-0.5 bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 rounded text-[9px] font-bold border border-slate-200 dark:border-slate-700">{name}</span>
                            ))}
                            {product.categoryIds.length > 3 && <span className="text-[9px] text-slate-400">+{product.categoryIds.length - 3}</span>}
                        </div>
                      ) : isNum ? (
                        <>
                          <div className="absolute bottom-1 right-5 h-0.5 bg-emerald-500/10 rounded-full w-2/3">
                             <div className="h-full bg-emerald-500/40 rounded-full" style={{ width: `${barWidth}%` }}></div>
                          </div>
                          <span className="relative z-10">{product.properties[col.key]?.value} <span className="text-[9px] text-slate-400 font-sans">{product.properties[col.key]?.unit}</span></span>
                        </>
                      ) : (
                        <span className="text-slate-600 dark:text-slate-400">{String(product.properties[col.key]?.value || '-')}</span>
                      )}
                    </td>
                  );
                })}
                <td className="px-5 py-3 text-right sticky right-0 bg-white dark:bg-slate-900 group-hover:bg-slate-50 transition-colors z-20">
                   <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={() => setEditingProduct(product)} className="p-1.5 hover:text-blue-500 transition-colors"><Edit size={14}/></button>
                      <button onClick={() => setDeletingIds([product.id])} className="p-1.5 hover:text-rose-500 transition-colors"><Trash2 size={14}/></button>
                   </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      <div className="p-3 border-t border-slate-100 dark:border-slate-800 flex justify-between items-center text-xs text-slate-500 bg-slate-50/50 dark:bg-slate-950/30">
          <div>{t('showing')} {(currentPage - 1) * pageSize + 1} - {Math.min(currentPage * pageSize, data.length)} / {data.length}</div>
          <div className="flex gap-2 items-center">
              <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} className="p-1.5 rounded bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition-colors"><ChevronLeft size={14} /></button>
              <span className="font-bold">{currentPage} / {totalPages}</span>
              <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} className="p-1.5 rounded bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition-colors"><ChevronRight size={14} /></button>
          </div>
      </div>
    </div>

    <EditProductModal isOpen={!!editingProduct} onClose={() => setEditingProduct(null)} product={editingProduct} onSave={onUpdate} />
    <BatchEditModal isOpen={isBatchEditing} onClose={() => setIsBatchEditing(false)} selectedProducts={data.filter(p => selectedIds.has(p.id))} onSave={(ids, updates) => { onBatchUpdate(ids, updates); setSelectedIds(new Set()); }} />
    <DeleteConfirmationModal isOpen={!!deletingIds} onClose={() => setDeletingIds(null)} onConfirm={() => { onDelete(deletingIds!); setSelectedIds(new Set()); }} productNames={deletingIds?.map(id => data.find(p => p.id === id)?.gradeName || '') || []} />
    </>
  );
};

import React, { useState } from 'react';
import { X, FileSpreadsheet, UploadCloud, CheckCircle, AlertCircle, Search, ShieldCheck, Database, Filter } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

interface ImportModalProps {
  isOpen: boolean;
  onClose: () => void;
  onImport?: () => void;
}

export const ImportModal: React.FC<ImportModalProps> = ({ isOpen, onClose, onImport }) => {
  const [step, setStep] = useState<1 | 2 | 3 | 4>(1);
  const [isDragging, setIsDragging] = useState(false);
  const { t } = useLanguage();

  if (!isOpen) return null;

  const handleStartProcess = () => {
    setStep(2);
    setTimeout(() => setStep(3), 1200); // 1.2s logic to move to Cleaning step
  };

  const handleFinish = () => {
      if (onImport) onImport();
      onClose();
      setTimeout(() => setStep(1), 300);
  };

  return (
    <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="w-full max-w-xl bg-white dark:bg-slate-900 rounded-3xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200 border border-slate-200 dark:border-slate-800 flex flex-col">
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-950/50">
          <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100 flex items-center gap-2">
            <Database className="text-emerald-600" size={20} />
            {t('importTitle')}
          </h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 transition-colors"><X size={20} /></button>
        </div>

        <div className="p-8">
          {step === 1 && (
            <div 
                className={`border-2 border-dashed rounded-3xl p-12 flex flex-col items-center justify-center text-center transition-all ${isDragging ? 'border-emerald-500 bg-emerald-50/50' : 'border-slate-200 hover:border-emerald-300 bg-slate-50/30'}`}
                onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
                onDragLeave={() => setIsDragging(false)}
                onDrop={(e) => { e.preventDefault(); setIsDragging(false); handleStartProcess(); }}
            >
              <div className="w-20 h-20 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 rounded-full flex items-center justify-center mb-6 shadow-inner">
                <UploadCloud size={40} />
              </div>
              <h4 className="text-slate-900 dark:text-slate-100 font-bold mb-2">{t('dragDrop')}</h4>
              <p className="text-slate-500 text-sm mb-8">{t('dragDropDesc')}</p>
              <button onClick={handleStartProcess} className="px-8 py-3 bg-slate-900 dark:bg-emerald-600 text-white text-sm font-bold rounded-2xl hover:scale-105 active:scale-95 transition-all shadow-xl shadow-emerald-500/20">{t('browseFiles')}</button>
              <div className="mt-8 text-[10px] text-slate-400 bg-white dark:bg-slate-800 px-4 py-2 rounded-full border border-slate-100 dark:border-slate-700 flex items-center gap-2">
                 <ShieldCheck size={12} className="text-emerald-500" /> {t('securityNote')}
              </div>
            </div>
          )}

          {step === 2 && (
            <div className="flex flex-col items-center justify-center py-12">
                <div className="relative mb-6">
                    <div className="w-16 h-16 border-4 border-emerald-100 dark:border-emerald-900/30 border-t-emerald-600 rounded-full animate-spin"></div>
                </div>
                <h4 className="text-slate-900 dark:text-slate-100 font-bold animate-pulse">{t('processing')}</h4>
                <p className="text-xs text-slate-500 mt-2">正在执行牌号数据对齐与单位转换...</p>
            </div>
          )}

          {step === 3 && (
            <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4">
                <div className="flex items-center justify-between">
                    <h4 className="font-bold text-slate-800 dark:text-slate-200 flex items-center gap-2"><Filter size={18} className="text-emerald-500" /> {t('cleanData')} (治理中)</h4>
                    <span className="text-[10px] font-bold bg-amber-100 text-amber-600 px-2 py-0.5 rounded-full uppercase">3 Warnings Found</span>
                </div>
                <div className="space-y-2 max-h-48 overflow-y-auto custom-scrollbar pr-1">
                    <div className="p-3 bg-emerald-50/50 dark:bg-emerald-900/10 border border-emerald-100 dark:border-emerald-900/30 rounded-xl flex items-center justify-between">
                        <span className="text-xs font-medium">牌号名称规范化: <span className="font-bold">PE-100S</span></span>
                        <CheckCircle size={14} className="text-emerald-500" />
                    </div>
                    <div className="p-3 bg-amber-50/50 dark:bg-amber-900/10 border border-amber-100 dark:border-amber-900/30 rounded-xl flex items-center justify-between">
                        <span className="text-xs font-medium">厂家对齐建议: <span className="font-bold">中石化</span> &rarr; <span className="text-amber-600 font-bold">Sinopec</span></span>
                        <AlertCircle size={14} className="text-amber-500" />
                    </div>
                    <div className="p-3 bg-rose-50/50 dark:bg-rose-900/10 border border-rose-100 dark:border-rose-900/30 rounded-xl flex items-center justify-between">
                        <span className="text-xs font-medium">缺少关键指标: <span className="font-bold">密度 (Density)</span></span>
                        <span className="text-[9px] font-bold text-rose-500 uppercase">Will be ignored</span>
                    </div>
                </div>
                <button onClick={() => setStep(4)} className="w-full py-3 bg-emerald-600 text-white rounded-2xl font-bold text-sm shadow-lg active:scale-[0.98] transition-all">执行合并并入库</button>
            </div>
          )}

          {step === 4 && (
            <div className="flex flex-col items-center justify-center py-6 text-center animate-in zoom-in-95 duration-500">
                <div className="w-20 h-20 bg-emerald-100 dark:bg-emerald-900/40 rounded-full flex items-center justify-center mb-6 shadow-xl shadow-emerald-500/10">
                    <CheckCircle className="text-emerald-600 w-10 h-10" />
                </div>
                <h4 className="text-slate-900 dark:text-white font-black text-xl mb-2">{t('success')}</h4>
                <p className="text-slate-500 text-sm mb-8 leading-relaxed">{t('importSuccessMsg')}<br/><span className="text-emerald-500 font-bold">{t('importStatMsg')}</span></p>
                <div className="flex gap-3 w-full">
                    <button onClick={onClose} className="flex-1 px-4 py-3 bg-slate-100 dark:bg-slate-800 text-slate-600 font-bold rounded-2xl hover:bg-slate-200 transition-colors">{t('viewLog')}</button>
                    <button onClick={handleFinish} className="flex-[2] px-4 py-3 bg-slate-900 dark:bg-emerald-600 text-white font-bold rounded-2xl shadow-xl active:scale-95 transition-all">{t('finish')}</button>
                </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

