import React, { useMemo } from 'react';
import { X, ChevronRight, Layers, Factory, Microscope, LayoutGrid } from 'lucide-react';
import { Product, Category } from '../types';
import { CATEGORY_TREE } from '../constants';
import { useLanguage } from '../contexts/LanguageContext';

interface ProductDetailDrawerProps {
  product: Product | null;
  onClose: () => void;
  onCategoryClick: (id: string) => void;
}

export const ProductDetailDrawer: React.FC<ProductDetailDrawerProps> = ({ product, onClose, onCategoryClick }) => {
  const { t, tProp, language } = useLanguage();

  const allPaths = useMemo(() => {
    if (!product) return [];

    const paths: string[][] = [];
    const findPaths = (nodes: Category[], targetId: string, currentPath: string[]) => {
      for (const node of nodes) {
        const nodeName = language === 'en' && node.nameEn ? node.nameEn : node.name;
        if (node.id === targetId) {
          paths.push([...currentPath, nodeName]);
        }
        if (node.children) {
          findPaths(node.children, targetId, [...currentPath, nodeName]);
        }
      }
    };

    product.categoryIds.forEach(id => {
      findPaths(CATEGORY_TREE, id, []);
    });

    return paths;
  }, [product, language]);

  if (!product) return null;

  return (
    <div className={`fixed inset-y-0 right-0 w-[450px] bg-white dark:bg-slate-900 shadow-2xl z-[60] border-l border-slate-200 dark:border-slate-800 transition-transform duration-300 transform ${product ? 'translate-x-0' : 'translate-x-full'} flex flex-col`}>
      {/* Header */}
      <div className="px-6 py-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-950/50">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-emerald-600 rounded-xl flex items-center justify-center text-white shadow-lg">
            <Microscope size={20} />
          </div>
          <div>
            <h3 className="text-lg font-bold text-slate-900 dark:text-white leading-none">{product.gradeName}</h3>
            <p className="text-[10px] text-slate-500 uppercase tracking-widest mt-1 font-black">Technical Datasheet</p>
          </div>
        </div>
        <button onClick={onClose} className="p-2 text-slate-400 hover:text-rose-500 transition-colors">
          <X size={24} />
        </button>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-6 custom-scrollbar space-y-8">

        {/* Multi-Path Section - THE CORE FEATURE */}
        <section className="space-y-4">
          <div className="flex items-center gap-2 text-xs font-black text-slate-400 uppercase tracking-widest">
            <Layers size={14} className="text-emerald-500" />
            {tProp('所属分类')} (多路径访问)
          </div>
          <div className="space-y-3">
            {allPaths.map((path, idx) => (
              <div key={idx} className="p-3 bg-slate-50 dark:bg-slate-800/50 border border-slate-100 dark:border-slate-800 rounded-xl flex flex-wrap items-center gap-x-1 gap-y-1.5 transition-all hover:border-emerald-200 dark:hover:border-emerald-800">
                {path.map((segment, sIdx) => (
                  <React.Fragment key={sIdx}>
                    <span className={`text-xs ${sIdx === path.length - 1 ? 'font-bold text-emerald-600 dark:text-emerald-400' : 'text-slate-500 dark:text-slate-400'}`}>
                      {segment}
                    </span>
                    {sIdx < path.length - 1 && <ChevronRight size={12} className="text-slate-300" />}
                  </React.Fragment>
                ))}
              </div>
            ))}
          </div>
        </section>

        {/* Manufacturer */}
        <section className="space-y-3">
            <div className="flex items-center gap-2 text-xs font-black text-slate-400 uppercase tracking-widest">
                <Factory size={14} className="text-emerald-500" />
                {tProp('生产厂家')}
            </div>
            <div className="px-4 py-3 bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl text-sm font-bold text-slate-700 dark:text-slate-200 shadow-sm">
                {product.manufacturer}
            </div>
        </section>

        {/* Properties */}
        <section className="space-y-4">
            <div className="flex items-center gap-2 text-xs font-black text-slate-400 uppercase tracking-widest">
                <LayoutGrid size={14} className="text-emerald-500" />
                产品性能
            </div>
            <div className="grid grid-cols-1 gap-2">
                {Object.entries(product.properties).map(([key, prop]) => (
                    <div key={key} className="flex items-center justify-between p-3 border-b border-slate-50 dark:border-slate-800 last:border-none">
                        <span className="text-xs text-slate-500 dark:text-slate-400">{tProp(key)}</span>
                        <span className="text-xs font-mono font-bold text-slate-800 dark:text-slate-200">
                            {prop.value} <span className="text-[10px] text-slate-400 font-sans ml-1">{prop.unit}</span>
                        </span>
                    </div>
                ))}
            </div>
        </section>
      </div>

      {/* Footer Disclaimer */}
      <div className="p-6 bg-slate-50 dark:bg-slate-950/50 border-t border-slate-100 dark:border-slate-800">
        <p className="text-[10px] text-slate-400 leading-relaxed italic">
          注：多路径分类旨在为不同研发背景的用户提供一致的数据触达，物理层数据保持单点维护，确保数据冗余度为零。
        </p>
