export const DataGrid: React.FC<DataGridProps> = ({ data, columns, isLoading, onDelete, onUpdate, onBatchUpdate, onCategorySelect }) => {
  const { t, tProp, language } = useLanguage();
  const visibleColumns = columns.filter((c) => c.visible);

  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [viewingProduct, setViewingProduct] = useState<Product | null>(null);
  const [isBatchEditing, setIsBatchEditing] = useState(false);
  const [deletingIds, setDeletingIds] = useState<string[] | null>(null);
  const [sortConfig, setSortConfig] = useState<SortConfig | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(15);
  const [hoveredCell, setHoveredCell] = useState<{ productId: string, colKey: string } | null>(null);

  useEffect(() => { setCurrentPage(1); }, [data.length]);

  const handleSort = (key: string) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') direction = 'desc';
    setSortConfig({ key, direction });
  };

  const sortedData = useMemo(() => {
    if (!sortConfig) return data;
    return [...data].sort((a, b) => {
      const getVal = (p: Product, k: string) => {
        if (k === 'gradeName') return p.gradeName;
        if (k === 'manufacturer') return p.manufacturer;
        if (k === 'updatedAt') return p.updatedAt;
        const prop = p.properties[k];
        return prop && prop.value !== undefined ? prop.value : '';
      };
      const valA = getVal(a, sortConfig.key);
      const valB = getVal(b, sortConfig.key);
      if (typeof valA === 'number' && typeof valB === 'number') return sortConfig.direction === 'asc' ? valA - valB : valB - valA;
      return sortConfig.direction === 'asc' ? String(valA).localeCompare(String(valB)) : String(valB).localeCompare(String(valA));
    });
  }, [data, sortConfig]);

  const paginatedData = useMemo(() => {
    const startIndex = (currentPage - 1) * pageSize;
    return sortedData.slice(startIndex, startIndex + pageSize);
  }, [sortedData, currentPage, pageSize]);

  const totalPages = Math.ceil(sortedData.length / pageSize);

  const columnMaxValues = useMemo(() => {
    const maxVals: Record<string, number> = {};
    visibleColumns.forEach(col => {
       if (['gradeName', 'manufacturer', 'updatedAt'].includes(col.key)) return;
       let max = 0;
       data.forEach(p => {
           const v = p.properties[col.key]?.value;
           if (typeof v === 'number' && v > max) max = v;
       });
       if (max > 0) maxVals[col.key] = max;
    });
    return maxVals;
  }, [data, visibleColumns]);

  const isAllSelected = paginatedData.length > 0 && paginatedData.every(p => selectedIds.has(p.id));
  const isIndeterminate = paginatedData.some(p => selectedIds.has(p.id)) && !isAllSelected;

  const toggleSelectAll = () => {
    const newSet = new Set(selectedIds);
    if (isAllSelected) paginatedData.forEach(p => newSet.delete(p.id));
    else paginatedData.forEach(p => newSet.add(p.id));
    setSelectedIds(newSet);
  };

  const getCategoryNames = (ids: string[]) => {
      const names: string[] = [];
      const traverse = (cats: any[]) => {
          cats.forEach(c => {
              if (ids.includes(c.id)) names.push(language === 'en' && c.nameEn ? c.nameEn : c.name);
              if (c.children) traverse(c.children);
          });
      };
      traverse(CATEGORY_TREE);
      return Array.from(new Set(names));
  };

  if (isLoading) return <div className="flex flex-col items-center justify-center h-64 text-slate-400 animate-pulse">...</div>;

  return (
    <>
    <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden flex flex-col h-full relative ring-1 ring-slate-900/5 transition-colors">

      {/* Batch Action Toolbar */}
      <div className={`absolute top-0 left-0 right-0 z-40 h-[52px] bg-emerald-600 dark:bg-emerald-600 backdrop-blur-md flex items-center justify-between px-4 transition-all duration-300 transform ${selectedIds.size > 0 ? 'translate-y-0 opacity-100' : '-translate-y-full opacity-0 pointer-events-none'}`}>
          <div className="flex items-center gap-3 text-sm font-bold text-white">
              <CheckSquare size={18} />
              <span>{selectedIds.size} {t('selected')}</span>
          </div>
          <div className="flex gap-2">
              <button onClick={() => setIsBatchEditing(true)} className="flex items-center gap-1.5 px-3 py-1.5 bg-white/20 hover:bg-white/30 text-white rounded-lg text-xs font-bold transition-all"><ListChecks size={14} /> 批量编辑</button>
              <button onClick={() => setDeletingIds(Array.from(selectedIds))} className="flex items-center gap-1.5 px-3 py-1.5 bg-rose-500 hover:bg-rose-400 text-white rounded-lg text-xs font-bold transition-all"><Trash2 size={14} /> {t('deleteSelected')}</button>
          </div>
      </div>

      <div className="overflow-x-auto overflow-y-auto custom-scrollbar flex-1 relative">
        <table className="w-full text-sm text-left border-collapse">
          <thead className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase bg-slate-50/80 dark:bg-slate-950/80 sticky top-0 z-30 backdrop-blur-md border-b border-slate-100 dark:border-slate-800">
            <tr>
              <th className="w-12 px-4 py-3"><div onClick={toggleSelectAll} className="cursor-pointer flex justify-center">{isAllSelected ? <CheckSquare size={16} className="text-emerald-500"/> : (isIndeterminate ? <MinusSquare size={16} className="text-emerald-500"/> : <Square size={16}/>)}</div></th>
              {visibleColumns.map((col) => (
                <th key={col.key} onClick={() => handleSort(col.key)} className={`px-5 py-3 whitespace-nowrap cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors ${columnMaxValues[col.key] ? 'text-right' : 'text-left'}`}>
                  <div className={`flex items-center gap-1.5 ${columnMaxValues[col.key] ? 'justify-end' : 'justify-start'}`}>
                    <span className={sortConfig?.key === col.key ? 'text-emerald-500' : ''}>{tProp(col.label)}</span>
                    {sortConfig?.key === col.key && (sortConfig.direction === 'asc' ? <ArrowUp size={10} /> : <ArrowDown size={10} />)}
                  </div>
                </th>
              ))}
              <th className="px-5 py-3 text-right sticky right-0 z-40 bg-slate-50/90 dark:bg-slate-950/90 shadow-[-4px_0_12px_-4px_rgba(0,0,0,0.1)]">{t('actions')}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
            {paginatedData.map((product) => (
              <tr 
                key={product.id} 
                onClick={() => setViewingProduct(product)}
                className={`group cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-800/40 transition-colors ${selectedIds.has(product.id) ? 'bg-emerald-50/30 dark:bg-emerald-900/10' : ''}`}
              >
                <td className="px-4 py-3" onClick={(e) => e.stopPropagation()}>
                    <div onClick={() => { const s = new Set(selectedIds); if(s.has(product.id)) s.delete(product.id); else s.add(product.id); setSelectedIds(s); }} className="cursor-pointer flex justify-center text-slate-300 dark:text-slate-700 group-hover:text-emerald-500">
                        {selectedIds.has(product.id) ? <CheckSquare size={16} className="text-emerald-500"/> : <Square size={16}/>}
                    </div>
                </td>
                {visibleColumns.map((col) => {
                  const isNum = !!columnMaxValues[col.key];
                  const barWidth = isNum ? Math.min((Number(product.properties[col.key]?.value || 0) / columnMaxValues[col.key]) * 100, 100) : 0;
                  const property = product.properties[col.key];
                  const hasContext = property && (property.standard || property.temperature || property.referenceId);
                  const isHovered = hoveredCell?.productId === product.id && hoveredCell?.colKey === col.key;

                  return (
                    <td 
                      key={col.key} 
                      className={`px-5 py-3 whitespace-nowrap relative ${isNum ? 'text-right font-mono' : ''}`}
                      onMouseEnter={() => hasContext && setHoveredCell({ productId: product.id, colKey: col.key })}
                      onMouseLeave={() => setHoveredCell(null)}
                    >
                      {col.key === 'gradeName' ? (
                        <div className="flex flex-col">
                            <span className="font-bold text-slate-800 dark:text-slate-100">{product.gradeName}</span>
                            <span className="text-[9px] text-slate-400 flex items-center gap-1 uppercase tracking-wider font-semibold"><Factory size={10} /> {product.manufacturer}</span>
                        </div>
                      ) : col.key === 'manufacturer' ? (
                        <div className="flex flex-wrap gap-1 max-w-[200px]">
                            {getCategoryNames(product.categoryIds).slice(0, 3).map(name => (
                                <span key={name} className="px-1.5 py-0.5 bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 rounded text-[9px] font-bold border border-slate-200 dark:border-slate-700">{name}</span>
                            ))}
                            {product.categoryIds.length > 3 && <span className="text-[9px] text-slate-400">+{product.categoryIds.length - 3}</span>}
                        </div>
                      ) : isNum ? (
                        <>
                          <div className="absolute bottom-1 right-5 h-0.5 bg-emerald-500/10 rounded-full w-2/3">
                             <div className="h-full bg-emerald-500/40 rounded-full" style={{ width: `${barWidth}%` }}></div>
                          </div>
                          <div className="flex items-center justify-end gap-1.5 relative z-10">
                            {hasContext && <Info size={10} className={`shrink-0 transition-colors ${isHovered ? 'text-emerald-500' : 'text-slate-300'}`} />}
                            <span>{property?.value} <span className="text-[9px] text-slate-400 font-sans">{property?.unit}</span></span>
                          </div>
                          {isHovered && property && <PropertyContextTooltip prop={property} />}
                        </>
                      ) : (
                        <div className="flex items-center gap-1.5">
                           {hasContext && <Info size={10} className={`shrink-0 transition-colors ${isHovered ? 'text-emerald-500' : 'text-slate-300'}`} />}
                           <span className="text-slate-600 dark:text-slate-400 truncate max-w-[150px]">{String(property?.value || '-')}</span>
                           {isHovered && property && <PropertyContextTooltip prop={property} />}
                        </div>
                      )}
                    </td>
                  );
                })}
                <td className="px-5 py-3 text-right sticky right-0 bg-white dark:bg-slate-900 group-hover:bg-slate-50 transition-colors z-20" onClick={(e) => e.stopPropagation()}>
                   <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={() => setViewingProduct(product)} className="p-1.5 hover:text-emerald-500 transition-colors" title="View Details"><Eye size={14}/></button>
                      <button onClick={() => setEditingProduct(product)} className="p-1.5 hover:text-blue-500 transition-colors" title="Edit"><Edit size={14}/></button>
                      <button onClick={() => setDeletingIds([product.id])} className="p-1.5 hover:text-rose-500 transition-colors" title="Delete"><Trash2 size={14}/></button>
                   </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      <div className="p-3 border-t border-slate-100 dark:border-slate-800 flex justify-between items-center text-xs text-slate-500 bg-slate-50/50 dark:bg-slate-950/30">
          <div>{t('showing')} {(currentPage - 1) * pageSize + 1} - {Math.min(currentPage * pageSize, data.length)} / {data.length}</div>
          <div className="flex gap-2 items-center">
              <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} className="p-1.5 rounded bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition-colors"><ChevronLeft size={14} /></button>
              <span className="font-bold">{currentPage} / {totalPages}</span>
              <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} className="p-1.5 rounded bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition-colors"><ChevronRight size={14} /></button>
          </div>
      </div>
    </div>

    <ProductDetailDrawer 
        product={viewingProduct} 
        onClose={() => setViewingProduct(null)} 
        onCategoryClick={onCategorySelect} 
    />

    <EditProductModal isOpen={!!editingProduct} onClose={() => setEditingProduct(null)} product={editingProduct} onSave={onUpdate} />
    <BatchEditModal isOpen={isBatchEditing} onClose={() => setIsBatchEditing(false)} selectedProducts={data.filter(p => selectedIds.has(p.id))} onSave={(ids, updates) => { onBatchUpdate(ids, updates); setSelectedIds(new Set()); }} />
    <DeleteConfirmationModal isOpen={!!deletingIds} onClose={() => setDeletingIds(null)} onConfirm={() => { onDelete(deletingIds!); setSelectedIds(new Set()); }} productNames={deletingIds?.map(id => data.find(p => p.id === id)?.gradeName || '') || []} />
    </>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  ReferenceLine,
  Cell,
  LabelList,
  Line,
  ComposedChart,
  ZAxis
} from 'recharts';
import { Settings, Download, ChevronUp, BarChart2, ScatterChart as ScatterIcon, TrendingUp, Palette, FileJson, Image as ImageIcon, RotateCcw, LayoutDashboard, Pipette, Maximize, X, Filter, Plus, Trash2, Eye, EyeOff } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

interface PlotFilter {
  id: string;
  key: string;
  operator: '>' | '<' | '>=' | '<=' | 'between';
  value: number | '';
  value2: number | '';
}

const DEFAULT_PALETTE = [
  '#10b981', // Emerald
  '#3b82f6', // Blue
  '#f59e0b', // Amber
  '#ef4444', // Red
  '#8b5cf6', // Violet
  '#ec4899', // Pink
  '#06b6d4', // Cyan
  '#84cc16', // Lime
  '#f97316', // Orange
  '#6366f1', // Indigo
];

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const { t, tProp } = useLanguage();
  const { theme } = useTheme();
  const chartRef = useRef<HTMLDivElement>(null);

  const [showConfig, setShowConfig] = useState(true);
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('gradeName');
  const [yAxisKey, setYAxisKey] = useState<string>('');

  // Manual Axis Limits
  const [xMin, setXMin] = useState<number | ''>('');
  const [xMax, setXMax] = useState<number | ''>('');
  const [yMin, setYMin] = useState<number | ''>('');
  const [yMax, setYMax] = useState<number | ''>('');

  // Plot Filters
  const [plotFilters, setPlotFilters] = useState<PlotFilter[]>([]);

  // Trendline State
  const [showTrendline, setShowTrendline] = useState(false);
  const [trendlineColor, setTrendlineColor] = useState('#ef4444');
  const [trendlineWidth, setTrendlineWidth] = useState(2);
  const [trendlineStyle, setTrendlineStyle] = useState<'solid' | 'dashed' | 'dotted'>('dashed');

  // Grouping & Color State
  const [groupByKey, setGroupByKey] = useState<string>('');
  const [groupColors, setGroupColors] = useState<Record<string, string>>({});
  const [hiddenGroups, setHiddenGroups] = useState<Set<string>>(new Set());

  // 1. Identify Numeric Keys (for Axes and Filtering)
  const numericKeys = useMemo(() => {
     const keys = new Set<string>();
     data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
           if (typeof v.value === 'number' || (!isNaN(Number(v.value)) && v.value !== '')) {
               keys.add(k);
           }
        });
     });
     return Array.from(keys).sort();
  }, [data]);

  // 2. Identify Categorical Keys (for Grouping)
  const categoricalKeys = useMemo(() => {
    const keys = new Set<string>(['manufacturer']); // Always available
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (typeof v.value === 'string' && isNaN(Number(v.value))) {
                keys.add(k);
            }
        });
    });
    return Array.from(keys).sort();
  }, [data]);

  useEffect(() => {
      if (!yAxisKey && numericKeys.length > 0) {
          const preferred = ['密度', '熔体流动速率', '拉伸强度'].find(k => numericKeys.includes(k));
          setYAxisKey(preferred || numericKeys[0]);
      }
  }, [numericKeys, yAxisKey]);

  useEffect(() => {
    setXMin(''); setXMax(''); setYMin(''); setYMax('');
    setHiddenGroups(new Set()); // Reset hidden groups when keys change
  }, [xAxisKey, yAxisKey, chartType, groupByKey]);

  // 3. Prepare Base Chart Data (with Filters applied)
  const filteredBaseData = useMemo(() => {
    return data.filter(product => {
        return plotFilters.every(f => {
            if (!f.key || f.value === '') return true;
            const prop = product.properties[f.key];
            if (!prop || prop.value === undefined || prop.value === null || prop.value === '') return false;
            const val = Number(prop.value);
            if (isNaN(val)) return false;

            const v1 = Number(f.value);
            const v2 = f.value2 !== '' ? Number(f.value2) : Infinity;

            switch (f.operator) {
                case '>': return val > v1;
                case '<': return val < v1;
                case '>=': return val >= v1;
                case '<=': return val <= v1;
                case 'between': return val >= v1 && val <= v2;
                default: return true;
            }
        });
    });
  }, [data, plotFilters]);

  const chartData = useMemo(() => {
    return filteredBaseData.map(p => {
        const item: any = {
            id: p.id,
            gradeName: p.gradeName,
            manufacturer: p.manufacturer,
            tooltipTitle: `${p.manufacturer} - ${p.gradeName}`
        };
        Object.entries(p.properties).forEach(([k, v]) => {
            const num = Number(v.value);
            item[k] = !isNaN(num) && v.value !== '' ? num : v.value;
        });
        return item;
    });
  }, [filteredBaseData]);

  // 4. Determine Unique Groups
  const uniqueGroups = useMemo(() => {
    if (!groupByKey) return [];
    const groups = new Set<string>();
    chartData.forEach((item: any) => {
        groups.add(String(item[groupByKey] || 'Unknown'));
    });
    return Array.from(groups).sort();
  }, [groupByKey, chartData]);

  // 5. Final Visible Chart Data (Filtered by Hidden Groups)
  const visibleChartData = useMemo(() => {
    if (!groupByKey) return chartData;
    return chartData.filter(d => !hiddenGroups.has(String(d[groupByKey] || 'Unknown')));
  }, [chartData, groupByKey, hiddenGroups]);

  // 6. Calculate Linear Regression for Trendline (Based on Visible Data)
  const trendlineSegment = useMemo(() => {
    if (!showTrendline || chartType !== 'scatter') return null;

    const validPoints = visibleChartData.filter(d => 
        typeof d[xAxisKey] === 'number' && typeof d[yAxisKey] === 'number'
    );

    if (validPoints.length < 2) return null;

    const n = validPoints.length;
    let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
    let minX = Infinity, maxX = -Infinity;

    validPoints.forEach(p => {
        const x = p[xAxisKey];
        const y = p[yAxisKey];
        sumX += x; sumY += y; sumXY += x * y; sumX2 += x * x;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
    });

    const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
    const intercept = (sumY - slope * sumX) / n;

    return [
        { [xAxisKey]: minX, [yAxisKey]: slope * minX + intercept, isTrend: true },
        { [xAxisKey]: maxX, [yAxisKey]: slope * maxX + intercept, isTrend: true }
    ];
  }, [visibleChartData, xAxisKey, yAxisKey, showTrendline, chartType]);

  const dashArray = useMemo(() => {
    if (trendlineStyle === 'dashed') return '5 5';
    if (trendlineStyle === 'dotted') return '2 2';
    return '0';
  }, [trendlineStyle]);

  useEffect(() => {
    if (uniqueGroups.length > 0) {
        setGroupColors(prev => {
            const next = { ...prev };
            uniqueGroups.forEach((group, index) => {
                if (!next[group]) next[group] = DEFAULT_PALETTE[index % DEFAULT_PALETTE.length];
            });
            return next;
        });
    }
  }, [uniqueGroups]);

  const updateGroupColor = (group: string, color: string) => {
    setGroupColors(prev => ({ ...prev, [group]: color }));
  };

  const toggleGroupVisibility = (group: string) => {
    setHiddenGroups(prev => {
      const next = new Set(prev);
      if (next.has(group)) next.delete(group);
      else next.add(group);
      return next;
    });
  };

  const handleDownload = async (type: 'json' | 'png') => {
    if (type === 'json') {
        const blob = new Blob([JSON.stringify(visibleChartData, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = 'resindb_data.json'; a.click();
    } else if (type === 'png' && chartRef.current) {
        const canvas = await html2canvas(chartRef.current, { backgroundColor: theme === 'dark' ? '#020617' : '#ffffff' });
        const a = document.createElement('a');
        a.href = canvas.toDataURL('image/png'); a.download = 'resindb_chart.png'; a.click();
    }
  };

  const addPlotFilter = () => {
    const newFilter: PlotFilter = {
        id: Date.now().toString(),
        key: numericKeys[0] || '',
        operator: '>=',
        value: '',
        value2: ''
    };
    setPlotFilters([...plotFilters, newFilter]);
  };

  const updatePlotFilter = (id: string, updates: Partial<PlotFilter>) => {
    setPlotFilters(prev => prev.map(f => f.id === id ? { ...f, ...updates } : f));
  };

  const removePlotFilter = (id: string) => {
    setPlotFilters(prev => prev.filter(f => f.id !== id));
  };

  const CustomTooltipContent = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const d = payload[0].payload;
      if (d.isTrend) return null;
      const product = data.find(p => p.id === d.id);
      if (!product) return null;

      // Identify up to 3 additional 'less common' properties for enhanced technical context
      const additionalProps = Object.entries(product.properties)
        .filter(([k]) => k !== xAxisKey && k !== yAxisKey && k !== groupByKey)
        .sort((a, b) => {
           // We define 'common' attributes to push them to the end of the priority list
           const commonAttributes = ['密度', 'Density', '熔体流动速率', 'MFR', '拉伸强度', 'Tensile Strength', '应用', 'Application', '类型', 'Type'];
           const aIsCommon = commonAttributes.includes(a[0]) ? 1 : 0;
           const bIsCommon = commonAttributes.includes(b[0]) ? 1 : 0;
           return aIsCommon - bIsCommon;
        })
        .slice(0, 3);

      return (
        <div className="p-4 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-2xl min-w-[240px] animate-in fade-in zoom-in-95 duration-200">
          <div className="flex items-center justify-between gap-4 mb-1">
            <p className="font-bold text-slate-800 dark:text-white truncate text-sm">{product.gradeName}</p>
            {groupByKey && d[groupByKey] && (
               <span className="text-[9px] px-2 py-0.5 rounded-full text-white font-bold" style={{ backgroundColor: groupColors[String(d[groupByKey])] }}>
                  {d[groupByKey]}
               </span>
            )}
          </div>
          <p className="text-[10px] text-slate-500 dark:text-slate-400 mb-3">{product.manufacturer}</p>

          <div className="space-y-1.5 pt-2 border-t border-slate-100 dark:border-slate-800">
             <p className="text-xs flex justify-between gap-4">
                <span className="text-slate-500 font-medium">{tProp(yAxisKey)}:</span>
                <span className="font-mono font-bold text-emerald-600 dark:text-emerald-400">
                    {product.properties[yAxisKey]?.value ?? d[yAxisKey]}
                    {product.properties[yAxisKey]?.unit ? ` ${product.properties[yAxisKey].unit}` : ''}
                </span>
             </p>
             {chartType === 'scatter' && (
               <p className="text-xs flex justify-between gap-4">
                  <span className="text-slate-500 font-medium">{tProp(xAxisKey)}:</span>
                  <span className="font-mono font-bold text-blue-600 dark:text-blue-400">
                      {product.properties[xAxisKey]?.value ?? d[xAxisKey]}
                      {product.properties[xAxisKey]?.unit ? ` ${product.properties[xAxisKey].unit}` : ''}
                  </span>
               </p>
             )}
          </div>

          {additionalProps.length > 0 && (
            <div className="mt-3 pt-3 border-t border-slate-100 dark:border-slate-800 space-y-1.5">
              <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1 flex items-center gap-1.5">
                <Plus size={10} className="text-emerald-500" /> Technical Context
              </p>
              {additionalProps.map(([key, prop]) => (
                <div key={key} className="text-[11px] flex justify-between gap-4 text-slate-600 dark:text-slate-300">
                  <span className="opacity-70 truncate max-w-[130px]">{tProp(key)}:</span>
                  <span className="font-semibold whitespace-nowrap text-slate-700 dark:text-slate-200">
                    {prop.value} <span className="text-[9px] font-sans opacity-50">{prop.unit || ''}</span>
                  </span>
                </div>
              ))}
            </div>
          )}
        </div>
      );
    }
    return null;
  };

  const RenderCustomLegend = (props: any) => {
    const { payload } = props;
    if (!payload || payload.length === 0) return null;

    return (
      <div className="flex flex-wrap justify-center gap-x-4 gap-y-2 mb-6 animate-in fade-in duration-500">
        {payload.map((entry: any, index: number) => (
          <button 
            key={`item-${index}`} 
            onClick={() => toggleGroupVisibility(entry.value)}
            className={`flex items-center gap-2 group transition-all ${hiddenGroups.has(entry.value) ? 'opacity-30' : 'opacity-100'}`}
          >
            <div className="w-2.5 h-2.5 rounded-full transition-transform group-hover:scale-125" style={{ backgroundColor: entry.color }}></div>
            <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest group-hover:text-slate-900 dark:group-hover:text-slate-100">
              {entry.value}
            </span>
          </button>
        ))}
      </div>
    );
  };

  return (
    <div className="flex flex-col md:flex-row h-full gap-4 overflow-hidden">
      {/* Settings Panel */}
      <div className={`flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl transition-all duration-300 shrink-0 overflow-hidden ${showConfig ? 'w-full md:w-80 opacity-100' : 'w-0 opacity-0 md:border-none'}`}>
        <div className="p-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-950/50">
          <div className="flex items-center gap-2 font-bold text-sm text-slate-700 dark:text-slate-200 uppercase tracking-wider">
            <Settings size={16} className="text-emerald-500" />
            {t('chartConfig')}
          </div>
          <button onClick={() => setShowConfig(false)} className="md:hidden text-slate-400 hover:text-slate-600">
            <X size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-5 custom-scrollbar space-y-6">
          <div className="space-y-3">
             <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <LayoutDashboard size={12} /> {t('chartType')}
