            </button>
        )}
        <div className="flex-1 p-6 flex flex-col min-h-0" ref={chartRef}>
            <div className="mb-4 flex justify-between items-center gap-4">
               <h2 className="text-lg font-bold text-slate-800 dark:text-white flex items-center gap-2">
                  {chartType === 'bar' ? <BarChart2 size={20} className="text-emerald-500" /> : <ScatterIcon size={20} className="text-emerald-500" />}
                  {tProp(yAxisKey)} vs {chartType === 'bar' ? tProp('牌号') : tProp(xAxisKey)}
               </h2>
            </div>

            <div className="flex-1 w-full min-h-0">
                <ResponsiveContainer width="100%" height="100%">
                    {chartType === 'bar' ? (
                        <BarChart data={visibleChartData} margin={{ top: 10, right: 30, left: 0, bottom: 40 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis dataKey="gradeName" angle={-45} textAnchor="end" interval={0} height={60} fontSize={10} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} />
                            <YAxis fontSize={10} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} />
                            <Tooltip cursor={{ fill: 'rgba(16, 185, 129, 0.05)' }} content={<CustomTooltipContent />} />
                            {groupByKey && (
                              /* @ts-ignore - Legend payload causes strict type issues in Recharts */
                              <Legend 
                                verticalAlign="top" 
                                content={<RenderCustomLegend />}
                                // @ts-ignore
                                payload={uniqueGroups.map(group => ({
                                  value: group,
                                  type: 'circle',
                                  id: group,
                                  color: groupColors[group]
                                }))}
                              />
                            )}
                            <Bar dataKey={yAxisKey} radius={[4, 4, 0, 0]} animationDuration={1000}>
                                {visibleChartData.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={groupByKey ? groupColors[String(entry[groupByKey] || 'Unknown')] : DEFAULT_PALETTE[index % DEFAULT_PALETTE.length]} />
                                ))}
                            </Bar>
                        </BarChart>
                    ) : (
                        <ComposedChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis type={xAxisKey === 'gradeName' ? 'category' : 'number'} dataKey={xAxisKey} name={tProp(xAxisKey)} fontSize={10} domain={[xMin === '' ? 'auto' : xMin, xMax === '' ? 'auto' : xMax]} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} label={{ value: tProp(xAxisKey), position: 'bottom', offset: 0, fontSize: 10, fill: '#64748b' }} />
                            <YAxis type="number" dataKey={yAxisKey} name={tProp(yAxisKey)} fontSize={10} domain={[yMin === '' ? 'auto' : yMin, yMax === '' ? 'auto' : yMax]} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} label={{ value: tProp(yAxisKey), angle: -90, position: 'insideLeft', offset: 10, fontSize: 10, fill: '#64748b' }} />
                            <ZAxis range={[60, 400]} />
                            <Tooltip cursor={{ strokeDasharray: '3 3' }} content={<CustomTooltipContent />} />
                            {groupByKey && (
                              /* @ts-ignore - Legend payload causes strict type issues in Recharts */
                              <Legend 
                                verticalAlign="top" 
                                content={<RenderCustomLegend />}
                                // @ts-ignore
                                payload={uniqueGroups.map(group => ({
                                  value: group,
                                  type: 'circle',
                                  id: group,
                                  color: groupColors[group]
                                }))}
                              />
                            )}
                            <Scatter name="Resin Samples" data={visibleChartData} animationDuration={1500}>
                                {visibleChartData.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={groupByKey ? groupColors[String(entry[groupByKey] || 'Unknown')] : '#10b981'} strokeWidth={1} stroke="#ffffff" />
                                ))}
                            </Scatter>
                            {trendlineSegment && (
                                <Line type="monotone" data={trendlineSegment} dataKey={yAxisKey} stroke={trendlineColor} strokeWidth={trendlineWidth} strokeDasharray={dashArray} dot={false} activeDot={false} legendType="none" />
                            )}
                        </ComposedChart>
                    )}
                </ResponsiveContainer>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  ReferenceLine,
  Cell,
  LabelList,
  Line,
  ComposedChart,
  ZAxis
} from 'recharts';
import { Settings, Download, ChevronUp, BarChart2, ScatterChart as ScatterIcon, TrendingUp, Palette, FileJson, Image as ImageIcon, RotateCcw, LayoutDashboard, Pipette, Maximize, X, Filter, Plus, Trash2, Eye, EyeOff, Info, RefreshCw, Palette as PaletteIcon, Layers } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

interface PlotFilter {
  id: string;
  key: string;
  operator: '>' | '<' | '>=' | '<=' | 'between';
  value: number | '';
  value2: number | '';
}

const DEFAULT_PALETTE = [
  '#10b981', // Emerald
  '#3b82f6', // Blue
  '#f59e0b', // Amber
  '#ef4444', // Red
  '#8b5cf6', // Violet
  '#ec4899', // Pink
  '#06b6d4', // Cyan
  '#84cc16', // Lime
  '#f97316', // Orange
  '#6366f1', // Indigo
];

const QUICK_COLORS = [
  '#10b981', '#3b82f6', '#f59e0b', '#ef4444', '#8b5cf6', 
  '#ec4899', '#06b6d4', '#f97316', '#6366f1', '#475569'
];

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const { t, tProp } = useLanguage();
  const { theme } = useTheme();
  const chartRef = useRef<HTMLDivElement>(null);

  const [showConfig, setShowConfig] = useState(true);
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('gradeName');
  const [yAxisKey, setYAxisKey] = useState<string>('');

  // Manual Axis Limits
  const [xMin, setXMin] = useState<number | ''>('');
  const [xMax, setXMax] = useState<number | ''>('');
  const [yMin, setYMin] = useState<number | ''>('');
  const [yMax, setYMax] = useState<number | ''>('');

  // Plot Filters
  const [plotFilters, setPlotFilters] = useState<PlotFilter[]>([]);

  // Trendline State
  const [showTrendline, setShowTrendline] = useState(false);
  const [trendlineColor, setTrendlineColor] = useState('#ef4444');
  const [trendlineWidth, setTrendlineWidth] = useState(2);
  const [trendlineStyle, setTrendlineStyle] = useState<'solid' | 'dashed' | 'dotted'>('dashed');

  // Grouping & Color State
  const [groupByKey, setGroupByKey] = useState<string>('');
  const [groupColors, setGroupColors] = useState<Record<string, string>>({});
  const [hiddenGroups, setHiddenGroups] = useState<Set<string>>(new Set());

  // 1. Identify Numeric Keys (for Axes and Filtering)
  const numericKeys = useMemo(() => {
     const keys = new Set<string>();
     data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
           if (typeof v.value === 'number' || (!isNaN(Number(v.value)) && v.value !== '')) {
               keys.add(k);
           }
        });
     });
     return Array.from(keys).sort();
  }, [data]);

  // 2. Identify Categorical Keys (for Grouping)
  const categoricalKeys = useMemo(() => {
    const keys = new Set<string>(['manufacturer']); // Always available
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (typeof v.value === 'string' && isNaN(Number(v.value))) {
                keys.add(k);
            }
        });
    });
    return Array.from(keys).sort();
  }, [data]);

  useEffect(() => {
      if (!yAxisKey && numericKeys.length > 0) {
          const preferred = ['密度', '熔体流动速率', '拉伸强度'].find(k => numericKeys.includes(k));
          setYAxisKey(preferred || numericKeys[0]);
      }
  }, [numericKeys, yAxisKey]);

  useEffect(() => {
    setXMin(''); setXMax(''); setYMin(''); setYMax('');
    setHiddenGroups(new Set()); // Reset hidden groups when keys change
  }, [xAxisKey, yAxisKey, chartType, groupByKey]);

  // 3. Prepare Base Chart Data (with Filters applied)
  const filteredBaseData = useMemo(() => {
    return data.filter(product => {
        return plotFilters.every(f => {
            if (!f.key || f.value === '') return true;
            const prop = product.properties[f.key];
            if (!prop || prop.value === undefined || prop.value === null || prop.value === '') return false;
            const val = Number(prop.value);
            if (isNaN(val)) return false;

            const v1 = Number(f.value);
            const v2 = f.value2 !== '' ? Number(f.value2) : Infinity;

            switch (f.operator) {
                case '>': return val > v1;
                case '<': return val < v1;
                case '>=': return val >= v1;
                case '<=': return val <= v1;
                case 'between': return val >= v1 && val <= v2;
                default: return true;
            }
        });
    });
  }, [data, plotFilters]);

  const chartData = useMemo(() => {
    return filteredBaseData.map(p => {
        const item: any = {
            id: p.id,
            gradeName: p.gradeName,
            manufacturer: p.manufacturer,
            tooltipTitle: `${p.manufacturer} - ${p.gradeName}`
        };
        Object.entries(p.properties).forEach(([k, v]) => {
            const num = Number(v.value);
            item[k] = !isNaN(num) && v.value !== '' ? num : v.value;
        });
        return item;
    });
  }, [filteredBaseData]);

  // 4. Determine Unique Groups
  const uniqueGroups = useMemo(() => {
    if (!groupByKey) return [];
    const groups = new Set<string>();
    chartData.forEach((item: any) => {
        groups.add(String(item[groupByKey] || 'Unknown'));
    });
    return Array.from(groups).sort();
  }, [groupByKey, chartData]);

  // 5. Final Visible Chart Data (Filtered by Hidden Groups)
  const visibleChartData = useMemo(() => {
    if (!groupByKey) return chartData;
    return chartData.filter(d => !hiddenGroups.has(String(d[groupByKey] || 'Unknown')));
  }, [chartData, groupByKey, hiddenGroups]);

  // 6. Calculate Linear Regression for Trendline (Based on Visible Data)
  const trendlineSegment = useMemo(() => {
    if (!showTrendline || chartType !== 'scatter') return null;

    const validPoints = visibleChartData.filter(d => 
        typeof d[xAxisKey] === 'number' && typeof d[yAxisKey] === 'number'
    );

    if (validPoints.length < 2) return null;

    const n = validPoints.length;
    let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
    let minX = Infinity, maxX = -Infinity;

    validPoints.forEach(p => {
        const x = p[xAxisKey];
        const y = p[yAxisKey];
        sumX += x; sumY += y; sumXY += x * y; sumX2 += x * x;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
    });

    const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
    const intercept = (sumY - slope * sumX) / n;

    return [
        { [xAxisKey]: minX, [yAxisKey]: slope * minX + intercept, isTrend: true },
        { [xAxisKey]: maxX, [yAxisKey]: slope * maxX + intercept, isTrend: true }
    ];
  }, [visibleChartData, xAxisKey, yAxisKey, showTrendline, chartType]);

  const dashArray = useMemo(() => {
    if (trendlineStyle === 'dashed') return '5 5';
    if (trendlineStyle === 'dotted') return '2 2';
    return '0';
  }, [trendlineStyle]);

  useEffect(() => {
    if (uniqueGroups.length > 0) {
        setGroupColors(prev => {
            const next = { ...prev };
            uniqueGroups.forEach((group, index) => {
                if (!next[group]) next[group] = DEFAULT_PALETTE[index % DEFAULT_PALETTE.length];
            });
            return next;
        });
    }
  }, [uniqueGroups]);

  const updateGroupColor = (group: string, color: string) => {
    setGroupColors(prev => ({ ...prev, [group]: color }));
  };

  const shufflePalette = () => {
    const shuffled = [...DEFAULT_PALETTE].sort(() => Math.random() - 0.5);
    setGroupColors(prev => {
        const next = { ...prev };
        uniqueGroups.forEach((group, index) => {
            next[group] = shuffled[index % shuffled.length];
        });
        return next;
    });
  };

  const resetPalette = () => {
    setGroupColors(prev => {
        const next = { ...prev };
        uniqueGroups.forEach((group, index) => {
            next[group] = DEFAULT_PALETTE[index % DEFAULT_PALETTE.length];
        });
        return next;
    });
  };

  const toggleGroupVisibility = (group: string) => {
    setHiddenGroups(prev => {
      const next = new Set(prev);
      if (next.has(group)) next.delete(group);
      else next.add(group);
      return next;
    });
  };

  const handleDownload = async (type: 'json' | 'png') => {
    if (type === 'json') {
        const blob = new Blob([JSON.stringify(visibleChartData, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = 'resindb_data.json'; a.click();
    } else if (type === 'png' && chartRef.current) {
        const canvas = await html2canvas(chartRef.current, { backgroundColor: theme === 'dark' ? '#020617' : '#ffffff' });
        const a = document.createElement('a');
        a.href = canvas.toDataURL('image/png'); a.download = 'resindb_chart.png'; a.click();
    }
  };

  const addPlotFilter = () => {
    const newFilter: PlotFilter = {
        id: Date.now().toString(),
        key: numericKeys[0] || '',
        operator: '>=',
        value: '',
        value2: ''
    };
    setPlotFilters([...plotFilters, newFilter]);
  };

  const updatePlotFilter = (id: string, updates: Partial<PlotFilter>) => {
    setPlotFilters(prev => prev.map(f => f.id === id ? { ...f, ...updates } : f));
  };

  const removePlotFilter = (id: string) => {
    setPlotFilters(prev => prev.filter(f => f.id !== id));
  };

  const CustomTooltipContent = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const d = payload[0].payload;
      if (d.isTrend) return null;
      const product = data.find(p => p.id === d.id);
      if (!product) return null;

      const additionalProps = Object.entries(product.properties)
        .filter(([k]) => k !== xAxisKey && k !== yAxisKey && k !== groupByKey)
        .sort((a, b) => {
           const commonAttributes = ['密度', 'Density', '熔体流动速率', 'MFR', '拉伸强度', 'Tensile Strength', '应用', 'Application', '类型', 'Type'];
           const aIsCommon = commonAttributes.includes(a[0]) ? 1 : 0;
           const bIsCommon = commonAttributes.includes(b[0]) ? 1 : 0;
           return aIsCommon - bIsCommon;
        })
        .slice(0, 3);

      const formatPropValue = (key: string) => {
          const prop = product.properties[key];
          if (!prop) return <span className="text-sm font-black text-slate-800 dark:text-slate-100">{d[key]}</span>;
          return (
            <div className="flex items-baseline gap-1">
              <span className="text-sm font-mono font-black">{prop.value}</span>
              {prop.unit && (
                <span className="text-[10px] opacity-60 font-sans font-medium">
                  {prop.unit}
                </span>
              )}
            </div>
          );
      };

      return (
        <div className="p-4 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-2xl min-w-[260px] animate-in fade-in zoom-in-95 duration-200 border-l-4" style={{ borderLeftColor: groupByKey ? groupColors[String(d[groupByKey])] : '#10b981' }}>
          <div className="flex items-center justify-between gap-4 mb-1">
            <p className="font-bold text-slate-800 dark:text-white truncate text-sm">{product.gradeName}</p>
            {groupByKey && d[groupByKey] && (
               <span className="text-[9px] px-2 py-0.5 rounded-full text-white font-bold whitespace-nowrap" style={{ backgroundColor: groupColors[String(d[groupByKey])] }}>
                  {d[groupByKey]}
               </span>
            )}
          </div>
          <p className="text-[10px] text-slate-500 dark:text-slate-400 mb-3 uppercase tracking-widest font-bold flex items-center gap-1.5">
            <Factory size={10} className="text-emerald-500" /> {product.manufacturer}
          </p>

          <div className="space-y-2 pt-2 border-t border-slate-100 dark:border-slate-800">
             <div className="flex justify-between gap-4 items-center">
                <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">{tProp(yAxisKey)}</span>
                <div className="text-emerald-600 dark:text-emerald-400">
                    {formatPropValue(yAxisKey)}
                </div>
             </div>
             {chartType === 'scatter' && xAxisKey !== 'gradeName' && (
               <div className="flex justify-between gap-4 items-center">
                  <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">{tProp(xAxisKey)}</span>
                  <div className="text-blue-600 dark:text-blue-400">
                      {formatPropValue(xAxisKey)}
                  </div>
               </div>
             )}
          </div>

          {additionalProps.length > 0 && (
            <div className="mt-3 pt-3 border-t border-slate-100 dark:border-slate-800 space-y-2">
              <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1 flex items-center gap-1.5">
                <Info size={10} className="text-emerald-500" /> Technical Context
              </p>
              {additionalProps.map(([key, prop]) => (
                <div key={key} className="text-[11px] flex justify-between gap-4 text-slate-600 dark:text-slate-300 items-baseline">
                  <span className="opacity-70 truncate max-w-[140px]">{tProp(key)}</span>
                  <div className="font-bold whitespace-nowrap text-slate-800 dark:text-slate-100 font-mono">
                    <div className="flex items-baseline gap-1 justify-end">
                      <span>{prop.value}</span>
                      {prop.unit && (
                        <span className="text-[9px] font-sans opacity-40 font-normal">
                          {prop.unit}
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      );
    }
    return null;
  };

  const RenderCustomLegend = (props: any) => {
    const { payload } = props;
    if (!payload || payload.length === 0) return null;

    return (
      <div className="flex flex-wrap justify-center gap-x-4 gap-y-2 mb-6 animate-in fade-in duration-500">
        {payload.map((entry: any, index: number) => (
          <button 
            key={`item-${index}`} 
            onClick={() => toggleGroupVisibility(entry.value)}
            className={`flex items-center gap-2 group transition-all ${hiddenGroups.has(entry.value) ? 'opacity-30' : 'opacity-100'}`}
          >
            <div className="w-2.5 h-2.5 rounded-full transition-transform group-hover:scale-125" style={{ backgroundColor: entry.color }}></div>
            <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest group-hover:text-slate-900 dark:group-hover:text-slate-100">
              {entry.value}
            </span>
          </button>
        ))}
      </div>
    );
  };

  return (
    <div className="flex flex-col md:flex-row h-full gap-4 overflow-hidden">
      {/* Settings Panel */}
      <div className={`flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl transition-all duration-300 shrink-0 overflow-hidden ${showConfig ? 'w-full md:w-80 opacity-100' : 'w-0 opacity-0 md:border-none'}`}>
        <div className="p-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-950/50">
          <div className="flex items-center gap-2 font-bold text-sm text-slate-700 dark:text-slate-200 uppercase tracking-wider">
            <Settings size={16} className="text-emerald-500" />
            {t('chartConfig')}
          </div>
          <button onClick={() => setShowConfig(false)} className="md:hidden text-slate-400 hover:text-slate-600">
            <X size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-5 custom-scrollbar space-y-6">
          <div className="space-y-3">
             <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <LayoutDashboard size={12} /> {t('chartType')}
             </label>
             <div className="flex gap-2">
                <button onClick={() => setChartType('bar')} className={`flex-1 flex flex-col items-center gap-2 p-3 rounded-xl border-2 transition-all ${chartType === 'bar' ? 'border-emerald-500 bg-emerald-50/50 dark:bg-emerald-900/20 text-emerald-600' : 'border-slate-100 dark:border-slate-800 text-slate-400'}`}>
                  <BarChart2 size={24} /> <span className="text-[10px] font-bold uppercase">{t('barChart')}</span>
                </button>
                <button onClick={() => setChartType('scatter')} className={`flex-1 flex flex-col items-center gap-2 p-3 rounded-xl border-2 transition-all ${chartType === 'scatter' ? 'border-emerald-500 bg-emerald-50/50 dark:bg-emerald-900/20 text-emerald-600' : 'border-slate-100 dark:border-slate-800 text-slate-400'}`}>
                  <ScatterIcon size={24} /> <span className="text-[10px] font-bold uppercase">{t('scatterChart')}</span>
                </button>
             </div>
          </div>

          <div className="space-y-4 pt-2 border-t border-slate-100 dark:border-slate-800">
            <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <RotateCcw size={12} /> {t('axisMapping')}
            </label>
            <div className="space-y-3">
              <div className="space-y-1.5">
                <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('yAxis')}</span>
                <select value={yAxisKey} onChange={(e) => setYAxisKey(e.target.value)} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm outline-none transition-colors">
                  {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                </select>
              </div>
              {chartType === 'scatter' && (
                <div className="space-y-1.5">
                    <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('xAxis')}</span>
                    <select value={xAxisKey} onChange={(e) => setXAxisKey(e.target.value)} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm outline-none transition-colors">
                        <option value="gradeName">{tProp('牌号')}</option>
                        {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                    </select>
                </div>
              )}
            </div>
          </div>

          {/* Manual Axis Limits (Scatter only) */}
          {chartType === 'scatter' && (
            <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
               <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                  <Maximize size={12} /> {t('axisMapping')} (Limits)
               </label>
               <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1"><span className="text-[10px] text-slate-500 font-bold uppercase">{t('xAxisMin')}</span>
                    <input type="number" value={xMin} onChange={(e) => setXMin(e.target.value === '' ? '' : Number(e.target.value))} placeholder="Auto" className="w-full px-2 py-1 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded text-xs outline-none" />
                  </div>
                  <div className="space-y-1"><span className="text-[10px] text-slate-500 font-bold uppercase">{t('xAxisMax')}</span>
                    <input type="number" value={xMax} onChange={(e) => setXMax(e.target.value === '' ? '' : Number(e.target.value))} placeholder="Auto" className="w-full px-2 py-1 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded text-xs outline-none" />
                  </div>
               </div>
            </div>
          )}

          {/* Plot Filters Section */}
          <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
            <div className="flex items-center justify-between">
                <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                    <Filter size={12} /> {t('dataFilters')}
                </label>
                <button 
                    onClick={addPlotFilter}
                    className="p-1 rounded bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 hover:bg-emerald-100 transition-colors"
                >
                    <Plus size={14} />
                </button>
            </div>

            <div className="space-y-3">
                {plotFilters.length === 0 ? (
                    <p className="text-[10px] text-slate-400 italic text-center py-2">{t('noFilters')}</p>
                ) : (
                    plotFilters.map((f) => (
                        <div key={f.id} className="p-3 bg-slate-50 dark:bg-slate-800/50 rounded-xl border border-slate-100 dark:border-slate-800 space-y-2 animate-in slide-in-from-top-1">
                            <div className="flex items-center justify-between gap-2">
                                <select 
                                    value={f.key} 
                                    onChange={(e) => updatePlotFilter(f.id, { key: e.target.value })}
                                    className="flex-1 bg-transparent border-none text-[11px] font-bold text-slate-700 dark:text-slate-200 outline-none p-0"
                                >
                                    {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                                </select>
                                <button onClick={() => removePlotFilter(f.id)} className="text-slate-400 hover:text-rose-500">
                                    <Trash2 size={12} />
                                </button>
                            </div>
                            <div className="flex items-center gap-2">
                                <select 
                                    value={f.operator} 
                                    onChange={(e) => updatePlotFilter(f.id, { operator: e.target.value as any })}
                                    className="bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded px-1.5 py-0.5 text-[10px] outline-none"
                                >
                                    <option value=">=">&ge;</option>
                                    <option value="<=">&le;</option>
                                    <option value=">">&gt;</option>
                                    <option value="<">&lt;</option>
                                    <option value="between">Range</option>
                                </select>
                                <input 
                                    type="number" 
                                    value={f.value}
                                    onChange={(e) => updatePlotFilter(f.id, { value: e.target.value === '' ? '' : Number(e.target.value) })}
                                    placeholder={f.operator === 'between' ? t('min') : t('val')}
                                    className="w-full bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded px-2 py-0.5 text-[10px] outline-none"
                                />
                                {f.operator === 'between' && (
                                    <input 
                                        type="number" 
                                        value={f.value2}
                                        onChange={(e) => updatePlotFilter(f.id, { value2: e.target.value === '' ? '' : Number(e.target.value) })}
                                        placeholder={t('max')}
                                        className="w-full bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded px-2 py-0.5 text-[10px] outline-none"
                                    />
                                )}
                            </div>
                        </div>
                    ))
                )}
            </div>
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
             <div className="flex items-center justify-between">
                <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                    <PaletteIcon size={12} /> {t('styleGrouping')}
                </label>
                {groupByKey && (
                    <div className="flex items-center gap-1">
                        <button 
                            onClick={shufflePalette}
                            title="Shuffle Colors"
                            className="p-1 text-slate-400 hover:text-emerald-500 transition-colors rounded hover:bg-slate-100 dark:hover:bg-slate-800"
                        >
                            <RefreshCw size={12} />
                        </button>
                        <button 
                            onClick={resetPalette}
                            title="Reset to Default Palette"
                            className="p-1 text-slate-400 hover:text-rose-500 transition-colors rounded hover:bg-slate-100 dark:hover:bg-slate-800"
                        >
                            <RotateCcw size={12} />
                        </button>
                    </div>
                )}
             </div>

             <div className="space-y-1.5">
               <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('groupBy')}</span>
               <select value={groupByKey} onChange={(e) => setGroupByKey(e.target.value)} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm outline-none transition-colors">
                 <option value="">{t('none')}</option>
                 {categoricalKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
               </select>
             </div>

             {groupByKey && (
               <div className="space-y-2 max-h-64 overflow-y-auto custom-scrollbar pr-1 py-1">
                 {uniqueGroups.map(group => (
                    <div key={group} className="flex flex-col gap-2 p-3 bg-slate-50 dark:bg-slate-800/40 border border-slate-100 dark:border-slate-800 rounded-xl animate-in fade-in slide-in-from-left-2">
                        <div className="flex items-center justify-between gap-4">
                            <div className="flex items-center gap-2 flex-1 min-w-0">
                                <button 
                                    onClick={() => toggleGroupVisibility(group)}
                                    className={`p-1.5 rounded-lg transition-colors ${hiddenGroups.has(group) ? 'bg-slate-200 dark:bg-slate-700 text-slate-400 dark:text-slate-500' : 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400'}`}
                                >
                                    {hiddenGroups.has(group) ? <EyeOff size={14} /> : <Eye size={14} />}
                                </button>
                                <span className={`text-[10px] font-bold truncate ${hiddenGroups.has(group) ? 'text-slate-400 line-through' : 'text-slate-500 dark:text-slate-400'}`}>
                                    {group}
                                </span>
                            </div>
                            <div className="relative group/picker">
                                <div 
                                    className="w-8 h-8 rounded-full shadow-sm border-2 border-white dark:border-slate-700 overflow-hidden cursor-pointer ring-1 ring-slate-200 dark:ring-slate-800"
                                    style={{ backgroundColor: groupColors[group] || '#10b981' }}
                                >
                                    <input 
                                        type="color" 
                                        value={groupColors[group] || '#10b981'} 
                                        onChange={(e) => updateGroupColor(group, e.target.value)} 
                                        className="absolute inset-0 opacity-0 cursor-pointer w-full h-full" 
                                    />
                                </div>
                            </div>
                        </div>
                        {/* Quick Color Suggestions */}
                        <div className="flex flex-wrap gap-1 mt-1">
                            {QUICK_COLORS.map(c => (
                                <button 
                                    key={c}
                                    onClick={() => updateGroupColor(group, c)}
                                    className={`w-3.5 h-3.5 rounded-full border border-white dark:border-slate-800 transition-transform hover:scale-125 ${groupColors[group] === c ? 'ring-2 ring-emerald-500/50 scale-110 shadow-sm' : ''}`}
                                    style={{ backgroundColor: c }}
                                />
                            ))}
                        </div>
                    </div>
                 ))}
               </div>
             )}
          </div>

          {chartType === 'scatter' && (
            <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
               <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                  <TrendingUp size={12} /> {t('trendline')}
               </label>
               <label className="flex items-center gap-3 cursor-pointer group">
                  <div className={`w-8 h-4 rounded-full relative transition-colors ${showTrendline ? 'bg-emerald-500' : 'bg-slate-200 dark:bg-slate-700'}`}>
                      <div className={`absolute top-0.5 w-3 h-3 bg-white rounded-full transition-transform ${showTrendline ? 'translate-x-4' : ''}`}></div>
                      <input type="checkbox" checked={showTrendline} onChange={() => setShowTrendline(!showTrendline)} className="hidden" />
                  </div>
                  <span className="text-sm text-slate-600 dark:text-slate-300">{t('showTrendline')}</span>
               </label>
            </div>
          )}

          <div className="pt-4 border-t border-slate-100 dark:border-slate-800 grid grid-cols-2 gap-2">
            <button onClick={() => handleDownload('json')} className="flex items-center justify-center gap-2 p-2 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 rounded-lg text-[10px] font-bold text-slate-600 transition-colors uppercase">
              <FileJson size={14} /> JSON
            </button>
            <button onClick={() => handleDownload('png')} className="flex items-center justify-center gap-2 p-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-[10px] font-bold transition-colors uppercase shadow-md shadow-emerald-500/20">
              <ImageIcon size={14} /> PNG
            </button>
          </div>
        </div>
      </div>

      {/* Chart Canvas Area */}
      <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl relative min-h-[400px]">
        {!showConfig && (
            <button onClick={() => setShowConfig(true)} className="absolute top-4 left-4 z-10 p-2.5 bg-white dark:bg-slate-800 border border-slate-200 rounded-xl text-emerald-500 shadow-lg">
                <Settings size={20} />
            </button>
        )}
        <div className="flex-1 p-6 flex flex-col min-h-0" ref={chartRef}>
            <div className="mb-4 flex justify-between items-center gap-4">
               <h2 className="text-lg font-bold text-slate-800 dark:text-white flex items-center gap-2">
                  {chartType === 'bar' ? <BarChart2 size={20} className="text-emerald-500" /> : <ScatterIcon size={20} className="text-emerald-500" />}
                  {tProp(yAxisKey)} vs {chartType === 'bar' ? tProp('牌号') : tProp(xAxisKey)}
               </h2>
            </div>

            <div className="flex-1 w-full min-h-0">
                <ResponsiveContainer width="100%" height="100%">
                    {chartType === 'bar' ? (
                        <BarChart data={visibleChartData} margin={{ top: 10, right: 30, left: 0, bottom: 40 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis dataKey="gradeName" angle={-45} textAnchor="end" interval={0} height={60} fontSize={10} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} />
                            <YAxis fontSize={10} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} />
                            <Tooltip cursor={{ fill: 'rgba(16, 185, 129, 0.05)' }} content={<CustomTooltipContent />} />
                            {groupByKey && (
                              /* @ts-ignore - Legend payload causes strict type issues in Recharts */
                              <Legend 
                                verticalAlign="top" 
                                content={<RenderCustomLegend />}
                                // @ts-ignore
                                payload={uniqueGroups.map(group => ({
                                  value: group,
                                  type: 'circle',
                                  id: group,
                                  color: groupColors[group]
                                }))}
                              />
                            )}
                            <Bar dataKey={yAxisKey} radius={[4, 4, 0, 0]} animationDuration={1000}>
                                {visibleChartData.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={groupByKey ? groupColors[String(entry[groupByKey] || 'Unknown')] : DEFAULT_PALETTE[index % DEFAULT_PALETTE.length]} />
                                ))}
                            </Bar>
                        </BarChart>
                    ) : (
                        <ComposedChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis type={xAxisKey === 'gradeName' ? 'category' : 'number'} dataKey={xAxisKey} name={tProp(xAxisKey)} fontSize={10} domain={[xMin === '' ? 'auto' : xMin, xMax === '' ? 'auto' : xMax]} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} label={{ value: tProp(xAxisKey), position: 'bottom', offset: 0, fontSize: 10, fill: '#64748b' }} />
                            <YAxis type="number" dataKey={yAxisKey} name={tProp(yAxisKey)} fontSize={10} domain={[yMin === '' ? 'auto' : yMin, yMax === '' ? 'auto' : yMax]} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} label={{ value: tProp(yAxisKey), angle: -90, position: 'insideLeft', offset: 10, fontSize: 10, fill: '#64748b' }} />
                            <ZAxis range={[60, 400]} />
                            <Tooltip cursor={{ strokeDasharray: '3 3' }} content={<CustomTooltipContent />} />
                            {groupByKey && (
                              /* @ts-ignore - Legend payload causes strict type issues in Recharts */
                              <Legend 
                                verticalAlign="top" 
                                content={<RenderCustomLegend />}
                                // @ts-ignore
                                payload={uniqueGroups.map(group => ({
                                  value: group,
                                  type: 'circle',
                                  id: group,
                                  color: groupColors[group]
                                }))}
                              />
                            )}
                            <Scatter name="Resin Samples" data={visibleChartData} animationDuration={1500}>
                                {visibleChartData.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={groupByKey ? groupColors[String(entry[groupByKey] || 'Unknown')] : '#10b981'} strokeWidth={1} stroke="#ffffff" />
                                ))}
                            </Scatter>
                            {trendlineSegment && (
                                <Line type="monotone" data={trendlineSegment} dataKey={yAxisKey} stroke={trendlineColor} strokeWidth={trendlineWidth} strokeDasharray={dashArray} dot={false} activeDot={false} legendType="none" />
                            )}
                        </ComposedChart>
                    )}
                </ResponsiveContainer>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  ReferenceLine,
  Cell,
  LabelList,
  Line,
  ComposedChart,
  ZAxis
} from 'recharts';
// Added Factory to imports
import { Settings, Download, ChevronUp, BarChart2, ScatterChart as ScatterIcon, TrendingUp, Palette, FileJson, Image as ImageIcon, RotateCcw, LayoutDashboard, Pipette, Maximize, X, Filter, Plus, Trash2, Eye, EyeOff, Info, RefreshCw, Palette as PaletteIcon, Layers, Factory } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

interface PlotFilter {
  id: string;
  key: string;
  operator: '>' | '<' | '>=' | '<=' | 'between';
  value: number | '';
  value2: number | '';
}

const DEFAULT_PALETTE = [
  '#10b981', // Emerald
  '#3b82f6', // Blue
  '#f59e0b', // Amber
  '#ef4444', // Red
  '#8b5cf6', // Violet
  '#ec4899', // Pink
  '#06b6d4', // Cyan
  '#84cc16', // Lime
  '#f97316', // Orange
  '#6366f1', // Indigo
];

const QUICK_COLORS = [
  '#10b981', '#3b82f6', '#f59e0b', '#ef4444', '#8b5cf6', 
  '#ec4899', '#06b6d4', '#f97316', '#6366f1', '#475569'
];

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const { t, tProp } = useLanguage();
  const { theme } = useTheme();
  const chartRef = useRef<HTMLDivElement>(null);

  const [showConfig, setShowConfig] = useState(true);
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('gradeName');
  const [yAxisKey, setYAxisKey] = useState<string>('');

  // Manual Axis Limits
  const [xMin, setXMin] = useState<number | ''>('');
  const [xMax, setXMax] = useState<number | ''>('');
  const [yMin, setYMin] = useState<number | ''>('');
  const [yMax, setYMax] = useState<number | ''>('');

  // Plot Filters
  const [plotFilters, setPlotFilters] = useState<PlotFilter[]>([]);

  // Trendline State
  const [showTrendline, setShowTrendline] = useState(false);
  const [trendlineColor, setTrendlineColor] = useState('#ef4444');
  const [trendlineWidth, setTrendlineWidth] = useState(2);
  const [trendlineStyle, setTrendlineStyle] = useState<'solid' | 'dashed' | 'dotted'>('dashed');

  // Grouping & Color State
  const [groupByKey, setGroupByKey] = useState<string>('');
  const [groupColors, setGroupColors] = useState<Record<string, string>>({});
  const [hiddenGroups, setHiddenGroups] = useState<Set<string>>(new Set());

  // 1. Identify Numeric Keys (for Axes and Filtering)
  const numericKeys = useMemo(() => {
     const keys = new Set<string>();
     data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
           if (typeof v.value === 'number' || (!isNaN(Number(v.value)) && v.value !== '')) {
               keys.add(k);
           }
        });
     });
     return Array.from(keys).sort();
  }, [data]);

  // 2. Identify Categorical Keys (for Grouping)
  const categoricalKeys = useMemo(() => {
    const keys = new Set<string>(['manufacturer']); // Always available
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            if (typeof v.value === 'string' && isNaN(Number(v.value))) {
                keys.add(k);
            }
        });
    });
    return Array.from(keys).sort();
  }, [data]);

  useEffect(() => {
      if (!yAxisKey && numericKeys.length > 0) {
          const preferred = ['密度', '熔体流动速率', '拉伸强度'].find(k => numericKeys.includes(k));
          setYAxisKey(preferred || numericKeys[0]);
      }
  }, [numericKeys, yAxisKey]);

  useEffect(() => {
    setXMin(''); setXMax(''); setYMin(''); setYMax('');
    setHiddenGroups(new Set()); // Reset hidden groups when keys change
  }, [xAxisKey, yAxisKey, chartType, groupByKey]);

  // 3. Prepare Base Chart Data (with Filters applied)
  const filteredBaseData = useMemo(() => {
    return data.filter(product => {
        return plotFilters.every(f => {
            if (!f.key || f.value === '') return true;
            const prop = product.properties[f.key];
            if (!prop || prop.value === undefined || prop.value === null || prop.value === '') return false;
            const val = Number(prop.value);
            if (isNaN(val)) return false;

            const v1 = Number(f.value);
            const v2 = f.value2 !== '' ? Number(f.value2) : Infinity;

            switch (f.operator) {
                case '>': return val > v1;
                case '<': return val < v1;
                case '>=': return val >= v1;
                case '<=': return val <= v1;
                case 'between': return val >= v1 && val <= v2;
                default: return true;
            }
        });
    });
  }, [data, plotFilters]);

  const chartData = useMemo(() => {
    return filteredBaseData.map(p => {
        const item: any = {
            id: p.id,
            gradeName: p.gradeName,
            manufacturer: p.manufacturer,
            tooltipTitle: `${p.manufacturer} - ${p.gradeName}`
        };
        Object.entries(p.properties).forEach(([k, v]) => {
            const num = Number(v.value);
            item[k] = !isNaN(num) && v.value !== '' ? num : v.value;
        });
        return item;
    });
  }, [filteredBaseData]);

  // 4. Determine Unique Groups
  const uniqueGroups = useMemo(() => {
    if (!groupByKey) return [];
    const groups = new Set<string>();
    chartData.forEach((item: any) => {
        groups.add(String(item[groupByKey] || 'Unknown'));
    });
    return Array.from(groups).sort();
  }, [groupByKey, chartData]);

  // 5. Final Visible Chart Data (Filtered by Hidden Groups)
  const visibleChartData = useMemo(() => {
    if (!groupByKey) return chartData;
    return chartData.filter(d => !hiddenGroups.has(String(d[groupByKey] || 'Unknown')));
  }, [chartData, groupByKey, hiddenGroups]);

  // 6. Calculate Linear Regression for Trendline (Based on Visible Data)
  const trendlineSegment = useMemo(() => {
    if (!showTrendline || chartType !== 'scatter') return null;

    const validPoints = visibleChartData.filter(d => 
        typeof d[xAxisKey] === 'number' && typeof d[yAxisKey] === 'number'
    );

    if (validPoints.length < 2) return null;

    const n = validPoints.length;
    let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
    let minX = Infinity, maxX = -Infinity;

    validPoints.forEach(p => {
        const x = p[xAxisKey];
        const y = p[yAxisKey];
        sumX += x; sumY += y; sumXY += x * y; sumX2 += x * x;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
    });

    const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
    const intercept = (sumY - slope * sumX) / n;

    return [
        { [xAxisKey]: minX, [yAxisKey]: slope * minX + intercept, isTrend: true },
        { [xAxisKey]: maxX, [yAxisKey]: slope * maxX + intercept, isTrend: true }
    ];
  }, [visibleChartData, xAxisKey, yAxisKey, showTrendline, chartType]);

  const dashArray = useMemo(() => {
    if (trendlineStyle === 'dashed') return '5 5';
    if (trendlineStyle === 'dotted') return '2 2';
    return '0';
  }, [trendlineStyle]);

  useEffect(() => {
    if (uniqueGroups.length > 0) {
        setGroupColors(prev => {
            const next = { ...prev };
            uniqueGroups.forEach((group, index) => {
                if (!next[group]) next[group] = DEFAULT_PALETTE[index % DEFAULT_PALETTE.length];
            });
            return next;
        });
    }
  }, [uniqueGroups]);

  const updateGroupColor = (group: string, color: string) => {
    setGroupColors(prev => ({ ...prev, [group]: color }));
  };

  const shufflePalette = () => {
    const shuffled = [...DEFAULT_PALETTE].sort(() => Math.random() - 0.5);
    setGroupColors(prev => {
        const next = { ...prev };
        uniqueGroups.forEach((group, index) => {
            next[group] = shuffled[index % shuffled.length];
        });
        return next;
    });
  };

  const resetPalette = () => {
    setGroupColors(prev => {
        const next = { ...prev };
        uniqueGroups.forEach((group, index) => {
            next[group] = DEFAULT_PALETTE[index % DEFAULT_PALETTE.length];
        });
        return next;
    });
  };

  const toggleGroupVisibility = (group: string) => {
    setHiddenGroups(prev => {
      const next = new Set(prev);
      if (next.has(group)) next.delete(group);
      else next.add(group);
      return next;
    });
  };

  const handleDownload = async (type: 'json' | 'png') => {
    if (type === 'json') {
        const blob = new Blob([JSON.stringify(visibleChartData, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = 'resindb_data.json'; a.click();
    } else if (type === 'png' && chartRef.current) {
        const canvas = await html2canvas(chartRef.current, { backgroundColor: theme === 'dark' ? '#020617' : '#ffffff' });
        const a = document.createElement('a');
        a.href = canvas.toDataURL('image/png'); a.download = 'resindb_chart.png'; a.click();
    }
  };

  const addPlotFilter = () => {
    const newFilter: PlotFilter = {
        id: Date.now().toString(),
        key: numericKeys[0] || '',
        operator: '>=',
        value: '',
        value2: ''
    };
    setPlotFilters([...plotFilters, newFilter]);
  };

  const updatePlotFilter = (id: string, updates: Partial<PlotFilter>) => {
    setPlotFilters(prev => prev.map(f => f.id === id ? { ...f, ...updates } : f));
  };

  const removePlotFilter = (id: string) => {
    setPlotFilters(prev => prev.filter(f => f.id !== id));
  };

  const CustomTooltipContent = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const d = payload[0].payload;
      if (d.isTrend) return null;
      const product = data.find(p => p.id === d.id);
      if (!product) return null;

      const additionalProps = Object.entries(product.properties)
        .filter(([k]) => k !== xAxisKey && k !== yAxisKey && k !== groupByKey)
        .sort((a, b) => {
           const commonAttributes = ['密度', 'Density', '熔体流动速率', 'MFR', '拉伸强度', 'Tensile Strength', '应用', 'Application', '类型', 'Type'];
           const aIsCommon = commonAttributes.includes(a[0]) ? 1 : 0;
           const bIsCommon = commonAttributes.includes(b[0]) ? 1 : 0;
           return aIsCommon - bIsCommon;
        })
        .slice(0, 3);

      const formatPropValue = (key: string) => {
          const prop = product.properties[key];
          if (!prop) return <span className="text-sm font-black text-slate-800 dark:text-slate-100">{d[key]}</span>;
          return (
            <div className="flex items-baseline gap-1">
              <span className="text-sm font-mono font-black">{prop.value}</span>
              {prop.unit && (
                <span className="text-[10px] opacity-60 font-sans font-medium">
                  {prop.unit}
                </span>
              )}
            </div>
          );
      };

      return (
        <div className="p-4 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-2xl min-w-[260px] animate-in fade-in zoom-in-95 duration-200 border-l-4" style={{ borderLeftColor: groupByKey ? groupColors[String(d[groupByKey])] : '#10b981' }}>
          <div className="flex items-center justify-between gap-4 mb-1">
            <p className="font-bold text-slate-800 dark:text-white truncate text-sm">{product.gradeName}</p>
            {groupByKey && d[groupByKey] && (
               <span className="text-[9px] px-2 py-0.5 rounded-full text-white font-bold whitespace-nowrap" style={{ backgroundColor: groupColors[String(d[groupByKey])] }}>
                  {d[groupByKey]}
               </span>
            )}
          </div>
          <p className="text-[10px] text-slate-500 dark:text-slate-400 mb-3 uppercase tracking-widest font-bold flex items-center gap-1.5">
            <Factory size={10} className="text-emerald-500" /> {product.manufacturer}
          </p>

          <div className="space-y-2 pt-2 border-t border-slate-100 dark:border-slate-800">
             <div className="flex justify-between gap-4 items-center">
                <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">{tProp(yAxisKey)}</span>
                <div className="text-emerald-600 dark:text-emerald-400">
                    {formatPropValue(yAxisKey)}
                </div>
             </div>
             {chartType === 'scatter' && xAxisKey !== 'gradeName' && (
               <div className="flex justify-between gap-4 items-center">
                  <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">{tProp(xAxisKey)}</span>
                  <div className="text-blue-600 dark:text-blue-400">
                      {formatPropValue(xAxisKey)}
                  </div>
               </div>
             )}
          </div>

          {additionalProps.length > 0 && (
            <div className="mt-3 pt-3 border-t border-slate-100 dark:border-slate-800 space-y-2">
              <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1 flex items-center gap-1.5">
                <Info size={10} className="text-emerald-500" /> Technical Context
              </p>
              {additionalProps.map(([key, prop]) => (
                <div key={key} className="text-[11px] flex justify-between gap-4 text-slate-600 dark:text-slate-300 items-baseline">
                  <span className="opacity-70 truncate max-w-[140px]">{tProp(key)}</span>
                  <div className="font-bold whitespace-nowrap text-slate-800 dark:text-slate-100 font-mono">
                    <div className="flex items-baseline gap-1 justify-end">
                      <span>{prop.value}</span>
                      {prop.unit && (
                        <span className="text-[9px] font-sans opacity-40 font-normal">
                          {prop.unit}
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      );
    }
    return null;
  };

  const RenderCustomLegend = (props: any) => {
    const { payload } = props;
    if (!payload || payload.length === 0) return null;

    return (
      <div className="flex flex-wrap justify-center gap-x-4 gap-y-2 mb-6 animate-in fade-in duration-500">
        {payload.map((entry: any, index: number) => (
          <button 
            key={`item-${index}`} 
            onClick={() => toggleGroupVisibility(entry.value)}
            className={`flex items-center gap-2 group transition-all ${hiddenGroups.has(entry.value) ? 'opacity-30' : 'opacity-100'}`}
          >
            <div className="w-2.5 h-2.5 rounded-full transition-transform group-hover:scale-125" style={{ backgroundColor: entry.color }}></div>
            <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest group-hover:text-slate-900 dark:group-hover:text-slate-100">
              {entry.value}
            </span>
          </button>
        ))}
      </div>
    );
  };

  return (
    <div className="flex flex-col md:flex-row h-full gap-4 overflow-hidden">
      {/* Settings Panel */}
      <div className={`flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl transition-all duration-300 shrink-0 overflow-hidden ${showConfig ? 'w-full md:w-80 opacity-100' : 'w-0 opacity-0 md:border-none'}`}>
        <div className="p-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-950/50">
          <div className="flex items-center gap-2 font-bold text-sm text-slate-700 dark:text-slate-200 uppercase tracking-wider">
            <Settings size={16} className="text-emerald-500" />
            {t('chartConfig')}
          </div>
          <button onClick={() => setShowConfig(false)} className="md:hidden text-slate-400 hover:text-slate-600">
            <X size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-5 custom-scrollbar space-y-6">
          <div className="space-y-3">
             <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <LayoutDashboard size={12} /> {t('chartType')}
             </label>
             <div className="flex gap-2">
                <button onClick={() => setChartType('bar')} className={`flex-1 flex flex-col items-center gap-2 p-3 rounded-xl border-2 transition-all ${chartType === 'bar' ? 'border-emerald-500 bg-emerald-50/50 dark:bg-emerald-900/20 text-emerald-600' : 'border-slate-100 dark:border-slate-800 text-slate-400'}`}>
                  <BarChart2 size={24} /> <span className="text-[10px] font-bold uppercase">{t('barChart')}</span>
                </button>
                <button onClick={() => setChartType('scatter')} className={`flex-1 flex flex-col items-center gap-2 p-3 rounded-xl border-2 transition-all ${chartType === 'scatter' ? 'border-emerald-500 bg-emerald-50/50 dark:bg-emerald-900/20 text-emerald-600' : 'border-slate-100 dark:border-slate-800 text-slate-400'}`}>
                  <ScatterIcon size={24} /> <span className="text-[10px] font-bold uppercase">{t('scatterChart')}</span>
                </button>
             </div>
          </div>

          <div className="space-y-4 pt-2 border-t border-slate-100 dark:border-slate-800">
            <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <RotateCcw size={12} /> {t('axisMapping')}
            </label>
            <div className="space-y-3">
              <div className="space-y-1.5">
                <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('yAxis')}</span>
                <select value={yAxisKey} onChange={(e) => setYAxisKey(e.target.value)} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm outline-none transition-colors">
                  {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                </select>
              </div>
              {chartType === 'scatter' && (
                <div className="space-y-1.5">
                    <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('xAxis')}</span>
                    <select value={xAxisKey} onChange={(e) => setXAxisKey(e.target.value)} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm outline-none transition-colors">
                        <option value="gradeName">{tProp('牌号')}</option>
                        {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                    </select>
                </div>
              )}
            </div>
          </div>

          {/* Manual Axis Limits (Scatter only) */}
          {chartType === 'scatter' && (
            <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
               <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                  <Maximize size={12} /> {t('axisMapping')} (Limits)
               </label>
               <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1"><span className="text-[10px] text-slate-500 font-bold uppercase">{t('xAxisMin')}</span>
                    <input type="number" value={xMin} onChange={(e) => setXMin(e.target.value === '' ? '' : Number(e.target.value))} placeholder="Auto" className="w-full px-2 py-1 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded text-xs outline-none" />
                  </div>
                  <div className="space-y-1"><span className="text-[10px] text-slate-500 font-bold uppercase">{t('xAxisMax')}</span>
                    <input type="number" value={xMax} onChange={(e) => setXMax(e.target.value === '' ? '' : Number(e.target.value))} placeholder="Auto" className="w-full px-2 py-1 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded text-xs outline-none" />
                  </div>
               </div>
            </div>
          )}

          {/* Plot Filters Section */}
          <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
            <div className="flex items-center justify-between">
                <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                    <Filter size={12} /> {t('dataFilters')}
                </label>
                <button 
                    onClick={addPlotFilter}
                    className="p-1 rounded bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 hover:bg-emerald-100 transition-colors"
                >
                    <Plus size={14} />
                </button>
            </div>

            <div className="space-y-3">
                {plotFilters.length === 0 ? (
                    <p className="text-[10px] text-slate-400 italic text-center py-2">{t('noFilters')}</p>
                ) : (
                    plotFilters.map((f) => (
                        <div key={f.id} className="p-3 bg-slate-50 dark:bg-slate-800/50 rounded-xl border border-slate-100 dark:border-slate-800 space-y-2 animate-in slide-in-from-top-1">
                            <div className="flex items-center justify-between gap-2">
                                <select 
                                    value={f.key} 
                                    onChange={(e) => updatePlotFilter(f.id, { key: e.target.value })}
                                    className="flex-1 bg-transparent border-none text-[11px] font-bold text-slate-700 dark:text-slate-200 outline-none p-0"
                                >
                                    {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                                </select>
                                <button onClick={() => removePlotFilter(f.id)} className="text-slate-400 hover:text-rose-500">
                                    <Trash2 size={12} />
                                </button>
                            </div>
                            <div className="flex items-center gap-2">
                                <select 
                                    value={f.operator} 
                                    onChange={(e) => updatePlotFilter(f.id, { operator: e.target.value as any })}
                                    className="bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded px-1.5 py-0.5 text-[10px] outline-none"
                                >
                                    <option value=">=">&ge;</option>
                                    <option value="<=">&le;</option>
                                    <option value=">">&gt;</option>
                                    <option value="<">&lt;</option>
                                    <option value="between">Range</option>
                                </select>
                                <input 
                                    type="number" 
                                    value={f.value}
                                    onChange={(e) => updatePlotFilter(f.id, { value: e.target.value === '' ? '' : Number(e.target.value) })}
                                    placeholder={f.operator === 'between' ? t('min') : t('val')}
                                    className="w-full bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded px-2 py-0.5 text-[10px] outline-none"
                                />
                                {f.operator === 'between' && (
                                    <input 
                                        type="number" 
                                        value={f.value2}
                                        onChange={(e) => updatePlotFilter(f.id, { value2: e.target.value === '' ? '' : Number(e.target.value) })}
                                        placeholder={t('max')}
                                        className="w-full bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded px-2 py-0.5 text-[10px] outline-none"
                                    />
                                )}
                            </div>
                        </div>
                    ))
                )}
            </div>
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
             <div className="flex items-center justify-between">
                <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                    <PaletteIcon size={12} /> {t('styleGrouping')}
                </label>
                {groupByKey && (
                    <div className="flex items-center gap-1">
                        <button 
                            onClick={shufflePalette}
                            title="Shuffle Colors"
                            className="p-1 text-slate-400 hover:text-emerald-500 transition-colors rounded hover:bg-slate-100 dark:hover:bg-slate-800"
                        >
                            <RefreshCw size={12} />
                        </button>
                        <button 
                            onClick={resetPalette}
                            title="Reset to Default Palette"
                            className="p-1 text-slate-400 hover:text-rose-500 transition-colors rounded hover:bg-slate-100 dark:hover:bg-slate-800"
                        >
                            <RotateCcw size={12} />
                        </button>
                    </div>
                )}
             </div>

             <div className="space-y-1.5">
               <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('groupBy')}</span>
               <select value={groupByKey} onChange={(e) => setGroupByKey(e.target.value)} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm outline-none transition-colors">
                 <option value="">{t('none')}</option>
                 {categoricalKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
               </select>
             </div>

             {groupByKey && (
               <div className="space-y-2 max-h-64 overflow-y-auto custom-scrollbar pr-1 py-1">
                 {uniqueGroups.map(group => (
                    <div key={group} className="flex flex-col gap-2 p-3 bg-slate-50 dark:bg-slate-800/40 border border-slate-100 dark:border-slate-800 rounded-xl animate-in fade-in slide-in-from-left-2">
                        <div className="flex items-center justify-between gap-4">
                            <div className="flex items-center gap-2 flex-1 min-w-0">
                                <button 
                                    onClick={() => toggleGroupVisibility(group)}
                                    className={`p-1.5 rounded-lg transition-colors ${hiddenGroups.has(group) ? 'bg-slate-200 dark:bg-slate-700 text-slate-400 dark:text-slate-500' : 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400'}`}
                                >
                                    {hiddenGroups.has(group) ? <EyeOff size={14} /> : <Eye size={14} />}
                                </button>
                                <span className={`text-[10px] font-bold truncate ${hiddenGroups.has(group) ? 'text-slate-400 line-through' : 'text-slate-500 dark:text-slate-400'}`}>
                                    {group}
                                </span>
                            </div>
                            <div className="relative group/picker">
                                <div 
                                    className="w-8 h-8 rounded-full shadow-sm border-2 border-white dark:border-slate-700 overflow-hidden cursor-pointer ring-1 ring-slate-200 dark:ring-slate-800"
                                    style={{ backgroundColor: groupColors[group] || '#10b981' }}
                                >
                                    <input 
                                        type="color" 
                                        value={groupColors[group] || '#10b981'} 
                                        onChange={(e) => updateGroupColor(group, e.target.value)} 
                                        className="absolute inset-0 opacity-0 cursor-pointer w-full h-full" 
                                    />
                                </div>
                            </div>
                        </div>
                        {/* Quick Color Suggestions */}
                        <div className="flex flex-wrap gap-1 mt-1">
                            {QUICK_COLORS.map(c => (
                                <button 
                                    key={c}
                                    onClick={() => updateGroupColor(group, c)}
                                    className={`w-3.5 h-3.5 rounded-full border border-white dark:border-slate-800 transition-transform hover:scale-125 ${groupColors[group] === c ? 'ring-2 ring-emerald-500/50 scale-110 shadow-sm' : ''}`}
                                    style={{ backgroundColor: c }}
                                />
                            ))}
                        </div>
                    </div>
                 ))}
               </div>
             )}
          </div>

          {chartType === 'scatter' && (
            <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
               <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                  <TrendingUp size={12} /> {t('trendline')}
               </label>
               <label className="flex items-center gap-3 cursor-pointer group">
                  <div className={`w-8 h-4 rounded-full relative transition-colors ${showTrendline ? 'bg-emerald-500' : 'bg-slate-200 dark:bg-slate-700'}`}>
                      <div className={`absolute top-0.5 w-3 h-3 bg-white rounded-full transition-transform ${showTrendline ? 'translate-x-4' : ''}`}></div>
                      <input type="checkbox" checked={showTrendline} onChange={() => setShowTrendline(!showTrendline)} className="hidden" />
                  </div>
                  <span className="text-sm text-slate-600 dark:text-slate-300">{t('showTrendline')}</span>
               </label>
            </div>
          )}

          <div className="pt-4 border-t border-slate-100 dark:border-slate-800 grid grid-cols-2 gap-2">
            <button onClick={() => handleDownload('json')} className="flex items-center justify-center gap-2 p-2 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 rounded-lg text-[10px] font-bold text-slate-600 transition-colors uppercase">
              <FileJson size={14} /> JSON
            </button>
            <button onClick={() => handleDownload('png')} className="flex items-center justify-center gap-2 p-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-[10px] font-bold transition-colors uppercase shadow-md shadow-emerald-500/20">
              <ImageIcon size={14} /> PNG
            </button>
          </div>
        </div>
      </div>

      {/* Chart Canvas Area */}
      <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl relative min-h-[400px]">
        {!showConfig && (
            <button onClick={() => setShowConfig(true)} className="absolute top-4 left-4 z-10 p-2.5 bg-white dark:bg-slate-800 border border-slate-200 rounded-xl text-emerald-500 shadow-lg">
                <Settings size={20} />
            </button>
        )}
        <div className="flex-1 p-6 flex flex-col min-h-0" ref={chartRef}>
            <div className="mb-4 flex justify-between items-center gap-4">
               <h2 className="text-lg font-bold text-slate-800 dark:text-white flex items-center gap-2">
                  {chartType === 'bar' ? <BarChart2 size={20} className="text-emerald-500" /> : <ScatterIcon size={20} className="text-emerald-500" />}
                  {tProp(yAxisKey)} vs {chartType === 'bar' ? tProp('牌号') : tProp(xAxisKey)}
               </h2>
            </div>

            <div className="flex-1 w-full min-h-0">
                <ResponsiveContainer width="100%" height="100%">
                    {chartType === 'bar' ? (
                        <BarChart data={visibleChartData} margin={{ top: 10, right: 30, left: 0, bottom: 40 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis dataKey="gradeName" angle={-45} textAnchor="end" interval={0} height={60} fontSize={10} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} />
                            <YAxis fontSize={10} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} />
                            <Tooltip cursor={{ fill: 'rgba(16, 185, 129, 0.05)' }} content={<CustomTooltipContent />} />
