                        <div className="relative">
                            {isHidden ? <EyeOff size={10} className="text-slate-400" /> : <Eye size={10} style={{ color: entry.color }} />}
                        </div>
                        <span className={`text-[10px] font-black uppercase tracking-widest ${isHidden ? 'text-slate-400 line-through' : 'text-slate-600 dark:text-slate-300'}`}>
                            {entry.value}
