import React, { useState, useEffect, useRef } from 'react';
import { Search, SlidersHorizontal, Upload, LayoutGrid, BarChart2, Moon, Sun, Globe, User, LogOut, Settings, Shield, Monitor, History, X, Trash2, Clock } from 'lucide-react';
import { ColumnConfig, ViewMode, User as UserType } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';

interface TopBarProps {
  user: UserType | null;
  onLogout: () => void;
  onOpenProfile: () => void;
  onOpenAdmin: () => void;
  searchQuery: string;
  onSearchChange: (query: string) => void;
  columns: ColumnConfig[];
  onToggleColumn: (key: string) => void;
  onToggleAllColumns: (visible: boolean) => void;
  onOpenImport: () => void;
  viewMode: ViewMode;
  onViewModeChange: (mode: ViewMode) => void;
}

const MAX_HISTORY = 8;

export const TopBar: React.FC<TopBarProps> = ({
  user,
  onLogout,
  onOpenProfile,
  onOpenAdmin,
  searchQuery,
  onSearchChange,
  columns,
  onToggleColumn,
  onToggleAllColumns,
  onOpenImport,
  viewMode,
  onViewModeChange,
}) => {
  const [isColumnMenuOpen, setIsColumnMenuOpen] = useState(false);
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [searchHistory, setSearchHistory] = useState<string[]>(() => {
    const saved = localStorage.getItem('resindb-search-history');
    return saved ? JSON.parse(saved) : [];
  });

  const historyRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const { t, language, toggleLanguage, tProp } = useLanguage();
  const { theme, toggleTheme } = useTheme();

  // Close history when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (historyRef.current && !historyRef.current.contains(event.target as Node) && 
          inputRef.current && !inputRef.current.contains(event.target as Node)) {
        setIsHistoryOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const saveToHistory = (query: string) => {
    const trimmed = query.trim();
    if (!trimmed) return;

    setSearchHistory(prev => {
      const filtered = prev.filter(h => h !== trimmed);
      const updated = [trimmed, ...filtered].slice(0, MAX_HISTORY);
      localStorage.setItem('resindb-search-history', JSON.stringify(updated));
      return updated;
    });
  };

  const removeFromHistory = (query: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setSearchHistory(prev => {
      const updated = prev.filter(h => h !== query);
      localStorage.setItem('resindb-search-history', JSON.stringify(updated));
      return updated;
    });
  };

  const clearHistory = () => {
    setSearchHistory([]);
    localStorage.removeItem('resindb-search-history');
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      saveToHistory(searchQuery);
      setIsHistoryOpen(false);
      inputRef.current?.blur();
    }
  };

  const handleHistoryItemClick = (query: string) => {
    onSearchChange(query);
    saveToHistory(query); // Move to top
    setIsHistoryOpen(false);
  };

  return (
    <div className="h-16 px-6 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 flex items-center justify-between z-30 transition-colors duration-300 sticky top-0">
      {/* Search Bar Area */}
      <div className="flex-1 max-w-xl relative group">
        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
          <Search className="text-slate-400 group-focus-within:text-emerald-500 transition-colors" size={18} />
        </div>
        <input
          ref={inputRef}
          type="text"
          placeholder={t('searchPlaceholder')}
          value={searchQuery}
          onFocus={() => setIsHistoryOpen(true)}
          onKeyDown={handleKeyDown}
          onChange={(e) => onSearchChange(e.target.value)}
          className="block w-full pl-10 pr-4 py-2 bg-slate-100/50 dark:bg-slate-800/50 border border-transparent focus:border-emerald-500/50 focus:bg-white dark:focus:bg-slate-900 rounded-xl text-sm transition-all outline-none focus:ring-4 focus:ring-emerald-500/10 dark:text-slate-200 placeholder:text-slate-400 font-medium"
        />

        {/* Search History Dropdown */}
        {isHistoryOpen && searchHistory.length > 0 && (
          <div 
            ref={historyRef}
            className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-2xl z-[100] overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200"
          >
            <div className="px-4 py-3 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50/50 dark:bg-slate-950/50">
              <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">
                <History size={12} />
                Recent Searches
              </div>
              <button 
                onClick={clearHistory}
                className="text-[10px] font-bold text-slate-400 hover:text-rose-500 transition-colors flex items-center gap-1 uppercase tracking-tighter"
              >
                <Trash2 size={10} />
                Clear History
              </button>
            </div>
            <div className="py-2 max-h-[320px] overflow-y-auto custom-scrollbar">
              {searchHistory.map((query, idx) => (
                <div 
                  key={`${query}-${idx}`}
                  onClick={() => handleHistoryItemClick(query)}
                  className="flex items-center justify-between px-4 py-2.5 hover:bg-slate-50 dark:hover:bg-slate-800 cursor-pointer group transition-colors"
                >
                  <div className="flex items-center gap-3 overflow-hidden">
                    <Clock size={14} className="text-slate-300 dark:text-slate-600 shrink-0" />
                    <span className="text-sm text-slate-600 dark:text-slate-300 truncate">{query}</span>
                  </div>
                  <button 
                    onClick={(e) => removeFromHistory(query, e)}
                    className="p-1 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all rounded-md"
                  >
                    <X size={14} />
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Right Actions Area */}
      <div className="flex items-center gap-3 ml-4">

        {/* View Switcher */}
        <div className="flex items-center p-1 bg-slate-100 dark:bg-slate-800/80 rounded-lg border border-slate-200 dark:border-slate-700/50">
            <button
                onClick={() => onViewModeChange('grid')}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-semibold transition-all duration-200 ${viewMode === 'grid' ? 'bg-white dark:bg-slate-700 text-emerald-600 dark:text-emerald-400 shadow-sm' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-300'}`}
                title={t('viewList')}
            >
                <LayoutGrid size={14} />
                <span className="hidden sm:inline">{t('viewList')}</span>
            </button>
            <button
                onClick={() => onViewModeChange('chart')}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-semibold transition-all duration-200 ${viewMode === 'chart' ? 'bg-white dark:bg-slate-700 text-emerald-600 dark:text-emerald-400 shadow-sm' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-300'}`}
                title={t('viewChart')}
            >
                <BarChart2 size={14} />
                <span className="hidden sm:inline">{t('viewChart')}</span>
            </button>
        </div>

        {/* Column Config */}
        {viewMode === 'grid' && (
            <div className="relative">
                <button
                    onClick={() => setIsColumnMenuOpen(!isColumnMenuOpen)}
                    className={`p-2.5 rounded-xl border transition-all duration-200 ${isColumnMenuOpen ? 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-200 dark:border-emerald-800 text-emerald-600 dark:text-emerald-400' : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'}`}
                >
                    <SlidersHorizontal size={18} />
                </button>

                {isColumnMenuOpen && (
                    <>
                    <div className="fixed inset-0 z-10" onClick={() => setIsColumnMenuOpen(false)}></div>
                    <div className="absolute right-0 top-full mt-2 w-72 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-2xl z-20 flex flex-col max-h-[80vh] overflow-hidden animate-in fade-in zoom-in-95 duration-200">
                        <div className="p-4 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-950/50 flex justify-between items-center">
                            <span className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">{t('configureColumns')}</span>
                        </div>
                        <div className="overflow-y-auto p-2 custom-scrollbar space-y-0.5">
                            {columns.map(col => (
                                <label key={col.key} className={`flex items-center gap-3 px-3 py-2 rounded-lg cursor-pointer transition-colors ${col.isSystem ? 'opacity-60 cursor-not-allowed' : 'hover:bg-slate-50 dark:hover:bg-slate-800'}`}>
                                    <input 
                                        type="checkbox" 
                                        checked={col.visible} 
                                        onChange={() => !col.isSystem && onToggleColumn(col.key)}
                                        disabled={col.isSystem}
                                        className="w-4 h-4 accent-emerald-600"
                                    />
                                    <span className={`text-sm ${col.visible ? 'text-slate-900 dark:text-slate-100 font-medium' : 'text-slate-500 dark:text-slate-500'}`}>
                                        {tProp(col.label)}
                                    </span>
                                </label>
                            ))}
                        </div>
                    </div>
                    </>
                )}
            </div>
        )}

        {/* Action Group */}
        <div className="flex items-center bg-slate-100 dark:bg-slate-800/80 rounded-xl p-1 border border-slate-200 dark:border-slate-700/50">
            <button onClick={onOpenImport} className="p-2 text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-100 hover:bg-white dark:hover:bg-slate-700 rounded-lg transition-all" title={t('importData')}>
              <Upload size={18} />
            </button>
            <div className="w-px h-4 bg-slate-300 dark:bg-slate-700 mx-1"></div>
            <button onClick={toggleLanguage} className="flex items-center gap-2 px-3 py-2 text-slate-500 dark:text-slate-400 hover:text-emerald-600 dark:hover:text-emerald-400 hover:bg-white dark:hover:bg-slate-700 rounded-lg transition-all group" title={language === 'zh' ? 'English' : '中文'}>
                <Globe size={18} />
                <span className="text-[10px] font-bold uppercase tracking-wider">{language}</span>
            </button>
            <div className="w-px h-4 bg-slate-300 dark:bg-slate-700 mx-1"></div>

            {/* Themed Toggle Button */}
            <button 
                onClick={toggleTheme} 
                className={`relative p-2 rounded-lg transition-all duration-300 overflow-hidden group/theme
                  ${theme === 'dark' 
                    ? 'text-amber-400 bg-slate-900 shadow-inner' 
                    : 'text-slate-500 hover:text-amber-500 bg-white hover:bg-slate-50'
                  }`}
                aria-label="Toggle Theme"
                title={theme === 'dark' ? 'Switch to Light Mode' : 'Switch to Dark Mode'}
            >
                <div className={`transition-transform duration-500 flex items-center justify-center ${theme === 'dark' ? 'rotate-[360deg]' : 'rotate-0'}`}>
                    {theme === 'dark' ? (
                        <Sun size={18} className="animate-in fade-in zoom-in duration-300" />
                    ) : (
                        <Moon size={18} className="animate-in fade-in zoom-in duration-300" />
                    )}
                </div>
                {/* Subtle Glow Effect for Dark Mode */}
                {theme === 'dark' && (
                    <div className="absolute inset-0 bg-amber-400/10 blur-xl group-hover/theme:bg-amber-400/20 transition-all pointer-events-none"></div>
                )}
            </button>
        </div>

        {/* User Menu */}
        <div className="relative">
            <button
                onClick={() => setIsUserMenuOpen(!isUserMenuOpen)}
                className="flex items-center gap-2 p-1 pl-1 pr-2 bg-slate-900 dark:bg-slate-800 hover:bg-slate-800 dark:hover:bg-slate-700 rounded-full transition-all border border-transparent focus:border-emerald-500/50"
            >
                <div className="w-8 h-8 rounded-full overflow-hidden border-2 border-white/10">
                    <img src={user?.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user?.name}`} alt="User" className="w-full h-full object-cover" />
                </div>
                <div className="hidden md:block text-left">
                    <p className="text-[10px] font-bold text-white uppercase tracking-tighter leading-none">{user?.name.split(' ')[0]}</p>
                    <p className="text-[8px] text-emerald-400 font-bold uppercase tracking-tighter mt-0.5">{user?.role}</p>
                </div>
            </button>

            {isUserMenuOpen && (
                <>
                <div className="fixed inset-0 z-10" onClick={() => setIsUserMenuOpen(false)}></div>
                <div className="absolute right-0 top-full mt-2 w-56 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-2xl z-20 flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-200 origin-top-right">
                    <div className="p-4 bg-slate-50 dark:bg-slate-950/50 border-b border-slate-100 dark:border-slate-800">
                        <p className="text-xs font-bold text-slate-900 dark:text-white truncate">{user?.name}</p>
                        <p className="text-[10px] text-slate-500 dark:text-slate-500 truncate mt-0.5">{user?.email}</p>
                    </div>
                    <div className="p-2 space-y-0.5">
                        <button 
                            onClick={() => { onOpenProfile(); setIsUserMenuOpen(false); }}
                            className="w-full flex items-center gap-3 px-3 py-2 text-sm text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors"
                        >
                            <User size={16} />
                            {t('profile')}
                        </button>
                        <button 
                            onClick={() => { onOpenAdmin(); setIsUserMenuOpen(false); }}
                            className="w-full flex items-center gap-3 px-3 py-2 text-sm text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors"
                        >
                            <Shield size={16} />
                            {t('adminPanel')}
                        </button>
                        <button 
                             onClick={() => { onOpenProfile(); setIsUserMenuOpen(false); }}
                             className="w-full flex items-center gap-3 px-3 py-2 text-sm text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors"
                        >
                            <Settings size={16} />
                            {t('settings')}
                        </button>
                    </div>
                    <div className="p-2 border-t border-slate-100 dark:border-slate-800">
                        <button 
                            onClick={onLogout}
                            className="w-full flex items-center gap-3 px-3 py-2 text-sm text-rose-600 dark:text-rose-400 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg transition-colors font-semibold"
                        >
                            <LogOut size={16} />
                            {t('logout')}
                        </button>
                    </div>
                </div>
                </>
            )}
        </div>

      </div>
    </div>
  );
};

