                    )}
                </ResponsiveContainer>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Product, ColumnConfig, SortConfig, PropertyValue } from '../types';
import { MoreHorizontal, FileText, Factory, CalendarClock, Edit, Trash2, CheckSquare, Square, MinusSquare, ArrowUp, ArrowDown, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight, ArrowUpDown, ListChecks, Tags, Eye, Info, BookOpen, X } from 'lucide-react';
