}

// Helper to render property context tooltip
const PropertyContextTooltip: React.FC<{ prop: PropertyValue }> = ({ prop }) => {
    const { t } = useLanguage();
    const reference = REFERENCES.find(r => r.id === prop.referenceId);

    return (
        <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-3 z-[100] w-64 bg-slate-900 dark:bg-slate-800 text-white rounded-xl shadow-2xl p-4 animate-in fade-in zoom-in-95 duration-200 pointer-events-none border border-slate-700">
            <div className="flex items-center gap-2 mb-3 border-b border-slate-700 pb-2">
                <Info size={14} className="text-emerald-400" />
                <span className="text-[10px] font-black uppercase tracking-widest">{t('details')}</span>
            </div>

            <div className="space-y-3">
                {prop.standard && (
                    <div>
                        <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter mb-0.5">Standard</p>
                        <p className="text-xs font-medium text-slate-100">{prop.standard}</p>
                    </div>
                )}
                {prop.temperature && (
                    <div>
                        <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter mb-0.5">Test Conditions</p>
                        <p className="text-xs font-medium text-slate-100">{prop.temperature}</p>
                    </div>
                )}
                {reference && (
                    <div>
                        <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter mb-0.5">Reference Source</p>
                        <div className="flex items-center gap-1.5 mt-0.5">
                            <BookOpen size={10} className="text-emerald-400" />
                            <p className="text-[10px] italic text-slate-300 truncate">{reference.name}</p>
                        </div>
                    </div>
                )}
                {!prop.standard && !prop.temperature && !reference && (
                    <p className="text-[10px] italic text-slate-500">No additional 2D context available.</p>
                )}
            </div>

            {/* Arrow */}
            <div className="absolute top-full left-1/2 -translate-x-1/2 w-3 h-3 bg-slate-900 dark:bg-slate-800 rotate-45 -mt-1.5 border-r border-b border-slate-700"></div>
        </div>
    );
};

export const DataGrid: React.FC<DataGridProps> = ({ data, columns, isLoading, onDelete, onUpdate, onBatchUpdate, onCategorySelect }) => {
  const { t, tProp, language } = useLanguage();
  const visibleColumns = columns.filter((c) => c.visible);

  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [viewingProduct, setViewingProduct] = useState<Product | null>(null);
  const [isBatchEditing, setIsBatchEditing] = useState(false);
  const [deletingIds, setDeletingIds] = useState<string[] | null>(null);
  const [sortConfig, setSortConfig] = useState<SortConfig | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(15);
  const [hoveredCell, setHoveredCell] = useState<{ productId: string, colKey: string } | null>(null);

  useEffect(() => { setSelectedIds(new Set()); }, [data.length]);
  useEffect(() => { setCurrentPage(1); }, [data.length]);

  const handleSort = (key: string) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') direction = 'desc';
    setSortConfig({ key, direction });
  };

  const sortedData = useMemo(() => {
    if (!sortConfig) return data;
    return [...data].sort((a, b) => {
      const getVal = (p: Product, k: string) => {
        if (k === 'gradeName') return p.gradeName;
        if (k === 'manufacturer') return p.manufacturer;
        if (k === 'updatedAt') return p.updatedAt;
        const prop = p.properties[k];
        return prop && prop.value !== undefined ? prop.value : '';
      };
      const valA = getVal(a, sortConfig.key);
      const valB = getVal(b, sortConfig.key);
      if (typeof valA === 'number' && typeof valB === 'number') return sortConfig.direction === 'asc' ? valA - valB : valB - valA;
      return sortConfig.direction === 'asc' ? String(valA).localeCompare(String(valB)) : String(valB).localeCompare(String(valA));
    });
  }, [data, sortConfig]);

  const paginatedData = useMemo(() => {
    const startIndex = (currentPage - 1) * pageSize;
    return sortedData.slice(startIndex, startIndex + pageSize);
  }, [sortedData, currentPage, pageSize]);

  const totalPages = Math.ceil(sortedData.length / pageSize);

  const columnMaxValues = useMemo(() => {
    const maxVals: Record<string, number> = {};
    visibleColumns.forEach(col => {
       if (['gradeName', 'manufacturer', 'updatedAt'].includes(col.key)) return;
       let max = 0;
       data.forEach(p => {
           const v = p.properties[col.key]?.value;
           if (typeof v === 'number' && v > max) max = v;
       });
       if (max > 0) maxVals[col.key] = max;
    });
    return maxVals;
  }, [data, visibleColumns]);

  const isAllSelected = paginatedData.length > 0 && paginatedData.every(p => selectedIds.has(p.id));
  const isIndeterminate = paginatedData.some(p => selectedIds.has(p.id)) && !isAllSelected;

  const toggleSelectAll = () => {
    const newSet = new Set(selectedIds);
    if (isAllSelected) paginatedData.forEach(p => newSet.delete(p.id));
    else paginatedData.forEach(p => newSet.add(p.id));
    setSelectedIds(newSet);
  };

  const clearSelection = () => {
      setSelectedIds(new Set());
  };

  const getCategoryNames = (ids: string[]) => {
      const names: string[] = [];
      const traverse = (cats: any[]) => {
          cats.forEach(c => {
              if (ids.includes(c.id)) names.push(language === 'en' && c.nameEn ? c.nameEn : c.name);
              if (c.children) traverse(c.children);
          });
      };
      traverse(CATEGORY_TREE);
      return Array.from(new Set(names));
  };

  if (isLoading) return <div className="flex flex-col items-center justify-center h-64 text-slate-400 animate-pulse">...</div>;

  return (
    <>
    <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden flex flex-col h-full relative ring-1 ring-slate-900/5 transition-colors">

      {/* Batch Action Toolbar */}
      <div className={`absolute top-0 left-0 right-0 z-40 h-[52px] bg-emerald-600 dark:bg-emerald-600 backdrop-blur-md shadow-lg flex items-center justify-between px-4 transition-all duration-300 transform ${selectedIds.size > 0 ? 'translate-y-0 opacity-100' : '-translate-y-full opacity-0 pointer-events-none'}`}>
          <div className="flex items-center gap-4">
              <button 
                onClick={clearSelection}
                className="p-1.5 hover:bg-white/20 rounded-lg text-white transition-colors"
                title={t('deselectAll')}
              >
                  <X size={18} />
              </button>
              <div className="flex items-center gap-2 text-sm font-black text-white uppercase tracking-wider">
                  <span>{selectedIds.size} {t('selected')}</span>
              </div>
          </div>
          <div className="flex gap-2">
              <button 
                onClick={() => setIsBatchEditing(true)} 
                className="flex items-center gap-2 px-4 py-2 bg-white/10 hover:bg-white/20 text-white rounded-xl text-xs font-black transition-all border border-white/10"
              >
                  <ListChecks size={14} /> 
                  {t('editSelected')}
              </button>
              <button 
                onClick={() => setDeletingIds(Array.from(selectedIds))} 
                className="flex items-center gap-2 px-4 py-2 bg-rose-500 hover:bg-rose-400 text-white rounded-xl text-xs font-black transition-all shadow-md shadow-black/10"
              >
                  <Trash2 size={14} /> 
                  {t('deleteSelected')}
              </button>
          </div>
      </div>

      <div className="overflow-x-auto overflow-y-auto custom-scrollbar flex-1 relative">
        <table className="w-full text-sm text-left border-collapse">
          <thead className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase bg-slate-50/80 dark:bg-slate-950/80 sticky top-0 z-30 backdrop-blur-md border-b border-slate-100 dark:border-slate-800">
            <tr>
              <th className="w-12 px-4 py-3"><div onClick={toggleSelectAll} className="cursor-pointer flex justify-center">{isAllSelected ? <CheckSquare size={16} className="text-emerald-500"/> : (isIndeterminate ? <MinusSquare size={16} className="text-emerald-500"/> : <Square size={16}/>)}</div></th>
              {visibleColumns.map((col) => (
                <th key={col.key} onClick={() => handleSort(col.key)} className={`px-5 py-3 whitespace-nowrap cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors ${columnMaxValues[col.key] ? 'text-right' : 'text-left'}`}>
                  <div className={`flex items-center gap-1.5 ${columnMaxValues[col.key] ? 'justify-end' : 'justify-start'}`}>
                    <span className={sortConfig?.key === col.key ? 'text-emerald-500' : ''}>{tProp(col.label)}</span>
                    {sortConfig?.key === col.key && (sortConfig.direction === 'asc' ? <ArrowUp size={10} /> : <ArrowDown size={10} />)}
                  </div>
                </th>
              ))}
              <th className="px-5 py-3 text-right sticky right-0 z-40 bg-slate-50/90 dark:bg-slate-950/90 shadow-[-4px_0_12px_-4px_rgba(0,0,0,0.1)]">{t('actions')}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
            {paginatedData.map((product) => (
              <tr 
                key={product.id} 
                onClick={() => setViewingProduct(product)}
                className={`group cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-800/40 transition-colors ${selectedIds.has(product.id) ? 'bg-emerald-50/40 dark:bg-emerald-900/20' : ''}`}
              >
                <td className="px-4 py-3" onClick={(e) => e.stopPropagation()}>
                    <div onClick={() => { const s = new Set(selectedIds); if(s.has(product.id)) s.delete(product.id); else s.add(product.id); setSelectedIds(s); }} className="cursor-pointer flex justify-center text-slate-300 dark:text-slate-700 group-hover:text-emerald-500">
                        {selectedIds.has(product.id) ? <CheckSquare size={16} className="text-emerald-500"/> : <Square size={16}/>}
                    </div>
                </td>
                {visibleColumns.map((col) => {
                  const isNum = !!columnMaxValues[col.key];
                  const barWidth = isNum ? Math.min((Number(product.properties[col.key]?.value || 0) / columnMaxValues[col.key]) * 100, 100) : 0;
                  const property = product.properties[col.key];
                  const hasContext = property && (property.standard || property.temperature || property.referenceId);
                  const isHovered = hoveredCell?.productId === product.id && hoveredCell?.colKey === col.key;

                  return (
                    <td 
                      key={col.key} 
                      className={`px-5 py-3 whitespace-nowrap relative ${isNum ? 'text-right font-mono' : ''}`}
                      onMouseEnter={() => hasContext && setHoveredCell({ productId: product.id, colKey: col.key })}
                      onMouseLeave={() => setHoveredCell(null)}
                    >
                      {col.key === 'gradeName' ? (
                        <div className="flex flex-col">
                            <span className="font-bold text-slate-800 dark:text-slate-100">{product.gradeName}</span>
                            <span className="text-[9px] text-slate-400 flex items-center gap-1 uppercase tracking-wider font-semibold"><Factory size={10} /> {product.manufacturer}</span>
                        </div>
                      ) : col.key === 'manufacturer' ? (
                        <div className="flex flex-wrap gap-1 max-w-[200px]">
                            {getCategoryNames(product.categoryIds).slice(0, 3).map(name => (
                                <span key={name} className="px-1.5 py-0.5 bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 rounded text-[9px] font-bold border border-slate-200 dark:border-slate-700">{name}</span>
                            ))}
                            {product.categoryIds.length > 3 && <span className="text-[9px] text-slate-400">+{product.categoryIds.length - 3}</span>}
                        </div>
                      ) : isNum ? (
                        <>
                          <div className="absolute bottom-1 right-5 h-0.5 bg-emerald-500/10 rounded-full w-2/3">
                             <div className="h-full bg-emerald-500/40 rounded-full" style={{ width: `${barWidth}%` }}></div>
                          </div>
                          <div className="flex items-center justify-end gap-1.5 relative z-10">
                            {hasContext && <Info size={10} className={`shrink-0 transition-colors ${isHovered ? 'text-emerald-500' : 'text-slate-300'}`} />}
                            <span>{property?.value} <span className="text-[9px] text-slate-400 font-sans">{property?.unit}</span></span>
                          </div>
                          {isHovered && property && <PropertyContextTooltip prop={property} />}
                        </>
                      ) : (
                        <div className="flex items-center gap-1.5">
                           {hasContext && <Info size={10} className={`shrink-0 transition-colors ${isHovered ? 'text-emerald-500' : 'text-slate-300'}`} />}
                           <span className="text-slate-600 dark:text-slate-400 truncate max-w-[150px]">{String(property?.value || '-')}</span>
                           {isHovered && property && <PropertyContextTooltip prop={property} />}
                        </div>
                      )}
                    </td>
                  );
                })}
                <td className="px-5 py-3 text-right sticky right-0 bg-white dark:bg-slate-900 group-hover:bg-slate-50 transition-colors z-20" onClick={(e) => e.stopPropagation()}>
                   <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={() => setViewingProduct(product)} className="p-1.5 hover:text-emerald-500 transition-colors" title="View Details"><Eye size={14}/></button>
                      <button onClick={() => setEditingProduct(product)} className="p-1.5 hover:text-blue-500 transition-colors" title="Edit"><Edit size={14}/></button>
                      <button onClick={() => setDeletingIds([product.id])} className="p-1.5 hover:text-rose-500 transition-colors" title="Delete"><Trash2 size={14}/></button>
                   </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      <div className="p-3 border-t border-slate-100 dark:border-slate-800 flex justify-between items-center text-xs text-slate-500 bg-slate-50/50 dark:bg-slate-950/30">
          <div>{t('showing')} {(currentPage - 1) * pageSize + 1} - {Math.min(currentPage * pageSize, data.length)} / {data.length}</div>
          <div className="flex gap-2 items-center">
              <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} className="p-1.5 rounded bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition-colors"><ChevronLeft size={14} /></button>
              <span className="font-bold">{currentPage} / {totalPages}</span>
              <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} className="p-1.5 rounded bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition-colors"><ChevronRight size={14} /></button>
          </div>
      </div>
    </div>

    <ProductDetailDrawer 
        product={viewingProduct} 
        onClose={() => setViewingProduct(null)} 
        onCategoryClick={onCategorySelect} 
    />

    <EditProductModal isOpen={!!editingProduct} onClose={() => setEditingProduct(null)} product={editingProduct} onSave={onUpdate} />
    <BatchEditModal isOpen={isBatchEditing} onClose={() => setIsBatchEditing(false)} selectedProducts={data.filter(p => selectedIds.has(p.id))} onSave={(ids, updates) => { onBatchUpdate(ids, updates); setSelectedIds(new Set()); }} />
    <DeleteConfirmationModal isOpen={!!deletingIds} onClose={() => setDeletingIds(null)} onConfirm={() => { onDelete(deletingIds!); setSelectedIds(new Set()); }} productNames={deletingIds?.map(id => data.find(p => p.id === id)?.gradeName || '') || []} />
    </>
  );
};

import React, { useState, useEffect } from 'react';
import { X, Save, Factory, CheckCircle2, AlertCircle, ListChecks } from 'lucide-react';
import { Product, PropertyValue } from '../types';
import { useLanguage } from '../contexts/LanguageContext';

interface BatchEditModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (ids: string[], updates: Partial<Product>) => void;
  selectedProducts: Product[];
}

export const BatchEditModal: React.FC<BatchEditModalProps> = ({ isOpen, onClose, onSave, selectedProducts }) => {
  const { t, tProp } = useLanguage();

  // Track which fields are enabled for bulk update
  const [enabledFields, setEnabledFields] = useState<Record<string, boolean>>({
    manufacturer: false
  });

  const [manufacturer, setManufacturer] = useState('');
  const [properties, setProperties] = useState<Record<string, { value: string, unit: string, enabled: boolean }>>({});

  useEffect(() => {
    if (isOpen && selectedProducts.length > 0) {
      const first = selectedProducts[0];
      setManufacturer(first.manufacturer);

      // Initialize properties from all unique keys across selected products
      const allPropKeys = new Set<string>();
      selectedProducts.forEach(p => {
        Object.keys(p.properties).forEach(k => allPropKeys.add(k));
      });

      const initialProps: Record<string, any> = {};
      allPropKeys.forEach(key => {
        const p = first.properties[key];
        initialProps[key] = {
          value: p ? String(p.value) : '',
          unit: p?.unit || '',
          enabled: false
        };
      });
      setProperties(initialProps);
      setEnabledFields({ manufacturer: false });
    }
  }, [isOpen, selectedProducts]);

  if (!isOpen || selectedProducts.length === 0) return null;

  const handleSave = () => {
    const updates: Partial<Product> = {};
    const finalProperties: Record<string, PropertyValue> = {};

    if (enabledFields.manufacturer) {
      updates.manufacturer = manufacturer;
    }

    Object.entries(properties).forEach(([key, data]) => {
      if (data.enabled) {
        const numVal = Number(data.value);
        finalProperties[key] = {
          value: !isNaN(numVal) && data.value.trim() !== '' ? numVal : data.value,
          unit: data.unit.trim() || undefined
        };
      }
    });

    (updates as any)._propertyUpdates = finalProperties;

    onSave(selectedProducts.map(p => p.id), updates);
    onClose();
  };

  const toggleField = (field: string) => {
    setEnabledFields(prev => ({ ...prev, [field]: !prev[field] }));
  };

  const toggleProp = (key: string) => {
    setProperties(prev => ({
      ...prev,
      [key]: { ...prev[key], enabled: !prev[key].enabled }
    }));
  };

  const updateProp = (key: string, field: 'value' | 'unit', val: string) => {
    setProperties(prev => ({
      ...prev,
      [key]: { ...prev[key], [field]: val, enabled: true } // Auto-enable on edit
    }));
  };

  return (
    <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-in fade-in duration-300">
      <div className="w-full max-w-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]">

        {/* Header */}
        <div className="px-6 py-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-950/50">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-emerald-600 text-white rounded-xl shadow-lg shadow-emerald-500/20">
              <ListChecks size={20} />
            </div>
            <div>
              <h3 className="text-lg font-bold text-slate-900 dark:text-white leading-none">{t('batchEditTitle')}</h3>
              <p className="text-[10px] text-emerald-600 dark:text-emerald-400 uppercase tracking-widest mt-1 font-black">
                {selectedProducts.length} {t('selected')}
              </p>
            </div>
          </div>
          <button onClick={onClose} className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200">
            <X size={20} />
          </button>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto p-6 custom-scrollbar space-y-6">
          <div className="p-4 bg-amber-50 dark:bg-amber-900/10 border border-amber-100 dark:border-amber-900/30 rounded-2xl flex items-start gap-3">
             <AlertCircle size={18} className="text-amber-600 shrink-0 mt-0.5" />
             <p className="text-xs text-amber-800 dark:text-amber-400 leading-relaxed font-medium">
                {t('batchUpdateWarning')}
             </p>
          </div>

          {/* Manufacturer Field */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
               <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                  <Factory size={14} className="text-emerald-500" /> {tProp('生产厂家')}
               </label>
               <button 
                  onClick={() => toggleField('manufacturer')}
                  className={`text-[10px] px-3 py-1 rounded-full font-black uppercase tracking-tighter transition-all border ${enabledFields.manufacturer ? 'bg-emerald-600 border-emerald-600 text-white' : 'bg-slate-100 dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-400'}`}
               >
                  {enabledFields.manufacturer ? t('enableUpdate') : t('enableUpdate')}
               </button>
            </div>
            <input 
                type="text" 
                disabled={!enabledFields.manufacturer}
                value={manufacturer}
                onChange={(e) => setManufacturer(e.target.value)}
                className={`w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border rounded-2xl text-sm outline-none transition-all ${enabledFields.manufacturer ? 'border-emerald-500 ring-4 ring-emerald-500/10 text-slate-900 dark:text-white' : 'border-slate-200 dark:border-slate-700 opacity-50 grayscale text-slate-400 cursor-not-allowed'}`}
                placeholder="Enter manufacturer..."
            />
          </div>

          {/* Properties Section */}
          <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
             <h4 className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-4">{t('properties')}</h4>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                {Object.entries(properties).map(([key, data]) => (
                   <div key={key} className={`p-4 rounded-2xl border transition-all ${data.enabled ? 'bg-emerald-50/50 dark:bg-emerald-900/10 border-emerald-200 dark:border-emerald-800/50 shadow-sm' : 'bg-white dark:bg-slate-900 border-slate-100 dark:border-slate-800 opacity-60 hover:opacity-100'}`}>
                      <div className="flex items-center justify-between mb-3">
                         <span className={`text-xs font-bold truncate pr-2 ${data.enabled ? 'text-emerald-700 dark:text-emerald-400' : 'text-slate-500'}`}>{tProp(key)}</span>
                         <label className="flex items-center gap-2 cursor-pointer group">
                            <span className="text-[8px] font-black text-slate-400 uppercase tracking-tighter opacity-0 group-hover:opacity-100 transition-opacity">{t('enableUpdate')}</span>
                            <div 
                              onClick={() => toggleProp(key)}
                              className={`w-8 h-4 rounded-full relative transition-colors ${data.enabled ? 'bg-emerald-500' : 'bg-slate-200 dark:bg-slate-700'}`}
                            >
                                <div className={`absolute top-0.5 w-3 h-3 bg-white rounded-full transition-transform ${data.enabled ? 'translate-x-4 shadow-sm' : 'translate-x-0.5'}`}></div>
                            </div>
                         </label>
                      </div>
                      <div className="flex gap-2">
                        <input 
                            type="text" 
                            disabled={!data.enabled}
                            value={data.value}
                            onChange={(e) => updateProp(key, 'value', e.target.value)}
                            placeholder={t('propertyValue')}
                            className="flex-1 px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-xs font-mono outline-none focus:border-emerald-500 disabled:opacity-50 disabled:cursor-not-allowed"
                        />
                        <input 
                            type="text" 
                            disabled={!data.enabled}
                            value={data.unit}
                            onChange={(e) => updateProp(key, 'unit', e.target.value)}
                            placeholder={t('propertyUnit')}
                            className="w-16 px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-xs text-slate-500 outline-none focus:border-emerald-500 disabled:opacity-50 disabled:cursor-not-allowed"
                        />
                      </div>
                   </div>
                ))}
             </div>
          </div>
        </div>

        {/* Footer */}
        <div className="p-6 border-t border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/50 flex justify-end gap-3">
          <button onClick={onClose} className="px-6 py-2.5 text-xs font-black uppercase tracking-widest text-slate-500 hover:text-slate-700 dark:hover:text-slate-300 transition-colors">{t('cancel')}</button>
          <button 
            onClick={handleSave}
            className="px-8 py-2.5 bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-black uppercase tracking-widest rounded-xl shadow-xl shadow-emerald-500/20 transition-all active:scale-95 flex items-center gap-2"
          >
            <Save size={16} />
            {t('applyChanges')}
          </button>
        </div>
      </div>
    </div>
  );
};

