  const [allProducts, setAllProducts] = useState<Product[]>(MOCK_PRODUCTS);
  const [selectedCategoryId, setSelectedCategoryId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [columns, setColumns] = useState<ColumnConfig[]>([]);
  const [isImportOpen, setIsImportOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>('grid');

  useEffect(() => {
    setColumns(getDynamicColumns(allProducts));
  }, []);

  useEffect(() => {
     const newCols = getDynamicColumns(allProducts);
     if (newCols.length !== columns.length) {
         setColumns(newCols);
     }
  }, [allProducts.length]);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    localStorage.setItem('resindb-session', JSON.stringify(user));
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('resindb-session');
  };

  const handleUpdateUserProfile = (updatedInfo: any) => {
    if (!currentUser) return;

    const newUser = { ...currentUser, ...updatedInfo };
    setCurrentUser(newUser);
    localStorage.setItem('resindb-session', JSON.stringify(newUser));

    const allUsersStr = localStorage.getItem('resindb-users');
    if (allUsersStr) {
        const allUsers = JSON.parse(allUsersStr);
        const updatedUsers = allUsers.map((u: any) => 
            u.id === currentUser.id ? { ...u, ...updatedInfo } : u
        );
        localStorage.setItem('resindb-users', JSON.stringify(updatedUsers));
    }
  };

  const handleToggleColumn = (key: string) => {
    setColumns(cols => cols.map(c => 
      c.key === key ? { ...c, visible: !c.visible } : c
    ));
  };

  const handleToggleAllColumns = (visible: boolean) => {
    setColumns(cols => cols.map(c => 
      c.isSystem ? c : { ...c, visible }
    ));
  };

  const handleImportData = () => {
      const newProducts: Product[] = Array.from({ length: 5 }).map((_, i) => ({
        id: `imported-${Date.now()}-${i}`,
        gradeName: `New-Grade-${1000 + i} (Imported)`,
        manufacturer: 'Synthetic Tech Inc.',
        manufacturerId: 'm-30',
        categoryIds: ['cat_epdm_path_1'],
        updatedAt: new Date().toISOString().split('T')[0],
        properties: {
          '密度': { value: 0.92 + (Math.random() * 0.05), unit: 'g/cm³' },
          '熔体流动速率': { value: 1 + (Math.random() * 5), unit: 'g/10min' },
          '应用': { value: 'Imported batch test' }
        }
      }));

      setAllProducts(prev => [...newProducts, ...prev]);
      setIsImportOpen(false);
  };

  const handleDeleteProducts = (ids: string[]) => {
    setAllProducts(prev => prev.filter(p => !ids.includes(p.id)));
  };

  const handleUpdateProduct = (updatedProduct: Product) => {
    setAllProducts(prev => prev.map(p => p.id === updatedProduct.id ? updatedProduct : p));
  };

  const handleBatchUpdate = (ids: string[], updates: Partial<Product>) => {
    const { _propertyUpdates, ...directUpdates } = updates as any;

    setAllProducts(prev => prev.map(p => {
      if (!ids.includes(p.id)) return p;

      const newProps = { ...p.properties };
      if (_propertyUpdates) {
        Object.entries(_propertyUpdates).forEach(([key, val]) => {
          newProps[key] = val as PropertyValue;
        });
      }

      return {
        ...p,
        ...directUpdates,
        properties: newProps,
        updatedAt: new Date().toISOString().split('T')[0]
      };
    }));
  };

  const filteredData = useMemo(() => {
    return allProducts.filter(product => {
      const matchesCategory = selectedCategoryId 
        ? product.categoryIds.includes(selectedCategoryId)
        : true;

      if (!matchesCategory) return false;

      const query = searchQuery.toLowerCase();
      const matchesSearch = 
        product.gradeName.toLowerCase().includes(query) ||
        product.manufacturer.toLowerCase().includes(query) ||
        Object.keys(product.properties).some(k => k.toLowerCase().includes(query));

      return matchesSearch;
    });
  }, [allProducts, selectedCategoryId, searchQuery]);

  if (!currentUser) {
    return <AuthScreen onLogin={handleLogin} />;
  }

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 font-sans text-slate-900 dark:text-slate-100 overflow-hidden transition-colors duration-300">

      <TreeSidebar 
        categories={CATEGORY_TREE}
        selectedCategoryId={selectedCategoryId}
        onSelectCategory={setSelectedCategoryId}
      />

      <div className="flex-1 flex flex-col min-w-0 h-full relative">

        <TopBar 
            user={currentUser}
            onLogout={handleLogout}
            onOpenProfile={() => setIsProfileOpen(true)}
            onOpenAdmin={() => setIsAdminOpen(true)}
            searchQuery={searchQuery}
            onSearchChange={setSearchQuery}
            columns={columns}
            onToggleColumn={handleToggleColumn}
            onToggleAllColumns={handleToggleAllColumns}
            onOpenImport={() => setIsImportOpen(true)}
            viewMode={viewMode}
            onViewModeChange={setViewMode}
        />

        <div className="flex-1 flex flex-col p-6 min-h-0 overflow-hidden">

            <Breadcrumbs categoryId={selectedCategoryId} />

            <SummaryStats data={filteredData} />

            <div className="flex-1 w-full min-h-0 relative animate-in fade-in zoom-in-95 duration-300">
                <ErrorBoundary>
                    {viewMode === 'grid' ? (
                         <div className="absolute inset-0 pb-1">
                            <DataGrid 
                                data={filteredData}
                                columns={columns}
                                isLoading={false}
                                onDelete={handleDeleteProducts}
                                onUpdate={handleUpdateProduct}
                                onBatchUpdate={handleBatchUpdate}
                                onCategorySelect={setSelectedCategoryId}
                            />
                         </div>
                    ) : (
                        <div className="absolute inset-0">
                            <DataVisualizer data={filteredData} />
                        </div>
                    )}
                </ErrorBoundary>
            </div>
        </div>
      </div>

      <ImportModal 
        isOpen={isImportOpen} 
        onClose={() => setIsImportOpen(false)} 
        onImport={handleImportData}
      />

      <ProfileModal
        isOpen={isProfileOpen}
        onClose={() => setIsProfileOpen(false)}
        user={currentUser}
        onSave={handleUpdateUserProfile}
      />

      <AdminModal
        isOpen={isAdminOpen}
        onClose={() => setIsAdminOpen(false)}
      />

      <AIAssistant contextData={filteredData} />
    </div>
  );
};

