                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis dataKey="gradeName" angle={-45} textAnchor="end" interval={0} height={60} fontSize={10} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} />
                            <YAxis fontSize={10} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} domain={['auto', 'auto']} />
                            <Tooltip cursor={{ fill: 'rgba(16, 185, 129, 0.05)' }} content={<CustomTooltipContent />} />
                            {groupByKey && (
                              <Legend 
                                verticalAlign="top"
                                content={RenderCustomLegend}
                              />
                            )}
                            <Bar dataKey={yAxisKey} radius={[4, 4, 0, 0]} animationDuration={1000}>
                                {visibleChartData.map((entry, index) => {
                                    const group = String(entry[groupByKey] || 'Unknown');
                                    const isHighlighted = highlightedGroup === null || highlightedGroup === group;
                                    return (
                                        <Cell 
                                            key={`cell-${index}`} 
                                            fill={groupByKey ? groupColors[group] : DEFAULT_PALETTE[index % DEFAULT_PALETTE.length]} 
                                            fillOpacity={isHighlighted ? 1 : 0.15}
                                        />
                                    );
                                })}
                            </Bar>
                        </BarChart>
                    ) : (
                        <ComposedChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis type={xAxisKey === 'gradeName' ? 'category' : 'number'} dataKey={xAxisKey} name={tProp(xAxisKey)} fontSize={10} domain={[xMin === '' ? 'auto' : xMin, xMax === '' ? 'auto' : xMax]} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} label={{ value: tProp(xAxisKey), position: 'bottom', offset: 0, fontSize: 10, fill: '#64748b' }} />
                            <YAxis type="number" dataKey={yAxisKey} name={tProp(yAxisKey)} fontSize={10} domain={[yMin === '' ? 'auto' : yMin, yMax === '' ? 'auto' : yMax]} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} label={{ value: tProp(yAxisKey), angle: -90, position: 'insideLeft', offset: 10, fontSize: 10, fill: '#64748b' }} />
                            <ZAxis range={[60, 400]} />
                            <Tooltip cursor={{ strokeDasharray: '3 3' }} content={<CustomTooltipContent />} />
                            {groupByKey && (
                              <Legend 
                                verticalAlign="top"
                                content={RenderCustomLegend}
                              />
                            )}
                            <Scatter name="Resin Samples" data={visibleChartData} animationDuration={1500}>
                                {visibleChartData.map((entry, index) => {
                                    const group = String(entry[groupByKey] || 'Unknown');
                                    const isHighlighted = highlightedGroup === null || highlightedGroup === group;
                                    return (
                                        <Cell 
                                            key={`cell-${index}`} 
                                            fill={groupByKey ? groupColors[group] : '#10b981'} 
                                            fillOpacity={isHighlighted ? 1 : 0.1}
                                            strokeOpacity={isHighlighted ? 1 : 0.1}
                                            strokeWidth={1} 
                                            stroke="#ffffff" 
                                        />
                                    );
                                })}
                            </Scatter>
                            {trendlineSegment && (
                                <Line type="monotone" data={trendlineSegment} dataKey={yAxisKey} stroke={trendlineColor} strokeWidth={trendlineWidth} strokeDasharray={dashArray} dot={false} activeDot={false} legendType="none" />
                            )}
                        </ComposedChart>
                    )}
                </ResponsiveContainer>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { X, Save, Plus, Trash2, Beaker, Factory } from 'lucide-react';
import { Product, PropertyValue } from '../types';
import { useLanguage } from '../contexts/LanguageContext';

interface EditProductModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (product: Product) => void;
  product: Product | null;
}

interface PropertyRow {
  id: string;
  key: string;
  value: string;
  unit: string;
}

export const EditProductModal: React.FC<EditProductModalProps> = ({ isOpen, onClose, onSave, product }) => {
  const { t, tProp } = useLanguage();
  const [formData, setFormData] = useState<Partial<Product>>({});
  const [propertyRows, setPropertyRows] = useState<PropertyRow[]>([]);

  // Dedicated states for common properties for better UX
  const [ethyleneData, setEthyleneData] = useState({ value: '', unit: '' });
  const [densityData, setDensityData] = useState({ value: '', unit: '' });
  const [mfrData, setMfrData] = useState({ value: '', unit: '' });

  useEffect(() => {
    if (product) {
      setFormData({
        id: product.id,
        gradeName: product.gradeName,
        manufacturer: product.manufacturer,
        categoryIds: product.categoryIds,
        updatedAt: product.updatedAt,
      });

      // Handle dedicated Density field
      // Fix: Cast explicitly to PropertyValue
      const denProp = product.properties['密度'] as PropertyValue | undefined;
      setDensityData({
        value: denProp ? String(denProp.value) : '',
        unit: denProp?.unit || 'g/cm³'
      });

      // Handle dedicated MFR field
      // Fix: Cast explicitly to PropertyValue
      const mfrProp = product.properties['熔体流动速率'] as PropertyValue | undefined;
      setMfrData({
        value: mfrProp ? String(mfrProp.value) : '',
        unit: mfrProp?.unit || 'g/10min'
      });

      // Handle dedicated Ethylene Content field
      // Fix: Cast explicitly to PropertyValue
      const ethProp = product.properties['乙烯含量'] as PropertyValue | undefined;
      setEthyleneData({
        value: ethProp ? String(ethProp.value) : '',
        unit: ethProp?.unit || '%'
      });

      // Filter out dedicated fields from dynamic rows to avoid duplicates
      const dedicatedKeys = ['乙烯含量', '密度', '熔体流动速率'];
      // Fix: Cast entries to satisfy compiler
      const rows: PropertyRow[] = (Object.entries(product.properties) as [string, PropertyValue][])
        .filter(([key]) => !dedicatedKeys.includes(key))
        .map(([key, val], index) => ({
          id: `prop-${index}-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
          key,
          value: String(val.value),
          unit: val.unit || ''
        }));
      setPropertyRows(rows);
    }
  }, [product, isOpen]);

  if (!isOpen || !product) return null;

  const handleSave = () => {
    const newProperties: Record<string, PropertyValue> = {};

    // Add dedicated Density
    if (densityData.value.trim() !== '') {
        const numVal = Number(densityData.value);
        newProperties['密度'] = {
            value: !isNaN(numVal) ? numVal : densityData.value,
            unit: densityData.unit.trim() || undefined
        };
    }

    // Add dedicated MFR
    if (mfrData.value.trim() !== '') {
        const numVal = Number(mfrData.value);
        newProperties['熔体流动速率'] = {
            value: !isNaN(numVal) ? numVal : mfrData.value,
            unit: mfrData.unit.trim() || undefined
        };
    }

    // Add dedicated Ethylene Content
    if (ethyleneData.value.trim() !== '') {
        const numVal = Number(ethyleneData.value);
        newProperties['乙烯含量'] = {
            value: !isNaN(numVal) ? numVal : ethyleneData.value,
            unit: ethyleneData.unit.trim() || undefined
        };
    }

    propertyRows.forEach(row => {
      if (row.key.trim()) {
        const numVal = Number(row.value);
        newProperties[row.key] = {
          value: !isNaN(numVal) && row.value.trim() !== '' ? numVal : row.value,
          unit: row.unit.trim() || undefined
        };
      }
    });

    onSave({
      ...product,
      ...formData as Product,
      properties: newProperties,
      updatedAt: new Date().toISOString().split('T')[0]
    });
    onClose();
  };

  const addProperty = () => {
    setPropertyRows([...propertyRows, { id: `new-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`, key: '', value: '', unit: '' }]);
  };

  const removeProperty = (id: string) => {
    setPropertyRows(prev => prev.filter(p => p.id !== id));
  };

  const updateProperty = (id: string, field: keyof PropertyRow, val: string) => {
    setPropertyRows(prev => prev.map(p => p.id === id ? { ...p, [field]: val } : p));
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="w-full max-w-2xl bg-white dark:bg-slate-900 rounded-xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200 ring-1 ring-slate-200 dark:ring-slate-800 flex flex-col max-h-[90vh]">

        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/50">
          <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 flex items-center justify-center">
                <Beaker size={18} />
            </div>
            {t('editProduct')}
          </h3>
          <button onClick={onClose} type="button" className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors">
            <X size={20} />
          </button>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">

            {/* Basic Info Section */}
            <div className="mb-6">
                <h4 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-4 border-b border-slate-100 dark:border-slate-800 pb-2">
                    {t('basicInfo')}
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                        <label className="text-sm font-medium text-slate-700 dark:text-slate-300">{tProp('牌号')}</label>
                        <input 
                            type="text" 
                            value={formData.gradeName || ''}
                            onChange={(e) => setFormData({...formData, gradeName: e.target.value})}
                            className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all"
                        />
                    </div>
                    <div className="space-y-1.5">
                        <label className="text-sm font-medium text-slate-700 dark:text-slate-300">{tProp('生产厂家')}</label>
                        <div className="relative">
                            <Factory size={16} className="absolute left-3 top-2.5 text-slate-400" />
                            <input 
                                type="text" 
                                value={formData.manufacturer || ''}
                                onChange={(e) => setFormData({...formData, manufacturer: e.target.value})}
                                className="w-full pl-9 pr-3 py-2 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all"
                            />
                        </div>
                    </div>
                </div>
            </div>

            {/* Dynamic Properties Section */}
            <div>
                <div className="flex items-center justify-between mb-4 border-b border-slate-100 dark:border-slate-800 pb-2">
                    <h4 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                        {t('properties')}
                    </h4>
                    <button 
                        onClick={addProperty}
                        type="button"
                        className="text-xs flex items-center gap-1 text-emerald-600 dark:text-emerald-400 hover:text-emerald-700 font-medium px-2 py-1 rounded hover:bg-emerald-50 dark:hover:bg-emerald-900/20 transition-colors"
                    >
                        <Plus size={14} /> {t('addProperty')}
                    </button>
                </div>

                <div className="space-y-2">

                    {/* Specific Ethylene Content Field */}
                    <div className="flex items-center gap-2 group p-0.5 rounded-md hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                        <div className="flex-1 px-3 py-2 bg-slate-100 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-700 rounded-md text-sm text-slate-600 dark:text-slate-400 font-medium select-none">
                            {tProp('乙烯含量')}
                        </div>
                        <input 
                            type="text" 
                            placeholder={t('propertyValue')}
                            value={ethyleneData.value}
                            onChange={(e) => setEthyleneData(prev => ({ ...prev, value: e.target.value }))}
                            className="flex-1 px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md text-sm focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 outline-none font-mono"
                        />
                        <input 
                            type="text" 
                            placeholder={t('propertyUnit')}
                            value={ethyleneData.unit}
                            onChange={(e) => setEthyleneData(prev => ({ ...prev, unit: e.target.value }))}
                            className="w-20 px-3 py-2 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-md text-sm text-slate-500 focus:border-emerald-500 outline-none"
                        />
                        <div className="w-[34px]"></div>
                    </div>

                    {/* Specific Density Field */}
                    <div className="flex items-center gap-2 group p-0.5 rounded-md hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                        <div className="flex-1 px-3 py-2 bg-slate-100 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-700 rounded-md text-sm text-slate-600 dark:text-slate-400 font-medium select-none">
                            {tProp('密度')}
                        </div>
                        <input 
                            type="text" 
                            placeholder={t('propertyValue')}
                            value={densityData.value}
                            onChange={(e) => setDensityData(prev => ({ ...prev, value: e.target.value }))}
                            className="flex-1 px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md text-sm focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 outline-none font-mono"
                        />
                        <input 
                            type="text" 
                            placeholder={t('propertyUnit')}
                            value={densityData.unit}
                            onChange={(e) => setDensityData(prev => ({ ...prev, unit: e.target.value }))}
                            className="w-20 px-3 py-2 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-md text-sm text-slate-500 focus:border-emerald-500 outline-none"
                        />
                        <div className="w-[34px]"></div>
                    </div>

                    {/* Specific MFR Field */}
                    <div className="flex items-center gap-2 group p-0.5 rounded-md hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                        <div className="flex-1 px-3 py-2 bg-slate-100 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-700 rounded-md text-sm text-slate-600 dark:text-slate-400 font-medium select-none">
                            {tProp('熔体流动速率')}
                        </div>
                        <input 
                            type="text" 
                            placeholder={t('propertyValue')}
                            value={mfrData.value}
                            onChange={(e) => setMfrData(prev => ({ ...prev, value: e.target.value }))}
                            className="flex-1 px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md text-sm focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 outline-none font-mono"
                        />
                        <input 
                            type="text" 
                            placeholder={t('propertyUnit')}
                            value={mfrData.unit}
                            onChange={(e) => setMfrData(prev => ({ ...prev, unit: e.target.value }))}
                            className="w-20 px-3 py-2 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-md text-sm text-slate-500 focus:border-emerald-500 outline-none"
                        />
                        <div className="w-[34px]"></div>
                    </div>

                    {propertyRows.map((row) => (
                        <div key={row.id} className="flex items-center gap-2 group">
                            <input 
                                type="text" 
                                placeholder={t('propertyName')}
                                value={row.key}
                                onChange={(e) => updateProperty(row.id, 'key', e.target.value)}
                                className="flex-1 px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md text-sm focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 outline-none"
                            />
                            <input 
                                type="text" 
                                placeholder={t('propertyValue')}
                                value={row.value}
                                onChange={(e) => updateProperty(row.id, 'value', e.target.value)}
                                className="flex-1 px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md text-sm focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 outline-none font-mono"
                            />
                            <input 
                                type="text" 
                                placeholder={t('propertyUnit')}
                                value={row.unit}
                                onChange={(e) => updateProperty(row.id, 'unit', e.target.value)}
                                className="w-20 px-3 py-2 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-md text-sm text-slate-500 focus:border-emerald-500 outline-none"
                            />
                            <button 
                                onClick={() => removeProperty(row.id)}
                                type="button"
                                className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-md transition-colors opacity-0 group-hover:opacity-100 focus:opacity-100"
                                title={t('delete')}
                            >
                                <Trash2 size={16} />
                            </button>
                        </div>
                    ))}
                    {propertyRows.length === 0 && ethyleneData.value === '' && densityData.value === '' && mfrData.value === '' && (
                        <div className="text-center py-6 text-slate-400 dark:text-slate-600 text-sm italic border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-lg">
                            No properties defined. Click "Add Property" to start.
                        </div>
                    )}
                </div>
            </div>

        </div>

        {/* Footer */}
        <div className="p-4 border-t border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/50 flex justify-end gap-3">
            <button 
                onClick={onClose}
                type="button"
                className="px-4 py-2 text-sm font-medium text-slate-600 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors"
            >
                {t('cancel')}
            </button>
            <button 
                onClick={handleSave}
                type="button"
                className="px-4 py-2 text-sm font-medium text-white bg-emerald-600 hover:bg-emerald-700 rounded-lg shadow-md shadow-emerald-500/20 flex items-center gap-2 transition-all active:scale-95"
            >
                <Save size={16} />
                {t('save')}
            </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { X, Save, Factory, CheckCircle2, AlertCircle, ListChecks } from 'lucide-react';
import { Product, PropertyValue } from '../types';
import { useLanguage } from '../contexts/LanguageContext';

interface BatchEditModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (ids: string[], updates: Partial<Product>) => void;
  selectedProducts: Product[];
}

export const BatchEditModal: React.FC<BatchEditModalProps> = ({ isOpen, onClose, onSave, selectedProducts }) => {
  const { t, tProp } = useLanguage();

  // Track which fields are enabled for bulk update
  const [enabledFields, setEnabledFields] = useState<Record<string, boolean>>({
    manufacturer: false
  });

  const [manufacturer, setManufacturer] = useState('');
  const [properties, setProperties] = useState<Record<string, { value: string, unit: string, enabled: boolean }>>({});

  useEffect(() => {
    if (isOpen && selectedProducts.length > 0) {
      const first = selectedProducts[0];
      setManufacturer(first.manufacturer);

      // Initialize properties from all unique keys across selected products
      const allPropKeys = new Set<string>();
      selectedProducts.forEach(p => {
        Object.keys(p.properties).forEach(k => allPropKeys.add(k));
      });

      const initialProps: Record<string, { value: string, unit: string, enabled: boolean }> = {};
      allPropKeys.forEach(key => {
        const p = first.properties[key] as PropertyValue | undefined;
        initialProps[key] = {
          value: p ? String(p.value) : '',
          unit: p?.unit || '',
          enabled: false
        };
      });
      setProperties(initialProps);
      setEnabledFields({ manufacturer: false });
    }
  }, [isOpen, selectedProducts]);

  if (!isOpen || selectedProducts.length === 0) return null;

  const handleSave = () => {
    const updates: Partial<Product> = {};
    const finalProperties: Record<string, PropertyValue> = {};

    if (enabledFields.manufacturer) {
      updates.manufacturer = manufacturer;
    }

    // Fix: Cast explicitly to satisfy compiler
    (Object.entries(properties) as [string, { value: string, unit: string, enabled: boolean }][]).forEach(([key, data]) => {
      if (data.enabled) {
        const numVal = Number(data.value);
        finalProperties[key] = {
          value: !isNaN(numVal) && data.value.trim() !== '' ? numVal : data.value,
          unit: data.unit.trim() || undefined
        };
      }
    });

    (updates as any)._propertyUpdates = finalProperties;

    onSave(selectedProducts.map(p => p.id), updates);
    onClose();
  };

  const toggleField = (field: string) => {
    setEnabledFields(prev => ({ ...prev, [field]: !prev[field] }));
  };

  const toggleProp = (key: string) => {
    setProperties(prev => ({
      ...prev,
      [key]: { ...prev[key], enabled: !prev[key].enabled }
    }));
  };

  const updateProp = (key: string, field: 'value' | 'unit', val: string) => {
    setProperties(prev => ({
      ...prev,
      [key]: { ...prev[key], [field]: val, enabled: true } // Auto-enable on edit
    }));
  };

  return (
    <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-in fade-in duration-300">
      <div className="w-full max-w-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]">

        {/* Header */}
        <div className="px-6 py-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-950/50">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-emerald-600 text-white rounded-xl shadow-lg shadow-emerald-500/20">
              <ListChecks size={20} />
            </div>
            <div>
              <h3 className="text-lg font-bold text-slate-900 dark:text-white leading-none">{t('batchEditTitle')}</h3>
              <p className="text-[10px] text-emerald-600 dark:text-emerald-400 uppercase tracking-widest mt-1 font-black">
                {selectedProducts.length} {t('selected')}
              </p>
            </div>
          </div>
          <button onClick={onClose} className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200">
            <X size={20} />
          </button>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto p-6 custom-scrollbar space-y-6">
          <div className="p-4 bg-amber-50 dark:bg-amber-900/10 border border-amber-100 dark:border-amber-900/30 rounded-2xl flex items-start gap-3">
             <AlertCircle size={18} className="text-amber-600 shrink-0 mt-0.5" />
             <p className="text-xs text-amber-800 dark:text-amber-400 leading-relaxed font-medium">
                {t('batchUpdateWarning')}
             </p>
          </div>

          {/* Manufacturer Field */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
               <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                  <Factory size={14} className="text-emerald-500" /> {tProp('生产厂家')}
               </label>
               <button 
                  onClick={() => toggleField('manufacturer')}
