import React, { useMemo } from 'react';
import { X, ChevronRight, Layers, Factory, Microscope, LayoutGrid, Globe, Info, BookOpen, ExternalLink, Calendar, FileText, ShieldCheck, Link2 } from 'lucide-react';
import { Product, Category, Manufacturer, Reference, PropertyValue } from '../types';
import { CATEGORY_TREE, MANUFACTURERS, REFERENCES } from '../constants';
import { useLanguage } from '../contexts/LanguageContext';

interface ProductDetailDrawerProps {
  product: Product | null;
  onClose: () => void;
  onCategoryClick: (id: string) => void;
}

export const ProductDetailDrawer: React.FC<ProductDetailDrawerProps> = ({ product, onClose, onCategoryClick }) => {
  const { t, tProp, language } = useLanguage();

  const manufacturer = useMemo(() => 
    MANUFACTURERS.find(m => m.id === product?.manufacturerId), 
  [product]);

  const relevantRefs = useMemo(() => {
    if (!product) return [];
    // Fix: Cast explicitly to PropertyValue[]
    const refIds = new Set((Object.values(product.properties) as PropertyValue[]).map(p => p.referenceId).filter(Boolean));
    return REFERENCES.filter(r => refIds.has(r.id as string));
  }, [product]);

  // 深度查找算法：生成该牌号在多路径分类体系下的所有路径列表
  const allPaths = useMemo(() => {
    if (!product) return [];
    const paths: {segments: string[], leafId: string}[] = [];

    const findPaths = (nodes: Category[], targetId: string, currentPath: string[]) => {
      for (const node of nodes) {
        const nodeName = language === 'en' && node.nameEn ? node.nameEn : node.name;
        const newPath = [...currentPath, nodeName];
        if (node.id === targetId) {
            paths.push({ segments: newPath, leafId: node.id });
        }
        if (node.children) findPaths(node.children, targetId, newPath);
      }
    };

    product.categoryIds.forEach(id => findPaths(CATEGORY_TREE, id, []));
    return paths;
  }, [product, language]);

  if (!product) return null;

  return (
    <div className={`fixed inset-y-0 right-0 w-[580px] bg-white dark:bg-slate-900 shadow-2xl z-[60] border-l border-slate-200 dark:border-slate-800 transition-transform duration-300 transform ${product ? 'translate-x-0' : 'translate-x-full'} flex flex-col`}>
      {/* Header */}
      <div className="px-6 py-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-950/50">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-emerald-600 rounded-xl flex items-center justify-center text-white shadow-lg">
            <Microscope size={20} />
          </div>
          <div>
            <h3 className="text-lg font-bold text-slate-900 dark:text-white leading-none">{product.gradeName}</h3>
            <p className="text-[10px] text-slate-500 uppercase tracking-widest mt-1 font-black">牌号数据的结构化二维描述</p>
          </div>
        </div>
        <button onClick={onClose} className="p-2 text-slate-400 hover:text-rose-500 transition-colors">
          <X size={24} />
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-6 custom-scrollbar space-y-8">

        {/* 多路径访问溯源 (Redundant Paths) - 核心还原自设计图 */}
        <section className="space-y-4">
          <div className="flex items-center gap-2 text-xs font-black text-slate-400 uppercase tracking-widest">
            <Link2 size={14} className="text-blue-500" />
            多路径分类溯源 (所属分类)
          </div>
          <div className="bg-blue-50/30 dark:bg-blue-900/10 border border-blue-100/50 dark:border-blue-800/30 rounded-2xl p-4 space-y-2">
            {allPaths.map((path, idx) => (
              <button 
                key={idx} 
                onClick={() => onCategoryClick(path.leafId)}
                className="w-full text-left group flex items-center gap-1.5 py-1"
              >
                <div className="flex flex-wrap items-center text-[11px]">
                  {path.segments.map((segment, sIdx) => (
                    <React.Fragment key={sIdx}>
                      <span className={`transition-colors ${sIdx === path.segments.length - 1 ? 'font-bold text-blue-600 dark:text-blue-400' : 'text-slate-500 group-hover:text-blue-400'}`}>
                        {segment}
                      </span>
                      {sIdx < path.segments.length - 1 && (
                        <ChevronRight size={10} className="mx-1 text-slate-300" />
                      )}
                    </React.Fragment>
                  ))}
                </div>
              </button>
            ))}
          </div>
          <p className="text-[10px] text-slate-400 italic pl-2">特点：指向同一目标，数据不冗余，支持多种习惯访问路径。</p>
        </section>

        {/* 生产厂家 */}
        <section className="space-y-3">
            <div className="flex items-center gap-2 text-xs font-black text-slate-400 uppercase tracking-widest">
                <Factory size={14} className="text-emerald-500" />
                {tProp('生产厂家')}
            </div>
            {manufacturer ? (
                <div className="p-4 bg-emerald-50/30 dark:bg-emerald-900/10 border border-emerald-100/50 dark:border-emerald-800/30 rounded-2xl space-y-2">
                    <div className="flex items-center justify-between">
                        <span className="font-bold text-slate-800 dark:text-slate-100">{manufacturer.name}</span>
                        {manufacturer.website && (
                            <a href={`https://${manufacturer.website}`} target="_blank" rel="noreferrer" className="text-[10px] text-emerald-600 hover:underline flex items-center gap-1">
                                <Globe size={12} /> 官网
                            </a>
                        )}
                    </div>
                    <p className="text-xs text-slate-600 dark:text-slate-400 leading-relaxed italic">{manufacturer.description}</p>
                </div>
            ) : (
                <div className="px-4 py-3 bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl text-sm font-bold text-slate-700 dark:text-slate-200">
                    {product.manufacturer}
                </div>
            )}
