                            <th className="px-3 py-3 text-slate-500 font-bold uppercase tracking-tighter w-12 text-center">出处</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
                        {/* Fix: Explicitly cast entries to satisfy compiler */}
                        {(Object.entries(product.properties) as [string, PropertyValue][]).map(([key, prop]) => (
                            <tr key={key} className="hover:bg-slate-50/50 dark:hover:bg-slate-800/20 transition-colors">
                                <td className="px-3 py-4 font-bold text-slate-700 dark:text-slate-200">{tProp(key)}</td>
                                <td className="px-3 py-4 font-mono font-bold text-emerald-600 dark:text-emerald-400">
                                    {prop.value} <span className="text-[9px] text-slate-400 font-sans ml-0.5">{prop.unit}</span>
                                </td>
                                <td className="px-3 py-4">
                                    <div className="flex flex-col gap-0.5">
                                        <span className="text-slate-500 dark:text-slate-400">{prop.standard || '-'}</span>
                                        {prop.temperature && (
                                            <span className="text-[9px] text-slate-400 flex items-center gap-1 uppercase">
                                                <Info size={10} className="text-blue-400" /> {prop.temperature}
                                            </span>
                                        )}
                                    </div>
                                </td>
                                <td className="px-3 py-4 text-center">
                                    {prop.referenceId && (
                                        <span className="inline-flex items-center justify-center w-5 h-5 bg-slate-100 dark:bg-slate-800 text-[10px] font-black rounded text-slate-400" title="引用文献详情">
                                            {prop.referenceId.split('-')[1]}
                                        </span>
                                    )}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </section>

        {/* 参考文献 */}
        {relevantRefs.length > 0 && (
            <section className="space-y-4">
                <div className="flex items-center gap-2 text-xs font-black text-slate-400 uppercase tracking-widest">
                    <BookOpen size={14} className="text-emerald-500" />
                    关联参考文献库
                </div>
                <div className="space-y-2">
                    {relevantRefs.map(ref => (
                        <div key={ref.id} className="group p-3 bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-xl hover:shadow-md transition-all flex items-start gap-3">
                            <div className="p-2 bg-slate-50 dark:bg-slate-800 rounded-lg text-slate-400 group-hover:text-emerald-500 transition-colors">
                                <FileText size={16} />
                            </div>
                            <div className="flex-1 overflow-hidden">
                                <div className="flex items-center justify-between mb-0.5">
                                    <h5 className="text-xs font-bold text-slate-800 dark:text-slate-200 truncate">{ref.name}</h5>
                                    <span className="text-[10px] font-bold text-slate-400 flex items-center gap-1">
                                        <Calendar size={10} /> {ref.year}
                                    </span>
                                </div>
                                <p className="text-[10px] text-slate-500">作者: {ref.author || 'N/A'}</p>
                            </div>
                        </div>
                    ))}
                </div>
            </section>
        )}
      </div>

      <div className="p-6 bg-slate-50 dark:bg-slate-950/50 border-t border-slate-100 dark:border-slate-800 text-[10px] text-slate-400 flex items-center gap-3">
        <ShieldCheck size={14} className="text-emerald-500" />
        <div>
            <p className="font-bold uppercase tracking-widest text-[8px] mb-0.5">PetroChina Resin Data Integrity</p>
            <p>本系统已通过多路径分类索引，确保物性数据在不同业务视角下的一致性与可追溯性。</p>
        </div>
      </div>
    </div>
  );
};

