              >
                <Trash2 size={10} />
                {t('clearHistory')}
              </button>
            </div>
            <div className="py-2 max-h-[320px] overflow-y-auto custom-scrollbar">
              {searchHistory.map((query, idx) => (
                <div 
                  key={`${query}-${idx}`}
