                    <span className="text-sm text-slate-600 dark:text-slate-300 truncate font-medium">{query}</span>
                  </div>
                  <button 
                    onClick={(e) => removeFromHistory(query, e)}
                    className="p-1 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all rounded-md hover:bg-rose-50 dark:hover:bg-rose-900/20"
                  >
                    <X size={14} />
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Right Actions Area */}
      <div className="flex items-center gap-3 ml-4">

        {/* View Switcher */}
        <div className="flex items-center p-1 bg-slate-100 dark:bg-slate-800/80 rounded-lg border border-slate-200 dark:border-slate-700/50">
