                                </label>
                            ))}
                        </div>
                    </div>
                    </>
                )}
            </div>
        )}

        {/* Action Group */}
        <div className="flex items-center bg-slate-100 dark:bg-slate-800/80 rounded-xl p-1 border border-slate-200 dark:border-slate-700/50">
            <button onClick={onOpenImport} className="p-2 text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-100 hover:bg-white dark:hover:bg-slate-700 rounded-lg transition-all" title={t('importData')}>
              <Upload size={18} />
