const FormattedText: React.FC<{ text: string; className?: string }> = ({ text, className }) => {
  if (!text) return null;
  return (
    <div className={className}>
      {text.split('\n').map((line, i) => {
        const trimmed = line.trim();
        if (trimmed.startsWith('- ') || trimmed.startsWith('* ') || trimmed.match(/^\d+\./)) {
             const cleanLine = trimmed.replace(/^[-*]\s+|\d+\.\s+/, '');
             const parts = cleanLine.split(/(\*\*.*?\*\*)/g);
             return (
                <div key={i} className="flex gap-2.5 ml-1 mb-1.5 items-start">
                    <span className="text-emerald-500 dark:text-emerald-400 mt-1.5 shrink-0 text-[10px]">•</span>
                    <span className="leading-relaxed text-sm">
                        {parts.map((part, j) => {
                            if (part.startsWith('**') && part.endsWith('**')) {
                                return <strong key={j} className="font-bold text-slate-800 dark:text-white">{part.slice(2, -2)}</strong>;
                            }
                            return <span key={j}>{part}</span>;
                        })}
                    </span>
                </div>
             );
        }
        const parts = line.split(/(\*\*.*?\*\*)/g);
        if (line.startsWith('##')) return <h3 key={i} className="font-bold text-emerald-700 dark:text-emerald-400 mt-4 mb-2 text-base">{line.replace(/#/g, '')}</h3>
        if (!trimmed) return <div key={i} className="h-2"></div>;
        return (
          <p key={i} className="mb-2 last:mb-0 leading-relaxed text-sm">
            {parts.map((part, j) => {
              if (part.startsWith('**') && part.endsWith('**')) return <strong key={j} className="font-bold text-slate-800 dark:text-white">{part.slice(2, -2)}</strong>;
              return <span key={j}>{part}</span>;
            })}
          </p>
        );
      })}
    </div>
  );
};

export const AIAssistant: React.FC<AIAssistantProps> = ({ contextData, inlineView = false }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const [input, setInput] = useState('');
  const { t, language } = useLanguage();
  const { theme } = useTheme();
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [useThinking, setUseThinking] = useState(false);
  const [attachedImage, setAttachedImage] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (messages.length === 0) {
        setMessages([{ id: 'welcome', role: 'model', text: t('welcomeMessage') }]);
    }
  }, [t]);

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const scrollToBottom = () => messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 5 * 1024 * 1024) { alert("File too large. Please use an image under 5MB."); return; }
      const reader = new FileReader();
      reader.onloadend = () => setAttachedImage(reader.result as string);
      reader.readAsDataURL(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSendMessage = async () => {
    if ((!input.trim() && !attachedImage) || isLoading) return;
    const userMsg: Message = { id: Date.now().toString(), role: 'user', text: input, image: attachedImage || undefined };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setAttachedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const parts: any[] = [];
      let systemInstruction = "You are ResinAI. A professional technical assistant for synthetic resin data analysis.";
      if (userMsg.image) {
         const base64Data = userMsg.image.split(',')[1];
         const mimeType = userMsg.image.split(';')[0].split(':')[1] || 'image/jpeg';
         parts.push({ inlineData: { mimeType, data: base64Data } });
         systemInstruction = `You are a Senior QC Specialist. Analyze image for material type and defects.`;
         parts.push({ text: userMsg.text || "Perform a full QC analysis." });
      } else {
         parts.push({ text: userMsg.text });
         if (contextData.length > 0) {
            const contextStr = JSON.stringify(contextData.slice(0, 15).map(p => ({ grade: p.gradeName, manufacturer: p.manufacturer, properties: p.properties })));
            parts.push({ text: `\n[Database Context]: ${contextStr}` });
         }
      }
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [{ role: 'user', parts: parts }],
        config: { systemInstruction, thinkingConfig: useThinking ? { thinkingBudget: 4096 } : undefined }
      });
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'model', text: response.text || "AI completed analysis." }]);
    } catch (error) {
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'model', text: "Error connecting to AI." }]);
    } finally { setIsLoading(false); }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); } };

  // Inline view for full-page navigation
  if (inlineView) {
    return (
      <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-950/20">
        <div className="flex-1 overflow-y-auto p-8 space-y-6 custom-scrollbar" ref={chatContainerRef}>
