        </div>

        <div className="flex flex-wrap justify-center gap-2 px-2 max-h-32 overflow-y-auto custom-scrollbar w-full py-1">
            {filteredPayload.length > 0 ? (
                filteredPayload.map((entry: any, index: number) => {
                    const isHidden = hiddenGroups.has(entry.value);
                    const isHighlighted = highlightedGroup === entry.value;
                    const otherHighlighted = highlightedGroup !== null && highlightedGroup !== entry.value;

                    return (
                        <button 
                            key={`item-${index}`} 
                            onClick={(e) => toggleGroupVisibility(entry.value, e.altKey)}
                            onMouseEnter={() => !isHidden && setHighlightedGroup(entry.value)}
                            onMouseLeave={() => setHighlightedGroup(null)}
                            title={`${entry.value}\n• Click to Toggle\n• Alt+Click to Isolate`}
                            className={`
                                flex items-center gap-2.5 px-3 py-1.5 rounded-xl border transition-all duration-300 relative group/item
                                ${isHidden 
                                    ? 'bg-slate-50 dark:bg-slate-800/50 border-slate-100 dark:border-slate-800 opacity-30 grayscale' 
                                    : isHighlighted
                                      ? 'bg-white dark:bg-slate-800 border-emerald-500 shadow-lg -translate-y-0.5 scale-105 z-10'
                                      : otherHighlighted
                                        ? 'bg-white dark:bg-slate-900 border-slate-200 dark:border-slate-700 opacity-60'
                                        : 'bg-white dark:bg-slate-900 border-slate-200 dark:border-slate-700 shadow-sm hover:shadow-md hover:-translate-y-0.5'
                                }
                            `}
                            style={{ borderLeft: isHidden ? '4px solid #cbd5e1' : `4px solid ${entry.color}` }}
                        >
                            <div className="relative">
                                {isHidden ? (
                                    <EyeOff size={10} className="text-slate-400" />
                                ) : isHighlighted ? (
                                    <Target size={10} className="text-emerald-500 animate-pulse" />
                                ) : (
                                    <Eye size={10} style={{ color: entry.color }} />
                                )}
                            </div>
                            <span className={`text-[10px] font-black uppercase tracking-widest ${isHidden ? 'text-slate-400 line-through' : isHighlighted ? 'text-emerald-600 dark:text-emerald-400' : 'text-slate-600 dark:text-slate-300'}`}>
                                {entry.value}
                            </span>

                            {!isHidden && (
                                <div className="absolute -top-6 left-1/2 -translate-x-1/2 px-2 py-0.5 bg-slate-900 text-white text-[8px] rounded opacity-0 group-hover/item:opacity-100 transition-opacity pointer-events-none whitespace-nowrap z-[100]">
                                    Alt+Click to isolate
                                </div>
                            )}
                        </button>
                    );
                })
            ) : (
                <div className="py-4 text-center w-full">
                    <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest italic">No groups match "{legendSearch}"</p>
                </div>
            )}
        </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col md:flex-row h-full gap-4 overflow-hidden">
      {/* Settings Panel */}
      <div className={`flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl transition-all duration-300 shrink-0 overflow-hidden ${showConfig ? 'w-full md:w-80 opacity-100' : 'w-0 opacity-0 md:border-none'}`}>
        <div className="p-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-950/50">
          <div className="flex items-center gap-2 font-bold text-sm text-slate-700 dark:text-slate-200 uppercase tracking-wider">
            <Settings size={16} className="text-emerald-500" />
            {t('chartConfig')}
          </div>
          <button onClick={() => setShowConfig(false)} className="md:hidden text-slate-400 hover:text-slate-600">
            <X size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-5 custom-scrollbar space-y-6">
          <div className="space-y-3">
             <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
