                        {plotFilters.map((f) => {
                            const stats = propertyStats[f.key];
                            return (
                                <div key={f.id} className="p-3 bg-white dark:bg-slate-800/40 rounded-xl border border-slate-200 dark:border-slate-700 space-y-2 animate-in slide-in-from-top-1 shadow-sm ring-1 ring-slate-900/5 transition-all hover:ring-emerald-500/20 group/filter">
                                    <div className="flex items-center justify-between gap-2">
                                        <div className="flex items-center gap-1.5 flex-1 min-w-0">
                                            <Hash size={10} className="text-emerald-500 shrink-0" />
                                            <select 
                                                value={f.key} 
                                                onChange={(e) => updatePlotFilter(f.id, { key: e.target.value })}
                                                className="flex-1 bg-transparent border-none text-[11px] font-black text-slate-700 dark:text-slate-200 outline-none p-0 appearance-none cursor-pointer truncate"
                                            >
                                                {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                                            </select>
                                        </div>
                                        <button onClick={() => removePlotFilter(f.id)} className="text-slate-300 hover:text-rose-500 transition-colors opacity-0 group-hover/filter:opacity-100">
                                            <Trash2 size={12} />
                                        </button>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <select 
                                            value={f.operator} 
                                            onChange={(e) => updatePlotFilter(f.id, { operator: e.target.value as any })}
                                            className="bg-slate-50 dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-lg px-2 py-1 text-[10px] font-bold outline-none ring-offset-white dark:ring-offset-slate-900 focus:ring-1 focus:ring-emerald-500"
                                        >
                                            <option value=">=">&ge;</option>
                                            <option value="<=">&le;</option>
                                            <option value=">">&gt;</option>
                                            <option value="<">&lt;</option>
                                            <option value="between">RANGE</option>
                                        </select>

                                        <div className="flex-1 flex items-center gap-1.5">
                                            <input 
                                                type="number" 
                                                value={f.value}
                                                onChange={(e) => updatePlotFilter(f.id, { value: e.target.value === '' ? '' : Number(e.target.value) })}
                                                placeholder={f.operator === 'between' ? 'MIN' : 'VAL'}
                                                className="w-full bg-slate-50 dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-lg px-2.5 py-1 text-[10px] font-mono outline-none focus:ring-1 focus:ring-emerald-500"
                                            />
                                            {f.operator === 'between' && (
                                                <>
                                                    <ArrowRight size={10} className="text-slate-300" />
                                                    <input 
                                                        type="number" 
                                                        value={f.value2}
                                                        onChange={(e) => updatePlotFilter(f.id, { value2: e.target.value === '' ? '' : Number(e.target.value) })}
                                                        placeholder="MAX"
                                                        className="w-full bg-slate-50 dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-lg px-2.5 py-1 text-[10px] font-mono outline-none focus:ring-1 focus:ring-emerald-500"
                                                    />
                                                </>
                                            )}
                                        </div>
                                    </div>
                                    {stats && (
                                        <div className="flex justify-between items-center px-1 text-[9px] text-slate-400 font-bold uppercase tracking-tighter">
                                            <span>Min: {stats.min}</span>
                                            <span>Max: {stats.max}</span>
                                        </div>
                                    )}
                                </div>
                            );
                        })}
                        <button 
                            onClick={addPlotFilter}
                            className="w-full flex items-center justify-center gap-2 py-2 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-xl text-[10px] font-bold text-slate-400 hover:text-emerald-500 hover:border-emerald-500/50 transition-all group"
                        >
                            <Plus size={14} className="group-hover:rotate-90 transition-transform" />
                            ADD ANOTHER FILTER
                        </button>
                    </div>
                )}
            </div>
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
             <div className="flex items-center justify-between">
                <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                    <PaletteIcon size={12} /> {t('styleGrouping')}
                </label>
                {groupByKey && (
                    <div className="flex items-center gap-1">
                        <button 
                            onClick={shufflePalette}
                            title="Shuffle Colors"
                            className="p-1 text-slate-400 hover:text-emerald-500 transition-colors rounded hover:bg-slate-100 dark:hover:bg-slate-800"
                        >
                            <RefreshCw size={12} />
                        </button>
                        <button 
                            onClick={resetPalette}
                            title="Reset to Default Palette"
                            className="p-1 text-slate-400 hover:text-rose-500 transition-colors rounded hover:bg-slate-100 dark:hover:bg-slate-800"
                        >
                            <RotateCcw size={12} />
                        </button>
                    </div>
                )}
             </div>

             <div className="space-y-1.5">
               <span className="text-[11px] font-semibold text-slate-500 ml-1 uppercase tracking-tighter">{t('groupBy')}</span>
               <select value={groupByKey} onChange={(e) => setGroupByKey(e.target.value)} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm outline-none transition-colors">
                 <option value="">{t('none')}</option>
                 {categoricalKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
               </select>
             </div>

             {groupByKey && (
               <div className="space-y-5">
                 {/* Palette Presets */}
                 <div className="p-3 bg-slate-50/50 dark:bg-slate-950/50 border border-slate-100 dark:border-slate-800 rounded-xl">
                    <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2 block">Apply Palette Preset</span>
                    <div className="space-y-1.5">
                        {COLOR_SCHEMES.map(scheme => (
                            <button 
                                key={scheme.id}
                                onClick={() => applyScheme(scheme.id)}
                                className={`w-full flex items-center gap-2 p-1.5 rounded-lg border transition-all ${activeSchemeId === scheme.id ? 'bg-white dark:bg-slate-800 border-emerald-500 ring-2 ring-emerald-500/10' : 'bg-transparent border-transparent hover:border-slate-200 dark:hover:border-slate-700'}`}
                            >
                                <div className="flex-1 flex h-2 rounded-full overflow-hidden">
                                    {scheme.colors.slice(0, 6).map((c, i) => (
                                        <div key={i} className="flex-1 h-full" style={{ backgroundColor: c }} />
                                    ))}
                                </div>
                                <span className={`text-[9px] font-bold whitespace-nowrap px-1 ${activeSchemeId === scheme.id ? 'text-emerald-600' : 'text-slate-500'}`}>{scheme.name}</span>
                            </button>
                        ))}
                    </div>
                 </div>

                 {/* Gradient Generator Tool */}
                 <div className="p-3 bg-slate-50/50 dark:bg-slate-950/50 border border-slate-100 dark:border-slate-800 rounded-xl space-y-3">
                    <div className="flex items-center justify-between">
                        <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Gradient Generator</span>
                        <Wand2 size={12} className="text-emerald-500" />
                    </div>
                    <div className="flex items-center gap-3">
                        <div className="flex-1 space-y-1">
                            <div className="h-6 rounded-lg border border-white dark:border-slate-700 shadow-sm relative overflow-hidden" style={{ backgroundColor: gradientStart }}>
                                <input type="color" value={gradientStart} onChange={(e) => setGradientStart(e.target.value)} className="absolute inset-0 opacity-0 cursor-pointer w-full h-full" />
                            </div>
                        </div>
                        <ArrowRight size={14} className="text-slate-300" />
                        <div className="flex-1 space-y-1">
                            <div className="h-6 rounded-lg border border-white dark:border-slate-700 shadow-sm relative overflow-hidden" style={{ backgroundColor: gradientEnd }}>
                                <input type="color" value={gradientEnd} onChange={(e) => setGradientEnd(e.target.value)} className="absolute inset-0 opacity-0 cursor-pointer w-full h-full" />
                            </div>
                        </div>
                        <button 
                            onClick={applyGradientColors}
                            className="p-1.5 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 transition-all shadow-md shadow-emerald-500/20 active:scale-95"
                            title="Generate Gradient Colors"
                        >
                            <Repeat size={14} />
                        </button>
                    </div>
                    <div className="h-1.5 w-full rounded-full overflow-hidden flex" style={{ background: `linear-gradient(to right, ${gradientStart}, ${gradientEnd})` }}></div>
                 </div>

                 {/* Individual Group Mappings with Search */}
                 <div className="space-y-2 border-t border-slate-100 dark:border-slate-800 pt-4">
                    <div className="flex items-center justify-between gap-4 mb-2">
                        <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Group Assignments</span>
                        <div className="relative flex-1 max-w-[140px]">
                            <Search size={10} className="absolute left-2 top-2 text-slate-400" />
                            <input 
                                type="text"
                                placeholder="Search groups..."
                                value={groupSettingsSearch}
                                onChange={(e) => setGroupSettingsSearch(e.target.value)}
                                className="w-full pl-6 pr-2 py-1 bg-slate-100 dark:bg-slate-800 border-none rounded-lg text-[10px] focus:ring-1 focus:ring-emerald-500 outline-none"
                            />
                        </div>
                    </div>

                    <div className="max-h-64 overflow-y-auto custom-scrollbar pr-1 py-1 space-y-2">
                        {filteredUniqueGroupsSettings.length > 0 ? (
                            filteredUniqueGroupsSettings.map(group => (
                                <div key={group} className="flex flex-col gap-2 p-2.5 bg-slate-50 dark:bg-slate-800/40 border border-slate-100 dark:border-slate-800 rounded-xl animate-in fade-in slide-in-from-left-2 transition-all hover:border-emerald-500/30">
                                    <div className="flex items-center justify-between gap-3">
                                        <div className="flex items-center gap-2 flex-1 min-w-0">
                                            <div 
                                                className="w-6 h-6 rounded-lg shadow-sm border border-white dark:border-slate-700 overflow-hidden cursor-pointer ring-1 ring-slate-200 dark:ring-slate-800 shrink-0 relative"
                                                style={{ backgroundColor: groupColors[group] || '#10b981' }}
                                            >
                                                <input 
                                                    type="color" 
                                                    value={groupColors[group] || '#10b981'} 
                                                    onChange={(e) => updateGroupColor(group, e.target.value)} 
                                                    className="absolute inset-0 opacity-0 cursor-pointer w-full h-full" 
                                                />
                                            </div>
                                            <span className={`text-[10px] font-bold truncate ${hiddenGroups.has(group) ? 'text-slate-400 line-through' : 'text-slate-700 dark:text-slate-300'}`}>
                                                {group}
                                            </span>
                                        </div>
                                        <button 
                                            onClick={() => toggleGroupVisibility(group)}
                                            className={`p-1 rounded-md transition-colors ${hiddenGroups.has(group) ? 'text-slate-300 dark:text-slate-600' : 'text-emerald-500 dark:text-emerald-400 hover:bg-emerald-50 dark:hover:bg-emerald-900/20'}`}
                                        >
                                            {hiddenGroups.has(group) ? <EyeOff size={12} /> : <Eye size={12} />}
                                        </button>
                                    </div>

                                    {/* Mini Palette Switcher for this group */}
                                    <div className="flex flex-wrap gap-1 mt-0.5">
                                        {(COLOR_SCHEMES.find(s => s.id === activeSchemeId)?.colors || QUICK_COLORS).slice(0, 8).map(c => (
                                            <button 
                                                key={c}
                                                onClick={() => updateGroupColor(group, c)}
                                                className={`w-3 h-3 rounded-full border border-white dark:border-slate-800 transition-transform hover:scale-125 ${groupColors[group] === c ? 'ring-1 ring-emerald-500 scale-110' : ''}`}
                                                style={{ backgroundColor: c }}
                                            />
                                        ))}
                                    </div>
                                </div>
                            ))
                        ) : (
                            <div className="py-4 text-center">
                                <p className="text-[10px] text-slate-400 font-bold uppercase italic">No matches</p>
                            </div>
                        )}
                    </div>
                 </div>
               </div>
             )}
          </div>

          {chartType === 'scatter' && (
            <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800 animate-in slide-in-from-top-1">
               <div className="flex items-center justify-between">
                 <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                    <TrendingUp size={12} /> {t('trendline')}
                 </label>
                 <label className="flex items-center gap-2 cursor-pointer group">
                    <div className={`w-8 h-4 rounded-full relative transition-colors ${showTrendline ? 'bg-emerald-500' : 'bg-slate-200 dark:bg-slate-700'}`}>
                        <div className={`absolute top-0.5 w-3 h-3 bg-white rounded-full transition-transform ${showTrendline ? 'translate-x-4' : 'translate-x-0.5'}`}></div>
                        <input type="checkbox" checked={showTrendline} onChange={() => setShowTrendline(!showTrendline)} className="hidden" />
                    </div>
                 </label>
               </div>

               {showTrendline && (
                 <div className="space-y-4 p-3 bg-slate-50/50 dark:bg-slate-950/20 rounded-2xl border border-slate-100 dark:border-slate-800 animate-in zoom-in-95 duration-200">
                    {/* Color picker & Style */}
                    <div className="space-y-2">
                      <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 block">Line Style & Color</span>
                      <div className="flex items-center gap-3">
                         <div className="w-8 h-8 rounded-lg shadow-sm border border-white dark:border-slate-700 overflow-hidden relative ring-1 ring-slate-200 dark:ring-slate-800 shrink-0" style={{ backgroundColor: trendlineColor }}>
                            <input type="color" value={trendlineColor} onChange={(e) => setTrendlineColor(e.target.value)} className="absolute inset-0 opacity-0 cursor-pointer w-full h-full" title="Pick Trendline Color" />
                         </div>
                         <div className="flex-1 grid grid-cols-3 gap-1 bg-white dark:bg-slate-800 p-1 rounded-lg border border-slate-100 dark:border-slate-700">
                            {(['solid', 'dashed', 'dotted'] as const).map(style => (
                               <button 
                                 key={style}
                                 onClick={() => setTrendlineStyle(style)}
                                 className={`px-1.5 py-1 rounded text-[8px] font-black uppercase border transition-all ${trendlineStyle === style ? 'bg-emerald-500 border-emerald-500 text-white shadow-sm' : 'bg-transparent border-transparent text-slate-400 hover:text-slate-600'}`}
                               >
                                 {style}
                               </button>
                            ))}
                         </div>
                      </div>
                    </div>

                    {/* Width Slider */}
                    <div className="space-y-2">
                       <div className="flex justify-between items-center">
                          <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Stroke Width</span>
                          <span className="text-[10px] font-mono font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/30 px-1.5 rounded">{trendlineWidth}px</span>
                       </div>
                       <input 
                         type="range" min="1" max="8" step="1"
                         value={trendlineWidth}
                         onChange={(e) => setTrendlineWidth(Number(e.target.value))}
                         className="w-full h-1.5 bg-slate-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-emerald-500"
                       />
                    </div>
                 </div>
               )}
            </div>
          )}

          <div className="pt-4 border-t border-slate-100 dark:border-slate-800 grid grid-cols-2 gap-2">
            <button onClick={() => handleDownload('json')} className="flex items-center justify-center gap-2 p-2 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 rounded-lg text-[10px] font-bold text-slate-600 transition-colors uppercase">
              <FileJson size={14} /> JSON
            </button>
            <button 
              onClick={() => handleDownload('png')} 
              disabled={isExporting}
              className="flex items-center justify-center gap-2 p-2 bg-emerald-600 hover:bg-emerald-700 disabled:bg-emerald-400 text-white rounded-lg text-[10px] font-bold transition-colors uppercase shadow-md shadow-emerald-500/20"
            >
              {isExporting ? <Loader2 size={14} className="animate-spin" /> : <ImageIcon size={14} />} 
              PNG
            </button>
          </div>
        </div>
      </div>

      {/* Chart Canvas Area */}
      <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl relative min-h-[400px]">
        <div className="absolute top-4 right-4 z-10 flex gap-2">
             {!showConfig && (
                <button onClick={() => setShowConfig(true)} className="p-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-500 hover:text-emerald-500 shadow-lg transition-all">
                    <Settings size={20} />
                </button>
            )}
            <button 
              onClick={() => handleDownload('png')} 
              disabled={isExporting}
              title="Snapshot Export"
              className="p-2.5 bg-emerald-600 text-white rounded-xl shadow-lg shadow-emerald-500/20 hover:bg-emerald-700 active:scale-95 transition-all disabled:bg-slate-300 dark:disabled:bg-slate-700"
            >
              {isExporting ? <Loader2 size={20} className="animate-spin" /> : <Camera size={20} />}
            </button>
        </div>

        <div className="flex-1 p-6 flex flex-col min-h-0" ref={chartRef}>
            <div className="mb-4 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
               <h2 className="text-lg font-bold text-slate-800 dark:text-white flex items-center gap-2">
                  {chartType === 'bar' ? <BarChart2 size={20} className="text-emerald-500" /> : <ScatterIcon size={20} className="text-emerald-500" />}
                  {tProp(yAxisKey)} vs {chartType === 'bar' ? tProp('牌号') : tProp(xAxisKey)}
               </h2>

               <div className="flex items-center gap-2 pr-12 md:pr-0">
                    <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">{t('showing')}</span>
                    <div className="flex items-center gap-1.5 px-3 py-1 bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-full shadow-inner">
                        <span className="text-xs font-black text-emerald-600 dark:text-emerald-400">{visibleChartData.length}</span>
                        <span className="text-[9px] text-slate-400 font-bold">/</span>
                        <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400">{data.length}</span>
                    </div>
               </div>
            </div>

            <div className="flex-1 w-full min-h-0 relative">
                {visibleChartData.length === 0 && (
                    <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-50/20 dark:bg-slate-950/20 backdrop-blur-[2px] z-50 rounded-xl">
                        <div className="p-8 bg-white dark:bg-slate-900 rounded-3xl shadow-2xl border border-slate-200 dark:border-slate-800 flex flex-col items-center gap-6 animate-in zoom-in-95 max-w-sm text-center">
                            <div className="w-16 h-16 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center">
                                <ListFilter size={32} className="text-slate-400" />
                            </div>
                            <div>
                                <p className="text-lg font-black text-slate-800 dark:text-white mb-2">No Matching Data</p>
                                <p className="text-sm text-slate-500 leading-relaxed">Your current filters returned 0 results. Try loosening range constraints or showing hidden groups.</p>
                            </div>
                            <div className="flex gap-3 w-full">
                                <button 
                                    onClick={clearAllFilters}
                                    className="flex-1 px-4 py-2.5 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300 text-xs font-bold rounded-xl transition-all"
                                >
                                    Reset Filters
                                </button>
                                <button 
                                    onClick={() => setAllGroupsVisibility(true)}
                                    className="flex-1 px-4 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold rounded-xl shadow-lg shadow-emerald-500/20 transition-all active:scale-95"
                                >
                                    Show All
                                </button>
                            </div>
                        </div>
                    </div>
                )}

                <ResponsiveContainer width="100%" height="100%">
                    {chartType === 'bar' ? (
                        <BarChart data={visibleChartData} margin={{ top: 10, right: 30, left: 0, bottom: 40 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis dataKey="gradeName" angle={-45} textAnchor="end" interval={0} height={60} fontSize={10} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} />
                            <YAxis fontSize={10} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} domain={['auto', 'auto']} />
                            <Tooltip cursor={{ fill: 'rgba(16, 185, 129, 0.05)' }} content={<CustomTooltipContent />} />
                            {groupByKey && (
                              <Legend 
                                verticalAlign="top"
                                content={RenderCustomLegend}
                              />
                            )}
                            <Bar dataKey={yAxisKey} radius={[4, 4, 0, 0]} animationDuration={1000}>
                                {visibleChartData.map((entry, index) => {
                                    const group = String(entry[groupByKey] || 'Unknown');
                                    const isHighlighted = highlightedGroup === null || highlightedGroup === group;
                                    return (
                                        <Cell 
                                            key={`cell-${index}`} 
                                            fill={groupByKey ? groupColors[group] : DEFAULT_PALETTE[index % DEFAULT_PALETTE.length]} 
                                            fillOpacity={isHighlighted ? 1 : 0.15}
                                        />
                                    );
                                })}
                            </Bar>
                        </BarChart>
                    ) : (
                        <ComposedChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis type={xAxisKey === 'gradeName' ? 'category' : 'number'} dataKey={xAxisKey} name={tProp(xAxisKey)} fontSize={10} domain={[xMin === '' ? 'auto' : xMin, xMax === '' ? 'auto' : xMax]} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} label={{ value: tProp(xAxisKey), position: 'bottom', offset: 0, fontSize: 10, fill: '#64748b' }} />
                            <YAxis type="number" dataKey={yAxisKey} name={tProp(yAxisKey)} fontSize={10} domain={[yMin === '' ? 'auto' : yMin, yMax === '' ? 'auto' : yMax]} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} label={{ value: tProp(yAxisKey), angle: -90, position: 'insideLeft', offset: 10, fontSize: 10, fill: '#64748b' }} />
                            <ZAxis range={[60, 400]} />
                            <Tooltip cursor={{ strokeDasharray: '3 3' }} content={<CustomTooltipContent />} />
                            {groupByKey && (
                              <Legend 
                                verticalAlign="top"
                                content={RenderCustomLegend}
                              />
                            )}
                            <Scatter name="Resin Samples" data={visibleChartData} animationDuration={1500}>
                                {visibleChartData.map((entry, index) => {
                                    const group = String(entry[groupByKey] || 'Unknown');
                                    const isHighlighted = highlightedGroup === null || highlightedGroup === group;
                                    return (
                                        <Cell 
                                            key={`cell-${index}`} 
                                            fill={groupByKey ? groupColors[group] : '#10b981'} 
                                            fillOpacity={isHighlighted ? 1 : 0.1}
                                            strokeOpacity={isHighlighted ? 1 : 0.1}
                                            strokeWidth={1} 
                                            stroke="#ffffff" 
                                        />
                                    );
                                })}
                            </Scatter>
                            {trendlineSegment && (
                                <Line type="monotone" data={trendlineSegment} dataKey={yAxisKey} stroke={trendlineColor} strokeWidth={trendlineWidth} strokeDasharray={dashArray} dot={false} activeDot={false} legendType="none" />
                            )}
                        </ComposedChart>
                    )}
                </ResponsiveContainer>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  ReferenceLine,
  Cell,
  LabelList,
  Line,
  ComposedChart,
  ZAxis
} from 'recharts';
import { Settings, Download, ChevronUp, BarChart2, ScatterChart as ScatterIcon, TrendingUp, Palette, FileJson, Image as ImageIcon, RotateCcw, LayoutDashboard, Pipette, Maximize, X, Filter, Plus, Trash2, Eye, EyeOff, Info, RefreshCw, Palette as PaletteIcon, Layers, Factory, CheckCircle2, Wand2, Hash, ArrowRight, Binary, ListFilter, Eraser, PlusCircle, Target, MousePointer2, Search, Camera, Loader2, GripVertical, Repeat } from 'lucide-react';
import { Product, PropertyValue } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

interface PlotFilter {
  id: string;
  key: string;
  operator: '>' | '<' | '>=' | '<=' | 'between';
  value: number | '';
  value2: number | '';
}

const DEFAULT_PALETTE = [
  '#10b981', // Emerald
  '#3b82f6', // Blue
  '#f59e0b', // Amber
  '#ef4444', // Red
  '#8b5cf6', // Violet
  '#ec4899', // Pink
  '#06b6d4', // Cyan
  '#84cc16', // Lime
  '#f97316', // Orange
  '#6366f1', // Indigo
];

const COLOR_SCHEMES = [
  { id: 'emerald', name: 'Resin Classic', colors: ['#10b981', '#059669', '#047857', '#065f46', '#064e3b', '#34d399'] },
  { id: 'vibrant', name: 'Scientific Vibrant', colors: ['#6366f1', '#8b5cf6', '#ec4899', '#f43f5e', '#f97316', '#eab308'] },
  { id: 'ocean', name: 'Deep Ocean', colors: ['#0c4a6e', '#075985', '#0369a1', '#0284c7', '#0ea5e9', '#38bdf8'] },
  { id: 'pastel', name: 'Soft Material', colors: ['#a7f3d0', '#bfdbfe', '#fde68a', '#fecaca', '#ddd6fe', '#fbcfe8'] },
  { id: 'industrial', name: 'Industrial Gray', colors: ['#1e293b', '#334155', '#475569', '#64748b', '#94a3b8', '#cbd5e1'] }
];

const QUICK_COLORS = [
  '#10b981', '#3b82f6', '#f59e0b', '#ef4444', '#8b5cf6', 
  '#ec4899', '#06b6d4', '#f97316', '#6366f1', '#475569'
];

const interpolateColor = (color1: string, color2: string, factor: number) => {
  const hex = (x: number) => x.toString(16).padStart(2, '0');
  const r1 = parseInt(color1.slice(1, 3), 16);
  const g1 = parseInt(color1.slice(3, 5), 16);
  const b1 = parseInt(color1.slice(5, 7), 16);
  const r2 = parseInt(color2.slice(1, 3), 16);
  const g2 = parseInt(color2.slice(3, 5), 16);
  const b2 = parseInt(color2.slice(5, 7), 16);
  const r = Math.round(r1 + factor * (r2 - r1));
  const g = Math.round(g1 + factor * (g2 - g1));
  const b = Math.round(b1 + factor * (b2 - b1));
  return `#${hex(r)}${hex(g)}${hex(b)}`;
};

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const { t, tProp } = useLanguage();
  const { theme } = useTheme();
  const chartRef = useRef<HTMLDivElement>(null);

  const [showConfig, setShowConfig] = useState(true);
  const [isExporting, setIsExporting] = useState(false);
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('gradeName');
  const [yAxisKey, setYAxisKey] = useState<string>('');
  const [legendSearch, setLegendSearch] = useState('');
  const [groupSettingsSearch, setGroupSettingsSearch] = useState('');

  const [gradientStart, setGradientStart] = useState('#10b981');
  const [gradientEnd, setGradientEnd] = useState('#3b82f6');

  const [xMin, setXMin] = useState<number | ''>('');
  const [xMax, setXMax] = useState<number | ''>('');
  const [yMin, setYMin] = useState<number | ''>('');
  const [yMax, setYMax] = useState<number | ''>('');

  const [plotFilters, setPlotFilters] = useState<PlotFilter[]>([]);

  const [showTrendline, setShowTrendline] = useState(false);
  const [trendlineColor, setTrendlineColor] = useState('#ef4444');
  const [trendlineWidth, setTrendlineWidth] = useState(2);
  const [trendlineStyle, setTrendlineStyle] = useState<'solid' | 'dashed' | 'dotted'>('dashed');

  const [groupByKey, setGroupByKey] = useState<string>('');
  const [groupColors, setGroupColors] = useState<Record<string, string>>({});
  const [hiddenGroups, setHiddenGroups] = useState<Set<string>>(new Set());
  const [highlightedGroup, setHighlightedGroup] = useState<string | null>(null);
  const [activeSchemeId, setActiveSchemeId] = useState('emerald');

  const numericKeys = useMemo(() => {
     const keys = new Set<string>();
     data.forEach(p => {
        (Object.entries(p.properties) as [string, PropertyValue][]).forEach(([k, v]) => {
           if (typeof v.value === 'number' || (!isNaN(Number(v.value)) && v.value !== '')) {
               keys.add(k);
           }
        });
     });
     return Array.from(keys).sort();
  }, [data]);

  const propertyStats = useMemo(() => {
    const stats: Record<string, { min: number; max: number }> = {};
    numericKeys.forEach(key => {
        let min = Infinity;
        let max = -Infinity;
        data.forEach(p => {
            const val = Number(p.properties[key]?.value);
            if (!isNaN(val)) {
                if (val < min) min = val;
                if (val > max) max = val;
            }
        });
        if (min !== Infinity) {
            stats[key] = { min, max };
        }
    });
    return stats;
  }, [data, numericKeys]);

  const categoricalKeys = useMemo(() => {
    const keys = new Set<string>(['manufacturer']);
    data.forEach(p => {
        (Object.entries(p.properties) as [string, PropertyValue][]).forEach(([k, v]) => {
            if (typeof v.value === 'string' && isNaN(Number(v.value))) {
                keys.add(k);
            }
        });
    });
    return Array.from(keys).sort();
  }, [data]);

  useEffect(() => {
      if (!yAxisKey && numericKeys.length > 0) {
          const preferred = ['密度', '熔体流动速率', '拉伸强度'].find(k => numericKeys.includes(k));
          setYAxisKey(preferred || numericKeys[0]);
      }
  }, [numericKeys, yAxisKey]);

  useEffect(() => {
    setXMin(''); setXMax(''); setYMin(''); setYMax('');
    setHiddenGroups(new Set());
    setHighlightedGroup(null);
    setLegendSearch('');
  }, [xAxisKey, yAxisKey, chartType, groupByKey]);

  const filteredBaseData = useMemo(() => {
    return data.filter(product => {
        return plotFilters.every(f => {
            if (!f.key || f.value === '') return true;
            const prop = product.properties[f.key] as PropertyValue;
            if (!prop || prop.value === undefined || prop.value === null || prop.value === '') return false;
            const val = Number(prop.value);
            if (isNaN(val)) return false;

            const v1 = Number(f.value);
            const v2 = f.value2 !== '' ? Number(f.value2) : Infinity;

            switch (f.operator) {
                case '>': return val > v1;
                case '<': return val < v1;
                case '>=': return val >= v1;
                case '<=': return val <= v1;
                case 'between': return val >= v1 && val <= v2;
                default: return true;
            }
        });
    });
  }, [data, plotFilters]);

  const chartData = useMemo(() => {
    return filteredBaseData.map(p => {
        const item: any = {
            id: p.id,
            gradeName: p.gradeName,
            manufacturer: p.manufacturer,
            tooltipTitle: `${p.manufacturer} - ${p.gradeName}`
        };
        (Object.entries(p.properties) as [string, PropertyValue][]).forEach(([k, v]) => {
            const num = Number(v.value);
            item[k] = !isNaN(num) && v.value !== '' ? num : v.value;
        });
        return item;
    });
  }, [filteredBaseData]);

  const uniqueGroups = useMemo(() => {
    if (!groupByKey) return [];
    const groups = new Set<string>();
    chartData.forEach((item: any) => {
        groups.add(String(item[groupByKey] || 'Unknown'));
    });
    return Array.from(groups).sort();
  }, [groupByKey, chartData]);

  const filteredUniqueGroupsSettings = useMemo(() => {
    if (!groupSettingsSearch) return uniqueGroups;
    return uniqueGroups.filter(g => g.toLowerCase().includes(groupSettingsSearch.toLowerCase()));
  }, [uniqueGroups, groupSettingsSearch]);

  const visibleChartData = useMemo(() => {
    if (!groupByKey) return chartData;
    return chartData.filter(d => !hiddenGroups.has(String(d[groupByKey] || 'Unknown')));
  }, [chartData, groupByKey, hiddenGroups]);

  const trendlineSegment = useMemo(() => {
    if (!showTrendline || chartType !== 'scatter') return null;

    const validPoints = visibleChartData.filter(d => 
        typeof d[xAxisKey] === 'number' && typeof d[yAxisKey] === 'number'
    );

    if (validPoints.length < 2) return null;

    const n = validPoints.length;
    let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
    let minX = Infinity, maxX = -Infinity;

    validPoints.forEach(p => {
        const x = p[xAxisKey];
        const y = p[yAxisKey];
        sumX += x; sumY += y; sumXY += x * y; sumX2 += x * x;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
    });

    const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
    const intercept = (sumY - slope * sumX) / n;

    return [
        { [xAxisKey]: minX, [yAxisKey]: slope * minX + intercept, isTrend: true },
        { [xAxisKey]: maxX, [yAxisKey]: slope * maxX + intercept, isTrend: true }
    ];
  }, [visibleChartData, xAxisKey, yAxisKey, showTrendline, chartType]);

  const dashArray = useMemo(() => {
    if (trendlineStyle === 'dashed') return '5 5';
    if (trendlineStyle === 'dotted') return '2 2';
    return '0';
  }, [trendlineStyle]);

  useEffect(() => {
    if (uniqueGroups.length > 0) {
        setGroupColors(prev => {
            const next = { ...prev };
            const currentPalette = COLOR_SCHEMES.find(s => s.id === activeSchemeId)?.colors || DEFAULT_PALETTE;
            uniqueGroups.forEach((group, index) => {
                if (!next[group]) next[group] = currentPalette[index % currentPalette.length];
            });
            return next;
        });
    }
  }, [uniqueGroups, activeSchemeId]);

  const updateGroupColor = (group: string, color: string) => {
    setGroupColors(prev => ({ ...prev, [group]: color }));
  };

  const applyScheme = (schemeId: string) => {
    setActiveSchemeId(schemeId);
    const scheme = COLOR_SCHEMES.find(s => s.id === schemeId);
    if (!scheme) return;

    setGroupColors(prev => {
        const next = { ...prev };
        uniqueGroups.forEach((group, index) => {
            next[group] = scheme.colors[index % scheme.colors.length];
        });
        return next;
    });
  };

  const applyGradientColors = () => {
    if (uniqueGroups.length === 0) return;
    setGroupColors(prev => {
        const next = { ...prev };
        const steps = uniqueGroups.length > 1 ? uniqueGroups.length - 1 : 1;
        uniqueGroups.forEach((group, index) => {
            const factor = index / steps;
            next[group] = interpolateColor(gradientStart, gradientEnd, factor);
        });
        return next;
    });
  };

  const shufflePalette = () => {
    const scheme = COLOR_SCHEMES.find(s => s.id === activeSchemeId)?.colors || DEFAULT_PALETTE;
    const shuffled = [...scheme].sort(() => Math.random() - 0.5);
    setGroupColors(prev => {
        const next = { ...prev };
        uniqueGroups.forEach((group, index) => {
            next[group] = shuffled[index % shuffled.length];
        });
        return next;
    });
  };

  const resetPalette = () => {
    applyScheme('emerald');
  };

  const toggleGroupVisibility = (group: string, isAltKey: boolean = false) => {
    if (isAltKey) {
        const others = uniqueGroups.filter(g => g !== group);
        setHiddenGroups(new Set(others));
    } else {
        setHiddenGroups(prev => {
          const next = new Set(prev);
          if (next.has(group)) next.delete(group);
          else next.add(group);
          return next;
        });
    }
  };

  const setAllGroupsVisibility = (visible: boolean) => {
    if (visible) setHiddenGroups(new Set());
    else setHiddenGroups(new Set(uniqueGroups));
  };

  const handleDownload = async (type: 'json' | 'png') => {
    if (type === 'json') {
        const blob = new Blob([JSON.stringify(visibleChartData, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = `resindb_data_${Date.now()}.json`; a.click();
    } else if (type === 'png' && chartRef.current) {
        setIsExporting(true);
        try {
          const canvas = await html2canvas(chartRef.current, { 
            backgroundColor: theme === 'dark' ? '#020617' : '#ffffff',
            scale: 2, 
            logging: false,
            useCORS: true
          });
          const a = document.createElement('a');
          a.href = canvas.toDataURL('image/png'); 
          a.download = `resindb_chart_${Date.now()}.png`; 
          a.click();
        } catch (err) {
          console.error("Export failed:", err);
        } finally {
          setIsExporting(false);
        }
    }
  };

  const addPlotFilter = () => {
    const newFilter: PlotFilter = {
        id: Date.now().toString(),
        key: numericKeys[0] || '',
        operator: '>=',
        value: '',
        value2: ''
    };
    setPlotFilters([...plotFilters, newFilter]);
  };

  const updatePlotFilter = (id: string, updates: Partial<PlotFilter>) => {
    setPlotFilters(prev => prev.map(f => f.id === id ? { ...f, ...updates } : f));
  };

  const removePlotFilter = (id: string) => {
    setPlotFilters(prev => prev.filter(f => f.id !== id));
  };

  const clearAllFilters = () => {
      setPlotFilters([]);
  };

  const CustomTooltipContent = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const d = payload[0].payload;
      if (d.isTrend) return null;
      const product = data.find(p => p.id === d.id);
      if (!product) return null;

      const additionalProps = (Object.entries(product.properties) as [string, PropertyValue][])
        .filter(([k]) => k !== xAxisKey && k !== yAxisKey && k !== groupByKey)
        .sort((a, b) => {
           const commonAttributes = ['密度', 'Density', '熔体流动速率', 'MFR', '拉伸强度', 'Tensile Strength', '应用', 'Application', '类型', 'Type'];
           const aIsCommon = commonAttributes.includes(a[0]) ? 1 : 0;
           const bIsCommon = commonAttributes.includes(b[0]) ? 1 : 0;
           return aIsCommon - bIsCommon;
        })
        .slice(0, 3);

      const formatPropValue = (key: string) => {
          const prop = product.properties[key] as PropertyValue;
          if (!prop) return <span className="text-sm font-black text-slate-800 dark:text-slate-100">{d[key]}</span>;
          return (
            <div className="flex items-baseline gap-1">
              <span className="text-sm font-mono font-black">{prop.value}</span>
              {prop.unit && (
                <span className="text-[10px] opacity-60 font-sans font-medium">
                  {prop.unit}
                </span>
              )}
            </div>
          );
      };

      return (
        <div className="p-4 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-2xl min-w-[260px] animate-in fade-in zoom-in-95 duration-200 border-l-4" style={{ borderLeftColor: groupByKey ? groupColors[String(d[groupByKey])] : '#10b981' }}>
          <div className="flex items-center justify-between gap-4 mb-1">
            <p className="font-bold text-slate-800 dark:text-white truncate text-sm">{product.gradeName}</p>
            {groupByKey && d[groupByKey] && (
               <span className="text-[9px] px-2 py-0.5 rounded-full text-white font-bold whitespace-nowrap" style={{ backgroundColor: groupColors[String(d[groupByKey])] }}>
                  {d[groupByKey]}
               </span>
            )}
          </div>
          <p className="text-[10px] text-slate-500 dark:text-slate-400 mb-3 uppercase tracking-widest font-bold flex items-center gap-1.5">
            <Factory size={10} className="text-emerald-500" /> {product.manufacturer}
          </p>

          <div className="space-y-2 pt-2 border-t border-slate-100 dark:border-slate-800">
             <div className="flex justify-between gap-4 items-center">
                <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">{tProp(yAxisKey)}</span>
                <div className="text-emerald-600 dark:text-emerald-400">
                    {formatPropValue(yAxisKey)}
                </div>
             </div>
             {chartType === 'scatter' && xAxisKey !== 'gradeName' && (
               <div className="flex justify-between gap-4 items-center">
                  <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">{tProp(xAxisKey)}</span>
                  <div className="text-blue-600 dark:text-blue-400">
                      {formatPropValue(xAxisKey)}
                  </div>
               </div>
             )}
          </div>

          {additionalProps.length > 0 && (
            <div className="mt-3 pt-3 border-t border-slate-100 dark:border-slate-800 space-y-2">
              <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1 flex items-center gap-1.5">
                <Info size={10} className="text-emerald-500" /> Technical Context
              </p>
              {additionalProps.map(([key, prop]) => (
                <div key={key} className="text-[11px] flex justify-between gap-4 text-slate-600 dark:text-slate-300 items-baseline">
                  <span className="opacity-70 truncate max-w-[140px]">{tProp(key)}</span>
                  <div className="font-bold whitespace-nowrap text-slate-800 dark:text-slate-100 font-mono">
                    <div className="flex items-baseline gap-1 justify-end">
                      <span>{prop.value}</span>
                      {prop.unit && (
                        <span className="text-[9px] font-sans opacity-40 font-normal">
                          {prop.unit}
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      );
    }
    return null;
  };

  const RenderCustomLegend = (props: any) => {
    const { payload } = props;
    if (!payload || payload.length === 0) return null;

    const filteredPayload = payload.filter((entry: any) => 
        entry.value.toLowerCase().includes(legendSearch.toLowerCase())
    );

    const allVisible = hiddenGroups.size === 0;
    const noneVisible = hiddenGroups.size === uniqueGroups.length;
    const visibleCount = uniqueGroups.length - hiddenGroups.size;

    return (
      <div className="flex flex-col items-center mb-8 gap-4 animate-in fade-in duration-500 bg-white/40 dark:bg-slate-900/40 backdrop-blur-sm border border-slate-100 dark:border-slate-800 rounded-3xl p-4 shadow-xl shadow-slate-200/20 dark:shadow-black/20">
        <div className="flex flex-wrap items-center justify-between w-full gap-4 px-2">
            {/* Legend Stats & Controls */}
            <div className="flex items-center gap-3 bg-white/80 dark:bg-slate-800/80 px-4 py-1.5 rounded-full border border-slate-200 dark:border-slate-700 shadow-sm transition-all">
                <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1.5">
                    <MousePointer2 size={10} className="text-emerald-500" />
                    Viewing <span className="text-emerald-600 dark:text-emerald-400">{visibleCount}</span> of <span className="text-slate-600 dark:text-slate-300">{uniqueGroups.length}</span> Groups
                </span>
                <div className="w-px h-3 bg-slate-200 dark:bg-slate-700"></div>
                <div className="flex items-center gap-1">
                    <button 
                        onClick={() => setAllGroupsVisibility(true)}
                        disabled={allVisible}
                        className={`px-1.5 py-0.5 rounded text-[8px] font-black uppercase tracking-tighter transition-colors ${allVisible ? 'text-slate-300 cursor-not-allowed' : 'text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-900/20'}`}
                    >
                        {t('finish')}
                    </button>
                    <button 
                        onClick={() => setAllGroupsVisibility(false)}
                        disabled={noneVisible}
                        className={`px-1.5 py-0.5 rounded text-[8px] font-black uppercase tracking-tighter transition-colors ${noneVisible ? 'text-slate-300 cursor-not-allowed' : 'text-rose-600 hover:bg-rose-50 dark:hover:bg-rose-900/20'}`}
                    >
                        {t('deselectAll')}
                    </button>
                </div>
            </div>

            {/* Legend Search */}
            <div className="relative group/search max-w-[200px] flex-1 min-w-[150px]">
                <Search size={12} className="absolute left-2.5 top-2 text-slate-400 group-focus-within/search:text-emerald-500 transition-colors" />
                <input 
                    type="text"
                    placeholder={t('filterGroups')}
                    value={legendSearch}
                    onChange={(e) => setLegendSearch(e.target.value)}
                    className="w-full pl-8 pr-4 py-1.5 bg-white/80 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700 rounded-full text-[10px] font-bold outline-none focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 transition-all placeholder:text-slate-400"
                />
            </div>
        </div>

        {/* Legend Items Grid */}
        <div className="flex flex-wrap justify-center gap-2 px-2 max-h-32 overflow-y-auto custom-scrollbar w-full py-1">
            {filteredPayload.length > 0 ? (
                filteredPayload.map((entry: any, index: number) => {
                    const isHidden = hiddenGroups.has(entry.value);
                    const isHighlighted = highlightedGroup === entry.value;
                    const otherHighlighted = highlightedGroup !== null && highlightedGroup !== entry.value;

                    return (
                        <button 
                            key={`item-${index}`} 
                            onClick={(e) => toggleGroupVisibility(entry.value, e.altKey)}
                            onMouseEnter={() => !isHidden && setHighlightedGroup(entry.value)}
                            onMouseLeave={() => setHighlightedGroup(null)}
                            title={`${entry.value}\n• Click: Toggle\n• Alt+Click: Isolate Group`}
                            className={`
                                flex items-center gap-2.5 px-3 py-1.5 rounded-xl border transition-all duration-300 relative group/item
                                ${isHidden 
                                    ? 'bg-slate-50 dark:bg-slate-800/50 border-slate-100 dark:border-slate-800 opacity-30 grayscale' 
                                    : isHighlighted
                                      ? 'bg-white dark:bg-slate-800 border-emerald-500 shadow-lg -translate-y-0.5 scale-105 z-10'
                                      : otherHighlighted
                                        ? 'bg-white dark:bg-slate-900 border-slate-200 dark:border-slate-700 opacity-60'
                                        : 'bg-white dark:bg-slate-900 border-slate-200 dark:border-slate-700 shadow-sm hover:shadow-md hover:-translate-y-0.5'
                                }
                            `}
                            style={{ borderLeft: isHidden ? '4px solid #cbd5e1' : `4px solid ${entry.color}` }}
                        >
                            <div className="relative">
                                {isHidden ? (
                                    <EyeOff size={10} className="text-slate-400" />
                                ) : isHighlighted ? (
                                    <Target size={10} className="text-emerald-500 animate-pulse" />
                                ) : (
                                    <Eye size={10} style={{ color: entry.color }} />
                                )}
                            </div>
                            <span className={`text-[10px] font-black uppercase tracking-widest ${isHidden ? 'text-slate-400 line-through' : isHighlighted ? 'text-emerald-600 dark:text-emerald-400' : 'text-slate-600 dark:text-slate-300'}`}>
                                {entry.value}
                            </span>
                        </button>
                    );
                })
            ) : (
                <div className="py-4 text-center w-full">
                    <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest italic">No groups match "{legendSearch}"</p>
                </div>
            )}
        </div>
      </div>
    );
  };

  return (
