                    <select value={xAxisKey} onChange={(e) => setXAxisKey(e.target.value)} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm outline-none transition-colors">
                        <option value="gradeName">{tProp('牌号')}</option>
