                            className="p-1 text-slate-400 hover:text-emerald-500 transition-colors rounded hover:bg-slate-100 dark:hover:bg-slate-800"
                        >
                            <RefreshCw size={12} />
                        </button>
                        <button 
                            onClick={resetPalette}
                            title="Reset to Default Palette"
                            className="p-1 text-slate-400 hover:text-rose-500 transition-colors rounded hover:bg-slate-100 dark:hover:bg-slate-800"
