                                {visibleChartData.map((entry, index) => {
                                    const group = String(entry[groupByKey] || 'Unknown');
                                    const isHighlighted = highlightedGroup === null || highlightedGroup === group;
                                    return (
                                        <Cell 
                                            key={`cell-${index}`} 
                                            fill={groupByKey ? groupColors[group] : DEFAULT_PALETTE[index % DEFAULT_PALETTE.length]} 
                                            fillOpacity={isHighlighted ? 1 : 0.15}
                                        />
                                    );
                                })}
                            </Bar>
                        </BarChart>
                    ) : (
                        <ComposedChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis type={xAxisKey === 'gradeName' ? 'category' : 'number'} dataKey={xAxisKey} name={tProp(xAxisKey)} fontSize={10} domain={[xMin === '' ? 'auto' : xMin, xMax === '' ? 'auto' : xMax]} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} label={{ value: tProp(xAxisKey), position: 'bottom', offset: 0, fontSize: 10, fill: '#64748b' }} />
                            <YAxis type="number" dataKey={yAxisKey} name={tProp(yAxisKey)} fontSize={10} domain={[yMin === '' ? 'auto' : yMin, yMax === '' ? 'auto' : yMax]} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} label={{ value: tProp(yAxisKey), angle: -90, position: 'insideLeft', offset: 10, fontSize: 10, fill: '#64748b' }} />
                            <ZAxis range={[60, 400]} />
                            <Tooltip cursor={{ strokeDasharray: '3 3' }} content={<CustomTooltipContent />} />
                            {groupByKey && (
                              <Legend 
                                verticalAlign="top"
                                content={RenderCustomLegend}
                              />
                            )}
                            <Scatter name="Resin Samples" data={visibleChartData} animationDuration={1500}>
                                {visibleChartData.map((entry, index) => {
                                    const group = String(entry[groupByKey] || 'Unknown');
                                    const isHighlighted = highlightedGroup === null || highlightedGroup === group;
                                    return (
                                        <Cell 
                                            key={`cell-${index}`} 
                                            fill={groupByKey ? groupColors[group] : '#10b981'} 
                                            fillOpacity={isHighlighted ? 1 : 0.1}
                                            strokeOpacity={isHighlighted ? 1 : 0.1}
                                            strokeWidth={1} 
                                            stroke="#ffffff" 
                                        />
                                    );
                                })}
                            </Scatter>
                            {trendlineSegment && (
                                <Line type="monotone" data={trendlineSegment} dataKey={yAxisKey} stroke={trendlineColor} strokeWidth={trendlineWidth} strokeDasharray={dashArray} dot={false} activeDot={false} legendType="none" />
                            )}
                        </ComposedChart>
                    )}
                </ResponsiveContainer>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { BarChart3, TrendingUp, Settings2, ScatterChart, Activity } from 'lucide-react';

interface DataVisualizerProps {
  data: Product[];
}

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const { t, tProp } = useLanguage();
  const [chartType, setChartType] = useState<'scatter' | 'bar'>('scatter');
  const [xAxis, setXAxis] = useState<string>('密度');
  const [yAxis, setYAxis] = useState<string>('熔体流动速率');
  const [showTrendline, setShowTrendline] = useState(false);

  // Extract available numeric properties
  const numericProperties = useMemo(() => {
    const props = new Set<string>();
    data.forEach(p => {
      Object.entries(p.properties).forEach(([key, val]) => {
        if (typeof val.value === 'number') {
          props.add(key);
        }
      });
    });
    return Array.from(props);
  }, [data]);

  // Prepare data points
  const points = useMemo(() => {
    return data.map(p => {
      const xVal = p.properties[xAxis]?.value;
      const yVal = p.properties[yAxis]?.value;
      const groupVal = p.manufacturer; 

      return {
        id: p.id,
        x: typeof xVal === 'number' ? xVal : 0,
        y: typeof yVal === 'number' ? yVal : 0,
        name: p.gradeName,
        group: groupVal
      };
    }).filter(p => p.x !== 0 && p.y !== 0);
  }, [data, xAxis, yAxis]);

  // Scales calculation (simple normalization)
  const scales = useMemo(() => {
    if (points.length === 0) return { minX: 0, maxX: 100, minY: 0, maxY: 100 };
    const xs = points.map(p => p.x);
    const ys = points.map(p => p.y);
    return {
      minX: Math.min(...xs) * 0.9,
      maxX: Math.max(...xs) * 1.1,
      minY: Math.min(...ys) * 0.9,
      maxY: Math.max(...ys) * 1.1
    };
  }, [points]);

  const getX = (val: number) => ((val - scales.minX) / (scales.maxX - scales.minX)) * 100;
  const getY = (val: number) => 100 - ((val - scales.minY) / (scales.maxY - scales.minY)) * 100;

  return (
    <div className="flex h-full gap-4 p-4 bg-slate-50 dark:bg-slate-950/20">
       {/* Sidebar Config */}
       <div className="w-64 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-4 shadow-sm h-full flex flex-col">
          <div className="flex items-center gap-2 mb-6 text-slate-800 dark:text-white font-bold">
             <Settings2 size={18} className="text-emerald-500" />
             {t('chartSettings')}
          </div>

          <div className="space-y-5">
             <div className="space-y-2">
                <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest">{t('chartType')}</label>
                <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-lg">
                   <button 
                     onClick={() => setChartType('scatter')}
                     className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-md text-xs font-bold transition-all ${chartType === 'scatter' ? 'bg-white dark:bg-slate-700 shadow-sm text-emerald-600 dark:text-emerald-400' : 'text-slate-500'}`}
                   >
                     <ScatterChart size={14} /> {t('scatter')}
                   </button>
                   <button 
                     onClick={() => setChartType('bar')}
                     className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-md text-xs font-bold transition-all ${chartType === 'bar' ? 'bg-white dark:bg-slate-700 shadow-sm text-emerald-600 dark:text-emerald-400' : 'text-slate-500'}`}
                   >
                     <BarChart3 size={14} /> {t('bar')}
                   </button>
                </div>
             </div>

             <div className="space-y-2">
                <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest">{t('xAxis')}</label>
                <select 
                  value={xAxis} 
                  onChange={(e) => setXAxis(e.target.value)}
                  className="w-full p-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm outline-none focus:border-emerald-500"
                >
                  {numericProperties.map(p => <option key={p} value={p}>{tProp(p)}</option>)}
                </select>
             </div>

             <div className="space-y-2">
                <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest">{t('yAxis')}</label>
                <select 
                  value={yAxis} 
                  onChange={(e) => setYAxis(e.target.value)}
                  className="w-full p-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm outline-none focus:border-emerald-500"
                >
                  {numericProperties.map(p => <option key={p} value={p}>{tProp(p)}</option>)}
                </select>
             </div>

             {chartType === 'scatter' && (
                <div className="space-y-2 pt-4 border-t border-slate-100 dark:border-slate-800">
                    <div className="flex items-center justify-between">
                         <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                            <TrendingUp size={12} /> {t('showTrendline')}
                         </label>
                         <div 
                            onClick={() => setShowTrendline(!showTrendline)}
                            className={`w-8 h-4 rounded-full relative cursor-pointer transition-colors ${showTrendline ? 'bg-emerald-500' : 'bg-slate-200 dark:bg-slate-700'}`}
                        >
                            <div className={`absolute top-0.5 w-3 h-3 bg-white rounded-full transition-transform ${showTrendline ? 'translate-x-4' : 'translate-x-0.5'}`}></div>
                        </div>
                    </div>
                </div>
             )}
          </div>
       </div>

       {/* Chart Area */}
       <div className="flex-1 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm relative overflow-hidden flex flex-col">
          <div className="mb-4">
             <h3 className="text-lg font-bold text-slate-800 dark:text-white flex items-center gap-2">
                <Activity size={20} className="text-emerald-500" />
                {t('analysis')}
             </h3>
             <p className="text-xs text-slate-500">{tProp(xAxis)} vs {tProp(yAxis)}</p>
          </div>

          <div className="flex-1 relative border-l border-b border-slate-200 dark:border-slate-700 m-4">
             {/* Chart Content Placeholder - using SVG for simple rendering */}
             {points.length > 0 ? (
                <svg className="w-full h-full overflow-visible">
                    {/* Grid Lines */}
                    {[0, 25, 50, 75, 100].map(p => (
                        <g key={p}>
                            <line x1={`${p}%`} y1="0" x2={`${p}%`} y2="100%" className="stroke-slate-100 dark:stroke-slate-800" strokeDasharray="4" />
                            <line x1="0" y1={`${p}%`} x2="100%" y2={`${p}%`} className="stroke-slate-100 dark:stroke-slate-800" strokeDasharray="4" />
                        </g>
                    ))}

                    {/* Points */}
                    {chartType === 'scatter' && points.map((p, i) => (
                        <circle 
                            key={i}
                            cx={`${getX(p.x)}%`}
                            cy={`${getY(p.y)}%`}
                            r="6"
                            className="fill-emerald-500/60 stroke-emerald-600 hover:fill-emerald-500 hover:scale-125 transition-all cursor-pointer"
                        >
                            <title>{p.name}: ({p.x}, {p.y})</title>
                        </circle>
                    ))}

                    {/* Bars (Simplified) */}
                    {chartType === 'bar' && points.slice(0, 20).map((p, i) => {
                        const height = 100 - getY(p.y);
                        return (
                             <rect
                                key={i}
                                x={`${(i / Math.min(points.length, 20)) * 100 + 1}%`}
                                y={`${getY(p.y)}%`}
                                width={`${(100 / Math.min(points.length, 20)) - 2}%`}
                                height={`${height}%`}
                                className="fill-emerald-500/60 hover:fill-emerald-500 transition-all cursor-pointer"
                             >
                                <title>{p.name}: {p.y}</title>
                             </rect>
                        );
                    })}

                    {/* Trendline (Simplified Linear Regression) */}
                    {showTrendline && chartType === 'scatter' && points.length > 1 && (
                        <line 
                            x1="0%" 
                            y1={`${getY(scales.minY + (scales.maxY - scales.minY) * 0.2)}%`} // Dummy points for visual
                            x2="100%" 
                            y2={`${getY(scales.minY + (scales.maxY - scales.minY) * 0.8)}%`}
                            className="stroke-amber-500 stroke-2"
                            strokeDasharray="5,5"
                        />
                    )}
                </svg>
             ) : (
                <div className="absolute inset-0 flex items-center justify-center text-slate-400">
                    No data available for selected dimensions
                </div>
             )}
          </div>

          <div className="flex justify-between text-xs text-slate-400 mt-2">
             <span>{scales.minX.toFixed(1)}</span>
             <span className="font-bold text-slate-600 dark:text-slate-300">{tProp(xAxis)}</span>
             <span>{scales.maxX.toFixed(1)}</span>
          </div>
       </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";
import React, { useState, useRef, useEffect } from 'react';
import { Send, Image as ImageIcon, Sparkles, X, Loader2, BrainCircuit, Bot, User, ShieldCheck, ScanEye, Trash2, Maximize2, Minimize2 } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';

interface AIAssistantProps {
  contextData: Product[];
  inlineView?: boolean;
}

interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  image?: string;
  isThinking?: boolean;
}

const FormattedText: React.FC<{ text: string; className?: string }> = ({ text, className }) => {
  if (!text) return null;

  return (
    <div className={className}>
      {text.split('\n').map((line, i) => {
        const trimmed = line.trim();
        if (trimmed.startsWith('- ') || trimmed.startsWith('* ') || trimmed.match(/^\d+\./)) {
             const cleanLine = trimmed.replace(/^[-*]\s+|\d+\.\s+/, '');
             const parts = cleanLine.split(/(\*\*.*?\*\*)/g);
             return (
                <div key={i} className="flex gap-2.5 ml-1 mb-1.5 items-start">
                    <span className="text-emerald-500 dark:text-emerald-400 mt-1.5 shrink-0 text-[10px]">•</span>
                    <span className="leading-relaxed text-sm">
                        {parts.map((part, j) => {
                            if (part.startsWith('**') && part.endsWith('**')) {
                                return <strong key={j} className="font-bold text-slate-800 dark:text-white">{part.slice(2, -2)}</strong>;
                            }
                            return <span key={j}>{part}</span>;
                        })}
                    </span>
                </div>
             );
        }

        const parts = line.split(/(\*\*.*?\*\*)/g);
        if (line.startsWith('##')) {
             return <h3 key={i} className="font-bold text-emerald-700 dark:text-emerald-400 mt-4 mb-2 text-base">{line.replace(/#/g, '')}</h3>
        }

        if (!trimmed) return <div key={i} className="h-2"></div>;

        return (
          <p key={i} className="mb-2 last:mb-0 leading-relaxed text-sm">
            {parts.map((part, j) => {
              if (part.startsWith('**') && part.endsWith('**')) {
                return <strong key={j} className="font-bold text-slate-800 dark:text-white">{part.slice(2, -2)}</strong>;
              }
              return <span key={j}>{part}</span>;
            })}
          </p>
        );
      })}
    </div>
  );
};

export const AIAssistant: React.FC<AIAssistantProps> = ({ contextData, inlineView = false }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const [input, setInput] = useState('');
  const { t } = useLanguage();
  const { theme } = useTheme();
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [useThinking, setUseThinking] = useState(false);
  const [attachedImage, setAttachedImage] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (messages.length === 0) {
        setMessages([{ 
            id: 'welcome', 
            role: 'model', 
            text: t('welcomeMessage') 
        }]);
    }
  }, [t]);

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 5 * 1024 * 1024) {
          alert("File too large. Please use an image under 5MB.");
          return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setAttachedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSendMessage = async () => {
    if ((!input.trim() && !attachedImage) || isLoading) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      image: attachedImage || undefined
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setAttachedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const parts: any[] = [];
      let systemInstruction = "You are ResinAI. A professional technical assistant for synthetic resin data analysis.";

      if (userMsg.image) {
         const base64Data = userMsg.image.split(',')[1];
         const mimeType = userMsg.image.split(';')[0].split(':')[1] || 'image/jpeg';

         parts.push({
            inlineData: {
                mimeType: mimeType, 
                data: base64Data
            }
         });

         systemInstruction = `You are a Senior QC Specialist. 
Analyze the image focus on:
1. IDENTIFY: Material type/form.
2. DEFECTS: Detect Black Specks, Gels, Flow Marks, Discoloration.
3. ASSESSMENT: Pass/Fail based on industrial standards.`;

         const analysisPrompt = userMsg.text 
           ? `Review this resin sample: ${userMsg.text}`
           : "Perform a full QC analysis on this resin sample.";

         parts.push({ text: analysisPrompt });
      } else {
         parts.push({ text: userMsg.text });

         if (contextData.length > 0) {
            const contextStr = JSON.stringify(contextData.slice(0, 15).map(p => ({
                grade: p.gradeName,
                manufacturer: p.manufacturer,
                properties: p.properties
            })));
            parts.push({ text: `\n[Database Context]: ${contextStr}` });
         }
      }

      // Use the gemini-3-flash-preview model
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [{ role: 'user', parts: parts }],
        config: {
            systemInstruction: systemInstruction,
            thinkingConfig: useThinking ? { thinkingBudget: 4096 } : undefined,
        }
      });

      const responseText = response.text || "AI analysis completed but no text output was generated.";

      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        text: responseText
      }]);

    } catch (error) {
      console.error("AI Error:", error);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        text: "Error: Could not reach the AI data center. Please check your network or API key."
      }]);
    } finally {
      setIsLoading(false);
    }
  };

