                            <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-bounce"></span>
                        </div>
                        <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">
                            {useThinking ? t('reasoning') : t('analyzing')}
                        </span>
                    </div>
                    </div>
            </div>
        )}
      </>
  );

  const renderInputArea = () => (
    <div className="p-3 bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800">
        {attachedImage && (
            <div className="flex items-center justify-between px-3 py-2 mb-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg animate-in slide-in-from-bottom-2">
                <div className="flex items-center gap-3 overflow-hidden">
                    <div className="w-10 h-10 rounded bg-slate-200 dark:bg-slate-700 shrink-0 overflow-hidden border border-slate-300 dark:border-slate-600">
