        <div className="flex items-end gap-2 bg-slate-100 dark:bg-slate-800/50 p-1.5 rounded-2xl border border-slate-200 dark:border-slate-700 focus-within:ring-2 focus-within:ring-emerald-500/20 focus-within:border-emerald-500 transition-all">
            <input type="file" ref={fileInputRef} accept="image/*" className="hidden" onChange={handleImageUpload} />
            <button onClick={() => fileInputRef.current?.click()} className={`p-2 rounded-xl transition-all shrink-0 ${attachedImage ? 'text-emerald-600 bg-emerald-100 dark:bg-emerald-900/30' : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 hover:bg-slate-200'}`}>
                {attachedImage ? <ScanEye size={20} /> : <ImageIcon size={20} />}
            </button>
            <textarea
                value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={handleKeyDown}
                placeholder={attachedImage ? t('imageContext') : t('aiPlaceholder')}
                className="w-full max-h-32 min-h-[40px] py-2 bg-transparent text-sm text-slate-800 dark:text-slate-200 outline-none resize-none leading-relaxed"
                rows={1}
