                      </div>
                    </div>
                    <div className="space-y-2"><div className="flex justify-between items-center"><span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Stroke Width</span><span className="text-[10px] font-mono font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/30 px-1.5 rounded">{trendlineWidth}px</span></div><input type="range" min="1" max="8" step="1" value={trendlineWidth} onChange={(e) => setTrendlineWidth(Number(e.target.value))} className="w-full h-1.5 bg-slate-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-emerald-500" /></div>
                 </div>
               )}
            </div>
          )}

          <div className="pt-4 border-t border-slate-100 dark:border-slate-800 grid grid-cols-2 gap-2">
            <button onClick={() => handleDownload('json')} className="flex items-center justify-center gap-2 p-2 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 rounded-lg text-[10px] font-bold text-slate-600 transition-colors uppercase"><FileJson size={14} /> JSON</button>
            <button onClick={() => handleDownload('png')} disabled={isExporting} className="flex items-center justify-center gap-2 p-2 bg-emerald-600 hover:bg-emerald-700 disabled:bg-emerald-400 text-white rounded-lg text-[10px] font-bold transition-colors uppercase shadow-md shadow-emerald-500/20">{isExporting ? <Loader2 size={14} className="animate-spin" /> : <ImageIcon size={14} />} PNG</button>
          </div>
        </div>
      </div>

      {/* Chart Canvas Area */}
      <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl relative min-h-[400px]">
        <div className="absolute top-4 right-4 z-10 flex gap-2">
             {!showConfig && <button onClick={() => setShowConfig(true)} className="p-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-500 hover:text-emerald-500 shadow-lg transition-all no-capture"><Settings size={20} /></button>}
            <button onClick={() => handleDownload('png')} disabled={isExporting} title="Snapshot Export" className="p-2.5 bg-emerald-600 text-white rounded-xl shadow-lg shadow-emerald-500/20 hover:bg-emerald-700 active:scale-95 transition-all disabled:bg-slate-300 dark:disabled:bg-slate-700 no-capture">{isExporting ? <Loader2 size={20} className="animate-spin" /> : <Camera size={20} />}</button>
        </div>

        <div className="flex-1 p-6 flex flex-col min-h-0" ref={chartRef}>
            <div className="mb-4 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
               <h2 className="text-lg font-bold text-slate-800 dark:text-white flex items-center gap-2">
                  {chartType === 'bar' ? <BarChart2 size={20} className="text-emerald-500" /> : <ScatterIcon size={20} className="text-emerald-500" />}
                  {getLabelWithUnit(yAxisKey)} vs {chartType === 'bar' ? tProp('牌号') : getLabelWithUnit(xAxisKey)}
               </h2>

               <div className="flex items-center gap-2 pr-12 md:pr-0">
                    <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">{t('showing')}</span>
                    <div className="flex items-center gap-1.5 px-3 py-1 bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-full shadow-inner">
                        <span className="text-xs font-black text-emerald-600 dark:text-emerald-400">{visibleChartData.length}</span>
                        <span className="text-[9px] text-slate-400 font-bold">/</span>
                        <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400">{data.length}</span>
                    </div>
               </div>
            </div>

            <div className="flex-1 w-full min-h-0 relative">
                {visibleChartData.length === 0 && (
                    <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-50/20 dark:bg-slate-950/20 backdrop-blur-[2px] z-50 rounded-xl">
                        <div className="p-8 bg-white dark:bg-slate-900 rounded-3xl shadow-2xl border border-slate-200 dark:border-slate-800 flex flex-col items-center gap-6 animate-in zoom-in-95 max-w-sm text-center">
                            <div className="w-16 h-16 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center"><ListFilter size={32} className="text-slate-400" /></div>
                            <div><p className="text-lg font-black text-slate-800 dark:text-white mb-2">No Matching Data</p><p className="text-sm text-slate-500 leading-relaxed">Your current filters returned 0 results. Try loosening range constraints or showing hidden groups.</p></div>
                            <div className="flex gap-3 w-full"><button onClick={clearAllFilters} className="flex-1 px-4 py-2.5 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300 text-xs font-bold rounded-xl transition-all">Reset Filters</button><button onClick={() => setAllGroupsVisibility(true)} className="flex-1 px-4 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold rounded-xl shadow-lg shadow-emerald-500/20 transition-all active:scale-95">Show All</button></div>
                        </div>
                    </div>
                )}

                <ResponsiveContainer width="100%" height="100%">
                    {chartType === 'bar' ? (
                        <BarChart data={visibleChartData} margin={{ top: 10, right: 30, left: 10, bottom: 40 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis dataKey="gradeName" angle={-45} textAnchor="end" interval={0} height={60} fontSize={10} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} />
                            <YAxis fontSize={10} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} domain={['auto', 'auto']} label={{ value: getLabelWithUnit(yAxisKey), angle: -90, position: 'insideLeft', offset: 10, fontSize: 10, fill: '#64748b' }} />
                            <Tooltip cursor={{ fill: 'rgba(16, 185, 129, 0.05)' }} content={<CustomTooltipContent />} />
                            {groupByKey && <Legend verticalAlign="top" content={RenderCustomLegend} />}
                            <Bar dataKey={yAxisKey} radius={[4, 4, 0, 0]} animationDuration={1000}>
                                {visibleChartData.map((entry, index) => {
                                    const group = String(entry[groupByKey] || 'Unknown');
                                    const isHighlighted = highlightedGroup === null || highlightedGroup === group;
                                    return <Cell key={`cell-${index}`} fill={groupByKey ? groupColors[group] : DEFAULT_PALETTE[index % DEFAULT_PALETTE.length]} fillOpacity={isHighlighted ? 1 : 0.15} />;
                                })}
                            </Bar>
                        </BarChart>
                    ) : (
                        <ComposedChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={theme === 'dark' ? '#1e293b' : '#f1f5f9'} />
                            <XAxis type={xAxisKey === 'gradeName' ? 'category' : 'number'} dataKey={xAxisKey} name={tProp(xAxisKey)} fontSize={10} domain={[xMin === '' ? 'auto' : xMin, xMax === '' ? 'auto' : xMax]} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} label={{ value: getLabelWithUnit(xAxisKey), position: 'bottom', offset: 0, fontSize: 10, fill: '#64748b' }} />
                            <YAxis type="number" dataKey={yAxisKey} name={tProp(yAxisKey)} fontSize={10} domain={[yMin === '' ? 'auto' : yMin, yMax === '' ? 'auto' : yMax]} stroke={theme === 'dark' ? '#475569' : '#94a3b8'} label={{ value: getLabelWithUnit(yAxisKey), angle: -90, position: 'insideLeft', offset: 10, fontSize: 10, fill: '#64748b' }} />
                            <ZAxis range={[60, 400]} />
                            <Tooltip cursor={{ strokeDasharray: '3 3' }} content={<CustomTooltipContent />} />
                            {groupByKey && <Legend verticalAlign="top" content={RenderCustomLegend} />}
                            <Scatter name="Resin Samples" data={visibleChartData} animationDuration={1500}>
                                {visibleChartData.map((entry, index) => {
                                    const group = String(entry[groupByKey] || 'Unknown');
                                    const isHighlighted = highlightedGroup === null || highlightedGroup === group;
                                    return <Cell key={`cell-${index}`} fill={groupByKey ? groupColors[group] : '#10b981'} fillOpacity={isHighlighted ? 1 : 0.1} strokeOpacity={isHighlighted ? 1 : 0.1} strokeWidth={1} stroke="#ffffff" />;
                                })}
                            </Scatter>
                            {trendlineSegment && <Line type="monotone" data={trendlineSegment} dataKey={yAxisKey} stroke={trendlineColor} strokeWidth={trendlineWidth} strokeDasharray={dashArray} dot={false} activeDot={false} legendType="none" />}
                        </ComposedChart>
                    )}
                </ResponsiveContainer>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { X, FileSpreadsheet, UploadCloud, CheckCircle, AlertCircle, Search, ShieldCheck, Database, Filter, Clipboard, FileText, FileJson, Image as ImageIcon, Trash2, File as FileIcon, Plus } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

interface ImportModalProps {
  isOpen: boolean;
  onClose: () => void;
  onImport?: () => void;
}

export const ImportModal: React.FC<ImportModalProps> = ({ isOpen, onClose, onImport }) => {
  const [step, setStep] = useState<1 | 2 | 3 | 4>(1);
  const [isDragging, setIsDragging] = useState(false);
  const [stagedFiles, setStagedFiles] = useState<File[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { t } = useLanguage();

  // Reset state when modal opens/closes
  useEffect(() => {
    if (!isOpen) {
        setTimeout(() => {
            setStep(1);
            setStagedFiles([]);
        }, 300);
    }
  }, [isOpen]);

  // Global Paste Listener
  useEffect(() => {
    if (!isOpen) return;

    const handlePaste = (e: ClipboardEvent) => {
        e.preventDefault();
        const items = e.clipboardData?.items;
        if (!items) return;

        const newFiles: File[] = [];

        for (let i = 0; i < items.length; i++) {
            if (items[i].kind === 'file') {
                const file = items[i].getAsFile();
                if (file) newFiles.push(file);
            } else if (items[i].kind === 'string' && items[i].type === 'text/plain') {
                items[i].getAsString((text) => {
                    if (text.trim()) {
                        // Intelligent Type Detection
                        let type = 'text/plain';
                        let ext = 'txt';
                        const trimmed = text.trim();

                        if ((trimmed.startsWith('{') || trimmed.startsWith('[')) && (trimmed.endsWith('}') || trimmed.endsWith(']'))) {
                            type = 'application/json';
                            ext = 'json';
                        } else if (text.includes(',') && text.includes('\n')) {
                            type = 'text/csv';
                            ext = 'csv';
                        } else if (text.includes('\t') && text.includes('\n')) {
                            type = 'text/tab-separated-values';
                            ext = 'tsv';
                        }

                        const blob = new Blob([text], { type });
                        const file = new File([blob], `clipboard-data-${Date.now()}.${ext}`, { type });
                        setStagedFiles(prev => [...prev, file]);
                    }
                });
            }
        }

        if (newFiles.length > 0) {
            setStagedFiles(prev => [...prev, ...newFiles]);
        }
    };

    window.addEventListener('paste', handlePaste);
    return () => window.removeEventListener('paste', handlePaste);
  }, [isOpen]);

  const addFiles = (files: FileList | File[]) => {
      const newFiles = Array.from(files);
      setStagedFiles(prev => {
          // Filter duplicates by name and size simple check
          const existing = new Set(prev.map(f => `${f.name}-${f.size}`));
          const unique = newFiles.filter(f => !existing.has(`${f.name}-${f.size}`));
          return [...prev, ...unique];
      });
  };

  const removeFile = (index: number) => {
      setStagedFiles(prev => prev.filter((_, i) => i !== index));
  };

  const handleStartProcess = () => {
    if (stagedFiles.length === 0) return;
    setStep(2);
    // Simulate processing time proportional to file count
    setTimeout(() => setStep(3), 1500); 
  };

  const handleFinish = () => {
      if (onImport) onImport();
      onClose();
  };

  const getFileIcon = (file: File) => {
      if (file.type.includes('image')) return <ImageIcon size={18} className="text-purple-500" />;
      if (file.type.includes('json')) return <FileJson size={18} className="text-amber-500" />;
      if (file.type.includes('csv') || file.type.includes('spreadsheet') || file.name.endsWith('.csv') || file.name.endsWith('.xlsx')) return <FileSpreadsheet size={18} className="text-emerald-500" />;
      return <FileText size={18} className="text-blue-500" />;
  };

  const formatFileSize = (bytes: number) => {
      if (bytes === 0) return '0 B';
      const k = 1024;
      const sizes = ['B', 'KB', 'MB', 'GB'];
      const i = Math.floor(Math.log(bytes) / Math.log(k));
      return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="w-full max-w-xl bg-white dark:bg-slate-900 rounded-3xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200 border border-slate-200 dark:border-slate-800 flex flex-col max-h-[90vh]">

        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-950/50">
          <div className="flex items-center gap-2">
            <div className="p-2 bg-emerald-100 dark:bg-emerald-900/30 rounded-xl">
                <Database className="text-emerald-600 dark:text-emerald-400" size={20} />
            </div>
            <div>
                <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100 leading-none">{t('importTitle')}</h3>
                <p className="text-[10px] text-slate-500 font-medium mt-0.5 uppercase tracking-wide">Data Ingestion Pipeline</p>
            </div>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors p-1 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-800"><X size={20} /></button>
        </div>

        {/* Content Body */}
        <div className="p-6 overflow-y-auto custom-scrollbar flex-1">
          {step === 1 && (
            <div className="space-y-6">
                {/* Drag & Drop Zone */}
                <div 
                    className={`
                        relative group border-2 border-dashed rounded-3xl p-8 flex flex-col items-center justify-center text-center transition-all duration-300 cursor-pointer overflow-hidden
                        ${isDragging 
                            ? 'border-emerald-500 bg-emerald-50/50 dark:bg-emerald-900/20 scale-[1.02]' 
                            : 'border-slate-200 dark:border-slate-700 hover:border-emerald-400 hover:bg-slate-50 dark:hover:bg-slate-800/50 bg-slate-50/30 dark:bg-slate-950/30'
                        }
                    `}
                    onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
                    onDragLeave={() => setIsDragging(false)}
                    onDrop={(e) => { e.preventDefault(); setIsDragging(false); addFiles(e.dataTransfer.files); }}
                    onClick={() => fileInputRef.current?.click()}
                >
                    <input 
                        type="file" 
                        ref={fileInputRef} 
                        className="hidden" 
                        multiple 
                        accept=".csv,.xlsx,.json,.txt,image/*" 
                        onChange={(e) => { if(e.target.files) addFiles(e.target.files); }} 
                    />

                    <div className="w-16 h-16 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 rounded-2xl flex items-center justify-center mb-4 shadow-inner group-hover:scale-110 transition-transform duration-300">
                        <UploadCloud size={32} />
                    </div>

                    <div className="space-y-1 relative z-10">
                        <h4 className="text-slate-900 dark:text-slate-100 font-bold text-sm">
                            {t('dragDrop')} <span className="text-emerald-600 dark:text-emerald-400">or Click to Browse</span>
                        </h4>
                        <div className="flex items-center justify-center gap-2 text-xs text-slate-400 font-medium">
                            <span className="flex items-center gap-1"><Clipboard size={10} /> Ctrl+V to Paste</span>
                            <span>•</span>
                            <span>.CSV, .XLSX, .JSON</span>
                        </div>
                    </div>

                    {/* Decorative Background Icon */}
                    <div className="absolute right-[-20px] bottom-[-20px] text-slate-100 dark:text-slate-800 opacity-50 pointer-events-none transition-transform group-hover:rotate-12">
                        <FileIcon size={120} />
                    </div>
                </div>

                {/* Staged Files List */}
                {stagedFiles.length > 0 && (
                    <div className="space-y-3 animate-in slide-in-from-bottom-2 fade-in">
                        <div className="flex items-center justify-between text-xs font-black text-slate-400 uppercase tracking-widest px-1">
                            <span>Ready to Import ({stagedFiles.length})</span>
                            <button onClick={() => setStagedFiles([])} className="text-rose-500 hover:text-rose-600 hover:underline">Clear All</button>
                        </div>
                        <div className="max-h-48 overflow-y-auto custom-scrollbar space-y-2 pr-1">
                            {stagedFiles.map((file, idx) => (
                                <div key={`${file.name}-${idx}`} className="flex items-center gap-3 p-3 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl group hover:border-emerald-300/50 dark:hover:border-emerald-700/50 transition-colors">
                                    <div className="p-2 bg-white dark:bg-slate-900 rounded-lg shadow-sm border border-slate-100 dark:border-slate-800">
                                        {getFileIcon(file)}
                                    </div>
                                    <div className="flex-1 min-w-0 text-left">
                                        <p className="text-sm font-bold text-slate-700 dark:text-slate-200 truncate">{file.name}</p>
                                        <p className="text-[10px] text-slate-400 font-mono uppercase">{file.type || 'Unknown Type'} • {formatFileSize(file.size)}</p>
                                    </div>
                                    <button 
                                        onClick={(e) => { e.stopPropagation(); removeFile(idx); }}
                                        className="p-1.5 text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg transition-all opacity-0 group-hover:opacity-100"
                                    >
                                        <Trash2 size={16} />
                                    </button>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {/* Action Footer */}
                <div className="pt-2">
                    <button 
                        onClick={handleStartProcess} 
                        disabled={stagedFiles.length === 0}
                        className={`
                            w-full py-4 rounded-2xl font-bold text-sm shadow-xl transition-all flex items-center justify-center gap-2
                            ${stagedFiles.length > 0 
                                ? 'bg-slate-900 dark:bg-emerald-600 text-white hover:scale-[1.01] active:scale-[0.98] shadow-emerald-500/10' 
                                : 'bg-slate-100 dark:bg-slate-800 text-slate-400 cursor-not-allowed'
                            }
                        `}
                    >
                        {stagedFiles.length > 0 ? (
                            <>
                                <Database size={16} /> {t('importTitle')} ({stagedFiles.length})
                            </>
                        ) : (
                            t('dragDropDesc')
                        )}
                    </button>
                    {stagedFiles.length === 0 && (
                        <div className="mt-4 flex justify-center">
                            <span className="text-[10px] text-slate-400 bg-slate-50 dark:bg-slate-800 px-3 py-1.5 rounded-full border border-slate-100 dark:border-slate-700 flex items-center gap-1.5">
                                <ShieldCheck size={12} className="text-emerald-500" /> {t('securityNote')}
                            </span>
                        </div>
                    )}
                </div>
            </div>
          )}

          {step === 2 && (
            <div className="flex flex-col items-center justify-center py-12">
                <div className="relative mb-8">
                    <div className="absolute inset-0 bg-emerald-500/20 blur-xl rounded-full animate-pulse"></div>
                    <div className="relative w-20 h-20 border-4 border-emerald-100 dark:border-emerald-900/30 border-t-emerald-600 rounded-full animate-spin"></div>
                    <div className="absolute inset-0 flex items-center justify-center">
                        <UploadCloud size={24} className="text-emerald-600 animate-bounce" />
                    </div>
                </div>
                <h4 className="text-slate-900 dark:text-slate-100 font-black text-lg animate-pulse">{t('processing')}</h4>
                <p className="text-xs text-slate-500 mt-2 max-w-xs text-center">Parsing {stagedFiles.length} files... Normalizing data structures and validating properties.</p>
            </div>
          )}

          {step === 3 && (
            <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4">
                <div className="flex items-center justify-between">
                    <h4 className="font-bold text-slate-800 dark:text-slate-200 flex items-center gap-2"><Filter size={18} className="text-emerald-500" /> {t('cleanData')} (Governance)</h4>
                    <span className="text-[10px] font-bold bg-amber-100 text-amber-600 px-2 py-0.5 rounded-full uppercase border border-amber-200">3 Issues Found</span>
                </div>
                <div className="space-y-2 max-h-60 overflow-y-auto custom-scrollbar pr-1">
                    <div className="p-3 bg-emerald-50/50 dark:bg-emerald-900/10 border border-emerald-100 dark:border-emerald-900/30 rounded-xl flex items-center justify-between">
                        <span className="text-xs font-medium text-slate-700 dark:text-slate-300">Grade Normalization: <span className="font-bold">PE-100S</span></span>
                        <CheckCircle size={14} className="text-emerald-500" />
                    </div>
                    <div className="p-3 bg-amber-50/50 dark:bg-amber-900/10 border border-amber-100 dark:border-amber-900/30 rounded-xl flex items-center justify-between">
                        <span className="text-xs font-medium text-slate-700 dark:text-slate-300">Manufacturer Alias: <span className="font-bold">中石化</span> &rarr; <span className="text-amber-600 font-bold">Sinopec</span></span>
                        <AlertCircle size={14} className="text-amber-500" />
                    </div>
                    <div className="p-3 bg-rose-50/50 dark:bg-rose-900/10 border border-rose-100 dark:border-rose-900/30 rounded-xl flex items-center justify-between">
                        <span className="text-xs font-medium text-slate-700 dark:text-slate-300">Missing Key Prop: <span className="font-bold">Density</span></span>
                        <span className="text-[9px] font-bold text-rose-500 uppercase">Skip Row</span>
                    </div>
                </div>
                <div className="pt-2">
                    <button onClick={() => setStep(4)} className="w-full py-3.5 bg-emerald-600 hover:bg-emerald-500 text-white rounded-2xl font-bold text-sm shadow-lg shadow-emerald-500/20 active:scale-[0.98] transition-all flex items-center justify-center gap-2">
                        <CheckCircle size={16} />
                        Confirm & Merge
                    </button>
                </div>
            </div>
          )}

          {step === 4 && (
            <div className="flex flex-col items-center justify-center py-6 text-center animate-in zoom-in-95 duration-500">
                <div className="w-24 h-24 bg-emerald-100 dark:bg-emerald-900/40 rounded-full flex items-center justify-center mb-6 shadow-xl shadow-emerald-500/10 ring-8 ring-emerald-50 dark:ring-emerald-900/20">
                    <CheckCircle className="text-emerald-600 w-12 h-12" />
                </div>
                <h4 className="text-slate-900 dark:text-white font-black text-2xl mb-2">{t('success')}</h4>
                <p className="text-slate-500 text-sm mb-8 leading-relaxed max-w-xs mx-auto">
                    {t('importSuccessMsg')}<br/>
                    <span className="text-emerald-600 dark:text-emerald-400 font-bold">{stagedFiles.length + 4} records processed.</span>
                </p>
                <div className="flex gap-3 w-full">
                    <button onClick={onClose} className="flex-1 px-4 py-3 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 font-bold rounded-2xl hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">{t('viewLog')}</button>
                    <button onClick={handleFinish} className="flex-[2] px-4 py-3 bg-slate-900 dark:bg-emerald-600 text-white font-bold rounded-2xl shadow-xl active:scale-95 transition-all">{t('finish')}</button>
                </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import { Category, Product, Manufacturer, Reference } from './types';

