                <div className="flex flex-col relative z-10"><div className="flex items-baseline gap-1.5 pl-1"><span className="text-2xl font-black text-white tracking-tight">{stats.refCoverage}%</span><span className="text-[9px] font-bold text-emerald-100 uppercase">Validated</span></div><div className="mt-3 w-full h-1 bg-white/20 rounded-full overflow-hidden"><div className="h-full bg-white transition-all duration-1000" style={{ width: `${stats.refCoverage}%` }}></div></div></div>
            </div>
        </div>
    );
};

type AppView = 'dashboard' | 'analytics' | 'ai';

const AppContent: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('resindb-session');
    return saved ? JSON.parse(saved) : null;
  });

  const [allProducts, setAllProducts] = useState<Product[]>(MOCK_PRODUCTS);
  const [selectedCategoryId, setSelectedCategoryId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [columns, setColumns] = useState<ColumnConfig[]>([]);
  const [isImportOpen, setIsImportOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [activeView, setActiveView] = useState<AppView>('dashboard');

  useEffect(() => {
    setColumns(getDynamicColumns(allProducts));
  }, []);

  useEffect(() => {
     const newCols = getDynamicColumns(allProducts);
     // Only update if keys have changed to avoid flickering, simplistic check by length for now
     if (newCols.length !== columns.length) setColumns(newCols);
  }, [allProducts.length]);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    localStorage.setItem('resindb-session', JSON.stringify(user));
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('resindb-session');
  };

  const handleUpdateUserProfile = (updatedInfo: any) => {
    if (!currentUser) return;
    const newUser = { ...currentUser, ...updatedInfo };
    setCurrentUser(newUser);
    localStorage.setItem('resindb-session', JSON.stringify(newUser));
    const allUsersStr = localStorage.getItem('resindb-users');
    if (allUsersStr) {
        const allUsers = JSON.parse(allUsersStr);
        const updatedUsers = allUsers.map((u: any) => u.id === currentUser.id ? { ...u, ...updatedInfo } : u);
        localStorage.setItem('resindb-users', JSON.stringify(updatedUsers));
    }
  };

  const handleToggleColumn = (key: string) => {
    setColumns(cols => cols.map(c => c.key === key ? { ...c, visible: !c.visible } : c));
  };

  const handleToggleAllColumns = (visible: boolean) => {
    setColumns(cols => cols.map(c => c.isSystem ? c : { ...c, visible }));
  };

  const handleImportData = () => {
      const newProducts: Product[] = Array.from({ length: 5 }).map((_, i) => ({
        id: `imported-${Date.now()}-${i}`,
        gradeName: `New-Grade-${1000 + i} (Imported)`,
        manufacturer: 'Synthetic Tech Inc.',
        manufacturerId: 'm-30',
        categoryIds: ['cat_epdm_path_1'],
        updatedAt: new Date().toISOString().split('T')[0],
        properties: {
          '密度': { value: 0.92 + (Math.random() * 0.05), unit: 'g/cm³' },
          '熔体质量流动速率': { value: 1 + (Math.random() * 5), unit: 'g/10min' },
          '典型应用': { value: 'Imported batch test' }
        }
      }));
      setAllProducts(prev => [...newProducts, ...prev]);
      setIsImportOpen(false);
  };

  const handleDeleteProducts = (ids: string[]) => {
    setAllProducts(prev => prev.filter(p => !ids.includes(p.id)));
  };

  const handleUpdateProduct = (updatedProduct: Product) => {
    setAllProducts(prev => prev.map(p => p.id === updatedProduct.id ? updatedProduct : p));
  };

  const handleBatchUpdate = (ids: string[], updates: Partial<Product>) => {
    const { _propertyUpdates, ...directUpdates } = updates as any;
    setAllProducts(prev => prev.map(p => {
      if (!ids.includes(p.id)) return p;
      const newProps = { ...p.properties };
      if (_propertyUpdates) {
        Object.entries(_propertyUpdates).forEach(([key, val]) => {
          newProps[key] = val as PropertyValue;
        });
      }
      return { ...p, ...directUpdates, properties: newProps, updatedAt: new Date().toISOString().split('T')[0] };
    }));
  };

  const filteredData = useMemo(() => {
    return allProducts.filter(product => {
      const matchesCategory = selectedCategoryId ? product.categoryIds.includes(selectedCategoryId) : true;
      if (!matchesCategory) return false;
      const query = searchQuery.toLowerCase();
      return product.gradeName.toLowerCase().includes(query) || product.manufacturer.toLowerCase().includes(query) || Object.keys(product.properties).some(k => k.toLowerCase().includes(query));
    });
  }, [allProducts, selectedCategoryId, searchQuery]);

  if (!currentUser) return <AuthScreen onLogin={handleLogin} />;

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 font-sans text-slate-900 dark:text-slate-100 overflow-hidden transition-colors duration-300">

      {/* Primary Navigation Sidebar */}
      <nav className="w-16 md:w-20 bg-slate-900 dark:bg-slate-950 flex flex-col items-center py-6 gap-8 z-50 shrink-0 border-r border-white/5">
         <div className="w-10 h-10 bg-emerald-600 rounded-xl flex items-center justify-center shadow-lg shadow-emerald-900/40 mb-2">
            <Beaker size={20} className="text-white" />
         </div>

         <div className="flex-1 flex flex-col gap-4">
            <button 
                onClick={() => setActiveView('dashboard')}
                className={`p-3 rounded-2xl transition-all duration-300 group relative ${activeView === 'dashboard' ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-500/20' : 'text-slate-500 hover:text-emerald-400 hover:bg-slate-800'}`}
                title="Dashboard"
            >
                <LayoutDashboard size={24} />
                {activeView === 'dashboard' && <div className="absolute -left-3 top-1/2 -translate-y-1/2 w-1.5 h-8 bg-emerald-500 rounded-r-full shadow-[0_0_12px_rgba(16,185,129,0.8)]"></div>}
            </button>
            <button 
                onClick={() => setActiveView('analytics')}
                className={`p-3 rounded-2xl transition-all duration-300 group relative ${activeView === 'analytics' ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-500/20' : 'text-slate-500 hover:text-emerald-400 hover:bg-slate-800'}`}
                title="Data Visualization"
            >
                <BarChart3 size={24} />
                {activeView === 'analytics' && <div className="absolute -left-3 top-1/2 -translate-y-1/2 w-1.5 h-8 bg-emerald-500 rounded-r-full shadow-[0_0_12px_rgba(16,185,129,0.8)]"></div>}
            </button>
            <button 
                onClick={() => setActiveView('ai')}
                className={`p-3 rounded-2xl transition-all duration-300 group relative ${activeView === 'ai' ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-500/20' : 'text-slate-500 hover:text-emerald-400 hover:bg-slate-800'}`}
                title="AI Assistant"
            >
                <Bot size={24} />
                {activeView === 'ai' && <div className="absolute -left-3 top-1/2 -translate-y-1/2 w-1.5 h-8 bg-emerald-500 rounded-r-full shadow-[0_0_12px_rgba(16,185,129,0.8)]"></div>}
            </button>
         </div>

         <div className="flex flex-col gap-4 mb-2">
            <button 
                onClick={() => setIsAdminOpen(true)}
                className="p-3 text-slate-500 hover:text-emerald-400 hover:bg-slate-800 rounded-2xl transition-all"
                title="System Admin"
            >
                <ShieldCheck size={24} />
            </button>
         </div>
      </nav>

      {/* Secondary Category Sidebar (only for Data views) */}
      {(activeView === 'dashboard' || activeView === 'analytics') && (
        <TreeSidebar 
          categories={CATEGORY_TREE}
          selectedCategoryId={selectedCategoryId}
          onSelectCategory={setSelectedCategoryId}
          totalCount={allProducts.length}
        />
      )}

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0 h-full relative">
        <TopBar 
            user={currentUser}
            onLogout={handleLogout}
            onOpenProfile={() => setIsProfileOpen(true)}
            onOpenAdmin={() => setIsAdminOpen(true)}
            searchQuery={searchQuery}
            onSearchChange={setSearchQuery}
            columns={columns}
            onToggleColumn={handleToggleColumn}
            onToggleAllColumns={handleToggleAllColumns}
            onOpenImport={() => setIsImportOpen(true)}
            viewMode={activeView === 'analytics' ? 'chart' : 'grid'}
            onViewModeChange={(m) => setActiveView(m === 'chart' ? 'analytics' : 'dashboard')}
        />

        <div className="flex-1 flex flex-col p-6 min-h-0 overflow-hidden">
            {activeView !== 'ai' && <Breadcrumbs categoryId={selectedCategoryId} onReset={() => setSelectedCategoryId(null)} />}
            {activeView === 'dashboard' && <SummaryStats data={filteredData} />}

            <div className="flex-1 w-full min-h-0 relative animate-in fade-in zoom-in-95 duration-300">
                <ErrorBoundary>
                    {activeView === 'dashboard' && (
                         <div className="absolute inset-0 pb-1">
                            <DataGrid 
                                data={filteredData}
                                columns={columns}
                                isLoading={false}
                                onDelete={handleDeleteProducts}
                                onUpdate={handleUpdateProduct}
                                onBatchUpdate={handleBatchUpdate}
                                onCategorySelect={setSelectedCategoryId}
                            />
                         </div>
                    )}
                    {activeView === 'analytics' && (
                        <div className="absolute inset-0">
                            <DataVisualizer data={filteredData} />
                        </div>
                    )}
                    {activeView === 'ai' && (
                        <div className="absolute inset-0 bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 overflow-hidden shadow-xl flex flex-col">
                             <div className="p-4 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-950/50 flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                    <div className="p-2 bg-emerald-600 rounded-lg text-white"><Bot size={20} /></div>
                                    <h2 className="text-lg font-bold">ResinAI 全屏对话空间</h2>
                                </div>
                             </div>
                             <div className="flex-1 relative">
                                <AIAssistant contextData={filteredData} inlineView={true} />
                             </div>
                        </div>
                    )}
                </ErrorBoundary>
            </div>
        </div>
      </div>

      <ImportModal isOpen={isImportOpen} onClose={() => setIsImportOpen(false)} onImport={handleImportData} />
      <ProfileModal isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} user={currentUser} onSave={handleUpdateUserProfile} />
      <AdminModal isOpen={isAdminOpen} onClose={() => setIsAdminOpen(false)} />

      {/* Keep floating AI button as an alternative trigger when not in AI view */}
      {activeView !== 'ai' && <AIAssistant contextData={filteredData} />}
    </div>
  );
};

const App: React.FC = () => {
  return (
    <LanguageProvider>
      <ThemeProvider>
        <AppContent />
      </ThemeProvider>
    </LanguageProvider>
  );
};

export default App;

