                <div className="absolute top-full right-0 mt-4 w-60 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2rem] shadow-2xl p-2 animate-in fade-in zoom-in-95 origin-top-right z-50 flex flex-col gap-1">
                    <button onClick={onOpenProfile} className="flex items-center gap-3 px-4 py-3 rounded-2xl hover:bg-slate-50 dark:hover:bg-slate-800 text-sm font-bold text-slate-700 dark:text-slate-200 transition-colors"><User size={18} /> Profile</button>
                    <button onClick={onOpenAdmin} className="flex items-center gap-3 px-4 py-3 rounded-2xl hover:bg-slate-50 dark:hover:bg-slate-800 text-sm font-bold text-slate-700 dark:text-slate-200 transition-colors"><Shield size={18} /> Admin</button>
                    <button onClick={toggleLanguage} className="flex items-center gap-3 px-4 py-3 rounded-2xl hover:bg-slate-50 dark:hover:bg-slate-800 text-sm font-bold text-slate-700 dark:text-slate-200 transition-colors"><Globe size={18} /> {language === 'zh' ? 'English' : '中文'}</button>
                    <div className="h-px bg-slate-100 dark:bg-slate-800 my-1"></div>
                    <button onClick={onLogout} className="flex items-center gap-3 px-4 py-3 rounded-2xl hover:bg-rose-50 dark:hover:bg-rose-900/20 text-sm font-bold text-rose-600 transition-colors"><LogOut size={18} /> Logout</button>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Category } from '../types';
import { ChevronRight, Folder, FolderOpen, Layers, LayoutGrid, Beaker, Database, Search, X } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

interface TreeSidebarProps {
  categories: Category[];
  selectedCategoryId: string | null;
  onSelectCategory: (id: string | null) => void;
  totalCount?: number;
}

const TreeNode: React.FC<{
  category: Category;
  selectedId: string | null;
  onSelect: (id: string) => void;
  depth: number;
  forceExpand?: boolean;
}> = ({ category, selectedId, onSelect, depth, forceExpand = false }) => {
  const [isExpanded, setIsExpanded] = useState(depth < 1); 
  const hasChildren = category.children && category.children.length > 0;
  const isSelected = selectedId === category.id;
  const { language } = useLanguage();

  React.useEffect(() => { if (forceExpand) setIsExpanded(true); }, [forceExpand]);

  const displayOpen = isExpanded || forceExpand;

  return (
    <div className="select-none my-1">
      <div
        onClick={(e) => {
            e.stopPropagation();
            if(hasChildren) setIsExpanded(!isExpanded);
            onSelect(category.id);
        }}
        className={`
          flex items-center px-4 py-3 cursor-pointer text-sm transition-all duration-300 mx-2 rounded-full relative overflow-hidden group
          ${isSelected 
            ? 'bg-slate-900 dark:bg-white text-white dark:text-slate-900 font-bold shadow-lg shadow-slate-200/50 dark:shadow-black/30' 
            : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 hover:text-slate-900 dark:hover:text-slate-200'}
        `}
        style={{ paddingLeft: `${depth * 16 + 16}px` }}
      >
        <div className={`mr-3 transition-transform duration-300 ${displayOpen && hasChildren ? 'rotate-90' : ''}`}>
            {hasChildren && (
                <ChevronRight size={14} className={isSelected ? 'text-white/70 dark:text-slate-900/70' : 'text-slate-400'} />
            )}
        </div>
        <span className="truncate relative z-10 flex-1">{language === 'en' && category.nameEn ? category.nameEn : category.name}</span>
        {isSelected && <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 mr-1 animate-pulse"></div>}
      </div>
      {displayOpen && hasChildren && (
        <div className="relative ml-5 pl-3 border-l-2 border-slate-100 dark:border-slate-800 transition-all duration-300">
          {category.children!.map((child) => (
            <TreeNode
              key={child.id}
              category={child}
              selectedId={selectedId}
              onSelect={onSelect}
              depth={depth + 1}
              forceExpand={forceExpand}
            />
          ))}
        </div>
      )}
    </div>
  );
};

export const TreeSidebar: React.FC<TreeSidebarProps> = ({ categories, selectedCategoryId, onSelectCategory, totalCount = 0 }) => {
  const { t, language } = useLanguage();
  const [searchTerm, setSearchTerm] = useState('');

  const filterCategories = (cats: Category[], term: string): Category[] => {
    return cats.reduce<Category[]>((acc, cat) => {
        const name = language === 'en' && cat.nameEn ? cat.nameEn : cat.name;
        const matches = name.toLowerCase().includes(term.toLowerCase());
        let filteredChildren: Category[] = [];
        if (cat.children) filteredChildren = filterCategories(cat.children, term);
        if (matches || filteredChildren.length > 0) acc.push({ ...cat, children: filteredChildren });
        return acc;
    }, []);
  };

  const displayedCategories = useMemo(() => searchTerm.trim() ? filterCategories(categories, searchTerm) : categories, [categories, searchTerm, language]);

  return (
    <div className="flex flex-col h-full">
      <div className="p-5 pb-2">
        {/* Header */}
        <div 
            className={`
              flex items-center justify-between px-4 py-3.5 rounded-[1.5rem] cursor-pointer transition-all duration-300 mb-4 border
              ${!selectedCategoryId 
                ? 'bg-gradient-to-br from-emerald-500 to-teal-600 text-white shadow-xl shadow-emerald-500/20 border-transparent' 
                : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 hover:border-emerald-500/50'
              }
            `}
            onClick={() => onSelectCategory(null)}
        >
            <div className="flex items-center gap-3">
                <LayoutGrid size={18} />
                <span className="font-bold text-sm tracking-wide">{t('allProducts')}</span>
            </div>
            <span className={`px-2 py-0.5 rounded-full text-[10px] font-black ${!selectedCategoryId ? 'bg-white/20' : 'bg-slate-100 dark:bg-slate-700'}`}>{totalCount}</span>
        </div>

        {/* Search */}
        <div className="relative group mb-2">
             <Search className="absolute left-3.5 top-2.5 text-slate-400 group-focus-within:text-emerald-500 transition-colors" size={16} />
             <input 
                type="text" 
                placeholder={t('searchCategories')} 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-8 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-sm font-medium focus:ring-2 focus:ring-emerald-500/20 outline-none transition-all placeholder:text-slate-400"
             />
             {searchTerm && <button onClick={() => setSearchTerm('')} className="absolute right-3 top-3 text-slate-400 hover:text-slate-600"><X size={14} /></button>}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-3 custom-scrollbar pb-4">
        {displayedCategories.length > 0 ? (
            displayedCategories.map((cat) => (
              <TreeNode key={cat.id} category={cat} selectedId={selectedCategoryId} onSelect={onSelectCategory} depth={0} forceExpand={!!searchTerm} />
            ))
        ) : (
            <div className="text-center py-8 text-xs text-slate-400 italic">No matching categories</div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Product, ColumnConfig, SortConfig, PropertyValue } from '../types';
import { MoreHorizontal, FileText, Factory, CalendarClock, Edit, Trash2, CheckSquare, Square, MinusSquare, ArrowUp, ArrowDown, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight, ArrowUpDown, ListChecks, Tags, Eye, Info, BookOpen, X, Copy } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { EditProductModal } from './EditProductModal';
import { DeleteConfirmationModal } from './DeleteConfirmationModal';
import { BatchEditModal } from './BatchEditModal';
import { CATEGORY_TREE, REFERENCES } from '../constants';
import { ProductDetailDrawer } from './ProductDetailDrawer';

interface DataGridProps {
  data: Product[];
  columns: ColumnConfig[];
  isLoading: boolean;
  onDelete: (ids: string[]) => void;
  onUpdate: (product: Product) => void;
  onBatchUpdate: (ids: string[], updates: Partial<Product>) => void;
  onCategorySelect: (id: string) => void;
}

