// --- Error Boundary Component ---
class ErrorBoundary extends React.Component<{children?: ReactNode, fallback?: ReactNode}, {hasError: boolean}> {
  constructor(props: any) { super(props); this.state = { hasError: false }; }
  static getDerivedStateFromError() { return { hasError: true }; }
  render() {
    if (this.state.hasError) return this.props.fallback || <div className="p-8 text-center">Something went wrong.</div>;
    return this.props.children;
  }
}

const getDynamicColumns = (products: Product[]): ColumnConfig[] => {
  const propertyKeys = new Set<string>();
  products.forEach(p => Object.keys(p.properties).forEach(k => propertyKeys.add(k)));
  const defaultVisible = ['密度', '熔体质量流动速率', '拉伸屈服应力', '弯曲模量', '悬臂梁缺口冲击强度', '热变形温度', '典型应用'];
  const dynamicCols: ColumnConfig[] = Array.from(propertyKeys).map(key => ({
    key, label: key, visible: defaultVisible.includes(key), isSystem: false
  })).sort((a, b) => {
      const aPrio = defaultVisible.includes(a.key);
      const bPrio = defaultVisible.includes(b.key);
      if (aPrio && !bPrio) return -1;
      if (!aPrio && bPrio) return 1;
      return a.label.localeCompare(b.label);
  });
  return [
    { key: 'gradeName', label: '牌号', visible: true, isSystem: true },
    { key: 'manufacturer', label: '所属分类', visible: true, isSystem: true },
    { key: 'updatedAt', label: '更新时间', visible: false, isSystem: false },
    ...dynamicCols
  ];
};

const Breadcrumbs: React.FC<{ categoryId: string | null, onReset: () => void }> = ({ categoryId, onReset }) => {
    const { t, language } = useLanguage();

    const path = useMemo(() => {
        if (!categoryId) return [];
        const findPath = (nodes: Category[], targetId: string, currentPath: Category[]): Category[] | null => {
            for (const node of nodes) {
                if (node.id === targetId) return [...currentPath, node];
                if (node.children) {
                    const childResult = findPath(node.children, targetId, [...currentPath, node]);
                    if (childResult) return childResult;
                }
            }
            return null;
        };
        return findPath(CATEGORY_TREE, categoryId, []) || [];
    }, [categoryId]);

    return (
        <nav className="flex items-center text-sm text-slate-500 dark:text-slate-400 mb-4 px-1">
            <div 
                className="flex items-center hover:text-emerald-600 dark:hover:text-emerald-400 transition-colors cursor-pointer group" 
                onClick={onReset}
            >
                <Home size={14} className="mr-1.5 transition-transform group-hover:scale-110" />
                <span className="font-medium">{t('home')}</span>
            </div>
            {path.map((cat) => (
                <React.Fragment key={cat.id}>
                    <ChevronRight size={14} className="mx-2 text-slate-300 dark:text-slate-600" />
                    <span className="font-medium text-slate-800 dark:text-slate-200 hover:text-emerald-600 dark:hover:text-emerald-400 transition-colors cursor-pointer">
                        {language === 'en' && cat.nameEn ? cat.nameEn : cat.name}
                    </span>
                </React.Fragment>
            ))}
        </nav>
    );
};

const SummaryStats: React.FC<{ data: Product[] }> = ({ data }) => {
    const { t, tProp } = useLanguage();
    const stats = useMemo(() => {
        const manufacturers = new Set(data.map(p => p.manufacturerId || p.manufacturer)).size;
        let densitySum = 0, densityCount = 0, mfrSum = 0, mfrCount = 0, totalPropsWithRefs = 0, totalPropsCount = 0;
        data.forEach(p => {
            const d = parseFloat(String(p.properties['密度']?.value));
            if (!isNaN(d)) { densitySum += d; densityCount++; }
            const m = parseFloat(String(p.properties['熔体质量流动速率']?.value));
            if (!isNaN(m)) { mfrSum += m; mfrCount++; }
            (Object.values(p.properties) as PropertyValue[]).forEach(prop => {
                totalPropsCount++;
                if (prop.referenceId) totalPropsWithRefs++;
            });
        });
        return {
            count: data.length,
            manufacturers,
            avgDensity: densityCount ? (densitySum / densityCount).toFixed(3) : '-',
            avgMfr: mfrCount ? (mfrSum / mfrCount).toFixed(2) : '-',
            refCoverage: totalPropsCount > 0 ? ((totalPropsWithRefs / totalPropsCount) * 100).toFixed(1) : '0'
        };
    }, [data]);

    const Card = ({ icon: Icon, color, label, value, sub, delay }: any) => (
        <div className={`relative overflow-hidden bg-white dark:bg-slate-800/60 rounded-[2rem] p-5 shadow-sm border border-slate-100 dark:border-slate-800 transition-all hover:scale-[1.02] hover:shadow-xl group animate-in fade-in slide-in-from-bottom-4 duration-700`} style={{ animationDelay: delay }}>
            <div className={`absolute top-0 right-0 p-8 opacity-[0.03] dark:opacity-[0.05] group-hover:scale-125 group-hover:rotate-12 transition-transform duration-500`}>
                <Icon size={120} />
            </div>
            <div className="relative z-10 flex flex-col h-full justify-between">
                <div className="flex items-center gap-3 mb-4">
                    <div className={`w-10 h-10 rounded-2xl flex items-center justify-center text-white shadow-lg ${color}`}>
                        <Icon size={20} />
                    </div>
                    <span className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest">{label}</span>
                </div>
                <div>
                    <div className="text-3xl font-black text-slate-800 dark:text-slate-100 tracking-tight">{value}</div>
                    <div className="text-xs font-semibold text-slate-400 mt-1">{sub}</div>
                </div>
            </div>
        </div>
    );

    return (
        <div className="grid grid-cols-2 lg:grid-cols-4 xl:grid-cols-5 gap-4 mb-6">
            <Card icon={Database} color="bg-gradient-to-br from-indigo-500 to-violet-600" label={t('total')} value={stats.count} sub={tProp('牌号')} delay="0ms" />
            <Card icon={Factory} color="bg-gradient-to-br from-blue-500 to-cyan-600" label={t('manufacturers')} value={stats.manufacturers} sub="Active Entities" delay="100ms" />
            <Card icon={FlaskConical} color="bg-gradient-to-br from-emerald-500 to-teal-600" label={`${t('avg')} ${tProp('密度')}`} value={stats.avgDensity} sub="g/cm³" delay="200ms" />
            <Card icon={TrendingUp} color="bg-gradient-to-br from-amber-500 to-orange-600" label={`${t('avg')} MFR`} value={stats.avgMfr} sub="g/10min" delay="300ms" />

            <div className="hidden xl:flex relative overflow-hidden bg-slate-900 dark:bg-emerald-950/30 rounded-[2rem] p-5 shadow-lg border border-slate-800 dark:border-emerald-900/50 group animate-in fade-in slide-in-from-bottom-4 duration-700" style={{ animationDelay: '400ms' }}>
                <div className="absolute inset-0 bg-gradient-to-br from-emerald-600/20 to-transparent"></div>
                <div className="relative z-10 w-full flex flex-col justify-between">
                    <div className="flex items-center justify-between">
                        <div className="p-2 bg-emerald-500/10 rounded-xl text-emerald-400 border border-emerald-500/20"><ShieldCheck size={20} /></div>
                        <span className="text-[10px] font-black text-emerald-500/60 uppercase tracking-widest">Quality</span>
                    </div>
                    <div>
                        <div className="flex items-baseline gap-1">
                            <span className="text-3xl font-black text-white">{stats.refCoverage}<span className="text-lg text-emerald-500/60">%</span></span>
                        </div>
                        <div className="w-full h-1.5 bg-slate-800 rounded-full mt-3 overflow-hidden">
                            <div className="h-full bg-emerald-500 rounded-full transition-all duration-1000 group-hover:shadow-[0_0_10px_rgba(16,185,129,0.5)]" style={{ width: `${stats.refCoverage}%` }}></div>
                        </div>
                        <p className="text-[10px] text-slate-400 mt-2 font-medium">Standardized Data Coverage</p>
                    </div>
                </div>
            </div>
        </div>
    );
};

type AppView = 'dashboard' | 'analytics' | 'ai';

const AppContent: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('resindb-session');
    return saved ? JSON.parse(saved) : null;
  });

  const [allProducts, setAllProducts] = useState<Product[]>(MOCK_PRODUCTS);
  const [selectedCategoryId, setSelectedCategoryId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [columns, setColumns] = useState<ColumnConfig[]>([]);
  const [isImportOpen, setIsImportOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [activeView, setActiveView] = useState<AppView>('dashboard');
  const [isNavCollapsed, setIsNavCollapsed] = useState(false);

  useEffect(() => { setColumns(getDynamicColumns(allProducts)); }, []);
  useEffect(() => {
     const newCols = getDynamicColumns(allProducts);
     if (newCols.length !== columns.length) setColumns(newCols);
  }, [allProducts.length]);

  const filteredData = useMemo(() => {
    return allProducts.filter(product => {
      if (selectedCategoryId && !product.categoryIds.includes(selectedCategoryId)) return false;
      const q = searchQuery.toLowerCase();
      return product.gradeName.toLowerCase().includes(q) || product.manufacturer.toLowerCase().includes(q) || Object.keys(product.properties).some(k => k.toLowerCase().includes(q));
    });
  }, [allProducts, selectedCategoryId, searchQuery]);

  const handleImportData = () => {
      const newProducts: Product[] = Array.from({ length: 5 }).map((_, i) => ({
        id: `imported-${Date.now()}-${i}`,
        gradeName: `New-Grade-${1000 + i} (Imported)`,
        manufacturer: 'Synthetic Tech Inc.',
        manufacturerId: 'm-30',
        categoryIds: ['root_plastic'], 
        updatedAt: new Date().toISOString().split('T')[0],
        properties: {
          '密度': { value: 0.92 + (Math.random() * 0.05), unit: 'g/cm³' },
          '熔体质量流动速率': { value: 1 + (Math.random() * 5), unit: 'g/10min' },
          '应用': { value: 'Imported batch test' }
        }
      }));
      setAllProducts(prev => [...newProducts, ...prev]);
      setIsImportOpen(false);
  };

  const handleUpdateUserProfile = (updatedInfo: any) => {
    if (!currentUser) return;
    const newUser = { ...currentUser, ...updatedInfo };
    setCurrentUser(newUser);
    localStorage.setItem('resindb-session', JSON.stringify(newUser));
    const allUsersStr = localStorage.getItem('resindb-users');
    if (allUsersStr) {
        const allUsers = JSON.parse(allUsersStr);
        const updatedUsers = allUsers.map((u: any) => u.id === currentUser.id ? { ...u, ...updatedInfo } : u);
        localStorage.setItem('resindb-users', JSON.stringify(updatedUsers));
    }
  };

  if (!currentUser) return <AuthScreen onLogin={(u) => { setCurrentUser(u); localStorage.setItem('resindb-session', JSON.stringify(u)); }} />;

  return (
    <div className="flex h-screen bg-[#f2f4f6] dark:bg-[#050505] font-sans text-slate-900 dark:text-slate-100 overflow-hidden transition-colors duration-500 selection:bg-emerald-500/30">

      {/* Floating Navigation Dock */}
      <nav className={`fixed left-4 top-1/2 -translate-y-1/2 z-50 flex flex-col items-center py-4 gap-6 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border border-white/20 dark:border-slate-800/50 shadow-2xl shadow-slate-200/50 dark:shadow-black/50 rounded-[2.5rem] transition-all duration-500 ${isNavCollapsed ? 'w-0 opacity-0 overflow-hidden py-0 border-0' : 'w-20'}`}>
         <div className="w-12 h-12 bg-gradient-to-br from-emerald-500 to-teal-600 rounded-[1.2rem] flex items-center justify-center shadow-lg shadow-emerald-500/30 mb-2 group cursor-pointer hover:scale-110 transition-transform">
            <Beaker size={24} className="text-white" />
         </div>

         <div className="flex flex-col gap-3 w-full px-3">
            {[
                { id: 'dashboard', icon: LayoutDashboard },
                { id: 'analytics', icon: PieChart },
                { id: 'ai', icon: Bot }
            ].map((item) => (
                <button 
                    key={item.id}
                    onClick={() => setActiveView(item.id as AppView)}
                    className={`relative w-14 h-14 rounded-[1.2rem] flex items-center justify-center transition-all duration-300 group ${activeView === item.id ? 'bg-slate-900 dark:bg-white text-white dark:text-slate-900 shadow-xl scale-105' : 'text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 hover:text-slate-600 dark:hover:text-slate-200'}`}
                >
                    <item.icon size={24} />
                    {activeView === item.id && <div className="absolute -right-1 top-1/2 -translate-y-1/2 w-1 h-3 bg-emerald-500 rounded-full"></div>}
                </button>
            ))}
         </div>

         <div className="mt-auto flex flex-col gap-3 w-full px-3">
            <button onClick={() => setIsAdminOpen(true)} className="w-14 h-14 rounded-[1.2rem] text-slate-400 hover:bg-emerald-50 dark:hover:bg-emerald-900/20 hover:text-emerald-600 transition-all flex items-center justify-center">
                <ShieldCheck size={24} />
            </button>
         </div>
      </nav>

      {/* Main Layout Grid */}
      <div className={`flex-1 flex flex-col h-full transition-all duration-500 p-4 gap-4 ${isNavCollapsed ? 'ml-0' : 'ml-24'}`}>

        {/* Floating Top Bar */}
        <div className="shrink-0 z-40">
            <TopBar 
                user={currentUser}
                onLogout={() => { setCurrentUser(null); localStorage.removeItem('resindb-session'); }}
                onOpenProfile={() => setIsProfileOpen(true)}
                onOpenAdmin={() => setIsAdminOpen(true)}
                searchQuery={searchQuery}
                onSearchChange={setSearchQuery}
                columns={columns}
                onToggleColumn={(k) => setColumns(c => c.map(col => col.key === k ? {...col, visible: !col.visible} : col))}
                onToggleAllColumns={() => {}}
                onOpenImport={() => setIsImportOpen(true)}
                viewMode={activeView === 'analytics' ? 'chart' : 'grid'}
                onViewModeChange={(m) => setActiveView(m === 'chart' ? 'analytics' : 'dashboard')}
            />
        </div>

        <div className="flex-1 flex min-h-0 gap-4">
            {/* Secondary Sidebar Panel */}
            {(activeView === 'dashboard' || activeView === 'analytics') && (
                <div className="w-72 shrink-0 flex flex-col">
                    <div className="flex-1 bg-white/60 dark:bg-slate-900/60 backdrop-blur-xl border border-white/20 dark:border-slate-800 rounded-[2.5rem] shadow-sm overflow-hidden flex flex-col">
                        <TreeSidebar 
                            categories={CATEGORY_TREE}
                            selectedCategoryId={selectedCategoryId}
                            onSelectCategory={setSelectedCategoryId}
                            totalCount={allProducts.length}
                        />
                    </div>
                </div>
            )}

            {/* Main Content Surface */}
            <div className="flex-1 flex flex-col min-w-0 bg-white/60 dark:bg-slate-900/60 backdrop-blur-xl border border-white/20 dark:border-slate-800 rounded-[2.5rem] shadow-sm overflow-hidden relative">
                <div className="flex-1 overflow-hidden p-6 flex flex-col relative">
                    {/* Background Pattern */}
                    <div className="absolute inset-0 opacity-[0.02] pointer-events-none" style={{ backgroundImage: 'radial-gradient(#64748b 1px, transparent 1px)', backgroundSize: '24px 24px' }}></div>

                    {activeView !== 'ai' && (
                        <div className="mb-2 shrink-0">
                            <Breadcrumbs categoryId={selectedCategoryId} onReset={() => setSelectedCategoryId(null)} />
                        </div>
                    )}

                    {activeView === 'dashboard' && (
                        <div className="shrink-0">
                            <SummaryStats data={filteredData} />
                        </div>
                    )}

                    <div className="flex-1 min-h-0 relative rounded-[2rem] overflow-hidden bg-white/50 dark:bg-slate-950/30 border border-white/40 dark:border-slate-800 shadow-inner">
                        <ErrorBoundary>
                            {activeView === 'dashboard' && (
                                <div className="absolute inset-0">
                                    <DataGrid 
                                        data={filteredData}
                                        columns={columns}
                                        isLoading={false}
                                        onDelete={(ids) => setAllProducts(p => p.filter(x => !ids.includes(x.id)))}
                                        onUpdate={(up) => setAllProducts(p => p.map(x => x.id === up.id ? up : x))}
                                        onBatchUpdate={(ids, ups) => { /* simplified for brevity */ }}
                                        onCategorySelect={setSelectedCategoryId}
                                    />
                                </div>
                            )}
                            {activeView === 'analytics' && <div className="absolute inset-0"><DataVisualizer data={filteredData} /></div>}
                            {activeView === 'ai' && (
                                <div className="absolute inset-0 flex flex-col">
                                     <div className="p-6 border-b border-slate-100 dark:border-slate-800/50 flex items-center justify-between bg-white/40 dark:bg-slate-900/40 backdrop-blur-md">
                                        <div className="flex items-center gap-4">
                                            <div className="w-12 h-12 rounded-2xl bg-gradient-to-tr from-emerald-500 to-teal-400 flex items-center justify-center text-white shadow-lg shadow-emerald-500/20"><Bot size={24} /></div>
                                            <div>
                                                <h2 className="text-xl font-black text-slate-800 dark:text-white tracking-tight">ResinAI Workspace</h2>
                                                <p className="text-xs font-medium text-slate-500 flex items-center gap-1.5"><span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span> Gemini 3 Flash Online</p>
                                            </div>
                                        </div>
                                     </div>
                                     <div className="flex-1 relative bg-slate-50/50 dark:bg-transparent">
                                        <AIAssistant contextData={filteredData} inlineView={true} />
                                     </div>
                                </div>
                            )}
                        </ErrorBoundary>
                    </div>
                </div>
            </div>
        </div>
      </div>

      <ImportModal isOpen={isImportOpen} onClose={() => setIsImportOpen(false)} onImport={handleImportData} />
      <ProfileModal isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} user={currentUser} onSave={handleUpdateUserProfile} />
      <AdminModal isOpen={isAdminOpen} onClose={() => setIsAdminOpen(false)} />

      {activeView !== 'ai' && <AIAssistant contextData={filteredData} />}
    </div>
  );
};

const App: React.FC = () => (
  <LanguageProvider>
    <ThemeProvider>
      <AppContent />
    </ThemeProvider>
  </LanguageProvider>
);

export default App;

