            avgDensity: densityCount ? (densitySum / densityCount).toFixed(3) : '-',
            avgMfr: mfrCount ? (mfrSum / mfrCount).toFixed(2) : '-',
            refCoverage: totalPropsCount > 0 ? ((totalPropsWithRefs / totalPropsCount) * 100).toFixed(1) : '0'
        };
    }, [data]);

    const Card = ({ icon: Icon, color, label, value, sub, delay }: any) => (
        <div className={`relative overflow-hidden bg-white/80 dark:bg-slate-800/60 backdrop-blur-md rounded-[1.5rem] p-5 shadow-sm border border-white/50 dark:border-slate-700/50 transition-all hover:-translate-y-1 hover:shadow-xl group animate-in fade-in slide-in-from-bottom-4 duration-700`} style={{ animationDelay: delay }}>
            <div className={`absolute -top-4 -right-4 p-8 opacity-[0.05] dark:opacity-[0.08] group-hover:scale-110 group-hover:rotate-6 transition-transform duration-500`}>
                <Icon size={100} />
            </div>
            <div className="relative z-10 flex flex-col h-full justify-between">
                <div className="flex items-center gap-3 mb-3">
                    <div className={`w-9 h-9 rounded-xl flex items-center justify-center text-white shadow-lg ${color} ring-2 ring-white/20 dark:ring-black/20`}>
                        <Icon size={18} />
                    </div>
                    <span className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">{label}</span>
                </div>
                <div>
                    <div className="text-2xl font-black text-slate-800 dark:text-slate-100 tracking-tighter">{value}</div>
                    <div className="text-[10px] font-bold text-slate-400 mt-0.5">{sub}</div>
                </div>
            </div>
        </div>
    );

    return (
        <div className="grid grid-cols-2 lg:grid-cols-4 xl:grid-cols-5 gap-4 mb-6">
            <Card icon={Database} color="bg-gradient-to-br from-indigo-500 to-violet-600" label={t('total')} value={stats.count} sub={tProp('牌号')} delay="0ms" />
            <Card icon={Factory} color="bg-gradient-to-br from-blue-500 to-cyan-600" label={t('manufacturers')} value={stats.manufacturers} sub="Active Entities" delay="75ms" />
            <Card icon={FlaskConical} color="bg-gradient-to-br from-emerald-500 to-teal-600" label={`${t('avg')} ${tProp('密度')}`} value={stats.avgDensity} sub="g/cm³" delay="150ms" />
            <Card icon={TrendingUp} color="bg-gradient-to-br from-amber-500 to-orange-600" label={`${t('avg')} MFR`} value={stats.avgMfr} sub="g/10min" delay="225ms" />

            <div className="hidden xl:flex relative overflow-hidden bg-slate-900 dark:bg-emerald-950/40 rounded-[1.5rem] p-5 shadow-lg border border-slate-800 dark:border-emerald-900/50 group animate-in fade-in slide-in-from-bottom-4 duration-700" style={{ animationDelay: '300ms' }}>
                <div className="absolute inset-0 bg-gradient-to-br from-emerald-600/10 to-transparent"></div>
                <div className="relative z-10 w-full flex flex-col justify-between">
                    <div className="flex items-center justify-between">
                        <div className="p-1.5 bg-emerald-500/10 rounded-lg text-emerald-400 border border-emerald-500/20"><ShieldCheck size={16} /></div>
                        <span className="text-[9px] font-black text-emerald-500/60 uppercase tracking-widest">Confidence</span>
                    </div>
                    <div>
                        <div className="flex items-baseline gap-1">
                            <span className="text-3xl font-black text-white tracking-tighter">{stats.refCoverage}<span className="text-lg text-emerald-500/60">%</span></span>
                        </div>
                        <div className="w-full h-1 bg-slate-800 rounded-full mt-3 overflow-hidden">
                            <div className="h-full bg-emerald-500 rounded-full transition-all duration-1000 group-hover:shadow-[0_0_10px_rgba(16,185,129,0.5)]" style={{ width: `${stats.refCoverage}%` }}></div>
