import React, { useState, useMemo, useEffect } from 'react';
import { Category } from '../types';
import { ChevronRight, LayoutGrid, Search, X } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

interface TreeSidebarProps {
  categories: Category[];
  selectedCategoryId: string | null;
  onSelectCategory: (id: string | null) => void;
  totalCount?: number;
}

const TreeNode: React.FC<{
  category: Category;
  selectedId: string | null;
  onSelect: (id: string) => void;
  depth: number;
  forceExpand?: boolean;
}> = ({ category, selectedId, onSelect, depth, forceExpand = false }) => {
  const [isExpanded, setIsExpanded] = useState(depth < 1); 
  const hasChildren = category.children && category.children.length > 0;
  const isSelected = selectedId === category.id;
  const { language } = useLanguage();

  useEffect(() => { if (forceExpand) setIsExpanded(true); }, [forceExpand]);

  const displayOpen = isExpanded || forceExpand;

  return (
    <div className="select-none my-1">
      <div
        onClick={(e) => {
            e.stopPropagation();
            if(hasChildren) setIsExpanded(!isExpanded);
            onSelect(category.id);
        }}
        className={`
          flex items-center px-4 py-3 cursor-pointer text-sm transition-all duration-300 mx-2 rounded-[1rem] relative overflow-hidden group active:scale-[0.98]
          ${isSelected 
            ? 'bg-slate-900 dark:bg-white text-white dark:text-slate-900 font-bold shadow-lg shadow-slate-200/50 dark:shadow-black/30' 
            : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 hover:text-slate-900 dark:hover:text-slate-200'}
        `}
        style={{ paddingLeft: `${depth * 16 + 16}px` }}
      >
        <div className={`mr-2.5 transition-transform duration-300 ${displayOpen && hasChildren ? 'rotate-90' : ''}`}>
            {hasChildren && (
                <ChevronRight size={14} className={isSelected ? 'text-white/70 dark:text-slate-900/70' : 'text-slate-400'} />
            )}
        </div>
        <span className="truncate relative z-10 flex-1 tracking-wide">{language === 'en' && category.nameEn ? category.nameEn : category.name}</span>
        {isSelected && <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 mr-1 animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.8)]"></div>}
      </div>

      {/* Smooth Collapse Animation */}
      <div 
        className={`overflow-hidden transition-all duration-300 ease-in-out ${displayOpen ? 'max-h-[500px] opacity-100' : 'max-h-0 opacity-0'}`}
      >
        <div className="relative ml-5 pl-2 border-l border-slate-200/50 dark:border-slate-700/50 my-1">
          {hasChildren && category.children!.map((child) => (
            <TreeNode
              key={child.id}
              category={child}
              selectedId={selectedId}
              onSelect={onSelect}
              depth={depth + 1}
              forceExpand={forceExpand}
            />
          ))}
        </div>
      </div>
    </div>
  );
};

export const TreeSidebar: React.FC<TreeSidebarProps> = ({ categories, selectedCategoryId, onSelectCategory, totalCount = 0 }) => {
  const { t, language } = useLanguage();
  const [searchTerm, setSearchTerm] = useState('');

  const filterCategories = (cats: Category[], term: string): Category[] => {
    return cats.reduce<Category[]>((acc, cat) => {
        const name = language === 'en' && cat.nameEn ? cat.nameEn : cat.name;
        const matches = name.toLowerCase().includes(term.toLowerCase());
        let filteredChildren: Category[] = [];
        if (cat.children) filteredChildren = filterCategories(cat.children, term);
        if (matches || filteredChildren.length > 0) acc.push({ ...cat, children: filteredChildren });
        return acc;
    }, []);
  };

  const displayedCategories = useMemo(() => searchTerm.trim() ? filterCategories(categories, searchTerm) : categories, [categories, searchTerm, language]);

  return (
    <div className="flex flex-col h-full">
      <div className="p-5 pb-2 shrink-0">
        {/* Header */}
        <div 
            className={`
              flex items-center justify-between px-4 py-4 rounded-[1.25rem] cursor-pointer transition-all duration-300 mb-4 border group active:scale-[0.98]
              ${!selectedCategoryId 
                ? 'bg-gradient-to-br from-emerald-500 to-teal-600 text-white shadow-xl shadow-emerald-500/20 border-transparent' 
                : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 hover:border-emerald-500/50 hover:shadow-md'
              }
            `}
            onClick={() => onSelectCategory(null)}
        >
            <div className="flex items-center gap-3">
                <LayoutGrid size={18} />
                <span className="font-bold text-sm tracking-wide">{t('allProducts')}</span>
            </div>
            <span className={`px-2.5 py-1 rounded-lg text-[10px] font-black ${!selectedCategoryId ? 'bg-white/20' : 'bg-slate-100 dark:bg-slate-700 text-slate-500'}`}>{totalCount}</span>
        </div>

        {/* Search */}
        <div className="relative group mb-2">
             <Search className="absolute left-4 top-3 text-slate-400 group-focus-within:text-emerald-500 transition-colors" size={16} />
             <input 
                type="text" 
                placeholder={t('searchCategories')} 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-11 pr-8 py-3 bg-slate-50/80 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700 rounded-2xl text-sm font-medium focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all placeholder:text-slate-400"
             />
             {searchTerm && <button onClick={() => setSearchTerm('')} className="absolute right-3 top-3 text-slate-400 hover:text-slate-600"><X size={14} /></button>}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-2 custom-scrollbar pb-6 space-y-1">
        {displayedCategories.length > 0 ? (
            displayedCategories.map((cat) => (
              <TreeNode key={cat.id} category={cat} selectedId={selectedCategoryId} onSelect={onSelectCategory} depth={0} forceExpand={!!searchTerm} />
            ))
        ) : (
            <div className="text-center py-12 text-xs text-slate-400 italic">No matching categories</div>
        )}
      </div>
    </div>
  );
};

