          )}

          <div className="pt-6 border-t border-slate-100 dark:border-slate-800 grid grid-cols-2 gap-3 pb-4">
            <button onClick={() => handleDownload('json')} className="flex items-center justify-center gap-2 p-3 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-xl text-[10px] font-bold text-slate-600 dark:text-slate-300 transition-colors uppercase tracking-wider"><FileJson size={14} /> JSON DATA</button>
            <button onClick={() => handleDownload('png')} disabled={isExporting} className="flex items-center justify-center gap-2 p-3 bg-slate-900 dark:bg-emerald-600 hover:bg-slate-800 dark:hover:bg-emerald-500 disabled:opacity-70 text-white rounded-xl text-[10px] font-bold transition-all uppercase tracking-wider shadow-lg shadow-slate-900/20 dark:shadow-emerald-500/20">{isExporting ? <Loader2 size={14} className="animate-spin" /> : <ImageIcon size={14} />} EXPORT IMAGE</button>
          </div>
        </div>
      </div>

      {/* Chart Canvas Area */}
      <div className="flex-1 flex flex-col bg-white/50 dark:bg-slate-900/50 backdrop-blur-xl border border-slate-200 dark:border-slate-800 rounded-[2rem] relative min-h-[500px] shadow-2xl shadow-slate-200/50 dark:shadow-black/20 overflow-hidden">

        {/* Floating Toolbar */}
        <div className="absolute top-6 right-6 z-30 flex gap-2">
             {!showConfig && <button onClick={() => setShowConfig(true)} className="p-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-slate-500 hover:text-emerald-500 shadow-xl transition-all hover:scale-105 active:scale-95 no-capture group"><Settings size={20} className="group-hover:rotate-90 transition-transform duration-500" /></button>}
            <button onClick={() => handleDownload('png')} disabled={isExporting} title="Snapshot Export" className="p-3 bg-emerald-600 text-white rounded-2xl shadow-xl shadow-emerald-500/30 hover:bg-emerald-700 active:scale-95 transition-all disabled:bg-slate-300 dark:disabled:bg-slate-700 no-capture hover:scale-105">{isExporting ? <Loader2 size={20} className="animate-spin" /> : <Camera size={20} />}</button>
        </div>

        <div className="flex-1 p-6 md:p-8 flex flex-col min-h-0" ref={chartRef}>
            <div className="mb-6 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
               <div className="flex flex-col">
                   <h2 className="text-xl md:text-2xl font-black text-slate-800 dark:text-white flex items-center gap-3 tracking-tight">
                      {chartType === 'bar' ? <BarChart2 size={24} className="text-emerald-500" /> : <ScatterIcon size={24} className="text-emerald-500" />}
                      <span className="bg-clip-text text-transparent bg-gradient-to-r from-slate-800 to-slate-500 dark:from-white dark:to-slate-400">
                        {getLabelWithUnit(yAxisKey)} <span className="text-slate-300 mx-1">vs</span> {chartType === 'bar' ? tProp('牌号') : getLabelWithUnit(xAxisKey)}
                      </span>
                   </h2>
                   <p className="text-xs font-medium text-slate-400 mt-1 pl-9 uppercase tracking-widest">{t('analysis')} Visualization</p>
               </div>

               <div className="flex items-center gap-2 pr-24 md:pr-0">
                    <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest bg-slate-100 dark:bg-slate-800 px-3 py-1 rounded-full">{t('showing')}</span>
                    <div className="flex items-center gap-1.5 px-4 py-1.5 bg-slate-900 dark:bg-emerald-600 text-white rounded-full shadow-lg shadow-slate-900/10 dark:shadow-emerald-500/20">
                        <span className="text-sm font-black">{visibleChartData.length}</span>
                        <span className="text-[10px] opacity-60 font-bold">/</span>
                        <span className="text-xs font-bold opacity-80">{data.length}</span>
                    </div>
               </div>
            </div>

            <div className="flex-1 w-full min-h-0 relative rounded-3xl overflow-hidden bg-white/40 dark:bg-slate-950/20 border border-slate-100/50 dark:border-slate-800/50">
                {visibleChartData.length === 0 && (
                    <div className="absolute inset-0 flex flex-col items-center justify-center bg-white/60 dark:bg-slate-950/60 backdrop-blur-sm z-40">
                        <div className="p-8 bg-white dark:bg-slate-900 rounded-[2rem] shadow-2xl border border-slate-200 dark:border-slate-800 flex flex-col items-center gap-4 animate-in zoom-in-95 max-w-sm text-center">
                            <div className="w-20 h-20 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center mb-2"><ListFilter size={40} className="text-slate-300 dark:text-slate-600" /></div>
                            <div><p className="text-xl font-black text-slate-800 dark:text-white mb-2">No Matching Data</p><p className="text-sm text-slate-500 leading-relaxed font-medium">Your filters match 0 records. Try resetting filters or showing hidden groups.</p></div>
                            <div className="flex gap-3 w-full mt-2"><button onClick={clearAllFilters} className="flex-1 px-4 py-3 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300 text-xs font-bold rounded-xl transition-all uppercase tracking-wide">Reset Filters</button><button onClick={() => setAllGroupsVisibility(true)} className="flex-1 px-4 py-3 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold rounded-xl shadow-lg shadow-emerald-500/20 transition-all active:scale-95 uppercase tracking-wide">Show All</button></div>
                        </div>
                    </div>
                )}

                <ResponsiveContainer width="100%" height="100%">
                    {chartType === 'bar' ? (
                        <BarChart data={visibleChartData} margin={{ top: 20, right: 30, left: 20, bottom: 60 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={gridColor} strokeWidth={1} />
                            <XAxis dataKey="gradeName" angle={-45} textAnchor="end" interval={0} height={80} fontSize={10} stroke={axisColor} tick={{ fill: axisColor, fontWeight: 600 }} tickLine={{ stroke: axisColor }} padding={{ left: 20, right: 20 }} />
                            <YAxis fontSize={10} stroke={axisColor} tick={{ fill: axisColor, fontWeight: 600 }} tickLine={{ stroke: axisColor }} domain={['auto', 'auto']} label={{ value: getLabelWithUnit(yAxisKey), angle: -90, position: 'insideLeft', offset: 0, fontSize: 10, fill: axisColor, fontWeight: 700 }} padding={{ top: 20, bottom: 0 }} />
                            <Tooltip cursor={{ fill: theme === 'dark' ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.03)' }} content={<CustomTooltipContent />} />
                            {groupByKey && <Legend verticalAlign="top" content={RenderCustomLegend} wrapperStyle={{ top: -10 }} />}
                            <Bar dataKey={yAxisKey} radius={[6, 6, 0, 0]} animationDuration={1000} minPointSize={2}>
                                {visibleChartData.map((entry, index) => {
                                    const group = String(entry[groupByKey] || 'Unknown');
                                    const isHighlighted = highlightedGroup === null || highlightedGroup === group;
                                    return <Cell key={`cell-${index}`} fill={groupByKey ? groupColors[group] : DEFAULT_PALETTE[index % DEFAULT_PALETTE.length]} fillOpacity={isHighlighted ? 1 : 0.2} />;
                                })}
                            </Bar>
                        </BarChart>
                    ) : (
                        <ComposedChart margin={{ top: 30, right: 30, bottom: 30, left: 30 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke={gridColor} strokeWidth={1} />
                            <XAxis 
                                type="number" 
                                dataKey={xAxisKey} 
                                name={tProp(xAxisKey)} 
                                fontSize={10} 
                                domain={[xMin === '' ? 'auto' : xMin, xMax === '' ? 'auto' : xMax]} 
                                stroke={axisColor} 
                                tick={{ fill: axisColor, fontWeight: 600 }}
                                tickLine={{ stroke: axisColor }}
                                label={{ value: getLabelWithUnit(xAxisKey), position: 'bottom', offset: 0, fontSize: 11, fill: axisColor, fontWeight: 700 }}
                                padding={{ left: 20, right: 20 }}
                            />
                            <YAxis 
                                type="number" 
                                dataKey={yAxisKey} 
                                name={tProp(yAxisKey)} 
                                fontSize={10} 
                                domain={[yMin === '' ? 'auto' : yMin, yMax === '' ? 'auto' : yMax]} 
                                stroke={axisColor}
                                tick={{ fill: axisColor, fontWeight: 600 }}
                                tickLine={{ stroke: axisColor }}
                                label={{ value: getLabelWithUnit(yAxisKey), angle: -90, position: 'insideLeft', offset: 10, fontSize: 11, fill: axisColor, fontWeight: 700 }} 
                                padding={{ top: 20, bottom: 20 }}
                            />
                            <ZAxis range={[100, 500]} />
                            <Tooltip cursor={{ strokeDasharray: '3 3', stroke: axisColor, strokeWidth: 1 }} content={<CustomTooltipContent />} />
                            {groupByKey && <Legend verticalAlign="top" content={RenderCustomLegend} wrapperStyle={{ top: -10 }} />}

                            <Scatter name="Resin Samples" data={visibleChartData} animationDuration={1000} isAnimationActive={true}>
                                {visibleChartData.map((entry, index) => {
                                    const group = String(entry[groupByKey] || 'Unknown');
                                    const isHighlighted = highlightedGroup === null || highlightedGroup === group;
                                    const fillColor = groupByKey ? groupColors[group] : '#10b981';
                                    return (
                                        <Cell 
                                            key={`cell-${index}`} 
                                            fill={fillColor} 
                                            fillOpacity={isHighlighted ? 0.9 : 0.2} 
                                            stroke={scatterStroke}
                                            strokeWidth={1.5}
                                            strokeOpacity={isHighlighted ? 0.8 : 0.1}
                                        />
                                    );
                                })}
                            </Scatter>

                            {/* Trendline - ensured to render on top */}
                            {trendlineSegment && (
                                <Line 
                                    type="monotone" 
                                    data={trendlineSegment} 
                                    dataKey={yAxisKey} 
                                    stroke={trendlineColor} 
                                    strokeWidth={trendlineWidth} 
                                    strokeDasharray={dashArray} 
                                    dot={{ r: 4, fill: trendlineColor, strokeWidth: 2, stroke: '#fff' }} 
                                    activeDot={{ r: 6, strokeWidth: 0 }} 
                                    isAnimationActive={false}
                                    legendType="none"
                                    strokeLinecap="round"
                                />
                            )}
                        </ComposedChart>
                    )}
                </ResponsiveContainer>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  ReferenceLine,
  Cell,
  LabelList,
  Line,
  ComposedChart,
  ZAxis
} from 'recharts';
import { Settings, Download, ChevronUp, BarChart2, ScatterChart as ScatterIcon, TrendingUp, Palette, FileJson, Image as ImageIcon, RotateCcw, LayoutDashboard, Pipette, Maximize, X, Filter, Plus, Trash2, Eye, EyeOff, Info, RefreshCw, Palette as PaletteIcon, Layers, Factory, CheckCircle2, Wand2, Hash, ArrowRight, Binary, ListFilter, Eraser, PlusCircle, Target, MousePointer2, Search, Camera, Loader2, GripVertical, Repeat, Sliders, AlertTriangle } from 'lucide-react';
import { Product, PropertyValue } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

interface PlotFilter {
  id: string;
  key: string;
  operator: '>' | '<' | '>=' | '<=' | 'between';
  value: number | '';
  value2: number | '';
}

const DEFAULT_PALETTE = [
  '#10b981', // Emerald
  '#3b82f6', // Blue
  '#f59e0b', // Amber
  '#ef4444', // Red
  '#8b5cf6', // Violet
  '#ec4899', // Pink
  '#06b6d4', // Cyan
  '#84cc16', // Lime
  '#f97316', // Orange
  '#6366f1', // Indigo
];

const COLOR_SCHEMES = [
  { id: 'emerald', name: 'Resin Classic', colors: ['#10b981', '#059669', '#047857', '#065f46', '#064e3b', '#34d399'] },
  { id: 'vibrant', name: 'Scientific Vibrant', colors: ['#6366f1', '#8b5cf6', '#ec4899', '#f43f5e', '#f97316', '#eab308'] },
  { id: 'ocean', name: 'Deep Ocean', colors: ['#0c4a6e', '#075985', '#0369a1', '#0284c7', '#0ea5e9', '#38bdf8'] },
  { id: 'pastel', name: 'Soft Material', colors: ['#a7f3d0', '#bfdbfe', '#fde68a', '#fecaca', '#ddd6fe', '#fbcfe8'] },
  { id: 'industrial', name: 'Industrial Gray', colors: ['#475569', '#64748b', '#94a3b8', '#cbd5e1', '#e2e8f0', '#1e293b'] }
];

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const { t, tProp } = useLanguage();
  const { theme } = useTheme();
  const chartRef = useRef<HTMLDivElement>(null);

  const [showConfig, setShowConfig] = useState(true);
  const [isExporting, setIsExporting] = useState(false);
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('gradeName');
  const [yAxisKey, setYAxisKey] = useState<string>('');
  const [legendSearch, setLegendSearch] = useState('');
  const [groupSettingsSearch, setGroupSettingsSearch] = useState('');

  const [xMin, setXMin] = useState<number | ''>('');
  const [xMax, setXMax] = useState<number | ''>('');
  const [yMin, setYMin] = useState<number | ''>('');
  const [yMax, setYMax] = useState<number | ''>('');

  const [plotFilters, setPlotFilters] = useState<PlotFilter[]>([]);

  const [showTrendline, setShowTrendline] = useState(false);
  const [trendlineColor, setTrendlineColor] = useState('#ef4444');
  const [trendlineWidth, setTrendlineWidth] = useState(3);
  const [trendlineStyle, setTrendlineStyle] = useState<'solid' | 'dashed' | 'dotted'>('solid');

  const [groupByKey, setGroupByKey] = useState<string>('');
  const [groupColors, setGroupColors] = useState<Record<string, string>>({});
  const [hiddenGroups, setHiddenGroups] = useState<Set<string>>(new Set());
  const [highlightedGroup, setHighlightedGroup] = useState<string | null>(null);
  const [activeSchemeId, setActiveSchemeId] = useState('emerald');

  const numericKeys = useMemo(() => {
     const keys = new Set<string>();
     data.forEach(p => {
        (Object.entries(p.properties) as [string, PropertyValue][]).forEach(([k, v]) => {
           if (typeof v.value === 'number' || (!isNaN(Number(v.value)) && v.value !== '')) {
               keys.add(k);
           }
        });
     });
     return Array.from(keys).sort();
  }, [data]);

  const propertyStats = useMemo(() => {
    const stats: Record<string, { min: number; max: number; unit?: string }> = {};
    numericKeys.forEach(key => {
        let min = Infinity;
        let max = -Infinity;
        let unit: string | undefined;

        data.forEach(p => {
            const prop = p.properties[key];
            const val = Number(prop?.value);
            if (!isNaN(val) && prop?.value !== '' && prop?.value !== undefined) {
                if (val < min) min = val;
                if (val > max) max = val;
                if (!unit && prop.unit) unit = prop.unit;
            }
        });
        if (min !== Infinity) {
            stats[key] = { min, max, unit };
        }
    });
    return stats;
  }, [data, numericKeys]);

  const categoricalKeys = useMemo(() => {
    const keys = new Set<string>(['manufacturer']);
    data.forEach(p => {
        (Object.entries(p.properties) as [string, PropertyValue][]).forEach(([k, v]) => {
            if (typeof v.value === 'string' && isNaN(Number(v.value))) {
                keys.add(k);
            }
        });
    });
    return Array.from(keys).sort();
  }, [data]);

  // Initial Axis Setup
  useEffect(() => {
      if (!yAxisKey && numericKeys.length > 0) {
          const preferred = ['密度', '熔体质量流动速率', '拉伸屈服应力'].find(k => numericKeys.includes(k));
          setYAxisKey(preferred || numericKeys[0]);
      }
  }, [numericKeys, yAxisKey]);

  // Enforce Numeric X-Axis for Scatter
  useEffect(() => {
    if (chartType === 'scatter') {
        if (!numericKeys.includes(xAxisKey)) {
            // Find a different key than yAxisKey if possible
            const nextKey = numericKeys.find(k => k !== yAxisKey) || numericKeys[0] || '';
            setXAxisKey(nextKey);
        }
    }
  }, [chartType, numericKeys, xAxisKey, yAxisKey]);

  // Reset View Config on major changes
  useEffect(() => {
    setXMin(''); setXMax(''); setYMin(''); setYMax('');
    setHiddenGroups(new Set());
    setHighlightedGroup(null);
    setLegendSearch('');
  }, [chartType, groupByKey]); // Removed axes from dep array to prevent annoying resets

  const filteredBaseData = useMemo(() => {
    return data.filter(product => {
        return plotFilters.every(f => {
            if (!f.key || f.value === '') return true;
            const prop = product.properties[f.key] as PropertyValue;
            if (!prop || prop.value === undefined || prop.value === null || prop.value === '') return false;
            const val = Number(prop.value);
            if (isNaN(val)) return false;

            const v1 = Number(f.value);
            const v2 = f.value2 !== '' ? Number(f.value2) : Infinity;

            switch (f.operator) {
                case '>': return val > v1;
                case '<': return val < v1;
                case '>=': return val >= v1;
                case '<=': return val <= v1;
                case 'between': return val >= v1 && val <= v2;
                default: return true;
            }
        });
    });
  }, [data, plotFilters]);

  const chartData = useMemo(() => {
    return filteredBaseData.map(p => {
        const item: any = {
            id: p.id,
            gradeName: p.gradeName,
            manufacturer: p.manufacturer,
            tooltipTitle: `${p.manufacturer} - ${p.gradeName}`
        };
        (Object.entries(p.properties) as [string, PropertyValue][]).forEach(([k, v]) => {
            const num = Number(v.value);
            item[k] = !isNaN(num) && v.value !== '' ? num : v.value;
        });
        return item;
    });
  }, [filteredBaseData]);

  const uniqueGroups = useMemo(() => {
    if (!groupByKey) return [];
    const groups = new Set<string>();
    chartData.forEach((item: any) => {
        groups.add(String(item[groupByKey] || 'Unknown'));
    });
    return Array.from(groups).sort();
  }, [groupByKey, chartData]);

  const visibleChartData = useMemo(() => {
    if (!groupByKey) return chartData;
    return chartData.filter(d => !hiddenGroups.has(String(d[groupByKey] || 'Unknown')));
  }, [chartData, groupByKey, hiddenGroups]);

  const trendlineSegment = useMemo(() => {
    if (!showTrendline || chartType !== 'scatter') return null;

    // Only use visible data
    const validPoints = visibleChartData.filter(d => 
        typeof d[xAxisKey] === 'number' && typeof d[yAxisKey] === 'number'
    );

    if (validPoints.length < 2) return null;

    const n = validPoints.length;
    let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
    let minX = Infinity, maxX = -Infinity;

    validPoints.forEach(p => {
        const x = p[xAxisKey];
        const y = p[yAxisKey];
        sumX += x; sumY += y; sumXY += x * y; sumX2 += x * x;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
    });

    const denominator = n * sumX2 - sumX * sumX;
    if (denominator === 0) return null; // Vertical line

    const slope = (n * sumXY - sumX * sumY) / denominator;
    const intercept = (sumY - slope * sumX) / n;

    // Extend line slightly
    const range = maxX - minX;
    const padding = range * 0.05; // 5% padding

    return [
        { [xAxisKey]: minX - padding, [yAxisKey]: slope * (minX - padding) + intercept, isTrend: true },
        { [xAxisKey]: maxX + padding, [yAxisKey]: slope * (maxX + padding) + intercept, isTrend: true }
    ];
  }, [visibleChartData, xAxisKey, yAxisKey, showTrendline, chartType]);

  const dashArray = useMemo(() => {
    if (trendlineStyle === 'dashed') return '8 8';
    if (trendlineStyle === 'dotted') return '3 3';
    return '0';
  }, [trendlineStyle]);

  useEffect(() => {
    if (uniqueGroups.length > 0) {
        setGroupColors(prev => {
            const next = { ...prev };
            const currentPalette = COLOR_SCHEMES.find(s => s.id === activeSchemeId)?.colors || DEFAULT_PALETTE;
            uniqueGroups.forEach((group, index) => {
                if (!next[group]) next[group] = currentPalette[index % currentPalette.length];
            });
            return next;
        });
    }
  }, [uniqueGroups, activeSchemeId]);

  const applyScheme = (schemeId: string) => {
    setActiveSchemeId(schemeId);
    const scheme = COLOR_SCHEMES.find(s => s.id === schemeId);
    if (!scheme) return;

    setGroupColors(prev => {
        const next = { ...prev };
        uniqueGroups.forEach((group, index) => {
            next[group] = scheme.colors[index % scheme.colors.length];
        });
        return next;
    });
  };

  const shufflePalette = () => {
    const scheme = COLOR_SCHEMES.find(s => s.id === activeSchemeId)?.colors || DEFAULT_PALETTE;
    const shuffled = [...scheme].sort(() => Math.random() - 0.5);
    setGroupColors(prev => {
        const next = { ...prev };
        uniqueGroups.forEach((group, index) => {
            next[group] = shuffled[index % shuffled.length];
        });
        return next;
    });
  };

  const resetPalette = () => {
    applyScheme('emerald');
  };

  const toggleGroupVisibility = (group: string, isAltKey: boolean = false) => {
    if (isAltKey) {
        const others = uniqueGroups.filter(g => g !== group);
        setHiddenGroups(new Set(others));
    } else {
        setHiddenGroups(prev => {
          const next = new Set(prev);
          if (next.has(group)) next.delete(group);
          else next.add(group);
          return next;
        });
    }
  };

  const setAllGroupsVisibility = (visible: boolean) => {
    if (visible) setHiddenGroups(new Set());
    else setHiddenGroups(new Set(uniqueGroups));
  };

  const handleDownload = async (type: 'json' | 'png') => {
    if (type === 'json') {
        const blob = new Blob([JSON.stringify(visibleChartData, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = `resindb_data_${Date.now()}.json`; a.click();
    } else if (type === 'png' && chartRef.current) {
        setIsExporting(true);
        try {
          await new Promise(resolve => setTimeout(resolve, 100));

          const canvas = await html2canvas(chartRef.current, { 
            backgroundColor: theme === 'dark' ? '#0f172a' : '#ffffff',
            scale: 2, 
            logging: false,
            useCORS: true, 
            ignoreElements: (element) => {
                return element.classList.contains('no-capture');
            }
          });
          const a = document.createElement('a');
          a.href = canvas.toDataURL('image/png', 1.0); 
          a.download = `resindb_chart_${new Date().toISOString().slice(0,10)}.png`; 
          a.click();
        } catch (err) {
          console.error("Export failed:", err);
        } finally {
          setIsExporting(false);
        }
    }
  };

  // Filter Logic
  const addPlotFilter = () => {
    const newFilter: PlotFilter = {
        id: Date.now().toString(),
        key: numericKeys[0] || '',
        operator: '>=',
        value: '',
        value2: ''
    };
    setPlotFilters([...plotFilters, newFilter]);
  };

  const updatePlotFilter = (id: string, updates: Partial<PlotFilter>) => {
    setPlotFilters(prev => prev.map(f => f.id === id ? { ...f, ...updates } : f));
  };

  const removePlotFilter = (id: string) => {
    setPlotFilters(prev => prev.filter(f => f.id !== id));
  };

  const clearAllFilters = () => {
      setPlotFilters([]);
  };

  const getLabelWithUnit = (key: string) => {
      const label = tProp(key);
      const unit = propertyStats[key]?.unit;
      return unit ? `${label} (${unit})` : label;
  };

  const CustomTooltipContent = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const d = payload[0].payload;
      if (d.isTrend) return (
          <div className="px-3 py-2 bg-slate-800 text-white text-xs font-bold rounded-lg shadow-xl border border-slate-700">
              Trendline Fit
          </div>
      );
      const product = data.find(p => p.id === d.id);
      if (!product) return null;

      const additionalProps = (Object.entries(product.properties) as [string, PropertyValue][])
        .filter(([k]) => k !== xAxisKey && k !== yAxisKey && k !== groupByKey)
        .sort((a, b) => {
           const commonAttributes = ['密度', 'Density', '熔体流动速率', 'MFR', '拉伸强度', 'Tensile Strength', '应用', 'Application', '类型', 'Type'];
           const aIsCommon = commonAttributes.includes(a[0]) ? 1 : 0;
           const bIsCommon = commonAttributes.includes(b[0]) ? 1 : 0;
           return bIsCommon - aIsCommon;
        })
        .slice(0, 4);

      const formatPropValue = (key: string) => {
          const prop = product.properties[key] as PropertyValue;
          const unit = prop?.unit || propertyStats[key]?.unit;

          if (!prop) return <span className="text-sm font-black text-slate-800 dark:text-slate-100">{d[key]}</span>;
          return (
            <div className="flex items-baseline gap-1">
              <span className="text-sm font-mono font-black">{prop.value}</span>
              {unit && (
                <span className="text-[10px] opacity-60 font-sans font-medium">
                  {unit}
                </span>
              )}
            </div>
          );
      };

      return (
        <div className="p-4 bg-white/95 dark:bg-slate-900/95 backdrop-blur-xl border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl min-w-[280px] animate-in fade-in zoom-in-95 duration-200 border-l-4 z-50" style={{ borderLeftColor: groupByKey ? groupColors[String(d[groupByKey])] : '#10b981' }}>
          <div className="flex items-center justify-between gap-4 mb-1">
            <p className="font-bold text-slate-800 dark:text-white truncate text-sm">{product.gradeName}</p>
            {groupByKey && d[groupByKey] && (
               <span className="text-[9px] px-2 py-0.5 rounded-full text-white font-bold whitespace-nowrap" style={{ backgroundColor: groupColors[String(d[groupByKey])] }}>
                  {d[groupByKey]}
               </span>
            )}
          </div>
          <p className="text-[10px] text-slate-500 dark:text-slate-400 mb-3 uppercase tracking-widest font-bold flex items-center gap-1.5">
            <Factory size={10} className="text-emerald-500" /> {product.manufacturer}
          </p>

          <div className="space-y-2 pt-2 border-t border-slate-100 dark:border-slate-800">
             <div className="flex justify-between gap-4 items-center">
                <span className="text-xs text-slate-500 dark:text-slate-400 font-bold">{tProp(yAxisKey)}</span>
                <div className="text-emerald-600 dark:text-emerald-400">
                    {formatPropValue(yAxisKey)}
                </div>
             </div>
             {chartType === 'scatter' && xAxisKey !== 'gradeName' && (
               <div className="flex justify-between gap-4 items-center">
                  <span className="text-xs text-slate-500 dark:text-slate-400 font-bold">{tProp(xAxisKey)}</span>
                  <div className="text-blue-600 dark:text-blue-400">
                      {formatPropValue(xAxisKey)}
                  </div>
               </div>
             )}
          </div>

          {additionalProps.length > 0 && (
            <div className="mt-3 pt-3 border-t border-slate-100 dark:border-slate-800 space-y-1.5">
              <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1 flex items-center gap-1.5">
                <Info size={10} className="text-emerald-500" /> Details
              </p>
              {additionalProps.map(([key, prop]) => (
                <div key={key} className="text-[10px] flex justify-between gap-4 text-slate-600 dark:text-slate-300 items-baseline">
                  <span className="opacity-70 truncate max-w-[140px]">{tProp(key)}</span>
                  <div className="font-bold whitespace-nowrap text-slate-800 dark:text-slate-100 font-mono">
                    {String(prop.value).length > 20 ? <span title={String(prop.value)}>{String(prop.value).substring(0, 20)}...</span> : prop.value}
                    {prop.unit && <span className="text-[8px] opacity-50 ml-1">{prop.unit}</span>}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      );
    }
    return null;
  };

  const RenderCustomLegend = (props: any) => {
    const { payload } = props;
    if (!payload || payload.length === 0) return null;

    const filteredPayload = payload.filter((entry: any) => 
        entry.value !== 'Trendline' && entry.value.toLowerCase().includes(legendSearch.toLowerCase())
    );

    const allVisible = hiddenGroups.size === 0;
    const noneVisible = hiddenGroups.size === uniqueGroups.length;
    const visibleCount = uniqueGroups.length - hiddenGroups.size;

    return (
      <div className="flex flex-col items-center mb-6 gap-3 animate-in fade-in duration-500 bg-white/60 dark:bg-slate-900/60 backdrop-blur-md border border-slate-200 dark:border-slate-800 rounded-[1.5rem] p-4 shadow-xl z-20 relative mx-4">
        <div className="flex flex-wrap items-center justify-between w-full gap-4 px-2">
            {/* Legend Stats & Controls */}
            <div className="flex items-center gap-3 bg-white dark:bg-slate-800 px-3 py-1.5 rounded-full border border-slate-200 dark:border-slate-700 shadow-sm transition-all">
                <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1.5">
                    <MousePointer2 size={10} className="text-emerald-500" />
                    Viewing <span className="text-emerald-600 dark:text-emerald-400">{visibleCount}</span> / <span className="text-slate-600 dark:text-slate-300">{uniqueGroups.length}</span>
                </span>
                <div className="w-px h-3 bg-slate-200 dark:bg-slate-700"></div>
                <div className="flex items-center gap-1">
                    <button 
                        type="button"
                        onClick={() => setAllGroupsVisibility(true)}
                        disabled={allVisible}
                        className={`px-2 py-1 rounded-md text-[9px] font-black uppercase tracking-tighter transition-colors ${allVisible ? 'text-slate-300 cursor-not-allowed' : 'text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-900/20'}`}
                    >
                        Show All
                    </button>
                    <button 
                        type="button"
                        onClick={() => setAllGroupsVisibility(false)}
                        disabled={noneVisible}
                        className={`px-2 py-1 rounded-md text-[9px] font-black uppercase tracking-tighter transition-colors ${noneVisible ? 'text-slate-300 cursor-not-allowed' : 'text-rose-600 hover:bg-rose-50 dark:hover:bg-rose-900/20'}`}
                    >
                        Hide All
                    </button>
                </div>
            </div>

            {/* Legend Search */}
            <div className="relative group/search max-w-[180px] flex-1 min-w-[120px]">
                <Search size={12} className="absolute left-2.5 top-2 text-slate-400 group-focus-within/search:text-emerald-500 transition-colors" />
                <input 
                    type="text"
                    placeholder={t('filterGroups')}
                    value={legendSearch}
                    onChange={(e) => setLegendSearch(e.target.value)}
                    className="w-full pl-8 pr-4 py-1.5 bg-white/80 dark:bg-slate-950/80 border border-slate-200 dark:border-slate-700 rounded-full text-[10px] font-bold outline-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 transition-all placeholder:text-slate-400"
                />
            </div>
        </div>

        {/* Legend Items Grid */}
        <div className="flex flex-wrap justify-center gap-2 px-1 max-h-28 overflow-y-auto custom-scrollbar w-full py-1">
            {filteredPayload.length > 0 ? (
                filteredPayload.map((entry: any, index: number) => {
                    const isHidden = hiddenGroups.has(entry.value);
                    const isHighlighted = highlightedGroup === entry.value;
                    const otherHighlighted = highlightedGroup !== null && highlightedGroup !== entry.value;

                    return (
                        <button 
                            type="button"
                            key={`item-${index}`} 
                            onClick={(e) => toggleGroupVisibility(entry.value, e.altKey)}
                            onMouseEnter={() => !isHidden && setHighlightedGroup(entry.value)}
                            onMouseLeave={() => setHighlightedGroup(null)}
                            title={`${entry.value}\n• Click: Toggle\n• Alt+Click: Isolate Group`}
                            className={`
                                flex items-center gap-2 px-2.5 py-1 rounded-lg border transition-all duration-200 relative group/item
                                ${isHidden 
                                    ? 'bg-slate-50 dark:bg-slate-800/30 border-slate-100 dark:border-slate-800 text-slate-300 dark:text-slate-600 grayscale' 
                                    : isHighlighted
                                      ? 'bg-emerald-50 dark:bg-emerald-900/30 border-emerald-200 dark:border-emerald-800 text-emerald-800 dark:text-emerald-100 scale-105 shadow-md z-10'
                                      : otherHighlighted
                                        ? 'bg-white dark:bg-slate-900 border-slate-100 dark:border-slate-800 opacity-40'
                                        : 'bg-white dark:bg-slate-900 border-slate-200 dark:border-slate-700 hover:border-emerald-300 dark:hover:border-emerald-700 text-slate-600 dark:text-slate-300 shadow-sm'
                                }
                            `}
                        >
                            <div className={`w-2.5 h-2.5 rounded-full shadow-sm ${isHidden ? 'bg-slate-300' : ''}`} style={{ backgroundColor: isHidden ? undefined : entry.color }}></div>
                            <span className="text-[10px] font-bold uppercase tracking-wide truncate max-w-[100px]">
                                {entry.value}
                            </span>
                            {isHighlighted && !isHidden && <Eye size={10} className="text-emerald-500 animate-pulse ml-1" />}
                        </button>
                    );
                })
            ) : (
                <div className="py-2 text-center w-full">
                    <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest italic">No groups match "{legendSearch}"</p>
                </div>
            )}
        </div>
      </div>
    );
  };

  // Color Constants for Themes (Updated for visibility)
  // Lighter grid in dark mode, darker in light mode for visibility
  const gridColor = theme === 'dark' ? '#475569' : '#cbd5e1'; 
  const axisColor = theme === 'dark' ? '#94a3b8' : '#64748b'; 
  const scatterStroke = theme === 'dark' ? '#0f172a' : '#ffffff'; 

  return (
    <div className="flex flex-col md:flex-row h-full gap-4 overflow-hidden">
      {/* Settings Panel */}
      <div className={`flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl transition-all duration-500 ease-out shrink-0 overflow-hidden shadow-xl ${showConfig ? 'w-full md:w-80 opacity-100 translate-x-0' : 'w-0 opacity-0 -translate-x-10 border-0 pointer-events-none'}`}>
        <div className="p-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50/80 dark:bg-slate-950/50 backdrop-blur-sm">
          <div className="flex items-center gap-2 font-black text-sm text-slate-800 dark:text-white uppercase tracking-widest">
            <Sliders size={16} className="text-emerald-500" />
            {t('chartConfig')}
          </div>
          <button onClick={() => setShowConfig(false)} className="md:hidden text-slate-400 hover:text-slate-600">
            <X size={20} />
