                        <div className="p-1.5 bg-emerald-500/10 rounded-lg text-emerald-400 border border-emerald-500/20"><ShieldCheck size={16} /></div>
                        <span className="text-[9px] font-black text-emerald-500/60 uppercase tracking-widest">Confidence</span>
                    </div>
                    <div>
                        <div className="flex items-baseline gap-1">
                            <span className="text-3xl font-black text-white tracking-tighter">{stats.refCoverage}<span className="text-lg text-emerald-500/60">%</span></span>
                        </div>
                        <div className="w-full h-1 bg-slate-800 rounded-full mt-3 overflow-hidden">
                            <div className="h-full bg-emerald-500 rounded-full transition-all duration-1000 group-hover:shadow-[0_0_10px_rgba(16,185,129,0.5)]" style={{ width: `${stats.refCoverage}%` }}></div>
