import React, { useState, useMemo, useEffect } from 'react';
import { Category } from '../types';
import { ChevronRight, LayoutGrid, Search, X, Layers } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

interface TreeSidebarProps {
  categories: Category[];
  selectedCategoryId: string | null;
  onSelectCategory: (id: string | null) => void;
  totalCount?: number;
  counts?: Record<string, number>;
}

const TreeNode: React.FC<{
  category: Category;
  selectedId: string | null;
  onSelect: (id: string) => void;
  depth: number;
  forceExpand?: boolean;
  count?: number;
}> = ({ category, selectedId, onSelect, depth, forceExpand = false, count = 0 }) => {
  const [isExpanded, setIsExpanded] = useState(depth < 1); 
  const hasChildren = category.children && category.children.length > 0;
  const isSelected = selectedId === category.id;
  const { language } = useLanguage();

  useEffect(() => { if (forceExpand) setIsExpanded(true); }, [forceExpand]);

  const displayOpen = isExpanded || forceExpand;

  return (
    <div className="select-none my-1">
      <div
        onClick={(e) => {
            e.stopPropagation();
            if(hasChildren) setIsExpanded(!isExpanded);
            onSelect(category.id);
        }}
        className={`
          flex items-center px-3 py-2.5 cursor-pointer text-sm transition-all duration-200 mx-2 rounded-xl relative overflow-hidden group active:scale-[0.98]
          ${isSelected 
            ? 'bg-slate-900 dark:bg-white text-white dark:text-slate-900 font-bold shadow-md' 
            : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 hover:text-slate-900 dark:hover:text-slate-200'}
        `}
        style={{ paddingLeft: `${depth * 12 + 12}px` }}
      >
        <div className={`mr-2 transition-transform duration-200 ${displayOpen && hasChildren ? 'rotate-90' : ''}`}>
            {hasChildren ? (
                <ChevronRight size={14} className={isSelected ? 'text-white/70 dark:text-slate-900/70' : 'text-slate-400'} />
            ) : (
                <div className="w-3.5" /> 
            )}
        </div>
        <span className="truncate relative z-10 flex-1 tracking-tight">{language === 'en' && category.nameEn ? category.nameEn : category.name}</span>

        {count > 0 && (
            <span className={`ml-2 px-1.5 py-0.5 rounded-md text-[9px] font-bold ${isSelected ? 'bg-white/20 text-white' : 'bg-slate-100 dark:bg-slate-700 text-slate-400 dark:text-slate-500 group-hover:bg-white dark:group-hover:bg-slate-600'}`}>
                {count}
            </span>
        )}

        {isSelected && <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 ml-1 animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.8)]"></div>}
      </div>

      {/* Smooth Collapse Animation */}
      <div 
        className={`overflow-hidden transition-all duration-300 ease-in-out ${displayOpen ? 'max-h-[800px] opacity-100' : 'max-h-0 opacity-0'}`}
      >
        <div className="relative ml-4 pl-2 border-l border-slate-200/50 dark:border-slate-700/50 my-0.5">
          {hasChildren && category.children!.map((child) => (
            <TreeNode
              key={child.id}
              category={child}
              selectedId={selectedId}
              onSelect={onSelect}
              depth={depth + 1}
              forceExpand={forceExpand}
              count={0} // Counts are passed down but children usually get their own count from the parent map if we passed the map. See fix below.
            />
          ))}
        </div>
      </div>
    </div>
  );
};

// Wrapper to pass counts map down recursively
const RecursiveTree: React.FC<{
    categories: Category[];
    selectedId: string | null;
    onSelect: (id: string) => void;
    depth: number;
    forceExpand: boolean;
    counts: Record<string, number>;
}> = ({ categories, selectedId, onSelect, depth, forceExpand, counts }) => {
    return (
        <>
            {categories.map(cat => (
                <TreeNodeWithChildren 
                    key={cat.id} 
                    category={cat} 
                    selectedId={selectedId} 
                    onSelect={onSelect} 
                    depth={depth} 
                    forceExpand={forceExpand}
                    counts={counts}
                />
            ))}
        </>
    )
}

const TreeNodeWithChildren: React.FC<{
  category: Category;
  selectedId: string | null;
  onSelect: (id: string) => void;
  depth: number;
  forceExpand?: boolean;
  counts: Record<string, number>;
}> = ({ category, selectedId, onSelect, depth, forceExpand = false, counts }) => {
  const [isExpanded, setIsExpanded] = useState(depth < 1); 
  const hasChildren = category.children && category.children.length > 0;
  const isSelected = selectedId === category.id;
  const { language } = useLanguage();

  useEffect(() => { if (forceExpand) setIsExpanded(true); }, [forceExpand]);

  const displayOpen = isExpanded || forceExpand;
  const count = counts[category.id] || 0;

  return (
    <div className="select-none my-1">
      <div
        onClick={(e) => {
            e.stopPropagation();
            if(hasChildren) setIsExpanded(!isExpanded);
            onSelect(category.id);
        }}
        className={`
          flex items-center px-3 py-2.5 cursor-pointer text-sm transition-all duration-200 mx-2 rounded-xl relative overflow-hidden group active:scale-[0.98]
          ${isSelected 
            ? 'bg-slate-900 dark:bg-white text-white dark:text-slate-900 font-bold shadow-md' 
            : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 hover:text-slate-900 dark:hover:text-slate-200'}
        `}
        style={{ paddingLeft: `${depth * 12 + 12}px` }}
      >
        <div className={`mr-2 transition-transform duration-200 ${displayOpen && hasChildren ? 'rotate-90' : ''}`}>
            {hasChildren ? (
                <ChevronRight size={14} className={isSelected ? 'text-white/70 dark:text-slate-900/70' : 'text-slate-400'} />
            ) : (
                <div className="w-3.5" /> 
            )}
        </div>
        <span className="truncate relative z-10 flex-1 tracking-tight">{language === 'en' && category.nameEn ? category.nameEn : category.name}</span>

        {count > 0 && (
            <span className={`ml-2 px-1.5 py-0.5 rounded-md text-[9px] font-bold ${isSelected ? 'bg-white/20 text-white' : 'bg-slate-100 dark:bg-slate-700 text-slate-400 dark:text-slate-500 group-hover:bg-white dark:group-hover:bg-slate-600'}`}>
                {count}
            </span>
        )}

        {isSelected && <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 ml-1 animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.8)]"></div>}
      </div>

      {/* Smooth Collapse Animation */}
      <div 
        className={`overflow-hidden transition-all duration-300 ease-in-out ${displayOpen ? 'max-h-[800px] opacity-100' : 'max-h-0 opacity-0'}`}
      >
        <div className="relative ml-4 pl-2 border-l border-slate-200/50 dark:border-slate-700/50 my-0.5">
          {hasChildren && (
              <RecursiveTree 
                categories={category.children!} 
                selectedId={selectedId} 
                onSelect={onSelect} 
                depth={depth + 1} 
                forceExpand={!!forceExpand} 
                counts={counts} 
              />
          )}
        </div>
      </div>
    </div>
  );
};

export const TreeSidebar: React.FC<TreeSidebarProps> = ({ categories, selectedCategoryId, onSelectCategory, totalCount = 0, counts = {} }) => {
  const { t, language } = useLanguage();
  const [searchTerm, setSearchTerm] = useState('');

  const filterCategories = (cats: Category[], term: string): Category[] => {
    return cats.reduce<Category[]>((acc, cat) => {
        const name = language === 'en' && cat.nameEn ? cat.nameEn : cat.name;
        const matches = name.toLowerCase().includes(term.toLowerCase());
        let filteredChildren: Category[] = [];
        if (cat.children) filteredChildren = filterCategories(cat.children, term);
        if (matches || filteredChildren.length > 0) acc.push({ ...cat, children: filteredChildren });
        return acc;
    }, []);
  };

  const displayedCategories = useMemo(() => searchTerm.trim() ? filterCategories(categories, searchTerm) : categories, [categories, searchTerm, language]);

  return (
    <div className="flex flex-col h-full bg-transparent">
      <div className="p-4 pb-2 shrink-0 space-y-3">
        {/* Search */}
        <div className="relative group">
             <Search className="absolute left-3.5 top-2.5 text-slate-400 group-focus-within:text-emerald-500 transition-colors" size={16} />
             <input 
                type="text" 
                placeholder={t('searchCategories')} 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-8 py-2.5 bg-slate-50/80 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700 rounded-xl text-sm font-medium focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all placeholder:text-slate-400"
             />
             {searchTerm && <button onClick={() => setSearchTerm('')} className="absolute right-3 top-2.5 text-slate-400 hover:text-slate-600"><X size={14} /></button>}
        </div>

        {/* All Products Root Node - Visually Distinct */}
        <div 
            className={`
              flex items-center justify-between px-4 py-3 rounded-xl cursor-pointer transition-all duration-200 border group active:scale-[0.98] mx-1
              ${!selectedCategoryId 
                ? 'bg-gradient-to-r from-emerald-600 to-teal-600 text-white shadow-lg shadow-emerald-500/20 border-transparent' 
                : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 hover:border-emerald-500/30 hover:bg-emerald-50/50 dark:hover:bg-slate-700'
              }
            `}
            onClick={() => onSelectCategory(null)}
        >
            <div className="flex items-center gap-3">
                <div className={`p-1.5 rounded-lg ${!selectedCategoryId ? 'bg-white/20' : 'bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400'}`}>
                    <Layers size={16} />
                </div>
                <span className="font-bold text-sm tracking-wide">{t('allProducts')}</span>
            </div>
            <span className={`px-2 py-0.5 rounded-md text-[10px] font-black ${!selectedCategoryId ? 'bg-white/20 text-white' : 'bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400'}`}>{totalCount}</span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-2 custom-scrollbar pb-6 pt-1">
        {displayedCategories.length > 0 ? (
            <RecursiveTree 
                categories={displayedCategories} 
                selectedId={selectedCategoryId} 
                onSelect={onSelectCategory} 
                depth={0} 
                forceExpand={!!searchTerm}
                counts={counts}
            />
        ) : (
            <div className="text-center py-12 text-xs text-slate-400 italic flex flex-col items-center gap-2">
                <Search size={24} className="opacity-20" />
                No matching categories
            </div>
        )}
      </div>
    </div>
  );
};

import React, { useMemo } from 'react';
import { X, ChevronRight, Layers, Factory, Microscope, LayoutGrid, Globe, Info, BookOpen, ExternalLink, Calendar, FileText, ShieldCheck, Link2, Activity, Flame, Zap, TestTube, Box } from 'lucide-react';
import { Product, Category, Manufacturer, Reference, PropertyValue } from '../types';
import { CATEGORY_TREE, MANUFACTURERS, REFERENCES } from '../constants';
import { useLanguage } from '../contexts/LanguageContext';

interface ProductDetailDrawerProps {
  product: Product | null;
  onClose: () => void;
  onCategoryClick: (id: string) => void;
}

const PROPERTY_GROUPS: Record<string, string[]> = {
  'General': ['密度', '熔体质量流动速率', '成型收缩率', '吸水率', '典型应用', '应用', '牌号', '生产厂家', 'Grade', 'Manufacturer', 'Density', 'Melt Mass-Flow Rate (MFR)'],
  'Mechanical': ['拉伸屈服应力', '拉伸断裂应力', '拉伸强度', '断裂伸长率', '拉伸模量', '弯曲模量', '弯曲强度', '悬臂梁缺口冲击强度', '简支梁缺口冲击强度', '落镖冲击强度', '洛氏硬度', '邵氏硬度', 'Tensile Strength', 'Flexural Modulus', 'Impact Strength'],
  'Thermal': ['热变形温度', '维卡软化温度', '熔点', '熔融温度', '玻璃化转变温度', '氧化诱导时间', 'Melting Point', 'Heat Deflection Temp'],
  'Optical/Electrical': ['透光率', '雾度', '光泽度', '黄色指数', '体积电阻率', '介电强度'],
  'Chemical': ['乙烯含量', '门尼粘度', '灰分', '挥发分', '第三单体(ENB)', '结合苯乙烯', '顺式含量', 'K值', '粘数']
};

export const ProductDetailDrawer: React.FC<ProductDetailDrawerProps> = ({ product, onClose, onCategoryClick }) => {
  const { t, tProp, language } = useLanguage();

  const manufacturer = useMemo(() => 
    MANUFACTURERS.find(m => m.id === product?.manufacturerId), 
  [product]);

  const relevantRefs = useMemo(() => {
    if (!product) return [];
    const refIds = new Set((Object.values(product.properties) as PropertyValue[]).map(p => p.referenceId).filter(Boolean));
    return REFERENCES.filter(r => refIds.has(r.id as string));
  }, [product]);

  const allPaths = useMemo(() => {
    if (!product) return [];
    const paths: {segments: string[], leafId: string}[] = [];

    const findPaths = (nodes: Category[], targetId: string, currentPath: string[]) => {
      for (const node of nodes) {
        const nodeName = language === 'en' && node.nameEn ? node.nameEn : node.name;
        const newPath = [...currentPath, nodeName];
        if (node.id === targetId) {
            paths.push({ segments: newPath, leafId: node.id });
        }
        if (node.children) findPaths(node.children, targetId, newPath);
      }
    };

    product.categoryIds.forEach(id => findPaths(CATEGORY_TREE, id, []));
    return paths;
  }, [product, language]);

  const groupedProperties = useMemo(() => {
      if (!product) return {};
      const groups: Record<string, [string, PropertyValue][]> = {
          'General': [],
          'Mechanical': [],
          'Thermal': [],
          'Optical/Electrical': [],
          'Chemical': [],
          'Other': []
      };

      Object.entries(product.properties).forEach(([key, val]) => {
          let found = false;
          for (const groupName in PROPERTY_GROUPS) {
              if (PROPERTY_GROUPS[groupName].some(k => key.includes(k) || k === key)) {
                  groups[groupName].push([key, val as PropertyValue]);
                  found = true;
                  break;
              }
          }
          if (!found) groups['Other'].push([key, val as PropertyValue]);
      });

      return groups;
  }, [product]);

  if (!product) return null;

  const getGroupIcon = (name: string) => {
      switch(name) {
          case 'Mechanical': return <Activity size={16} className="text-blue-500" />;
          case 'Thermal': return <Flame size={16} className="text-orange-500" />;
          case 'Optical/Electrical': return <Zap size={16} className="text-yellow-500" />;
          case 'Chemical': return <TestTube size={16} className="text-purple-500" />;
          case 'General': return <Box size={16} className="text-emerald-500" />;
          default: return <LayoutGrid size={16} className="text-slate-400" />;
      }
  };

  return (
    <div className={`fixed inset-y-0 right-0 w-[600px] bg-white dark:bg-slate-900 shadow-2xl z-[60] border-l border-slate-200 dark:border-slate-800 transition-transform duration-300 transform ${product ? 'translate-x-0' : 'translate-x-full'} flex flex-col`}>
      {/* Header */}
      <div className="px-6 py-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-950/50">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-emerald-600 rounded-xl flex items-center justify-center text-white shadow-lg">
            <Microscope size={20} />
          </div>
          <div>
            <h3 className="text-lg font-bold text-slate-900 dark:text-white leading-none">{product.gradeName}</h3>
            <p className="text-[10px] text-slate-500 uppercase tracking-widest mt-1 font-black">ResinDB Technical Datasheet (TDS)</p>
          </div>
        </div>
        <button onClick={onClose} className="p-2 text-slate-400 hover:text-rose-500 transition-colors">
          <X size={24} />
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-6 custom-scrollbar space-y-8">

        {/* Manufacturer Info Card */}
        {manufacturer && (
            <div className="p-4 bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-800/50 dark:to-slate-800/20 border border-slate-200 dark:border-slate-700 rounded-2xl flex flex-col gap-3 relative overflow-hidden">
                <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none"><Factory size={100} /></div>
                <div className="flex items-center justify-between z-10">
                    <div className="flex items-center gap-2.5">
                        <div className="p-2 bg-white dark:bg-slate-900 rounded-lg shadow-sm text-emerald-600 dark:text-emerald-400"><Factory size={18} /></div>
                        <div>
                            <h4 className="text-sm font-bold text-slate-800 dark:text-slate-100">{manufacturer.name}</h4>
                            <p className="text-[10px] text-slate-500">{product.manufacturer}</p>
                        </div>
                    </div>
                    {manufacturer.website && (
                        <a href={manufacturer.website.startsWith('http') ? manufacturer.website : `https://${manufacturer.website}`} target="_blank" rel="noreferrer" className="text-[10px] bg-white dark:bg-slate-900 px-3 py-1.5 rounded-full border border-slate-200 dark:border-slate-700 flex items-center gap-1.5 hover:text-emerald-500 transition-colors shadow-sm z-10">
                            <Globe size={12} /> Website
                        </a>
                    )}
                </div>
                <p className="text-xs text-slate-600 dark:text-slate-400 leading-relaxed z-10">{manufacturer.description}</p>
            </div>
        )}

        {/* Multi-path Classification */}
        <section className="space-y-3">
          <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-widest">
            <Link2 size={12} className="text-blue-500" />
            Taxonomy Paths
          </div>
          <div className="bg-blue-50/30 dark:bg-blue-900/10 border border-blue-100/50 dark:border-blue-800/30 rounded-xl p-3 space-y-1.5">
            {allPaths.map((path, idx) => (
              <button key={idx} onClick={() => onCategoryClick(path.leafId)} className="w-full text-left group flex items-center gap-1.5 py-0.5 hover:translate-x-1 transition-transform">
                <div className="flex flex-wrap items-center text-[11px]">
                  {path.segments.map((segment, sIdx) => (
                    <React.Fragment key={sIdx}>
                      <span className={`transition-colors ${sIdx === path.segments.length - 1 ? 'font-bold text-blue-600 dark:text-blue-400' : 'text-slate-500 group-hover:text-blue-400'}`}>{segment}</span>
                      {sIdx < path.segments.length - 1 && <ChevronRight size={10} className="mx-1 text-slate-300" />}
                    </React.Fragment>
                  ))}
                </div>
              </button>
            ))}
          </div>
        </section>

        {/* Property Groups */}
        <div className="space-y-6">
            {Object.entries(groupedProperties).map(([groupName, items]) => {
                if (items.length === 0) return null;
                return (
                    <section key={groupName} className="animate-in fade-in slide-in-from-bottom-2 duration-500">
                        <div className="flex items-center gap-2 mb-3 pb-2 border-b border-slate-100 dark:border-slate-800">
                            {getGroupIcon(groupName)}
                            <h4 className="text-sm font-bold text-slate-800 dark:text-slate-200">{groupName === 'Other' ? 'Other Properties' : `${groupName} Properties`}</h4>
                        </div>
                        <div className="grid grid-cols-1 gap-2">
                            {items.map(([key, prop]) => (
                                <div key={key} className="flex flex-col sm:flex-row sm:items-center justify-between p-3 rounded-xl bg-slate-50/50 dark:bg-slate-800/20 hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors border border-transparent hover:border-slate-100 dark:hover:border-slate-700">
                                    <div className="mb-1 sm:mb-0">
                                        <span className="text-xs font-semibold text-slate-600 dark:text-slate-300 block">{tProp(key)}</span>
                                        <div className="flex items-center gap-2 mt-0.5">
                                            {prop.standard && <span className="text-[9px] text-slate-400 bg-white dark:bg-slate-900 px-1.5 py-0.5 rounded border border-slate-100 dark:border-slate-700">{prop.standard}</span>}
                                            {prop.temperature && <span className="text-[9px] text-slate-400 flex items-center gap-0.5"><Info size={8} /> {prop.temperature}</span>}
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-3 sm:text-right">
                                        <div className="font-mono font-bold text-sm text-slate-900 dark:text-white">
                                            {prop.value} <span className="text-[10px] text-slate-400 font-sans ml-0.5">{prop.unit}</span>
                                        </div>
                                        {prop.referenceId && (
                                            <div className="w-6 h-6 rounded-full bg-slate-200 dark:bg-slate-700 flex items-center justify-center text-[9px] font-bold text-slate-500" title="Source Verified">
                                                <ShieldCheck size={12} />
                                            </div>
                                        )}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </section>
                );
            })}
        </div>

        {/* References */}
        {relevantRefs.length > 0 && (
            <section className="space-y-3 pt-4 border-t border-slate-100 dark:border-slate-800">
                <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                    <BookOpen size={12} className="text-emerald-500" />
                    Reference Documents
                </div>
                <div className="grid grid-cols-1 gap-2">
                    {relevantRefs.map(ref => (
                        <div key={ref.id} className="flex items-start gap-3 p-3 bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-xl hover:shadow-md transition-all">
                            <FileText size={16} className="text-slate-400 mt-0.5" />
                            <div>
                                <p className="text-xs font-bold text-slate-700 dark:text-slate-300">{ref.name}</p>
                                <p className="text-[10px] text-slate-400 mt-0.5">{ref.author} • {ref.year}</p>
                            </div>
                        </div>
                    ))}
                </div>
            </section>
        )}
      </div>

      <div className="p-4 bg-slate-50 dark:bg-slate-950/50 border-t border-slate-100 dark:border-slate-800 text-[10px] text-slate-400 flex justify-center items-center gap-2">
        <ShieldCheck size={12} className="text-emerald-500" />
        <span>Data verified against PetroChina Standards Database.</span>
      </div>
    </div>
  );
};

