import React, { useMemo } from 'react';
import { X, ChevronRight, Layers, Factory, Microscope, LayoutGrid, Globe, Info, BookOpen, ExternalLink, Calendar, FileText, ShieldCheck, Link2, Activity, Flame, Zap, TestTube, Box, FlaskConical, Beaker } from 'lucide-react';
import { Product, Category, Manufacturer, Reference, PropertyValue } from '../types';
import { CATEGORY_TREE, MANUFACTURERS, REFERENCES, PROPERTY_GROUPS } from '../constants';
import { useLanguage } from '../contexts/LanguageContext';

interface ProductDetailDrawerProps {
  product: Product | null;
  onClose: () => void;
  onCategoryClick: (id: string) => void;
}

export const ProductDetailDrawer: React.FC<ProductDetailDrawerProps> = ({ product, onClose, onCategoryClick }) => {
  const { t, tProp, language } = useLanguage();

  const manufacturer = useMemo(() => 
    MANUFACTURERS.find(m => m.id === product?.manufacturerId), 
  [product]);

  const relevantRefs = useMemo(() => {
    if (!product) return [];
    const refIds = new Set((Object.values(product.properties) as PropertyValue[]).map(p => p.referenceId).filter(Boolean));
    return REFERENCES.filter(r => refIds.has(r.id as string));
  }, [product]);

  const allPaths = useMemo(() => {
    if (!product) return [];
    const paths: {segments: string[], leafId: string}[] = [];

    const findPaths = (nodes: Category[], targetId: string, currentPath: string[]) => {
      for (const node of nodes) {
        const nodeName = language === 'en' && node.nameEn ? node.nameEn : node.name;
        const newPath = [...currentPath, nodeName];
        if (node.id === targetId) {
            paths.push({ segments: newPath, leafId: node.id });
        }
        if (node.children) findPaths(node.children, targetId, newPath);
      }
    };

    product.categoryIds.forEach(id => findPaths(CATEGORY_TREE, id, []));
    return paths;
  }, [product, language]);

  const groupedProperties = useMemo(() => {
      if (!product) return {};
      const groups: Record<string, [string, PropertyValue][]> = {
          'General': [],
          'Mechanical': [],
          'Thermal': [],
          'Optical/Electrical': [],
          'Chemical': [],
          'Other': []
      };

      Object.entries(product.properties).forEach(([key, val]) => {
          let found = false;
          for (const groupName in PROPERTY_GROUPS) {
              if (PROPERTY_GROUPS[groupName].some(k => key.includes(k) || k === key)) {
                  groups[groupName].push([key, val as PropertyValue]);
                  found = true;
                  break;
              }
          }
          if (!found) groups['Other'].push([key, val as PropertyValue]);
      });

      return groups;
  }, [product]);

  if (!product) return null;

  const getGroupIcon = (name: string) => {
      switch(name) {
          case 'Mechanical': return <Activity size={16} className="text-blue-500" />;
          case 'Thermal': return <Flame size={16} className="text-orange-500" />;
          case 'Optical/Electrical': return <Zap size={16} className="text-yellow-500" />;
          case 'Chemical': return <TestTube size={16} className="text-purple-500" />;
          case 'General': return <Box size={16} className="text-emerald-500" />;
          default: return <LayoutGrid size={16} className="text-slate-400" />;
      }
  };

  return (
    <div className={`fixed inset-y-0 right-0 w-full sm:w-[640px] bg-white dark:bg-slate-900 shadow-2xl z-[60] border-l border-slate-200 dark:border-slate-800 transition-transform duration-300 transform ${product ? 'translate-x-0' : 'translate-x-full'} flex flex-col`}>
      {/* Header */}
      <div className="px-6 py-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-950/50 backdrop-blur-sm sticky top-0 z-10">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-gradient-to-br from-emerald-500 to-teal-600 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-emerald-500/20">
            <Microscope size={24} />
          </div>
          <div>
            <h3 className="text-xl font-black text-slate-900 dark:text-white leading-tight tracking-tight">{product.gradeName}</h3>
            <div className="flex items-center gap-2 mt-1">
                <span className="text-[10px] font-bold bg-slate-200 dark:bg-slate-800 text-slate-600 dark:text-slate-400 px-2 py-0.5 rounded-full uppercase tracking-wider">TDS Report</span>
                <span className="text-[10px] text-slate-400 font-medium">Updated: {product.updatedAt}</span>
            </div>
          </div>
        </div>
        <button onClick={onClose} className="p-2 text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-xl transition-all">
          <X size={24} />
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-6 custom-scrollbar space-y-8 bg-slate-50/30 dark:bg-slate-950/30">

        {/* Manufacturer & Source Card */}
        {manufacturer && (
            <div className="bg-white dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-2xl p-5 relative overflow-hidden group shadow-sm">
                <div className="absolute top-0 right-0 p-6 opacity-[0.03] pointer-events-none group-hover:scale-110 transition-transform duration-700"><Factory size={120} /></div>
                <div className="relative z-10">
                    <div className="flex justify-between items-start mb-4">
                        <div className="flex items-center gap-3">
                            <div className="p-2.5 bg-blue-50 dark:bg-blue-900/20 rounded-xl text-blue-600 dark:text-blue-400">
                                <Factory size={20} />
                            </div>
                            <div>
                                <h4 className="text-base font-bold text-slate-900 dark:text-white">{manufacturer.name}</h4>
                                <div className="flex items-center gap-1.5 mt-0.5">
                                    <ShieldCheck size={12} className="text-emerald-500" />
                                    <span className="text-[10px] font-medium text-emerald-600 dark:text-emerald-400 uppercase tracking-wide">Verified Manufacturer</span>
                                </div>
                            </div>
                        </div>
                        {manufacturer.website && (
                            <a 
                                href={manufacturer.website.startsWith('http') ? manufacturer.website : `https://${manufacturer.website}`} 
                                target="_blank" 
                                rel="noreferrer" 
                                className="flex items-center gap-2 px-4 py-2 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-xl text-xs font-bold hover:opacity-90 transition-opacity shadow-lg shadow-slate-500/10"
                            >
                                <Globe size={14} /> Official Website
                            </a>
                        )}
                    </div>
                    <p className="text-xs text-slate-600 dark:text-slate-300 leading-relaxed bg-slate-50 dark:bg-slate-900/50 p-3 rounded-xl border border-slate-100 dark:border-slate-800">
                        {manufacturer.description}
                    </p>
                </div>
            </div>
        )}

        {/* Multi-path Classification */}
        <section className="space-y-3">
          <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-widest">
            <Link2 size={12} className="text-blue-500" />
            Taxonomy Paths
          </div>
          <div className="space-y-2">
            {allPaths.map((path, idx) => (
              <button 
                key={idx} 
                onClick={() => onCategoryClick(path.leafId)} 
                className="w-full text-left group flex items-center p-2 rounded-xl bg-white dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 hover:border-emerald-400 dark:hover:border-emerald-600 transition-all shadow-sm hover:shadow-md"
              >
                <div className="flex flex-wrap items-center text-xs">
                  {path.segments.map((segment, sIdx) => (
                    <React.Fragment key={sIdx}>
                      <span className={`font-medium transition-colors ${sIdx === path.segments.length - 1 ? 'font-bold text-slate-800 dark:text-white' : 'text-slate-500 dark:text-slate-400'}`}>{segment}</span>
                      {sIdx < path.segments.length - 1 && <ChevronRight size={12} className="mx-1.5 text-slate-300" />}
                    </React.Fragment>
                  ))}
                </div>
              </button>
            ))}
          </div>
        </section>

        {/* Property Groups */}
        <div className="space-y-8">
            {Object.entries(groupedProperties).map(([groupName, items]) => {
                if (items.length === 0) return null;
                return (
                    <section key={groupName} className="animate-in fade-in slide-in-from-bottom-2 duration-500">
                        <div className="flex items-center gap-2 mb-4 pb-2 border-b border-slate-200 dark:border-slate-700">
                            {getGroupIcon(groupName)}
                            <h4 className="text-sm font-black text-slate-800 dark:text-white uppercase tracking-wider">{groupName === 'Other' ? 'Other Properties' : `${groupName} Properties`}</h4>
                        </div>
                        <div className="grid grid-cols-1 gap-3">
                            {items.map(([key, prop]) => (
                                <div key={key} className="flex flex-col p-4 rounded-2xl bg-white dark:bg-slate-800/30 border border-slate-200 dark:border-slate-800 hover:border-emerald-200 dark:hover:border-emerald-800 transition-colors shadow-sm">
                                    <div className="flex justify-between items-start mb-2">
                                        <div className="flex-1">
                                            <span className="text-xs font-bold text-slate-700 dark:text-slate-200 block mb-1">{tProp(key)}</span>

                                            {/* Context Tags */}
                                            <div className="flex flex-wrap gap-2">
                                                {prop.standard && (
                                                    <span className="text-[9px] font-medium text-slate-500 bg-slate-100 dark:bg-slate-900 px-1.5 py-0.5 rounded border border-slate-200 dark:border-slate-700 flex items-center gap-1">
                                                        <FileText size={8} /> {prop.standard}
                                                    </span>
                                                )}
                                                {prop.temperature && (
                                                    <span className="text-[9px] font-medium text-slate-500 bg-slate-100 dark:bg-slate-900 px-1.5 py-0.5 rounded border border-slate-200 dark:border-slate-700 flex items-center gap-1">
                                                        <Flame size={8} /> {prop.temperature}
                                                    </span>
                                                )}
                                            </div>
                                        </div>

                                        {/* Value Display */}
                                        <div className="text-right">
                                            <div className="font-mono font-black text-lg text-slate-900 dark:text-white leading-none">
                                                {prop.value}
                                            </div>
                                            {prop.unit && <div className="text-[10px] font-bold text-slate-400 mt-1">{prop.unit}</div>}
                                        </div>
                                    </div>

                                    {/* Equipment Line - Detailed Parameter */}
                                    {prop.instrument && (
                                        <div className="mt-3 pt-3 border-t border-slate-100 dark:border-slate-700/50 flex items-center gap-2 text-[10px] text-slate-500 dark:text-slate-400">
                                            <FlaskConical size={12} className="text-emerald-500" />
                                            <span className="font-bold uppercase tracking-wider text-emerald-700 dark:text-emerald-500 text-[9px]">Source Equipment:</span>
                                            <span className="font-medium">{prop.instrument}</span>
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    </section>
                );
            })}
        </div>

        {/* References */}
        {relevantRefs.length > 0 && (
            <section className="space-y-4 pt-4 border-t border-slate-200 dark:border-slate-800">
                <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                    <BookOpen size={12} className="text-emerald-500" />
                    Reference Documents
                </div>
                <div className="grid grid-cols-1 gap-2">
                    {relevantRefs.map(ref => (
                        <div key={ref.id} className="flex items-center gap-4 p-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl hover:shadow-md transition-all group">
                            <div className="p-2 bg-slate-100 dark:bg-slate-700 rounded-lg text-slate-500 group-hover:text-emerald-600 transition-colors">
                                <FileText size={18} />
                            </div>
                            <div>
                                <p className="text-xs font-bold text-slate-800 dark:text-white mb-0.5">{ref.name}</p>
                                <p className="text-[10px] text-slate-400 font-medium uppercase tracking-wide">{ref.author} • {ref.year}</p>
                            </div>
                        </div>
                    ))}
                </div>
            </section>
        )}
      </div>

      <div className="p-4 bg-slate-50 dark:bg-slate-950/80 border-t border-slate-200 dark:border-slate-800 backdrop-blur-md">
        <div className="flex justify-center items-center gap-2 text-[10px] text-slate-400 font-medium">
            <ShieldCheck size={12} className="text-emerald-500" />
            <span>Data verified against PetroChina Standards Database.</span>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Product, ColumnConfig, SortConfig, PropertyValue } from '../types';
import { Factory, Edit, Trash2, CheckSquare, Square, MinusSquare, ArrowUp, ArrowDown, ChevronLeft, ChevronRight, ListChecks, Eye, Info, BookOpen, X, MoreHorizontal, GitCompare, FlaskConical } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { EditProductModal } from './EditProductModal';
import { DeleteConfirmationModal } from './DeleteConfirmationModal';
import { BatchEditModal } from './BatchEditModal';
import { CATEGORY_TREE, REFERENCES } from '../constants';
import { ProductDetailDrawer } from './ProductDetailDrawer';
import { ComparisonView } from './ComparisonView';

interface DataGridProps {
  data: Product[];
  columns: ColumnConfig[];
  isLoading: boolean;
  onDelete: (ids: string[]) => void;
  onUpdate: (product: Product) => void;
  onBatchUpdate: (ids: string[], updates: Partial<Product>) => void;
  onCategorySelect: (id: string) => void;
}

const PropertyContextTooltip: React.FC<{ prop: PropertyValue }> = ({ prop }) => {
    const { t } = useLanguage();
    const reference = REFERENCES.find(r => r.id === prop.referenceId);
    return (
        <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 z-[100] w-64 bg-slate-900/95 dark:bg-white/95 backdrop-blur-xl text-white dark:text-slate-900 rounded-2xl shadow-2xl p-4 animate-in fade-in zoom-in-95 duration-200 pointer-events-none border border-slate-700 dark:border-slate-200">
            <div className="flex items-center gap-2 mb-3 border-b border-white/10 dark:border-slate-900/10 pb-2">
                <Info size={14} className="text-emerald-400 dark:text-emerald-600" />
                <span className="text-[10px] font-black uppercase tracking-widest">{t('details')}</span>
            </div>
            <div className="space-y-3">
                {prop.instrument && (<div><p className="text-[9px] opacity-60 font-bold uppercase tracking-tighter mb-0.5">Source Equipment</p><div className="flex items-center gap-1.5 mt-0.5"><FlaskConical size={10} className="text-emerald-400 dark:text-emerald-600" /><p className="text-xs font-medium">{prop.instrument}</p></div></div>)}
                {prop.standard && (<div><p className="text-[9px] opacity-60 font-bold uppercase tracking-tighter mb-0.5">Standard</p><p className="text-xs font-medium">{prop.standard}</p></div>)}
                {prop.temperature && (<div><p className="text-[9px] opacity-60 font-bold uppercase tracking-tighter mb-0.5">Test Conditions</p><p className="text-xs font-medium">{prop.temperature}</p></div>)}
                {reference && (<div><p className="text-[9px] opacity-60 font-bold uppercase tracking-tighter mb-0.5">Reference Source</p><div className="flex items-center gap-1.5 mt-0.5"><BookOpen size={10} className="text-emerald-400 dark:text-emerald-600" /><p className="text-[10px] italic opacity-80 truncate">{reference.name}</p></div></div>)}
            </div>
            <div className="absolute top-full left-1/2 -translate-x-1/2 w-3 h-3 bg-slate-900/95 dark:bg-white/95 rotate-45 -mt-1.5"></div>
        </div>
    );
};

const GridSkeleton: React.FC = () => (
    <div className="animate-pulse space-y-4 p-4">
        {[...Array(8)].map((_, i) => (
            <div key={i} className="flex gap-4">
                <div className="w-8 h-8 rounded-lg bg-slate-200 dark:bg-slate-800"></div>
                <div className="w-48 h-8 rounded-lg bg-slate-200 dark:bg-slate-800"></div>
                <div className="flex-1 h-8 rounded-lg bg-slate-200 dark:bg-slate-800"></div>
                <div className="w-24 h-8 rounded-lg bg-slate-200 dark:bg-slate-800"></div>
            </div>
        ))}
    </div>
);

export const DataGrid: React.FC<DataGridProps> = ({ data, columns, isLoading, onDelete, onUpdate, onBatchUpdate, onCategorySelect }) => {
  const { t, tProp, language } = useLanguage();
  const visibleColumns = columns.filter((c) => c.visible);

  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [viewingProduct, setViewingProduct] = useState<Product | null>(null);
  const [isBatchEditing, setIsBatchEditing] = useState(false);
  const [isComparing, setIsComparing] = useState(false);
  const [deletingIds, setDeletingIds] = useState<string[] | null>(null);
  const [sortConfig, setSortConfig] = useState<SortConfig | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(15);
  const [hoveredCell, setHoveredCell] = useState<{ productId: string, colKey: string } | null>(null);

  useEffect(() => { setSelectedIds(new Set()); setCurrentPage(1); }, [data.length]);

  const handleSort = (key: string) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') direction = 'desc';
    setSortConfig({ key, direction });
  };

  const sortedData = useMemo(() => {
    if (!sortConfig) return data;
    return [...data].sort((a, b) => {
      const getVal = (p: Product, k: string) => {
        if (k === 'gradeName') return p.gradeName;
        if (k === 'manufacturer') return p.manufacturer;
        if (k === 'updatedAt') return p.updatedAt;
        const prop = p.properties[k];
        return prop && prop.value !== undefined ? prop.value : '';
      };
      const valA = getVal(a, sortConfig.key);
      const valB = getVal(b, sortConfig.key);
      if (typeof valA === 'number' && typeof valB === 'number') return sortConfig.direction === 'asc' ? valA - valB : valB - valA;
      return sortConfig.direction === 'asc' ? String(valA).localeCompare(String(valB)) : String(valB).localeCompare(String(valA));
    });
  }, [data, sortConfig]);

  const paginatedData = useMemo(() => {
    const startIndex = (currentPage - 1) * pageSize;
    return sortedData.slice(startIndex, startIndex + pageSize);
  }, [sortedData, currentPage, pageSize]);

  const totalPages = Math.ceil(sortedData.length / pageSize);
  const columnMaxValues = useMemo(() => {
    const maxVals: Record<string, number> = {};
    visibleColumns.forEach(col => {
       if (['gradeName', 'manufacturer', 'updatedAt'].includes(col.key)) return;
       let max = 0;
       data.forEach(p => {
           const v = p.properties[col.key]?.value;
           const num = Number(v);
           if (!isNaN(num) && num > max) max = num;
       });
       if (max > 0) maxVals[col.key] = max;
    });
    return maxVals;
  }, [data, visibleColumns]);

  const isAllSelected = paginatedData.length > 0 && paginatedData.every(p => selectedIds.has(p.id));
  const isIndeterminate = paginatedData.some(p => selectedIds.has(p.id)) && !isAllSelected;

  const toggleSelectAll = () => {
    const newSet = new Set(selectedIds);
    if (isAllSelected) paginatedData.forEach(p => newSet.delete(p.id));
    else paginatedData.forEach(p => newSet.add(p.id));
    setSelectedIds(newSet);
  };

  const getCategoryNames = (ids: string[]) => {
      const names: string[] = [];
      const traverse = (cats: any[]) => {
          cats.forEach(c => {
              if (ids.includes(c.id)) names.push(language === 'en' && c.nameEn ? c.nameEn : c.name);
              if (c.children) traverse(c.children);
          });
      };
      traverse(CATEGORY_TREE);
      return Array.from(new Set(names));
  };

  if (isLoading) return <GridSkeleton />;

  return (
    <>
    <div className="flex flex-col h-full relative">
      {/* Batch Action Island */}
      <div className={`absolute top-4 left-1/2 -translate-x-1/2 z-[100] bg-slate-900/90 dark:bg-white/90 backdrop-blur-xl text-white dark:text-slate-900 shadow-2xl rounded-full px-6 py-2.5 flex items-center gap-6 transition-all duration-500 transform ${selectedIds.size > 0 ? 'translate-y-0 opacity-100' : '-translate-y-10 opacity-0 pointer-events-none scale-90'}`}>
          <div className="flex items-center gap-3 border-r border-white/20 dark:border-slate-900/20 pr-4">
              <span className="font-black text-sm">{selectedIds.size}</span>
              <span className="text-xs font-medium opacity-80 uppercase tracking-wider">{t('selected')}</span>
          </div>
          <div className="flex gap-2">
              <button 
                onClick={() => setIsComparing(true)} 
                disabled={selectedIds.size < 2 || selectedIds.size > 4}
                className="flex items-center gap-2 px-3 py-1.5 hover:bg-white/20 dark:hover:bg-slate-900/10 rounded-full transition-colors disabled:opacity-30 disabled:cursor-not-allowed text-xs font-bold uppercase tracking-wide"
              >
                  <GitCompare size={16} /> Compare
              </button>
              <div className="w-px h-6 bg-white/20 dark:bg-slate-900/20 my-auto"></div>
              <button onClick={() => setIsBatchEditing(true)} className="p-2 hover:bg-white/20 dark:hover:bg-slate-900/10 rounded-full transition-colors" title="Batch Edit"><ListChecks size={18} /></button>
              <button onClick={() => setDeletingIds(Array.from(selectedIds))} className="p-2 hover:bg-rose-500/80 rounded-full transition-colors text-rose-300 hover:text-white" title="Delete"><Trash2 size={18} /></button>
              <button onClick={() => setSelectedIds(new Set())} className="p-2 hover:bg-white/20 dark:hover:bg-slate-900/10 rounded-full transition-colors ml-2" title="Clear Selection"><X size={18} /></button>
          </div>
      </div>

      <div className="overflow-x-auto overflow-y-auto custom-scrollbar flex-1 relative px-3 pt-2">
        <table className="w-full text-sm text-left border-separate border-spacing-y-3">
          <thead className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase sticky top-0 z-30">
            <tr>
              <th className="w-12 px-4 py-3.5 bg-white/95 dark:bg-slate-950/95 backdrop-blur-xl first:rounded-l-2xl last:rounded-r-2xl shadow-sm border border-slate-100 dark:border-slate-800 sticky left-0 z-40">
                  <div onClick={toggleSelectAll} className="cursor-pointer flex justify-center hover:scale-110 transition-transform">
                      {isAllSelected ? <CheckSquare size={18} className="text-emerald-500"/> : (isIndeterminate ? <MinusSquare size={18} className="text-emerald-500"/> : <Square size={18} className="text-slate-300"/>)}
                  </div>
              </th>
              {visibleColumns.map((col, index) => (
                <th 
                    key={col.key} 
                    onClick={() => handleSort(col.key)} 
                    className={`
                        px-5 py-3.5 whitespace-nowrap cursor-pointer hover:text-emerald-500 transition-colors bg-white/95 dark:bg-slate-950/95 backdrop-blur-xl shadow-sm border border-l-0 border-slate-100 dark:border-slate-800
                        ${columnMaxValues[col.key] ? 'text-right' : 'text-left'}
                        ${col.key === 'gradeName' ? 'sticky left-[48px] z-40' : ''} 
                    `}
                >
                  <div className={`flex items-center gap-1.5 ${columnMaxValues[col.key] ? 'justify-end' : 'justify-start'}`}>
                    <span className={sortConfig?.key === col.key ? 'text-emerald-500' : ''}>{tProp(col.label)}</span>
                    {sortConfig?.key === col.key && (sortConfig.direction === 'asc' ? <ArrowUp size={10} /> : <ArrowDown size={10} />)}
                  </div>
                </th>
              ))}
              <th className="px-5 py-3.5 text-right bg-white/95 dark:bg-slate-950/95 backdrop-blur-xl rounded-r-2xl shadow-sm border border-l-0 border-slate-100 dark:border-slate-800 sticky right-0 z-40">{t('actions')}</th>
            </tr>
          </thead>
          <tbody className="pb-4">
            {paginatedData.map((product) => (
              <tr 
                key={product.id} 
                onClick={() => setViewingProduct(product)}
                className={`group cursor-pointer transition-all duration-300 hover:scale-[1.005] hover:-translate-y-0.5 rounded-[1.5rem] relative ${selectedIds.has(product.id) ? 'shadow-lg shadow-emerald-500/10' : 'shadow-sm hover:shadow-lg'}`}
              >
                {/* Checkbox Cell - Sticky */}
                <td className={`px-4 py-4 rounded-l-[1.5rem] border-y border-l transition-colors sticky left-0 z-20 ${selectedIds.has(product.id) ? 'bg-emerald-50 dark:bg-slate-900 border-emerald-500/30' : 'bg-white dark:bg-slate-900/60 border-transparent hover:border-slate-100 dark:hover:border-slate-800'}`} onClick={(e) => e.stopPropagation()}>
                    <div onClick={() => { const s = new Set(selectedIds); if(s.has(product.id)) s.delete(product.id); else s.add(product.id); setSelectedIds(s); }} className="cursor-pointer flex justify-center text-slate-300 dark:text-slate-600 group-hover:text-emerald-500 transition-colors">
                        {selectedIds.has(product.id) ? <CheckSquare size={18} className="text-emerald-500"/> : <Square size={18}/>}
                    </div>
                </td>

                {/* Data Cells */}
                {visibleColumns.map((col) => {
                  const isNum = !!columnMaxValues[col.key];
                  const barWidth = isNum ? Math.min((Number(product.properties[col.key]?.value || 0) / columnMaxValues[col.key]) * 100, 100) : 0;
                  const property = product.properties[col.key];
                  const hasContext = property && (property.standard || property.temperature || property.referenceId || property.instrument);
                  const isHovered = hoveredCell?.productId === product.id && hoveredCell?.colKey === col.key;

                  // Sticky Style for Grade Name column
                  const stickyStyle = col.key === 'gradeName' ? `sticky left-[48px] z-20` : '';

                  return (
                    <td 
                      key={col.key} 
                      className={`
                        px-5 py-4 whitespace-nowrap border-y transition-colors relative 
                        ${selectedIds.has(product.id) ? 'bg-emerald-50 dark:bg-slate-900 border-emerald-500/30' : 'bg-white dark:bg-slate-900/60 border-transparent hover:border-slate-100 dark:hover:border-slate-800'} 
                        ${isNum ? 'text-right font-mono' : ''}
                        ${stickyStyle}
                      `}
                      onMouseEnter={() => hasContext && setHoveredCell({ productId: product.id, colKey: col.key })}
                      onMouseLeave={() => setHoveredCell(null)}
                    >
                      {col.key === 'gradeName' ? (
                        <div className="flex flex-col">
                            <span className="font-bold text-slate-800 dark:text-slate-100 text-sm">{product.gradeName}</span>
                            <span className="text-[9px] text-slate-400 flex items-center gap-1 uppercase tracking-wider font-bold mt-0.5"><Factory size={10} /> {product.manufacturer}</span>
                        </div>
                      ) : col.key === 'manufacturer' ? (
                        <div className="flex flex-wrap gap-1 max-w-[200px]">
                            {getCategoryNames(product.categoryIds).slice(0, 2).map(name => (
                                <span key={name} className="px-2 py-0.5 bg-slate-100 dark:bg-slate-800/80 text-slate-500 dark:text-slate-300 rounded-full text-[9px] font-bold border border-slate-200 dark:border-slate-700">{name}</span>
                            ))}
                            {product.categoryIds.length > 2 && <span className="text-[9px] text-slate-400 font-bold px-1">+{product.categoryIds.length - 2}</span>}
                        </div>
                      ) : isNum ? (
                        <>
                          <div className="absolute bottom-2 right-5 h-1 bg-slate-100 dark:bg-slate-700/50 rounded-full w-16 overflow-hidden">
                             <div className="h-full bg-emerald-500 rounded-full" style={{ width: `${barWidth}%` }}></div>
                          </div>
                          <div className="flex items-center justify-end gap-1.5 relative z-10 pb-1">
                            {hasContext && <Info size={12} className={`shrink-0 transition-colors ${isHovered ? 'text-emerald-500' : 'text-slate-300'}`} />}
                            <span className="font-bold text-slate-700 dark:text-slate-200">{property?.value} <span className="text-[10px] text-slate-400 font-sans font-medium">{property?.unit}</span></span>
                          </div>
                          {isHovered && property && <PropertyContextTooltip prop={property} />}
                        </>
                      ) : (
                        <div className="flex items-center gap-1.5">
                           {hasContext && <Info size={12} className={`shrink-0 transition-colors ${isHovered ? 'text-emerald-500' : 'text-slate-300'}`} />}
                           <span className="text-slate-600 dark:text-slate-400 font-medium truncate max-w-[150px]">{String(property?.value || '-')}</span>
                           {isHovered && property && <PropertyContextTooltip prop={property} />}
                        </div>
                      )}
                    </td>
                  );
                })}

                {/* Actions Cell */}
                <td className={`px-5 py-4 text-right rounded-r-[1.5rem] border-y border-r sticky right-0 z-20 transition-colors ${selectedIds.has(product.id) ? 'bg-emerald-50 dark:bg-slate-900 border-emerald-500/30' : 'bg-white/90 dark:bg-slate-900/90 border-transparent hover:border-slate-100 dark:hover:border-slate-800'}`} onClick={(e) => e.stopPropagation()}>
                   <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-all translate-x-4 group-hover:translate-x-0">
                      <button onClick={() => setViewingProduct(product)} className="p-2 bg-slate-100 dark:bg-slate-800 hover:bg-emerald-500 hover:text-white rounded-xl transition-colors shadow-sm active:scale-95" title="View"><Eye size={14}/></button>
                      <button onClick={() => setEditingProduct(product)} className="p-2 bg-slate-100 dark:bg-slate-800 hover:bg-blue-500 hover:text-white rounded-xl transition-colors shadow-sm active:scale-95" title="Edit"><Edit size={14}/></button>
                      <button onClick={() => setDeletingIds([product.id])} className="p-2 bg-slate-100 dark:bg-slate-800 hover:bg-rose-500 hover:text-white rounded-xl transition-colors shadow-sm active:scale-95" title="Delete"><Trash2 size={14}/></button>
                   </div>
                   <div className="absolute right-4 top-1/2 -translate-y-1/2 group-hover:opacity-0 transition-opacity">
                      <MoreHorizontal size={16} className="text-slate-300" />
                   </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Pagination Island */}
      <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl px-5 py-2.5 rounded-full shadow-2xl border border-white/40 dark:border-slate-800 z-[80] transition-transform hover:scale-105">
          <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} className="p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors disabled:opacity-30 disabled:hover:bg-transparent" disabled={currentPage === 1}><ChevronLeft size={18} /></button>
          <span className="text-xs font-bold font-mono text-slate-500 dark:text-slate-400">{currentPage} <span className="opacity-40 mx-1">/</span> {totalPages}</span>
          <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} className="p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors disabled:opacity-30 disabled:hover:bg-transparent" disabled={currentPage === totalPages}><ChevronRight size={18} /></button>
      </div>
    </div>

    <ProductDetailDrawer product={viewingProduct} onClose={() => setViewingProduct(null)} onCategoryClick={onCategorySelect} />
    <EditProductModal isOpen={!!editingProduct} onClose={() => setEditingProduct(null)} product={editingProduct} onSave={onUpdate} />
    <BatchEditModal isOpen={isBatchEditing} onClose={() => setIsBatchEditing(false)} selectedProducts={data.filter(p => selectedIds.has(p.id))} onSave={(ids, updates) => { onBatchUpdate(ids, updates); setSelectedIds(new Set()); }} />
    <DeleteConfirmationModal isOpen={!!deletingIds} onClose={() => setDeletingIds(null)} onConfirm={() => { onDelete(deletingIds!); setSelectedIds(new Set()); }} productNames={deletingIds?.map(id => data.find(p => p.id === id)?.gradeName || '') || []} />
    {isComparing && (
        <ComparisonView 
            products={data.filter(p => selectedIds.has(p.id))} 
            onClose={() => setIsComparing(false)} 
            onRemoveProduct={(id) => {
                const newSet = new Set(selectedIds);
                newSet.delete(id);
                setSelectedIds(newSet);
                if (newSet.size < 2) setIsComparing(false);
            }} 
        />
    )}
    </>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  ReferenceLine,
  Cell,
  LabelList,
  Line,
  ComposedChart,
  ZAxis
} from 'recharts';
import { Settings, Download, ChevronUp, BarChart2, ScatterChart as ScatterIcon, TrendingUp, Palette, FileJson, Image as ImageIcon, RotateCcw, LayoutDashboard, Pipette, Maximize, X, Filter, Plus, Trash2, Eye, EyeOff, Info, RefreshCw, Palette as PaletteIcon, Layers, Factory, CheckCircle2, Wand2, Hash, ArrowRight, Binary, ListFilter, Eraser, PlusCircle, Target, MousePointer2, Search, Camera, Loader2, GripVertical, Repeat, Sliders, AlertTriangle, Command } from 'lucide-react';
import { Product, PropertyValue } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

interface PlotFilter {
  id: string;
  key: string;
  operator: '>' | '<' | '>=' | '<=' | 'between';
  value: number | '';
  value2: number | '';
}

const DEFAULT_PALETTE = [
  '#10b981', // Emerald
  '#3b82f6', // Blue
  '#f59e0b', // Amber
  '#ef4444', // Red
  '#8b5cf6', // Violet
  '#ec4899', // Pink
  '#06b6d4', // Cyan
  '#84cc16', // Lime
  '#f97316', // Orange
  '#6366f1', // Indigo
];

const COLOR_SCHEMES = [
  { id: 'emerald', name: 'Resin Classic', colors: ['#10b981', '#059669', '#047857', '#065f46', '#064e3b', '#34d399'] },
  { id: 'vibrant', name: 'Scientific Vibrant', colors: ['#6366f1', '#8b5cf6', '#ec4899', '#f43f5e', '#f97316', '#eab308'] },
  { id: 'ocean', name: 'Deep Ocean', colors: ['#0c4a6e', '#075985', '#0369a1', '#0284c7', '#0ea5e9', '#38bdf8'] },
  { id: 'pastel', name: 'Soft Material', colors: ['#a7f3d0', '#bfdbfe', '#fde68a', '#fecaca', '#ddd6fe', '#fbcfe8'] },
  { id: 'industrial', name: 'Industrial Gray', colors: ['#475569', '#64748b', '#94a3b8', '#cbd5e1', '#e2e8f0', '#1e293b'] }
];

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const { t, tProp } = useLanguage();
  const { theme } = useTheme();
  const chartRef = useRef<HTMLDivElement>(null);

  const [showConfig, setShowConfig] = useState(true);
  const [isExporting, setIsExporting] = useState(false);
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('gradeName');
  const [yAxisKey, setYAxisKey] = useState<string>('');
  const [legendSearch, setLegendSearch] = useState('');

  const [xMin, setXMin] = useState<number | ''>('');
  const [xMax, setXMax] = useState<number | ''>('');
  const [yMin, setYMin] = useState<number | ''>('');
  const [yMax, setYMax] = useState<number | ''>('');

  const [plotFilters, setPlotFilters] = useState<PlotFilter[]>([]);

  const [showTrendline, setShowTrendline] = useState(false);
  const [trendlineColor, setTrendlineColor] = useState('#ef4444');
  const [trendlineWidth, setTrendlineWidth] = useState(3);
  const [trendlineStyle, setTrendlineStyle] = useState<'solid' | 'dashed' | 'dotted'>('solid');

  const [groupByKey, setGroupByKey] = useState<string>('');
  const [groupColors, setGroupColors] = useState<Record<string, string>>({});
  const [hiddenGroups, setHiddenGroups] = useState<Set<string>>(new Set());
  const [highlightedGroup, setHighlightedGroup] = useState<string | null>(null);
  const [activeSchemeId, setActiveSchemeId] = useState('emerald');

  // Robustly identify keys that have numeric values across the dataset
  const numericKeys = useMemo(() => {
     const keys = new Set<string>();
     data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
           // Handle both raw numbers and object structures
           const val = typeof v === 'object' && v !== null && 'value' in v ? v.value : v;
           if (typeof val === 'number' || (!isNaN(Number(val)) && val !== '' && val !== null && val !== undefined)) {
               keys.add(k);
           }
        });
     });
     // Prioritize common resin properties for sorting
     const priority = ['密度', 'Density', '熔体质量流动速率', 'Melt Flow Rate', '拉伸屈服应力', 'Tensile Strength'];
     return Array.from(keys).sort((a, b) => {
         const idxA = priority.indexOf(a);
         const idxB = priority.indexOf(b);
         if (idxA !== -1 && idxB !== -1) return idxA - idxB;
         if (idxA !== -1) return -1;
         if (idxB !== -1) return 1;
         return a.localeCompare(b);
     });
  }, [data]);

  const categoricalKeys = useMemo(() => {
    const keys = new Set<string>(['manufacturer']);
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            const val = typeof v === 'object' && v !== null && 'value' in v ? v.value : v;
            if (typeof val === 'string' && isNaN(Number(val))) {
                keys.add(k);
            }
        });
    });
    return Array.from(keys).sort();
  }, [data]);

  // Ensure Y-Axis is set immediately when keys are available
  useEffect(() => {
      if (!yAxisKey && numericKeys.length > 0) {
          // Default to first numeric key (which is sorted by priority)
          setYAxisKey(numericKeys[0]);
      }
  }, [numericKeys, yAxisKey]);

  // If chart is scatter, ensure X-axis is numeric, else fallback
  useEffect(() => {
    if (chartType === 'scatter') {
        if (xAxisKey === 'gradeName' || !numericKeys.includes(xAxisKey)) {
            // Pick a different key than Y if possible
            const nextKey = numericKeys.find(k => k !== yAxisKey) || numericKeys[0] || '';
            setXAxisKey(nextKey);
        }
    } else {
        // Bar charts usually use categorical X axis (gradeName)
        if (xAxisKey !== 'gradeName') setXAxisKey('gradeName');
    }
  }, [chartType, numericKeys, yAxisKey]);

  const propertyStats = useMemo(() => {
    const stats: Record<string, { min: number; max: number; unit?: string }> = {};
    numericKeys.forEach(key => {
        let min = Infinity;
        let max = -Infinity;
        let unit: string | undefined;

        data.forEach(p => {
            const prop = p.properties[key];
            const rawVal = prop?.value;
            const val = Number(rawVal);

            if (!isNaN(val) && rawVal !== '' && rawVal !== undefined && rawVal !== null) {
                if (val < min) min = val;
                if (val > max) max = val;
                if (!unit && prop.unit) unit = prop.unit;
            }
        });
        if (min !== Infinity) {
            stats[key] = { min, max, unit };
        }
    });
    return stats;
  }, [data, numericKeys]);

  const chartData = useMemo(() => {
    // First apply filters
    const filtered = data.filter(product => {
        return plotFilters.every(f => {
            if (!f.key || f.value === '') return true;
            const prop = product.properties[f.key];
            const val = Number(prop?.value);
            if (isNaN(val)) return false;

            const v1 = Number(f.value);
            const v2 = f.value2 !== '' ? Number(f.value2) : Infinity;

            switch (f.operator) {
                case '>': return val > v1;
                case '<': return val < v1;
                case '>=': return val >= v1;
                case '<=': return val <= v1;
                case 'between': return val >= v1 && val <= v2;
                default: return true;
            }
        });
    });

    // Then map to flat structure for Recharts
    return filtered.map(p => {
        const item: any = {
            id: p.id,
            gradeName: p.gradeName,
            manufacturer: p.manufacturer,
        };
        // Flatten properties
        Object.entries(p.properties).forEach(([k, v]) => {
            const num = Number(v.value);
            // Store as number if valid, else string
            item[k] = !isNaN(num) && v.value !== '' && v.value !== null ? num : v.value;
        });
        return item;
    });
  }, [data, plotFilters]);

  const uniqueGroups = useMemo(() => {
    if (!groupByKey) return [];
    const groups = new Set<string>();
    chartData.forEach((item: any) => {
        const val = item[groupByKey];
        groups.add(val !== undefined && val !== null ? String(val) : 'Unknown');
    });
    return Array.from(groups).sort();
  }, [groupByKey, chartData]);

  const visibleChartData = useMemo(() => {
    if (!groupByKey) return chartData;
    return chartData.filter(d => !hiddenGroups.has(String(d[groupByKey] || 'Unknown')));
  }, [chartData, groupByKey, hiddenGroups]);

  // --- Derived State for Colors & Trendlines ---

  const trendlineSegment = useMemo(() => {
    if (!showTrendline || chartType !== 'scatter' || !xAxisKey || !yAxisKey) return null;

    const validPoints = visibleChartData.filter(d => 
        typeof d[xAxisKey] === 'number' && typeof d[yAxisKey] === 'number'
    );

    if (validPoints.length < 2) return null;

    const n = validPoints.length;
    let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
    let minX = Infinity, maxX = -Infinity;

    validPoints.forEach(p => {
        const x = p[xAxisKey];
        const y = p[yAxisKey];
        sumX += x; sumY += y; sumXY += x * y; sumX2 += x * x;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
    });

    const denominator = n * sumX2 - sumX * sumX;
    if (denominator === 0) return null; 

    const slope = (n * sumXY - sumX * sumY) / denominator;
    const intercept = (sumY - slope * sumX) / n;

    // Extend line slightly beyond min/max
    const padding = (maxX - minX) * 0.05; 

    return [
        { [xAxisKey]: minX - padding, [yAxisKey]: slope * (minX - padding) + intercept, isTrend: true },
        { [xAxisKey]: maxX + padding, [yAxisKey]: slope * (maxX + padding) + intercept, isTrend: true }
    ];
  }, [visibleChartData, xAxisKey, yAxisKey, showTrendline, chartType]);

  useEffect(() => {
    if (uniqueGroups.length > 0) {
        setGroupColors(prev => {
            const next = { ...prev };
            const currentPalette = COLOR_SCHEMES.find(s => s.id === activeSchemeId)?.colors || DEFAULT_PALETTE;
            uniqueGroups.forEach((group, index) => {
                if (!next[group]) next[group] = currentPalette[index % currentPalette.length];
            });
            return next;
        });
    }
  }, [uniqueGroups, activeSchemeId]);

  // --- Handlers ---

  const toggleGroupVisibility = (group: string, isAltKey: boolean = false) => {
    if (isAltKey) {
        const others = uniqueGroups.filter(g => g !== group);
        setHiddenGroups(new Set(others));
    } else {
        setHiddenGroups(prev => {
          const next = new Set(prev);
          if (next.has(group)) next.delete(group);
          else next.add(group);
          return next;
        });
    }
  };

  const handleDownload = async (type: 'json' | 'png') => {
    if (type === 'json') {
        const blob = new Blob([JSON.stringify(visibleChartData, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = `resindb_data_${Date.now()}.json`; a.click();
    } else if (type === 'png' && chartRef.current) {
        setIsExporting(true);
        try {
          await new Promise(resolve => setTimeout(resolve, 100)); // Allow render
          const canvas = await html2canvas(chartRef.current, { 
            backgroundColor: theme === 'dark' ? '#0f172a' : '#ffffff',
            scale: 2, 
            logging: false,
            useCORS: true, 
            ignoreElements: (el) => el.classList.contains('no-capture')
          });
          const a = document.createElement('a');
          a.href = canvas.toDataURL('image/png', 1.0); 
          a.download = `resindb_chart_${new Date().toISOString().slice(0,10)}.png`; 
          a.click();
        } catch (err) {
          console.error("Export failed:", err);
        } finally {
          setIsExporting(false);
        }
    }
  };

  const getLabelWithUnit = (key: string) => {
      const label = tProp(key);
      const unit = propertyStats[key]?.unit;
      return unit ? `${label} (${unit})` : label;
  };

  // --- Render Helpers ---

  const CustomTooltipContent = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const d = payload[0].payload;
      if (d.isTrend) return <div className="px-2 py-1 bg-slate-800 text-white text-xs rounded">Trendline</div>;

      const product = data.find(p => p.id === d.id);
      if (!product) return null;

      // Find top distinct properties to show
      const additionalProps = Object.entries(product.properties)
        .filter(([k]) => k !== xAxisKey && k !== yAxisKey && k !== groupByKey && numericKeys.includes(k))
        .slice(0, 3);

      return (
        <div className="p-4 bg-white/95 dark:bg-slate-900/95 backdrop-blur-xl border border-slate-200 dark:border-slate-700 rounded-2xl shadow-xl min-w-[200px] border-l-4" style={{ borderLeftColor: groupByKey ? groupColors[String(d[groupByKey])] : '#10b981' }}>
          <div className="flex items-center justify-between gap-4 mb-2">
            <p className="font-bold text-slate-800 dark:text-white text-sm">{product.gradeName}</p>
            <div className="flex items-center gap-1 bg-slate-100 dark:bg-slate-800 px-2 py-0.5 rounded-full">
                <Factory size={10} className="text-slate-400" />
                <span className="text-[10px] font-bold text-slate-500 uppercase">{product.manufacturer}</span>
            </div>
          </div>

          <div className="space-y-1.5 pt-2 border-t border-slate-100 dark:border-slate-800">
             <div className="flex justify-between gap-4">
                <span className="text-xs text-slate-500 font-medium">{tProp(yAxisKey)}</span>
                <span className="text-sm font-black text-emerald-600 dark:text-emerald-400 font-mono">
                    {d[yAxisKey]} {propertyStats[yAxisKey]?.unit && <span className="text-[9px] opacity-60 ml-0.5">{propertyStats[yAxisKey]?.unit}</span>}
                </span>
             </div>
             {chartType === 'scatter' && xAxisKey !== 'gradeName' && (
               <div className="flex justify-between gap-4">
                  <span className="text-xs text-slate-500 font-medium">{tProp(xAxisKey)}</span>
                  <span className="text-sm font-black text-blue-600 dark:text-blue-400 font-mono">
                      {d[xAxisKey]} {propertyStats[xAxisKey]?.unit && <span className="text-[9px] opacity-60 ml-0.5">{propertyStats[xAxisKey]?.unit}</span>}
                  </span>
               </div>
             )}
             {additionalProps.map(([k, v]) => (
                 <div key={k} className="flex justify-between gap-4">
                    <span className="text-xs text-slate-400">{tProp(k)}</span>
                    <span className="text-xs font-bold text-slate-700 dark:text-slate-300 font-mono">
                        {v.value}
                    </span>
                 </div>
             ))}
          </div>
        </div>
      );
    }
    return null;
  };

  const RenderCustomLegend = (props: any) => {
    const { payload } = props;
    if (!payload || !groupByKey) return null;

    const items = uniqueGroups.filter(g => g.toLowerCase().includes(legendSearch.toLowerCase()));

    return (
      <div className="flex flex-col items-center mb-4 gap-2 animate-in fade-in duration-500 bg-white/60 dark:bg-slate-900/60 backdrop-blur-md border border-slate-200 dark:border-slate-800 rounded-2xl p-3 shadow-lg mx-4">
        <div className="flex w-full items-center gap-2 px-1">
            <Search size={12} className="text-slate-400" />
            <input 
                value={legendSearch} 
                onChange={(e) => setLegendSearch(e.target.value)} 
                className="flex-1 bg-transparent text-[10px] font-bold outline-none" 
                placeholder="Filter groups..." 
            />
            {legendSearch && <button onClick={() => setLegendSearch('')}><X size={10} /></button>}
        </div>
        <div className="flex flex-wrap justify-center gap-2 max-h-32 overflow-y-auto custom-scrollbar w-full">
            {items.map((group, idx) => {
                const isHidden = hiddenGroups.has(group);
                return (
                    <button 
                        key={group} 
                        onClick={(e) => toggleGroupVisibility(group, e.altKey)}
                        onMouseEnter={() => !isHidden && setHighlightedGroup(group)}
                        onMouseLeave={() => setHighlightedGroup(null)}
                        className={`flex items-center gap-1.5 px-2 py-1 rounded-lg border text-[10px] font-bold transition-all ${isHidden ? 'bg-slate-100 dark:bg-slate-800 text-slate-400 border-transparent grayscale' : 'bg-white dark:bg-slate-900 border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 hover:border-emerald-400'}`}
                    >
                        <div className="w-2 h-2 rounded-full" style={{ backgroundColor: groupColors[group] || '#ccc' }}></div>
                        {group}
                    </button>
                );
            })}
        </div>
      </div>
    );
  };

  // Theme colors
  const gridColor = theme === 'dark' ? '#334155' : '#e2e8f0'; 
  const axisColor = theme === 'dark' ? '#94a3b8' : '#64748b'; 

  // --- EFFECTIVE Y-AXIS SAFEGUARD ---
  // Ensure we always have a valid Y-Axis key to render
  const effectiveYAxisKey = yAxisKey || numericKeys[0] || '';

  return (
    <div className="flex flex-col md:flex-row h-full gap-4 overflow-hidden">
      {/* Settings Panel */}
      <div className={`flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl transition-all duration-500 ease-out shrink-0 overflow-hidden shadow-xl ${showConfig ? 'w-full md:w-80 opacity-100 translate-x-0' : 'w-0 opacity-0 -translate-x-10 border-0 pointer-events-none'}`}>
        <div className="p-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50/80 dark:bg-slate-950/50 backdrop-blur-sm">
          <div className="flex items-center gap-2 font-black text-sm text-slate-800 dark:text-white uppercase tracking-widest">
            <Sliders size={16} className="text-emerald-500" />
            {t('chartConfig')}
          </div>
          <button onClick={() => setShowConfig(false)} className="md:hidden text-slate-400 hover:text-slate-600">
            <X size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-5 custom-scrollbar space-y-8">
          {/* Chart Type Selection */}
          <div className="space-y-3">
             <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <LayoutDashboard size={12} /> {t('chartType')}
             </label>
             <div className="flex gap-3">
                <button onClick={() => setChartType('bar')} className={`flex-1 flex flex-col items-center gap-2 p-4 rounded-2xl border-2 transition-all duration-200 ${chartType === 'bar' ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 shadow-md' : 'border-slate-100 dark:border-slate-800 text-slate-400 hover:border-emerald-200 dark:hover:border-emerald-800'}`}>
                  <BarChart2 size={24} /> <span className="text-[10px] font-black uppercase tracking-wider">{t('barChart')}</span>
                </button>
                <button onClick={() => setChartType('scatter')} className={`flex-1 flex flex-col items-center gap-2 p-4 rounded-2xl border-2 transition-all duration-200 ${chartType === 'scatter' ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 shadow-md' : 'border-slate-100 dark:border-slate-800 text-slate-400 hover:border-emerald-200 dark:hover:border-emerald-800'}`}>
                  <ScatterIcon size={24} /> <span className="text-[10px] font-black uppercase tracking-wider">{t('scatterChart')}</span>
                </button>
             </div>
          </div>

          {/* Filters */}
          <div className="space-y-4 pt-2 border-t border-slate-100 dark:border-slate-800">
            <div className="flex items-center justify-between">
                <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                    <Filter size={12} /> {t('dataFilters')}
                </label>
                <button onClick={() => setPlotFilters([...plotFilters, { id: Date.now().toString(), key: numericKeys[0], operator: '>=', value: '', value2: '' }])} className="flex items-center gap-1 px-2 py-1 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 rounded-lg hover:bg-emerald-100 dark:hover:bg-emerald-900/30 transition-colors text-[10px] font-bold uppercase tracking-wider border border-emerald-100 dark:border-emerald-800">
                    <Plus size={10} /> Add
                </button>
            </div>
            {plotFilters.length === 0 ? (
                <div className="text-center py-6 bg-slate-50/50 dark:bg-slate-900/50 rounded-2xl border border-dashed border-slate-200 dark:border-slate-800">
                    <p className="text-[10px] text-slate-400 font-medium uppercase tracking-wide">{t('noFilters')}</p>
                </div>
            ) : (
                <div className="space-y-3">
                    {plotFilters.map((filter, idx) => (
                        <div key={filter.id} className="p-3 bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-sm space-y-2">
                            <div className="flex items-center gap-2">
                                <div className="w-5 h-5 rounded bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-[10px] font-bold text-slate-500">{idx+1}</div>
                                <select value={filter.key} onChange={(e) => { const newF = [...plotFilters]; newF[idx].key = e.target.value; setPlotFilters(newF); }} className="flex-1 bg-transparent text-xs font-bold outline-none">
                                    {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                                </select>
                                <button onClick={() => setPlotFilters(plotFilters.filter((_, i) => i !== idx))}><Trash2 size={12} className="text-slate-300 hover:text-rose-500" /></button>
                            </div>
                            <div className="flex items-center gap-2">
                                <select value={filter.operator} onChange={(e) => { const newF = [...plotFilters]; newF[idx].operator = e.target.value as any; setPlotFilters(newF); }} className="bg-slate-50 dark:bg-slate-900 border rounded text-[10px] p-1 font-mono">
                                    <option value=">">&gt;</option><option value="<">&lt;</option><option value=">=">&ge;</option><option value="<=">&le;</option><option value="between">Range</option>
                                </select>
                                <input type="number" value={filter.value} onChange={(e) => { const newF = [...plotFilters]; newF[idx].value = Number(e.target.value); setPlotFilters(newF); }} className="flex-1 bg-slate-50 dark:bg-slate-900 border rounded text-[10px] p-1 font-mono" placeholder="Value" />
                                {filter.operator === 'between' && <input type="number" value={filter.value2} onChange={(e) => { const newF = [...plotFilters]; newF[idx].value2 = Number(e.target.value); setPlotFilters(newF); }} className="flex-1 bg-slate-50 dark:bg-slate-900 border rounded text-[10px] p-1 font-mono" placeholder="Max" />}
                            </div>
                        </div>
                    ))}
                </div>
            )}
          </div>

          {/* Axes */}
          <div className="space-y-4 pt-2 border-t border-slate-100 dark:border-slate-800">
            <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <RotateCcw size={12} /> {t('axisMapping')}
            </label>
            <div className="space-y-3 bg-slate-50 dark:bg-slate-950/30 p-3 rounded-2xl border border-slate-100 dark:border-slate-800">
              <div className="space-y-1.5">
                <span className="text-[10px] font-bold text-emerald-600 dark:text-emerald-500 ml-1 uppercase tracking-widest">{t('yAxis')} (Vertical)</span>
                <div className="relative">
                    <select value={yAxisKey} onChange={(e) => setYAxisKey(e.target.value)} className="w-full pl-3 pr-3 py-2.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl text-xs font-bold outline-none focus:border-emerald-500 transition-colors shadow-sm appearance-none cursor-pointer">
                        {numericKeys.length > 0 ? numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>) : <option disabled>No numeric data available</option>}
                    </select>
                </div>
              </div>
              {chartType === 'scatter' && (
                <div className="space-y-1.5">
                    <span className="text-[10px] font-bold text-blue-600 dark:text-blue-500 ml-1 uppercase tracking-widest">{t('xAxis')} (Horizontal)</span>
                    <div className="relative">
                        <select value={xAxisKey} onChange={(e) => setXAxisKey(e.target.value)} className="w-full pl-3 pr-3 py-2.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl text-xs font-bold outline-none focus:border-emerald-500 transition-colors shadow-sm appearance-none cursor-pointer">
                            {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                        </select>
                    </div>
                </div>
              )}
            </div>
          </div>

          {/* Grouping */}
          <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
             <div className="flex items-center justify-between">
                <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2"><PaletteIcon size={12} /> {t('styleGrouping')}</label>
             </div>
             <div className="space-y-1.5">
               <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1">{t('groupBy')}</span>
               <div className="relative">
                   <select value={groupByKey} onChange={(e) => setGroupByKey(e.target.value)} className="w-full pl-3 pr-8 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-xs font-bold outline-none focus:border-emerald-500 transition-colors appearance-none cursor-pointer">
                       <option value="">{t('none')}</option>
                       {categoricalKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                   </select>
                   <ChevronUp size={12} className="absolute right-3 top-3 pointer-events-none text-slate-400 rotate-180" />
               </div>
             </div>
             {groupByKey && (
                 <div className="grid grid-cols-1 gap-1.5 p-2 bg-slate-50 dark:bg-slate-900/50 rounded-xl">
                    {COLOR_SCHEMES.map(scheme => (
                        <button key={scheme.id} onClick={() => setActiveSchemeId(scheme.id)} className={`w-full flex h-6 rounded-lg overflow-hidden border ${activeSchemeId === scheme.id ? 'border-emerald-500 ring-1 ring-emerald-500' : 'border-transparent'}`}>
                            {scheme.colors.map(c => <div key={c} style={{backgroundColor: c}} className="flex-1 h-full" />)}
                        </button>
                    ))}
                 </div>
             )}
          </div>

          <div className="pt-6 border-t border-slate-100 dark:border-slate-800 grid grid-cols-2 gap-3 pb-4">
            <button onClick={() => handleDownload('json')} className="flex items-center justify-center gap-2 p-3 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-xl text-[10px] font-bold text-slate-600 dark:text-slate-300 transition-colors uppercase tracking-wider"><FileJson size={14} /> JSON</button>
            <button onClick={() => handleDownload('png')} disabled={isExporting} className="flex items-center justify-center gap-2 p-3 bg-slate-900 dark:bg-emerald-600 hover:bg-slate-800 dark:hover:bg-emerald-500 disabled:opacity-70 text-white rounded-xl text-[10px] font-bold transition-all uppercase tracking-wider shadow-lg">{isExporting ? <Loader2 size={14} className="animate-spin" /> : <ImageIcon size={14} />} EXPORT</button>
          </div>
        </div>
      </div>

      {/* Chart Canvas Area */}
      <div className="flex-1 flex flex-col bg-white/50 dark:bg-slate-900/50 backdrop-blur-xl border border-slate-200 dark:border-slate-800 rounded-[2rem] relative min-h-[500px] shadow-2xl overflow-hidden">

        {/* Floating Toolbar */}
        <div className="absolute top-6 right-6 z-30 flex gap-2">
             {!showConfig && <button onClick={() => setShowConfig(true)} className="p-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-slate-500 hover:text-emerald-500 shadow-xl transition-all hover:scale-105 active:scale-95 no-capture group"><Settings size={20} className="group-hover:rotate-90 transition-transform duration-500" /></button>}
        </div>

        <div className="flex-1 p-6 md:p-8 flex flex-col min-h-0" ref={chartRef}>
            <div className="mb-6 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
               <div className="flex flex-col">
                   <h2 className="text-xl md:text-2xl font-black text-slate-800 dark:text-white flex items-center gap-3 tracking-tight">
                      {chartType === 'bar' ? <BarChart2 size={24} className="text-emerald-500" /> : <ScatterIcon size={24} className="text-emerald-500" />}
                      {effectiveYAxisKey ? (
                          <span className="bg-clip-text text-transparent bg-gradient-to-r from-slate-800 to-slate-500 dark:from-white dark:to-slate-400">
                            {getLabelWithUnit(effectiveYAxisKey)} <span className="text-slate-300 mx-1">vs</span> {chartType === 'bar' ? tProp('牌号') : getLabelWithUnit(xAxisKey)}
                          </span>
                      ) : <span className="text-slate-400">Select Properties</span>}
                   </h2>
               </div>

               <div className="flex items-center gap-2">
                    <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest bg-slate-100 dark:bg-slate-800 px-3 py-1 rounded-full">{t('showing')}</span>
                    <div className="flex items-center gap-1.5 px-4 py-1.5 bg-slate-900 dark:bg-emerald-600 text-white rounded-full shadow-lg">
                        <span className="text-sm font-black">{visibleChartData.length}</span>
                        <span className="text-[10px] opacity-60 font-bold">/</span>
                        <span className="text-xs font-bold opacity-80">{data.length}</span>
                    </div>
               </div>
            </div>

            <div className="flex-1 w-full min-h-0 relative rounded-3xl overflow-hidden bg-white/40 dark:bg-slate-950/20 border border-slate-100/50 dark:border-slate-800/50">
                {!effectiveYAxisKey || visibleChartData.length === 0 ? (
                    <div className="absolute inset-0 flex flex-col items-center justify-center bg-white/60 dark:bg-slate-950/60 backdrop-blur-sm z-40">
                        <div className="p-8 bg-white dark:bg-slate-900 rounded-[2rem] shadow-2xl border border-slate-200 dark:border-slate-800 flex flex-col items-center gap-4 animate-in zoom-in-95 max-w-sm text-center">
                            <div className="w-20 h-20 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center mb-2"><ListFilter size={40} className="text-slate-300 dark:text-slate-600" /></div>
                            <div>
                                <p className="text-xl font-black text-slate-800 dark:text-white mb-2">No Matching Data</p>
                                <p className="text-sm text-slate-500 leading-relaxed font-medium">
                                    {!effectiveYAxisKey ? "Please select a Y-Axis property to visualize." : "Your filters match 0 records. Try resetting filters."}
                                </p>
                            </div>
                        </div>
                    </div>
                ) : (
                    <ResponsiveContainer width="100%" height="100%">
                        {chartType === 'bar' ? (
                            <BarChart data={visibleChartData} margin={{ top: 20, right: 30, left: 20, bottom: 60 }}>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={gridColor} strokeWidth={1} />
                                <XAxis dataKey="gradeName" angle={-45} textAnchor="end" interval={0} height={80} fontSize={10} stroke={axisColor} tick={{ fill: axisColor, fontWeight: 600 }} tickLine={{ stroke: axisColor }} padding={{ left: 20, right: 20 }} />
                                <YAxis fontSize={10} stroke={axisColor} tick={{ fill: axisColor, fontWeight: 600 }} tickLine={{ stroke: axisColor }} domain={['auto', 'auto']} label={{ value: getLabelWithUnit(effectiveYAxisKey), angle: -90, position: 'insideLeft', offset: 0, fontSize: 10, fill: axisColor, fontWeight: 700 }} padding={{ top: 20, bottom: 0 }} />
                                <Tooltip cursor={{ fill: theme === 'dark' ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.03)' }} content={<CustomTooltipContent />} />
                                {groupByKey && <Legend verticalAlign="top" content={RenderCustomLegend} wrapperStyle={{ top: -10 }} />}
                                <Bar dataKey={effectiveYAxisKey} radius={[6, 6, 0, 0]} animationDuration={1000} minPointSize={2}>
                                    {visibleChartData.map((entry, index) => {
                                        const group = String(entry[groupByKey] || 'Unknown');
                                        const isHighlighted = highlightedGroup === null || highlightedGroup === group;
                                        return <Cell key={`cell-${index}`} fill={groupByKey ? groupColors[group] : DEFAULT_PALETTE[index % DEFAULT_PALETTE.length]} fillOpacity={isHighlighted ? 1 : 0.2} />;
                                    })}
                                </Bar>
                            </BarChart>
                        ) : (
                            <ComposedChart margin={{ top: 30, right: 30, bottom: 30, left: 30 }}>
                                <CartesianGrid strokeDasharray="3 3" stroke={gridColor} strokeWidth={1} />
                                <XAxis 
                                    type="number" 
                                    dataKey={xAxisKey} 
                                    name={tProp(xAxisKey)} 
                                    fontSize={10} 
                                    domain={[xMin === '' ? 'auto' : xMin, xMax === '' ? 'auto' : xMax]} 
                                    stroke={axisColor} 
                                    tick={{ fill: axisColor, fontWeight: 600 }}
                                    tickLine={{ stroke: axisColor }}
                                    label={{ value: getLabelWithUnit(xAxisKey), position: 'bottom', offset: 0, fontSize: 11, fill: axisColor, fontWeight: 700 }}
                                    padding={{ left: 20, right: 20 }}
                                />
                                <YAxis 
                                    type="number" 
                                    dataKey={effectiveYAxisKey} 
                                    name={tProp(effectiveYAxisKey)} 
                                    fontSize={10} 
                                    domain={[yMin === '' ? 'auto' : yMin, yMax === '' ? 'auto' : yMax]} 
                                    stroke={axisColor}
                                    tick={{ fill: axisColor, fontWeight: 600 }}
                                    tickLine={{ stroke: axisColor }}
                                    label={{ value: getLabelWithUnit(effectiveYAxisKey), angle: -90, position: 'insideLeft', offset: 10, fontSize: 11, fill: axisColor, fontWeight: 700 }} 
                                    padding={{ top: 20, bottom: 20 }}
                                />
                                <ZAxis range={[100, 500]} />
                                <Tooltip cursor={{ strokeDasharray: '3 3', stroke: axisColor, strokeWidth: 1 }} content={<CustomTooltipContent />} />
                                {groupByKey && <Legend verticalAlign="top" content={RenderCustomLegend} wrapperStyle={{ top: -10 }} />}

                                <Scatter name="Resin Samples" data={visibleChartData} animationDuration={1000} isAnimationActive={true}>
                                    {visibleChartData.map((entry, index) => {
                                        const group = String(entry[groupByKey] || 'Unknown');
                                        const isHighlighted = highlightedGroup === null || highlightedGroup === group;
                                        const fillColor = groupByKey ? groupColors[group] : '#10b981';
                                        return (
                                            <Cell 
                                                key={`cell-${index}`} 
                                                fill={fillColor} 
                                                fillOpacity={isHighlighted ? 0.9 : 0.6} 
                                                stroke={theme === 'dark' ? '#fff' : '#fff'}
                                                strokeWidth={1.5}
                                                strokeOpacity={isHighlighted ? 0.8 : 0.4}
                                            />
                                        );
                                    })}
                                </Scatter>

                                {trendlineSegment && (
                                    <Line 
                                        type="monotone" 
                                        data={trendlineSegment} 
                                        dataKey={effectiveYAxisKey} 
                                        stroke={trendlineColor} 
                                        strokeWidth={trendlineWidth} 
                                        strokeDasharray={trendlineStyle === 'dashed' ? '8 8' : trendlineStyle === 'dotted' ? '3 3' : '0'} 
                                        dot={false}
                                        activeDot={false}
                                        isAnimationActive={false}
                                        legendType="none"
                                        strokeLinecap="round"
                                    />
                                )}
                            </ComposedChart>
                        )}
                    </ResponsiveContainer>
                )}
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  Cell,
  Line,
  ZAxis
} from 'recharts';
import { Settings, BarChart2, ScatterChart as ScatterIcon, LayoutDashboard, X, Filter, Plus, Trash2, Palette as PaletteIcon, Factory, Search, FileJson, Image as ImageIcon, RotateCcw, ChevronUp, Loader2, ListFilter } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import html2canvas from 'html2canvas';

interface DataVisualizerProps {
  data: Product[];
}

interface PlotFilter {
  id: string;
  key: string;
  operator: '>' | '<' | '>=' | '<=' | 'between';
  value: number | '';
  value2: number | '';
}

const DEFAULT_PALETTE = [
  '#10b981', // Emerald
  '#3b82f6', // Blue
  '#f59e0b', // Amber
  '#ef4444', // Red
  '#8b5cf6', // Violet
  '#ec4899', // Pink
  '#06b6d4', // Cyan
  '#84cc16', // Lime
  '#f97316', // Orange
  '#6366f1', // Indigo
];

const COLOR_SCHEMES = [
  { id: 'emerald', name: 'Resin Classic', colors: ['#10b981', '#059669', '#047857', '#065f46', '#064e3b', '#34d399'] },
  { id: 'vibrant', name: 'Scientific Vibrant', colors: ['#6366f1', '#8b5cf6', '#ec4899', '#f43f5e', '#f97316', '#eab308'] },
  { id: 'ocean', name: 'Deep Ocean', colors: ['#0c4a6e', '#075985', '#0369a1', '#0284c7', '#0ea5e9', '#38bdf8'] },
  { id: 'pastel', name: 'Soft Material', colors: ['#a7f3d0', '#bfdbfe', '#fde68a', '#fecaca', '#ddd6fe', '#fbcfe8'] },
  { id: 'industrial', name: 'Industrial Gray', colors: ['#475569', '#64748b', '#94a3b8', '#cbd5e1', '#e2e8f0', '#1e293b'] }
];

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const { t, tProp } = useLanguage();
  const { theme } = useTheme();
  const chartRef = useRef<HTMLDivElement>(null);

  const [showConfig, setShowConfig] = useState(true);
  const [isExporting, setIsExporting] = useState(false);
  const [chartType, setChartType] = useState<'bar' | 'scatter'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('gradeName');
  const [yAxisKey, setYAxisKey] = useState<string>('');
  const [legendSearch, setLegendSearch] = useState('');

  const [xMin, setXMin] = useState<number | ''>('');
  const [xMax, setXMax] = useState<number | ''>('');
  const [yMin, setYMin] = useState<number | ''>('');
  const [yMax, setYMax] = useState<number | ''>('');

  const [plotFilters, setPlotFilters] = useState<PlotFilter[]>([]);

  const [showTrendline, setShowTrendline] = useState(false);
  const [trendlineColor, setTrendlineColor] = useState('#ef4444');
  const [trendlineWidth, setTrendlineWidth] = useState(3);
  const [trendlineStyle, setTrendlineStyle] = useState<'solid' | 'dashed' | 'dotted'>('solid');

  const [groupByKey, setGroupByKey] = useState<string>('');
  const [groupColors, setGroupColors] = useState<Record<string, string>>({});
  const [hiddenGroups, setHiddenGroups] = useState<Set<string>>(new Set());
  const [highlightedGroup, setHighlightedGroup] = useState<string | null>(null);
  const [activeSchemeId, setActiveSchemeId] = useState('emerald');

  // Robustly identify keys that have numeric values across the dataset
  const numericKeys = useMemo(() => {
     const keys = new Set<string>();
     data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
           // Handle both raw numbers and object structures
           const val = typeof v === 'object' && v !== null && 'value' in v ? v.value : v;
           if (typeof val === 'number' || (!isNaN(parseFloat(String(val))) && val !== '' && val !== null && val !== undefined)) {
               keys.add(k);
           }
        });
     });
     // Prioritize common resin properties for sorting
     const priority = ['密度', 'Density', '熔体质量流动速率', 'Melt Flow Rate', '拉伸屈服应力', 'Tensile Strength'];
     return Array.from(keys).sort((a, b) => {
         const idxA = priority.indexOf(a);
         const idxB = priority.indexOf(b);
         if (idxA !== -1 && idxB !== -1) return idxA - idxB;
         if (idxA !== -1) return -1;
         if (idxB !== -1) return 1;
         return a.localeCompare(b);
     });
  }, [data]);

  const categoricalKeys = useMemo(() => {
    const keys = new Set<string>(['manufacturer']);
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            const val = typeof v === 'object' && v !== null && 'value' in v ? v.value : v;
            if (typeof val === 'string' && isNaN(parseFloat(String(val)))) {
                keys.add(k);
            }
        });
    });
    return Array.from(keys).sort();
  }, [data]);

  // Ensure Y-Axis is set immediately when keys are available
  useEffect(() => {
      if (!yAxisKey && numericKeys.length > 0) {
          setYAxisKey(numericKeys[0]);
      }
  }, [numericKeys, yAxisKey]);

  // Ensure X-Axis is set correctly based on chart type
  useEffect(() => {
    if (chartType === 'scatter') {
        // For scatter, X must be numeric. If current X is 'gradeName' or not in numericKeys, switch it.
        if (xAxisKey === 'gradeName' || !numericKeys.includes(xAxisKey)) {
            // Try to find a numeric key that isn't the Y axis, or default to first numeric
            const nextKey = numericKeys.find(k => k !== yAxisKey) || numericKeys[0] || '';
            if (nextKey) setXAxisKey(nextKey);
        }
    } else {
        // Bar charts default to categorical X (gradeName)
        if (xAxisKey !== 'gradeName') setXAxisKey('gradeName');
    }
  }, [chartType, numericKeys, yAxisKey, xAxisKey]);

  const propertyStats = useMemo(() => {
    const stats: Record<string, { min: number; max: number; unit?: string }> = {};
    numericKeys.forEach(key => {
        let min = Infinity;
        let max = -Infinity;
        let unit: string | undefined;

        data.forEach(p => {
            const prop = p.properties[key];
            const rawVal = prop?.value;
            const val = parseFloat(String(rawVal));

            if (!isNaN(val) && rawVal !== '' && rawVal !== undefined && rawVal !== null) {
                if (val < min) min = val;
                if (val > max) max = val;
                if (!unit && prop.unit) unit = prop.unit;
            }
        });
        if (min !== Infinity) {
            stats[key] = { min, max, unit };
        }
    });
    return stats;
  }, [data, numericKeys]);

  const chartData = useMemo(() => {
    // First apply filters
    const filtered = data.filter(product => {
        return plotFilters.every(f => {
            if (!f.key || f.value === '') return true;
            const prop = product.properties[f.key];
            const val = parseFloat(String(prop?.value));
            if (isNaN(val)) return false;

            const v1 = Number(f.value);
            const v2 = f.value2 !== '' ? Number(f.value2) : Infinity;

            switch (f.operator) {
                case '>': return val > v1;
                case '<': return val < v1;
                case '>=': return val >= v1;
                case '<=': return val <= v1;
                case 'between': return val >= v1 && val <= v2;
                default: return true;
            }
        });
    });

    // Then map to flat structure for Recharts
    return filtered.map(p => {
        const item: any = {
            id: p.id,
            gradeName: p.gradeName,
            manufacturer: p.manufacturer,
        };
        // Flatten properties
        Object.entries(p.properties).forEach(([k, v]) => {
            const rawVal = v.value;
            // Robust parsing: handle strings that might represent numbers
            const num = parseFloat(String(rawVal));
            // Store as number if valid number, else original value
            item[k] = !isNaN(num) && rawVal !== '' && rawVal !== null ? num : rawVal;
        });
        return item;
    });
  }, [data, plotFilters]);

  const uniqueGroups = useMemo(() => {
    if (!groupByKey) return [];
    const groups = new Set<string>();
    chartData.forEach((item: any) => {
        const val = item[groupByKey];
        groups.add(val !== undefined && val !== null ? String(val) : 'Unknown');
    });
    return Array.from(groups).sort();
  }, [groupByKey, chartData]);

  const visibleChartData = useMemo(() => {
    if (!groupByKey) return chartData;
    return chartData.filter(d => !hiddenGroups.has(String(d[groupByKey] || 'Unknown')));
  }, [chartData, groupByKey, hiddenGroups]);

  // --- Derived State for Colors & Trendlines ---

  const trendlineSegment = useMemo(() => {
    if (!showTrendline || chartType !== 'scatter' || !xAxisKey || !yAxisKey) return null;

    // Filter for points that have valid numeric X and Y
    const validPoints = visibleChartData.filter(d => 
        typeof d[xAxisKey] === 'number' && !isNaN(d[xAxisKey]) &&
        typeof d[yAxisKey] === 'number' && !isNaN(d[yAxisKey])
    );

    if (validPoints.length < 2) return null;

    const n = validPoints.length;
    let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
    let minX = Infinity, maxX = -Infinity;

    validPoints.forEach(p => {
        const x = p[xAxisKey];
        const y = p[yAxisKey];
        sumX += x; sumY += y; sumXY += x * y; sumX2 += x * x;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
    });

    const denominator = n * sumX2 - sumX * sumX;
    if (denominator === 0) return null; 

    const slope = (n * sumXY - sumX * sumY) / denominator;
    const intercept = (sumY - slope * sumX) / n;

    const padding = (maxX - minX) * 0.05; 

    return [
        { [xAxisKey]: minX - padding, [yAxisKey]: slope * (minX - padding) + intercept, isTrend: true },
        { [xAxisKey]: maxX + padding, [yAxisKey]: slope * (maxX + padding) + intercept, isTrend: true }
    ];
  }, [visibleChartData, xAxisKey, yAxisKey, showTrendline, chartType]);

  useEffect(() => {
    if (uniqueGroups.length > 0) {
        setGroupColors(prev => {
            const next = { ...prev };
            const currentPalette = COLOR_SCHEMES.find(s => s.id === activeSchemeId)?.colors || DEFAULT_PALETTE;
            uniqueGroups.forEach((group, index) => {
                if (!next[group]) next[group] = currentPalette[index % currentPalette.length];
            });
            return next;
        });
    }
  }, [uniqueGroups, activeSchemeId]);

  // --- Handlers ---

  const toggleGroupVisibility = (group: string, isAltKey: boolean = false) => {
    if (isAltKey) {
        const others = uniqueGroups.filter(g => g !== group);
        setHiddenGroups(new Set(others));
    } else {
        setHiddenGroups(prev => {
          const next = new Set(prev);
          if (next.has(group)) next.delete(group);
          else next.add(group);
          return next;
        });
    }
  };

  const handleDownload = async (type: 'json' | 'png') => {
    if (type === 'json') {
        const blob = new Blob([JSON.stringify(visibleChartData, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = `resindb_data_${Date.now()}.json`; a.click();
    } else if (type === 'png' && chartRef.current) {
        setIsExporting(true);
        try {
          await new Promise(resolve => setTimeout(resolve, 100)); // Allow render
          const canvas = await html2canvas(chartRef.current, { 
            backgroundColor: theme === 'dark' ? '#0f172a' : '#ffffff',
            scale: 2, 
            logging: false,
            useCORS: true, 
            ignoreElements: (el) => el.classList.contains('no-capture')
          });
          const a = document.createElement('a');
          a.href = canvas.toDataURL('image/png', 1.0); 
          a.download = `resindb_chart_${new Date().toISOString().slice(0,10)}.png`; 
          a.click();
        } catch (err) {
          console.error("Export failed:", err);
        } finally {
          setIsExporting(false);
        }
    }
  };

  const getLabelWithUnit = (key: string) => {
      const label = tProp(key);
      const unit = propertyStats[key]?.unit;
      return unit ? `${label} (${unit})` : label;
  };

  // --- Render Helpers ---

  const CustomTooltipContent = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const d = payload[0].payload;
      if (d.isTrend) return <div className="px-2 py-1 bg-slate-800 text-white text-xs rounded">Trendline</div>;

      const product = data.find(p => p.id === d.id);
      if (!product) return null;

      // Find top distinct properties to show
      const additionalProps = Object.entries(product.properties)
        .filter(([k]) => k !== xAxisKey && k !== yAxisKey && k !== groupByKey && numericKeys.includes(k))
        .slice(0, 3);

      return (
        <div className="p-4 bg-white/95 dark:bg-slate-900/95 backdrop-blur-xl border border-slate-200 dark:border-slate-700 rounded-2xl shadow-xl min-w-[200px] border-l-4" style={{ borderLeftColor: groupByKey ? groupColors[String(d[groupByKey])] : '#10b981' }}>
          <div className="flex items-center justify-between gap-4 mb-2">
            <p className="font-bold text-slate-800 dark:text-white text-sm">{product.gradeName}</p>
            <div className="flex items-center gap-1 bg-slate-100 dark:bg-slate-800 px-2 py-0.5 rounded-full">
                <Factory size={10} className="text-slate-400" />
                <span className="text-[10px] font-bold text-slate-500 uppercase">{product.manufacturer}</span>
            </div>
          </div>

          <div className="space-y-1.5 pt-2 border-t border-slate-100 dark:border-slate-800">
             <div className="flex justify-between gap-4">
                <span className="text-xs text-slate-500 font-medium">{tProp(yAxisKey)}</span>
                <span className="text-sm font-black text-emerald-600 dark:text-emerald-400 font-mono">
                    {d[yAxisKey]} {propertyStats[yAxisKey]?.unit && <span className="text-[9px] opacity-60 ml-0.5">{propertyStats[yAxisKey]?.unit}</span>}
                </span>
             </div>
             {chartType === 'scatter' && xAxisKey !== 'gradeName' && (
               <div className="flex justify-between gap-4">
                  <span className="text-xs text-slate-500 font-medium">{tProp(xAxisKey)}</span>
                  <span className="text-sm font-black text-blue-600 dark:text-blue-400 font-mono">
                      {d[xAxisKey]} {propertyStats[xAxisKey]?.unit && <span className="text-[9px] opacity-60 ml-0.5">{propertyStats[xAxisKey]?.unit}</span>}
                  </span>
               </div>
             )}
             {additionalProps.map(([k, v]) => (
                 <div key={k} className="flex justify-between gap-4">
                    <span className="text-xs text-slate-400">{tProp(k)}</span>
                    <span className="text-xs font-bold text-slate-700 dark:text-slate-300 font-mono">
                        {v.value}
                    </span>
                 </div>
             ))}
          </div>
        </div>
      );
    }
    return null;
  };

  const RenderCustomLegend = (props: any) => {
    const { payload } = props;
    if (!payload || !groupByKey) return null;

    const items = uniqueGroups.filter(g => g.toLowerCase().includes(legendSearch.toLowerCase()));

    return (
      <div className="flex flex-col items-center mb-4 gap-2 animate-in fade-in duration-500 bg-white/60 dark:bg-slate-900/60 backdrop-blur-md border border-slate-200 dark:border-slate-800 rounded-2xl p-3 shadow-lg mx-4">
        <div className="flex w-full items-center gap-2 px-1">
            <Search size={12} className="text-slate-400" />
            <input 
                value={legendSearch} 
                onChange={(e) => setLegendSearch(e.target.value)} 
                className="flex-1 bg-transparent text-[10px] font-bold outline-none" 
                placeholder="Filter groups..." 
            />
            {legendSearch && <button onClick={() => setLegendSearch('')}><X size={10} /></button>}
        </div>
        <div className="flex flex-wrap justify-center gap-2 max-h-32 overflow-y-auto custom-scrollbar w-full">
            {items.map((group, idx) => {
                const isHidden = hiddenGroups.has(group);
                return (
                    <button 
                        key={group} 
                        onClick={(e) => toggleGroupVisibility(group, e.altKey)}
                        onMouseEnter={() => !isHidden && setHighlightedGroup(group)}
                        onMouseLeave={() => setHighlightedGroup(null)}
                        className={`flex items-center gap-1.5 px-2 py-1 rounded-lg border text-[10px] font-bold transition-all ${isHidden ? 'bg-slate-100 dark:bg-slate-800 text-slate-400 border-transparent grayscale' : 'bg-white dark:bg-slate-900 border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 hover:border-emerald-400'}`}
                    >
                        <div className="w-2 h-2 rounded-full" style={{ backgroundColor: groupColors[group] || '#ccc' }}></div>
                        {group}
                    </button>
                );
            })}
        </div>
      </div>
    );
  };

  // Theme colors
  const gridColor = theme === 'dark' ? '#334155' : '#e2e8f0'; 
  const axisColor = theme === 'dark' ? '#94a3b8' : '#64748b'; 

  // --- EFFECTIVE Y-AXIS SAFEGUARD ---
  // Ensure we always have a valid Y-Axis key to render
  const effectiveYAxisKey = yAxisKey || numericKeys[0] || '';

  return (
    <div className="flex flex-col md:flex-row h-full gap-4 overflow-hidden">
      {/* Settings Panel */}
      <div className={`flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl transition-all duration-500 ease-out shrink-0 overflow-hidden shadow-xl ${showConfig ? 'w-full md:w-80 opacity-100 translate-x-0' : 'w-0 opacity-0 -translate-x-10 border-0 pointer-events-none'}`}>
        <div className="p-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50/80 dark:bg-slate-950/50 backdrop-blur-sm">
          <div className="flex items-center gap-2 font-black text-sm text-slate-800 dark:text-white uppercase tracking-widest">
            <Sliders size={16} className="text-emerald-500" />
            {t('chartConfig')}
          </div>
          <button onClick={() => setShowConfig(false)} className="md:hidden text-slate-400 hover:text-slate-600">
            <X size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-5 custom-scrollbar space-y-8">
          {/* Chart Type Selection */}
          <div className="space-y-3">
             <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <LayoutDashboard size={12} /> {t('chartType')}
             </label>
             <div className="flex gap-3">
                <button onClick={() => setChartType('bar')} className={`flex-1 flex flex-col items-center gap-2 p-4 rounded-2xl border-2 transition-all duration-200 ${chartType === 'bar' ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 shadow-md' : 'border-slate-100 dark:border-slate-800 text-slate-400 hover:border-emerald-200 dark:hover:border-emerald-800'}`}>
                  <BarChart2 size={24} /> <span className="text-[10px] font-black uppercase tracking-wider">{t('barChart')}</span>
                </button>
                <button onClick={() => setChartType('scatter')} className={`flex-1 flex flex-col items-center gap-2 p-4 rounded-2xl border-2 transition-all duration-200 ${chartType === 'scatter' ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 shadow-md' : 'border-slate-100 dark:border-slate-800 text-slate-400 hover:border-emerald-200 dark:hover:border-emerald-800'}`}>
                  <ScatterIcon size={24} /> <span className="text-[10px] font-black uppercase tracking-wider">{t('scatterChart')}</span>
                </button>
             </div>
          </div>

          {/* Filters */}
          <div className="space-y-4 pt-2 border-t border-slate-100 dark:border-slate-800">
            <div className="flex items-center justify-between">
                <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                    <Filter size={12} /> {t('dataFilters')}
                </label>
                <button onClick={() => setPlotFilters([...plotFilters, { id: Date.now().toString(), key: numericKeys[0], operator: '>=', value: '', value2: '' }])} className="flex items-center gap-1 px-2 py-1 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 rounded-lg hover:bg-emerald-100 dark:hover:bg-emerald-900/30 transition-colors text-[10px] font-bold uppercase tracking-wider border border-emerald-100 dark:border-emerald-800">
                    <Plus size={10} /> Add
                </button>
            </div>
            {plotFilters.length === 0 ? (
                <div className="text-center py-6 bg-slate-50/50 dark:bg-slate-900/50 rounded-2xl border border-dashed border-slate-200 dark:border-slate-800">
                    <p className="text-[10px] text-slate-400 font-medium uppercase tracking-wide">{t('noFilters')}</p>
                </div>
            ) : (
                <div className="space-y-3">
                    {plotFilters.map((filter, idx) => (
                        <div key={filter.id} className="p-3 bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-sm space-y-2">
                            <div className="flex items-center gap-2">
                                <div className="w-5 h-5 rounded bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-[10px] font-bold text-slate-500">{idx+1}</div>
                                <select value={filter.key} onChange={(e) => { const newF = [...plotFilters]; newF[idx].key = e.target.value; setPlotFilters(newF); }} className="flex-1 bg-transparent text-xs font-bold outline-none">
                                    {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                                </select>
                                <button onClick={() => setPlotFilters(plotFilters.filter((_, i) => i !== idx))}><Trash2 size={12} className="text-slate-300 hover:text-rose-500" /></button>
                            </div>
                            <div className="flex items-center gap-2">
                                <select value={filter.operator} onChange={(e) => { const newF = [...plotFilters]; newF[idx].operator = e.target.value as any; setPlotFilters(newF); }} className="bg-slate-50 dark:bg-slate-900 border rounded text-[10px] p-1 font-mono">
                                    <option value=">">&gt;</option><option value="<">&lt;</option><option value=">=">&ge;</option><option value="<=">&le;</option><option value="between">Range</option>
                                </select>
                                <input type="number" value={filter.value} onChange={(e) => { const newF = [...plotFilters]; newF[idx].value = Number(e.target.value); setPlotFilters(newF); }} className="flex-1 bg-slate-50 dark:bg-slate-900 border rounded text-[10px] p-1 font-mono" placeholder="Value" />
                                {filter.operator === 'between' && <input type="number" value={filter.value2} onChange={(e) => { const newF = [...plotFilters]; newF[idx].value2 = Number(e.target.value); setPlotFilters(newF); }} className="flex-1 bg-slate-50 dark:bg-slate-900 border rounded text-[10px] p-1 font-mono" placeholder="Max" />}
                            </div>
                        </div>
                    ))}
                </div>
            )}
          </div>

          {/* Axes */}
          <div className="space-y-4 pt-2 border-t border-slate-100 dark:border-slate-800">
            <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <RotateCcw size={12} /> {t('axisMapping')}
            </label>
            <div className="space-y-3 bg-slate-50 dark:bg-slate-950/30 p-3 rounded-2xl border border-slate-100 dark:border-slate-800">
              <div className="space-y-1.5">
                <span className="text-[10px] font-bold text-emerald-600 dark:text-emerald-500 ml-1 uppercase tracking-widest">{t('yAxis')} (Vertical)</span>
                <div className="relative">
                    <select value={yAxisKey} onChange={(e) => setYAxisKey(e.target.value)} className="w-full pl-3 pr-3 py-2.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl text-xs font-bold outline-none focus:border-emerald-500 transition-colors shadow-sm appearance-none cursor-pointer">
                        {numericKeys.length > 0 ? numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>) : <option disabled>No numeric data available</option>}
                    </select>
                </div>
              </div>
              {chartType === 'scatter' && (
                <div className="space-y-1.5">
                    <span className="text-[10px] font-bold text-blue-600 dark:text-blue-500 ml-1 uppercase tracking-widest">{t('xAxis')} (Horizontal)</span>
                    <div className="relative">
                        <select value={xAxisKey} onChange={(e) => setXAxisKey(e.target.value)} className="w-full pl-3 pr-3 py-2.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl text-xs font-bold outline-none focus:border-emerald-500 transition-colors shadow-sm appearance-none cursor-pointer">
                            {numericKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                        </select>
                    </div>
                </div>
              )}
            </div>
          </div>

          {/* Grouping */}
          <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800">
             <div className="flex items-center justify-between">
                <label className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2"><PaletteIcon size={12} /> {t('styleGrouping')}</label>
             </div>
             <div className="space-y-1.5">
               <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1">{t('groupBy')}</span>
               <div className="relative">
                   <select value={groupByKey} onChange={(e) => setGroupByKey(e.target.value)} className="w-full pl-3 pr-8 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-xs font-bold outline-none focus:border-emerald-500 transition-colors appearance-none cursor-pointer">
                       <option value="">{t('none')}</option>
                       {categoricalKeys.map(k => <option key={k} value={k}>{tProp(k)}</option>)}
                   </select>
                   <ChevronUp size={12} className="absolute right-3 top-3 pointer-events-none text-slate-400 rotate-180" />
               </div>
             </div>
             {groupByKey && (
                 <div className="grid grid-cols-1 gap-1.5 p-2 bg-slate-50 dark:bg-slate-900/50 rounded-xl">
