                        <button key={scheme.id} onClick={() => setActiveSchemeId(scheme.id)} className={`w-full flex h-6 rounded-lg overflow-hidden border ${activeSchemeId === scheme.id ? 'border-emerald-500 ring-1 ring-emerald-500' : 'border-transparent'}`}>
                            {scheme.colors.map(c => <div key={c} style={{backgroundColor: c}} className="flex-1 h-full" />)}
                        </button>
                    ))}
                 </div>
             )}
          </div>

          <div className="pt-6 border-t border-slate-100 dark:border-slate-800 grid grid-cols-2 gap-3 pb-4">
            <button onClick={() => handleDownload('json')} className="flex items-center justify-center gap-2 p-3 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-xl text-[10px] font-bold text-slate-600 dark:text-slate-300 transition-colors uppercase tracking-wider"><FileJson size={14} /> JSON</button>
            <button onClick={() => handleDownload('png')} disabled={isExporting} className="flex items-center justify-center gap-2 p-3 bg-slate-900 dark:bg-emerald-600 hover:bg-slate-800 dark:hover:bg-emerald-500 disabled:opacity-70 text-white rounded-xl text-[10px] font-bold transition-all uppercase tracking-wider shadow-lg">{isExporting ? <Loader2 size={14} className="animate-spin" /> : <ImageIcon size={14} />} EXPORT</button>
          </div>
        </div>
      </div>

      {/* Chart Canvas Area */}
      <div className="flex-1 flex flex-col bg-white/50 dark:bg-slate-900/50 backdrop-blur-xl border border-slate-200 dark:border-slate-800 rounded-[2rem] relative min-h-[500px] shadow-2xl overflow-hidden">

        {/* Floating Toolbar */}
        <div className="absolute top-6 right-6 z-30 flex gap-2">
             {!showConfig && <button onClick={() => setShowConfig(true)} className="p-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-slate-500 hover:text-emerald-500 shadow-xl transition-all hover:scale-105 active:scale-95 no-capture group"><Settings size={20} className="group-hover:rotate-90 transition-transform duration-500" /></button>}
        </div>

        <div className="flex-1 p-6 md:p-8 flex flex-col min-h-0" ref={chartRef}>
            <div className="mb-6 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
               <div className="flex flex-col">
                   <h2 className="text-xl md:text-2xl font-black text-slate-800 dark:text-white flex items-center gap-3 tracking-tight">
                      {chartType === 'bar' ? <BarChart2 size={24} className="text-emerald-500" /> : <ScatterIcon size={24} className="text-emerald-500" />}
                      {effectiveYAxisKey ? (
                          <span className="bg-clip-text text-transparent bg-gradient-to-r from-slate-800 to-slate-500 dark:from-white dark:to-slate-400">
