         </div>

         <div className="mt-auto flex flex-col gap-3 w-full px-3">
            <button onClick={() => setIsAdminOpen(true)} className="w-14 h-14 rounded-[1.2rem] text-slate-400 hover:bg-emerald-50 dark:hover:bg-emerald-900/20 hover:text-emerald-600 transition-all flex items-center justify-center hover:scale-105 active:scale-95">
                <ShieldCheck size={24} />
