interface DataVisualizerProps {
  data: Product[];
}

interface PlotFilter {
  id: string;
  key: string;
  operator: '>' | '<' | '>=' | '<=' | 'between';
  value: number | '';
  value2: number | '';
}

const DEFAULT_PALETTE = [
  '#10b981', // Emerald
  '#3b82f6', // Blue
  '#f59e0b', // Amber
  '#ef4444', // Red
  '#8b5cf6', // Violet
  '#ec4899', // Pink
