  '#84cc16', // Lime
];

const COLOR_SCHEMES = [
  { id: 'emerald', name: 'Resin Classic', colors: ['#10b981', '#059669', '#047857', '#065f46', '#064e3b', '#34d399'] },
  { id: 'vibrant', name: 'Scientific Vibrant', colors: ['#6366f1', '#8b5cf6', '#ec4899', '#f43f5e', '#f97316', '#eab308'] },
  { id: 'ocean', name: 'Deep Ocean', colors: ['#0c4a6e', '#075985', '#0369a1', '#0284c7', '#0ea5e9', '#38bdf8'] },
];

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const { t, tProp } = useLanguage();
  const { theme } = useTheme();
  const chartRef = useRef<HTMLDivElement>(null);
  const plotlyRef = useRef<HTMLDivElement>(null);
  const echartsRef = useRef<HTMLDivElement>(null);
  const echartsInstance = useRef<echarts.ECharts | null>(null);

  const [showConfig, setShowConfig] = useState(true);
  const [isExporting, setIsExporting] = useState(false);
  const [chartType, setChartType] = useState<'bar' | 'scatter' | 'rheology'>('bar');
  const [xAxisKey, setXAxisKey] = useState<string>('熔体质量流动速率'); // Default to MFR for Ashby
  const [yAxisKey, setYAxisKey] = useState<string>('拉伸屈服应力');
  const [legendSearch, setLegendSearch] = useState('');

  const [plotFilters, setPlotFilters] = useState<PlotFilter[]>([]);

  const [groupByKey, setGroupByKey] = useState<string>('manufacturer');
  const [activeSchemeId, setActiveSchemeId] = useState('emerald');

  // Robustly identify keys that have numeric values across the dataset
  const numericKeys = useMemo(() => {
     const keys = new Set<string>();
     data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
           const val = typeof v === 'object' && v !== null && 'value' in v ? v.value : v;
           if (typeof val === 'number' || (!isNaN(parseFloat(String(val))) && val !== '' && val !== null && val !== undefined)) {
               keys.add(k);
           }
        });
     });
     const priority = ['密度', 'Density', '熔体质量流动速率', 'Melt Flow Rate', '拉伸屈服应力', 'Tensile Strength'];
     return Array.from(keys).sort((a, b) => {
         const idxA = priority.indexOf(a);
         const idxB = priority.indexOf(b);
         if (idxA !== -1 && idxB !== -1) return idxA - idxB;
         if (idxA !== -1) return -1;
         if (idxB !== -1) return 1;
         return a.localeCompare(b);
     });
  }, [data]);

  const categoricalKeys = useMemo(() => {
    const keys = new Set<string>(['manufacturer']);
    data.forEach(p => {
        Object.entries(p.properties).forEach(([k, v]) => {
            const val = typeof v === 'object' && v !== null && 'value' in v ? v.value : v;
            if (typeof val === 'string' && isNaN(parseFloat(String(val)))) {
                keys.add(k);
            }
        });
    });
    return Array.from(keys).sort();
  }, [data]);

  // --- Safe Data Mapping ---
  const renderData = useMemo(() => {
    // 1. Filter
    const filtered = data.filter(product => {
        return plotFilters.every(f => {
            if (!f.key || f.value === '') return true;
            const prop = product.properties[f.key];
            const val = parseFloat(String(prop?.value));
            if (isNaN(val)) return false;
            const v1 = Number(f.value);
            const v2 = f.value2 !== '' ? Number(f.value2) : Infinity;
            switch (f.operator) {
                case '>': return val > v1;
                case '<': return val < v1;
                case '>=': return val >= v1;
                case '<=': return val <= v1;
                case 'between': return val >= v1 && val <= v2;
                default: return true;
            }
        });
    });

    // 2. Map
    return filtered.map(p => {
        const yProp = p.properties[yAxisKey || numericKeys[0]];
        const yVal = parseFloat(String(yProp?.value));

        let xVal: number | string = p.gradeName; 
        if (chartType === 'scatter' || chartType === 'rheology') {
            const xProp = p.properties[xAxisKey];
            const parsedX = parseFloat(String(xProp?.value));
            xVal = isNaN(parsedX) ? 0 : parsedX;
        }

        let groupVal = 'Unknown';
        if (groupByKey) {
            if (groupByKey === 'manufacturer') groupVal = p.manufacturer;
            else {
                const gProp = p.properties[groupByKey];
                if (gProp?.value) groupVal = String(gProp.value);
            }
        }

        return {
            id: p.id,
            gradeName: p.gradeName,
            x: xVal, 
            y: !isNaN(yVal) ? yVal : 0, 
            isValid: !isNaN(yVal) && (chartType === 'bar' || (typeof xVal === 'number' && !isNaN(xVal) && xVal !== 0)),
            group: groupVal,
            original: p 
        };
    }).filter(d => d.isValid);

  }, [data, plotFilters, yAxisKey, xAxisKey, chartType, groupByKey, numericKeys]);

  // --- Plotly Effect for Scatter (Ashby Plot) ---
  useEffect(() => {
    if (chartType !== 'scatter' || !plotlyRef.current || renderData.length === 0) return;

    // Group data for Plotly traces
    const groups: Record<string, { x: number[], y: number[], text: string[] }> = {};
    renderData.forEach(d => {
        if (!groups[d.group]) groups[d.group] = { x: [], y: [], text: [] };
        groups[d.group].x.push(d.x as number);
        groups[d.group].y.push(d.y as number);
        groups[d.group].text.push(`${d.gradeName}<br>${tProp(xAxisKey)}: ${d.x}<br>${tProp(yAxisKey)}: ${d.y}`);
    });

    const traces: any[] = Object.keys(groups).map(g => ({
        x: groups[g].x,
        y: groups[g].y,
        mode: 'markers',
        type: 'scatter',
        name: g,
        text: groups[g].text,
        marker: { size: 10, opacity: 0.7, line: { width: 1, color: 'white' } }
    }));

    // Add Pareto Frontier (Simple approximations for demo)
    // In real app, calculate convex hull of max(y) for each x bin
    const allX = renderData.map(d => d.x as number);
    const allY = renderData.map(d => d.y as number);
    if(allX.length > 2) {
        // Mock frontier line
        const minX = Math.min(...allX);
        const maxX = Math.max(...allX);
        const maxY = Math.max(...allY);
        traces.push({
            x: [minX, maxX],
            y: [maxY, maxY * 0.8], // Fake slope
            mode: 'lines',
            name: 'Pareto Limit',
            line: { dash: 'dashdot', width: 2, color: '#ef4444' },
            hoverinfo: 'none'
        });
    }

    const layout = {
        paper_bgcolor: 'transparent',
        plot_bgcolor: 'transparent',
        font: { color: theme === 'dark' ? '#cbd5e1' : '#334155', family: 'Inter' },
        xaxis: { 
            title: { text: tProp(xAxisKey), font: { size: 12, weight: 'bold' } }, 
            type: 'log', 
            gridcolor: theme === 'dark' ? '#334155' : '#e2e8f0',
            zerolinecolor: theme === 'dark' ? '#334155' : '#e2e8f0'
        },
        yaxis: { 
            title: { text: tProp(yAxisKey), font: { size: 12, weight: 'bold' } }, 
            gridcolor: theme === 'dark' ? '#334155' : '#e2e8f0',
            zerolinecolor: theme === 'dark' ? '#334155' : '#e2e8f0'
        },
        margin: { l: 60, r: 20, t: 30, b: 50 },
        showlegend: true,
        legend: { orientation: 'h', y: 1.1 }
    };

    Plotly.newPlot(plotlyRef.current, traces, layout as any, { responsive: true, displayModeBar: false });

    return () => {
        if (plotlyRef.current) Plotly.purge(plotlyRef.current);
    };
  }, [renderData, chartType, theme, xAxisKey, yAxisKey, tProp]);

  // --- ECharts Effect for Rheology ---
  useEffect(() => {
    if (chartType !== 'rheology' || !echartsRef.current) return;

    if (!echartsInstance.current) {
        echartsInstance.current = echarts.init(echartsRef.current);
    }

    // Generate Synthetic Rheology Curves (Power Law: eta = K * gamma^(n-1))
    // We assume MFR correlates inversely with K (Viscosity magnitude)
    // We assume 'n' (shear thinning) is around 0.4 - 0.6
    const series = renderData.slice(0, 10).map(d => { // Limit to 10 for clarity
        const mfr = d.x as number; // Using xAxisKey (MFR) as base
        if (mfr <= 0) return null;

        // Approximate K based on MFR (Higher MFR = Lower Viscosity)
        // Empirical: log(K) ~ C - log(MFR)
        const K = 50000 / Math.pow(mfr, 0.8); 
        const n = 0.4 + (Math.random() * 0.2); // Random n for variety

        const dataPoints = [];
        // Shear rates from 0.1 to 10000 (Log scale)
        for (let exp = -1; exp <= 4; exp += 0.2) {
            const gamma = Math.pow(10, exp);
            const eta = K * Math.pow(gamma, n - 1);
            dataPoints.push([gamma, eta]);
        }

        return {
            name: d.gradeName,
            type: 'line',
            smooth: true,
            symbol: 'none',
            data: dataPoints,
            lineStyle: { width: 2 }
        };
    }).filter(Boolean);

    const option = {
        backgroundColor: 'transparent',
        tooltip: {
            trigger: 'axis',
            formatter: (params: any) => {
                let html = `<div class="font-bold text-xs mb-1">Shear Rate: ${params[0].value[0].toFixed(2)} s⁻¹</div>`;
                params.forEach((item: any) => {
                    html += `<div style="color:${item.color}; font-size:10px">${item.seriesName}: <b>${Math.round(item.value[1])} Pa·s</b></div>`;
                });
                return html;
            }
        },
        legend: {
            data: series.map((s: any) => s.name),
            textStyle: { color: theme === 'dark' ? '#cbd5e1' : '#475569' },
            type: 'scroll',
            bottom: 0
        },
        grid: { left: '10%', right: '5%', top: '10%', bottom: '15%' },
        xAxis: {
            type: 'log',
            name: 'Shear Rate (1/s)',
            nameLocation: 'middle',
            nameGap: 25,
            axisLabel: { color: theme === 'dark' ? '#94a3b8' : '#64748b' },
            splitLine: { show: true, lineStyle: { color: theme === 'dark' ? '#334155' : '#e2e8f0' } }
        },
        yAxis: {
            type: 'log',
            name: 'Viscosity (Pa·s)',
            axisLabel: { color: theme === 'dark' ? '#94a3b8' : '#64748b' },
            splitLine: { show: true, lineStyle: { color: theme === 'dark' ? '#334155' : '#e2e8f0' } }
        },
        series: series as any
    };

    echartsInstance.current.setOption(option);

    const handleResize = () => echartsInstance.current?.resize();
    window.addEventListener('resize', handleResize);

    return () => {
        window.removeEventListener('resize', handleResize);
        echartsInstance.current?.dispose();
        echartsInstance.current = null;
    };
  }, [renderData, chartType, theme]);

  // Theme colors for Recharts
  const gridColor = theme === 'dark' ? '#334155' : '#e2e8f0'; 
  const axisColor = theme === 'dark' ? '#94a3b8' : '#64748b'; 

  // Recharts Bar Renderer
  const renderBarChart = () => (
    <ResponsiveContainer width="100%" height="100%">
        <BarChart data={renderData} margin={{ top: 20, right: 30, left: 20, bottom: 60 }}>
            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={gridColor} strokeWidth={1} />
            <XAxis dataKey="gradeName" angle={-45} textAnchor="end" interval={0} height={80} fontSize={10} stroke={axisColor} tick={{ fill: axisColor, fontWeight: 600 }} tickLine={{ stroke: axisColor }} padding={{ left: 20, right: 20 }} />
            <YAxis dataKey="y" fontSize={10} stroke={axisColor} tick={{ fill: axisColor, fontWeight: 600 }} tickLine={{ stroke: axisColor }} label={{ value: tProp(yAxisKey), angle: -90, position: 'insideLeft', offset: 0, fontSize: 10, fill: axisColor, fontWeight: 700 }} padding={{ top: 20, bottom: 0 }} />
            <Tooltip cursor={{ fill: theme === 'dark' ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.03)' }} contentStyle={{ backgroundColor: theme === 'dark' ? '#0f172a' : '#fff', borderColor: theme === 'dark' ? '#1e293b' : '#e2e8f0' }} />
            <Legend verticalAlign="top" wrapperStyle={{ top: -10 }} />
            <Bar dataKey="y" radius={[6, 6, 0, 0]} animationDuration={1000} name={tProp(yAxisKey)}>
                {renderData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={DEFAULT_PALETTE[index % DEFAULT_PALETTE.length]} />
                ))}
            </Bar>
        </BarChart>
    </ResponsiveContainer>
  );

  const handleDownload = async (type: 'json' | 'png') => {
    if (type === 'json') {
        const exportData = renderData.map(d => d.original);
        const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = `resindb_data.json`; a.click();
    } else if (type === 'png' && chartRef.current) {
        setIsExporting(true);
        // Basic implementation for Recharts. 
        // Note: Plotly/Echarts have their own export methods which should be used if active.
        try {
          const canvas = await html2canvas(chartRef.current);
          const a = document.createElement('a');
