  // Generate points from shear rate 1 to 10000
  for (let i = 0; i <= 4; i += 0.2) { // Exponents of 10
    const shearRate = Math.pow(10, i);
    // Simplified Cross Model approximation
    const viscosity = zeroShearViscosity / (1 + Math.pow(shearRate * 0.01, 1 - shearThinningIndex));
    data.push([shearRate, viscosity]);
  }
  return data;
};

