// Mock Data: a, b, c must sum to ~1 (or 100). Value is the property (color).
// data = [ { a: 0.5, b: 0.3, c: 0.2, value: 45, name: 'Formulation 1' }, ... ]

// Ternary Math: Convert (a, b, c) proportions to (x, y) coordinates
// Vertices: A(Top), B(Right), C(Left) for this standard implementation
// Height of equilateral triangle = sqrt(3)/2 * Side
const sin60 = Math.sqrt(3) / 2;

function ternaryToCartesian(a: number, b: number, c: number, width: number, height: number) {
  // Normalize just in case
  const sum = a + b + c;
  const an = a / sum;
  const bn = b / sum;
  const cn = c / sum;

  // Coordinate Mapping (A=Top, B=Right, C=Left)
  // x = (B_fraction * 1.0 + A_fraction * 0.5) * width
  // y = (1 - A_fraction) * height (since SVG/Canvas Y is inverted, 0 is top)

  // Wait, correct mapping for ECharts (0,0 is top-left):
  // Let's define the triangle center within the width/height container.
  // We'll define a virtual square box inside the container.

  const size = Math.min(width, height);
  const h = size * sin60;
  const xOffset = (width - size) / 2;
  const yOffset = (height - h) / 2;

  // Vertex coordinates in the canvas
  // A (Top) = [size / 2, 0]
  // B (Right) = [size, h]
  // C (Left) = [0, h]

  const x = xOffset + (cn * 0 + bn * size + an * (size / 2));
  const y = yOffset + (cn * h + bn * h + an * 0);

  return [x, y];
}

export const getTernaryChartOption = (data: any[], theme: 'light' | 'dark'): echarts.EChartsOption => {
  const isDark = theme === 'dark';
