      text: 'Blend Formulation (Ternary)',
      subtext: 'Property Map: Monomer A-B-C',
      left: 'center',
      textStyle: { color: isDark ? '#e2e8f0' : '#1e293b' }
    },
    tooltip: {
      formatter: (params: any) => {
        const d = params.data;
        return `
          <b>${d.name || 'Sample'}</b><br/>
          Comp A: ${(d.a * 100).toFixed(1)}%<br/>
          Comp B: ${(d.b * 100).toFixed(1)}%<br/>
          Comp C: ${(d.c * 100).toFixed(1)}%<br/>
          ----<br/>
          Property: <b>${d.value}</b>
        `;
      }
    },
    // Visual Map to color the points based on the 'value' property
    visualMap: {
      min: 0,
      max: 100,
      calculable: true,
      orient: 'horizontal',
      left: 'center',
      bottom: 20,
      text: ['High', 'Low'],
      textStyle: { color: textColor },
      inRange: {
        color: ['#3b82f6', '#10b981', '#f59e0b', '#ef4444'] // Blue -> Green -> Yellow -> Red
      }
    },
    series: [
      {
        type: 'custom',
        renderItem: (params, api) => {
          const width = api.getWidth();
          const height = api.getHeight();
          const d = data[params.dataIndex];
          const [x, y] = ternaryToCartesian(d.a, d.b, d.c, width, height * 0.8); // 0.8 to leave room for visualMap

          return {
            type: 'circle',
            shape: { cx: x, cy: y, r: 8 },
            style: api.style({
              fill: api.visual('color'),
              stroke: isDark ? '#0f172a' : '#fff',
              lineWidth: 1
            })
          };
        },
        data: data
      },
      // Graphic Elements to draw the Triangle Grid/Frame
      {
        type: 'custom',
        renderItem: (params, api) => {
          const width = api.getWidth();
          const height = api.getHeight() * 0.8;
          const size = Math.min(width, height);
          const h = size * sin60;
          const xOffset = (width - size) / 2;
          const yOffset = (height - h) / 2;

          const A = [xOffset + size / 2, yOffset];
          const B = [xOffset + size, yOffset + h];
          const C = [xOffset, yOffset + h];

          return {
            type: 'group',
            children: [
              // The Triangle Frame
              {
                type: 'polygon',
                shape: { points: [A, B, C] },
                style: {
                  fill: 'transparent',
                  stroke: isDark ? '#475569' : '#cbd5e1',
                  lineWidth: 2
                }
              },
              // Labels
              { type: 'text', style: { text: 'A', x: A[0], y: A[1] - 15, textAlign: 'center', fill: textColor, fontWeight: 'bold' } },
              { type: 'text', style: { text: 'B', x: B[0] + 10, y: B[1], textAlign: 'left', fill: textColor, fontWeight: 'bold' } },
              { type: 'text', style: { text: 'C', x: C[0] - 10, y: C[1], textAlign: 'right', fill: textColor, fontWeight: 'bold' } }
            ]
          };
        },
        data: [0] // Dummy data to trigger render
      }
    ]
  };
};

