import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  Settings, LayoutDashboard, X, FileJson, Image as ImageIcon, 
  Sliders, Hexagon, ScatterChart, Waves, Activity, Triangle, 
  Info, Download, Loader2, RefreshCw
} from 'lucide-react';
import * as echarts from 'echarts';
import html2canvas from 'html2canvas';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';

// Import Scientific Chart Configurations
import { getRadarChartOption } from './charts/RadarBenchmark';
import { getAshbyChartOption } from './charts/AshbyScatter';
import { getGpcChartOption } from './charts/GpcDistribution';
import { getRheologyChartOption } from './charts/RheologyCurve';
import { getTernaryChartOption } from './charts/TernaryBlend';

interface DataVisualizerProps {
  data: Product[];
}

type ChartType = 'radar' | 'ashby' | 'gpc' | 'rheology' | 'ternary';

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data }) => {
  const { t, tProp } = useLanguage();
  const { theme } = useTheme();

  const chartRef = useRef<HTMLDivElement>(null);
  const chartInstance = useRef<echarts.ECharts | null>(null);

  const [activeChart, setActiveChart] = useState<ChartType>('radar');
  const [showConfig, setShowConfig] = useState(true);
  const [isExporting, setIsExporting] = useState(false);

  // --- Data Preparation Logic ---

  // 1. Radar Data: Compare top 3 products
  const radarData = useMemo(() => {
    return data.slice(0, 3).map(p => ({
      name: p.gradeName,
      value: [
        parseFloat(String(p.properties['熔体质量流动速率']?.value || 0)),
        parseFloat(String(p.properties['密度']?.value || 0)),
        parseFloat(String(p.properties['弯曲模量']?.value || 0)),
        parseFloat(String(p.properties['悬臂梁缺口冲击强度']?.value || 0)),
        parseFloat(String(p.properties['热变形温度']?.value || 0))
      ]
    }));
  }, [data]);

  // 2. Ashby Data: MFR vs Impact
  const ashbyData = useMemo(() => {
    // Group by manufacturer for series
    const groups: Record<string, any[]> = {};
    data.forEach(p => {
      const man = p.manufacturer;
      if (!groups[man]) groups[man] = [];
      const mfr = parseFloat(String(p.properties['熔体质量流动速率']?.value));
      const impact = parseFloat(String(p.properties['悬臂梁缺口冲击强度']?.value));

      if (!isNaN(mfr) && !isNaN(impact) && mfr > 0) {
        groups[man].push([mfr, impact, p.gradeName]);
      }
    });

    return Object.entries(groups).map(([name, points]) => ({
      name,
      data: points
    }));
  }, [data]);

  // 5. Ternary Data: Mock Formulation (Simulated based on properties)
  const ternaryData = useMemo(() => {
    return data.slice(0, 50).map((p, i) => {
        // Simulate formulation based on index/random for demo purposes
        // In real app, this would come from `p.composition`
        let a = 0.1 + Math.random() * 0.8;
        let b = 0.1 + Math.random() * (0.9 - a);
        let c = 1 - a - b;
        // Ensure strictly positive
        if (c < 0) { a=0.33; b=0.33; c=0.34; }

        return {
            a, b, c,
            name: p.gradeName,
            value: parseFloat(String(p.properties['拉伸强度']?.value || Math.floor(Math.random() * 60) + 20))
        };
    });
  }, [data]);

  // --- Render Chart Effect ---
  useEffect(() => {
    if (!chartRef.current) return;

    // Dispose old instance if exists to prevent memory leaks or context conflicts
    if (chartInstance.current) {
      chartInstance.current.dispose();
    }

    // Init new instance
    chartInstance.current = echarts.init(chartRef.current);

    let option = {};

    try {
        switch (activeChart) {
            case 'radar':
                option = getRadarChartOption(radarData, theme);
                break;
            case 'ashby':
                option = getAshbyChartOption(ashbyData, theme);
                break;
            case 'gpc':
                // GPC generates its own mock data internally for the curve demo
                option = getGpcChartOption(theme); 
                break;
            case 'rheology':
                // Rheology generates its own mock data internally for the curve demo
                option = getRheologyChartOption(theme);
                break;
            case 'ternary':
                option = getTernaryChartOption(ternaryData, theme);
                break;
        }

        chartInstance.current.setOption(option);
    } catch (e) {
        console.error("Chart Render Error:", e);
    }

    const handleResize = () => chartInstance.current?.resize();
    window.addEventListener('resize', handleResize);

    return () => {
        window.removeEventListener('resize', handleResize);
        chartInstance.current?.dispose();
        chartInstance.current = null;
    };
  }, [activeChart, theme, radarData, ashbyData, ternaryData]);

  const handleExport = async (format: 'png' | 'json') => {
      setIsExporting(true);
      if (format === 'png' && chartRef.current) {
          try {
            const canvas = await html2canvas(chartRef.current);
            const a = document.createElement('a');
            a.href = canvas.toDataURL('image/png', 1.0);
            a.download = `resindb_${activeChart}_analysis.png`;
            a.click();
          } catch(e) { console.error(e); }
      } else if (format === 'json') {
          const jsonStr = JSON.stringify(activeChart === 'radar' ? radarData : ashbyData, null, 2);
          const blob = new Blob([jsonStr], {type: 'application/json'});
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `resindb_${activeChart}_data.json`;
          a.click();
      }
      setIsExporting(false);
  };

  const chartDescriptions = {
      radar: "Compare comprehensive performance balance (Stiffness-Toughness-Processability) against benchmarks.",
      ashby: "Analyze trade-offs between Flowability (MFR) and Impact Strength. Identify technological frontiers.",
      gpc: "Visualize Molecular Weight Distribution (MWD). Distinguish between Uni-modal and Bi-modal grades.",
      rheology: "Study shear-thinning behavior (Viscosity vs Shear Rate) critical for processing simulation.",
      ternary: "Optimize blends and formulations by mapping properties to 3-component composition ratios."
  };

  return (
    <div className="flex flex-col md:flex-row h-full gap-4 overflow-hidden">
      {/* Scientific Controls Sidebar */}
      <div className={`flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl transition-all duration-500 ease-out shrink-0 overflow-hidden shadow-xl ${showConfig ? 'w-full md:w-72 opacity-100 translate-x-0' : 'w-0 opacity-0 -translate-x-10 border-0 pointer-events-none'}`}>
        <div className="p-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50/80 dark:bg-slate-950/50 backdrop-blur-sm">
          <div className="flex items-center gap-2 font-black text-sm text-slate-800 dark:text-white uppercase tracking-widest">
            <Activity size={16} className="text-emerald-500" />
            Analysis Mode
          </div>
          <button onClick={() => setShowConfig(false)} className="md:hidden text-slate-400 hover:text-slate-600">
            <X size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar space-y-2">
            {[
                { id: 'radar', label: 'Fingerprint (Radar)', icon: Hexagon, color: 'text-indigo-500' },
                { id: 'ashby', label: 'Ashby Map (Scatter)', icon: ScatterChart, color: 'text-rose-500' },
                { id: 'gpc', label: 'GPC Distribution', icon: Waves, color: 'text-blue-500' },
                { id: 'rheology', label: 'Rheology Curve', icon: Activity, color: 'text-amber-500' },
                { id: 'ternary', label: 'Ternary Phase', icon: Triangle, color: 'text-emerald-500' },
            ].map(item => (
                <button 
                    key={item.id}
                    onClick={() => setActiveChart(item.id as ChartType)}
                    className={`w-full flex items-center gap-3 p-3 rounded-2xl border transition-all duration-200 group relative overflow-hidden ${
                        activeChart === item.id 
                        ? 'bg-slate-900 dark:bg-white text-white dark:text-slate-900 border-transparent shadow-lg' 
                        : 'bg-white dark:bg-slate-800/50 border-slate-100 dark:border-slate-800 text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800'
                    }`}
                >
                    <div className={`p-2 rounded-xl bg-slate-100 dark:bg-slate-700/50 ${activeChart === item.id ? 'bg-white/20 text-white' : item.color}`}>
                        <item.icon size={18} />
                    </div>
                    <span className="text-xs font-bold uppercase tracking-wide">{item.label}</span>
                    {activeChart === item.id && <div className="absolute right-0 top-0 bottom-0 w-1 bg-emerald-500"></div>}
                </button>
            ))}

            <div className="mt-6 p-4 bg-slate-50 dark:bg-slate-950/30 rounded-2xl border border-slate-100 dark:border-slate-800">
                <div className="flex items-center gap-2 mb-2 text-slate-400 dark:text-slate-500">
                    <Info size={14} />
                    <span className="text-[10px] font-bold uppercase tracking-widest">Chart Context</span>
                </div>
                <p className="text-xs text-slate-600 dark:text-slate-300 leading-relaxed font-medium">
                    {chartDescriptions[activeChart]}
                </p>
            </div>
        </div>

        <div className="p-4 border-t border-slate-100 dark:border-slate-800 grid grid-cols-2 gap-3">
            <button onClick={() => handleExport('json')} className="flex items-center justify-center gap-2 p-3 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-xl text-[10px] font-bold text-slate-600 dark:text-slate-300 transition-colors uppercase tracking-wider"><FileJson size={14} /> JSON</button>
            <button onClick={() => handleExport('png')} disabled={isExporting} className="flex items-center justify-center gap-2 p-3 bg-emerald-600 hover:bg-emerald-500 disabled:opacity-70 text-white rounded-xl text-[10px] font-bold transition-all uppercase tracking-wider shadow-lg">{isExporting ? <Loader2 size={14} className="animate-spin" /> : <ImageIcon size={14} />} EXPORT</button>
        </div>
      </div>

      {/* Chart Canvas */}
      <div className="flex-1 flex flex-col bg-white/50 dark:bg-slate-900/50 backdrop-blur-xl border border-slate-200 dark:border-slate-800 rounded-[2rem] relative min-h-[500px] shadow-2xl overflow-hidden">
         {!showConfig && (
             <button onClick={() => setShowConfig(true)} className="absolute top-6 right-6 z-30 p-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-slate-500 hover:text-emerald-500 shadow-xl transition-all hover:scale-105 active:scale-95">
                <Settings size={20} />
             </button>
         )}

         <div className="flex-1 w-full h-full p-4 relative">
            <div ref={chartRef} className="w-full h-full" />

            {/* Watermark / Brand */}
            <div className="absolute bottom-6 right-6 pointer-events-none opacity-10 flex flex-col items-end">
                <span className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter">ResinDB</span>
                <span className="text-xs font-bold uppercase tracking-widest text-slate-500">Scientific Visualization</span>
            </div>
         </div>
      </div>
    </div>
  );
};

