  const axisColor = isDark ? '#94a3b8' : '#333333';

  // Generate curves based on product data (simulation)
  const series = products.map((p, idx) => {
      const data = [];
      // Use MFR to shift the curve (High MFR = Low MW = Shift Left)
      // MFR 0.1 -> Peak at 6.0 (High MW)
      // MFR 50 -> Peak at 4.0 (Low MW)
      const mfr = parseFloat(p.properties['熔体质量流动速率']?.value || 1);
      const safeMfr = isNaN(mfr) ? 1 : mfr;
      const peakLogMw = 6.0 - (Math.log10(safeMfr) * 0.5); 

      // Check if "High Impact" or "Bimodal" in name/app to simulate bimodal
      const isBimodal = p.gradeName.includes('High') || p.gradeName.includes('Pipe') || (Math.random() > 0.7);

      for (let i = 3; i <= 7; i += 0.05) {
        let val = 0;
        if (isBimodal) {
            // Main Peak + Shoulder
            val = 0.7 * Math.exp(-Math.pow(i - peakLogMw, 2) / (2 * 0.25)) + 
                  0.4 * Math.exp(-Math.pow(i - (peakLogMw + 0.8), 2) / (2 * 0.2));
        } else {
            // Single Peak
            val = 1.0 * Math.exp(-Math.pow(i - peakLogMw, 2) / (2 * 0.2));
        }
        data.push([Math.pow(10, i), val]);
      }

      return {
        name: p.gradeName,
        type: 'line',
        smooth: 0.3,
        showSymbol: false,
        data: data,
        lineStyle: { width: 2 },
        areaStyle: {
          color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
            { offset: 0, color: colorPalette[idx % colorPalette.length] + '80' }, // 50% opacity
            { offset: 1, color: colorPalette[idx % colorPalette.length] + '00' }
          ])
        }
      };
  });

  return {
    backgroundColor: 'transparent',
    color: colorPalette,
    title: {
      text: '分子量分布 (GPC Distribution)',
      subtext: '单峰 vs 双峰 (聚合工艺指纹)',
      left: 'center',
      textStyle: { color: isDark ? '#e2e8f0' : '#333333', fontSize: 16 }
    },
    tooltip: {
      trigger: 'axis',
      confine: true,
      backgroundColor: isDark ? 'rgba(15, 23, 42, 0.9)' : 'rgba(255, 255, 255, 0.95)',
      formatter: (params: any) => {
        let html = `<div style="margin-bottom:4px;font-weight:bold">Log MW: ${Math.log10(params[0].value[0]).toFixed(2)}</div>`;
        params.forEach((p: any) => {
          html += `<div style="color:${p.color}">${p.seriesName}: ${p.value[1].toFixed(3)}</div>`;
        });
        return html;
      }
    },
    legend: {
      top: 50,
      textStyle: { color: axisColor }
    },
    grid: {
      containLabel: true,
      left: '5%',
      right: '5%',
      bottom: '10%'
    },
    xAxis: {
      type: 'log',
      name: 'Molecular Weight (g/mol)',
      nameLocation: 'middle',
      nameGap: 30,
      min: 1000,
      max: 10000000,
      logBase: 10,
      axisLabel: { 
          color: axisColor,
          formatter: (value: number) => `10^${Math.log10(value)}`
      },
      axisLine: { lineStyle: { color: '#cbd5e1' } }
    },
    yAxis: {
      type: 'value',
      name: 'dw/d(logM)',
      nameLocation: 'middle',
      nameGap: 40,
      splitLine: { show: false },
      axisLabel: { color: axisColor },
