// Chart 4: Rheology Viscosity Curve Option Configuration
export const getRheologyChartOption = (products: any[], theme: 'light' | 'dark'): echarts.EChartsOption => {
  const isDark = theme === 'dark';
  const colorPalette = ['#2b6cb0', '#d69e2e', '#e53e3e', '#38a169', '#8b5cf6'];
  const gridColor = isDark ? '#334155' : '#eeeeee';
  const axisColor = isDark ? '#94a3b8' : '#333333';

  // Cross Model Simulation based on MFR
  const generateData = (mfr: number) => {
    const data = [];
    // Approximate Zero Shear Viscosity based on inverse MFR
    // Low MFR (0.1) -> High Eta0 (100,000)
    // High MFR (50) -> Low Eta0 (1,000)
    const eta0 = 30000 * Math.pow(mfr, -0.8);

    // Shear thinning index (n). Broad distribution = more shear thinning (lower n).
    // Assume standard 0.4 - 0.6 range
    const n = 0.4 + (Math.random() * 0.2); 

    for (let i = 0; i <= 4; i += 0.1) { // 10^0 to 10^4
      const rate = Math.pow(10, i);
      // Carreau-Yasuda simplified: eta = eta0 / (1 + (lambda * rate)^a)^((1-n)/a)
      // Simplified Cross: eta = eta0 / (1 + (lambda * rate)^(1-n))
      const viscosity = eta0 / (1 + Math.pow(rate * 0.05, 1 - n));
      data.push([rate, viscosity]);
    }
    return data;
  };

  const series = products.map((p, idx) => {
      const mfr = parseFloat(p.properties['熔体质量流动速率']?.value || 5);
      return {
        name: p.gradeName,
        type: 'line',
        smooth: true,
        showSymbol: false,
        data: generateData(isNaN(mfr) ? 5 : mfr),
        lineStyle: { width: 3 }
      };
  });

  return {
    backgroundColor: 'transparent',
    color: colorPalette,
    title: {
      text: '流变行为曲线 (Rheology Curve)',
      subtext: '剪切速率 vs 粘度 (加工性预测)',
      left: 'center',
      textStyle: { color: isDark ? '#e2e8f0' : '#333333', fontSize: 16 }
    },
    tooltip: {
      trigger: 'axis',
      confine: true,
      formatter: (params: any) => {
        let html = `<div>Shear Rate: <b>${params[0].value[0].toFixed(1)}</b> s⁻¹</div>`;
        params.forEach((item: any) => {
          html += `<div style="color:${item.color}">${item.seriesName}: <b>${Math.round(item.value[1])}</b> Pa·s</div>`;
        });
        return html;
      }
    },
    legend: {
      right: '10%',
      top: '10%',
      orient: 'vertical',
      backgroundColor: isDark ? 'rgba(0,0,0,0.5)' : 'rgba(255,255,255,0.8)',
      borderColor: '#ccc',
      borderWidth: 1,
      padding: 10,
      textStyle: { color: axisColor }
    },
    grid: {
      containLabel: true,
      left: '8%',
      right: '15%',
      bottom: '10%'
    },
    xAxis: {
      type: 'log',
      name: 'Shear Rate / 剪切速率 (1/s)',
      nameLocation: 'middle',
      nameGap: 30,
      min: 1,
      max: 10000,
      logBase: 10,
      splitLine: { show: true, lineStyle: { color: gridColor } },
      axisLabel: { color: axisColor },
      axisLine: { lineStyle: { color: '#cbd5e1' } }
    },
    yAxis: {
      type: 'log',
      name: 'Shear Viscosity / 剪切粘度 (Pa·s)',
      nameLocation: 'middle',
      nameGap: 50,
      logBase: 10,
      splitLine: { show: true, lineStyle: { color: gridColor } },
      axisLabel: { color: axisColor },
      axisLine: { lineStyle: { color: '#cbd5e1' } }
    },
    series: series as any[]
  };
};

