// Chart 5: Ternary Plot Option Configuration
export const getTernaryChartOption = (data: any[], theme: 'light' | 'dark'): echarts.EChartsOption => {
  const isDark = theme === 'dark';
  const axisColor = isDark ? '#94a3b8' : '#333333';

  // Equilateral Triangle Math
  const sin60 = Math.sqrt(3) / 2;

  // Convert (a, b, c) percentages to (x, y) coordinates
  const ternaryToCartesian = (a: number, b: number, c: number, width: number, height: number) => {
    const sum = a + b + c;
    const an = a / sum;
    const bn = b / sum;
    const cn = c / sum;

    const size = Math.min(width, height);
    const h = size * sin60;
    const xOffset = (width - size) / 2;
    const yOffset = (height - h) / 2;

    const x = xOffset + (0.5 * an + bn) * size;
    const y = yOffset + (1 - an) * h;

    return [x, y];
  };

  return {
    backgroundColor: 'transparent',
    title: {
      text: '三元相图 (Ternary Phase Plot)',
      subtext: '配方组分优化 (Formulation Optimization)',
      left: 'center',
      textStyle: { color: isDark ? '#e2e8f0' : '#333333', fontSize: 16 }
    },
    tooltip: {
      confine: true,
      formatter: (params: any) => {
        const d = params.data;
        if (!d) return '';
        return `
          <b>${d.name || 'Sample'}</b><br/>
          Comp A: ${(d.a * 100).toFixed(1)}%<br/>
          Comp B: ${(d.b * 100).toFixed(1)}%<br/>
          Comp C: ${(d.c * 100).toFixed(1)}%<br/>
          Performance: <b>${d.value}</b>
        `;
      }
    },
    visualMap: {
      min: 0,
      max: 100,
      dimension: 3, 
      calculable: true,
      orient: 'horizontal',
      left: 'center',
      bottom: 10,
      text: ['High (优)', 'Low (差)'],
      textStyle: { color: axisColor },
      inRange: {
        color: ['#2b6cb0', '#38a169', '#d69e2e', '#e53e3e'] 
      }
    },
    series: [
      {
        type: 'custom',
        renderItem: (params, api) => {
          const width = api.getWidth();
          const height = api.getHeight() * 0.85; 
          const d = data[params.dataIndex];
          const [x, y] = ternaryToCartesian(d.a, d.b, d.c, width, height);

          return {
            type: 'circle',
            shape: { cx: x, cy: y, r: 6 },
            style: api.style({
              fill: api.visual('color'),
              stroke: '#fff',
              lineWidth: 1
            })
          };
        },
        data: data
      },
      // Draw Triangle Grid
      {
        type: 'custom',
        renderItem: (params, api) => {
          const width = api.getWidth();
          const height = api.getHeight() * 0.85;
          const size = Math.min(width, height);
          const h = size * sin60;
          const xOffset = (width - size) / 2;
          const yOffset = (height - h) / 2;

          const A = [xOffset + size / 2, yOffset];
          const B = [xOffset + size, yOffset + h];
          const C = [xOffset, yOffset + h];

          return {
            type: 'group',
            children: [
              {
                type: 'polygon',
                shape: { points: [A, B, C] },
                style: { fill: 'none', stroke: axisColor, lineWidth: 2 }
              },
              { type: 'text', style: { text: 'Component A', x: A[0], y: A[1] - 20, textAlign: 'center', fill: axisColor, fontWeight: 'bold' } },
              { type: 'text', style: { text: 'Component B', x: B[0] + 15, y: B[1], textAlign: 'left', fill: axisColor, fontWeight: 'bold' } },
              { type: 'text', style: { text: 'Component C', x: C[0] - 15, y: C[1], textAlign: 'right', fill: axisColor, fontWeight: 'bold' } }
            ]
          };
        },
        data: [0]
      }
    ]
  };
};

