export const DataGrid: React.FC<DataGridProps> = ({ data, columns, isLoading, onDelete, onUpdate, onBatchUpdate, onCategorySelect, selectedIds: propSelectedIds, onSelectionChange }) => {
  const { t, tProp, language } = useLanguage();
  const visibleColumns = columns.filter((c) => c.visible);

  // Use props if available, otherwise local state (for backward compatibility if needed)
  const [localSelectedIds, setLocalSelectedIds] = useState<Set<string>>(new Set());
  const selectedIds = propSelectedIds || localSelectedIds;
  const handleSelectionChange = onSelectionChange || setLocalSelectedIds;

  const [sortConfig, setSortConfig] = useState<SortConfig | null>(null);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [deletingIds, setDeletingIds] = useState<string[]>([]);
  const [isBatchEditOpen, setIsBatchEditOpen] = useState(false);
  const [viewingProduct, setViewingProduct] = useState<Product | null>(null);
  const [isComparisonOpen, setIsComparisonOpen] = useState(false);

  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 15;

  const handleSort = (key: string) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const sortedData = useMemo(() => {
    if (!sortConfig) return data;
    return [...data].sort((a, b) => {
      let aVal: any = a.properties[sortConfig.key]?.value ?? (a as any)[sortConfig.key];
      let bVal: any = b.properties[sortConfig.key]?.value ?? (b as any)[sortConfig.key];

      // Handle numeric strings
      if (!isNaN(Number(aVal)) && !isNaN(Number(bVal)) && aVal !== '' && bVal !== '') {
          aVal = Number(aVal);
          bVal = Number(bVal);
      }

      if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
      if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
  }, [data, sortConfig]);

  const paginatedData = useMemo(() => {
      const start = (currentPage - 1) * pageSize;
      return sortedData.slice(start, start + pageSize);
  }, [sortedData, currentPage]);

  const totalPages = Math.ceil(sortedData.length / pageSize);

  const toggleSelection = (id: string) => {
    const newSelected = new Set(selectedIds);
    if (newSelected.has(id)) newSelected.delete(id);
    else newSelected.add(id);
    handleSelectionChange(newSelected);
  };

  const toggleAll = () => {
    if (selectedIds.size === paginatedData.length && paginatedData.length > 0) {
      handleSelectionChange(new Set());
    } else {
      const newSelected = new Set(selectedIds);
      paginatedData.forEach(p => newSelected.add(p.id));
      handleSelectionChange(newSelected);
    }
  };

  if (isLoading) return <GridSkeleton />;

  return (
    <div className="h-full flex flex-col bg-transparent">
        {/* Toolbar */}
        {selectedIds.size > 0 && (
            <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-50 flex items-center gap-2 px-4 py-2 bg-slate-900/90 dark:bg-white/90 backdrop-blur-md rounded-2xl shadow-2xl text-white dark:text-slate-900 animate-in slide-in-from-bottom-6 border border-white/10 dark:border-slate-300">
                <span className="text-xs font-bold px-2">{selectedIds.size} {t('selected')}</span>
                <div className="h-4 w-px bg-white/20 dark:bg-slate-900/20"></div>
                <button 
                    onClick={() => setIsComparisonOpen(true)}
                    className="p-2 hover:bg-white/10 dark:hover:bg-slate-900/10 rounded-lg transition-colors flex items-center gap-2 text-xs font-bold"
                >
                    <GitCompare size={14} /> Compare
                </button>
                <button 
                    onClick={() => setIsBatchEditOpen(true)}
                    className="p-2 hover:bg-white/10 dark:hover:bg-slate-900/10 rounded-lg transition-colors flex items-center gap-2 text-xs font-bold"
                >
                    <Edit size={14} /> Edit
                </button>
                <button 
                    onClick={() => setDeletingIds(Array.from(selectedIds))}
                    className="p-2 hover:bg-rose-500/80 rounded-lg transition-colors text-rose-300 hover:text-white"
                >
                    <Trash2 size={14} />
                </button>
                <button 
                    onClick={() => handleSelectionChange(new Set())}
                    className="ml-2 p-1.5 hover:bg-white/10 dark:hover:bg-slate-900/10 rounded-full"
                >
                    <X size={12} />
                </button>
            </div>
        )}

      <div className="flex-1 overflow-auto custom-scrollbar relative">
        <table className="w-full text-sm text-left border-separate border-spacing-0">
          <thead className="text-xs text-slate-500 uppercase bg-slate-50/50 dark:bg-slate-900/50 sticky top-0 z-20 backdrop-blur-sm">
            <tr>
              <th className="px-4 py-3 font-medium w-10 border-b border-slate-200 dark:border-slate-800 rounded-tl-xl bg-slate-50 dark:bg-slate-900">
                <div className="flex items-center justify-center">
                  <button onClick={toggleAll} className="text-slate-400 hover:text-emerald-500 transition-colors">
                    {selectedIds.size > 0 && selectedIds.size === paginatedData.length ? <CheckSquare size={16} /> : selectedIds.size > 0 ? <MinusSquare size={16} /> : <Square size={16} />}
                  </button>
                </div>
              </th>
              {visibleColumns.map((col) => (
                <th key={col.key} className="px-4 py-3 font-bold border-b border-slate-200 dark:border-slate-800 hover:bg-slate-100 dark:hover:bg-slate-800/50 transition-colors cursor-pointer select-none whitespace-nowrap bg-slate-50 dark:bg-slate-900" onClick={() => handleSort(col.key)}>
                  <div className="flex items-center gap-1.5">
                    {tProp(col.label)}
                    {sortConfig?.key === col.key && (
                      sortConfig.direction === 'asc' ? <ArrowUp size={12} className="text-emerald-500" /> : <ArrowDown size={12} className="text-emerald-500" />
                    )}
                  </div>
                </th>
              ))}
              <th className="px-4 py-3 font-medium text-right w-20 border-b border-slate-200 dark:border-slate-800 rounded-tr-xl bg-slate-50 dark:bg-slate-900 sticky right-0 z-30 shadow-[-4px_0_8px_-2px_rgba(0,0,0,0.05)]">{t('actions')}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 dark:divide-slate-800/50">
            {paginatedData.map((product) => {
                const isSelected = selectedIds.has(product.id);
                return (
                    <tr 
                        key={product.id} 
                        className={`group transition-all hover:bg-white dark:hover:bg-slate-800 ${isSelected ? 'bg-emerald-50/50 dark:bg-emerald-900/10' : ''}`}
                        onClick={() => toggleSelection(product.id)}
                    >
                        <td className="px-4 py-3 w-10 sticky left-0 z-10 bg-transparent" onClick={e => e.stopPropagation()}>
                            <div className="flex items-center justify-center">
                                <button onClick={() => toggleSelection(product.id)} className={`transition-colors ${isSelected ? 'text-emerald-500' : 'text-slate-300 group-hover:text-slate-400'}`}>
                                    {isSelected ? <CheckSquare size={16} /> : <Square size={16} />}
                                </button>
                            </div>
                        </td>
                        {visibleColumns.map((col) => {
                            if (col.key === 'gradeName') {
                                return (
                                    <td key={col.key} className="px-4 py-3 font-bold text-slate-800 dark:text-white whitespace-nowrap">
                                        <div className="flex items-center gap-2 cursor-pointer hover:text-emerald-600" onClick={(e) => { e.stopPropagation(); setViewingProduct(product); }}>
                                            {product.gradeName}
                                            {product.properties['密度']?.instrument && <FlaskConical size={10} className="text-emerald-500" />}
                                        </div>
                                    </td>
                                );
                            }
                            if (col.key === 'manufacturer') {
                                return (
                                    <td key={col.key} className="px-4 py-3 text-slate-600 dark:text-slate-300 whitespace-nowrap">
                                        <div className="flex items-center gap-2">
                                            <div className="p-1 rounded bg-slate-100 dark:bg-slate-800 text-slate-500"><Factory size={10} /></div>
                                            {product.manufacturer}
                                        </div>
                                    </td>
                                );
                            }
                            const prop = product.properties[col.key];
                            return (
                                <td key={col.key} className="px-4 py-3 text-slate-600 dark:text-slate-400 whitespace-nowrap relative group/cell">
                                    {prop ? (
                                        <div className="flex items-baseline gap-1">
                                            <span className={`font-mono ${typeof prop.value === 'number' ? 'text-emerald-600 dark:text-emerald-400 font-bold' : ''}`}>{prop.value}</span>
                                            {prop.unit && <span className="text-[10px] text-slate-400 select-none">{prop.unit}</span>}
                                            {(prop.instrument || prop.standard) && (
                                                <div className="opacity-0 group-hover/cell:opacity-100 transition-opacity absolute right-2 top-1/2 -translate-y-1/2">
                                                     <Info size={12} className="text-slate-300 hover:text-emerald-500 cursor-help" />
                                                </div>
                                            )}
                                            {/* Tooltip on hover of Info icon could be implemented here or using the tooltip component more generally */}
                                            {(prop.instrument || prop.standard) && <PropertyContextTooltip prop={prop} />}
                                        </div>
                                    ) : (
                                        <span className="text-slate-300 text-xs">-</span>
                                    )}
                                </td>
                            );
                        })}
                        <td className="px-4 py-3 text-right w-20 sticky right-0 z-10 bg-transparent group-hover:bg-white dark:group-hover:bg-slate-800 shadow-[-4px_0_8px_-2px_rgba(0,0,0,0.05)] transition-colors" onClick={e => e.stopPropagation()}>
                            <div className="flex items-center justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                <button onClick={() => setViewingProduct(product)} className="p-1.5 text-slate-400 hover:text-emerald-500 hover:bg-emerald-50 dark:hover:bg-emerald-900/20 rounded-lg transition-colors" title={t('details')}><Eye size={14} /></button>
                                <button onClick={() => setEditingProduct(product)} className="p-1.5 text-slate-400 hover:text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg transition-colors" title={t('editProduct')}><Edit size={14} /></button>
                                <button onClick={() => setDeletingIds([product.id])} className="p-1.5 text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg transition-colors" title={t('delete')}><Trash2 size={14} /></button>
                            </div>
                        </td>
                    </tr>
                );
            })}
            {paginatedData.length === 0 && (
                <tr>
                    <td colSpan={visibleColumns.length + 2} className="py-12 text-center text-slate-400">
                        <div className="flex flex-col items-center gap-2">
                             <div className="w-12 h-12 bg-slate-50 dark:bg-slate-800 rounded-full flex items-center justify-center mb-2"><Info size={24} className="opacity-50" /></div>
                             <p>No products found matching your criteria</p>
                        </div>
                    </td>
                </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination Footer */}
      <div className="flex items-center justify-between px-4 py-3 border-t border-slate-200 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50 backdrop-blur-sm shrink-0">
         <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">
            {t('showing')} <span className="font-bold text-slate-800 dark:text-slate-200">{(currentPage - 1) * pageSize + 1}-{Math.min(currentPage * pageSize, sortedData.length)}</span> of <span className="font-bold text-slate-800 dark:text-slate-200">{sortedData.length}</span>
         </span>
         <div className="flex items-center gap-2">
             <button 
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))} 
                disabled={currentPage === 1}
                className="p-1.5 rounded-lg border border-slate-200 dark:border-slate-700 text-slate-500 hover:bg-white dark:hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
             >
                <ChevronLeft size={16} />
             </button>
             <span className="text-xs font-bold text-slate-700 dark:text-slate-300 min-w-[3rem] text-center">
                {currentPage} / {totalPages || 1}
             </span>
             <button 
                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} 
                disabled={currentPage === totalPages || totalPages === 0}
                className="p-1.5 rounded-lg border border-slate-200 dark:border-slate-700 text-slate-500 hover:bg-white dark:hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
             >
                <ChevronRight size={16} />
             </button>
         </div>
      </div>

      {/* Modals */}
      <EditProductModal 
        isOpen={!!editingProduct} 
        onClose={() => setEditingProduct(null)} 
        product={editingProduct} 
        onSave={async (p) => { onUpdate(p); setEditingProduct(null); }} 
      />
      <DeleteConfirmationModal 
        isOpen={deletingIds.length > 0} 
        onClose={() => setDeletingIds([])} 
        onConfirm={() => { onDelete(deletingIds); setDeletingIds([]); handleSelectionChange(new Set()); }} 
        productNames={deletingIds.map(id => data.find(p => p.id === id)?.gradeName || 'Unknown')} 
      />
      <BatchEditModal
        isOpen={isBatchEditOpen}
        onClose={() => setIsBatchEditOpen(false)}
        selectedProducts={data.filter(p => selectedIds.has(p.id))}
        onSave={(ids, updates) => { onBatchUpdate(ids, updates); handleSelectionChange(new Set()); }}
      />
      <ProductDetailDrawer 
        product={viewingProduct}
        onClose={() => setViewingProduct(null)}
        onCategoryClick={(id) => { onCategorySelect(id); setViewingProduct(null); }}
      />
      {isComparisonOpen && (
          <ComparisonView 
              products={data.filter(p => selectedIds.has(p.id))}
              onClose={() => setIsComparisonOpen(false)}
              onRemoveProduct={(id) => toggleSelection(id)}
          />
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  Settings, LayoutDashboard, X, FileJson, Image as ImageIcon, 
  Sliders, Hexagon, ScatterChart, Waves, Activity, Triangle, 
  Info, Download, Loader2, RefreshCw
} from 'lucide-react';
import * as echarts from 'echarts';
import html2canvas from 'html2canvas';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';

// Import Scientific Chart Configurations
import { getRadarChartOption } from './charts/RadarBenchmark';
import { getAshbyChartOption } from './charts/AshbyScatter';
import { getGpcChartOption } from './charts/GpcDistribution';
import { getRheologyChartOption } from './charts/RheologyCurve';
import { getTernaryChartOption } from './charts/TernaryBlend';

interface DataVisualizerProps {
  data: Product[];
  selectedProducts?: Product[];
}

type ChartType = 'radar' | 'ashby' | 'gpc' | 'rheology' | 'ternary';

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data, selectedProducts }) => {
  const { t, tProp } = useLanguage();
  const { theme } = useTheme();

  const chartRef = useRef<HTMLDivElement>(null);
  const chartInstance = useRef<echarts.ECharts | null>(null);

  const [activeChart, setActiveChart] = useState<ChartType>('radar');
  const [showConfig, setShowConfig] = useState(true);
  const [isExporting, setIsExporting] = useState(false);

  // Determine which data set to use for visualization
  const visualizationData = useMemo(() => {
    return (selectedProducts && selectedProducts.length > 0) ? selectedProducts : data;
  }, [data, selectedProducts]);

  // --- Data Preparation Logic ---

  // 1. Radar Data: Compare top 3 (or selected) products
  const radarData = useMemo(() => {
    const source = visualizationData.slice(0, 5); // Limit to 5 for radar clarity
    return source.map(p => ({
      name: p.gradeName,
      value: [
        parseFloat(String(p.properties['熔体质量流动速率']?.value || 0)),
        parseFloat(String(p.properties['密度']?.value || 0)),
        parseFloat(String(p.properties['弯曲模量']?.value || 0)),
        parseFloat(String(p.properties['悬臂梁缺口冲击强度']?.value || 0)),
        parseFloat(String(p.properties['热变形温度']?.value || 0))
      ]
    }));
  }, [visualizationData]);

  // 2. Ashby Data: MFR vs Impact
  const ashbyData = useMemo(() => {
    // Group by manufacturer for series
    const groups: Record<string, any[]> = {};
    visualizationData.forEach(p => {
      const man = p.manufacturer;
      if (!groups[man]) groups[man] = [];
      const mfr = parseFloat(String(p.properties['熔体质量流动速率']?.value));
      const impact = parseFloat(String(p.properties['悬臂梁缺口冲击强度']?.value));

      if (!isNaN(mfr) && !isNaN(impact) && mfr > 0) {
        groups[man].push([mfr, impact, p.gradeName]);
      }
    });

    return Object.entries(groups).map(([name, points]) => ({
      name,
      data: points
    }));
  }, [visualizationData]);

  // 5. Ternary Data: Mock Formulation (Simulated based on properties)
  const ternaryData = useMemo(() => {
    return visualizationData.slice(0, 50).map((p, i) => {
        // Simulate formulation based on index/random for demo purposes
        // In real app, this would come from `p.composition`
        let a = 0.1 + Math.random() * 0.8;
        let b = 0.1 + Math.random() * (0.9 - a);
        let c = 1 - a - b;
        // Ensure strictly positive
        if (c < 0) { a=0.33; b=0.33; c=0.34; }

        return {
            a, b, c,
            name: p.gradeName,
            value: parseFloat(String(p.properties['拉伸强度']?.value || Math.floor(Math.random() * 60) + 20))
        };
    });
  }, [visualizationData]);

  // --- Render Chart Effect ---
  useEffect(() => {
    if (!chartRef.current) return;

    // Dispose old instance if exists to prevent memory leaks or context conflicts
    if (chartInstance.current) {
      chartInstance.current.dispose();
    }

    // Init new instance
    chartInstance.current = echarts.init(chartRef.current);

    let option = {};

    try {
        switch (activeChart) {
            case 'radar':
                option = getRadarChartOption(radarData, theme);
                break;
            case 'ashby':
                option = getAshbyChartOption(ashbyData, theme);
                break;
            case 'gpc':
                // Pass visualizationData to GPC chart
                option = getGpcChartOption(visualizationData, theme); 
                break;
            case 'rheology':
                // Pass visualizationData to Rheology chart
                option = getRheologyChartOption(visualizationData, theme);
                break;
            case 'ternary':
                option = getTernaryChartOption(ternaryData, theme);
                break;
        }

        chartInstance.current.setOption(option);
    } catch (e) {
        console.error("Chart Render Error:", e);
    }

    const handleResize = () => chartInstance.current?.resize();
    window.addEventListener('resize', handleResize);

    return () => {
        window.removeEventListener('resize', handleResize);
        chartInstance.current?.dispose();
        chartInstance.current = null;
    };
  }, [activeChart, theme, radarData, ashbyData, ternaryData, visualizationData]);

  const handleExport = async (format: 'png' | 'json') => {
      setIsExporting(true);
      if (format === 'png' && chartRef.current) {
          try {
            const canvas = await html2canvas(chartRef.current);
            const a = document.createElement('a');
            a.href = canvas.toDataURL('image/png', 1.0);
            a.download = `resindb_${activeChart}_analysis.png`;
            a.click();
          } catch(e) { console.error(e); }
      } else if (format === 'json') {
          const jsonStr = JSON.stringify(activeChart === 'radar' ? radarData : ashbyData, null, 2);
          const blob = new Blob([jsonStr], {type: 'application/json'});
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `resindb_${activeChart}_data.json`;
          a.click();
      }
      setIsExporting(false);
  };

  const chartDescriptions = {
      radar: "Compare comprehensive performance balance (Stiffness-Toughness-Processability) against benchmarks.",
      ashby: "Analyze trade-offs between Flowability (MFR) and Impact Strength. Identify technological frontiers.",
      gpc: "Visualize Molecular Weight Distribution (MWD). Distinguish between Uni-modal and Bi-modal grades.",
      rheology: "Study shear-thinning behavior (Viscosity vs Shear Rate) critical for processing simulation.",
      ternary: "Optimize blends and formulations by mapping properties to 3-component composition ratios."
  };

  return (
    <div className="flex flex-col md:flex-row h-full gap-4 overflow-hidden">
      {/* Scientific Controls Sidebar */}
      <div className={`flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl transition-all duration-500 ease-out shrink-0 overflow-hidden shadow-xl ${showConfig ? 'w-full md:w-72 opacity-100 translate-x-0' : 'w-0 opacity-0 -translate-x-10 border-0 pointer-events-none'}`}>
        <div className="p-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50/80 dark:bg-slate-950/50 backdrop-blur-sm">
          <div className="flex items-center gap-2 font-black text-sm text-slate-800 dark:text-white uppercase tracking-widest">
            <Activity size={16} className="text-emerald-500" />
            Analysis Mode
          </div>
          <button onClick={() => setShowConfig(false)} className="md:hidden text-slate-400 hover:text-slate-600">
            <X size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar space-y-2">
            {[
                { id: 'radar', label: 'Fingerprint (Radar)', icon: Hexagon, color: 'text-indigo-500' },
                { id: 'ashby', label: 'Ashby Map (Scatter)', icon: ScatterChart, color: 'text-rose-500' },
                { id: 'gpc', label: 'GPC Distribution', icon: Waves, color: 'text-blue-500' },
                { id: 'rheology', label: 'Rheology Curve', icon: Activity, color: 'text-amber-500' },
                { id: 'ternary', label: 'Ternary Phase', icon: Triangle, color: 'text-emerald-500' },
            ].map(item => (
                <button 
                    key={item.id}
                    onClick={() => setActiveChart(item.id as ChartType)}
                    className={`w-full flex items-center gap-3 p-3 rounded-2xl border transition-all duration-200 group relative overflow-hidden ${
                        activeChart === item.id 
                        ? 'bg-slate-900 dark:bg-white text-white dark:text-slate-900 border-transparent shadow-lg' 
                        : 'bg-white dark:bg-slate-800/50 border-slate-100 dark:border-slate-800 text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800'
                    }`}
                >
                    <div className={`p-2 rounded-xl bg-slate-100 dark:bg-slate-700/50 ${activeChart === item.id ? 'bg-white/20 text-white' : item.color}`}>
                        <item.icon size={18} />
                    </div>
                    <span className="text-xs font-bold uppercase tracking-wide">{item.label}</span>
                    {activeChart === item.id && <div className="absolute right-0 top-0 bottom-0 w-1 bg-emerald-500"></div>}
                </button>
            ))}

            <div className="mt-6 p-4 bg-slate-50 dark:bg-slate-950/30 rounded-2xl border border-slate-100 dark:border-slate-800">
                <div className="flex items-center gap-2 mb-2 text-slate-400 dark:text-slate-500">
                    <Info size={14} />
                    <span className="text-[10px] font-bold uppercase tracking-widest">Chart Context</span>
                </div>
                <p className="text-xs text-slate-600 dark:text-slate-300 leading-relaxed font-medium">
                    {chartDescriptions[activeChart]}
                </p>
            </div>
        </div>

        <div className="p-4 border-t border-slate-100 dark:border-slate-800 grid grid-cols-2 gap-3">
            <button onClick={() => handleExport('json')} className="flex items-center justify-center gap-2 p-3 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-xl text-[10px] font-bold text-slate-600 dark:text-slate-300 transition-colors uppercase tracking-wider"><FileJson size={14} /> JSON</button>
            <button onClick={() => handleExport('png')} disabled={isExporting} className="flex items-center justify-center gap-2 p-3 bg-emerald-600 hover:bg-emerald-500 disabled:opacity-70 text-white rounded-xl text-[10px] font-bold transition-all uppercase tracking-wider shadow-lg">{isExporting ? <Loader2 size={14} className="animate-spin" /> : <ImageIcon size={14} />} EXPORT</button>
        </div>
      </div>

      {/* Chart Canvas */}
      <div className="flex-1 flex flex-col bg-white/50 dark:bg-slate-900/50 backdrop-blur-xl border border-slate-200 dark:border-slate-800 rounded-[2rem] relative min-h-[500px] shadow-2xl overflow-hidden">
         {!showConfig && (
             <button onClick={() => setShowConfig(true)} className="absolute top-6 right-6 z-30 p-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-slate-500 hover:text-emerald-500 shadow-xl transition-all hover:scale-105 active:scale-95">
                <Settings size={20} />
             </button>
         )}

         <div className="flex-1 w-full h-full p-4 relative">
            <div ref={chartRef} className="w-full h-full" />

            {/* Watermark / Brand */}
            <div className="absolute bottom-6 right-6 pointer-events-none opacity-10 flex flex-col items-end">
                <span className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter">ResinDB</span>
                <span className="text-xs font-bold uppercase tracking-widest text-slate-500">Scientific Visualization</span>
            </div>
         </div>
      </div>
    </div>
  );
};

