// Chart 3: Molecular Weight Distribution (GPC) Option Configuration
export const getGpcChartOption = (products: any[], theme: 'light' | 'dark'): echarts.EChartsOption => {
  const isDark = theme === 'dark';
  const colorPalette = ['#37A2DA', '#32C5E9', '#67E0E3', '#9FE6B8', '#FFDB5C'];
  const axisColor = isDark ? '#94a3b8' : '#333333';
  const gridColor = isDark ? '#334155' : '#e0e0e0';

  // Generate curves based on product data (simulation)
  const series = products.map((p, idx) => {
      const data = [];
      const mfr = parseFloat(p.properties['熔体质量流动速率']?.value || 1);
      const safeMfr = isNaN(mfr) ? 1 : mfr;
      // High MFR = Low MW (Shift Left)
      const peakLogMw = 5.5 - (Math.log10(safeMfr) * 0.4); 

      const isBimodal = p.gradeName.includes('High') || p.gradeName.includes('Pipe') || (Math.random() > 0.7);

      for (let i = 3; i <= 7; i += 0.05) {
        let val = 0;
        const xVal = Math.pow(10, i);
        if (isBimodal) {
            // Main Peak + Shoulder
            val = 0.7 * Math.exp(-Math.pow(i - peakLogMw, 2) / (2 * 0.25)) + 
                  0.4 * Math.exp(-Math.pow(i - (peakLogMw + 0.8), 2) / (2 * 0.2));
        } else {
            // Single Peak
            val = 1.0 * Math.exp(-Math.pow(i - peakLogMw, 2) / (2 * 0.2));
        }
        data.push([xVal, val]);
      }

      return {
        name: p.gradeName,
        type: 'line',
        smooth: 0.4,
        showSymbol: false,
        data: data,
        lineStyle: { width: 3 },
        areaStyle: {
          color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
            { offset: 0, color: colorPalette[idx % colorPalette.length] + '40' }, // 25% opacity
            { offset: 1, color: colorPalette[idx % colorPalette.length] + '00' }
          ])
        },
        markArea: idx === 0 ? {
            itemStyle: { color: 'rgba(200, 200, 200, 0.1)' },
            data: [
                [{ name: 'Processability Zone (Low Mw)', xAxis: 1000 }, { xAxis: 30000 }],
                [{ name: 'Strength Zone (High Mw)', xAxis: 300000 }, { xAxis: 10000000 }]
            ],
            label: { position: 'top', color: axisColor, fontSize: 10 }
        } : undefined
      };
  });

  return {
    backgroundColor: 'transparent',
    color: colorPalette,
    title: {
      text: '分子量分布 (GPC Distribution)',
      subtext: 'Polymerization Uniformity Analysis',
      left: 'center',
      textStyle: { color: isDark ? '#e2e8f0' : '#333333', fontSize: 16 }
    },
    tooltip: {
      trigger: 'axis',
      confine: true,
      backgroundColor: isDark ? 'rgba(15, 23, 42, 0.9)' : 'rgba(255, 255, 255, 0.95)',
      formatter: (params: any) => {
        let html = `<div style="margin-bottom:4px;font-weight:bold">Mw: ${params[0].value[0].toExponential(2)}</div>`;
        params.forEach((p: any) => {
          html += `<div style="color:${p.color}">${p.seriesName}: ${p.value[1].toFixed(3)}</div>`;
        });
        return html;
      }
    },
    legend: {
      top: 50,
      textStyle: { color: axisColor }
    },
    grid: {
      containLabel: true,
      left: '8%',
      right: '8%',
      bottom: '10%'
    },
    xAxis: {
      type: 'log',
      name: 'Molecular Weight (Mw) [g/mol]',
      nameLocation: 'middle',
      nameGap: 30,
      min: 1000,
      max: 10000000,
      logBase: 10,
      axisLabel: { 
          color: axisColor,
          formatter: (value: number) => value.toExponential(0)
      },
      splitLine: { show: true, lineStyle: { color: gridColor, type: 'dashed' } },
      axisLine: { lineStyle: { color: '#888' } }
    },
    yAxis: {
      type: 'value',
      name: 'Normalized Intensity (dw/dlogM)',
      nameLocation: 'middle',
      nameGap: 40,
      splitLine: { show: true, lineStyle: { color: gridColor, type: 'dashed' } },
