// Chart 5: Ternary Plot Option Configuration
export const getTernaryChartOption = (data: any[], theme: 'light' | 'dark'): echarts.EChartsOption => {
  const isDark = theme === 'dark';
  const axisColor = isDark ? '#94a3b8' : '#333333';

  // Triangle Geometry
  // A (Bottom-Left), B (Bottom-Right), C (Top)
  // X = B + C/2
  // Y = C * sin(60)
  const sin60 = Math.sqrt(3) / 2;

  // Convert (a, b, c) percentages to (x, y) coordinates relative to a 100x100 box
  const ternaryToCartesian = (a: number, b: number, c: number, width: number, height: number) => {
    // Normalize to 0-1
    const sum = a + b + c;
    const an = a / sum; // Component A
    const bn = b / sum; // Component B
    const cn = c / sum; // Component C

    // We assume Origin A is at (0,0) in ternary space for X calc logic?
    // Wait, let's use the Prompt's formula: X = B + C/2
    // If A=1, X=0, Y=0 (Origin) -> This implies A is Origin.
    // If B=1, X=1, Y=0
    // If C=1, X=0.5, Y=sin60

    // So visual triangle:
    // Left Corner: A (100%)
    // Right Corner: B (100%)
    // Top Corner: C (100%)

    const xNorm = bn + cn / 2;
    const yNorm = cn * sin60;

    // Scale to canvas
    // Needs centering in the container
    const size = Math.min(width, height) * 0.8;
    const xOffset = (width - size) / 2;
    const yOffset = (height - (size * sin60)) / 2 + (size * sin60); // Invert Y for canvas coords? No, ECharts Y is top-down

    // ECharts Y 0 is top. We want Y 0 to be bottom.
    // Screen X = xOffset + xNorm * size
    // Screen Y = (Height - yOffset) - yNorm * size

    const sx = xOffset + xNorm * size;
    const sy = (height - yOffset) - yNorm * size; // Flip Y for display

    return [sx, sy];
  };

  // Generate Frame Points
  // A: (0, 0) -> (0, 0)
  // B: (0, 1, 0) -> (1, 0)
  // C: (0, 0, 1) -> (0.5, sin60)

  return {
    backgroundColor: 'transparent',
    title: {
      text: '三元相图 (Ternary Phase Plot)',
      subtext: 'Optimization: Component A + B + C = 100%',
      left: 'center',
      textStyle: { color: isDark ? '#e2e8f0' : '#333333', fontSize: 16 }
    },
    tooltip: {
      formatter: (params: any) => {
        const d = params.data;
        if (!d || !d.a) return '';
        return `
          <b>${d.name || 'Sample'}</b><br/>
          Comp A: ${(d.a * 100).toFixed(1)}%<br/>
          Comp B: ${(d.b * 100).toFixed(1)}%<br/>
          Comp C: ${(d.c * 100).toFixed(1)}%<br/>
          Performance: <b>${d.value.toFixed(1)}</b>
        `;
      }
    },
    visualMap: {
      min: 20,
      max: 100,
      dimension: 3, // The 'value' is actually not in 'data' array directly for custom series, handled in renderItem?
      // Actually visualMap works on series data values.
      calculable: true,
      orient: 'vertical',
      right: 10,
      top: 'center',
      text: ['High', 'Low'],
      textStyle: { color: axisColor },
      inRange: {
        color: ['#37A2DA', '#9FE6B8', '#FFDB5C', '#fb7293'] 
      }
    },
    series: [
      {
        type: 'custom',
        renderItem: (params, api) => {
          const width = api.getWidth();
          const height = api.getHeight();
          const size = Math.min(width, height) * 0.8;
          const xOffset = (width - size) / 2;
          const yOffset = (height - (size * sin60)) / 2; // Top margin

          // Vertices in Screen Coords
          // A (Bottom Left)
          const Ax = xOffset;
          const Ay = height - yOffset;

          // B (Bottom Right)
          const Bx = xOffset + size;
          const By = height - yOffset;

          // C (Top)
          const Cx = xOffset + size / 2;
          const Cy = height - yOffset - size * sin60;

          // Background Triangle
          if (params.dataIndex === 0) {
              return {
                  type: 'group',
                  children: [
                      {
                          type: 'polygon',
                          shape: { points: [[Ax, Ay], [Bx, By], [Cx, Cy]] },
                          style: { fill: isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.02)', stroke: axisColor, lineWidth: 2 }
                      },
                      // Labels
                      { type: 'text', style: { text: 'Comp A', x: Ax - 10, y: Ay + 15, fill: axisColor, fontWeight: 'bold' } },
                      { type: 'text', style: { text: 'Comp B', x: Bx - 10, y: By + 15, fill: axisColor, fontWeight: 'bold' } },
                      { type: 'text', style: { text: 'Comp C', x: Cx - 20, y: Cy - 20, fill: axisColor, fontWeight: 'bold' } },
                      // Grid lines (approx)
                      { type: 'line', shape: { x1: (Ax+Cx)/2, y1: (Ay+Cy)/2, x2: (Bx+Cx)/2, y2: (By+Cy)/2 }, style: { stroke: axisColor, lineDash: [4, 4], opacity: 0.3 } },
                      { type: 'line', shape: { x1: (Ax+Bx)/2, y1: Ay, x2: (Ax+Bx)/2, y2: Ay - (Ay-Cy)/2 }, style: { stroke: axisColor, lineDash: [4, 4], opacity: 0.3 } }
                  ]
              };
          }
          return null; // Only draw grid once
        },
        data: [0]
      },
      {
        name: 'Blend Samples',
        type: 'custom',
        renderItem: (params, api) => {
          const width = api.getWidth();
          const height = api.getHeight();
          const d = data[params.dataIndex];
          const size = Math.min(width, height) * 0.8;
          const xOffset = (width - size) / 2;
          const yOffset = (height - (size * sin60)) / 2;

          // Calculate normalized barycentric coords
          // X_norm = b + c/2
          // Y_norm = c * sin60
          const sum = d.a + d.b + d.c;
          const bn = d.b / sum;
          const cn = d.c / sum;

          const xNorm = bn + cn / 2;
          const yNorm = cn * sin60;

          const x = xOffset + xNorm * size;
          const y = (height - yOffset) - yNorm * size;

          const color = api.visual('color');

          return {
            type: 'circle',
            shape: { cx: x, cy: y, r: 8 },
            style: {
              fill: color,
              stroke: '#fff',
              lineWidth: 1,
              shadowBlur: 3,
              shadowColor: 'rgba(0,0,0,0.3)'
            }
          };
        },
        data: data
      }
    ]
  };
};

import React, { useMemo } from 'react';
import { X, ChevronRight, Layers, Factory, Microscope, LayoutGrid, Globe, Info, BookOpen, ExternalLink, Calendar, FileText, ShieldCheck, Link2, Activity, Flame, Zap, TestTube, Box, FlaskConical, Beaker } from 'lucide-react';
