import React, { useEffect, useRef, useState, useMemo, useCallback } from 'react';
import * as echarts from 'echarts';
import { Loader2, AlertCircle, Database, RefreshCw, BarChart3 } from 'lucide-react';
import { useTheme } from '../contexts/ThemeContext';
import { getRadarChartOption } from './charts/RadarBenchmark';
import { getAshbyChartOption } from './charts/AshbyScatter';
import { getGpcChartOption } from './charts/GpcDistribution';
import { getRheologyChartOption } from './charts/RheologyCurve';
import { getTernaryChartOption } from './charts/TernaryBlend';

export type ChartType = 'radar' | 'ashby' | 'gpc' | 'rheology' | 'ternary';

interface ScientificChartProps {
  type: ChartType;
  data: any;
  loading?: boolean;
  className?: string;
  height?: string | number;
  onChartReady?: (instance: echarts.ECharts) => void;
}

export const ScientificChart: React.FC<ScientificChartProps> = ({ 
  type, 
  data, 
  loading = false, 
  className = "", 
  height = "100%",
  onChartReady 
}) => {
  const chartRef = useRef<HTMLDivElement>(null);
  const chartInstance = useRef<echarts.ECharts | null>(null);
  const resizeObserver = useRef<ResizeObserver | null>(null);
  const { theme } = useTheme();

  const [error, setError] = useState<string | null>(null);
  const [isChartEmpty, setIsChartEmpty] = useState(false);

  // 1. Safe Dispose Helper
  const disposeChart = useCallback(() => {
    if (chartInstance.current) {
      chartInstance.current.dispose();
      chartInstance.current = null;
    }
  }, []);

  // 2. Data Validation Logic
  const validateData = useCallback(() => {
    if (!data) return false;
    if (Array.isArray(data) && data.length === 0) return false;
    // Specific check for Ashby/Series structure
    if (type === 'ashby' && Array.isArray(data) && data.every(s => !s.data || s.data.length === 0)) return false;
    return true;
  }, [data, type]);

  // 3. Option Generation with Safety Injection
  const getOption = useCallback(() => {
    try {
        let option: any = {};

        switch (type) {
            case 'radar': option = getRadarChartOption(data, theme); break;
            case 'ashby': option = getAshbyChartOption(data, theme); break;
            case 'gpc': option = getGpcChartOption(data, theme); break;
            case 'rheology': option = getRheologyChartOption(data, theme); break;
            case 'ternary': option = getTernaryChartOption(data, theme); break;
            default: throw new Error(`Unknown chart type: ${type}`);
        }

        // --- The "Zero-Glitch" Protocol Enforcements ---

        // Force Grid Containment
        if (option.grid) {
            option.grid.containLabel = true;
        }

        // Force Tooltip Confinement
        if (option.tooltip) {
            option.tooltip.confine = true;
            option.tooltip.appendToBody = true; // Fix z-index issues in modals/drawers
        }

        // Safe Log Axis Handling (prevent crash on 0)
        ['xAxis', 'yAxis'].forEach(axis => {
            if (option[axis] && option[axis].type === 'log') {
               option[axis].logBase = 10;
               // Ensure we don't have extremely small values that break rendering
               if (!option[axis].min) option[axis].min = (v: any) => v.min > 0 ? v.min * 0.9 : 1; 
            }
        });

        return option;
    } catch (err: any) {
        console.error("Chart Option Generation Error:", err);
        throw new Error(err.message || "Failed to generate visualization configuration");
    }
  }, [type, data, theme]);

  // 4. Main Lifecycle Effect
  useEffect(() => {
    // A. Pre-flight Checks
    if (!chartRef.current) return;

    // Check for empty data
    if (!validateData()) {
        setIsChartEmpty(true);
        disposeChart();
        return;
    }
    setIsChartEmpty(false);
    setError(null);

    // B. Initialization
    if (!chartInstance.current) {
        chartInstance.current = echarts.init(chartRef.current, undefined, { renderer: 'canvas' });
        if (onChartReady) onChartReady(chartInstance.current);
    }

    // C. Render with Error Boundary
    try {
        const option = getOption();
        chartInstance.current.setOption(option, { notMerge: true }); // notMerge=true prevents ghost data
    } catch (err: any) {
        setError(err.message);
        disposeChart();
    }

    // D. Robust Resizing
    if (!resizeObserver.current) {
        resizeObserver.current = new ResizeObserver((entries) => {
            if (!chartInstance.current) return;

            // Debounce resize slightly or check if dimensions actually changed
            for (const entry of entries) {
                if (entry.contentRect.width > 0 && entry.contentRect.height > 0) {
                    chartInstance.current.resize();
                }
            }
        });
        resizeObserver.current.observe(chartRef.current);
    }

    // E. Cleanup
    return () => {
        // We don't dispose on every render, only unmount. 
        // Note: React 18 strict mode might double invoke, but ref check handles it.
    };
  }, [data, theme, type, validateData, getOption, disposeChart, onChartReady]);

  // Dispose on unmount
  useEffect(() => {
      return () => {
          if (resizeObserver.current) resizeObserver.current.disconnect();
          disposeChart();
      };
  }, [disposeChart]);


  // --- Render States ---

  if (error) {
      return (
          <div className={`flex flex-col items-center justify-center bg-rose-50/50 dark:bg-rose-900/10 border border-rose-100 dark:border-rose-900/30 rounded-2xl ${className}`} style={{ height }}>
              <AlertCircle className="text-rose-500 mb-2" size={24} />
              <p className="text-xs font-bold text-rose-600 dark:text-rose-400">Visualization Error</p>
              <p className="text-[10px] text-rose-400 mt-1 max-w-[200px] text-center">{error}</p>
          </div>
      );
  }

  return (
    <div className={`relative w-full ${className}`} style={{ height }}>

        {/* The Chart Container */}
        <div 
            ref={chartRef} 
            className={`w-full h-full transition-opacity duration-500 ${loading || isChartEmpty ? 'opacity-0' : 'opacity-100'}`} 
        />

        {/* Loading Overlay */}
        {loading && (
            <div className="absolute inset-0 z-10 flex flex-col items-center justify-center bg-white/80 dark:bg-slate-900/80 backdrop-blur-sm rounded-2xl transition-all duration-300">
                <Loader2 className="w-8 h-8 text-emerald-500 animate-spin mb-3" />
                <span className="text-xs font-bold text-slate-500 dark:text-slate-400 animate-pulse">Processing Data...</span>
            </div>
        )}

        {/* Empty State Overlay */}
        {!loading && isChartEmpty && (
            <div className="absolute inset-0 z-10 flex flex-col items-center justify-center bg-slate-50/50 dark:bg-slate-900/50 rounded-2xl border border-dashed border-slate-200 dark:border-slate-800">
                <div className="p-4 bg-white dark:bg-slate-800 rounded-full shadow-sm mb-3">
                    <BarChart3 className="text-slate-300 dark:text-slate-600" size={24} />
                </div>
                <p className="text-sm font-bold text-slate-500 dark:text-slate-400">No Data Available</p>
                <p className="text-[10px] text-slate-400 mt-1">Select products to visualize {type} analysis</p>
            </div>
        )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { 
  Settings, Activity, X, FileJson, Image as ImageIcon, 
  Hexagon, ScatterChart, Waves, Triangle, Info, Loader2 
} from 'lucide-react';
import * as echarts from 'echarts';
import html2canvas from 'html2canvas';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { ScientificChart, ChartType } from './ScientificChart';

interface DataVisualizerProps {
  data: Product[];
  selectedProducts?: Product[];
}

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data, selectedProducts }) => {
  const { t } = useLanguage();

  // We keep a ref to the chart instance exposed by ScientificChart for exporting
  const [chartInstance, setChartInstance] = useState<echarts.ECharts | null>(null);

  const [activeChart, setActiveChart] = useState<ChartType>('radar');
  const [showConfig, setShowConfig] = useState(true);
  const [isExporting, setIsExporting] = useState(false);

  // Determine which data set to use for visualization
  const visualizationData = useMemo(() => {
    return (selectedProducts && selectedProducts.length > 0) ? selectedProducts : data;
  }, [data, selectedProducts]);

  // --- Data Preparation Logic ---

  // 1. Radar Data: Compare top 5 (or selected) products
  const radarData = useMemo(() => {
    const source = visualizationData.slice(0, 5); // Limit to 5 for radar clarity
    return source.map(p => ({
      name: p.gradeName,
      value: [
        parseFloat(String(p.properties['熔体质量流动速率']?.value || 0)),
        parseFloat(String(p.properties['密度']?.value || 0)),
        parseFloat(String(p.properties['弯曲模量']?.value || 0)),
        parseFloat(String(p.properties['悬臂梁缺口冲击强度']?.value || 0)),
        parseFloat(String(p.properties['热变形温度']?.value || 0))
      ]
    }));
  }, [visualizationData]);

  // 2. Ashby Data: MFR vs Impact
  const ashbyData = useMemo(() => {
    const groups: Record<string, any[]> = {};
    visualizationData.forEach(p => {
      const man = p.manufacturer;
      if (!groups[man]) groups[man] = [];
      const mfr = parseFloat(String(p.properties['熔体质量流动速率']?.value));
      const impact = parseFloat(String(p.properties['悬臂梁缺口冲击强度']?.value));

      if (!isNaN(mfr) && !isNaN(impact) && mfr > 0) {
        groups[man].push([mfr, impact, p.gradeName]);
      }
    });

    return Object.entries(groups).map(([name, points]) => ({
      name,
      data: points
    }));
  }, [visualizationData]);

  // 5. Ternary Data: Mock Formulation (Simulated based on properties)
  const ternaryData = useMemo(() => {
    return visualizationData.slice(0, 50).map((p, i) => {
        let a = 0.1 + Math.random() * 0.8;
