  }, [allProducts, selectedCategoryId, searchQuery]);

  const handleExport = async () => {
    if (isExporting) return;
    setIsExporting(true);
    // Simulate export delay
    await new Promise(resolve => setTimeout(resolve, 1000));

    try {
        const headers = ['ID', 'Grade', 'Manufacturer', 'Category', 'Updated', 'Properties'];
        const rows = filteredData.map(p => {
            const propsStr = Object.entries(p.properties)
                .map(([k, v]) => `${k}:${v.value}${v.unit ? v.unit : ''}`)
                .join('; ');
            return [
                p.id,
                `"${p.gradeName}"`,
                `"${p.manufacturer}"`,
                p.categoryIds.join('|'),
                p.updatedAt,
                `"${propsStr}"`
            ].join(',');
        });

        const csvContent = [headers.join(','), ...rows].join('\n');
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.setAttribute("href", url);
        link.setAttribute("download", `resindb_export_${new Date().toISOString().slice(0,10)}.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    } catch (e) {
        console.error("Export failed", e);
    } finally {
        setIsExporting(false);
    }
  };

  if (!currentUser) return <AuthScreen onLogin={handleLogin} />;

