      gpc: "Visualize Molecular Weight Distribution (MWD). Distinguish between Uni-modal and Bi-modal grades.",
      rheology: "Study shear-thinning behavior (Viscosity vs Shear Rate) critical for processing simulation.",
      ternary: "Optimize blends and formulations by mapping properties to 3-component composition ratios."
  };

