import * as echarts from 'echarts';

// Chart 5: Ternary Plot Option Configuration
export const getTernaryChartOption = (data: any[], theme: 'light' | 'dark'): echarts.EChartsOption => {
  const isDark = theme === 'dark';
  const axisColor = isDark ? '#94a3b8' : '#333333';
  const sin60 = Math.sqrt(3) / 2;

  // FIX: Transform object data to flat array for ECharts VisualMap compatibility
  // New Schema: [a, b, c, value, name]
  // Dimensions: 0, 1, 2, 3,     4
  const seriesData = data.map(item => [
      item.a, 
      item.b, 
      item.c, 
      item.value, 
      item.name
  ]);

  return {
    backgroundColor: 'transparent',
    title: {
      text: '三元相图 (Ternary Phase Plot)',
      subtext: 'Optimization: Component A + B + C = 100%',
      left: 'center',
      textStyle: { color: isDark ? '#e2e8f0' : '#333333', fontSize: 16 }
    },
    tooltip: {
      formatter: (params: any) => {
        const d = params.data; // Now an array: [a, b, c, value, name]
        if (!Array.isArray(d)) return '';
        return `
          <b>${d[4] || 'Sample'}</b><br/>
          Comp A: ${(d[0] * 100).toFixed(1)}%<br/>
          Comp B: ${(d[1] * 100).toFixed(1)}%<br/>
          Comp C: ${(d[2] * 100).toFixed(1)}%<br/>
          Performance: <b>${(d[3] as number).toFixed(1)}</b>
        `;
      }
    },
    visualMap: {
      min: 20,
      max: 100,
      dimension: 3, // Correctly points to 'value' at index 3 in the array
      calculable: true,
      orient: 'vertical',
      right: 10,
      top: 'center',
      text: ['High', 'Low'],
      textStyle: { color: axisColor },
      inRange: {
        color: ['#37A2DA', '#9FE6B8', '#FFDB5C', '#fb7293'] 
      }
    },
    series: [
      {
        name: 'Background Frame',
        type: 'custom',
        renderItem: (params, api) => {
          const width = api.getWidth();
          const height = api.getHeight();
          const size = Math.min(width, height) * 0.8;
          const xOffset = (width - size) / 2;
          const yOffset = (height - (size * sin60)) / 2;

          // Vertices in Screen Coords
          const Ax = xOffset;
          const Ay = height - yOffset;
          const Bx = xOffset + size;
          const By = height - yOffset;
          const Cx = xOffset + size / 2;
          const Cy = height - yOffset - size * sin60;

          return {
              type: 'group',
              children: [
                  {
                      type: 'polygon',
                      shape: { points: [[Ax, Ay], [Bx, By], [Cx, Cy]] },
                      style: { fill: isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.02)', stroke: axisColor, lineWidth: 2 }
                  },
                  // Labels
                  { type: 'text', style: { text: 'Comp A', x: Ax - 10, y: Ay + 15, fill: axisColor, fontWeight: 'bold' } },
                  { type: 'text', style: { text: 'Comp B', x: Bx - 10, y: By + 15, fill: axisColor, fontWeight: 'bold' } },
                  { type: 'text', style: { text: 'Comp C', x: Cx - 20, y: Cy - 20, fill: axisColor, fontWeight: 'bold' } },
                  // Grid lines (approx)
                  { type: 'line', shape: { x1: (Ax+Cx)/2, y1: (Ay+Cy)/2, x2: (Bx+Cx)/2, y2: (By+Cy)/2 }, style: { stroke: axisColor, lineDash: [4, 4], opacity: 0.3 } },
                  { type: 'line', shape: { x1: (Ax+Bx)/2, y1: Ay, x2: (Ax+Bx)/2, y2: Ay - (Ay-Cy)/2 }, style: { stroke: axisColor, lineDash: [4, 4], opacity: 0.3 } }
              ]
          };
        },
        data: [[0]] // Dummy data to trigger one render
      },
      {
        name: 'Blend Samples',
        type: 'custom',
        renderItem: (params, api) => {
          const width = api.getWidth();
          const height = api.getHeight();
          const size = Math.min(width, height) * 0.8;
          const xOffset = (width - size) / 2;
          const yOffset = (height - (size * sin60)) / 2;

          // SAFE DATA ACCESS: Use api.value(index) to get array items
          const a = api.value(0) as number; // Index 0: a
          const b = api.value(1) as number; // Index 1: b
          const c = api.value(2) as number; // Index 2: c

          // Coordinate Calculation
          const sum = a + b + c;
          // Avoid division by zero
          const safeSum = sum === 0 ? 1 : sum;
          const bn = b / safeSum;
          const cn = c / safeSum;

          const xNorm = bn + cn / 2;
          const yNorm = cn * sin60;

          const x = xOffset + xNorm * size;
          const y = (height - yOffset) - yNorm * size;

          // Safe Visual Access
          const color = api.visual('color');

          return {
            type: 'circle',
            shape: { cx: x, cy: y, r: 8 },
            style: {
              fill: color,
              stroke: '#fff',
              lineWidth: 1,
              shadowBlur: 3,
              shadowColor: 'rgba(0,0,0,0.3)'
            }
          };
        },
        data: seriesData // Pass the transformed array data
      }
    ]
  };
};

