              <th className="px-4 py-3 font-medium w-10 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-900">
                <div className="flex items-center justify-center">
                  <button onClick={toggleAll} className="text-slate-400 hover:text-emerald-500 transition-colors">
                    {selectedIds.size > 0 && selectedIds.size === paginatedData.length ? <CheckSquare size={16} /> : selectedIds.size > 0 ? <MinusSquare size={16} /> : <Square size={16} />}
