import { ColumnConfig, ViewMode, User as UserType } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';

interface TopBarProps {
  user: UserType | null;
  onLogout: () => void;
  onOpenProfile: () => void;
  onOpenAdmin: () => void;
  searchQuery: string;
  onSearchChange: (query: string) => void;
  isSearching?: boolean;
  columns: ColumnConfig[];
  onToggleColumn: (key: string) => void;
  onToggleAllColumns: (visible: boolean) => void;
  onOpenImport: () => void;
  onExport: () => void;
  isExporting: boolean;
  viewMode: ViewMode;
  onViewModeChange: (mode: ViewMode) => void;
}

export const TopBar: React.FC<TopBarProps> = ({
  user, onLogout, onOpenProfile, onOpenAdmin, searchQuery, onSearchChange, isSearching, columns, onToggleColumn, onOpenImport, onExport, isExporting, viewMode, onViewModeChange
}) => {
  const [isColumnMenuOpen, setIsColumnMenuOpen] = useState(false);
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);
  const { t, language, toggleLanguage, tProp } = useLanguage();
  const { theme, toggleTheme } = useTheme();
  const inputRef = useRef<HTMLInputElement>(null);

  // Refs for click outside detection
  const colMenuRef = useRef<HTMLDivElement>(null);
  const userMenuRef = useRef<HTMLDivElement>(null);

  // Keyboard shortcut for search & Click Outside Logic
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
            e.preventDefault();
            inputRef.current?.focus();
        }
    };

    const handleClickOutside = (e: MouseEvent) => {
        if (colMenuRef.current && !colMenuRef.current.contains(e.target as Node)) {
            setIsColumnMenuOpen(false);
        }
        if (userMenuRef.current && !userMenuRef.current.contains(e.target as Node)) {
            setIsUserMenuOpen(false);
        }
    };

    window.addEventListener('keydown', handleKeyDown);
    document.addEventListener('mousedown', handleClickOutside);

    return () => {
        window.removeEventListener('keydown', handleKeyDown);
        document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
        document.documentElement.requestFullscreen().catch((e) => {
            console.error(`Error attempting to enable fullscreen: ${e.message}`);
        });
    } else {
        if (document.exitFullscreen) {
            document.exitFullscreen();
        }
    }
  };

  return (
    <div className="w-full flex items-center justify-between gap-6 px-2 py-2 pointer-events-none">
      {/* Search Pill - Enable pointer events for children */}
      <div className="flex-1 max-w-2xl relative z-[60] pointer-events-auto">
        <div className="relative group transition-all duration-300 focus-within:scale-[1.01]">
            <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                {isSearching ? (
                    <Loader2 className="text-emerald-500 animate-spin" size={20} />
                ) : (
                    <Search className="text-slate-400 group-focus-within:text-emerald-500 transition-colors" size={20} />
                )}
            </div>
            <input
                ref={inputRef}
                type="text"
                value={searchQuery}
                onChange={(e) => onSearchChange(e.target.value)}
                placeholder={t('searchPlaceholder')}
                className="block w-full pl-12 pr-12 py-3.5 bg-white/90 dark:bg-slate-900/90 backdrop-blur-2xl border border-white/20 dark:border-slate-800 rounded-[1.5rem] text-sm font-medium shadow-xl shadow-slate-200/40 dark:shadow-black/40 outline-none focus:ring-4 focus:ring-emerald-500/10 transition-all text-slate-700 dark:text-slate-200 placeholder:text-slate-400"
            />
            <div className="absolute inset-y-0 right-4 flex items-center">
                {searchQuery ? (
                    <button 
                        onClick={() => { onSearchChange(''); inputRef.current?.focus(); }}
                        className="p-1 rounded-full text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700 hover:text-slate-600 dark:hover:text-slate-200 transition-colors animate-in fade-in zoom-in duration-200"
                    >
                        <X size={14} />
                    </button>
                ) : (
                    <span className="flex items-center gap-1 px-2 py-1 bg-slate-100 dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 text-[10px] font-bold text-slate-400 shadow-sm pointer-events-none">
                        <Command size={10} /> K
                    </span>
                )}
            </div>
        </div>
      </div>

      {/* Right Actions Island - Enable pointer events */}
      <div className="flex items-center gap-3 p-1.5 bg-white/90 dark:bg-slate-900/90 backdrop-blur-2xl border border-white/20 dark:border-slate-800 rounded-[1.5rem] shadow-xl shadow-slate-200/40 dark:shadow-black/40 pointer-events-auto z-[60]">

        {/* View Toggle */}
        <div className="flex items-center bg-slate-100 dark:bg-slate-800 rounded-[1.2rem] p-1 border border-slate-200 dark:border-slate-700">
            <button onClick={() => onViewModeChange('grid')} className={`p-2.5 rounded-[1rem] transition-all active:scale-95 ${viewMode === 'grid' ? 'bg-white dark:bg-slate-700 text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>
                <LayoutGrid size={18} />
            </button>
            <button onClick={() => onViewModeChange('chart')} className={`p-2.5 rounded-[1rem] transition-all active:scale-95 ${viewMode === 'chart' ? 'bg-white dark:bg-slate-700 text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>
                <BarChart2 size={18} />
