        </div>

        <div className="h-6 w-px bg-slate-200 dark:bg-slate-700 mx-1"></div>

        <button onClick={onOpenImport} className="p-3 text-slate-500 hover:text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-900/20 rounded-full transition-all active:scale-95" title={t('importData')}>
            <Upload size={20} />
        </button>

        <button 
            onClick={onExport} 
            disabled={isExporting}
