import { User as UserType } from '../types';

interface AdminModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export const AdminModal: React.FC<AdminModalProps> = ({ isOpen, onClose }) => {
  const { t } = useLanguage();
  const [activeTab, setActiveTab] = useState<'users' | 'projects' | 'docs' | 'system'>('users');
  const [users, setUsers] = useState<UserType[]>([]);
  const [stats, setStats] = useState({
    dbSize: '124 MB',
    uptime: '12d 4h 22m',
    apiStatus: 'Healthy',
    totalRecords: 0
  });

  const loadUsers = () => {
    const saved = localStorage.getItem('resindb-users');
    if (saved) setUsers(JSON.parse(saved));
    setStats(prev => ({...prev, totalRecords: users.length * 10 + 42}));
  };

  useEffect(() => {
    if (isOpen) loadUsers();
  }, [isOpen]);

  if (!isOpen) return null;

  const handleDeleteUser = (id: string) => {
    if (id === 'user-001') return;
    const updated = users.filter(u => u.id !== id);
    setUsers(updated);
    localStorage.setItem('resindb-users', JSON.stringify(updated));
  };

  const handleUpdateRole = (id: string, role: UserType['role']) => {
    const updated = users.map(u => u.id === id ? { ...u, role } : u);
    setUsers(updated);
    localStorage.setItem('resindb-users', JSON.stringify(updated));
  };

