    { id: 1, title: 'ResinDB 操作说明手册 v2.0', type: 'PDF', date: '2024-01-10' },
    { id: 2, title: '关于规范实验数据入库的通知', type: 'DOC', date: '2023-12-20' },
    { id: 3, title: '系统安全等级保护声明', type: 'PDF', date: '2023-11-15' },
  ];

