            <button onClick={() => onViewModeChange('chart')} className={`p-2.5 rounded-[1rem] transition-all active:scale-95 ${viewMode === 'chart' ? 'bg-white dark:bg-slate-700 text-red-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>
