  const [rememberMe, setRememberMe] = useState(true);
  const [accounts, setAccounts] = useState<PersistentUser[]>([]);

  const loadAccounts = () => {
    const savedAccounts = localStorage.getItem('resindb-users');
    if (savedAccounts) {
      setAccounts(JSON.parse(savedAccounts));
    } else {
      const defaultUsers: PersistentUser[] = [
        {
          id: 'user-001',
          name: 'System Administrator',
          email: 'admin@petrochina.com.cn',
          role: 'admin',
          password: '123456',
          avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Felix'
        },
        {
          id: 'user-002',
          name: 'Technical Director',
          email: 'director@petrochina.com.cn',
          role: 'admin',
          password: '123456',
          avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Aiden'
        }
      ];
      setAccounts(defaultUsers);
      localStorage.setItem('resindb-users', JSON.stringify(defaultUsers));
    }
  };

  useEffect(() => {
    loadAccounts();
    window.addEventListener('storage', loadAccounts);
    return () => window.removeEventListener('storage', loadAccounts);
  }, []);

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    setTimeout(() => {
      if (mode === 'login') {
        const found = accounts.find(acc => 
          (acc.name.toLowerCase() === username.toLowerCase() || acc.email.toLowerCase() === username.toLowerCase()) && 
          acc.password === password
        );

        if (found) {
          onLogin(found);
        } else {
          alert('Invalid credentials. Please check your username and password.');
        }
      } else {
        if (password !== confirmPassword) {
          alert('Passwords do not match');
          setIsLoading(false);
          return;
        }

        const newUser: PersistentUser = {
          id: `user-${Date.now()}`,
          name: username,
          email: email || `${username}@petrochina.com.cn`,
          role: 'editor',
          password: password,
          avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${username}`
        };

        const updated = [...accounts, newUser];
        setAccounts(updated);
        localStorage.setItem('resindb-users', JSON.stringify(updated));
        onLogin(newUser);
      }
      setIsLoading(false);
    }, 1200);
  };

  const removeAccount = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (id === 'user-001') {
        alert("Primary admin account cannot be removed.");
        return;
    }
    const updated = accounts.filter(acc => acc.id !== id);
    setAccounts(updated);
    localStorage.setItem('resindb-users', JSON.stringify(updated));
  };

  const selectAccount = (acc: PersistentUser) => {
    setUsername(acc.email || acc.name);
    setPassword(acc.password || '');
    setMode('login');
  };

  return (
