      <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-600/10 rounded-full blur-[120px] animate-pulse [animation-delay:2s]"></div>

      <div className="z-10 w-full max-w-4xl flex flex-col md:flex-row gap-6 animate-in fade-in zoom-in-95 duration-500 h-[600px] md:h-auto">
        <div className={`hidden md:flex flex-col w-full md:w-72 bg-white/50 dark:bg-slate-900/50 backdrop-blur-xl border border-slate-200 dark:border-slate-800 rounded-3xl p-6 transition-all duration-300 ${mode === 'register' ? 'opacity-30 pointer-events-none grayscale' : ''}`}>
            <h2 className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-4 flex items-center gap-2 shrink-0">
                <User size={14} className="text-red-600" />
                {t('availableAccounts')}
            </h2>
            <div className="flex-1 space-y-2 overflow-y-auto custom-scrollbar pr-2 -mr-2">
                {accounts.map(acc => (
                    <div key={acc.id} className="group relative">
                        <button 
                            onClick={() => selectAccount(acc)}
                            className={`w-full flex items-center gap-3 p-2 rounded-2xl hover:bg-white dark:hover:bg-slate-800 transition-all border border-transparent hover:border-slate-100 dark:hover:border-slate-700 text-left ${username === (acc.email || acc.name) ? 'bg-red-50/50 dark:bg-red-900/10 border-red-100/50 dark:border-red-900/30' : ''}`}
                        >
                            <div className="w-9 h-9 rounded-xl overflow-hidden shadow-sm border border-slate-200 dark:border-slate-700 shrink-0">
                                <img src={acc.avatar} alt={acc.name} className="w-full h-full object-cover" />
