// Chart 2: "Ashby" Scatter Plot Option Configuration
export const getAshbyChartOption = (seriesData: { name: string; data: any[] }[], theme: 'light' | 'dark'): echarts.EChartsOption => {
  const isDark = theme === 'dark';
  // Petro Palette: Red, Blue, Yellow...
  const colorPalette = ['#D62828', '#003366', '#FFC800', '#2dd4bf', '#8b5cf6'];
  const gridColor = isDark ? '#334155' : '#e0e0e0';
  const axisColor = isDark ? '#94a3b8' : '#333333';

  return {
    backgroundColor: 'transparent',
    color: colorPalette,
    title: {
      text: '构效关系映射 (Ashby Plot)',
      subtext: 'MFR (Flow) vs Impact (Toughness) Trade-off',
      left: 'center',
      textStyle: { color: isDark ? '#e2e8f0' : '#333333', fontSize: 16, fontFamily: 'Arial, sans-serif' }
    },
    grid: {
      left: '10%',
      right: '12%',
      bottom: '12%',
      top: '18%',
      containLabel: true,
      show: true,
      borderWidth: 0,
      backgroundColor: isDark ? 'rgba(255,255,255,0.02)' : 'rgba(0,0,0,0.01)'
    },
    tooltip: {
      trigger: 'item',
      confine: true,
      backgroundColor: isDark ? 'rgba(15, 23, 42, 0.9)' : 'rgba(255, 255, 255, 0.95)',
      formatter: (params: any) => {
        if (params.componentType === 'markLine') return params.name;
        const val = params.value;
        return `
          <div style="font-weight:bold; margin-bottom:4px;">${val[2]}</div>
          <span style="display:inline-block;width:10px;height:10px;border-radius:50%;background-color:${params.color};margin-right:5px;"></span>
          ${params.seriesName}<br/>
          MFR: <b>${val[0]}</b> g/10min<br/>
