import React, { useState, useMemo, useEffect } from 'react';
import { Category } from '../types';
import { ChevronRight, LayoutGrid, Search, X, Layers } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

interface TreeSidebarProps {
  categories: Category[];
  selectedCategoryId: string | null;
  onSelectCategory: (id: string | null) => void;
  totalCount?: number;
  counts?: Record<string, number>;
}

const TreeNode: React.FC<{
  category: Category;
  selectedId: string | null;
  onSelect: (id: string) => void;
  depth: number;
  forceExpand?: boolean;
  count?: number;
}> = ({ category, selectedId, onSelect, depth, forceExpand = false, count = 0 }) => {
  const [isExpanded, setIsExpanded] = useState(depth < 1); 
  const hasChildren = category.children && category.children.length > 0;
  const isSelected = selectedId === category.id;
  const { language } = useLanguage();

  useEffect(() => { if (forceExpand) setIsExpanded(true); }, [forceExpand]);

  const displayOpen = isExpanded || forceExpand;

  return (
    <div className="select-none my-1">
      <div
        onClick={(e) => {
            e.stopPropagation();
            if(hasChildren) setIsExpanded(!isExpanded);
            onSelect(category.id);
        }}
        className={`
          flex items-center px-3 py-2.5 cursor-pointer text-sm transition-all duration-200 mx-2 rounded-xl relative overflow-hidden group active:scale-[0.98]
          ${isSelected 
            ? 'bg-red-600 text-white font-bold shadow-md' 
            : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 hover:text-slate-900 dark:hover:text-slate-200'}
        `}
        style={{ paddingLeft: `${depth * 12 + 12}px` }}
      >
        <div className={`mr-2 transition-transform duration-200 ${displayOpen && hasChildren ? 'rotate-90' : ''}`}>
            {hasChildren ? (
                <ChevronRight size={14} className={isSelected ? 'text-white/70' : 'text-slate-400'} />
            ) : (
                <div className="w-3.5" /> 
            )}
        </div>
        <span className="truncate relative z-10 flex-1 tracking-tight">{language === 'en' && category.nameEn ? category.nameEn : category.name}</span>

        {count > 0 && (
            <span className={`ml-2 px-1.5 py-0.5 rounded-md text-[9px] font-bold ${isSelected ? 'bg-white/20 text-white' : 'bg-slate-100 dark:bg-slate-700 text-slate-400 dark:text-slate-500 group-hover:bg-white dark:group-hover:bg-slate-600'}`}>
                {count}
            </span>
        )}

        {isSelected && <div className="w-1.5 h-1.5 rounded-full bg-white ml-1 animate-pulse shadow-[0_0_8px_rgba(255,255,255,0.8)]"></div>}
      </div>

      <div 
        className={`overflow-hidden transition-all duration-300 ease-in-out ${displayOpen ? 'max-h-[800px] opacity-100' : 'max-h-0 opacity-0'}`}
      >
        <div className="relative ml-4 pl-2 border-l border-slate-200/50 dark:border-slate-700/50 my-0.5">
          {hasChildren && category.children!.map((child) => (
            <TreeNode
              key={child.id}
              category={child}
              selectedId={selectedId}
              onSelect={onSelect}
              depth={depth + 1}
              forceExpand={forceExpand}
              count={0} 
            />
          ))}
        </div>
      </div>
    </div>
  );
};

const RecursiveTree: React.FC<{
    categories: Category[];
    selectedId: string | null;
    onSelect: (id: string) => void;
    depth: number;
    forceExpand: boolean;
    counts: Record<string, number>;
}> = ({ categories, selectedId, onSelect, depth, forceExpand, counts }) => {
    return (
        <>
            {categories.map(cat => (
                <TreeNodeWithChildren 
                    key={cat.id} 
                    category={cat} 
                    selectedId={selectedId} 
                    onSelect={onSelect} 
                    depth={depth} 
                    forceExpand={forceExpand}
                    counts={counts}
                />
            ))}
        </>
    )
}

const TreeNodeWithChildren: React.FC<{
  category: Category;
  selectedId: string | null;
  onSelect: (id: string) => void;
  depth: number;
  forceExpand?: boolean;
  counts: Record<string, number>;
}> = ({ category, selectedId, onSelect, depth, forceExpand = false, counts }) => {
  const [isExpanded, setIsExpanded] = useState(depth < 1); 
  const hasChildren = category.children && category.children.length > 0;
  const isSelected = selectedId === category.id;
  const { language } = useLanguage();

  useEffect(() => { if (forceExpand) setIsExpanded(true); }, [forceExpand]);

  const displayOpen = isExpanded || forceExpand;
  const count = counts[category.id] || 0;

  return (
    <div className="select-none my-1">
      <div
        onClick={(e) => {
            e.stopPropagation();
            if(hasChildren) setIsExpanded(!isExpanded);
            onSelect(category.id);
        }}
        className={`
          flex items-center px-3 py-2.5 cursor-pointer text-sm transition-all duration-200 mx-2 rounded-xl relative overflow-hidden group active:scale-[0.98]
          ${isSelected 
            ? 'bg-red-600 text-white font-bold shadow-md' 
            : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 hover:text-slate-900 dark:hover:text-slate-200'}
        `}
        style={{ paddingLeft: `${depth * 12 + 12}px` }}
      >
        <div className={`mr-2 transition-transform duration-200 ${displayOpen && hasChildren ? 'rotate-90' : ''}`}>
            {hasChildren ? (
                <ChevronRight size={14} className={isSelected ? 'text-white/70' : 'text-slate-400'} />
            ) : (
                <div className="w-3.5" /> 
            )}
        </div>
        <span className="truncate relative z-10 flex-1 tracking-tight">{language === 'en' && category.nameEn ? category.nameEn : category.name}</span>

        {count > 0 && (
            <span className={`ml-2 px-1.5 py-0.5 rounded-md text-[9px] font-bold ${isSelected ? 'bg-white/20 text-white' : 'bg-slate-100 dark:bg-slate-700 text-slate-400 dark:text-slate-500 group-hover:bg-white dark:group-hover:bg-slate-600'}`}>
                {count}
            </span>
        )}

        {isSelected && <div className="w-1.5 h-1.5 rounded-full bg-white ml-1 animate-pulse shadow-[0_0_8px_rgba(255,255,255,0.8)]"></div>}
      </div>

      <div 
        className={`overflow-hidden transition-all duration-300 ease-in-out ${displayOpen ? 'max-h-[800px] opacity-100' : 'max-h-0 opacity-0'}`}
      >
        <div className="relative ml-4 pl-2 border-l border-slate-200/50 dark:border-slate-700/50 my-0.5">
          {hasChildren && (
              <RecursiveTree 
                categories={category.children!} 
                selectedId={selectedId} 
                onSelect={onSelect} 
                depth={depth + 1} 
                forceExpand={!!forceExpand} 
                counts={counts} 
              />
          )}
        </div>
      </div>
    </div>
  );
};

export const TreeSidebar: React.FC<TreeSidebarProps> = ({ categories, selectedCategoryId, onSelectCategory, totalCount = 0, counts = {} }) => {
  const { t, language } = useLanguage();
  const [searchTerm, setSearchTerm] = useState('');

  const filterCategories = (cats: Category[], term: string): Category[] => {
    return cats.reduce<Category[]>((acc, cat) => {
        const name = language === 'en' && cat.nameEn ? cat.nameEn : cat.name;
        const matches = name.toLowerCase().includes(term.toLowerCase());
        let filteredChildren: Category[] = [];
        if (cat.children) filteredChildren = filterCategories(cat.children, term);
        if (matches || filteredChildren.length > 0) acc.push({ ...cat, children: filteredChildren });
        return acc;
    }, []);
  };

  const displayedCategories = useMemo(() => searchTerm.trim() ? filterCategories(categories, searchTerm) : categories, [categories, searchTerm, language]);

  return (
    <div className="flex flex-col h-full bg-transparent">
      <div className="p-4 pb-2 shrink-0 space-y-3">
        {/* Search */}
        <div className="relative group">
             <Search className="absolute left-3.5 top-2.5 text-slate-400 group-focus-within:text-red-500 transition-colors" size={16} />
             <input 
                type="text" 
                placeholder={t('searchCategories')} 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-8 py-2.5 bg-slate-50/80 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700 rounded-xl text-sm font-medium focus:ring-2 focus:ring-red-500/20 focus:border-red-500 outline-none transition-all placeholder:text-slate-400"
             />
             {searchTerm && <button onClick={() => setSearchTerm('')} className="absolute right-3 top-2.5 text-slate-400 hover:text-slate-600"><X size={14} /></button>}
        </div>

        {/* All Products Root Node */}
        <div 
            className={`
              flex items-center justify-between px-4 py-3 rounded-xl cursor-pointer transition-all duration-200 border group active:scale-[0.98] mx-1
              ${!selectedCategoryId 
                ? 'bg-gradient-to-r from-red-600 to-red-500 text-white shadow-lg shadow-red-500/20 border-transparent' 
                : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 hover:border-red-500/30 hover:bg-red-50/50 dark:hover:bg-slate-700'
              }
            `}
            onClick={() => onSelectCategory(null)}
        >
            <div className="flex items-center gap-3">
                <div className={`p-1.5 rounded-lg ${!selectedCategoryId ? 'bg-white/20' : 'bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400'}`}>
                    <Layers size={16} />
                </div>
                <span className="font-bold text-sm tracking-wide">{t('allProducts')}</span>
            </div>
            <span className={`px-2 py-0.5 rounded-md text-[10px] font-black ${!selectedCategoryId ? 'bg-white/20 text-white' : 'bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400'}`}>{totalCount}</span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-2 custom-scrollbar pb-6 pt-1">
        {displayedCategories.length > 0 ? (
            <RecursiveTree 
                categories={displayedCategories} 
                selectedId={selectedCategoryId} 
                onSelect={onSelectCategory} 
                depth={0} 
                forceExpand={!!searchTerm}
                counts={counts}
            />
        ) : (
            <div className="text-center py-12 text-xs text-slate-400 italic flex flex-col items-center gap-2">
                <Search size={24} className="opacity-20" />
                No matching categories
            </div>
        )}
      </div>
    </div>
  );
};

