      ];
      setAccounts(defaultUsers);
      localStorage.setItem('resindb-users', JSON.stringify(defaultUsers));
    }
  };

  useEffect(() => {
    loadAccounts();
    window.addEventListener('storage', loadAccounts);
    return () => window.removeEventListener('storage', loadAccounts);
