                                    <span className={`text-[8px] font-black uppercase px-1 rounded shrink-0 ${
                                        acc.role === 'admin' ? 'bg-red-100 text-red-600' : 
                                        acc.role === 'editor' ? 'bg-blue-100 text-blue-600' : 'bg-slate-200 text-slate-600'
                                    }`}>
                                        {acc.role}
                                    </span>
                                </div>
                                <p className="text-[9px] text-slate-500 truncate mt-0.5">{acc.email}</p>
                            </div>
                            <ChevronRight size={14} className={`text-slate-300 shrink-0 transition-all ${username === (acc.email || acc.name) ? 'opacity-100 text-red-600' : 'opacity-0 group-hover:opacity-100'}`} />
