      })),
      {
        name: 'Technological Limit',
        type: 'line' as const,
        markLine: {
          symbol: ['none', 'none'],
          label: { show: true, position: 'middle', formatter: 'Pareto Frontier (Bound)', color: '#ff7f50' },
          lineStyle: {
            type: 'dashed',
            color: '#ff7f50',
