          },
          data: [
            [
              { coord: [0.1, 90] }, 
              { coord: [100, 5] }   
            ]
          ]
        }
      }
    ]
  };
};

import * as echarts from 'echarts';

// Chart 3: Molecular Weight Distribution (GPC) Option Configuration
export const getGpcChartOption = (products: any[], theme: 'light' | 'dark'): echarts.EChartsOption => {
  const isDark = theme === 'dark';
  const colorPalette = ['#D62828', '#003366', '#FFC800', '#2dd4bf', '#8b5cf6'];
  const axisColor = isDark ? '#94a3b8' : '#333333';
  const gridColor = isDark ? '#334155' : '#e0e0e0';

  // Generate curves based on product data (simulation)
  const series = products.map((p, idx) => {
      const data = [];
      const mfr = parseFloat(p.properties['熔体质量流动速率']?.value || 1);
      const safeMfr = isNaN(mfr) ? 1 : mfr;
      // High MFR = Low MW (Shift Left)
      const peakLogMw = 5.5 - (Math.log10(safeMfr) * 0.4); 

      const isBimodal = p.gradeName.includes('High') || p.gradeName.includes('Pipe') || (Math.random() > 0.7);

      for (let i = 3; i <= 7; i += 0.05) {
        let val = 0;
        const xVal = Math.pow(10, i);
        if (isBimodal) {
            // Main Peak + Shoulder
            val = 0.7 * Math.exp(-Math.pow(i - peakLogMw, 2) / (2 * 0.25)) + 
                  0.4 * Math.exp(-Math.pow(i - (peakLogMw + 0.8), 2) / (2 * 0.2));
        } else {
            // Single Peak
            val = 1.0 * Math.exp(-Math.pow(i - peakLogMw, 2) / (2 * 0.2));
        }
        data.push([xVal, val]);
      }

      return {
        name: p.gradeName,
        type: 'line',
        smooth: 0.4,
        showSymbol: false,
        data: data,
        lineStyle: { width: 3 },
        areaStyle: {
          color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
            { offset: 0, color: colorPalette[idx % colorPalette.length] + '40' }, // 25% opacity
            { offset: 1, color: colorPalette[idx % colorPalette.length] + '00' }
          ])
        },
        markArea: idx === 0 ? {
            itemStyle: { color: 'rgba(200, 200, 200, 0.1)' },
            data: [
                [{ name: 'Processability Zone (Low Mw)', xAxis: 1000 }, { xAxis: 30000 }],
                [{ name: 'Strength Zone (High Mw)', xAxis: 300000 }, { xAxis: 10000000 }]
            ],
            label: { position: 'top', color: axisColor, fontSize: 10 }
        } : undefined
      };
  });

  return {
    backgroundColor: 'transparent',
    color: colorPalette,
    title: {
      text: '分子量分布 (GPC Distribution)',
      subtext: 'Polymerization Uniformity Analysis',
      left: 'center',
      textStyle: { color: isDark ? '#e2e8f0' : '#333333', fontSize: 16 }
    },
    tooltip: {
      trigger: 'axis',
      confine: true,
      backgroundColor: isDark ? 'rgba(15, 23, 42, 0.9)' : 'rgba(255, 255, 255, 0.95)',
      formatter: (params: any) => {
        let html = `<div style="margin-bottom:4px;font-weight:bold">Mw: ${params[0].value[0].toExponential(2)}</div>`;
        params.forEach((p: any) => {
          html += `<div style="color:${p.color}">${p.seriesName}: ${p.value[1].toFixed(3)}</div>`;
        });
        return html;
      }
    },
    legend: {
      top: 50,
      textStyle: { color: axisColor }
    },
    grid: {
      containLabel: true,
      left: '8%',
      right: '8%',
      bottom: '10%'
    },
    xAxis: {
      type: 'log',
      name: 'Molecular Weight (Mw) [g/mol]',
      nameLocation: 'middle',
      nameGap: 30,
      min: 1000,
      max: 10000000,
      logBase: 10,
      axisLabel: { 
          color: axisColor,
          formatter: (value: number) => value.toExponential(0)
      },
      splitLine: { show: true, lineStyle: { color: gridColor, type: 'dashed' } },
      axisLine: { lineStyle: { color: '#888' } }
    },
    yAxis: {
      type: 'value',
      name: 'Normalized Intensity (dw/dlogM)',
      nameLocation: 'middle',
      nameGap: 40,
      splitLine: { show: true, lineStyle: { color: gridColor, type: 'dashed' } },
      axisLabel: { color: axisColor },
      axisLine: { show: true, lineStyle: { color: '#888' } }
    },
    series: series as any[]
  };
};

import * as echarts from 'echarts';

// Chart 4: Rheology Viscosity Curve Option Configuration
export const getRheologyChartOption = (products: any[], theme: 'light' | 'dark'): echarts.EChartsOption => {
  const isDark = theme === 'dark';
  const colorPalette = ['#D62828', '#003366', '#FFC800', '#2dd4bf', '#8b5cf6'];
  const gridColor = isDark ? '#334155' : '#e0e0e0';
  const axisColor = isDark ? '#94a3b8' : '#333333';

  // Cross Model Simulation based on MFR
  const generateData = (mfr: number, tempOffset: number) => {
    const data = [];
    // Base Zero Shear Viscosity modified by Temp
    const eta0 = (30000 * Math.pow(mfr, -0.8)) * Math.exp(tempOffset * -0.02);
    const n = 0.45; // Shear thinning index

    for (let i = 0; i <= 4; i += 0.2) { // 10^0 to 10^4
      const rate = Math.pow(10, i);
      const viscosity = eta0 / (1 + Math.pow(rate * 0.05, 1 - n));
      data.push([rate, viscosity]);
    }
    return data;
  };

  const series = products.flatMap((p: any, idx: number) => {
      const mfr = parseFloat(p.properties['熔体质量流动速率']?.value || 5);
      const safeMfr = isNaN(mfr) ? 5 : mfr;
      const baseColor = colorPalette[idx % colorPalette.length];

      // Generate 3 curves per product for Temps (190, 210, 230)
      return [
          {
            name: `${p.gradeName} @ 190°C`,
            type: 'line',
            smooth: true,
            showSymbol: false,
            data: generateData(safeMfr, 0),
            lineStyle: { width: 3, type: 'solid', color: baseColor }
          },
          // Only show extra temps if single product selected to avoid clutter
          ...(products.length === 1 ? [
            {
                name: `${p.gradeName} @ 210°C`,
                type: 'line',
                smooth: true,
                showSymbol: false,
                data: generateData(safeMfr, 20),
                lineStyle: { width: 2, type: 'dashed', color: baseColor, opacity: 0.7 }
            },
            {
                name: `${p.gradeName} @ 230°C`,
                type: 'line',
                smooth: true,
                showSymbol: false,
                data: generateData(safeMfr, 40),
                lineStyle: { width: 2, type: 'dotted', color: baseColor, opacity: 0.5 }
            }
          ] : [])
      ];
  });

  return {
    backgroundColor: 'transparent',
    color: colorPalette,
    title: {
      text: '流变行为曲线 (Rheology Curve)',
      subtext: 'Double Log Plot: Shear Rate vs Viscosity',
      left: 'center',
      textStyle: { color: isDark ? '#e2e8f0' : '#333333', fontSize: 16 }
    },
    tooltip: {
      trigger: 'axis',
      confine: true,
      formatter: (params: any) => {
        let html = `<div>Shear Rate: <b>${params[0].value[0].toExponential(2)}</b> s⁻¹</div>`;
        params.forEach((item: any) => {
          html += `<div style="color:${item.color}">${item.seriesName}: <b>${item.value[1].toExponential(2)}</b> Pa·s</div>`;
        });
        return html;
      }
    },
    legend: {
      bottom: 5,
      type: 'scroll',
      textStyle: { color: axisColor }
    },
    grid: {
      containLabel: true,
      left: '8%',
      right: '15%',
      bottom: '12%'
    },
    dataZoom: [
        { type: 'inside', xAxisIndex: 0 },
        { type: 'inside', yAxisIndex: 0 }
    ],
    xAxis: {
      type: 'log',
      name: 'Shear Rate (γ̇) [s⁻¹]',
      nameLocation: 'middle',
      nameGap: 30,
      min: 1,
      max: 10000,
      logBase: 10,
      splitLine: { show: true, lineStyle: { color: gridColor, type: 'dashed' } },
      axisLabel: { color: axisColor, formatter: (v: number) => `10^${Math.log10(v)}` },
      axisLine: { lineStyle: { color: '#888' } }
    },
    yAxis: {
      type: 'log',
      name: 'Viscosity (η) [Pa·s]',
      nameLocation: 'middle',
      nameGap: 50,
      logBase: 10,
      splitLine: { show: true, lineStyle: { color: gridColor, type: 'dashed' } },
      axisLabel: { color: axisColor, formatter: (v: number) => `10^${Math.log10(v)}` },
      axisLine: { lineStyle: { color: '#888' } }
    },
    series: series as any[]
  };
};

import React, { useMemo, useEffect, useRef } from 'react';
import { X, Radar, Factory, Layers, Info } from 'lucide-react';
import { Product } from '../types';
import { PROPERTY_GROUPS } from '../constants';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import * as echarts from 'echarts';

interface ComparisonViewProps {
  products: Product[];
  onClose: () => void;
  onRemoveProduct: (id: string) => void;
}

export const ComparisonView: React.FC<ComparisonViewProps> = ({ products, onClose, onRemoveProduct }) => {
  const { tProp } = useLanguage();
  const { theme } = useTheme();
  const chartRef = useRef<HTMLDivElement>(null);
  const chartInstance = useRef<echarts.ECharts | null>(null);

  // Petro Palette
  const colors = ['#D62828', '#003366', '#FFC800', '#2dd4bf', '#8b5cf6'];

  // Radar Chart Data Prep (ECharts format)
  const radarKeys = ['密度', '熔体质量流动速率', '拉伸屈服应力', '弯曲模量', '悬臂梁缺口冲击强度'];

  useEffect(() => {
    if (!chartRef.current || products.length === 0) return;

    // Initialize Chart
    if (!chartInstance.current) {
        chartInstance.current = echarts.init(chartRef.current);
    }

    const indicator = radarKeys.map(key => {
        let maxVal = -Infinity;
        products.forEach(p => {
            const val = Number(p.properties[key]?.value);
            if (!isNaN(val) && val > maxVal) maxVal = val;
        });
        // Add 10% buffer
        return { name: tProp(key), max: maxVal * 1.1 || 100 };
    });

    const seriesData = products.map((p, idx) => ({
        value: radarKeys.map(key => {
            const val = Number(p.properties[key]?.value);
            return isNaN(val) ? 0 : val;
        }),
        name: p.gradeName,
        areaStyle: {
            opacity: 0.3
        },
        lineStyle: {
            width: 2
        },
        itemStyle: {
            color: colors[idx % colors.length]
        }
    }));

    const option = {
        backgroundColor: 'transparent',
        tooltip: {
            trigger: 'item'
        },
        legend: {
            bottom: 0,
            data: products.map(p => p.gradeName),
            textStyle: {
                color: theme === 'dark' ? '#94a3b8' : '#475569'
            }
        },
        radar: {
            indicator: indicator,
            shape: 'circle',
            splitNumber: 4,
            axisName: {
                color: theme === 'dark' ? '#cbd5e1' : '#1e293b',
                fontWeight: 'bold',
                fontSize: 10
            },
            splitLine: {
                lineStyle: {
                    color: theme === 'dark' ? [
                        'rgba(255, 255, 255, 0.1)', 'rgba(255, 255, 255, 0.2)',
                        'rgba(255, 255, 255, 0.4)', 'rgba(255, 255, 255, 0.6)'
                    ] : [
                        'rgba(0, 0, 0, 0.1)', 'rgba(0, 0, 0, 0.2)',
                        'rgba(0, 0, 0, 0.3)', 'rgba(0, 0, 0, 0.4)'
                    ].reverse()
                }
            },
            splitArea: {
                show: false
            },
            axisLine: {
                lineStyle: {
                    color: theme === 'dark' ? 'rgba(255, 255, 255, 0.3)' : 'rgba(0, 0, 0, 0.3)'
                }
            }
        },
        series: [
            {
                type: 'radar',
                data: seriesData,
                symbol: 'circle',
                symbolSize: 6
            }
        ]
    };

    chartInstance.current.setOption(option);

    const handleResize = () => chartInstance.current?.resize();
    window.addEventListener('resize', handleResize);

    return () => {
        window.removeEventListener('resize', handleResize);
        chartInstance.current?.dispose();
        chartInstance.current = null;
    };
  }, [products, theme, tProp]);

  // Aggregate all unique properties from selected products
  const allProperties = useMemo(() => {
      const props = new Set<string>();
      products.forEach(p => Object.keys(p.properties).forEach(k => props.add(k)));
      return Array.from(props);
  }, [products]);

  // Group properties based on constants
  const groupedProps = useMemo(() => {
     const grouped: Record<string, string[]> = {};
     Object.keys(PROPERTY_GROUPS).forEach(g => grouped[g] = []);
     grouped['Other'] = [];

     allProperties.forEach(prop => {
        let found = false;
        for (const [group, keys] of Object.entries(PROPERTY_GROUPS)) {
            if (keys.some(k => prop.includes(k) || k === prop)) {
                grouped[group].push(prop);
                found = true;
                break;
            }
        }
        if(!found) grouped['Other'].push(prop);
     });

     return Object.entries(grouped).filter(([_, props]) => props.length > 0);
  }, [allProperties]);

  const isBestValue = (key: string, val: string | number) => {
      const numVal = Number(val);
      if(isNaN(numVal)) return false;
      const values = products.map(p => Number(p.properties[key]?.value)).filter(n => !isNaN(n));
      const max = Math.max(...values);
      return numVal === max;
  };

  return (
    <div className="fixed inset-0 z-[120] bg-slate-50 dark:bg-slate-950 flex flex-col animate-in slide-in-from-bottom-10 duration-300">
      {/* Header */}
      <div className="px-6 py-4 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 shadow-sm flex justify-between items-center shrink-0">
         <div className="flex items-center gap-4">
            <div className="p-2.5 bg-blue-900 text-white rounded-xl shadow-lg shadow-blue-900/20">
                <Layers size={24} />
            </div>
            <div>
                <h2 className="text-xl font-black text-slate-800 dark:text-white tracking-tight">Material Fingerprint</h2>
                <p className="text-xs font-medium text-slate-500 flex gap-2">
                    Benchmarking <span className="text-red-600 font-bold">{products.length}</span> grades against standard properties
                </p>
            </div>
         </div>
         <button onClick={onClose} className="p-2 bg-slate-100 dark:bg-slate-800 hover:bg-red-100 hover:text-red-600 dark:hover:bg-red-900/20 rounded-xl transition-all">
            <X size={24} />
         </button>
      </div>

      <div className="flex-1 overflow-hidden flex flex-col md:flex-row">
          {/* Radar Chart Section */}
          <div className="h-[400px] md:h-full md:w-2/5 bg-white/50 dark:bg-slate-900/50 border-b md:border-b-0 md:border-r border-slate-200 dark:border-slate-800 p-6 flex flex-col relative">
             <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                <Radar size={16} /> Property Overlap
             </h3>
             <div className="flex-1 w-full min-h-0 relative rounded-2xl overflow-hidden bg-gradient-to-br from-slate-50 to-white dark:from-slate-900 dark:to-slate-950 border border-slate-100 dark:border-slate-800 shadow-inner">
                <div ref={chartRef} className="w-full h-full" />
             </div>
             <div className="mt-4 p-3 bg-blue-50 dark:bg-blue-900/10 rounded-xl border border-blue-100 dark:border-blue-800/30 text-[10px] text-blue-600 dark:text-blue-400 leading-relaxed flex gap-2">
                <Info size={14} className="shrink-0 mt-0.5" />
                Areas of intersection indicate competitive equivalence. Outer spikes represent superior performance in specific domains.
             </div>
          </div>

          {/* Comparison Table Section */}
          <div className="flex-1 overflow-auto custom-scrollbar bg-slate-50 dark:bg-slate-950 relative">
             <table className="w-full text-sm text-left border-separate border-spacing-0">
                <thead className="text-xs text-slate-500 uppercase bg-white dark:bg-slate-900 sticky top-0 z-20 shadow-sm">
                    <tr>
                        <th className="px-6 py-4 font-black tracking-wider border-b border-r border-slate-200 dark:border-slate-800 min-w-[200px] sticky left-0 bg-white dark:bg-slate-900 z-30">Property</th>
                        {products.map((p, idx) => (
                            <th key={p.id} className="px-6 py-4 border-b border-r border-slate-200 dark:border-slate-800 min-w-[200px] relative group">
                                <div className="flex justify-between items-start">
                                    <div>
                                        <div className="font-black text-slate-800 dark:text-white text-base mb-1" style={{ color: colors[idx % colors.length] }}>{p.gradeName}</div>
                                        <div className="flex items-center gap-1 text-[10px] font-bold text-slate-400 bg-slate-100 dark:bg-slate-800 px-2 py-0.5 rounded-full w-fit">
                                            <Factory size={10} /> {p.manufacturer}
                                        </div>
                                    </div>
                                    <button 
                                        onClick={() => onRemoveProduct(p.id)}
                                        className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"
                                    >
                                        <X size={16} />
                                    </button>
                                </div>
                            </th>
                        ))}
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
                    {groupedProps.map(([group, props]) => (
                        <React.Fragment key={group}>
                            <tr className="bg-slate-100/50 dark:bg-slate-900/50">
                                <td colSpan={products.length + 1} className="px-6 py-2 text-[10px] font-black uppercase tracking-widest text-slate-500 sticky left-0 z-10 bg-slate-100/50 dark:bg-slate-900/50 backdrop-blur-sm border-y border-slate-200 dark:border-slate-800">
                                    {group} Properties
                                </td>
                            </tr>
                            {props.map(propKey => (
                                <tr key={propKey} className="hover:bg-white dark:hover:bg-slate-900 transition-colors">
                                    <td className="px-6 py-3 font-medium text-slate-600 dark:text-slate-300 border-r border-slate-200 dark:border-slate-800 sticky left-0 bg-slate-50 dark:bg-slate-950 group-hover:bg-white dark:group-hover:bg-slate-900 transition-colors z-10 text-xs">
                                        {propKey}
                                    </td>
                                    {products.map(p => {
                                        const prop = p.properties[propKey];
                                        const isMax = prop && typeof prop.value === 'number' && isBestValue(propKey, prop.value);
                                        return (
                                            <td key={`${p.id}-${propKey}`} className={`px-6 py-3 border-r border-slate-200 dark:border-slate-800 ${isMax ? 'bg-red-50/30 dark:bg-red-900/10' : ''}`}>
                                                <div className="flex items-baseline gap-1">
                                                    <span className={`font-mono font-bold ${isMax ? 'text-red-700 dark:text-red-400' : 'text-slate-700 dark:text-slate-300'}`}>
                                                        {prop?.value ?? '-'}
                                                    </span>
                                                    {prop?.unit && <span className="text-[10px] text-slate-400">{prop.unit}</span>}
                                                </div>
                                            </td>
                                        );
                                    })}
                                </tr>
                            ))}
                        </React.Fragment>
                    ))}
                </tbody>
             </table>
          </div>
      </div>
    </div>
  );
};

import * as echarts from 'echarts';

// Chart 5: Ternary Plot Option Configuration
export const getTernaryChartOption = (data: any[], theme: 'light' | 'dark'): echarts.EChartsOption => {
  const isDark = theme === 'dark';
  const axisColor = isDark ? '#94a3b8' : '#333333';
  const sin60 = Math.sqrt(3) / 2;
  const hasData = data && data.length > 0;

  // New Schema: [a, b, c, value, name]
  // Dimensions: 0, 1, 2, 3,     4
  const seriesData = hasData ? data.map(item => [
      typeof item.a === 'number' ? item.a : 0, 
      typeof item.b === 'number' ? item.b : 0, 
      typeof item.c === 'number' ? item.c : 0, 
      typeof item.value === 'number' ? item.value : 0, 
      item.name || 'Sample'
  ]) : [];

  const dummyBackgroundData = [[0, 0, 0, 0, 'Background']];

  const option: echarts.EChartsOption = {
    backgroundColor: 'transparent',
    title: {
      text: '三元相图 (Ternary Phase Plot)',
      subtext: 'Optimization: Component A + B + C = 100%',
      left: 'center',
      textStyle: { color: isDark ? '#e2e8f0' : '#333333', fontSize: 16 }
    },
    tooltip: {
      trigger: 'item',
      formatter: (params: any) => {
        // Skip background tooltip
        if (params.seriesIndex === 0) return '';

        const d = params.data; // Now an array: [a, b, c, value, name]
        if (!Array.isArray(d) || d.length < 5) return '';
        return `
          <div style="font-weight:bold; margin-bottom:4px;">${d[4]}</div>
          Comp A: <b>${(d[0] * 100).toFixed(1)}%</b><br/>
          Comp B: <b>${(d[1] * 100).toFixed(1)}%</b><br/>
          Comp C: <b>${(d[2] * 100).toFixed(1)}%</b><br/>
          Performance: <b>${(d[3] as number).toFixed(1)}</b>
        `;
      }
    },
    series: [
      {
        name: 'Background Frame',
        type: 'custom',
        renderItem: (params, api) => {
          const width = api.getWidth();
          const height = api.getHeight();
          const size = Math.min(width, height) * 0.8;
          const xOffset = (width - size) / 2;
          const yOffset = (height - (size * sin60)) / 2;

          // Vertices in Screen Coords
          const Ax = xOffset;
          const Ay = height - yOffset;
          const Bx = xOffset + size;
          const By = height - yOffset;
          const Cx = xOffset + size / 2;
          const Cy = height - yOffset - size * sin60;

          return {
              type: 'group',
              children: [
                  {
                      type: 'polygon',
                      shape: { points: [[Ax, Ay], [Bx, By], [Cx, Cy]] },
                      style: { fill: isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.02)', stroke: axisColor, lineWidth: 2 }
                  },
                  // Labels
                  { type: 'text', style: { text: 'Comp A', x: Ax - 10, y: Ay + 15, fill: axisColor, fontWeight: 'bold' } },
                  { type: 'text', style: { text: 'Comp B', x: Bx - 10, y: By + 15, fill: axisColor, fontWeight: 'bold' } },
                  { type: 'text', style: { text: 'Comp C', x: Cx - 20, y: Cy - 20, fill: axisColor, fontWeight: 'bold' } },
                  // Grid lines (approx)
                  { type: 'line', shape: { x1: (Ax+Cx)/2, y1: (Ay+Cy)/2, x2: (Bx+Cx)/2, y2: (By+Cy)/2 }, style: { stroke: axisColor, lineDash: [4, 4], opacity: 0.3 } },
                  { type: 'line', shape: { x1: (Ax+Bx)/2, y1: Ay, x2: (Ax+Bx)/2, y2: Ay - (Ay-Cy)/2 }, style: { stroke: axisColor, lineDash: [4, 4], opacity: 0.3 } },
                  { type: 'line', shape: { x1: Ax + size/4, y1: Ay - (size*sin60)/4, x2: Bx - size/4, y2: By - (size*sin60)/4 }, style: { stroke: axisColor, lineDash: [4, 4], opacity: 0.3 } }
              ]
          };
        },
        data: dummyBackgroundData, // Uses padded data
        silent: true // Disable interactions for background
      },
      {
        name: 'Blend Samples',
        type: 'custom',
        renderItem: (params, api) => {
          const width = api.getWidth();
          const height = api.getHeight();
          const size = Math.min(width, height) * 0.8;
          const xOffset = (width - size) / 2;
          const yOffset = (height - (size * sin60)) / 2;

          // SAFE DATA ACCESS: Use api.value(index) to get array items
          const a = api.value(0) as number; 
          const b = api.value(1) as number; 
          const c = api.value(2) as number; 

          // Coordinate Calculation
          const sum = a + b + c;
          // Avoid division by zero
          const safeSum = sum === 0 ? 1 : sum;
          const bn = b / safeSum;
          const cn = c / safeSum;

          const xNorm = bn + cn / 2;
          const yNorm = cn * sin60;

          const x = xOffset + xNorm * size;
          const y = (height - yOffset) - yNorm * size;

          // Safe Visual Access
          const color = api.visual('color');

          return {
            type: 'circle',
            shape: { cx: x, cy: y, r: 8 },
            style: {
              fill: color,
              stroke: '#fff',
              lineWidth: 1,
              shadowBlur: 3,
              shadowColor: 'rgba(0,0,0,0.3)'
            }
          };
        },
        data: seriesData // Pass the transformed array data
      }
    ]
  };

  // Only attach visualMap if we have data
  if (hasData) {
    option.visualMap = {
      min: 20,
      max: 100,
      dimension: 3, // Points to 'value'
      seriesIndex: 1, // Explicitly target Series 1
      calculable: true,
      orient: 'vertical',
      right: 10,
      top: 'center',
      text: ['High', 'Low'],
      textStyle: { color: axisColor },
      inRange: {
        color: ['#003366', '#2dd4bf', '#FFC800', '#D62828'] 
      }
    };
  }

  return option;
};

