import React, { useState, useEffect, useRef } from 'react';
import { Search, SlidersHorizontal, Upload, LayoutGrid, BarChart2, Moon, Sun, Globe, User, LogOut, Settings, Shield, History, X, Trash2, Clock, Command, Download, Loader2, Maximize } from 'lucide-react';
import { ColumnConfig, ViewMode, User as UserType } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';

interface TopBarProps {
  user: UserType | null;
  onLogout: () => void;
  onOpenProfile: () => void;
  onOpenAdmin: () => void;
  searchQuery: string;
  onSearchChange: (query: string) => void;
  isSearching?: boolean;
  columns: ColumnConfig[];
  onToggleColumn: (key: string) => void;
  onToggleAllColumns: (visible: boolean) => void;
  onOpenImport: () => void;
  onExport: () => void;
  isExporting: boolean;
  viewMode: ViewMode;
  onViewModeChange: (mode: ViewMode) => void;
}

export const TopBar: React.FC<TopBarProps> = ({
  user, onLogout, onOpenProfile, onOpenAdmin, searchQuery, onSearchChange, isSearching, columns, onToggleColumn, onToggleAllColumns, onOpenImport, onExport, isExporting, viewMode, onViewModeChange
}) => {
  const [isColumnMenuOpen, setIsColumnMenuOpen] = useState(false);
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);
  const { t, language, toggleLanguage, tProp } = useLanguage();
  const { theme, toggleTheme } = useTheme();
  const inputRef = useRef<HTMLInputElement>(null);

  const colMenuRef = useRef<HTMLDivElement>(null);
  const userMenuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
            e.preventDefault();
            inputRef.current?.focus();
        }
    };

    const handleClickOutside = (e: MouseEvent) => {
        if (colMenuRef.current && !colMenuRef.current.contains(e.target as Node)) {
            setIsColumnMenuOpen(false);
        }
        if (userMenuRef.current && !userMenuRef.current.contains(e.target as Node)) {
            setIsUserMenuOpen(false);
        }
    };

    window.addEventListener('keydown', handleKeyDown);
    document.addEventListener('mousedown', handleClickOutside);

    return () => {
        window.removeEventListener('keydown', handleKeyDown);
        document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
        document.documentElement.requestFullscreen().catch((e) => {
            console.error(`Error attempting to enable fullscreen: ${e.message}`);
        });
    } else {
        if (document.exitFullscreen) {
            document.exitFullscreen();
        }
    }
  };

  const nonSystemCols = columns.filter(c => !c.isSystem);
  const visibleCount = nonSystemCols.filter(c => c.visible).length;
  const isAllSelected = nonSystemCols.length > 0 && visibleCount === nonSystemCols.length;
  const isIndeterminate = visibleCount > 0 && !isAllSelected;

  const handleSelectAll = () => {
    onToggleAllColumns(!isAllSelected);
  };

  return (
    <div className="w-full flex items-center justify-between gap-6 px-2 py-2 pointer-events-none">
      {/* Search Pill */}
      <div className="flex-1 max-w-2xl relative z-[60] pointer-events-auto">
        <div className="relative group transition-all duration-300 focus-within:scale-[1.01]">
            <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                {isSearching ? (
                    <Loader2 className="text-sky-600 animate-spin" size={20} />
                ) : (
                    <Search className="text-slate-400 group-focus-within:text-sky-600 transition-colors" size={20} />
                )}
            </div>
            <input
                ref={inputRef}
                type="text"
                value={searchQuery}
                onChange={(e) => onSearchChange(e.target.value)}
                placeholder={t('searchPlaceholder')}
                className="block w-full pl-12 pr-12 py-3.5 bg-white/90 dark:bg-slate-900/90 backdrop-blur-2xl border border-white/20 dark:border-slate-800 rounded-[1.5rem] text-sm font-medium shadow-xl shadow-slate-200/40 dark:shadow-black/40 outline-none focus:ring-4 focus:ring-sky-500/10 transition-all text-slate-700 dark:text-slate-200 placeholder:text-slate-400"
            />
            <div className="absolute inset-y-0 right-4 flex items-center">
                {searchQuery ? (
                    <button 
                        onClick={() => { onSearchChange(''); inputRef.current?.focus(); }}
                        className="p-1 rounded-full text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700 hover:text-slate-600 dark:hover:text-slate-200 transition-colors animate-in fade-in zoom-in duration-200"
                    >
                        <X size={14} />
                    </button>
                ) : (
                    <span className="flex items-center gap-1 px-2 py-1 bg-slate-100 dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 text-[10px] font-bold text-slate-400 shadow-sm pointer-events-none">
                        <Command size={10} /> K
                    </span>
                )}
            </div>
        </div>
      </div>

      {/* Right Actions Island */}
      <div className="flex items-center gap-3 p-1.5 bg-white/90 dark:bg-slate-900/90 backdrop-blur-2xl border border-white/20 dark:border-slate-800 rounded-[1.5rem] shadow-xl shadow-slate-200/40 dark:shadow-black/40 pointer-events-auto z-[60]">

        {/* View Toggle */}
        <div className="flex items-center bg-slate-100 dark:bg-slate-800 rounded-[1.2rem] p-1 border border-slate-200 dark:border-slate-700">
            <button onClick={() => onViewModeChange('grid')} className={`p-2.5 rounded-[1rem] transition-all active:scale-95 ${viewMode === 'grid' ? 'bg-white dark:bg-slate-700 text-sky-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>
                <LayoutGrid size={18} />
            </button>
            <button onClick={() => onViewModeChange('chart')} className={`p-2.5 rounded-[1rem] transition-all active:scale-95 ${viewMode === 'chart' ? 'bg-white dark:bg-slate-700 text-sky-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>
                <BarChart2 size={18} />
            </button>
        </div>

        <div className="h-6 w-px bg-slate-200 dark:bg-slate-700 mx-1"></div>

        <button onClick={onOpenImport} className="p-3 text-slate-500 hover:text-sky-600 hover:bg-sky-50 dark:hover:bg-sky-900/20 rounded-full transition-all active:scale-95" title={t('importData')}>
            <Upload size={20} />
        </button>

        <button 
            onClick={onExport} 
            disabled={isExporting}
            className="p-3 text-slate-500 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-full transition-all active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed" 
            title="Download Report (CSV)"
        >
            {isExporting ? <Loader2 size={20} className="animate-spin text-blue-500" /> : <Download size={20} />}
        </button>

        <div className="relative" ref={colMenuRef}>
            <button onClick={() => setIsColumnMenuOpen(!isColumnMenuOpen)} className={`p-3 rounded-full transition-all active:scale-95 ${isColumnMenuOpen ? 'bg-sky-50 text-sky-600' : 'text-slate-500 hover:text-sky-600 hover:bg-sky-50 dark:hover:bg-sky-900/20'}`}>
                <SlidersHorizontal size={20} />
            </button>
            {isColumnMenuOpen && (
                <div className="absolute top-full right-0 mt-4 w-72 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2rem] shadow-2xl p-4 animate-in fade-in zoom-in-95 origin-top-right z-[100]">
                    <h4 className="text-xs font-black uppercase text-slate-400 mb-3 tracking-widest px-2">{t('visibleAttributes')}</h4>

                    <label className="flex items-center gap-3 px-3 py-2.5 rounded-xl hover:bg-slate-50 dark:hover:bg-slate-800 cursor-pointer transition-colors group mb-2 border-b border-slate-100 dark:border-slate-800 pb-2">
                        <div className={`w-5 h-5 rounded-md border flex items-center justify-center transition-colors ${isAllSelected || isIndeterminate ? 'bg-sky-600 border-sky-600' : 'border-slate-300 dark:border-slate-600 group-hover:border-sky-400'}`}>
                            {isAllSelected && <div className="w-2 h-2 bg-white rounded-full"></div>}
                            {isIndeterminate && <div className="w-2.5 h-0.5 bg-white rounded-full"></div>}
                        </div>
                        <input 
                            type="checkbox" 
                            checked={isAllSelected} 
                            ref={(el) => { if(el) el.indeterminate = isIndeterminate; }}
                            onChange={handleSelectAll} 
                            className="hidden" 
                        />
                        <span className="text-xs font-bold text-slate-800 dark:text-white transition-colors">{t('selectAll')}</span>
                    </label>

                    <div className="max-h-64 overflow-y-auto custom-scrollbar space-y-1 pr-1">
                        {columns.map(col => (
                            <label key={col.key} className="flex items-center gap-3 px-3 py-2.5 rounded-xl hover:bg-slate-50 dark:hover:bg-slate-800 cursor-pointer transition-colors group">
                                <div className={`w-5 h-5 rounded-md border flex items-center justify-center transition-colors ${col.visible ? 'bg-sky-600 border-sky-600' : 'border-slate-300 dark:border-slate-600 group-hover:border-sky-400'}`}>
                                    {col.visible && <div className="w-2 h-2 bg-white rounded-full"></div>}
                                </div>
                                <input type="checkbox" checked={col.visible} onChange={() => !col.isSystem && onToggleColumn(col.key)} disabled={col.isSystem} className="hidden" />
                                <span className={`text-xs font-bold transition-colors ${col.visible ? 'text-slate-800 dark:text-white' : 'text-slate-500'}`}>{tProp(col.label)}</span>
                            </label>
                        ))}
                    </div>
                </div>
            )}
        </div>

        <button onClick={toggleTheme} className="p-3 text-slate-500 hover:text-amber-500 hover:bg-amber-50 dark:hover:bg-amber-900/20 rounded-full transition-all active:scale-95">
            {theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}
        </button>

        <button onClick={toggleFullScreen} className="p-3 text-slate-500 hover:text-indigo-500 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 rounded-full transition-all active:scale-95" title="Full Screen">
            <Maximize size={20} />
