  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    setTimeout(() => {
      if (mode === 'login') {
        const found = accounts.find(acc => 
          (acc.name.toLowerCase() === username.toLowerCase() || acc.email.toLowerCase() === username.toLowerCase()) && 
          acc.password === password
        );

        if (found) {
          onLogin(found);
        } else {
          alert('Invalid credentials. Please check your username and password.');
        }
      } else {
        if (password !== confirmPassword) {
          alert('Passwords do not match');
          setIsLoading(false);
          return;
        }

        const newUser: PersistentUser = {
          id: `user-${Date.now()}`,
          name: username,
          email: email || `${username}@cnpc.com.cn`,
          role: 'editor',
          password: password,
          avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${username}`
        };

        const updated = [...accounts, newUser];
        setAccounts(updated);
        localStorage.setItem('resindb-users', JSON.stringify(updated));
        onLogin(newUser);
      }
      setIsLoading(false);
    }, 1200);
