                            className={`w-full flex items-center gap-3 p-2 rounded-2xl hover:bg-white dark:hover:bg-slate-800 transition-all border border-transparent hover:border-slate-100 dark:hover:border-slate-700 text-left ${username === (acc.email || acc.name) ? 'bg-sky-50/50 dark:bg-sky-900/10 border-sky-100/50 dark:border-sky-900/30' : ''}`}
                        >
