// FIX: Helper to safely format cell values. Handles objects, nulls, and undefined without crashing.
const safeRenderValue = (val: any, unit?: string): string => {
    if (val === null || val === undefined || val === '') return '-';
    if (typeof val === 'object') return JSON.stringify(val); // Fallback for raw objects
    return `${val}${unit ? ` ${unit}` : ''}`;
};

