);

export const DataGrid: React.FC<DataGridProps> = ({ data, columns, isLoading, onDelete, onUpdate, onBatchUpdate, onCategorySelect, selectedIds: propSelectedIds, onSelectionChange }) => {
  const { t, tProp } = useLanguage();
  // FIX: Guard against undefined columns
  const visibleColumns = (columns || []).filter((c) => c.visible);

  const [localSelectedIds, setLocalSelectedIds] = useState<Set<string>>(new Set());
  const selectedIds = propSelectedIds || localSelectedIds;
  const handleSelectionChange = onSelectionChange || setLocalSelectedIds;

  const [sortConfig, setSortConfig] = useState<SortConfig | null>(null);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [deletingIds, setDeletingIds] = useState<string[]>([]);
  const [isBatchEditOpen, setIsBatchEditOpen] = useState(false);
  const [viewingProduct, setViewingProduct] = useState<Product | null>(null);
  const [isComparisonOpen, setIsComparisonOpen] = useState(false);

  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 15;

  const handleSort = (key: string) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const sortedData = useMemo(() => {
    // FIX: Guard against undefined data
    if (!data) return [];
    if (!sortConfig) return data;

    return [...data].sort((a, b) => {
      // FIX: Robust safe access. Fallback to empty string for safety.
      let aVal: any = a.properties?.[sortConfig.key]?.value ?? (a as any)[sortConfig.key] ?? '';
      let bVal: any = b.properties?.[sortConfig.key]?.value ?? (b as any)[sortConfig.key] ?? '';

      // FIX: Handle mixed types (numbers vs strings). Force numeric sort if strictly numeric.
      const aNum = parseFloat(String(aVal));
      const bNum = parseFloat(String(bVal));
      const isANum = !isNaN(aNum);
      const isBNum = !isNaN(bNum);

      if (isANum && isBNum) {
          aVal = aNum;
          bVal = bNum;
      } else {
          // Fallback to string comparison for mixed/text data
          aVal = String(aVal).toLowerCase();
          bVal = String(bVal).toLowerCase();
      }

      if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
      if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
  }, [data, sortConfig]);

  const paginatedData = useMemo(() => {
      const start = (currentPage - 1) * pageSize;
      return sortedData.slice(start, start + pageSize);
  }, [sortedData, currentPage]);

  const totalPages = Math.ceil(sortedData.length / pageSize);

  const toggleSelection = (id: string) => {
    const newSelected = new Set(selectedIds);
    if (newSelected.has(id)) newSelected.delete(id);
    else newSelected.add(id);
    handleSelectionChange(newSelected);
  };

  const toggleAll = () => {
    if (selectedIds.size === paginatedData.length && paginatedData.length > 0) {
      handleSelectionChange(new Set());
    } else {
      const newSelected = new Set(selectedIds);
      paginatedData.forEach(p => newSelected.add(p.id));
      handleSelectionChange(newSelected);
    }
  };

  // UX: Show skeleton when loading
  if (isLoading) return <GridSkeleton />;

  return (
    <div className="h-full flex flex-col bg-transparent relative">
        {/* Toolbar - Only visible when selection active */}
        {selectedIds.size > 0 && (
            <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-50 flex items-center gap-2 px-4 py-2 bg-slate-900/90 dark:bg-white/90 backdrop-blur-md rounded-2xl shadow-2xl text-white dark:text-slate-900 animate-in slide-in-from-bottom-6 border border-white/10 dark:border-slate-300">
                <span className="text-xs font-bold px-2">{selectedIds.size} {t('selected')}</span>
                <div className="h-4 w-px bg-white/20 dark:bg-slate-900/20"></div>
                <button 
                    onClick={() => setIsComparisonOpen(true)}
                    className="p-2 hover:bg-white/10 dark:hover:bg-slate-900/10 rounded-lg transition-colors flex items-center gap-2 text-xs font-bold"
                >
                    <GitCompare size={14} /> Compare
                </button>
                <button 
                    onClick={() => setIsBatchEditOpen(true)}
                    className="p-2 hover:bg-white/10 dark:hover:bg-slate-900/10 rounded-lg transition-colors flex items-center gap-2 text-xs font-bold"
                >
                    <Edit size={14} /> {t('editSelected')}
                </button>
                <button 
                    onClick={() => setDeletingIds(Array.from(selectedIds))}
                    className="p-2 bg-rose-500 hover:bg-rose-600 text-white rounded-lg transition-colors flex items-center gap-2 text-xs font-bold ml-1"
                >
                    <Trash2 size={14} /> {t('deleteSelected')}
                </button>
                <button 
                    onClick={() => handleSelectionChange(new Set())}
                    className="ml-2 p-1.5 hover:bg-white/10 dark:hover:bg-slate-900/10 rounded-full"
                >
                    <X size={12} />
                </button>
            </div>
        )}

      <div className="flex-1 overflow-auto custom-scrollbar relative">
        <table className="w-full text-sm text-left border-separate border-spacing-0">
          <thead className="text-xs text-slate-500 dark:text-slate-400 uppercase bg-white/80 dark:bg-slate-900/80 sticky top-0 z-20 backdrop-blur-md shadow-sm">
            <tr>
              <th className="px-4 py-3 font-medium w-10 border-b border-slate-200 dark:border-slate-800">
                <div className="flex items-center justify-center">
                  <button onClick={toggleAll} className="text-slate-400 hover:text-primary-500 transition-colors">
                    {selectedIds.size > 0 && selectedIds.size === paginatedData.length ? <CheckSquare size={16} /> : selectedIds.size > 0 ? <MinusSquare size={16} /> : <Square size={16} />}
                  </button>
                </div>
              </th>
              {visibleColumns.map((col) => {
                  // UX: Numbers should align right
                  const isNumeric = !['gradeName', 'manufacturer', 'typicalApplication', '应用', '典型应用'].includes(col.key) && !col.isSystem;
                  return (
                    <th key={col.key} className={`px-4 py-3 font-bold border-b border-slate-200 dark:border-slate-800 hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors cursor-pointer select-none whitespace-nowrap ${isNumeric ? 'text-right' : 'text-left'}`} onClick={() => handleSort(col.key)}>
                      <div className={`flex items-center gap-1.5 ${isNumeric ? 'justify-end' : 'justify-start'}`}>
                        {tProp(col.label)}
                        {sortConfig?.key === col.key && (
                          sortConfig.direction === 'asc' ? <ArrowUp size={12} className="text-primary-500" /> : <ArrowDown size={12} className="text-primary-500" />
                        )}
                      </div>
                    </th>
                  );
              })}
              <th className="px-4 py-3 font-medium text-right w-20 border-b border-slate-200 dark:border-slate-800 bg-white/80 dark:bg-slate-900/80 sticky right-0 z-30 shadow-[-4px_0_8px_-2px_rgba(0,0,0,0.05)] backdrop-blur-md">{t('actions')}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 dark:divide-slate-800/50">
            {paginatedData.map((product) => {
                const isSelected = selectedIds.has(product.id);
                return (
                    <tr 
                        key={product.id} 
                        className={`group transition-all hover:bg-white dark:hover:bg-slate-800 ${isSelected ? 'bg-primary-50/50 dark:bg-primary-900/10' : ''}`}
                        onClick={() => toggleSelection(product.id)}
                    >
                        <td className="px-4 py-3 w-10 sticky left-0 z-10 bg-transparent" onClick={e => e.stopPropagation()}>
                            <div className="flex items-center justify-center">
                                <button onClick={() => toggleSelection(product.id)} className={`transition-colors ${isSelected ? 'text-primary-500' : 'text-slate-300 group-hover:text-slate-400'}`}>
                                    {isSelected ? <CheckSquare size={16} /> : <Square size={16} />}
                                </button>
                            </div>
                        </td>
                        {visibleColumns.map((col) => {
                            // System Columns
                            if (col.key === 'gradeName') {
                                return (
                                    <td key={col.key} className="px-4 py-3 font-bold text-slate-800 dark:text-white whitespace-nowrap">
                                        <div className="flex items-center gap-2 cursor-pointer hover:text-primary-600" onClick={(e) => { e.stopPropagation(); setViewingProduct(product); }}>
                                            {product.gradeName || <span className="text-slate-300 italic">Unnamed</span>}
                                            {product.properties?.['密度']?.instrument && <FlaskConical size={10} className="text-emerald-500" />}
                                        </div>
                                    </td>
                                );
                            }
                            if (col.key === 'manufacturer') {
                                return (
                                    <td key={col.key} className="px-4 py-3 text-slate-600 dark:text-slate-300 whitespace-nowrap">
                                        <div className="flex items-center gap-2 max-w-[180px]">
                                            <div className="p-1 rounded bg-slate-100 dark:bg-slate-800 text-slate-500 shrink-0"><Factory size={10} /></div>
                                            <span className="truncate" title={product.manufacturer}>{product.manufacturer || '-'}</span>
                                        </div>
                                    </td>
                                );
                            }

                            // Dynamic Property Columns
                            const prop = product.properties?.[col.key];
                            const isNumeric = typeof prop?.value === 'number';

                            return (
                                <td key={col.key} className={`px-4 py-3 text-slate-600 dark:text-slate-400 whitespace-nowrap relative group/cell ${isNumeric ? 'text-right' : 'text-left'}`}>
                                    {prop ? (
                                        <div className={`flex items-baseline gap-1 ${isNumeric ? 'justify-end' : 'justify-start'} max-w-[200px]`}>
                                            <span className={`block truncate ${isNumeric ? 'font-mono tabular-nums text-primary-600 dark:text-primary-400 font-bold' : ''}`} title={String(prop.value)}>
                                                {safeRenderValue(prop.value)}
                                            </span>
                                            {prop.unit && <span className="text-[10px] text-slate-400 select-none shrink-0">{prop.unit}</span>}

                                            {(prop.instrument || prop.standard) && (
                                                <div className="opacity-0 group-hover/cell:opacity-100 transition-opacity absolute right-2 top-1/2 -translate-y-1/2 z-20">
                                                     <Info size={12} className="text-slate-300 hover:text-primary-500 cursor-help" />
                                                </div>
                                            )}
                                            {(prop.instrument || prop.standard) && (
                                                <PropertyContextTooltip 
                                                    prop={prop} 
                                                    className="opacity-0 group-hover/cell:opacity-100 invisible group-hover/cell:visible scale-95 group-hover/cell:scale-100"
                                                />
                                            )}
                                        </div>
                                    ) : (
                                        <span className="text-slate-300 text-xs">-</span>
                                    )}
                                </td>
                            );
                        })}
                        <td className="px-4 py-3 text-right w-20 sticky right-0 z-10 bg-transparent group-hover:bg-white dark:group-hover:bg-slate-800 shadow-[-4px_0_8px_-2px_rgba(0,0,0,0.05)] transition-colors" onClick={e => e.stopPropagation()}>
                            <div className="flex items-center justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                <button onClick={() => setViewingProduct(product)} className="p-1.5 text-slate-400 hover:text-primary-500 hover:bg-primary-50 dark:hover:bg-primary-900/20 rounded-lg transition-colors" title={t('details')}><Eye size={14} /></button>
                                <button onClick={() => setEditingProduct(product)} className="p-1.5 text-slate-400 hover:text-amber-500 hover:bg-amber-50 dark:hover:bg-amber-900/20 rounded-lg transition-colors" title={t('editProduct')}><Edit size={14} /></button>
                                <button onClick={() => setDeletingIds([product.id])} className="p-1.5 text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg transition-colors" title={t('delete')}><Trash2 size={14} /></button>
                            </div>
                        </td>
                    </tr>
                );
            })}

            {/* UX: Empty State - Better UI than just whitespace */}
            {paginatedData.length === 0 && (
                <tr>
                    <td colSpan={visibleColumns.length + 2} className="py-20 text-center">
                        <div className="flex flex-col items-center justify-center gap-4">
                             <div className="w-16 h-16 bg-slate-50 dark:bg-slate-800/50 rounded-full flex items-center justify-center border border-slate-100 dark:border-slate-800">
                                <Info size={32} className="text-slate-300" />
                             </div>
                             <div>
                                <p className="text-slate-500 font-bold">No products found</p>
                                <p className="text-xs text-slate-400 mt-1">Try adjusting your search filters or clear selection</p>
                             </div>
                        </div>
                    </td>
                </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination Footer */}
      <div className="flex items-center justify-between px-4 py-3 border-t border-slate-200 dark:border-slate-800 bg-white/60 dark:bg-slate-900/60 backdrop-blur-sm shrink-0">
         <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">
            {t('showing')} <span className="font-bold text-slate-800 dark:text-slate-200">{(currentPage - 1) * pageSize + 1}-{Math.min(currentPage * pageSize, sortedData.length)}</span> of <span className="font-bold text-slate-800 dark:text-slate-200">{sortedData.length}</span>
         </span>
         <div className="flex items-center gap-2">
             <button 
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))} 
                disabled={currentPage === 1}
                className="p-1.5 rounded-lg border border-slate-200 dark:border-slate-700 text-slate-500 hover:bg-white dark:hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
             >
                <ChevronLeft size={16} />
             </button>
             <span className="text-xs font-bold text-slate-700 dark:text-slate-300 min-w-[3rem] text-center">
                {currentPage} / {totalPages || 1}
             </span>
             <button 
                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} 
                disabled={currentPage === totalPages || totalPages === 0}
                className="p-1.5 rounded-lg border border-slate-200 dark:border-slate-700 text-slate-500 hover:bg-white dark:hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
             >
                <ChevronRight size={16} />
             </button>
         </div>
      </div>

      {/* Modals */}
      <EditProductModal 
        isOpen={!!editingProduct} 
        onClose={() => setEditingProduct(null)} 
        product={editingProduct} 
        onSave={async (p) => { onUpdate(p); setEditingProduct(null); return true; }} 
      />
      <DeleteConfirmationModal 
        isOpen={deletingIds.length > 0} 
        onClose={() => setDeletingIds([])} 
        onConfirm={() => { onDelete(deletingIds); setDeletingIds([]); handleSelectionChange(new Set()); }} 
        productNames={deletingIds.map(id => data.find(p => p.id === id)?.gradeName || 'Unknown')} 
      />
      <BatchEditModal
        isOpen={isBatchEditOpen}
        onClose={() => setIsBatchEditOpen(false)}
        selectedProducts={data.filter(p => selectedIds.has(p.id))}
        onSave={(ids, updates) => { onBatchUpdate(ids, updates); handleSelectionChange(new Set()); }}
      />
      <ProductDetailDrawer 
        product={viewingProduct}
        onClose={() => setViewingProduct(null)}
        onCategoryClick={(id) => { onCategorySelect(id); setViewingProduct(null); }}
      />
      {isComparisonOpen && (
          <ComparisonView 
              products={data.filter(p => selectedIds.has(p.id))}
              onClose={() => setIsComparisonOpen(false)}
              onRemoveProduct={(id) => toggleSelection(id)}
          />
      )}
    </div>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  Settings, Activity, X, FileJson, Image as ImageIcon, 
  Hexagon, ScatterChart, Waves, Triangle, Info, Loader2,
  Filter, Plus, Trash2, ChevronDown, Check
} from 'lucide-react';
import * as echarts from 'echarts';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { ScientificChart, ChartType } from './ScientificChart';

interface DataVisualizerProps {
  data: Product[];
  selectedProducts?: Product[];
}

export const DataVisualizer: React.FC<DataVisualizerProps> = ({ data, selectedProducts }) => {
  const { t, tProp } = useLanguage();
  const [chartInstance, setChartInstance] = useState<echarts.ECharts | null>(null);
  const [activeChart, setActiveChart] = useState<ChartType>('radar');
  const [showConfig, setShowConfig] = useState(true);
  const [isExporting, setIsExporting] = useState(false);

  // Filter State
  const [filters, setFilters] = useState<Record<string, { min: string; max: string }>>({});
  const [isFilterDropdownOpen, setIsFilterDropdownOpen] = useState(false);
  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
              setIsFilterDropdownOpen(false);
          }
      };
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Determine base data set
  const baseData = useMemo(() => {
    return (selectedProducts && selectedProducts.length > 0) ? selectedProducts : data;
  }, [data, selectedProducts]);

  // Extract available numeric properties for filtering
  const numericProperties = useMemo(() => {
      const props = new Set<string>();
      baseData.forEach(p => {
          Object.entries(p.properties).forEach(([key, val]) => {
              const num = parseFloat(String(val.value));
              if (!isNaN(num)) props.add(key);
          });
      });
      return Array.from(props).sort();
  }, [baseData]);

  // Apply filters to baseData
  const filteredData = useMemo(() => {
      if (Object.keys(filters).length === 0) return baseData;

      return baseData.filter(p => {
          return Object.entries(filters).every(([key, { min, max }]) => {
              const val = p.properties[key]?.value;
              const numVal = parseFloat(String(val));

              // If property doesn't exist or isn't a number, decide policy. 
              // Strict: exclude. Lenient: include? Usually strict for filters.
              if (isNaN(numVal)) return false; 

              const minVal = min === '' ? -Infinity : parseFloat(min);
              const maxVal = max === '' ? Infinity : parseFloat(max);

              return numVal >= minVal && numVal <= maxVal;
          });
      });
  }, [baseData, filters]);

  const handleAddFilter = (key: string) => {
      if (!filters[key]) {
          setFilters(prev => ({ ...prev, [key]: { min: '', max: '' } }));
      }
      setIsFilterDropdownOpen(false);
  };

  const updateFilter = (key: string, field: 'min' | 'max', val: string) => {
      // Allow only numbers and decimals
      if (val && !/^-?\d*\.?\d*$/.test(val)) return;
      setFilters(prev => ({
          ...prev,
          [key]: { ...prev[key], [field]: val }
      }));
  };

  const removeFilter = (key: string) => {
      setFilters(prev => {
          const next = { ...prev };
          delete next[key];
          return next;
      });
  };

  // Helper: Safe Float Parser (Layer 1: Anti-Crash)
  const safeParse = (val: any, fallback = 0): number => {
      if (val === undefined || val === null || val === '') return fallback;
      const num = parseFloat(String(val));
      return isNaN(num) ? fallback : num;
  };

  // --- Data Preparation Logic (Defensive) using filteredData ---

  // 1. Radar Data: Compare top 5 (or selected) products
  const radarData = useMemo(() => {
    try {
        const source = filteredData.slice(0, 5); 
        return source.map(p => ({
          name: p.gradeName,
          value: [
            safeParse(p.properties['熔体质量流动速率']?.value),
            safeParse(p.properties['密度']?.value),
            safeParse(p.properties['弯曲模量']?.value),
            safeParse(p.properties['悬臂梁缺口冲击强度']?.value),
            safeParse(p.properties['热变形温度']?.value)
          ]
        }));
    } catch (e) {
        console.error("Radar Prep Error:", e);
        return [];
    }
  }, [filteredData]);

  // 2. Ashby Data: MFR vs Impact
  const ashbyData = useMemo(() => {
    try {
        const groups: Record<string, any[]> = {};
        filteredData.forEach(p => {
          const man = p.manufacturer || 'Unknown';
          if (!groups[man]) groups[man] = [];

          const mfr = safeParse(p.properties['熔体质量流动速率']?.value, -1);
          const impact = safeParse(p.properties['悬臂梁缺口冲击强度']?.value, -1);

          if (mfr > 0 && impact > 0) {
            groups[man].push([mfr, impact, p.gradeName]);
          }
        });

        return Object.entries(groups).map(([name, points]) => ({
          name,
          data: points
        }));
    } catch(e) {
        console.error("Ashby Prep Error:", e);
        return [];
    }
  }, [filteredData]);

  // 5. Ternary Data: Mock Formulation (Simulated based on properties)
  const ternaryData = useMemo(() => {
    try {
        const source = filteredData.length > 0 ? filteredData : [];
        return source.slice(0, 100).map((p, i) => {
            // Simulation logic to create 3 clusters based on density/MFR
            const mfr = safeParse(p.properties['熔体质量流动速率']?.value, 1);
            let a, b, c;

            if (mfr < 1) {
                // High Viscosity Cluster (High A)
                a = 0.6 + Math.random() * 0.3;
                b = Math.random() * (0.9 - a);
                c = 1 - a - b;
            } else if (mfr > 10) {
                // Low Viscosity Cluster (High B)
                b = 0.6 + Math.random() * 0.3;
                a = Math.random() * (0.9 - b);
                c = 1 - a - b;
            } else {
                // Balanced Cluster (High C or center)
                c = 0.5 + Math.random() * 0.4;
                a = Math.random() * (0.9 - c);
                b = 1 - a - c;
            }

            // Normalize exactly to 1
            const sum = a + b + c;
            a = a / sum;
            b = b / sum;
            c = c / sum;

            return {
                a, b, c,
                name: p.gradeName,
                value: safeParse(p.properties['拉伸强度']?.value, 50) + (Math.random() * 10 - 5)
            };
        });
    } catch(e) {
        return [];
    }
  }, [filteredData]);

  // Select the correct data based on chart type to pass to ScientificChart
  const currentChartData = useMemo(() => {
      switch(activeChart) {
          case 'radar': return radarData;
          case 'ashby': return ashbyData;
          case 'gpc': return filteredData; 
          case 'rheology': return filteredData; 
          case 'ternary': return ternaryData;
          default: return [];
      }
  }, [activeChart, radarData, ashbyData, filteredData, ternaryData]);

  const handleExport = async (format: 'png' | 'json') => {
      setIsExporting(true);
      if (format === 'png' && chartInstance) {
          try {
            const dataUrl = chartInstance.getDataURL({
                type: 'png',
                pixelRatio: 2,
                backgroundColor: '#fff'
            });
            const a = document.createElement('a');
            a.href = dataUrl;
            a.download = `resindb_${activeChart}_analysis.png`;
            a.click();
          } catch(e) { console.error(e); }
      } else if (format === 'json') {
          const jsonStr = JSON.stringify(currentChartData, null, 2);
          const blob = new Blob([jsonStr], {type: 'application/json'});
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `resindb_${activeChart}_data.json`;
          a.click();
      }
      setIsExporting(false);
  };

  const chartDescriptions = {
      radar: t('desc_radar'),
      ashby: t('desc_ashby'),
      gpc: t('desc_gpc'),
      rheology: t('desc_rheology'),
      ternary: t('desc_ternary')
  };

  return (
    <div className="flex flex-col md:flex-row h-full gap-4 overflow-hidden">
      {/* Scientific Controls Sidebar */}
      <div className={`flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl transition-all duration-500 ease-out shrink-0 overflow-hidden shadow-xl ${showConfig ? 'w-full md:w-72 opacity-100 translate-x-0' : 'w-0 opacity-0 -translate-x-10 border-0 pointer-events-none'}`}>
        <div className="p-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50/80 dark:bg-slate-950/50 backdrop-blur-sm">
          <div className="flex items-center gap-2 font-black text-sm text-slate-800 dark:text-white uppercase tracking-widest">
            <Activity size={16} className="text-emerald-500" />
            {t('analysisMode')}
          </div>
          <button onClick={() => setShowConfig(false)} className="md:hidden text-slate-400 hover:text-slate-600">
            <X size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar">
            <div className="p-4 space-y-2">
                {[
                    { id: 'radar', label: t('chart_radar'), icon: Hexagon, color: 'text-indigo-500' },
                    { id: 'ashby', label: t('chart_ashby'), icon: ScatterChart, color: 'text-rose-500' },
                    { id: 'gpc', label: t('chart_gpc'), icon: Waves, color: 'text-blue-500' },
                    { id: 'rheology', label: t('chart_rheology'), icon: Activity, color: 'text-amber-500' },
                    { id: 'ternary', label: t('chart_ternary'), icon: Triangle, color: 'text-emerald-500' },
                ].map(item => (
                    <button 
                        key={item.id}
                        onClick={() => setActiveChart(item.id as ChartType)}
                        className={`w-full flex items-center gap-3 p-3 rounded-2xl border transition-all duration-200 group relative overflow-hidden ${
                            activeChart === item.id 
                            ? 'bg-slate-900 dark:bg-white text-white dark:text-slate-900 border-transparent shadow-lg' 
                            : 'bg-white dark:bg-slate-800/50 border-slate-100 dark:border-slate-800 text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800'
                        }`}
                    >
                        <div className={`p-2 rounded-xl bg-slate-100 dark:bg-slate-700/50 ${activeChart === item.id ? 'bg-white/20 text-white' : item.color}`}>
                            <item.icon size={18} />
                        </div>
                        <span className="text-xs font-bold uppercase tracking-wide">{item.label}</span>
                        {activeChart === item.id && <div className="absolute right-0 top-0 bottom-0 w-1 bg-emerald-500"></div>}
                    </button>
                ))}
            </div>

            {/* --- Data Filters Section --- */}
            <div className="px-4 pb-4">
                <div className="border-t border-slate-100 dark:border-slate-800 pt-4 mb-3 flex items-center justify-between">
                    <div className="flex items-center gap-2 font-black text-sm text-slate-800 dark:text-white uppercase tracking-widest">
                        <Filter size={16} className="text-blue-500" />
                        {t('dataFilters')}
                    </div>

                    <div className="relative" ref={filterDropdownRef}>
                        <button 
                            onClick={() => setIsFilterDropdownOpen(!isFilterDropdownOpen)}
                            className="p-1.5 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 rounded-lg hover:bg-blue-100 dark:hover:bg-blue-900/40 transition-colors"
                            title="Add Filter"
                        >
                            <Plus size={16} />
                        </button>

                        {isFilterDropdownOpen && (
                            <div className="absolute top-full right-0 mt-2 w-56 max-h-60 overflow-y-auto custom-scrollbar bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl shadow-xl z-50 p-1">
                                {numericProperties.length > 0 ? numericProperties.map(prop => (
                                    <button
                                        key={prop}
                                        onClick={() => handleAddFilter(prop)}
                                        className="w-full text-left px-3 py-2 text-xs font-medium text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-700 rounded-lg transition-colors truncate"
                                        disabled={!!filters[prop]}
                                    >
                                        <div className="flex items-center justify-between">
                                            <span className="truncate">{tProp(prop)}</span>
                                            {filters[prop] && <Check size={12} className="text-emerald-500 shrink-0" />}
                                        </div>
                                    </button>
                                )) : <div className="p-3 text-xs text-slate-400 text-center">No numeric properties</div>}
                            </div>
                        )}
                    </div>
                </div>

                <div className="space-y-3">
                    {Object.keys(filters).length === 0 ? (
                        <div className="p-4 rounded-2xl bg-slate-50 dark:bg-slate-900/30 border border-slate-100 dark:border-slate-800 border-dashed text-center">
                            <span className="text-xs text-slate-400">{t('noFilters')}</span>
                        </div>
                    ) : (
                        Object.entries(filters).map(([key, { min, max }]) => (
                            <div key={key} className="bg-white dark:bg-slate-800/50 p-3 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm animate-in slide-in-from-right-2 fade-in duration-300">
                                <div className="flex justify-between items-center mb-2.5">
                                    <span className="text-xs font-bold text-slate-700 dark:text-slate-200 truncate" title={tProp(key)}>{tProp(key)}</span>
                                    <button 
                                        onClick={() => removeFilter(key)}
                                        className="text-slate-400 hover:text-rose-500 transition-colors p-1"
                                    >
                                        <X size={12} />
                                    </button>
                                </div>
                                <div className="flex items-center gap-2">
                                    <div className="flex-1 relative">
                                        <input 
                                            type="text" 
                                            placeholder="Min" 
                                            value={min}
                                            onChange={(e) => updateFilter(key, 'min', e.target.value)}
                                            className="w-full px-2 py-1.5 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg text-xs font-mono outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/10 transition-all text-center"
                                        />
                                    </div>
                                    <span className="text-slate-300 dark:text-slate-600 font-light">—</span>
                                    <div className="flex-1 relative">
                                        <input 
                                            type="text" 
                                            placeholder="Max" 
                                            value={max}
                                            onChange={(e) => updateFilter(key, 'max', e.target.value)}
                                            className="w-full px-2 py-1.5 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg text-xs font-mono outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/10 transition-all text-center"
                                        />
                                    </div>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>

            <div className="mx-4 mt-2 mb-6 p-4 bg-slate-50 dark:bg-slate-950/30 rounded-2xl border border-slate-100 dark:border-slate-800">
                <div className="flex items-center gap-2 mb-2 text-slate-400 dark:text-slate-500">
                    <Info size={14} />
                    <span className="text-[10px] font-bold uppercase tracking-widest">{t('chartContext')}</span>
                </div>
                <p className="text-xs text-slate-600 dark:text-slate-300 leading-relaxed font-medium">
                    {chartDescriptions[activeChart]}
                </p>
                <div className="mt-3 pt-3 border-t border-slate-200/50 dark:border-slate-800/50 flex items-center justify-between text-[10px]">
                    <span className="text-slate-400 font-bold uppercase tracking-wider">Active Dataset</span>
                    <span className="text-blue-600 dark:text-blue-400 font-black bg-blue-50 dark:bg-blue-900/20 px-2 py-0.5 rounded-full">{filteredData.length} Items</span>
                </div>
            </div>
        </div>

        <div className="p-4 border-t border-slate-100 dark:border-slate-800 grid grid-cols-2 gap-3 bg-white dark:bg-slate-900 shrink-0">
            <button onClick={() => handleExport('json')} className="flex items-center justify-center gap-2 p-3 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-xl text-[10px] font-bold text-slate-600 dark:text-slate-300 transition-colors uppercase tracking-wider"><FileJson size={14} /> {t('exportJson')}</button>
            <button onClick={() => handleExport('png')} disabled={isExporting} className="flex items-center justify-center gap-2 p-3 bg-emerald-600 hover:bg-emerald-500 disabled:opacity-70 text-white rounded-xl text-[10px] font-bold transition-all uppercase tracking-wider shadow-lg">{isExporting ? <Loader2 size={14} className="animate-spin" /> : <ImageIcon size={14} />} {t('exportPng')}</button>
        </div>
      </div>

      {/* Chart Canvas Area */}
      <div className="flex-1 flex flex-col bg-white/50 dark:bg-slate-900/50 backdrop-blur-xl border border-slate-200 dark:border-slate-800 rounded-[2rem] relative min-h-[500px] shadow-2xl overflow-hidden group">
         {!showConfig && (
             <button onClick={() => setShowConfig(true)} className="absolute top-6 right-6 z-30 p-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-slate-500 hover:text-emerald-500 shadow-xl transition-all hover:scale-105 active:scale-95">
                <Settings size={20} />
             </button>
         )}

         <div className="flex-1 w-full h-full p-4 relative">
            <ScientificChart 
                type={activeChart} 
                data={currentChartData} 
                onChartReady={setChartInstance}
                loading={false}
            />

            {/* Watermark */}
            <div className="absolute bottom-6 right-6 pointer-events-none opacity-10 flex flex-col items-end z-0">
                <span className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter">ResinDB</span>
                <span className="text-xs font-bold uppercase tracking-widest text-slate-500">Scientific Visualization</span>
            </div>
         </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Search, SlidersHorizontal, Upload, LayoutGrid, BarChart2, Moon, Sun, Globe, User, LogOut, Settings, Shield, History, X, Trash2, Clock, Command, Download, Loader2, Maximize } from 'lucide-react';
import { ColumnConfig, ViewMode, User as UserType } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';

interface TopBarProps {
  user: UserType | null;
  onLogout: () => void;
  onOpenProfile: () => void;
  onOpenAdmin: () => void;
  searchQuery: string;
  onSearchChange: (query: string) => void;
  isSearching?: boolean;
  columns: ColumnConfig[];
  onToggleColumn: (key: string) => void;
  onToggleAllColumns: (visible: boolean) => void;
  onOpenImport: () => void;
  onExport: () => void;
  isExporting: boolean;
  viewMode: ViewMode;
  onViewModeChange: (mode: ViewMode) => void;
}

export const TopBar: React.FC<TopBarProps> = ({
  user, onLogout, onOpenProfile, onOpenAdmin, searchQuery, onSearchChange, isSearching, columns, onToggleColumn, onToggleAllColumns, onOpenImport, onExport, isExporting, viewMode, onViewModeChange
}) => {
  const [isColumnMenuOpen, setIsColumnMenuOpen] = useState(false);
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);
  const { t, language, toggleLanguage, tProp } = useLanguage();
  const { theme, toggleTheme } = useTheme();
  const inputRef = useRef<HTMLInputElement>(null);

  const colMenuRef = useRef<HTMLDivElement>(null);
  const userMenuRef = useRef<HTMLDivElement>(null);

  // Search History State
  const [searchHistory, setSearchHistory] = useState<string[]>([]);
  const [showHistory, setShowHistory] = useState(false);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
            e.preventDefault();
            inputRef.current?.focus();
        }
    };

    const handleClickOutside = (e: MouseEvent) => {
        if (colMenuRef.current && !colMenuRef.current.contains(e.target as Node)) {
            setIsColumnMenuOpen(false);
        }
        if (userMenuRef.current && !userMenuRef.current.contains(e.target as Node)) {
            setIsUserMenuOpen(false);
        }
    };

    window.addEventListener('keydown', handleKeyDown);
    document.addEventListener('mousedown', handleClickOutside);

    // Load history
    const savedHistory = localStorage.getItem('resindb_search_history');
    if (savedHistory) {
        try {
            setSearchHistory(JSON.parse(savedHistory));
        } catch (e) {
            console.error('Failed to load search history');
        }
    }

    return () => {
        window.removeEventListener('keydown', handleKeyDown);
        document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const saveToHistory = (query: string) => {
      if (!query.trim()) return;
      const clean = query.trim();
      setSearchHistory(prev => {
          const filtered = prev.filter(item => item !== clean);
          const updated = [clean, ...filtered].slice(0, 5);
          localStorage.setItem('resindb_search_history', JSON.stringify(updated));
          return updated;
      });
  };

  const removeFromHistory = (e: React.MouseEvent, itemToRemove: string) => {
      e.stopPropagation();
      setSearchHistory(prev => {
          const updated = prev.filter(item => item !== itemToRemove);
          localStorage.setItem('resindb_search_history', JSON.stringify(updated));
          return updated;
      });
  };

  const clearHistory = () => {
      setSearchHistory([]);
      localStorage.removeItem('resindb_search_history');
  };

  const handleInputKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
          saveToHistory(searchQuery);
          setShowHistory(false);
          inputRef.current?.blur();
      }
  };

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
        document.documentElement.requestFullscreen().catch((e) => {
            console.error(`Error attempting to enable fullscreen: ${e.message}`);
        });
    } else {
        if (document.exitFullscreen) {
            document.exitFullscreen();
        }
    }
  };

  const nonSystemCols = columns.filter(c => !c.isSystem);
  const visibleCount = nonSystemCols.filter(c => c.visible).length;
  const isAllSelected = nonSystemCols.length > 0 && visibleCount === nonSystemCols.length;
  const isIndeterminate = visibleCount > 0 && !isAllSelected;

  const handleSelectAll = () => {
    onToggleAllColumns(!isAllSelected);
  };

  return (
    <div className="w-full flex items-center justify-between gap-6 px-2 py-2 pointer-events-none">
      {/* Search Pill - Clean & Minimal */}
      <div className="flex-1 max-w-2xl relative z-[60] pointer-events-auto">
        <div className="relative group transition-all duration-300 focus-within:scale-[1.01]">
            <div className="absolute inset-y-0 left-0 pl-5 flex items-center pointer-events-none">
                {isSearching ? (
                    <Loader2 className="text-primary-500 animate-spin" size={20} />
                ) : (
                    <Search className="text-slate-400 group-focus-within:text-primary-500 transition-colors" size={20} />
                )}
            </div>
            <input
                ref={inputRef}
                type="text"
                value={searchQuery}
                onChange={(e) => onSearchChange(e.target.value)}
                onFocus={() => setShowHistory(true)}
                onBlur={() => setTimeout(() => setShowHistory(false), 200)}
                onKeyDown={handleInputKeyDown}
                placeholder={t('searchPlaceholder')}
                className="block w-full pl-14 pr-12 py-4 bg-white/80 dark:bg-slate-900/80 backdrop-blur-2xl border border-slate-200/50 dark:border-slate-800/50 rounded-[2rem] text-sm font-medium shadow-glass dark:shadow-none outline-none focus:ring-4 focus:ring-primary-500/10 focus:border-primary-500/20 transition-all text-slate-700 dark:text-slate-200 placeholder:text-slate-400"
            />
            <div className="absolute inset-y-0 right-5 flex items-center">
                {searchQuery ? (
                    <button 
                        onClick={() => { onSearchChange(''); inputRef.current?.focus(); }}
                        className="p-1 rounded-full text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700 hover:text-slate-600 dark:hover:text-slate-200 transition-colors animate-in fade-in zoom-in duration-200"
                    >
                        <X size={14} />
                    </button>
                ) : (
                    <span className="flex items-center gap-1 px-2.5 py-1 bg-slate-100/50 dark:bg-slate-800/50 rounded-lg border border-slate-200/50 dark:border-slate-700/50 text-[10px] font-bold text-slate-400 shadow-sm pointer-events-none">
                        <Command size={10} /> K
                    </span>
                )}
            </div>

            {/* Search History Dropdown */}
            {showHistory && searchHistory.length > 0 && (
                <div className="absolute top-full left-4 right-4 mt-2 bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl border border-slate-200/50 dark:border-slate-800/50 rounded-2xl shadow-xl overflow-hidden z-50 animate-in fade-in slide-in-from-top-2 duration-200">
                    <div className="flex items-center justify-between px-4 py-2 border-b border-slate-100 dark:border-slate-800/50 bg-slate-50/50 dark:bg-slate-950/30">
                        <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1.5">
                            <Clock size={10} /> {t('recentSearches')}
                        </span>
                        <button 
                            onClick={clearHistory}
                            className="text-[10px] text-rose-500 hover:text-rose-600 font-bold uppercase tracking-wider flex items-center gap-1 hover:bg-rose-50 dark:hover:bg-rose-900/20 px-2 py-0.5 rounded transition-colors"
                        >
                            <Trash2 size={10} /> {t('clearHistory')}
                        </button>
                    </div>
                    <div className="py-1">
                        {searchHistory.map((query, index) => (
                            <button
                                key={index}
                                onClick={() => { onSearchChange(query); saveToHistory(query); setShowHistory(false); }}
                                className="w-full flex items-center justify-between px-4 py-2.5 hover:bg-slate-100 dark:hover:bg-slate-800/50 transition-colors group text-left"
                            >
                                <div className="flex items-center gap-3 overflow-hidden">
                                    <History size={14} className="text-slate-400 group-hover:text-primary-500 transition-colors shrink-0" />
                                    <span className="text-sm font-medium text-slate-600 dark:text-slate-300 truncate">{query}</span>
                                </div>
                                <div 
                                    role="button"
                                    onClick={(e) => removeFromHistory(e, query)}
                                    className="p-1 text-slate-300 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded opacity-0 group-hover:opacity-100 transition-all"
                                >
                                    <X size={12} />
                                </div>
                            </button>
                        ))}
                    </div>
                </div>
            )}
        </div>
      </div>

      {/* Right Actions Island - Floating Glass */}
      <div className="flex items-center gap-2 p-2 bg-white/80 dark:bg-slate-900/80 backdrop-blur-2xl border border-slate-200/50 dark:border-slate-800/50 rounded-[2rem] shadow-glass dark:shadow-none pointer-events-auto z-[60]">

        {/* View Toggle */}
        <div className="flex items-center bg-slate-100 dark:bg-slate-800 rounded-[1.5rem] p-1 border border-slate-200 dark:border-slate-700">
            <button onClick={() => onViewModeChange('grid')} className={`p-2.5 rounded-[1.2rem] transition-all active:scale-95 ${viewMode === 'grid' ? 'bg-white dark:bg-slate-700 text-primary-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>
                <LayoutGrid size={18} />
            </button>
            <button onClick={() => onViewModeChange('chart')} className={`p-2.5 rounded-[1.2rem] transition-all active:scale-95 ${viewMode === 'chart' ? 'bg-white dark:bg-slate-700 text-primary-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>
                <BarChart2 size={18} />
            </button>
        </div>

        <div className="h-6 w-px bg-slate-200 dark:bg-slate-700 mx-2"></div>

        <button onClick={onOpenImport} className="w-10 h-10 flex items-center justify-center text-slate-500 hover:text-primary-600 hover:bg-primary-50 dark:hover:bg-primary-900/20 rounded-full transition-all active:scale-95" title={t('importData')}>
            <Upload size={20} />
        </button>

        <button 
            onClick={onExport} 
            disabled={isExporting}
            className="w-10 h-10 flex items-center justify-center text-slate-500 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-full transition-all active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed" 
            title="Download Report (CSV)"
        >
            {isExporting ? <Loader2 size={20} className="animate-spin text-blue-500" /> : <Download size={20} />}
        </button>

        <div className="relative" ref={colMenuRef}>
            <button onClick={() => setIsColumnMenuOpen(!isColumnMenuOpen)} className={`w-10 h-10 flex items-center justify-center rounded-full transition-all active:scale-95 ${isColumnMenuOpen ? 'bg-primary-50 text-primary-600' : 'text-slate-500 hover:text-primary-600 hover:bg-primary-50 dark:hover:bg-primary-900/20'}`}>
                <SlidersHorizontal size={20} />
            </button>
            {isColumnMenuOpen && (
                <div className="absolute top-full right-0 mt-4 w-72 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2rem] shadow-2xl p-4 animate-in fade-in zoom-in-95 origin-top-right z-[100]">
                    <h4 className="text-xs font-black uppercase text-slate-400 mb-3 tracking-widest px-2">{t('visibleAttributes')}</h4>

                    <label className="flex items-center gap-3 px-3 py-2.5 rounded-xl hover:bg-slate-50 dark:hover:bg-slate-800 cursor-pointer transition-colors group mb-2 border-b border-slate-100 dark:border-slate-800 pb-2">
                        <div className={`w-5 h-5 rounded-md border flex items-center justify-center transition-colors ${isAllSelected || isIndeterminate ? 'bg-primary-600 border-primary-600' : 'border-slate-300 dark:border-slate-600 group-hover:border-primary-400'}`}>
                            {isAllSelected && <div className="w-2 h-2 bg-white rounded-full"></div>}
                            {isIndeterminate && <div className="w-2.5 h-0.5 bg-white rounded-full"></div>}
                        </div>
                        <input 
                            type="checkbox" 
                            checked={isAllSelected} 
                            ref={(el) => { if(el) el.indeterminate = isIndeterminate; }}
                            onChange={handleSelectAll} 
                            className="hidden" 
                        />
                        <span className="text-xs font-bold text-slate-800 dark:text-white transition-colors">{t('selectAll')}</span>
                    </label>

                    <div className="max-h-64 overflow-y-auto custom-scrollbar space-y-1 pr-1">
                        {columns.map(col => (
                            <label key={col.key} className="flex items-center gap-3 px-3 py-2.5 rounded-xl hover:bg-slate-50 dark:hover:bg-slate-800 cursor-pointer transition-colors group">
                                <div className={`w-5 h-5 rounded-md border flex items-center justify-center transition-colors ${col.visible ? 'bg-primary-600 border-primary-600' : 'border-slate-300 dark:border-slate-600 group-hover:border-primary-400'}`}>
                                    {col.visible && <div className="w-2 h-2 bg-white rounded-full"></div>}
                                </div>
                                <input type="checkbox" checked={col.visible} onChange={() => !col.isSystem && onToggleColumn(col.key)} disabled={col.isSystem} className="hidden" />
                                <span className={`text-xs font-bold transition-colors ${col.visible ? 'text-slate-800 dark:text-white' : 'text-slate-500'}`}>{tProp(col.label)}</span>
                            </label>
                        ))}
                    </div>
                </div>
            )}
        </div>

        <button onClick={toggleTheme} className="w-10 h-10 flex items-center justify-center text-slate-500 hover:text-amber-500 hover:bg-amber-50 dark:hover:bg-amber-900/20 rounded-full transition-all active:scale-95">
            {theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}
        </button>

        <button onClick={toggleFullScreen} className="w-10 h-10 flex items-center justify-center text-slate-500 hover:text-indigo-500 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 rounded-full transition-all active:scale-95" title="Full Screen">
            <Maximize size={20} />
        </button>

        <div className="h-6 w-px bg-slate-200 dark:bg-slate-700 mx-2"></div>

        {/* Profile Pill */}
        <div className="relative" ref={userMenuRef}>
            <button onClick={() => setIsUserMenuOpen(!isUserMenuOpen)} className="flex items-center gap-2 pl-1 pr-4 py-1.5 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full transition-all border border-slate-200 dark:border-slate-700 active:scale-95">
                <img src={user?.avatar} alt="" className="w-8 h-8 rounded-full border border-white dark:border-slate-600 shadow-sm" />
                <span className="text-xs font-bold text-slate-700 dark:text-slate-200 max-w-[80px] truncate">{user?.name.split(' ')[0]}</span>
            </button>
            {isUserMenuOpen && (
                <div className="absolute top-full right-0 mt-4 w-60 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2rem] shadow-2xl p-2 animate-in fade-in zoom-in-95 origin-top-right z-[100] flex flex-col gap-1">
                    <button onClick={() => { setIsUserMenuOpen(false); onOpenProfile(); }} className="flex items-center gap-3 px-4 py-3 rounded-2xl hover:bg-slate-50 dark:hover:bg-slate-800 text-sm font-bold text-slate-700 dark:text-slate-200 transition-colors"><User size={18} /> {t('profile')}</button>
                    <button onClick={() => { setIsUserMenuOpen(false); onOpenAdmin(); }} className="flex items-center gap-3 px-4 py-3 rounded-2xl hover:bg-slate-50 dark:hover:bg-slate-800 text-sm font-bold text-slate-700 dark:text-slate-200 transition-colors"><Shield size={18} /> {t('adminPanel')}</button>
                    <button onClick={() => { setIsUserMenuOpen(false); toggleLanguage(); }} className="flex items-center gap-3 px-4 py-3 rounded-2xl hover:bg-slate-50 dark:hover:bg-slate-800 text-sm font-bold text-slate-700 dark:text-slate-200 transition-colors"><Globe size={18} /> {language === 'zh' ? 'English' : '中文'}</button>
                    <div className="h-px bg-slate-100 dark:bg-slate-800 my-1"></div>
                    <button onClick={onLogout} className="flex items-center gap-3 px-4 py-3 rounded-2xl hover:bg-blue-50 dark:hover:bg-blue-900/20 text-sm font-bold text-blue-600 transition-colors"><LogOut size={18} /> {t('logout')}</button>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useMemo } from 'react';
import { X, ChevronRight, Layers, Factory, Microscope, LayoutGrid, Globe, Info, BookOpen, ExternalLink, Calendar, FileText, ShieldCheck, Link2, Activity, Flame, Zap, TestTube, Box, FlaskConical, Beaker } from 'lucide-react';
import { Product, Category, Manufacturer, Reference, PropertyValue } from '../types';
import { CATEGORY_TREE, MANUFACTURERS, REFERENCES, PROPERTY_GROUPS } from '../constants';
import { useLanguage } from '../contexts/LanguageContext';

interface ProductDetailDrawerProps {
  product: Product | null;
  onClose: () => void;
  onCategoryClick: (id: string) => void;
}

export const ProductDetailDrawer: React.FC<ProductDetailDrawerProps> = ({ product, onClose, onCategoryClick }) => {
  const { t, tProp, language } = useLanguage();

  const manufacturer = useMemo(() => 
    MANUFACTURERS.find(m => m.id === product?.manufacturerId), 
  [product]);

  const relevantRefs = useMemo(() => {
    if (!product) return [];
    const refIds = new Set((Object.values(product.properties) as PropertyValue[]).map(p => p.referenceId).filter(Boolean));
    return REFERENCES.filter(r => refIds.has(r.id as string));
  }, [product]);

  const allPaths = useMemo(() => {
    if (!product) return [];
    const paths: {segments: string[], leafId: string}[] = [];

    const findPaths = (nodes: Category[], targetId: string, currentPath: string[]) => {
      for (const node of nodes) {
        const nodeName = language === 'en' && node.nameEn ? node.nameEn : node.name;
        const newPath = [...currentPath, nodeName];
        if (node.id === targetId) {
            paths.push({ segments: newPath, leafId: node.id });
        }
        if (node.children) findPaths(node.children, targetId, newPath);
      }
    };

    product.categoryIds.forEach(id => findPaths(CATEGORY_TREE, id, []));
    return paths;
  }, [product, language]);

  const groupedProperties = useMemo(() => {
      if (!product) return {};
      const groups: Record<string, [string, PropertyValue][]> = {
          'General': [],
          'Mechanical': [],
          'Thermal': [],
          'Optical/Electrical': [],
          'Chemical': [],
          'Other': []
      };

      Object.entries(product.properties).forEach(([key, val]) => {
          let found = false;
          for (const groupName in PROPERTY_GROUPS) {
              if (PROPERTY_GROUPS[groupName].some(k => key.includes(k) || k === key)) {
                  groups[groupName].push([key, val as PropertyValue]);
                  found = true;
                  break;
              }
          }
          if (!found) groups['Other'].push([key, val as PropertyValue]);
      });

      return groups;
  }, [product]);

  if (!product) return null;

  const getGroupIcon = (name: string) => {
      switch(name) {
          case 'Mechanical': return <Activity size={16} className="text-blue-500" />;
          case 'Thermal': return <Flame size={16} className="text-orange-500" />;
          case 'Optical/Electrical': return <Zap size={16} className="text-yellow-500" />;
          case 'Chemical': return <TestTube size={16} className="text-purple-500" />;
          case 'General': return <Box size={16} className="text-emerald-500" />;
          default: return <LayoutGrid size={16} className="text-slate-400" />;
      }
  };

  const getGroupName = (name: string) => {
      const key = `group_${name.replace('/', '').replace(' ', '')}`;
      return t(key as any) || name;
  };

  return (
    <div className={`fixed inset-y-0 right-0 w-full sm:w-[640px] bg-white dark:bg-slate-900 shadow-2xl z-[60] border-l border-slate-200 dark:border-slate-800 transition-transform duration-300 transform ${product ? 'translate-x-0' : 'translate-x-full'} flex flex-col`}>
      {/* Header */}
      <div className="px-6 py-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-950/50 backdrop-blur-sm sticky top-0 z-10">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-gradient-to-br from-emerald-500 to-teal-600 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-emerald-500/20">
            <Microscope size={24} />
          </div>
          <div>
            <h3 className="text-xl font-black text-slate-900 dark:text-white leading-tight tracking-tight">{product.gradeName}</h3>
            <div className="flex items-center gap-2 mt-1">
                <span className="text-[10px] font-bold bg-slate-200 dark:bg-slate-800 text-slate-600 dark:text-slate-400 px-2 py-0.5 rounded-full uppercase tracking-wider">{t('tdsReport')}</span>
                <span className="text-[10px] text-slate-400 font-medium">Updated: {product.updatedAt}</span>
            </div>
          </div>
        </div>
        <button onClick={onClose} className="p-2 text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-xl transition-all">
          <X size={24} />
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-6 custom-scrollbar space-y-8 bg-slate-50/30 dark:bg-slate-950/30">

        {/* Manufacturer & Source Card */}
        {manufacturer && (
            <div className="bg-white dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-2xl p-5 relative overflow-hidden group shadow-sm">
                <div className="absolute top-0 right-0 p-6 opacity-[0.03] pointer-events-none group-hover:scale-110 transition-transform duration-700"><Factory size={120} /></div>
                <div className="relative z-10">
                    <div className="flex flex-col sm:flex-row sm:justify-between sm:items-start gap-4 mb-4">
                        <div className="flex items-center gap-3">
                            <div className="p-2.5 bg-blue-50 dark:bg-blue-900/20 rounded-xl text-blue-600 dark:text-blue-400">
                                <Factory size={20} />
                            </div>
                            <div>
                                <h4 className="text-base font-bold text-slate-900 dark:text-white">{manufacturer.name}</h4>
                                <div className="flex items-center gap-1.5 mt-0.5">
                                    <ShieldCheck size={12} className="text-emerald-500" />
                                    <span className="text-[10px] font-medium text-emerald-600 dark:text-emerald-400 uppercase tracking-wide">{t('verifiedManufacturer')}</span>
                                </div>
                            </div>
                        </div>
                        {manufacturer.website && (
                            <a 
                                href={manufacturer.website.startsWith('http') ? manufacturer.website : `https://${manufacturer.website}`} 
                                target="_blank" 
                                rel="noreferrer" 
                                className="flex items-center gap-2 px-4 py-2 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-xl text-xs font-bold hover:opacity-90 transition-opacity shadow-lg shadow-slate-500/10 shrink-0"
                            >
