// Helper to create product quickly
const createProduct = (
    index: number, 
    grade: string, 
    manId: string, 
    manName: string, 
    catIds: string[], 
    props: Record<string, any>
): Product => ({
    id: `prod-${String(index).padStart(3, '0')}`,
    gradeName: grade,
    manufacturerId: manId,
    manufacturer: manName,
    categoryIds: catIds,
    updatedAt: new Date(2024, Math.floor(Math.random() * 6), Math.floor(Math.random() * 28) + 1).toISOString().split('T')[0],
    properties: props
});

