const handleInputKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' && selectedIndex !== -1 && searchHistory.length > 0) {
      handleHistoryItemClick(searchHistory[selectedIndex]);
      setSelectedIndex(-1);
      event.preventDefault();
      setShowHistory(false);
    }
    if (event.key === 'ArrowDown') {
      event.preventDefault(); // Prevent cursor movement in the input
      setSelectedIndex((prevIndex) => Math.min(prevIndex + 1, searchHistory.length - 1));
    } else if (event.key === 'ArrowUp') {
      event.preventDefault();
      setSelectedIndex((prevIndex) => Math.max(prevIndex - 1, -1));
    }
  };
