import React, { useState, useMemo, useEffect } from 'react';
import { Category } from '../types';
import { ChevronRight, LayoutGrid, Search, X, Layers } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

interface TreeSidebarProps {
  categories: Category[];
  selectedCategoryId: string | null;
  onSelectCategory: (id: string | null) => void;
  totalCount?: number;
  counts?: Record<string, number>;
}

const TreeNode: React.FC<{
  category: Category;
  selectedId: string | null;
  onSelect: (id: string) => void;
  depth: number;
  forceExpand?: boolean;
  counts?: Record<string, number>;
}> = ({ category, selectedId, onSelect, depth, forceExpand = false, counts = {} }) => {
  const [isExpanded, setIsExpanded] = useState(depth < 1); 
  const hasChildren = category.children && category.children.length > 0;
  const isSelected = selectedId === category.id;
  const { language } = useLanguage();

  useEffect(() => { if (forceExpand) setIsExpanded(true); }, [forceExpand]);

  const displayOpen = isExpanded || forceExpand;
  const count = counts[category.id] || 0;

  return (
    <div className="select-none my-0.5">
      <div
        onClick={(e) => {
            e.stopPropagation();
            if(hasChildren) setIsExpanded(!isExpanded);
            onSelect(category.id);
        }}
        className={`
          flex items-center px-3 py-2 cursor-pointer text-sm transition-all duration-200 mx-2 rounded-lg relative group active:scale-[0.98]
          ${isSelected 
            ? 'bg-primary-50 dark:bg-primary-900/20 text-primary-700 dark:text-primary-300 font-bold' 
            : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800 hover:text-slate-900 dark:hover:text-slate-200'}
        `}
        style={{ paddingLeft: `${depth * 12 + 12}px` }}
      >
        {isSelected && <div className="absolute left-0 top-1.5 bottom-1.5 w-1 bg-primary-500 rounded-r-full"></div>}

        <div className={`mr-2 transition-transform duration-200 ${displayOpen && hasChildren ? 'rotate-90' : ''}`}>
            {hasChildren ? (
                <ChevronRight size={14} className={isSelected ? 'text-primary-500' : 'text-slate-400'} />
            ) : (
                <div className="w-3.5" /> 
            )}
        </div>
        <span className="truncate relative z-10 flex-1 tracking-tight">{language === 'en' && category.nameEn ? category.nameEn : category.name}</span>

        {count > 0 && (
            <span className={`ml-2 px-1.5 py-0.5 rounded-md text-[9px] font-bold ${isSelected ? 'bg-primary-200 dark:bg-primary-800 text-primary-700 dark:text-primary-200' : 'bg-slate-100 dark:bg-slate-800 text-slate-400 dark:text-slate-500 group-hover:bg-white dark:group-hover:bg-slate-700'}`}>
                {count}
            </span>
        )}
      </div>

      <div 
        className={`overflow-hidden transition-all duration-300 ease-in-out ${displayOpen ? 'max-h-[800px] opacity-100' : 'max-h-0 opacity-0'}`}
      >
        <div className="relative ml-4 pl-2 border-l border-slate-200 dark:border-slate-800 my-0.5">
          {hasChildren && category.children!.map((child) => (
            <TreeNode
              key={child.id}
              category={child}
              selectedId={selectedId}
              onSelect={onSelect}
              depth={depth + 1}
              forceExpand={forceExpand}
              counts={counts} 
            />
          ))}
        </div>
      </div>
    </div>
  );
};

export const TreeSidebar: React.FC<TreeSidebarProps> = ({ categories, selectedCategoryId, onSelectCategory, totalCount = 0, counts = {} }) => {
  const { t, language } = useLanguage();
  const [searchTerm, setSearchTerm] = useState('');

  const filterCategories = (cats: Category[], term: string): Category[] => {
    return cats.reduce<Category[]>((acc, cat) => {
        const name = language === 'en' && cat.nameEn ? cat.nameEn : cat.name;
        const matches = name.toLowerCase().includes(term.toLowerCase());
        let filteredChildren: Category[] = [];
        if (cat.children) filteredChildren = filterCategories(cat.children, term);
        if (matches || filteredChildren.length > 0) acc.push({ ...cat, children: filteredChildren });
        return acc;
    }, []);
  };

  const displayedCategories = useMemo(() => searchTerm.trim() ? filterCategories(categories, searchTerm) : categories, [categories, searchTerm, language]);

  return (
    <div className="flex flex-col h-full bg-transparent">
      <div className="p-4 pb-2 shrink-0 space-y-3">
        {/* Search */}
        <div className="relative group">
             <Search className="absolute left-3.5 top-2.5 text-slate-400 group-focus-within:text-primary-500 transition-colors" size={16} />
             <input 
                type="text" 
                placeholder={t('searchCategories')} 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-8 py-2.5 bg-white/50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl text-sm font-medium focus:ring-2 focus:ring-primary-500/20 focus:border-primary-500 outline-none transition-all placeholder:text-slate-400 shadow-sm"
             />
             {searchTerm && <button onClick={() => setSearchTerm('')} className="absolute right-3 top-2.5 text-slate-400 hover:text-slate-600"><X size={14} /></button>}
        </div>

        {/* All Products Root Node */}
        <div 
            className={`
              flex items-center justify-between px-4 py-3 rounded-xl cursor-pointer transition-all duration-200 border group active:scale-[0.98] mx-1
              ${!selectedCategoryId 
                ? 'bg-gradient-to-r from-primary-600 to-indigo-600 text-white shadow-lg shadow-primary-500/20 border-transparent' 
                : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 hover:border-primary-200 hover:bg-primary-50/50 dark:hover:bg-slate-700'
              }
            `}
            onClick={() => onSelectCategory(null)}
        >
            <div className="flex items-center gap-3">
                <div className={`p-1.5 rounded-lg ${!selectedCategoryId ? 'bg-white/20' : 'bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400'}`}>
                    <Layers size={16} />
                </div>
                <span className="font-bold text-sm tracking-wide">{t('allProducts')}</span>
            </div>
            <span className={`px-2 py-0.5 rounded-md text-[10px] font-black ${!selectedCategoryId ? 'bg-white/20 text-white' : 'bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400'}`}>{totalCount}</span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-2 custom-scrollbar pb-6 pt-1">
        {displayedCategories.length > 0 ? (
            displayedCategories.map(cat => (
                <TreeNode
                    key={cat.id}
                    category={cat}
                    selectedId={selectedCategoryId}
                    onSelect={onSelectCategory}
                    depth={0}
                    forceExpand={!!searchTerm}
                    counts={counts}
                />
            ))
        ) : (
            <div className="text-center py-12 text-xs text-slate-400 italic flex flex-col items-center gap-2">
                <Search size={24} className="opacity-20" />
                No matching categories
            </div>
        )}
      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";
import React, { useState, useRef, useEffect } from 'react';
import { Send, Image as ImageIcon, Sparkles, X, Loader2, BrainCircuit, Bot, User, Cpu, ScanEye, Trash2, Maximize2, Minimize2, ShieldCheck } from 'lucide-react';
import { Product } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';

interface AIAssistantProps {
  contextData: Product[];
  inlineView?: boolean;
}

interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  image?: string;
  isThinking?: boolean;
}

const FormattedText: React.FC<{ text: string; className?: string }> = ({ text, className }) => {
  if (!text) return null;

  return (
    <div className={className}>
      {text.split('\n').map((line, i) => {
        const trimmed = line.trim();
        if (trimmed.startsWith('- ') || trimmed.startsWith('* ') || trimmed.match(/^\d+\./)) {
             const cleanLine = trimmed.replace(/^[-*]\s+|\d+\.\s+/, '');
             const parts = cleanLine.split(/(\*\*.*?\*\*)/g);
             return (
                <div key={i} className="flex gap-2.5 ml-1 mb-1.5 items-start">
                    <span className="text-emerald-500 dark:text-emerald-400 mt-1.5 shrink-0 text-[10px]">•</span>
                    <span className="leading-relaxed text-sm">
                        {parts.map((part, j) => {
                            if (part.startsWith('**') && part.endsWith('**')) {
                                return <strong key={j} className="font-bold text-slate-800 dark:text-white">{part.slice(2, -2)}</strong>;
                            }
                            return <span key={j}>{part}</span>;
                        })}
                    </span>
                </div>
             );
        }

        const parts = line.split(/(\*\*.*?\*\*)/g);
        if (line.startsWith('##')) {
             return <h3 key={i} className="font-bold text-emerald-700 dark:text-emerald-400 mt-4 mb-2 text-base">{line.replace(/#/g, '')}</h3>
        }

        if (!trimmed) return <div key={i} className="h-2"></div>;

        return (
          <p key={i} className="mb-2 last:mb-0 leading-relaxed text-sm">
            {parts.map((part, j) => {
              if (part.startsWith('**') && part.endsWith('**')) {
                return <strong key={j} className="font-bold text-slate-800 dark:text-white">{part.slice(2, -2)}</strong>;
              }
              return <span key={j}>{part}</span>;
            })}
          </p>
        );
      })}
    </div>
  );
};

export const AIAssistant: React.FC<AIAssistantProps> = ({ contextData, inlineView = false }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const [input, setInput] = useState('');
  const { t } = useLanguage();
  const { theme } = useTheme();
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [useThinking, setUseThinking] = useState(false);
  const [attachedImage, setAttachedImage] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (messages.length === 0) {
        setMessages([{ 
            id: 'welcome', 
            role: 'model', 
            text: t('welcomeMessage') 
        }]);
    }
  }, [t]);

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 5 * 1024 * 1024) {
          alert("File too large. Please use an image under 5MB.");
          return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setAttachedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSendMessage = async () => {
    if ((!input.trim() && !attachedImage) || isLoading) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      image: attachedImage || undefined
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setAttachedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const parts: any[] = [];
      let systemInstruction = "You are ResinAI. A professional technical assistant for synthetic resin data analysis.";

      if (userMsg.image) {
         const base64Data = userMsg.image.split(',')[1];
         const mimeType = userMsg.image.split(';')[0].split(':')[1] || 'image/jpeg';

         parts.push({
            inlineData: {
                mimeType: mimeType, 
                data: base64Data
            }
         });

         systemInstruction = `You are a Senior QC Specialist. 
Analyze the image focus on:
1. IDENTIFY: Material type/form.
2. DEFECTS: Detect Black Specks, Gels, Flow Marks, Discoloration.
3. ASSESSMENT: Pass/Fail based on industrial standards.`;

         const analysisPrompt = userMsg.text 
           ? `Review this resin sample: ${userMsg.text}`
           : "Identify the resin type and detect any visible defects (e.g., black specks, gels, discoloration) in this image.";

         parts.push({ text: analysisPrompt });
      } else {
         parts.push({ text: userMsg.text });

         if (contextData.length > 0) {
            const contextStr = JSON.stringify(contextData.slice(0, 15).map(p => ({
                grade: p.gradeName,
                manufacturer: p.manufacturer,
                properties: p.properties
            })));
            parts.push({ text: `\n[Database Context]: ${contextStr}` });
         }
      }

      // Use the gemini-3-flash-preview model
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [{ role: 'user', parts: parts }],
        config: {
            systemInstruction: systemInstruction,
            thinkingConfig: useThinking ? { thinkingBudget: 4096 } : undefined,
        }
      });

      const responseText = response.text || "AI analysis completed but no text output was generated.";

      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        text: responseText
      }]);

    } catch (error) {
      console.error("AI Error:", error);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        text: "Error: Could not reach the AI data center. Please check your network or API key."
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  // Shared inner content logic could be refactored, but repeating structure for simplicity given file constraints
  const renderMessageList = () => (
      <>
        {messages.map((msg) => (
            <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
                <div className={`flex gap-3 max-w-[85%] ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 border shadow-sm ${msg.role === 'user' ? 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700' : 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-100 dark:border-emerald-800/50'}`}>
                        {msg.role === 'user' ? <User size={14} className="text-slate-600 dark:text-slate-400"/> : <Sparkles size={14} className="text-emerald-600 dark:text-emerald-400"/>}
                    </div>
                    <div className={`flex flex-col gap-1 ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                        <div className={`rounded-2xl px-4 py-3 text-sm shadow-sm ${
                            msg.role === 'user' 
                            ? 'bg-slate-900 dark:bg-emerald-600 text-white rounded-tr-sm' 
                            : 'bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-200 border border-slate-200 dark:border-slate-700 rounded-tl-sm'
                        }`}>
                            {msg.image && (
                                <div className="mb-3 rounded-lg overflow-hidden border border-white/20 shadow-sm relative group/img">
                                    <img src={msg.image} alt="Uploaded" className="max-w-full h-auto max-h-48 object-cover" />
                                    <div className="absolute top-2 left-2 px-1.5 py-0.5 bg-black/60 backdrop-blur-sm rounded text-[9px] text-white font-bold flex items-center gap-1 opacity-0 group-hover/img:opacity-100 transition-opacity">
                                        <ShieldCheck size={10} className="text-emerald-400" />
                                        QC SCAN
                                    </div>
                                </div>
                            )}
                            <FormattedText text={msg.text} />
                        </div>
                    </div>
                </div>
            </div>
        ))}

        {messages.length === 1 && messages[0].id === 'welcome' && (
            <div className="flex flex-col gap-2 mt-4 px-4 animate-in fade-in slide-in-from-bottom-2">
                <p className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1 text-center">Quick Actions</p>
                <div className="flex justify-center gap-3">
                    <button 
                        onClick={() => fileInputRef.current?.click()}
                        className="flex items-center gap-2 px-4 py-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl shadow-sm hover:border-emerald-500 dark:hover:border-emerald-500 hover:text-emerald-600 dark:hover:text-emerald-400 transition-all text-xs font-bold text-slate-600 dark:text-slate-300 group"
                    >
                        <div className="p-1 bg-emerald-100 dark:bg-emerald-900/30 rounded-lg text-emerald-600 dark:text-emerald-400 group-hover:scale-110 transition-transform">
                            <ScanEye size={16} />
                        </div>
                        {t('analyzeImage') || "Analyze Image"}
                    </button>
                </div>
            </div>
        )}

        {isLoading && (
            <div className="flex justify-start animate-in fade-in duration-300">
                    <div className="flex gap-3 max-w-[85%]">
                    <div className="w-8 h-8 rounded-full bg-emerald-50 dark:bg-emerald-900/20 flex items-center justify-center shrink-0">
                        <Sparkles size={14} className="text-emerald-600 dark:text-emerald-400"/>
                    </div>
                    <div className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl rounded-tl-sm px-4 py-3 shadow-sm flex items-center gap-3">
                        <div className="flex gap-1">
                            <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                            <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                            <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-bounce"></span>
                        </div>
                        <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">
                            {useThinking ? t('reasoning') : t('analyzing')}
                        </span>
                    </div>
                    </div>
            </div>
        )}
      </>
  );

  const renderInputArea = () => (
    <div className="p-3 bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800">
        {attachedImage && (
            <div className="flex items-center justify-between px-3 py-2 mb-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg animate-in slide-in-from-bottom-2">
                <div className="flex items-center gap-3 overflow-hidden">
                    <div className="w-10 h-10 rounded bg-slate-200 dark:bg-slate-700 shrink-0 overflow-hidden border border-slate-300 dark:border-slate-600">
                            <img src={attachedImage} alt="Preview" className="w-full h-full object-cover" />
                    </div>
                    <div className="flex flex-col overflow-hidden">
                            <span className="text-xs font-semibold text-slate-700 dark:text-slate-200 truncate">{t('imageAttached')}</span>
                            <span className="text-[10px] text-emerald-600 dark:text-emerald-400 flex items-center gap-1">
                            <ShieldCheck size={10} /> QC Protocol Active
                            </span>
                    </div>
                </div>
                <button onClick={() => setAttachedImage(null)} className="p-1.5 text-slate-400 hover:text-rose-500 rounded-md transition-colors">
                    <Trash2 size={16} />
                </button>
            </div>
        )}
        <div className="flex items-end gap-2 bg-slate-100 dark:bg-slate-800/50 p-1.5 rounded-2xl border border-slate-200 dark:border-slate-700 focus-within:ring-2 focus-within:ring-emerald-500/20 focus-within:border-emerald-500 transition-all">
            <input type="file" ref={fileInputRef} accept="image/*" className="hidden" onChange={handleImageUpload} />
            <button onClick={() => fileInputRef.current?.click()} className={`p-2 rounded-xl transition-all shrink-0 ${attachedImage ? 'text-emerald-600 bg-emerald-100 dark:bg-emerald-900/30' : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 hover:bg-slate-200'}`}>
                {attachedImage ? <ScanEye size={20} /> : <ImageIcon size={20} />}
            </button>
            <textarea
                value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={handleKeyDown}
                placeholder={attachedImage ? t('imageContext') : t('aiPlaceholder')}
