import React, { useState, useMemo, useEffect } from 'react';
import { Category } from '../types';
import { ChevronRight, Layers, Search, X } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

interface TreeSidebarProps {
  categories: Category[];
  selectedCategoryId: string | null;
  onSelectCategory: (id: string | null) => void;
  totalCount?: number;
  counts?: Record<string, number>;
}

const TreeNode: React.FC<{
  category: Category;
  selectedId: string | null;
  onSelect: (id: string) => void;
  depth: number;
  forceExpand?: boolean;
  counts?: Record<string, number>;
}> = ({ category, selectedId, onSelect, depth, forceExpand = false, counts = {} }) => {
  const [isExpanded, setIsExpanded] = useState(depth < 1); 
  const hasChildren = category.children && category.children.length > 0;
  const isSelected = selectedId === category.id;
  const { language } = useLanguage();

  // Update expansion state when forceExpand changes
  useEffect(() => { 
      if (forceExpand) {
          setIsExpanded(true);
      }
  }, [forceExpand]);

  const displayOpen = isExpanded || forceExpand;
  const count = counts[category.id] || 0;

  return (
    <div className="select-none my-0.5">
      <div
        onClick={(e) => {
            e.stopPropagation();
            if(hasChildren) setIsExpanded(!isExpanded);
            onSelect(category.id);
        }}
        className={`
          flex items-center px-3 py-2 cursor-pointer text-sm transition-all duration-200 mx-2 rounded-lg relative group active:scale-[0.98]
          ${isSelected 
            ? 'bg-primary-50 dark:bg-primary-900/20 text-primary-700 dark:text-primary-300 font-bold' 
            : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800 hover:text-slate-900 dark:hover:text-slate-200'}
        `}
        style={{ paddingLeft: `${depth * 12 + 12}px` }}
      >
        {isSelected && <div className="absolute left-0 top-1.5 bottom-1.5 w-1 bg-primary-500 rounded-r-full"></div>}

        <div className={`mr-2 transition-transform duration-200 ${displayOpen && hasChildren ? 'rotate-90' : ''}`}>
            {hasChildren ? (
                <ChevronRight size={14} className={isSelected ? 'text-primary-500' : 'text-slate-400'} />
            ) : (
                <div className="w-3.5" /> 
            )}
        </div>
        <span className="truncate relative z-10 flex-1 tracking-tight">{language === 'en' && category.nameEn ? category.nameEn : category.name}</span>

        {count > 0 && (
            <span className={`ml-2 px-1.5 py-0.5 rounded-md text-[9px] font-bold ${isSelected ? 'bg-primary-200 dark:bg-primary-800 text-primary-700 dark:text-primary-200' : 'bg-slate-100 dark:bg-slate-800 text-slate-400 dark:text-slate-500 group-hover:bg-white dark:group-hover:bg-slate-700'}`}>
                {count}
            </span>
        )}
      </div>

      <div 
        className={`overflow-hidden transition-all duration-300 ease-in-out ${displayOpen ? 'max-h-[800px] opacity-100' : 'max-h-0 opacity-0'}`}
      >
        <div className="relative ml-4 pl-2 border-l border-slate-200 dark:border-slate-800 my-0.5">
          {hasChildren && category.children!.map((child) => (
            <TreeNode
              key={child.id}
              category={child}
              selectedId={selectedId}
              onSelect={onSelect}
              depth={depth + 1}
              forceExpand={forceExpand}
              counts={counts} 
            />
          ))}
        </div>
      </div>
    </div>
  );
};

export const TreeSidebar: React.FC<TreeSidebarProps> = ({ categories, selectedCategoryId, onSelectCategory, totalCount = 0, counts = {} }) => {
  const { t, language } = useLanguage();
  const [searchTerm, setSearchTerm] = useState('');

  // Recursive filter that preserves the tree structure of matching nodes
  const filterCategories = (cats: Category[], term: string): Category[] => {
    return cats.reduce<Category[]>((acc, cat) => {
        const name = language === 'en' && cat.nameEn ? cat.nameEn : cat.name;
        const matches = name.toLowerCase().includes(term.toLowerCase());
        let filteredChildren: Category[] = [];

        if (cat.children) {
            filteredChildren = filterCategories(cat.children, term);
        }

        // Include node if it matches OR if it has matching children
        if (matches || filteredChildren.length > 0) {
            acc.push({ ...cat, children: filteredChildren });
        }
        return acc;
    }, []);
  };

  const displayedCategories = useMemo(() => {
      if (!searchTerm.trim()) return categories;
      return filterCategories(categories, searchTerm);
  }, [categories, searchTerm, language]);

  return (
    <div className="flex flex-col h-full bg-transparent">
      <div className="p-4 pb-2 shrink-0 space-y-3">
        {/* Search */}
        <div className="relative group">
             <Search className="absolute left-3.5 top-2.5 text-slate-400 group-focus-within:text-primary-500 transition-colors" size={16} />
             <input 
                type="text" 
                placeholder={t('searchCategories')} 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-8 py-2.5 bg-white/50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl text-sm font-medium focus:ring-2 focus:ring-primary-500/20 focus:border-primary-500 outline-none transition-all placeholder:text-slate-400 shadow-sm"
             />
             {searchTerm && <button onClick={() => setSearchTerm('')} className="absolute right-3 top-2.5 text-slate-400 hover:text-slate-600"><X size={14} /></button>}
        </div>

        {/* All Products Root Node */}
        <div 
            className={`
              flex items-center justify-between px-4 py-3 rounded-xl cursor-pointer transition-all duration-200 border group active:scale-[0.98] mx-1
              ${!selectedCategoryId 
                ? 'bg-gradient-to-r from-primary-600 to-indigo-600 text-white shadow-lg shadow-primary-500/20 border-transparent' 
                : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 hover:border-primary-200 hover:bg-primary-50/50 dark:hover:bg-slate-700'
              }
            `}
            onClick={() => onSelectCategory(null)}
        >
            <div className="flex items-center gap-3">
                <div className={`p-1.5 rounded-lg ${!selectedCategoryId ? 'bg-white/20' : 'bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400'}`}>
                    <Layers size={16} />
                </div>
                <span className="font-bold text-sm tracking-wide">{t('allProducts')}</span>
            </div>
            <span className={`px-2 py-0.5 rounded-md text-[10px] font-black ${!selectedCategoryId ? 'bg-white/20 text-white' : 'bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400'}`}>{totalCount}</span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-2 custom-scrollbar pb-6 pt-1">
        {displayedCategories.length > 0 ? (
            displayedCategories.map(cat => (
                <TreeNode
                    key={cat.id}
                    category={cat}
                    selectedId={selectedCategoryId}
                    onSelect={onSelectCategory}
                    depth={0}
                    // When filtering, always expand to show the matches
                    forceExpand={!!searchTerm}
                    counts={counts}
                />
            ))
        ) : (
            <div className="text-center py-12 text-xs text-slate-400 italic flex flex-col items-center gap-2">
                <Search size={24} className="opacity-20" />
                No matching categories
            </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { X, Save, Plus, Trash2, Beaker, Factory, Loader2, Settings2, ChevronDown, ChevronUp } from 'lucide-react';
import { Product, PropertyValue } from '../types';
import { useLanguage } from '../contexts/LanguageContext';

interface EditProductModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (product: Product) => Promise<boolean> | void;
  product: Product | null;
}

interface PropertyRow {
  id: string;
  key: string;
  value: string;
  unit: string;
  // Metadata fields
  standard: string;
  instrument: string;
  temperature: string;
  referenceId: string;
  isExpanded: boolean;
}

export const EditProductModal: React.FC<EditProductModalProps> = ({ isOpen, onClose, onSave, product }) => {
  const { t, tProp } = useLanguage();
  const [formData, setFormData] = useState<Partial<Product>>({});
  const [propertyRows, setPropertyRows] = useState<PropertyRow[]>([]);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    if (product) {
      setFormData({
        gradeName: product.gradeName,
        manufacturer: product.manufacturer,
        categoryIds: product.categoryIds
      });

      const rows = Object.entries(product.properties).map(([key, val], index) => ({
        id: `prop-${index}-${Date.now()}`,
        key,
        value: String(val.value),
        unit: val.unit || '',
        standard: val.standard || '',
        instrument: val.instrument || '',
        temperature: val.temperature || '',
        referenceId: val.referenceId || '',
        isExpanded: false
      }));
      setPropertyRows(rows);
    }
  }, [product, isOpen]);

  const handleSave = async () => {
    if (!product || isSaving) return;
    setIsSaving(true);

    const newProperties: Record<string, PropertyValue> = {};
    propertyRows.forEach(row => {
      if (row.key.trim()) {
        const numVal = Number(row.value);
        newProperties[row.key] = {
          value: !isNaN(numVal) && row.value.trim() !== '' ? numVal : row.value,
          unit: row.unit.trim() || undefined,
          standard: row.standard.trim() || undefined,
          instrument: row.instrument.trim() || undefined,
          temperature: row.temperature.trim() || undefined,
          referenceId: row.referenceId.trim() || undefined
        };
      }
    });

    const updatedProduct = {
      ...product,
      ...formData as Product,
      properties: newProperties,
      updatedAt: new Date().toISOString().split('T')[0]
    };

    try {
        await onSave(updatedProduct);
        onClose();
    } catch (e) {
        // Error handling done in parent
    } finally {
        setIsSaving(false);
    }
  };

  const addRow = () => {
    setPropertyRows([...propertyRows, { 
        id: `new-${Date.now()}`, 
        key: '', value: '', unit: '', 
        standard: '', instrument: '', temperature: '', referenceId: '',
        isExpanded: true 
    }]);
  };

  const removeRow = (id: string) => {
    setPropertyRows(propertyRows.filter(r => r.id !== id));
  };

  const updateRow = (id: string, field: keyof PropertyRow, val: any) => {
    setPropertyRows(propertyRows.map(r => r.id === id ? { ...r, [field]: val } : r));
  };

  const toggleExpand = (id: string) => {
    setPropertyRows(propertyRows.map(r => r.id === id ? { ...r, isExpanded: !r.isExpanded } : r));
  };

  if (!isOpen || !product) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-in fade-in duration-300">
      <div className="w-full max-w-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]">

        {/* Header */}
        <div className="px-6 py-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-950/50">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 rounded-xl">
               <Beaker size={20} />
            </div>
            <h3 className="text-lg font-bold text-slate-900 dark:text-white">{t('editProduct')}</h3>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200">
            <X size={20} />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6 custom-scrollbar space-y-6">
           <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                 <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">{tProp('牌号')}</label>
                 <input 
                    className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm font-bold text-slate-900 dark:text-slate-100 outline-none focus:border-emerald-500 transition-all"
                    value={formData.gradeName || ''}
                    onChange={e => setFormData({...formData, gradeName: e.target.value})}
                 />
              </div>
              <div className="space-y-1.5">
                 <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">{tProp('生产厂家')}</label>
                 <div className="relative">
                    <Factory size={16} className="absolute left-3.5 top-3 text-slate-400" />
                    <input 
                        className="w-full pl-10 pr-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm font-bold text-slate-900 dark:text-slate-100 outline-none focus:border-emerald-500 transition-all"
                        value={formData.manufacturer || ''}
                        onChange={e => setFormData({...formData, manufacturer: e.target.value})}
                    />
                 </div>
              </div>
           </div>

           <div className="space-y-3">
              <div className="flex items-center justify-between border-b border-slate-100 dark:border-slate-800 pb-2">
                 <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest">{t('properties')}</h4>
                 <button onClick={addRow} className="flex items-center gap-1 text-[10px] font-bold text-emerald-600 hover:text-emerald-500 bg-emerald-50 dark:bg-emerald-900/20 px-2 py-1 rounded-lg transition-colors">
                    <Plus size={12} /> {t('addProperty')}
                 </button>
              </div>

              <div className="space-y-2">
                 {propertyRows.map((row) => (
                    <div key={row.id} className="group bg-white dark:bg-slate-900 rounded-xl border border-transparent hover:border-slate-100 dark:hover:border-slate-800 transition-colors p-1">
                        <div className="flex items-center gap-2">
                           <button 
                                onClick={() => toggleExpand(row.id)}
                                className={`p-2 rounded-lg transition-colors ${row.isExpanded ? 'text-primary-500 bg-primary-50 dark:bg-primary-900/20' : 'text-slate-300 hover:text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
                                title="Edit Source Details"
                           >
                                <Settings2 size={16} />
                           </button>
                           <input 
                              placeholder={t('propertyName')}
                              value={row.key}
                              onChange={e => updateRow(row.id, 'key', e.target.value)}
                              className="flex-1 px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-xs font-bold text-slate-700 dark:text-slate-300 outline-none focus:border-emerald-500 transition-all"
                           />
                           <input 
                              placeholder={t('propertyValue')}
