import { Product, PropertyValue } from './types';
import { MOCK_PRODUCTS } from './constants';

// Simulated latency (network delay)
const DELAY_MS = 800;

// Helper to simulate network errors occasionally
const simulateNetworkCondition = () => {
  const rand = Math.random();
  if (rand > 0.99) { // 1% chance of random network failure (reduced from 2% for stability)
    throw new Error("503 Service Unavailable: Connection timeout");
  }
};

export const api = {
  /**
   * [Search/Filter] Endpoint
   * POST /api/resins/search
   */
  search: async (query: string, categoryId: string | null): Promise<Product[]> => {
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        try {
          simulateNetworkCondition();

          const lowerQuery = query.toLowerCase().trim();
          const results = MOCK_PRODUCTS.filter(p => {
            // 1. Category Filter
            if (categoryId && !p.categoryIds.includes(categoryId)) return false;

            // 2. Text Search (Full-text simulation)
            if (!lowerQuery) return true;

            return (
              p.gradeName.toLowerCase().includes(lowerQuery) ||
              p.manufacturer.toLowerCase().includes(lowerQuery) ||
              Object.keys(p.properties).some(k => k.toLowerCase().includes(lowerQuery))
            );
          });

          resolve(results);
        } catch (error) {
          reject(error);
        }
      }, DELAY_MS);
    });
  },

  /**
   * [Save/Update] Endpoint
   * PATCH /api/resins/:id
   */
  update: async (product: Product): Promise<Product> => {
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        try {
          simulateNetworkCondition();

          // Validate payload
          if (!product.id || !product.gradeName) {
            throw new Error("400 Bad Request: Missing required fields");
          }

          resolve({
            ...product,
            updatedAt: new Date().toISOString().split('T')[0]
          });
        } catch (error) {
          reject(error);
        }
      }, 1200); 
    });
  },

  /**
   * [Batch Update] Endpoint
   * PATCH /api/resins/batch
   */
  batchUpdate: async (ids: string[], updates: Partial<Product>): Promise<void> => {
    return new Promise((resolve, reject) => {
        setTimeout(() => {
            try {
                simulateNetworkCondition();
                if (!ids.length) throw new Error("400 Bad Request: No IDs provided");
                resolve();
            } catch (error) {
                reject(error);
            }
        }, 1500);
    });
  },

  /**
   * [Delete] Endpoint
   * DELETE /api/resins
   */
  delete: async (ids: string[]): Promise<void> => {
    return new Promise((resolve, reject) => {
        setTimeout(() => {
            try {
                simulateNetworkCondition();
                if (!ids.length) throw new Error("400 Bad Request: No IDs provided");
                resolve();
            } catch (error) {
                reject(error);
            }
        }, 1000);
    });
  },

  /**
   * [Export Data] Endpoint
   * GET /api/resins/export
   */
  exportReport: async (products: Product[], format: 'csv' | 'xlsx'): Promise<Blob> => {
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        try {
          simulateNetworkCondition();

          if (products.length === 0) {
            throw new Error("400 Bad Request: No data to export");
          }

          const headers = ['ID', 'Grade', 'Manufacturer', 'Category', 'Updated'];
          // Dynamic headers based on available properties in the set
          const allPropKeys = new Set<string>();
          products.forEach(p => Object.keys(p.properties).forEach(k => allPropKeys.add(k)));
          const propKeys = Array.from(allPropKeys);

          const allHeaders = [...headers, ...propKeys].join(',');

          const rows = products.map(p => {
            const basic = [p.id, p.gradeName, p.manufacturer, p.categoryIds.join('|'), p.updatedAt];
            const props = propKeys.map(k => {
                const val = p.properties[k]?.value;
                // Escape commas and quotes for CSV
                const strVal = String(val ?? '');
                return strVal.includes(',') || strVal.includes('"') ? `"${strVal.replace(/"/g, '""')}"` : strVal;
            });
            return [...basic, ...props].join(',');
          });

          const csvContent = [allHeaders, ...rows].join('\n');
          const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' }); // Add BOM

          resolve(blob);
        } catch (error) {
          reject(error);
        }
      }, 1500); 
    });
  }
};

