const FormattedText: React.FC<{ text: string; className?: string }> = ({ text, className }) => {
  if (!text) return null;

  return (
    <div className={className}>
      {text.split('\n').map((line, i) => {
        const trimmed = line.trim();
        // List items
        if (trimmed.startsWith('- ') || trimmed.startsWith('* ') || trimmed.match(/^\d+\./)) {
             const cleanLine = trimmed.replace(/^[-*]\s+|\d+\.\s+/, '');
             const parts = cleanLine.split(/(\*\*.*?\*\*)/g);
             return (
                <div key={i} className="flex gap-2.5 ml-1 mb-1.5 items-start">
                    <span className="text-emerald-500 dark:text-emerald-400 mt-1.5 shrink-0 text-[10px]">•</span>
                    <span className="leading-relaxed text-sm">
                        {parts.map((part, j) => {
                            if (part.startsWith('**') && part.endsWith('**')) {
                                return <strong key={j} className="font-bold text-slate-800 dark:text-white">{part.slice(2, -2)}</strong>;
                            }
                            return <span key={j}>{part}</span>;
                        })}
                    </span>
                </div>
             );
        }

        // Headings
        if (line.startsWith('##')) {
             return <h3 key={i} className="font-bold text-emerald-700 dark:text-emerald-400 mt-4 mb-2 text-base">{line.replace(/#/g, '')}</h3>
        }

        // Empty lines
        if (!trimmed) return <div key={i} className="h-2"></div>;

        // Standard Paragraphs with bold parsing
        const parts = line.split(/(\*\*.*?\*\*)/g);
        return (
          <p key={i} className="mb-2 last:mb-0 leading-relaxed text-sm">
            {parts.map((part, j) => {
              if (part.startsWith('**') && part.endsWith('**')) {
                return <strong key={j} className="font-bold text-slate-800 dark:text-white">{part.slice(2, -2)}</strong>;
              }
              return <span key={j}>{part}</span>;
            })}
          </p>
        );
      })}
    </div>
  );
};

export const AIAssistant: React.FC<AIAssistantProps> = ({ contextData, inlineView = false }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const [input, setInput] = useState('');
  const { t, language } = useLanguage();
  const { theme } = useTheme();
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [useThinking, setUseThinking] = useState(false);
  const [attachedImage, setAttachedImage] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatContainerRef = useRef<HTMLDivElement>(null);

  // Initialize welcome message
  useEffect(() => {
    if (messages.length === 0) {
        setMessages([{ 
            id: 'welcome', 
            role: 'model', 
            text: t('welcomeMessage') 
        }]);
    }
  }, [t]);

  // Auto-scroll logic
  useEffect(() => {
    if (messagesEndRef.current) {
        messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isOpen, isLoading]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 5 * 1024 * 1024) {
          // Simple alert replacement for error handling
          setMessages(prev => [...prev, {
              id: Date.now().toString(),
              role: 'model',
              text: "⚠️ System Alert: Image file is too large. Please upload an image smaller than 5MB."
          }]);
          return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setAttachedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
    // Reset input
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSendMessage = async () => {
    if ((!input.trim() && !attachedImage) || isLoading) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      image: attachedImage || undefined
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setAttachedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const parts: any[] = [];
      let systemInstruction = "You are ResinAI. A professional technical assistant for synthetic resin data analysis. Be concise, scientific, and data-driven.";

      if (userMsg.image) {
         const base64Data = userMsg.image.split(',')[1];
         const mimeType = userMsg.image.split(';')[0].split(':')[1] || 'image/jpeg';

         parts.push({
            inlineData: {
                mimeType: mimeType, 
                data: base64Data
            }
         });

         systemInstruction = `You are a Senior QC Specialist for Petrochemicals. 
Analyze the image with focus on:
1. IDENTIFICATION: Material form (pellets, powder, film, part).
2. DEFECT ANALYSIS: Detect Black Specks, Gels, Flow Marks, Discoloration, or Contamination.
3. ASSESSMENT: Pass/Fail recommendation based on industrial appearance standards.`;

         const analysisPrompt = userMsg.text 
           ? `User Query: ${userMsg.text}`
           : "Perform a standard QC analysis on this resin sample image.";

         parts.push({ text: analysisPrompt });
      } else {
         parts.push({ text: userMsg.text });

         // Context Injection (Limit to prevent token overflow)
         if (contextData.length > 0) {
            const contextStr = JSON.stringify(contextData.slice(0, 10).map(p => ({
                grade: p.gradeName,
                manufacturer: p.manufacturer,
                properties: p.properties
            })));
            parts.push({ text: `\n[Current Data View Context (Top 10)]: ${contextStr}` });
         }
      }

      // Model Selection logic based on guidelines
      const modelName = 'gemini-3-flash-preview';

      const response = await ai.models.generateContent({
        model: modelName,
        contents: [{ role: 'user', parts: parts }],
        config: {
            systemInstruction: systemInstruction,
            // Only apply thinking config if toggled and using supported model (Gemini 3 supports it)
            thinkingConfig: useThinking ? { thinkingBudget: 2048 } : undefined,
        }
      });

      const responseText = response.text || "Analysis completed, but no text output was generated. Please try again.";

      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        text: responseText
      }]);

    } catch (error: any) {
      console.error("AI Error:", error);
      let errorMessage = "Error: Unable to process request.";
      if (error.message?.includes('429')) errorMessage = "System Busy: Too many requests. Please wait a moment.";
      if (error.message?.includes('API_KEY')) errorMessage = "Configuration Error: API Key invalid.";

      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        text: errorMessage
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const renderMessages = () => (
    <>
      {messages.map((msg) => (
        <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
          <div className={`flex gap-3 max-w-[85%] ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
            <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 border shadow-sm ${msg.role === 'user' ? 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700' : 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-100 dark:border-emerald-800/50'}`}>
              {msg.role === 'user' ? <User size={14} className="text-slate-600 dark:text-slate-400"/> : <Sparkles size={14} className="text-emerald-600 dark:text-emerald-400"/>}
            </div>
            <div className={`flex flex-col gap-1 ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
              <div className={`rounded-2xl px-4 py-3 text-sm shadow-sm ${
                msg.role === 'user' 
