                {msg.image && (
                  <div className="mb-3 rounded-lg overflow-hidden border border-white/20 shadow-sm relative group/img">
                    <img src={msg.image} alt="Uploaded" className="max-w-full h-auto max-h-48 object-cover bg-black/10" />
                    <div className="absolute top-2 left-2 px-1.5 py-0.5 bg-black/60 backdrop-blur-sm rounded text-[9px] text-white font-bold flex items-center gap-1 opacity-0 group-hover/img:opacity-100 transition-opacity">
                      <ShieldCheck size={10} className="text-emerald-400" />
                      QC SCAN
                    </div>
                  </div>
                )}
                <FormattedText text={msg.text} />
              </div>
            </div>
          </div>
        </div>
      ))}
      {isLoading && (
        <div className="flex justify-start animate-in fade-in duration-300">
          <div className="flex gap-3 max-w-[85%]">
            <div className="w-8 h-8 rounded-full bg-emerald-50 dark:bg-emerald-900/20 flex items-center justify-center shrink-0">
