                                    <label className="text-[9px] font-bold text-slate-400 uppercase tracking-wider">{t('testConditions')}</label>
                                    <input 
                                        value={row.temperature}
                                        onChange={e => updateRow(row.id, 'temperature', e.target.value)}
                                        placeholder="230°C/2.16kg"
